CREATE OR REPLACE FUNCTION "private"."approve_supplier_invoice_commercially_phase_ab_legacy"("p_organization_id" "uuid", "p_supplier_invoice_id" "uuid", "p_expected_finance_hash" "text", "p_accepted_variances" "jsonb" DEFAULT '[]'::"jsonb", "p_no_po_reason" "text" DEFAULT NULL::"text", "p_no_po_explanation" "text" DEFAULT NULL::"text", "p_approval_note" "text" DEFAULT ''::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_invoice public.supplier_invoices%rowtype;
  v_hash text;
  v_approval_id uuid;
  v_line_count integer;
  v_allocation_count integer;
  v_allocated_total numeric;
  v_has_po boolean;
  v_invalid_count integer;
begin
  if auth.uid() is null
    or not public.has_org_permission(p_organization_id, 'supplier_invoices.review') then
    raise exception 'You do not have permission to commercially approve supplier invoices.';
  end if;

  select * into v_invoice
  from public.supplier_invoices
  where id = p_supplier_invoice_id
    and organization_id = p_organization_id
  for update;

  if not found then
    raise exception 'Supplier invoice not found.';
  end if;

  if v_invoice.supplier_id is null then
    raise exception 'Select a supplier before commercial approval.';
  end if;
  if char_length(public.normalize_supplier_invoice_number(coalesce(v_invoice.invoice_number, ''))) = 0 then
    raise exception 'Enter an invoice number before commercial approval.';
  end if;
  if v_invoice.invoice_date is null then
    raise exception 'Enter an invoice date before commercial approval.';
  end if;

  if exists (
    select 1
    from public.supplier_invoices other
    where other.organization_id = p_organization_id
      and other.supplier_id = v_invoice.supplier_id
      and other.id <> v_invoice.id
      and public.normalize_supplier_invoice_number(other.invoice_number)
        = public.normalize_supplier_invoice_number(v_invoice.invoice_number)
  ) then
    raise exception 'Another invoice for this supplier uses the same invoice number.';
  end if;

  select count(*) into v_line_count
  from public.supplier_invoice_lines
  where supplier_invoice_id = v_invoice.id;

  if v_line_count = 0 then
    raise exception 'Add at least one invoice line before commercial approval.';
  end if;

  select count(*), coalesce(sum(a.allocated_amount), 0), bool_or(a.purchase_order_id is not null)
  into v_allocation_count, v_allocated_total, v_has_po
  from public.supplier_invoice_line_allocations a
  where a.supplier_invoice_id = v_invoice.id;

  if v_allocation_count <> v_line_count then
    raise exception 'Every invoice line must have exactly one active allocation.';
  end if;
  if abs(v_allocated_total - v_invoice.subtotal) > 0.01
    and abs(v_allocated_total - v_invoice.total) > 0.01 then
    raise exception 'Allocated amounts do not reconcile to the invoice.';
  end if;

  select count(*) into v_invalid_count
  from public.supplier_invoice_line_allocations a
  left join public.organization_tradesstack_accounting_mappings m
    on m.id = a.accounting_mapping_id
    and m.organization_id = p_organization_id
    and m.is_active = true
  left join public.organization_accounting_tax_rates t
    on t.id = a.accounting_tax_rate_id
    and t.organization_id = p_organization_id
    and t.is_active = true
  where a.supplier_invoice_id = v_invoice.id
    and (
      a.approval_status <> 'approved'
      or a.accounting_mapping_id is null
      or m.id is null
      or a.tax_resolution_status = 'unresolved'
      or (
        a.tax_resolution_status = 'not_applicable'
        and exists (
          select 1
          from public.supplier_invoice_lines tax_line
          where tax_line.id = a.supplier_invoice_line_id
            and tax_line.tax_amount > 0.01
        )
      )
      or (a.tax_resolution_status = 'resolved' and t.id is null)
      or (a.purchase_order_id is null and char_length(trim(coalesce(a.approval_notes, ''))) = 0)
    );

  if v_invalid_count > 0 then
    raise exception 'Every allocation must be approved with active accounting and tax mappings.';
  end if;

  if exists (
    select 1
    from public.supplier_invoice_line_allocations a
    join public.project_purchase_orders po on po.id = a.purchase_order_id
    where a.supplier_invoice_id = v_invoice.id
      and po.supplier_id is distinct from v_invoice.supplier_id
  ) then
    raise exception 'The invoice supplier does not match one or more purchase orders.';
  end if;

  if coalesce(v_has_po, false) = false then
    if p_no_po_reason not in (
      'utilities', 'insurance', 'emergency_purchase',
      'professional_service', 'approved_overhead', 'other'
    ) then
      raise exception 'Select a valid no-PO reason.';
    end if;
    if p_no_po_reason = 'other'
      and char_length(trim(coalesce(p_no_po_explanation, ''))) = 0 then
      raise exception 'Explain the no-PO reason.';
    end if;
  end if;

  if exists (
    select 1
    from public.supplier_invoice_line_allocations current_a
    join public.project_purchase_order_line_items po_line
      on po_line.id = current_a.purchase_order_line_item_id
    left join lateral (
      select
        coalesce(sum(snapshot.quantity), 0) as approved_quantity,
        coalesce(sum(snapshot.amount), 0) as approved_amount
      from public.supplier_invoice_commercial_line_snapshots snapshot
      join public.supplier_invoice_commercial_approvals approval
        on approval.id = snapshot.commercial_approval_id
      where snapshot.purchase_order_line_item_id = current_a.purchase_order_line_item_id
        and snapshot.supplier_invoice_id <> v_invoice.id
        and approval.status = 'approved'
    ) history on true
    left join lateral (
      select coalesce(sum(release_line.released_amount), 0) as released_amount
      from public.purchase_order_commitment_release_lines release_line
      where release_line.purchase_order_line_item_id = current_a.purchase_order_line_item_id
    ) released on true
    where current_a.supplier_invoice_id = v_invoice.id
      and (
        history.approved_quantity + coalesce(current_a.allocated_quantity, 0) > po_line.quantity + 0.001
        or history.approved_amount + released.released_amount + current_a.allocated_amount
          > po_line.total + 0.01
      )
  ) then
    raise exception 'Commercial approval is blocked because the invoice would over-invoice a purchase order line.';
  end if;

  if exists (
    select 1
    from public.supplier_invoice_line_allocations current_a
    join public.supplier_invoice_lines invoice_line
      on invoice_line.id = current_a.supplier_invoice_line_id
    join public.project_purchase_order_line_items po_line
      on po_line.id = current_a.purchase_order_line_item_id
    where current_a.supplier_invoice_id = v_invoice.id
      and abs(invoice_line.unit_price - po_line.rate) > 0.0001
      and not exists (
        select 1
        from jsonb_array_elements(coalesce(p_accepted_variances, '[]'::jsonb)) accepted
        where accepted ->> 'type' = 'rate_variance'
          and accepted ->> 'purchaseOrderLineItemId' = po_line.id::text
          and char_length(trim(coalesce(accepted ->> 'note', ''))) > 0
      )
  ) then
    raise exception 'Accept and explain every rate variance before commercial approval.';
  end if;

  if exists (
    select 1
    from public.supplier_invoice_line_allocations current_a
    join public.supplier_invoice_lines invoice_line
      on invoice_line.id = current_a.supplier_invoice_line_id
    join public.project_purchase_order_line_items po_line
      on po_line.id = current_a.purchase_order_line_item_id
    where current_a.supplier_invoice_id = v_invoice.id
      and abs(
        current_a.allocated_amount
        - round(coalesce(current_a.allocated_quantity, invoice_line.quantity, 0) * po_line.rate, 2)
      ) > 0.01
      and not exists (
        select 1
        from jsonb_array_elements(coalesce(p_accepted_variances, '[]'::jsonb)) accepted
        where accepted ->> 'type' = 'value_variance'
          and accepted ->> 'purchaseOrderLineItemId' = po_line.id::text
          and char_length(trim(coalesce(accepted ->> 'note', ''))) > 0
      )
  ) then
    raise exception 'Accept and explain every purchase order line value variance before commercial approval.';
  end if;

  if exists (
    select 1
    from public.supplier_invoices other
    where other.organization_id = p_organization_id
      and other.supplier_id = v_invoice.supplier_id
      and other.id <> v_invoice.id
      and other.invoice_date is not distinct from v_invoice.invoice_date
      and abs(other.total - v_invoice.total) <= 0.01
      and public.normalize_supplier_invoice_number(other.invoice_number)
        <> public.normalize_supplier_invoice_number(v_invoice.invoice_number)
  )
  and not exists (
    select 1
    from jsonb_array_elements(coalesce(p_accepted_variances, '[]'::jsonb)) accepted
    where accepted ->> 'type' = 'duplicate_invoice'
      and char_length(trim(coalesce(accepted ->> 'note', ''))) > 0
  ) then
    raise exception 'Review and explain the likely duplicate invoice warning before commercial approval.';
  end if;

  v_hash := public.supplier_invoice_finance_version_hash(v_invoice.id);
  if v_hash is null or v_hash <> p_expected_finance_hash then
    raise exception 'The invoice changed while it was being reviewed. Refresh and review it again.';
  end if;

  perform public.invalidate_supplier_invoice_commercial_approval(
    v_invoice.id,
    'Superseded by a newer commercial approval.',
    'commercial_approval',
    auth.uid()
  );

  insert into public.supplier_invoice_commercial_approvals (
    organization_id,
    supplier_invoice_id,
    status,
    finance_version_hash,
    supplier_id,
    normalized_invoice_number,
    invoice_total,
    invoice_tax_total,
    currency,
    accepted_variances,
    no_po_reason,
    no_po_explanation,
    approval_note,
    reviewed_by
  )
  values (
    p_organization_id,
    v_invoice.id,
    'approved',
    v_hash,
    v_invoice.supplier_id,
    public.normalize_supplier_invoice_number(v_invoice.invoice_number),
    v_invoice.total,
    v_invoice.tax_total,
    v_invoice.currency,
    coalesce(p_accepted_variances, '[]'::jsonb),
    case when coalesce(v_has_po, false) then null else p_no_po_reason end,
    case when coalesce(v_has_po, false) then null else nullif(trim(p_no_po_explanation), '') end,
    coalesce(p_approval_note, ''),
    auth.uid()
  )
  returning id into v_approval_id;

  insert into public.supplier_invoice_commercial_line_snapshots (
    organization_id,
    commercial_approval_id,
    supplier_invoice_id,
    supplier_invoice_line_id,
    allocation_id,
    purchase_order_id,
    purchase_order_line_item_id,
    project_id,
    accounting_mapping_id,
    accounting_tax_rate_id,
    description,
    quantity,
    unit_rate,
    amount,
    tax_amount,
    tax_resolution_status
  )
  select
    p_organization_id,
    v_approval_id,
    v_invoice.id,
    l.id,
    a.id,
    a.purchase_order_id,
    a.purchase_order_line_item_id,
    a.project_id,
    a.accounting_mapping_id,
    a.accounting_tax_rate_id,
    l.description,
    coalesce(a.allocated_quantity, l.quantity, 0),
    l.unit_price,
    a.allocated_amount,
    l.tax_amount,
    a.tax_resolution_status
  from public.supplier_invoice_lines l
  join public.supplier_invoice_line_allocations a
    on a.supplier_invoice_line_id = l.id
    and a.supplier_invoice_id = v_invoice.id
  where l.supplier_invoice_id = v_invoice.id;

  insert into public.supplier_invoice_commercial_variances (
    organization_id,
    commercial_approval_id,
    supplier_invoice_id,
    variance_key,
    variance_type,
    severity,
    purchase_order_line_item_id,
    expected_value,
    actual_value,
    variance_amount,
    accepted_by,
    explanation
  )
  select
    p_organization_id,
    v_approval_id,
    v_invoice.id,
    accepted ->> 'key',
    accepted ->> 'type',
    'warning',
    nullif(accepted ->> 'purchaseOrderLineItemId', '')::uuid,
    accepted -> 'expectedValue',
    accepted -> 'actualValue',
    case
      when jsonb_typeof(accepted -> 'varianceAmount') = 'number'
        then (accepted ->> 'varianceAmount')::numeric
      else null
    end,
    auth.uid(),
    trim(accepted ->> 'note')
  from jsonb_array_elements(coalesce(p_accepted_variances, '[]'::jsonb)) accepted
  where char_length(trim(coalesce(accepted ->> 'key', ''))) > 0
    and char_length(trim(coalesce(accepted ->> 'type', ''))) > 0
    and char_length(trim(coalesce(accepted ->> 'note', ''))) > 0;

  insert into public.supplier_invoice_activity_events (
    organization_id,
    supplier_invoice_id,
    event_type,
    message,
    metadata,
    created_by
  )
  values (
    p_organization_id,
    v_invoice.id,
    'approved',
    'Supplier invoice commercially approved.',
    jsonb_build_object(
      'commercial_approval_id', v_approval_id,
      'finance_version_hash', v_hash,
      'accepted_variances', coalesce(p_accepted_variances, '[]'::jsonb)
    ),
    auth.uid()
  );

  return v_approval_id;
end;
$$;


ALTER FUNCTION "private"."approve_supplier_invoice_commercially_phase_ab_legacy"("p_organization_id" "uuid", "p_supplier_invoice_id" "uuid", "p_expected_finance_hash" "text", "p_accepted_variances" "jsonb", "p_no_po_reason" "text", "p_no_po_explanation" "text", "p_approval_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."create_retention_successor_draft"("p_submitted_claim_id" "uuid", "p_correlation_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_source public.retention_claims%rowtype;
  v_successor public.retention_claims%rowtype;
  v_position jsonb;
  v_eligibility jsonb;
  v_count integer;
begin
  select * into v_source from public.retention_claims where id = p_submitted_claim_id;
  if not found or v_source.status <> 'submitted'
    or v_source.draft_kind <> 'automatic_rolling' then
    return jsonb_build_object('succeeded', true, 'created', false);
  end if;

  select * into v_successor from public.retention_claims
  where organization_id = v_source.organization_id
    and project_id = v_source.project_id
    and status = 'draft' and draft_kind = 'automatic_rolling'
  for update;
  if found then
    return jsonb_build_object('succeeded', true, 'created', false,
      'retentionClaimId', v_successor.id);
  end if;

  v_position := public.get_project_retention_position_summary(v_source.project_id);
  v_eligibility := public.get_project_retention_eligibility(v_source.project_id);
  select count(*) into v_count
  from jsonb_array_elements(coalesce(v_eligibility -> 'origins', '[]'::jsonb)) origin
  where round(greatest(
    coalesce((origin ->> 'currentRetentionOwned')::numeric, 0)
    - coalesce((origin ->> 'committedRetention')::numeric, 0), 0
  ), 2) > 0;

  if v_count = 0 then
    perform private.record_retention_claim_event(
      v_source.organization_id, v_source.project_id, v_source.id,
      'successor_draft_skipped', 'submitted', 'submitted', auth.uid(),
      'No remaining retention required a successor Draft.', p_correlation_id,
      jsonb_build_object('remainingOriginCount', 0)
    );
    return jsonb_build_object('succeeded', true, 'created', false);
  end if;

  insert into public.retention_claims (
    organization_id, project_id, claim_number, title, status,
    last_position_state_hash, last_eligibility_state_hash,
    created_by, draft_kind
  ) values (
    v_source.organization_id, v_source.project_id,
    private.generate_retention_claim_number(v_source.organization_id, v_source.project_id),
    'Retention Claim', 'draft', v_position ->> 'stateHash',
    v_eligibility ->> 'eligibilityStateHash', auth.uid(), 'automatic_rolling'
  ) returning * into v_successor;

  insert into public.retention_rolling_draft_origins (
    organization_id, project_id, retention_claim_id,
    originating_payment_claim_id, origin_sequence,
    latest_origin_state_hash, latest_origin_updated_at,
    latest_retention_owned
  )
  select
    v_source.organization_id, v_source.project_id, v_successor.id,
    claim.id,
    row_number() over (
      order by claim.claim_date asc nulls last, claim.created_at, claim.id
    )::integer,
    private.retention_claim_origin_state_hash(claim.id),
    claim.updated_at,
    greatest(coalesce((origin ->> 'currentRetentionOwned')::numeric, 0), 0)
  from jsonb_array_elements(coalesce(v_eligibility -> 'origins', '[]'::jsonb)) origin
  join public.project_claims claim
    on claim.id = (origin ->> 'originatingPaymentClaimId')::uuid
  where round(greatest(
    coalesce((origin ->> 'currentRetentionOwned')::numeric, 0)
    - coalesce((origin ->> 'committedRetention')::numeric, 0), 0
  ), 2) > 0;

  perform private.record_retention_claim_event(
    v_successor.organization_id, v_successor.project_id, v_successor.id,
    'successor_draft_created', null, 'draft', auth.uid(),
    'Automatic successor Retention Claim Draft created.', p_correlation_id,
    jsonb_build_object(
      'predecessorRetentionClaimId', v_source.id,
      'originCount', v_count
    )
  );
  return jsonb_build_object(
    'succeeded', true, 'created', true,
    'retentionClaimId', v_successor.id, 'originCount', v_count
  );
end;
$$;


ALTER FUNCTION "private"."create_retention_successor_draft"("p_submitted_claim_id" "uuid", "p_correlation_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."current_effective_retention_legacy_case"("p_project_id" "uuid") RETURNS "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select c.id
  from public.retention_legacy_reconciliation_cases c
  where c.project_id=p_project_id
    and c.status in ('approved','superseded')
    and c.approved_at is not null
  order by c.case_sequence desc limit 1;
$$;


ALTER FUNCTION "private"."current_effective_retention_legacy_case"("p_project_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."current_legacy_committed_by_origin"("p_project_id" "uuid") RETURNS TABLE("originating_payment_claim_id" "uuid", "amount" numeric)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select a.originating_payment_claim_id,round(sum(a.allocation_amount),2)
  from public.retention_legacy_release_allocations a
  where a.reconciliation_case_id=
    private.current_effective_retention_legacy_case(p_project_id)
  group by a.originating_payment_claim_id;
$$;


ALTER FUNCTION "private"."current_legacy_committed_by_origin"("p_project_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."decide_supplier_invoice_site_review_phase_ab_legacy"("p_decision_id" "uuid", "p_decision" "text", "p_note" "text", "p_accepted_variances" "jsonb" DEFAULT '[]'::"jsonb", "p_disputed_allocation_ids" "uuid"[] DEFAULT '{}'::"uuid"[]) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_member public.organization_members%rowtype;
  v_decision public.supplier_invoice_site_review_decisions%rowtype;
  v_submission public.supplier_invoice_site_review_submissions%rowtype;
  v_pending integer;
  v_approved integer;
  v_disputed integer;
begin
  select * into v_member from public.organization_members where user_id = auth.uid()
  order by created_at limit 1;
  select * into v_decision from public.supplier_invoice_site_review_decisions
  where id = p_decision_id and organization_id = v_member.organization_id for update;
  if not found then raise exception 'Site-review decision not found.'; end if;
  if v_decision.decision <> 'pending' then
    if v_decision.decision = p_decision then return v_decision.id; end if;
    raise exception 'The site-review decision has already been recorded.';
  end if;
  if not public.has_org_permission(v_member.organization_id, 'supplier_invoices.site_review') then
    raise exception 'You do not have permission to perform site review.';
  end if;
  if v_member.role not in ('owner', 'admin') and not exists (
    select 1 from public.project_members pm where pm.organization_id = v_member.organization_id
      and pm.project_id = v_decision.project_id and pm.organization_member_id = v_member.id and pm.is_active
  ) then raise exception 'You may only review Supplier Invoice costs for your assigned projects.'; end if;
  select * into v_submission from public.supplier_invoice_site_review_submissions
  where id = v_decision.submission_id and status in ('submitted', 'partially_reviewed', 'approved', 'disputed') for update;
  if not found or v_submission.finance_hash <> public.supplier_invoice_finance_version_hash(v_decision.supplier_invoice_id) then
    raise exception 'The site-review submission is no longer current.';
  end if;
  if p_decision not in ('approved', 'disputed') then raise exception 'Choose approved or disputed.'; end if;
  if p_decision = 'disputed' and char_length(trim(coalesce(p_note, ''))) = 0 then
    raise exception 'Add a dispute reason.';
  end if;
  if jsonb_typeof(coalesce(p_accepted_variances, '[]'::jsonb)) <> 'array' then
    raise exception 'Accepted variances must be an array.';
  end if;

  perform set_config('tradesstack.site_review_decision', 'on', true);
  update public.supplier_invoice_line_allocations
  set approval_status = p_decision,
      review_status = case when p_decision = 'approved' then 'resolved' else 'disputed' end,
      approval_notes = trim(coalesce(p_note, '')),
      reviewed_by_user_id = auth.uid(), reviewed_at = now(),
      approved_by_user_id = auth.uid(), approved_at = now()
  where organization_id = v_member.organization_id
    and id = any(v_decision.allocation_ids_snapshot);

  update public.supplier_invoice_site_review_decisions
  set decision = p_decision, reviewer_id = auth.uid(), reviewed_at = now(),
      note = trim(coalesce(p_note, '')), accepted_variances = coalesce(p_accepted_variances, '[]'::jsonb),
      disputed_allocation_ids = case when p_decision = 'disputed' then coalesce(p_disputed_allocation_ids, '{}') else '{}' end
  where id = p_decision_id;

  select count(*) filter (where decision = 'pending'), count(*) filter (where decision = 'approved'),
    count(*) filter (where decision = 'disputed')
  into v_pending, v_approved, v_disputed
  from public.supplier_invoice_site_review_decisions where submission_id = v_submission.id;
  update public.supplier_invoice_site_review_submissions
  set status = case when v_disputed > 0 then 'disputed' when v_pending = 0 then 'approved'
    when v_approved > 0 then 'partially_reviewed' else 'submitted' end
  where id = v_submission.id;

  insert into public.supplier_invoice_activity_events (
    organization_id, supplier_invoice_id, event_type, message, metadata, created_by
  ) values (v_member.organization_id, v_decision.supplier_invoice_id,
    case when p_decision = 'approved' then 'site_review_approved' else 'site_review_disputed' end,
    case when p_decision = 'approved' then 'Purchase Order costs approved by site review.' else 'Purchase Order costs disputed during site review.' end,
    jsonb_build_object('submission_id', v_submission.id, 'purchase_order_id', v_decision.purchase_order_id,
      'allocated_amount', v_decision.allocated_amount_snapshot), auth.uid());
  return p_decision_id;
end;
$$;


ALTER FUNCTION "private"."decide_supplier_invoice_site_review_phase_ab_legacy"("p_decision_id" "uuid", "p_decision" "text", "p_note" "text", "p_accepted_variances" "jsonb", "p_disputed_allocation_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."enforce_direct_retention_origin_inheritance"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private'
    AS $$
declare
  v_retention_revision public.organization_accounting_document_revisions%rowtype;
  v_origin_document public.organization_accounting_documents%rowtype;
  v_origin_revision public.organization_accounting_document_revisions%rowtype;
  v_origin_line public.organization_accounting_revision_lines%rowtype;
  v_origin_document_count integer;
  v_tax_type_count integer;
  v_origin_document_id uuid;
  v_origin_revision_id uuid;
  v_origin_line_id uuid;
  v_tax_type text;
begin
  if new.line_kind <> 'retention'
    or coalesce(new.source_snapshot->>'originEvidenceContract', '') <>
      'direct_immutable_retention_v1' then
    return new;
  end if;

  v_origin_document_id :=
    nullif(new.source_snapshot->>'originAccountingDocumentId', '')::uuid;
  v_origin_revision_id :=
    nullif(new.source_snapshot->>'originAccountingRevisionId', '')::uuid;
  v_origin_line_id :=
    nullif(new.source_snapshot->>'originAccountingRevisionLineId', '')::uuid;

  select revision.* into v_retention_revision
  from public.organization_accounting_document_revisions revision
  where revision.id = new.accounting_revision_id
    and revision.organization_id = new.organization_id
    and revision.source_document_type = 'retention_claim';
  if not found then
    raise exception 'RETENTION_ORIGIN_IDENTITY_MISMATCH: destination revision';
  end if;

  select count(*)::integer into v_origin_document_count
  from public.organization_accounting_documents document
  join public.organization_accounting_document_revisions revision
    on revision.id = document.active_accounting_revision_id
   and revision.organization_id = document.organization_id
   and revision.accounting_document_id = document.id
   and revision.lifecycle_state = 'succeeded'
   and revision.source_document_type = 'project_claim'
   and revision.source_document_id = new.originating_payment_claim_id
  where document.organization_id = new.organization_id
    and document.provider = 'xero'
    and document.local_document_type = 'project_claim'
    and document.project_claim_id = new.originating_payment_claim_id
    and document.integration_contract = 'payment_claim_revision_v1';
  if v_origin_document_count = 0 then
    raise exception 'ORIGIN_REVISION_MISSING: effective succeeded origin';
  elsif v_origin_document_count <> 1 then
    raise exception 'ORIGIN_REVISION_AMBIGUOUS: effective succeeded origin';
  end if;

  select document.* into v_origin_document
  from public.organization_accounting_documents document
  join public.organization_accounting_document_revisions revision
    on revision.id = document.active_accounting_revision_id
   and revision.organization_id = document.organization_id
   and revision.accounting_document_id = document.id
   and revision.lifecycle_state = 'succeeded'
  where document.id = v_origin_document_id
    and document.organization_id = new.organization_id
    and document.provider = 'xero'
    and document.local_document_type = 'project_claim'
    and document.project_claim_id = new.originating_payment_claim_id
    and document.integration_contract = 'payment_claim_revision_v1'
    and revision.id = v_origin_revision_id
    and revision.source_document_type = 'project_claim'
    and revision.source_document_id = new.originating_payment_claim_id;
  if not found then
    raise exception 'ORIGIN_REVISION_CHANGED: immutable origin is no longer effective';
  end if;
  select revision.* into v_origin_revision
  from public.organization_accounting_document_revisions revision
  where revision.id = v_origin_revision_id
    and revision.organization_id = new.organization_id
    and revision.accounting_document_id = v_origin_document.id
    and revision.lifecycle_state = 'succeeded'
    and revision.source_document_type = 'project_claim'
    and revision.source_document_id = new.originating_payment_claim_id;
  if not found then
    raise exception 'ORIGIN_REVISION_CHANGED: immutable origin revision is no longer effective';
  end if;
  if v_origin_revision.organization_id <> v_retention_revision.organization_id
    or v_origin_revision.project_id is distinct from v_retention_revision.project_id
    or v_origin_revision.connection_id <> v_retention_revision.connection_id
    or v_origin_revision.tenant_id <> v_retention_revision.tenant_id
    or v_origin_revision.currency_code <> v_retention_revision.currency_code then
    raise exception 'RETENTION_ORIGIN_IDENTITY_MISMATCH: organization, project, connection, tenant, or currency';
  end if;

  select line.* into v_origin_line
  from public.organization_accounting_revision_lines line
  where line.id = v_origin_line_id
    and line.organization_id = new.organization_id
    and line.accounting_revision_id = v_origin_revision.id
    and line.line_kind = 'retention'
    and line.originating_payment_claim_id = new.originating_payment_claim_id;
  if not found then
    raise exception 'ORIGIN_RETENTION_LINE_MISSING: immutable origin line';
  end if;
  if v_origin_line.line_amount_minor >= 0
    or v_origin_line.total_minor <>
      v_origin_line.line_amount_minor + v_origin_line.tax_minor
    or (
      v_origin_line.tax_minor <> 0
      and sign(v_origin_line.line_amount_minor) <>
        sign(v_origin_line.tax_minor)
    )
    or nullif(trim(v_origin_line.account_snapshot->>'accountCode'), '')
      is distinct from '700' then
    raise exception 'ORIGIN_RETENTION_LINE_INVALID: immutable origin amounts or account';
  end if;

  v_tax_type := nullif(trim(v_origin_line.tax_snapshot->>'taxType'), '');
  if v_tax_type is null
    or nullif(trim(v_origin_revision.tax_snapshot->>'taxRateId'), '') is null
    or nullif(trim(v_origin_revision.tax_snapshot->>'effectiveRate'), '') is null
    or nullif(trim(v_origin_revision.tax_snapshot->>'taxType'), '')
      is distinct from v_tax_type then
    raise exception 'ORIGIN_TAX_EVIDENCE_MISSING: immutable origin tax snapshot';
  end if;

  select count(*)::integer into v_tax_type_count
  from public.organization_accounting_tax_rates tax_rate
  where tax_rate.organization_id = v_origin_revision.organization_id
    and tax_rate.provider = 'xero'
    and tax_rate.accounting_connection_id = v_origin_revision.connection_id
    and tax_rate.tenant_id = v_origin_revision.tenant_id
    and tax_rate.is_active
    and upper(tax_rate.status) = 'ACTIVE'
    and tax_rate.metadata->>'canApplyToRevenue' = 'true'
    and upper(tax_rate.tax_type) = upper(v_tax_type);
  if v_tax_type_count <> 1 then
    raise exception 'ORIGIN_TAX_TYPE_UNAVAILABLE: immutable origin TaxType';
  end if;

  if new.line_amount_minor <> -v_origin_line.line_amount_minor
    or new.tax_minor <> -v_origin_line.tax_minor
    or new.total_minor <> -v_origin_line.total_minor
    or new.total_minor <> new.line_amount_minor + new.tax_minor
    or new.tax_snapshot->>'taxType' is distinct from v_tax_type
    or new.tax_snapshot->>'taxRateId' is distinct from
      v_origin_revision.tax_snapshot->>'taxRateId'
    or new.account_snapshot->>'accountCode' is distinct from
      v_origin_line.account_snapshot->>'accountCode' then
    raise exception 'RETENTION_ORIGIN_INVERSION_MISMATCH: release must exactly reverse origin';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "private"."enforce_direct_retention_origin_inheritance"() OWNER TO "postgres";


