    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  -- Retired. Kept as a no-op so previously compiled callers cannot create a
  -- Retention Claim or consume an RC number.
  return;
end;
$$;


