CREATE OR REPLACE FUNCTION "private"."ensure_master_retention_claim"("p_organization_id" "uuid", "p_project_id" "uuid", "p_actor_user_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private', 'extensions'
    AS $_$
declare
  v_master_id uuid;
  v_claim_number text;
  v_subtotal numeric(14,2);
  v_issue_date date;
  v_due_date date;
  v_state_hash text;
begin
  perform pg_advisory_xact_lock(
    hashtextextended(
      p_organization_id::text || ':' || p_project_id::text
        || ':master_retention_claim',
      2634
    )
  );

  select claim.id into v_master_id
  from public.retention_claims claim
  where claim.organization_id = p_organization_id
    and claim.project_id = p_project_id
    and claim.master_role = 'master_retention_claim'
  limit 1;
  if v_master_id is not null then
    return v_master_id;
  end if;

  -- Historical projects require a reviewed classification. Never manufacture
  -- a second commercial identity beside existing Retention records.
  if exists (
    select 1 from public.retention_claims claim
    where claim.organization_id = p_organization_id
      and claim.project_id = p_project_id
  ) then
    return null;
  end if;

  select
    round(sum(greatest(coalesce(claim.retention_withheld_amount, 0), 0)), 2),
    min(claim.claim_date),
    max(claim.due_date)
  into v_subtotal, v_issue_date, v_due_date
  from public.project_claims claim
  where claim.organization_id = p_organization_id
    and claim.project_id = p_project_id
    and claim.status = 'Submitted'
    and round(greatest(
      coalesce(claim.retention_withheld_amount, 0), 0
    ), 2) > 0;
  if coalesce(v_subtotal, 0) <= 0 then
    return null;
  end if;

  v_claim_number := private.generate_retention_claim_number(
    p_organization_id,
    p_project_id
  );
  if v_claim_number !~ '-RC-01$' then
    raise exception
      'A clean project master Retention identity must be RC-01.';
  end if;
  v_state_hash := encode(digest(convert_to(jsonb_build_object(
    'organizationId', p_organization_id,
    'projectId', p_project_id,
    'claimNumber', v_claim_number,
    'initialSubtotal', v_subtotal
  )::text, 'UTF8'), 'sha256'), 'hex');

  insert into public.retention_claims(
    organization_id, project_id, claim_number, title,
    issue_date, due_date, status, subtotal_excl_tax,
    submission_state_hash, submitted_by, submitted_at, created_by,
    draft_kind, master_role
  ) values (
    p_organization_id, p_project_id, v_claim_number, 'Retention Claim',
    v_issue_date, v_due_date, 'submitted', v_subtotal,
    v_state_hash, p_actor_user_id, now(), p_actor_user_id,
    'manual', 'master_retention_claim'
  )
  returning id into v_master_id;

  perform private.record_retention_claim_event(
    p_organization_id, p_project_id, v_master_id,
    'claim_created', null, 'submitted', p_actor_user_id,
    'Master Retention Claim initialized from submitted Payment Claim retention.',
    'master-retention-initialization:' || v_master_id::text,
    jsonb_build_object(
      'masterRetentionClaim', true,
      'claimNumber', v_claim_number,
      'initialCumulativeRetention', v_subtotal
    )
  );
  perform private.record_retention_claim_event(
    p_organization_id, p_project_id, v_master_id,
    'claim_submitted', null, 'submitted', p_actor_user_id,
    'Master Retention Claim uses cumulative structured Payment Claim evidence.',
    'master-retention-initialization:' || v_master_id::text,
    jsonb_build_object(
      'masterRetentionClaim', true,
      'structuredEvidenceOnly', true
    )
  );
  return v_master_id;
end;
$_$;


ALTER FUNCTION "private"."ensure_master_retention_claim"("p_organization_id" "uuid", "p_project_id" "uuid", "p_actor_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."evaluate_retention_variance_origin"("p_project_id" "uuid", "p_originating_payment_claim_id" "uuid", "p_correlation_id" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  s jsonb; v public.retention_variances%rowtype; old_state text; old_severity text;
  basis_hash text; event_name text; changed boolean:=false;
begin
  s:=private.retention_variance_snapshot(p_project_id,p_originating_payment_claim_id);
  if not coalesce((s->>'succeeded')::boolean,false) then return s; end if;
  perform pg_advisory_xact_lock(hashtextextended(
    p_originating_payment_claim_id::text||':retention_variance',5));
  select * into v from public.retention_variances
  where organization_id=(s->>'organizationId')::uuid
    and project_id=p_project_id
    and originating_payment_claim_id=p_originating_payment_claim_id
  for update;

  if not coalesce((s->>'hasVariance')::boolean,false) then
    if not found then return s||jsonb_build_object('action','none'); end if;
    old_state:=v.state;
    old_severity:=v.severity;
    perform set_config('app.retention_phase5_internal_write','true',true);
    update public.retention_variances set
      prior_phase2_state_hash=latest_phase2_state_hash,
      prior_phase4_eligibility_hash=latest_phase4_eligibility_hash,
      prior_committed_allocation_hash=committed_allocation_hash,
      current_ownership=(s->>'currentOwnership')::numeric,
      current_eligibility=(s->>'currentEligibility')::numeric,
      committed_retention=(s->>'committedRetention')::numeric,
      ownership_variance=(s->>'ownershipVariance')::numeric,
      eligibility_variance=(s->>'eligibilityVariance')::numeric,
      diagnostic_remaining=(s->>'diagnosticRemaining')::numeric,
      latest_phase2_state_hash=s->>'phase2StateHash',
      latest_phase4_eligibility_hash=s->>'phase4EligibilityHash',
      committed_allocation_hash=s->>'committedAllocationHash',
      affected_retention_claim_ids=array(
        select jsonb_array_elements_text(s->'affectedRetentionClaimIds')::uuid),
      affected_allocation_ids=array(
        select jsonb_array_elements_text(s->'affectedAllocationIds')::uuid),
      relied_schedule_ids=array(
        select jsonb_array_elements_text(s->'reliedScheduleIds')::uuid),
      current_schedule_ids=array(
        select jsonb_array_elements_text(s->'currentScheduleIds')::uuid),
      state=case when state='warning' then 'resolved' else state end,
      severity=case when state='warning' then 'low' else severity end,
      is_blocking=false,last_detected_at=now(),last_evaluated_at=now(),
      resolved_at=case when state='warning' then now() else resolved_at end,
      resolution_type=case when state='warning' then 'live_position_reconciled'
        else resolution_type end,
      last_correlation_id=p_correlation_id,revision=revision+1,updated_at=now()
    where id=v.id returning * into v;
    perform set_config('app.retention_phase5_internal_write','',true);
    if v.state='resolved' then
      perform private.record_retention_variance_event(
        v.id,'variance_auto_cleared',old_state,'resolved',old_severity,'low',
        'Warning auto-cleared because the live financial position reconciles.',
        p_correlation_id,'{}'::jsonb);
      return s||jsonb_build_object('action','auto_cleared','varianceId',v.id);
    end if;
    return s||jsonb_build_object('action','awaiting_explicit_resolution',
      'varianceId',v.id,'state',v.state);
  end if;

  basis_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'phase2',s->>'phase2StateHash','phase4',s->>'phase4EligibilityHash',
    'committed',s->>'committedAllocationHash','type',s->>'primaryType',
    'ownershipVariance',s->>'ownershipVariance',
    'eligibilityVariance',s->>'eligibilityVariance')::text,'UTF8'),'sha256'),'hex');

  if found then
    old_state:=v.state; old_severity:=v.severity;
    changed:=v.latest_phase2_state_hash<>(s->>'phase2StateHash')
      or v.latest_phase4_eligibility_hash<>(s->>'phase4EligibilityHash')
      or v.committed_allocation_hash<>(s->>'committedAllocationHash')
      or v.primary_type<>(s->>'primaryType')
      or v.current_ownership<>(s->>'currentOwnership')::numeric
      or v.current_eligibility<>(s->>'currentEligibility')::numeric
      or v.committed_retention<>(s->>'committedRetention')::numeric;
    -- An accepted override suppresses only the exact approved discrepancy.
    if v.state='accepted_contractual_override' and v.override_basis_hash=basis_hash then
      perform set_config('app.retention_phase5_internal_write','true',true);
      update public.retention_variances set last_evaluated_at=now(),
        last_detected_at=now(),last_correlation_id=p_correlation_id,
        revision=revision+1,updated_at=now() where id=v.id returning * into v;
      perform set_config('app.retention_phase5_internal_write','',true);
      return s||jsonb_build_object('action','override_unchanged','varianceId',v.id);
    end if;
    perform set_config('app.retention_phase5_internal_write','true',true);
    update public.retention_variances set
      prior_phase2_state_hash=latest_phase2_state_hash,
      prior_phase4_eligibility_hash=latest_phase4_eligibility_hash,
      prior_committed_allocation_hash=committed_allocation_hash,
      primary_type=s->>'primaryType',
      contributing_conditions=array(
        select jsonb_array_elements_text(s->'contributingConditions')),
      state=s->>'state',severity=s->>'severity',
      is_blocking=(s->>'isBlocking')::boolean,
      current_ownership=(s->>'currentOwnership')::numeric,
      current_eligibility=(s->>'currentEligibility')::numeric,
      committed_retention=(s->>'committedRetention')::numeric,
      ownership_variance=(s->>'ownershipVariance')::numeric,
      eligibility_variance=(s->>'eligibilityVariance')::numeric,
      diagnostic_remaining=(s->>'diagnosticRemaining')::numeric,
      latest_phase2_state_hash=s->>'phase2StateHash',
      latest_phase4_eligibility_hash=s->>'phase4EligibilityHash',
      committed_allocation_hash=s->>'committedAllocationHash',
      affected_retention_claim_ids=array(
        select jsonb_array_elements_text(s->'affectedRetentionClaimIds')::uuid),
      affected_allocation_ids=array(
        select jsonb_array_elements_text(s->'affectedAllocationIds')::uuid),
      relied_schedule_ids=array(
        select jsonb_array_elements_text(s->'reliedScheduleIds')::uuid),
      current_schedule_ids=array(
        select jsonb_array_elements_text(s->'currentScheduleIds')::uuid),
      resolution_type=null,resolution_reason=null,resolved_at=null,
      resolution_approved_by=null,override_approved_amount=null,override_basis_hash=null,
      last_detected_at=now(),last_evaluated_at=now(),
      last_correlation_id=p_correlation_id,revision=revision+1,updated_at=now()
    where id=v.id returning * into v;
    perform set_config('app.retention_phase5_internal_write','',true);
    event_name:=case when old_state in ('resolved','accepted_contractual_override')
      then 'variance_reopened'
      when old_severity<>v.severity then 'severity_changed'
      else 'variance_updated' end;
    if changed or event_name in ('variance_reopened','severity_changed') then
      perform private.record_retention_variance_event(v.id,event_name,old_state,v.state,
        old_severity,v.severity,'Retention variance reevaluated.',p_correlation_id,
        jsonb_build_object('basisHash',basis_hash));
    end if;
    return s||jsonb_build_object('action',case when event_name='variance_reopened'
      then 'reopened' else 'updated' end,'varianceId',v.id);
  end if;

  perform set_config('app.retention_phase5_internal_write','true',true);
  insert into public.retention_variances(
    organization_id,project_id,originating_payment_claim_id,primary_type,
    contributing_conditions,state,severity,is_blocking,current_ownership,
    current_eligibility,committed_retention,ownership_variance,eligibility_variance,
    diagnostic_remaining,latest_phase2_state_hash,latest_phase4_eligibility_hash,
    committed_allocation_hash,affected_retention_claim_ids,affected_allocation_ids,
    relied_schedule_ids,current_schedule_ids,last_correlation_id
  ) values (
    (s->>'organizationId')::uuid,p_project_id,p_originating_payment_claim_id,
    s->>'primaryType',array(select jsonb_array_elements_text(s->'contributingConditions')),
    s->>'state',s->>'severity',(s->>'isBlocking')::boolean,
    (s->>'currentOwnership')::numeric,(s->>'currentEligibility')::numeric,
    (s->>'committedRetention')::numeric,(s->>'ownershipVariance')::numeric,
    (s->>'eligibilityVariance')::numeric,(s->>'diagnosticRemaining')::numeric,
    s->>'phase2StateHash',s->>'phase4EligibilityHash',
    s->>'committedAllocationHash',
    array(select jsonb_array_elements_text(s->'affectedRetentionClaimIds')::uuid),
    array(select jsonb_array_elements_text(s->'affectedAllocationIds')::uuid),
    array(select jsonb_array_elements_text(s->'reliedScheduleIds')::uuid),
    array(select jsonb_array_elements_text(s->'currentScheduleIds')::uuid),
    p_correlation_id
  ) returning * into v;
  perform set_config('app.retention_phase5_internal_write','',true);
  perform private.record_retention_variance_event(v.id,'variance_detected',null,v.state,
    null,v.severity,'Retention variance detected.',p_correlation_id,
    jsonb_build_object('basisHash',basis_hash));
  return s||jsonb_build_object('action','detected','varianceId',v.id);
end;
$$;


ALTER FUNCTION "private"."evaluate_retention_variance_origin"("p_project_id" "uuid", "p_originating_payment_claim_id" "uuid", "p_correlation_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."evaluate_retention_variance_project"("p_project_id" "uuid", "p_correlation_id" "text" DEFAULT NULL::"text", "p_origin_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare r record; item jsonb; results jsonb:='[]'::jsonb; count_origins integer:=0;
begin
  for r in
    select p.id from public.project_claims p
    where p.project_id=p_project_id and (
      (p_origin_ids is not null and p.id=any(p_origin_ids))
      or (p_origin_ids is null and (
        exists(
          select 1 from public.retention_claim_allocations a
          join public.retention_claims c on c.id=a.retention_claim_id
          where c.status='submitted' and a.originating_payment_claim_id=p.id
        )
        or exists(
        select 1 from public.retention_variances v
        where v.project_id=p_project_id and v.originating_payment_claim_id=p.id
        )
      ))
    )
    order by p.id
  loop
    item:=private.evaluate_retention_variance_origin(p_project_id,r.id,p_correlation_id);
    results:=results||jsonb_build_array(item);
    count_origins:=count_origins+1;
  end loop;
  return jsonb_build_object('succeeded',true,'errorCode',null,
    'projectId',p_project_id,'originCount',count_origins,'results',results);
exception when others then
  return jsonb_build_object('succeeded',false,'errorCode','scan_failed',
    'projectId',p_project_id,'message',sqlerrm);
end;
$$;


ALTER FUNCTION "private"."evaluate_retention_variance_project"("p_project_id" "uuid", "p_correlation_id" "text", "p_origin_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."generate_activation_reminders"("p_schedule_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_s public.project_retention_release_schedules%rowtype; v_tz text; v_count integer;
begin
  select * into v_s from public.project_retention_release_schedules where id=p_schedule_id;
  select o.timezone into v_tz from public.organizations o where o.id=v_s.organization_id;
  if not exists(select 1 from pg_timezone_names where name=v_tz) then v_tz:='UTC'; end if;
  with rules as (
    select value as rule,ordinality
    from jsonb_array_elements(v_s.reminder_rules) with ordinality
  ), normalized as (
    select
      coalesce(rule->>'type','custom') as reminder_type,
      coalesce((rule->>'offsetDays')::integer,0) as offset_days,
      coalesce(rule->>'recurrence','none') as recurrence_type,
      (rule->>'customIntervalDays')::integer as recurrence_interval,
      (rule->>'escalationAfterDays')::integer as escalation_after_days,
      coalesce(rule->>'assignedPermissionKey','retention.reminders.manage') as assigned_permission_key,
      ordinality
    from rules
    where coalesce(rule->>'type','') in
      ('pre_eligibility','eligibility_due','overdue_unclaimed','escalation','custom')
  ), inserted as (
    insert into public.retention_reminders(
      organization_id,project_id,schedule_id,reminder_type,contractual_due_date,
      organization_timezone,due_at,assigned_permission_key,recurrence_type,
      recurrence_interval,escalation_after_days,state,next_delivery_at,
      occurrence_key,created_by
    )
    select
      v_s.organization_id,v_s.project_id,v_s.id,n.reminder_type,
      v_s.eligibility_date+n.offset_days,v_tz,
      ((v_s.eligibility_date+n.offset_days)::timestamp at time zone v_tz),
      n.assigned_permission_key,n.recurrence_type,n.recurrence_interval,
      n.escalation_after_days,'scheduled',
      ((v_s.eligibility_date+n.offset_days)::timestamp at time zone v_tz),
      format('activation:%s:%s:%s',n.ordinality,n.reminder_type,v_s.eligibility_date+n.offset_days),
      auth.uid()
    from normalized n
    on conflict(schedule_id,occurrence_key) do nothing
    returning id
  )
  select count(*) into v_count from inserted;
  perform private.record_retention_reminder_event(
    r.id,'reminder_created',null,'scheduled','Activation reminder created.',null,
    jsonb_build_object('contractualDueDate',r.contractual_due_date)
  )
  from public.retention_reminders r
  where r.schedule_id=v_s.id and r.created_at>=v_s.activated_at;
  return coalesce(v_count,0);
end;
$$;


ALTER FUNCTION "private"."generate_activation_reminders"("p_schedule_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."generate_retention_claim_number"("p_organization_id" "uuid", "p_project_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_project_code text;
  v_next_number integer;
begin
  select coalesce(
    nullif(trim(project.project_code), ''),
    nullif(regexp_replace(upper(coalesce(project.slug, '')), '[^A-Z0-9]+', '-', 'g'), ''),
    'JOB'
  )
  into v_project_code
  from public.organization_projects project
  where project.organization_id = p_organization_id
    and project.id = p_project_id;

  if v_project_code is null then
    raise exception 'Retention Claim project identity could not be resolved.';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended(p_project_id::text || ':retention_claim', 3)
  );

  insert into public.project_retention_claim_counters (
    organization_id,
    project_id,
    last_number
  )
  values (p_organization_id, p_project_id, 1)
  on conflict (project_id)
  do update
  set
    last_number = public.project_retention_claim_counters.last_number + 1,
    updated_at = now()
  returning last_number into v_next_number;

  return format('%s-RC-%s', v_project_code, lpad(v_next_number::text, 2, '0'));
end;
$$;


ALTER FUNCTION "private"."generate_retention_claim_number"("p_organization_id" "uuid", "p_project_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."maintain_retention_rolling_draft"("p_originating_payment_claim_id" "uuid", "p_operation" "text", "p_correlation_id" "text", "p_retry_count" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select jsonb_build_object(
    'succeeded', true,
    'changed', false,
    'result', 'retired'
  );
$$;


ALTER FUNCTION "private"."maintain_retention_rolling_draft"("p_originating_payment_claim_id" "uuid", "p_operation" "text", "p_correlation_id" "text", "p_retry_count" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."maintain_retention_rolling_draft_pre_document_lock"("p_originating_payment_claim_id" "uuid", "p_operation" "text", "p_correlation_id" "text", "p_retry_count" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  origin public.project_claims%rowtype;
  rolling_claim public.retention_claims%rowtype;
  existing_origin public.retention_rolling_draft_origins%rowtype;
  actor_user_id uuid;
  position jsonb;
  origin_hash text;
  inserted_origin boolean := false;
  draft_created boolean := false;
  changed boolean := false;
  next_sequence integer;
begin
  select * into origin
  from public.project_claims claim
  where claim.id = p_originating_payment_claim_id
  for update;

  if not found
    or origin.status not in ('Submitted', 'Unpaid', 'Paid', 'Overdue')
    or round(coalesce(origin.retention_withheld_amount, 0), 2) <= 0 then
    return jsonb_build_object('succeeded', true, 'changed', false, 'result', 'no_change');
  end if;

  if not exists (
    select 1
    from public.organization_capabilities capability
    join public.project_retention_workflow_states workflow
      on workflow.organization_id = capability.organization_id
     and workflow.project_id = origin.project_id
    where capability.organization_id = origin.organization_id
      and capability.capability_key = 'retention_management'
      and capability.enabled
      and workflow.mode = 'observe'
  ) then
    perform private.retention_rolling_record_event(
      origin.organization_id, origin.project_id, origin.id, null,
      p_operation, 'gate_closed', p_retry_count, p_correlation_id
    );
    return jsonb_build_object('succeeded', true, 'changed', false, 'result', 'gate_closed');
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended(origin.project_id::text || ':automatic_retention_draft', 7)
  );

  select claim.* into rolling_claim
  from public.retention_claims claim
  where claim.organization_id = origin.organization_id
    and claim.project_id = origin.project_id
    and claim.status = 'draft'
    and claim.draft_kind = 'automatic_rolling'
  for update;

  if rolling_claim.id is null and p_operation = 'refresh' then
    return jsonb_build_object('succeeded', true, 'changed', false, 'result', 'no_change');
  end if;

  actor_user_id := coalesce(origin.created_by, auth.uid());
  if actor_user_id is null then
    select member.user_id into actor_user_id
    from public.organization_members member
    where member.organization_id = origin.organization_id
    order by
      case member.role when 'owner' then 0 when 'admin' then 1 else 2 end,
      member.created_at,
      member.id
    limit 1;
  end if;
  if actor_user_id is null then
    raise exception 'No organization actor is available for the automatic Retention Draft.';
  end if;

  position := public.get_project_retention_position_summary(origin.project_id);
  origin_hash := private.retention_claim_origin_state_hash(origin.id);

  if rolling_claim.id is null then
    insert into public.retention_claims (
      organization_id, project_id, claim_number, title, status,
      last_position_state_hash, created_by, draft_kind
    )
    values (
      origin.organization_id,
      origin.project_id,
      private.generate_retention_claim_number(origin.organization_id, origin.project_id),
      'Retention Claim',
      'draft',
      position ->> 'stateHash',
      actor_user_id,
      'automatic_rolling'
    )
    returning * into rolling_claim;
    draft_created := true;

    perform private.record_retention_claim_event(
      rolling_claim.organization_id,
      rolling_claim.project_id,
      rolling_claim.id,
      'claim_created',
      null,
      'draft',
      actor_user_id,
      'Automatic rolling Retention Claim Draft created.',
      p_correlation_id,
      jsonb_build_object('automaticRolling', true, 'originatingPaymentClaimId', origin.id)
    );
  end if;

  select * into existing_origin
  from public.retention_rolling_draft_origins candidate
  where candidate.retention_claim_id = rolling_claim.id
    and candidate.originating_payment_claim_id = origin.id
  for update;

  if existing_origin.id is null then
    select coalesce(max(candidate.origin_sequence), 0) + 1
    into next_sequence
    from public.retention_rolling_draft_origins candidate
    where candidate.retention_claim_id = rolling_claim.id;

    insert into public.retention_rolling_draft_origins (
      organization_id, project_id, retention_claim_id,
      originating_payment_claim_id, origin_sequence,
      latest_origin_state_hash, latest_origin_updated_at,
      latest_retention_owned
    )
    values (
      origin.organization_id, origin.project_id, rolling_claim.id,
      origin.id, next_sequence, origin_hash, origin.updated_at,
      round(greatest(origin.retention_withheld_amount, 0), 2)
    );
    inserted_origin := true;
    changed := true;
  elsif existing_origin.latest_origin_state_hash is distinct from origin_hash
    or existing_origin.latest_retention_owned is distinct from
      round(greatest(origin.retention_withheld_amount, 0), 2) then
    update public.retention_rolling_draft_origins candidate
    set
      latest_origin_state_hash = origin_hash,
      latest_origin_updated_at = origin.updated_at,
      latest_retention_owned = round(greatest(origin.retention_withheld_amount, 0), 2),
      last_refreshed_at = now(),
      updated_at = now()
    where candidate.id = existing_origin.id;
    changed := true;
  end if;

  if changed then
    set constraints retention_rolling_draft_origins_sequence_unique deferred;
    with ordered as (
      select
        candidate.id,
        row_number() over (
          order by source.claim_date asc nulls last,
                   source.created_at asc,
                   source.id asc
        )::integer as sequence
      from public.retention_rolling_draft_origins candidate
      join public.project_claims source
        on source.id = candidate.originating_payment_claim_id
      where candidate.retention_claim_id = rolling_claim.id
    )
    update public.retention_rolling_draft_origins candidate
    set origin_sequence = ordered.sequence
    from ordered
    where candidate.id = ordered.id
      and candidate.origin_sequence is distinct from ordered.sequence;

    update public.retention_claims claim
    set
      last_position_state_hash = position ->> 'stateHash',
      draft_revision = claim.draft_revision + 1,
      updated_at = now()
    where claim.id = rolling_claim.id;
  end if;

  perform private.retention_rolling_record_event(
    origin.organization_id,
    origin.project_id,
    origin.id,
    rolling_claim.id,
    p_operation,
    case
      when draft_created then 'draft_created'
      when inserted_origin then 'origin_added'
      when changed then 'origin_refreshed'
      else 'no_change'
    end,
    p_retry_count,
    p_correlation_id,
    null,
    jsonb_build_object(
      'claimNumber', rolling_claim.claim_number,
      'retentionOwned', round(greatest(origin.retention_withheld_amount, 0), 2)
    )
  );

  return jsonb_build_object(
    'succeeded', true,
    'changed', changed or draft_created,
    'result', case
      when draft_created then 'draft_created'
      when inserted_origin then 'origin_added'
      when changed then 'origin_refreshed'
      else 'no_change'
    end,
    'retentionClaimId', rolling_claim.id,
    'claimNumber', rolling_claim.claim_number
  );
end;
$$;


ALTER FUNCTION "private"."maintain_retention_rolling_draft_pre_document_lock"("p_originating_payment_claim_id" "uuid", "p_operation" "text", "p_correlation_id" "text", "p_retry_count" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."master_retention_claim_source"("p_retention_claim_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
  with master as (
    select *
    from public.retention_claims
    where id = p_retention_claim_id
      and master_role = 'master_retention_claim'
      and status = 'submitted'
  ),
  origins as (
    select
      payment_claim.*,
      row_number() over (
        order by payment_claim.claim_date nulls last,
          payment_claim.created_at, payment_claim.id
      )::integer as sequence
    from public.project_claims payment_claim
    join master on master.organization_id = payment_claim.organization_id
      and master.project_id = payment_claim.project_id
    where payment_claim.status = 'Submitted'
      and round(greatest(
        coalesce(payment_claim.retention_withheld_amount, 0), 0
      ), 2) > 0
  ),
  position as (
    select
      coalesce(jsonb_agg(
        jsonb_build_object(
          'id', origin.id,
          'allocationSequence', origin.sequence,
          'originatingPaymentClaimId', origin.id,
          'allocationAmount',
            round(origin.retention_withheld_amount, 2),
          'originClaimNumberSnapshot', origin.claim_number,
          'originClaimDateSnapshot', origin.claim_date,
          'originClaimStatusSnapshot', origin.status,
          'originRetentionOwnedSnapshot',
            round(origin.retention_withheld_amount, 2),
          'retentionMethodSnapshot', origin.retention_method,
          'retentionRateSnapshot', origin.retention_percent,
          'retentionWithheldSnapshot',
            round(origin.retention_withheld_amount, 2),
          'retentionReleasedSnapshot', 0,
          'retentionBalanceSnapshot',
            round(origin.retention_withheld_amount, 2),
          'existingSubmittedAllocationBefore', 0,
          'remainingAfterAllocation', 0,
          'projectStateHashSnapshot', null,
          'originStateHashSnapshot', encode(digest(convert_to(
            jsonb_build_object(
              'id', origin.id,
              'claimNumber', origin.claim_number,
              'status', origin.status,
              'retention', round(origin.retention_withheld_amount, 2),
              'updatedAt', origin.updated_at
            )::text, 'UTF8'
          ), 'sha256'), 'hex'),
          'eligibilityStateHashSnapshot', null,
          'eligibilityScheduleIdsSnapshot', '[]'::jsonb,
          'submittedAt', origin.updated_at
        )
        order by origin.sequence
      ), '[]'::jsonb) as lines,
      coalesce(round(sum(origin.retention_withheld_amount), 2), 0) as subtotal,
      max(origin.updated_at) as latest_origin_at
    from origins origin
  ),
  evidence as (
    select
      master.*,
      position.lines,
      position.subtotal,
      greatest(
        master.submitted_at,
        master.updated_at,
        position.latest_origin_at
      ) as revised_at,
      encode(digest(convert_to(jsonb_build_object(
        'organizationId', master.organization_id,
        'projectId', master.project_id,
        'claimNumber', master.claim_number,
        'origins', position.lines,
        'subtotal', position.subtotal
      )::text, 'UTF8'), 'sha256'), 'hex') as state_hash
    from master cross join position
  )
  select jsonb_build_object(
    'schemaVersion', 1,
    'claim', jsonb_build_object(
      'id', evidence.id,
      'organizationId', evidence.organization_id,
      'projectId', evidence.project_id,
      'claimNumber', evidence.claim_number,
      'title', evidence.title,
      'reference', evidence.reference,
      'issueDate', evidence.issue_date,
      'dueDate', evidence.due_date,
      'status', 'submitted',
      'subtotalExclTax', evidence.subtotal,
      'submissionStateHash', evidence.state_hash,
      'submissionEligibilityStateHash', evidence.state_hash,
      'submittedBy', evidence.submitted_by,
      'submittedAt', evidence.revised_at
    ),
    'allocations', evidence.lines
  )
  from evidence;
$$;


ALTER FUNCTION "private"."master_retention_claim_source"("p_retention_claim_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."master_retention_claim_source_v2"("p_retention_claim_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'private', 'extensions'
    AS $_$
declare
  v_v1 jsonb;
  v_allocation jsonb;
  v_origin_id uuid;
  v_origin public.project_claims%rowtype;
  v_document public.organization_accounting_documents%rowtype;
  v_revision public.organization_accounting_document_revisions%rowtype;
  v_line public.organization_accounting_revision_lines%rowtype;
  v_classification public.organization_retention_tax_classifications_v2%rowtype;
  v_document_count integer;
  v_line_count integer;
  v_classification_count integer;
  v_tax_rate_count integer;
  v_blocker text;
  v_evidence_kind text;
  v_connection_id uuid;
  v_tenant_id text;
  v_currency_code text;
  v_tax_type text;
  v_tax_rate_snapshot_id text;
  v_tax_rate_name_snapshot text;
  v_effective_rate_basis_points integer;
  v_origin_amount bigint;
  v_origin_tax bigint;
  v_origin_total bigint;
  v_account_code text;
  v_account_id text;
  v_released_amount bigint;
  v_released_tax bigint;
  v_reserved_amount bigint;
  v_reserved_tax bigint;
  v_evidence jsonb;
  v_result jsonb := '[]'::jsonb;
begin
  v_v1 := private.master_retention_claim_source(p_retention_claim_id);
  if v_v1 is null then
    return null;
  end if;

  for v_allocation in
    select value from jsonb_array_elements(v_v1->'allocations')
  loop
    v_origin_id := (v_allocation->>'originatingPaymentClaimId')::uuid;
    select * into v_origin from public.project_claims where id = v_origin_id;
    v_blocker := null;
    v_evidence_kind := null;
    v_document := null;
    v_revision := null;
    v_line := null;
    v_classification := null;
    v_connection_id := null;
    v_tenant_id := null;
    v_currency_code := null;
    v_tax_type := null;
    v_tax_rate_snapshot_id := null;
    v_tax_rate_name_snapshot := null;
    v_effective_rate_basis_points := null;
    v_origin_amount := null;
    v_origin_tax := null;
    v_origin_total := null;
    v_account_code := null;
    v_account_id := null;

    select count(*)::integer into v_document_count
    from public.organization_accounting_documents document
    join public.organization_accounting_document_revisions revision
      on revision.id = document.active_accounting_revision_id
     and revision.organization_id = document.organization_id
     and revision.accounting_document_id = document.id
     and revision.lifecycle_state = 'succeeded'
     and revision.source_document_type = 'project_claim'
     and revision.source_document_id = v_origin_id
    where document.organization_id = v_origin.organization_id
      and document.project_claim_id = v_origin_id
      and document.local_document_type = 'project_claim'
      and document.provider = 'xero'
      and document.integration_contract = 'payment_claim_revision_v1';

    if v_document_count > 1 then
      v_blocker := 'origin_revision_ambiguous';
    elsif v_document_count = 1 then
      select document.*
      into v_document
      from public.organization_accounting_documents document
      join public.organization_accounting_document_revisions revision
        on revision.id = document.active_accounting_revision_id
       and revision.organization_id = document.organization_id
       and revision.accounting_document_id = document.id
       and revision.lifecycle_state = 'succeeded'
       and revision.source_document_type = 'project_claim'
       and revision.source_document_id = v_origin_id
      where document.organization_id = v_origin.organization_id
        and document.project_claim_id = v_origin_id
        and document.local_document_type = 'project_claim'
        and document.provider = 'xero'
        and document.integration_contract = 'payment_claim_revision_v1'
      limit 1;

      select revision.* into v_revision
      from public.organization_accounting_document_revisions revision
      where revision.id = v_document.active_accounting_revision_id
        and revision.organization_id = v_document.organization_id
        and revision.accounting_document_id = v_document.id
        and revision.lifecycle_state = 'succeeded';

      select count(*)::integer into v_line_count
      from public.organization_accounting_revision_lines line
      where line.organization_id = v_origin.organization_id
        and line.accounting_revision_id = v_revision.id
        and line.line_kind = 'retention'
        and line.originating_payment_claim_id = v_origin_id;

      if v_line_count = 0 then
        v_blocker := 'origin_retention_line_missing';
      elsif v_line_count > 1 then
        v_blocker := 'origin_retention_line_ambiguous';
      else
        select * into v_line
        from public.organization_accounting_revision_lines line
        where line.organization_id = v_origin.organization_id
          and line.accounting_revision_id = v_revision.id
          and line.line_kind = 'retention'
          and line.originating_payment_claim_id = v_origin_id;

        v_evidence_kind := case
          when v_revision.revision_intent = 'legacy_import'
            then 'exact_legacy_adoption'
          else 'immutable_revision'
        end;
        v_connection_id := v_revision.connection_id;
        v_tenant_id := v_revision.tenant_id;
        v_currency_code := v_revision.currency_code;
        v_tax_type := nullif(trim(v_line.tax_snapshot->>'taxType'), '');
        v_tax_rate_snapshot_id := nullif(
          trim(v_revision.tax_snapshot->>'taxRateId'), ''
        );
        v_tax_rate_name_snapshot := coalesce(
          nullif(trim(v_revision.tax_snapshot->>'name'), ''),
          nullif(trim(v_revision.tax_snapshot->>'taxRateName'), '')
        );
        if coalesce(v_revision.tax_snapshot->>'effectiveRate', '')
          ~ '^[0-9]+(?:\.[0-9]+)?$' then
          v_effective_rate_basis_points := round(
            (v_revision.tax_snapshot->>'effectiveRate')::numeric * 100
          )::integer;
        end if;
        v_origin_amount := v_line.line_amount_minor;
        v_origin_tax := v_line.tax_minor;
        v_origin_total := v_line.total_minor;
        v_account_code := nullif(
          trim(v_line.account_snapshot->>'accountCode'), ''
        );
        v_account_id := nullif(
          trim(v_revision.routing_snapshot#>>'{retention,accountId}'), ''
        );

        if v_line.line_amount_minor >= 0
          or v_line.total_minor <>
            v_line.line_amount_minor + v_line.tax_minor
          or (
            v_line.tax_minor <> 0
            and sign(v_line.line_amount_minor) <> sign(v_line.tax_minor)
          )
          or v_account_code is null
          or coalesce(v_revision.routing_snapshot#>>'{retention,route}', '')
            <> '700'
          or nullif(trim(
            v_revision.routing_snapshot#>>'{retention,accountCode}'
          ), '') is distinct from v_account_code then
          v_blocker := 'origin_retention_line_invalid';
        elsif abs(v_line.line_amount_minor) <>
          round((v_allocation->>'allocationAmount')::numeric * 100)::bigint then
          v_blocker := 'origin_amount_mismatch';
        elsif v_tax_type is null
          or v_effective_rate_basis_points is null then
          v_blocker := 'origin_tax_evidence_missing';
        end if;
      end if;
    else
      select count(*)::integer into v_classification_count
      from public.organization_retention_tax_classifications_v2 classification
      where classification.organization_id = v_origin.organization_id
        and classification.project_id = v_origin.project_id
        and classification.originating_payment_claim_id = v_origin_id
        and not exists (
          select 1
          from public.organization_retention_tax_classifications_v2 successor
          where successor.supersedes_classification_id = classification.id
        );

      if v_classification_count > 1 then
        v_blocker := 'legacy_tax_classification_ambiguous';
      elsif v_classification_count = 0 then
        v_blocker := 'origin_revision_missing';
      else
        select * into v_classification
        from public.organization_retention_tax_classifications_v2 classification
        where classification.organization_id = v_origin.organization_id
          and classification.project_id = v_origin.project_id
          and classification.originating_payment_claim_id = v_origin_id
          and not exists (
            select 1
            from public.organization_retention_tax_classifications_v2 successor
            where successor.supersedes_classification_id = classification.id
          );
        v_evidence_kind := v_classification.evidence_kind;
        v_connection_id := v_classification.xero_connection_id;
        v_tenant_id := v_classification.tenant_id;
        v_currency_code := v_classification.currency_code;
        v_tax_type := v_classification.tax_type;
        v_tax_rate_snapshot_id := v_classification.tax_rate_snapshot_id;
        v_tax_rate_name_snapshot := v_classification.tax_rate_name_snapshot;
        v_effective_rate_basis_points :=
          v_classification.effective_rate_basis_points;
        v_origin_amount := v_classification.origin_retained_amount_minor;
        v_origin_tax := v_classification.origin_retained_tax_minor;
        v_origin_total := v_classification.origin_retained_total_minor;
        v_account_code := nullif(
          trim(v_classification.evidence_snapshot->>'accountCode'), ''
        );
        v_account_id := nullif(
          trim(v_classification.evidence_snapshot->>'accountId'), ''
        );
        if abs(v_origin_amount) <>
          round((v_allocation->>'allocationAmount')::numeric * 100)::bigint then
          v_blocker := 'origin_amount_mismatch';
        end if;
      end if;
    end if;

    if v_blocker is null then
      select count(*)::integer into v_tax_rate_count
      from public.organization_accounting_tax_rates tax_rate
      where tax_rate.organization_id = v_origin.organization_id
        and tax_rate.provider = 'xero'
        and tax_rate.accounting_connection_id = v_connection_id
        and tax_rate.tenant_id = v_tenant_id
        and tax_rate.is_active
        and upper(tax_rate.status) = 'ACTIVE'
        and upper(tax_rate.tax_type) = upper(v_tax_type);
      if v_tax_rate_count = 0 then
        v_blocker := 'origin_tax_type_unavailable';
      elsif v_tax_rate_count > 1 then
        v_blocker := 'origin_tax_identity_ambiguous';
      end if;
    end if;

    select
      coalesce(sum(abs(ledger.released_amount_minor)) filter (
        where ledger.reservation_state = 'completed'
      ), 0),
      coalesce(sum(abs(ledger.released_tax_minor)) filter (
        where ledger.reservation_state = 'completed'
      ), 0),
      coalesce(sum(abs(ledger.released_amount_minor)) filter (
        where ledger.reservation_state in ('pending', 'reserved')
      ), 0),
      coalesce(sum(abs(ledger.released_tax_minor)) filter (
        where ledger.reservation_state in ('pending', 'reserved')
      ), 0)
    into v_released_amount, v_released_tax, v_reserved_amount, v_reserved_tax
    from public.organization_retention_release_allocation_ledger_v2 ledger
    where ledger.organization_id = v_origin.organization_id
      and ledger.project_id = v_origin.project_id
      and ledger.originating_payment_claim_id = v_origin_id
      and not exists (
        select 1
        from public.organization_retention_release_allocation_ledger_v2 successor
        where successor.supersedes_ledger_id = ledger.id
      );

    v_evidence := jsonb_strip_nulls(jsonb_build_object(
      'schemaVersion', 2,
      'status', case when v_blocker is null then 'resolved' else 'blocked' end,
      'blockerCode', v_blocker,
      'originatingPaymentClaimId', v_origin_id,
      'effectiveOriginAccountingDocumentId', v_document.id,
      'effectiveOriginRevisionId', v_revision.id,
      'originRevisionSequence', v_revision.revision_sequence,
      'originRetentionRevisionLineId', v_line.id,
      'originProviderInvoiceId', v_revision.external_document_id,
      'originPredecessorRevisionId', v_revision.previous_revision_id,
      'replacementRootAccountingDocumentId', v_document.id,
      'legacyTaxClassificationId', v_classification.id,
      'evidenceKind', v_evidence_kind,
      'originAmountMinor', v_origin_amount,
      'originTaxMinor', v_origin_tax,
      'originTotalMinor', v_origin_total,
      'taxType', v_tax_type,
      'taxRateSnapshotId', v_tax_rate_snapshot_id,
      'taxRateNameSnapshot', v_tax_rate_name_snapshot,
      'effectiveRateBasisPoints', v_effective_rate_basis_points,
      'originAccountCodeSnapshot', v_account_code,
      'originAccountIdSnapshot', v_account_id,
      'currencyCode', v_currency_code,
      'xeroConnectionId', v_connection_id,
      'tenantId', v_tenant_id,
      'releasedToDateAmountMinor', v_released_amount,
      'releasedToDateTaxMinor', v_released_tax,
      'reservedAmountMinor', v_reserved_amount,
      'reservedTaxMinor', v_reserved_tax
    ));
    v_evidence := v_evidence || jsonb_build_object(
      'evidenceHash', encode(digest(convert_to(
        v_evidence::text, 'UTF8'
      ), 'sha256'), 'hex')
    );
    v_result := v_result || jsonb_build_array(v_allocation || v_evidence);
  end loop;

  return jsonb_build_object(
    'schemaVersion', 2,
    'readOnly', true,
    'claim', v_v1->'claim',
    'allocations', v_result
  );
end;
$_$;


ALTER FUNCTION "private"."master_retention_claim_source_v2"("p_retention_claim_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."master_retention_date_edit_context"("p_retention_claim_id" "uuid", "p_lock" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private'
    AS $$
declare
  v_claim public.retention_claims%rowtype;
  v_context jsonb;
  v_document public.organization_accounting_documents%rowtype;
  v_revision public.organization_accounting_document_revisions%rowtype;
  v_projection public.organization_accounting_projections%rowtype;
  v_observation public.organization_accounting_remote_observations%rowtype;
  v_payment_count integer := 0;
  v_credit_count integer := 0;
begin
  select claim.* into v_claim
  from public.retention_claims claim
  where claim.id = p_retention_claim_id;
  if not found then
    return jsonb_build_object(
      'succeeded', false,
      'errorCode', 'RETENTION_DATE_RESET_BLOCKED',
      'reason', 'claim_not_found'
    );
  end if;

  v_context := private.retention_claim_operation_context(
    v_claim.project_id,
    'retention.claims.create',
    false
  );
  if not coalesce((v_context->>'succeeded')::boolean, false)
    or (v_context->>'organizationId')::uuid <> v_claim.organization_id then
    return jsonb_build_object(
      'succeeded', false,
      'errorCode', 'RETENTION_DATE_RESET_BLOCKED',
      'reason', coalesce(v_context->>'errorCode', 'permission_denied')
    );
  end if;
  if v_claim.status <> 'submitted'
    or v_claim.master_role <> 'master_retention_claim' then
    return jsonb_build_object(
      'succeeded', false,
      'errorCode', 'RETENTION_DATE_RESET_BLOCKED',
      'reason', 'not_submitted_master'
    );
  end if;

  if p_lock then
    perform pg_advisory_xact_lock(
      hashtextextended(v_claim.id::text, 2639)
    );
    select claim.* into v_claim
    from public.retention_claims claim
    where claim.id = p_retention_claim_id
      and claim.organization_id = (v_context->>'organizationId')::uuid
      and claim.status = 'submitted'
      and claim.master_role = 'master_retention_claim'
    for update;
    if not found then
      return jsonb_build_object(
        'succeeded', false,
        'errorCode', 'RETENTION_DATES_STALE',
        'reason', 'master_changed'
      );
    end if;
  end if;

  select document.* into v_document
  from public.organization_accounting_documents document
  where document.organization_id = v_claim.organization_id
    and document.retention_claim_id = v_claim.id
    and document.provider = 'xero'
    and document.local_document_type = 'retention_claim'
    and document.integration_contract = 'retention_claim_revision_v1'
  for update;
  if not found or v_document.active_accounting_revision_id is null then
    return jsonb_build_object(
      'succeeded', false,
      'errorCode', 'RETENTION_DATE_RESET_BLOCKED',
      'reason', 'active_accounting_identity_missing'
    );
  end if;

  select revision.* into v_revision
  from public.organization_accounting_document_revisions revision
  where revision.id = v_document.active_accounting_revision_id
    and revision.organization_id = v_claim.organization_id
    and revision.project_id = v_claim.project_id
    and revision.accounting_document_id = v_document.id
    and revision.lifecycle_state = 'succeeded'
    and revision.external_document_id = v_document.external_document_id
    and revision.external_document_number =
      v_document.external_document_number
  for update;
  if not found then
    return jsonb_build_object(
      'succeeded', false,
      'errorCode', 'RETENTION_DATE_RESET_BLOCKED',
      'reason', 'active_revision_not_stable'
    );
  end if;

  if not exists (
    select 1
    from public.organization_xero_connections connection
    where connection.id = v_revision.connection_id
      and connection.organization_id = v_claim.organization_id
      and connection.tenant_id = v_revision.tenant_id
      and connection.status = 'connected'
      and connection.scope @> array['accounting.invoices']::text[]
  ) then
    return jsonb_build_object(
      'succeeded', false,
      'errorCode', 'RETENTION_DATE_RESET_BLOCKED',
      'reason', 'connection_unavailable'
    );
  end if;

  if exists (
    select 1
    from public.organization_accounting_sync_jobs job
    where job.organization_id = v_claim.organization_id
      and job.provider = 'xero'
      and job.job_kind in (
        'xero.retention_claim.initial_push',
        'xero.retention_claim.update',
        'xero.retention_claim.replacement',
        'xero.retention_claim.refresh'
      )
      and job.queue_state in ('pending', 'claimed', 'retry_scheduled')
      and job.request_payload->>'accountingDocumentId' = v_document.id::text
  ) then
    return jsonb_build_object(
      'succeeded', false,
      'errorCode', 'RETENTION_DATE_RESET_BLOCKED',
      'reason', 'accounting_operation_processing'
    );
  end if;
  if exists (
    select 1
    from public.organization_accounting_revision_attempts attempt
    join public.organization_accounting_document_revisions revision
      on revision.id = attempt.accounting_revision_id
    where revision.accounting_document_id = v_document.id
      and attempt.attempt_intent in ('create', 'update', 'replace')
      and attempt.queue_state = 'attention_required'
  ) then
    return jsonb_build_object(
      'succeeded', false,
      'errorCode', 'RETENTION_DATE_RESET_BLOCKED',
      'reason', 'uncertain_accounting_result'
    );
  end if;

  select projection.* into v_projection
  from public.organization_accounting_projections projection
  where projection.accounting_document_id = v_document.id
    and projection.accounting_revision_id = v_revision.id
  for update;
  if not found
    or v_projection.normalized_invoice_status not in (
      'authorised', 'awaiting_payment'
    )
    or coalesce(v_projection.amount_paid_minor, 0) <> 0
    or coalesce(v_projection.amount_credited_minor, 0) <> 0
    or v_projection.divergent then
    return jsonb_build_object(
      'succeeded', false,
      'errorCode', 'RETENTION_DATE_RESET_BLOCKED',
      'reason', 'invoice_not_safely_updateable'
    );
  end if;

  select observation.* into v_observation
  from public.organization_accounting_remote_observations observation
  where observation.id = v_projection.remote_observation_id
    and observation.accounting_revision_id = v_revision.id
    and observation.external_document_id = v_revision.external_document_id;
  if found then
    v_payment_count := case
      when jsonb_typeof(v_observation.raw_observation->'Payments') = 'array'
      then jsonb_array_length(v_observation.raw_observation->'Payments')
      else 0
    end;
    v_credit_count := case
      when jsonb_typeof(v_observation.raw_observation->'CreditNotes') = 'array'
      then jsonb_array_length(v_observation.raw_observation->'CreditNotes')
      else 0
    end;
  end if;
  if not found
    or upper(coalesce(v_observation.raw_status, '')) <> 'AUTHORISED'
    or v_observation.observed_at < now() - interval '24 hours'
    or v_payment_count <> 0
    or v_credit_count <> 0 then
    return jsonb_build_object(
      'succeeded', false,
      'errorCode', 'RETENTION_DATE_RESET_BLOCKED',
      'reason', 'provider_state_not_safely_updateable'
    );
  end if;

  return jsonb_build_object(
    'succeeded', true,
    'errorCode', null,
    'organizationId', v_claim.organization_id,
    'projectId', v_claim.project_id,
    'actorUserId', v_context->>'actorUserId',
    'retentionClaimId', v_claim.id,
    'claimDate', v_claim.issue_date,
    'dueDate', v_claim.due_date,
    'optimisticRevision', v_claim.draft_revision,
    'activeAccountingRevisionId', v_revision.id,
    'invoiceId', v_revision.external_document_id,
    'invoiceNumber', v_revision.external_document_number
  );
end;
$$;


ALTER FUNCTION "private"."master_retention_date_edit_context"("p_retention_claim_id" "uuid", "p_lock" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."phase2b_actor_has_push_permission"("p_organization_id" "uuid", "p_actor_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select coalesce(
    (
      select o.is_allowed
      from public.organization_members m
      join public.member_permission_overrides o
        on o.organization_member_id = m.id
       and o.permission_key = 'accounting.sales_invoices.push'
      where m.organization_id = p_organization_id
        and m.user_id = p_actor_id
      limit 1
    ),
    (
      select rp.is_allowed
      from public.organization_members m
      join public.role_permissions rp
        on rp.role = m.role
       and rp.permission_key = 'accounting.sales_invoices.push'
      where m.organization_id = p_organization_id
        and m.user_id = p_actor_id
      limit 1
    ),
    false
  );
$$;


ALTER FUNCTION "private"."phase2b_actor_has_push_permission"("p_organization_id" "uuid", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."populate_retention_legacy_sources"("p_case_id" "uuid", "p_source_state" "jsonb") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare c public.retention_legacy_reconciliation_cases%rowtype; inserted_count integer;
begin
  select * into c from public.retention_legacy_reconciliation_cases where id=p_case_id;
  perform set_config('app.retention_phase6_internal_write','true',true);
  insert into public.retention_legacy_release_sources(
    organization_id,project_id,reconciliation_case_id,source_payment_claim_id,
    source_sequence,claim_number_snapshot,claim_date_snapshot,claim_status_snapshot,
    claim_created_at_snapshot,claim_updated_at_snapshot,
    retention_released_amount_snapshot,source_origin_state_hash
  )
  select c.organization_id,c.project_id,c.id,p.id,
    (x->>'chronologicalSequence')::integer,p.claim_number,p.claim_date,p.status,
    p.created_at,p.updated_at,round((x->>'retentionReleasedAmount')::numeric,2),
    private.retention_claim_origin_state_hash(p.id)
  from jsonb_array_elements(p_source_state->'legacyReleaseOrigins') x
  join public.project_claims p on p.id=(x->>'paymentClaimId')::uuid
    and p.organization_id=c.organization_id and p.project_id=c.project_id
  order by (x->>'chronologicalSequence')::integer,p.id;
  get diagnostics inserted_count=row_count;
  perform set_config('app.retention_phase6_internal_write','',true);
  return inserted_count;
end;
$$;


ALTER FUNCTION "private"."populate_retention_legacy_sources"("p_case_id" "uuid", "p_source_state" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."record_retention_claim_event"("p_organization_id" "uuid", "p_project_id" "uuid", "p_retention_claim_id" "uuid", "p_event_type" "text", "p_previous_status" "text", "p_new_status" "text", "p_actor_user_id" "uuid", "p_reason" "text", "p_correlation_id" "text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_event_id uuid;
begin
  insert into public.retention_claim_events (
    organization_id,
    project_id,
    retention_claim_id,
    event_type,
    previous_status,
    new_status,
    actor_user_id,
    reason,
    correlation_id,
    metadata
  )
  values (
    p_organization_id,
    p_project_id,
    p_retention_claim_id,
    p_event_type,
    p_previous_status,
    p_new_status,
    p_actor_user_id,
    coalesce(nullif(trim(p_reason), ''), p_event_type),
    nullif(trim(coalesce(p_correlation_id, '')), ''),
    coalesce(p_metadata, '{}'::jsonb)
  )
  returning id into v_event_id;

  return v_event_id;
end;
$$;


ALTER FUNCTION "private"."record_retention_claim_event"("p_organization_id" "uuid", "p_project_id" "uuid", "p_retention_claim_id" "uuid", "p_event_type" "text", "p_previous_status" "text", "p_new_status" "text", "p_actor_user_id" "uuid", "p_reason" "text", "p_correlation_id" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."record_retention_legacy_event"("p_case_id" "uuid", "p_event_type" "text", "p_previous_status" "text", "p_new_status" "text", "p_reason" "text", "p_correlation_id" "text" DEFAULT NULL::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare c public.retention_legacy_reconciliation_cases%rowtype; event_id uuid;
begin
  select * into c from public.retention_legacy_reconciliation_cases where id=p_case_id;
  if not found then return null; end if;
  insert into public.retention_legacy_reconciliation_events(
    organization_id,project_id,reconciliation_case_id,event_type,
    previous_status,new_status,actor_user_id,reason,correlation_id,
    position_state_hash,source_fingerprint,financial_snapshot,metadata
  ) values(
    c.organization_id,c.project_id,c.id,p_event_type,p_previous_status,p_new_status,
    auth.uid(),coalesce(nullif(trim(p_reason),''),p_event_type),
    nullif(trim(coalesce(p_correlation_id,'')),''),
    c.position_state_hash,c.source_fingerprint,
    jsonb_build_object(
      'totalLegacyReleased',c.total_legacy_released,
      'totalAllocated',c.total_allocated,
      'sourceCount',c.source_count,'allocationCount',c.allocation_count
    ),coalesce(p_metadata,'{}'::jsonb)
  ) returning id into event_id;
  return event_id;
end;
$$;


ALTER FUNCTION "private"."record_retention_legacy_event"("p_case_id" "uuid", "p_event_type" "text", "p_previous_status" "text", "p_new_status" "text", "p_reason" "text", "p_correlation_id" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."record_retention_reminder_event"("p_reminder_id" "uuid", "p_event_type" "text", "p_previous_state" "text", "p_new_state" "text", "p_reason" "text", "p_correlation_id" "text" DEFAULT NULL::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_r public.retention_reminders%rowtype; v_id uuid;
begin
  select * into v_r from public.retention_reminders where id=p_reminder_id;
  if not found then return null; end if;
  insert into public.retention_reminder_events(
    organization_id,project_id,reminder_id,schedule_id,event_type,previous_state,new_state,
    actor_user_id,reason,correlation_id,metadata
  ) values (
    v_r.organization_id,v_r.project_id,v_r.id,v_r.schedule_id,p_event_type,
    p_previous_state,p_new_state,auth.uid(),coalesce(nullif(trim(p_reason),''),p_event_type),
    nullif(trim(coalesce(p_correlation_id,'')),''),
    coalesce(p_metadata,'{}'::jsonb)
  ) returning id into v_id;
  return v_id;
end;
$$;


ALTER FUNCTION "private"."record_retention_reminder_event"("p_reminder_id" "uuid", "p_event_type" "text", "p_previous_state" "text", "p_new_state" "text", "p_reason" "text", "p_correlation_id" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."record_retention_schedule_event"("p_schedule_id" "uuid", "p_event_type" "text", "p_previous_status" "text", "p_new_status" "text", "p_reason" "text", "p_correlation_id" "text" DEFAULT NULL::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_s public.project_retention_release_schedules%rowtype; v_id uuid;
begin
  select * into v_s from public.project_retention_release_schedules where id=p_schedule_id;
  if not found then return null; end if;
  insert into public.retention_schedule_events(
    organization_id,project_id,schedule_id,event_type,previous_status,new_status,
    actor_user_id,reason,correlation_id,metadata
  ) values (
    v_s.organization_id,v_s.project_id,v_s.id,p_event_type,p_previous_status,p_new_status,
    auth.uid(),coalesce(nullif(trim(p_reason),''),p_event_type),
    nullif(trim(coalesce(p_correlation_id,'')),''),
    coalesce(p_metadata,'{}'::jsonb)
  ) returning id into v_id;
  return v_id;
end;
$$;


ALTER FUNCTION "private"."record_retention_schedule_event"("p_schedule_id" "uuid", "p_event_type" "text", "p_previous_status" "text", "p_new_status" "text", "p_reason" "text", "p_correlation_id" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."record_retention_variance_event"("p_variance_id" "uuid", "p_event_type" "text", "p_previous_state" "text", "p_new_state" "text", "p_previous_severity" "text", "p_new_severity" "text", "p_reason" "text", "p_correlation_id" "text" DEFAULT NULL::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v public.retention_variances%rowtype; v_id uuid;
begin
  select * into v from public.retention_variances where id=p_variance_id;
  if not found then return null; end if;
  insert into public.retention_variance_events(
    organization_id,project_id,variance_id,originating_payment_claim_id,event_type,
    previous_state,new_state,previous_severity,new_severity,actor_user_id,reason,
    correlation_id,phase2_state_hash,phase4_eligibility_hash,
    committed_allocation_hash,financial_snapshot,metadata
  ) values (
    v.organization_id,v.project_id,v.id,v.originating_payment_claim_id,p_event_type,
    p_previous_state,p_new_state,p_previous_severity,p_new_severity,auth.uid(),
    coalesce(nullif(trim(p_reason),''),p_event_type),
    nullif(trim(coalesce(p_correlation_id,'')),''),
    v.latest_phase2_state_hash,v.latest_phase4_eligibility_hash,
    v.committed_allocation_hash,
    jsonb_build_object(
      'currentOwnership',v.current_ownership,
      'currentEligibility',v.current_eligibility,
      'committedRetention',v.committed_retention,
      'ownershipVariance',v.ownership_variance,
      'eligibilityVariance',v.eligibility_variance,
      'diagnosticRemaining',v.diagnostic_remaining
    ),coalesce(p_metadata,'{}'::jsonb)
  ) returning id into v_id;
  return v_id;
end;
$$;


ALTER FUNCTION "private"."record_retention_variance_event"("p_variance_id" "uuid", "p_event_type" "text", "p_previous_state" "text", "p_new_state" "text", "p_previous_severity" "text", "p_new_severity" "text", "p_reason" "text", "p_correlation_id" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."record_supplier_invoice_accounts_approval_phase_ab_legacy"("p_supplier_invoice_id" "uuid", "p_site_review_submission_id" "uuid", "p_expected_finance_hash" "text", "p_approval_note" "text" DEFAULT ''::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_organization_id uuid;
  v_approval_id uuid;
  v_hash text;
begin
  select m.organization_id into v_organization_id from public.organization_members m
  where m.user_id = auth.uid() order by m.created_at limit 1;
  if v_organization_id is null
    or not public.has_org_permission(v_organization_id, 'supplier_invoices.accounts_approve') then
    raise exception 'You do not have permission to perform final Accounts approval.';
  end if;
  perform 1 from public.supplier_invoices i where i.id = p_supplier_invoice_id
    and i.organization_id = v_organization_id for update;
  if not found then raise exception 'Supplier Invoice not found.'; end if;
  v_hash := public.supplier_invoice_finance_version_hash(p_supplier_invoice_id);
  if v_hash is null or v_hash <> p_expected_finance_hash then
    raise exception 'Supplier Invoice finance data changed. Refresh and approve again.';
  end if;
  if p_site_review_submission_id is not null then
    if not exists (select 1 from public.supplier_invoice_site_review_submissions s
      where s.id = p_site_review_submission_id and s.organization_id = v_organization_id
        and s.supplier_invoice_id = p_supplier_invoice_id and s.finance_hash = v_hash and s.status = 'approved') then
      raise exception 'Every Purchase Order requires a current approved site-review decision.';
    end if;
  elsif exists (select 1 from public.supplier_invoice_line_allocations a
    where a.supplier_invoice_id = p_supplier_invoice_id and a.purchase_order_id is not null) then
    raise exception 'Matched Purchase Orders require site approval.';
  end if;
  if not exists (select 1 from public.supplier_invoice_commercial_approvals a
    where a.supplier_invoice_id = p_supplier_invoice_id and a.finance_version_hash = v_hash and a.status = 'approved') then
    raise exception 'A current commercial approval is required before final Accounts approval.';
  end if;
  select a.id into v_approval_id
  from public.supplier_invoice_accounts_approvals a
  where a.organization_id = v_organization_id
    and a.supplier_invoice_id = p_supplier_invoice_id
    and a.finance_hash = v_hash
    and a.site_review_submission_id is not distinct from p_site_review_submission_id
    and a.status = 'approved'
  order by a.created_at desc limit 1;
  if v_approval_id is not null then return v_approval_id; end if;
  update public.supplier_invoice_accounts_approvals
  set status = 'invalidated', invalidated_at = now(),
      invalidation_reason = 'Superseded by a newer Accounts approval.'
  where supplier_invoice_id = p_supplier_invoice_id and status = 'approved';
  insert into public.supplier_invoice_accounts_approvals (
    organization_id, supplier_invoice_id, site_review_submission_id, finance_hash,
    status, approved_by, approved_at, approval_note
  ) values (v_organization_id, p_supplier_invoice_id, p_site_review_submission_id,
    v_hash, 'approved', auth.uid(), now(), trim(coalesce(p_approval_note, '')))
  returning id into v_approval_id;
  insert into public.supplier_invoice_activity_events (
    organization_id, supplier_invoice_id, event_type, message, metadata, created_by
  ) values (v_organization_id, p_supplier_invoice_id, 'accounts_approved',
    'Supplier Invoice approved by Accounts for Xero readiness.',
    jsonb_build_object('accounts_approval_id', v_approval_id, 'finance_hash', v_hash), auth.uid());
  return v_approval_id;
end;
$$;


ALTER FUNCTION "private"."record_supplier_invoice_accounts_approval_phase_ab_legacy"("p_supplier_invoice_id" "uuid", "p_site_review_submission_id" "uuid", "p_expected_finance_hash" "text", "p_approval_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."refresh_retention_legacy_case_totals"("p_case_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  perform set_config('app.retention_phase6_internal_write','true',true);
  update public.retention_legacy_reconciliation_cases c set
    total_allocated=coalesce((
      select round(sum(a.allocation_amount),2)
      from public.retention_legacy_release_allocations a
      where a.reconciliation_case_id=c.id
    ),0),
    allocation_count=(
      select count(*) from public.retention_legacy_release_allocations a
      where a.reconciliation_case_id=c.id
    ),
    updated_at=now()
  where c.id=p_case_id;
  perform set_config('app.retention_phase6_internal_write','',true);
end;
$$;


ALTER FUNCTION "private"."refresh_retention_legacy_case_totals"("p_case_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."reject_retention_claim_submission"("p_retention_claim_id" "uuid", "p_error_code" "text", "p_details" "jsonb", "p_correlation_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_claim public.retention_claims%rowtype;
begin
  select * into v_claim
  from public.retention_claims claim
  where claim.id = p_retention_claim_id;

  if found then
    perform private.record_retention_claim_event(
      v_claim.organization_id,
      v_claim.project_id,
      v_claim.id,
      case
        when p_error_code in ('claim_not_draft', 'invalid_transition')
          then 'invalid_transition_attempted'
        else 'submission_rejected'
      end,
      v_claim.status,
      v_claim.status,
      auth.uid(),
      p_error_code,
      p_correlation_id,
      coalesce(p_details, '{}'::jsonb)
    );
  end if;

  return jsonb_build_object(
    'succeeded', false,
    'errorCode', p_error_code,
    'details', coalesce(p_details, '{}'::jsonb)
  );
end;
$$;


ALTER FUNCTION "private"."reject_retention_claim_submission"("p_retention_claim_id" "uuid", "p_error_code" "text", "p_details" "jsonb", "p_correlation_id" "text") OWNER TO "postgres";

SET default_tablespace = '';

SET default_table_access_method = "heap";


CREATE TABLE IF NOT EXISTS "public"."retention_claims" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "project_id" "uuid" NOT NULL,
    "claim_number" "text" NOT NULL,
    "title" "text" NOT NULL,
    "reference" "text",
    "issue_date" "date",
    "due_date" "date",
    "status" "text" DEFAULT 'draft'::"text" NOT NULL,
    "subtotal_excl_tax" numeric(14,2) DEFAULT 0 NOT NULL,
    "draft_revision" bigint DEFAULT 1 NOT NULL,
    "last_position_state_hash" "text",
    "submission_state_hash" "text",
    "submitted_by" "uuid",
    "submitted_at" timestamp with time zone,
    "cancelled_by" "uuid",
    "cancelled_at" timestamp with time zone,
    "created_by" "uuid" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "last_eligibility_state_hash" "text",
    "submission_eligibility_state_hash" "text",
    "draft_kind" "text" DEFAULT 'manual'::"text" NOT NULL,
    "master_role" "text" DEFAULT 'master_retention_claim'::"text",
    CONSTRAINT "retention_claims_date_order" CHECK ((("issue_date" IS NULL) OR ("due_date" IS NULL) OR ("due_date" >= "issue_date"))),
    CONSTRAINT "retention_claims_draft_kind_check" CHECK (("draft_kind" = ANY (ARRAY['manual'::"text", 'automatic_rolling'::"text"]))),
    CONSTRAINT "retention_claims_last_eligibility_hash_shape" CHECK ((("last_eligibility_state_hash" IS NULL) OR ("last_eligibility_state_hash" ~ '^[a-f0-9]{64}$'::"text"))),
    CONSTRAINT "retention_claims_last_hash_shape" CHECK ((("last_position_state_hash" IS NULL) OR ("last_position_state_hash" ~ '^[a-f0-9]{64}$'::"text"))),
    CONSTRAINT "retention_claims_lifecycle_fields_check" CHECK (((("status" = 'draft'::"text") AND ("subtotal_excl_tax" = (0)::numeric) AND ("submission_state_hash" IS NULL) AND ("submitted_by" IS NULL) AND ("submitted_at" IS NULL) AND ("cancelled_by" IS NULL) AND ("cancelled_at" IS NULL)) OR (("status" = 'submitted'::"text") AND ("submission_state_hash" IS NOT NULL) AND ("submitted_by" IS NOT NULL) AND ("submitted_at" IS NOT NULL) AND ("cancelled_by" IS NULL) AND ("cancelled_at" IS NULL)) OR (("status" = 'cancelled_draft'::"text") AND ("subtotal_excl_tax" = (0)::numeric) AND ("submission_state_hash" IS NULL) AND ("submitted_by" IS NULL) AND ("submitted_at" IS NULL) AND ("cancelled_by" IS NOT NULL) AND ("cancelled_at" IS NOT NULL)))),
    CONSTRAINT "retention_claims_master_role_check" CHECK ((("master_role" IS NULL) OR ("master_role" = ANY (ARRAY['master_retention_claim'::"text", 'obsolete_automatic_draft'::"text", 'legacy_separate_claim'::"text"])))),
    CONSTRAINT "retention_claims_number_not_blank" CHECK ((("char_length"(TRIM(BOTH FROM "claim_number")) >= 1) AND ("char_length"(TRIM(BOTH FROM "claim_number")) <= 100))),
    CONSTRAINT "retention_claims_reference_length" CHECK ((("reference" IS NULL) OR ("char_length"("reference") <= 250))),
    CONSTRAINT "retention_claims_revision_positive" CHECK (("draft_revision" > 0)),
    CONSTRAINT "retention_claims_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'submitted'::"text", 'cancelled_draft'::"text"]))),
    CONSTRAINT "retention_claims_submission_eligibility_hash_shape" CHECK ((("submission_eligibility_state_hash" IS NULL) OR ("submission_eligibility_state_hash" ~ '^[a-f0-9]{64}$'::"text"))),
    CONSTRAINT "retention_claims_submission_hash_shape" CHECK ((("submission_state_hash" IS NULL) OR ("submission_state_hash" ~ '^[a-f0-9]{64}$'::"text"))),
    CONSTRAINT "retention_claims_subtotal_nonnegative" CHECK (("subtotal_excl_tax" >= (0)::numeric)),
    CONSTRAINT "retention_claims_title_not_blank" CHECK ((("char_length"(TRIM(BOTH FROM "title")) >= 1) AND ("char_length"(TRIM(BOTH FROM "title")) <= 250)))
);

ALTER TABLE ONLY "public"."retention_claims" FORCE ROW LEVEL SECURITY;


ALTER TABLE "public"."retention_claims" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."reject_retention_document_save"("p_claim" "public"."retention_claims", "p_error_code" "text", "p_correlation_id" "text", "p_details" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  perform private.record_retention_claim_event(
    p_claim.organization_id, p_claim.project_id, p_claim.id,
    'draft_save_rejected', p_claim.status, p_claim.status, auth.uid(),
    p_error_code, p_correlation_id, coalesce(p_details, '{}'::jsonb)
  );
  return jsonb_build_object(
    'succeeded', false,
    'errorCode', p_error_code,
    'changed', false,
    'requiresReload', p_error_code in (
      'concurrent_update', 'origin_set_changed', 'position_changed',
      'eligibility_changed', 'stale_draft', 'claim_not_draft'
    ),
    'currentDraftRevision', p_claim.draft_revision,
    'details', coalesce(p_details, '{}'::jsonb)
  );
end;
$$;


ALTER FUNCTION "private"."reject_retention_document_save"("p_claim" "public"."retention_claims", "p_error_code" "text", "p_correlation_id" "text", "p_details" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."reject_supplier_invoice_commercially_phase_ab_legacy"("p_organization_id" "uuid", "p_supplier_invoice_id" "uuid", "p_reason" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_invoice public.supplier_invoices%rowtype;
  v_rejection_id uuid;
  v_reason text := trim(coalesce(p_reason, ''));
begin
  if auth.uid() is null
    or not public.has_org_permission(p_organization_id, 'supplier_invoices.review') then
    raise exception 'You do not have permission to commercially reject supplier invoices.';
  end if;
  if char_length(v_reason) = 0 then
    raise exception 'Add a commercial rejection reason.';
  end if;

  select * into v_invoice
  from public.supplier_invoices
  where id = p_supplier_invoice_id
    and organization_id = p_organization_id
  for update;

  if not found then
    raise exception 'Supplier invoice not found.';
  end if;

  perform public.invalidate_supplier_invoice_commercial_approval(
    v_invoice.id,
    'Commercial approval replaced by rejection.',
    'commercial_rejection',
    auth.uid()
  );

  insert into public.supplier_invoice_commercial_approvals (
    organization_id,
    supplier_invoice_id,
    status,
    finance_version_hash,
    supplier_id,
    normalized_invoice_number,
    invoice_total,
    invoice_tax_total,
    currency,
    approval_note,
    reviewed_by
  )
  values (
    p_organization_id,
    v_invoice.id,
    'rejected',
    coalesce(public.supplier_invoice_finance_version_hash(v_invoice.id), 'unavailable'),
    v_invoice.supplier_id,
    coalesce(nullif(public.normalize_supplier_invoice_number(v_invoice.invoice_number), ''), 'MISSING'),
    v_invoice.total,
    v_invoice.tax_total,
    v_invoice.currency,
    v_reason,
    auth.uid()
  )
  returning id into v_rejection_id;

  insert into public.supplier_invoice_activity_events (
    organization_id,
    supplier_invoice_id,
    event_type,
    message,
    metadata,
    created_by
  )
  values (
    p_organization_id,
    v_invoice.id,
    'disputed',
    'Supplier invoice commercially rejected.',
    jsonb_build_object('commercial_rejection_id', v_rejection_id, 'reason', v_reason),
    auth.uid()
  );

  return v_rejection_id;
end;
$$;


ALTER FUNCTION "private"."reject_supplier_invoice_commercially_phase_ab_legacy"("p_organization_id" "uuid", "p_supplier_invoice_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."retention_claim_chronological_sequence"("p_project_id" "uuid", "p_claim_id" "uuid") RETURNS integer
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select sequence_number::integer from (
    select p.id,row_number() over(order by p.claim_date nulls last,p.created_at,p.id)
      as sequence_number
    from public.project_claims p where p.project_id=p_project_id
  ) ordered where id=p_claim_id;
$$;


ALTER FUNCTION "private"."retention_claim_chronological_sequence"("p_project_id" "uuid", "p_claim_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."retention_claim_current_origin_details"("p_retention_claim_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with target_claim as (
    select claim.id
    from public.retention_claims claim
    where claim.id = p_retention_claim_id
  ),
  committed as (
    select
      allocation.originating_payment_claim_id,
      round(coalesce(sum(allocation.allocation_amount) filter (
        where submitted_claim.id <> p_retention_claim_id
      ), 0), 2) as submitted_allocation_from_other_claims,
      round(coalesce(sum(allocation.allocation_amount), 0), 2)
        as committed_retention_total
    from public.retention_claim_allocations allocation
    join public.retention_claims submitted_claim
      on submitted_claim.id = allocation.retention_claim_id
    where submitted_claim.status = 'submitted'
    group by allocation.originating_payment_claim_id
  )
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id', allocation.id,
        'organizationId', allocation.organization_id,
        'projectId', allocation.project_id,
        'retentionClaimId', allocation.retention_claim_id,
        'originatingPaymentClaimId', allocation.originating_payment_claim_id,
        'allocationSequence', allocation.allocation_sequence,
        'allocationAmount', allocation.allocation_amount,
        'draftOriginStateHash', allocation.draft_origin_state_hash,
        'draftOriginUpdatedAt', allocation.draft_origin_updated_at,
        'draftOriginRetentionOwned', allocation.draft_origin_retention_owned,
        'currentOriginStateHash',
          private.retention_claim_origin_state_hash(allocation.originating_payment_claim_id),
        'currentOriginStatus', origin.status,
        'currentOriginClaimNumber', origin.claim_number,
        'currentOriginClaimDate', origin.claim_date,
        'currentRetentionOwned', greatest(origin.retention_withheld_amount, 0),
        'currentSubmittedAllocationTotalFromOtherClaims',
          coalesce(committed.submitted_allocation_from_other_claims, 0),
        'currentCommittedRetentionTotal',
          coalesce(committed.committed_retention_total, 0),
        'currentAvailableBeforeSchedules',
          greatest(
            greatest(origin.retention_withheld_amount, 0)
            - coalesce(committed.committed_retention_total, 0),
            0
          ),
        'originStateStale',
          allocation.draft_origin_state_hash
          <> private.retention_claim_origin_state_hash(
            allocation.originating_payment_claim_id
          ),
        'originClaimNumberSnapshot', allocation.origin_claim_number_snapshot,
        'originClaimDateSnapshot', allocation.origin_claim_date_snapshot,
        'originClaimStatusSnapshot', allocation.origin_claim_status_snapshot,
        'originClaimCreatedAtSnapshot', allocation.origin_claim_created_at_snapshot,
        'originClaimUpdatedAtSnapshot', allocation.origin_claim_updated_at_snapshot,
        'retentionMethodSnapshot', allocation.retention_method_snapshot,
        'retentionRateSnapshot', allocation.retention_rate_snapshot,
        'retentionScaleBandsSnapshot', allocation.retention_scale_bands_snapshot,
        'retentionWithheldSnapshot', allocation.retention_withheld_snapshot,
        'retentionReleasedSnapshot', allocation.retention_released_snapshot,
        'retentionHeldToDateSnapshot', allocation.retention_held_to_date_snapshot,
        'retentionReleasedToDateSnapshot',
          allocation.retention_released_to_date_snapshot,
        'retentionBalanceSnapshot', allocation.retention_balance_snapshot,
        'existingSubmittedAllocationBefore',
          allocation.existing_submitted_allocation_before,
        'remainingAfterAllocation', allocation.remaining_after_allocation,
        'grossClaimAmountSnapshot', allocation.gross_claim_amount_snapshot,
        'netClaimExclGstSnapshot', allocation.net_claim_excl_gst_snapshot,
        'gstAmountSnapshot', allocation.gst_amount_snapshot,
        'totalPayableSnapshot', allocation.total_payable_snapshot,
        'projectStateHashSnapshot', allocation.project_state_hash_snapshot,
        'originStateHashSnapshot', allocation.origin_state_hash_snapshot,
        'submittedBy', allocation.submitted_by,
        'submittedAt', allocation.submitted_at,
        'createdBy', allocation.created_by,
        'createdAt', allocation.created_at,
        'updatedAt', allocation.updated_at
      )
      order by allocation.allocation_sequence, allocation.id
    ),
    '[]'::jsonb
  )
  from target_claim
  join public.retention_claim_allocations allocation
    on allocation.retention_claim_id = target_claim.id
  join public.project_claims origin
    on origin.id = allocation.originating_payment_claim_id
  left join committed
    on committed.originating_payment_claim_id = allocation.originating_payment_claim_id;
$$;


ALTER FUNCTION "private"."retention_claim_current_origin_details"("p_retention_claim_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."retention_claim_document_source"("p_retention_claim_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select jsonb_build_object(
    'schemaVersion', 1,
    'claim', jsonb_build_object(
      'id', claim.id,
      'organizationId', claim.organization_id,
      'projectId', claim.project_id,
      'claimNumber', claim.claim_number,
      'title', claim.title,
      'reference', claim.reference,
      'issueDate', claim.issue_date,
      'dueDate', claim.due_date,
      'status', claim.status,
      'subtotalExclTax', claim.subtotal_excl_tax,
      'submissionStateHash', claim.submission_state_hash,
      'submissionEligibilityStateHash',
        claim.submission_eligibility_state_hash,
      'submittedBy', claim.submitted_by,
      'submittedAt', claim.submitted_at
    ),
    'allocations', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'id', allocation.id,
          'allocationSequence', allocation.allocation_sequence,
          'originatingPaymentClaimId',
            allocation.originating_payment_claim_id,
          'allocationAmount', allocation.allocation_amount,
          'originClaimNumberSnapshot',
            allocation.origin_claim_number_snapshot,
          'originClaimDateSnapshot', allocation.origin_claim_date_snapshot,
          'originClaimStatusSnapshot',
            allocation.origin_claim_status_snapshot,
          'originRetentionOwnedSnapshot',
            allocation.draft_origin_retention_owned,
          'retentionMethodSnapshot',
            allocation.retention_method_snapshot,
          'retentionRateSnapshot', allocation.retention_rate_snapshot,
          'retentionWithheldSnapshot',
            allocation.retention_withheld_snapshot,
          'retentionReleasedSnapshot',
            allocation.retention_released_snapshot,
          'retentionBalanceSnapshot',
            allocation.retention_balance_snapshot,
          'existingSubmittedAllocationBefore',
            allocation.existing_submitted_allocation_before,
          'remainingAfterAllocation',
            allocation.remaining_after_allocation,
          'projectStateHashSnapshot',
            allocation.project_state_hash_snapshot,
          'originStateHashSnapshot',
            allocation.origin_state_hash_snapshot,
          'eligibilityStateHashSnapshot',
            allocation.eligibility_state_hash_snapshot,
          'eligibilityScheduleIdsSnapshot',
            to_jsonb(allocation.eligibility_schedule_ids_snapshot),
          'submittedAt', allocation.submitted_at
        )
        order by allocation.allocation_sequence, allocation.id
      )
      from public.retention_claim_allocations allocation
      where allocation.retention_claim_id = claim.id
    ), '[]'::jsonb)
  )
  from public.retention_claims claim
  where claim.id = p_retention_claim_id
    and claim.status = 'submitted';
$$;


ALTER FUNCTION "private"."retention_claim_document_source"("p_retention_claim_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."retention_claim_draft_origin_set_hash"("p_retention_claim_id" "uuid") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
  select encode(extensions.digest(convert_to(coalesce((
    select jsonb_agg(jsonb_build_object(
      'candidateId', source.candidate_id,
      'originatingPaymentClaimId', source.origin_id,
      'sequence', source.sequence,
      'originStateHash', source.origin_state_hash
    ) order by source.sequence, source.origin_id)
    from (
      select
        candidate.id candidate_id,
        candidate.originating_payment_claim_id origin_id,
        candidate.origin_sequence sequence,
        candidate.latest_origin_state_hash origin_state_hash
      from public.retention_rolling_draft_origins candidate
      join public.retention_claims claim on claim.id = candidate.retention_claim_id
      where candidate.retention_claim_id = p_retention_claim_id
        and claim.draft_kind = 'automatic_rolling'
      union all
      select
        null::uuid,
        allocation.originating_payment_claim_id,
        allocation.allocation_sequence,
        allocation.draft_origin_state_hash
      from public.retention_claim_allocations allocation
      join public.retention_claims claim on claim.id = allocation.retention_claim_id
      where allocation.retention_claim_id = p_retention_claim_id
        and claim.draft_kind = 'manual'
    ) source
  ), '[]'::jsonb)::text, 'UTF8'), 'sha256'), 'hex');
$$;


