CREATE OR REPLACE FUNCTION "private"."retention_eligibility_state"("p_project_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'private', 'extensions'
    AS $$
  with project_context as (
    select
      project.id,
      project.organization_id,
      public.get_project_retention_position_summary(project.id) as position
    from public.organization_projects project
    where project.id = p_project_id
  ),
  submitted_claimed as (
    select
      allocation.originating_payment_claim_id,
      round(coalesce(sum(allocation.allocation_amount), 0), 2) as amount
    from public.retention_claim_allocations allocation
    join public.retention_claims retention_claim
      on retention_claim.id = allocation.retention_claim_id
    where retention_claim.project_id = p_project_id
      and retention_claim.status = 'submitted'
    group by allocation.originating_payment_claim_id
  ),
  legacy_claimed as (
    select
      legacy.originating_payment_claim_id,
      round(coalesce(legacy.amount, 0), 2) as amount
    from private.current_legacy_committed_by_origin(p_project_id) legacy
  ),
  origins as (
    select
      payment_claim.id,
      payment_claim.claim_number,
      payment_claim.status,
      payment_claim.claim_date,
      greatest(
        round(coalesce(payment_claim.retention_withheld_amount, 0), 2),
        0
      )::numeric(14,2) as retention_held,
      coalesce(submitted.amount, 0)::numeric(14,2) as submitted_claimed,
      coalesce(legacy.amount, 0)::numeric(14,2) as legacy_claimed
    from public.project_claims payment_claim
    left join submitted_claimed submitted
      on submitted.originating_payment_claim_id = payment_claim.id
    left join legacy_claimed legacy
      on legacy.originating_payment_claim_id = payment_claim.id
    where payment_claim.project_id = p_project_id
      and payment_claim.status <> 'Cancelled'
  ),
  payload as (
    select
      context.organization_id,
      context.id as project_id,
      context.position,
      coalesce(jsonb_agg(
        jsonb_build_object(
          'originatingPaymentClaimId', origin.id,
          'claimNumber', origin.claim_number,
          'claimStatus', origin.status,
          'claimDate', origin.claim_date,
          'currentRetentionOwned', origin.retention_held,
          'retentionHeld', origin.retention_held,
          'submittedRetentionClaimCommitted', origin.submitted_claimed,
          'legacyCommittedRetention', origin.legacy_claimed,
          'committedRetention',
            round(origin.submitted_claimed + origin.legacy_claimed, 2),
          'previouslyClaimed',
            round(origin.submitted_claimed + origin.legacy_claimed, 2),
          'currentEligibleRetention',
            greatest(round(
              origin.retention_held
              - origin.submitted_claimed
              - origin.legacy_claimed,
              2
            ), 0),
          'availableRetention',
            greatest(round(
              origin.retention_held
              - origin.submitted_claimed
              - origin.legacy_claimed,
              2
            ), 0),
          'remainingRetention',
            greatest(round(
              origin.retention_held
              - origin.submitted_claimed
              - origin.legacy_claimed,
              2
            ), 0),
          'eligibilitySource', 'accumulated_retention',
          'scheduleIds', '[]'::jsonb,
          'schedules', '[]'::jsonb
        )
        order by origin.claim_date nulls last, origin.id
      ) filter (where origin.id is not null), '[]'::jsonb) as origins
    from project_context context
    left join origins origin on true
    group by context.organization_id, context.id, context.position
  )
  select jsonb_build_object(
    'organizationId', organization_id,
    'projectId', project_id,
    'positionStateHash', position ->> 'stateHash',
    'eligibilityModel', 'accumulated_retention_v1',
    'eligibilityStateHash', encode(extensions.digest(convert_to(
      jsonb_build_object(
        'organizationId', organization_id,
        'projectId', project_id,
        'positionStateHash', position ->> 'stateHash',
        'eligibilityModel', 'accumulated_retention_v1',
        'origins', origins
      )::text,
      'UTF8'
    ), 'sha256'), 'hex'),
    'origins', origins,
    'effectiveLegacyReconciliationCaseId',
      private.current_effective_retention_legacy_case(project_id)
  )
  from payload;
$$;


ALTER FUNCTION "private"."retention_eligibility_state"("p_project_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."retention_eligibility_state_phase4_pre_legacy_reconciliation"("p_project_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
  with project_context as (
    select p.id,p.organization_id,
      public.get_project_retention_position_summary(p.id) as position
    from public.organization_projects p where p.id=p_project_id
  ),
  committed as (
    select a.originating_payment_claim_id,
      round(coalesce(sum(a.allocation_amount),0),2) as amount
    from public.retention_claim_allocations a
    join public.retention_claims c on c.id=a.retention_claim_id
    where c.project_id=p_project_id and c.status='submitted'
    group by a.originating_payment_claim_id
  ),
  entitlements as (
    select o.originating_payment_claim_id,
      round(coalesce(sum(o.activated_entitlement_amount) filter(
        where s.eligibility_date <= ((now() at time zone org.timezone)::date)
      ),0),2) as raw_eligible,
      jsonb_agg(jsonb_build_object(
        'scheduleId',s.id,'revision',s.revision,'status',s.status,
        'activatedAt',s.activated_at,'triggerType',s.trigger_type,
        'eligibilityDate',s.eligibility_date,
        'currentlyEligible',
          s.eligibility_date <= ((now() at time zone org.timezone)::date),
        'entitlementMethod',s.entitlement_method,
        'percentageBps',
          case when s.entitlement_method='percentage'
            then (o.activation_evidence->>'originPercentageBps')::integer
            else null end,
        'entitlementAmount',o.activated_entitlement_amount,
        'scheduleCap',s.cap_amount,'originCap',o.cap_amount
      ) order by s.id) as schedules,
      coalesce(array_agg(s.id order by s.id) filter(
        where s.eligibility_date <= ((now() at time zone org.timezone)::date)
      ),'{}'::uuid[]) as schedule_ids
    from public.project_retention_schedule_origins o
    join public.project_retention_release_schedules s on s.id=o.schedule_id
    join public.organizations org on org.id=s.organization_id
    where s.project_id=p_project_id
      and s.status in ('activated','completed')
    group by o.originating_payment_claim_id
  ),
  origins as (
    select p.id,p.claim_number,p.status,p.claim_date,
      greatest(p.retention_withheld_amount,0)::numeric(14,2) as owned,
      least(
        greatest(p.retention_withheld_amount,0),
        coalesce(e.raw_eligible,0)
      )::numeric(14,2) as eligible,
      coalesce(c.amount,0)::numeric(14,2) as committed,
      greatest(
        least(greatest(p.retention_withheld_amount,0),coalesce(e.raw_eligible,0))
        - coalesce(c.amount,0),0
      )::numeric(14,2) as available,
      coalesce(e.schedules,'[]'::jsonb) as schedules,
      coalesce(e.schedule_ids,'{}'::uuid[]) as schedule_ids
    from public.project_claims p
    left join committed c on c.originating_payment_claim_id=p.id
    left join entitlements e on e.originating_payment_claim_id=p.id
    where p.project_id=p_project_id and p.status <> 'Cancelled'
  ),
  payload as (
    select pc.organization_id,pc.id as project_id,pc.position,
      coalesce(jsonb_agg(jsonb_build_object(
        'originatingPaymentClaimId',o.id,'claimNumber',o.claim_number,
        'claimStatus',o.status,'claimDate',o.claim_date,
        'currentRetentionOwned',o.owned,'rawScheduleEligibility',
        coalesce((select sum((x->>'entitlementAmount')::numeric)
          from jsonb_array_elements(o.schedules) x
          where coalesce((x->>'currentlyEligible')::boolean,false)),0),
        'cumulativeConfiguredPercentageBps',
          coalesce((select sum((x->>'percentageBps')::integer)
            from jsonb_array_elements(o.schedules) x
            where x->>'entitlementMethod'='percentage'),0),
        'overlapWarning',
          coalesce((select sum((x->>'percentageBps')::integer)
            from jsonb_array_elements(o.schedules) x
            where x->>'entitlementMethod'='percentage'),0)>10000,
        'currentEligibleRetention',o.eligible,
        'committedRetention',o.committed,'availableRetention',o.available,
        'scheduleIds',to_jsonb(o.schedule_ids),'schedules',o.schedules
      ) order by o.id),'[]'::jsonb) as origins
    from project_context pc left join origins o on true
    group by pc.organization_id,pc.id,pc.position
  )
  select jsonb_build_object(
    'organizationId',organization_id,'projectId',project_id,
    'positionStateHash',position->>'stateHash',
    'eligibilityStateHash',encode(extensions.digest(
      convert_to(jsonb_build_object(
        'organizationId',organization_id,'projectId',project_id,
        'positionStateHash',position->>'stateHash','origins',origins
      )::text,'UTF8'),'sha256'),'hex'),
    'origins',origins
  ) from payload;
$$;


ALTER FUNCTION "private"."retention_eligibility_state_phase4_pre_legacy_reconciliation"("p_project_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."retention_legacy_case_json"("p_case_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select to_jsonb(c)||jsonb_build_object(
    'sources',coalesce((
      select jsonb_agg(to_jsonb(s)||jsonb_build_object(
        'allocatedAmount',coalesce((
          select round(sum(a.allocation_amount),2)
          from public.retention_legacy_release_allocations a
          where a.legacy_release_source_id=s.id
        ),0),
        'allocations',coalesce((
          select jsonb_agg(to_jsonb(a)||jsonb_build_object(
            'currentOriginClaimNumber',p.claim_number,
            'currentOriginStatus',p.status,
            'currentRetentionOwned',greatest(p.retention_withheld_amount,0)
          ) order by a.allocation_sequence,a.id)
          from public.retention_legacy_release_allocations a
          join public.project_claims p on p.id=a.originating_payment_claim_id
          where a.legacy_release_source_id=s.id
        ),'[]'::jsonb)
      ) order by s.source_sequence,s.id)
      from public.retention_legacy_release_sources s
      where s.reconciliation_case_id=c.id
    ),'[]'::jsonb)
  )
  from public.retention_legacy_reconciliation_cases c where c.id=p_case_id;
$$;


ALTER FUNCTION "private"."retention_legacy_case_json"("p_case_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."retention_legacy_source_state"("p_project_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
