CREATE OR REPLACE FUNCTION "private"."retention_phase2c_actor_can_push"("p_organization_id" "uuid", "p_actor_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select coalesce(
    (
      select o.is_allowed
      from public.organization_members m
      join public.member_permission_overrides o
        on o.organization_member_id = m.id
       and o.permission_key = 'retention.claims.xero.manage'
      where m.organization_id = p_organization_id
        and m.user_id = p_actor_id
      limit 1
    ),
    (
      select rp.is_allowed
      from public.organization_members m
      join public.role_permissions rp
        on rp.role = m.role
       and rp.permission_key = 'retention.claims.xero.manage'
      where m.organization_id = p_organization_id
        and m.user_id = p_actor_id
      limit 1
    ),
    false
  );
$$;


