    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  select
    coalesce(
      current_setting('request.jwt.claim.retention_phase8_internal', true),
      ''
    ) = 'true'
    or coalesce(
      coalesce(
        nullif(current_setting('request.jwt.claims', true), ''),
        '{}'
      )::jsonb ->> 'retention_phase8_internal',
      'false'
    ) = 'true';
$$;


