CREATE OR REPLACE FUNCTION "private"."retention_variance_read_json"("p_variance_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select to_jsonb(v)||jsonb_build_object(
    'origin',jsonb_build_object(
      'claimNumber',p.claim_number,'claimStatus',p.status,'claimDate',p.claim_date,
      'retentionWithheldAmount',p.retention_withheld_amount,'updatedAt',p.updated_at
    ),
    'allocations',coalesce((
      select jsonb_agg(jsonb_build_object(
        'retentionClaimId',c.id,'retentionClaimNumber',c.claim_number,
        'retentionClaimStatus',c.status,'retentionClaimSubmittedAt',c.submitted_at,
        'allocationId',a.id,'allocationAmount',a.allocation_amount,
        'originClaimNumberSnapshot',a.origin_claim_number_snapshot,
        'retentionWithheldSnapshot',a.retention_withheld_snapshot,
        'originStateHashSnapshot',a.origin_state_hash_snapshot,
        'eligibilityStateHashSnapshot',a.eligibility_state_hash_snapshot,
        'scheduleIds',coalesce(to_jsonb(a.eligibility_schedule_ids_snapshot),'[]'::jsonb)
      ) order by c.submitted_at,c.id,a.id)
      from public.retention_claim_allocations a
      join public.retention_claims c on c.id=a.retention_claim_id
      where c.status='submitted'
        and a.originating_payment_claim_id=v.originating_payment_claim_id
    ),'[]'::jsonb),
    'schedules',coalesce((
      select jsonb_agg(jsonb_build_object(
        'scheduleId',s.id,'name',s.name,'status',s.status,
        'eligibilityDate',s.eligibility_date,
        'activatedEntitlementAmount',o.activated_entitlement_amount,
        'reliedUpon',s.id=any(v.relied_schedule_ids)
      ) order by s.schedule_sequence,s.id)
      from public.project_retention_schedule_origins o
      join public.project_retention_release_schedules s on s.id=o.schedule_id
      where o.originating_payment_claim_id=v.originating_payment_claim_id
    ),'[]'::jsonb)
  )
  from public.retention_variances v
  join public.project_claims p on p.id=v.originating_payment_claim_id
  where v.id=p_variance_id;
$$;


ALTER FUNCTION "private"."retention_variance_read_json"("p_variance_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."retention_variance_snapshot"("p_project_id" "uuid", "p_originating_payment_claim_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'private', 'extensions'
    AS $$
declare
  origin public.project_claims%rowtype;
  position jsonb;
  held numeric(14,2);
  native_committed numeric(14,2);
  legacy_committed numeric(14,2);
  total_committed numeric(14,2);
  snapshot_held numeric(14,2);
  claim_ids uuid[];
  allocation_ids uuid[];
  native_payload jsonb;
  legacy_payload jsonb;
  committed_hash text;
  conditions text[] := '{}'::text[];
  primary_type text;
  variance_state text;
  severity text;
  blocking boolean := false;
begin
  select *
  into origin
  from public.project_claims
  where id = p_originating_payment_claim_id
    and project_id = p_project_id;
  if not found then
    return jsonb_build_object(
      'succeeded', false,
      'errorCode', 'origin_not_found'
    );
  end if;

  position := public.get_project_retention_position_summary(p_project_id);
  held := greatest(round(coalesce(origin.retention_withheld_amount, 0), 2), 0);

  select
    round(coalesce(sum(allocation.allocation_amount), 0), 2),
    coalesce(array_agg(distinct claim.id order by claim.id), '{}'::uuid[]),
    coalesce(array_agg(allocation.id order by allocation.id), '{}'::uuid[]),
    round(coalesce(max(allocation.retention_withheld_snapshot), held), 2),
    coalesce(jsonb_agg(jsonb_build_object(
      'retentionClaimId', claim.id,
      'retentionClaimStatus', claim.status,
      'retentionClaimSubmittedAt', claim.submitted_at,
      'allocationId', allocation.id,
      'originatingPaymentClaimId', allocation.originating_payment_claim_id,
      'allocationAmount', allocation.allocation_amount,
      'allocationSubmittedAt', allocation.submitted_at,
      'originStateHashSnapshot', allocation.origin_state_hash_snapshot,
      'eligibilityStateHashSnapshot', allocation.eligibility_state_hash_snapshot
    ) order by claim.id, allocation.id), '[]'::jsonb)
  into
    native_committed,
    claim_ids,
    allocation_ids,
    snapshot_held,
    native_payload
  from public.retention_claim_allocations allocation
  join public.retention_claims claim
    on claim.id = allocation.retention_claim_id
  where claim.status = 'submitted'
    and allocation.originating_payment_claim_id = origin.id;

  select
    coalesce(committed.amount, 0),
    coalesce((
      select jsonb_agg(jsonb_build_object(
        'legacyAllocationId', allocation.id,
        'reconciliationCaseId', allocation.reconciliation_case_id,
        'legacyReleaseSourceId', allocation.legacy_release_source_id,
        'originatingPaymentClaimId', allocation.originating_payment_claim_id,
        'allocationAmount', allocation.allocation_amount,
        'approvedAt', allocation.approved_at
      ) order by allocation.id)
      from public.retention_legacy_release_allocations allocation
      where allocation.reconciliation_case_id =
        private.current_effective_retention_legacy_case(p_project_id)
        and allocation.originating_payment_claim_id = origin.id
    ), '[]'::jsonb)
  into legacy_committed, legacy_payload
  from (select 1) singleton
  left join private.current_legacy_committed_by_origin(p_project_id) committed
    on committed.originating_payment_claim_id = origin.id;

  native_committed := coalesce(native_committed, 0);
  legacy_committed := coalesce(legacy_committed, 0);
  total_committed := round(native_committed + legacy_committed, 2);
  committed_hash := encode(extensions.digest(convert_to(jsonb_build_object(
    'originatingPaymentClaimId', origin.id,
    'submittedAllocations', native_payload,
    'legacyAllocations', legacy_payload
  )::text, 'UTF8'), 'sha256'), 'hex');

  if total_committed > 0 and origin.status = 'Cancelled' then
    conditions := array_append(conditions, 'origin_payment_claim_cancelled');
  end if;
  if total_committed > held then
    conditions := array_append(conditions, 'ownership_reduced');
  end if;
  if total_committed > 0 and held <> snapshot_held
    and not ('ownership_reduced' = any(conditions))
  then
    conditions := array_append(conditions, 'ownership_reduced');
  end if;

  if 'origin_payment_claim_cancelled' = any(conditions) then
    primary_type := 'origin_payment_claim_cancelled';
    variance_state := case
      when total_committed > held then 'over_allocated'
      else 'reconciliation_required'
    end;
    severity := case
      when total_committed > held then 'critical'
      else 'high'
    end;
    blocking := true;
  elsif total_committed > held then
    primary_type := 'ownership_reduced';
    variance_state := 'over_allocated';
    severity := 'critical';
    blocking := true;
  elsif 'ownership_reduced' = any(conditions) then
    primary_type := 'ownership_reduced';
    variance_state := 'warning';
    severity := 'medium';
  end if;

  return jsonb_build_object(
    'succeeded', true,
    'errorCode', null,
    'organizationId', origin.organization_id,
    'projectId', origin.project_id,
    'originatingPaymentClaimId', origin.id,
    'originClaimNumber', origin.claim_number,
    'originStatus', origin.status,
    'hasVariance', primary_type is not null,
    'primaryType', primary_type,
    'contributingConditions', to_jsonb(conditions),
    'state', variance_state,
    'severity', severity,
    'isBlocking', blocking,
    'currentOwnership', held,
    'currentEligibility', held,
    'submittedRetentionClaimCommitted', native_committed,
    'legacyCommittedRetention', legacy_committed,
    'committedRetention', total_committed,
    'ownershipVariance', round(held - total_committed, 2),
    'eligibilityVariance', round(held - total_committed, 2),
    'diagnosticRemaining', greatest(round(held - total_committed, 2), 0),
    'allocatableAvailability', greatest(round(held - total_committed, 2), 0),
    'phase2StateHash', position ->> 'stateHash',
    'phase4EligibilityHash',
      private.retention_eligibility_state(p_project_id) ->> 'eligibilityStateHash',
    'committedAllocationHash', committed_hash,
    'affectedRetentionClaimIds', to_jsonb(claim_ids),
    'affectedAllocationIds', to_jsonb(allocation_ids),
    'reliedScheduleIds', '[]'::jsonb,
    'currentScheduleIds', '[]'::jsonb,
    'committedAllocations', native_payload,
    'legacyAllocations', legacy_payload,
    'currentSchedules', '[]'::jsonb,
    'eligibilityModel', 'accumulated_retention_v1',
    'effectiveLegacyReconciliationCaseId',
      private.current_effective_retention_legacy_case(p_project_id)
  );
end;
$$;


ALTER FUNCTION "private"."retention_variance_snapshot"("p_project_id" "uuid", "p_originating_payment_claim_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."retention_variance_snapshot_phase5_pre_legacy_reconciliation"("p_project_id" "uuid", "p_originating_payment_claim_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
declare
  v_origin public.project_claims%rowtype; v_position jsonb; v_eligibility jsonb;
  v_e jsonb; v_committed numeric(14,2); v_claims uuid[]; v_allocations uuid[];
  v_relied uuid[]; v_current_schedules uuid[]; v_committed_payload jsonb;
  v_committed_hash text; v_snapshot_owned numeric(14,2); v_schedule_cancelled boolean;
  v_type text; v_state text; v_severity text; v_blocking boolean:=false;
  v_conditions text[]:='{}'::text[]; v_owned numeric(14,2); v_eligible numeric(14,2);
begin
  select * into v_origin from public.project_claims
  where id=p_originating_payment_claim_id and project_id=p_project_id;
  if not found then
    return jsonb_build_object('succeeded',false,'errorCode','origin_not_found');
  end if;
  v_position:=public.get_project_retention_position_summary(p_project_id);
  v_eligibility:=private.retention_eligibility_state(p_project_id);
  select x into v_e from jsonb_array_elements(coalesce(v_eligibility->'origins','[]'::jsonb)) x
  where (x->>'originatingPaymentClaimId')::uuid=v_origin.id;

  select
    round(coalesce(sum(a.allocation_amount),0),2),
    coalesce(array_agg(distinct c.id order by c.id),'{}'::uuid[]),
    coalesce(array_agg(a.id order by a.id),'{}'::uuid[]),
    coalesce(array(
      select distinct unnest(coalesce(a2.eligibility_schedule_ids_snapshot,'{}'::uuid[]))
      from public.retention_claim_allocations a2
      join public.retention_claims c2 on c2.id=a2.retention_claim_id
      where c2.status='submitted'
        and a2.originating_payment_claim_id=v_origin.id order by 1
    ),'{}'::uuid[]),
    round(coalesce(max(a.retention_withheld_snapshot),v_origin.retention_withheld_amount,0),2),
    coalesce(jsonb_agg(jsonb_build_object(
      'retentionClaimId',c.id,'retentionClaimStatus',c.status,
      'retentionClaimSubmittedAt',c.submitted_at,'allocationId',a.id,
      'originatingPaymentClaimId',a.originating_payment_claim_id,
      'allocationAmount',a.allocation_amount,'allocationSubmittedAt',a.submitted_at,
      'originStateHashSnapshot',a.origin_state_hash_snapshot,
      'eligibilityStateHashSnapshot',a.eligibility_state_hash_snapshot,
      'scheduleIds',coalesce(to_jsonb(a.eligibility_schedule_ids_snapshot),'[]'::jsonb)
    ) order by c.id,a.id),'[]'::jsonb)
  into v_committed,v_claims,v_allocations,v_relied,v_snapshot_owned,v_committed_payload
  from public.retention_claim_allocations a
  join public.retention_claims c on c.id=a.retention_claim_id
  where c.status='submitted' and a.originating_payment_claim_id=v_origin.id;

  v_owned:=greatest(round(coalesce(v_origin.retention_withheld_amount,0),2),0);
  v_eligible:=least(v_owned,greatest(round(coalesce((v_e->>'currentEligibleRetention')::numeric,0),2),0));
  v_current_schedules:=coalesce(array(
    select jsonb_array_elements_text(coalesce(v_e->'scheduleIds','[]'::jsonb))::uuid order by 1
  ),'{}'::uuid[]);
  v_committed_hash:=encode(extensions.digest(convert_to(
    jsonb_build_object('originatingPaymentClaimId',v_origin.id,'allocations',v_committed_payload)::text,
    'UTF8'),'sha256'),'hex');
  select exists(
    select 1 from public.project_retention_release_schedules s
    where s.id=any(v_relied) and s.status='cancelled'
  ) into v_schedule_cancelled;

  if v_committed>0 and v_origin.status='Cancelled' then
    v_conditions:=array_append(v_conditions,'origin_payment_claim_cancelled');
  end if;
  if v_committed>v_owned then v_conditions:=array_append(v_conditions,'ownership_reduced'); end if;
  if v_committed>v_eligible then v_conditions:=array_append(v_conditions,'eligibility_reduced'); end if;
  if v_schedule_cancelled then v_conditions:=array_append(v_conditions,'schedule_cancelled'); end if;
  if v_committed>0 and v_relied is distinct from v_current_schedules then
    v_conditions:=array_append(v_conditions,'schedule_changed');
  end if;
  if v_committed>0 and v_owned<>v_snapshot_owned
    and not ('ownership_reduced'=any(v_conditions)) then
    v_conditions:=array_append(v_conditions,'ownership_reduced');
  end if;

  if 'origin_payment_claim_cancelled'=any(v_conditions) then
    v_type:='origin_payment_claim_cancelled';
    v_state:=case when v_committed>v_owned then 'over_allocated'
      else 'reconciliation_required' end;
    v_severity:=case when v_committed>v_owned then 'critical' else 'high' end;
    v_blocking:=true;
  elsif v_committed>v_owned then
    v_type:='ownership_reduced'; v_state:='over_allocated';
    v_severity:='critical'; v_blocking:=true;
  elsif v_committed>v_eligible then
    v_type:=case when v_schedule_cancelled then 'schedule_cancelled'
      else 'eligibility_reduced' end;
    v_state:='reconciliation_required'; v_severity:='high'; v_blocking:=true;
  elsif 'ownership_reduced'=any(v_conditions) then
    v_type:='ownership_reduced'; v_state:='warning'; v_severity:='medium';
  elsif 'schedule_cancelled'=any(v_conditions) then
    v_type:='schedule_cancelled'; v_state:='warning'; v_severity:='medium';
  elsif 'schedule_changed'=any(v_conditions) then
    v_type:='schedule_changed'; v_state:='warning'; v_severity:='low';
  end if;

  return jsonb_build_object(
    'succeeded',true,'errorCode',null,'organizationId',v_origin.organization_id,
    'projectId',v_origin.project_id,'originatingPaymentClaimId',v_origin.id,
    'originClaimNumber',v_origin.claim_number,'originStatus',v_origin.status,
    'hasVariance',v_type is not null,'primaryType',v_type,
    'contributingConditions',to_jsonb(v_conditions),'state',v_state,
    'severity',v_severity,'isBlocking',v_blocking,
    'currentOwnership',v_owned,'currentEligibility',v_eligible,
    'committedRetention',v_committed,
    'ownershipVariance',round(v_owned-v_committed,2),
    'eligibilityVariance',round(v_eligible-v_committed,2),
    'diagnosticRemaining',round(least(v_owned,v_eligible)-v_committed,2),
    'allocatableAvailability',greatest(round(least(v_owned,v_eligible)-v_committed,2),0),
    'phase2StateHash',v_position->>'stateHash',
    'phase4EligibilityHash',v_eligibility->>'eligibilityStateHash',
    'committedAllocationHash',v_committed_hash,
    'affectedRetentionClaimIds',to_jsonb(v_claims),
    'affectedAllocationIds',to_jsonb(v_allocations),
    'reliedScheduleIds',to_jsonb(v_relied),
    'currentScheduleIds',to_jsonb(v_current_schedules),
    'committedAllocations',v_committed_payload,
    'currentSchedules',coalesce(v_e->'schedules','[]'::jsonb)
  );
end;
$$;


ALTER FUNCTION "private"."retention_variance_snapshot_phase5_pre_legacy_reconciliation"("p_project_id" "uuid", "p_originating_payment_claim_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."save_supplier_invoice_capture_phase_ab_legacy"("p_invoice_id" "uuid", "p_supplier_id" "uuid", "p_invoice_number" "text", "p_supplier_po_reference" "text", "p_invoice_date" "date", "p_due_date" "date", "p_currency" "text", "p_subtotal" numeric, "p_tax_total" numeric, "p_total" numeric, "p_notes" "text", "p_source" "text", "p_lines" "jsonb" DEFAULT '[]'::"jsonb", "p_create" boolean DEFAULT false) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_organization_id uuid;
  v_line jsonb;
  v_line_id uuid;
  v_keep_line_ids uuid[] := '{}';
begin
  select m.organization_id into v_organization_id
  from public.organization_members m
  where m.user_id = auth.uid()
  order by m.created_at
  limit 1;

  if v_organization_id is null
    or not public.has_org_permission(v_organization_id, 'supplier_invoices.capture') then
    raise exception 'You do not have permission to capture Supplier Invoices.';
  end if;
  if p_invoice_id is null then raise exception 'Supplier Invoice ID is required.'; end if;
  if p_supplier_id is null or not exists (
    select 1 from public.organization_suppliers s
    where s.id = p_supplier_id and s.organization_id = v_organization_id
  ) then raise exception 'Select a valid Supplier.'; end if;
  if char_length(trim(coalesce(p_invoice_number, ''))) = 0 then
    raise exception 'Enter an invoice number.';
  end if;
  if p_invoice_date is null then raise exception 'Enter an invoice date.'; end if;
  if p_due_date is not null and p_due_date < p_invoice_date then
    raise exception 'Due date cannot be before the invoice date.';
  end if;
  if upper(trim(coalesce(p_currency, ''))) <> 'NZD' then
    raise exception 'Supplier Invoice currency must be NZD.';
  end if;
  if p_subtotal < 0 or p_tax_total < 0 or p_total < 0
    or abs((p_subtotal + p_tax_total) - p_total) > 0.01 then
    raise exception 'Invoice subtotal, tax and total do not reconcile.';
  end if;
  if p_supplier_po_reference is not null
    and char_length(trim(p_supplier_po_reference)) > 120 then
    raise exception 'Supplier PO reference must be 120 characters or fewer.';
  end if;
  if jsonb_typeof(coalesce(p_lines, '[]'::jsonb)) <> 'array' then
    raise exception 'Supplier Invoice lines must be an array.';
  end if;

  if exists (
    select 1 from public.supplier_invoices duplicate
    where duplicate.organization_id = v_organization_id
      and duplicate.supplier_id = p_supplier_id
      and public.normalize_supplier_invoice_number(duplicate.invoice_number)
        = public.normalize_supplier_invoice_number(p_invoice_number)
      and duplicate.id <> p_invoice_id
  ) then raise exception 'A Supplier Invoice with this invoice number already exists for the Supplier.';
  end if;

  if p_create then
    insert into public.supplier_invoices (
      id, organization_id, supplier_id, invoice_number, supplier_po_reference,
      invoice_date, due_date, currency, subtotal, tax_total, total, notes,
      status, source, created_by
    ) values (
      p_invoice_id, v_organization_id, p_supplier_id, trim(p_invoice_number),
      nullif(trim(coalesce(p_supplier_po_reference, '')), ''), p_invoice_date,
      p_due_date, 'NZD', p_subtotal, p_tax_total, p_total, trim(coalesce(p_notes, '')),
      'Captured', case when p_source = 'upload' then 'upload' else 'manual' end, auth.uid()
    );
  else
    if exists (
      select 1 from public.organization_accounting_documents d
      where d.organization_id = v_organization_id
        and d.local_document_id = p_invoice_id
        and d.export_status in ('queued', 'exporting', 'exported', 'attention_required')
    ) then raise exception 'This Supplier Invoice is locked by its Xero export state.';
    end if;
    update public.supplier_invoices
    set supplier_id = p_supplier_id,
        invoice_number = trim(p_invoice_number),
        supplier_po_reference = nullif(trim(coalesce(p_supplier_po_reference, '')), ''),
        invoice_date = p_invoice_date,
        due_date = p_due_date,
        currency = 'NZD', subtotal = p_subtotal, tax_total = p_tax_total,
        total = p_total, notes = trim(coalesce(p_notes, ''))
    where id = p_invoice_id and organization_id = v_organization_id;
    if not found then raise exception 'Supplier Invoice not found.'; end if;
  end if;

  for v_line in select value from jsonb_array_elements(coalesce(p_lines, '[]'::jsonb)) loop
    v_line_id := coalesce(nullif(v_line ->> 'id', '')::uuid, gen_random_uuid());
    if exists (
      select 1 from public.supplier_invoice_lines l
      where l.id = v_line_id
        and (l.supplier_invoice_id <> p_invoice_id or l.organization_id <> v_organization_id)
    ) then raise exception 'A Supplier Invoice line does not belong to this invoice.'; end if;
    if char_length(trim(coalesce(v_line ->> 'description', ''))) = 0 then
      raise exception 'Every Supplier Invoice line requires a description.';
    end if;
    if nullif(v_line ->> 'costCodeId', '') is not null and not exists (
      select 1 from public.organization_cost_codes c
      where c.id = (v_line ->> 'costCodeId')::uuid and c.organization_id = v_organization_id
    ) then raise exception 'A Supplier Invoice line cost code does not belong to this organization.'; end if;
    if nullif(v_line ->> 'projectId', '') is not null and not exists (
      select 1 from public.organization_projects p
      where p.id = (v_line ->> 'projectId')::uuid and p.organization_id = v_organization_id
    ) then raise exception 'A Supplier Invoice line project does not belong to this organization.'; end if;
    if coalesce((v_line ->> 'quantity')::numeric, 0) < 0
      or coalesce((v_line ->> 'unitPrice')::numeric, 0) < 0
      or coalesce((v_line ->> 'lineTotal')::numeric, 0) < 0
      or coalesce((v_line ->> 'taxAmount')::numeric, 0) < 0 then
      raise exception 'Supplier Invoice line values cannot be negative.';
    end if;

    insert into public.supplier_invoice_lines (
      id, organization_id, supplier_invoice_id, description, quantity, unit_price,
      line_total, tax_amount, cost_code_id, project_id, sort_order
    ) values (
      v_line_id, v_organization_id, p_invoice_id, trim(v_line ->> 'description'),
      coalesce((v_line ->> 'quantity')::numeric, 0),
      coalesce((v_line ->> 'unitPrice')::numeric, 0),
      coalesce((v_line ->> 'lineTotal')::numeric, 0),
      coalesce((v_line ->> 'taxAmount')::numeric, 0),
      nullif(v_line ->> 'costCodeId', '')::uuid,
      nullif(v_line ->> 'projectId', '')::uuid,
      coalesce((v_line ->> 'sortOrder')::integer, cardinality(v_keep_line_ids))
    )
    on conflict (id) do update set
      description = excluded.description, quantity = excluded.quantity,
      unit_price = excluded.unit_price, line_total = excluded.line_total,
      tax_amount = excluded.tax_amount, cost_code_id = excluded.cost_code_id,
      project_id = excluded.project_id, sort_order = excluded.sort_order;
    v_keep_line_ids := array_append(v_keep_line_ids, v_line_id);
  end loop;

  if not p_create then
    delete from public.supplier_invoice_lines l
    where l.organization_id = v_organization_id
      and l.supplier_invoice_id = p_invoice_id
      and not (l.id = any(v_keep_line_ids));
  end if;

  insert into public.supplier_invoice_activity_events (
    organization_id, supplier_invoice_id, event_type, message, metadata, created_by
  ) values (
    v_organization_id, p_invoice_id,
    case when p_create then 'invoice_created' else 'invoice_updated' end,
    case when p_create then 'Supplier Invoice captured by Accounts.' else 'Supplier Invoice capture details updated.' end,
    jsonb_build_object('supplier_po_reference', nullif(trim(coalesce(p_supplier_po_reference, '')), ''),
      'line_count', jsonb_array_length(coalesce(p_lines, '[]'::jsonb))), auth.uid()
  );
  return p_invoice_id;
end;
$$;


ALTER FUNCTION "private"."save_supplier_invoice_capture_phase_ab_legacy"("p_invoice_id" "uuid", "p_supplier_id" "uuid", "p_invoice_number" "text", "p_supplier_po_reference" "text", "p_invoice_date" "date", "p_due_date" "date", "p_currency" "text", "p_subtotal" numeric, "p_tax_total" numeric, "p_total" numeric, "p_notes" "text", "p_source" "text", "p_lines" "jsonb", "p_create" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."submit_supplier_invoice_for_site_review_phase_ab_legacy"("p_supplier_invoice_id" "uuid", "p_expected_finance_hash" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_organization_id uuid;
  v_submission_id uuid;
  v_hash text;
  v_invoice public.supplier_invoices%rowtype;
begin
  select m.organization_id into v_organization_id
  from public.organization_members m where m.user_id = auth.uid()
  order by m.created_at limit 1;
  if v_organization_id is null
    or not public.has_org_permission(v_organization_id, 'supplier_invoices.submit_site_review') then
    raise exception 'You do not have permission to submit Supplier Invoices for site review.';
  end if;
  select * into v_invoice from public.supplier_invoices
  where id = p_supplier_invoice_id and organization_id = v_organization_id for update;
  if not found then raise exception 'Supplier Invoice not found.'; end if;
  if exists (select 1 from public.organization_accounting_documents d
    where d.organization_id = v_organization_id and d.local_document_id = p_supplier_invoice_id
      and d.export_status in ('queued', 'exporting', 'exported', 'attention_required')) then
    raise exception 'This Supplier Invoice is locked by its Xero export state.';
  end if;
  if v_invoice.supplier_id is null or char_length(trim(v_invoice.invoice_number)) = 0
    or v_invoice.invoice_date is null then
    raise exception 'Complete the Supplier, invoice number and invoice date before site review.';
  end if;
  if not exists (select 1 from public.supplier_invoice_lines l where l.supplier_invoice_id = p_supplier_invoice_id) then
    raise exception 'Add at least one Supplier Invoice line before site review.';
  end if;
  if exists (
    select 1 from public.supplier_invoice_lines l
    left join public.supplier_invoice_line_allocations a
      on a.supplier_invoice_line_id = l.id and a.supplier_invoice_id = l.supplier_invoice_id
    where l.supplier_invoice_id = p_supplier_invoice_id
    group by l.id having count(a.id) <> 1
  ) then raise exception 'Allocate every Supplier Invoice line before site review.'; end if;
  if exists (select 1 from public.supplier_invoice_line_allocations a
    where a.supplier_invoice_id = p_supplier_invoice_id
      and (a.purchase_order_id is null or a.purchase_order_line_item_id is null)) then
    raise exception 'Use the explicit no-PO Accounts workflow for invoices without Purchase Orders.';
  end if;
  if not exists (select 1 from public.supplier_invoice_line_allocations a
    where a.supplier_invoice_id = p_supplier_invoice_id and a.purchase_order_id is not null) then
    raise exception 'Match and allocate at least one Purchase Order before site review.';
  end if;
  if exists (
    select 1 from public.supplier_invoice_line_allocations a
    join public.project_purchase_orders po on po.id = a.purchase_order_id
    where a.supplier_invoice_id = p_supplier_invoice_id
      and (po.organization_id <> v_organization_id or po.supplier_id is distinct from v_invoice.supplier_id
        or lower(po.status) = 'cancelled')
  ) then raise exception 'A matched Purchase Order has a Supplier mismatch or is cancelled.'; end if;
  if exists (select 1 from public.supplier_invoice_line_allocations a
    where a.supplier_invoice_id = p_supplier_invoice_id
      and (a.accounting_mapping_id is null
        or (a.tax_resolution_status = 'resolved' and a.accounting_tax_rate_id is null)
        or a.accounting_resolution_status <> 'resolved')) then
    raise exception 'Resolve routing, accounting and tax coding before site review.';
  end if;
  if abs((select coalesce(sum(a.allocated_amount), 0) from public.supplier_invoice_line_allocations a
    where a.supplier_invoice_id = p_supplier_invoice_id) - v_invoice.subtotal) > 0.01
    and abs((select coalesce(sum(a.allocated_amount), 0) from public.supplier_invoice_line_allocations a
    where a.supplier_invoice_id = p_supplier_invoice_id) - v_invoice.total) > 0.01 then
    raise exception 'Allocated amounts do not reconcile to the Supplier Invoice.';
  end if;
  v_hash := public.supplier_invoice_finance_version_hash(p_supplier_invoice_id);
  if v_hash is null or v_hash <> p_expected_finance_hash then
    raise exception 'Supplier Invoice finance data changed. Refresh and submit again.';
  end if;
  select s.id into v_submission_id
  from public.supplier_invoice_site_review_submissions s
  where s.organization_id = v_organization_id
    and s.supplier_invoice_id = p_supplier_invoice_id
    and s.finance_hash = v_hash
    and s.status in ('submitted', 'partially_reviewed', 'approved', 'disputed')
  order by s.submitted_at desc limit 1;
  if v_submission_id is not null then return v_submission_id; end if;

  perform public.invalidate_supplier_invoice_role_workflow(p_supplier_invoice_id, 'Superseded by a new site-review submission.');
  insert into public.supplier_invoice_site_review_submissions (
    organization_id, supplier_invoice_id, finance_hash, submitted_by
  ) values (v_organization_id, p_supplier_invoice_id, v_hash, auth.uid())
  returning id into v_submission_id;

  insert into public.supplier_invoice_site_review_decisions (
    organization_id, submission_id, supplier_invoice_id, purchase_order_id,
    project_id, allocated_amount_snapshot, allocation_ids_snapshot
  )
  select v_organization_id, v_submission_id, p_supplier_invoice_id,
    a.purchase_order_id, po.project_id, sum(a.allocated_amount), array_agg(a.id order by a.id)
  from public.supplier_invoice_line_allocations a
  join public.project_purchase_orders po on po.id = a.purchase_order_id
  where a.supplier_invoice_id = p_supplier_invoice_id
  group by a.purchase_order_id, po.project_id;

  insert into public.supplier_invoice_activity_events (
    organization_id, supplier_invoice_id, event_type, message, metadata, created_by
  ) values (v_organization_id, p_supplier_invoice_id, 'site_review_submitted',
    'Supplier Invoice submitted for site approval.',
    jsonb_build_object('submission_id', v_submission_id, 'finance_hash', v_hash), auth.uid());
  return v_submission_id;
end;
$$;


ALTER FUNCTION "private"."submit_supplier_invoice_for_site_review_phase_ab_legacy"("p_supplier_invoice_id" "uuid", "p_expected_finance_hash" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."validate_retention_legacy_case"("p_case_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare c public.retention_legacy_reconciliation_cases%rowtype; source_state jsonb;
  source_errors jsonb; origin_errors jsonb; allocated numeric; allocation_count integer;
begin
  select * into c from public.retention_legacy_reconciliation_cases where id=p_case_id;
  if not found then return jsonb_build_object('succeeded',false,'errorCode','legacy_case_not_found'); end if;
  source_state:=private.retention_legacy_source_state(c.project_id);
  if c.position_state_hash<>source_state->>'stateHash'
    or c.source_fingerprint<>source_state->>'sourceFingerprint' then
    return jsonb_build_object('succeeded',false,'errorCode','stale_reconciliation_case',
      'casePositionStateHash',c.position_state_hash,
      'currentPositionStateHash',source_state->>'stateHash',
      'caseSourceFingerprint',c.source_fingerprint,
      'currentSourceFingerprint',source_state->>'sourceFingerprint');
  end if;
  select jsonb_agg(jsonb_build_object(
    'sourceId',s.id,'sourcePaymentClaimId',s.source_payment_claim_id,
    'sourceAmount',s.retention_released_amount_snapshot,
    'allocatedAmount',coalesce(x.amount,0),
    'difference',round(s.retention_released_amount_snapshot-coalesce(x.amount,0),2)
  ) order by s.source_sequence,s.id)
  into source_errors
  from public.retention_legacy_release_sources s
  left join (
    select a.legacy_release_source_id,round(sum(a.allocation_amount),2) amount
    from public.retention_legacy_release_allocations a
    where a.reconciliation_case_id=c.id group by a.legacy_release_source_id
  ) x on x.legacy_release_source_id=s.id
  where s.reconciliation_case_id=c.id
    and coalesce(x.amount,0)<>s.retention_released_amount_snapshot;
  if source_errors is not null then
    return jsonb_build_object('succeeded',false,
      'errorCode','legacy_sources_not_fully_allocated','sources',source_errors);
  end if;
  select jsonb_agg(jsonb_build_object(
    'originatingPaymentClaimId',p.id,'claimNumber',p.claim_number,'status',p.status,
    'currentRetentionOwned',greatest(p.retention_withheld_amount,0),
    'migratedAllocation',x.amount
  ) order by p.id)
  into origin_errors
  from (
    select a.originating_payment_claim_id,round(sum(a.allocation_amount),2) amount
    from public.retention_legacy_release_allocations a
    where a.reconciliation_case_id=c.id group by a.originating_payment_claim_id
  ) x
  join public.project_claims p on p.id=x.originating_payment_claim_id
  where p.status='Cancelled' or x.amount>greatest(p.retention_withheld_amount,0);
  if origin_errors is not null then
    return jsonb_build_object('succeeded',false,
      'errorCode','legacy_origin_overallocated','origins',origin_errors);
  end if;
  select round(coalesce(sum(a.allocation_amount),0),2),count(*)
  into allocated,allocation_count
  from public.retention_legacy_release_allocations a
  where a.reconciliation_case_id=c.id;
  if allocated<>c.total_legacy_released then
    return jsonb_build_object('succeeded',false,
      'errorCode','legacy_total_mismatch','expectedTotal',c.total_legacy_released,
      'allocatedTotal',allocated);
  end if;
  return jsonb_build_object('succeeded',true,'errorCode',null,
    'positionStateHash',source_state->>'stateHash',
    'sourceFingerprint',source_state->>'sourceFingerprint',
    'totalLegacyReleased',c.total_legacy_released,
    'totalAllocated',allocated,'allocationCount',allocation_count);
end;
$$;


ALTER FUNCTION "private"."validate_retention_legacy_case"("p_case_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."validate_retention_release_ledger_v2"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'private'
    AS $_$
declare
  v_previous public.organization_retention_release_allocation_ledger_v2%rowtype;
  v_existing_amount bigint;
  v_existing_tax bigint;
begin
  perform pg_advisory_xact_lock(
    hashtextextended(new.originating_payment_claim_id::text, 2814)
  );

  if not exists (
    select 1 from public.organization_projects project
    where project.id = new.project_id
      and project.organization_id = new.organization_id
  ) or not exists (
    select 1 from public.retention_claims claim
    where claim.id = new.retention_claim_id
      and claim.organization_id = new.organization_id
      and claim.project_id = new.project_id
  ) or not exists (
    select 1 from public.project_claims claim
    where claim.id = new.originating_payment_claim_id
      and claim.organization_id = new.organization_id
      and claim.project_id = new.project_id
  ) or not exists (
    select 1 from public.organization_xero_connections connection
    where connection.id = new.xero_connection_id
      and connection.organization_id = new.organization_id
      and connection.tenant_id = new.tenant_id
  ) then
    raise exception 'Retention release allocation scope is inconsistent.'
      using errcode = '23514';
  end if;

  if not exists (
    select 1
    from public.organization_accounting_documents document
    join public.organization_accounting_document_revisions revision
      on revision.id = new.retention_accounting_revision_id
     and revision.accounting_document_id = document.id
     and revision.organization_id = new.organization_id
     and revision.project_id = new.project_id
     and revision.connection_id = new.xero_connection_id
     and revision.tenant_id = new.tenant_id
    join public.organization_accounting_revision_lines line
      on line.id = new.retention_accounting_revision_line_id
     and line.organization_id = new.organization_id
     and line.accounting_revision_id = revision.id
     and line.line_kind = 'retention'
     and line.originating_payment_claim_id =
       new.originating_payment_claim_id
     and line.line_amount_minor = new.released_amount_minor
     and line.tax_minor = new.released_tax_minor
     and line.total_minor = new.released_total_minor
     and line.tax_snapshot->>'taxType' = new.tax_type
    where document.id = new.retention_accounting_document_id
      and document.organization_id = new.organization_id
      and document.retention_claim_id = new.retention_claim_id
      and document.local_document_type = 'retention_claim'
      and document.provider = 'xero'
  ) then
    raise exception 'Retention release accounting evidence is inconsistent.'
      using errcode = '23514';
  end if;

  if new.evidence_kind in ('immutable_revision', 'exact_legacy_adoption') then
    if not exists (
      select 1
      from public.organization_accounting_documents document
      join public.organization_accounting_document_revisions revision
        on revision.id = new.origin_accounting_revision_id
       and revision.accounting_document_id = document.id
       and revision.organization_id = new.organization_id
       and revision.project_id = new.project_id
       and revision.connection_id = new.xero_connection_id
       and revision.tenant_id = new.tenant_id
      join public.organization_accounting_revision_lines line
        on line.id = new.origin_accounting_revision_line_id
       and line.organization_id = new.organization_id
       and line.accounting_revision_id = revision.id
       and line.line_kind = 'retention'
       and line.originating_payment_claim_id =
         new.originating_payment_claim_id
       and line.line_amount_minor = new.origin_retained_amount_minor
       and line.tax_minor = new.origin_retained_tax_minor
       and line.total_minor = new.origin_retained_total_minor
       and line.tax_snapshot->>'taxType' = new.tax_type
       and line.account_snapshot->>'accountCode' =
         new.origin_account_code_snapshot
      where document.id = new.origin_accounting_document_id
        and document.organization_id = new.organization_id
        and document.project_claim_id = new.originating_payment_claim_id
        and document.local_document_type = 'project_claim'
        and document.provider = 'xero'
        and (
          (
            new.evidence_kind = 'immutable_revision'
            and revision.revision_intent <> 'legacy_import'
          )
          or (
            new.evidence_kind = 'exact_legacy_adoption'
            and revision.revision_intent = 'legacy_import'
          )
        )
        and coalesce(revision.tax_snapshot->>'effectiveRate', '')
          ~ '^[0-9]+(?:\.[0-9]+)?$'
        and round(
          (revision.tax_snapshot->>'effectiveRate')::numeric * 100
        )::integer = new.effective_rate_basis_points
    ) then
      raise exception 'Origin Retention accounting evidence is inconsistent.'
        using errcode = '23514';
    end if;
  elsif not exists (
    select 1
    from public.organization_retention_tax_classifications_v2 classification
    where classification.id = new.legacy_tax_classification_id
      and classification.organization_id = new.organization_id
      and classification.project_id = new.project_id
      and classification.originating_payment_claim_id =
        new.originating_payment_claim_id
      and classification.xero_connection_id = new.xero_connection_id
      and classification.tenant_id = new.tenant_id
      and classification.currency_code = new.currency_code
      and classification.tax_type = new.tax_type
      and classification.effective_rate_basis_points =
        new.effective_rate_basis_points
      and classification.evidence_kind = new.evidence_kind
      and classification.tax_rate_snapshot_id is not distinct from
        new.tax_rate_snapshot_id
      and classification.origin_retained_amount_minor =
        new.origin_retained_amount_minor
      and classification.origin_retained_tax_minor =
        new.origin_retained_tax_minor
      and classification.origin_retained_total_minor =
        new.origin_retained_total_minor
  ) then
    raise exception 'Reviewed Retention tax classification is inconsistent.'
      using errcode = '23514';
  end if;

  if new.supersedes_ledger_id is null then
    if new.reservation_sequence <> 1
      or new.reservation_root_id <> new.id then
      raise exception 'Initial Retention release reservation identity is invalid.'
        using errcode = '23514';
    end if;
  else
    select * into v_previous
    from public.organization_retention_release_allocation_ledger_v2
    where id = new.supersedes_ledger_id
    for update;
    if not found
      or v_previous.organization_id <> new.organization_id
      or v_previous.project_id <> new.project_id
      or v_previous.originating_payment_claim_id <>
        new.originating_payment_claim_id
      or v_previous.allocation_id <> new.allocation_id
      or v_previous.reservation_root_id <> new.reservation_root_id
      or v_previous.reservation_sequence + 1 <> new.reservation_sequence then
      raise exception 'Retention release reservation supersession is invalid.'
        using errcode = '23514';
    end if;
  end if;

  if new.reservation_state in ('pending', 'reserved', 'completed') then
    select
      coalesce(sum(abs(existing.released_amount_minor)), 0),
      coalesce(sum(abs(existing.released_tax_minor)), 0)
    into v_existing_amount, v_existing_tax
    from public.organization_retention_release_allocation_ledger_v2 existing
    where existing.organization_id = new.organization_id
      and existing.project_id = new.project_id
      and existing.originating_payment_claim_id =
        new.originating_payment_claim_id
      and existing.reservation_state in ('pending', 'reserved', 'completed')
      and existing.id is distinct from new.supersedes_ledger_id
      and not exists (
        select 1
        from public.organization_retention_release_allocation_ledger_v2 successor
        where successor.supersedes_ledger_id = existing.id
      );

    if v_existing_amount + abs(new.released_amount_minor) >
        abs(new.origin_retained_amount_minor)
      or v_existing_tax + abs(new.released_tax_minor) >
        abs(new.origin_retained_tax_minor) then
      raise exception 'Retention release reservation exceeds origin capacity.'
        using errcode = '23514';
    end if;
  end if;
  return new;
end;
$_$;


ALTER FUNCTION "private"."validate_retention_release_ledger_v2"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."validate_retention_tax_classification_v2"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'private'
    AS $$
declare
  v_previous public.organization_retention_tax_classifications_v2%rowtype;
begin
  if not exists (
    select 1 from public.organization_projects project
    where project.id = new.project_id
      and project.organization_id = new.organization_id
  ) or not exists (
    select 1 from public.project_claims claim
    where claim.id = new.originating_payment_claim_id
      and claim.organization_id = new.organization_id
      and claim.project_id = new.project_id
  ) or not exists (
    select 1 from public.organization_xero_connections connection
    where connection.id = new.xero_connection_id
      and connection.organization_id = new.organization_id
      and connection.tenant_id = new.tenant_id
  ) then
    raise exception 'Retention tax classification scope is inconsistent.'
      using errcode = '23514';
  end if;

  if new.supersedes_classification_id is null then
    if new.classification_sequence <> 1 then
      raise exception 'Initial Retention tax classification sequence must be one.'
        using errcode = '23514';
    end if;
  else
    select * into v_previous
    from public.organization_retention_tax_classifications_v2
    where id = new.supersedes_classification_id
    for update;
    if not found
      or v_previous.organization_id <> new.organization_id
      or v_previous.project_id <> new.project_id
      or v_previous.originating_payment_claim_id <>
        new.originating_payment_claim_id
      or v_previous.classification_sequence + 1 <>
        new.classification_sequence then
      raise exception 'Retention tax classification supersession is invalid.'
        using errcode = '23514';
    end if;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "private"."validate_retention_tax_classification_v2"() OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."supplier_bill_ucl_refresh_queue" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "container_type" "text" DEFAULT 'supplier_invoice'::"text" NOT NULL,
    "source_id" "uuid" NOT NULL,
    "reason_code" "text" NOT NULL,
    "priority" smallint DEFAULT 50 NOT NULL,
    "queue_state" "text" DEFAULT 'pending'::"text" NOT NULL,
    "attempt_count" integer DEFAULT 0 NOT NULL,
    "max_attempts" integer DEFAULT 5 NOT NULL,
    "available_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "lease_owner" "text",
    "lease_token" "uuid",
    "leased_at" timestamp with time zone,
    "lease_expires_at" timestamp with time zone,
    "first_requested_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "last_requested_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "deletion_evidence_at" timestamp with time zone,
    "completed_at" timestamp with time zone,
    "first_failed_at" timestamp with time zone,
    "last_failed_at" timestamp with time zone,
    "last_error_code" "text",
    "last_error_summary" "text",
    "schema_version" "text",
    "builder_version" "text",
    "content_hash" "text",
    "canonical_updated_at" timestamp with time zone,
    "latest_dependency_updated_at" timestamp with time zone,
    "validated_at" timestamp with time zone,
    "payload_bytes" integer,
    "refresh_result" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "supplier_bill_ucl_refresh_queue_attempt_check" CHECK ((("attempt_count" >= 0) AND (("max_attempts" >= 1) AND ("max_attempts" <= 20)))),
    CONSTRAINT "supplier_bill_ucl_refresh_queue_container_check" CHECK (("container_type" = 'supplier_invoice'::"text")),
    CONSTRAINT "supplier_bill_ucl_refresh_queue_error_code_check" CHECK ((("last_error_code" IS NULL) OR ("char_length"("last_error_code") <= 120))),
    CONSTRAINT "supplier_bill_ucl_refresh_queue_error_summary_check" CHECK ((("last_error_summary" IS NULL) OR ("char_length"("last_error_summary") <= 500))),
    CONSTRAINT "supplier_bill_ucl_refresh_queue_payload_bytes_check" CHECK ((("payload_bytes" IS NULL) OR ("payload_bytes" >= 0))),
    CONSTRAINT "supplier_bill_ucl_refresh_queue_priority_check" CHECK ((("priority" >= 0) AND ("priority" <= 100))),
    CONSTRAINT "supplier_bill_ucl_refresh_queue_reason_check" CHECK (("reason_code" = ANY (ARRAY['supplier_bill_created'::"text", 'supplier_bill_header_changed'::"text", 'supplier_bill_lines_changed'::"text", 'supplier_bill_supplier_changed'::"text", 'supplier_bill_project_scope_changed'::"text", 'supplier_bill_document_changed'::"text", 'supplier_bill_extraction_changed'::"text", 'supplier_bill_po_match_changed'::"text", 'supplier_bill_allocation_changed'::"text", 'supplier_bill_routing_changed'::"text", 'supplier_bill_site_review_changed'::"text", 'supplier_bill_accounts_approval_changed'::"text", 'supplier_bill_commercial_approval_changed'::"text", 'supplier_bill_commercial_snapshot_changed'::"text", 'supplier_bill_variance_changed'::"text", 'supplier_bill_actual_cost_changed'::"text", 'supplier_bill_xero_export_changed'::"text", 'supplier_bill_xero_attachment_changed'::"text", 'supplier_bill_payment_changed'::"text", 'supplier_bill_voided'::"text", 'supplier_bill_deleted'::"text", 'supplier_bill_manual_refresh'::"text"]))),
    CONSTRAINT "supplier_bill_ucl_refresh_queue_result_check" CHECK ((("refresh_result" IS NULL) OR ("refresh_result" = ANY (ARRAY['changed'::"text", 'no_change'::"text", 'voided'::"text", 'deleted'::"text", 'stale'::"text"])))),
    CONSTRAINT "supplier_bill_ucl_refresh_queue_state_check" CHECK (("queue_state" = ANY (ARRAY['pending'::"text", 'leased'::"text", 'retry_wait'::"text", 'completed'::"text", 'dead_letter'::"text", 'deleted'::"text"])))
);

ALTER TABLE ONLY "public"."supplier_bill_ucl_refresh_queue" FORCE ROW LEVEL SECURITY;


ALTER TABLE "public"."supplier_bill_ucl_refresh_queue" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_enqueue_supplier_bill_ucl_refresh"("p_organization_id" "uuid", "p_source_id" "uuid", "p_reason_code" "text", "p_priority" integer, "p_confirmed_deletion" boolean DEFAULT false) RETURNS "public"."supplier_bill_ucl_refresh_queue"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  queued public.supplier_bill_ucl_refresh_queue%rowtype;
  source_exists boolean;
begin
  if p_organization_id is null or p_source_id is null then
    return null;
  end if;

  select exists (
    select 1
    from public.supplier_invoices i
    where i.organization_id = p_organization_id
      and i.id = p_source_id
  ) into source_exists;

  -- Cascade child triggers can run after the parent row has disappeared. The
  -- parent DELETE trigger is the only trigger permitted to assert deletion.
  if not source_exists and not coalesce(p_confirmed_deletion, false) then
    return null;
  end if;

  insert into public.supplier_bill_ucl_refresh_queue (
    organization_id,
    container_type,
    source_id,
    reason_code,
    priority,
    queue_state,
    attempt_count,
    available_at,
    first_requested_at,
    last_requested_at,
    deletion_evidence_at,
    completed_at,
    lease_owner,
    lease_token,
    leased_at,
    lease_expires_at,
    last_error_code,
    last_error_summary,
    refresh_result
  ) values (
    p_organization_id,
    'supplier_invoice',
    p_source_id,
    p_reason_code,
    least(greatest(coalesce(p_priority, 50), 0), 100),
    'pending',
    0,
    now(),
    now(),
    now(),
    case when p_confirmed_deletion then now() else null end,
    null,
    null,
    null,
    null,
    null,
    null,
    null,
    null
  )
  on conflict (organization_id, container_type, source_id)
  do update set
    reason_code = case
      when public.supplier_bill_ucl_refresh_queue.queue_state in ('completed', 'deleted')
        or excluded.priority >= public.supplier_bill_ucl_refresh_queue.priority
        then excluded.reason_code
      else public.supplier_bill_ucl_refresh_queue.reason_code
    end,
    priority = case
      when public.supplier_bill_ucl_refresh_queue.queue_state in ('completed', 'deleted')
        then excluded.priority
      else greatest(public.supplier_bill_ucl_refresh_queue.priority, excluded.priority)
    end,
    queue_state = case
      when public.supplier_bill_ucl_refresh_queue.queue_state = 'dead_letter' then 'dead_letter'
      else 'pending'
    end,
    attempt_count = case
      when public.supplier_bill_ucl_refresh_queue.queue_state in ('completed', 'deleted', 'leased', 'retry_wait')
        then 0
      else public.supplier_bill_ucl_refresh_queue.attempt_count
    end,
    available_at = now(),
    first_requested_at = case
      when public.supplier_bill_ucl_refresh_queue.queue_state in ('completed', 'deleted')
        then now()
      else public.supplier_bill_ucl_refresh_queue.first_requested_at
    end,
    last_requested_at = now(),
    deletion_evidence_at = case
      when p_confirmed_deletion then now()
      when source_exists then null
      else public.supplier_bill_ucl_refresh_queue.deletion_evidence_at
    end,
    completed_at = null,
    lease_owner = null,
    lease_token = null,
    leased_at = null,
    lease_expires_at = null,
    last_error_code = case
      when public.supplier_bill_ucl_refresh_queue.queue_state = 'dead_letter'
        then public.supplier_bill_ucl_refresh_queue.last_error_code
      else null
    end,
    last_error_summary = case
      when public.supplier_bill_ucl_refresh_queue.queue_state = 'dead_letter'
        then public.supplier_bill_ucl_refresh_queue.last_error_summary
      else null
    end,
    refresh_result = null,
    updated_at = now()
  returning * into queued;

  return queued;
end;
$$;


