CREATE OR REPLACE FUNCTION "public"."_intelligence_can_read_visibility_scope"("p_organization_id" "uuid", "p_visibility_scope" "text") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  member_row public.organization_members%rowtype;
begin
  if auth.uid() is null then
    return false;
  end if;

  select *
  into member_row
  from public.organization_members m
  where m.organization_id = p_organization_id
    and m.user_id = auth.uid()
  limit 1;

  if member_row.id is null then
    return false;
  end if;

  if p_visibility_scope = 'organization' then
    return true;
  end if;

  if p_visibility_scope = 'restricted_role' then
    return member_row.role in ('owner', 'admin')
      or public.has_org_permission(p_organization_id, 'intelligence.restricted.read');
  end if;

  return false;
end;
$$;


