CREATE OR REPLACE FUNCTION "public"."_organization_memory_confidence_from_signal"("p_evidence_count" integer, "p_dominance_ratio" numeric, "p_is_user_confirmed" boolean DEFAULT false) RETURNS numeric
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
  select least(
    0.99,
    greatest(
      0,
      0.30
      + greatest(coalesce(p_evidence_count, 0) - 2, 0) * 0.10
      + greatest(coalesce(p_dominance_ratio, 0) - 0.50, 0) * 0.40
      + case when coalesce(p_is_user_confirmed, false) then 0.08 else 0 end
    )
  )
$$;


