CREATE OR REPLACE FUNCTION "public"."_organization_memory_default_confidence_delta"("p_link_type" "text") RETURNS numeric
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
  select case lower(coalesce(p_link_type, ''))
    when 'seed' then 0.15
    when 'supporting' then 0.08
    when 'confirmation' then 0.12
    when 'contradiction' then -0.15
    when 'supersession' then -0.20
    else 0
  end
$$;


ALTER FUNCTION "public"."_organization_memory_default_confidence_delta"("p_link_type" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_organization_memory_mark_superseded_conflicts"("p_organization_id" "uuid", "p_memory_category" "text", "p_memory_type" "text", "p_pattern_scope_key" "text", "p_winner_memory_item_id" "uuid", "p_note" "text" DEFAULT 'Superseded by a newer dominant organization-memory pattern.'::"text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  affected_count integer := 0;
begin
  with conflicting_items as (
    select omi.id
    from public.organization_memory_items omi
    where omi.organization_id = p_organization_id
      and omi.memory_category = p_memory_category
      and omi.memory_type = p_memory_type
      and omi.id <> p_winner_memory_item_id
      and omi.is_active
      and coalesce(omi.memory_value->>'patternScopeKey', '') = coalesce(p_pattern_scope_key, '')
  ),
  inserted_supersession_links as (
    insert into public.organization_memory_links (
      organization_memory_item_id,
      organization_id,
      link_type,
      source_entity_type,
      source_entity_id,
      weight,
      confidence_delta,
      note,
      created_by_user_id
    )
    select
      c.id,
      p_organization_id,
      'supersession',
      'organization_memory_item',
      p_winner_memory_item_id,
      1,
      public._organization_memory_default_confidence_delta('supersession'),
      p_note,
      auth.uid()
    from conflicting_items c
    where not exists (
      select 1
      from public.organization_memory_links oml
      where oml.organization_memory_item_id = c.id
        and oml.link_type = 'supersession'
        and oml.source_entity_type = 'organization_memory_item'
        and oml.source_entity_id = p_winner_memory_item_id
    )
    returning organization_memory_item_id
  )
  update public.organization_memory_items omi
  set
    is_active = false,
    contradiction_count = contradiction_count + 1,
    last_contradicted_at = now(),
    confidence_score = greatest(0, least(omi.confidence_score, 0.35) - 0.05),
    updated_at = now()
  where omi.id in (
    select isl.organization_memory_item_id
    from inserted_supersession_links isl
  );

  get diagnostics affected_count = row_count;
  return affected_count;
end;
$$;


ALTER FUNCTION "public"."_organization_memory_mark_superseded_conflicts"("p_organization_id" "uuid", "p_memory_category" "text", "p_memory_type" "text", "p_pattern_scope_key" "text", "p_winner_memory_item_id" "uuid", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_organization_memory_upsert_derived_item"("p_organization_id" "uuid", "p_memory_category" "text", "p_memory_type" "text", "p_memory_key" "text", "p_title" "text", "p_summary" "text", "p_memory_value" "jsonb", "p_evidence_summary" "jsonb", "p_confidence_score" numeric, "p_privacy_classification" "text" DEFAULT 'commercial_sensitive'::"text", "p_visibility_scope" "text" DEFAULT 'organization'::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  resolved_id uuid;
begin
  insert into public.organization_memory_items (
    organization_id,
    memory_category,
    memory_type,
    memory_key,
    title,
    summary,
    memory_value,
    evidence_summary,
    confidence_score,
    is_active,
    first_derived_at,
    last_derived_at,
    privacy_classification,
    visibility_scope
  )
  values (
    p_organization_id,
    p_memory_category,
    p_memory_type,
    p_memory_key,
    p_title,
    p_summary,
    coalesce(p_memory_value, '{}'::jsonb),
    coalesce(p_evidence_summary, '{}'::jsonb),
    least(greatest(coalesce(p_confidence_score, 0), 0), 1),
    true,
    now(),
    now(),
    coalesce(nullif(btrim(coalesce(p_privacy_classification, '')), ''), 'commercial_sensitive'),
    coalesce(nullif(btrim(coalesce(p_visibility_scope, '')), ''), 'organization')
  )
  on conflict (organization_id, memory_category, memory_type, memory_key)
  do update set
    title = excluded.title,
    summary = excluded.summary,
    memory_value = excluded.memory_value,
    evidence_summary = excluded.evidence_summary,
    confidence_score = least(
      1,
      greatest(public.organization_memory_items.confidence_score, excluded.confidence_score)
      + case when public.organization_memory_items.is_user_confirmed then 0.08 else 0 end
    ),
    is_active = true,
    last_derived_at = now(),
    privacy_classification = excluded.privacy_classification,
    visibility_scope = excluded.visibility_scope,
    updated_at = now()
  returning id into resolved_id;

  return resolved_id;
end;
$$;


ALTER FUNCTION "public"."_organization_memory_upsert_derived_item"("p_organization_id" "uuid", "p_memory_category" "text", "p_memory_type" "text", "p_memory_key" "text", "p_title" "text", "p_summary" "text", "p_memory_value" "jsonb", "p_evidence_summary" "jsonb", "p_confidence_score" numeric, "p_privacy_classification" "text", "p_visibility_scope" "text") OWNER TO "postgres";


