CREATE OR REPLACE FUNCTION "public"."_pricing_worksheet_structure_summary"("p_worksheet_data" "jsonb") RETURNS "jsonb"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
  with cell_entries as (
    select value
    from jsonb_each(coalesce(p_worksheet_data->'cells', '{}'::jsonb))
  ),
  counts as (
    select
      count(*) filter (
        where nullif(btrim(coalesce(value->>'formula', '')), '') is not null
      )::integer as formula_count,
      count(*) filter (
        where nullif(btrim(coalesce(value->>'formula', '')), '') is not null
          or jsonb_typeof(value->'value') = 'number'
          or (
            jsonb_typeof(value->'value') = 'string'
            and char_length(btrim(coalesce(value->>'value', ''))) > 0
          )
      )::integer as populated_cell_count
    from cell_entries
  )
  select jsonb_build_object(
    'rowCount',
    greatest(
      coalesce(jsonb_array_length(coalesce(p_worksheet_data->'rows', '[]'::jsonb)), 0),
      case
        when jsonb_typeof(p_worksheet_data->'rowCount') = 'number' then (p_worksheet_data->>'rowCount')::integer
        else 0
      end
    ),
    'columnCount',
    greatest(
      coalesce(jsonb_array_length(coalesce(p_worksheet_data->'columns', '[]'::jsonb)), 0),
      case
        when jsonb_typeof(p_worksheet_data->'columnCount') = 'number' then (p_worksheet_data->>'columnCount')::integer
        else 0
      end
    ),
    'formulaCount', coalesce((select formula_count from counts), 0),
    'populatedCellCount', coalesce((select populated_cell_count from counts), 0)
  );
$$;


ALTER FUNCTION "public"."_pricing_worksheet_structure_summary"("p_worksheet_data" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_supplier_bill_ucl_accounting_document_trigger"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  row_data jsonb := coalesce(to_jsonb(new), to_jsonb(old));
  reason_code text := 'supplier_bill_xero_export_changed';
begin
  if row_data->>'local_document_type' <> 'supplier_invoice' then
    if tg_op = 'DELETE' then return old; end if;
    return new;
  end if;

  if tg_op = 'UPDATE' and (
    (to_jsonb(new) -> 'amount_paid') is distinct from (to_jsonb(old) -> 'amount_paid')
    or (to_jsonb(new) -> 'amount_due') is distinct from (to_jsonb(old) -> 'amount_due')
    or (to_jsonb(new) -> 'fully_paid_at') is distinct from (to_jsonb(old) -> 'fully_paid_at')
    or (to_jsonb(new) -> 'normalized_external_status') is distinct from (to_jsonb(old) -> 'normalized_external_status')
    or (to_jsonb(new) -> 'last_status_sync_error') is distinct from (to_jsonb(old) -> 'last_status_sync_error')
  ) then
    reason_code := 'supplier_bill_payment_changed';
  elsif tg_op = 'UPDATE' and (
    (to_jsonb(new) -> 'attachment_status') is distinct from (to_jsonb(old) -> 'attachment_status')
  ) then
    reason_code := 'supplier_bill_xero_attachment_changed';
  end if;

  perform public._enqueue_supplier_bill_ucl_refresh(
    nullif(row_data->>'organization_id', '')::uuid,
    nullif(row_data->>'local_document_id', '')::uuid,
    reason_code,
    80,
    false
  );
  if tg_op = 'DELETE' then return old; end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."_supplier_bill_ucl_accounting_document_trigger"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_supplier_bill_ucl_accounting_line_trigger"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  row_data jsonb := coalesce(to_jsonb(new), to_jsonb(old));
  accounting_document record;
begin
  select d.organization_id, d.local_document_id
  into accounting_document
  from public.organization_accounting_documents d
  where d.local_document_type = 'supplier_invoice'
    and d.current_version_id = nullif(row_data->>'version_id', '')::uuid
  limit 1;

  if found then
    perform public._enqueue_supplier_bill_ucl_refresh(
      accounting_document.organization_id,
      accounting_document.local_document_id,
      'supplier_bill_routing_changed',
      80,
      false
    );
  end if;
  if tg_op = 'DELETE' then return old; end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."_supplier_bill_ucl_accounting_line_trigger"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_supplier_bill_ucl_direct_dependency_trigger"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  row_data jsonb := coalesce(to_jsonb(new), to_jsonb(old));
  organization_id uuid := nullif(row_data->>'organization_id', '')::uuid;
  source_id uuid;
  reason_code text := tg_argv[0];
  priority integer := coalesce(nullif(tg_argv[1], '')::integer, 50);
begin
  if tg_table_name = 'supplier_invoices' then
    source_id := nullif(row_data->>'id', '')::uuid;
    if tg_op = 'INSERT' then
      reason_code := 'supplier_bill_created';
      priority := 50;
    elsif tg_op = 'DELETE' then
      reason_code := 'supplier_bill_deleted';
      priority := 100;
    elsif coalesce(new.status, '') is distinct from coalesce(old.status, '')
      and lower(coalesce(new.status, '')) in ('void', 'voided', 'cancelled', 'canceled') then
      reason_code := 'supplier_bill_voided';
      priority := 100;
    elsif new.supplier_id is distinct from old.supplier_id then
      reason_code := 'supplier_bill_supplier_changed';
      priority := 100;
    else
      reason_code := 'supplier_bill_header_changed';
      priority := 50;
    end if;
  else
    source_id := nullif(row_data->>'supplier_invoice_id', '')::uuid;
  end if;

  -- Removal of document, match, allocation or snapshot references is critical:
  -- a stale current context could otherwise continue to advertise removed data.
  if tg_op = 'DELETE' and tg_table_name in (
    'supplier_invoice_documents',
    'supplier_invoice_purchase_order_matches',
    'supplier_invoice_line_allocations',
    'supplier_invoice_commercial_line_snapshots'
  ) then
    priority := 100;
  end if;

  if tg_table_name = 'supplier_invoice_line_allocations' and tg_op = 'UPDATE' then
    if (to_jsonb(new) -> 'organization_cost_code_id') is distinct from (to_jsonb(old) -> 'organization_cost_code_id')
      or (to_jsonb(new) -> 'accounting_mapping_id') is distinct from (to_jsonb(old) -> 'accounting_mapping_id')
      or (to_jsonb(new) -> 'accounting_tax_rate_id') is distinct from (to_jsonb(old) -> 'accounting_tax_rate_id')
      or (to_jsonb(new) -> 'tradesstack_cost_code') is distinct from (to_jsonb(old) -> 'tradesstack_cost_code')
      or (to_jsonb(new) -> 'xero_account_code') is distinct from (to_jsonb(old) -> 'xero_account_code')
      or (to_jsonb(new) -> 'xero_tax_type') is distinct from (to_jsonb(old) -> 'xero_tax_type') then
      reason_code := 'supplier_bill_routing_changed';
      priority := 80;
    end if;
  end if;

  perform public._enqueue_supplier_bill_ucl_refresh(
    organization_id,
    source_id,
    reason_code,
    priority,
    tg_table_name = 'supplier_invoices' and tg_op = 'DELETE'
  );
  if tg_op = 'DELETE' then return old; end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."_supplier_bill_ucl_direct_dependency_trigger"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_supplier_bill_ucl_project_dependency_trigger"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_row_data jsonb := coalesce(to_jsonb(new), to_jsonb(old));
  v_organization_id uuid := nullif(v_row_data->>'organization_id', '')::uuid;
  v_project_id uuid := nullif(v_row_data->>'id', '')::uuid;
  v_invoice record;
begin
  for v_invoice in
    select distinct candidate.supplier_invoice_id
    from (
      select l.supplier_invoice_id
      from public.supplier_invoice_lines l
      where l.organization_id = v_organization_id
        and l.project_id = v_project_id
      union
      select a.supplier_invoice_id
      from public.supplier_invoice_line_allocations a
      where a.organization_id = v_organization_id
        and a.project_id = v_project_id
      union
      select m.supplier_invoice_id
      from public.supplier_invoice_purchase_order_matches m
      join public.project_purchase_orders po
        on po.organization_id = v_organization_id
       and po.id = m.purchase_order_id
      where m.organization_id = v_organization_id
        and po.project_id = v_project_id
    ) candidate
    where candidate.supplier_invoice_id is not null
  loop
    perform public._enqueue_supplier_bill_ucl_refresh(
      v_organization_id,
      v_invoice.supplier_invoice_id,
      'supplier_bill_project_scope_changed',
      100,
      false
    );
  end loop;

  if tg_op = 'DELETE' then return old; end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."_supplier_bill_ucl_project_dependency_trigger"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_supplier_bill_ucl_purchase_order_dependency_trigger"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_row_data jsonb := coalesce(to_jsonb(new), to_jsonb(old));
  v_organization_id uuid := nullif(v_row_data->>'organization_id', '')::uuid;
  v_purchase_order_id uuid;
  v_purchase_order_line_id uuid;
  v_dependency record;
begin
  if tg_table_name = 'project_purchase_orders' then
    v_purchase_order_id := nullif(v_row_data->>'id', '')::uuid;
  else
    v_purchase_order_line_id := nullif(v_row_data->>'id', '')::uuid;
    v_purchase_order_id := nullif(v_row_data->>'purchase_order_id', '')::uuid;
  end if;

  for v_dependency in
    select distinct candidate.supplier_invoice_id
    from (
      select m.supplier_invoice_id
      from public.supplier_invoice_purchase_order_matches m
      where m.organization_id = v_organization_id
        and m.purchase_order_id = v_purchase_order_id
      union
      select a.supplier_invoice_id
      from public.supplier_invoice_line_allocations a
      where a.organization_id = v_organization_id
        and (
          a.purchase_order_id = v_purchase_order_id
          or (
            v_purchase_order_line_id is not null
            and a.purchase_order_line_item_id = v_purchase_order_line_id
          )
        )
      union
      select s.supplier_invoice_id
      from public.supplier_invoice_commercial_line_snapshots s
      where s.organization_id = v_organization_id
        and (
          s.purchase_order_id = v_purchase_order_id
          or (
            v_purchase_order_line_id is not null
            and s.purchase_order_line_item_id = v_purchase_order_line_id
          )
        )
      union
      select e.supplier_invoice_id
      from public.project_actual_cost_events e
      where e.organization_id = v_organization_id
        and (
          e.purchase_order_id = v_purchase_order_id
          or (
            v_purchase_order_line_id is not null
            and e.purchase_order_line_item_id = v_purchase_order_line_id
          )
        )
    ) candidate
    where candidate.supplier_invoice_id is not null
  loop
    perform public._enqueue_supplier_bill_ucl_refresh(
      v_organization_id,
      v_dependency.supplier_invoice_id,
      'supplier_bill_po_match_changed',
      80,
      false
    );
  end loop;

  if tg_op = 'DELETE' then return old; end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."_supplier_bill_ucl_purchase_order_dependency_trigger"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_supplier_bill_ucl_supplier_dependency_trigger"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  row_data jsonb := coalesce(to_jsonb(new), to_jsonb(old));
  invoice record;
begin
  for invoice in
    select i.organization_id, i.id
    from public.supplier_invoices i
    where i.organization_id = nullif(row_data->>'organization_id', '')::uuid
      and i.supplier_id = nullif(row_data->>'id', '')::uuid
  loop
    perform public._enqueue_supplier_bill_ucl_refresh(
      invoice.organization_id,
      invoice.id,
      'supplier_bill_supplier_changed',
      100,
      false
    );
  end loop;
  if tg_op = 'DELETE' then return old; end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."_supplier_bill_ucl_supplier_dependency_trigger"() OWNER TO "postgres";


