    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
  select jsonb_set(
    case
      when jsonb_typeof(coalesce(p_worksheet_data, '{}'::jsonb)) = 'object' then coalesce(p_worksheet_data, '{}'::jsonb)
      else '{}'::jsonb
    end,
    '{sheetName}',
