    CONSTRAINT "organization_projects_name_not_blank" CHECK (("char_length"(TRIM(BOTH FROM "name")) > 0)),
    CONSTRAINT "organization_projects_slug_not_blank" CHECK (("char_length"(TRIM(BOTH FROM "slug")) > 0)),
