CREATE OR REPLACE FUNCTION "public"."_worksheet_pricing_pattern_shadow_normalize_text"("p_value" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select nullif(regexp_replace(lower(btrim(coalesce(p_value, ''))), '\s+', ' ', 'g'), '');
$$;


