CREATE OR REPLACE FUNCTION "public"."accept_organization_invite"("invite_token" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  invite_row public.organization_invites%rowtype;
  current_email text;
  member_name text;
begin
  if auth.uid() is null then
    raise exception 'You must be signed in to accept an invite.';
  end if;

  select i.*
  into invite_row
  from public.organization_invites i
  where i.token = invite_token
    and i.status = 'pending'
  limit 1;

  if not found then
    raise exception 'Invite is invalid or no longer active.';
  end if;

  if invite_row.expires_at <= now() then
    update public.organization_invites
    set status = 'expired', updated_at = now()
    where id = invite_row.id;

    raise exception 'Invite has expired.';
  end if;

  current_email := lower(coalesce(auth.jwt() ->> 'email', ''));
  if current_email = '' then
    raise exception 'Signed-in user email is missing.';
  end if;

  if lower(invite_row.invited_email) <> current_email then
    raise exception 'This invite was issued to a different email.';
  end if;

  if exists (
    select 1
    from public.organization_members m
    where m.user_id = auth.uid()
      and m.organization_id <> invite_row.organization_id
  ) then
    raise exception 'This account already belongs to a different organization.';
  end if;

  member_name := nullif(trim(coalesce(auth.jwt() ->> 'full_name', '')), '');
  if member_name is null then
    member_name := split_part(current_email, '@', 1);
  end if;

  insert into public.organization_members (organization_id, user_id, role, display_name)
  values (invite_row.organization_id, auth.uid(), invite_row.role, member_name)
  on conflict (organization_id, user_id) do update
  set
    role = excluded.role,
    display_name = excluded.display_name,
    updated_at = now();

  update public.organization_invites
  set status = 'accepted', accepted_at = now(), updated_at = now()
  where id = invite_row.id;

  return invite_row.organization_id;
end;
$$;


ALTER FUNCTION "public"."accept_organization_invite"("invite_token" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."accept_retention_variance_contractual_override"("p_input" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
declare v public.retention_variances%rowtype; ctx jsonb; reason text; evidence jsonb;
  approved numeric; basis text; old_state text;
begin
  select * into v from public.retention_variances where id=(p_input->>'varianceId')::uuid;
  if not found then return jsonb_build_object('succeeded',false,'errorCode','variance_not_found'); end if;
  ctx:=private.retention_phase5_context(v.project_id,'retention.variances.override',true);
  if not coalesce((ctx->>'succeeded')::boolean,false) then
    return case when ctx->>'errorCode'='permission_denied'
      then jsonb_build_object('succeeded',false,'errorCode','override_permission_required')
      else ctx end;
  end if;
  reason:=nullif(trim(coalesce(p_input->>'reason','')),'');
  evidence:=p_input->'evidence';
  if reason is null then
    return jsonb_build_object('succeeded',false,'errorCode','override_reason_required');
  end if;
  if evidence is null or jsonb_typeof(evidence)<>'object' or evidence='{}'::jsonb then
    return jsonb_build_object('succeeded',false,'errorCode','corrective_evidence_required');
  end if;
  begin approved:=(p_input->>'approvedDiscrepancyAmount')::numeric;
  exception when others then
    return jsonb_build_object('succeeded',false,'errorCode','invalid_corrective_amount');
  end;
  if approved is null or approved<0 then
    return jsonb_build_object('succeeded',false,'errorCode','invalid_corrective_amount');
  end if;
  select * into v from public.retention_variances where id=v.id for update;
  if v.revision<>(p_input->>'expectedRevision')::bigint then
    return jsonb_build_object('succeeded',false,'errorCode','concurrent_update',
      'currentRevision',v.revision);
  end if;
  if v.state in ('resolved','accepted_contractual_override') then
    return jsonb_build_object('succeeded',false,'errorCode','variance_already_resolved');
  end if;
  basis:=encode(extensions.digest(convert_to(jsonb_build_object(
    'phase2',v.latest_phase2_state_hash,'phase4',v.latest_phase4_eligibility_hash,
    'committed',v.committed_allocation_hash,'type',v.primary_type,
    'ownershipVariance',v.ownership_variance,
    'eligibilityVariance',v.eligibility_variance)::text,'UTF8'),'sha256'),'hex');
  old_state:=v.state;
  perform set_config('app.retention_phase5_internal_write','true',true);
  update public.retention_variances set
    state='accepted_contractual_override',is_blocking=false,
    resolution_type='accepted_contractual_override',resolution_reason=reason,
    resolution_evidence=evidence,override_approved_amount=approved,
    override_basis_hash=basis,resolution_approved_by=auth.uid(),resolved_at=now(),
    last_correlation_id=p_input->>'correlationId',revision=revision+1,updated_at=now()
  where id=v.id returning * into v;
  perform set_config('app.retention_phase5_internal_write','',true);
  perform private.record_retention_variance_event(v.id,'contractual_override_accepted',
    old_state,v.state,v.severity,v.severity,reason,p_input->>'correlationId',
    jsonb_build_object('approvedDiscrepancyAmount',approved,'evidence',evidence,
      'basisHash',basis,'availabilityRestored',false));
  return jsonb_build_object('succeeded',true,'errorCode',null,
    'availabilityRestored',false,'variance',private.retention_variance_read_json(v.id));
end;
$$;


ALTER FUNCTION "public"."accept_retention_variance_contractual_override"("p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."acquire_document_download_guard"("p_ip_subject_key" "text") RETURNS TABLE("allowed" boolean, "rejected_by" "text", "ip_limit_ms" double precision, "user_limit_ms" double precision, "concurrency_ms" double precision)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  actor_user_id uuid := auth.uid();
  stage_started timestamptz;
  ip_allowed boolean;
  user_allowed boolean;
  concurrency_allowed boolean;
  user_subject_key text;
  active_subject_key text;
begin
  if actor_user_id is null then
    raise exception 'Authentication required.' using errcode = '42501';
  end if;

  user_subject_key := 'user:document-download:' || actor_user_id::text;
  active_subject_key := 'active:document-download:' || actor_user_id::text;

  stage_started := clock_timestamp();
  ip_allowed := public.enforce_shared_rate_limit(
    'document-download', p_ip_subject_key, 240, 60
  );
  ip_limit_ms := extract(epoch from clock_timestamp() - stage_started) * 1000;
  if ip_allowed is not true then
    return query select false, 'ip', ip_limit_ms, 0::double precision, 0::double precision;
    return;
  end if;

  stage_started := clock_timestamp();
  user_allowed := public.enforce_shared_rate_limit(
    'document-download', user_subject_key, 120, 60
  );
  user_limit_ms := extract(epoch from clock_timestamp() - stage_started) * 1000;
  if user_allowed is not true then
    return query select false, 'user', ip_limit_ms, user_limit_ms, 0::double precision;
    return;
  end if;

  stage_started := clock_timestamp();
  concurrency_allowed := public.acquire_shared_concurrency_slot(
    'document-download', active_subject_key, 8
  );
  concurrency_ms := extract(epoch from clock_timestamp() - stage_started) * 1000;
  return query select
    concurrency_allowed is true,
    case when concurrency_allowed is true then null::text else 'concurrency' end,
    ip_limit_ms,
    user_limit_ms,
    concurrency_ms;
end;
$$;


ALTER FUNCTION "public"."acquire_document_download_guard"("p_ip_subject_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."acquire_shared_concurrency_slot"("p_route_key" "text", "p_subject_key" "text", "p_limit" integer) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_limit integer := greatest(coalesce(p_limit, 0), 0);
  v_active_count integer;
begin
  if v_limit = 0 then
    return true;
  end if;

  insert into public.request_concurrency_limits (route_key, subject_key, active_count, updated_at)
  values (p_route_key, p_subject_key, 1, now())
  on conflict (route_key, subject_key)
  do update
    set active_count = request_concurrency_limits.active_count + 1,
        updated_at = now()
    where request_concurrency_limits.active_count < v_limit
  returning active_count into v_active_count;

  return v_active_count is not null;
end;
$$;


ALTER FUNCTION "public"."acquire_shared_concurrency_slot"("p_route_key" "text", "p_subject_key" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."activate_retention_release_schedule"("p_input" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare s public.project_retention_release_schedules%rowtype; result jsonb;
  origins uuid[]; ctx jsonb;
begin
  if not private.retention_phase5_gate_enabled() then
    return public.activate_retention_release_schedule_phase4_pre_variance(p_input);
  end if;
  select * into s from public.project_retention_release_schedules
  where id=(p_input->>'scheduleId')::uuid;
  if not found then return jsonb_build_object('succeeded',false,'errorCode','schedule_not_found'); end if;
  ctx:=private.retention_phase5_context(
    s.project_id,'retention.schedules.confirm',true);
  if not coalesce((ctx->>'succeeded')::boolean,false) then return ctx; end if;
  select coalesce(array_agg(o.originating_payment_claim_id order by o.originating_payment_claim_id),
    '{}'::uuid[]) into origins
  from public.project_retention_schedule_origins o where o.schedule_id=s.id;
  perform private.evaluate_retention_variance_project(
    s.project_id,p_input->>'correlationId',origins);
  result:=public.activate_retention_release_schedule_phase4_pre_variance(p_input);
  if coalesce((result->>'succeeded')::boolean,false) then
    perform private.evaluate_retention_variance_project(
      s.project_id,p_input->>'correlationId',origins);
  end if;
  return result;
end;
$$;


ALTER FUNCTION "public"."activate_retention_release_schedule"("p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."activate_retention_release_schedule_phase4_pre_variance"("p_input" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
declare v_s public.project_retention_release_schedules%rowtype; v_context jsonb;
  v_position jsonb; v_position_hash text; v_tz text; v_local_today date;
  v_base_date date; v_origin_count integer; v_explicit_fixed numeric; v_auto_count integer;
  v_state jsonb; v_hash text; v_reminders integer;
begin
  select * into v_s from public.project_retention_release_schedules where id=(p_input->>'scheduleId')::uuid;
  if not found then return jsonb_build_object('succeeded',false,'errorCode','schedule_not_found'); end if;
  v_context:=private.retention_phase4_context(v_s.project_id,'retention.schedules.confirm',true);
  if not coalesce((v_context->>'succeeded')::boolean,false) then return v_context; end if;
  select * into v_s from public.project_retention_release_schedules where id=v_s.id for update;
  if v_s.status not in ('scheduled','awaiting_confirmation') then
    perform private.record_retention_schedule_event(v_s.id,'activation_rejected',v_s.status,v_s.status,
      'schedule_not_activatable',p_input->>'correlationId','{}'::jsonb);
    return jsonb_build_object('succeeded',false,'errorCode','schedule_not_activatable');
  end if;
  if v_s.revision<>(p_input->>'expectedRevision')::bigint then
    return jsonb_build_object('succeeded',false,'errorCode','concurrent_update','currentRevision',v_s.revision);
  end if;
  select o.timezone into v_tz from public.organizations o where o.id=v_s.organization_id;
  if not exists(select 1 from pg_timezone_names where name=v_tz) then v_tz:='UTC'; end if;
  v_local_today:=(now() at time zone v_tz)::date;
  if v_s.trigger_type='fixed_date' then
    if v_s.scheduled_trigger_date is null then
      return jsonb_build_object('succeeded',false,'errorCode','invalid_trigger');
    end if;
    if v_s.scheduled_trigger_date>v_local_today then
      return jsonb_build_object('succeeded',false,'errorCode','schedule_not_activatable',
        'currentBusinessDate',v_local_today);
    end if;
    if v_s.confirmation_required and v_s.trigger_confirmed_at is null then
      return jsonb_build_object('succeeded',false,'errorCode','trigger_confirmation_required');
    end if;
    v_base_date:=coalesce(v_s.actual_trigger_date,v_s.scheduled_trigger_date);
  else
    if v_s.trigger_confirmed_at is null or v_s.actual_trigger_date is null then
      return jsonb_build_object('succeeded',false,'errorCode','trigger_confirmation_required');
    end if;
    if v_s.trigger_type in ('manual_milestone','custom') and
      (nullif(trim(coalesce(v_s.trigger_confirmation_reason,'')),'') is null
       or v_s.trigger_confirmation_evidence is null) then
      return jsonb_build_object('succeeded',false,'errorCode','trigger_confirmation_required');
    end if;
    v_base_date:=v_s.actual_trigger_date;
  end if;

  v_position:=public.get_project_retention_position_summary(v_s.project_id);
  v_position_hash:=v_position->>'stateHash';
  if coalesce(v_position->>'accessState','')<>'available' then
    return jsonb_build_object('succeeded',false,'errorCode','stale_retention_position');
  end if;

  if v_s.scope_policy='all_current_origins' then
    insert into public.project_retention_schedule_origins(
      organization_id,project_id,schedule_id,originating_payment_claim_id,
      origin_sequence,created_by
    )
    select v_s.organization_id,v_s.project_id,v_s.id,p.id,
      coalesce((select max(o.origin_sequence) from public.project_retention_schedule_origins o
                where o.schedule_id=v_s.id),0)
        + row_number() over(order by p.created_at,p.id),auth.uid()
    from public.project_claims p
    where p.organization_id=v_s.organization_id and p.project_id=v_s.project_id
      and p.status<>'Cancelled' and greatest(p.retention_withheld_amount,0)>0
      and not exists(select 1 from public.project_retention_schedule_origins o
        where o.schedule_id=v_s.id and o.originating_payment_claim_id=p.id)
    order by p.created_at,p.id;
  end if;

  perform p.id from public.project_claims p
  join public.project_retention_schedule_origins o on o.originating_payment_claim_id=p.id
  where o.schedule_id=v_s.id order by p.id for update of p;

  if exists(
    select 1 from public.project_retention_schedule_origins o
    left join public.project_claims p on p.id=o.originating_payment_claim_id
    where o.schedule_id=v_s.id and (
      p.id is null or p.organization_id<>v_s.organization_id or p.project_id<>v_s.project_id
      or p.status='Cancelled'
    )
  ) then return jsonb_build_object('succeeded',false,'errorCode','invalid_schedule_scope'); end if;

  select count(*),coalesce(sum(o.fixed_amount_override),0),
    count(*) filter(where o.fixed_amount_override is null)
  into v_origin_count,v_explicit_fixed,v_auto_count
  from public.project_retention_schedule_origins o where o.schedule_id=v_s.id;
  if v_origin_count=0 then return jsonb_build_object('succeeded',false,'errorCode','invalid_schedule_scope'); end if;
  if v_s.entitlement_method='fixed_amount' and (
    v_explicit_fixed>v_s.fixed_amount
    or (v_auto_count=0 and round(v_explicit_fixed,2)<>round(v_s.fixed_amount,2))
  ) then return jsonb_build_object('succeeded',false,'errorCode','schedule_overlap_invalid'); end if;

  -- All arithmetic is performed in integer cents. Fixed unassigned pools and
  -- schedule caps use largest-remainder distribution, ties broken by origin ID.
  with source as (
    select o.id,o.originating_payment_claim_id,o.fixed_amount_override,o.cap_amount,
      greatest(p.retention_withheld_amount,0) as owned,
      coalesce(o.percentage_bps_override,v_s.percentage_bps) as bps
    from public.project_retention_schedule_origins o
    join public.project_claims p on p.id=o.originating_payment_claim_id
    where o.schedule_id=v_s.id
  ), fixed_context as (
    select greatest(round(v_s.fixed_amount*100)::bigint
      -coalesce(sum(round(fixed_amount_override*100)::bigint),0),0) as remaining_cents,
      coalesce(sum(round(owned*100)::bigint) filter(where fixed_amount_override is null),0) as weight_total
    from source
  ), raw as (
    select s.*,
      case when v_s.entitlement_method='percentage'
        then round(s.owned*s.bps/10000.0*100)::bigint
        when s.fixed_amount_override is not null
        then round(s.fixed_amount_override*100)::bigint
        when f.weight_total=0 then 0
        else floor(f.remaining_cents*round(s.owned*100)::numeric/f.weight_total)::bigint end as base_cents,
      case when v_s.entitlement_method='fixed_amount' and s.fixed_amount_override is null
                and f.weight_total>0
        then (f.remaining_cents*round(s.owned*100)::numeric/f.weight_total)
          -floor(f.remaining_cents*round(s.owned*100)::numeric/f.weight_total)
        else 0 end as fraction,
      f.remaining_cents
    from source s cross join fixed_context f
  ), fixed_ranked as (
    select r.*,
      row_number() over(order by r.fraction desc,r.originating_payment_claim_id) as fraction_rank,
      case when v_s.entitlement_method='fixed_amount'
        then greatest(round(v_s.fixed_amount*100)::bigint-sum(r.base_cents) over(),0)
        else 0 end as leftover
    from raw r
  ), origin_capped as (
    select *,
      least(base_cents+case when fraction_rank<=leftover then 1 else 0 end,
        round(owned*100)::bigint,
        coalesce(round(cap_amount*100)::bigint,9223372036854775807)) as preliminary_cents
    from fixed_ranked
  ), schedule_context as (
    select *,
      least(coalesce(round(v_s.cap_amount*100)::bigint,sum(preliminary_cents) over()),
            sum(preliminary_cents) over()) as target_cents,
      sum(preliminary_cents) over() as preliminary_total
    from origin_capped
  ), schedule_base as (
    select *,
      case when preliminary_total=0 then 0
        else floor(target_cents*preliminary_cents::numeric/preliminary_total)::bigint end as cap_base,
      case when preliminary_total=0 then 0
        else (target_cents*preliminary_cents::numeric/preliminary_total)
          -floor(target_cents*preliminary_cents::numeric/preliminary_total) end as cap_fraction
    from schedule_context
  ), final_ranked as (
    select *,
      row_number() over(order by cap_fraction desc,originating_payment_claim_id) as cap_rank,
      greatest(target_cents-sum(cap_base) over(),0) as cap_leftover
    from schedule_base
  )
  update public.project_retention_schedule_origins o set
    activated_entitlement_amount=(f.cap_base+case when f.cap_rank<=f.cap_leftover then 1 else 0 end)/100.0,
    activation_claim_number_snapshot=p.claim_number,
    activation_claim_date_snapshot=p.claim_date,
    activation_claim_status_snapshot=p.status,
    activation_claim_created_at_snapshot=p.created_at,
    activation_claim_updated_at_snapshot=p.updated_at,
    activation_retention_owned_snapshot=greatest(p.retention_withheld_amount,0),
    activation_origin_state_hash=private.retention_claim_origin_state_hash(p.id),
    activation_position_state_hash=v_position_hash,
    activation_evidence=jsonb_build_object(
      'entitlementMethod',v_s.entitlement_method,'schedulePercentageBps',v_s.percentage_bps,
      'originPercentageBps',f.bps,'scheduleFixedAmount',v_s.fixed_amount,
      'originFixedAmount',f.fixed_amount_override,'scheduleCap',v_s.cap_amount,
      'originCap',f.cap_amount,'preliminaryCents',f.preliminary_cents,
      'activatedEntitlementCents',f.cap_base+case when f.cap_rank<=f.cap_leftover then 1 else 0 end,
      'distribution','largest_remainder'
    ),
    activated_at=now()
  from final_ranked f join public.project_claims p on p.id=f.originating_payment_claim_id
  where o.id=f.id;

  update public.project_retention_release_schedules set
    status='activated',eligibility_date=v_base_date+delay_days,
    activated_at=now(),activated_by=auth.uid(),
    activation_position_state_hash=v_position_hash,
    activation_evidence=jsonb_build_object(
      'originCount',v_origin_count,'scopePolicy',v_s.scope_policy,
      'businessTimezone',v_tz,'contractualBaseDate',v_base_date,
      'entitlementMethod',v_s.entitlement_method,'positionStateHash',v_position_hash
    ),
    revision=revision+1
  where id=v_s.id returning * into v_s;

  v_state:=private.retention_eligibility_state(v_s.project_id);
  v_hash:=v_state->>'eligibilityStateHash';
  perform set_config('app.retention_phase4_internal_write','true',true);
  update public.project_retention_release_schedules set activation_eligibility_state_hash=v_hash
  where id=v_s.id returning * into v_s;
  perform set_config('app.retention_phase4_internal_write','',true);
  v_reminders:=private.generate_activation_reminders(v_s.id);
  perform private.record_retention_schedule_event(
    v_s.id,'schedule_activated','scheduled','activated','Retention release schedule activated.',
    p_input->>'correlationId',jsonb_build_object(
      'eligibilityDate',v_s.eligibility_date,'positionStateHash',v_position_hash,
      'eligibilityStateHash',v_hash,'originCount',v_origin_count,'reminderCount',v_reminders
    )
  );
  return jsonb_build_object('succeeded',true,'errorCode',null,'schedule',to_jsonb(v_s),
    'origins',private.retention_schedule_origins_json(v_s.id),'eligibility',v_state);
end;
$$;


ALTER FUNCTION "public"."activate_retention_release_schedule_phase4_pre_variance"("p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."activate_successful_accounting_revision_phase2a"("p_revision_id" "uuid", "p_external_document_id" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  revision public.organization_accounting_document_revisions%rowtype;
  successful_attempt public.organization_accounting_revision_attempts%rowtype;
  prior_id uuid;
begin
  select * into revision
  from public.organization_accounting_document_revisions
  where id = p_revision_id for update;
  if not found then raise exception 'Accounting revision not found.'; end if;
  if revision.lifecycle_state = 'superseded' then
    raise exception 'A superseded accounting revision cannot become active.';
  end if;

  select * into successful_attempt
  from public.organization_accounting_revision_attempts a
  where a.accounting_revision_id = revision.id
    and a.attempt_intent in ('create', 'update', 'amend', 'credit', 'void', 'replace')
  order by a.attempt_sequence desc
  limit 1;
  if not found or successful_attempt.queue_state <> 'succeeded' then
    raise exception 'Only the latest successful invoice attempt can activate a revision.';
  end if;
  if nullif(trim(p_external_document_id), '') is null then
    raise exception 'A successful provider document identity is required.';
  end if;

  select active_accounting_revision_id into prior_id
  from public.organization_accounting_documents
  where id = revision.accounting_document_id
    and organization_id = revision.organization_id
  for update;
  if not found then raise exception 'Stable accounting document not found.'; end if;

  perform set_config('app.accounting_phase2a_lifecycle_write', 'true', true);
  if prior_id is not null and prior_id <> revision.id then
    update public.organization_accounting_document_revisions set
      lifecycle_state = 'superseded',
      superseded_at = now(),
      superseded_by_revision_id = revision.id,
      updated_at = now()
    where id = prior_id
      and organization_id = revision.organization_id
      and accounting_document_id = revision.accounting_document_id
      and lifecycle_state = 'succeeded';
    if not found then
      raise exception 'Current active revision is not a successful revision of this document.';
    end if;
  end if;
  update public.organization_accounting_document_revisions set
    lifecycle_state = 'succeeded',
    external_document_id = trim(p_external_document_id),
    succeeded_at = coalesce(succeeded_at, now()),
    activated_at = coalesce(activated_at, now()),
    updated_at = now()
  where id = revision.id;
  perform set_config('app.accounting_phase2a_lifecycle_write', '', true);

  perform set_config('app.accounting_phase2a_pointer_write', 'true', true);
  update public.organization_accounting_documents
  set active_accounting_revision_id = revision.id
  where id = revision.accounting_document_id
    and organization_id = revision.organization_id;
  perform set_config('app.accounting_phase2a_pointer_write', '', true);
  return true;
end;
$$;


ALTER FUNCTION "public"."activate_successful_accounting_revision_phase2a"("p_revision_id" "uuid", "p_external_document_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_project_member"("p_organization_id" "uuid", "p_project_id" "uuid", "p_organization_member_id" "uuid") RETURNS TABLE("id" "uuid", "organization_id" "uuid", "project_id" "uuid", "organization_member_id" "uuid", "created_by" "uuid", "is_active" boolean, "removed_at" timestamp with time zone, "removed_by" "uuid", "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  existing_active_row public.project_members%rowtype;
  restored_row public.project_members%rowtype;
  inserted_row public.project_members%rowtype;
begin
  if auth.uid() is null then
    raise exception 'Authentication is required';
  end if;

  if not public.is_owner_of_organization(p_organization_id) then
    raise exception 'Not authorized to manage project members for this organization';
  end if;

  if not exists (
    select 1
    from public.organization_projects p
    where p.id = p_project_id
      and p.organization_id = p_organization_id
  ) then
    raise exception 'Project not found for organization';
  end if;

  if not exists (
    select 1
    from public.organization_members m
    where m.id = p_organization_member_id
      and m.organization_id = p_organization_id
  ) then
    raise exception 'Organization member not found for organization';
  end if;

  select *
  into existing_active_row
  from public.project_members pm
  where pm.organization_id = p_organization_id
    and pm.project_id = p_project_id
    and pm.organization_member_id = p_organization_member_id
    and pm.is_active = true
  order by pm.created_at asc
  limit 1;

  if existing_active_row.id is not null then
    return query
    select
      existing_active_row.id,
      existing_active_row.organization_id,
      existing_active_row.project_id,
      existing_active_row.organization_member_id,
      existing_active_row.created_by,
      existing_active_row.is_active,
      existing_active_row.removed_at,
      existing_active_row.removed_by,
      existing_active_row.created_at,
      existing_active_row.updated_at;
    return;
  end if;

  with candidate as (
    select pm.id
    from public.project_members pm
    where pm.organization_id = p_organization_id
      and pm.project_id = p_project_id
      and pm.organization_member_id = p_organization_member_id
      and pm.is_active = false
    order by pm.updated_at desc, pm.created_at desc
    limit 1
  )
  update public.project_members pm
  set
    is_active = true,
    removed_at = null,
    removed_by = null
  from candidate
  where pm.id = candidate.id
  returning pm.* into restored_row;

  if restored_row.id is not null then
    return query
    select
      restored_row.id,
      restored_row.organization_id,
      restored_row.project_id,
      restored_row.organization_member_id,
      restored_row.created_by,
      restored_row.is_active,
      restored_row.removed_at,
      restored_row.removed_by,
      restored_row.created_at,
      restored_row.updated_at;
    return;
  end if;

  begin
    insert into public.project_members (
      organization_id,
      project_id,
      organization_member_id,
      created_by
    )
    values (
      p_organization_id,
      p_project_id,
      p_organization_member_id,
      auth.uid()
    )
    returning * into inserted_row;
  exception
    when unique_violation then
      select *
      into inserted_row
      from public.project_members pm
      where pm.organization_id = p_organization_id
        and pm.project_id = p_project_id
        and pm.organization_member_id = p_organization_member_id
        and pm.is_active = true
      order by pm.created_at asc
      limit 1;

      if inserted_row.id is null then
        raise exception 'Active project membership already exists';
      end if;
  end;

  return query
  select
    inserted_row.id,
    inserted_row.organization_id,
    inserted_row.project_id,
    inserted_row.organization_member_id,
    inserted_row.created_by,
    inserted_row.is_active,
    inserted_row.removed_at,
    inserted_row.removed_by,
    inserted_row.created_at,
    inserted_row.updated_at;
end;
$$;


ALTER FUNCTION "public"."add_project_member"("p_organization_id" "uuid", "p_project_id" "uuid", "p_organization_member_id" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."project_purchase_order_assignments" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "project_id" "uuid" NOT NULL,
    "purchase_order_id" "uuid" NOT NULL,
    "organization_member_id" "uuid" NOT NULL,
    "is_active" boolean DEFAULT true NOT NULL,
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL
);

ALTER TABLE ONLY "public"."project_purchase_order_assignments" FORCE ROW LEVEL SECURITY;


ALTER TABLE "public"."project_purchase_order_assignments" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_purchase_order_assignment"("p_organization_id" "uuid", "p_project_id" "uuid", "p_purchase_order_id" "uuid", "p_organization_member_id" "uuid") RETURNS "public"."project_purchase_order_assignments"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  assignment_row public.project_purchase_order_assignments%rowtype;
begin
  if auth.uid() is null then
    raise exception 'Authentication is required';
  end if;

  if not public.has_org_permission(p_organization_id, 'purchase_orders.write') then
    raise exception 'You do not have permission to manage purchase order assignments';
  end if;

  if not exists (
    select 1
    from public.organization_projects p
    where p.id = p_project_id
      and p.organization_id = p_organization_id
  ) then
    raise exception 'Project not found for organization';
  end if;

  insert into public.project_purchase_order_assignments (
    organization_id,
    project_id,
    purchase_order_id,
    organization_member_id,
    is_active,
    created_by
  )
  values (
    p_organization_id,
    p_project_id,
    p_purchase_order_id,
    p_organization_member_id,
    true,
    auth.uid()
  )
  on conflict (project_id, purchase_order_id, organization_member_id)
  do update
  set
    is_active = true,
    updated_at = now()
  returning * into assignment_row;

  return assignment_row;
end;
$$;


ALTER FUNCTION "public"."add_purchase_order_assignment"("p_organization_id" "uuid", "p_project_id" "uuid", "p_purchase_order_id" "uuid", "p_organization_member_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_retention_claim_allocation"("p_retention_claim_id" "uuid", "p_expected_draft_revision" bigint, "p_originating_payment_claim_id" "uuid", "p_allocation_amount" numeric, "p_allocation_sequence" integer DEFAULT NULL::integer, "p_correlation_id" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_claim public.retention_claims%rowtype;
  v_origin public.project_claims%rowtype;
  v_context jsonb;
  v_allocation public.retention_claim_allocations%rowtype;
  v_sequence integer;
begin
  select * into v_claim
  from public.retention_claims claim
  where claim.id = p_retention_claim_id;
  if not found then
    return jsonb_build_object('succeeded', false, 'errorCode', 'claim_not_found');
  end if;

  v_context := private.retention_claim_operation_context(
    v_claim.project_id,
    'retention.claims.create',
    true
  );
  if not coalesce((v_context ->> 'succeeded')::boolean, false) then
    return v_context;
  end if;

  select * into v_claim
  from public.retention_claims claim
  where claim.id = p_retention_claim_id
    and claim.organization_id = (v_context ->> 'organizationId')::uuid
  for update;
  if not found then
    return jsonb_build_object('succeeded', false, 'errorCode', 'claim_not_found');
  end if;
  if v_claim.status <> 'draft' then
    return jsonb_build_object('succeeded', false, 'errorCode', 'claim_not_draft');
  end if;
  if v_claim.draft_revision <> p_expected_draft_revision then
    return jsonb_build_object(
      'succeeded', false,
      'errorCode', 'concurrent_update',
      'currentDraftRevision', v_claim.draft_revision
    );
  end if;
  if p_allocation_amount is null or round(p_allocation_amount, 2) <= 0 then
    return jsonb_build_object(
      'succeeded', false,
      'errorCode', 'invalid_allocation_amount'
    );
  end if;

  select * into v_origin
  from public.project_claims origin
  where origin.id = p_originating_payment_claim_id
    and origin.organization_id = v_claim.organization_id;

  if not found then
    return jsonb_build_object('succeeded', false, 'errorCode', 'origin_not_found');
  end if;
  if v_origin.project_id <> v_claim.project_id then
    return jsonb_build_object(
      'succeeded', false,
      'errorCode', 'cross_project_origin'
    );
  end if;
  if v_origin.status = 'Cancelled' then
    return jsonb_build_object(
      'succeeded', false,
      'errorCode', 'origin_cancelled'
    );
  end if;
  if round(p_allocation_amount, 2) > greatest(v_origin.retention_withheld_amount, 0) then
    return jsonb_build_object(
      'succeeded', false,
      'errorCode', 'invalid_allocation_amount',
      'currentRetentionOwned', greatest(v_origin.retention_withheld_amount, 0)
    );
  end if;
  if exists (
    select 1
    from public.retention_claim_allocations allocation
    where allocation.retention_claim_id = v_claim.id
      and allocation.originating_payment_claim_id = v_origin.id
  ) then
    return jsonb_build_object('succeeded', false, 'errorCode', 'duplicate_origin');
  end if;

  if p_allocation_sequence is null then
    select coalesce(max(allocation.allocation_sequence), 0) + 1
    into v_sequence
    from public.retention_claim_allocations allocation
    where allocation.retention_claim_id = v_claim.id;
  else
    v_sequence := p_allocation_sequence;
  end if;

  if v_sequence <= 0 or exists (
    select 1
    from public.retention_claim_allocations allocation
    where allocation.retention_claim_id = v_claim.id
      and allocation.allocation_sequence = v_sequence
  ) then
    return jsonb_build_object(
      'succeeded', false,
      'errorCode', 'invalid_allocation_order'
    );
  end if;

  insert into public.retention_claim_allocations (
    organization_id,
    project_id,
    retention_claim_id,
    originating_payment_claim_id,
    allocation_sequence,
    allocation_amount,
    draft_origin_state_hash,
    draft_origin_updated_at,
    draft_origin_retention_owned,
    created_by
  )
  values (
    v_claim.organization_id,
    v_claim.project_id,
    v_claim.id,
    v_origin.id,
    v_sequence,
    round(p_allocation_amount, 2),
    private.retention_claim_origin_state_hash(v_origin.id),
    v_origin.updated_at,
    greatest(v_origin.retention_withheld_amount, 0),
    auth.uid()
  )
  returning * into v_allocation;

  update public.retention_claims claim
  set draft_revision = claim.draft_revision + 1
  where claim.id = v_claim.id
  returning * into v_claim;

  perform private.record_retention_claim_event(
    v_claim.organization_id, v_claim.project_id, v_claim.id,
    'allocation_added', 'draft', 'draft', auth.uid(),
    'Retention Claim allocation added.', p_correlation_id,
    jsonb_build_object(
      'allocationId', v_allocation.id,
      'originatingPaymentClaimId', v_origin.id,
      'allocationAmount', v_allocation.allocation_amount,
      'allocationSequence', v_allocation.allocation_sequence,
      'draftRevision', v_claim.draft_revision
    )
  );

  return jsonb_build_object(
    'succeeded', true,
    'errorCode', null,
    'claim', private.retention_claim_header_json(v_claim.id),
    'allocationId', v_allocation.id
  );
end;
$$;


ALTER FUNCTION "public"."add_retention_claim_allocation"("p_retention_claim_id" "uuid", "p_expected_draft_revision" bigint, "p_originating_payment_claim_id" "uuid", "p_allocation_amount" numeric, "p_allocation_sequence" integer, "p_correlation_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_retention_legacy_release_allocation"("p_input" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare c public.retention_legacy_reconciliation_cases%rowtype;
  s public.retention_legacy_release_sources%rowtype; origin public.project_claims%rowtype;
  ctx jsonb; amount numeric; sequence_number integer; source_total numeric;
  origin_total numeric; origin_sequence integer; allocation_id uuid;
begin
  select * into c from public.retention_legacy_reconciliation_cases
  where id=(p_input->>'caseId')::uuid;
  if not found then return jsonb_build_object('succeeded',false,'errorCode','legacy_case_not_found'); end if;
  ctx:=private.retention_phase6_context(c.project_id,'retention.legacy.reconcile',true);
  if not coalesce((ctx->>'succeeded')::boolean,false) then return ctx; end if;
  select * into c from public.retention_legacy_reconciliation_cases where id=c.id for update;
  if c.status not in ('draft','rejected') then
    return jsonb_build_object('succeeded',false,'errorCode','legacy_case_not_editable');
  end if;
  if c.revision<>(p_input->>'expectedRevision')::bigint then
    return jsonb_build_object('succeeded',false,'errorCode','concurrent_update',
      'currentRevision',c.revision);
  end if;
  begin amount:=round((p_input->>'allocationAmount')::numeric,2);
  exception when others then
    return jsonb_build_object('succeeded',false,'errorCode','invalid_allocation_amount');
  end;
  if amount is null or amount<=0 then
    return jsonb_build_object('succeeded',false,'errorCode','invalid_allocation_amount');
  end if;
  select * into s from public.retention_legacy_release_sources
  where id=(p_input->>'sourceId')::uuid and reconciliation_case_id=c.id;
  if not found then return jsonb_build_object('succeeded',false,'errorCode','legacy_source_not_found'); end if;
  select * into origin from public.project_claims
  where id=(p_input->>'originatingPaymentClaimId')::uuid
    and organization_id=c.organization_id and project_id=c.project_id;
  if not found then return jsonb_build_object('succeeded',false,'errorCode','origin_not_found'); end if;
  if origin.status='Cancelled' or greatest(origin.retention_withheld_amount,0)<=0 then
    return jsonb_build_object('succeeded',false,'errorCode',
      case when origin.status='Cancelled' then 'origin_cancelled'
        else 'origin_has_no_retention' end);
  end if;
  origin_sequence:=private.retention_claim_chronological_sequence(c.project_id,origin.id);
  if origin_sequence>s.source_sequence then
    return jsonb_build_object('succeeded',false,'errorCode','origin_after_legacy_release');
  end if;
  if exists(select 1 from public.retention_legacy_release_allocations a
    where a.legacy_release_source_id=s.id
      and a.originating_payment_claim_id=origin.id) then
    return jsonb_build_object('succeeded',false,'errorCode','duplicate_origin');
  end if;
  select round(coalesce(sum(a.allocation_amount),0),2) into source_total
  from public.retention_legacy_release_allocations a
  where a.legacy_release_source_id=s.id;
  if source_total+amount>s.retention_released_amount_snapshot then
    return jsonb_build_object('succeeded',false,'errorCode','source_overallocated',
      'sourceAmount',s.retention_released_amount_snapshot,
      'currentlyAllocated',source_total,'proposedAllocation',amount);
  end if;
  select round(coalesce(sum(a.allocation_amount),0),2) into origin_total
  from public.retention_legacy_release_allocations a
  where a.reconciliation_case_id=c.id and a.originating_payment_claim_id=origin.id;
  if origin_total+amount>greatest(origin.retention_withheld_amount,0) then
    return jsonb_build_object('succeeded',false,'errorCode','origin_overallocated',
      'currentRetentionOwned',greatest(origin.retention_withheld_amount,0),
      'currentlyAllocated',origin_total,'proposedAllocation',amount);
  end if;
  sequence_number:=coalesce((p_input->>'allocationSequence')::integer,(
    select coalesce(max(a.allocation_sequence),0)+1
    from public.retention_legacy_release_allocations a
    where a.legacy_release_source_id=s.id
  ));
  perform set_config('app.retention_phase6_internal_write','true',true);
  insert into public.retention_legacy_release_allocations(
    organization_id,project_id,reconciliation_case_id,legacy_release_source_id,
    originating_payment_claim_id,allocation_sequence,allocation_amount,created_by
  ) values(
    c.organization_id,c.project_id,c.id,s.id,origin.id,sequence_number,amount,auth.uid()
  ) returning id into allocation_id;
  update public.retention_legacy_reconciliation_cases set
    revision=revision+1,updated_at=now() where id=c.id returning * into c;
  perform set_config('app.retention_phase6_internal_write','',true);
  perform private.refresh_retention_legacy_case_totals(c.id);
  perform private.record_retention_legacy_event(
    c.id,'allocation_added',c.status,c.status,
    'Legacy release allocation added.',p_input->>'correlationId',
    jsonb_build_object('allocationId',allocation_id,'sourceId',s.id,
      'originatingPaymentClaimId',origin.id,'allocationAmount',amount));
  return jsonb_build_object('succeeded',true,'errorCode',null,
    'allocationId',allocation_id,'case',private.retention_legacy_case_json(c.id));
exception when unique_violation then
  return jsonb_build_object('succeeded',false,'errorCode','duplicate_origin');
end;
$$;


ALTER FUNCTION "public"."add_retention_legacy_release_allocation"("p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_retention_schedule_origin"("p_input" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_s public.project_retention_release_schedules%rowtype; v_p public.project_claims%rowtype;
  v_context jsonb; v_o public.project_retention_schedule_origins%rowtype; v_seq integer;
begin
  select * into v_s from public.project_retention_release_schedules where id=(p_input->>'scheduleId')::uuid;
  if not found then return jsonb_build_object('succeeded',false,'errorCode','schedule_not_found'); end if;
  v_context:=private.retention_phase4_context(v_s.project_id,'retention.schedules.manage',true);
  if not coalesce((v_context->>'succeeded')::boolean,false) then return v_context; end if;
  select * into v_s from public.project_retention_release_schedules where id=v_s.id for update;
  if v_s.status not in ('draft','scheduled','awaiting_confirmation') then
    return jsonb_build_object('succeeded',false,'errorCode','schedule_immutable');
  end if;
  if v_s.revision<>(p_input->>'expectedRevision')::bigint then
    return jsonb_build_object('succeeded',false,'errorCode','concurrent_update','currentRevision',v_s.revision);
  end if;
  select * into v_p from public.project_claims where id=(p_input->>'originatingPaymentClaimId')::uuid;
  if not found then return jsonb_build_object('succeeded',false,'errorCode','origin_not_found'); end if;
  if v_p.organization_id<>v_s.organization_id or v_p.project_id<>v_s.project_id then
    return jsonb_build_object('succeeded',false,'errorCode','invalid_schedule_scope');
  end if;
  if v_p.status='Cancelled' then return jsonb_build_object('succeeded',false,'errorCode','origin_cancelled'); end if;
  if exists(select 1 from public.project_retention_schedule_origins where schedule_id=v_s.id and originating_payment_claim_id=v_p.id) then
    return jsonb_build_object('succeeded',false,'errorCode','duplicate_schedule_origin');
  end if;
  select coalesce(max(origin_sequence),0)+1 into v_seq
  from public.project_retention_schedule_origins where schedule_id=v_s.id;
  begin
    insert into public.project_retention_schedule_origins(
      organization_id,project_id,schedule_id,originating_payment_claim_id,origin_sequence,
      percentage_bps_override,fixed_amount_override,cap_amount,created_by
    ) values (
      v_s.organization_id,v_s.project_id,v_s.id,v_p.id,coalesce((p_input->>'originSequence')::integer,v_seq),
      (p_input->>'percentageBpsOverride')::integer,(p_input->>'fixedAmountOverride')::numeric,
      (p_input->>'capAmount')::numeric,auth.uid()
    ) returning * into v_o;
  exception when unique_violation then
    return jsonb_build_object('succeeded',false,'errorCode','duplicate_schedule_origin');
  when check_violation then
    return jsonb_build_object('succeeded',false,'errorCode','invalid_schedule_scope');
  end;
  update public.project_retention_release_schedules set revision=revision+1 where id=v_s.id returning * into v_s;
  perform private.record_retention_schedule_event(
    v_s.id,'origin_added',v_s.status,v_s.status,'Schedule origin added.',
    p_input->>'correlationId',jsonb_build_object('originId',v_p.id,'originSequence',v_o.origin_sequence)
  );
  return jsonb_build_object('succeeded',true,'errorCode',null,'schedule',to_jsonb(v_s),'origin',to_jsonb(v_o));
end;
$$;


ALTER FUNCTION "public"."add_retention_schedule_origin"("p_input" "jsonb") OWNER TO "postgres";


