CREATE OR REPLACE FUNCTION "public"."add_task_link"("p_task_id" "uuid", "p_linked_type" "text", "p_linked_id" "uuid", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  actor_user_id uuid := auth.uid();
  task_row public.project_job_todos%rowtype;
  link_row public.task_links%rowtype;
begin
  task_row := public._task_assert_task_access(p_task_id);

  insert into public.task_links (
    organization_id,
    task_id,
    linked_type,
    linked_id,
    created_by,
    metadata
  )
  values (
    task_row.organization_id,
    task_row.id,
    p_linked_type,
    p_linked_id,
    actor_user_id,
    coalesce(p_metadata, '{}'::jsonb)
  )
  on conflict (task_id, linked_type, linked_id)
  do update set metadata = excluded.metadata
  returning * into link_row;

  perform public._write_task_activity(task_row.organization_id, task_row.id, task_row.project_id, actor_user_id, 'source_linked', 'task_links', null, to_jsonb(link_row.linked_id), jsonb_build_object('taskLinkId', link_row.id, 'linkedType', link_row.linked_type));

  return jsonb_build_object(
    'id', link_row.id,
    'organizationId', link_row.organization_id,
    'taskId', link_row.task_id,
    'linkedType', link_row.linked_type,
    'linkedId', link_row.linked_id,
    'createdBy', link_row.created_by,
    'createdAt', link_row.created_at,
    'metadata', link_row.metadata
  );
end;
$$;


ALTER FUNCTION "public"."add_task_link"("p_task_id" "uuid", "p_linked_type" "text", "p_linked_id" "uuid", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."adjust_document_storage_usage"("p_organization_id" "uuid", "p_active_bytes" bigint DEFAULT 0, "p_deleted_bytes" bigint DEFAULT 0, "p_pending_bytes" bigint DEFAULT 0, "p_file_count" bigint DEFAULT 0, "p_folder_count" bigint DEFAULT 0, "p_current_version_count" bigint DEFAULT 0, "p_version_count" bigint DEFAULT 0) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  perform public.ensure_document_storage_usage_row(p_organization_id);

  update public.organization_document_storage_usage usage
  set
    active_bytes = greatest(0, usage.active_bytes + p_active_bytes),
    deleted_bytes = greatest(0, usage.deleted_bytes + p_deleted_bytes),
    pending_bytes = greatest(0, usage.pending_bytes + p_pending_bytes),
    file_count = greatest(0, usage.file_count + p_file_count),
    folder_count = greatest(0, usage.folder_count + p_folder_count),
    current_version_count = greatest(
      0,
      usage.current_version_count + p_current_version_count
    ),
    version_count = greatest(0, usage.version_count + p_version_count),
    historical_version_count = greatest(
      0,
      (usage.version_count + p_version_count)
      - (usage.current_version_count + p_current_version_count)
    )
  where usage.organization_id = p_organization_id;
end;
$$;


ALTER FUNCTION "public"."adjust_document_storage_usage"("p_organization_id" "uuid", "p_active_bytes" bigint, "p_deleted_bytes" bigint, "p_pending_bytes" bigint, "p_file_count" bigint, "p_folder_count" bigint, "p_current_version_count" bigint, "p_version_count" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."adopt_legacy_voided_payment_claim_phase2c"("p_input" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private'
    AS $$
declare
  v_source_revision timestamptz;
  v_normalized_input jsonb;
begin
  begin
    v_source_revision := (p_input->>'sourceOptimisticRevision')::timestamptz;
  exception
    when invalid_datetime_format or datetime_field_overflow then
      raise exception 'The Payment Claim optimistic revision is invalid.'
        using errcode = '22007';
  end;

  if v_source_revision is null then
    raise exception 'The Payment Claim optimistic revision is missing.'
      using errcode = '22007';
  end if;

  v_normalized_input := jsonb_set(
    p_input,
    '{sourceOptimisticRevision}',
    to_jsonb(v_source_revision::text),
    true
  );

  return public.adopt_legacy_voided_payment_claim_phase2c_v1(
    v_normalized_input
  );
end;
$$;


ALTER FUNCTION "public"."adopt_legacy_voided_payment_claim_phase2c"("p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."adopt_legacy_voided_payment_claim_phase2c_v1"("p_input" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private', 'extensions'
    AS $$
declare
  v_org uuid := (p_input->>'organizationId')::uuid;
  v_project uuid := (p_input->>'projectId')::uuid;
  v_claim uuid := (p_input->>'claimId')::uuid;
  v_actor uuid := (p_input->>'adoptedBy')::uuid;
  v_connection uuid := (p_input->>'connectionId')::uuid;
  v_tenant text := p_input->>'tenantId';
  v_invoice_id text := p_input->>'externalDocumentId';
  v_invoice_number text := p_input->>'externalDocumentNumber';
  v_document public.organization_accounting_documents%rowtype;
  v_existing public.organization_accounting_document_revisions%rowtype;
  v_revision public.organization_accounting_document_revisions%rowtype;
  v_observation public.organization_accounting_remote_observations%rowtype;
  v_classification public.organization_accounting_legacy_classifications%rowtype;
  v_claim_row public.project_claims%rowtype;
  v_line jsonb;
  v_line_subtotal bigint;
  v_line_tax bigint;
  v_remote jsonb := p_input->'rawObservation';
begin
  if not private.phase2b_actor_has_push_permission(v_org, v_actor) then
    raise exception 'Payment Claim Push to Xero permission is required.';
  end if;
  if not exists (
    select 1
    from public.organization_accounting_phase2b_settings s
    where s.organization_id = v_org
      and s.initial_payment_claim_push_enabled
  ) then
    raise exception 'Immutable Payment Claim Push to Xero is not enabled.';
  end if;
  if nullif(trim(v_invoice_id), '') is null
    or nullif(trim(v_invoice_number), '') is null
    or nullif(trim(v_tenant), '') is null then
    raise exception 'The legacy Xero identity is incomplete.';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(v_claim::text, 2602));

  select * into v_claim_row
  from public.project_claims
  where id = v_claim
    and organization_id = v_org
    and project_id = v_project
  for update;
  if not found or v_claim_row.status <> 'Submitted' then
    raise exception 'Payment Claim is no longer in an exportable state.';
  end if;
  if v_claim_row.updated_at::text <> p_input->>'sourceOptimisticRevision' then
    raise exception 'The Payment Claim changed before legacy adoption.';
  end if;
  if not exists (
    select 1
    from public.organization_xero_connections c
    where c.id = v_connection
      and c.organization_id = v_org
      and c.status = 'connected'
      and c.tenant_id = v_tenant
      and c.scope @> array['accounting.invoices']::text[]
  ) then
    raise exception 'The Xero connection, tenant, or invoice scope changed.';
  end if;

  select * into v_document
  from public.organization_accounting_documents
  where organization_id = v_org
    and provider = 'xero'
    and local_document_type = 'project_claim'
    and project_claim_id = v_claim
  for update;

  if not found then
    insert into public.organization_accounting_documents(
      organization_id, accounting_connection_id, provider, tenant_id,
      local_document_type, local_document_id, project_claim_id,
      current_version_id, external_document_id, external_document_number,
      raw_external_status, normalized_external_status, export_status,
      amount_exported, tax_exported, currency_code, exported_by, exported_at,
      last_synced_at, last_synced_hash, integration_contract
    ) values (
      v_org, v_connection, 'xero', v_tenant,
      'project_claim', null, v_claim,
      null, v_invoice_id, v_invoice_number,
      'VOIDED', 'voided', 'exported',
      (p_input->>'totalMinor')::numeric / 100,
      (p_input->>'taxMinor')::numeric / 100,
      p_input->>'currencyCode', v_actor,
      nullif(p_input->>'providerUpdatedAt', '')::timestamptz,
      now(), p_input#>>'{commercialSnapshot,currentStateHash}',
      'payment_claim_revision_v1'
    )
    returning * into v_document;
  end if;

  if v_document.accounting_connection_id <> v_connection
    or v_document.tenant_id <> v_tenant
    or v_document.external_document_id <> v_invoice_id
    or v_document.external_document_number <> v_invoice_number then
    raise exception 'The legacy Xero identity changed before adoption.';
  end if;

  if v_document.active_accounting_revision_id is not null then
    select * into v_existing
    from public.organization_accounting_document_revisions
    where id = v_document.active_accounting_revision_id
      and organization_id = v_org
      and accounting_document_id = v_document.id;
    if found
      and v_existing.revision_intent = 'legacy_import'
      and v_existing.external_document_id = v_invoice_id
      and v_existing.external_document_number = v_invoice_number
      and v_existing.tenant_id = v_tenant then
      return jsonb_build_object(
        'accountingDocumentId', v_document.id,
        'accountingRevisionId', v_existing.id,
        'adopted', false
      );
    end if;
    raise exception 'An immutable accounting revision already exists for this Payment Claim.';
  end if;
  if v_document.integration_contract is not null
    and v_document.integration_contract <> 'payment_claim_revision_v1' then
    raise exception 'The accounting document uses an unsupported integration contract.';
  end if;

  if v_remote->>'Type' <> 'ACCREC'
    or v_remote->>'Status' <> 'VOIDED'
    or v_remote->>'InvoiceID' <> v_invoice_id
    or v_remote->>'InvoiceNumber' <> v_invoice_number
    or coalesce((v_remote->>'AmountPaid')::numeric, 0) <> 0
    or coalesce((v_remote->>'AmountCredited')::numeric, 0) <> 0
    or jsonb_array_length(coalesce(v_remote->'Payments', '[]'::jsonb)) <> 0
    or jsonb_array_length(coalesce(v_remote->'CreditNotes', '[]'::jsonb)) <> 0 then
    raise exception 'The predecessor is not a confirmed unsettled VOIDED Sales Invoice.';
  end if;
  if round((v_remote->>'SubTotal')::numeric * 100)::bigint <> (p_input->>'subtotalMinor')::bigint
    or round((v_remote->>'TotalTax')::numeric * 100)::bigint <> (p_input->>'taxMinor')::bigint
    or round((v_remote->>'Total')::numeric * 100)::bigint <> (p_input->>'totalMinor')::bigint
    or (p_input->>'subtotalMinor')::bigint + (p_input->>'taxMinor')::bigint
      <> (p_input->>'totalMinor')::bigint then
    raise exception 'The adopted Xero totals do not reconcile.';
  end if;

  select
    coalesce(sum((value->>'lineAmountMinor')::bigint), 0),
    coalesce(sum((value->>'taxMinor')::bigint), 0)
  into v_line_subtotal, v_line_tax
  from jsonb_array_elements(p_input->'lines');
  if v_line_subtotal <> (p_input->>'subtotalMinor')::bigint
    or v_line_tax <> (p_input->>'taxMinor')::bigint then
    raise exception 'The adopted Xero lines do not reconcile.';
  end if;

  insert into public.organization_accounting_document_revisions(
    organization_id, project_id, accounting_document_id, revision_sequence,
    source_document_type, source_document_id, revision_intent,
    resolution_strategy, previous_revision_id, provider, connection_id,
    tenant_id, number_reservation_id, external_document_id,
    external_document_number, commercial_snapshot, contact_snapshot,
    routing_snapshot, tax_snapshot, attachment_snapshot, payload_snapshot,
    canonical_schema_version, source_evidence_hash, commercial_hash,
    lines_hash, payload_hash, provider_content_hash, pdf_hash,
    currency_code, provider_document_type, requested_provider_status,
    line_amount_type, subtotal_minor, tax_minor, total_minor,
    confirmation_preview_hash, confirmed_by, confirmed_at,
    confirmation_reason, lifecycle_state, succeeded_at, activated_at
  ) values (
    v_org, v_project, v_document.id, 1,
    'project_claim', v_claim, 'legacy_import',
    'legacy_preservation', null, 'xero', v_connection,
    v_tenant, null, v_invoice_id,
    v_invoice_number, p_input->'commercialSnapshot',
    p_input->'contactSnapshot', p_input->'routingSnapshot',
    p_input->'taxSnapshot',
    jsonb_build_object(
      'provenance', 'legacy_adoption',
      'evidenceQuality', p_input->>'evidenceQuality'
    ),
    p_input->'payloadSnapshot', p_input->>'canonicalSchemaVersion',
    p_input->>'sourceEvidenceHash', p_input->>'commercialHash',
    p_input->>'linesHash', p_input->>'payloadHash',
    p_input->>'providerContentHash', null,
    p_input->>'currencyCode', 'ACCREC', 'AUTHORISED',
    p_input->>'lineAmountType',
    (p_input->>'subtotalMinor')::bigint,
    (p_input->>'taxMinor')::bigint,
    (p_input->>'totalMinor')::bigint,
    p_input->>'confirmationPreviewHash', v_actor, now(),
    'Historical Xero invoice adopted from reconstructed current evidence.',
    'succeeded', now(), now()
  )
  returning * into v_revision;

  for v_line in
    select value from jsonb_array_elements(p_input->'lines')
  loop
    insert into public.organization_accounting_revision_lines(
      organization_id, accounting_revision_id, sequence, line_kind,
      source_line_type, source_line_id, originating_payment_claim_id,
      description, quantity, unit_amount_minor, line_amount_minor,
      tax_minor, total_minor, account_snapshot, tax_snapshot,
      tracking_snapshot, source_snapshot
    ) values (
      v_org, v_revision.id, (v_line->>'sequence')::integer,
      v_line->>'lineKind', v_line->>'sourceLineType',
      nullif(v_line->>'sourceLineId', '')::uuid,
      v_claim, v_line->>'description',
      (v_line->>'quantity')::numeric,
      (v_line->>'unitAmountMinor')::bigint,
      (v_line->>'lineAmountMinor')::bigint,
      (v_line->>'taxMinor')::bigint,
      (v_line->>'totalMinor')::bigint,
      v_line->'accountSnapshot', v_line->'taxSnapshot',
      coalesce(v_line->'trackingSnapshot', '{}'::jsonb),
      v_line->'sourceSnapshot'
    );
  end loop;

  perform set_config('app.accounting_phase2a_pointer_write', 'true', true);
  update public.organization_accounting_documents
  set active_accounting_revision_id = v_revision.id,
      integration_contract = 'payment_claim_revision_v1',
      raw_external_status = 'VOIDED',
      normalized_external_status = 'voided',
      export_status = 'exported',
      amount_paid = 0,
      amount_due = (p_input->>'totalMinor')::numeric / 100,
      amount_credited = 0,
      last_status_synced_at = now(),
      last_status_sync_error = 'The linked Xero Sales Invoice is voided or deleted.',
      updated_at = now()
  where id = v_document.id
    and organization_id = v_org
    and active_accounting_revision_id is null;
  if not found then
    raise exception 'Legacy adoption lost its accounting document lock.';
  end if;
  perform set_config('app.accounting_phase2a_pointer_write', '', true);

  select * into v_observation
  from public.record_accounting_remote_observation_phase2a(
    jsonb_build_object(
      'organizationId', v_org,
      'accountingDocumentId', v_document.id,
      'accountingRevisionId', v_revision.id,
      'provider', 'xero',
      'tenantId', v_tenant,
      'externalDocumentId', v_invoice_id,
      'providerUpdatedAt', p_input->>'providerUpdatedAt',
      'rawStatus', 'VOIDED',
      'normalizedStatus', 'voided',
      'normalizedInvoiceStatus', 'voided',
      'normalizedPaymentStatus', 'attention_required',
      'contentHash', p_input->>'providerContentHash',
      'settlementHash', p_input->>'settlementHash',
      'amountPaidMinor', '0',
      'amountDueMinor', p_input->>'totalMinor',
      'amountCreditedMinor', '0',
      'rawObservation', v_remote,
      'correlationId', p_input->>'correlationId'
    )
  );

  insert into public.organization_accounting_legacy_classifications(
    organization_id, accounting_document_id, classification_sequence,
    classification, evidence_snapshot, evidence_hash, classified_by
  ) values (
    v_org, v_document.id, 1, 'authoritative_match',
    jsonb_build_object(
      'provenance', 'legacy_adoption',
      'evidenceQuality', p_input->>'evidenceQuality',
      'externalDocumentId', v_invoice_id,
      'externalDocumentNumber', v_invoice_number,
      'remoteObservationId', v_observation.id
    ),
    p_input->>'sourceEvidenceHash', v_actor
  )
  returning * into v_classification;

  perform set_config('app.accounting_phase2a_pointer_write', 'true', true);
  update public.organization_accounting_documents
  set current_legacy_classification_id = v_classification.id
  where id = v_document.id and organization_id = v_org;
  perform set_config('app.accounting_phase2a_pointer_write', '', true);

  insert into public.organization_accounting_events(
    organization_id, accounting_document_id, accounting_revision_id,
    event_type, actor_user_id, correlation_id, event_evidence
  ) values
    (
      v_org, v_document.id, v_revision.id,
      'legacy_adopted', v_actor, p_input->>'correlationId',
      jsonb_build_object(
        'provenance', 'legacy_adoption',
        'evidenceQuality', p_input->>'evidenceQuality',
        'externalDocumentId', v_invoice_id,
        'externalDocumentNumber', v_invoice_number,
        'remoteObservationId', v_observation.id,
        'xeroPostPerformed', false
      )
    ),
    (
      v_org, v_document.id, v_revision.id,
      'legacy_adoption_activated', v_actor, p_input->>'correlationId',
      jsonb_build_object('activeRevisionId', v_revision.id)
    );

  return jsonb_build_object(
    'accountingDocumentId', v_document.id,
    'accountingRevisionId', v_revision.id,
    'remoteObservationId', v_observation.id,
    'adopted', true
  );
end;
$$;


ALTER FUNCTION "public"."adopt_legacy_voided_payment_claim_phase2c_v1"("p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."adopt_legacy_voided_retention_claim_phase2c"("p_input" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private'
    AS $$
declare
  v_org uuid := (p_input->>'organizationId')::uuid;
  v_project uuid := (p_input->>'projectId')::uuid;
  v_claim uuid := (p_input->>'retentionClaimId')::uuid;
  v_actor uuid := (p_input->>'adoptedBy')::uuid;
  v_connection uuid := (p_input->>'connectionId')::uuid;
  v_tenant text := p_input->>'tenantId';
  v_invoice_id text := p_input->>'externalDocumentId';
  v_invoice_number text := p_input->>'externalDocumentNumber';
  v_claim_row public.retention_claims%rowtype;
  v_document public.organization_accounting_documents%rowtype;
  v_existing public.organization_accounting_document_revisions%rowtype;
  v_revision public.organization_accounting_document_revisions%rowtype;
  v_observation public.organization_accounting_remote_observations%rowtype;
  v_classification public.organization_accounting_legacy_classifications%rowtype;
  v_line jsonb;
  v_line_subtotal bigint;
  v_line_tax bigint;
  v_remote jsonb := p_input->'rawObservation';
begin
  if auth.role() <> 'service_role' then
    raise exception 'Historical Retention Claim adoption is server-only.';
  end if;
  if not private.retention_phase2c_actor_can_push(v_org, v_actor) then
    raise exception 'Retention Claim Push to Xero permission is required.';
  end if;
  if not exists (
    select 1
    from public.organization_accounting_phase2b_settings s
    where s.organization_id = v_org
      and s.retention_claim_immutable_xero_enabled
  ) then
    raise exception 'Immutable Retention Claim Push to Xero is not enabled.';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(v_claim::text, 2631));
  select * into v_claim_row
  from public.retention_claims
  where id = v_claim
    and organization_id = v_org
    and project_id = v_project
  for update;
  if not found or v_claim_row.status <> 'submitted' then
    raise exception 'The Retention Claim is no longer submitted.';
  end if;
  if v_claim_row.submitted_at is distinct from
      (p_input->>'sourceOptimisticRevision')::timestamptz then
    raise exception 'The Retention Claim changed before legacy adoption.';
  end if;
  if not exists (
    select 1
    from public.organization_xero_connections c
    where c.id = v_connection
      and c.organization_id = v_org
      and c.status = 'connected'
      and c.tenant_id = v_tenant
      and c.scope @> array['accounting.invoices']::text[]
  ) then
    raise exception 'The Xero connection, tenant, or invoice scope changed.';
  end if;
  if coalesce((
    public.evaluate_retention_ownership_phase2a(v_org, v_project, '[]'::jsonb)
      ->>'valid'
  )::boolean, false) is not true then
    raise exception 'Retention ownership changed before legacy adoption.';
  end if;

  select * into v_document
  from public.organization_accounting_documents
  where organization_id = v_org
    and provider = 'xero'
    and local_document_type = 'retention_claim'
    and retention_claim_id = v_claim
  for update;
  if not found then
    raise exception 'The historical Retention Claim accounting document is missing.';
  end if;
  if v_document.accounting_connection_id <> v_connection
    or v_document.tenant_id <> v_tenant
    or v_document.external_document_id <> v_invoice_id
    or v_document.external_document_number <> v_invoice_number then
    raise exception 'The historical Retention Claim Xero identity changed.';
  end if;
  if v_document.active_accounting_revision_id is not null then
    select * into v_existing
    from public.organization_accounting_document_revisions
    where id = v_document.active_accounting_revision_id
      and organization_id = v_org
      and accounting_document_id = v_document.id;
    if found
      and v_existing.revision_intent = 'legacy_import'
      and v_existing.external_document_id = v_invoice_id
      and v_existing.external_document_number = v_invoice_number
      and v_existing.tenant_id = v_tenant then
      return jsonb_build_object(
        'accountingDocumentId', v_document.id,
        'accountingRevisionId', v_existing.id,
        'adopted', false
      );
    end if;
    raise exception 'An immutable Retention Claim revision already exists.';
  end if;
  if v_document.integration_contract is not null
    and v_document.integration_contract <> 'retention_claim_revision_v1' then
    raise exception 'The historical accounting document uses an unsupported contract.';
  end if;
  if v_remote->>'Type' <> 'ACCREC'
    or v_remote->>'Status' <> 'VOIDED'
    or v_remote->>'InvoiceID' <> v_invoice_id
    or v_remote->>'InvoiceNumber' <> v_invoice_number
    or coalesce((v_remote->>'AmountPaid')::numeric, 0) <> 0
    or coalesce((v_remote->>'AmountCredited')::numeric, 0) <> 0
    or jsonb_array_length(coalesce(v_remote->'Payments', '[]'::jsonb)) <> 0
    or jsonb_array_length(coalesce(v_remote->'CreditNotes', '[]'::jsonb)) <> 0 then
    raise exception 'The historical predecessor is not a confirmed unsettled VOIDED invoice.';
  end if;
  if round((v_remote->>'SubTotal')::numeric * 100)::bigint
      <> (p_input->>'subtotalMinor')::bigint
    or round((v_remote->>'TotalTax')::numeric * 100)::bigint
      <> (p_input->>'taxMinor')::bigint
    or round((v_remote->>'Total')::numeric * 100)::bigint
      <> (p_input->>'totalMinor')::bigint
    or (p_input->>'subtotalMinor')::bigint
      + (p_input->>'taxMinor')::bigint
      <> (p_input->>'totalMinor')::bigint
    or round(v_claim_row.subtotal_excl_tax * 100)::bigint
      <> (p_input->>'subtotalMinor')::bigint then
    raise exception 'The historical Retention Claim totals do not reconcile.';
  end if;
  select
    coalesce(sum((value->>'lineAmountMinor')::bigint), 0),
    coalesce(sum((value->>'taxMinor')::bigint), 0)
  into v_line_subtotal, v_line_tax
  from jsonb_array_elements(p_input->'lines');
  if v_line_subtotal <> (p_input->>'subtotalMinor')::bigint
    or v_line_tax <> (p_input->>'taxMinor')::bigint then
    raise exception 'The historical Retention Claim lines do not reconcile.';
  end if;

  insert into public.organization_accounting_document_revisions(
    organization_id, project_id, accounting_document_id, revision_sequence,
    source_document_type, source_document_id, revision_intent,
    resolution_strategy, previous_revision_id, provider, connection_id,
    tenant_id, number_reservation_id, external_document_id,
    external_document_number, commercial_snapshot, contact_snapshot,
    routing_snapshot, tax_snapshot, attachment_snapshot, payload_snapshot,
    canonical_schema_version, source_evidence_hash, commercial_hash,
    lines_hash, payload_hash, provider_content_hash, pdf_hash,
    currency_code, provider_document_type, requested_provider_status,
    line_amount_type, subtotal_minor, tax_minor, total_minor,
    confirmation_preview_hash, confirmed_by, confirmed_at,
    confirmation_reason, lifecycle_state, succeeded_at, activated_at
  ) values (
    v_org, v_project, v_document.id, 1,
    'retention_claim', v_claim, 'legacy_import',
    'legacy_preservation', null, 'xero', v_connection,
    v_tenant, null, v_invoice_id, v_invoice_number,
    p_input->'commercialSnapshot', p_input->'contactSnapshot',
    p_input->'routingSnapshot', p_input->'taxSnapshot',
    jsonb_build_object(
      'provenance', 'legacy_adoption',
      'evidenceQuality', p_input->>'evidenceQuality',
      'historicalPdfAvailable', false,
      'historicalPdfFabricated', false
    ),
    p_input->'payloadSnapshot', p_input->>'canonicalSchemaVersion',
    p_input->>'sourceEvidenceHash', p_input->>'commercialHash',
    p_input->>'linesHash', p_input->>'payloadHash',
    p_input->>'providerContentHash', null,
    'NZD', 'ACCREC', 'AUTHORISED', 'Exclusive',
    (p_input->>'subtotalMinor')::bigint,
    (p_input->>'taxMinor')::bigint,
    (p_input->>'totalMinor')::bigint,
    p_input->>'confirmationPreviewHash', v_actor, now(),
    'Historical Retention Claim invoice adopted from reconstructed evidence.',
    'succeeded', now(), now()
  )
  returning * into v_revision;

  for v_line in
    select value from jsonb_array_elements(p_input->'lines')
  loop
    insert into public.organization_accounting_revision_lines(
      organization_id, accounting_revision_id, sequence, line_kind,
      source_line_type, source_line_id, originating_payment_claim_id,
      description, quantity, unit_amount_minor, line_amount_minor,
      tax_minor, total_minor, account_snapshot, tax_snapshot,
      tracking_snapshot, source_snapshot
    ) values (
      v_org, v_revision.id, (v_line->>'sequence')::integer,
      v_line->>'lineKind', v_line->>'sourceLineType',
      nullif(v_line->>'sourceLineId', '')::uuid,
      nullif(v_line->>'originatingPaymentClaimId', '')::uuid,
      v_line->>'description', (v_line->>'quantity')::numeric,
      (v_line->>'unitAmountMinor')::bigint,
      (v_line->>'lineAmountMinor')::bigint,
      (v_line->>'taxMinor')::bigint,
      (v_line->>'totalMinor')::bigint,
      v_line->'accountSnapshot', v_line->'taxSnapshot',
      coalesce(v_line->'trackingSnapshot', '{}'::jsonb),
      v_line->'sourceSnapshot'
    );
  end loop;

  perform set_config('app.accounting_phase2a_pointer_write', 'true', true);
  update public.organization_accounting_documents
  set
    active_accounting_revision_id = v_revision.id,
    integration_contract = 'retention_claim_revision_v1',
    raw_external_status = 'VOIDED',
    normalized_external_status = 'voided',
    export_status = 'exported',
    amount_paid = 0,
    amount_due = (p_input->>'totalMinor')::numeric / 100,
    amount_credited = 0,
    last_status_synced_at = now(),
    last_status_sync_error = null,
    updated_at = now()
  where id = v_document.id
    and organization_id = v_org
    and active_accounting_revision_id is null;
  if not found then
    raise exception 'Legacy Retention Claim adoption lost its document lock.';
  end if;
  perform set_config('app.accounting_phase2a_pointer_write', '', true);

  select * into v_observation
  from public.record_accounting_remote_observation_phase2a(
    jsonb_build_object(
      'organizationId', v_org,
      'accountingDocumentId', v_document.id,
      'accountingRevisionId', v_revision.id,
      'provider', 'xero',
      'tenantId', v_tenant,
      'externalDocumentId', v_invoice_id,
      'providerUpdatedAt', p_input->>'providerUpdatedAt',
      'rawStatus', 'VOIDED',
      'normalizedStatus', 'voided',
      'normalizedInvoiceStatus', 'voided',
      'normalizedPaymentStatus', 'attention_required',
      'contentHash', p_input->>'providerContentHash',
      'settlementHash', p_input->>'settlementHash',
      'amountPaidMinor', '0',
      'amountDueMinor', p_input->>'totalMinor',
      'amountCreditedMinor', '0',
      'rawObservation', v_remote,
      'correlationId', p_input->>'correlationId'
    )
  );
  insert into public.organization_accounting_legacy_classifications(
    organization_id, accounting_document_id, classification_sequence,
    classification, evidence_snapshot, evidence_hash, classified_by
  ) values (
    v_org, v_document.id, 1, 'authoritative_match',
    jsonb_build_object(
      'provenance', 'legacy_adoption',
      'evidenceQuality', p_input->>'evidenceQuality',
      'externalDocumentId', v_invoice_id,
      'externalDocumentNumber', v_invoice_number,
      'remoteObservationId', v_observation.id,
      'historicalPdfFabricated', false
    ),
    p_input->>'sourceEvidenceHash', v_actor
  )
  returning * into v_classification;
  perform set_config('app.accounting_phase2a_pointer_write', 'true', true);
  update public.organization_accounting_documents
  set current_legacy_classification_id = v_classification.id
  where id = v_document.id
    and organization_id = v_org;
  perform set_config('app.accounting_phase2a_pointer_write', '', true);
  insert into public.organization_accounting_events(
    organization_id, accounting_document_id, accounting_revision_id,
    event_type, actor_user_id, correlation_id, event_evidence
  ) values (
    v_org, v_document.id, v_revision.id, 'legacy_adopted',
    v_actor, p_input->>'correlationId',
    jsonb_build_object(
      'externalDocumentId', v_invoice_id,
      'externalDocumentNumber', v_invoice_number,
      'remoteObservationId', v_observation.id,
      'evidenceQuality', p_input->>'evidenceQuality',
      'xeroPostPerformed', false,
      'historicalPdfFabricated', false
    )
  );
  return jsonb_build_object(
    'accountingDocumentId', v_document.id,
    'accountingRevisionId', v_revision.id,
    'remoteObservationId', v_observation.id,
    'adopted', true
  );
end;
$$;


ALTER FUNCTION "public"."adopt_legacy_voided_retention_claim_phase2c"("p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_xero_bill_status_refresh"("p_organization_id" "uuid", "p_document_id" "uuid", "p_expected_tenant_id" "text", "p_expected_external_document_id" "text", "p_raw_external_status" "text", "p_normalized_external_status" "text", "p_amount_paid" numeric, "p_amount_due" numeric, "p_amount_credited" numeric, "p_fully_paid_at" timestamp with time zone, "p_provider_updated_at" timestamp with time zone, "p_synced_at" timestamp with time zone, "p_job_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_document public.organization_accounting_documents%rowtype;
  v_changed boolean;
  v_stale boolean;
  v_message text;
begin
  select *
  into v_document
  from public.organization_accounting_documents
  where id = p_document_id
    and organization_id = p_organization_id
  for update;

  if not found then
    raise exception 'Accounting document not found.';
  end if;
  if v_document.provider <> 'xero'
    or v_document.tenant_id <> trim(p_expected_tenant_id)
    or v_document.external_document_id <> trim(p_expected_external_document_id) then
    raise exception 'Accounting document provider identity does not match.';
  end if;
  if p_normalized_external_status not in (
    'draft', 'awaiting_approval', 'awaiting_payment', 'partially_paid',
    'paid', 'voided', 'deleted', 'unknown'
  ) then
    raise exception 'Normalized accounting status is invalid.';
  end if;

  v_stale := v_document.provider_updated_at is not null
    and p_provider_updated_at is not null
    and p_provider_updated_at < v_document.provider_updated_at;

  if v_stale then
    return jsonb_build_object(
      'applied', false,
      'changed', false,
      'stale', true,
      'normalizedStatus', v_document.normalized_external_status
    );
  end if;

  v_changed := v_document.raw_external_status is distinct from p_raw_external_status
    or v_document.normalized_external_status is distinct from p_normalized_external_status
    or v_document.amount_paid is distinct from p_amount_paid
    or v_document.amount_due is distinct from p_amount_due
    or v_document.amount_credited is distinct from p_amount_credited
    or v_document.fully_paid_at is distinct from p_fully_paid_at;

  update public.organization_accounting_documents
  set raw_external_status = p_raw_external_status,
      normalized_external_status = p_normalized_external_status,
      amount_paid = p_amount_paid,
      amount_due = p_amount_due,
      amount_credited = p_amount_credited,
      fully_paid_at = p_fully_paid_at,
      provider_updated_at = coalesce(p_provider_updated_at, provider_updated_at),
      last_status_synced_at = p_synced_at,
      last_synced_at = p_synced_at,
      last_status_sync_error = null,
      last_error_code = null,
      last_error_message = null,
      updated_at = p_synced_at
  where id = v_document.id;

  if v_changed then
    v_message := case p_normalized_external_status
      when 'paid' then 'Xero Bill paid.'
      when 'partially_paid' then 'Xero Bill partially paid.'
      when 'awaiting_payment' then 'Xero Bill is awaiting payment.'
      when 'awaiting_approval' then 'Xero Bill is awaiting approval.'
      when 'voided' then 'Xero Bill voided.'
      when 'deleted' then 'Xero Bill deleted.'
      else 'Xero Bill status refreshed.'
    end;

    insert into public.supplier_invoice_activity_events (
      organization_id,
      supplier_invoice_id,
      event_type,
      message,
      metadata,
      created_by
    ) values (
      v_document.organization_id,
      v_document.local_document_id,
      'xero_bill_status_refreshed',
      v_message,
      jsonb_build_object(
        'accounting_document_id', v_document.id,
        'job_id', p_job_id,
        'previous_normalized_status', v_document.normalized_external_status,
        'new_normalized_status', p_normalized_external_status,
        'previous_amount_paid', v_document.amount_paid,
        'new_amount_paid', p_amount_paid,
        'previous_amount_due', v_document.amount_due,
        'new_amount_due', p_amount_due,
        'provider_updated_at', p_provider_updated_at
      ),
      v_document.exported_by
    );
  end if;

  return jsonb_build_object(
    'applied', true,
    'changed', v_changed,
    'stale', false,
    'normalizedStatus', p_normalized_external_status
  );
end;
$$;


ALTER FUNCTION "public"."apply_xero_bill_status_refresh"("p_organization_id" "uuid", "p_document_id" "uuid", "p_expected_tenant_id" "text", "p_expected_external_document_id" "text", "p_raw_external_status" "text", "p_normalized_external_status" "text", "p_amount_paid" numeric, "p_amount_due" numeric, "p_amount_credited" numeric, "p_fully_paid_at" timestamp with time zone, "p_provider_updated_at" timestamp with time zone, "p_synced_at" timestamp with time zone, "p_job_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_xero_sales_invoice_payment_to_claim"("p_organization_id" "uuid", "p_document_id" "uuid", "p_project_claim_id" "uuid", "p_accounting_connection_id" "uuid", "p_tenant_id" "text", "p_external_document_id" "text", "p_expected_claim_updated_at" timestamp with time zone, "p_raw_external_status" "text", "p_normalized_external_status" "text", "p_amount_paid" numeric, "p_amount_due" numeric, "p_amount_credited" numeric, "p_fully_paid_at" timestamp with time zone, "p_provider_updated_at" timestamp with time zone, "p_status_synced_at" timestamp with time zone, "p_attention_message" "text", "p_projected_claim_status" "text", "p_projected_paid_amount" numeric) RETURNS TABLE("document_id" "uuid", "claim_id" "uuid", "claim_status" "text", "claim_paid_amount" numeric, "claim_projection_applied" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_document public.organization_accounting_documents%rowtype;
  v_claim public.project_claims%rowtype;
  v_apply_claim_projection boolean := false;
begin
  select d.*
  into v_document
  from public.organization_accounting_documents d
  where d.id = p_document_id
    and d.organization_id = p_organization_id
    and d.provider = 'xero'
    and d.local_document_type = 'project_claim'
    and d.project_claim_id = p_project_claim_id
    and d.accounting_connection_id = p_accounting_connection_id
    and d.tenant_id = p_tenant_id
    and d.external_document_id = p_external_document_id
  for update;

  if not found then
    raise exception 'The accounting document identity changed during status refresh.' using errcode = '40001';
  end if;

  select c.*
  into v_claim
  from public.project_claims c
  where c.id = p_project_claim_id
    and c.organization_id = p_organization_id
  for update;

  if not found then
    raise exception 'The linked Payment Claim identity is invalid.' using errcode = '40001';
  end if;

  if p_expected_claim_updated_at is not null
    and v_claim.updated_at is distinct from p_expected_claim_updated_at then
    raise exception 'The Payment Claim changed while Xero payment status was refreshing.' using errcode = '40001';
  end if;

  if p_amount_paid < 0 or p_amount_due < 0 or p_amount_credited < 0 then
    raise exception 'Xero payment values must be non-negative.';
  end if;

  update public.organization_accounting_documents d
  set
    raw_external_status = p_raw_external_status,
    normalized_external_status = p_normalized_external_status,
    amount_paid = round(p_amount_paid, 2),
    amount_due = round(p_amount_due, 2),
    amount_credited = round(p_amount_credited, 2),
    fully_paid_at = p_fully_paid_at,
    provider_updated_at = coalesce(p_provider_updated_at, d.provider_updated_at),
    last_status_synced_at = p_status_synced_at,
    last_status_sync_error = p_attention_message
  where d.id = v_document.id;

  v_apply_claim_projection :=
    p_attention_message is null
    and v_claim.status in ('Submitted', 'Unpaid', 'Paid', 'Overdue')
    and p_projected_claim_status in ('Unpaid', 'Paid', 'Overdue')
    and p_projected_paid_amount is not null
    and p_projected_paid_amount >= 0;

  if v_apply_claim_projection then
    update public.project_claims c
    set
      status = p_projected_claim_status,
      paid_amount = round(p_projected_paid_amount, 2)
    where c.id = v_claim.id
      and c.organization_id = p_organization_id
      and c.status in ('Submitted', 'Unpaid', 'Paid', 'Overdue');

    select c.* into v_claim
    from public.project_claims c
    where c.id = p_project_claim_id
      and c.organization_id = p_organization_id;
  end if;

  return query
  select
    v_document.id,
    v_claim.id,
    v_claim.status,
    v_claim.paid_amount,
    v_apply_claim_projection;
end;
$$;


ALTER FUNCTION "public"."apply_xero_sales_invoice_payment_to_claim"("p_organization_id" "uuid", "p_document_id" "uuid", "p_project_claim_id" "uuid", "p_accounting_connection_id" "uuid", "p_tenant_id" "text", "p_external_document_id" "text", "p_expected_claim_updated_at" timestamp with time zone, "p_raw_external_status" "text", "p_normalized_external_status" "text", "p_amount_paid" numeric, "p_amount_due" numeric, "p_amount_credited" numeric, "p_fully_paid_at" timestamp with time zone, "p_provider_updated_at" timestamp with time zone, "p_status_synced_at" timestamp with time zone, "p_attention_message" "text", "p_projected_claim_status" "text", "p_projected_paid_amount" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."approve_material_import_row"("p_input" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_snapshot jsonb := p_input #> '{observation_metadata,tax_snapshot}';
begin
  perform public.materials_validate_price_tax_review_state(p_input);
  perform public.materials_validate_price_tax_idempotency(p_input);
  if v_snapshot is not null then
    update public.organization_material_import_rows
    set source_payload = pg_catalog.jsonb_set(
      coalesce(source_payload, '{}'::jsonb),
      '{approvedTaxSnapshot}', v_snapshot, true
    )
    where organization_id = (p_input->>'organization_id')::uuid
      and id = (p_input->>'import_row_id')::uuid;
  end if;
  return public.approve_material_import_row_without_tax_idempotency(p_input);
end;
$$;


ALTER FUNCTION "public"."approve_material_import_row"("p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."approve_material_import_row_without_tax_idempotency"("p_input" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_org uuid := (p_input->>'organization_id')::uuid;
  v_actor uuid;
  v_result jsonb;
  v_row public.organization_material_import_rows%rowtype;
  v_material public.organization_materials%rowtype;
  v_product public.organization_material_supplier_products%rowtype;
  v_price public.organization_material_supplier_prices%rowtype;
  v_conversion_input jsonb := p_input->'unit_conversion';
  v_current public.organization_material_supplier_product_unit_conversions%rowtype;
  v_conversion public.organization_material_supplier_product_unit_conversions%rowtype;
  v_supplier_quantity numeric;
  v_material_quantity numeric;
  v_expected_cost numeric;
  v_effective_from timestamptz := statement_timestamp();
begin
  v_actor := public.materials_phase1f_require_writer(v_org);
  v_result := public.approve_material_import_row_without_unit_conversion(p_input);

  select * into v_row
  from public.organization_material_import_rows
  where organization_id = v_org and id = (p_input->>'import_row_id')::uuid
  for update;

  if v_conversion_input is null then
    return v_result || pg_catalog.jsonb_build_object('unit_conversion_id', v_row.approved_unit_conversion_id);
  end if;
  if (v_result->>'idempotent_replay')::boolean and v_row.approved_unit_conversion_id is null then
    perform public.materials_phase1f_error('idempotency_conflict');
  end if;
  if v_row.approved_unit_conversion_id is not null then
    return v_result || pg_catalog.jsonb_build_object(
      'unit_conversion_id', v_row.approved_unit_conversion_id,
      'reused_conversion', true
    );
  end if;

  select * into v_product
  from public.organization_material_supplier_products
  where organization_id = v_org and id = (v_result->>'supplier_product_id')::uuid
  for update;
  select * into v_material
  from public.organization_materials
  where organization_id = v_org and id = (v_result->>'material_id')::uuid;
  select * into v_price
  from public.organization_material_supplier_prices
  where organization_id = v_org and id = (v_result->>'price_id')::uuid;

  v_supplier_quantity := (v_conversion_input->>'supplier_quantity')::numeric;
  v_material_quantity := (v_conversion_input->>'material_quantity')::numeric;
  if v_supplier_quantity is null or v_supplier_quantity <= 0
    or v_material_quantity is null or v_material_quantity <= 0 then
    perform public.materials_phase1f_error('invalid_unit_conversion');
  end if;
  if lower(regexp_replace(btrim(v_conversion_input->>'supplier_unit'), '\s+', ' ', 'g'))
      <> v_product.normalized_supplier_unit
    or lower(regexp_replace(btrim(v_conversion_input->>'material_unit'), '\s+', ' ', 'g'))
      <> lower(regexp_replace(btrim(v_material.default_unit), '\s+', ' ', 'g')) then
    perform public.materials_phase1f_error('invalid_unit_conversion');
  end if;
  v_expected_cost := v_price.unit_cost * v_supplier_quantity / v_material_quantity;
  if abs(v_expected_cost - (v_conversion_input->>'converted_unit_cost')::numeric)
      > greatest(0.000001, abs(v_expected_cost) * 0.0001) then
    perform public.materials_phase1f_error('invalid_unit_conversion');
  end if;

  select * into v_current
  from public.organization_material_supplier_product_unit_conversions
  where organization_id = v_org
    and supplier_product_id = v_product.id
    and normalized_supplier_unit = v_product.normalized_supplier_unit
    and normalized_material_unit = lower(regexp_replace(btrim(v_material.default_unit), '\s+', ' ', 'g'))
    and effective_to is null
  for update;

  if v_current.id is not null
    and v_current.supplier_quantity = v_supplier_quantity
    and v_current.material_quantity = v_material_quantity then
    v_conversion := v_current;
  else
    if v_current.id is not null then
      update public.organization_material_supplier_product_unit_conversions
      set effective_to = v_effective_from
      where organization_id = v_org and id = v_current.id;
    end if;
    insert into public.organization_material_supplier_product_unit_conversions (
      organization_id, supplier_product_id, supplier_unit, material_unit,
      supplier_quantity, material_quantity, source, contract_version,
      proposal_metadata, source_import_row_id, confirmed_by, confirmed_at,
      effective_from, supersedes_conversion_id
    ) values (
      v_org, v_product.id, v_product.supplier_unit, v_material.default_unit,
      v_supplier_quantity, v_material_quantity,
      coalesce(v_conversion_input->>'source', 'user_confirmed_ai'),
      coalesce(v_conversion_input->>'contract_version', 'material_unit_conversion_v1'),
      coalesce(v_conversion_input->'proposal_metadata', '{}'::jsonb),
      v_row.id, v_actor, v_effective_from, v_effective_from, v_current.id
    ) returning * into v_conversion;
  end if;

  update public.organization_material_import_rows
  set approved_unit_conversion_id = v_conversion.id
  where organization_id = v_org and id = v_row.id;

  return v_result || pg_catalog.jsonb_build_object(
    'unit_conversion_id', v_conversion.id,
    'reused_conversion', v_conversion.id = v_current.id
  );
end;
$$;


ALTER FUNCTION "public"."approve_material_import_row_without_tax_idempotency"("p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."approve_material_import_row_without_unit_conversion"("p_input" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_org uuid := (p_input->>'organization_id')::uuid;
  v_actor uuid;
  v_row public.organization_material_import_rows%rowtype;
  v_batch public.organization_material_import_batches%rowtype;
  v_product public.organization_material_supplier_products%rowtype;
  v_material_id uuid := (p_input->>'material_id')::uuid;
  v_product_id uuid := (p_input->>'supplier_product_id')::uuid;
  v_price_result jsonb;
  v_price_id uuid;
  v_name text;
begin
  v_actor := public.materials_phase1f_require_writer(v_org);

  select * into v_row
  from public.organization_material_import_rows
  where organization_id = v_org and id = (p_input->>'import_row_id')::uuid
  for update;
  if not found then
    perform public.materials_phase1f_error('import_row_not_found');
  end if;

  if v_row.status = 'approved' then
    if v_row.approved_supplier_product_id is not null and v_row.approved_supplier_price_id is not null then
      return pg_catalog.jsonb_build_object(
        'material_id', v_row.matched_material_id,
        'supplier_product_id', v_row.approved_supplier_product_id,
        'price_id', v_row.approved_supplier_price_id,
        'idempotent_replay', true
      );
    end if;
    perform public.materials_phase1f_error('import_row_already_approved');
  end if;

  select * into v_batch
  from public.organization_material_import_batches
  where organization_id = v_org and id = v_row.import_batch_id
  for update;
  if not found then
    perform public.materials_phase1f_error('organization_mismatch');
  end if;
  if v_batch.supplier_id is null then
    perform public.materials_phase1f_error('supplier_not_found');
  end if;

  if v_material_id is null then
    v_name := pg_catalog.btrim(coalesce(p_input->>'material_name', v_row.reviewed_name, v_row.extracted_name));
    if v_name is null or v_name = '' then
      perform public.materials_phase1f_error('material_name_required');
    end if;
    begin
      insert into public.organization_materials (
        organization_id, created_by, name, normalized_name, description,
        default_unit, metadata, is_active
      ) values (
        v_org, v_actor, v_name,
        pg_catalog.lower(pg_catalog.regexp_replace(v_name, '\s+', ' ', 'g')),
        coalesce(p_input->>'material_description', v_row.reviewed_description, v_row.extracted_description),
        coalesce(nullif(pg_catalog.btrim(p_input->>'material_unit'), ''), v_row.reviewed_unit, v_row.extracted_unit, 'ea'),
        pg_catalog.jsonb_build_object('created_from_import_row_id', v_row.id), true
      ) returning id into v_material_id;
    exception when unique_violation then
      perform public.materials_phase1f_error('identity_conflict');
    end;
  elsif not exists (select 1 from public.organization_materials where organization_id = v_org and id = v_material_id) then
    perform public.materials_phase1f_error('material_not_found');
  end if;

  if v_product_id is not null then
    select * into v_product
    from public.organization_material_supplier_products
    where organization_id = v_org and id = v_product_id
    for update;
    if not found then
      perform public.materials_phase1f_error('supplier_product_not_found');
    end if;
    if v_product.material_id <> v_material_id or v_product.supplier_id <> v_batch.supplier_id then
      perform public.materials_phase1f_error('organization_mismatch');
    end if;
  else
    begin
      insert into public.organization_material_supplier_products (
        organization_id, material_id, supplier_id, supplier_sku,
        supplier_description, supplier_unit, identity_variant, identity_status,
        created_source, created_by, updated_by, metadata
      ) values (
        v_org, v_material_id, v_batch.supplier_id,
        nullif(pg_catalog.btrim(coalesce(p_input->>'supplier_sku', v_row.reviewed_supplier_sku, v_row.supplier_sku)), ''),
        nullif(pg_catalog.btrim(coalesce(p_input->>'supplier_description', v_row.reviewed_supplier_description, v_row.supplier_description)), ''),
        coalesce(nullif(pg_catalog.btrim(p_input->>'supplier_unit'), ''), v_row.reviewed_unit, v_row.extracted_unit, 'ea'),
        coalesce(nullif(pg_catalog.btrim(p_input->>'identity_variant'), ''), 'default'),
        'confirmed', 'import', v_actor, v_actor,
        pg_catalog.jsonb_build_object('created_from_import_row_id', v_row.id)
      ) returning * into v_product;
    exception when unique_violation then
      perform public.materials_phase1f_error('identity_conflict');
    when check_violation then
      perform public.materials_phase1f_error('identity_required');
    end;
    v_product_id := v_product.id;
    insert into public.organization_material_supplier_product_assignments (
      organization_id, supplier_product_id, previous_material_id, new_material_id,
      reason, source_import_row_id, created_by, metadata
    ) values (
      v_org, v_product.id, null, v_material_id,
      'Initial Supplier Product assignment from import approval.', v_row.id,
      v_actor, pg_catalog.jsonb_build_object('operation', 'phase1f_import_approval')
    );
  end if;

  v_price_result := public.materials_phase1f_add_price_internal(
    v_org, v_product_id,
    coalesce((p_input->>'unit_cost')::numeric, v_row.reviewed_unit_cost, v_row.extracted_unit_cost),
    coalesce(p_input->>'currency', v_row.reviewed_currency, v_row.extracted_currency, 'NZD'),
    coalesce((p_input->>'effective_from')::timestamptz, statement_timestamp()),
    p_input ? 'effective_from', 'import',
    coalesce(p_input->>'idempotency_key', 'import-row:' || v_row.id::text),
    v_batch.id, v_row.id,
    pg_catalog.jsonb_build_object('import_row_id', v_row.id, 'import_batch_id', v_batch.id)
  );
  v_price_id := (v_price_result->>'price_id')::uuid;

  update public.organization_material_import_rows
  set matched_material_id = v_material_id,
      action = case when (p_input->>'material_id') is null then 'create_material' else 'match_material' end,
      status = 'approved',
      reviewed_name = coalesce(p_input->>'material_name', reviewed_name, extracted_name),
      reviewed_description = coalesce(p_input->>'material_description', reviewed_description, extracted_description),
      reviewed_unit = coalesce(p_input->>'material_unit', reviewed_unit, extracted_unit),
      reviewed_unit_cost = coalesce((p_input->>'unit_cost')::numeric, reviewed_unit_cost, extracted_unit_cost),
      reviewed_currency = coalesce(p_input->>'currency', reviewed_currency, extracted_currency, 'NZD'),
      reviewed_by = v_actor,
      reviewed_at = statement_timestamp(),
      approved_supplier_product_id = v_product_id,
      approved_supplier_price_id = v_price_id
  where organization_id = v_org and id = v_row.id;

  update public.organization_material_import_batches
  set rows_approved = (
        select pg_catalog.count(*)::integer
        from public.organization_material_import_rows
        where organization_id = v_org and import_batch_id = v_batch.id and status = 'approved'
      ),
      rows_rejected = (
        select pg_catalog.count(*)::integer
        from public.organization_material_import_rows
        where organization_id = v_org and import_batch_id = v_batch.id and status = 'rejected'
      ),
      status = case
        when not exists (
          select 1 from public.organization_material_import_rows
          where organization_id = v_org and import_batch_id = v_batch.id and status = 'pending_review'
        ) then 'approved'
        else 'partially_approved'
      end
  where organization_id = v_org and id = v_batch.id;

  return pg_catalog.jsonb_build_object(
    'material_id', v_material_id,
    'supplier_product_id', v_product_id,
    'price_id', v_price_id,
    'idempotent_replay', false
  );
end;
$$;


ALTER FUNCTION "public"."approve_material_import_row_without_unit_conversion"("p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."approve_retention_legacy_reconciliation_case"("p_input" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare c public.retention_legacy_reconciliation_cases%rowtype; ctx jsonb;
  validation jsonb; approval_reason text; affected_origins uuid[];
begin
  select * into c from public.retention_legacy_reconciliation_cases
  where id=(p_input->>'caseId')::uuid;
  if not found then return jsonb_build_object('succeeded',false,'errorCode','legacy_case_not_found'); end if;
  ctx:=private.retention_phase6_context(c.project_id,'retention.legacy.approve',true);
  if not coalesce((ctx->>'succeeded')::boolean,false) then
    return case when ctx->>'errorCode'='permission_denied'
      then jsonb_build_object('succeeded',false,'errorCode','legacy_approval_permission_required')
      else ctx end;
  end if;
  select * into c from public.retention_legacy_reconciliation_cases where id=c.id for update;
  if c.status<>'in_review' then
    return jsonb_build_object('succeeded',false,'errorCode','invalid_legacy_transition');
  end if;
  if c.revision<>(p_input->>'expectedRevision')::bigint then
    return jsonb_build_object('succeeded',false,'errorCode','concurrent_update',
      'currentRevision',c.revision);
  end if;
  approval_reason:=nullif(trim(coalesce(p_input->>'approvalReason','')),'');
  if approval_reason is null then
    return jsonb_build_object('succeeded',false,'errorCode','approval_reason_required');
  end if;
  validation:=private.validate_retention_legacy_case(c.id);
  if not coalesce((validation->>'succeeded')::boolean,false) then
    perform private.record_retention_legacy_event(
      c.id,'stale_state_rejected',c.status,c.status,
      validation->>'errorCode',p_input->>'correlationId',validation);
    return validation;
  end if;
  perform set_config('app.retention_phase6_internal_write','true',true);
  update public.retention_legacy_release_allocations set
    approved_by=auth.uid(),approved_at=now(),updated_at=now()
  where reconciliation_case_id=c.id;
  update public.retention_legacy_reconciliation_cases set
    status='approved',approved_by=auth.uid(),approved_at=now(),
    revision=revision+1,updated_at=now()
  where id=c.id returning * into c;
  perform set_config('app.retention_phase6_internal_write','',true);
  perform private.record_retention_legacy_event(
    c.id,'reconciliation_approved','in_review','approved',approval_reason,
    p_input->>'correlationId',jsonb_build_object(
      'validation',validation,'createsXeroInvoice',false,
      'modifiesPaymentClaims',false));
  select array_agg(distinct a.originating_payment_claim_id
    order by a.originating_payment_claim_id) into affected_origins
  from public.retention_legacy_release_allocations a
  where a.reconciliation_case_id=c.id;
  perform private.evaluate_retention_variance_project(
    c.project_id,p_input->>'correlationId',affected_origins);
  return jsonb_build_object('succeeded',true,'errorCode',null,
    'availabilityRestored',false,'xeroDocumentCreated',false,
    'case',private.retention_legacy_case_json(c.id),
    'retentionPosition',public.get_project_retention_position_summary(c.project_id));
end;
$$;


ALTER FUNCTION "public"."approve_retention_legacy_reconciliation_case"("p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."approve_supplier_invoice_commercially"("p_organization_id" "uuid", "p_supplier_invoice_id" "uuid", "p_expected_finance_hash" "text", "p_accepted_variances" "jsonb" DEFAULT '[]'::"jsonb", "p_no_po_reason" "text" DEFAULT NULL::"text", "p_no_po_explanation" "text" DEFAULT NULL::"text", "p_approval_note" "text" DEFAULT ''::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_invoice public.supplier_invoices%rowtype;
  v_hash text;
  v_approval_id uuid;
  v_line_count integer;
  v_allocation_count integer;
  v_allocated_total numeric;
  v_has_po boolean;
  v_invalid_count integer;
begin
  if auth.uid() is null
    or not public.has_org_permission(p_organization_id, 'supplier_invoices.accounts_approve') then
    raise exception 'You do not have permission to commercially approve supplier invoices.';
  end if;

  select * into v_invoice
  from public.supplier_invoices
  where id = p_supplier_invoice_id
    and organization_id = p_organization_id
  for update;

  if not found then
    raise exception 'Supplier invoice not found.';
  end if;

  if v_invoice.supplier_id is null then
    raise exception 'Select a supplier before commercial approval.';
  end if;
  if char_length(public.normalize_supplier_invoice_number(coalesce(v_invoice.invoice_number, ''))) = 0 then
    raise exception 'Enter an invoice number before commercial approval.';
  end if;
  if v_invoice.invoice_date is null then
    raise exception 'Enter an invoice date before commercial approval.';
  end if;

  if exists (
    select 1
    from public.supplier_invoices other
    where other.organization_id = p_organization_id
      and other.supplier_id = v_invoice.supplier_id
      and other.id <> v_invoice.id
      and public.normalize_supplier_invoice_number(other.invoice_number)
        = public.normalize_supplier_invoice_number(v_invoice.invoice_number)
  ) then
    raise exception 'Another invoice for this supplier uses the same invoice number.';
  end if;

  select count(*) into v_line_count
  from public.supplier_invoice_lines
  where supplier_invoice_id = v_invoice.id;

  if v_line_count = 0 then
    raise exception 'Add at least one invoice line before commercial approval.';
  end if;

  select count(*), coalesce(sum(a.allocated_amount), 0), bool_or(a.purchase_order_id is not null)
  into v_allocation_count, v_allocated_total, v_has_po
  from public.supplier_invoice_line_allocations a
  where a.supplier_invoice_id = v_invoice.id;

  if v_allocation_count <> v_line_count then
    raise exception 'Every invoice line must have exactly one active allocation.';
  end if;
  if abs(v_allocated_total - v_invoice.subtotal) > 0.01
    and abs(v_allocated_total - v_invoice.total) > 0.01 then
    raise exception 'Allocated amounts do not reconcile to the invoice.';
  end if;

  select count(*) into v_invalid_count
  from public.supplier_invoice_line_allocations a
  left join public.organization_tradesstack_accounting_mappings legacy_mapping
    on legacy_mapping.id = a.accounting_mapping_id
    and legacy_mapping.organization_id = p_organization_id
    and legacy_mapping.is_active = true
  left join public.organization_accounting_route_mappings route_mapping
    on route_mapping.id = a.accounting_route_mapping_id
    and route_mapping.organization_id = p_organization_id
    and route_mapping.accounting_route = 'supplier_bill_expense'
    and route_mapping.is_active = true
    and (route_mapping.project_id is null or route_mapping.project_id is not distinct from a.project_id)
  left join public.organization_cost_codes account
    on account.id = a.organization_cost_code_id
    and account.organization_id = p_organization_id
    and account.is_active = true
  left join public.organization_accounting_tax_rates t
    on t.id = a.accounting_tax_rate_id
    and t.organization_id = p_organization_id
    and t.is_active = true
  where a.supplier_invoice_id = v_invoice.id
    and (
      a.approval_status <> 'approved'
      or account.id is null
      or not (
        (a.accounting_route = 'supplier_bill_expense'
          and (
            (a.account_override_organization_cost_code_id = account.id)
            or (route_mapping.id is not null
              and route_mapping.organization_cost_code_id = account.id)
          ))
        or (a.accounting_mapping_id is not null and legacy_mapping.id is not null)
      )
      or a.tax_resolution_status = 'unresolved'
      or (
        a.tax_resolution_status = 'not_applicable'
        and exists (
          select 1 from public.supplier_invoice_lines tax_line
          where tax_line.id = a.supplier_invoice_line_id
            and tax_line.tax_amount > 0.01
        )
      )
      or (a.tax_resolution_status = 'resolved' and t.id is null)
      or (a.purchase_order_id is null and char_length(trim(coalesce(a.approval_notes, ''))) = 0)
    );

  if v_invalid_count > 0 then
    raise exception 'Every allocation must be approved with active accounting and tax mappings.';
  end if;

  if exists (
    select 1
    from public.supplier_invoice_line_allocations a
    join public.project_purchase_orders po on po.id = a.purchase_order_id
    where a.supplier_invoice_id = v_invoice.id
      and po.supplier_id is distinct from v_invoice.supplier_id
  ) then
    raise exception 'The invoice supplier does not match one or more purchase orders.';
  end if;

  if coalesce(v_has_po, false) = false then
    if p_no_po_reason not in (
      'utilities', 'insurance', 'emergency_purchase',
      'professional_service', 'approved_overhead', 'other'
    ) then
      raise exception 'Select a valid no-PO reason.';
    end if;
    if p_no_po_reason = 'other'
      and char_length(trim(coalesce(p_no_po_explanation, ''))) = 0 then
      raise exception 'Explain the no-PO reason.';
    end if;
  end if;

  if exists (
    select 1
    from public.supplier_invoice_line_allocations current_a
    join public.project_purchase_order_line_items po_line
      on po_line.id = current_a.purchase_order_line_item_id
    left join lateral (
      select
        coalesce(sum(snapshot.quantity), 0) as approved_quantity,
        coalesce(sum(snapshot.amount), 0) as approved_amount
      from public.supplier_invoice_commercial_line_snapshots snapshot
      join public.supplier_invoice_commercial_approvals approval
        on approval.id = snapshot.commercial_approval_id
      where snapshot.purchase_order_line_item_id = current_a.purchase_order_line_item_id
        and snapshot.supplier_invoice_id <> v_invoice.id
        and approval.status = 'approved'
    ) history on true
    left join lateral (
      select coalesce(sum(release_line.released_amount), 0) as released_amount
      from public.purchase_order_commitment_release_lines release_line
      where release_line.purchase_order_line_item_id = current_a.purchase_order_line_item_id
    ) released on true
    where current_a.supplier_invoice_id = v_invoice.id
      and (
        history.approved_quantity + coalesce(current_a.allocated_quantity, 0) > po_line.quantity + 0.001
        or history.approved_amount + released.released_amount + current_a.allocated_amount
          > po_line.total + 0.01
      )
  ) then
    raise exception 'Commercial approval is blocked because the invoice would over-invoice a purchase order line.';
  end if;

  if exists (
    select 1
    from public.supplier_invoice_line_allocations current_a
    join public.supplier_invoice_lines invoice_line
      on invoice_line.id = current_a.supplier_invoice_line_id
    join public.project_purchase_order_line_items po_line
      on po_line.id = current_a.purchase_order_line_item_id
    where current_a.supplier_invoice_id = v_invoice.id
      and abs(invoice_line.unit_price - po_line.rate) > 0.0001
      and not exists (
        select 1
        from jsonb_array_elements(coalesce(p_accepted_variances, '[]'::jsonb)) accepted
        where accepted ->> 'type' = 'rate_variance'
          and accepted ->> 'purchaseOrderLineItemId' = po_line.id::text
          and char_length(trim(coalesce(accepted ->> 'note', ''))) > 0
      )
  ) then
    raise exception 'Accept and explain every rate variance before commercial approval.';
  end if;

  if exists (
    select 1
    from public.supplier_invoice_line_allocations current_a
    join public.project_purchase_order_line_items po_line
      on po_line.id = current_a.purchase_order_line_item_id
    left join lateral (
      select coalesce(sum(snapshot.quantity), 0) as approved_quantity
      from public.supplier_invoice_commercial_line_snapshots snapshot
      join public.supplier_invoice_commercial_approvals approval
        on approval.id = snapshot.commercial_approval_id
      where snapshot.purchase_order_line_item_id = current_a.purchase_order_line_item_id
        and snapshot.supplier_invoice_id <> v_invoice.id
        and approval.status = 'approved'
    ) history on true
    where current_a.supplier_invoice_id = v_invoice.id
      and coalesce(current_a.allocated_quantity, 0) > 0
      and coalesce(current_a.allocated_quantity, 0)
        < po_line.quantity - history.approved_quantity - 0.001
      and not exists (
        select 1
        from jsonb_array_elements(coalesce(p_accepted_variances, '[]'::jsonb)) accepted
        where accepted ->> 'type' = 'quantity_variance'
          and accepted ->> 'purchaseOrderLineItemId' = po_line.id::text
          and char_length(trim(coalesce(accepted ->> 'note', ''))) > 0
      )
  ) then
    raise exception 'Accept and explain every partial quantity variance before commercial approval.';
  end if;

  if exists (
    select 1
    from public.supplier_invoice_line_allocations current_a
    join public.supplier_invoice_lines invoice_line
      on invoice_line.id = current_a.supplier_invoice_line_id
    join public.project_purchase_order_line_items po_line
      on po_line.id = current_a.purchase_order_line_item_id
    where current_a.supplier_invoice_id = v_invoice.id
      and abs(
        current_a.allocated_amount
        - round(coalesce(current_a.allocated_quantity, invoice_line.quantity, 0) * po_line.rate, 2)
      ) > 0.01
      and not exists (
        select 1
        from jsonb_array_elements(coalesce(p_accepted_variances, '[]'::jsonb)) accepted
        where accepted ->> 'type' = 'value_variance'
          and accepted ->> 'purchaseOrderLineItemId' = po_line.id::text
          and char_length(trim(coalesce(accepted ->> 'note', ''))) > 0
      )
  ) then
    raise exception 'Accept and explain every purchase order line value variance before commercial approval.';
  end if;

  if exists (
    select 1
    from public.supplier_invoices other
    where other.organization_id = p_organization_id
      and other.supplier_id = v_invoice.supplier_id
      and other.id <> v_invoice.id
      and other.invoice_date is not distinct from v_invoice.invoice_date
      and abs(other.total - v_invoice.total) <= 0.01
      and public.normalize_supplier_invoice_number(other.invoice_number)
        <> public.normalize_supplier_invoice_number(v_invoice.invoice_number)
  )
  and not exists (
    select 1
    from jsonb_array_elements(coalesce(p_accepted_variances, '[]'::jsonb)) accepted
    where accepted ->> 'type' = 'duplicate_invoice'
      and char_length(trim(coalesce(accepted ->> 'note', ''))) > 0
  ) then
    raise exception 'Review and explain the likely duplicate invoice warning before commercial approval.';
  end if;

  v_hash := public.supplier_invoice_finance_version_hash(v_invoice.id);
  if v_hash is null or v_hash <> p_expected_finance_hash then
    raise exception 'The invoice changed while it was being reviewed. Refresh and review it again.';
  end if;

  perform public.invalidate_supplier_invoice_commercial_approval(
    v_invoice.id,
    'Superseded by a newer commercial approval.',
    'commercial_approval',
    auth.uid()
  );

  insert into public.supplier_invoice_commercial_approvals (
    organization_id,
    supplier_invoice_id,
    status,
    finance_version_hash,
    supplier_id,
    normalized_invoice_number,
    invoice_total,
    invoice_tax_total,
    currency,
    accepted_variances,
    no_po_reason,
    no_po_explanation,
    approval_note,
    reviewed_by
  )
  values (
    p_organization_id,
    v_invoice.id,
    'approved',
    v_hash,
    v_invoice.supplier_id,
    public.normalize_supplier_invoice_number(v_invoice.invoice_number),
    v_invoice.total,
    v_invoice.tax_total,
    v_invoice.currency,
    coalesce(p_accepted_variances, '[]'::jsonb),
    case when coalesce(v_has_po, false) then null else p_no_po_reason end,
    case when coalesce(v_has_po, false) then null else nullif(trim(p_no_po_explanation), '') end,
    coalesce(p_approval_note, ''),
    auth.uid()
  )
  returning id into v_approval_id;

  insert into public.supplier_invoice_commercial_line_snapshots (
    organization_id,
    commercial_approval_id,
    supplier_invoice_id,
    supplier_invoice_line_id,
    allocation_id,
    purchase_order_id,
    purchase_order_line_item_id,
    project_id,
    accounting_mapping_id,
    accounting_route,
    accounting_route_mapping_id,
    organization_cost_code_id,
    account_override_organization_cost_code_id,
    accounting_tax_rate_id,
    description,
    quantity,
    unit_rate,
    amount,
    tax_amount,
    tax_resolution_status
  )
  select
    p_organization_id,
    v_approval_id,
    v_invoice.id,
    l.id,
    a.id,
    a.purchase_order_id,
    a.purchase_order_line_item_id,
    a.project_id,
    a.accounting_mapping_id,
    a.accounting_route,
    a.accounting_route_mapping_id,
    a.organization_cost_code_id,
    a.account_override_organization_cost_code_id,
    a.accounting_tax_rate_id,
    l.description,
    coalesce(a.allocated_quantity, l.quantity, 0),
    l.unit_price,
    a.allocated_amount,
    l.tax_amount,
    a.tax_resolution_status
  from public.supplier_invoice_lines l
  join public.supplier_invoice_line_allocations a
    on a.supplier_invoice_line_id = l.id
    and a.supplier_invoice_id = v_invoice.id
  where l.supplier_invoice_id = v_invoice.id;

  insert into public.supplier_invoice_commercial_variances (
    organization_id,
    commercial_approval_id,
    supplier_invoice_id,
    variance_key,
    variance_type,
    severity,
    purchase_order_line_item_id,
    expected_value,
    actual_value,
    variance_amount,
    accepted_by,
    explanation
  )
  select
    p_organization_id,
    v_approval_id,
    v_invoice.id,
    accepted ->> 'key',
    accepted ->> 'type',
    'warning',
    nullif(accepted ->> 'purchaseOrderLineItemId', '')::uuid,
    accepted -> 'expectedValue',
    accepted -> 'actualValue',
    case
      when jsonb_typeof(accepted -> 'varianceAmount') = 'number'
        then (accepted ->> 'varianceAmount')::numeric
      else null
    end,
    auth.uid(),
    trim(accepted ->> 'note')
  from jsonb_array_elements(coalesce(p_accepted_variances, '[]'::jsonb)) accepted
  where char_length(trim(coalesce(accepted ->> 'key', ''))) > 0
    and char_length(trim(coalesce(accepted ->> 'type', ''))) > 0
    and char_length(trim(coalesce(accepted ->> 'note', ''))) > 0;

  insert into public.supplier_invoice_activity_events (
    organization_id,
    supplier_invoice_id,
    event_type,
    message,
    metadata,
    created_by
  )
  values (
    p_organization_id,
    v_invoice.id,
    'approved',
    'Supplier invoice commercially approved.',
    jsonb_build_object(
      'commercial_approval_id', v_approval_id,
      'finance_version_hash', v_hash,
      'accepted_variances', coalesce(p_accepted_variances, '[]'::jsonb)
    ),
    auth.uid()
  );

  return v_approval_id;
end;
$$;


ALTER FUNCTION "public"."approve_supplier_invoice_commercially"("p_organization_id" "uuid", "p_supplier_invoice_id" "uuid", "p_expected_finance_hash" "text", "p_accepted_variances" "jsonb", "p_no_po_reason" "text", "p_no_po_explanation" "text", "p_approval_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."archive_material_supplier_product"("p_input" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_org uuid := (p_input->>'organization_id')::uuid;
  v_material_id uuid := (p_input->>'material_id')::uuid;
  v_product_id uuid := (p_input->>'supplier_product_id')::uuid;
  v_reason text := nullif(pg_catalog.btrim(p_input->>'reason'), '');
  v_actor uuid;
  v_product public.organization_material_supplier_products%rowtype;
  v_archived_at timestamptz := statement_timestamp();
begin
  v_actor := public.materials_phase1f_require_writer(v_org);
  if v_reason is null then
    perform public.materials_phase1f_error('supplier_product_archive_reason_required');
  end if;

  perform 1
  from public.organization_materials
  where organization_id = v_org and id = v_material_id
  for update;
  if not found then
    perform public.materials_phase1f_error('material_not_found');
  end if;

  select * into v_product
  from public.organization_material_supplier_products
  where organization_id = v_org and id = v_product_id
  for update;
  if not found or v_product.material_id <> v_material_id then
    perform public.materials_phase1f_error('supplier_product_not_found');
  end if;

  if not v_product.is_active or v_product.archived_at is not null then
    return pg_catalog.jsonb_build_object(
      'supplier_product_id', v_product.id,
      'material_id', v_product.material_id,
      'is_active', v_product.is_active,
      'is_preferred', v_product.is_preferred,
      'archived_at', v_product.archived_at,
      'idempotent_replay', true
    );
  end if;

  update public.organization_material_supplier_prices
  set is_preferred = false
  where organization_id = v_org
    and supplier_product_id = v_product.id
    and is_current = true
    and is_preferred = true;

  update public.organization_material_supplier_products
  set is_active = false,
      is_preferred = false,
      archived_at = v_archived_at,
      archived_by = v_actor,
      updated_by = v_actor
  where organization_id = v_org and id = v_product.id;

  insert into public.organization_material_supplier_product_lifecycle_events (
    organization_id,
    supplier_product_id,
    event_type,
    reason,
    previous_is_active,
    previous_is_preferred,
    actor_user_id,
    metadata
  ) values (
    v_org,
    v_product.id,
    'archived',
    v_reason,
    v_product.is_active,
    v_product.is_preferred,
    v_actor,
    coalesce(p_input->'metadata', '{}'::jsonb)
  );

  return pg_catalog.jsonb_build_object(
    'supplier_product_id', v_product.id,
    'material_id', v_product.material_id,
    'is_active', false,
    'is_preferred', false,
    'archived_at', v_archived_at,
    'idempotent_replay', false
  );
end;
$$;


ALTER FUNCTION "public"."archive_material_supplier_product"("p_input" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."archive_material_supplier_product"("p_input" "jsonb") IS 'Soft-archives a Supplier Product while preserving immutable price, conversion, assignment, and import history.';



CREATE OR REPLACE FUNCTION "public"."archive_task"("p_task_id" "uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  actor_user_id uuid := auth.uid();
  old_row public.project_job_todos%rowtype;
  updated_row public.project_job_todos%rowtype;
begin
  old_row := public._task_assert_task_access(p_task_id);

  update public.project_job_todos t
  set
    status = 'Archived',
    archived_at = now(),
    archived_by = actor_user_id,
    archive_reason = nullif(btrim(coalesce(p_reason, '')), ''),
    updated_by = actor_user_id
  where t.id = p_task_id
    and t.organization_id = old_row.organization_id
  returning * into updated_row;

  perform public._write_task_activity(updated_row.organization_id, updated_row.id, updated_row.project_id, actor_user_id, 'archived', 'archived_at', null, to_jsonb(updated_row.archived_at), jsonb_build_object('reason', updated_row.archive_reason));

  return public._task_to_json(updated_row);
end;
$$;


ALTER FUNCTION "public"."archive_task"("p_task_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."document_workspaces" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "created_by" "uuid" NOT NULL,
    "updated_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL
);

ALTER TABLE ONLY "public"."document_workspaces" FORCE ROW LEVEL SECURITY;


ALTER TABLE "public"."document_workspaces" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."assert_document_workspace_permission"("p_workspace_id" "uuid", "p_permission_key" "text") RETURNS "public"."document_workspaces"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  workspace_row public.document_workspaces%rowtype;
begin
  if auth.uid() is null then
    raise exception 'Authentication required.'
      using errcode = '42501';
  end if;

  select *
  into workspace_row
  from public.document_workspaces workspace
  where workspace.id = p_workspace_id;

  if not found
    or not public.can_access_document_workspace(workspace_row.id, p_permission_key)
  then
    raise exception 'Document workspace not found or access denied.'
      using errcode = '42501';
  end if;

  return workspace_row;
end;
$$;


ALTER FUNCTION "public"."assert_document_workspace_permission"("p_workspace_id" "uuid", "p_permission_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."assert_supplier_invoice_commercial_snapshot_completeness"("p_commercial_approval_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_approval public.supplier_invoice_commercial_approvals%rowtype;
  v_expected_count integer;
  v_snapshot_count integer;
  v_distinct_line_count integer;
begin
  select * into v_approval
  from public.supplier_invoice_commercial_approvals
  where id = p_commercial_approval_id;

  if not found or v_approval.status <> 'approved' then
    return;
  end if;

  select count(*) into v_expected_count
  from public.supplier_invoice_lines
  where organization_id = v_approval.organization_id
    and supplier_invoice_id = v_approval.supplier_invoice_id;

  select count(*), count(distinct snapshot.supplier_invoice_line_id)
  into v_snapshot_count, v_distinct_line_count
  from public.supplier_invoice_commercial_line_snapshots snapshot
  where snapshot.organization_id = v_approval.organization_id
    and snapshot.supplier_invoice_id = v_approval.supplier_invoice_id
    and snapshot.commercial_approval_id = v_approval.id;

  if v_expected_count = 0
    or v_snapshot_count <> v_expected_count
    or v_distinct_line_count <> v_expected_count
    or exists (
      select 1
      from public.supplier_invoice_lines line
      left join public.supplier_invoice_commercial_line_snapshots snapshot
        on snapshot.commercial_approval_id = v_approval.id
        and snapshot.supplier_invoice_line_id = line.id
      where line.organization_id = v_approval.organization_id
        and line.supplier_invoice_id = v_approval.supplier_invoice_id
      group by line.id
      having count(snapshot.id) <> 1
    ) then
    raise exception 'Commercial approval requires one complete line snapshot per Supplier Invoice line.';
  end if;
end;
$$;


