CREATE OR REPLACE FUNCTION "public"."attach_opportunity_commercial_history_to_project"("p_organization_id" "uuid", "p_opportunity_id" "uuid", "p_project_id" "uuid") RETURNS TABLE("attached_quote_count" integer, "attached_quote_line_count" integer, "attached_commercial_item_count" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  opportunity_row public.organization_opportunities%rowtype;
  workspace_row public.organization_projects%rowtype;
  target_row public.organization_projects%rowtype;
  final_mapping public.opportunity_final_projects%rowtype;
begin
  if auth.uid() is null then
    raise exception 'Authentication is required' using errcode = '42501';
  end if;
  if not (
    public.has_org_permission(p_organization_id, 'leads.opportunities.write')
    and public.has_org_permission(p_organization_id, 'quotes.write')
  ) then
    raise exception 'Not authorized for this organization' using errcode = '42501';
  end if;

  select * into opportunity_row
  from public.organization_opportunities opportunity
  where opportunity.id = p_opportunity_id
    and opportunity.organization_id = p_organization_id
  for key share;
  if not found then
    raise exception 'Opportunity not found for organization' using errcode = 'TS422';
  end if;
  if opportunity_row.workspace_project_id is null then
    raise exception 'Opportunity has no recorded tender workspace' using errcode = 'TS422';
  end if;

  select * into workspace_row
  from public.organization_projects project
  where project.id = opportunity_row.workspace_project_id
    and project.organization_id = p_organization_id;
  if not found or workspace_row.source_opportunity_id is distinct from opportunity_row.id then
    raise exception 'Tender workspace does not belong to the Opportunity' using errcode = 'TS409';
  end if;

  select * into target_row
  from public.organization_projects project
  where project.id = p_project_id
    and project.organization_id = p_organization_id;
  if not found or target_row.source_opportunity_id is distinct from opportunity_row.id then
    raise exception 'Final Project must belong to the same Opportunity' using errcode = 'TS409';
  end if;

  select * into final_mapping
  from public.opportunity_final_projects mapping
  where mapping.organization_id = p_organization_id
    and mapping.opportunity_id = p_opportunity_id
    and mapping.project_id = p_project_id;
  if not found then
    raise exception 'Target Project is not the designated final Project' using errcode = 'TS409';
  end if;

  if exists (
    select 1 from public.project_quotes quote
    where quote.organization_id = p_organization_id
      and quote.originating_opportunity_id = p_opportunity_id
      and quote.project_id is not null
      and quote.project_id not in (workspace_row.id, target_row.id)
  ) then
    raise exception 'Commercial quote history is attached to an unrelated Project' using errcode = 'TS409';
  end if;
  if exists (
    select 1
    from public.project_quote_line_items line
    join public.project_quotes quote
      on quote.id = line.quote_id and quote.organization_id = line.organization_id
    where line.organization_id = p_organization_id
      and quote.originating_opportunity_id = p_opportunity_id
      and line.project_id is not null
      and line.project_id not in (workspace_row.id, target_row.id)
  ) then
    raise exception 'Commercial quote line history is attached to an unrelated Project' using errcode = 'TS409';
  end if;
  if exists (
    select 1 from public.commercial_items item
    where item.organization_id = p_organization_id
      and item.opportunity_id = p_opportunity_id
      and item.project_id is not null
      and item.project_id not in (workspace_row.id, target_row.id)
  ) then
    raise exception 'Commercial items are attached to an unrelated Project' using errcode = 'TS409';
  end if;
  if exists (
    select 1
    from public.cost_items cost_item
    join public.project_quotes quote
      on quote.id = cost_item.source_document_id
     and cost_item.source_document_kind = 'project_quote'
     and quote.organization_id = cost_item.organization_id
    where cost_item.organization_id = p_organization_id
      and quote.originating_opportunity_id = p_opportunity_id
      and cost_item.project_id not in (workspace_row.id, target_row.id)
  ) then
    raise exception 'Commercial CostItems are attached to an unrelated Project' using errcode = 'TS409';
  end if;

  perform set_config('tradesstack.defer_award_pricing_finalize', 'on', true);

  with updated_quotes as (
    update public.project_quotes quote
    set project_id = target_row.id
    where quote.organization_id = p_organization_id
      and quote.originating_opportunity_id = p_opportunity_id
      and (quote.project_id is null or quote.project_id = workspace_row.id)
    returning quote.id
  )
  select count(*)::integer into attached_quote_count from updated_quotes;

  with updated_lines as (
    update public.project_quote_line_items line
    set project_id = target_row.id
    from public.project_quotes quote
    where line.organization_id = p_organization_id
      and line.quote_id = quote.id
      and quote.organization_id = p_organization_id
      and quote.originating_opportunity_id = p_opportunity_id
      and (line.project_id is null or line.project_id = workspace_row.id)
    returning line.id
  )
  select count(*)::integer into attached_quote_line_count from updated_lines;

  update public.commercial_items item
  set project_id = target_row.id,
      updated_at = timezone('utc', now()),
      updated_by = auth.uid()
  where item.organization_id = p_organization_id
    and item.opportunity_id = p_opportunity_id
    and (item.project_id is null or item.project_id = workspace_row.id);
  get diagnostics attached_commercial_item_count = row_count;

  update public.cost_items cost_item
  set project_id = target_row.id,
      updated_at = timezone('utc', now())
  from public.project_quotes quote
  where quote.id = cost_item.source_document_id
    and cost_item.source_document_kind = 'project_quote'
    and quote.organization_id = cost_item.organization_id
    and cost_item.organization_id = p_organization_id
    and quote.originating_opportunity_id = p_opportunity_id
    and cost_item.project_id = workspace_row.id;

  perform set_config('tradesstack.defer_award_pricing_finalize', 'off', true);
  perform * from public.finalize_opportunity_award_pricing_v1(
    p_organization_id,
    p_opportunity_id,
    p_project_id,
    final_mapping.accepted_quote_id
  );

  return query select
    coalesce(attached_quote_count, 0),
    coalesce(attached_quote_line_count, 0),
    coalesce(attached_commercial_item_count, 0);
end;
$$;


ALTER FUNCTION "public"."attach_opportunity_commercial_history_to_project"("p_organization_id" "uuid", "p_opportunity_id" "uuid", "p_project_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."audit_opportunity_lifecycle_default_policy_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  actor_id uuid;
begin
  actor_id := coalesce(new.configured_by, old.configured_by);
  insert into public.opportunity_lifecycle_default_policy_events (
    operation,
    environment,
    previous_policy,
    resulting_policy,
    changed_by
  ) values (
    lower(tg_op),
    coalesce(new.environment, old.environment),
    case when tg_op in ('UPDATE', 'DELETE') then to_jsonb(old) else null end,
    case when tg_op in ('INSERT', 'UPDATE') then to_jsonb(new) else null end,
    actor_id
  );
  return coalesce(new, old);
end;
$$;


ALTER FUNCTION "public"."audit_opportunity_lifecycle_default_policy_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."audit_opportunity_lifecycle_rollout_control_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  previous_value jsonb;
  next_value jsonb;
begin
  previous_value := case when tg_op in ('UPDATE', 'DELETE') then to_jsonb(old) else null end;
  next_value := case when tg_op in ('INSERT', 'UPDATE') then to_jsonb(new) else null end;

  insert into public.opportunity_lifecycle_rollout_control_events (
    organization_id,
    operation,
    previous_control,
    next_control,
    changed_by
  ) values (
    coalesce(new.organization_id, old.organization_id),
    lower(tg_op),
    previous_value,
    next_value,
    coalesce(auth.uid(), new.updated_by, old.updated_by)
  );

  return coalesce(new, old);
end;
$$;


ALTER FUNCTION "public"."audit_opportunity_lifecycle_rollout_control_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."award_opportunity_by_lifecycle_pre_quote_series_v1"("p_organization_id" "uuid", "p_opportunity_id" "uuid", "p_accepted_quote_id" "uuid", "p_correlation_id" "text") RETURNS TABLE("project_id" "uuid", "project_slug" "text", "project_created" boolean, "storage_clone_required" boolean, "lifecycle_strategy" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  award_result record;
begin
  select * into award_result
  from public.award_opportunity_by_lifecycle_v1_without_document_invariant(
    p_organization_id,
    p_opportunity_id,
    p_accepted_quote_id,
    p_correlation_id
  );

  perform public.ensure_opportunity_project_document_workspace(
    p_opportunity_id,
    award_result.project_id
  );

  return query select
    award_result.project_id,
    award_result.project_slug,
    award_result.project_created,
    award_result.storage_clone_required,
    award_result.lifecycle_strategy;
end;
$$;


ALTER FUNCTION "public"."award_opportunity_by_lifecycle_pre_quote_series_v1"("p_organization_id" "uuid", "p_opportunity_id" "uuid", "p_accepted_quote_id" "uuid", "p_correlation_id" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."award_opportunity_by_lifecycle_pre_quote_series_v1"("p_organization_id" "uuid", "p_opportunity_id" "uuid", "p_accepted_quote_id" "uuid", "p_correlation_id" "text") IS 'Lifecycle award orchestrator with transactional shared document workspace continuity for promotion and legacy strategies.';



CREATE OR REPLACE FUNCTION "public"."award_opportunity_by_lifecycle_v1"("p_organization_id" "uuid", "p_opportunity_id" "uuid", "p_accepted_quote_id" "uuid", "p_correlation_id" "text") RETURNS TABLE("project_id" "uuid", "project_slug" "text", "project_created" boolean, "storage_clone_required" boolean, "lifecycle_strategy" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  opportunity public.organization_opportunities%rowtype;
  accepted public.project_quotes%rowtype;
  series public.opportunity_quote_series%rowtype;
  converted record;
begin
  select * into opportunity from public.organization_opportunities candidate
  where candidate.organization_id = p_organization_id and candidate.id = p_opportunity_id
  for update;
  if not found or opportunity.accepted_quote_revision_id is distinct from p_accepted_quote_id then
    raise exception 'Conversion requires the explicitly selected accepted quote revision'
      using errcode = 'TS409';
  end if;
  select * into accepted from public.project_quotes quote
  where quote.organization_id = p_organization_id and quote.id = p_accepted_quote_id
    and quote.originating_opportunity_id = p_opportunity_id
    and quote.status = 'Accepted' and quote.quote_series_id is not null;
  if not found then raise exception 'Accepted quote revision is invalid for this Opportunity' using errcode = 'TS422'; end if;
  select * into series from public.opportunity_quote_series candidate
  where candidate.organization_id = p_organization_id and candidate.id = accepted.quote_series_id
    and candidate.opportunity_id = p_opportunity_id and candidate.recipient_client_id is not null;
  if not found then raise exception 'Accepted Quote Series recipient is unavailable' using errcode = 'TS422'; end if;

  perform set_config('tradesstack.conversion_opportunity_id', p_opportunity_id::text, true);
  select * into converted from public.award_opportunity_by_lifecycle_pre_quote_series_v1(
    p_organization_id, p_opportunity_id, p_accepted_quote_id, p_correlation_id
  );
  perform set_config('tradesstack.conversion_opportunity_id', '', true);
  update public.organization_projects project
  set client_id = series.recipient_client_id
  where project.organization_id = p_organization_id and project.id = converted.project_id
    and project.client_id is distinct from series.recipient_client_id;
  return query select converted.project_id, converted.project_slug, converted.project_created,
    converted.storage_clone_required, converted.lifecycle_strategy;
end;
$$;


ALTER FUNCTION "public"."award_opportunity_by_lifecycle_v1"("p_organization_id" "uuid", "p_opportunity_id" "uuid", "p_accepted_quote_id" "uuid", "p_correlation_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."award_opportunity_by_lifecycle_v1_without_document_invariant"("p_organization_id" "uuid", "p_opportunity_id" "uuid", "p_accepted_quote_id" "uuid", "p_correlation_id" "text") RETURNS TABLE("project_id" "uuid", "project_slug" "text", "project_created" boolean, "storage_clone_required" boolean, "lifecycle_strategy" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
declare
  opportunity_row public.organization_opportunities%rowtype;
  lifecycle_row public.opportunity_lifecycles%rowtype;
  mapping_row public.opportunity_final_projects%rowtype;
  project_row public.organization_projects%rowtype;
  override_row public.opportunity_lifecycle_rollout_controls%rowtype;
  default_row public.opportunity_lifecycle_default_policy%rowtype;
  promotion_result record;
  legacy_result record;
  promotion_event_count integer;
  resolved_strategy text;
  resolved_correlation_id uuid;
  promotion_authorized boolean := false;
begin
  if auth.uid() is null then
    raise exception 'Authentication is required' using errcode = '42501';
  end if;

  if not (
    public.has_org_permission(p_organization_id, 'leads.opportunities.write')
    and public.has_org_permission(p_organization_id, 'quotes.write')
  ) then
    raise exception 'Not authorized for this organization' using errcode = '42501';
  end if;

  if p_correlation_id is null then
    raise exception 'Award correlation ID is required' using errcode = 'TS422';
  end if;

  resolved_correlation_id := case
    when p_correlation_id ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
      then p_correlation_id::uuid
    else md5(p_correlation_id)::uuid
  end;

  select * into opportunity_row
  from public.organization_opportunities opportunity
  where opportunity.organization_id = p_organization_id
    and opportunity.id = p_opportunity_id
  for update;

  if not found then
    raise exception 'Opportunity not found for organization' using errcode = 'TS422';
  end if;

  select * into lifecycle_row
  from public.opportunity_lifecycles lifecycle
  where lifecycle.organization_id = p_organization_id
    and lifecycle.opportunity_id = p_opportunity_id
  for key share;

  resolved_strategy := coalesce(lifecycle_row.strategy, 'unmarked_historical');
  if lifecycle_row.id is not null and (
    lifecycle_row.strategy_version <> 1
    or lifecycle_row.strategy not in ('legacy_two_project_v1', 'promote_workspace_v1')
  ) then
    raise exception 'Unsupported Opportunity lifecycle strategy' using errcode = 'TS409';
  end if;

  select * into mapping_row
  from public.opportunity_final_projects mapping
  where mapping.organization_id = p_organization_id
    and mapping.opportunity_id = p_opportunity_id
  for update;

  if mapping_row.opportunity_id is not null then
    if mapping_row.accepted_quote_id is distinct from p_accepted_quote_id
      or opportunity_row.converted_project_id is distinct from mapping_row.project_id
    then
      raise exception 'Opportunity has a conflicting final Project mapping'
        using errcode = 'TS409';
    end if;

    select * into project_row
    from public.organization_projects project
    where project.organization_id = p_organization_id
      and project.id = mapping_row.project_id;
    if not found then
      raise exception 'Designated final Project is missing' using errcode = 'TS409';
    end if;

    if lifecycle_row.strategy = 'promote_workspace_v1' then
      select count(*)::integer into promotion_event_count
      from public.opportunity_promotion_events event
      where event.organization_id = p_organization_id
        and event.opportunity_id = p_opportunity_id
        and event.project_id = opportunity_row.workspace_project_id
        and event.accepted_quote_id = p_accepted_quote_id;

      if mapping_row.project_id is distinct from opportunity_row.workspace_project_id
        or lifecycle_row.original_workspace_project_id
          is distinct from opportunity_row.workspace_project_id
        or promotion_event_count <> 1
      then
        raise exception 'Completed promotion evidence is inconsistent'
          using errcode = 'TS409';
      end if;

      return query select project_row.id, project_row.slug, false, false,
        'promote_workspace_v1'::text;
      return;
    end if;

    if lifecycle_row.id is not null and lifecycle_row.strategy <> 'legacy_two_project_v1' then
      raise exception 'Final mapping contradicts lifecycle strategy' using errcode = 'TS409';
    end if;

    return query select project_row.id, project_row.slug, false, true,
      resolved_strategy;
    return;
  end if;

  if lifecycle_row.strategy = 'promote_workspace_v1' then
    select * into override_row
    from public.opportunity_lifecycle_rollout_controls rollout
    where rollout.organization_id = p_organization_id
      and rollout.override_enabled
      and public.is_opportunity_lifecycle_override_active_v1(
        rollout.pilot_scope,
        rollout.pilot_environment
      );

    if found then
      promotion_authorized := override_row.creation_enabled
        and override_row.promotion_enabled
        and override_row.allowed_strategy = 'promote_workspace_v1';
    else
      select * into default_row
      from public.opportunity_lifecycle_default_policy policy
      where policy.singleton
        and policy.effective_from <= now();
      promotion_authorized := found
        and default_row.creation_enabled
        and default_row.promotion_enabled
        and default_row.default_strategy = 'promote_workspace_v1';
    end if;

    if promotion_authorized is not true then
      raise exception 'Opportunity promotion award is paused'
        using errcode = 'TS409';
    end if;

    select * into promotion_result
    from public.promote_opportunity_workspace_v1(
      p_organization_id,
      p_opportunity_id,
      p_accepted_quote_id,
      resolved_correlation_id
    );

    return query select
      promotion_result.project_id,
      promotion_result.project_slug,
      false,
      false,
      'promote_workspace_v1'::text;
    return;
  end if;

  if lifecycle_row.id is not null and lifecycle_row.strategy <> 'legacy_two_project_v1' then
    raise exception 'Opportunity lifecycle strategy is contradictory'
      using errcode = 'TS409';
  end if;

  select * into legacy_result
  from public.convert_accepted_opportunity_to_project(
    p_organization_id,
    p_opportunity_id,
    p_accepted_quote_id
  );

  return query select
    legacy_result.project_id,
    legacy_result.project_slug,
    legacy_result.project_created,
    legacy_result.storage_clone_required,
    resolved_strategy;
end;
$_$;


ALTER FUNCTION "public"."award_opportunity_by_lifecycle_v1_without_document_invariant"("p_organization_id" "uuid", "p_opportunity_id" "uuid", "p_accepted_quote_id" "uuid", "p_correlation_id" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."award_opportunity_by_lifecycle_v1_without_document_invariant"("p_organization_id" "uuid", "p_opportunity_id" "uuid", "p_accepted_quote_id" "uuid", "p_correlation_id" "text") IS 'Stage 7 immutable-strategy award orchestrator. Policy controls promotion execution only and never selects strategy at award.';



CREATE OR REPLACE FUNCTION "public"."backfill_commercial_lineage_edges"("p_evidence_batch_id" "uuid" DEFAULT "gen_random_uuid"()) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  item_id uuid;
  inserted_count integer := 0;
  item_count integer := 0;
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'commercial_lineage:service_role_required' using errcode = '42501';
  end if;
  for item_id in select id from public.commercial_items order by id loop
    item_count := item_count + 1;
    inserted_count := inserted_count + public.sync_commercial_item_lineage_internal(item_id, p_evidence_batch_id);
  end loop;
  return jsonb_build_object(
    'evidenceBatchId', p_evidence_batch_id,
    'commercialItemsScanned', item_count,
    'edgesInserted', inserted_count
  );
end;
$$;


ALTER FUNCTION "public"."backfill_commercial_lineage_edges"("p_evidence_batch_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."begin_cost_item_revision"("p_document_kind" "text", "p_document_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  resolved_context record;
begin
  select *
  into resolved_context
  from public.resolve_cost_item_document_context(p_document_kind, p_document_id)
  limit 1;

  if resolved_context.organization_id is null then
    raise exception 'Document not found or not authorized for CostItem revision';
  end if;

  return lower(p_document_kind)
    || ':'
    || p_document_id::text
    || ':'
    || to_char(clock_timestamp() at time zone 'utc', 'YYYYMMDDHH24MISSUS')
    || ':'
    || replace(gen_random_uuid()::text, '-', '');
end;
$$;


ALTER FUNCTION "public"."begin_cost_item_revision"("p_document_kind" "text", "p_document_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."build_time_sheet_entry_labour_line_description"("p_organization_id" "uuid", "p_worker_name" "text", "p_clock_in_at" timestamp with time zone) RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  organization_timezone text;
  effective_timezone text := 'Pacific/Auckland';
  local_clock_in timestamp;
begin
  select nullif(btrim(o.timezone), '')
  into organization_timezone
  from public.organizations o
  where o.id = p_organization_id
  limit 1;

  if organization_timezone is not null then
    effective_timezone := organization_timezone;
  end if;

  begin
    local_clock_in := p_clock_in_at at time zone effective_timezone;
  exception
    when others then
      local_clock_in := p_clock_in_at at time zone 'UTC';
  end;

  return coalesce(nullif(btrim(p_worker_name), ''), 'Worker') || ' - ' || to_char(local_clock_in, 'DD/MM/YYYY');
end;
$$;


ALTER FUNCTION "public"."build_time_sheet_entry_labour_line_description"("p_organization_id" "uuid", "p_worker_name" "text", "p_clock_in_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."calculate_project_quote_pre_gst_total"("p_subtotal" numeric, "p_margin_percent" numeric, "p_discount_amount" numeric, "p_contingency_amount" numeric) RETURNS numeric
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select round(
    greatest(
      0,
      coalesce(p_subtotal, 0)
      + (coalesce(p_subtotal, 0) * (coalesce(p_margin_percent, 0) / 100))
      + coalesce(p_contingency_amount, 0)
      - coalesce(p_discount_amount, 0)
    ),
    2
  );
$$;


