CREATE OR REPLACE FUNCTION "public"."can_upload_document_storage_object"("p_object_path" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
  select
    auth.uid() is not null
    and coalesce(p_object_path, '') ~
      '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}/[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}/[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
    and exists (
      select 1
      from public.document_versions version
      join public.document_nodes node
        on node.organization_id = version.organization_id
       and node.workspace_id = version.workspace_id
       and node.id = version.node_id
      where version.storage_key = p_object_path
        and version.uploaded_by = auth.uid()
        and version.upload_state = 'pending'
        and version.upload_expires_at > now()
        and node.deleted_at is null
        and node.lifecycle_state in ('pending', 'active')
        and public.can_access_document_workspace(
          version.workspace_id,
          'files.write'
        )
    );
$_$;


ALTER FUNCTION "public"."can_upload_document_storage_object"("p_object_path" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."can_view_supplier_invoice_workflow"("p_organization_id" "uuid", "p_supplier_invoice_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select exists (
    select 1 from public.organization_members m
    where m.organization_id = p_organization_id
      and m.user_id = auth.uid()
      and (
        m.role in ('owner', 'admin')
        or (
          m.role in ('qs', 'project_manager')
          and public.has_org_permission(p_organization_id, 'supplier_invoices.view')
          and exists (
            select 1
            from public.supplier_invoice_line_allocations a
            join public.project_members pm
              on pm.organization_id = p_organization_id
             and pm.project_id = a.project_id
             and pm.organization_member_id = m.id
             and pm.is_active
            where a.organization_id = p_organization_id
              and a.supplier_invoice_id = p_supplier_invoice_id
          )
        )
      )
  );
$$;


ALTER FUNCTION "public"."can_view_supplier_invoice_workflow"("p_organization_id" "uuid", "p_supplier_invoice_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."can_write_pricing_workbook_owner"("p_organization_id" "uuid", "p_opportunity_id" "uuid", "p_project_id" "uuid" DEFAULT NULL::"uuid", "p_quote_id" "uuid" DEFAULT NULL::"uuid", "p_variation_id" "uuid" DEFAULT NULL::"uuid") RETURNS boolean
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  resolved_project_source_opportunity_id uuid;
begin
  if not public.is_member_of_organization(p_organization_id) then
    return false;
  end if;

  if p_variation_id is not null then
    if p_quote_id is not null or p_project_id is null
      or not public.has_org_permission(p_organization_id, 'variations.write') then
      return false;
    end if;

    select project.source_opportunity_id into resolved_project_source_opportunity_id
    from public.project_variations variation
    join public.organization_projects project
      on project.id = variation.project_id and project.organization_id = variation.organization_id
    where variation.id = p_variation_id
      and variation.organization_id = p_organization_id
      and variation.project_id = p_project_id;

    return found and resolved_project_source_opportunity_id is not distinct from p_opportunity_id;
  end if;

  if p_quote_id is not null then
    if p_project_id is null or not public.has_org_permission(p_organization_id, 'quotes.write') then
      return false;
    end if;

    return exists (
      select 1 from public.project_quotes quote
      where quote.id = p_quote_id
        and quote.organization_id = p_organization_id
        and quote.project_id = p_project_id
        and quote.originating_opportunity_id = p_opportunity_id
    );
  end if;

  if p_project_id is not null then
    if not public.has_org_permission(p_organization_id, 'quotes.write') then
      return false;
    end if;

    return exists (
      select 1 from public.organization_projects project
      where project.id = p_project_id
        and project.organization_id = p_organization_id
        and project.source_opportunity_id = p_opportunity_id
    );
  end if;

  return public.has_org_permission(p_organization_id, 'leads.opportunities.write')
    and exists (
      select 1 from public.organization_opportunities opportunity
      where opportunity.id = p_opportunity_id
        and opportunity.organization_id = p_organization_id
    );
end;
$$;


ALTER FUNCTION "public"."can_write_pricing_workbook_owner"("p_organization_id" "uuid", "p_opportunity_id" "uuid", "p_project_id" "uuid", "p_quote_id" "uuid", "p_variation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_material_import_job"("p_organization_id" "uuid", "p_import_batch_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_cancelled boolean := false;
begin
  if not public.has_org_permission(p_organization_id, 'materials.write') then
    raise exception 'materials.write required' using errcode = '42501';
  end if;

  update public.organization_material_import_jobs
  set cancel_requested_at = now(), state = 'cancelled', lease_expires_at = null
  where organization_id = p_organization_id and import_batch_id = p_import_batch_id
    and state in ('queued', 'processing');
  v_cancelled := found;

  update public.organization_material_import_runs run
  set status = 'cancelled', completed_at = now()
  where run.organization_id = p_organization_id and run.import_batch_id = p_import_batch_id
    and run.status in ('queued', 'processing');

  update public.organization_material_import_batches
  set status = 'cancelled'
  where organization_id = p_organization_id and id = p_import_batch_id and status = 'extracting';

  return v_cancelled;
end;
$$;


ALTER FUNCTION "public"."cancel_material_import_job"("p_organization_id" "uuid", "p_import_batch_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_project_qa_run_v1"("p_organization_id" "uuid", "p_project_id" "uuid", "p_run_id" "uuid", "p_expected_lock_version" integer) RETURNS TABLE("status" "text", "cancelled_at" timestamp with time zone, "lock_version" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  next_time timestamptz := now();
  next_lock integer;
begin
  if auth.uid() is null
    or not public.can_access_qa_project(p_organization_id, p_project_id, 'qa.inspect')
  then
    raise exception 'Not authorized to cancel QA' using errcode = '42501';
  end if;

  update public.project_qa_runs as target
  set status = 'cancelled',
      cancelled_by = auth.uid(),
      cancelled_at = next_time,
      lock_version = target.lock_version + 1
  where target.organization_id = p_organization_id
    and target.project_id = p_project_id
    and target.id = p_run_id
    and target.status = 'in_progress'
    and target.lock_version = p_expected_lock_version
  returning target.lock_version into next_lock;

  if next_lock is null then
    if exists (
      select 1 from public.project_qa_runs run
      where run.organization_id = p_organization_id
        and run.project_id = p_project_id
        and run.id = p_run_id
        and run.status = 'in_progress'
    ) then
      raise exception 'This QA Record has changed since you opened it. Reload the latest record before cancelling.' using errcode = 'TS409';
    end if;
    raise exception 'Only an in-progress QA Record can be cancelled' using errcode = 'TS409';
  end if;

  return query select 'cancelled'::text, next_time, next_lock;
end;
$$;


ALTER FUNCTION "public"."cancel_project_qa_run_v1"("p_organization_id" "uuid", "p_project_id" "uuid", "p_run_id" "uuid", "p_expected_lock_version" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_retention_claim_draft"("p_retention_claim_id" "uuid", "p_expected_draft_revision" bigint, "p_reason" "text", "p_correlation_id" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_claim public.retention_claims%rowtype;
  v_context jsonb;
  v_allocation_count integer;
  v_allocation_total numeric;
begin
  select * into v_claim
  from public.retention_claims claim
  where claim.id = p_retention_claim_id;
  if not found then
    return jsonb_build_object('succeeded', false, 'errorCode', 'claim_not_found');
  end if;

  v_context := private.retention_claim_operation_context(
    v_claim.project_id,
    'retention.claims.create',
    true
  );
  if not coalesce((v_context ->> 'succeeded')::boolean, false) then
    return v_context;
  end if;

  select * into v_claim
  from public.retention_claims claim
  where claim.id = p_retention_claim_id
    and claim.organization_id = (v_context ->> 'organizationId')::uuid
  for update;
  if not found then
    return jsonb_build_object('succeeded', false, 'errorCode', 'claim_not_found');
  end if;
  if v_claim.status <> 'draft' then
    return private.reject_retention_claim_submission(
      v_claim.id,
      'claim_not_draft',
      jsonb_build_object('operation', 'cancel_retention_claim_draft'),
      p_correlation_id
    );
  end if;
  if v_claim.draft_revision <> p_expected_draft_revision then
    return jsonb_build_object(
      'succeeded', false,
      'errorCode', 'concurrent_update',
      'currentDraftRevision', v_claim.draft_revision
    );
  end if;
  if nullif(trim(coalesce(p_reason, '')), '') is null then
    return jsonb_build_object('succeeded', false, 'errorCode', 'invalid_transition');
  end if;

  select count(*)::integer, round(coalesce(sum(allocation_amount), 0), 2)
  into v_allocation_count, v_allocation_total
  from public.retention_claim_allocations allocation
  where allocation.retention_claim_id = v_claim.id;

  delete from public.retention_claim_allocations allocation
  where allocation.retention_claim_id = v_claim.id;

  update public.retention_claims claim
  set
    status = 'cancelled_draft',
    cancelled_by = auth.uid(),
    cancelled_at = now(),
    draft_revision = claim.draft_revision + 1
  where claim.id = v_claim.id
  returning * into v_claim;

  perform private.record_retention_claim_event(
    v_claim.organization_id, v_claim.project_id, v_claim.id,
    'draft_cancelled', 'draft', 'cancelled_draft', auth.uid(),
    trim(p_reason), p_correlation_id,
    jsonb_build_object(
      'removedDraftAllocationCount', v_allocation_count,
      'removedDraftAllocationTotal', v_allocation_total,
      'draftRevision', v_claim.draft_revision
    )
  );

  return jsonb_build_object(
    'succeeded', true,
    'errorCode', null,
    'claim', private.retention_claim_header_json(v_claim.id)
  );
end;
$$;


ALTER FUNCTION "public"."cancel_retention_claim_draft"("p_retention_claim_id" "uuid", "p_expected_draft_revision" bigint, "p_reason" "text", "p_correlation_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_retention_release_schedule"("p_input" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare s public.project_retention_release_schedules%rowtype; origins uuid[];
  blocks jsonb; result jsonb; ctx jsonb;
begin
  if not private.retention_phase5_gate_enabled() then
    return public.cancel_retention_release_schedule_phase4_pre_variance(p_input);
  end if;
  select * into s from public.project_retention_release_schedules
  where id=(p_input->>'scheduleId')::uuid;
  if not found then return jsonb_build_object('succeeded',false,'errorCode','schedule_not_found'); end if;
  ctx:=private.retention_phase5_context(s.project_id,
    case when s.status='activated' then 'retention.schedules.confirm'
      else 'retention.schedules.manage' end,true);
  if not coalesce((ctx->>'succeeded')::boolean,false) then return ctx; end if;
  select coalesce(array_agg(o.originating_payment_claim_id order by o.originating_payment_claim_id),
    '{}'::uuid[]) into origins
  from public.project_retention_schedule_origins o where o.schedule_id=s.id;
  perform private.evaluate_retention_variance_project(
    s.project_id,p_input->>'correlationId',origins);
  blocks:=private.retention_variance_blocking_details(s.project_id,origins);
  if coalesce((blocks->>'blocking')::boolean,false)
    or (s.status='activated' and exists(
      select 1 from public.retention_claim_allocations a
      join public.retention_claims c on c.id=a.retention_claim_id
      where c.status='submitted' and s.id=any(coalesce(a.eligibility_schedule_ids_snapshot,'{}'))
    )) then
    return jsonb_build_object('succeeded',false,'errorCode','variance_blocking',
      'details',blocks||jsonb_build_object('scheduleId',s.id));
  end if;
  result:=public.cancel_retention_release_schedule_phase4_pre_variance(p_input);
  if coalesce((result->>'succeeded')::boolean,false) then
    perform private.evaluate_retention_variance_project(
      s.project_id,p_input->>'correlationId',origins);
  end if;
  return result;
end;
$$;


ALTER FUNCTION "public"."cancel_retention_release_schedule"("p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_retention_release_schedule_phase4_pre_variance"("p_input" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_s public.project_retention_release_schedules%rowtype; v_context jsonb; v_permission text;
begin
  select * into v_s from public.project_retention_release_schedules where id=(p_input->>'scheduleId')::uuid;
  if not found then return jsonb_build_object('succeeded',false,'errorCode','schedule_not_found'); end if;
  v_permission:=case when v_s.status='activated' then 'retention.schedules.confirm'
                     else 'retention.schedules.manage' end;
  v_context:=private.retention_phase4_context(v_s.project_id,v_permission,true);
  if not coalesce((v_context->>'succeeded')::boolean,false) then return v_context; end if;
  select * into v_s from public.project_retention_release_schedules where id=v_s.id for update;
  if v_s.status in ('completed','cancelled') then
    return jsonb_build_object('succeeded',false,'errorCode','schedule_immutable');
  end if;
  if v_s.revision<>(p_input->>'expectedRevision')::bigint then
    return jsonb_build_object('succeeded',false,'errorCode','concurrent_update','currentRevision',v_s.revision);
  end if;
  if nullif(trim(coalesce(p_input->>'reason','')),'') is null then
    return jsonb_build_object('succeeded',false,'errorCode','invalid_transition');
  end if;
  if v_s.status='activated' and exists(
    select 1 from public.retention_claim_allocations a
    join public.retention_claims c on c.id=a.retention_claim_id
    where c.status='submitted'
      and v_s.id=any(coalesce(a.eligibility_schedule_ids_snapshot,'{}'::uuid[]))
  ) then return jsonb_build_object('succeeded',false,'errorCode','schedule_immutable'); end if;
  perform set_config('app.retention_phase4_internal_write','true',true);
  update public.project_retention_release_schedules set
    status='cancelled',cancelled_at=now(),cancelled_by=auth.uid(),
    cancellation_reason=trim(p_input->>'reason'),revision=revision+1
  where id=v_s.id returning * into v_s;
  perform set_config('app.retention_phase4_internal_write','',true);
  update public.retention_reminders set
    state='cancelled',cancelled_at=now(),cancelled_by=auth.uid(),
    cancellation_reason='schedule_cancelled',revision=revision+1,
    next_delivery_at=null,delivery_claimed_at=null,delivery_claim_token=null
  where schedule_id=v_s.id and state not in ('completed','cancelled');
  perform private.record_retention_schedule_event(
    v_s.id,'schedule_cancelled',null,'cancelled',trim(p_input->>'reason'),
    p_input->>'correlationId','{}'::jsonb
  );
  return jsonb_build_object('succeeded',true,'errorCode',null,'schedule',to_jsonb(v_s));
end;
$$;


ALTER FUNCTION "public"."cancel_retention_release_schedule_phase4_pre_variance"("p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_retention_reminder"("p_input" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_r public.retention_reminders%rowtype; v_context jsonb;
begin
  select * into v_r from public.retention_reminders where id=(p_input->>'reminderId')::uuid;
  if not found then return jsonb_build_object('succeeded',false,'errorCode','reminder_not_found'); end if;
  v_context:=private.retention_phase4_context(v_r.project_id,'retention.reminders.manage',true);
  if not coalesce((v_context->>'succeeded')::boolean,false) then return v_context; end if;
  select * into v_r from public.retention_reminders where id=v_r.id for update;
  if v_r.revision<>(p_input->>'expectedRevision')::bigint then
    return jsonb_build_object('succeeded',false,'errorCode','concurrent_update','currentRevision',v_r.revision);
  end if;
  if v_r.state in ('completed','cancelled') then
    return jsonb_build_object('succeeded',false,'errorCode','reminder_immutable');
  end if;
  if nullif(trim(coalesce(p_input->>'reason','')),'') is null then
    return jsonb_build_object('succeeded',false,'errorCode','invalid_reminder_state');
  end if;
  update public.retention_reminders set state='cancelled',cancelled_at=now(),
    cancelled_by=auth.uid(),cancellation_reason=trim(p_input->>'reason'),
    next_delivery_at=null,delivery_claimed_at=null,delivery_claim_token=null,
    revision=revision+1 where id=v_r.id returning * into v_r;
  perform private.record_retention_reminder_event(
    v_r.id,'reminder_cancelled',null,'cancelled',v_r.cancellation_reason,
    p_input->>'correlationId','{}'::jsonb
  );
  return jsonb_build_object('succeeded',true,'errorCode',null,'reminder',to_jsonb(v_r));
end;
$$;


ALTER FUNCTION "public"."cancel_retention_reminder"("p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_supplier_invoice_xero_bill_export"("p_organization_id" "uuid", "p_supplier_invoice_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_document public.organization_accounting_documents%rowtype;
  v_job_id uuid;
begin
  if auth.uid() is null
    or not public.has_org_permission(p_organization_id, 'accounting.ap_bills.export') then
    raise exception 'You do not have permission to cancel this Xero export.';
  end if;

  select * into v_document
  from public.organization_accounting_documents
  where organization_id = p_organization_id
    and local_document_type = 'supplier_invoice'
    and local_document_id = p_supplier_invoice_id
    and export_status = 'queued'
  for update;
  if not found then
    raise exception 'Only a queued Xero export can be cancelled.';
  end if;

  update public.organization_accounting_sync_jobs
  set queue_state = 'completed',
      result_summary = jsonb_build_object('cancelled', true),
      last_completed_at = now(),
      last_error = null
  where organization_id = p_organization_id
    and job_kind = 'xero.bill.export'
    and request_payload ->> 'documentVersionId' = v_document.current_version_id::text
    and queue_state = 'pending'
  returning id into v_job_id;
  if v_job_id is null then
    raise exception 'The Xero export has already been claimed and cannot be cancelled.';
  end if;

  update public.organization_accounting_documents
  set export_status = 'cancelled'
  where id = v_document.id;
  update public.organization_accounting_document_versions
  set status = 'cancelled'
  where id = v_document.current_version_id;

  insert into public.supplier_invoice_activity_events (
    organization_id, supplier_invoice_id, event_type, message, metadata, created_by
  )
  values (
    p_organization_id,
    p_supplier_invoice_id,
    'xero_export_cancelled',
    'Queued Draft Xero Bill export cancelled.',
    jsonb_build_object('accounting_document_id', v_document.id, 'job_id', v_job_id),
    auth.uid()
  );

  return jsonb_build_object('documentId', v_document.id, 'jobId', v_job_id, 'status', 'cancelled');
end;
$$;


ALTER FUNCTION "public"."cancel_supplier_invoice_xero_bill_export"("p_organization_id" "uuid", "p_supplier_invoice_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."capture_opportunity_promotion_shadow_v1"("p_organization_id" "uuid", "p_opportunity_id" "uuid", "p_accepted_quote_id" "uuid", "p_correlation_id" "uuid", "p_actor_user_id" "uuid") RETURNS TABLE("run_id" "uuid", "captured" boolean, "eligible" boolean, "failure_codes" "text"[])
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  control_row public.opportunity_promotion_shadow_controls%rowtype;
  evaluation record;
  existing_row public.opportunity_promotion_shadow_runs%rowtype;
begin
  select * into control_row
  from public.opportunity_promotion_shadow_controls control
  where control.organization_id = p_organization_id;
  if control_row.organization_id is null or not control_row.shadow_enabled then
    return query select null::uuid, false, false, '{}'::text[];
    return;
  end if;

  select * into evaluation
  from public.evaluate_opportunity_promotion_shadow_v1(
    p_organization_id, p_opportunity_id, p_accepted_quote_id, p_actor_user_id
  );

  insert into public.opportunity_promotion_shadow_runs (
    organization_id, opportunity_id, workspace_project_id, accepted_quote_id,
    lifecycle_strategy, lifecycle_strategy_version, evaluator_version,
    conversion_correlation_id, eligibility_result, eligibility_failure_codes,
    pre_snapshot, immutable_payload_hash, created_by
  ) values (
    p_organization_id, p_opportunity_id, evaluation.workspace_project_id,
    p_accepted_quote_id, evaluation.lifecycle_strategy,
    evaluation.lifecycle_strategy_version, evaluation.evaluator_version,
    p_correlation_id, case when evaluation.eligible then 'eligible' else 'ineligible' end,
    evaluation.failure_codes, evaluation.snapshot, evaluation.payload_hash,
    p_actor_user_id
  )
  on conflict (organization_id, opportunity_id) do nothing;

  select * into existing_row
  from public.opportunity_promotion_shadow_runs shadow_run
  where shadow_run.organization_id = p_organization_id
    and shadow_run.opportunity_id = p_opportunity_id;

  return query select
    existing_row.id,
    existing_row.conversion_correlation_id = p_correlation_id,
    existing_row.eligibility_result = 'eligible',
    existing_row.eligibility_failure_codes;
end;
$$;


ALTER FUNCTION "public"."capture_opportunity_promotion_shadow_v1"("p_organization_id" "uuid", "p_opportunity_id" "uuid", "p_accepted_quote_id" "uuid", "p_correlation_id" "uuid", "p_actor_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."capture_opportunity_promotion_shadow_v2"("p_organization_id" "uuid", "p_opportunity_id" "uuid", "p_accepted_quote_id" "uuid", "p_correlation_id" "uuid", "p_actor_user_id" "uuid") RETURNS TABLE("run_id" "uuid", "captured" boolean, "eligible" boolean, "failure_codes" "text"[])
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  control_row public.opportunity_promotion_shadow_controls%rowtype;
  evaluation record;
  existing_row public.opportunity_promotion_shadow_runs%rowtype;
begin
  select * into control_row
  from public.opportunity_promotion_shadow_controls control
  where control.organization_id = p_organization_id;
  if control_row.organization_id is null
    or not control_row.shadow_enabled
    or control_row.evaluator_version <> 'shadow-v2'
  then
    return query select null::uuid, false, false, array[]::text[];
    return;
  end if;

  select * into evaluation
  from public.evaluate_opportunity_promotion_shadow_v2(
    p_organization_id, p_opportunity_id, p_accepted_quote_id, p_actor_user_id
  );

  if evaluation.lifecycle_strategy is distinct from 'legacy_two_project_v1' then
    return query select null::uuid, false, false, evaluation.failure_codes;
    return;
  end if;

  insert into public.opportunity_promotion_shadow_runs (
    organization_id, opportunity_id, workspace_project_id, accepted_quote_id,
    lifecycle_strategy, lifecycle_strategy_version, evaluator_version,
    conversion_correlation_id, eligibility_result, eligibility_failure_codes,
    pre_snapshot, immutable_payload_hash, created_by
  ) values (
    p_organization_id, p_opportunity_id, evaluation.workspace_project_id,
    p_accepted_quote_id, evaluation.lifecycle_strategy,
    evaluation.lifecycle_strategy_version, evaluation.evaluator_version,
    p_correlation_id, case when evaluation.eligible then 'eligible' else 'ineligible' end,
    evaluation.failure_codes, evaluation.snapshot, evaluation.payload_hash,
    p_actor_user_id
  )
  on conflict (organization_id, opportunity_id) do nothing;

  select * into existing_row
  from public.opportunity_promotion_shadow_runs shadow_run
  where shadow_run.organization_id = p_organization_id
    and shadow_run.opportunity_id = p_opportunity_id;

  return query select
    existing_row.id,
    existing_row.conversion_correlation_id = p_correlation_id,
    existing_row.eligibility_result = 'eligible',
    existing_row.eligibility_failure_codes;
end;
$$;


ALTER FUNCTION "public"."capture_opportunity_promotion_shadow_v2"("p_organization_id" "uuid", "p_opportunity_id" "uuid", "p_accepted_quote_id" "uuid", "p_correlation_id" "uuid", "p_actor_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_retention_variance_blocks"("p_project_id" "uuid", "p_origin_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare ctx jsonb;
begin
  ctx:=private.retention_phase5_context(
    p_project_id,'retention.variances.view',false);
  if not coalesce((ctx->>'succeeded')::boolean,false) then return ctx; end if;
  return jsonb_build_object('succeeded',true,'errorCode',null)
    ||private.retention_variance_blocking_details(p_project_id,p_origin_ids);
end;
$$;


ALTER FUNCTION "public"."check_retention_variance_blocks"("p_project_id" "uuid", "p_origin_ids" "uuid"[]) OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."organization_accounting_revision_attempts" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "accounting_revision_id" "uuid" NOT NULL,
    "attempt_sequence" integer NOT NULL,
    "attempt_intent" "text" NOT NULL,
    "queue_state" "text" DEFAULT 'queued'::"text" NOT NULL,
    "idempotency_key" "text" NOT NULL,
    "request_evidence" "jsonb" NOT NULL,
    "response_evidence" "jsonb",
    "worker_id" "text",
    "lease_token" "uuid",
    "lease_expires_at" timestamp with time zone,
    "heartbeat_at" timestamp with time zone,
    "started_at" timestamp with time zone,
    "completed_at" timestamp with time zone,
    "outcome_code" "text",
    "outcome_message" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "accounting_revision_attempt_intent_check" CHECK (("attempt_intent" = ANY (ARRAY['create'::"text", 'update'::"text", 'amend'::"text", 'credit'::"text", 'void'::"text", 'replace'::"text", 'attach'::"text"]))),
    CONSTRAINT "accounting_revision_attempt_lease_shape_check" CHECK (((("queue_state" = 'claimed'::"text") AND (NULLIF(TRIM(BOTH FROM "worker_id"), ''::"text") IS NOT NULL) AND ("lease_token" IS NOT NULL) AND ("lease_expires_at" IS NOT NULL) AND ("started_at" IS NOT NULL)) OR ("queue_state" <> 'claimed'::"text"))),
    CONSTRAINT "accounting_revision_attempt_request_check" CHECK (("jsonb_typeof"("request_evidence") = 'object'::"text")),
    CONSTRAINT "accounting_revision_attempt_response_check" CHECK ((("response_evidence" IS NULL) OR ("jsonb_typeof"("response_evidence") = 'object'::"text"))),
    CONSTRAINT "accounting_revision_attempt_sequence_check" CHECK (("attempt_sequence" > 0)),
    CONSTRAINT "accounting_revision_attempt_state_check" CHECK (("queue_state" = ANY (ARRAY['queued'::"text", 'claimed'::"text", 'succeeded'::"text", 'failed'::"text", 'attention_required'::"text"]))),
    CONSTRAINT "accounting_revision_attempt_terminal_shape_check" CHECK (((("queue_state" = ANY (ARRAY['succeeded'::"text", 'failed'::"text", 'attention_required'::"text"])) AND ("completed_at" IS NOT NULL) AND ("response_evidence" IS NOT NULL) AND (NULLIF(TRIM(BOTH FROM "outcome_code"), ''::"text") IS NOT NULL)) OR (("queue_state" <> ALL (ARRAY['succeeded'::"text", 'failed'::"text", 'attention_required'::"text"])) AND ("completed_at" IS NULL))))
);

ALTER TABLE ONLY "public"."organization_accounting_revision_attempts" FORCE ROW LEVEL SECURITY;


ALTER TABLE "public"."organization_accounting_revision_attempts" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_accounting_revision_attempt_phase2b"("p_attempt_id" "uuid", "p_worker_id" "text", "p_lease_seconds" integer DEFAULT 120) RETURNS "public"."organization_accounting_revision_attempts"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_attempt public.organization_accounting_revision_attempts%rowtype;
begin
  if nullif(trim(p_worker_id), '') is null or p_lease_seconds not between 10 and 900 then
    raise exception 'Invalid accounting attempt lease request.';
  end if;
  select * into v_attempt
  from public.organization_accounting_revision_attempts a
  where a.id = p_attempt_id
    and (
      a.queue_state = 'queued'
      or (a.queue_state = 'claimed' and a.lease_expires_at < now())
    )
  for update skip locked;
  if not found then return null; end if;
  perform set_config('app.accounting_phase2a_lease_write', 'true', true);
  update public.organization_accounting_revision_attempts set
    queue_state = 'claimed', worker_id = trim(p_worker_id),
    lease_token = gen_random_uuid(),
    lease_expires_at = now() + make_interval(secs => p_lease_seconds),
    heartbeat_at = now(), started_at = coalesce(started_at, now()),
    updated_at = now()
  where id = p_attempt_id returning * into v_attempt;
  perform set_config('app.accounting_phase2a_lease_write', '', true);
  return v_attempt;
end;
$$;


ALTER FUNCTION "public"."claim_accounting_revision_attempt_phase2b"("p_attempt_id" "uuid", "p_worker_id" "text", "p_lease_seconds" integer) OWNER TO "postgres";


