ALTER TABLE "public"."cost_construction_intelligence_events" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_cost_construction_intelligence_batch"("p_limit" integer DEFAULT 25, "p_organization_id" "uuid" DEFAULT NULL::"uuid", "p_worker_id" "text" DEFAULT 'cost-construction-intelligence-worker'::"text", "p_lease_seconds" integer DEFAULT 600) RETURNS SETOF "public"."cost_construction_intelligence_events"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_now timestamptz := timezone('utc'::text, now());
  v_claim_expires_at timestamptz := v_now + make_interval(secs => greatest(p_lease_seconds, 30));
  v_token text := concat(coalesce(nullif(p_worker_id, ''), 'cost-construction-intelligence-worker'), ':', gen_random_uuid()::text);
begin
  return query
  with candidates as (
    select q.id as queue_id, q.event_id
    from public.cost_construction_intelligence_queue q
    where (p_organization_id is null or q.organization_id = p_organization_id)
      and (
        q.processing_status = 'pending'
        or (
          q.processing_status = 'retry_scheduled'
          and (q.retry_after is null or q.retry_after <= v_now)
        )
        or (
          q.processing_status = 'claimed'
          and q.claim_expires_at is not null
          and q.claim_expires_at <= v_now
        )
      )
    order by q.created_at asc
    limit greatest(p_limit, 1)
    for update skip locked
  ),
  claimed as (
    update public.cost_construction_intelligence_queue q
    set
      processing_status = 'claimed',
      attempt_count = q.attempt_count + 1,
      claim_token = v_token,
      claim_expires_at = v_claim_expires_at,
      updated_at = v_now
    from candidates
    where q.id = candidates.queue_id
    returning q.event_id, q.claim_token, q.claim_expires_at, q.attempt_count, q.max_attempts
  )
  select
    e.id,
    e.idempotency_key,
    e.organization_id,
    e.project_id,
    e.source_type,
    e.source_id,
    e.source_line_id,
    e.tradesstack_cost_code,
    e.tradesstack_cost_code_label,
    e.accounting_mapping_id,
    e.description,
    e.supplier_id,
    e.supplier_name_snapshot,
    e.quantity,
    e.unit,
    e.rate,
    e.amount,
    e.document_context,
    e.event_payload,
    e.ai_construction_intelligence,
    e.classification_status,
    e.classification_version,
    e.ai_provider,
    e.ai_model,
    e.ai_prompt_version,
    e.processed_at,
    e.error_code,
    e.error_message,
    e.created_at,
    e.updated_at
  from public.cost_construction_intelligence_events e
  join claimed c on c.event_id = e.id;
end;
$$;


ALTER FUNCTION "public"."claim_cost_construction_intelligence_batch"("p_limit" integer, "p_organization_id" "uuid", "p_worker_id" "text", "p_lease_seconds" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_document_storage_cleanup_jobs"("p_limit" integer, "p_worker_id" "text", "p_lease_seconds" integer DEFAULT 300) RETURNS TABLE("job_id" "uuid", "claim_token" "uuid", "organization_id" "uuid", "workspace_id" "uuid", "cleanup_batch_id" "uuid", "job_type" "text", "storage_bucket" "text", "storage_key" "text", "byte_size" bigint, "attempt_count" integer, "max_attempts" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'Service role required.'
      using errcode = '42501';
  end if;
  if p_limit < 1 or p_limit > 500
    or p_lease_seconds < 30 or p_lease_seconds > 3600
    or char_length(btrim(coalesce(p_worker_id, ''))) not between 1 and 120
  then
    raise exception 'Invalid cleanup claim request.';
  end if;

  return query
  with candidates as (
    select job.id
    from public.document_storage_cleanup_jobs job
    where (
      job.processing_status in ('pending', 'retry_scheduled')
      and job.available_at <= now()
    ) or (
      job.processing_status = 'claimed'
      and job.claim_expires_at <= now()
    )
    order by job.available_at, job.created_at, job.id
    for update skip locked
    limit p_limit
  ),
  claimed as (
    update public.document_storage_cleanup_jobs job
    set
      processing_status = 'claimed',
      attempt_count = job.attempt_count + 1,
      claimed_at = now(),
      claim_expires_at = now() + make_interval(secs => p_lease_seconds),
      claimed_by = btrim(p_worker_id),
      claim_token = gen_random_uuid(),
      last_error_code = null,
      last_error_message = null
    where job.id in (select candidate.id from candidates candidate)
    returning job.*
  )
  select
    claimed.id,
    claimed.claim_token,
    claimed.organization_id,
    claimed.workspace_id,
    claimed.cleanup_batch_id,
    claimed.job_type,
    claimed.storage_bucket,
    claimed.storage_key,
    claimed.byte_size,
    claimed.attempt_count,
    claimed.max_attempts
  from claimed
  order by claimed.available_at, claimed.created_at, claimed.id;
end;
$$;


ALTER FUNCTION "public"."claim_document_storage_cleanup_jobs"("p_limit" integer, "p_worker_id" "text", "p_lease_seconds" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_learning_review_batch"("p_limit" integer DEFAULT 5, "p_organization_id" "uuid" DEFAULT NULL::"uuid", "p_container_type" "text" DEFAULT NULL::"text", "p_worker_id" "text" DEFAULT NULL::"text", "p_lease_seconds" integer DEFAULT 900) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  claimed_rows jsonb := '[]'::jsonb;
  resolved_worker_id text;
  resolved_lease_seconds integer;
begin
  resolved_worker_id := coalesce(nullif(btrim(coalesce(p_worker_id, '')), ''), 'universal-construction-learning-worker');
  resolved_lease_seconds := greatest(coalesce(p_lease_seconds, 900), 30);

  with candidate_rows as (
    select q.id
    from public.learning_review_queue q
    where (p_organization_id is null or q.organization_id = p_organization_id)
      and (p_container_type is null or q.container_type = p_container_type)
      and q.attempt_count < q.max_attempts
      and q.available_at <= now()
      and q.queue_state in ('pending', 'claimed', 'retry_scheduled')
      and (
        q.queue_state <> 'claimed'
        or q.claim_expires_at is null
        or q.claim_expires_at <= now()
      )
    order by
      q.priority desc,
      (q.attempt_count = 0) desc,
      case when q.attempt_count = 0 then q.created_at end desc,
      case when q.attempt_count > 0 then q.available_at end asc,
      q.created_at asc
    limit greatest(coalesce(p_limit, 5), 1)
    for update skip locked
  ),
  claimed as (
    update public.learning_review_queue q
    set
      queue_state = 'claimed',
      attempt_count = q.attempt_count + 1,
      claimed_at = now(),
      claim_expires_at = now() + make_interval(secs => resolved_lease_seconds),
      claimed_by = resolved_worker_id,
      claim_token = gen_random_uuid(),
      updated_at = now()
    from candidate_rows c
    where q.id = c.id
    returning q.*
  )
  select coalesce(jsonb_agg(
    jsonb_build_object(
      'id', c.id,
      'organizationId', c.organization_id,
      'containerType', c.container_type,
      'reviewMonth', c.review_month,
      'scopeKey', c.scope_key,
      'queueState', c.queue_state,
      'priority', c.priority,
      'attemptCount', c.attempt_count,
      'maxAttempts', c.max_attempts,
      'availableAt', c.available_at,
      'retryAfter', c.retry_after,
      'claimedAt', c.claimed_at,
      'claimExpiresAt', c.claim_expires_at,
      'claimedBy', c.claimed_by,
      'claimToken', c.claim_token,
      'lastRunId', c.last_run_id,
      'lastErrorCode', c.last_error_code,
      'lastErrorMessage', c.last_error_message,
      'lastCompletedAt', c.last_completed_at,
      'eligibilitySnapshot', c.eligibility_snapshot,
      'budgetSnapshot', c.budget_snapshot,
      'createdAt', c.created_at,
      'updatedAt', c.updated_at
    )
    order by c.priority desc, c.created_at asc
  ), '[]'::jsonb)
  into claimed_rows
  from claimed c;

  return claimed_rows;
end;
$$;


ALTER FUNCTION "public"."claim_learning_review_batch"("p_limit" integer, "p_organization_id" "uuid", "p_container_type" "text", "p_worker_id" "text", "p_lease_seconds" integer) OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."organization_material_import_jobs" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "import_batch_id" "uuid" NOT NULL,
    "run_id" "uuid" NOT NULL,
    "state" "text" DEFAULT 'queued'::"text" NOT NULL,
    "attempt_count" integer DEFAULT 0 NOT NULL,
    "max_attempts" integer DEFAULT 3 NOT NULL,
    "run_after" timestamp with time zone DEFAULT "now"() NOT NULL,
    "lease_owner" "text",
    "lease_token" "uuid",
    "lease_expires_at" timestamp with time zone,
    "heartbeat_at" timestamp with time zone,
    "cancel_requested_at" timestamp with time zone,
    "last_error_code" "text",
    "last_error_message" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "organization_material_import_jobs_attempts_check" CHECK ((("attempt_count" >= 0) AND (("max_attempts" >= 1) AND ("max_attempts" <= 10)))),
    CONSTRAINT "organization_material_import_jobs_state_check" CHECK (("state" = ANY (ARRAY['queued'::"text", 'processing'::"text", 'completed'::"text", 'failed'::"text", 'cancelled'::"text"])))
);


ALTER TABLE "public"."organization_material_import_jobs" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_material_import_job"("p_worker_id" "text", "p_lease_seconds" integer DEFAULT 120) RETURNS SETOF "public"."organization_material_import_jobs"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_job public.organization_material_import_jobs%rowtype;
begin
  if auth.role() <> 'service_role' then
    raise exception 'service_role required' using errcode = '42501';
  end if;

  select * into v_job
  from public.organization_material_import_jobs
  where (
      state = 'queued'
      or (state = 'processing' and lease_expires_at < now())
    )
    and run_after <= now()
    and cancel_requested_at is null
    and attempt_count < max_attempts
  order by run_after asc, created_at asc
  for update skip locked
  limit 1;

  if not found then return; end if;

  update public.organization_material_import_jobs
  set state = 'processing',
      attempt_count = attempt_count + 1,
      lease_owner = p_worker_id,
      lease_token = gen_random_uuid(),
      lease_expires_at = now() + make_interval(secs => greatest(30, least(p_lease_seconds, 900))),
      heartbeat_at = now()
  where id = v_job.id
  returning * into v_job;

  return next v_job;
end;
$$;


ALTER FUNCTION "public"."claim_material_import_job"("p_worker_id" "text", "p_lease_seconds" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_material_import_job_v2"("p_worker_id" "text", "p_lease_seconds" integer DEFAULT 120, "p_job_id" "uuid" DEFAULT NULL::"uuid") RETURNS SETOF "public"."organization_material_import_jobs"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_job public.organization_material_import_jobs%rowtype;
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'service_role required' using errcode = '42501';
  end if;

  select * into v_job
  from public.organization_material_import_jobs
  where (
      state = 'queued'
      or (state = 'processing' and lease_expires_at < now())
    )
    and (p_job_id is null or id = p_job_id)
    and run_after <= now()
    and cancel_requested_at is null
    and attempt_count < max_attempts
  order by run_after asc, created_at asc
  for update skip locked
  limit 1;

  if not found then return; end if;

  update public.organization_material_import_jobs
  set state = 'processing',
      attempt_count = attempt_count + 1,
      lease_owner = p_worker_id,
      lease_token = gen_random_uuid(),
      lease_expires_at = now() + make_interval(secs => greatest(30, least(p_lease_seconds, 900))),
      heartbeat_at = now()
  where id = v_job.id
  returning * into v_job;

  return next v_job;
end;
$$;


