CREATE TABLE IF NOT EXISTS "public"."material_source_cleanup_jobs" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "batch_id" "uuid" NOT NULL,
    "storage_path" "text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "lease_token" "uuid",
    "lease_expires_at" timestamp with time zone,
    "attempt_count" integer DEFAULT 0 NOT NULL,
    "next_attempt_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "completed_at" timestamp with time zone,
    "dead_lettered_at" timestamp with time zone,
    "last_error" "text"
);

ALTER TABLE ONLY "public"."material_source_cleanup_jobs" FORCE ROW LEVEL SECURITY;


ALTER TABLE "public"."material_source_cleanup_jobs" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_material_source_cleanup_v1"("p_limit" integer DEFAULT 25) RETURNS SETOF "public"."material_source_cleanup_jobs"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if auth.role() is distinct from 'service_role' then raise exception 'service_role required' using errcode='42501'; end if;
  insert into public.material_source_cleanup_jobs(batch_id,storage_path)
  select b.id,b.storage_path from public.organization_material_import_batches b
  where b.storage_path is not null and b.source_deleted_at is null and b.source_retention_until<=now()
    and not exists(select 1 from public.material_source_cleanup_jobs c where c.batch_id=b.id)
    and b.status in ('ready_for_review','partially_approved','approved','failed','cancelled')
    and not exists(select 1 from public.organization_material_import_jobs j where j.import_batch_id=b.id and j.state in ('queued','processing'))
  order by b.source_retention_until,b.id limit greatest(1,least(coalesce(p_limit,25),100))
  for update of b skip locked on conflict(batch_id) do nothing;
  update public.material_source_cleanup_jobs set dead_lettered_at=now(),last_error='Cleanup retry limit reached.'
    where completed_at is null and dead_lettered_at is null and attempt_count>=5 and (lease_expires_at is null or lease_expires_at<now());
  return query with candidates as (
    select id from public.material_source_cleanup_jobs
    where completed_at is null and dead_lettered_at is null and next_attempt_at<=now()
      and (lease_expires_at is null or lease_expires_at<now())
    order by next_attempt_at,created_at,id for update skip locked limit greatest(1,least(coalesce(p_limit,25),100))
  ) update public.material_source_cleanup_jobs j set lease_token=gen_random_uuid(),lease_expires_at=now()+interval '5 minutes',attempt_count=j.attempt_count+1
    from candidates c where j.id=c.id returning j.*;
end; $$;


ALTER FUNCTION "public"."claim_material_source_cleanup_v1"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_next_accounting_revision_attempt_phase2a"("p_worker_id" "text", "p_lease_seconds" integer DEFAULT 60) RETURNS "public"."organization_accounting_revision_attempts"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare attempt public.organization_accounting_revision_attempts%rowtype;
begin
  if nullif(trim(p_worker_id), '') is null or p_lease_seconds not between 10 and 900 then
    raise exception 'Invalid accounting attempt lease request.';
  end if;
  select * into attempt
  from public.organization_accounting_revision_attempts a
  where a.queue_state = 'queued'
     or (a.queue_state = 'claimed' and a.lease_expires_at < now())
  order by a.created_at, a.id
  for update skip locked
  limit 1;
  if not found then return null; end if;

  perform set_config('app.accounting_phase2a_lease_write', 'true', true);
  update public.organization_accounting_revision_attempts set
    queue_state = 'claimed',
    worker_id = trim(p_worker_id),
    lease_token = gen_random_uuid(),
    lease_expires_at = now() + make_interval(secs => p_lease_seconds),
    heartbeat_at = now(),
    started_at = coalesce(started_at, now()),
    updated_at = now()
  where id = attempt.id returning * into attempt;
  perform set_config('app.accounting_phase2a_lease_write', '', true);
  return attempt;
end;
$$;


ALTER FUNCTION "public"."claim_next_accounting_revision_attempt_phase2a"("p_worker_id" "text", "p_lease_seconds" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_organization_memory_retirement_batch"("p_limit" integer DEFAULT 25, "p_organization_id" "uuid" DEFAULT NULL::"uuid", "p_memory_id" "uuid" DEFAULT NULL::"uuid", "p_worker_id" "text" DEFAULT NULL::"text", "p_lease_seconds" integer DEFAULT 600) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  claimed_rows jsonb := '[]'::jsonb;
  resolved_worker_id text;
  resolved_lease_seconds integer;
begin
  perform public.enqueue_organization_memory_retirement_queue(
    p_limit := greatest(coalesce(p_limit, 25), 1) * 4,
    p_organization_id := p_organization_id,
    p_memory_id := p_memory_id
  );

  resolved_worker_id := coalesce(nullif(btrim(coalesce(p_worker_id, '')), ''), 'organization-memory-retirement-runner');
  resolved_lease_seconds := greatest(coalesce(p_lease_seconds, 600), 30);

  with candidate_rows as (
    select q.id
    from public.organization_memory_retirement_queue q
    where (p_organization_id is null or q.organization_id = p_organization_id)
      and (p_memory_id is null or q.memory_id = p_memory_id)
      and q.attempt_count < q.max_attempts
      and q.available_at <= now()
      and q.queue_state in ('pending', 'claimed', 'retry_scheduled')
      and (
        q.queue_state <> 'claimed'
        or q.claim_expires_at is null
        or q.claim_expires_at <= now()
      )
    order by
      q.priority desc,
      (q.attempt_count = 0) desc,
      case when q.attempt_count = 0 then q.created_at end desc,
      case when q.attempt_count > 0 then q.available_at end asc,
      q.created_at asc
    limit greatest(coalesce(p_limit, 25), 1)
    for update skip locked
  ),
  claimed as (
    update public.organization_memory_retirement_queue q
    set
      queue_state = 'claimed',
      attempt_count = q.attempt_count + 1,
      claimed_at = now(),
      claim_expires_at = now() + make_interval(secs => resolved_lease_seconds),
      claimed_by = resolved_worker_id,
      claim_token = gen_random_uuid(),
      last_attempt_at = now(),
      updated_at = now()
    from candidate_rows c
    where q.id = c.id
    returning q.*
  )
  select coalesce(jsonb_agg(
    jsonb_build_object(
      'id', c.id,
      'organizationId', c.organization_id,
      'memoryId', c.memory_id,
      'queueState', c.queue_state,
      'attemptCount', c.attempt_count,
      'maxAttempts', c.max_attempts,
      'priority', c.priority,
      'availableAt', c.available_at,
      'retryAfter', c.retry_after,
      'claimedAt', c.claimed_at,
      'claimExpiresAt', c.claim_expires_at,
      'claimedBy', c.claimed_by,
      'claimToken', c.claim_token,
      'lastErrorCode', c.last_error_code,
      'lastErrorMessage', c.last_error_message,
      'lastNoActionReason', c.last_no_action_reason,
      'createdAt', c.created_at,
      'updatedAt', c.updated_at
    )
    order by c.priority desc, c.created_at asc
  ), '[]'::jsonb)
  into claimed_rows
  from claimed c;

  return claimed_rows;
end;
$$;


ALTER FUNCTION "public"."claim_organization_memory_retirement_batch"("p_limit" integer, "p_organization_id" "uuid", "p_memory_id" "uuid", "p_worker_id" "text", "p_lease_seconds" integer) OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."project_qa_evidence_cleanup_jobs" (
