    "dead_lettered_at" timestamp with time zone,
    CONSTRAINT "project_qa_evidence_cleanup_attempt_check" CHECK (("attempt_count" >= 0)),
    CONSTRAINT "project_qa_evidence_cleanup_reason_check" CHECK (("reason" = ANY (ARRAY['abandoned'::"text", 'expired'::"text", 'removed'::"text"])))
);

ALTER TABLE ONLY "public"."project_qa_evidence_cleanup_jobs" FORCE ROW LEVEL SECURITY;


