CREATE OR REPLACE FUNCTION "public"."claim_project_qa_cleanup_jobs_v1"("p_limit" integer DEFAULT 25) RETURNS SETOF "public"."project_qa_evidence_cleanup_jobs"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if auth.role() is distinct from 'service_role' then raise exception 'service_role required' using errcode='42501'; end if;
  update public.project_qa_evidence_cleanup_jobs set dead_lettered_at=now(),last_error='Cleanup retry limit reached.'
    where completed_at is null and dead_lettered_at is null and attempt_count>=5 and (lease_expires_at is null or lease_expires_at<now());
  return query
  with candidates as (
    select j.id from public.project_qa_evidence_cleanup_jobs j
    where j.completed_at is null and j.dead_lettered_at is null
      and j.next_attempt_at <= now() and j.created_at <= now() - interval '1 hour'
      and (j.lease_expires_at is null or j.lease_expires_at < now())
      and j.storage_bucket = 'project-qa-evidence'
      and not exists (select 1 from public.project_qa_response_evidence e where e.storage_path=j.storage_path)
      and not exists (select 1 from public.project_qa_evidence_uploads u where u.storage_path=j.storage_path and u.status='pending')
    order by j.next_attempt_at,j.created_at,j.id
    for update of j skip locked limit greatest(1,least(coalesce(p_limit,25),100))
  )
  update public.project_qa_evidence_cleanup_jobs j
  set lease_token=gen_random_uuid(), lease_expires_at=now()+interval '5 minutes', attempt_count=j.attempt_count+1
  from candidates c where j.id=c.id returning j.*;
end; $$;


ALTER FUNCTION "public"."claim_project_qa_cleanup_jobs_v1"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_retention_variance_scan_batch"("p_limit" integer DEFAULT 25, "p_worker_id" "text" DEFAULT 'retention-variance-scanner'::"text", "p_lease_seconds" integer DEFAULT 600, "p_organization_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare token uuid:=gen_random_uuid(); rows jsonb;
begin
  if auth.role()<>'service_role' then
    return jsonb_build_object('succeeded',false,'errorCode','permission_denied');
  end if;
  with candidates as (
    select q.id from public.retention_variance_scan_queue q
    where (p_organization_id is null or q.organization_id=p_organization_id)
      and q.attempt_count<q.max_attempts and q.available_at<=now()
      and q.queue_state in ('pending','claimed','retry_scheduled')
      and (q.queue_state<>'claimed' or q.claim_expires_at is null or q.claim_expires_at<=now())
    order by q.priority desc,q.available_at,q.project_id
    limit least(greatest(coalesce(p_limit,25),1),100)
    for update skip locked
  ), claimed as (
    update public.retention_variance_scan_queue q set
      queue_state='claimed',attempt_count=attempt_count+1,claimed_at=now(),
      claim_expires_at=now()+make_interval(secs=>greatest(coalesce(p_lease_seconds,600),30)),
      claimed_by=coalesce(nullif(trim(p_worker_id),''),'retention-variance-scanner'),
      claim_token=token,last_attempt_at=now(),updated_at=now()
    from candidates c where q.id=c.id returning q.*
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'id',id,'organizationId',organization_id,'projectId',project_id,
    'attemptCount',attempt_count,'maxAttempts',max_attempts,
    'claimToken',claim_token,'claimExpiresAt',claim_expires_at
  ) order by project_id),'[]'::jsonb) into rows from claimed;
  return jsonb_build_object('succeeded',true,'errorCode',null,
    'claimToken',token,'projects',rows);
end;
$$;


ALTER FUNCTION "public"."claim_retention_variance_scan_batch"("p_limit" integer, "p_worker_id" "text", "p_lease_seconds" integer, "p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_supplier_bill_ucl_refresh_batch"("p_limit" integer DEFAULT 10, "p_organization_id" "uuid" DEFAULT NULL::"uuid", "p_worker_id" "text" DEFAULT NULL::"text", "p_lease_seconds" integer DEFAULT 900) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  result jsonb;
  resolved_worker text :=
    coalesce(nullif(btrim(coalesce(p_worker_id, '')), ''), 'supplier-bill-ucl-refresh-worker');
  resolved_lease_seconds integer := least(greatest(coalesce(p_lease_seconds, 900), 30), 3600);
begin
  with candidates as (
    select q.id
    from public.supplier_bill_ucl_refresh_queue q
    where (p_organization_id is null or q.organization_id = p_organization_id)
      and q.attempt_count < q.max_attempts
      and q.available_at <= now()
      and (
        q.queue_state in ('pending', 'retry_wait')
        or (
          q.queue_state = 'leased'
          and (q.lease_expires_at is null or q.lease_expires_at <= now())
        )
      )
    order by q.priority desc, q.first_requested_at asc, q.source_id asc
    limit least(greatest(coalesce(p_limit, 10), 1), 100)
    for update skip locked
  ),
  claimed as (
    update public.supplier_bill_ucl_refresh_queue q
    set
      queue_state = 'leased',
      attempt_count = q.attempt_count + 1,
      lease_owner = resolved_worker,
      lease_token = gen_random_uuid(),
      leased_at = now(),
      lease_expires_at = now() + make_interval(secs => resolved_lease_seconds),
      updated_at = now()
    from candidates c
    where q.id = c.id
    returning q.*
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'id', c.id,
    'organizationId', c.organization_id,
    'containerType', c.container_type,
    'sourceId', c.source_id,
    'reasonCode', c.reason_code,
    'priority', c.priority,
    'queueState', c.queue_state,
    'attemptCount', c.attempt_count,
    'maxAttempts', c.max_attempts,
    'availableAt', c.available_at,
    'leaseOwner', c.lease_owner,
    'leaseToken', c.lease_token,
    'leaseExpiresAt', c.lease_expires_at,
    'firstRequestedAt', c.first_requested_at,
    'lastRequestedAt', c.last_requested_at,
    'deletionEvidenceAt', c.deletion_evidence_at,
    'contentHash', c.content_hash,
    'schemaVersion', c.schema_version,
    'builderVersion', c.builder_version
  ) order by c.priority desc, c.first_requested_at asc, c.source_id asc), '[]'::jsonb)
  into result
  from claimed c;

  return result;
end;
$$;


ALTER FUNCTION "public"."claim_supplier_bill_ucl_refresh_batch"("p_limit" integer, "p_organization_id" "uuid", "p_worker_id" "text", "p_lease_seconds" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_worksheet_event_classification_batch"("p_limit" integer DEFAULT 25, "p_classification_version" integer DEFAULT 1, "p_organization_id" "uuid" DEFAULT NULL::"uuid", "p_worker_id" "text" DEFAULT NULL::"text", "p_lease_seconds" integer DEFAULT 600) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  claimed_events jsonb := '[]'::jsonb;
  resolved_worker_id text;
  resolved_lease_seconds integer;
begin
  perform public.enqueue_worksheet_event_classification_queue(
    p_limit := greatest(coalesce(p_limit, 25), 1) * 4,
    p_classification_version := greatest(coalesce(p_classification_version, 1), 1),
    p_organization_id := p_organization_id
  );

  resolved_worker_id := coalesce(nullif(btrim(coalesce(p_worker_id, '')), ''), 'worksheet-event-classification-runner');
  resolved_lease_seconds := greatest(coalesce(p_lease_seconds, 600), 30);

  with candidate_rows as (
    select q.id
    from public.worksheet_event_classification_queue q
    join public.intelligence_events e
      on e.id = q.source_event_id
     and e.organization_id = q.organization_id
    where q.classification_version = greatest(coalesce(p_classification_version, 1), 1)
      and (p_organization_id is null or q.organization_id = p_organization_id)
      and q.attempt_count < q.max_attempts
      and q.available_at <= now()
      and q.queue_state in ('pending', 'claimed', 'retry_scheduled')
      and (
        q.queue_state <> 'claimed'
        or q.claim_expires_at is null
        or q.claim_expires_at <= now()
      )
      and e.module = 'pricing_worksheets'
      and e.event_type in (
        'worksheet_cell_edited',
        'worksheet_formula_edited',
        'worksheet_rate_changed',
        'worksheet_assumption_changed',
        'worksheet_ai_rate_corrected',
        'worksheet_ai_assumption_corrected',
        'worksheet_ai_formula_corrected',
        'worksheet_ai_output_corrected'
      )
      and coalesce(e.diff_data->>'classificationStatus', '') = 'pending'
      and coalesce(nullif(e.diff_data->>'rawContextVersion', '')::integer, 1) = 1
    order by
      (q.attempt_count = 0) desc,
      case when q.attempt_count = 0 then e.occurred_at end desc,
      case when q.attempt_count = 0 then e.created_at end desc,
      case when q.attempt_count > 0 then q.available_at end asc,
      case when q.attempt_count > 0 then e.occurred_at end asc,
      case when q.attempt_count > 0 then e.created_at end asc
    limit greatest(coalesce(p_limit, 25), 1)
    for update of q skip locked
  ),
  claimed as (
    update public.worksheet_event_classification_queue q
    set
      queue_state = 'claimed',
      attempt_count = q.attempt_count + 1,
      claimed_at = now(),
      claim_expires_at = now() + make_interval(secs => resolved_lease_seconds),
      claimed_by = resolved_worker_id,
      claim_token = gen_random_uuid(),
      last_attempt_at = now(),
      updated_at = now()
    from candidate_rows c
    where q.id = c.id
    returning
      q.id,
      q.source_event_id,
      q.organization_id,
      q.classification_version,
      q.attempt_count as attempt_number,
      q.claim_token,
      q.claim_expires_at
  )
  select coalesce(jsonb_agg(
    jsonb_build_object(
      'queueId', c.id,
      'eventId', e.id,
      'organizationId', e.organization_id,
      'projectId', e.project_id,
      'opportunityId', e.opportunity_id,
      'eventType', e.event_type,
      'occurredAt', e.occurred_at,
      'metadata', e.metadata,
      'diffData', e.diff_data,
      'classificationVersion', c.classification_version,
      'attemptNumber', c.attempt_number,
      'claimToken', c.claim_token,
      'claimExpiresAt', c.claim_expires_at
    )
    order by e.occurred_at asc
  ), '[]'::jsonb)
  into claimed_events
  from claimed c
  join public.intelligence_events e
    on e.id = c.source_event_id
   and e.organization_id = c.organization_id;

  return claimed_events;
end;
$$;


ALTER FUNCTION "public"."claim_worksheet_event_classification_batch"("p_limit" integer, "p_classification_version" integer, "p_organization_id" "uuid", "p_worker_id" "text", "p_lease_seconds" integer) OWNER TO "postgres";


