CREATE OR REPLACE FUNCTION "public"."claim_worksheet_memory_semantic_pool_batch"("p_limit" integer DEFAULT 25, "p_organization_id" "uuid" DEFAULT NULL::"uuid", "p_worker_id" "text" DEFAULT NULL::"text", "p_lease_seconds" integer DEFAULT 600) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  claimed_rows jsonb := '[]'::jsonb;
  resolved_worker_id text;
  resolved_lease_seconds integer;
begin
  perform public.enqueue_worksheet_memory_semantic_pool_queue(
    p_limit := greatest(coalesce(p_limit, 25), 1) * 4,
    p_organization_id := p_organization_id
  );

  resolved_worker_id := coalesce(nullif(btrim(coalesce(p_worker_id, '')), ''), 'worksheet-memory-semantic-pool-runner');
  resolved_lease_seconds := greatest(coalesce(p_lease_seconds, 600), 30);

  with candidate_rows as (
    select q.id
    from public.worksheet_memory_semantic_pool_queue q
    where (p_organization_id is null or q.organization_id = p_organization_id)
      and q.attempt_count < q.max_attempts
      and q.available_at <= now()
      and q.queue_state in ('pending', 'claimed', 'retry_scheduled')
      and (
        q.queue_state <> 'claimed'
        or q.claim_expires_at is null
        or q.claim_expires_at <= now()
      )
    order by
      q.priority desc,
      (q.attempt_count = 0) desc,
      case when q.attempt_count = 0 then q.created_at end desc,
      case when q.attempt_count > 0 then q.available_at end asc,
      q.created_at asc
    limit greatest(coalesce(p_limit, 25), 1)
    for update skip locked
  ),
  claimed as (
    update public.worksheet_memory_semantic_pool_queue q
    set
      queue_state = 'claimed',
      attempt_count = q.attempt_count + 1,
      claimed_at = now(),
      claim_expires_at = now() + make_interval(secs => resolved_lease_seconds),
      claimed_by = resolved_worker_id,
      claim_token = gen_random_uuid(),
      last_attempt_at = now(),
      updated_at = now()
    from candidate_rows c
    where q.id = c.id
    returning q.*
  )
  select coalesce(jsonb_agg(
    jsonb_build_object(
      'id', c.id,
      'organizationId', c.organization_id,
      'seedPoolId', c.seed_pool_id,
      'seedPoolSignature', c.seed_pool_signature,
      'seedPoolRevisionHash', c.seed_pool_revision_hash,
      'seedMaturityStatus', c.seed_maturity_status,
      'queueState', c.queue_state,
      'attemptCount', c.attempt_count,
      'maxAttempts', c.max_attempts,
      'priority', c.priority,
      'availableAt', c.available_at,
      'retryAfter', c.retry_after,
      'claimedAt', c.claimed_at,
      'claimExpiresAt', c.claim_expires_at,
      'claimedBy', c.claimed_by,
      'claimToken', c.claim_token,
      'lastErrorCode', c.last_error_code,
      'lastErrorMessage', c.last_error_message,
      'createdAt', c.created_at,
      'updatedAt', c.updated_at
    )
    order by c.priority desc, c.created_at asc
  ), '[]'::jsonb)
  into claimed_rows
  from claimed c;

  return claimed_rows;
end;
$$;


ALTER FUNCTION "public"."claim_worksheet_memory_semantic_pool_batch"("p_limit" integer, "p_organization_id" "uuid", "p_worker_id" "text", "p_lease_seconds" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_worksheet_memory_synthesis_batch"("p_limit" integer DEFAULT 25, "p_organization_id" "uuid" DEFAULT NULL::"uuid", "p_worker_id" "text" DEFAULT NULL::"text", "p_lease_seconds" integer DEFAULT 600, "p_semantic_pool_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  claimed_rows jsonb := '[]'::jsonb;
  resolved_worker_id text;
  resolved_lease_seconds integer;
begin
  perform public.enqueue_worksheet_memory_synthesis_queue(
    p_limit := greatest(coalesce(p_limit, 25), 1) * 4,
    p_organization_id := p_organization_id,
    p_semantic_pool_id := p_semantic_pool_id
  );

  resolved_worker_id := coalesce(nullif(btrim(coalesce(p_worker_id, '')), ''), 'worksheet-memory-synthesis-runner');
  resolved_lease_seconds := greatest(coalesce(p_lease_seconds, 600), 30);

  with candidate_rows as (
    select q.id
    from public.worksheet_memory_synthesis_queue q
    where (p_organization_id is null or q.organization_id = p_organization_id)
      and (p_semantic_pool_id is null or q.semantic_pool_id = p_semantic_pool_id)
      and q.attempt_count < q.max_attempts
      and q.available_at <= now()
      and q.queue_state in ('pending', 'claimed', 'retry_scheduled')
      and (
        q.queue_state <> 'claimed'
        or q.claim_expires_at is null
        or q.claim_expires_at <= now()
      )
    order by
      q.priority desc,
      (q.attempt_count = 0) desc,
      case when q.attempt_count = 0 then q.created_at end desc,
      case when q.attempt_count > 0 then q.available_at end asc,
      q.created_at asc
    limit case
      when p_semantic_pool_id is null then greatest(coalesce(p_limit, 25), 1)
      else 1
    end
    for update skip locked
  ),
  claimed as (
    update public.worksheet_memory_synthesis_queue q
    set
      queue_state = 'claimed',
      attempt_count = q.attempt_count + 1,
      claimed_at = now(),
      claim_expires_at = now() + make_interval(secs => resolved_lease_seconds),
      claimed_by = resolved_worker_id,
      claim_token = gen_random_uuid(),
      last_attempt_at = now(),
      updated_at = now()
    from candidate_rows c
    where q.id = c.id
    returning q.*
  )
  select coalesce(jsonb_agg(
    jsonb_build_object(
      'id', c.id,
      'organizationId', c.organization_id,
      'semanticPoolId', c.semantic_pool_id,
      'semanticPoolSignature', c.semantic_pool_signature,
      'sourceRevisionHash', c.source_revision_hash,
      'maturityStatus', c.maturity_status,
      'queueState', c.queue_state,
      'attemptCount', c.attempt_count,
      'maxAttempts', c.max_attempts,
      'priority', c.priority,
      'availableAt', c.available_at,
      'retryAfter', c.retry_after,
      'claimedAt', c.claimed_at,
      'claimExpiresAt', c.claim_expires_at,
      'claimedBy', c.claimed_by,
      'claimToken', c.claim_token,
      'lastErrorCode', c.last_error_code,
      'lastErrorMessage', c.last_error_message,
      'createdAt', c.created_at,
      'updatedAt', c.updated_at
    )
    order by c.priority desc, c.created_at asc
  ), '[]'::jsonb)
  into claimed_rows
  from claimed c;

  return claimed_rows;
end;
$$;


ALTER FUNCTION "public"."claim_worksheet_memory_synthesis_batch"("p_limit" integer, "p_organization_id" "uuid", "p_worker_id" "text", "p_lease_seconds" integer, "p_semantic_pool_id" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."worksheet_mutation_evidence_v2_outbox" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "project_id" "uuid",
    "opportunity_id" "uuid" NOT NULL,
    "workbook_id" "uuid" NOT NULL,
    "workbook_name" "text",
    "sheet_id" "uuid" NOT NULL,
    "sheet_name" "text" NOT NULL,
    "worksheet_id" "uuid" NOT NULL,
    "worksheet_name" "text" NOT NULL,
    "trade_package" "text",
    "user_id" "uuid",
    "source" "text" DEFAULT 'manual'::"text" NOT NULL,
    "client_mutation_id" "text" NOT NULL,
    "occurred_at" timestamp with time zone NOT NULL,
    "previous_worksheet" "jsonb" NOT NULL,
    "next_worksheet" "jsonb" NOT NULL,
    "processing_status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "attempt_count" integer DEFAULT 0 NOT NULL,
    "max_attempts" integer DEFAULT 5 NOT NULL,
    "claimed_at" timestamp with time zone,
    "claim_expires_at" timestamp with time zone,
    "claimed_by" "text",
    "claim_token" "uuid",
    "retry_after" timestamp with time zone,
    "last_error_code" "text",
    "last_error_message" "text",
    "processed_at" timestamp with time zone,
    "dead_lettered_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "worksheet_mutation_evidence_v2_outbox_attempt_count_check" CHECK (("attempt_count" >= 0)),
    CONSTRAINT "worksheet_mutation_evidence_v2_outbox_client_mutation_id_not_bl" CHECK (("char_length"(TRIM(BOTH FROM "client_mutation_id")) > 0)),
    CONSTRAINT "worksheet_mutation_evidence_v2_outbox_max_attempts_check" CHECK (("max_attempts" >= 1)),
    CONSTRAINT "worksheet_mutation_evidence_v2_outbox_next_worksheet_object_che" CHECK (("jsonb_typeof"("next_worksheet") = 'object'::"text")),
    CONSTRAINT "worksheet_mutation_evidence_v2_outbox_previous_worksheet_object" CHECK (("jsonb_typeof"("previous_worksheet") = 'object'::"text")),
    CONSTRAINT "worksheet_mutation_evidence_v2_outbox_processing_status_check" CHECK (("processing_status" = ANY (ARRAY['pending'::"text", 'claimed'::"text", 'completed'::"text", 'retry_scheduled'::"text", 'dead_lettered'::"text"]))),
    CONSTRAINT "worksheet_mutation_evidence_v2_outbox_sheet_name_not_blank" CHECK (("char_length"(TRIM(BOTH FROM "sheet_name")) > 0)),
    CONSTRAINT "worksheet_mutation_evidence_v2_outbox_source_check" CHECK (("source" = ANY (ARRAY['manual'::"text", 'ai'::"text", 'system'::"text"]))),
    CONSTRAINT "worksheet_mutation_evidence_v2_outbox_worksheet_name_not_blank" CHECK (("char_length"(TRIM(BOTH FROM "worksheet_name")) > 0))
);

ALTER TABLE ONLY "public"."worksheet_mutation_evidence_v2_outbox" FORCE ROW LEVEL SECURITY;


ALTER TABLE "public"."worksheet_mutation_evidence_v2_outbox" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_worksheet_mutation_evidence_v2_outbox_batch"("p_limit" integer DEFAULT 25, "p_organization_id" "uuid" DEFAULT NULL::"uuid", "p_worker_id" "text" DEFAULT NULL::"text", "p_lease_seconds" integer DEFAULT 600) RETURNS SETOF "public"."worksheet_mutation_evidence_v2_outbox"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  resolved_limit integer;
  resolved_worker_id text;
  resolved_lease_seconds integer;
begin
  resolved_limit := greatest(coalesce(p_limit, 25), 1);
  resolved_worker_id := coalesce(nullif(btrim(coalesce(p_worker_id, '')), ''), 'worksheet-mutation-evidence-v2-worker');
  resolved_lease_seconds := greatest(coalesce(p_lease_seconds, 600), 30);

  return query
  with claimable as (
    select outbox.id
    from public.worksheet_mutation_evidence_v2_outbox outbox
    where (p_organization_id is null or outbox.organization_id = p_organization_id)
      and (
        outbox.processing_status = 'pending'
        or (
          outbox.processing_status = 'retry_scheduled'
          and (outbox.retry_after is null or outbox.retry_after <= now())
        )
        or (
          outbox.processing_status = 'claimed'
          and outbox.claim_expires_at is not null
          and outbox.claim_expires_at <= now()
        )
      )
    order by outbox.occurred_at asc, outbox.created_at asc, outbox.id asc
    limit resolved_limit
    for update skip locked
  )
  update public.worksheet_mutation_evidence_v2_outbox outbox
  set
    processing_status = 'claimed',
    attempt_count = outbox.attempt_count + 1,
    claimed_at = now(),
    claim_expires_at = now() + make_interval(secs => resolved_lease_seconds),
    claimed_by = resolved_worker_id,
    claim_token = gen_random_uuid(),
    retry_after = null,
    updated_at = now()
  where outbox.id in (select id from claimable)
  returning outbox.*;
end;
$$;


ALTER FUNCTION "public"."claim_worksheet_mutation_evidence_v2_outbox_batch"("p_limit" integer, "p_organization_id" "uuid", "p_worker_id" "text", "p_lease_seconds" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_worksheet_pricing_pattern_evidence_processing_batch"("p_limit" integer DEFAULT 100, "p_organization_id" "uuid" DEFAULT NULL::"uuid", "p_source_event_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_worker_id" "text" DEFAULT NULL::"text", "p_processing_run_id" "uuid" DEFAULT NULL::"uuid", "p_lease_seconds" integer DEFAULT 600) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  claimed_rows jsonb := '[]'::jsonb;
  resolved_worker_id text;
  resolved_lease_seconds integer;
begin
  resolved_worker_id := coalesce(nullif(btrim(coalesce(p_worker_id, '')), ''), 'worksheet-pricing-pattern-shadow-runner');
  resolved_lease_seconds := greatest(coalesce(p_lease_seconds, 600), 30);

  with candidate_rows as (
    select q.id
    from public.worksheet_pricing_pattern_evidence_processing q
    where (p_organization_id is null or q.organization_id = p_organization_id)
      and (p_source_event_ids is null or q.source_event_id = any(p_source_event_ids))
      and q.attempt_count < q.max_attempts
      and (
        q.processing_status = 'pending'
        or (
          q.processing_status = 'retry_scheduled'
          and (q.retry_after is null or q.retry_after <= now())
        )
        or (
          q.processing_status = 'claimed'
          and (q.claim_expires_at is null or q.claim_expires_at <= now())
        )
      )
    order by
      (q.attempt_count = 0) desc,
      case when q.attempt_count = 0 then q.created_at end desc,
      case when q.attempt_count > 0 then q.retry_after end asc,
      q.created_at asc
    limit greatest(coalesce(p_limit, 100), 1)
    for update skip locked
  ),
  claimed as (
    update public.worksheet_pricing_pattern_evidence_processing q
    set
      processing_status = 'claimed',
      attempt_count = q.attempt_count + 1,
      processing_run_id = coalesce(p_processing_run_id, q.processing_run_id),
      claimed_at = now(),
      claim_expires_at = now() + make_interval(secs => resolved_lease_seconds),
      claimed_by = resolved_worker_id,
      claim_token = gen_random_uuid(),
      failed_at = null,
      updated_at = now()
    from candidate_rows c
    where q.id = c.id
    returning q.*
  )
  select coalesce(jsonb_agg(
    jsonb_build_object(
      'rowId', c.id,
      'organizationId', c.organization_id,
      'sourceEventId', c.source_event_id,
      'classificationRecordId', c.classification_record_id,
      'classificationVersion', c.classification_version,
      'classificationAttemptNumber', c.classification_attempt_number,
      'attemptCount', c.attempt_count,
      'maxAttempts', c.max_attempts,
      'processingStatus', c.processing_status,
      'processingRunId', c.processing_run_id,
      'claimedAt', c.claimed_at,
      'claimExpiresAt', c.claim_expires_at,
      'claimedBy', c.claimed_by,
      'claimToken', c.claim_token,
      'retryAfter', c.retry_after,
      'lastErrorCode', c.last_error_code,
      'lastErrorMessage', c.last_error_message,
      'createdAt', c.created_at,
      'updatedAt', c.updated_at
    )
    order by c.created_at asc
  ), '[]'::jsonb)
  into claimed_rows
  from claimed c;

  return claimed_rows;
end;
$$;


ALTER FUNCTION "public"."claim_worksheet_pricing_pattern_evidence_processing_batch"("p_limit" integer, "p_organization_id" "uuid", "p_source_event_ids" "uuid"[], "p_worker_id" "text", "p_processing_run_id" "uuid", "p_lease_seconds" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."classify_legacy_automatic_project_quote_draft_v1"("p_organization_id" "uuid", "p_quote_id" "uuid") RETURNS TABLE("manifest_linked" boolean, "deterministic_id_match" boolean, "expected_predecessor" boolean, "expected_revision_kind" boolean, "expected_status" boolean, "quote_values_match" boolean, "line_values_match" boolean, "workbook_untouched" boolean, "successor_absent" boolean, "is_legacy_automatic_draft" boolean)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  with evidence as (
    select
      manifest.id as manifest_id,
      manifest.created_at as manifest_created_at,
      accepted.id as accepted_id,
      working.*,
      to_jsonb(accepted) as accepted_json,
      to_jsonb(working) as working_json
    from public.opportunity_award_pricing_manifests manifest
    join public.project_quotes accepted
      on accepted.organization_id = manifest.organization_id
     and accepted.id = manifest.accepted_quote_id
    join public.project_quotes working
      on working.organization_id = manifest.organization_id
     and working.id = manifest.working_quote_id
    where manifest.organization_id = p_organization_id
      and manifest.working_quote_id = p_quote_id
  ), predicates as (
    select
      true as manifest_linked,
      evidence.id = md5(evidence.manifest_id::text || ':working-quote')::uuid
        as deterministic_id_match,
      evidence.predecessor_quote_id = evidence.accepted_id as expected_predecessor,
      evidence.revision_kind = 'project_working' as expected_revision_kind,
      evidence.status = 'Draft' as expected_status,
      (evidence.working_json - array[
        'id', 'quote_number', 'status', 'predecessor_quote_id',
        'revision_number', 'revision_kind', 'revision_created_at',
        'revision_created_by', 'award_locked_at', 'award_locked_reason',
        'pricing_basis_status', 'pricing_basis_checked_at',
        'publication_basis_hash', 'publication_basis_json', 'published_at',
        'created_at', 'updated_at'
      ]::text[]) = (evidence.accepted_json - array[
        'id', 'quote_number', 'status', 'predecessor_quote_id',
        'revision_number', 'revision_kind', 'revision_created_at',
        'revision_created_by', 'award_locked_at', 'award_locked_reason',
        'pricing_basis_status', 'pricing_basis_checked_at',
        'publication_basis_hash', 'publication_basis_json', 'published_at',
        'created_at', 'updated_at'
      ]::text[]) as quote_values_match,
      not exists (
        (select line.section, line.description, line.quantity, line.unit, line.rate,
          line.total, line.is_optional, line.sort_order, line.pricing_source_kind
         from public.project_quote_line_items line
         where line.organization_id = p_organization_id
           and line.quote_id = evidence.accepted_id)
        except all
        (select line.section, line.description, line.quantity, line.unit, line.rate,
          line.total, line.is_optional, line.sort_order, line.pricing_source_kind
         from public.project_quote_line_items line
         where line.organization_id = p_organization_id
           and line.quote_id = evidence.id)
      ) and not exists (
        (select line.section, line.description, line.quantity, line.unit, line.rate,
          line.total, line.is_optional, line.sort_order, line.pricing_source_kind
         from public.project_quote_line_items line
         where line.organization_id = p_organization_id
           and line.quote_id = evidence.id)
        except all
        (select line.section, line.description, line.quantity, line.unit, line.rate,
          line.total, line.is_optional, line.sort_order, line.pricing_source_kind
         from public.project_quote_line_items line
         where line.organization_id = p_organization_id
           and line.quote_id = evidence.accepted_id)
      ) as line_values_match,
      not exists (
        select 1 from public.opportunity_pricing_worksheets workbook
        where workbook.organization_id = p_organization_id
          and workbook.quote_id = evidence.id
          and workbook.updated_at > evidence.manifest_created_at + interval '5 seconds'
      ) as workbook_untouched,
      not exists (
        select 1 from public.project_quotes successor
        where successor.organization_id = p_organization_id
          and successor.predecessor_quote_id = evidence.id
      ) as successor_absent
    from evidence
  )
  select predicates.*,
    predicates.manifest_linked
      and predicates.deterministic_id_match
      and predicates.expected_predecessor
      and predicates.expected_revision_kind
      and predicates.expected_status
      and predicates.quote_values_match
      and predicates.line_values_match
      and predicates.workbook_untouched
      and predicates.successor_absent as is_legacy_automatic_draft
  from predicates;
$$;


ALTER FUNCTION "public"."classify_legacy_automatic_project_quote_draft_v1"("p_organization_id" "uuid", "p_quote_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."classify_opportunity_lifecycle_v1"("p_organization_id" "uuid", "p_opportunity_id" "uuid") RETURNS TABLE("classification" "text", "is_valid" boolean, "opportunity_id" "uuid", "workspace_project_id" "uuid", "converted_project_id" "uuid", "mapped_project_id" "uuid", "mapped_accepted_quote_id" "uuid", "lifecycle_strategy" "text", "lifecycle_strategy_version" smallint, "reason_code" "text")
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
declare
  opportunity_row public.organization_opportunities%rowtype;
  lifecycle_row public.opportunity_lifecycles%rowtype;
  mapping_row public.opportunity_final_projects%rowtype;
  workspace_row public.organization_projects%rowtype;
  final_row public.organization_projects%rowtype;
  event_row public.opportunity_promotion_events%rowtype;
  accepted_quote_row public.project_quotes%rowtype;
  workspace_reference_count integer := 0;
begin
  select *
  into opportunity_row
  from public.organization_opportunities opportunity
  where opportunity.organization_id = p_organization_id
    and opportunity.id = p_opportunity_id;

  if not found then
    return query select
      'invalid_or_ambiguous'::text, false, p_opportunity_id,
      null::uuid, null::uuid, null::uuid, null::uuid,
      null::text, null::smallint, 'opportunity_not_found'::text;
    return;
  end if;

  select *
  into lifecycle_row
  from public.opportunity_lifecycles lifecycle
  where lifecycle.organization_id = p_organization_id
    and lifecycle.opportunity_id = p_opportunity_id;

  select *
  into mapping_row
  from public.opportunity_final_projects mapping
  where mapping.organization_id = p_organization_id
    and mapping.opportunity_id = p_opportunity_id;

  if opportunity_row.workspace_project_id is not null then
    select *
    into workspace_row
    from public.organization_projects project
    where project.organization_id = p_organization_id
      and project.id = opportunity_row.workspace_project_id;

    select count(*)
    into workspace_reference_count
    from public.organization_opportunities other_opportunity
    where other_opportunity.workspace_project_id = opportunity_row.workspace_project_id;

    if workspace_row.id is null then
      return query select
        'invalid_or_ambiguous'::text, false, opportunity_row.id,
        opportunity_row.workspace_project_id, opportunity_row.converted_project_id,
        mapping_row.project_id, mapping_row.accepted_quote_id,
        lifecycle_row.strategy, lifecycle_row.strategy_version,
        'workspace_project_missing'::text;
      return;
    end if;

    if workspace_reference_count <> 1 then
      return query select
        'invalid_or_ambiguous'::text, false, opportunity_row.id,
        opportunity_row.workspace_project_id, opportunity_row.converted_project_id,
        mapping_row.project_id, mapping_row.accepted_quote_id,
        lifecycle_row.strategy, lifecycle_row.strategy_version,
        'workspace_project_shared'::text;
      return;
    end if;
  end if;

  if mapping_row.project_id is not null then
    select *
    into final_row
    from public.organization_projects project
    where project.organization_id = p_organization_id
      and project.id = mapping_row.project_id;

    if final_row.id is null
      or final_row.source_opportunity_id is distinct from opportunity_row.id
      or opportunity_row.converted_project_id is distinct from mapping_row.project_id
    then
      return query select
        'invalid_or_ambiguous'::text, false, opportunity_row.id,
        opportunity_row.workspace_project_id, opportunity_row.converted_project_id,
        mapping_row.project_id, mapping_row.accepted_quote_id,
        lifecycle_row.strategy, lifecycle_row.strategy_version,
        'final_mapping_contradiction'::text;
      return;
    end if;
  elsif opportunity_row.converted_project_id is not null then
    return query select
      'invalid_or_ambiguous'::text, false, opportunity_row.id,
      opportunity_row.workspace_project_id, opportunity_row.converted_project_id,
      null::uuid, null::uuid, lifecycle_row.strategy,
      lifecycle_row.strategy_version, 'converted_project_without_mapping'::text;
    return;
  end if;

  if mapping_row.accepted_quote_id is not null then
    select *
    into accepted_quote_row
    from public.project_quotes quote
    where quote.organization_id = p_organization_id
      and quote.id = mapping_row.accepted_quote_id;

    if accepted_quote_row.id is null
      or accepted_quote_row.originating_opportunity_id is distinct from opportunity_row.id
      or accepted_quote_row.project_id is distinct from mapping_row.project_id
      or accepted_quote_row.status <> 'Accepted'
      or exists (
        select 1
        from public.project_quote_line_items line
        where line.quote_id = accepted_quote_row.id
          and (
            line.organization_id is distinct from p_organization_id
            or line.project_id is distinct from mapping_row.project_id
          )
      )
    then
      return query select
        'invalid_or_ambiguous'::text, false, opportunity_row.id,
        opportunity_row.workspace_project_id, opportunity_row.converted_project_id,
        mapping_row.project_id, mapping_row.accepted_quote_id,
        lifecycle_row.strategy, lifecycle_row.strategy_version,
        'accepted_quote_mapping_contradiction'::text;
      return;
    end if;
  end if;

  if lifecycle_row.id is null then
    if opportunity_row.workspace_project_id is not null
      and opportunity_row.converted_project_id is not null
      and opportunity_row.workspace_project_id <> opportunity_row.converted_project_id
      and mapping_row.project_id = opportunity_row.converted_project_id
    then
      return query select
        'historical_two_project'::text, true, opportunity_row.id,
        opportunity_row.workspace_project_id, opportunity_row.converted_project_id,
        mapping_row.project_id, mapping_row.accepted_quote_id,
        null::text, null::smallint, 'valid_historical_final_mapping'::text;
      return;
    end if;

    if opportunity_row.workspace_project_id is not null
      and opportunity_row.converted_project_id is null
      and mapping_row.project_id is null
    then
      return query select
        'legacy_unmarked'::text, true, opportunity_row.id,
        opportunity_row.workspace_project_id, null::uuid, null::uuid, null::uuid,
        null::text, null::smallint, 'unmarked_unawarded_workspace'::text;
      return;
    end if;

    return query select
      'invalid_or_ambiguous'::text, false, opportunity_row.id,
      opportunity_row.workspace_project_id, opportunity_row.converted_project_id,
      mapping_row.project_id, mapping_row.accepted_quote_id,
      null::text, null::smallint, 'unmarked_unsupported_shape'::text;
    return;
  end if;

  if lifecycle_row.strategy_version <> 1
    or lifecycle_row.original_workspace_project_id
      is distinct from opportunity_row.workspace_project_id
    or workspace_row.source_opportunity_id is distinct from opportunity_row.id
  then
    return query select
      'invalid_or_ambiguous'::text, false, opportunity_row.id,
      opportunity_row.workspace_project_id, opportunity_row.converted_project_id,
      mapping_row.project_id, mapping_row.accepted_quote_id,
      lifecycle_row.strategy, lifecycle_row.strategy_version,
      'lifecycle_workspace_contradiction'::text;
    return;
  end if;

  if lifecycle_row.strategy = 'legacy_two_project_v1' then
    if (
      opportunity_row.converted_project_id is null
      and mapping_row.project_id is null
    ) or (
      opportunity_row.converted_project_id is not null
      and opportunity_row.converted_project_id <> opportunity_row.workspace_project_id
      and mapping_row.project_id = opportunity_row.converted_project_id
    ) then
      return query select
        'future_explicit_legacy'::text, true, opportunity_row.id,
        opportunity_row.workspace_project_id, opportunity_row.converted_project_id,
        mapping_row.project_id, mapping_row.accepted_quote_id,
        lifecycle_row.strategy, lifecycle_row.strategy_version,
        'valid_explicit_legacy_strategy'::text;
      return;
    end if;

    return query select
      'invalid_or_ambiguous'::text, false, opportunity_row.id,
      opportunity_row.workspace_project_id, opportunity_row.converted_project_id,
      mapping_row.project_id, mapping_row.accepted_quote_id,
      lifecycle_row.strategy, lifecycle_row.strategy_version,
      'explicit_legacy_shape_contradiction'::text;
    return;
  end if;

  if lifecycle_row.strategy = 'promote_workspace_v1' then
    if opportunity_row.converted_project_id is null
      and mapping_row.project_id is null
      and not exists (
        select 1
        from public.opportunity_promotion_events promotion_event
        where promotion_event.organization_id = p_organization_id
          and promotion_event.opportunity_id = opportunity_row.id
      )
    then
      return query select
        'future_unawarded_promotion'::text, true, opportunity_row.id,
        opportunity_row.workspace_project_id, null::uuid, null::uuid, null::uuid,
        lifecycle_row.strategy, lifecycle_row.strategy_version,
        'valid_unawarded_promotion'::text;
      return;
    end if;

    select *
    into event_row
    from public.opportunity_promotion_events promotion_event
    where promotion_event.organization_id = p_organization_id
      and promotion_event.opportunity_id = opportunity_row.id;

    if opportunity_row.workspace_project_id is not null
      and opportunity_row.converted_project_id = opportunity_row.workspace_project_id
      and mapping_row.project_id = opportunity_row.workspace_project_id
      and mapping_row.accepted_quote_id is not null
      and event_row.id is not null
      and event_row.lifecycle_id = lifecycle_row.id
      and event_row.project_id = opportunity_row.workspace_project_id
      and event_row.accepted_quote_id = mapping_row.accepted_quote_id
      and event_row.strategy = lifecycle_row.strategy
      and event_row.strategy_version = lifecycle_row.strategy_version
    then
      return query select
        'future_awarded_promotion'::text, true, opportunity_row.id,
        opportunity_row.workspace_project_id, opportunity_row.converted_project_id,
        mapping_row.project_id, mapping_row.accepted_quote_id,
        lifecycle_row.strategy, lifecycle_row.strategy_version,
        'valid_completed_promotion'::text;
      return;
    end if;

    return query select
      'invalid_or_ambiguous'::text, false, opportunity_row.id,
      opportunity_row.workspace_project_id, opportunity_row.converted_project_id,
      mapping_row.project_id, mapping_row.accepted_quote_id,
      lifecycle_row.strategy, lifecycle_row.strategy_version,
      'promotion_shape_or_event_contradiction'::text;
    return;
  end if;

  return query select
    'invalid_or_ambiguous'::text, false, opportunity_row.id,
    opportunity_row.workspace_project_id, opportunity_row.converted_project_id,
    mapping_row.project_id, mapping_row.accepted_quote_id,
    lifecycle_row.strategy, lifecycle_row.strategy_version,
    'unsupported_lifecycle_strategy'::text;
end;
$$;


ALTER FUNCTION "public"."classify_opportunity_lifecycle_v1"("p_organization_id" "uuid", "p_opportunity_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."classify_opportunity_lifecycle_v1"("p_organization_id" "uuid", "p_opportunity_id" "uuid") IS 'Stage 2 read-only Opportunity lifecycle truth table. Explicit lifecycle evidence is required for same-Project promotion.';



CREATE OR REPLACE FUNCTION "public"."clean_same_project_promotion_metadata_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
declare
  opportunity_row public.organization_opportunities%rowtype;
  project_row public.organization_projects%rowtype;
  base_slug text;
  candidate_slug text;
  suffix integer := 2;
begin
  if new.strategy <> 'promote_workspace_v1' or new.strategy_version <> 1 then
    return new;
  end if;

  select * into opportunity_row
  from public.organization_opportunities opportunity
  where opportunity.id = new.opportunity_id
    and opportunity.organization_id = new.organization_id;

  select * into project_row
  from public.organization_projects project
  where project.id = new.project_id
    and project.organization_id = new.organization_id
  for update;

  if not found
    or opportunity_row.workspace_project_id is distinct from project_row.id
    or opportunity_row.converted_project_id is distinct from project_row.id
    or project_row.source_opportunity_id is distinct from opportunity_row.id
    or not exists (
      select 1 from public.opportunity_final_projects final_project
      where final_project.organization_id = new.organization_id
        and final_project.opportunity_id = opportunity_row.id
        and final_project.project_id = project_row.id
        and final_project.accepted_quote_id = new.accepted_quote_id
    )
  then
    raise exception 'Promotion metadata cleanup requires consistent same-Project evidence'
      using errcode = 'TS409';
  end if;

  base_slug := coalesce(
    nullif(btrim(opportunity_row.slug), ''),
    nullif(regexp_replace(
      regexp_replace(lower(btrim(opportunity_row.name)), '[^a-z0-9]+', '-', 'g'),
      '(^-+|-+$)', '', 'g'
    ), ''),
    'project'
  );

  perform pg_advisory_xact_lock(
    hashtextextended(new.organization_id::text || ':project-slug-namespace', 0)
  );

  candidate_slug := base_slug;
  while exists (
    select 1 from public.organization_projects project
    where project.organization_id = new.organization_id
      and project.id <> project_row.id
      and lower(project.slug) = lower(candidate_slug)
  ) or exists (
    select 1 from public.organization_project_slug_aliases alias
    where alias.organization_id = new.organization_id
      and alias.project_id <> project_row.id
      and lower(alias.alias_slug) = lower(candidate_slug)
  ) loop
    candidate_slug := base_slug || '-' || suffix::text;
    suffix := suffix + 1;
  end loop;

  if lower(project_row.slug) <> lower(candidate_slug) then
    insert into public.organization_project_slug_aliases (
      organization_id, project_id, alias_slug, created_by, reason
    ) values (
      new.organization_id, project_row.id, project_row.slug, new.completed_by,
      'same_project_promotion'
    ) on conflict (organization_id, lower(alias_slug)) do nothing;
  end if;

  update public.organization_projects project
  set name = case
        when project.name = opportunity_row.name || ' Tender Workspace'
          then opportunity_row.name
        else project.name
      end,
      slug = candidate_slug
  where project.id = project_row.id
    and project.organization_id = new.organization_id;

  return new;
end;
$_$;


ALTER FUNCTION "public"."clean_same_project_promotion_metadata_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cleanup_project_todo_from_inspection_item"() RETURNS "trigger"
