CREATE OR REPLACE FUNCTION "public"."clone_workspace_metadata_to_project"("p_organization_id" "uuid", "p_target_project_id" "uuid", "p_drawing_sets" "jsonb", "p_trade_packs" "jsonb", "p_scope_runs" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if auth.uid() is null then
    raise exception 'Unauthorized'
      using errcode = '42501';
  end if;

  if not public.is_member_of_organization(p_organization_id) then
    raise exception 'Forbidden'
      using errcode = '42501';
  end if;

  if not exists (
    select 1
    from public.organization_projects project
    where project.id = p_target_project_id
      and project.organization_id = p_organization_id
  ) then
    raise exception 'Target Project not found for organization'
      using errcode = 'TS422';
  end if;

  if coalesce(jsonb_typeof(p_drawing_sets), 'null') = 'array'
    and jsonb_array_length(p_drawing_sets) > 0
  then
    insert into public.project_drawing_sets (
      id,
      organization_id,
      project_id,
      uploaded_by,
      file_name,
      storage_path,
      file_size_bytes,
      mime_type,
      uploaded_at
    )
    select
      row.id,
      row.organization_id,
      row.project_id,
      row.uploaded_by,
      row.file_name,
      row.storage_path,
      row.file_size_bytes,
      row.mime_type,
      row.uploaded_at
    from jsonb_to_recordset(p_drawing_sets) as row(
      id uuid,
      organization_id uuid,
      project_id uuid,
      uploaded_by uuid,
      file_name text,
      storage_path text,
      file_size_bytes bigint,
      mime_type text,
      uploaded_at timestamptz
    )
    on conflict (id) do update
    set file_name = excluded.file_name,
        storage_path = excluded.storage_path,
        file_size_bytes = excluded.file_size_bytes,
        mime_type = excluded.mime_type,
        uploaded_at = excluded.uploaded_at
    where project_drawing_sets.organization_id = excluded.organization_id
      and project_drawing_sets.project_id = excluded.project_id;
  end if;

  if coalesce(jsonb_typeof(p_trade_packs), 'null') = 'array'
    and jsonb_array_length(p_trade_packs) > 0
  then
    insert into public.trade_packs (
      id,
      organization_id,
      project_id,
      trade_id,
      trade_label,
      pdf_url,
      page_index_json,
      created_by,
      created_at
    )
    select
      row.id,
      row.organization_id,
      row.project_id,
      row.trade_id,
      row.trade_label,
      row.pdf_url,
      row.page_index_json,
      row.created_by,
      row.created_at
    from jsonb_to_recordset(p_trade_packs) as row(
      id uuid,
      organization_id uuid,
      project_id uuid,
      trade_id text,
      trade_label text,
      pdf_url text,
      page_index_json jsonb,
      created_by uuid,
      created_at timestamptz
    )
    on conflict (id) do update
    set trade_id = excluded.trade_id,
        trade_label = excluded.trade_label,
        pdf_url = excluded.pdf_url,
        page_index_json = excluded.page_index_json
    where trade_packs.organization_id = excluded.organization_id
      and trade_packs.project_id = excluded.project_id;
  end if;

  if coalesce(jsonb_typeof(p_scope_runs), 'null') = 'array'
    and jsonb_array_length(p_scope_runs) > 0
  then
    insert into public.scope_runs (
      id,
      organization_id,
      project_id,
      trade_pack_id,
      created_by,
      status,
      result_json,
      error_message,
      created_at,
      updated_at
    )
    select
      row.id,
      row.organization_id,
      row.project_id,
      row.trade_pack_id,
      row.created_by,
      row.status,
      row.result_json,
      row.error_message,
      row.created_at,
      row.updated_at
    from jsonb_to_recordset(p_scope_runs) as row(
      id uuid,
      organization_id uuid,
      project_id uuid,
      trade_pack_id uuid,
      created_by uuid,
      status text,
      result_json jsonb,
      error_message text,
      created_at timestamptz,
      updated_at timestamptz
    )
    on conflict (id) do update
    set status = excluded.status,
        result_json = excluded.result_json,
        error_message = excluded.error_message,
        updated_at = excluded.updated_at
    where scope_runs.organization_id = excluded.organization_id
      and scope_runs.project_id = excluded.project_id;
  end if;
end;
$$;


ALTER FUNCTION "public"."clone_workspace_metadata_to_project"("p_organization_id" "uuid", "p_target_project_id" "uuid", "p_drawing_sets" "jsonb", "p_trade_packs" "jsonb", "p_scope_runs" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."commercial_item_json_is_non_negative_integer_like"("p_value" "jsonb") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    AS $_$
  select case
    when p_value is null then false
    when jsonb_typeof(p_value) = 'number' then p_value::text ~ '^\d+$'
    when jsonb_typeof(p_value) = 'string' then btrim(trim(both '"' from p_value::text)) ~ '^\d+$'
    else false
  end;
$_$;


ALTER FUNCTION "public"."commercial_item_json_is_non_negative_integer_like"("p_value" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."commercial_item_json_is_non_negative_number"("p_value" "jsonb") RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
begin
  if jsonb_typeof(p_value) <> 'number' then
    return false;
  end if;

  return (p_value #>> '{}')::numeric >= 0;
exception
  when others then
    return false;
end;
$$;


ALTER FUNCTION "public"."commercial_item_json_is_non_negative_number"("p_value" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."commercial_item_json_is_positive_integer"("p_value" "jsonb") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    AS $_$
  select coalesce(
    jsonb_typeof(p_value) = 'number'
      and (p_value #>> '{}') ~ '^[1-9][0-9]*$',
    false
  );
$_$;


ALTER FUNCTION "public"."commercial_item_json_is_positive_integer"("p_value" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."commercial_item_json_is_timestamp_string"("p_value" "jsonb") RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
declare
  parsed_timestamp timestamptz;
begin
  if jsonb_typeof(p_value) <> 'string'
    or btrim(coalesce(p_value #>> '{}', '')) = '' then
    return false;
  end if;

  parsed_timestamp := (p_value #>> '{}')::timestamptz;
  return isfinite(parsed_timestamp);
exception
  when others then
    return false;
end;
$$;


ALTER FUNCTION "public"."commercial_item_json_is_timestamp_string"("p_value" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."commercial_item_json_is_uuid_string"("p_value" "jsonb") RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
begin
  if jsonb_typeof(p_value) <> 'string'
    or btrim(coalesce(p_value #>> '{}', '')) = '' then
    return false;
  end if;

  perform (p_value #>> '{}')::uuid;
  return true;
exception
  when others then
    return false;
end;
$$;


ALTER FUNCTION "public"."commercial_item_json_is_uuid_string"("p_value" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."commercial_item_json_object_has_only_keys"("p_object" "jsonb", "p_allowed_keys" "text"[]) RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select coalesce(
    not exists (
      select 1
      from jsonb_object_keys(coalesce(p_object, '{}'::jsonb)) as key_name
      where not (key_name = any (p_allowed_keys))
    ),
    true
  );
$$;


ALTER FUNCTION "public"."commercial_item_json_object_has_only_keys"("p_object" "jsonb", "p_allowed_keys" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."commercial_item_json_object_has_required_keys"("p_object" "jsonb", "p_required_keys" "text"[]) RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select coalesce(
    not exists (
      select 1
      from unnest(p_required_keys) as required_key
      where not (coalesce(p_object, '{}'::jsonb) ? required_key)
    ),
    true
  );
$$;


ALTER FUNCTION "public"."commercial_item_json_object_has_required_keys"("p_object" "jsonb", "p_required_keys" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."commercial_item_json_text_matches_regex"("p_value" "jsonb", "p_pattern" "text") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select case
    when jsonb_typeof(p_value) <> 'string' then false
    else btrim(trim(both '"' from p_value::text)) ~ p_pattern
  end;
$$;


ALTER FUNCTION "public"."commercial_item_json_text_matches_regex"("p_value" "jsonb", "p_pattern" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."commercial_item_json_value_is_type"("p_value" "jsonb", "p_allowed_types" "text"[]) RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select case
    when p_value is null then false
    else jsonb_typeof(p_value) = any (p_allowed_types)
  end;
$$;


ALTER FUNCTION "public"."commercial_item_json_value_is_type"("p_value" "jsonb", "p_allowed_types" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."commercial_lineage_relationship_is_allowed"("p_from_entity_type" "text", "p_to_entity_type" "text", "p_relationship_type" "text") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select (p_from_entity_type, p_to_entity_type, p_relationship_type) in (
    ('commercial_item', 'organization_material', 'derived_from_material'),
    ('commercial_item', 'organization_material_supplier_product', 'priced_from_supplier_product'),
    ('commercial_item', 'organization_material_supplier_price', 'priced_from_supplier_price'),
    ('commercial_item', 'takeoff_measurement', 'measured_from'),
    ('commercial_item', 'project_quote', 'scoped_by'),
    ('commercial_item', 'project_variation', 'scoped_by'),
    ('project_purchase_order_line_item', 'project_quote_line_item', 'caused_by'),
    ('project_purchase_order_line_item', 'project_variation_line_item', 'caused_by')
  );
$$;


ALTER FUNCTION "public"."commercial_lineage_relationship_is_allowed"("p_from_entity_type" "text", "p_to_entity_type" "text", "p_relationship_type" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."commit_ai_chat_quota_reservation"("p_usage_id" "uuid", "p_tokens_used" integer, "p_response_chars" integer) RETURNS boolean
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  update public.ai_chat_usage
  set tokens_used = greatest(coalesce(p_tokens_used, 0), 0),
      response_chars = greatest(coalesce(p_response_chars, 0), 0),
      reservation_state = 'committed'
  where id = p_usage_id
    and user_id = auth.uid()
    and reservation_state = 'pending';

  return found;
end;
$$;


