CREATE OR REPLACE FUNCTION "public"."complete_document_storage_cleanup_job"("p_job_id" "uuid", "p_claim_token" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  job_row public.document_storage_cleanup_jobs%rowtype;
  completed_batch public.document_storage_cleanup_batches%rowtype;
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'Service role required.'
      using errcode = '42501';
  end if;

  select *
  into job_row
  from public.document_storage_cleanup_jobs job
  where job.id = p_job_id
  for update;

  if not found
    or job_row.processing_status <> 'claimed'
    or job_row.claim_token <> p_claim_token
  then
    raise exception 'Cleanup lease is not owned.'
      using errcode = '42501';
  end if;

  if job_row.job_type = 'abandoned_upload'
    and job_row.version_id is not null
  then
    update public.document_versions version
    set upload_state = 'purge_pending'
    where version.id = job_row.version_id
      and version.upload_state in ('failed', 'abandoned');

    update public.document_versions version
    set
      upload_state = 'purged',
      purged_at = now(),
      storage_object_id = null,
      storage_etag = null
    where version.id = job_row.version_id
      and version.upload_state = 'purge_pending';
  end if;

  update public.document_storage_cleanup_jobs job
  set
    processing_status = 'completed',
    completed_at = now(),
    claimed_at = null,
    claim_expires_at = null,
    claimed_by = null,
    claim_token = null,
    last_error_code = null,
    last_error_message = null
  where job.id = job_row.id;

  update public.document_storage_reconciliation_findings finding
  set
    finding_status = 'resolved',
    resolved_at = now()
  where finding.storage_bucket = job_row.storage_bucket
    and finding.storage_key = job_row.storage_key
    and finding.finding_status <> 'resolved'
    and job_row.job_type <> 'orphan_reconciliation';

  if job_row.cleanup_batch_id is not null
    and not exists (
      select 1
      from public.document_storage_cleanup_jobs remaining
      where remaining.cleanup_batch_id = job_row.cleanup_batch_id
        and remaining.processing_status <> 'completed'
    )
  then
    update public.document_storage_cleanup_batches batch
    set
      processing_status = 'completed',
      completed_at = now(),
      dead_lettered_at = null
    where batch.id = job_row.cleanup_batch_id
      and batch.processing_status <> 'completed'
    returning * into completed_batch;

    if completed_batch.id is not null then
      insert into public.document_activity_events (
        organization_id,
        workspace_id,
        actor_user_id,
        event_type,
        metadata
      )
      values (
        completed_batch.organization_id,
        completed_batch.workspace_id,
        completed_batch.requested_by,
        'purged',
        jsonb_build_object(
          'cleanupBatchId', completed_batch.id,
          'deletionBatchId', completed_batch.deletion_batch_id,
          'rootNodeId', completed_batch.root_node_id,
          'objectCount', completed_batch.object_count,
          'byteCount', completed_batch.byte_count
        )
      );
    end if;
  end if;

  return 'completed';
end;
$$;


ALTER FUNCTION "public"."complete_document_storage_cleanup_job"("p_job_id" "uuid", "p_claim_token" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_document_upload"("p_version_id" "uuid", "p_actor_user_id" "uuid") RETURNS TABLE("node_id" "uuid", "version_id" "uuid", "version_number" integer, "display_name" "text", "byte_size" bigint, "verified_mime_type" "text", "activated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  version_row public.document_versions%rowtype;
  node_row public.document_nodes%rowtype;
  object_row storage.objects%rowtype;
  actual_size bigint;
  actual_mime_type text;
  actor_can_write boolean;
  activation_time timestamptz := now();
begin
  if p_actor_user_id is null then
    raise exception 'Authenticated actor is required.';
  end if;

  select version.*
  into version_row
  from public.document_versions version
  where version.id = p_version_id
  for update;

  if not found or version_row.uploaded_by <> p_actor_user_id then
    raise exception 'Pending upload not found or access denied.';
  end if;

  select exists (
    select 1
    from public.organization_members member
    join public.role_permissions role_permission
     on role_permission.role = member.role
     and role_permission.permission_key = 'files.write'
     and role_permission.is_allowed
    where member.organization_id = version_row.organization_id
      and member.user_id = p_actor_user_id
  )
  into actor_can_write;

  if not actor_can_write then
    raise exception 'Pending upload not found or access denied.';
  end if;

  select node.*
  into node_row
  from public.document_nodes node
  where node.organization_id = version_row.organization_id
    and node.workspace_id = version_row.workspace_id
    and node.id = version_row.node_id
  for update;

  if not found
    or node_row.kind <> 'file'
    or node_row.deleted_at is not null
    or node_row.lifecycle_state not in ('pending', 'active')
  then
    raise exception 'Document file is not available for activation.';
  end if;

  if version_row.upload_state = 'active' then
    if node_row.current_version_id <> version_row.id then
      raise exception 'Activated version is no longer current.';
    end if;

    return query
    select
      node_row.id,
      version_row.id,
      version_row.version_number,
      node_row.display_name,
      version_row.byte_size,
      version_row.verified_mime_type,
      version_row.activated_at;
    return;
  end if;

  if version_row.upload_state <> 'pending' then
    raise exception 'Upload is not pending.';
  end if;

  if version_row.upload_expires_at <= now() then
    raise exception 'Pending upload has expired.';
  end if;

  select object.*
  into object_row
  from storage.objects object
  where object.bucket_id = 'organization-documents'
    and object.name = version_row.storage_key;

  if not found then
    raise exception 'Expected Storage object was not found.';
  end if;

  actual_size := nullif(object_row.metadata ->> 'size', '')::bigint;
  actual_mime_type := lower(
    btrim(
      coalesce(
        object_row.metadata ->> 'mimetype',
        object_row.metadata ->> 'contentType',
        ''
      )
    )
  );

  if actual_size is null or actual_size <> version_row.byte_size then
    raise exception 'Stored object size does not match the reservation.';
  end if;

  if actual_mime_type = ''
    or actual_mime_type <> lower(version_row.claimed_mime_type)
    or not public.document_upload_mime_extension_allowed(
      actual_mime_type,
      version_row.file_extension
    )
  then
    raise exception 'Stored object MIME type does not match the reservation.';
  end if;

  update public.document_versions version
  set
    upload_state = 'active',
    verified_mime_type = actual_mime_type,
    storage_object_id = object_row.id,
    storage_etag = nullif(
      coalesce(
        object_row.metadata ->> 'eTag',
        object_row.metadata ->> 'etag',
        ''
      ),
      ''
    ),
    uploaded_at = activation_time,
    verified_at = activation_time,
    activated_at = activation_time,
    failure_code = null,
    failure_message = null
  where version.id = version_row.id
  returning * into version_row;

  update public.document_nodes node
  set
    lifecycle_state = 'active',
    current_version_id = version_row.id,
    updated_by = p_actor_user_id,
    updated_at = activation_time
  where node.id = node_row.id
  returning * into node_row;

  insert into public.document_activity_events (
    organization_id,
    workspace_id,
    node_id,
    version_id,
    actor_user_id,
    event_type,
    metadata
  )
  values
    (
      version_row.organization_id,
      version_row.workspace_id,
      version_row.node_id,
      version_row.id,
      p_actor_user_id,
      'file_uploaded',
      jsonb_build_object(
        'version_number', version_row.version_number,
        'byte_size', version_row.byte_size
      )
    ),
    (
      version_row.organization_id,
      version_row.workspace_id,
      version_row.node_id,
      version_row.id,
      p_actor_user_id,
      'version_activated',
      jsonb_build_object(
        'version_number', version_row.version_number,
        'replacement', version_row.replaces_version_id is not null
      )
    );

  return query
  select
    node_row.id,
    version_row.id,
    version_row.version_number,
    node_row.display_name,
    version_row.byte_size,
    version_row.verified_mime_type,
    version_row.activated_at;
end;
$$;


ALTER FUNCTION "public"."complete_document_upload"("p_version_id" "uuid", "p_actor_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_master_retention_claim_push"("p_attempt_id" "uuid", "p_worker_id" "text", "p_lease_token" "uuid", "p_result" "jsonb") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_attempt public.organization_accounting_revision_attempts%rowtype;
  v_revision public.organization_accounting_document_revisions%rowtype;
  v_document public.organization_accounting_documents%rowtype;
  v_previous public.organization_accounting_document_revisions%rowtype;
  v_finalized boolean;
begin
  select * into v_attempt
  from public.organization_accounting_revision_attempts
  where id = p_attempt_id
  for update;
  if not found
    or v_attempt.queue_state <> 'claimed'
    or v_attempt.worker_id <> p_worker_id
    or v_attempt.lease_token <> p_lease_token
    or v_attempt.lease_expires_at < now() then
    return false;
  end if;
  select * into v_revision
  from public.organization_accounting_document_revisions
  where id = v_attempt.accounting_revision_id
  for update;
  select * into v_document
  from public.organization_accounting_documents
  where id = v_revision.accounting_document_id
  for update;
  if v_revision.source_document_type <> 'retention_claim'
    or v_revision.revision_intent not in (
      'initial_push', 'direct_update', 'replacement'
    )
    or p_result->>'externalDocumentNumber' <>
      v_revision.external_document_number
    or nullif(trim(p_result->>'externalDocumentId'), '') is null then
    raise exception 'Verified Xero result does not match the master Retention revision.';
  end if;
  if v_revision.revision_intent = 'initial_push' then
    if v_document.active_accounting_revision_id is not null then
      raise exception 'A master Retention revision is already active.';
    end if;
  else
    select * into v_previous
    from public.organization_accounting_document_revisions
    where id = v_revision.previous_revision_id
    for update;
    if not found
      or v_document.active_accounting_revision_id <> v_previous.id
      or v_document.external_document_id <> v_previous.external_document_id
      or v_document.external_document_number <>
        v_previous.external_document_number then
      raise exception 'The master Retention predecessor changed before activation.';
    end if;
    if v_revision.revision_intent = 'direct_update' and (
      p_result->>'externalDocumentId' <> v_previous.external_document_id
      or v_revision.external_document_number <>
        v_previous.external_document_number
    ) then
      raise exception 'The direct update did not preserve the Xero invoice identity.';
    end if;
    if v_revision.revision_intent = 'replacement' and (
      p_result->>'externalDocumentId' = v_previous.external_document_id
      or v_revision.external_document_number =
        v_previous.external_document_number
    ) then
      raise exception 'The replacement did not create a distinct Xero invoice identity.';
    end if;
  end if;
  v_finalized := public.finalize_accounting_revision_attempt_phase2a(
    p_attempt_id, p_worker_id, p_lease_token, 'succeeded',
    case when coalesce((p_result->>'recovered')::boolean, false)
      then 'recovered_authorised_invoice'
      else 'verified_authorised_invoice' end,
    'Xero exactly matched the immutable cumulative Retention revision.',
    p_result->'rawObservation'
  );
  if not v_finalized then return false; end if;
  update public.organization_accounting_documents
  set
    external_document_id = p_result->>'externalDocumentId',
    external_document_number = v_revision.external_document_number,
    amount_exported = v_revision.total_minor::numeric / 100,
    tax_exported = v_revision.tax_minor::numeric / 100,
    exported_by = v_revision.confirmed_by,
    exported_at = now(),
    last_synced_at = now(),
    raw_external_status = 'AUTHORISED',
    normalized_external_status = 'awaiting_payment',
    amount_paid = 0,
    amount_due = v_revision.total_minor::numeric / 100,
    amount_credited = 0,
    export_status = 'exported',
    last_synced_hash = v_revision.commercial_snapshot->>'currentStateHash',
    last_error_code = null,
    last_error_message = null,
    last_status_sync_error = null,
    updated_at = now()
  where id = v_document.id;
  perform public.activate_successful_accounting_revision_phase2a(
    v_revision.id, p_result->>'externalDocumentId'
  );
  perform public.record_accounting_remote_observation_phase2a(
    jsonb_build_object(
      'organizationId', v_revision.organization_id,
      'accountingDocumentId', v_document.id,
      'accountingRevisionId', v_revision.id,
      'provider', 'xero',
      'tenantId', v_revision.tenant_id,
      'externalDocumentId', p_result->>'externalDocumentId',
      'providerUpdatedAt', p_result->>'providerUpdatedAt',
      'rawStatus', 'AUTHORISED',
      'normalizedStatus', 'authorised_unpaid',
      'normalizedInvoiceStatus', 'authorised',
      'normalizedPaymentStatus', 'unpaid',
      'contentHash', v_revision.provider_content_hash,
      'settlementHash', p_result->>'settlementHash',
      'amountPaidMinor', '0',
      'amountDueMinor', v_revision.total_minor::text,
      'amountCreditedMinor', '0',
      'rawObservation', p_result->'rawObservation',
      'correlationId', p_attempt_id::text
    )
  );
  return true;
end;
$$;


ALTER FUNCTION "public"."complete_master_retention_claim_push"("p_attempt_id" "uuid", "p_worker_id" "text", "p_lease_token" "uuid", "p_result" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_payment_claim_accounting_update"("p_attempt_id" "uuid", "p_worker_id" "text", "p_lease_token" "uuid", "p_result" "jsonb") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_attempt public.organization_accounting_revision_attempts%rowtype;
  v_revision public.organization_accounting_document_revisions%rowtype;
  v_previous public.organization_accounting_document_revisions%rowtype;
  v_document public.organization_accounting_documents%rowtype;
  v_job public.organization_accounting_sync_jobs%rowtype;
  v_observation public.organization_accounting_remote_observations%rowtype;
  v_projection public.organization_accounting_projections%rowtype;
  v_finalized boolean;
begin
  select * into v_attempt
  from public.organization_accounting_revision_attempts
  where id = p_attempt_id
  for update;
  if not found then
    return false;
  end if;
  select * into v_revision
  from public.organization_accounting_document_revisions
  where id = v_attempt.accounting_revision_id
  for update;
  select * into v_previous
  from public.organization_accounting_document_revisions
  where id = v_revision.previous_revision_id
  for update;
  select * into v_document
  from public.organization_accounting_documents
  where id = v_revision.accounting_document_id
  for update;
  select * into v_job
  from public.organization_accounting_sync_jobs
  where id = nullif(p_result->>'jobId', '')::uuid
    and organization_id = v_revision.organization_id
    and job_kind = 'xero.payment_claim.accounting_update'
    and request_payload->>'accountingRevisionId' = v_revision.id::text
    and request_payload->>'attemptId' = v_attempt.id::text
  for update;
  if v_attempt.queue_state = 'succeeded' then
    return v_revision.lifecycle_state = 'succeeded'
      and v_document.active_accounting_revision_id = v_revision.id
      and v_job.queue_state = 'completed'
      and v_revision.external_document_id = p_result->>'externalDocumentId'
      and v_revision.external_document_number =
        p_result->>'externalDocumentNumber';
  end if;
  if v_attempt.queue_state <> 'claimed'
    or v_attempt.worker_id <> p_worker_id
    or v_attempt.lease_token <> p_lease_token
    or v_attempt.lease_expires_at < now()
    or v_job.queue_state <> 'claimed'
    or v_job.claimed_by <> p_worker_id
    or v_job.claim_expires_at < now() then
    return false;
  end if;
  if v_revision.source_document_type <> 'project_claim'
    or v_revision.revision_intent <> 'direct_update'
    or v_attempt.attempt_intent <> 'update'
    or v_document.integration_contract <> 'payment_claim_revision_v1'
    or v_document.active_accounting_revision_id <> v_previous.id
    or v_document.external_document_id <> v_previous.external_document_id
    or v_document.external_document_number <>
      v_previous.external_document_number
    or v_job.id is null
    or p_result->>'externalDocumentId' <>
      v_previous.external_document_id
    or p_result->>'externalDocumentNumber' <>
      v_previous.external_document_number
    or v_revision.external_document_number <>
      v_previous.external_document_number
    or (p_result->>'subtotalMinor')::bigint <> v_revision.subtotal_minor
    or (p_result->>'taxMinor')::bigint <> v_revision.tax_minor
    or (p_result->>'totalMinor')::bigint <> v_revision.total_minor then
    raise exception 'Verified Xero result does not match the immutable Payment Claim amendment.';
  end if;
  v_finalized := public.finalize_accounting_revision_attempt_phase2a(
    p_attempt_id,
    p_worker_id,
    p_lease_token,
    'succeeded',
    case when coalesce((p_result->>'recovered')::boolean, false)
      then 'recovered_authorised_invoice'
      else 'verified_authorised_invoice' end,
    'Xero exactly matched the immutable Payment Claim amendment revision.',
    p_result->'rawObservation'
  );
  if not v_finalized then return false; end if;
  update public.organization_accounting_documents
  set
    external_document_id = v_previous.external_document_id,
    external_document_number = v_previous.external_document_number,
    amount_exported = v_revision.total_minor::numeric / 100,
    tax_exported = v_revision.tax_minor::numeric / 100,
    exported_by = v_revision.confirmed_by,
    exported_at = now(),
    last_synced_at = now(),
    raw_external_status = 'AUTHORISED',
    normalized_external_status = 'awaiting_payment',
    amount_paid = 0,
    amount_due = v_revision.total_minor::numeric / 100,
    amount_credited = 0,
    export_status = 'exported',
    last_synced_hash = v_revision.commercial_snapshot->>'currentStateHash',
    last_error_code = null,
    last_error_message = null,
    last_status_sync_error = null,
    updated_at = now()
  where id = v_document.id;
  perform public.activate_successful_accounting_revision_phase2a(
    v_revision.id, v_previous.external_document_id
  );
  select * into v_observation
  from public.record_accounting_remote_observation_phase2a(
    jsonb_build_object(
      'organizationId', v_revision.organization_id,
      'accountingDocumentId', v_document.id,
      'accountingRevisionId', v_revision.id,
      'provider', 'xero',
      'tenantId', v_revision.tenant_id,
      'externalDocumentId', v_previous.external_document_id,
      'providerUpdatedAt', p_result->>'providerUpdatedAt',
      'rawStatus', 'AUTHORISED',
      'normalizedStatus', 'authorised_unpaid',
      'normalizedInvoiceStatus', 'authorised',
      'normalizedPaymentStatus', 'unpaid',
      'contentHash', v_revision.provider_content_hash,
      'settlementHash', p_result->>'settlementHash',
      'amountPaidMinor', '0',
      'amountDueMinor', v_revision.total_minor::text,
      'amountCreditedMinor', '0',
      'rawObservation', p_result->'rawObservation',
      'correlationId', p_attempt_id::text
    )
  );
  select * into v_projection
  from public.organization_accounting_projections projection
  where projection.accounting_document_id = v_document.id
    and projection.accounting_revision_id = v_revision.id
    and projection.remote_observation_id = v_observation.id;
  update public.organization_accounting_sync_jobs
  set
    queue_state = 'completed',
    result_summary = jsonb_build_object(
      'accountingDocumentId', v_document.id,
      'predecessorRevisionId', v_previous.id,
      'successorRevisionId', v_revision.id,
      'attemptId', v_attempt.id,
      'jobId', v_job.id,
      'observationId', v_observation.id,
      'projectionId', v_projection.id,
      'externalDocumentId', v_previous.external_document_id,
      'externalDocumentNumber', v_previous.external_document_number,
      'recovered', coalesce((p_result->>'recovered')::boolean, false)
    ),
    last_error = null,
    claimed_at = null,
    claimed_by = null,
    claim_expires_at = null,
    last_completed_at = now(),
    updated_at = now()
  where id = v_job.id;
  insert into public.organization_accounting_events(
    organization_id, accounting_document_id, accounting_revision_id,
    event_type, event_evidence
  ) values (
    v_revision.organization_id, v_document.id, v_revision.id,
    case when coalesce((p_result->>'recovered')::boolean, false)
      then 'payment_claim_accounting_update_recovered'
      else 'payment_claim_accounting_update_succeeded' end,
    jsonb_build_object(
      'predecessorRevisionId', v_previous.id,
      'externalDocumentId', v_previous.external_document_id,
      'externalDocumentNumber', v_previous.external_document_number
    )
  );
  return true;
end;
$$;


ALTER FUNCTION "public"."complete_payment_claim_accounting_update"("p_attempt_id" "uuid", "p_worker_id" "text", "p_lease_token" "uuid", "p_result" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_payment_claim_initial_push_phase2b"("p_attempt_id" "uuid", "p_worker_id" "text", "p_lease_token" "uuid", "p_result" "jsonb") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private', 'extensions'
    AS $$
declare
  v_attempt public.organization_accounting_revision_attempts%rowtype;
  v_revision public.organization_accounting_document_revisions%rowtype;
  v_document public.organization_accounting_documents%rowtype;
  v_finalized boolean;
  v_attachment_attempt public.organization_accounting_revision_attempts%rowtype;
  v_attachment_key text;
begin
  select * into v_attempt
  from public.organization_accounting_revision_attempts
  where id = p_attempt_id for update;
  if not found
    or v_attempt.queue_state <> 'claimed'
    or v_attempt.worker_id <> p_worker_id
    or v_attempt.lease_token <> p_lease_token
    or v_attempt.lease_expires_at < now() then
    return false;
  end if;
  select * into v_revision
  from public.organization_accounting_document_revisions
  where id = v_attempt.accounting_revision_id for update;
  select * into v_document
  from public.organization_accounting_documents
  where id = v_revision.accounting_document_id for update;
  if v_revision.revision_intent <> 'initial_push'
    or v_revision.provider_document_type <> 'ACCREC'
    or v_revision.requested_provider_status <> 'AUTHORISED'
    or v_document.integration_contract <> 'payment_claim_revision_v1'
    or v_document.external_document_id is not null
    or p_result->>'externalDocumentNumber' <> v_revision.external_document_number
    or nullif(trim(p_result->>'externalDocumentId'), '') is null then
    raise exception 'Verified Xero result does not match the immutable initial-push identity.';
  end if;

  v_finalized := public.finalize_accounting_revision_attempt_phase2a(
    p_attempt_id, p_worker_id, p_lease_token, 'succeeded',
    'verified_authorised_invoice', 'Xero invoice exactly matched immutable revision.',
    p_result->'rawObservation'
  );
  if not v_finalized then return false; end if;

  update public.organization_accounting_documents set
    external_document_id = p_result->>'externalDocumentId',
    external_document_number = v_revision.external_document_number,
    amount_exported = (v_revision.total_minor::numeric / 100),
    tax_exported = (v_revision.tax_minor::numeric / 100),
    exported_by = v_revision.confirmed_by,
    exported_at = now(),
    last_synced_at = now(),
    raw_external_status = 'AUTHORISED',
    normalized_external_status = 'awaiting_payment',
    export_status = 'exported',
    last_synced_hash = v_revision.commercial_snapshot->>'currentStateHash',
    last_error_code = null,
    last_error_message = null,
    updated_at = now()
  where id = v_document.id and external_document_id is null;

  perform public.activate_successful_accounting_revision_phase2a(
    v_revision.id, p_result->>'externalDocumentId'
  );
  perform public.record_accounting_remote_observation_phase2a(
    jsonb_build_object(
      'organizationId', v_revision.organization_id,
      'accountingDocumentId', v_document.id,
      'accountingRevisionId', v_revision.id,
      'provider', 'xero',
      'tenantId', v_revision.tenant_id,
      'externalDocumentId', p_result->>'externalDocumentId',
      'providerUpdatedAt', p_result->>'providerUpdatedAt',
      'rawStatus', 'AUTHORISED',
      'normalizedStatus', 'authorised_unpaid',
      'normalizedInvoiceStatus', 'authorised',
      'normalizedPaymentStatus', 'unpaid',
      'contentHash', v_revision.provider_content_hash,
      'settlementHash', p_result->>'settlementHash',
      'amountPaidMinor', '0',
      'amountDueMinor', v_revision.total_minor::text,
      'amountCreditedMinor', '0',
      'rawObservation', p_result->'rawObservation',
      'correlationId', p_attempt_id::text
    )
  );
  v_attachment_key := encode(
    digest(('xero:payment_claim:initial_push:attachment:' || v_revision.id)::bytea, 'sha256'),
    'hex'
  );
  select * into v_attachment_attempt
  from public.create_accounting_revision_attempt_phase2a(
    v_revision.id, 'attach', v_attachment_key,
    jsonb_build_object(
      'accountingDocumentId', v_document.id,
      'accountingRevisionId', v_revision.id,
      'attachmentId', (
        select id from public.organization_accounting_revision_attachments
        where accounting_revision_id = v_revision.id and attachment_sequence = 1
      ),
      'tenantId', v_revision.tenant_id,
      'intent', 'initial_push_attachment'
    )
  );
  insert into public.organization_accounting_sync_jobs(
    organization_id, provider, connection_id, job_kind, trigger_source,
    request_payload, result_summary, idempotency_key, max_attempts,
    created_by_user_id
  ) values (
    v_revision.organization_id, 'xero', v_revision.connection_id,
    'xero.payment_claim.initial_push.attachment', 'user_export',
    jsonb_build_object(
      'accountingDocumentId', v_document.id,
      'accountingRevisionId', v_revision.id,
      'attemptId', v_attachment_attempt.id,
      'tenantId', v_revision.tenant_id,
      'intent', 'initial_push_attachment'
    ),
    '{}'::jsonb, v_attachment_key, 5, v_revision.confirmed_by
  ) on conflict (idempotency_key) where idempotency_key is not null do nothing;
  return true;
end;
$$;


ALTER FUNCTION "public"."complete_payment_claim_initial_push_phase2b"("p_attempt_id" "uuid", "p_worker_id" "text", "p_lease_token" "uuid", "p_result" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_payment_claim_replacement_phase2c"("p_attempt_id" "uuid", "p_worker_id" "text", "p_lease_token" "uuid", "p_result" "jsonb") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
declare
  v_attempt public.organization_accounting_revision_attempts%rowtype;
  v_revision public.organization_accounting_document_revisions%rowtype;
  v_previous public.organization_accounting_document_revisions%rowtype;
  v_document public.organization_accounting_documents%rowtype;
  v_finalized boolean;
  v_attachment_attempt public.organization_accounting_revision_attempts%rowtype;
  v_attachment_key text;
begin
  select * into v_attempt from public.organization_accounting_revision_attempts
  where id = p_attempt_id for update;
  if not found or v_attempt.queue_state <> 'claimed' or v_attempt.worker_id <> p_worker_id
    or v_attempt.lease_token <> p_lease_token or v_attempt.lease_expires_at < now() then return false; end if;
  select * into v_revision from public.organization_accounting_document_revisions
  where id = v_attempt.accounting_revision_id for update;
  select * into v_previous from public.organization_accounting_document_revisions
  where id = v_revision.previous_revision_id for update;
  select * into v_document from public.organization_accounting_documents
  where id = v_revision.accounting_document_id for update;
  if v_revision.revision_intent <> 'replacement' or v_attempt.attempt_intent <> 'replace'
    or v_document.active_accounting_revision_id <> v_previous.id
    or v_document.external_document_id <> v_previous.external_document_id
    or p_result->>'externalDocumentNumber' <> v_revision.external_document_number
    or nullif(trim(p_result->>'externalDocumentId'), '') is null then
    raise exception 'Verified Xero result does not match the immutable replacement identity.';
  end if;
  v_finalized := public.finalize_accounting_revision_attempt_phase2a(
    p_attempt_id, p_worker_id, p_lease_token, 'succeeded',
    'verified_authorised_replacement', 'Xero replacement exactly matched immutable revision.',
    p_result->'rawObservation'
  );
  if not v_finalized then return false; end if;
  update public.organization_accounting_documents set
    external_document_id = p_result->>'externalDocumentId',
    external_document_number = v_revision.external_document_number,
    amount_exported = v_revision.total_minor::numeric / 100,
    tax_exported = v_revision.tax_minor::numeric / 100,
    exported_by = v_revision.confirmed_by, exported_at = now(), last_synced_at = now(),
    raw_external_status = 'AUTHORISED', normalized_external_status = 'awaiting_payment',
    amount_paid = 0, amount_due = v_revision.total_minor::numeric / 100, amount_credited = 0,
    last_status_sync_error = null, export_status = 'exported',
    last_synced_hash = v_revision.commercial_snapshot->>'currentStateHash',
    last_error_code = null, last_error_message = null, updated_at = now()
  where id = v_document.id and active_accounting_revision_id = v_previous.id;
  perform public.activate_successful_accounting_revision_phase2a(v_revision.id, p_result->>'externalDocumentId');
  perform public.record_accounting_remote_observation_phase2a(jsonb_build_object(
    'organizationId', v_revision.organization_id, 'accountingDocumentId', v_document.id,
    'accountingRevisionId', v_revision.id, 'provider', 'xero', 'tenantId', v_revision.tenant_id,
    'externalDocumentId', p_result->>'externalDocumentId', 'providerUpdatedAt', p_result->>'providerUpdatedAt',
    'rawStatus', 'AUTHORISED', 'normalizedStatus', 'authorised_unpaid',
    'normalizedInvoiceStatus', 'authorised', 'normalizedPaymentStatus', 'unpaid',
    'contentHash', v_revision.provider_content_hash, 'settlementHash', p_result->>'settlementHash',
    'amountPaidMinor', '0', 'amountDueMinor', v_revision.total_minor::text, 'amountCreditedMinor', '0',
    'rawObservation', p_result->'rawObservation', 'correlationId', p_attempt_id::text
  ));
  insert into public.organization_accounting_events(
    organization_id, accounting_document_id, accounting_revision_id,
    accounting_attempt_id, event_type, actor_user_id, event_evidence
  ) values (
    v_revision.organization_id, v_document.id, v_revision.id, v_attempt.id,
    case when coalesce((p_result->>'recovered')::boolean, false)
      then 'replacement_recovered' else 'replacement_succeeded' end,
    v_revision.confirmed_by,
    jsonb_build_object('previousRevisionId', v_previous.id, 'externalDocumentId', p_result->>'externalDocumentId')
  );
  v_attachment_key := encode(digest(('xero:payment_claim:replacement:attachment:' || v_revision.id)::bytea, 'sha256'), 'hex');
  select * into v_attachment_attempt from public.create_accounting_revision_attempt_phase2a(
    v_revision.id, 'attach', v_attachment_key,
    jsonb_build_object('accountingDocumentId', v_document.id, 'accountingRevisionId', v_revision.id,
      'attachmentId', (select id from public.organization_accounting_revision_attachments
        where accounting_revision_id = v_revision.id and attachment_sequence = 1),
      'tenantId', v_revision.tenant_id, 'intent', 'replacement_attachment')
  );
  insert into public.organization_accounting_sync_jobs(
    organization_id, provider, connection_id, job_kind, trigger_source,
    request_payload, result_summary, idempotency_key, max_attempts, created_by_user_id
  ) values (
    v_revision.organization_id, 'xero', v_revision.connection_id,
    'xero.payment_claim.replacement.attachment', 'user_export',
    jsonb_build_object('accountingDocumentId', v_document.id, 'accountingRevisionId', v_revision.id,
      'attemptId', v_attachment_attempt.id, 'tenantId', v_revision.tenant_id, 'intent', 'replacement_attachment'),
    '{}'::jsonb, v_attachment_key, 5, v_revision.confirmed_by
  ) on conflict (idempotency_key) where idempotency_key is not null do nothing;
  return true;
end;
$$;


ALTER FUNCTION "public"."complete_payment_claim_replacement_phase2c"("p_attempt_id" "uuid", "p_worker_id" "text", "p_lease_token" "uuid", "p_result" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_project_qa_run_v1"("p_organization_id" "uuid", "p_project_id" "uuid", "p_run_id" "uuid", "p_expected_lock_version" integer) RETURNS TABLE("status" "text", "completed_at" timestamp with time zone, "lock_version" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
declare run_row public.project_qa_runs%rowtype; response_row public.project_qa_responses%rowtype; config jsonb; required boolean; answered boolean; comment_rule text; min_value numeric; max_value numeric; target_value numeric; tolerance_value numeric; evidence_count integer; minimum_evidence integer; next_completed timestamptz; next_lock integer;
begin
  if auth.uid() is null or not public.can_access_qa_project(p_organization_id,p_project_id,'qa.inspect') then raise exception 'Not authorized to complete QA Record' using errcode='42501'; end if;
  select * into run_row from public.project_qa_runs where organization_id=p_organization_id and project_id=p_project_id and id=p_run_id for update;
  if not found then raise exception 'QA Record not found' using errcode='TS404'; end if;
  if run_row.status<>'in_progress' then raise exception 'Only an in-progress QA Record can be completed' using errcode='TS409'; end if;
  if run_row.lock_version<>p_expected_lock_version then raise exception 'This QA Record changed elsewhere. Reload before completing.' using errcode='TS409'; end if;
  if exists(select 1 from public.project_qa_evidence_uploads upload where upload.run_id=p_run_id and upload.status='pending' and upload.expires_at>now()) then raise exception 'Wait for pending QA evidence uploads to finish' using errcode='TS409'; end if;
  for response_row in select * from public.project_qa_responses where organization_id=p_organization_id and project_id=p_project_id and run_id=p_run_id order by section_sort_order,field_sort_order loop
    required:=coalesce((response_row.field_snapshot->>'required')::boolean,false);
    minimum_evidence:=greatest(coalesce((response_row.field_snapshot->>'minimumPhotos')::integer,0),1);
    answered:=case response_row.field_type
      when 'short_text' then nullif(btrim(coalesce(response_row.text_value,'')),'') is not null when 'long_text' then nullif(btrim(coalesce(response_row.text_value,'')),'') is not null
      when 'number' then response_row.numeric_value is not null when 'measurement' then response_row.numeric_value is not null when 'date' then response_row.date_value is not null
      when 'yes_no' then response_row.boolean_value is not null when 'single_select' then jsonb_array_length(response_row.selected_options)=1 when 'multi_select' then jsonb_array_length(response_row.selected_options)>0
      when 'checkbox' then response_row.boolean_value is true when 'inspection_check' then response_row.inspection_result is not null
      when 'person' then nullif(btrim(coalesce(response_row.person_display_name,'')),'') is not null when 'location' then nullif(btrim(coalesce(response_row.location_label,'')),'') is not null
      when 'product_material' then response_row.product_material_value is not null and nullif(btrim(response_row.product_material_value->>'productName'),'') is not null
      when 'photo' then (select count(*) from public.project_qa_response_evidence where project_qa_response_id=response_row.id and evidence_type='photo')>=minimum_evidence
      when 'file' then (select count(*) from public.project_qa_response_evidence where project_qa_response_id=response_row.id and evidence_type='file')>=1
      when 'signature' then (
        response_row.signature_method='typed_acknowledgement' and response_row.signature_signed_at is not null and response_row.signature_signed_by is not null and nullif(btrim(response_row.signature_signer_name),'') is not null and nullif(btrim(response_row.signature_attestation),'') is not null
        or response_row.signature_method='drawn_signature' and response_row.signature_signed_at is not null and response_row.signature_signed_by is not null and nullif(btrim(response_row.signature_signer_name),'') is not null and nullif(btrim(response_row.signature_attestation),'') is not null and nullif(btrim(response_row.signature_recorded_by_name),'') is not null and response_row.signature_artifact_sha256~'^[a-f0-9]{64}$' and public.qa_signature_metadata_is_valid_v1(response_row.signature_artifact_metadata) and exists(select 1 from public.project_qa_response_evidence evidence where evidence.id=response_row.signature_evidence_id and evidence.project_qa_response_id=response_row.id and evidence.evidence_type='signature' and evidence.mime_type='image/png' and evidence.content_sha256=response_row.signature_artifact_sha256 and evidence.image_width=(response_row.signature_artifact_metadata->>'pixelWidth')::integer and evidence.image_height=(response_row.signature_artifact_metadata->>'pixelHeight')::integer)
      )
      else false end;
    if required and not answered then raise exception 'Required QA field "%" is incomplete',response_row.field_snapshot->>'label' using errcode='TS422'; end if;
    if response_row.field_type='inspection_check' then
      config:=coalesce(response_row.field_snapshot->'configuration','{}'::jsonb);
      comment_rule:=case when config->>'commentRule' in ('optional','required','required_on_fail') then config->>'commentRule' when coalesce((response_row.field_snapshot->>'requireCommentOnFail')::boolean,false) then 'required_on_fail' else 'optional' end;
      if comment_rule='required' and nullif(btrim(response_row.comment),'') is null then raise exception 'Check "%" requires a comment',response_row.field_snapshot->>'label' using errcode='TS422'; end if;
      if response_row.inspection_result='fail' and comment_rule='required_on_fail' and nullif(btrim(response_row.comment),'') is null then raise exception 'Failed check "%" requires a comment',response_row.field_snapshot->>'label' using errcode='TS422'; end if;
      select count(*) into evidence_count from public.project_qa_response_evidence where project_qa_response_id=response_row.id and evidence_type='photo';
      if coalesce((response_row.field_snapshot->>'photoRequired')::boolean,false) and evidence_count<minimum_evidence then raise exception 'Check "%" requires at least % photo(s)',response_row.field_snapshot->>'label',minimum_evidence using errcode='TS422'; end if;
      if response_row.inspection_result='fail' and coalesce((response_row.field_snapshot->>'requirePhotoOnFail')::boolean,false) and evidence_count<minimum_evidence then raise exception 'Failed check "%" requires at least % photo(s)',response_row.field_snapshot->>'label',minimum_evidence using errcode='TS422'; end if;
      if coalesce((response_row.field_snapshot->>'fileRequired')::boolean,false) and not exists(select 1 from public.project_qa_response_evidence where project_qa_response_id=response_row.id and evidence_type='file') then raise exception 'Check "%" requires a supporting file',response_row.field_snapshot->>'label' using errcode='TS422'; end if;
      if coalesce((config->>'holdPointEnabled')::boolean,false) and not exists(select 1 from public.project_qa_hold_releases release where release.response_id=response_row.id and release.status='released') then raise exception 'Hold Point "%" must be released before completion',response_row.field_snapshot->>'label' using errcode='TS422'; end if;
    end if;
    if response_row.field_type='measurement' and response_row.numeric_value is not null then
      config:=coalesce(response_row.field_snapshot->'configuration','{}'::jsonb); min_value:=nullif(config->>'minimum','')::numeric; max_value:=nullif(config->>'maximum','')::numeric; target_value:=nullif(config->>'target','')::numeric; tolerance_value:=nullif(config->>'tolerance','')::numeric;
      if min_value is not null and response_row.numeric_value<min_value then raise exception 'Measurement "%" is below its captured minimum',response_row.field_snapshot->>'label' using errcode='TS422'; end if;
      if max_value is not null and response_row.numeric_value>max_value then raise exception 'Measurement "%" is above its captured maximum',response_row.field_snapshot->>'label' using errcode='TS422'; end if;
      if min_value is null and max_value is null and target_value is not null and tolerance_value is not null and (response_row.numeric_value<target_value-tolerance_value or response_row.numeric_value>target_value+tolerance_value) then raise exception 'Measurement "%" is outside its captured target tolerance',response_row.field_snapshot->>'label' using errcode='TS422'; end if;
    end if;
  end loop;
  update public.project_qa_runs as target set status='completed',completed_by=auth.uid(),completed_at=now(),lock_version=target.lock_version+1 where target.id=run_row.id returning target.completed_at,target.lock_version into next_completed,next_lock;
  return query select 'completed'::text,next_completed,next_lock;
end; $_$;


ALTER FUNCTION "public"."complete_project_qa_run_v1"("p_organization_id" "uuid", "p_project_id" "uuid", "p_run_id" "uuid", "p_expected_lock_version" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_retention_claim_push_phase2c"("p_attempt_id" "uuid", "p_worker_id" "text", "p_lease_token" "uuid", "p_result" "jsonb") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
declare
  v_attempt public.organization_accounting_revision_attempts%rowtype;
  v_revision public.organization_accounting_document_revisions%rowtype;
  v_previous public.organization_accounting_document_revisions%rowtype;
  v_document public.organization_accounting_documents%rowtype;
  v_attachment_attempt public.organization_accounting_revision_attempts%rowtype;
  v_attachment_key text;
  v_finalized boolean;
begin
  select * into v_attempt
  from public.organization_accounting_revision_attempts
  where id = p_attempt_id
  for update;
  if not found
    or v_attempt.queue_state <> 'claimed'
    or v_attempt.worker_id <> p_worker_id
    or v_attempt.lease_token <> p_lease_token
    or v_attempt.lease_expires_at < now() then
    return false;
  end if;
  select * into v_revision
  from public.organization_accounting_document_revisions
  where id = v_attempt.accounting_revision_id
  for update;
  select * into v_document
  from public.organization_accounting_documents
  where id = v_revision.accounting_document_id
  for update;
  if v_revision.source_document_type <> 'retention_claim'
    or v_revision.revision_intent not in ('initial_push', 'replacement')
    or p_result->>'externalDocumentNumber' <>
      v_revision.external_document_number
    or nullif(trim(p_result->>'externalDocumentId'), '') is null then
    raise exception 'Verified Xero result does not match the immutable Retention Claim revision.';
  end if;
  if v_revision.revision_intent = 'initial_push' then
    if v_document.active_accounting_revision_id is not null then
      raise exception 'A Retention Claim revision is already active.';
    end if;
  else
    select * into v_previous
    from public.organization_accounting_document_revisions
    where id = v_revision.previous_revision_id
    for update;
    if v_document.active_accounting_revision_id <> v_previous.id
      or v_document.external_document_id <>
        v_previous.external_document_id then
      raise exception 'The Retention Claim predecessor changed before activation.';
    end if;
  end if;
  v_finalized := public.finalize_accounting_revision_attempt_phase2a(
    p_attempt_id, p_worker_id, p_lease_token, 'succeeded',
    case when coalesce((p_result->>'recovered')::boolean, false)
      then 'recovered_authorised_invoice'
      else 'verified_authorised_invoice' end,
    'Xero invoice exactly matched immutable Retention Claim revision.',
    p_result->'rawObservation'
  );
  if not v_finalized then return false; end if;
  update public.organization_accounting_documents
  set
    external_document_id = p_result->>'externalDocumentId',
    external_document_number = v_revision.external_document_number,
    amount_exported = v_revision.total_minor::numeric / 100,
    tax_exported = v_revision.tax_minor::numeric / 100,
    exported_by = v_revision.confirmed_by,
    exported_at = now(),
    last_synced_at = now(),
    raw_external_status = 'AUTHORISED',
    normalized_external_status = 'awaiting_payment',
    amount_paid = 0,
    amount_due = v_revision.total_minor::numeric / 100,
    amount_credited = 0,
    last_status_sync_error = null,
    export_status = 'exported',
    last_synced_hash =
      v_revision.commercial_snapshot->>'currentStateHash',
    last_error_code = null,
    last_error_message = null,
    updated_at = now()
  where id = v_document.id;
  perform public.activate_successful_accounting_revision_phase2a(
    v_revision.id, p_result->>'externalDocumentId'
  );
  perform public.record_accounting_remote_observation_phase2a(
    jsonb_build_object(
      'organizationId', v_revision.organization_id,
      'accountingDocumentId', v_document.id,
      'accountingRevisionId', v_revision.id,
      'provider', 'xero',
      'tenantId', v_revision.tenant_id,
      'externalDocumentId', p_result->>'externalDocumentId',
      'providerUpdatedAt', p_result->>'providerUpdatedAt',
      'rawStatus', 'AUTHORISED',
      'normalizedStatus', 'authorised_unpaid',
      'normalizedInvoiceStatus', 'authorised',
      'normalizedPaymentStatus', 'unpaid',
      'contentHash', v_revision.provider_content_hash,
      'settlementHash', p_result->>'settlementHash',
      'amountPaidMinor', '0',
      'amountDueMinor', v_revision.total_minor::text,
      'amountCreditedMinor', '0',
      'rawObservation', p_result->'rawObservation',
      'correlationId', p_attempt_id::text
    )
  );
  v_attachment_key := encode(digest((
    'xero:retention_claim:attachment:' || v_revision.id
  )::bytea, 'sha256'), 'hex');
  select * into v_attachment_attempt
  from public.create_accounting_revision_attempt_phase2a(
    v_revision.id, 'attach', v_attachment_key,
    jsonb_build_object(
      'accountingDocumentId', v_document.id,
      'accountingRevisionId', v_revision.id,
      'attachmentId', (
        select id
        from public.organization_accounting_revision_attachments
        where accounting_revision_id = v_revision.id
          and attachment_sequence = 1
      ),
      'tenantId', v_revision.tenant_id
    )
  );
  insert into public.organization_accounting_sync_jobs(
    organization_id, provider, connection_id, job_kind, trigger_source,
    request_payload, result_summary, idempotency_key, max_attempts,
    created_by_user_id
  ) values (
    v_revision.organization_id, 'xero', v_revision.connection_id,
    case when v_revision.revision_intent = 'initial_push'
      then 'xero.retention_claim.initial_push.attachment'
      else 'xero.retention_claim.replacement.attachment' end,
    'user_export',
    jsonb_build_object(
      'accountingDocumentId', v_document.id,
      'accountingRevisionId', v_revision.id,
      'attemptId', v_attachment_attempt.id,
      'tenantId', v_revision.tenant_id
    ),
    '{}'::jsonb, v_attachment_key, 5, v_revision.confirmed_by
  ) on conflict (idempotency_key)
    where idempotency_key is not null do nothing;
  return true;
end;
$$;


ALTER FUNCTION "public"."complete_retention_claim_push_phase2c"("p_attempt_id" "uuid", "p_worker_id" "text", "p_lease_token" "uuid", "p_result" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_retention_release_schedule"("p_input" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare s public.project_retention_release_schedules%rowtype; origins uuid[];
  blocks jsonb; result jsonb; ctx jsonb;
begin
  if not private.retention_phase5_gate_enabled() then
    return public.complete_retention_release_schedule_phase4_pre_variance(p_input);
  end if;
  select * into s from public.project_retention_release_schedules
  where id=(p_input->>'scheduleId')::uuid;
  if not found then return jsonb_build_object('succeeded',false,'errorCode','schedule_not_found'); end if;
  ctx:=private.retention_phase5_context(s.project_id,'retention.schedules.confirm',true);
  if not coalesce((ctx->>'succeeded')::boolean,false) then return ctx; end if;
  select coalesce(array_agg(o.originating_payment_claim_id order by o.originating_payment_claim_id),
    '{}'::uuid[]) into origins
  from public.project_retention_schedule_origins o where o.schedule_id=s.id;
  perform private.evaluate_retention_variance_project(
    s.project_id,p_input->>'correlationId',origins);
  blocks:=private.retention_variance_blocking_details(s.project_id,origins);
  if coalesce((blocks->>'blocking')::boolean,false) then
    return jsonb_build_object('succeeded',false,'errorCode','variance_blocking','details',blocks);
  end if;
  result:=public.complete_retention_release_schedule_phase4_pre_variance(p_input);
  if coalesce((result->>'succeeded')::boolean,false) then
    perform private.evaluate_retention_variance_project(
      s.project_id,p_input->>'correlationId',origins);
  end if;
  return result;
end;
$$;


ALTER FUNCTION "public"."complete_retention_release_schedule"("p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_retention_release_schedule_phase4_pre_variance"("p_input" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_s public.project_retention_release_schedules%rowtype; v_context jsonb; v_remaining numeric;
begin
  select * into v_s from public.project_retention_release_schedules where id=(p_input->>'scheduleId')::uuid;
  if not found then return jsonb_build_object('succeeded',false,'errorCode','schedule_not_found'); end if;
  v_context:=private.retention_phase4_context(v_s.project_id,'retention.schedules.confirm',true);
  if not coalesce((v_context->>'succeeded')::boolean,false) then return v_context; end if;
  select * into v_s from public.project_retention_release_schedules where id=v_s.id for update;
  if v_s.status<>'activated' then
    return jsonb_build_object('succeeded',false,'errorCode','schedule_not_activatable');
  end if;
  if v_s.revision<>(p_input->>'expectedRevision')::bigint then
    return jsonb_build_object('succeeded',false,'errorCode','concurrent_update','currentRevision',v_s.revision);
  end if;
  select coalesce(sum(greatest((x->>'availableRetention')::numeric,0)),0) into v_remaining
  from jsonb_array_elements(private.retention_eligibility_state(v_s.project_id)->'origins') x
  where (x->'scheduleIds') ? v_s.id::text;
  if v_remaining>0 and not coalesce((p_input->>'acknowledgeRemaining')::boolean,false) then
    return jsonb_build_object('succeeded',false,'errorCode','schedule_not_activatable',
      'remainingEligibleAmount',v_remaining);
  end if;
  perform set_config('app.retention_phase4_internal_write','true',true);
  update public.project_retention_release_schedules set
    status='completed',completed_at=now(),completed_by=auth.uid(),
    completion_reason=coalesce(nullif(trim(p_input->>'reason'),''),'Completed'),
    revision=revision+1
  where id=v_s.id returning * into v_s;
  perform set_config('app.retention_phase4_internal_write','',true);
  perform private.record_retention_schedule_event(
    v_s.id,'schedule_completed','activated','completed',v_s.completion_reason,
    p_input->>'correlationId',jsonb_build_object('remainingEligibleAmount',v_remaining)
  );
  return jsonb_build_object('succeeded',true,'errorCode',null,'schedule',to_jsonb(v_s));
end;
$$;


ALTER FUNCTION "public"."complete_retention_release_schedule_phase4_pre_variance"("p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_retention_reminder"("p_input" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_r public.retention_reminders%rowtype; v_context jsonb;
begin
  select * into v_r from public.retention_reminders where id=(p_input->>'reminderId')::uuid;
  if not found then return jsonb_build_object('succeeded',false,'errorCode','reminder_not_found'); end if;
  v_context:=private.retention_phase4_context(v_r.project_id,'retention.reminders.manage',true);
  if not coalesce((v_context->>'succeeded')::boolean,false) then return v_context; end if;
  select * into v_r from public.retention_reminders where id=v_r.id for update;
  if v_r.revision<>(p_input->>'expectedRevision')::bigint then
    return jsonb_build_object('succeeded',false,'errorCode','concurrent_update','currentRevision',v_r.revision);
  end if;
  if v_r.state in ('completed','cancelled') then
    return jsonb_build_object('succeeded',false,'errorCode','reminder_immutable');
  end if;
  update public.retention_reminders set state='completed',completed_at=now(),
    completed_by=auth.uid(),next_delivery_at=null,delivery_claimed_at=null,
    delivery_claim_token=null,revision=revision+1 where id=v_r.id returning * into v_r;
  perform private.record_retention_reminder_event(
    v_r.id,'reminder_completed',null,'completed',
    coalesce(nullif(trim(p_input->>'reason'),''),'Retention reminder completed.'),
    p_input->>'correlationId','{}'::jsonb
  );
  return jsonb_build_object('succeeded',true,'errorCode',null,'reminder',to_jsonb(v_r));
end;
$$;


ALTER FUNCTION "public"."complete_retention_reminder"("p_input" "jsonb") OWNER TO "postgres";


