begin
  return public.update_task(p_task_id, jsonb_build_object('status', 'Done'));
end;
$$;


ALTER FUNCTION "public"."complete_task"("p_task_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."compute_cost_item_source_fingerprint"("p_source_document_kind" "text", "p_source_line_table" "text", "p_section" "text", "p_description" "text", "p_quantity" numeric, "p_unit" "text", "p_unit_rate" numeric, "p_line_total" numeric, "p_is_optional" boolean, "p_sort_order" integer, "p_identity_a" "text" DEFAULT ''::"text", "p_identity_b" "text" DEFAULT ''::"text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select md5(
    concat_ws(
      '|',
      lower(regexp_replace(btrim(coalesce(p_source_document_kind, '')), '\s+', ' ', 'g')),
      lower(regexp_replace(btrim(coalesce(p_source_line_table, '')), '\s+', ' ', 'g')),
      lower(regexp_replace(btrim(coalesce(p_section, '')), '\s+', ' ', 'g')),
      lower(regexp_replace(btrim(coalesce(p_description, '')), '\s+', ' ', 'g')),
      to_char(round(coalesce(p_quantity, 0), 3), 'FM999999999999990D000'),
      lower(regexp_replace(btrim(coalesce(p_unit, '')), '\s+', ' ', 'g')),
      to_char(round(coalesce(p_unit_rate, 0), 2), 'FM999999999999990D00'),
      to_char(round(coalesce(p_line_total, 0), 2), 'FM999999999999990D00'),
      case when coalesce(p_is_optional, false) then '1' else '0' end,
      coalesce(p_sort_order, 0)::text,
      lower(regexp_replace(btrim(coalesce(p_identity_a, '')), '\s+', ' ', 'g')),
      lower(regexp_replace(btrim(coalesce(p_identity_b, '')), '\s+', ' ', 'g'))
    )
  );
$$;


ALTER FUNCTION "public"."compute_cost_item_source_fingerprint"("p_source_document_kind" "text", "p_source_line_table" "text", "p_section" "text", "p_description" "text", "p_quantity" numeric, "p_unit" "text", "p_unit_rate" numeric, "p_line_total" numeric, "p_is_optional" boolean, "p_sort_order" integer, "p_identity_a" "text", "p_identity_b" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."confirm_master_retention_claim_push"("p_input" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private', 'extensions'
    AS $$
declare
  v_org uuid := (p_input->>'organizationId')::uuid;
  v_project uuid := (p_input->>'projectId')::uuid;
  v_claim uuid := (p_input->>'retentionClaimId')::uuid;
  v_actor uuid := (p_input->>'confirmedBy')::uuid;
  v_connection uuid := (p_input->>'connectionId')::uuid;
  v_tenant text := p_input->>'tenantId';
  v_operation text := p_input->>'operation';
  v_claim_row public.retention_claims%rowtype;
  v_document public.organization_accounting_documents%rowtype;
  v_previous public.organization_accounting_document_revisions%rowtype;
  v_revision public.organization_accounting_document_revisions%rowtype;
  v_attempt public.organization_accounting_revision_attempts%rowtype;
  v_projection public.organization_accounting_projections%rowtype;
  v_observation public.organization_accounting_remote_observations%rowtype;
  v_proposal public.organization_accounting_push_proposals%rowtype;
  v_reservation public.organization_accounting_number_reservations%rowtype;
  v_source jsonb;
  v_source_hash text;
  v_number text;
  v_global_sequence bigint;
  v_idempotency text;
  v_job_id uuid;
begin
  if auth.role() <> 'service_role' then
    raise exception 'Master Retention confirmation is server-only.';
  end if;
  if v_operation not in ('INITIAL_EXPORT', 'UPDATE_EXISTING_INVOICE') then
    raise exception 'The resolved master Retention operation is not executable.';
  end if;
  if not private.retention_phase2c_actor_can_push(v_org, v_actor) then
    raise exception 'Retention Claim Push to Xero permission is required.';
  end if;
  if not exists (
    select 1 from public.organization_accounting_phase2b_settings setting
    where setting.organization_id = v_org
      and setting.retention_claim_immutable_xero_enabled
  ) then
    raise exception 'Immutable Retention Claim Push to Xero is not enabled.';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(v_claim::text, 2633));
  select * into v_claim_row
  from public.retention_claims
  where id = v_claim
    and organization_id = v_org
    and project_id = v_project
    and master_role = 'master_retention_claim'
  for update;
  if not found or v_claim_row.status <> 'submitted' then
    raise exception 'The master Retention Claim is no longer submitted.';
  end if;
  if v_claim_row.claim_number <> p_input->>'commercialClaimNumber' then
    raise exception 'The master Retention Claim identity changed.';
  end if;

  v_source := private.master_retention_claim_source(v_claim);
  if v_source is null then
    raise exception 'The cumulative master Retention source is unavailable.';
  end if;
  v_source_hash := encode(
    digest(convert_to(v_source::text, 'UTF8'), 'sha256'), 'hex'
  );
  if v_source_hash <> p_input->>'retentionSourceEvidenceHash'
    or (v_source->'claim'->>'submittedAt')::timestamptz is distinct from
      (p_input->>'sourceOptimisticRevision')::timestamptz then
    raise exception 'New Payment Claim retention appeared after preview.';
  end if;
  if jsonb_array_length(p_input->'lines') <>
      jsonb_array_length(v_source->'allocations')
    or exists (
      select 1
      from jsonb_array_elements(p_input->'lines') line
      where not exists (
        select 1
        from public.project_claims payment_claim
        where payment_claim.id = (line->>'originatingPaymentClaimId')::uuid
          and payment_claim.id = (line->>'sourceLineId')::uuid
          and payment_claim.organization_id = v_org
          and payment_claim.project_id = v_project
          and payment_claim.status = 'Submitted'
          and round(payment_claim.retention_withheld_amount * 100)::bigint =
            (line->>'lineAmountMinor')::bigint
      )
    ) then
    raise exception 'Cumulative Retention origin evidence changed.';
  end if;
  if not exists (
    select 1 from public.organization_xero_connections connection
    where connection.id = v_connection
      and connection.organization_id = v_org
      and connection.status = 'connected'
      and connection.tenant_id = v_tenant
      and connection.scope @> array['accounting.invoices']::text[]
  ) then
    raise exception 'The Xero connection, tenant, or invoice scope changed.';
  end if;

  select * into v_proposal
  from public.organization_accounting_push_proposals
  where id = (p_input->>'proposalId')::uuid
    and organization_id = v_org
    and project_id = v_project
    and source_document_type = 'retention_claim'
    and source_document_id = v_claim;
  if not found
    or v_proposal.expires_at <= now()
    or v_proposal.preview_hash <> p_input->>'previewHash'
    or v_proposal.operation <> v_operation
    or v_proposal.external_document_number <>
      p_input->>'externalDocumentNumber'
    or v_proposal.source_optimistic_revision::timestamptz is distinct from
      (p_input->>'sourceOptimisticRevision')::timestamptz
    or v_proposal.evidence_hashes->>'sourceEvidenceHash' <>
      p_input->>'sourceEvidenceHash'
    or v_proposal.evidence_hashes->>'dependencyHash' <>
      p_input->>'dependencyHash'
    or v_proposal.evidence_hashes->>'commercialHash' <>
      p_input->>'commercialHash'
    or v_proposal.evidence_hashes->>'linesHash' <>
      p_input->>'linesHash'
    or v_proposal.evidence_hashes->>'payloadHash' <>
      p_input->>'payloadHash' then
    raise exception 'The structured master Retention proposal is missing, expired, or stale.';
  end if;

  select * into v_document
  from public.organization_accounting_documents
  where organization_id = v_org
    and provider = 'xero'
    and local_document_type = 'retention_claim'
    and retention_claim_id = v_claim
  for update;
  if not found then
    if v_operation <> 'INITIAL_EXPORT' then
      raise exception 'The master Retention accounting document is missing.';
    end if;
    insert into public.organization_accounting_documents(
      organization_id, accounting_connection_id, provider, tenant_id,
      local_document_type, retention_claim_id, export_status,
      currency_code, integration_contract
    ) values (
      v_org, v_connection, 'xero', v_tenant,
      'retention_claim', v_claim, 'not_ready',
      'NZD', 'retention_claim_revision_v1'
    ) returning * into v_document;
  end if;
  if v_document.accounting_connection_id <> v_connection
    or v_document.tenant_id <> v_tenant
    or v_document.integration_contract <> 'retention_claim_revision_v1' then
    raise exception 'The master Retention accounting identity changed.';
  end if;

  select * into v_revision
  from public.organization_accounting_document_revisions revision
  where revision.accounting_document_id = v_document.id
    and revision.confirmation_preview_hash = p_input->>'previewHash'
    and revision.external_document_number = p_input->>'externalDocumentNumber'
  order by revision.revision_sequence
  limit 1;
  if found then
    select * into v_attempt
    from public.organization_accounting_revision_attempts attempt
    where attempt.accounting_revision_id = v_revision.id
      and attempt.attempt_intent in ('create', 'update')
    order by attempt.attempt_sequence
    limit 1;
    select job.id into v_job_id
    from public.organization_accounting_sync_jobs job
    where job.organization_id = v_org
      and job.job_kind in (
        'xero.retention_claim.initial_push',
        'xero.retention_claim.update'
      )
      and job.request_payload->>'accountingRevisionId' = v_revision.id::text
    order by job.created_at
    limit 1;
    if v_attempt.id is null or v_job_id is null then
      raise exception 'The existing master Retention confirmation is incomplete.';
    end if;
    return jsonb_build_object(
      'accountingDocumentId', v_document.id,
      'accountingRevisionId', v_revision.id,
      'attemptId', v_attempt.id,
      'jobId', v_job_id,
      'invoiceNumber', v_revision.external_document_number,
      'revisionSequence', v_revision.revision_sequence,
      'status', case
        when v_revision.lifecycle_state = 'succeeded' then 'completed'
        when v_revision.lifecycle_state = 'processing' then 'processing'
        else 'queued'
      end
    );
  end if;

  v_number := v_claim_row.claim_number;
  if p_input->>'externalDocumentNumber' <> v_number
    or p_input->'payloadTemplate'->>'InvoiceNumber' <> v_number
    or p_input->'payloadTemplate'->>'Type' <> 'ACCREC'
    or p_input->'payloadTemplate'->>'Status' <> 'AUTHORISED' then
    raise exception 'The confirmed master Retention invoice identity is stale.';
  end if;
  if v_operation = 'INITIAL_EXPORT' then
    if v_document.active_accounting_revision_id is not null
      or v_document.external_document_id is not null
      or exists (
        select 1 from public.organization_accounting_document_revisions revision
        where revision.accounting_document_id = v_document.id
      ) then
      raise exception 'An initial master Retention revision already exists.';
    end if;
    insert into public.organization_accounting_number_counters(
      organization_id, provider, tenant_id, document_class, last_sequence
    ) values (v_org, 'xero', v_tenant, 'sales_invoice', 1)
    on conflict (organization_id, provider, tenant_id, document_class)
    do update set
      last_sequence =
        public.organization_accounting_number_counters.last_sequence + 1,
      updated_at = now()
    returning last_sequence into v_global_sequence;
    insert into public.organization_accounting_number_reservations(
      organization_id, provider, tenant_id, document_class,
      sequence_number, formatted_number, accounting_document_id,
      source_document_type, source_document_id, reservation_reason, reserved_by
    ) values (
      v_org, 'xero', v_tenant, 'sales_invoice',
      v_global_sequence, v_number, v_document.id,
      'retention_claim', v_claim, 'retention_claim_initial_push', v_actor
    ) returning * into v_reservation;
  else
    select * into v_previous
    from public.organization_accounting_document_revisions
    where id = v_document.active_accounting_revision_id
      and id = (p_input->>'previousRevisionId')::uuid
      and accounting_document_id = v_document.id
      and lifecycle_state = 'succeeded'
    for update;
    if not found
      or v_previous.external_document_id <> p_input->>'previousInvoiceId'
      or v_previous.external_document_number <> v_number
      or v_document.external_document_id <> v_previous.external_document_id
      or v_document.external_document_number <> v_number then
      raise exception 'The active master Retention Xero invoice changed.';
    end if;
    select * into v_projection
    from public.organization_accounting_projections
    where accounting_document_id = v_document.id
      and accounting_revision_id = v_previous.id
    for update;
    if not found
      or v_projection.normalized_invoice_status not in (
        'authorised', 'awaiting_payment'
      )
      or coalesce(v_projection.amount_paid_minor, 0) <> 0
      or coalesce(v_projection.amount_credited_minor, 0) <> 0
      or v_projection.divergent then
      raise exception 'The existing Xero invoice is not safely updateable.';
    end if;
    select * into v_observation
    from public.organization_accounting_remote_observations
    where id = v_projection.remote_observation_id
      and accounting_revision_id = v_previous.id
      and external_document_id = v_previous.external_document_id;
    if not found
      or v_observation.id <> (p_input->>'previousObservationId')::uuid
      or upper(coalesce(v_observation.raw_status, '')) <> 'AUTHORISED'
      or jsonb_array_length(
        coalesce(v_observation.raw_observation->'Payments', '[]'::jsonb)
      ) <> 0
      or jsonb_array_length(
        coalesce(v_observation.raw_observation->'CreditNotes', '[]'::jsonb)
      ) <> 0 then
      raise exception 'Payments, credits, or Xero state prevent this update.';
    end if;
    select * into v_reservation
    from public.organization_accounting_number_reservations
    where id = v_previous.number_reservation_id
      and accounting_document_id = v_document.id
      and formatted_number = v_number;
    if not found then
      raise exception 'The stable master Retention invoice number is not reserved.';
    end if;
  end if;

  select * into v_revision
  from public.persist_confirmed_accounting_revision_phase2a(
    jsonb_build_object(
      'organizationId', v_org,
      'projectId', v_project,
      'accountingDocumentId', v_document.id,
      'sourceDocumentType', 'retention_claim',
      'sourceDocumentId', v_claim,
      'revisionIntent', case when v_operation = 'INITIAL_EXPORT'
        then 'initial_push' else 'direct_update' end,
      'resolutionStrategy', case when v_operation = 'INITIAL_EXPORT'
        then 'new_document' else 'update_existing' end,
      'previousRevisionId', case when v_operation = 'INITIAL_EXPORT'
        then null else v_previous.id end,
      'provider', 'xero',
      'connectionId', v_connection,
      'tenantId', v_tenant,
      'numberReservationId', v_reservation.id,
      'externalDocumentNumber', v_number,
      'commercialSnapshot', p_input->'commercialSnapshot',
      'contactSnapshot', p_input->'contactSnapshot',
      'routingSnapshot', p_input->'routingSnapshot',
      'taxSnapshot', p_input->'taxSnapshot',
      'attachmentSnapshot', jsonb_build_object(
        'required', false, 'evidenceModel', 'structured_only'
      ),
      'payloadSnapshot', p_input->'payloadTemplate',
      'canonicalSchemaVersion', p_input->>'canonicalSchemaVersion',
      'sourceEvidenceHash', p_input->>'sourceEvidenceHash',
      'commercialHash', p_input->>'commercialHash',
      'linesHash', p_input->>'linesHash',
      'payloadHash', p_input->>'payloadHash',
      'providerContentHash', p_input->>'payloadHash',
      'pdfHash', null,
      'currencyCode', 'NZD',
      'providerDocumentType', 'ACCREC',
      'requestedProviderStatus', 'AUTHORISED',
      'lineAmountType', 'Exclusive',
      'subtotalMinor', p_input->>'subtotalMinor',
      'taxMinor', p_input->>'taxMinor',
      'totalMinor', p_input->>'totalMinor',
      'confirmationPreviewHash', p_input->>'previewHash',
      'confirmedBy', v_actor,
      'confirmedAt', now(),
      'confirmationReason', case when v_operation = 'INITIAL_EXPORT'
        then null else 'New cumulative Retention added' end,
      'correlationId', p_input->>'proposalId',
      'lines', p_input->'lines',
      'attachments', '[]'::jsonb
    )
  );
  v_idempotency := encode(digest(convert_to(
    'xero:master_retention:' ||
    case when v_operation = 'INITIAL_EXPORT' then 'create:' else 'update:' end ||
    v_revision.id,
    'UTF8'
  ), 'sha256'), 'hex');
  select * into v_attempt
  from public.create_accounting_revision_attempt_phase2a(
    v_revision.id,
    case when v_operation = 'INITIAL_EXPORT' then 'create' else 'update' end,
    v_idempotency,
    jsonb_build_object(
      'accountingDocumentId', v_document.id,
      'accountingRevisionId', v_revision.id,
      'previousRevisionId', v_previous.id,
      'externalDocumentId', v_previous.external_document_id,
      'payloadHash', p_input->>'payloadHash',
      'tenantId', v_tenant,
      'intent', case when v_operation = 'INITIAL_EXPORT'
        then 'initial_push' else 'direct_update' end
    )
  );
  perform public.transition_accounting_revision_lifecycle_phase2a(
    v_revision.id, 'queued', null, null
  );
  insert into public.organization_accounting_sync_jobs(
    organization_id, provider, connection_id, job_kind, trigger_source,
    request_payload, result_summary, idempotency_key, max_attempts,
    created_by_user_id
  ) values (
    v_org, 'xero', v_connection,
    case when v_operation = 'INITIAL_EXPORT'
      then 'xero.retention_claim.initial_push'
      else 'xero.retention_claim.update' end,
    'user_export',
    jsonb_build_object(
      'accountingDocumentId', v_document.id,
      'accountingRevisionId', v_revision.id,
      'attemptId', v_attempt.id,
      'previousRevisionId', v_previous.id,
      'externalDocumentId', v_previous.external_document_id,
      'payloadHash', p_input->>'payloadHash',
      'tenantId', v_tenant
    ),
    '{}'::jsonb, v_idempotency, 5, v_actor
  ) returning id into v_job_id;
  update public.organization_accounting_documents
  set export_status = 'queued', updated_at = now()
  where id = v_document.id;
  return jsonb_build_object(
    'accountingDocumentId', v_document.id,
    'accountingRevisionId', v_revision.id,
    'attemptId', v_attempt.id,
    'jobId', v_job_id,
    'invoiceNumber', v_number,
    'revisionSequence', v_revision.revision_sequence,
    'status', 'queued'
  );
end;
$$;


ALTER FUNCTION "public"."confirm_master_retention_claim_push"("p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."confirm_master_retention_claim_replacement"("p_input" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private', 'extensions'
    AS $_$
declare
  v_org uuid := (p_input->>'organizationId')::uuid;
  v_project uuid := (p_input->>'projectId')::uuid;
  v_claim uuid := (p_input->>'retentionClaimId')::uuid;
  v_actor uuid := (p_input->>'confirmedBy')::uuid;
  v_connection uuid := (p_input->>'connectionId')::uuid;
  v_tenant text := p_input->>'tenantId';
  v_claim_row public.retention_claims%rowtype;
  v_document public.organization_accounting_documents%rowtype;
  v_previous public.organization_accounting_document_revisions%rowtype;
  v_revision public.organization_accounting_document_revisions%rowtype;
  v_attempt public.organization_accounting_revision_attempts%rowtype;
  v_projection public.organization_accounting_projections%rowtype;
  v_observation public.organization_accounting_remote_observations%rowtype;
  v_proposal public.organization_accounting_push_proposals%rowtype;
  v_reservation public.organization_accounting_number_reservations%rowtype;
  v_source jsonb;
  v_source_hash text;
  v_number text;
  v_replacement_sequence bigint;
  v_global_sequence bigint;
  v_idempotency text;
  v_job_id uuid;
begin
  if auth.role() <> 'service_role' then
    raise exception 'Master Retention replacement confirmation is server-only.';
  end if;
  if p_input->>'operation' <> 'REPLACEMENT_EXPORT' then
    raise exception 'XERO_STATE_CHANGED: The resolved master Retention operation is no longer replacement.';
  end if;
  if not private.retention_phase2c_actor_can_push(v_org, v_actor) then
    raise exception 'Retention Claim Push to Xero permission is required.';
  end if;
  if not exists (
    select 1
    from public.organization_accounting_phase2b_settings setting
    where setting.organization_id = v_org
      and setting.retention_claim_immutable_xero_enabled
  ) then
    raise exception 'Immutable Retention Claim Push to Xero is not enabled.';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(v_claim::text, 2636));
  select * into v_claim_row
  from public.retention_claims
  where id = v_claim
    and organization_id = v_org
    and project_id = v_project
    and master_role = 'master_retention_claim'
  for update;
  if not found
    or v_claim_row.status <> 'submitted'
    or v_claim_row.claim_number <> p_input->>'commercialClaimNumber' then
    raise exception 'RETENTION_MASTER_CHANGED: The submitted master Retention Claim identity changed.';
  end if;

  v_source := private.master_retention_claim_source(v_claim);
  if v_source is null then
    raise exception 'RETENTION_MASTER_CHANGED: The cumulative master Retention source is unavailable.';
  end if;
  v_source_hash := encode(
    digest(convert_to(v_source::text, 'UTF8'), 'sha256'), 'hex'
  );
  if v_source_hash <> p_input->>'retentionSourceEvidenceHash'
    or (v_source->'claim'->>'submittedAt')::timestamptz is distinct from
      (p_input->>'sourceOptimisticRevision')::timestamptz then
    raise exception 'RETENTION_MASTER_CHANGED: New Payment Claim retention appeared after preview.';
  end if;
  if jsonb_array_length(p_input->'lines') <>
      jsonb_array_length(v_source->'allocations')
    or exists (
      select 1
      from jsonb_array_elements(p_input->'lines') line
      where not exists (
        select 1
        from public.project_claims payment_claim
        where payment_claim.id = (line->>'originatingPaymentClaimId')::uuid
          and payment_claim.id = (line->>'sourceLineId')::uuid
          and payment_claim.organization_id = v_org
          and payment_claim.project_id = v_project
          and payment_claim.status = 'Submitted'
          and round(payment_claim.retention_withheld_amount * 100)::bigint =
            (line->>'lineAmountMinor')::bigint
      )
    ) then
    raise exception 'RETENTION_MASTER_CHANGED: Cumulative Retention origin evidence changed.';
  end if;
  if not exists (
    select 1
    from public.organization_xero_connections connection
    where connection.id = v_connection
      and connection.organization_id = v_org
      and connection.status = 'connected'
      and connection.tenant_id = v_tenant
      and connection.scope @> array['accounting.invoices']::text[]
  ) then
    raise exception 'The Xero connection, tenant, or invoice scope changed.';
  end if;

  select * into v_proposal
  from public.organization_accounting_push_proposals
  where id = (p_input->>'proposalId')::uuid
    and organization_id = v_org
    and project_id = v_project
    and source_document_type = 'retention_claim'
    and source_document_id = v_claim;
  if not found or v_proposal.expires_at <= now() then
    raise exception 'PROPOSAL_EXPIRED: The master Retention replacement proposal is missing or expired.';
  end if;
  if v_proposal.preview_hash <> p_input->>'previewHash'
    or v_proposal.operation <> 'REPLACEMENT_EXPORT'
    or v_proposal.external_document_number <>
      p_input->>'externalDocumentNumber'
    or v_proposal.source_optimistic_revision::timestamptz is distinct from
      (p_input->>'sourceOptimisticRevision')::timestamptz
    or v_proposal.evidence_hashes->>'sourceEvidenceHash' <>
      p_input->>'sourceEvidenceHash'
    or v_proposal.evidence_hashes->>'dependencyHash' <>
      p_input->>'dependencyHash'
    or v_proposal.evidence_hashes->>'commercialHash' <>
      p_input->>'commercialHash'
    or v_proposal.evidence_hashes->>'linesHash' <>
      p_input->>'linesHash'
    or v_proposal.evidence_hashes->>'payloadHash' <>
      p_input->>'payloadHash' then
    raise exception 'XERO_STATE_CHANGED: The structured master Retention replacement proposal is stale.';
  end if;

  select * into v_document
  from public.organization_accounting_documents
  where organization_id = v_org
    and provider = 'xero'
    and local_document_type = 'retention_claim'
    and retention_claim_id = v_claim
  for update;
  if not found
    or v_document.accounting_connection_id <> v_connection
    or v_document.tenant_id <> v_tenant
    or v_document.integration_contract <> 'retention_claim_revision_v1' then
    raise exception 'ACTIVE_REVISION_CHANGED: The master Retention accounting identity changed.';
  end if;

  -- A repeated confirmation of this exact preview reuses all durable
  -- identities and never allocates another replacement number.
  select * into v_revision
  from public.organization_accounting_document_revisions revision
  where revision.accounting_document_id = v_document.id
    and revision.confirmation_preview_hash = p_input->>'previewHash'
    and revision.external_document_number =
      p_input->>'externalDocumentNumber'
  order by revision.revision_sequence
  limit 1;
  if found then
    select * into v_attempt
    from public.organization_accounting_revision_attempts attempt
    where attempt.accounting_revision_id = v_revision.id
      and attempt.attempt_intent = 'replace'
    order by attempt.attempt_sequence
    limit 1;
    select job.id into v_job_id
    from public.organization_accounting_sync_jobs job
    where job.organization_id = v_org
      and job.job_kind = 'xero.retention_claim.replacement'
      and job.request_payload->>'accountingRevisionId' = v_revision.id::text
    order by job.created_at
    limit 1;
    if v_attempt.id is null or v_job_id is null then
      raise exception 'The existing master Retention replacement confirmation is incomplete.';
    end if;
    return jsonb_build_object(
      'accountingDocumentId', v_document.id,
      'accountingRevisionId', v_revision.id,
      'attemptId', v_attempt.id,
      'jobId', v_job_id,
      'invoiceNumber', v_revision.external_document_number,
      'revisionSequence', v_revision.revision_sequence,
      'status', case
        when v_revision.lifecycle_state = 'succeeded' then 'completed'
        when v_revision.lifecycle_state = 'processing' then 'processing'
        else 'queued'
      end
    );
  end if;

  select * into v_previous
  from public.organization_accounting_document_revisions
  where id = v_document.active_accounting_revision_id
    and id = (p_input->>'previousRevisionId')::uuid
    and accounting_document_id = v_document.id
    and lifecycle_state = 'succeeded'
  for update;
  if not found
    or v_previous.external_document_id <> p_input->>'previousInvoiceId'
    or v_previous.external_document_number <>
      p_input->>'previousInvoiceNumber'
    or v_document.external_document_id <> v_previous.external_document_id
    or v_document.external_document_number <>
      v_previous.external_document_number then
    raise exception 'ACTIVE_REVISION_CHANGED: The active master Retention revision changed.';
  end if;

  select * into v_projection
  from public.organization_accounting_projections
  where accounting_document_id = v_document.id
    and accounting_revision_id = v_previous.id
  for update;
  if not found
    or v_projection.normalized_invoice_status not in ('voided', 'deleted')
    or coalesce(v_projection.amount_paid_minor, 0) <> 0
    or coalesce(v_projection.amount_credited_minor, 0) <> 0
    or v_projection.divergent then
    raise exception 'REPLACEMENT_NO_LONGER_ELIGIBLE: The previous invoice is not voided, unpaid, uncredited, and non-divergent.';
  end if;
  select * into v_observation
  from public.organization_accounting_remote_observations
  where id = v_projection.remote_observation_id
    and id = (p_input->>'previousObservationId')::uuid
    and accounting_revision_id = v_previous.id
    and external_document_id = v_previous.external_document_id;
  if not found
    or upper(coalesce(v_observation.raw_status, '')) not in ('VOIDED', 'DELETED')
    or jsonb_array_length(
      coalesce(v_observation.raw_observation->'Payments', '[]'::jsonb)
    ) <> 0
    or jsonb_array_length(
      coalesce(v_observation.raw_observation->'CreditNotes', '[]'::jsonb)
    ) <> 0 then
    raise exception 'XERO_STATE_CHANGED: The exact voided Xero observation changed.';
  end if;

  select coalesce(max(
    case
      when left(
        revision.external_document_number,
        char_length(v_claim_row.claim_number) + 2
      ) = v_claim_row.claim_number || '-R'
        and substring(
          revision.external_document_number
          from char_length(v_claim_row.claim_number) + 3
        ) ~ '^[1-9][0-9]*$'
      then substring(
        revision.external_document_number
        from char_length(v_claim_row.claim_number) + 3
      )::bigint
      else 0
    end
  ), 0) + 1 into v_replacement_sequence
  from public.organization_accounting_document_revisions revision
  where revision.accounting_document_id = v_document.id;
  v_number := v_claim_row.claim_number || '-R' || v_replacement_sequence;
  if p_input->>'externalDocumentNumber' <> v_number
    or p_input->'payloadTemplate'->>'InvoiceNumber' <> v_number
    or p_input->'payloadTemplate'->>'Type' <> 'ACCREC'
    or p_input->'payloadTemplate'->>'Status' <> 'AUTHORISED' then
    raise exception 'XERO_STATE_CHANGED: The replacement invoice identity changed.';
  end if;

  insert into public.organization_accounting_number_counters(
    organization_id, provider, tenant_id, document_class, last_sequence
  ) values (v_org, 'xero', v_tenant, 'sales_invoice', 1)
  on conflict (organization_id, provider, tenant_id, document_class)
  do update set
    last_sequence =
      public.organization_accounting_number_counters.last_sequence + 1,
    updated_at = now()
  returning last_sequence into v_global_sequence;
  insert into public.organization_accounting_number_reservations(
    organization_id, provider, tenant_id, document_class,
    sequence_number, formatted_number, accounting_document_id,
    source_document_type, source_document_id, reservation_reason, reserved_by
  ) values (
    v_org, 'xero', v_tenant, 'sales_invoice',
    v_global_sequence, v_number, v_document.id,
    'retention_claim', v_claim, 'replacement', v_actor
  ) returning * into v_reservation;

  select * into v_revision
  from public.persist_confirmed_accounting_revision_phase2a(
    jsonb_build_object(
      'organizationId', v_org,
      'projectId', v_project,
      'accountingDocumentId', v_document.id,
      'sourceDocumentType', 'retention_claim',
      'sourceDocumentId', v_claim,
      'revisionIntent', 'replacement',
      'resolutionStrategy', 'replacement',
      'previousRevisionId', v_previous.id,
      'provider', 'xero',
      'connectionId', v_connection,
      'tenantId', v_tenant,
      'numberReservationId', v_reservation.id,
      'externalDocumentNumber', v_number,
      'commercialSnapshot', p_input->'commercialSnapshot',
      'contactSnapshot', p_input->'contactSnapshot',
      'routingSnapshot', p_input->'routingSnapshot',
      'taxSnapshot', p_input->'taxSnapshot',
      'attachmentSnapshot', jsonb_build_object(
        'required', false, 'evidenceModel', 'structured_only'
      ),
      'payloadSnapshot', p_input->'payloadTemplate',
      'canonicalSchemaVersion', p_input->>'canonicalSchemaVersion',
      'sourceEvidenceHash', p_input->>'sourceEvidenceHash',
      'commercialHash', p_input->>'commercialHash',
      'linesHash', p_input->>'linesHash',
      'payloadHash', p_input->>'payloadHash',
      'providerContentHash', p_input->>'payloadHash',
      'pdfHash', null,
      'currencyCode', 'NZD',
      'providerDocumentType', 'ACCREC',
      'requestedProviderStatus', 'AUTHORISED',
      'lineAmountType', 'Exclusive',
      'subtotalMinor', p_input->>'subtotalMinor',
      'taxMinor', p_input->>'taxMinor',
      'totalMinor', p_input->>'totalMinor',
      'confirmationPreviewHash', p_input->>'previewHash',
      'confirmedBy', v_actor,
      'confirmedAt', now(),
      'confirmationReason', 'Previous Xero invoice voided',
      'correlationId', p_input->>'proposalId',
      'lines', p_input->'lines',
      'attachments', '[]'::jsonb
    )
  );
  v_idempotency := encode(digest(convert_to(
    'xero:master_retention:replacement:' || v_revision.id,
    'UTF8'
  ), 'sha256'), 'hex');
  select * into v_attempt
  from public.create_accounting_revision_attempt_phase2a(
    v_revision.id,
    'replace',
    v_idempotency,
    jsonb_build_object(
      'accountingDocumentId', v_document.id,
      'accountingRevisionId', v_revision.id,
      'previousRevisionId', v_previous.id,
      'externalDocumentId', v_previous.external_document_id,
      'payloadHash', p_input->>'payloadHash',
      'tenantId', v_tenant,
      'intent', 'replacement'
    )
  );
  perform public.transition_accounting_revision_lifecycle_phase2a(
    v_revision.id, 'queued', null, null
  );
  insert into public.organization_accounting_sync_jobs(
    organization_id, provider, connection_id, job_kind, trigger_source,
    request_payload, result_summary, idempotency_key, max_attempts,
    created_by_user_id
  ) values (
    v_org, 'xero', v_connection, 'xero.retention_claim.replacement',
    'user_export',
    jsonb_build_object(
      'accountingDocumentId', v_document.id,
      'accountingRevisionId', v_revision.id,
      'attemptId', v_attempt.id,
      'previousRevisionId', v_previous.id,
      'externalDocumentId', v_previous.external_document_id,
      'payloadHash', p_input->>'payloadHash',
      'tenantId', v_tenant
    ),
    '{}'::jsonb, v_idempotency, 5, v_actor
  ) returning id into v_job_id;
  update public.organization_accounting_documents
  set export_status = 'queued', updated_at = now()
  where id = v_document.id;
  insert into public.organization_accounting_events(
    organization_id, accounting_document_id, accounting_revision_id,
    accounting_attempt_id, event_type, actor_user_id,
    correlation_id, event_evidence
  ) values (
    v_org, v_document.id, v_revision.id, v_attempt.id,
    'decision_resolved', v_actor, p_input->>'proposalId',
    jsonb_build_object(
      'operation', 'REPLACEMENT_EXPORT',
      'commercialClaimNumber', v_claim_row.claim_number,
      'previousInvoiceId', v_previous.external_document_id,
      'previousInvoiceNumber', v_previous.external_document_number,
      'replacementInvoiceNumber', v_number,
      'previousObservationId', v_observation.id
    )
  );
  return jsonb_build_object(
    'accountingDocumentId', v_document.id,
    'accountingRevisionId', v_revision.id,
    'attemptId', v_attempt.id,
    'jobId', v_job_id,
    'invoiceNumber', v_number,
    'revisionSequence', v_revision.revision_sequence,
    'status', 'queued'
  );
end;
$_$;


ALTER FUNCTION "public"."confirm_master_retention_claim_replacement"("p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."confirm_master_retention_claim_update"("p_input" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private', 'extensions'
    AS $$
declare
  v_org uuid := (p_input->>'organizationId')::uuid;
  v_project uuid := (p_input->>'projectId')::uuid;
  v_claim uuid := (p_input->>'retentionClaimId')::uuid;
  v_actor uuid := (p_input->>'confirmedBy')::uuid;
  v_connection uuid := (p_input->>'connectionId')::uuid;
  v_tenant text := p_input->>'tenantId';
  v_claim_row public.retention_claims%rowtype;
  v_document public.organization_accounting_documents%rowtype;
  v_previous public.organization_accounting_document_revisions%rowtype;
  v_revision public.organization_accounting_document_revisions%rowtype;
  v_attempt public.organization_accounting_revision_attempts%rowtype;
  v_projection public.organization_accounting_projections%rowtype;
  v_observation public.organization_accounting_remote_observations%rowtype;
  v_proposal public.organization_accounting_push_proposals%rowtype;
  v_reservation public.organization_accounting_number_reservations%rowtype;
  v_source jsonb;
  v_source_hash text;
  v_number text;
  v_idempotency text;
  v_job_id uuid;
  v_payment_count integer := 0;
  v_credit_count integer := 0;
begin
  if auth.role() <> 'service_role' then
    raise exception 'Master Retention update confirmation is server-only.';
  end if;
  if p_input->>'operation' <> 'UPDATE_EXISTING_INVOICE' then
    raise exception 'The resolved master Retention operation is not an update.';
  end if;
  if not private.retention_phase2c_actor_can_push(v_org, v_actor) then
    raise exception 'Retention Claim Push to Xero permission is required.';
  end if;
  if not exists (
    select 1
    from public.organization_accounting_phase2b_settings setting
    where setting.organization_id = v_org
      and setting.retention_claim_immutable_xero_enabled
  ) then
    raise exception 'Immutable Retention Claim Push to Xero is not enabled.';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(v_claim::text, 2637));

  select * into v_claim_row
  from public.retention_claims
  where id = v_claim
    and organization_id = v_org
    and project_id = v_project
    and master_role = 'master_retention_claim'
  for update;
  if not found or v_claim_row.status <> 'submitted' then
    raise exception 'The master Retention Claim is no longer submitted.';
  end if;
  if v_claim_row.claim_number <> p_input->>'commercialClaimNumber' then
    raise exception 'The master Retention Claim identity changed.';
  end if;

  v_source := private.master_retention_claim_source(v_claim);
  if v_source is null then
    raise exception 'The cumulative master Retention source is unavailable.';
  end if;
  v_source_hash := encode(
    digest(convert_to(v_source::text, 'UTF8'), 'sha256'),
    'hex'
  );
  if v_source_hash <> p_input->>'retentionSourceEvidenceHash'
    or (v_source->'claim'->>'submittedAt')::timestamptz is distinct from
      (p_input->>'sourceOptimisticRevision')::timestamptz then
    raise exception 'New Payment Claim retention appeared after preview.';
  end if;
  if jsonb_array_length(p_input->'lines') <>
      jsonb_array_length(v_source->'allocations')
    or exists (
      select 1
      from jsonb_array_elements(p_input->'lines') line
      where not exists (
        select 1
        from public.project_claims payment_claim
        where payment_claim.id =
          (line->>'originatingPaymentClaimId')::uuid
          and payment_claim.id = (line->>'sourceLineId')::uuid
          and payment_claim.organization_id = v_org
          and payment_claim.project_id = v_project
          and payment_claim.status = 'Submitted'
          and round(
            payment_claim.retention_withheld_amount * 100
          )::bigint = (line->>'lineAmountMinor')::bigint
      )
    ) then
    raise exception 'Cumulative Retention origin evidence changed.';
  end if;
  if not exists (
    select 1
    from public.organization_xero_connections connection
    where connection.id = v_connection
      and connection.organization_id = v_org
      and connection.status = 'connected'
      and connection.tenant_id = v_tenant
      and connection.scope @> array['accounting.invoices']::text[]
  ) then
    raise exception 'The Xero connection, tenant, or invoice scope changed.';
  end if;

  select * into v_proposal
  from public.organization_accounting_push_proposals
  where id = (p_input->>'proposalId')::uuid
    and organization_id = v_org
    and project_id = v_project
    and source_document_type = 'retention_claim'
    and source_document_id = v_claim;
  if not found
    or v_proposal.expires_at <= now()
    or v_proposal.preview_hash <> p_input->>'previewHash'
    or v_proposal.operation <> 'UPDATE_EXISTING_INVOICE'
    or v_proposal.external_document_number <>
      p_input->>'externalDocumentNumber'
    or v_proposal.source_optimistic_revision::timestamptz is distinct from
      (p_input->>'sourceOptimisticRevision')::timestamptz
    or v_proposal.evidence_hashes->>'sourceEvidenceHash' <>
      p_input->>'sourceEvidenceHash'
    or v_proposal.evidence_hashes->>'dependencyHash' <>
      p_input->>'dependencyHash'
    or v_proposal.evidence_hashes->>'commercialHash' <>
      p_input->>'commercialHash'
    or v_proposal.evidence_hashes->>'linesHash' <>
      p_input->>'linesHash'
    or v_proposal.evidence_hashes->>'payloadHash' <>
      p_input->>'payloadHash' then
    raise exception 'The structured master Retention update proposal is missing, expired, or stale.';
  end if;

  select * into v_document
  from public.organization_accounting_documents
  where organization_id = v_org
    and provider = 'xero'
    and local_document_type = 'retention_claim'
    and retention_claim_id = v_claim
  for update;
  if not found
    or v_document.accounting_connection_id <> v_connection
    or v_document.tenant_id <> v_tenant
    or v_document.integration_contract <> 'retention_claim_revision_v1'
    or v_document.active_accounting_revision_id is null then
    raise exception 'The master Retention accounting identity changed.';
  end if;

  select * into v_revision
  from public.organization_accounting_document_revisions revision
  where revision.accounting_document_id = v_document.id
    and revision.confirmation_preview_hash = p_input->>'previewHash'
    and revision.external_document_number =
      p_input->>'externalDocumentNumber'
  order by revision.revision_sequence
  limit 1;
  if found then
    select * into v_attempt
    from public.organization_accounting_revision_attempts attempt
    where attempt.accounting_revision_id = v_revision.id
      and attempt.attempt_intent = 'update'
    order by attempt.attempt_sequence
    limit 1;
    select job.id into v_job_id
    from public.organization_accounting_sync_jobs job
    where job.organization_id = v_org
      and job.job_kind = 'xero.retention_claim.update'
      and job.request_payload->>'accountingRevisionId' =
        v_revision.id::text
    order by job.created_at
    limit 1;
    if v_attempt.id is null or v_job_id is null then
      raise exception 'The existing master Retention update confirmation is incomplete.';
    end if;
    return jsonb_build_object(
      'accountingDocumentId', v_document.id,
      'accountingRevisionId', v_revision.id,
      'attemptId', v_attempt.id,
      'jobId', v_job_id,
      'invoiceNumber', v_revision.external_document_number,
      'revisionSequence', v_revision.revision_sequence,
      'status', case
        when v_revision.lifecycle_state = 'succeeded' then 'completed'
        when v_revision.lifecycle_state = 'processing' then 'processing'
        else 'queued'
      end
    );
  end if;

  select * into v_previous
  from public.organization_accounting_document_revisions
  where id = v_document.active_accounting_revision_id
    and id = (p_input->>'previousRevisionId')::uuid
    and accounting_document_id = v_document.id
    and lifecycle_state = 'succeeded'
  for update;
  if not found then
    raise exception 'The active master Retention revision changed.';
  end if;

  v_number := v_previous.external_document_number;
  if nullif(trim(v_number), '') is null
    or v_previous.external_document_id <>
      p_input->>'previousInvoiceId'
    or v_document.external_document_id <>
      v_previous.external_document_id
    or v_document.external_document_number <> v_number
    or p_input->>'externalDocumentNumber' <> v_number
    or p_input->'payloadTemplate'->>'InvoiceNumber' <> v_number
    or p_input->'payloadTemplate'->>'Type' <> 'ACCREC'
    or p_input->'payloadTemplate'->>'Status' <> 'AUTHORISED' then
    raise exception 'The active master Retention Xero invoice changed.';
  end if;

  select * into v_projection
  from public.organization_accounting_projections
  where accounting_document_id = v_document.id
    and accounting_revision_id = v_previous.id
  for update;
  if not found
    or v_projection.normalized_invoice_status not in (
      'authorised',
      'awaiting_payment'
    )
    or coalesce(v_projection.amount_paid_minor, 0) <> 0
    or coalesce(v_projection.amount_credited_minor, 0) <> 0
    or v_projection.divergent then
    raise exception 'The existing Xero invoice is not safely updateable.';
  end if;

  select * into v_observation
  from public.organization_accounting_remote_observations
  where id = v_projection.remote_observation_id
    and accounting_revision_id = v_previous.id
    and external_document_id = v_previous.external_document_id;
  if found then
    v_payment_count := case
      when jsonb_typeof(v_observation.raw_observation->'Payments') = 'array'
      then jsonb_array_length(v_observation.raw_observation->'Payments')
      else 0
    end;
    v_credit_count := case
      when jsonb_typeof(v_observation.raw_observation->'CreditNotes') = 'array'
      then jsonb_array_length(v_observation.raw_observation->'CreditNotes')
      else 0
    end;
  end if;
  if not found
    or v_observation.id <>
      (p_input->>'previousObservationId')::uuid
    or upper(coalesce(v_observation.raw_status, '')) <> 'AUTHORISED'
    or v_payment_count <> 0
    or v_credit_count <> 0 then
    raise exception 'Payments, credits, or Xero state prevent this update.';
  end if;

  select * into v_reservation
  from public.organization_accounting_number_reservations
  where id = v_previous.number_reservation_id
    and accounting_document_id = v_document.id
    and formatted_number = v_number;
  if not found then
    raise exception 'The stable master Retention invoice number is not reserved.';
  end if;

  select * into v_revision
  from public.persist_confirmed_accounting_revision_phase2a(
    jsonb_build_object(
      'organizationId', v_org,
      'projectId', v_project,
      'accountingDocumentId', v_document.id,
      'sourceDocumentType', 'retention_claim',
      'sourceDocumentId', v_claim,
      'revisionIntent', 'direct_update',
      'resolutionStrategy', 'update_existing',
      'previousRevisionId', v_previous.id,
      'provider', 'xero',
      'connectionId', v_connection,
      'tenantId', v_tenant,
      'numberReservationId', v_reservation.id,
      'externalDocumentNumber', v_number,
      'commercialSnapshot', p_input->'commercialSnapshot',
      'contactSnapshot', p_input->'contactSnapshot',
      'routingSnapshot', p_input->'routingSnapshot',
      'taxSnapshot', p_input->'taxSnapshot',
      'attachmentSnapshot', jsonb_build_object(
        'required', false,
        'evidenceModel', 'structured_only'
      ),
      'payloadSnapshot', p_input->'payloadTemplate',
      'canonicalSchemaVersion',
        p_input->>'canonicalSchemaVersion',
      'sourceEvidenceHash', p_input->>'sourceEvidenceHash',
      'commercialHash', p_input->>'commercialHash',
      'linesHash', p_input->>'linesHash',
      'payloadHash', p_input->>'payloadHash',
      'providerContentHash', p_input->>'payloadHash',
      'pdfHash', null,
      'currencyCode', 'NZD',
      'providerDocumentType', 'ACCREC',
      'requestedProviderStatus', 'AUTHORISED',
      'lineAmountType', 'Exclusive',
      'subtotalMinor', p_input->>'subtotalMinor',
      'taxMinor', p_input->>'taxMinor',
      'totalMinor', p_input->>'totalMinor',
      'confirmationPreviewHash', p_input->>'previewHash',
      'confirmedBy', v_actor,
      'confirmedAt', now(),
      'confirmationReason', 'New cumulative Retention added',
      'correlationId', p_input->>'proposalId',
      'lines', p_input->'lines',
      'attachments', '[]'::jsonb
    )
  );

  v_idempotency := encode(digest(convert_to(
    'xero:master_retention:update:' || v_revision.id,
    'UTF8'
  ), 'sha256'), 'hex');
  select * into v_attempt
  from public.create_accounting_revision_attempt_phase2a(
    v_revision.id,
    'update',
    v_idempotency,
    jsonb_build_object(
      'accountingDocumentId', v_document.id,
      'accountingRevisionId', v_revision.id,
      'previousRevisionId', v_previous.id,
      'externalDocumentId', v_previous.external_document_id,
      'externalDocumentNumber', v_number,
      'payloadHash', p_input->>'payloadHash',
      'tenantId', v_tenant,
      'intent', 'direct_update'
    )
  );
  perform public.transition_accounting_revision_lifecycle_phase2a(
    v_revision.id,
    'queued',
    null,
    null
  );
  insert into public.organization_accounting_sync_jobs(
    organization_id,
    provider,
    connection_id,
    job_kind,
    trigger_source,
    request_payload,
    result_summary,
    idempotency_key,
    max_attempts,
    created_by_user_id
  ) values (
    v_org,
    'xero',
    v_connection,
    'xero.retention_claim.update',
    'user_export',
    jsonb_build_object(
      'accountingDocumentId', v_document.id,
      'accountingRevisionId', v_revision.id,
      'attemptId', v_attempt.id,
      'previousRevisionId', v_previous.id,
      'externalDocumentId', v_previous.external_document_id,
      'externalDocumentNumber', v_number,
      'payloadHash', p_input->>'payloadHash',
      'tenantId', v_tenant
    ),
    '{}'::jsonb,
    v_idempotency,
    5,
    v_actor
  )
  returning id into v_job_id;

  update public.organization_accounting_documents
  set export_status = 'queued',
      updated_at = now()
  where id = v_document.id;

  return jsonb_build_object(
    'accountingDocumentId', v_document.id,
    'accountingRevisionId', v_revision.id,
    'attemptId', v_attempt.id,
    'jobId', v_job_id,
    'invoiceNumber', v_number,
    'revisionSequence', v_revision.revision_sequence,
    'status', 'queued'
  );
end;
$$;


ALTER FUNCTION "public"."confirm_master_retention_claim_update"("p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."confirm_payment_claim_accounting_update"("p_input" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private', 'extensions'
    AS $$
declare
  v_org uuid := (p_input->>'organizationId')::uuid;
  v_project uuid := (p_input->>'projectId')::uuid;
  v_claim uuid := (p_input->>'claimId')::uuid;
  v_actor uuid := (p_input->>'confirmedBy')::uuid;
  v_connection uuid := (p_input->>'connectionId')::uuid;
  v_tenant text := p_input->>'tenantId';
  v_claim_row public.project_claims%rowtype;
  v_proposal public.organization_accounting_push_proposals%rowtype;
  v_document public.organization_accounting_documents%rowtype;
  v_previous public.organization_accounting_document_revisions%rowtype;
  v_projection public.organization_accounting_projections%rowtype;
  v_observation public.organization_accounting_remote_observations%rowtype;
  v_revision public.organization_accounting_document_revisions%rowtype;
  v_attempt public.organization_accounting_revision_attempts%rowtype;
  v_payment_count integer := 0;
  v_credit_count integer := 0;
  v_idempotency text;
  v_job_id uuid;
begin
  if auth.role() <> 'service_role' then
    raise exception 'Payment Claim accounting updates are server-only.';
  end if;
  if p_input->>'operation' <> 'ACCOUNTING_UPDATE' then
    raise exception 'The resolved Payment Claim operation is not an accounting update.';
  end if;
  if not private.phase2b_actor_has_push_permission(v_org, v_actor) then
    raise exception 'Payment Claim Push to Xero permission is required.';
  end if;
  if not exists (
    select 1
    from public.organization_accounting_phase2b_settings setting
    where setting.organization_id = v_org
      and setting.initial_payment_claim_push_enabled
  ) then
    raise exception 'Immutable Payment Claim Push to Xero is not enabled.';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(v_claim::text, 2645));
  select * into v_claim_row
  from public.project_claims claim
  where claim.id = v_claim
    and claim.organization_id = v_org
    and claim.project_id = v_project
  for update;
  if not found or v_claim_row.status <> 'Submitted' then
    raise exception 'The Payment Claim is no longer submitted.';
  end if;
  if v_claim_row.updated_at is distinct from
    (p_input->>'sourceOptimisticRevision')::timestamptz then
    raise exception 'The Payment Claim changed after the accounting preview was created.';
  end if;
  if not exists (
    select 1
    from public.organization_xero_connections connection
    where connection.id = v_connection
      and connection.organization_id = v_org
      and connection.tenant_id = v_tenant
      and connection.status = 'connected'
      and connection.scope @> array['accounting.invoices']::text[]
  ) then
    raise exception 'The Xero connection, tenant, or invoice scope changed.';
  end if;

  select * into v_proposal
  from public.organization_accounting_push_proposals proposal
  where proposal.id = (p_input->>'proposalId')::uuid
    and proposal.organization_id = v_org
    and proposal.project_id = v_project
    and proposal.source_document_type = 'project_claim'
    and proposal.source_document_id = v_claim;
  if not found
    or v_proposal.expires_at <= now()
    or v_proposal.operation <> 'ACCOUNTING_UPDATE'
    or v_proposal.preview_hash <> p_input->>'previewHash'
    or v_proposal.active_revision_id <>
      (p_input->>'previousRevisionId')::uuid
    or v_proposal.external_document_number <>
      p_input->>'externalDocumentNumber'
    or v_proposal.source_optimistic_revision::timestamptz is distinct from
      (p_input->>'sourceOptimisticRevision')::timestamptz
    or v_proposal.evidence_hashes->>'sourceEvidenceHash' <>
      p_input->>'sourceEvidenceHash'
    or v_proposal.evidence_hashes->>'commercialHash' <>
      p_input->>'commercialHash'
    or v_proposal.evidence_hashes->>'linesHash' <>
      p_input->>'linesHash'
    or v_proposal.evidence_hashes->>'dependencyHash' <>
      p_input->>'dependencyHash'
    or v_proposal.evidence_hashes->>'payloadHash' <>
      p_input->>'payloadHash' then
    raise exception 'The immutable Payment Claim amendment proposal is stale.';
  end if;

  select * into v_document
  from public.organization_accounting_documents document
  where document.id = v_proposal.accounting_document_id
    and document.organization_id = v_org
    and document.project_claim_id = v_claim
    and document.local_document_type = 'project_claim'
    and document.provider = 'xero'
  for update;
  if not found
    or v_document.integration_contract <> 'payment_claim_revision_v1'
    or v_document.accounting_connection_id <> v_connection
    or v_document.tenant_id <> v_tenant then
    raise exception 'The Payment Claim accounting document identity changed.';
  end if;

  select * into v_revision
  from public.organization_accounting_document_revisions revision
  where revision.accounting_document_id = v_document.id
    and revision.confirmation_preview_hash = p_input->>'previewHash'
    and revision.revision_intent = 'direct_update'
  order by revision.revision_sequence
  limit 1;
  if found then
    select * into v_attempt
    from public.organization_accounting_revision_attempts attempt
    where attempt.accounting_revision_id = v_revision.id
      and attempt.attempt_intent = 'update'
    order by attempt.attempt_sequence
    limit 1;
    select job.id into v_job_id
    from public.organization_accounting_sync_jobs job
    where job.organization_id = v_org
      and job.job_kind = 'xero.payment_claim.accounting_update'
      and job.request_payload->>'accountingRevisionId' = v_revision.id::text
    order by job.created_at
    limit 1;
    if v_attempt.id is null or v_job_id is null then
      raise exception 'The existing Payment Claim amendment confirmation is incomplete.';
    end if;
    return jsonb_build_object(
      'accountingDocumentId', v_document.id,
      'accountingRevisionId', v_revision.id,
      'attemptId', v_attempt.id,
      'jobId', v_job_id,
      'invoiceNumber', v_revision.external_document_number,
      'revisionSequence', v_revision.revision_sequence,
      'status', case
        when v_revision.lifecycle_state = 'succeeded' then 'completed'
        when v_revision.lifecycle_state = 'processing' then 'processing'
        else 'queued'
      end
    );
  end if;

  select * into v_previous
  from public.organization_accounting_document_revisions revision
  where revision.id = v_document.active_accounting_revision_id
    and revision.id = (p_input->>'previousRevisionId')::uuid
    and revision.accounting_document_id = v_document.id
    and revision.lifecycle_state = 'succeeded'
  for update;
  if not found
    or v_previous.external_document_id <> p_input->>'previousInvoiceId'
    or v_previous.external_document_number <>
      p_input->>'previousInvoiceNumber'
    or v_document.external_document_id <> v_previous.external_document_id
    or v_document.external_document_number <>
      v_previous.external_document_number
    or p_input->>'externalDocumentNumber' <>
      v_previous.external_document_number
    or p_input->'payloadTemplate'->>'InvoiceNumber' <>
      v_previous.external_document_number then
    raise exception 'The active Payment Claim Xero identity changed.';
  end if;
  if v_previous.number_reservation_id is null then
    if v_previous.revision_intent not in ('initial_push', 'direct_update')
      or v_previous.external_document_number <> v_claim_row.claim_number then
      raise exception 'The active Payment Claim number identity changed.';
    end if;
  elsif not exists (
    select 1
    from public.organization_accounting_number_reservations reservation
    where reservation.id = v_previous.number_reservation_id
      and reservation.accounting_document_id = v_document.id
      and reservation.formatted_number = v_previous.external_document_number
  ) then
    raise exception 'The existing Payment Claim invoice number reservation changed.';
  end if;

  select * into v_projection
  from public.organization_accounting_projections projection
  where projection.accounting_document_id = v_document.id
    and projection.accounting_revision_id = v_previous.id
  for update;
  if not found
    or v_projection.normalized_invoice_status not in (
      'authorised', 'awaiting_payment'
    )
    or coalesce(v_projection.amount_paid_minor, 0) <> 0
    or coalesce(v_projection.amount_credited_minor, 0) <> 0
    or v_projection.divergent then
    raise exception 'The existing Xero invoice is not safely amendable.';
  end if;
  select * into v_observation
  from public.organization_accounting_remote_observations observation
  where observation.id = v_projection.remote_observation_id
    and observation.id = (p_input->>'previousObservationId')::uuid
    and observation.accounting_revision_id = v_previous.id
    and observation.external_document_id = v_previous.external_document_id
  for update;
  if found then
    v_payment_count := case
      when jsonb_typeof(v_observation.raw_observation->'Payments') = 'array'
      then jsonb_array_length(v_observation.raw_observation->'Payments')
      else 0
    end;
    v_credit_count := case
      when jsonb_typeof(v_observation.raw_observation->'CreditNotes') = 'array'
      then jsonb_array_length(v_observation.raw_observation->'CreditNotes')
      else 0
    end;
  end if;
  if not found
    or upper(coalesce(v_observation.raw_status, '')) <> 'AUTHORISED'
    or v_payment_count <> 0
    or v_credit_count <> 0 then
    raise exception 'Payments, credits, or Xero state prevent this amendment.';
  end if;
  if exists (
    select 1
    from public.organization_accounting_revision_attempts attempt
    join public.organization_accounting_document_revisions revision
      on revision.id = attempt.accounting_revision_id
    where revision.accounting_document_id = v_document.id
      and attempt.attempt_intent in ('create', 'update', 'replace')
      and attempt.queue_state = 'attention_required'
  ) then
    raise exception 'An uncertain accounting attempt prevents this amendment.';
  end if;
  if exists (
    select 1
    from public.organization_accounting_sync_jobs job
    where job.organization_id = v_org
      and job.queue_state in ('pending', 'claimed', 'retry_scheduled')
      and job.request_payload->>'accountingDocumentId' = v_document.id::text
      and job.job_kind in (
        'xero.payment_claim.initial_push',
        'xero.payment_claim.replacement',
        'xero.payment_claim.accounting_update',
        'xero.sales_invoice.sync'
      )
  ) then
    raise exception 'Another Payment Claim accounting action is active.';
  end if;

  if p_input->'payloadTemplate'->>'Type' <> 'ACCREC'
    or p_input->'payloadTemplate'->>'Status' <> 'AUTHORISED' then
    raise exception 'The Payment Claim amendment payload is invalid.';
  end if;

  select * into v_revision
  from public.persist_confirmed_accounting_revision_phase2a(
    jsonb_build_object(
      'organizationId', v_org,
      'projectId', v_project,
      'accountingDocumentId', v_document.id,
      'sourceDocumentType', 'project_claim',
      'sourceDocumentId', v_claim,
      'revisionIntent', 'direct_update',
      'resolutionStrategy', 'update_existing',
      'previousRevisionId', v_previous.id,
      'provider', 'xero',
      'connectionId', v_connection,
      'tenantId', v_tenant,
      'numberReservationId', v_previous.number_reservation_id,
      'externalDocumentNumber', v_previous.external_document_number,
      'commercialSnapshot', p_input->'commercialSnapshot',
      'contactSnapshot', p_input->'contactSnapshot',
      'routingSnapshot', p_input->'routingSnapshot',
      'taxSnapshot', p_input->'taxSnapshot',
      'attachmentSnapshot', jsonb_build_object(
        'required', false,
        'reason', 'same_invoice_accounting_update'
      ),
      'payloadSnapshot', p_input->'payloadTemplate',
      'canonicalSchemaVersion', p_input->>'canonicalSchemaVersion',
      'sourceEvidenceHash', p_input->>'sourceEvidenceHash',
      'commercialHash', p_input->>'commercialHash',
      'linesHash', p_input->>'linesHash',
      'payloadHash', p_input->>'payloadHash',
      'providerContentHash', p_input->>'payloadHash',
      'pdfHash', null,
      'currencyCode', 'NZD',
      'providerDocumentType', 'ACCREC',
      'requestedProviderStatus', 'AUTHORISED',
      'lineAmountType', 'Exclusive',
      'subtotalMinor', p_input->>'subtotalMinor',
      'taxMinor', p_input->>'taxMinor',
      'totalMinor', p_input->>'totalMinor',
      'confirmationPreviewHash', p_input->>'previewHash',
      'confirmedBy', v_actor,
      'confirmedAt', now(),
      'confirmationReason', 'Payment Claim amended after export',
      'correlationId', p_input->>'proposalId',
      'lines', p_input->'lines',
      'attachments', '[]'::jsonb
    )
  );
  v_idempotency := encode(digest(convert_to(
    'xero:payment_claim:accounting_update:' || v_revision.id,
    'UTF8'
  ), 'sha256'), 'hex');
  select * into v_attempt
  from public.create_accounting_revision_attempt_phase2a(
    v_revision.id,
    'update',
    v_idempotency,
    jsonb_build_object(
      'accountingDocumentId', v_document.id,
      'accountingRevisionId', v_revision.id,
      'previousRevisionId', v_previous.id,
      'externalDocumentId', v_previous.external_document_id,
      'externalDocumentNumber', v_previous.external_document_number,
      'payloadHash', p_input->>'payloadHash',
      'tenantId', v_tenant,
      'intent', 'direct_update'
    )
  );
  perform public.transition_accounting_revision_lifecycle_phase2a(
    v_revision.id, 'queued', null, null
  );
  insert into public.organization_accounting_sync_jobs(
    organization_id, provider, connection_id, job_kind, trigger_source,
    request_payload, result_summary, idempotency_key, max_attempts,
    created_by_user_id
  ) values (
    v_org, 'xero', v_connection,
    'xero.payment_claim.accounting_update', 'user_export',
    jsonb_build_object(
      'organizationId', v_org,
      'projectId', v_project,
      'claimId', v_claim,
      'accountingDocumentId', v_document.id,
      'accountingRevisionId', v_revision.id,
      'successorRevisionId', v_revision.id,
      'previousRevisionId', v_previous.id,
      'attemptId', v_attempt.id,
      'proposalId', p_input->>'proposalId',
      'connectionId', v_connection,
      'externalDocumentId', v_previous.external_document_id,
      'externalDocumentNumber', v_previous.external_document_number,
      'tenantId', v_tenant,
      'intent', 'direct_update'
    ),
    '{}'::jsonb, v_idempotency, 5, v_actor
  ) returning id into v_job_id;
  update public.organization_accounting_documents
  set export_status = 'queued', updated_at = now()
  where id = v_document.id;
  insert into public.organization_accounting_events(
    organization_id, accounting_document_id, accounting_revision_id,
    event_type, event_evidence
  ) values (
    v_org, v_document.id, v_revision.id,
    'payment_claim_accounting_update_confirmed',
    jsonb_build_object(
      'proposalId', p_input->>'proposalId',
      'predecessorRevisionId', v_previous.id,
      'externalDocumentId', v_previous.external_document_id
    )
  );
  return jsonb_build_object(
    'accountingDocumentId', v_document.id,
    'accountingRevisionId', v_revision.id,
    'attemptId', v_attempt.id,
    'jobId', v_job_id,
    'invoiceNumber', v_revision.external_document_number,
    'revisionSequence', v_revision.revision_sequence,
    'status', 'queued'
  );
end;
$$;


ALTER FUNCTION "public"."confirm_payment_claim_accounting_update"("p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."confirm_payment_claim_initial_push_phase2b"("p_input" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_org uuid := (p_input->>'organizationId')::uuid;
  v_project uuid := (p_input->>'projectId')::uuid;
  v_claim uuid := (p_input->>'claimId')::uuid;
  v_source_revision timestamptz;
  v_claim_updated_at timestamptz;
  v_document public.organization_accounting_documents%rowtype;
  v_normalized_input jsonb;
begin
  begin
    v_source_revision := (p_input->>'sourceOptimisticRevision')::timestamptz;
  exception
    when invalid_datetime_format or datetime_field_overflow then
      raise exception 'The Payment Claim accounting preview has an invalid source revision.';
  end;
  if v_source_revision is null then
    raise exception 'The Payment Claim accounting preview has an invalid source revision.';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(v_claim::text, 2600));
  select c.updated_at into v_claim_updated_at
  from public.project_claims c
  where c.id = v_claim
    and c.organization_id = v_org
    and c.project_id = v_project
  for update;
  if not found then
    raise exception 'Payment Claim is outside the organisation project.';
  end if;
  if v_claim_updated_at is distinct from v_source_revision then
    raise exception 'The Payment Claim changed after the accounting preview was created.';
  end if;

  -- The verified Phase 2B implementation predates this wrapper and compares
  -- updated_at::text internally. Preserve that implementation while supplying
  -- PostgreSQL's own canonical text form after the semantic timestamp check.
  v_normalized_input := jsonb_set(
    p_input,
    '{sourceOptimisticRevision}',
    to_jsonb(v_claim_updated_at::text),
    true
  );

  select * into v_document
  from public.organization_accounting_documents d
  where d.organization_id = v_org
    and d.provider = 'xero'
    and d.tenant_id = p_input->>'tenantId'
    and d.local_document_type = 'project_claim'
    and d.project_claim_id = v_claim
  for update;
  if found and v_document.integration_contract is null then
    if v_document.external_document_id is not null
      or v_document.active_accounting_revision_id is not null then
      raise exception 'Existing linked Payment Claims remain on the legacy integration.';
    end if;
    update public.organization_accounting_documents
    set integration_contract = 'payment_claim_revision_v1', updated_at = now()
    where id = v_document.id
      and integration_contract is null
      and external_document_id is null
      and active_accounting_revision_id is null;
  end if;
  return public.confirm_payment_claim_initial_push_phase2b_impl(v_normalized_input);
end;
$$;


ALTER FUNCTION "public"."confirm_payment_claim_initial_push_phase2b"("p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."confirm_payment_claim_initial_push_phase2b_impl"("p_input" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private', 'extensions'
    AS $$
declare
  v_org uuid := (p_input->>'organizationId')::uuid;
  v_project uuid := (p_input->>'projectId')::uuid;
  v_claim uuid := (p_input->>'claimId')::uuid;
  v_actor uuid := (p_input->>'confirmedBy')::uuid;
  v_connection uuid := (p_input->>'connectionId')::uuid;
  v_tenant text := p_input->>'tenantId';
  v_claim_row public.project_claims%rowtype;
  v_document public.organization_accounting_documents%rowtype;
  v_revision public.organization_accounting_document_revisions%rowtype;
  v_attempt public.organization_accounting_revision_attempts%rowtype;
  v_attachment public.organization_accounting_revision_attachments%rowtype;
  v_payload jsonb;
  v_pdf bytea;
  v_pdf_hash text;
  v_payload_hash text;
  v_idempotency text;
  v_job_id uuid;
  v_invoice_number text;
begin
  if not private.phase2b_actor_has_push_permission(v_org, v_actor) then
    raise exception 'Payment Claim initial Push to Xero permission is required.';
  end if;
  if not exists (
    select 1 from public.organization_accounting_phase2b_settings s
    where s.organization_id = v_org
      and s.initial_payment_claim_push_enabled
  ) then
    raise exception 'Immutable Payment Claim Push to Xero is not enabled.';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(v_claim::text, 2600));
  select * into v_claim_row
  from public.project_claims c
  where c.id = v_claim
    and c.organization_id = v_org
    and c.project_id = v_project
  for update;
  if not found then raise exception 'Payment Claim is outside the organisation project.'; end if;
  if v_claim_row.status <> 'Submitted' then
    raise exception 'Payment Claim is no longer in an exportable state.';
  end if;
  if v_claim_row.updated_at::text <> p_input->>'sourceOptimisticRevision' then
    raise exception 'The Payment Claim changed after the accounting preview was created.';
  end if;
  v_invoice_number := nullif(trim(v_claim_row.claim_number), '');
  if v_invoice_number is null
    or p_input#>>'{payloadTemplate,InvoiceNumber}' <> v_invoice_number
    or p_input#>>'{commercialSnapshot,commercialClaimNumber}' <> v_invoice_number then
    raise exception 'The confirmed Xero InvoiceNumber must equal the Payment Claim number.';
  end if;
  if not exists (
    select 1 from public.organization_xero_connections c
    where c.id = v_connection and c.organization_id = v_org
      and c.status = 'connected' and c.tenant_id = v_tenant
  ) then
    raise exception 'The Xero connection or selected tenant changed.';
  end if;

  select * into v_document
  from public.organization_accounting_documents d
  where d.organization_id = v_org
    and d.provider = 'xero'
    and d.tenant_id = v_tenant
    and d.local_document_type = 'project_claim'
    and d.project_claim_id = v_claim
  for update;
  if not found then
    insert into public.organization_accounting_documents(
      organization_id, accounting_connection_id, provider, tenant_id,
      local_document_type, local_document_id, project_claim_id,
      current_version_id, export_status, currency_code, integration_contract
    ) values (
      v_org, v_connection, 'xero', v_tenant,
      'project_claim', null, v_claim, null, 'not_ready', 'NZD',
      'payment_claim_revision_v1'
    ) returning * into v_document;
  end if;
  if v_document.accounting_connection_id <> v_connection
    or v_document.external_document_id is not null
    or v_document.active_accounting_revision_id is not null
    or v_document.integration_contract is distinct from 'payment_claim_revision_v1' then
    raise exception 'Payment Claim accounting identity is already linked or incompatible.';
  end if;
  if exists (
    select 1 from public.organization_accounting_document_revisions r
    where r.accounting_document_id = v_document.id
      and r.revision_intent = 'initial_push'
  ) then
    raise exception 'An immutable initial-push revision already exists.';
  end if;

  v_pdf := decode(p_input->>'pdfBase64', 'base64');
  v_pdf_hash := encode(digest(v_pdf, 'sha256'), 'hex');
  if v_pdf_hash <> p_input->>'pdfHash'
    or octet_length(v_pdf) <> (p_input->>'pdfByteSize')::bigint
    or substring(v_pdf from 1 for 4) <> decode('25504446', 'hex') then
    raise exception 'Confirmed Payment Claim PDF evidence is invalid.';
  end if;

  v_payload := p_input->'payloadTemplate';
  v_payload_hash := encode(digest(v_payload::text, 'sha256'), 'hex');

  select * into v_revision
  from public.persist_payment_claim_initial_revision_phase2b(
    jsonb_build_object(
      'organizationId', v_org,
      'projectId', v_project,
      'accountingDocumentId', v_document.id,
      'sourceDocumentType', 'project_claim',
      'sourceDocumentId', v_claim,
      'revisionIntent', 'initial_push',
      'resolutionStrategy', 'new_document',
      'previousRevisionId', null,
      'provider', 'xero',
      'connectionId', v_connection,
      'tenantId', v_tenant,
      'numberReservationId', null,
      'externalDocumentNumber', v_invoice_number,
      'commercialSnapshot', p_input->'commercialSnapshot',
      'contactSnapshot', p_input->'contactSnapshot',
      'routingSnapshot', p_input->'routingSnapshot',
      'taxSnapshot', p_input->'taxSnapshot',
      'attachmentSnapshot', jsonb_build_object(
        'contentSha256', v_pdf_hash,
        'byteSize', octet_length(v_pdf),
        'statutoryDocumentsIncluded', p_input->'statutoryDocumentsIncluded'
      ),
      'payloadSnapshot', v_payload,
      'canonicalSchemaVersion', p_input->>'canonicalSchemaVersion',
      'sourceEvidenceHash', p_input->>'sourceEvidenceHash',
      'commercialHash', p_input->>'commercialHash',
      'linesHash', p_input->>'linesHash',
      'payloadHash', v_payload_hash,
      'providerContentHash', v_payload_hash,
      'pdfHash', v_pdf_hash,
      'currencyCode', 'NZD',
      'providerDocumentType', 'ACCREC',
      'requestedProviderStatus', 'AUTHORISED',
      'lineAmountType', 'Exclusive',
      'subtotalMinor', p_input->>'subtotalMinor',
      'taxMinor', p_input->>'taxMinor',
      'totalMinor', p_input->>'totalMinor',
      'confirmationPreviewHash', p_input->>'previewHash',
      'confirmedBy', v_actor,
      'confirmedAt', now(),
      'confirmationReason', null,
      'correlationId', p_input->>'proposalId',
      'lines', p_input->'lines',
      'attachments', jsonb_build_array(jsonb_build_object(
        'sequence', 1,
        'kind', 'claim_pdf',
        'sourceDocumentId', v_claim,
        'filename', v_invoice_number || '-r0001.pdf',
        'contentType', 'application/pdf',
        'byteSize', octet_length(v_pdf),
        'contentSha256', v_pdf_hash,
        'storageBucket', 'accounting-revision-evidence',
        'storagePath', v_org || '/' || v_document.id || '/revision-1/claim.pdf'
      ))
    )
  );

  select * into v_attachment
  from public.organization_accounting_revision_attachments a
  where a.accounting_revision_id = v_revision.id and a.attachment_sequence = 1;
  insert into public.organization_accounting_revision_blobs(
    accounting_revision_id, organization_id, attachment_id, content_type,
    byte_size, content_sha256, content_bytes
  ) values (
    v_revision.id, v_org, v_attachment.id, 'application/pdf',
    octet_length(v_pdf), v_pdf_hash, v_pdf
  );

  v_idempotency := encode(
    digest(('xero:payment_claim:initial_push:' || v_revision.id)::bytea, 'sha256'),
    'hex'
  );
  select * into v_attempt
  from public.create_accounting_revision_attempt_phase2a(
    v_revision.id, 'create', v_idempotency,
    jsonb_build_object(
      'accountingDocumentId', v_document.id,
      'accountingRevisionId', v_revision.id,
      'payloadHash', v_payload_hash,
      'tenantId', v_tenant,
      'intent', 'initial_push'
    )
  );
  perform public.transition_accounting_revision_lifecycle_phase2a(
    v_revision.id, 'queued', null, null
  );

  insert into public.organization_accounting_sync_jobs(
    organization_id, provider, connection_id, job_kind, trigger_source,
    request_payload, result_summary, idempotency_key, max_attempts,
    created_by_user_id
  ) values (
    v_org, 'xero', v_connection, 'xero.payment_claim.initial_push', 'user_export',
    jsonb_build_object(
      'accountingDocumentId', v_document.id,
      'accountingRevisionId', v_revision.id,
      'attemptId', v_attempt.id,
      'payloadHash', v_payload_hash,
      'tenantId', v_tenant,
      'intent', 'initial_push'
    ),
    '{}'::jsonb, v_idempotency, 5, v_actor
  ) returning id into v_job_id;

  update public.organization_accounting_documents
  set export_status = 'queued', updated_at = now()
  where id = v_document.id;

  return jsonb_build_object(
    'accountingDocumentId', v_document.id,
    'accountingRevisionId', v_revision.id,
    'attemptId', v_attempt.id,
    'jobId', v_job_id,
    'invoiceNumber', v_invoice_number,
    'revisionSequence', v_revision.revision_sequence,
    'pdfFilename', v_attachment.filename,
    'status', 'queued'
  );
end;
$$;


ALTER FUNCTION "public"."confirm_payment_claim_initial_push_phase2b_impl"("p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."confirm_payment_claim_push_phase2c"("p_input" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_proposal public.organization_accounting_push_proposals%rowtype;
begin
  select * into v_proposal
  from public.organization_accounting_push_proposals
  where id = (p_input->>'proposalId')::uuid
    and organization_id = (p_input->>'organizationId')::uuid
    and source_document_id = (p_input->>'claimId')::uuid
    and project_id = (p_input->>'projectId')::uuid;
  if not found
    or v_proposal.expires_at <= now()
    or v_proposal.source_document_type <> 'project_claim'
    or v_proposal.preview_hash <> p_input->>'previewHash'
    or v_proposal.operation <> p_input->>'operation'
    or v_proposal.external_document_number <>
      p_input->>'externalDocumentNumber'
    or v_proposal.source_optimistic_revision <>
      p_input->>'sourceOptimisticRevision'
    or v_proposal.active_revision_id is distinct from
      nullif(p_input->>'previousRevisionId', '')::uuid
    or v_proposal.evidence_hashes->>'sourceEvidenceHash' <>
      p_input->>'sourceEvidenceHash'
    or v_proposal.evidence_hashes->>'commercialHash' <>
      p_input->>'commercialHash'
    or v_proposal.evidence_hashes->>'linesHash' <> p_input->>'linesHash'
    or v_proposal.evidence_hashes->>'dependencyHash' <>
      p_input->>'dependencyHash'
    or v_proposal.evidence_hashes->>'payloadHash' <> p_input->>'payloadHash'
    or v_proposal.evidence_hashes->>'previewHash' <> p_input->>'previewHash'
    or (
      v_proposal.operation <> 'ACCOUNTING_UPDATE'
      and v_proposal.evidence_hashes->>'pdfHash' is distinct from
        p_input->>'pdfHash'
    ) then
    raise exception 'The immutable accounting proposal is missing, expired, or stale.';
  end if;
  if v_proposal.operation = 'INITIAL_EXPORT' then
    return public.confirm_payment_claim_initial_push_phase2b(p_input);
  elsif v_proposal.operation = 'REPLACEMENT_EXPORT' then
    return public.confirm_payment_claim_replacement_phase2c(p_input);
  elsif v_proposal.operation = 'ACCOUNTING_UPDATE' then
    return public.confirm_payment_claim_accounting_update(p_input);
  end if;
  raise exception 'The resolved accounting operation is not executable.';
end;
$$;


ALTER FUNCTION "public"."confirm_payment_claim_push_phase2c"("p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."confirm_payment_claim_replacement_phase2c"("p_input" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private'
    AS $$
declare
  v_source_revision timestamptz;
  v_normalized_input jsonb;
begin
  begin
    v_source_revision := (p_input->>'sourceOptimisticRevision')::timestamptz;
  exception
    when invalid_datetime_format or datetime_field_overflow then
      raise exception 'The Payment Claim optimistic revision is invalid.'
        using errcode = '22007';
  end;

  if v_source_revision is null then
    raise exception 'The Payment Claim optimistic revision is missing.'
      using errcode = '22007';
  end if;

  v_normalized_input := jsonb_set(
    p_input,
    '{sourceOptimisticRevision}',
    to_jsonb(v_source_revision::text),
    true
  );

  return public.confirm_payment_claim_replacement_phase2c_v1(
    v_normalized_input
  );
end;
$$;


ALTER FUNCTION "public"."confirm_payment_claim_replacement_phase2c"("p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."confirm_payment_claim_replacement_phase2c_v1"("p_input" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private', 'extensions'
    AS $_$
declare
  v_org uuid := (p_input->>'organizationId')::uuid;
  v_project uuid := (p_input->>'projectId')::uuid;
  v_claim uuid := (p_input->>'claimId')::uuid;
  v_actor uuid := (p_input->>'confirmedBy')::uuid;
  v_connection uuid := (p_input->>'connectionId')::uuid;
  v_tenant text := p_input->>'tenantId';
  v_document public.organization_accounting_documents%rowtype;
  v_previous public.organization_accounting_document_revisions%rowtype;
  v_projection public.organization_accounting_projections%rowtype;
  v_observation public.organization_accounting_remote_observations%rowtype;
  v_reservation public.organization_accounting_number_reservations%rowtype;
  v_revision public.organization_accounting_document_revisions%rowtype;
  v_attempt public.organization_accounting_revision_attempts%rowtype;
  v_attachment public.organization_accounting_revision_attachments%rowtype;
  v_claim_row public.project_claims%rowtype;
  v_payload jsonb;
  v_pdf bytea;
  v_pdf_hash text;
  v_payload_hash text;
  v_number text;
  v_replacement_sequence bigint;
  v_global_sequence bigint;
  v_idempotency text;
  v_job_id uuid;
  v_missing_confirmed boolean := false;
begin
  if p_input->>'operation' <> 'REPLACEMENT_EXPORT' then
    raise exception 'Server-resolved replacement operation is required.';
  end if;
  if not private.phase2b_actor_has_push_permission(v_org, v_actor) then
    raise exception 'Payment Claim Push to Xero permission is required.';
  end if;
  if not exists (
    select 1 from public.organization_accounting_phase2b_settings s
    where s.organization_id = v_org and s.initial_payment_claim_push_enabled
  ) then
    raise exception 'Immutable Payment Claim Push to Xero is not enabled.';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(v_claim::text, 2601));
  select * into v_claim_row from public.project_claims
  where id = v_claim and organization_id = v_org and project_id = v_project
  for update;
  if not found or v_claim_row.status <> 'Submitted' then
    raise exception 'Payment Claim is no longer in an exportable state.';
  end if;
  if v_claim_row.updated_at::text <> p_input->>'sourceOptimisticRevision' then
    raise exception 'The Payment Claim changed after the accounting preview was created.';
  end if;
  select * into v_document from public.organization_accounting_documents
  where organization_id = v_org and provider = 'xero'
    and local_document_type = 'project_claim' and project_claim_id = v_claim
  for update;
  if not found
    or v_document.integration_contract <> 'payment_claim_revision_v1'
    or v_document.accounting_connection_id <> v_connection
    or v_document.tenant_id <> v_tenant then
    raise exception 'The immutable Payment Claim accounting identity changed.';
  end if;
  select * into v_previous from public.organization_accounting_document_revisions
  where id = v_document.active_accounting_revision_id
    and id = (p_input->>'previousRevisionId')::uuid
    and organization_id = v_org
    and accounting_document_id = v_document.id
    and lifecycle_state = 'succeeded'
  for update;
  if not found
    or v_previous.external_document_id <> p_input->>'previousInvoiceId'
    or v_previous.external_document_number <> p_input->>'previousInvoiceNumber'
    or v_document.external_document_id <> v_previous.external_document_id
    or v_document.external_document_number <> v_previous.external_document_number then
    raise exception 'The active Xero invoice changed after preview.';
  end if;
  if not exists (
    select 1 from public.organization_xero_connections c
    where c.id = v_connection and c.organization_id = v_org
      and c.status = 'connected' and c.tenant_id = v_tenant
      and c.scope @> array['accounting.invoices']::text[]
  ) then
    raise exception 'The Xero connection, tenant, or invoice scope changed.';
  end if;

  select exists (
    select 1 from public.organization_accounting_events e
    where e.organization_id = v_org
      and e.accounting_document_id = v_document.id
      and e.accounting_revision_id = v_previous.id
      and e.event_type = 'provider_missing_confirmed'
  ) into v_missing_confirmed;

  select * into v_projection from public.organization_accounting_projections
  where accounting_document_id = v_document.id
    and accounting_revision_id = v_previous.id
  for update;
  if not found
    or (
      v_projection.normalized_invoice_status NOT IN ('voided', 'deleted')
      and not v_missing_confirmed
    )
    or coalesce(v_projection.amount_paid_minor, 0) <> 0
    or coalesce(v_projection.amount_credited_minor, 0) <> 0
    or v_projection.divergent then
    raise exception 'The previous Xero invoice is not safely replacement eligible.';
  end if;
  select * into v_observation from public.organization_accounting_remote_observations
  where id = v_projection.remote_observation_id
    and accounting_revision_id = v_previous.id
    and external_document_id = v_previous.external_document_id;
  if not found
    or jsonb_array_length(coalesce(v_observation.raw_observation->'Payments', '[]'::jsonb)) <> 0
    or jsonb_array_length(coalesce(v_observation.raw_observation->'CreditNotes', '[]'::jsonb)) <> 0 then
    raise exception 'Payments or credits prevent replacement.';
  end if;

  select coalesce(max(
    case
      when left(r.external_document_number, char_length(v_claim_row.claim_number) + 2)
          = v_claim_row.claim_number || '-R'
        and substring(r.external_document_number from char_length(v_claim_row.claim_number) + 3) ~ '^[1-9][0-9]*$'
      then substring(r.external_document_number from char_length(v_claim_row.claim_number) + 3)::bigint
      else 0
    end
  ), 0) + 1 into v_replacement_sequence
  from public.organization_accounting_document_revisions r
  where r.accounting_document_id = v_document.id;
  v_number := v_claim_row.claim_number || '-R' || v_replacement_sequence;
  if p_input->>'externalDocumentNumber' <> v_number
    or p_input#>>'{payloadTemplate,InvoiceNumber}' <> v_number
    or p_input#>>'{payloadTemplate,Type}' <> 'ACCREC'
    or p_input#>>'{payloadTemplate,Status}' <> 'AUTHORISED' then
    raise exception 'The confirmed replacement invoice identity is stale.';
  end if;

  insert into public.organization_accounting_number_counters(
    organization_id, provider, tenant_id, document_class, last_sequence
  ) values (v_org, 'xero', v_tenant, 'sales_invoice', 1)
  on conflict (organization_id, provider, tenant_id, document_class)
  do update set last_sequence = organization_accounting_number_counters.last_sequence + 1, updated_at = now()
  returning last_sequence into v_global_sequence;
  insert into public.organization_accounting_number_reservations(
    organization_id, provider, tenant_id, document_class, sequence_number,
    formatted_number, accounting_document_id, source_document_type,
    source_document_id, reservation_reason, reserved_by
  ) values (
    v_org, 'xero', v_tenant, 'sales_invoice', v_global_sequence,
    v_number, v_document.id, 'project_claim', v_claim, 'replacement', v_actor
  ) returning * into v_reservation;

  v_pdf := decode(p_input->>'pdfBase64', 'base64');
  v_pdf_hash := encode(digest(v_pdf, 'sha256'), 'hex');
  if v_pdf_hash <> p_input->>'pdfHash'
    or octet_length(v_pdf) <> (p_input->>'pdfByteSize')::bigint
    or substring(v_pdf from 1 for 4) <> decode('25504446', 'hex') then
    raise exception 'Confirmed replacement PDF evidence is invalid.';
  end if;
  v_payload := p_input->'payloadTemplate';
  v_payload_hash := encode(digest(v_payload::text, 'sha256'), 'hex');
  select * into v_revision from public.persist_confirmed_accounting_revision_phase2a(
    jsonb_build_object(
      'organizationId', v_org, 'projectId', v_project,
      'accountingDocumentId', v_document.id, 'sourceDocumentType', 'project_claim',
      'sourceDocumentId', v_claim, 'revisionIntent', 'replacement',
      'resolutionStrategy', 'replacement', 'previousRevisionId', v_previous.id,
      'provider', 'xero', 'connectionId', v_connection, 'tenantId', v_tenant,
      'numberReservationId', v_reservation.id, 'externalDocumentNumber', v_number,
      'commercialSnapshot', p_input->'commercialSnapshot',
      'contactSnapshot', p_input->'contactSnapshot',
      'routingSnapshot', p_input->'routingSnapshot',
      'taxSnapshot', p_input->'taxSnapshot',
      'attachmentSnapshot', jsonb_build_object('contentSha256', v_pdf_hash, 'byteSize', octet_length(v_pdf)),
      'payloadSnapshot', v_payload, 'canonicalSchemaVersion', p_input->>'canonicalSchemaVersion',
      'sourceEvidenceHash', p_input->>'sourceEvidenceHash',
      'commercialHash', p_input->>'commercialHash', 'linesHash', p_input->>'linesHash',
      'payloadHash', v_payload_hash, 'providerContentHash', v_payload_hash,
      'pdfHash', v_pdf_hash, 'currencyCode', 'NZD', 'providerDocumentType', 'ACCREC',
      'requestedProviderStatus', 'AUTHORISED', 'lineAmountType', 'Exclusive',
      'subtotalMinor', p_input->>'subtotalMinor', 'taxMinor', p_input->>'taxMinor',
      'totalMinor', p_input->>'totalMinor', 'confirmationPreviewHash', p_input->>'previewHash',
      'confirmedBy', v_actor, 'confirmedAt', now(), 'confirmationReason', case when v_missing_confirmed
        then 'Previous Xero invoice confirmed permanently missing'
        else 'Previous Xero invoice voided'
      end,
      'correlationId', p_input->>'proposalId', 'lines', p_input->'lines',
      'attachments', jsonb_build_array(jsonb_build_object(
        'sequence', 1, 'kind', 'claim_pdf', 'sourceDocumentId', v_claim,
        'filename', v_number || '-r' || lpad((v_previous.revision_sequence + 1)::text, 4, '0') || '.pdf',
        'contentType', 'application/pdf', 'byteSize', octet_length(v_pdf),
        'contentSha256', v_pdf_hash, 'storageBucket', 'accounting-revision-evidence',
        'storagePath', v_org || '/' || v_document.id || '/revision-' || (v_previous.revision_sequence + 1) || '/claim.pdf'
      ))
    )
  );
  select * into v_attachment from public.organization_accounting_revision_attachments
  where accounting_revision_id = v_revision.id and attachment_sequence = 1;
  insert into public.organization_accounting_revision_blobs(
    accounting_revision_id, organization_id, attachment_id, content_type,
    byte_size, content_sha256, content_bytes
  ) values (v_revision.id, v_org, v_attachment.id, 'application/pdf', octet_length(v_pdf), v_pdf_hash, v_pdf);

  v_idempotency := encode(digest(('xero:payment_claim:replacement:' || v_revision.id)::bytea, 'sha256'), 'hex');
  select * into v_attempt from public.create_accounting_revision_attempt_phase2a(
    v_revision.id, 'replace', v_idempotency,
    jsonb_build_object('accountingDocumentId', v_document.id, 'accountingRevisionId', v_revision.id,
      'previousRevisionId', v_previous.id, 'payloadHash', v_payload_hash, 'tenantId', v_tenant)
  );
  perform public.transition_accounting_revision_lifecycle_phase2a(v_revision.id, 'queued', null, null);
  insert into public.organization_accounting_sync_jobs(
    organization_id, provider, connection_id, job_kind, trigger_source,
    request_payload, result_summary, idempotency_key, max_attempts, created_by_user_id
  ) values (
    v_org, 'xero', v_connection, 'xero.payment_claim.replacement', 'user_export',
    jsonb_build_object('accountingDocumentId', v_document.id, 'accountingRevisionId', v_revision.id,
      'attemptId', v_attempt.id, 'previousRevisionId', v_previous.id),
    '{}'::jsonb, v_idempotency, 5, v_actor
  ) returning id into v_job_id;
  insert into public.organization_accounting_events(
    organization_id, accounting_document_id, accounting_revision_id,
    accounting_attempt_id, event_type, actor_user_id, correlation_id, event_evidence
  ) values
    (v_org, v_document.id, v_revision.id, v_attempt.id, 'decision_resolved', v_actor,
      p_input->>'proposalId', jsonb_build_object('operation', 'REPLACEMENT_EXPORT')),
    (v_org, v_document.id, v_revision.id, v_attempt.id, 'replacement_confirmed', v_actor,
      p_input->>'proposalId', jsonb_build_object('previousRevisionId', v_previous.id, 'invoiceNumber', v_number));
  return jsonb_build_object(
    'accountingDocumentId', v_document.id, 'accountingRevisionId', v_revision.id,
    'attemptId', v_attempt.id, 'jobId', v_job_id, 'invoiceNumber', v_number,
    'revisionSequence', v_revision.revision_sequence, 'pdfFilename', v_attachment.filename, 'status', 'queued'
  );
end;
$_$;


ALTER FUNCTION "public"."confirm_payment_claim_replacement_phase2c_v1"("p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."confirm_retention_claim_push_phase2c"("p_input" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private', 'extensions'
    AS $_$
declare
  v_org uuid := (p_input->>'organizationId')::uuid;
  v_project uuid := (p_input->>'projectId')::uuid;
  v_claim uuid := (p_input->>'retentionClaimId')::uuid;
  v_actor uuid := (p_input->>'confirmedBy')::uuid;
  v_connection uuid := (p_input->>'connectionId')::uuid;
  v_tenant text := p_input->>'tenantId';
  v_operation text := p_input->>'operation';
  v_claim_row public.retention_claims%rowtype;
  v_document public.organization_accounting_documents%rowtype;
  v_previous public.organization_accounting_document_revisions%rowtype;
  v_projection public.organization_accounting_projections%rowtype;
  v_observation public.organization_accounting_remote_observations%rowtype;
  v_proposal public.organization_accounting_push_proposals%rowtype;
  v_reservation public.organization_accounting_number_reservations%rowtype;
  v_revision public.organization_accounting_document_revisions%rowtype;
  v_attempt public.organization_accounting_revision_attempts%rowtype;
  v_attachment public.organization_accounting_revision_attachments%rowtype;
  v_ownership jsonb;
  v_source jsonb;
  v_source_hash text;
  v_number text;
  v_replacement_sequence bigint;
  v_global_sequence bigint;
  v_pdf bytea;
  v_pdf_hash text;
  v_payload jsonb := p_input->'payloadTemplate';
  v_payload_hash text;
  v_idempotency text;
  v_job_id uuid;
begin
  if auth.role() <> 'service_role' then
    raise exception 'Retention Claim immutable confirmation is server-only.';
  end if;
  if v_operation not in ('INITIAL_EXPORT', 'REPLACEMENT_EXPORT') then
    raise exception 'The resolved Retention Claim operation is not executable.';
  end if;
  if not private.retention_phase2c_actor_can_push(v_org, v_actor) then
    raise exception 'Retention Claim Push to Xero permission is required.';
  end if;
  if not exists (
    select 1
    from public.organization_accounting_phase2b_settings s
    where s.organization_id = v_org
      and s.retention_claim_immutable_xero_enabled
  ) then
    raise exception 'Immutable Retention Claim Push to Xero is not enabled.';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(v_claim::text, 2630));
  select * into v_claim_row
  from public.retention_claims
  where id = v_claim
    and organization_id = v_org
    and project_id = v_project
  for update;
  if not found or v_claim_row.status <> 'submitted' then
    raise exception 'The Retention Claim is no longer submitted.';
  end if;
  if v_claim_row.submitted_at is distinct from
      (p_input->>'sourceOptimisticRevision')::timestamptz then
    raise exception 'The Retention Claim changed after the accounting preview was created.';
  end if;
  if v_claim_row.claim_number <> p_input->>'commercialClaimNumber' then
    raise exception 'The Retention Claim commercial identity changed.';
  end if;
  v_source := private.retention_claim_document_source(v_claim);
  v_source_hash := encode(
    extensions.digest(convert_to(v_source::text, 'UTF8'), 'sha256'),
    'hex'
  );
  if v_source_hash <> p_input->>'retentionSourceEvidenceHash' then
    raise exception 'Retention Claim ownership evidence changed.';
  end if;
  select public.evaluate_retention_ownership_phase2a(
    v_org, v_project, '[]'::jsonb
  ) into v_ownership;
  if coalesce((v_ownership->>'valid')::boolean, false) is not true then
    raise exception 'Retention ownership changed after preview.';
  end if;
  if exists (
    select 1
    from jsonb_array_elements(p_input->'lines') line
    where not exists (
      select 1
      from public.retention_claim_allocations allocation
      where allocation.id = (line->>'sourceLineId')::uuid
        and allocation.retention_claim_id = v_claim
        and allocation.organization_id = v_org
        and allocation.project_id = v_project
        and allocation.originating_payment_claim_id =
          (line->>'originatingPaymentClaimId')::uuid
        and round(allocation.allocation_amount * 100)::bigint =
          (line->>'lineAmountMinor')::bigint
    )
  ) then
    raise exception 'Retention Claim allocation ownership changed.';
  end if;
  if not exists (
    select 1 from public.organization_xero_connections c
    where c.id = v_connection
      and c.organization_id = v_org
      and c.status = 'connected'
      and c.tenant_id = v_tenant
      and c.scope @> array['accounting.invoices']::text[]
  ) then
    raise exception 'The Xero connection, tenant, or invoice scope changed.';
  end if;

  select * into v_proposal
  from public.organization_accounting_push_proposals
  where id = (p_input->>'proposalId')::uuid
    and organization_id = v_org
    and project_id = v_project
    and source_document_type = 'retention_claim'
    and source_document_id = v_claim;
  if not found
    or v_proposal.expires_at <= now()
    or v_proposal.preview_hash <> p_input->>'previewHash'
    or v_proposal.operation <> v_operation
    or v_proposal.external_document_number <>
      p_input->>'externalDocumentNumber'
    or v_proposal.source_optimistic_revision <>
      p_input->>'sourceOptimisticRevision'
    or v_proposal.evidence_hashes->>'sourceEvidenceHash' <>
      p_input->>'sourceEvidenceHash'
    or v_proposal.evidence_hashes->>'dependencyHash' <>
      p_input->>'dependencyHash'
    or v_proposal.evidence_hashes->>'commercialHash' <>
      p_input->>'commercialHash'
    or v_proposal.evidence_hashes->>'linesHash' <>
      p_input->>'linesHash'
    or v_proposal.evidence_hashes->>'payloadHash' <>
      p_input->>'payloadHash'
    or v_proposal.evidence_hashes->>'pdfHash' <>
      p_input->>'pdfHash' then
    raise exception 'The immutable Retention Claim proposal is missing, expired, or stale.';
  end if;

  select * into v_document
  from public.organization_accounting_documents
  where organization_id = v_org
    and provider = 'xero'
    and local_document_type = 'retention_claim'
    and retention_claim_id = v_claim
  for update;
  if not found then
    if v_operation <> 'INITIAL_EXPORT' then
      raise exception 'The immutable Retention Claim accounting document is missing.';
    end if;
    insert into public.organization_accounting_documents(
      organization_id, accounting_connection_id, provider, tenant_id,
      local_document_type, local_document_id, project_claim_id,
      retention_claim_id, current_version_id, export_status,
      currency_code, integration_contract
    ) values (
      v_org, v_connection, 'xero', v_tenant,
      'retention_claim', null, null, v_claim, null, 'not_ready',
      'NZD', 'retention_claim_revision_v1'
    ) returning * into v_document;
  end if;
  if v_document.accounting_connection_id <> v_connection
    or v_document.tenant_id <> v_tenant
    or (
      v_document.integration_contract is not null
      and v_document.integration_contract <> 'retention_claim_revision_v1'
    ) then
    raise exception 'The immutable Retention Claim accounting identity changed.';
  end if;
  if v_document.integration_contract is null then
    update public.organization_accounting_documents
    set integration_contract = 'retention_claim_revision_v1',
        updated_at = now()
    where id = v_document.id;
    v_document.integration_contract := 'retention_claim_revision_v1';
  end if;

  -- A repeated or concurrent confirmation of the same immutable preview
  -- returns the original durable identities and never allocates another
  -- revision, number, attempt, or job.
  select * into v_revision
  from public.organization_accounting_document_revisions r
  where r.accounting_document_id = v_document.id
    and r.confirmation_preview_hash = p_input->>'previewHash'
    and r.external_document_number = p_input->>'externalDocumentNumber'
  order by r.revision_sequence
  limit 1;
  if found then
    select * into v_attempt
    from public.organization_accounting_revision_attempts a
    where a.accounting_revision_id = v_revision.id
      and a.attempt_intent in ('create', 'replace')
    order by a.attempt_sequence
    limit 1;
    select j.id into v_job_id
    from public.organization_accounting_sync_jobs j
    where j.organization_id = v_org
      and j.job_kind in (
        'xero.retention_claim.initial_push',
        'xero.retention_claim.replacement'
      )
      and j.request_payload->>'accountingRevisionId' = v_revision.id::text
    order by j.created_at
    limit 1;
    select * into v_attachment
    from public.organization_accounting_revision_attachments a
    where a.accounting_revision_id = v_revision.id
      and a.attachment_sequence = 1;
    if v_attempt.id is null or v_job_id is null or v_attachment.id is null then
      raise exception 'The existing Retention Claim confirmation is incomplete.';
    end if;
    return jsonb_build_object(
      'accountingDocumentId', v_document.id,
      'accountingRevisionId', v_revision.id,
      'attemptId', v_attempt.id,
      'jobId', v_job_id,
      'invoiceNumber', v_revision.external_document_number,
      'revisionSequence', v_revision.revision_sequence,
      'pdfFilename', v_attachment.filename,
      'status', case
        when v_revision.lifecycle_state = 'succeeded' then 'completed'
        when v_revision.lifecycle_state = 'processing' then 'processing'
        else 'queued'
      end
    );
  end if;

  if v_operation = 'INITIAL_EXPORT' then
    if v_document.active_accounting_revision_id is not null
      or v_document.external_document_id is not null
      or exists (
        select 1 from public.organization_accounting_document_revisions r
        where r.accounting_document_id = v_document.id
      ) then
      raise exception 'An immutable Retention Claim revision already exists.';
    end if;
    v_number := v_claim_row.claim_number;
  else
    select * into v_previous
    from public.organization_accounting_document_revisions
    where id = v_document.active_accounting_revision_id
      and id = (p_input->>'previousRevisionId')::uuid
      and accounting_document_id = v_document.id
      and lifecycle_state = 'succeeded'
    for update;
    if not found
      or v_previous.external_document_id <> p_input->>'previousInvoiceId'
      or v_previous.external_document_number <>
        p_input->>'previousInvoiceNumber'
      or v_document.external_document_id <>
        v_previous.external_document_id then
      raise exception 'The active Retention Claim Xero invoice changed.';
    end if;
    select * into v_projection
    from public.organization_accounting_projections
    where accounting_document_id = v_document.id
      and accounting_revision_id = v_previous.id
    for update;
    if not found
      or v_projection.normalized_invoice_status not in ('voided', 'deleted')
      or coalesce(v_projection.amount_paid_minor, 0) <> 0
      or coalesce(v_projection.amount_credited_minor, 0) <> 0
      or v_projection.divergent then
      raise exception 'The previous Retention Claim invoice is not replacement eligible.';
    end if;
    select * into v_observation
    from public.organization_accounting_remote_observations
    where id = v_projection.remote_observation_id
      and accounting_revision_id = v_previous.id
      and external_document_id = v_previous.external_document_id;
    if not found
      or jsonb_array_length(
        coalesce(v_observation.raw_observation->'Payments', '[]'::jsonb)
      ) <> 0
      or jsonb_array_length(
        coalesce(v_observation.raw_observation->'CreditNotes', '[]'::jsonb)
      ) <> 0 then
      raise exception 'Payments or credits prevent Retention Claim replacement.';
    end if;
    select coalesce(max(
      case
        when left(
          r.external_document_number,
          char_length(v_claim_row.claim_number) + 2
        ) = v_claim_row.claim_number || '-R'
          and substring(
            r.external_document_number
            from char_length(v_claim_row.claim_number) + 3
          ) ~ '^[1-9][0-9]*$'
        then substring(
          r.external_document_number
          from char_length(v_claim_row.claim_number) + 3
        )::bigint
        else 0
      end
    ), 0) + 1 into v_replacement_sequence
    from public.organization_accounting_document_revisions r
    where r.accounting_document_id = v_document.id;
    v_number := v_claim_row.claim_number || '-R' || v_replacement_sequence;
  end if;

  if p_input->>'externalDocumentNumber' <> v_number
    or v_payload->>'InvoiceNumber' <> v_number
    or v_payload->>'Type' <> 'ACCREC'
    or v_payload->>'Status' <> 'AUTHORISED' then
    raise exception 'The confirmed Retention Claim invoice identity is stale.';
  end if;

  insert into public.organization_accounting_number_counters(
    organization_id, provider, tenant_id, document_class, last_sequence
  ) values (v_org, 'xero', v_tenant, 'sales_invoice', 1)
  on conflict (organization_id, provider, tenant_id, document_class)
  do update set
    last_sequence =
      public.organization_accounting_number_counters.last_sequence + 1,
    updated_at = now()
  returning last_sequence into v_global_sequence;
  insert into public.organization_accounting_number_reservations(
    organization_id, provider, tenant_id, document_class,
    sequence_number, formatted_number, accounting_document_id,
    source_document_type, source_document_id, reservation_reason, reserved_by
  ) values (
    v_org, 'xero', v_tenant, 'sales_invoice',
    v_global_sequence, v_number, v_document.id,
    'retention_claim', v_claim,
    case when v_operation = 'INITIAL_EXPORT'
      then 'retention_claim_initial_push' else 'replacement' end,
    v_actor
  ) returning * into v_reservation;

  v_pdf := decode(p_input->>'pdfBase64', 'base64');
  v_pdf_hash := encode(digest(v_pdf, 'sha256'), 'hex');
  if v_pdf_hash <> p_input->>'pdfHash'
    or octet_length(v_pdf) <> (p_input->>'pdfByteSize')::bigint
    or substring(v_pdf from 1 for 4) <> decode('25504446', 'hex') then
    raise exception 'Confirmed Retention Claim PDF evidence is invalid.';
  end if;
  v_payload_hash := encode(digest(v_payload::text, 'sha256'), 'hex');
  select * into v_revision
  from public.persist_confirmed_accounting_revision_phase2a(
    jsonb_build_object(
      'organizationId', v_org,
      'projectId', v_project,
      'accountingDocumentId', v_document.id,
      'sourceDocumentType', 'retention_claim',
      'sourceDocumentId', v_claim,
      'revisionIntent', case when v_operation = 'INITIAL_EXPORT'
        then 'initial_push' else 'replacement' end,
      'resolutionStrategy', case when v_operation = 'INITIAL_EXPORT'
        then 'new_document' else 'replacement' end,
      'previousRevisionId', case when v_operation = 'INITIAL_EXPORT'
        then null else v_previous.id end,
      'provider', 'xero',
      'connectionId', v_connection,
      'tenantId', v_tenant,
      'numberReservationId', v_reservation.id,
      'externalDocumentNumber', v_number,
      'commercialSnapshot', p_input->'commercialSnapshot',
      'contactSnapshot', p_input->'contactSnapshot',
      'routingSnapshot', p_input->'routingSnapshot',
      'taxSnapshot', p_input->'taxSnapshot',
      'attachmentSnapshot', jsonb_build_object(
        'contentSha256', v_pdf_hash,
        'byteSize', octet_length(v_pdf),
        'provenance', 'exact_immutable_retention_document'
      ),
      'payloadSnapshot', v_payload,
      'canonicalSchemaVersion', p_input->>'canonicalSchemaVersion',
      'sourceEvidenceHash', p_input->>'sourceEvidenceHash',
      'commercialHash', p_input->>'commercialHash',
      'linesHash', p_input->>'linesHash',
      'payloadHash', v_payload_hash,
      'providerContentHash', v_payload_hash,
      'pdfHash', v_pdf_hash,
      'currencyCode', 'NZD',
      'providerDocumentType', 'ACCREC',
      'requestedProviderStatus', 'AUTHORISED',
      'lineAmountType', 'Exclusive',
      'subtotalMinor', p_input->>'subtotalMinor',
      'taxMinor', p_input->>'taxMinor',
      'totalMinor', p_input->>'totalMinor',
      'confirmationPreviewHash', p_input->>'previewHash',
      'confirmedBy', v_actor,
      'confirmedAt', now(),
      'confirmationReason', case when v_operation = 'INITIAL_EXPORT'
        then null else 'Previous Xero invoice voided' end,
      'correlationId', p_input->>'proposalId',
      'lines', p_input->'lines',
      'attachments', jsonb_build_array(jsonb_build_object(
        'sequence', 1,
        'kind', 'claim_pdf',
        'sourceDocumentId', v_claim,
        'filename', v_number || '-r' ||
          lpad((coalesce(v_previous.revision_sequence, 0) + 1)::text, 4, '0')
          || '.pdf',
        'contentType', 'application/pdf',
        'byteSize', octet_length(v_pdf),
        'contentSha256', v_pdf_hash,
        'storageBucket', 'accounting-revision-evidence',
        'storagePath', v_org || '/' || v_document.id || '/revision-' ||
          (coalesce(v_previous.revision_sequence, 0) + 1) || '/retention-claim.pdf'
      ))
    )
  );
  select * into v_attachment
  from public.organization_accounting_revision_attachments
  where accounting_revision_id = v_revision.id
    and attachment_sequence = 1;
  insert into public.organization_accounting_revision_blobs(
    accounting_revision_id, organization_id, attachment_id,
    content_type, byte_size, content_sha256, content_bytes
  ) values (
    v_revision.id, v_org, v_attachment.id,
    'application/pdf', octet_length(v_pdf), v_pdf_hash, v_pdf
  );
  v_idempotency := encode(digest((
    'xero:retention_claim:' ||
    case when v_operation = 'INITIAL_EXPORT'
      then 'initial_push:' else 'replacement:' end ||
    v_revision.id
  )::bytea, 'sha256'), 'hex');
  select * into v_attempt
  from public.create_accounting_revision_attempt_phase2a(
    v_revision.id,
    case when v_operation = 'INITIAL_EXPORT' then 'create' else 'replace' end,
    v_idempotency,
    jsonb_build_object(
      'accountingDocumentId', v_document.id,
      'accountingRevisionId', v_revision.id,
      'previousRevisionId', v_previous.id,
      'payloadHash', v_payload_hash,
      'tenantId', v_tenant,
      'intent', case when v_operation = 'INITIAL_EXPORT'
        then 'initial_push' else 'replacement' end
    )
  );
  perform public.transition_accounting_revision_lifecycle_phase2a(
    v_revision.id, 'queued', null, null
  );
  insert into public.organization_accounting_sync_jobs(
    organization_id, provider, connection_id, job_kind, trigger_source,
    request_payload, result_summary, idempotency_key, max_attempts,
    created_by_user_id
  ) values (
    v_org, 'xero', v_connection,
    case when v_operation = 'INITIAL_EXPORT'
      then 'xero.retention_claim.initial_push'
      else 'xero.retention_claim.replacement' end,
    'user_export',
    jsonb_build_object(
      'accountingDocumentId', v_document.id,
      'accountingRevisionId', v_revision.id,
      'attemptId', v_attempt.id,
      'previousRevisionId', v_previous.id,
      'payloadHash', v_payload_hash,
      'tenantId', v_tenant
    ),
    '{}'::jsonb, v_idempotency, 5, v_actor
  ) returning id into v_job_id;
  update public.organization_accounting_documents
  set export_status = 'queued', updated_at = now()
  where id = v_document.id;
  insert into public.organization_accounting_events(
    organization_id, accounting_document_id, accounting_revision_id,
    accounting_attempt_id, event_type, actor_user_id,
    correlation_id, event_evidence
  ) values (
    v_org, v_document.id, v_revision.id, v_attempt.id,
    'decision_resolved', v_actor, p_input->>'proposalId',
    jsonb_build_object(
      'operation', v_operation,
      'invoiceNumber', v_number,
      'retentionOwnership', v_ownership
    )
  );
  return jsonb_build_object(
    'accountingDocumentId', v_document.id,
    'accountingRevisionId', v_revision.id,
    'attemptId', v_attempt.id,
    'jobId', v_job_id,
    'invoiceNumber', v_number,
    'revisionSequence', v_revision.revision_sequence,
    'pdfFilename', v_attachment.filename,
    'status', 'queued'
  );
end;
$_$;


ALTER FUNCTION "public"."confirm_retention_claim_push_phase2c"("p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."confirm_retention_schedule_trigger"("p_input" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_s public.project_retention_release_schedules%rowtype; v_context jsonb;
  v_date date; v_reason text; v_evidence jsonb; v_event text;
begin
  select * into v_s from public.project_retention_release_schedules where id=(p_input->>'scheduleId')::uuid;
  if not found then return jsonb_build_object('succeeded',false,'errorCode','schedule_not_found'); end if;
  v_context:=private.retention_phase4_context(v_s.project_id,'retention.schedules.confirm',true);
  if not coalesce((v_context->>'succeeded')::boolean,false) then return v_context; end if;
  select * into v_s from public.project_retention_release_schedules where id=v_s.id for update;
  if v_s.status not in ('scheduled','awaiting_confirmation') then
    return jsonb_build_object('succeeded',false,'errorCode','schedule_not_activatable');
  end if;
  if v_s.revision<>(p_input->>'expectedRevision')::bigint then
    return jsonb_build_object('succeeded',false,'errorCode','concurrent_update','currentRevision',v_s.revision);
  end if;
  v_date:=(p_input->>'actualTriggerDate')::date;
  v_reason:=nullif(trim(coalesce(p_input->>'reason','')),'');
  v_evidence:=p_input->'evidence';
  if v_date is null then return jsonb_build_object('succeeded',false,'errorCode','invalid_trigger'); end if;
  if v_s.trigger_type in ('manual_milestone','custom')
    and (v_reason is null or v_evidence is null or jsonb_typeof(v_evidence)<>'object') then
    return jsonb_build_object('succeeded',false,'errorCode','trigger_confirmation_required');
  end if;
  v_event:=case when v_s.trigger_confirmed_at is null then 'trigger_confirmed'
                else 'trigger_confirmation_amended' end;
  update public.project_retention_release_schedules set
    status='awaiting_confirmation',actual_trigger_date=v_date,
    trigger_confirmed_at=now(),trigger_confirmed_by=auth.uid(),
    trigger_confirmation_reason=v_reason,
    trigger_confirmation_evidence=coalesce(v_evidence,'{}'::jsonb),
    revision=revision+1
  where id=v_s.id returning * into v_s;
  perform private.record_retention_schedule_event(
    v_s.id,v_event,'scheduled','awaiting_confirmation','Contractual trigger confirmed.',
    p_input->>'correlationId',jsonb_build_object('actualTriggerDate',v_date,'reason',v_reason)
  );
  return jsonb_build_object('succeeded',true,'errorCode',null,'schedule',to_jsonb(v_s));
end;
$$;


ALTER FUNCTION "public"."confirm_retention_schedule_trigger"("p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."confirm_supplier_price_tax_evidence"("p_input" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_org uuid := (p_input->>'organization_id')::uuid;
  v_actor uuid;
  v_previous public.organization_material_supplier_prices%rowtype;
  v_policy public.organization_tax_policies%rowtype;
  v_existing public.organization_material_supplier_price_tax_correction_events%rowtype;
  v_effective_from timestamptz := (p_input->>'effective_from')::timestamptz;
  v_reason text := nullif(pg_catalog.btrim(p_input->>'reason'), '');
  v_key text := nullif(pg_catalog.btrim(p_input->>'idempotency_key'), '');
  v_basis text := coalesce(nullif(p_input->>'source_tax_basis', ''), 'unknown');
  v_source_rate numeric := nullif(p_input->>'source_tax_rate', '')::numeric;
  v_snapshot jsonb;
  v_metadata jsonb;
  v_result jsonb;
  v_new_price_id uuid;
begin
  v_actor := public.materials_phase1f_require_writer(v_org);
  if v_reason is null or char_length(v_reason) < 8 then
    perform public.materials_phase1f_error('tax_correction_reason_required');
  end if;
  if v_key is null then
    perform public.materials_phase1f_error('idempotency_key_required');
  end if;
  if v_effective_from is null or v_effective_from > statement_timestamp() + interval '1 second' then
    perform public.materials_phase1f_error('invalid_tax_correction_effective_date');
  end if;

  select * into v_existing
  from public.organization_material_supplier_price_tax_correction_events
  where organization_id = v_org and idempotency_key = v_key;
  if found then
    if v_existing.previous_supplier_price_id is distinct from (p_input->>'previous_supplier_price_id')::uuid
      or v_existing.policy_id is distinct from (p_input->>'policy_id')::uuid
      or v_existing.effective_from is distinct from v_effective_from
      or v_existing.reason is distinct from v_reason then
      perform public.materials_phase1f_error('idempotency_conflict');
    end if;
    return pg_catalog.jsonb_build_object(
      'supplier_product_id', v_existing.supplier_product_id,
      'price_id', v_existing.new_supplier_price_id,
      'supersedes_price_id', v_existing.previous_supplier_price_id,
      'correction_event_id', v_existing.id,
      'idempotent_replay', true
    );
  end if;

  select * into v_previous
  from public.organization_material_supplier_prices
  where organization_id = v_org
    and id = (p_input->>'previous_supplier_price_id')::uuid
  for update;
  if not found then perform public.materials_phase1f_error('supplier_price_not_found'); end if;
  if not v_previous.is_current then perform public.materials_phase1f_error('stale_supplier_price'); end if;
  if v_previous.supplier_product_id is null then perform public.materials_phase1f_error('supplier_product_not_found'); end if;
  if v_effective_from <= v_previous.effective_from then
    perform public.materials_phase1f_error('invalid_tax_correction_effective_date');
  end if;
  if v_basis not in ('exclusive', 'inclusive', 'zero_rated', 'exempt', 'no_tax') then
    perform public.materials_phase1f_error('confirmed_source_tax_basis_required');
  end if;

  select * into v_policy
  from public.organization_tax_policies
  where organization_id = v_org
    and id = (p_input->>'policy_id')::uuid
    and effective_from <= v_effective_from
    and (effective_to is null or effective_to > v_effective_from)
  for share;
  if not found then perform public.materials_phase1f_error('stale_tax_policy'); end if;
  if not v_policy.supports_inclusive_exclusive then
    perform public.materials_phase1f_error('unsupported_tax_jurisdiction');
  end if;
  if v_basis in ('exclusive', 'inclusive') and v_source_rate is not null
    and pg_catalog.abs(v_source_rate - v_policy.standard_rate) > 0.0001 then
    perform public.materials_phase1f_error('tax_rate_conflict');
  end if;

  v_snapshot := pg_catalog.jsonb_build_object(
    'sourceTaxBasis', v_basis,
    'sourceTaxRate', case when v_basis in ('zero_rated', 'no_tax') then 0 else v_source_rate end,
    'taxJurisdictionCode', v_policy.jurisdiction_code,
    'comparisonTaxBasis', v_policy.comparison_basis,
    'comparisonTaxRate', v_policy.standard_rate,
    'taxPolicySnapshot', pg_catalog.jsonb_build_object(
      'policyId', v_policy.id,
      'jurisdictionCode', v_policy.jurisdiction_code,
      'taxName', v_policy.tax_name,
      'registrationStatus', v_policy.registration_status,
      'comparisonBasis', v_policy.comparison_basis,
      'standardRate', v_policy.standard_rate,
      'supportsInclusiveExclusive', v_policy.supports_inclusive_exclusive,
      'effectiveFrom', v_policy.effective_from,
      'effectiveTo', v_policy.effective_to,
      'policySource', v_policy.policy_source
    ),
    'taxEvidence', coalesce(v_previous.tax_evidence, '{}'::jsonb) || pg_catalog.jsonb_build_object(
      'confirmationSource', 'user_confirmed',
      'actorUserId', v_actor,
      'confirmedAt', statement_timestamp(),
      'correctionReason', v_reason,
      'previousSupplierPriceId', v_previous.id
    )
  );
  v_metadata := pg_catalog.jsonb_build_object(
    'tax_snapshot', v_snapshot,
    'tax_review', pg_catalog.jsonb_build_object(
      'status', 'complete',
      'acknowledged', true,
      'reason', v_reason,
      'actorUserId', v_actor,
      'reviewedAt', statement_timestamp(),
      'previousSupplierPriceId', v_previous.id
    ),
    'tax_correction', pg_catalog.jsonb_build_object(
      'previousSupplierPriceId', v_previous.id,
      'policyId', v_policy.id,
      'effectiveFrom', v_effective_from,
      'reason', v_reason
    )
  );
  perform public.materials_validate_price_tax_review_state(
    pg_catalog.jsonb_build_object('observation_metadata', v_metadata)
  );

  v_result := public.materials_phase1f_add_price_internal(
    v_org, v_previous.supplier_product_id, v_previous.unit_cost, v_previous.currency,
    v_effective_from, true, v_previous.source, 'tax-correction:' || v_key,
    v_previous.import_batch_id, v_previous.import_row_id, v_metadata
  );
  v_new_price_id := (v_result->>'price_id')::uuid;

  insert into public.organization_material_supplier_price_tax_correction_events (
    organization_id, supplier_product_id, previous_supplier_price_id,
    new_supplier_price_id, reason, evidence_source, policy_id, effective_from,
    actor_user_id, idempotency_key, metadata
  ) values (
    v_org, v_previous.supplier_product_id, v_previous.id, v_new_price_id,
    v_reason,
    case when coalesce(v_previous.tax_evidence, '{}'::jsonb) <> '{}'::jsonb
      then 'document_and_user_confirmed' else 'user_confirmed' end,
    v_policy.id, v_effective_from, v_actor, v_key,
    pg_catalog.jsonb_build_object(
      'source', v_previous.source,
      'importBatchId', v_previous.import_batch_id,
      'importRowId', v_previous.import_row_id,
      'sourceTaxBasisBefore', v_previous.source_tax_basis,
      'sourceTaxBasisAfter', v_basis
    )
  ) returning id into v_existing.id;

  return v_result || pg_catalog.jsonb_build_object(
    'correction_event_id', v_existing.id,
    'policy_id', v_policy.id
  );
end;
$$;


ALTER FUNCTION "public"."confirm_supplier_price_tax_evidence"("p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."convert_accepted_opportunity_to_project"("p_organization_id" "uuid", "p_opportunity_id" "uuid", "p_accepted_quote_id" "uuid") RETURNS TABLE("project_id" "uuid", "project_slug" "text", "project_created" boolean, "storage_clone_required" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  conversion_result record;
begin
  select * into conversion_result
  from public.convert_accepted_opportunity_to_project_without_document_guard(
    p_organization_id,
    p_opportunity_id,
    p_accepted_quote_id
  );

  perform public.ensure_opportunity_project_document_workspace(
    p_opportunity_id,
    conversion_result.project_id
  );

  return query select
    conversion_result.project_id,
    conversion_result.project_slug,
    conversion_result.project_created,
    conversion_result.storage_clone_required;
end;
$$;


ALTER FUNCTION "public"."convert_accepted_opportunity_to_project"("p_organization_id" "uuid", "p_opportunity_id" "uuid", "p_accepted_quote_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."convert_accepted_opportunity_to_project"("p_organization_id" "uuid", "p_opportunity_id" "uuid", "p_accepted_quote_id" "uuid") IS 'Legacy Opportunity conversion with transactional Opportunity/Project document workspace continuity on every return path.';



CREATE OR REPLACE FUNCTION "public"."convert_accepted_opportunity_to_project_without_document_guard"("p_organization_id" "uuid", "p_opportunity_id" "uuid", "p_accepted_quote_id" "uuid") RETURNS TABLE("project_id" "uuid", "project_slug" "text", "project_created" boolean, "storage_clone_required" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
declare
  actor_user_id uuid := auth.uid();
  opportunity_row public.organization_opportunities%rowtype;
  workspace_row public.organization_projects%rowtype;
  accepted_quote_row public.project_quotes%rowtype;
  final_project_row public.organization_projects%rowtype;
  existing_final_project_id uuid;
  base_slug text;
  candidate_slug text;
  slug_suffix integer := 2;
  orphan_candidate_count integer;
begin
  if actor_user_id is null then
    raise exception 'Authentication is required'
      using errcode = '42501';
  end if;

  if not (
    public.has_org_permission(p_organization_id, 'leads.opportunities.write')
    and public.has_org_permission(p_organization_id, 'quotes.write')
  ) then
    raise exception 'Not authorized for this organization'
      using errcode = '42501';
  end if;

  select *
  into opportunity_row
  from public.organization_opportunities opportunity
  where opportunity.id = p_opportunity_id
    and opportunity.organization_id = p_organization_id
  for update;

  if not found then
    raise exception 'Opportunity not found for organization'
      using errcode = 'TS422';
  end if;

  if exists (
    select 1
    from public.opportunity_lifecycles lifecycle
    where lifecycle.organization_id = p_organization_id
      and lifecycle.opportunity_id = p_opportunity_id
      and lifecycle.strategy = 'promote_workspace_v1'
  ) then
    raise exception
      'Promotion-strategy Opportunities cannot use legacy conversion'
      using errcode = 'TS409';
  end if;

  select final_project.project_id
  into existing_final_project_id
  from public.opportunity_final_projects final_project
  where final_project.organization_id = p_organization_id
    and final_project.opportunity_id = p_opportunity_id;

  if existing_final_project_id is not null then
    select *
    into final_project_row
    from public.organization_projects project
    where project.id = existing_final_project_id
      and project.organization_id = p_organization_id;

    if not found then
      raise exception 'Designated final Project is missing'
        using errcode = 'TS409';
    end if;

    return query
    select final_project_row.id, final_project_row.slug, false, true;
    return;
  end if;

  select *
  into accepted_quote_row
  from public.project_quotes quote
  where quote.id = p_accepted_quote_id
    and quote.organization_id = p_organization_id
    and quote.originating_opportunity_id = p_opportunity_id
  for update;

  if not found then
    raise exception 'Accepted quote does not belong to this Opportunity'
      using errcode = 'TS422';
  end if;

  if accepted_quote_row.status <> 'Accepted' then
    raise exception 'Quote must be Accepted before conversion'
      using errcode = 'TS422';
  end if;

  if exists (
    select 1
    from public.project_quotes newer_quote
    where newer_quote.organization_id = p_organization_id
      and newer_quote.originating_opportunity_id = p_opportunity_id
      and newer_quote.status = 'Accepted'
      and (
        newer_quote.updated_at > accepted_quote_row.updated_at
        or (
          newer_quote.updated_at = accepted_quote_row.updated_at
          and newer_quote.id > accepted_quote_row.id
        )
      )
  ) then
    raise exception
      'Accepted quote has been superseded by a newer Accepted quote'
      using errcode = 'TS409';
  end if;

  if opportunity_row.workspace_project_id is null then
    raise exception 'Opportunity has no recorded tender workspace'
      using errcode = 'TS422';
  end if;

  select *
  into workspace_row
  from public.organization_projects project
  where project.id = opportunity_row.workspace_project_id
    and project.organization_id = p_organization_id
  for key share;

  if not found
    or workspace_row.source_opportunity_id is distinct from opportunity_row.id
  then
    raise exception 'Tender workspace does not belong to the Opportunity'
      using errcode = 'TS409';
  end if;

  if accepted_quote_row.project_id is not null
    and accepted_quote_row.project_id <> workspace_row.id
  then
    raise exception 'Accepted quote is attached to an unrelated Project'
      using errcode = 'TS409';
  end if;

  select count(*)
  into orphan_candidate_count
  from public.organization_projects project
  where project.organization_id = p_organization_id
    and project.source_opportunity_id = opportunity_row.id
    and project.id <> workspace_row.id;

  if orphan_candidate_count > 0 then
    raise exception
      'Opportunity has unclassified delivery Project candidates; administrative reconciliation is required'
      using errcode = 'TS409',
            detail = orphan_candidate_count::text;
  end if;

  base_slug := regexp_replace(
    regexp_replace(lower(btrim(opportunity_row.name)), '[^a-z0-9]+', '-', 'g'),
    '(^-+|-+$)',
    '',
    'g'
  );
  base_slug := coalesce(nullif(base_slug, ''), 'project');

  perform pg_advisory_xact_lock(
    hashtextextended(
      p_organization_id::text || ':project-slug:' || base_slug,
      0
    )
  );

  candidate_slug := base_slug;
  while exists (
    select 1
    from public.organization_projects project
    where project.organization_id = p_organization_id
      and lower(project.slug) = lower(candidate_slug)
  ) loop
    candidate_slug := base_slug || '-' || slug_suffix::text;
    slug_suffix := slug_suffix + 1;
  end loop;

  insert into public.organization_projects (
    organization_id,
    created_by,
    client_id,
    name,
    slug,
    stage,
    location,
    cover_image_url,
    source_opportunity_id
  )
  values (
    p_organization_id,
    actor_user_id,
    opportunity_row.client_id,
    opportunity_row.name,
    candidate_slug,
    'Pricing',
    coalesce(nullif(btrim(opportunity_row.location), ''), 'Unspecified'),
    null,
    opportunity_row.id
  )
  returning * into final_project_row;

  insert into public.opportunity_final_projects (
    opportunity_id,
    organization_id,
    project_id,
    accepted_quote_id,
    created_by
  )
  values (
    opportunity_row.id,
    p_organization_id,
    final_project_row.id,
    accepted_quote_row.id,
    actor_user_id
  );

  perform *
  from public.attach_opportunity_commercial_history_to_project(
    p_organization_id,
    opportunity_row.id,
    final_project_row.id
  );

  perform public.sync_opportunity_legacy_quote_on_conversion(
    p_organization_id,
    opportunity_row.id,
    final_project_row.id,
    actor_user_id
  );

  perform public.ensure_opportunity_project_document_workspace(
    opportunity_row.id,
    final_project_row.id
  );

  update public.organization_opportunities opportunity
  set converted_project_id = final_project_row.id,
      converted_at = timezone('utc', now()),
      stage = 'Won',
      quoted_at = coalesce(
        opportunity.quoted_at,
        accepted_quote_row.quote_date,
        timezone('utc', now())::date
      )
  where opportunity.id = opportunity_row.id
    and opportunity.organization_id = p_organization_id;

  return query
  select final_project_row.id, final_project_row.slug, true, true;
end;
$_$;


ALTER FUNCTION "public"."convert_accepted_opportunity_to_project_without_document_guard"("p_organization_id" "uuid", "p_opportunity_id" "uuid", "p_accepted_quote_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."convert_accepted_opportunity_to_project_without_document_guard"("p_organization_id" "uuid", "p_opportunity_id" "uuid", "p_accepted_quote_id" "uuid") IS 'Atomically validates the current Accepted canonical quote, serializes conversion on the Opportunity row, creates at most one final Project, reparents eligible commercial history, and marks the Opportunity Won.';



CREATE OR REPLACE FUNCTION "public"."convert_opportunity_quote_to_project_quote"("p_organization_id" "uuid", "p_opportunity_id" "uuid", "p_opportunity_quote_id" "uuid", "p_project_id" "uuid", "p_fallback_created_by" "uuid") RETURNS TABLE("project_quote_id" "uuid", "source_opportunity_quote_id" "uuid", "project_quote_number" "text", "quote_date" "date")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  opportunity_row public.organization_opportunities%rowtype;
  opportunity_quote_row public.opportunity_quotes%rowtype;
  project_quote_row public.project_quotes%rowtype;
  quote_number_for_project text;
  quote_number_conflict_id uuid;
begin
  if auth.uid() is null then
    raise exception 'Authentication is required';
  end if;

  if not public.has_org_permission(p_organization_id, 'quotes.write') then
    raise exception 'Not authorized for this organization';
  end if;

  select *
  into opportunity_row
  from public.organization_opportunities o
  where o.id = p_opportunity_id
    and o.organization_id = p_organization_id;

  if not found then
    raise exception 'Opportunity not found for organization';
  end if;

  select *
  into opportunity_quote_row
  from public.opportunity_quotes q
  where q.id = p_opportunity_quote_id
    and q.organization_id = p_organization_id
    and q.opportunity_id = p_opportunity_id;

  if not found then
    raise exception 'Opportunity quote not found for organization';
  end if;

  if not exists (
    select 1
    from public.organization_projects p
    where p.id = p_project_id
      and p.organization_id = p_organization_id
  ) then
    raise exception 'Project not found for organization';
  end if;

  if not exists (
    select 1
    from public.cost_items ci
    where ci.source_document_kind = 'opportunity_quote'
      and ci.source_document_id = p_opportunity_quote_id
      and ci.is_current = true
  ) then
    raise exception 'Opportunity quote has no current baseline CostItems';
  end if;

  select pq.id
  into quote_number_conflict_id
  from public.project_quotes pq
  where pq.organization_id = p_organization_id
    and pq.quote_number = opportunity_quote_row.quote_number
  limit 1;

  quote_number_for_project := case
    when quote_number_conflict_id is not null then ''
    else opportunity_quote_row.quote_number
  end;

  insert into public.project_quotes (
    organization_id,
    project_id,
    created_by,
    quote_title,
    quote_number,
    client_name,
    company_name,
    contact_person,
    client_email,
    client_phone,
    site_address,
    project_name,
    quote_date,
    expiry_date,
    status,
    optional_items_notes,
    scope_exclusions,
    assumptions,
    scope_notes,
    subtotal,
    optional_subtotal,
    margin_percent,
    margin_amount,
    discount_amount,
    contingency_amount,
    gst_percent,
    gst_amount,
    total_quote_price,
    validity_period,
    payment_terms,
    lead_time,
    terms_inclusions,
    terms_exclusions,
    clarifications,
    acceptance_notes,
    source_opportunity_id,
    source_opportunity_quote_id,
    source_opportunity_quote_number
  ) values (
    p_organization_id,
    p_project_id,
    coalesce(opportunity_quote_row.created_by, p_fallback_created_by),
    opportunity_quote_row.quote_title,
    quote_number_for_project,
    opportunity_quote_row.client_name,
    opportunity_quote_row.company_name,
    opportunity_quote_row.contact_person,
    opportunity_quote_row.client_email,
    opportunity_quote_row.client_phone,
    opportunity_quote_row.site_address,
    opportunity_quote_row.project_name,
    opportunity_quote_row.quote_date,
    opportunity_quote_row.expiry_date,
    opportunity_quote_row.status,
    opportunity_quote_row.optional_items_notes,
    opportunity_quote_row.scope_exclusions,
    opportunity_quote_row.assumptions,
    opportunity_quote_row.scope_notes,
    opportunity_quote_row.subtotal,
    opportunity_quote_row.optional_subtotal,
    opportunity_quote_row.margin_percent,
    opportunity_quote_row.margin_amount,
    opportunity_quote_row.discount_amount,
    opportunity_quote_row.contingency_amount,
    opportunity_quote_row.gst_percent,
    opportunity_quote_row.gst_amount,
    opportunity_quote_row.total_quote_price,
    opportunity_quote_row.validity_period,
    opportunity_quote_row.payment_terms,
    opportunity_quote_row.lead_time,
    opportunity_quote_row.terms_inclusions,
    opportunity_quote_row.terms_exclusions,
    opportunity_quote_row.clarifications,
    opportunity_quote_row.acceptance_notes,
    p_opportunity_id,
    p_opportunity_quote_id,
    opportunity_quote_row.quote_number
  )
  returning * into project_quote_row;

  insert into public.project_quote_line_items (
    organization_id,
    project_id,
    quote_id,
    section,
    description,
    quantity,
    unit,
    rate,
    total,
    is_optional,
    sort_order,
    source_opportunity_quote_id,
    source_opportunity_quote_line_item_id,
    source_opportunity_quote_number
  )
  select
    p_organization_id,
    p_project_id,
    project_quote_row.id,
    li.section,
    li.description,
    li.quantity,
    li.unit,
    li.rate,
    li.total,
    li.is_optional,
    li.sort_order,
    p_opportunity_quote_id,
    li.id,
    opportunity_quote_row.quote_number
  from public.opportunity_quote_line_items li
  where li.organization_id = p_organization_id
    and li.quote_id = p_opportunity_quote_id
  order by li.sort_order, li.id;

  perform public.upsert_project_quote_cost_items_from_opportunity(
    p_organization_id,
    project_quote_row.id,
    p_opportunity_quote_id
  );

  return query
  select
    project_quote_row.id,
    p_opportunity_quote_id,
    project_quote_row.quote_number,
    project_quote_row.quote_date;
end;
$$;


ALTER FUNCTION "public"."convert_opportunity_quote_to_project_quote"("p_organization_id" "uuid", "p_opportunity_id" "uuid", "p_opportunity_quote_id" "uuid", "p_project_id" "uuid", "p_fallback_created_by" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."count_trade_pack_workspaces_created_in_month"("p_organization_id" "uuid", "p_reference_at" timestamp with time zone DEFAULT "now"()) RETURNS integer
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_month_start timestamptz;
  v_month_end timestamptz;
  v_count integer := 0;
begin
  if p_organization_id is null then
    return 0;
  end if;

  v_month_start := date_trunc('month', coalesce(p_reference_at, now()));
  v_month_end := v_month_start + interval '1 month';

  select count(*)
  into v_count
  from public.organization_projects p
  where p.organization_id = p_organization_id
    and p.created_at >= v_month_start
    and p.created_at < v_month_end;

  return coalesce(v_count, 0);
end;
$$;


ALTER FUNCTION "public"."count_trade_pack_workspaces_created_in_month"("p_organization_id" "uuid", "p_reference_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_accounting_revision_attempt_phase2a"("p_revision_id" "uuid", "p_attempt_intent" "text", "p_idempotency_key" "text", "p_request_evidence" "jsonb") RETURNS "public"."organization_accounting_revision_attempts"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  revision public.organization_accounting_document_revisions%rowtype;
  attempt public.organization_accounting_revision_attempts%rowtype;
begin
  select * into revision
  from public.organization_accounting_document_revisions where id = p_revision_id;
  if not found then raise exception 'Accounting revision not found.'; end if;

  insert into public.organization_accounting_revision_attempts(
    organization_id, accounting_revision_id, attempt_sequence, attempt_intent,
    idempotency_key, request_evidence
  ) values (
    revision.organization_id, revision.id,
    coalesce((
      select max(a.attempt_sequence) + 1
      from public.organization_accounting_revision_attempts a
      where a.accounting_revision_id = revision.id
    ), 1),
    p_attempt_intent, p_idempotency_key, p_request_evidence
  )
  on conflict (idempotency_key) do nothing
  returning * into attempt;
  if attempt.id is null then
    select * into attempt
    from public.organization_accounting_revision_attempts
    where idempotency_key = p_idempotency_key;
    if attempt.accounting_revision_id <> revision.id
      or attempt.attempt_intent <> p_attempt_intent
      or attempt.request_evidence is distinct from p_request_evidence then
      raise exception 'Accounting attempt idempotency key was reused with different evidence.';
    end if;
  end if;
  return attempt;
end;
$$;


ALTER FUNCTION "public"."create_accounting_revision_attempt_phase2a"("p_revision_id" "uuid", "p_attempt_intent" "text", "p_idempotency_key" "text", "p_request_evidence" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_ai_interaction"("p_input" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  member_row public.organization_members%rowtype;
  inserted_id uuid;
  resolved_organization_id uuid;
  resolved_project_id uuid;
  resolved_opportunity_id uuid;
  resolved_linked_event_id uuid;
begin
  if p_input is null or jsonb_typeof(p_input) <> 'object' then
    raise exception 'create_ai_interaction requires a JSON object payload';
  end if;

  resolved_organization_id := nullif(p_input->>'organizationId', '')::uuid;
  if resolved_organization_id is null then
    raise exception 'organizationId is required';
  end if;

  member_row := public._intelligence_assert_organization_member(resolved_organization_id);
  resolved_project_id := nullif(p_input->>'projectId', '')::uuid;
  resolved_opportunity_id := nullif(p_input->>'opportunityId', '')::uuid;
  resolved_linked_event_id := nullif(p_input->>'linkedEventId', '')::uuid;

  perform public._intelligence_assert_project_in_organization(resolved_organization_id, resolved_project_id);
  perform public._intelligence_assert_opportunity_in_organization(resolved_organization_id, resolved_opportunity_id);
  perform public._intelligence_assert_event_in_organization(resolved_organization_id, resolved_linked_event_id);

  insert into public.ai_interactions (
    organization_id,
    project_id,
    opportunity_id,
    module,
    interaction_type,
    subject_entity_type,
    subject_entity_id,
    linked_event_id,
    actor_user_id,
    actor_member_id,
    actor_role,
    source_channel,
    provider,
    model,
    model_version,
    prompt_template_key,
    prompt_text,
    input_context_summary,
    input_refs,
    output_text,
    output_structured,
    output_refs,
    confidence,
    validation_status,
    usage_input_tokens,
    usage_output_tokens,
    usage_total_tokens,
    latency_ms,
    run_status,
    lifecycle_state,
    human_disposition,
    human_feedback_summary,
    edited_output,
    finalized_by_user_id,
    finalized_at,
    superseded_by_interaction_id,
    privacy_classification,
    visibility_scope,
    retention_policy_key,
    retention_expires_at
  )
  values (
    resolved_organization_id,
    resolved_project_id,
    resolved_opportunity_id,
    nullif(btrim(coalesce(p_input->>'module', '')), ''),
    nullif(btrim(coalesce(p_input->>'interactionType', '')), ''),
    nullif(btrim(coalesce(p_input->>'subjectEntityType', '')), ''),
    nullif(p_input->>'subjectEntityId', '')::uuid,
    resolved_linked_event_id,
    auth.uid(),
    member_row.id,
    member_row.role,
    coalesce(nullif(btrim(coalesce(p_input->>'sourceChannel', '')), ''), 'web'),
    nullif(btrim(coalesce(p_input->>'provider', '')), ''),
    nullif(btrim(coalesce(p_input->>'model', '')), ''),
    nullif(btrim(coalesce(p_input->>'modelVersion', '')), ''),
    nullif(btrim(coalesce(p_input->>'promptTemplateKey', '')), ''),
    nullif(p_input->>'promptText', ''),
    coalesce(p_input->'inputContextSummary', '{}'::jsonb),
    coalesce(p_input->'inputRefs', '[]'::jsonb),
    nullif(p_input->>'outputText', ''),
    p_input->'outputStructured',
    coalesce(p_input->'outputRefs', '[]'::jsonb),
    nullif(p_input->>'confidence', '')::numeric,
    nullif(btrim(coalesce(p_input->>'validationStatus', '')), ''),
    nullif(p_input->>'usageInputTokens', '')::integer,
    nullif(p_input->>'usageOutputTokens', '')::integer,
    nullif(p_input->>'usageTotalTokens', '')::integer,
    nullif(p_input->>'latencyMs', '')::integer,
    coalesce(nullif(btrim(coalesce(p_input->>'runStatus', '')), ''), 'completed'),
    coalesce(nullif(btrim(coalesce(p_input->>'lifecycleState', '')), ''), 'generated'),
    nullif(btrim(coalesce(p_input->>'humanDisposition', '')), ''),
    nullif(p_input->>'humanFeedbackSummary', ''),
    p_input->'editedOutput',
    case
      when nullif(btrim(coalesce(p_input->>'humanDisposition', '')), '') is not null then auth.uid()
      else null
    end,
    case
      when nullif(btrim(coalesce(p_input->>'humanDisposition', '')), '') is not null then now()
      else null
    end,
    nullif(p_input->>'supersededByInteractionId', '')::uuid,
    coalesce(nullif(btrim(coalesce(p_input->>'privacyClassification', '')), ''), 'commercial_sensitive'),
    coalesce(nullif(btrim(coalesce(p_input->>'visibilityScope', '')), ''), 'organization'),
    nullif(btrim(coalesce(p_input->>'retentionPolicyKey', '')), ''),
    nullif(p_input->>'retentionExpiresAt', '')::timestamptz
  )
  returning id into inserted_id;

  return inserted_id;
end;
$$;


ALTER FUNCTION "public"."create_ai_interaction"("p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_blank_project_qa_v1"("p_organization_id" "uuid", "p_project_id" "uuid", "p_name" "text", "p_description" "text" DEFAULT ''::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare result_id uuid;
begin
  if auth.uid() is null or not public.can_access_qa_project(p_organization_id,p_project_id,'qa.write') then raise exception 'Not authorized' using errcode='42501'; end if;
  if char_length(btrim(coalesce(p_name,''))) not between 1 and 160 then raise exception 'QA name is required' using errcode='TS422'; end if;
  insert into public.project_qas(organization_id,project_id,name,description,created_by,updated_by)
  values(p_organization_id,p_project_id,btrim(p_name),coalesce(p_description,''),auth.uid(),auth.uid()) returning id into result_id;
  return result_id;
end; $$;


