CREATE TABLE IF NOT EXISTS "public"."document_nodes" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "workspace_id" "uuid" NOT NULL,
    "parent_node_id" "uuid",
    "kind" "text" NOT NULL,
    "display_name" "text" NOT NULL,
    "normalized_name" "text" GENERATED ALWAYS AS ("lower"("btrim"("display_name"))) STORED,
    "current_version_id" "uuid",
    "created_by" "uuid" NOT NULL,
    "updated_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "deleted_at" timestamp with time zone,
    "deleted_by" "uuid",
    "deletion_batch_id" "uuid",
    "lifecycle_state" "text" DEFAULT 'active'::"text" NOT NULL,
    CONSTRAINT "document_nodes_deletion_fields_check" CHECK (((("deleted_at" IS NULL) AND ("deleted_by" IS NULL) AND ("deletion_batch_id" IS NULL)) OR (("deleted_at" IS NOT NULL) AND ("deleted_by" IS NOT NULL) AND ("deletion_batch_id" IS NOT NULL)))),
    CONSTRAINT "document_nodes_folder_version_check" CHECK ((("kind" = 'file'::"text") OR ("current_version_id" IS NULL))),
    CONSTRAINT "document_nodes_kind_check" CHECK (("kind" = ANY (ARRAY['folder'::"text", 'file'::"text"]))),
    CONSTRAINT "document_nodes_lifecycle_state_check" CHECK (((("kind" = 'folder'::"text") AND ("lifecycle_state" = 'active'::"text")) OR (("kind" = 'file'::"text") AND ("lifecycle_state" = ANY (ARRAY['pending'::"text", 'active'::"text", 'abandoned'::"text"]))))),
    CONSTRAINT "document_nodes_name_control_character_check" CHECK (("display_name" !~ '[[:cntrl:]]'::"text")),
    CONSTRAINT "document_nodes_name_length_check" CHECK ((("char_length"("display_name") >= 1) AND ("char_length"("display_name") <= 250))),
    CONSTRAINT "document_nodes_name_path_separator_check" CHECK (("display_name" !~ '[/\\]'::"text")),
    CONSTRAINT "document_nodes_name_reserved_check" CHECK (("display_name" <> ALL (ARRAY['.'::"text", '..'::"text"]))),
    CONSTRAINT "document_nodes_name_trimmed_check" CHECK (("display_name" = "btrim"("display_name"))),
    CONSTRAINT "document_nodes_not_own_parent_check" CHECK ((("parent_node_id" IS NULL) OR ("parent_node_id" <> "id")))
);

ALTER TABLE ONLY "public"."document_nodes" FORCE ROW LEVEL SECURITY;


ALTER TABLE "public"."document_nodes" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_document_folder"("p_workspace_id" "uuid", "p_parent_node_id" "uuid", "p_display_name" "text") RETURNS "public"."document_nodes"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  actor_user_id uuid := auth.uid();
  workspace_row public.document_workspaces%rowtype;
  node_row public.document_nodes%rowtype;
begin
  workspace_row := public.assert_document_workspace_permission(
    p_workspace_id,
    'files.write'
  );

  perform pg_advisory_xact_lock(
    hashtextextended('document-workspace:' || workspace_row.id::text, 0)
  );

  if p_parent_node_id is not null then
    perform 1
    from public.document_nodes parent
    where parent.organization_id = workspace_row.organization_id
      and parent.workspace_id = workspace_row.id
      and parent.id = p_parent_node_id
      and parent.kind = 'folder'
      and parent.deleted_at is null
    for update;

    if not found then
      raise exception 'Parent folder not found.'
        using errcode = '23503';
    end if;
  end if;

  insert into public.document_nodes (
    organization_id,
    workspace_id,
    parent_node_id,
    kind,
    display_name,
    created_by,
    updated_by
  )
  values (
    workspace_row.organization_id,
    workspace_row.id,
    p_parent_node_id,
    'folder',
    btrim(p_display_name),
    actor_user_id,
    actor_user_id
  )
  returning * into node_row;

  insert into public.document_activity_events (
    organization_id,
    workspace_id,
    node_id,
    actor_user_id,
    event_type,
    metadata
  )
  values (
    workspace_row.organization_id,
    workspace_row.id,
    node_row.id,
    actor_user_id,
    'folder_created',
    jsonb_build_object(
      'displayName', node_row.display_name,
      'parentNodeId', node_row.parent_node_id
    )
  );

  return node_row;
end;
$$;


ALTER FUNCTION "public"."create_document_folder"("p_workspace_id" "uuid", "p_parent_node_id" "uuid", "p_display_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_missing_opportunity_client_quotes_v1"("p_organization_id" "uuid", "p_opportunity_id" "uuid") RETURNS TABLE("client_id" "uuid", "client_name" "text", "outcome" "text", "series_id" "uuid", "revision_id" "uuid", "base_quote_number" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare relationship record; result record;
begin
  if auth.uid() is null or not public.has_org_permission(p_organization_id, 'quotes.write') then
    raise exception 'Not authorized for this organization' using errcode = '42501';
  end if;
  if not exists (
    select 1 from public.organization_opportunities opportunity
    join public.opportunity_quote_series series
      on series.organization_id = opportunity.organization_id
     and series.opportunity_id = opportunity.id
     and series.recipient_client_id = opportunity.client_id
     and series.archived_at is null
    where opportunity.organization_id = p_organization_id and opportunity.id = p_opportunity_id
      and series.current_revision_id is not null
  ) then
    raise exception 'Create the Primary Client quote before creating missing Tender Client quotes'
      using errcode = 'TS422';
  end if;
  for relationship in
    select tender.client_id, coalesce(nullif(client.company_name, ''), client.name) as client_name
    from public.opportunity_tender_clients tender
    join public.organization_clients client
      on client.organization_id = tender.organization_id and client.id = tender.client_id
    where tender.organization_id = p_organization_id and tender.opportunity_id = p_opportunity_id
      and tender.archived_at is null
    order by tender.is_primary desc, tender.created_at, tender.client_id
  loop
    select * into result from public.distribute_opportunity_primary_quote_core_v1(
      p_organization_id, p_opportunity_id, relationship.client_id
    );
    return query select relationship.client_id, relationship.client_name,
      case when result.created then 'created' else 'skipped' end,
      result.series_id, result.revision_id, result.base_quote_number;
  end loop;
end;
$$;


ALTER FUNCTION "public"."create_missing_opportunity_client_quotes_v1"("p_organization_id" "uuid", "p_opportunity_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_opportunity_quote_revision_v1"("p_organization_id" "uuid", "p_opportunity_id" "uuid", "p_predecessor_quote_id" "uuid") RETURNS TABLE("series_id" "uuid", "revision_id" "uuid", "base_quote_number" "text", "revision_number" integer, "cloned_workbook_count" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  actor_user_id uuid := auth.uid();
  predecessor public.project_quotes%rowtype;
  existing_successor public.project_quotes%rowtype;
  series public.opportunity_quote_series%rowtype;
  recipient public.organization_clients%rowtype;
  created_quote public.project_quotes%rowtype;
  source_workbook public.opportunity_pricing_worksheets%rowtype;
  source_sheet public.opportunity_pricing_workbook_sheets%rowtype;
  created_workbook_id uuid;
  cloned_count integer := 0;
  next_revision integer;
begin
  if actor_user_id is null or not public.has_org_permission(p_organization_id, 'quotes.write') then
    raise exception 'Not authorized for this organization' using errcode = '42501';
  end if;
  select * into predecessor from public.project_quotes quote
  where quote.organization_id = p_organization_id
    and quote.originating_opportunity_id = p_opportunity_id
    and quote.id = p_predecessor_quote_id and quote.quote_series_id is not null
    and quote.revision_kind = 'tender'
  for update;
  if not found then raise exception 'Tender revision was not found for this Opportunity' using errcode = 'TS422'; end if;

  select * into series from public.opportunity_quote_series candidate
  where candidate.organization_id = p_organization_id and candidate.id = predecessor.quote_series_id
    and candidate.opportunity_id = p_opportunity_id and candidate.archived_at is null
  for update;
  if not found then raise exception 'Quote Series was not found' using errcode = 'TS422'; end if;

  select * into existing_successor from public.project_quotes quote
  where quote.organization_id = p_organization_id and quote.predecessor_quote_id = predecessor.id;
  if found then
    if existing_successor.quote_series_id is distinct from series.id then
      raise exception 'Existing successor has conflicting Quote Series lineage' using errcode = 'TS409';
    end if;
    return query select series.id, existing_successor.id, series.base_quote_number,
      existing_successor.revision_number,
      (select count(*)::integer from public.opportunity_pricing_worksheets workbook
       where workbook.organization_id = p_organization_id and workbook.quote_id = existing_successor.id);
    return;
  end if;
  if series.current_revision_id is distinct from predecessor.id then
    raise exception 'A newer current revision already exists' using errcode = 'TS409';
  end if;
  if predecessor.status = 'Draft' then
    raise exception 'The current Draft can be edited without creating a revision' using errcode = 'TS422';
  end if;
  if exists (select 1 from public.organization_opportunities opportunity
    where opportunity.organization_id = p_organization_id and opportunity.id = p_opportunity_id
      and (opportunity.converted_at is not null or opportunity.stage = 'Won')) then
    raise exception 'Tender revisions cannot be created after conversion' using errcode = 'TS409';
  end if;
  if series.recipient_client_id is null then
    raise exception 'Quote Series recipient must be reconciled before revision' using errcode = 'TS409';
  end if;
  select * into recipient from public.organization_clients client
  where client.organization_id = p_organization_id and client.id = series.recipient_client_id;
  if not found then raise exception 'Quote Series recipient is unavailable' using errcode = 'TS409'; end if;
  next_revision := predecessor.revision_number + 1;

  insert into public.project_quotes (
    organization_id, project_id, originating_opportunity_id, source_opportunity_id,
    source_opportunity_quote_id, source_opportunity_quote_number, created_by,
    quote_title, quote_number, client_name, company_name, contact_person, client_email,
    client_phone, site_address, project_name, quote_date, expiry_date, status,
    optional_items_notes, scope_exclusions, assumptions, scope_notes, subtotal,
    optional_subtotal, margin_percent, margin_amount, discount_amount, contingency_amount,
    gst_percent, gst_amount, total_quote_price, validity_period, payment_terms,
    retention_percent_default, lead_time, terms_inclusions, terms_exclusions,
    clarifications, acceptance_notes, predecessor_quote_id, revision_number,
    revision_kind, revision_created_by, pricing_basis_status, quote_series_id
  ) values (
    predecessor.organization_id, predecessor.project_id, predecessor.originating_opportunity_id,
    predecessor.source_opportunity_id, predecessor.source_opportunity_quote_id,
    predecessor.source_opportunity_quote_number, actor_user_id, predecessor.quote_title,
    series.base_quote_number || '-R' || next_revision::text, recipient.name,
    coalesce(recipient.company_name, ''), recipient.name, coalesce(recipient.email, ''),
    coalesce(recipient.phone, ''), predecessor.site_address, predecessor.project_name,
    current_date, predecessor.expiry_date, 'Draft', predecessor.optional_items_notes,
    predecessor.scope_exclusions, predecessor.assumptions, predecessor.scope_notes,
    predecessor.subtotal, predecessor.optional_subtotal, predecessor.margin_percent,
    predecessor.margin_amount, predecessor.discount_amount, predecessor.contingency_amount,
    predecessor.gst_percent, predecessor.gst_amount, predecessor.total_quote_price,
    predecessor.validity_period, predecessor.payment_terms, predecessor.retention_percent_default,
    predecessor.lead_time, predecessor.terms_inclusions, predecessor.terms_exclusions,
    predecessor.clarifications, predecessor.acceptance_notes, predecessor.id, next_revision,
    'tender', actor_user_id, 'unpublished', series.id
  ) returning * into created_quote;

  insert into public.project_quote_line_items (
    id, organization_id, project_id, quote_id, section, description, quantity, unit,
    rate, total, is_optional, sort_order, source_opportunity_quote_id,
    source_opportunity_quote_line_item_id, source_opportunity_quote_number, pricing_source_kind
  ) select md5(created_quote.id::text || ':line:' || line.id::text)::uuid,
    line.organization_id, line.project_id, created_quote.id, line.section, line.description,
    line.quantity, line.unit, line.rate, line.total, line.is_optional, line.sort_order,
    line.source_opportunity_quote_id, line.source_opportunity_quote_line_item_id,
    line.source_opportunity_quote_number, line.pricing_source_kind
  from public.project_quote_line_items line
  where line.organization_id = p_organization_id and line.quote_id = predecessor.id;

  insert into public.commercial_item_document_links (
    id, organization_id, commercial_item_id, document_kind, document_id,
    document_line_id, link_role, snapshot_at_link_json, created_by, created_at
  ) select md5(created_quote.id::text || ':link:' || link.id::text)::uuid,
    link.organization_id, link.commercial_item_id, link.document_kind, created_quote.id,
    md5(created_quote.id::text || ':line:' || link.document_line_id::text)::uuid,
    link.link_role, link.snapshot_at_link_json, actor_user_id, timezone('utc', now())
  from public.commercial_item_document_links link
  where link.organization_id = p_organization_id
    and link.document_kind = 'quote_line' and link.document_id = predecessor.id;

  for source_workbook in select * from public.opportunity_pricing_worksheets workbook
    where workbook.organization_id = p_organization_id and workbook.quote_id = predecessor.id
      and workbook.variation_id is null and workbook.archived_at is null
  loop
    created_workbook_id := md5(created_quote.id::text || ':workbook:' || source_workbook.id::text)::uuid;
    insert into public.opportunity_pricing_worksheets (
      id, organization_id, opportunity_id, project_id, quote_id, variation_id, name,
      trade_package, sort_order, archived_at, worksheet_data, pricing_summary,
      extracted_pricing_data, version, created_by, updated_by, source_workbook_id,
      source_workbook_version, source_award_manifest_id, source_quote_id, clone_kind
    ) values (
      created_workbook_id, p_organization_id, source_workbook.opportunity_id,
      source_workbook.project_id, created_quote.id, null, source_workbook.name,
      source_workbook.trade_package, source_workbook.sort_order, null,
      public.regenerate_worksheet_material_binding_ids(source_workbook.worksheet_data),
      source_workbook.pricing_summary, source_workbook.extracted_pricing_data,
      source_workbook.version, actor_user_id, actor_user_id, source_workbook.id,
      source_workbook.version, source_workbook.source_award_manifest_id, predecessor.id,
      'quote_revision'
    );
    for source_sheet in select * from public.opportunity_pricing_workbook_sheets sheet
      where sheet.organization_id = p_organization_id and sheet.workbook_id = source_workbook.id
    loop
      insert into public.opportunity_pricing_workbook_sheets (
        id, workbook_id, organization_id, opportunity_id, name, sheet_order, is_default,
        worksheet_data, pricing_summary, extracted_pricing_data, version, created_by, updated_by
      ) values (
        md5(created_quote.id::text || ':sheet:' || source_sheet.id::text)::uuid,
        created_workbook_id, p_organization_id, source_sheet.opportunity_id, source_sheet.name,
        source_sheet.sheet_order, source_sheet.is_default,
        public.regenerate_worksheet_material_binding_ids(source_sheet.worksheet_data),
        source_sheet.pricing_summary, source_sheet.extracted_pricing_data,
        source_sheet.version, actor_user_id, actor_user_id
      );
    end loop;
    cloned_count := cloned_count + 1;
  end loop;

  update public.opportunity_quote_series
  set current_revision_id = created_quote.id
  where organization_id = p_organization_id and id = series.id;
  return query select series.id, created_quote.id, series.base_quote_number, next_revision, cloned_count;
end;
$$;


ALTER FUNCTION "public"."create_opportunity_quote_revision_v1"("p_organization_id" "uuid", "p_opportunity_id" "uuid", "p_predecessor_quote_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_opportunity_quote_series_v1"("p_organization_id" "uuid", "p_opportunity_id" "uuid", "p_recipient_client_id" "uuid") RETURNS TABLE("series_id" "uuid", "revision_id" "uuid", "base_quote_number" "text", "revision_number" integer)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select result.series_id, result.revision_id, result.base_quote_number, result.revision_number
  from public.distribute_opportunity_primary_quote_core_v1(
    p_organization_id, p_opportunity_id, p_recipient_client_id
  ) result;
$$;


ALTER FUNCTION "public"."create_opportunity_quote_series_v1"("p_organization_id" "uuid", "p_opportunity_id" "uuid", "p_recipient_client_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_opportunity_workspace_controlled_v1"("p_organization_id" "uuid", "p_creation_request_id" "uuid", "p_name" "text", "p_client_id" "uuid" DEFAULT NULL::"uuid", "p_new_client" "jsonb" DEFAULT NULL::"jsonb", "p_owner_user_id" "uuid" DEFAULT NULL::"uuid", "p_location" "text" DEFAULT 'Unspecified'::"text", "p_due_date" "date" DEFAULT NULL::"date", "p_estimated_value" numeric DEFAULT 0, "p_notes" "text" DEFAULT ''::"text") RETURNS TABLE("opportunity_id" "uuid", "opportunity_slug" "text", "workspace_project_id" "uuid", "workspace_project_slug" "text", "lifecycle_id" "uuid", "records_created" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  override_row public.opportunity_lifecycle_rollout_controls%rowtype;
  default_row public.opportunity_lifecycle_default_policy%rowtype;
  selected_strategy text;
begin
  if auth.uid() is null then
    raise exception 'Authentication is required' using errcode = '42501';
  end if;

  if not public.has_org_permission(p_organization_id, 'leads.opportunities.write') then
    raise exception 'Not authorized for this organization' using errcode = '42501';
  end if;

  select * into override_row
  from public.opportunity_lifecycle_rollout_controls rollout
  where rollout.organization_id = p_organization_id
    and rollout.override_enabled
    and public.is_opportunity_lifecycle_override_active_v1(
      rollout.pilot_scope,
      rollout.pilot_environment
    );

  if found then
    if override_row.creation_enabled is not true then
      raise exception 'Opportunity lifecycle creation is not enabled for organization override'
        using errcode = 'TS409';
    end if;

    if override_row.allowed_strategy = 'promote_workspace_v1' then
      if override_row.promotion_enabled is not true then
        raise exception 'Opportunity promotion creation is not authorized by organization override'
          using errcode = 'TS409';
      end if;
      selected_strategy := 'promote_workspace_v1';
    elsif override_row.allowed_strategy = 'legacy_two_project_v1' then
      selected_strategy := 'legacy_two_project_v1';
    else
      raise exception 'Opportunity lifecycle organization override is contradictory'
        using errcode = 'TS409';
    end if;
  else
    select * into default_row
    from public.opportunity_lifecycle_default_policy policy
    where policy.singleton
      and policy.effective_from <= now();

    if not found or default_row.creation_enabled is not true then
      raise exception 'Opportunity lifecycle default creation is not enabled'
        using errcode = 'TS409';
    end if;

    if default_row.default_strategy = 'promote_workspace_v1' then
      if default_row.promotion_enabled is not true then
        raise exception 'Opportunity promotion default is paused'
          using errcode = 'TS409';
      end if;
      selected_strategy := 'promote_workspace_v1';
    elsif default_row.default_strategy = 'legacy_two_project_v1' then
      selected_strategy := 'legacy_two_project_v1';
    else
      raise exception 'Opportunity lifecycle default policy is contradictory'
        using errcode = 'TS409';
    end if;
  end if;

  return query
  select * from public.create_opportunity_workspace_v1(
    p_organization_id,
    p_creation_request_id,
    selected_strategy,
    p_name,
    p_client_id,
    p_new_client,
    p_owner_user_id,
    p_location,
    p_due_date,
    p_estimated_value,
    p_notes
  );
end;
$$;


ALTER FUNCTION "public"."create_opportunity_workspace_controlled_v1"("p_organization_id" "uuid", "p_creation_request_id" "uuid", "p_name" "text", "p_client_id" "uuid", "p_new_client" "jsonb", "p_owner_user_id" "uuid", "p_location" "text", "p_due_date" "date", "p_estimated_value" numeric, "p_notes" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_opportunity_workspace_controlled_v1"("p_organization_id" "uuid", "p_creation_request_id" "uuid", "p_name" "text", "p_client_id" "uuid", "p_new_client" "jsonb", "p_owner_user_id" "uuid", "p_location" "text", "p_due_date" "date", "p_estimated_value" numeric, "p_notes" "text") IS 'Stage 7 trusted creation entry point: exact active organization override, then effective environment default, otherwise fail closed.';



CREATE OR REPLACE FUNCTION "public"."create_opportunity_workspace_v1"("p_organization_id" "uuid", "p_creation_request_id" "uuid", "p_strategy" "text", "p_name" "text", "p_client_id" "uuid" DEFAULT NULL::"uuid", "p_new_client" "jsonb" DEFAULT NULL::"jsonb", "p_owner_user_id" "uuid" DEFAULT NULL::"uuid", "p_location" "text" DEFAULT 'Unspecified'::"text", "p_due_date" "date" DEFAULT NULL::"date", "p_estimated_value" numeric DEFAULT 0, "p_notes" "text" DEFAULT ''::"text") RETURNS TABLE("opportunity_id" "uuid", "opportunity_slug" "text", "workspace_project_id" "uuid", "workspace_project_slug" "text", "lifecycle_id" "uuid", "records_created" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
declare
  actor_user_id uuid := auth.uid();
  rollout_row public.opportunity_lifecycle_rollout_controls%rowtype;
  lifecycle_row public.opportunity_lifecycles%rowtype;
  opportunity_row public.organization_opportunities%rowtype;
  workspace_row public.organization_projects%rowtype;
  resolved_client_id uuid;
  resolved_owner_user_id uuid;
  opportunity_base_slug text;
  opportunity_candidate_slug text;
  workspace_base_slug text;
  workspace_candidate_slug text;
  slug_suffix integer;
  new_client_name text;
  new_client_company_name text;
begin
  if actor_user_id is null then
    raise exception 'Authentication is required'
      using errcode = '42501';
  end if;

  if not public.has_org_permission(
    p_organization_id,
    'leads.opportunities.write'
  ) then
    raise exception 'Not authorized for this organization'
      using errcode = '42501';
  end if;

  if p_creation_request_id is null then
    raise exception 'Creation request ID is required'
      using errcode = 'TS422';
  end if;

  if p_strategy not in (
    'legacy_two_project_v1',
    'promote_workspace_v1'
  ) then
    raise exception 'Unsupported Opportunity lifecycle strategy'
      using errcode = 'TS422';
  end if;

  if not public.is_opportunity_lifecycle_strategy_authorized_v1(
    p_organization_id,
    p_strategy,
    p_strategy = 'promote_workspace_v1'
  ) then
    raise exception 'Opportunity lifecycle creation is not enabled'
      using errcode = 'TS409';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended(
      p_organization_id::text
      || ':opportunity-creation-request:'
      || p_creation_request_id::text,
      0
    )
  );

  select *
  into lifecycle_row
  from public.opportunity_lifecycles lifecycle
  where lifecycle.organization_id = p_organization_id
    and lifecycle.creation_request_id = p_creation_request_id;

  if found then
    if lifecycle_row.strategy <> p_strategy then
      raise exception 'Creation request is already bound to another strategy'
        using errcode = 'TS409';
    end if;

    select *
    into opportunity_row
    from public.organization_opportunities opportunity
    where opportunity.id = lifecycle_row.opportunity_id
      and opportunity.organization_id = p_organization_id;

    select *
    into workspace_row
    from public.organization_projects project
    where project.id = lifecycle_row.original_workspace_project_id
      and project.organization_id = p_organization_id;

    if opportunity_row.id is null
      or workspace_row.id is null
      or opportunity_row.workspace_project_id is distinct from workspace_row.id
      or workspace_row.source_opportunity_id is distinct from opportunity_row.id
    then
      raise exception 'Creation request lifecycle is inconsistent'
        using errcode = 'TS409';
    end if;

    return query
    select
      opportunity_row.id,
      opportunity_row.slug,
      workspace_row.id,
      workspace_row.slug,
      lifecycle_row.id,
      false;
    return;
  end if;

  if nullif(btrim(p_name), '') is null then
    raise exception 'Opportunity name is required'
      using errcode = 'TS422';
  end if;

  if p_client_id is not null and p_new_client is not null then
    raise exception 'Choose either an existing client or a new client'
      using errcode = 'TS422';
  end if;

  if p_client_id is null and p_new_client is null then
    raise exception 'A client is required'
      using errcode = 'TS422';
  end if;

  if p_client_id is not null then
    select client.id
    into resolved_client_id
    from public.organization_clients client
    where client.id = p_client_id
      and client.organization_id = p_organization_id;

    if resolved_client_id is null then
      raise exception 'Client not found for organization'
        using errcode = 'TS422';
    end if;
  else
    if jsonb_typeof(p_new_client) <> 'object' then
      raise exception 'New client must be a JSON object'
        using errcode = 'TS422';
    end if;

    new_client_name := nullif(btrim(p_new_client ->> 'name'), '');
    new_client_company_name :=
      nullif(btrim(p_new_client ->> 'company_name'), '');

    if new_client_name is null or new_client_company_name is null then
      raise exception 'New client name and company name are required'
        using errcode = 'TS422';
    end if;

    insert into public.organization_clients (
      organization_id,
      created_by,
      name,
      company_name,
      email,
      phone
    )
    values (
      p_organization_id,
      actor_user_id,
      new_client_name,
      new_client_company_name,
      nullif(btrim(p_new_client ->> 'email'), ''),
      nullif(btrim(p_new_client ->> 'phone'), '')
    )
    returning id into resolved_client_id;
  end if;

  resolved_owner_user_id := coalesce(p_owner_user_id, actor_user_id);
  if not exists (
    select 1
    from public.organization_members member
    where member.organization_id = p_organization_id
      and member.user_id = resolved_owner_user_id
  ) then
    raise exception 'Opportunity owner is not a member of the organization'
      using errcode = 'TS422';
  end if;

  opportunity_base_slug := regexp_replace(
    regexp_replace(lower(btrim(p_name)), '[^a-z0-9]+', '-', 'g'),
    '(^-+|-+$)',
    '',
    'g'
  );
  opportunity_base_slug :=
    coalesce(nullif(opportunity_base_slug, ''), 'opportunity');

  perform pg_advisory_xact_lock(
    hashtextextended(
      p_organization_id::text || ':opportunity-workspace-slugs',
      0
    )
  );

  opportunity_candidate_slug := opportunity_base_slug;
  slug_suffix := 2;
  while exists (
    select 1
    from public.organization_opportunities opportunity
    where opportunity.organization_id = p_organization_id
      and lower(opportunity.slug) = lower(opportunity_candidate_slug)
  ) loop
    opportunity_candidate_slug :=
      opportunity_base_slug || '-' || slug_suffix::text;
    slug_suffix := slug_suffix + 1;
  end loop;

  workspace_base_slug := opportunity_candidate_slug || '-tender';
  workspace_candidate_slug := workspace_base_slug;
  slug_suffix := 2;
  while exists (
    select 1
    from public.organization_projects project
    where project.organization_id = p_organization_id
      and lower(project.slug) = lower(workspace_candidate_slug)
  ) loop
    workspace_candidate_slug :=
      workspace_base_slug || '-' || slug_suffix::text;
    slug_suffix := slug_suffix + 1;
  end loop;

  insert into public.organization_opportunities (
    organization_id,
    created_by,
    owner_user_id,
    client_id,
    name,
    slug,
    stage,
    location,
    due_date,
    estimated_value,
    notes
  )
  values (
    p_organization_id,
    actor_user_id,
    resolved_owner_user_id,
    resolved_client_id,
    btrim(p_name),
    opportunity_candidate_slug,
    'New',
    coalesce(nullif(btrim(p_location), ''), 'Unspecified'),
    p_due_date,
    coalesce(p_estimated_value, 0),
    coalesce(p_notes, '')
  )
  returning * into opportunity_row;

  insert into public.organization_projects (
    organization_id,
    created_by,
    client_id,
    name,
    slug,
    stage,
    location,
    cover_image_url,
    source_opportunity_id
  )
  values (
    p_organization_id,
    actor_user_id,
    resolved_client_id,
    btrim(p_name) || ' Tender Workspace',
    workspace_candidate_slug,
    'Pricing',
    coalesce(nullif(btrim(p_location), ''), 'Unspecified'),
    null,
    opportunity_row.id
  )
  returning * into workspace_row;

  update public.organization_opportunities opportunity
  set workspace_project_id = workspace_row.id
  where opportunity.id = opportunity_row.id
    and opportunity.organization_id = p_organization_id;

  insert into public.opportunity_lifecycles (
    organization_id,
    opportunity_id,
    original_workspace_project_id,
    strategy,
    strategy_version,
    creation_request_id,
    created_by,
    metadata
  )
  values (
    p_organization_id,
    opportunity_row.id,
    workspace_row.id,
    p_strategy,
    1,
    p_creation_request_id,
    actor_user_id,
    jsonb_build_object('creation_function', 'create_opportunity_workspace_v1')
  )
  returning * into lifecycle_row;

  return query
  select
    opportunity_row.id,
    opportunity_row.slug,
    workspace_row.id,
    workspace_row.slug,
    lifecycle_row.id,
    true;
end;
$_$;


ALTER FUNCTION "public"."create_opportunity_workspace_v1"("p_organization_id" "uuid", "p_creation_request_id" "uuid", "p_strategy" "text", "p_name" "text", "p_client_id" "uuid", "p_new_client" "jsonb", "p_owner_user_id" "uuid", "p_location" "text", "p_due_date" "date", "p_estimated_value" numeric, "p_notes" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_opportunity_workspace_v1"("p_organization_id" "uuid", "p_creation_request_id" "uuid", "p_strategy" "text", "p_name" "text", "p_client_id" "uuid", "p_new_client" "jsonb", "p_owner_user_id" "uuid", "p_location" "text", "p_due_date" "date", "p_estimated_value" numeric, "p_notes" "text") IS 'Dormant atomic and idempotent Opportunity plus permanent workspace creation. Requires an explicit rollout-control row.';



CREATE OR REPLACE FUNCTION "public"."create_opportunity_workspace_with_tender_clients_v1"("p_organization_id" "uuid", "p_creation_request_id" "uuid", "p_name" "text", "p_client_id" "uuid" DEFAULT NULL::"uuid", "p_new_client" "jsonb" DEFAULT NULL::"jsonb", "p_owner_user_id" "uuid" DEFAULT NULL::"uuid", "p_location" "text" DEFAULT 'Unspecified'::"text", "p_due_date" "date" DEFAULT NULL::"date", "p_estimated_value" numeric DEFAULT 0, "p_notes" "text" DEFAULT ''::"text", "p_tender_client_ids" "uuid"[] DEFAULT '{}'::"uuid"[]) RETURNS TABLE("opportunity_id" "uuid", "opportunity_slug" "text", "workspace_project_id" "uuid", "workspace_project_slug" "text", "lifecycle_id" "uuid", "records_created" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  created record;
  resolved_primary_client_id uuid;
  resolved_client_ids uuid[];
begin
  select * into created
  from public.create_opportunity_workspace_controlled_v1(
    p_organization_id, p_creation_request_id, p_name, p_client_id, p_new_client,
    p_owner_user_id, p_location, p_due_date, p_estimated_value, p_notes
  );

  select opportunity.client_id into resolved_primary_client_id
  from public.organization_opportunities opportunity
  where opportunity.organization_id = p_organization_id
    and opportunity.id = created.opportunity_id;

  select array_agg(distinct value) into resolved_client_ids
  from unnest(array_append(coalesce(p_tender_client_ids, '{}'::uuid[]), resolved_primary_client_id)) value
  where value is not null;

  perform public.sync_opportunity_tender_clients_v1(
    p_organization_id, created.opportunity_id, resolved_client_ids, resolved_primary_client_id
  );

  return query select created.opportunity_id, created.opportunity_slug,
    created.workspace_project_id, created.workspace_project_slug,
    created.lifecycle_id, created.records_created;
end;
$$;


ALTER FUNCTION "public"."create_opportunity_workspace_with_tender_clients_v1"("p_organization_id" "uuid", "p_creation_request_id" "uuid", "p_name" "text", "p_client_id" "uuid", "p_new_client" "jsonb", "p_owner_user_id" "uuid", "p_location" "text", "p_due_date" "date", "p_estimated_value" numeric, "p_notes" "text", "p_tender_client_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_project_claim_draft"("p_organization_id" "uuid", "p_project_id" "uuid", "p_title" "text" DEFAULT 'New Claim'::"text") RETURNS TABLE("id" "uuid", "claim_number" "text", "claim_title" "text", "claim_type" "text", "status" "text", "claim_date" "date", "due_date" "date", "period_start" "date", "period_end" "date", "percent_complete" numeric, "paid_amount" numeric, "retention_method" "text", "retention_scale_bands" "jsonb", "retention_percent" numeric, "retention_withheld_amount" numeric, "retention_released_amount" numeric, "retention_held_to_date" numeric, "retention_released_to_date" numeric, "retention_balance" numeric, "net_claim_excl_gst" numeric, "gst_amount" numeric, "total_payable" numeric, "notes" "text", "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  created_row public.project_claims%rowtype;
  resolved_title text;
  resolved_quote_value numeric := 0;
  resolved_approved_variations numeric := 0;
  resolved_previous_claims_total numeric := 0;
  resolved_revised_contract_value numeric := 0;
  resolved_retention_method text := 'flat';
  resolved_retention_scale_bands jsonb := null;
  resolved_retention_percent numeric := 10;
  cost_item_revision_key text;
begin
  if auth.uid() is null then
    raise exception 'Authentication is required';
  end if;

  if not public.is_member_of_organization(p_organization_id) then
    raise exception 'Not authorized for this organization';
  end if;

  if not exists (
    select 1
    from public.organization_projects p
    where p.id = p_project_id
      and p.organization_id = p_organization_id
  ) then
    raise exception 'Project not found for organization';
  end if;

  resolved_title := coalesce(nullif(btrim(p_title), ''), 'New Claim');

  resolved_quote_value := public.get_project_claim_base_quote_total(p_organization_id, p_project_id);
  resolved_approved_variations := public.get_project_claim_approved_variations_total(p_organization_id, p_project_id);

  resolved_previous_claims_total := (
    select coalesce(sum(c.claim_amount), 0)
    from public.project_claims c
    where c.organization_id = p_organization_id
      and c.project_id = p_project_id
      and c.status <> 'Cancelled'
  );

  resolved_retention_method := coalesce((
    select case
      when coalesce(c.retention_method, 'flat') = 'sliding_scale' then 'sliding_scale'
      else 'flat'
    end
    from public.project_claims c
    where c.organization_id = p_organization_id
      and c.project_id = p_project_id
      and c.status <> 'Cancelled'
    order by
      c.updated_at desc,
      c.id desc
    limit 1
  ), 'flat');

  resolved_retention_scale_bands := case
    when resolved_retention_method = 'sliding_scale' then (
      select c.retention_scale_bands
      from public.project_claims c
      where c.organization_id = p_organization_id
        and c.project_id = p_project_id
        and c.status <> 'Cancelled'
      order by
        c.updated_at desc,
        c.id desc
      limit 1
    )
    else null
  end;

  resolved_retention_percent := coalesce((
    select greatest(0, least(100, coalesce(nullif(c.retention_percent, 0), 10)))
    from public.project_claims c
    where c.organization_id = p_organization_id
      and c.project_id = p_project_id
      and c.status <> 'Cancelled'
    order by
      c.updated_at desc,
      c.id desc
    limit 1
  ), 10);

  resolved_revised_contract_value := resolved_quote_value + resolved_approved_variations;

  insert into public.project_claims (
    organization_id,
    project_id,
    created_by,
    claim_number,
    claim_title,
    claim_type,
    status,
    claim_date,
    due_date,
    period_start,
    period_end,
    percent_complete,
    claim_amount,
    paid_amount,
    linked_quote_value,
    linked_approved_variations,
    previous_claims_total,
    revised_contract_value,
    retention_method,
    retention_scale_bands,
    retention_percent,
    retention_withheld_amount,
    retention_released_amount,
    retention_held_to_date,
    retention_released_to_date,
    retention_balance,
    net_claim_excl_gst,
    gst_amount,
    total_payable,
    notes
  ) values (
    p_organization_id,
    p_project_id,
    auth.uid(),
    public.generate_project_claim_number(p_organization_id, p_project_id),
    resolved_title,
    'Progress',
    'Draft',
    current_date,
    current_date + 7,
    current_date,
    current_date + 7,
    0,
    0,
    0,
    round(resolved_quote_value, 2),
    round(resolved_approved_variations, 2),
    round(resolved_previous_claims_total, 2),
    round(resolved_revised_contract_value, 2),
    resolved_retention_method,
    case
      when resolved_retention_method = 'sliding_scale' then resolved_retention_scale_bands
      else null
    end,
    round(coalesce(resolved_retention_percent, 10), 3),
    0,
    0,
    0,
    0,
    0,
    0,
    0,
    0,
    ''
  )
  returning * into created_row;

  perform public.sync_project_claim_line_items(
    p_organization_id,
    p_project_id,
    created_row.id,
    null,
    0
  );

  cost_item_revision_key := public.begin_cost_item_revision('project_claim', created_row.id);
  perform public.supersede_previous_cost_items('project_claim', created_row.id, cost_item_revision_key);
  perform public.upsert_cost_items_for_project_claim(created_row.id, cost_item_revision_key);

  return query
  select
    created_row.id,
    created_row.claim_number,
    created_row.claim_title,
    created_row.claim_type,
    created_row.status,
    created_row.claim_date,
    created_row.due_date,
    created_row.period_start,
    created_row.period_end,
    created_row.percent_complete,
    created_row.paid_amount,
    created_row.retention_method,
    created_row.retention_scale_bands,
    created_row.retention_percent,
    created_row.retention_withheld_amount,
    created_row.retention_released_amount,
    created_row.retention_held_to_date,
    created_row.retention_released_to_date,
    created_row.retention_balance,
    created_row.net_claim_excl_gst,
    created_row.gst_amount,
    created_row.total_payable,
    created_row.notes,
    created_row.updated_at;
end;
$$;


ALTER FUNCTION "public"."create_project_claim_draft"("p_organization_id" "uuid", "p_project_id" "uuid", "p_title" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_project_purchase_order_draft"("p_organization_id" "uuid", "p_project_id" "uuid", "p_title" "text" DEFAULT 'New Purchase Order'::"text", "p_origin" "text" DEFAULT 'Material Supply'::"text") RETURNS TABLE("id" "uuid", "updated_at" timestamp with time zone, "purchase_order_number" "text", "purchase_order_title" "text", "status" "text", "origin" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  created_row public.project_purchase_orders%rowtype;
  resolved_title text;
  resolved_origin text;
begin
  if auth.uid() is null then
    raise exception 'Authentication is required';
  end if;

  if not public.is_member_of_organization(p_organization_id) then
    raise exception 'Not authorized for this organization';
  end if;

  if not exists (
    select 1
    from public.organization_projects p
    where p.id = p_project_id
      and p.organization_id = p_organization_id
  ) then
    raise exception 'Project not found for organization';
  end if;

  resolved_title := coalesce(nullif(btrim(p_title), ''), 'New Purchase Order');
  resolved_origin := case
    when p_origin in ('Material Supply', 'Subcontract Work', 'Plant / Equipment Hire', 'Site Expense', 'Freight / Delivery', 'Variation Order', 'General Purchase', 'Other')
      then p_origin
    else 'Material Supply'
  end;

  insert into public.project_purchase_orders (
    organization_id,
    project_id,
    created_by,
    purchase_order_title,
    purchase_order_number,
    status,
    origin,
    requested_by
  ) values (
    p_organization_id,
    p_project_id,
    auth.uid(),
    resolved_title,
    '',
    'Draft',
    resolved_origin,
    ''
  )
  returning * into created_row;

  return query
  select
    created_row.id,
    created_row.updated_at,
    created_row.purchase_order_number,
    created_row.purchase_order_title,
    created_row.status,
    created_row.origin;
end;
$$;


ALTER FUNCTION "public"."create_project_purchase_order_draft"("p_organization_id" "uuid", "p_project_id" "uuid", "p_title" "text", "p_origin" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_project_qa_from_template_v1"("p_organization_id" "uuid", "p_project_id" "uuid", "p_template_id" "uuid", "p_name" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare source public.qa_templates%rowtype; result_id uuid; s record; f record; o record; new_section uuid; new_field uuid; section_map jsonb := '{}'::jsonb; field_map jsonb := '{}'::jsonb;
begin
  if auth.uid() is null or not public.can_access_qa_project(p_organization_id,p_project_id,'qa.write') or not public.has_org_permission(p_organization_id,'qa.templates.view') then raise exception 'Not authorized' using errcode='42501'; end if;
  select * into source from public.qa_templates where organization_id=p_organization_id and id=p_template_id and status='active';
  if not found then raise exception 'Active QA template not found' using errcode='TS404'; end if;
  insert into public.project_qas(organization_id,project_id,name,description,source_template_id,source_template_name,source_template_version,copied_at,copied_by,created_by,updated_by)
  values(p_organization_id,p_project_id,coalesce(nullif(btrim(p_name),''),source.name),source.description,source.id,source.name,source.definition_version,now(),auth.uid(),auth.uid(),auth.uid()) returning id into result_id;
  for s in select * from public.qa_template_sections where organization_id=p_organization_id and template_id=source.id order by sort_order loop
    new_section := gen_random_uuid(); section_map := section_map || jsonb_build_object(s.id::text,new_section::text);
    insert into public.project_qa_sections(id,organization_id,project_id,project_qa_id,title,description,sort_order) values(new_section,p_organization_id,p_project_id,result_id,s.title,s.description,s.sort_order);
  end loop;
  for f in select * from public.qa_template_fields where organization_id=p_organization_id and template_id=source.id order by section_id,sort_order loop
    new_field := gen_random_uuid(); field_map := field_map || jsonb_build_object(f.id::text,new_field::text);
    insert into public.project_qa_fields(id,organization_id,project_id,project_qa_id,section_id,field_type,label,description,instructions,required,allow_na,requirement,acceptance_criteria,reference_text,photo_required,minimum_photos,file_required,require_comment_on_fail,require_photo_on_fail,create_issue_on_fail,require_rectification_on_fail,block_completion_on_fail,require_supervisor_review_on_fail,ai_review_enabled,ai_review_instruction,include_in_report,configuration,configuration_schema_version,sort_order)
    values(new_field,p_organization_id,p_project_id,result_id,(section_map->>f.section_id::text)::uuid,f.field_type,f.label,f.description,f.instructions,f.required,f.allow_na,f.requirement,f.acceptance_criteria,f.reference_text,f.photo_required,f.minimum_photos,f.file_required,f.require_comment_on_fail,f.require_photo_on_fail,f.create_issue_on_fail,f.require_rectification_on_fail,f.block_completion_on_fail,f.require_supervisor_review_on_fail,f.ai_review_enabled,f.ai_review_instruction,f.include_in_report,f.configuration,f.configuration_schema_version,f.sort_order);
  end loop;
  for o in select * from public.qa_template_field_options where organization_id=p_organization_id and template_id=source.id order by field_id,sort_order loop
    insert into public.project_qa_field_options(organization_id,project_id,project_qa_id,field_id,label,value,sort_order)
    values(p_organization_id,p_project_id,result_id,(field_map->>o.field_id::text)::uuid,o.label,o.value,o.sort_order);
  end loop;
  return result_id;
end; $$;


ALTER FUNCTION "public"."create_project_qa_from_template_v1"("p_organization_id" "uuid", "p_project_id" "uuid", "p_template_id" "uuid", "p_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_project_quote_revision_core_v1"("p_organization_id" "uuid", "p_project_id" "uuid", "p_predecessor_quote_id" "uuid", "p_quote_number" "text") RETURNS TABLE("quote_id" "uuid", "quote_number" "text", "revision_number" integer, "cloned_workbook_count" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  actor_user_id uuid := auth.uid();
  predecessor public.project_quotes%rowtype;
  existing_successor public.project_quotes%rowtype;
  created_quote public.project_quotes%rowtype;
  source_workbook public.opportunity_pricing_worksheets%rowtype;
  source_sheet public.opportunity_pricing_workbook_sheets%rowtype;
  default_source_sheet public.opportunity_pricing_workbook_sheets%rowtype;
  created_workbook public.opportunity_pricing_worksheets%rowtype;
  resolved_quote_id uuid;
  resolved_quote_number text;
  resolved_revision_number integer;
  resolved_workbook_count integer := 0;
  resolved_parent_worksheet_data jsonb;
begin
  if actor_user_id is null then
    raise exception 'Authentication is required' using errcode = '42501';
  end if;
  if not public.has_org_permission(p_organization_id, 'quotes.write') then
    raise exception 'Not authorized for this organization' using errcode = '42501';
  end if;

  select * into predecessor
  from public.project_quotes quote
  where quote.organization_id = p_organization_id
    and quote.project_id = p_project_id
    and quote.id = p_predecessor_quote_id
  for update;
  if not found then
    raise exception 'Predecessor quote was not found for this Project' using errcode = 'TS422';
  end if;

  select * into existing_successor
  from public.project_quotes quote
  where quote.organization_id = p_organization_id
    and quote.predecessor_quote_id = p_predecessor_quote_id;
  if found then
    return query select existing_successor.id, existing_successor.quote_number,
      existing_successor.revision_number,
      (select count(*)::integer from public.opportunity_pricing_worksheets workbook
       where workbook.organization_id = p_organization_id and workbook.quote_id = existing_successor.id);
    return;
  end if;

  resolved_revision_number := predecessor.revision_number + 1;
  resolved_quote_id := md5(p_predecessor_quote_id::text || ':revision:' || resolved_revision_number::text)::uuid;
  resolved_quote_number := coalesce(nullif(btrim(p_quote_number), ''),
    predecessor.quote_number || '-R' || resolved_revision_number::text);

  if exists (
    select 1 from public.project_quotes quote
    where quote.organization_id = p_organization_id
      and quote.project_id = p_project_id
      and quote.quote_number = resolved_quote_number
  ) then
    raise exception 'The requested quote revision number already exists' using errcode = 'TS409';
  end if;

  insert into public.project_quotes (
    id, organization_id, project_id, originating_opportunity_id, source_opportunity_id,
    source_opportunity_quote_id, source_opportunity_quote_number, created_by,
    quote_title, quote_number, client_name, company_name, contact_person, client_email,
    client_phone, site_address, project_name, quote_date, expiry_date, status,
    optional_items_notes, scope_exclusions, assumptions, scope_notes, subtotal,
    optional_subtotal, margin_percent, margin_amount, discount_amount, contingency_amount,
    gst_percent, gst_amount, total_quote_price, validity_period, payment_terms,
    retention_percent_default, lead_time, terms_inclusions, terms_exclusions,
    clarifications, acceptance_notes, predecessor_quote_id, revision_number,
    revision_kind, revision_created_at, revision_created_by, pricing_basis_status
  ) values (
    resolved_quote_id, predecessor.organization_id, predecessor.project_id,
    predecessor.originating_opportunity_id, predecessor.source_opportunity_id,
    predecessor.source_opportunity_quote_id, predecessor.source_opportunity_quote_number,
    actor_user_id, predecessor.quote_title, resolved_quote_number, predecessor.client_name,
    predecessor.company_name, predecessor.contact_person, predecessor.client_email,
    predecessor.client_phone, predecessor.site_address, predecessor.project_name,
    current_date, predecessor.expiry_date, 'Draft', predecessor.optional_items_notes,
    predecessor.scope_exclusions, predecessor.assumptions, predecessor.scope_notes,
    predecessor.subtotal, predecessor.optional_subtotal, predecessor.margin_percent,
    predecessor.margin_amount, predecessor.discount_amount, predecessor.contingency_amount,
    predecessor.gst_percent, predecessor.gst_amount, predecessor.total_quote_price,
    predecessor.validity_period, predecessor.payment_terms,
    predecessor.retention_percent_default, predecessor.lead_time,
    predecessor.terms_inclusions, predecessor.terms_exclusions,
    predecessor.clarifications, predecessor.acceptance_notes, predecessor.id,
    resolved_revision_number, 'project_working', timezone('utc', now()), actor_user_id,
    'unpublished'
  ) returning * into created_quote;

  insert into public.project_quote_line_items (
    id, organization_id, project_id, quote_id, section, description, quantity, unit,
    rate, total, is_optional, sort_order, source_opportunity_quote_id,
    source_opportunity_quote_line_item_id, source_opportunity_quote_number, pricing_source_kind
  )
  select md5(created_quote.id::text || ':line:' || line.id::text)::uuid,
    line.organization_id, line.project_id, created_quote.id, line.section, line.description,
    line.quantity, line.unit, line.rate, line.total, line.is_optional, line.sort_order,
    line.source_opportunity_quote_id, line.source_opportunity_quote_line_item_id,
    line.source_opportunity_quote_number, line.pricing_source_kind
  from public.project_quote_line_items line
  where line.organization_id = p_organization_id and line.quote_id = predecessor.id;

  insert into public.commercial_item_document_links (
    id, organization_id, commercial_item_id, document_kind, document_id,
    document_line_id, link_role, snapshot_at_link_json, created_by, created_at
  )
  select md5(created_quote.id::text || ':link:' || link.id::text)::uuid,
    link.organization_id, link.commercial_item_id, link.document_kind, created_quote.id,
    md5(created_quote.id::text || ':line:' || link.document_line_id::text)::uuid,
    link.link_role, link.snapshot_at_link_json, actor_user_id, timezone('utc', now())
  from public.commercial_item_document_links link
  where link.organization_id = p_organization_id
    and link.document_kind = 'quote_line' and link.document_id = predecessor.id;

  for source_workbook in
    select * from public.opportunity_pricing_worksheets workbook
    where workbook.organization_id = p_organization_id
      and workbook.quote_id = predecessor.id and workbook.variation_id is null
      and workbook.archived_at is null
    order by workbook.sort_order, workbook.created_at
  loop
    select * into default_source_sheet
    from public.opportunity_pricing_workbook_sheets sheet
    where sheet.organization_id = p_organization_id and sheet.workbook_id = source_workbook.id
    order by sheet.is_default desc, sheet.sheet_order, sheet.created_at limit 1;

    resolved_parent_worksheet_data := public.regenerate_worksheet_material_binding_ids(
      coalesce(default_source_sheet.worksheet_data, source_workbook.worksheet_data)
    );
    insert into public.opportunity_pricing_worksheets (
      id, organization_id, opportunity_id, project_id, quote_id, variation_id,
      name, trade_package, sort_order, archived_at, last_active_sheet_id,
      worksheet_data, pricing_summary, extracted_pricing_data, version,
      created_by, updated_by, source_workbook_id, source_workbook_version,
      source_award_manifest_id, source_quote_id, clone_kind
    ) values (
      md5(created_quote.id::text || ':workbook:' || source_workbook.id::text)::uuid,
      p_organization_id, source_workbook.opportunity_id, p_project_id, created_quote.id, null,
      source_workbook.name, source_workbook.trade_package, source_workbook.sort_order, null,
      case when source_workbook.last_active_sheet_id is null then null
        else md5(created_quote.id::text || ':sheet:' || source_workbook.last_active_sheet_id::text)::uuid end,
      resolved_parent_worksheet_data,
      coalesce(default_source_sheet.pricing_summary, source_workbook.pricing_summary),
      coalesce(default_source_sheet.extracted_pricing_data, source_workbook.extracted_pricing_data),
      greatest(coalesce(default_source_sheet.version, source_workbook.version, 1), 1),
      actor_user_id, actor_user_id, source_workbook.id, source_workbook.version,
      source_workbook.source_award_manifest_id, predecessor.id, 'quote_revision'
    ) returning * into created_workbook;

    for source_sheet in
      select * from public.opportunity_pricing_workbook_sheets sheet
      where sheet.organization_id = p_organization_id and sheet.workbook_id = source_workbook.id
      order by sheet.sheet_order, sheet.created_at
    loop
      insert into public.opportunity_pricing_workbook_sheets (
        id, workbook_id, organization_id, opportunity_id, name, sheet_order,
        is_default, worksheet_data, pricing_summary, extracted_pricing_data,
        version, created_by, updated_by
      ) values (
        md5(created_quote.id::text || ':sheet:' || source_sheet.id::text)::uuid,
        created_workbook.id, p_organization_id, source_workbook.opportunity_id,
        source_sheet.name, source_sheet.sheet_order, source_sheet.is_default,
        case when source_sheet.id = default_source_sheet.id then resolved_parent_worksheet_data
          else public.regenerate_worksheet_material_binding_ids(source_sheet.worksheet_data) end,
        source_sheet.pricing_summary, source_sheet.extracted_pricing_data,
        source_sheet.version, actor_user_id, actor_user_id
      );
    end loop;
    resolved_workbook_count := resolved_workbook_count + 1;
  end loop;

  return query select created_quote.id, created_quote.quote_number,
    created_quote.revision_number, resolved_workbook_count;
end;
$$;


ALTER FUNCTION "public"."create_project_quote_revision_core_v1"("p_organization_id" "uuid", "p_project_id" "uuid", "p_predecessor_quote_id" "uuid", "p_quote_number" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_project_quote_revision_v1"("p_organization_id" "uuid", "p_project_id" "uuid", "p_predecessor_quote_id" "uuid", "p_quote_number" "text") RETURNS TABLE("quote_id" "uuid", "quote_number" "text", "revision_number" integer, "cloned_workbook_count" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
declare
  actor_user_id uuid := auth.uid();
  created_revision record;
  legacy_evidence record;
  source_workbook public.opportunity_pricing_worksheets%rowtype;
  source_sheet public.opportunity_pricing_workbook_sheets%rowtype;
  default_source_sheet public.opportunity_pricing_workbook_sheets%rowtype;
  destination_workbook_id uuid;
  destination_sheet_id uuid;
  parent_worksheet jsonb;
  next_quote_number text;
  project_suffix integer;
begin
  select * into created_revision
  from public.create_project_quote_revision_core_v1(
    p_organization_id, p_project_id, p_predecessor_quote_id, p_quote_number
  );

  select * into legacy_evidence
  from public.classify_legacy_automatic_project_quote_draft_v1(
    p_organization_id, created_revision.quote_id
  );

  if found
    and legacy_evidence.manifest_linked
    and legacy_evidence.deterministic_id_match
    and legacy_evidence.expected_predecessor
    and legacy_evidence.expected_revision_kind
    and legacy_evidence.expected_status
    and legacy_evidence.quote_values_match
    and legacy_evidence.line_values_match
    and legacy_evidence.workbook_untouched
  then
    project_suffix := substring(created_revision.quote_number from '-P([0-9]+)$')::integer;
    if project_suffix is null then
      raise exception 'Legacy automatic Draft has an unsupported quote number'
        using errcode = 'TS409';
    end if;
    next_quote_number := regexp_replace(created_revision.quote_number, '-P[0-9]+$', '')
      || '-P' || (project_suffix + 1)::text;

    select * into created_revision
    from public.create_project_quote_revision_core_v1(
      p_organization_id, p_project_id, created_revision.quote_id, next_quote_number
    );
  end if;

  for source_workbook in
    select * from public.opportunity_pricing_worksheets workbook
    where workbook.organization_id = p_organization_id
      and workbook.project_id = p_project_id
      and workbook.quote_id is null
      and workbook.variation_id is null
      and workbook.clone_kind = 'project_workspace'
      and workbook.archived_at is null
    order by workbook.sort_order, workbook.created_at
  loop
    if exists (
      select 1 from public.opportunity_pricing_worksheets clone
      where clone.organization_id = p_organization_id
        and clone.quote_id = created_revision.quote_id
        and clone.source_workbook_id = source_workbook.id
        and clone.clone_kind = 'quote_revision'
    ) then
      continue;
    end if;

    destination_workbook_id := md5(created_revision.quote_id::text || ':workspace:' || source_workbook.id::text)::uuid;
    select * into default_source_sheet
    from public.opportunity_pricing_workbook_sheets sheet
    where sheet.organization_id = p_organization_id and sheet.workbook_id = source_workbook.id
    order by sheet.is_default desc, sheet.sheet_order, sheet.created_at limit 1;

    parent_worksheet := public.regenerate_worksheet_material_binding_ids(
      coalesce(default_source_sheet.worksheet_data, source_workbook.worksheet_data)
    );

    insert into public.opportunity_pricing_worksheets (
      id, organization_id, opportunity_id, project_id, quote_id, variation_id,
      name, trade_package, sort_order, archived_at, last_active_sheet_id,
      worksheet_data, pricing_summary, extracted_pricing_data, version,
      created_by, updated_by, source_workbook_id, source_workbook_version,
      source_award_manifest_id, source_quote_id, clone_kind
    ) values (
      destination_workbook_id, p_organization_id, source_workbook.opportunity_id,
      p_project_id, created_revision.quote_id, null, source_workbook.name,
      source_workbook.trade_package, source_workbook.sort_order, null,
      case when source_workbook.last_active_sheet_id is null then null
        else md5(created_revision.quote_id::text || ':workspace-sheet:' || source_workbook.last_active_sheet_id::text)::uuid end,
      parent_worksheet,
      coalesce(default_source_sheet.pricing_summary, source_workbook.pricing_summary),
      coalesce(default_source_sheet.extracted_pricing_data, source_workbook.extracted_pricing_data),
      greatest(coalesce(default_source_sheet.version, source_workbook.version, 1), 1),
      actor_user_id, actor_user_id, source_workbook.id, source_workbook.version,
      source_workbook.source_award_manifest_id, p_predecessor_quote_id, 'quote_revision'
    ) on conflict (id) do nothing;

    for source_sheet in
      select * from public.opportunity_pricing_workbook_sheets sheet
      where sheet.organization_id = p_organization_id and sheet.workbook_id = source_workbook.id
      order by sheet.sheet_order, sheet.created_at
    loop
      destination_sheet_id := md5(created_revision.quote_id::text || ':workspace-sheet:' || source_sheet.id::text)::uuid;
      insert into public.opportunity_pricing_workbook_sheets (
        id, workbook_id, organization_id, opportunity_id, name, sheet_order,
        is_default, worksheet_data, pricing_summary, extracted_pricing_data,
        version, created_by, updated_by
      ) values (
        destination_sheet_id, destination_workbook_id, p_organization_id,
        source_workbook.opportunity_id, source_sheet.name, source_sheet.sheet_order,
        source_sheet.is_default,
        case when source_sheet.id = default_source_sheet.id then parent_worksheet
          else public.regenerate_worksheet_material_binding_ids(source_sheet.worksheet_data) end,
        source_sheet.pricing_summary, source_sheet.extracted_pricing_data,
        source_sheet.version, actor_user_id, actor_user_id
      ) on conflict (id) do nothing;
    end loop;
  end loop;

  return query select created_revision.quote_id, created_revision.quote_number,
    created_revision.revision_number,
    (select count(*)::integer from public.opportunity_pricing_worksheets workbook
      where workbook.organization_id = p_organization_id
        and workbook.quote_id = created_revision.quote_id);
end;
$_$;


ALTER FUNCTION "public"."create_project_quote_revision_v1"("p_organization_id" "uuid", "p_project_id" "uuid", "p_predecessor_quote_id" "uuid", "p_quote_number" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_project_variation_draft"("p_organization_id" "uuid", "p_project_id" "uuid", "p_title" "text" DEFAULT 'New Variation'::"text") RETURNS TABLE("id" "uuid", "updated_at" timestamp with time zone, "variation_number" "text", "variation_title" "text", "status" "text", "origin" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  created_row public.project_variations%rowtype;
  resolved_title text;
begin
  if auth.uid() is null then
    raise exception 'Authentication is required';
  end if;

  if not public.has_org_permission(p_organization_id, 'variations.write') then
    raise exception 'Not authorized for this organization';
  end if;

  if not exists (
    select 1
    from public.organization_projects p
    where p.id = p_project_id
      and p.organization_id = p_organization_id
  ) then
    raise exception 'Project not found for organization';
  end if;

  resolved_title := coalesce(nullif(btrim(p_title), ''), 'New Variation');

  insert into public.project_variations (
    organization_id,
    project_id,
    created_by,
    variation_title,
    variation_number,
    status,
    origin,
    source_reference,
    requested_by
  ) values (
    p_organization_id,
    p_project_id,
    auth.uid(),
    resolved_title,
    '',
    'Draft',
    'Unknown',
    '',
    ''
  )
  returning * into created_row;

  return query
  select
    created_row.id,
    created_row.updated_at,
    created_row.variation_number,
    created_row.variation_title,
    created_row.status,
    created_row.origin;
end;
$$;


ALTER FUNCTION "public"."create_project_variation_draft"("p_organization_id" "uuid", "p_project_id" "uuid", "p_title" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_qa_template_v1"("p_organization_id" "uuid", "p_name" "text", "p_description" "text" DEFAULT ''::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare result_id uuid;
begin
  if auth.uid() is null or not public.has_org_permission(p_organization_id,'qa.templates.write') then raise exception 'Not authorized' using errcode='42501'; end if;
  if char_length(btrim(coalesce(p_name,''))) not between 1 and 160 then raise exception 'Template name is required' using errcode='TS422'; end if;
  insert into public.qa_templates(organization_id,name,description,created_by,updated_by)
  values(p_organization_id,btrim(p_name),coalesce(p_description,''),auth.uid(),auth.uid()) returning id into result_id;
  return result_id;
end; $$;


ALTER FUNCTION "public"."create_qa_template_v1"("p_organization_id" "uuid", "p_name" "text", "p_description" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_retention_claim_draft"("p_project_id" "uuid", "p_title" "text" DEFAULT 'New Retention Claim'::"text", "p_reference" "text" DEFAULT NULL::"text", "p_issue_date" "date" DEFAULT NULL::"date", "p_due_date" "date" DEFAULT NULL::"date", "p_correlation_id" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private'
    AS $$
declare
  v_context jsonb;
  v_master public.retention_claims%rowtype;
begin
  v_context := private.retention_claim_operation_context(
    p_project_id,
    'retention.claims.create',
    true
  );
  if not coalesce((v_context->>'succeeded')::boolean, false) then
    return v_context;
  end if;
  select claim.* into v_master
  from public.retention_claims claim
  where claim.organization_id = (v_context->>'organizationId')::uuid
    and claim.project_id = p_project_id
    and claim.master_role = 'master_retention_claim'
  limit 1;
  if v_master.id is not null then
    return jsonb_build_object(
      'succeeded', true,
      'errorCode', null,
      'reused', true,
      'masterRetentionClaim', true,
      'claim', private.retention_claim_header_json(v_master.id)
    );
  end if;
  return jsonb_build_object(
    'succeeded', false,
    'errorCode', 'master_requires_submitted_payment_claim'
  );
end;
$$;


ALTER FUNCTION "public"."create_retention_claim_draft"("p_project_id" "uuid", "p_title" "text", "p_reference" "text", "p_issue_date" "date", "p_due_date" "date", "p_correlation_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_retention_legacy_reconciliation_case"("p_project_id" "uuid", "p_correlation_id" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare ctx jsonb; source_state jsonb; current_case public.retention_legacy_reconciliation_cases%rowtype;
  new_case public.retention_legacy_reconciliation_cases%rowtype; next_sequence integer;
  source_count integer; new_case_id uuid:=gen_random_uuid();
begin
  ctx:=private.retention_phase6_context(
    p_project_id,'retention.legacy.reconcile',true);
  if not coalesce((ctx->>'succeeded')::boolean,false) then return ctx; end if;
  source_state:=private.retention_legacy_source_state(p_project_id);
  if not coalesce((source_state->>'legacyReconciliationRequired')::boolean,false) then
    return jsonb_build_object('succeeded',false,'errorCode','legacy_reconciliation_not_required');
  end if;
  if round(coalesce((source_state->>'totalLegacyRetentionReleased')::numeric,0),2)<=0 then
    return jsonb_build_object('succeeded',false,'errorCode','legacy_release_not_found');
  end if;
  perform pg_advisory_xact_lock(hashtextextended(
    p_project_id::text||':legacy_retention_reconciliation',6));
  select * into current_case from public.retention_legacy_reconciliation_cases c
  where c.project_id=p_project_id and c.status in ('draft','in_review','approved')
  for update;
  if found and current_case.position_state_hash=source_state->>'stateHash'
    and current_case.source_fingerprint=source_state->>'sourceFingerprint' then
    return jsonb_build_object('succeeded',true,'errorCode',null,
      'created',false,'case',private.retention_legacy_case_json(current_case.id));
  end if;
  if found and current_case.status in ('draft','in_review') then
    return jsonb_build_object('succeeded',false,'errorCode','stale_reconciliation_case',
      'case',private.retention_legacy_case_json(current_case.id),
      'currentPositionStateHash',source_state->>'stateHash',
      'currentSourceFingerprint',source_state->>'sourceFingerprint');
  end if;
  select coalesce(max(c.case_sequence),0)+1 into next_sequence
  from public.retention_legacy_reconciliation_cases c where c.project_id=p_project_id;
  perform set_config('app.retention_phase6_internal_write','true',true);
  if current_case.id is not null then
    update public.retention_legacy_reconciliation_cases set
      status='superseded',superseded_by_case_id=new_case_id,
      superseded_at=now(),revision=revision+1,updated_at=now()
    where id=current_case.id;
  end if;
  insert into public.retention_legacy_reconciliation_cases(
    id,organization_id,project_id,case_sequence,position_state_hash,source_fingerprint,
    total_legacy_released,source_count,supersedes_case_id,created_by
  ) values(
    new_case_id,(ctx->>'organizationId')::uuid,p_project_id,next_sequence,
    source_state->>'stateHash',source_state->>'sourceFingerprint',
    round((source_state->>'totalLegacyRetentionReleased')::numeric,2),
    jsonb_array_length(source_state->'legacyReleaseOrigins'),
    current_case.id,auth.uid()
  ) returning * into new_case;
  perform set_config('app.retention_phase6_internal_write','',true);
  source_count:=private.populate_retention_legacy_sources(new_case.id,source_state);
  if source_count<>new_case.source_count then
    raise exception 'Legacy release source snapshot count changed during case creation.';
  end if;
  if current_case.id is not null then
    perform private.record_retention_legacy_event(
      current_case.id,'case_superseded','approved','superseded',
      'Approved reconciliation superseded by a changed persisted Payment Claim state.',
      p_correlation_id,jsonb_build_object('supersededByCaseId',new_case.id));
  end if;
  perform private.record_retention_legacy_event(
    new_case.id,'case_created',null,'draft',
    'Legacy retention reconciliation case created without inferred allocations.',
    p_correlation_id,jsonb_build_object('sourceCount',source_count));
  return jsonb_build_object('succeeded',true,'errorCode',null,'created',true,
    'case',private.retention_legacy_case_json(new_case.id));
end;
$$;


ALTER FUNCTION "public"."create_retention_legacy_reconciliation_case"("p_project_id" "uuid", "p_correlation_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_retention_release_schedule"("p_input" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_project uuid; v_context jsonb; v_s public.project_retention_release_schedules%rowtype;
  v_sequence integer; v_method text; v_trigger text;
begin
  v_project:=(p_input->>'projectId')::uuid;
  v_context:=private.retention_phase4_context(v_project,'retention.schedules.manage',true);
  if not coalesce((v_context->>'succeeded')::boolean,false) then return v_context; end if;
  v_method:=p_input->>'entitlementMethod'; v_trigger:=p_input->>'triggerType';
  if v_method not in ('percentage','fixed_amount') then
    return jsonb_build_object('succeeded',false,'errorCode','invalid_entitlement_method');
  end if;
  if v_trigger not in ('practical_completion','defects_liability_expiry','fixed_date','manual_milestone','custom') then
    return jsonb_build_object('succeeded',false,'errorCode','invalid_trigger');
  end if;
  perform pg_advisory_xact_lock(hashtextextended(v_project::text||':retention_schedule',4));
  select coalesce(max(schedule_sequence),0)+1 into v_sequence
  from public.project_retention_release_schedules where project_id=v_project;
  begin
    insert into public.project_retention_release_schedules(
      organization_id,project_id,name,schedule_sequence,trigger_type,entitlement_method,
      percentage_bps,fixed_amount,cap_amount,scope_policy,scheduled_trigger_date,
      delay_days,confirmation_required,reminder_rules,replaces_schedule_id,created_by
    ) values (
      (v_context->>'organizationId')::uuid,v_project,trim(p_input->>'name'),v_sequence,
      v_trigger,v_method,(p_input->>'percentageBps')::integer,
      (p_input->>'fixedAmount')::numeric,(p_input->>'capAmount')::numeric,
      coalesce(p_input->>'scopePolicy','explicit'),
      (p_input->>'scheduledTriggerDate')::date,
      coalesce((p_input->>'delayDays')::integer,0),
      coalesce((p_input->>'confirmationRequired')::boolean,v_trigger<>'fixed_date'),
      coalesce(p_input->'reminderRules',
        '[{"type":"eligibility_due","offsetDays":0,"recurrence":"none"},{"type":"overdue_unclaimed","offsetDays":7,"recurrence":"weekly"}]'::jsonb),
      (p_input->>'replacesScheduleId')::uuid,auth.uid()
    ) returning * into v_s;
  exception when check_violation or not_null_violation or invalid_text_representation then
    return jsonb_build_object('succeeded',false,'errorCode',
      case when v_method='percentage' then 'invalid_percentage' else 'invalid_fixed_amount' end);
  end;
  perform private.record_retention_schedule_event(
    v_s.id,'schedule_created',null,'draft','Retention release schedule created.',
    p_input->>'correlationId',jsonb_build_object('scheduleSequence',v_sequence)
  );
  return jsonb_build_object('succeeded',true,'errorCode',null,'schedule',to_jsonb(v_s));
end;
$$;


ALTER FUNCTION "public"."create_retention_release_schedule"("p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_retention_reminder"("p_input" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_s public.project_retention_release_schedules%rowtype; v_context jsonb;
  v_r public.retention_reminders%rowtype; v_tz text; v_due date;
begin
  select * into v_s from public.project_retention_release_schedules where id=(p_input->>'scheduleId')::uuid;
  if not found then return jsonb_build_object('succeeded',false,'errorCode','schedule_not_found'); end if;
  v_context:=private.retention_phase4_context(v_s.project_id,'retention.reminders.manage',true);
  if not coalesce((v_context->>'succeeded')::boolean,false) then return v_context; end if;
  select timezone into v_tz from public.organizations where id=v_s.organization_id;
  if not exists(select 1 from pg_timezone_names where name=v_tz) then
    return jsonb_build_object('succeeded',false,'errorCode','invalid_reminder_time');
  end if;
  v_due:=(p_input->>'contractualDueDate')::date;
  if v_due is null then return jsonb_build_object('succeeded',false,'errorCode','invalid_reminder_time'); end if;
  begin
    insert into public.retention_reminders(
      organization_id,project_id,schedule_id,retention_claim_id,reminder_type,
      contractual_due_date,organization_timezone,due_at,assigned_user_id,
      assigned_permission_key,use_project_owner_fallback,recurrence_type,
      recurrence_interval,escalation_after_days,next_delivery_at,
      maximum_attempts,occurrence_key,created_by
    ) values (
      v_s.organization_id,v_s.project_id,v_s.id,(p_input->>'retentionClaimId')::uuid,
      p_input->>'reminderType',v_due,v_tz,(v_due::timestamp at time zone v_tz),
      (p_input->>'assignedUserId')::uuid,p_input->>'assignedPermissionKey',
      coalesce((p_input->>'useProjectOwnerFallback')::boolean,false),
      coalesce(p_input->>'recurrenceType','none'),(p_input->>'recurrenceInterval')::integer,
      (p_input->>'escalationAfterDays')::integer,(v_due::timestamp at time zone v_tz),
      coalesce((p_input->>'maximumAttempts')::integer,5),
      coalesce(nullif(p_input->>'occurrenceKey',''),gen_random_uuid()::text),auth.uid()
    ) returning * into v_r;
  exception when check_violation or not_null_violation or invalid_text_representation then
    return jsonb_build_object('succeeded',false,'errorCode','invalid_assignment');
  end;
  perform private.record_retention_reminder_event(
    v_r.id,'reminder_created',null,'scheduled','Retention reminder created.',
    p_input->>'correlationId',jsonb_build_object('contractualDueDate',v_due)
  );
  return jsonb_build_object('succeeded',true,'errorCode',null,'reminder',to_jsonb(v_r));
end;
$$;


ALTER FUNCTION "public"."create_retention_reminder"("p_input" "jsonb") OWNER TO "postgres";


