CREATE OR REPLACE FUNCTION "public"."create_supplier_product_with_initial_price_without_tax_idempote"("p_input" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_org uuid := (p_input->>'organization_id')::uuid;
  v_actor uuid;
  v_material_id uuid := (p_input->>'material_id')::uuid;
  v_supplier_id uuid := (p_input->>'supplier_id')::uuid;
  v_sku text := nullif(pg_catalog.lower(pg_catalog.regexp_replace(pg_catalog.btrim(p_input->>'supplier_sku'), '\s+', ' ', 'g')), '');
  v_description text := nullif(pg_catalog.lower(pg_catalog.regexp_replace(pg_catalog.btrim(p_input->>'supplier_description'), '\s+', ' ', 'g')), '');
  v_unit text := pg_catalog.btrim(p_input->>'supplier_unit');
  v_normalized_unit text := pg_catalog.lower(pg_catalog.regexp_replace(v_unit, '\s+', ' ', 'g'));
  v_variant text := coalesce(nullif(pg_catalog.btrim(p_input->>'identity_variant'), ''), 'default');
  v_key text := pg_catalog.btrim(p_input->>'idempotency_key');
  v_product public.organization_material_supplier_products%rowtype;
  v_existing_price public.organization_material_supplier_prices%rowtype;
  v_result jsonb;
begin
  v_actor := public.materials_phase1f_require_writer(v_org);
  if not exists (select 1 from public.organization_materials where organization_id = v_org and id = v_material_id) then
    perform public.materials_phase1f_error('material_not_found');
  end if;
  if not exists (select 1 from public.organization_suppliers where organization_id = v_org and id = v_supplier_id) then
    perform public.materials_phase1f_error('supplier_not_found');
  end if;
  if nullif(v_unit, '') is null then
    perform public.materials_phase1f_error('invalid_unit');
  end if;
  if v_sku is null and v_description is null then
    perform public.materials_phase1f_error('identity_required');
  end if;
  if v_key is null or v_key = '' then
    perform public.materials_phase1f_error('idempotency_key_required');
  end if;

  select * into v_product
  from public.organization_material_supplier_products
  where organization_id = v_org
    and material_id = v_material_id
    and supplier_id = v_supplier_id
    and normalized_supplier_unit = v_normalized_unit
    and identity_variant = v_variant
    and identity_status = 'confirmed'
    and archived_at is null
    and (
      (v_sku is not null and normalized_supplier_sku = v_sku)
      or
      (v_sku is null and normalized_supplier_sku is null and normalized_supplier_description = v_description)
    )
  order by id
  limit 1
  for update;

  if v_product.id is not null then
    select * into v_existing_price
    from public.organization_material_supplier_prices
    where organization_id = v_org
      and supplier_product_id = v_product.id
      and idempotency_key = v_key;
    if v_existing_price.id is null then
      perform public.materials_phase1f_error('identity_conflict');
    end if;
    if v_existing_price.unit_cost is distinct from (p_input->>'unit_cost')::numeric
      or v_existing_price.currency is distinct from pg_catalog.upper(pg_catalog.btrim(coalesce(p_input->>'currency', 'NZD')))
      or v_existing_price.source is distinct from coalesce(p_input->>'source', 'manual')
      or ((p_input ? 'effective_from') and v_existing_price.effective_from is distinct from (p_input->>'effective_from')::timestamptz) then
      perform public.materials_phase1f_error('idempotency_conflict');
    end if;
    return pg_catalog.jsonb_build_object(
      'supplier_product_id', v_product.id,
      'price_id', v_existing_price.id,
      'supersedes_price_id', v_existing_price.supersedes_price_id,
      'idempotent_replay', true,
      'created_product', false
    );
  end if;

  begin
    insert into public.organization_material_supplier_products (
      organization_id, material_id, supplier_id, supplier_sku,
      supplier_description, supplier_unit, identity_variant, identity_status,
      is_preferred, created_source, created_by, updated_by, metadata
    ) values (
      v_org, v_material_id, v_supplier_id,
      nullif(pg_catalog.btrim(p_input->>'supplier_sku'), ''),
      nullif(pg_catalog.btrim(p_input->>'supplier_description'), ''),
      v_unit, v_variant, 'confirmed', false,
      coalesce(p_input->>'created_source', 'manual'), v_actor, v_actor,
      coalesce(p_input->'product_metadata', '{}'::jsonb)
    ) returning * into v_product;
  exception when unique_violation then
    perform public.materials_phase1f_error('identity_conflict');
  end;

  insert into public.organization_material_supplier_product_assignments (
    organization_id, supplier_product_id, previous_material_id, new_material_id,
    reason, created_by, metadata
  ) values (
    v_org, v_product.id, null, v_material_id,
    'Initial Supplier Product assignment.', v_actor,
    pg_catalog.jsonb_build_object('operation', 'phase1f_create_product')
  );

  v_result := public.materials_phase1f_add_price_internal(
    v_org, v_product.id, (p_input->>'unit_cost')::numeric,
    coalesce(p_input->>'currency', 'NZD'),
    coalesce((p_input->>'effective_from')::timestamptz, statement_timestamp()),
    p_input ? 'effective_from', coalesce(p_input->>'source', 'manual'),
    v_key, null, null, p_input->'observation_metadata'
  );

  if coalesce((p_input->>'is_preferred')::boolean, false) then
    perform public.materials_phase1f_set_preferred_internal(v_org, v_material_id, v_product.id);
  end if;

  return v_result || pg_catalog.jsonb_build_object('created_product', true);
end;
$$;


ALTER FUNCTION "public"."create_supplier_product_with_initial_price_without_tax_idempote"("p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_takeoff_commercial_item"("p_input" "jsonb") RETURNS TABLE("id" "uuid", "organization_id" "uuid", "opportunity_id" "uuid", "project_id" "uuid", "source_type" "text", "source_workbook_id" "uuid", "source_worksheet_id" "uuid", "source_sheet_id" "uuid", "source_takeoff_measurement_id" "uuid", "source_range" "text", "source_signature" "text", "source_version" integer, "source_status" "text", "stale_reason_code" "text", "last_source_checked_at" timestamp with time zone, "last_source_changed_at" timestamp with time zone, "description" "text", "quantity" numeric, "unit" "text", "rate" numeric, "total" numeric, "snapshot_json" "jsonb", "source_link_json" "jsonb", "ucl_classification" "text", "ucl_validation_status" "text", "created_by" "uuid", "updated_by" "uuid", "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
#variable_conflict use_variable
declare
  actor_user_id uuid := auth.uid();
  org_id uuid := nullif(p_input->>'organizationId', '')::uuid;
  opp_id uuid := nullif(p_input->>'opportunityId', '')::uuid;
  commercial_project_id uuid := nullif(p_input->>'projectId', '')::uuid;
  data_project_id uuid := nullif(p_input->>'dataProjectId', '')::uuid;
  measurement_id uuid := nullif(p_input->>'measurementId', '')::uuid;
  commercial_description text := btrim(coalesce(p_input->>'description', ''));
  commercial_rate numeric := round(coalesce(nullif(p_input->>'rate', '')::numeric, 0), 2);
  measurement public.takeoff_measurements%rowtype;
  inserted_row public.commercial_items%rowtype;
  commercial_quantity numeric;
  signature text;
  snapshot jsonb;
  source_link jsonb;
  resolved_owner_type text;
  resolved_owner_slug text;
begin
  if actor_user_id is null then raise exception 'Authentication is required'; end if;
  if org_id is null or opp_id is null or data_project_id is null or measurement_id is null then
    raise exception 'organizationId, opportunityId, dataProjectId, and measurementId are required' using errcode = 'TS422';
  end if;
  if commercial_description = '' then raise exception 'Description is required' using errcode = 'TS422'; end if;
  if commercial_rate < 0 then raise exception 'Rate must be non-negative' using errcode = 'TS422'; end if;
  if not public.has_org_permission(org_id, 'leads.opportunities.write') then
    raise exception 'Not authorized to capture Takeoff commercial items for this organization';
  end if;
  if not exists (
    select 1 from public.organization_opportunities o
    where o.organization_id = org_id and o.id = opp_id
      and o.workspace_project_id = data_project_id
  ) then
    raise exception 'Takeoff data Project does not belong to the Opportunity lineage';
  end if;
  if commercial_project_id is not null and not exists (
    select 1 from public.organization_projects p
    where p.organization_id = org_id and p.id = commercial_project_id and p.source_opportunity_id = opp_id
  ) then raise exception 'Commercial Project does not belong to the Opportunity'; end if;
  if commercial_project_id is not null then
    select 'project', p.slug into resolved_owner_type, resolved_owner_slug
    from public.organization_projects p
    where p.organization_id = org_id and p.id = commercial_project_id;
  else
    select 'opportunity', o.slug into resolved_owner_type, resolved_owner_slug
    from public.organization_opportunities o
    where o.organization_id = org_id and o.id = opp_id;
  end if;

  select m.* into measurement from public.takeoff_measurements m
  where m.organization_id = org_id and m.project_id = data_project_id and m.id = measurement_id
    and m.status = 'active' and m.measurement_kind in ('line', 'area', 'count')
    and exists (select 1 from public.project_drawing_sets ds where ds.id = m.drawing_set_id and ds.organization_id = org_id and ds.project_id = data_project_id)
    and exists (select 1 from public.takeoff_pages page where page.id = m.page_id and page.organization_id = org_id and page.project_id = data_project_id and page.drawing_set_id = m.drawing_set_id);
  if not found then raise exception 'Active committed measurement was not found for the authorized Takeoff Project' using errcode = 'TS404'; end if;

  commercial_quantity := round(case when measurement.measurement_kind = 'count'
    then coalesce(measurement.count_value, measurement.display_value)
    else measurement.display_value end, 3);
  if commercial_quantity is null or commercial_quantity < 0 then
    raise exception 'Measurement does not have a valid committed display quantity' using errcode = 'TS422';
  end if;
  if nullif(btrim(coalesce(measurement.display_unit, '')), '') is null then
    raise exception 'Measurement does not have a committed display unit' using errcode = 'TS422';
  end if;

  snapshot := jsonb_build_object(
    'version', 1, 'sourceType', 'takeoff_measurement',
    'measurementId', measurement.id, 'measurementVersion', measurement.version,
    'measurementUpdatedAt', measurement.updated_at, 'measurementKind', measurement.measurement_kind,
    'drawingSetId', measurement.drawing_set_id, 'pageId', measurement.page_id,
    'measurementName', measurement.name, 'measurementDescription', measurement.description,
    'displayQuantity', commercial_quantity, 'displayUnit', measurement.display_unit,
    'commercialDescription', commercial_description, 'commercialQuantity', commercial_quantity,
    'commercialRate', commercial_rate, 'commercialTotal', round(commercial_quantity * commercial_rate, 2)
  );
  signature := md5(snapshot::text);
  source_link := jsonb_build_object(
    'sourceType', 'takeoff_measurement', 'measurementId', measurement.id,
    'measurementVersion', measurement.version, 'drawingSetId', measurement.drawing_set_id,
    'measurementUpdatedAt', measurement.updated_at, 'pageId', measurement.page_id,
    'ownerType', resolved_owner_type, 'ownerSlug', resolved_owner_slug,
    'opportunityId', opp_id, 'projectId', commercial_project_id,
    'dataProjectId', data_project_id, 'capturedAt', timezone('utc', now())
  );

  select item.* into inserted_row from public.commercial_items item
  where item.organization_id = org_id and item.opportunity_id = opp_id
    and item.source_type = 'takeoff_measurement'
    and item.source_takeoff_measurement_id = measurement.id
    and item.source_signature = signature
  order by item.created_at desc limit 1;

  if not found then
    insert into public.commercial_items (
      organization_id, opportunity_id, project_id, source_type,
      source_takeoff_measurement_id, source_signature, source_version, source_status,
      last_source_checked_at, description, quantity, unit, rate, total,
      snapshot_json, source_link_json, locked_metadata_json,
      ucl_validation_status, created_by, updated_by
    ) values (
      org_id, opp_id, commercial_project_id, 'takeoff_measurement',
      measurement.id, signature, measurement.version, 'current', timezone('utc', now()),
      commercial_description, commercial_quantity, measurement.display_unit, commercial_rate,
      round(commercial_quantity * commercial_rate, 2), snapshot, source_link, '{}'::jsonb,
      'not_reviewed', actor_user_id, actor_user_id
    ) returning * into inserted_row;
  end if;

  return query select inserted_row.id, inserted_row.organization_id, inserted_row.opportunity_id,
    inserted_row.project_id, inserted_row.source_type, inserted_row.source_workbook_id,
    inserted_row.source_worksheet_id, inserted_row.source_sheet_id,
    inserted_row.source_takeoff_measurement_id, inserted_row.source_range,
    inserted_row.source_signature, inserted_row.source_version, inserted_row.source_status,
    inserted_row.stale_reason_code, inserted_row.last_source_checked_at,
    inserted_row.last_source_changed_at, inserted_row.description, inserted_row.quantity,
    inserted_row.unit, inserted_row.rate, inserted_row.total, inserted_row.snapshot_json,
    inserted_row.source_link_json, inserted_row.ucl_classification,
    inserted_row.ucl_validation_status, inserted_row.created_by, inserted_row.updated_by,
    inserted_row.created_at, inserted_row.updated_at;
end;
$$;


ALTER FUNCTION "public"."create_takeoff_commercial_item"("p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_task"("p_input" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  actor_user_id uuid := auth.uid();
  resolved_organization_id uuid := public._task_current_organization_id();
  project_row public.organization_projects%rowtype;
  inserted_row public.project_job_todos%rowtype;
  requested_project_id uuid;
  requested_opportunity_id uuid;
  requested_assigned_user_id uuid;
  requested_status text;
  requested_priority text;
begin
  requested_project_id := nullif(p_input->>'projectId', '')::uuid;
  if requested_project_id is null then
    raise exception 'projectId is required';
  end if;

  project_row := public._task_assert_project_access(requested_project_id, resolved_organization_id);

  requested_opportunity_id := nullif(p_input->>'opportunityId', '')::uuid;
  if requested_opportunity_id is not null and not exists (
    select 1
    from public.organization_opportunities o
    where o.id = requested_opportunity_id
      and o.organization_id = resolved_organization_id
      and o.workspace_project_id = requested_project_id
  ) then
    raise exception 'Opportunity does not belong to this project';
  end if;

  requested_assigned_user_id := nullif(p_input->>'assignedUserId', '')::uuid;
  perform public._task_validate_assignee(resolved_organization_id, requested_assigned_user_id);

  requested_status := public._task_normalize_status(p_input->>'status');
  requested_priority := public._task_normalize_priority(p_input->>'priority');

  insert into public.project_job_todos (
    organization_id,
    project_id,
    opportunity_id,
    created_by,
    updated_by,
    title,
    description,
    due_date,
    due_at,
    assigned_user_id,
    trade,
    priority,
    status,
    is_completed,
    completed_by,
    completed_at,
    source_type,
    source_id,
    linked_issue_id,
    linked_inspection_id,
    linked_inspection_item_id,
    linked_variation_id,
    linked_purchase_order_id,
    linked_quote_id,
    linked_client_id,
    task_type,
    metadata
  )
  values (
    resolved_organization_id,
    requested_project_id,
    requested_opportunity_id,
    actor_user_id,
    actor_user_id,
    nullif(btrim(coalesce(p_input->>'title', '')), ''),
    coalesce(p_input->>'description', ''),
    nullif(p_input->>'dueDate', '')::date,
    nullif(p_input->>'dueAt', '')::timestamptz,
    requested_assigned_user_id,
    coalesce(p_input->>'trade', ''),
    requested_priority,
    requested_status,
    requested_status = 'Done',
    case when requested_status = 'Done' then actor_user_id else null end,
    case when requested_status = 'Done' then now() else null end,
    nullif(p_input->>'sourceType', ''),
    nullif(p_input->>'sourceId', '')::uuid,
    nullif(p_input->>'linkedIssueId', '')::uuid,
    nullif(p_input->>'linkedInspectionId', '')::uuid,
    nullif(p_input->>'linkedInspectionItemId', '')::uuid,
    nullif(p_input->>'linkedVariationId', '')::uuid,
    nullif(p_input->>'linkedPurchaseOrderId', '')::uuid,
    nullif(p_input->>'linkedQuoteId', '')::uuid,
    nullif(p_input->>'linkedClientId', '')::uuid,
    nullif(p_input->>'taskType', ''),
    coalesce(p_input->'metadata', '{}'::jsonb)
  )
  returning * into inserted_row;

  perform public._write_task_activity(
    inserted_row.organization_id,
    inserted_row.id,
    inserted_row.project_id,
    actor_user_id,
    'task_created',
    null,
    null,
    public._task_to_json(inserted_row),
    '{}'::jsonb
  );

  if inserted_row.assigned_user_id is not null then
    perform public._write_task_activity(
      inserted_row.organization_id,
      inserted_row.id,
      inserted_row.project_id,
      actor_user_id,
      'assigned',
      'assigned_user_id',
      null,
      to_jsonb(inserted_row.assigned_user_id),
      '{}'::jsonb
    );
  end if;

  return public._task_to_json(inserted_row);
end;
$$;


ALTER FUNCTION "public"."create_task"("p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_task_attachment"("p_task_id" "uuid", "p_input" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  actor_user_id uuid := auth.uid();
  task_row public.project_job_todos%rowtype;
  attachment_row public.task_attachments%rowtype;
  requested_comment_id uuid;
  requested_storage_bucket text;
  requested_storage_path text;
  requested_attachment_type text;
begin
  task_row := public._task_assert_task_access(p_task_id);

  requested_storage_bucket := coalesce(nullif(btrim(p_input->>'storageBucket'), ''), 'task-attachments');
  if requested_storage_bucket <> 'task-attachments' then
    raise exception 'Invalid task attachment storage bucket';
  end if;

  requested_storage_path := nullif(btrim(coalesce(p_input->>'storagePath', '')), '');
  if requested_storage_path is null then
    raise exception 'storagePath is required';
  end if;

  if not public.can_access_task_attachment_storage_object(requested_storage_path) then
    raise exception 'Invalid or inaccessible task attachment storage path';
  end if;

  if split_part(requested_storage_path, '/', 1) <> task_row.organization_id::text then
    raise exception 'Storage path organization does not match task';
  end if;

  if split_part(requested_storage_path, '/', 2) <> 'unscoped'
     and split_part(requested_storage_path, '/', 2) <> task_row.project_id::text then
    raise exception 'Storage path project does not match task';
  end if;

  if split_part(requested_storage_path, '/', 4) <> task_row.id::text then
    raise exception 'Storage path task does not match task';
  end if;

  requested_comment_id := nullif(p_input->>'commentId', '')::uuid;
  if requested_comment_id is not null and not exists (
    select 1
    from public.task_comments c
    where c.id = requested_comment_id
      and c.organization_id = task_row.organization_id
      and c.task_id = task_row.id
      and c.deleted_at is null
  ) then
    raise exception 'Task comment not found';
  end if;

  requested_attachment_type := coalesce(nullif(btrim(p_input->>'attachmentType'), ''), 'other');

  insert into public.task_attachments (
    organization_id,
    task_id,
    project_id,
    comment_id,
    uploaded_by,
    file_name,
    original_file_name,
    file_type,
    mime_type,
    storage_bucket,
    storage_path,
    file_size,
    attachment_type,
    metadata
  )
  values (
    task_row.organization_id,
    task_row.id,
    task_row.project_id,
    requested_comment_id,
    actor_user_id,
    nullif(btrim(coalesce(p_input->>'fileName', '')), ''),
    nullif(btrim(coalesce(p_input->>'originalFileName', '')), ''),
    nullif(btrim(coalesce(p_input->>'fileType', '')), ''),
    nullif(btrim(coalesce(p_input->>'mimeType', '')), ''),
    requested_storage_bucket,
    requested_storage_path,
    nullif(p_input->>'fileSize', '')::bigint,
    requested_attachment_type,
    coalesce(p_input->'metadata', '{}'::jsonb)
  )
  returning * into attachment_row;

  perform public._write_task_activity(
    task_row.organization_id,
    task_row.id,
    task_row.project_id,
    actor_user_id,
    'attachment_added',
    null,
    null,
    to_jsonb(attachment_row.id),
    jsonb_build_object(
      'attachmentId', attachment_row.id,
      'fileName', attachment_row.file_name,
      'storagePath', attachment_row.storage_path
    )
  );

  return public._task_attachment_to_json(attachment_row);
end;
$$;


ALTER FUNCTION "public"."create_task_attachment"("p_task_id" "uuid", "p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_task_comment"("p_task_id" "uuid", "p_comment" "text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  actor_user_id uuid := auth.uid();
  task_row public.project_job_todos%rowtype;
  comment_row public.task_comments%rowtype;
begin
  task_row := public._task_assert_task_access(p_task_id);

  insert into public.task_comments (
    organization_id,
    task_id,
    project_id,
    user_id,
    comment,
    metadata
  )
  values (
    task_row.organization_id,
    task_row.id,
    task_row.project_id,
    actor_user_id,
    nullif(btrim(coalesce(p_comment, '')), ''),
    coalesce(p_metadata, '{}'::jsonb)
  )
  returning * into comment_row;

  perform public._write_task_activity(task_row.organization_id, task_row.id, task_row.project_id, actor_user_id, 'comment_added', null, null, to_jsonb(comment_row.id), jsonb_build_object('commentId', comment_row.id));

  return jsonb_build_object(
    'id', comment_row.id,
    'organizationId', comment_row.organization_id,
    'taskId', comment_row.task_id,
    'projectId', comment_row.project_id,
    'userId', comment_row.user_id,
    'comment', comment_row.comment,
    'metadata', comment_row.metadata,
    'createdAt', comment_row.created_at,
    'updatedAt', comment_row.updated_at,
    'deletedAt', comment_row.deleted_at,
    'deletedBy', comment_row.deleted_by
  );
end;
$$;


ALTER FUNCTION "public"."create_task_comment"("p_task_id" "uuid", "p_comment" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_validation_case"("p_input" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  member_row public.organization_members%rowtype;
  inserted_id uuid;
  resolved_organization_id uuid;
  resolved_project_id uuid;
  resolved_opportunity_id uuid;
  resolved_linked_event_id uuid;
  resolved_linked_ai_interaction_id uuid;
begin
  if p_input is null or jsonb_typeof(p_input) <> 'object' then
    raise exception 'create_validation_case requires a JSON object payload';
  end if;

  resolved_organization_id := nullif(p_input->>'organizationId', '')::uuid;
  if resolved_organization_id is null then
    raise exception 'organizationId is required';
  end if;

  member_row := public._intelligence_assert_organization_member(resolved_organization_id);
  resolved_project_id := nullif(p_input->>'projectId', '')::uuid;
  resolved_opportunity_id := nullif(p_input->>'opportunityId', '')::uuid;
  resolved_linked_event_id := nullif(p_input->>'linkedEventId', '')::uuid;
  resolved_linked_ai_interaction_id := nullif(p_input->>'linkedAiInteractionId', '')::uuid;

  perform public._intelligence_assert_project_in_organization(resolved_organization_id, resolved_project_id);
  perform public._intelligence_assert_opportunity_in_organization(resolved_organization_id, resolved_opportunity_id);
  perform public._intelligence_assert_event_in_organization(resolved_organization_id, resolved_linked_event_id);
  perform public._intelligence_assert_ai_interaction_in_organization(resolved_organization_id, resolved_linked_ai_interaction_id);

  insert into public.validation_cases (
    organization_id,
    project_id,
    opportunity_id,
    module,
    scope_entity_type,
    scope_entity_id,
    linked_event_id,
    linked_ai_interaction_id,
    rule_key,
    rule_version,
    validation_type,
    severity,
    result,
    expected_value,
    observed_value,
    details,
    requires_approval,
    approval_status,
    approved_by_user_id,
    approved_at,
    approval_note,
    privacy_classification,
    visibility_scope
  )
  values (
    resolved_organization_id,
    resolved_project_id,
    resolved_opportunity_id,
    nullif(btrim(coalesce(p_input->>'module', '')), ''),
    nullif(btrim(coalesce(p_input->>'scopeEntityType', '')), ''),
    nullif(p_input->>'scopeEntityId', '')::uuid,
    resolved_linked_event_id,
    resolved_linked_ai_interaction_id,
    nullif(btrim(coalesce(p_input->>'ruleKey', '')), ''),
    nullif(btrim(coalesce(p_input->>'ruleVersion', '')), ''),
    nullif(btrim(coalesce(p_input->>'validationType', '')), ''),
    nullif(btrim(coalesce(p_input->>'severity', '')), ''),
    nullif(btrim(coalesce(p_input->>'result', '')), ''),
    p_input->'expectedValue',
    p_input->'observedValue',
    coalesce(p_input->'details', '{}'::jsonb),
    coalesce(nullif(p_input->>'requiresApproval', '')::boolean, false),
    coalesce(nullif(btrim(coalesce(p_input->>'approvalStatus', '')), ''), 'not_required'),
    case
      when nullif(btrim(coalesce(p_input->>'approvalStatus', '')), '') = 'approved' then auth.uid()
      else null
    end,
    case
      when nullif(btrim(coalesce(p_input->>'approvalStatus', '')), '') = 'approved' then now()
      else null
    end,
    nullif(p_input->>'approvalNote', ''),
    coalesce(nullif(btrim(coalesce(p_input->>'privacyClassification', '')), ''), 'internal_operational'),
    coalesce(nullif(btrim(coalesce(p_input->>'visibilityScope', '')), ''), 'organization')
  )
  returning id into inserted_id;

  return inserted_id;
end;
$$;


ALTER FUNCTION "public"."create_validation_case"("p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."decide_supplier_invoice_site_review"("p_decision_id" "uuid", "p_decision" "text", "p_note" "text", "p_accepted_variances" "jsonb" DEFAULT '[]'::"jsonb", "p_disputed_allocation_ids" "uuid"[] DEFAULT '{}'::"uuid"[]) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_organization_id uuid;
  v_existing_decision text;
begin
  select m.organization_id into v_organization_id
  from public.organization_members m where m.user_id = auth.uid()
  order by m.created_at limit 1;
  select d.decision into v_existing_decision
  from public.supplier_invoice_site_review_decisions d
  where d.id = p_decision_id and d.organization_id = v_organization_id
  for update;
  if v_existing_decision is null then raise exception 'Site-review decision not found.'; end if;
  if v_existing_decision <> 'pending' then
    if v_existing_decision = p_decision then return p_decision_id; end if;
    raise exception 'The site-review decision has already been recorded.';
  end if;
  return private.decide_supplier_invoice_site_review_phase_ab_legacy(
    p_decision_id, p_decision, p_note, p_accepted_variances, p_disputed_allocation_ids
  );
end;
$$;


ALTER FUNCTION "public"."decide_supplier_invoice_site_review"("p_decision_id" "uuid", "p_decision" "text", "p_note" "text", "p_accepted_variances" "jsonb", "p_disputed_allocation_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."decide_supplier_invoice_site_review"("p_decision_id" "uuid", "p_allocation_id" "uuid", "p_decision" "text", "p_note" "text", "p_accepted_variances" "jsonb" DEFAULT '[]'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_member public.organization_members%rowtype;
  v_parent public.supplier_invoice_site_review_decisions%rowtype;
  v_submission public.supplier_invoice_site_review_submissions%rowtype;
  v_allocation public.supplier_invoice_line_allocations%rowtype;
  v_parent_pending integer;
  v_parent_approved integer;
  v_parent_disputed integer;
  v_submission_pending integer;
  v_submission_approved integer;
  v_submission_disputed integer;
  v_parent_status text;
  v_submission_status text;
begin
  if p_decision not in ('approved', 'disputed') then
    raise exception 'Choose approved or disputed.';
  end if;
  if p_decision = 'disputed' and char_length(trim(coalesce(p_note, ''))) = 0 then
    raise exception 'Add a decline comment.';
  end if;
  if jsonb_typeof(coalesce(p_accepted_variances, '[]'::jsonb)) <> 'array' then
    raise exception 'Accepted variances must be an array.';
  end if;

  select * into v_member
  from public.organization_members
  where user_id = auth.uid()
  order by created_at
  limit 1;
  if v_member.id is null
    or not public.has_org_permission(v_member.organization_id, 'supplier_invoices.site_review') then
    raise exception 'You do not have permission to perform site review.';
  end if;

  -- Serialize independent line decisions belonging to the same PO aggregate.
  perform pg_advisory_xact_lock(hashtextextended(p_decision_id::text, 2));

  select * into v_parent
  from public.supplier_invoice_site_review_decisions
  where id = p_decision_id
    and organization_id = v_member.organization_id
    and decision in ('pending', 'approved', 'disputed')
  for update;
  if not found then
    raise exception 'Site-review decision not found or no longer current.';
  end if;

  select * into v_submission
  from public.supplier_invoice_site_review_submissions
  where id = v_parent.submission_id
    and organization_id = v_member.organization_id
    and status in ('submitted', 'partially_reviewed', 'approved', 'disputed')
  for update;
  if not found
    or v_submission.finance_hash <> public.supplier_invoice_finance_version_hash(v_parent.supplier_invoice_id) then
    raise exception 'The site-review submission is no longer current.';
  end if;

  select * into v_allocation
  from public.supplier_invoice_line_allocations
  where id = p_allocation_id
    and organization_id = v_member.organization_id
  for update;
  if not found
    or not (p_allocation_id = any(v_parent.allocation_ids_snapshot))
    or v_allocation.supplier_invoice_id <> v_parent.supplier_invoice_id
    or v_allocation.purchase_order_id is distinct from v_parent.purchase_order_id
    or v_allocation.project_id is distinct from v_parent.project_id
    or v_allocation.purchase_order_line_item_id is null then
    raise exception 'The allocation does not belong to this current Team Approval request.';
  end if;

  if not exists (
    select 1
    from public.supplier_invoices invoice
    join public.project_purchase_orders purchase_order
      on purchase_order.id = v_allocation.purchase_order_id
     and purchase_order.organization_id = invoice.organization_id
    join public.project_purchase_order_line_items purchase_order_line
      on purchase_order_line.id = v_allocation.purchase_order_line_item_id
     and purchase_order_line.purchase_order_id = purchase_order.id
     and purchase_order_line.organization_id = invoice.organization_id
    join public.supplier_invoice_purchase_order_matches purchase_order_match
      on purchase_order_match.supplier_invoice_id = invoice.id
     and purchase_order_match.purchase_order_id = purchase_order.id
     and purchase_order_match.organization_id = invoice.organization_id
     and purchase_order_match.match_status in ('accepted', 'adjusted')
    where invoice.id = v_parent.supplier_invoice_id
      and invoice.organization_id = v_member.organization_id
      and purchase_order.supplier_id is not distinct from invoice.supplier_id
      and lower(purchase_order.status) <> 'cancelled'
  ) then
    raise exception 'The allocation Purchase Order relationship is no longer valid.';
  end if;

  if v_member.role not in ('owner', 'admin') and not exists (
    select 1
    from public.project_members project_member
    where project_member.organization_id = v_member.organization_id
      and project_member.project_id = v_parent.project_id
      and project_member.organization_member_id = v_member.id
      and project_member.is_active
  ) then
    raise exception 'You may only review Supplier Invoice costs for your assigned projects.';
  end if;

  if v_allocation.approval_status <> 'pending' then
    if v_allocation.approval_status = p_decision
      and v_allocation.approval_checks_json ->> 'siteReviewSubmissionId' = v_submission.id::text then
      return p_decision_id;
    end if;
    raise exception 'This Supplier Invoice line has already been reviewed.';
  end if;

  perform set_config('tradesstack.site_review_decision', 'on', true);
  update public.supplier_invoice_line_allocations
  set approval_status = p_decision,
      review_status = case when p_decision = 'approved' then 'resolved' else 'disputed' end,
      approval_notes = trim(coalesce(p_note, '')),
      approval_checks_json = jsonb_build_object(
        'acceptedVariances', case when p_decision = 'approved' then coalesce(p_accepted_variances, '[]'::jsonb) else '[]'::jsonb end,
        'siteReviewSubmissionId', v_submission.id,
        'siteReviewDecisionId', v_parent.id,
        'financeHash', v_submission.finance_hash
      ),
      reviewed_by_user_id = auth.uid(),
      reviewed_at = now(),
      approved_by_user_id = case when p_decision = 'approved' then auth.uid() else null end,
      approved_at = case when p_decision = 'approved' then now() else null end
  where id = p_allocation_id;

  select
    count(*) filter (where allocation.approval_status = 'pending'),
    count(*) filter (where allocation.approval_status = 'approved'),
    count(*) filter (where allocation.approval_status = 'disputed')
  into v_parent_pending, v_parent_approved, v_parent_disputed
  from unnest(v_parent.allocation_ids_snapshot) allocation_id
  join public.supplier_invoice_line_allocations allocation on allocation.id = allocation_id;

  v_parent_status := case
    when v_parent_disputed > 0 then 'disputed'
    when v_parent_pending = 0 and v_parent_approved > 0 then 'approved'
    else 'pending'
  end;

  update public.supplier_invoice_site_review_decisions
  set decision = v_parent_status,
      reviewer_id = case when v_parent_status = 'pending' then null else auth.uid() end,
      reviewed_at = case when v_parent_status = 'pending' then null else now() end,
      note = case when v_parent_status = 'pending' then '' else trim(coalesce(p_note, '')) end,
      accepted_variances = case
        when v_parent_status = 'approved' then coalesce((
          select jsonb_agg(accepted_variance.value)
          from unnest(v_parent.allocation_ids_snapshot) reviewed_allocation_id
          join public.supplier_invoice_line_allocations reviewed_allocation
            on reviewed_allocation.id = reviewed_allocation_id
          cross join lateral jsonb_array_elements(
            coalesce(reviewed_allocation.approval_checks_json -> 'acceptedVariances', '[]'::jsonb)
          ) accepted_variance(value)
        ), '[]'::jsonb)
        else '[]'::jsonb
      end,
      disputed_allocation_ids = coalesce((
        select array_agg(reviewed_allocation.id order by reviewed_allocation.id)
        from unnest(v_parent.allocation_ids_snapshot) reviewed_allocation_id
        join public.supplier_invoice_line_allocations reviewed_allocation
          on reviewed_allocation.id = reviewed_allocation_id
        where reviewed_allocation.approval_status = 'disputed'
      ), '{}'),
      updated_at = now()
  where id = v_parent.id;

  select
    count(*) filter (where allocation.approval_status = 'pending'),
    count(*) filter (where allocation.approval_status = 'approved'),
    count(*) filter (where allocation.approval_status = 'disputed')
  into v_submission_pending, v_submission_approved, v_submission_disputed
  from (
    select distinct unnest(parent.allocation_ids_snapshot) as allocation_id
    from public.supplier_invoice_site_review_decisions parent
    where parent.submission_id = v_submission.id
  ) submitted
  join public.supplier_invoice_line_allocations allocation on allocation.id = submitted.allocation_id;

  v_submission_status := case
    when v_submission_disputed > 0 then 'disputed'
    when v_submission_pending = 0 and v_submission_approved > 0 then 'approved'
    when v_submission_approved > 0 then 'partially_reviewed'
    else 'submitted'
  end;
  update public.supplier_invoice_site_review_submissions
  set status = v_submission_status,
      updated_at = now()
  where id = v_submission.id;

  insert into public.supplier_invoice_activity_events (
    organization_id, supplier_invoice_id, event_type, message, metadata, created_by
  ) values (
    v_member.organization_id,
    v_parent.supplier_invoice_id,
    case when p_decision = 'approved' then 'site_review_line_approved' else 'site_review_line_disputed' end,
    case when p_decision = 'approved'
      then 'Supplier Invoice line approved by the project team.'
      else 'Supplier Invoice line declined by the project team.'
    end,
    jsonb_build_object(
      'submission_id', v_submission.id,
      'site_review_decision_id', v_parent.id,
      'allocation_id', p_allocation_id,
      'supplier_invoice_line_id', v_allocation.supplier_invoice_line_id,
      'purchase_order_id', v_allocation.purchase_order_id,
      'purchase_order_line_item_id', v_allocation.purchase_order_line_item_id,
      'project_id', v_allocation.project_id,
      'decision', p_decision,
      'comment', trim(coalesce(p_note, '')),
      'accepted_variances', case when p_decision = 'approved' then coalesce(p_accepted_variances, '[]'::jsonb) else '[]'::jsonb end,
      'finance_hash', v_submission.finance_hash
    ),
    auth.uid()
  );

  return p_decision_id;
end;
$$;


ALTER FUNCTION "public"."decide_supplier_invoice_site_review"("p_decision_id" "uuid", "p_allocation_id" "uuid", "p_decision" "text", "p_note" "text", "p_accepted_variances" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."default_trade_pack_monthly_limit"("plan_tier" "text") RETURNS integer
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select case lower(trim(coalesce(plan_tier, 'starter')))
    when 'starter' then 4
    when 'professional' then 12
    when 'business' then 30
    else 4
  end;
$$;


ALTER FUNCTION "public"."default_trade_pack_monthly_limit"("plan_tier" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."delete_opportunity_pricing_workbook_sheet"("p_organization_id" "uuid", "p_opportunity_id" "uuid", "p_workbook_id" "uuid", "p_sheet_id" "uuid", "p_user_id" "uuid", "p_next_sheet_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  v_deleted_sheet public.opportunity_pricing_workbook_sheets%rowtype;
  v_next_sheet public.opportunity_pricing_workbook_sheets%rowtype;
  v_remaining_count integer;
begin
  select *
  into v_deleted_sheet
  from public.opportunity_pricing_workbook_sheets
  where id = p_sheet_id
    and workbook_id = p_workbook_id
    and organization_id = p_organization_id
    and opportunity_id = p_opportunity_id;

  if not found then
    raise exception 'Worksheet page not found.';
  end if;

  select count(*)
  into v_remaining_count
  from public.opportunity_pricing_workbook_sheets
  where workbook_id = p_workbook_id
    and organization_id = p_organization_id
    and opportunity_id = p_opportunity_id;

  if v_remaining_count <= 1 then
    raise exception 'You must keep at least one worksheet page.';
  end if;

  delete from public.opportunity_pricing_workbook_sheets
  where id = v_deleted_sheet.id;

  if p_next_sheet_id is not null then
    select *
    into v_next_sheet
    from public.opportunity_pricing_workbook_sheets
    where id = p_next_sheet_id
      and workbook_id = p_workbook_id
      and organization_id = p_organization_id
      and opportunity_id = p_opportunity_id;
  end if;

  if v_deleted_sheet.is_default then
    if v_next_sheet.id is null then
      select *
      into v_next_sheet
      from public.opportunity_pricing_workbook_sheets
      where workbook_id = p_workbook_id
        and organization_id = p_organization_id
        and opportunity_id = p_opportunity_id
      order by sheet_order asc, created_at asc
      limit 1;
    end if;

    update public.opportunity_pricing_workbook_sheets
    set
      is_default = (id = v_next_sheet.id),
      updated_by = p_user_id
    where workbook_id = p_workbook_id
      and organization_id = p_organization_id
      and opportunity_id = p_opportunity_id
      and (is_default = true or id = v_next_sheet.id);

    if v_next_sheet.id is not null then
      update public.opportunity_pricing_worksheets
      set
        name = v_next_sheet.name,
        worksheet_data = v_next_sheet.worksheet_data,
        pricing_summary = v_next_sheet.pricing_summary,
        extracted_pricing_data = v_next_sheet.extracted_pricing_data,
        version = v_next_sheet.version,
        updated_by = p_user_id
      where id = p_workbook_id
        and organization_id = p_organization_id
        and opportunity_id = p_opportunity_id
        and archived_at is null;
    end if;
  end if;

  return jsonb_build_object(
    'deletedSheetId', v_deleted_sheet.id,
    'nextSheetId', coalesce(v_next_sheet.id, p_next_sheet_id)
  );
end;
$$;


ALTER FUNCTION "public"."delete_opportunity_pricing_workbook_sheet"("p_organization_id" "uuid", "p_opportunity_id" "uuid", "p_workbook_id" "uuid", "p_sheet_id" "uuid", "p_user_id" "uuid", "p_next_sheet_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."delete_project_claim_safe"("p_organization_id" "uuid", "p_project_id" "uuid", "p_claim_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  existing_claim public.project_claims%rowtype;
begin
  if auth.uid() is null then
    raise exception 'Authentication is required';
  end if;

  if not public.has_org_permission(p_organization_id, 'quotes.write') then
    raise exception 'Not authorized for this organization';
  end if;

  if not exists (
    select 1
    from public.organization_projects p
    where p.id = p_project_id
      and p.organization_id = p_organization_id
  ) then
    raise exception 'Project not found for organization';
  end if;

  select *
  into existing_claim
  from public.project_claims c
  where c.id = p_claim_id
    and c.organization_id = p_organization_id
    and c.project_id = p_project_id
  for update;

  if not found then
    raise exception 'Claim not found';
  end if;

  if coalesce(existing_claim.status, 'Draft') <> 'Draft' then
    raise exception 'Only draft claims can be deleted';
  end if;

  update public.cost_items
  set
    status = 'deleted',
    effective_to = coalesce(effective_to, clock_timestamp()),
    is_current = false,
    source_line_id = null,
    linked_claim_line_item_id = null
  where source_document_kind = 'project_claim'
    and source_document_id = p_claim_id
    and is_current = true;

  delete from public.project_claims c
  where c.id = p_claim_id
    and c.organization_id = p_organization_id
    and c.project_id = p_project_id;

  perform public.recalculate_project_claim_snapshots(
    p_organization_id,
    p_project_id
  );
end;
$$;


ALTER FUNCTION "public"."delete_project_claim_safe"("p_organization_id" "uuid", "p_project_id" "uuid", "p_claim_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."delete_supplier_bill_ucl_current_container"("p_queue_id" "uuid", "p_lease_token" "uuid", "p_organization_id" "uuid", "p_source_id" "uuid", "p_refresh_reason" "text", "p_deletion_evidence_at" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  queue_row public.supplier_bill_ucl_refresh_queue%rowtype;
  historical_count integer := 0;
begin
  select *
  into queue_row
  from public.supplier_bill_ucl_refresh_queue q
  where q.id = p_queue_id
    and q.queue_state = 'leased'
    and q.lease_token = p_lease_token
    and q.organization_id = p_organization_id
    and q.source_id = p_source_id
  for update;

  if not found then
    raise exception 'Supplier Bill UCL deletion lease is not owned by this worker.'
      using errcode = 'P0001';
  end if;
  if p_refresh_reason <> 'supplier_bill_deleted'
    or p_refresh_reason is distinct from queue_row.reason_code then
    raise exception 'Supplier Bill UCL deletion reason does not match the leased request.'
      using errcode = '22023';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(
    p_organization_id::text || ':supplier_invoice:' || p_source_id::text,
    0
  ));
  if p_deletion_evidence_at is null
    or queue_row.deletion_evidence_at is null
    or exists (select 1 from public.supplier_invoices i where i.id = p_source_id) then
    raise exception 'Supplier Bill UCL deletion is not canonically proven.'
      using errcode = '22023';
  end if;

  insert into public.supplier_bill_ucl_current_state (
    organization_id,
    container_type,
    source_id,
    current_version_id,
    schema_version,
    builder_version,
    content_hash,
    canonical_updated_at,
    latest_dependency_updated_at,
    validated_at,
    payload_bytes,
    context_status,
    supplier_id,
    project_ids,
    primary_project_id,
    visibility_scope_hash,
    last_refresh_reason,
    deleted_at
  ) values (
    p_organization_id,
    'supplier_invoice',
    p_source_id,
    null,
    null,
    null,
    null,
    null,
    null,
    now(),
    null,
    'deleted',
    null,
    '{}',
    null,
    null,
    p_refresh_reason,
    p_deletion_evidence_at
  )
  on conflict (organization_id, container_type, source_id)
  do update set
    current_version_id = null,
    schema_version = null,
    builder_version = null,
    content_hash = null,
    canonical_updated_at = null,
    latest_dependency_updated_at = null,
    validated_at = now(),
    payload_bytes = null,
    context_status = 'deleted',
    supplier_id = null,
    project_ids = '{}',
    primary_project_id = null,
    visibility_scope_hash = null,
    last_refresh_reason = excluded.last_refresh_reason,
    deleted_at = excluded.deleted_at,
    updated_at = now();

  select count(*)::integer
  into historical_count
  from public.supplier_bill_ucl_container_versions v
  where v.organization_id = p_organization_id
    and v.container_type = 'supplier_invoice'
    and v.source_id = p_source_id;

  return jsonb_build_object(
    'createdVersion', false,
    'reusedVersion', false,
    'currentUpdated', true,
    'contentChanged', true,
    'staleWriteRejected', false,
    'versionId', null,
    'currentHash', null,
    'versionCount', historical_count,
    'payloadBytes', null,
    'contextStatus', 'deleted'
  );
end;
$$;


ALTER FUNCTION "public"."delete_supplier_bill_ucl_current_container"("p_queue_id" "uuid", "p_lease_token" "uuid", "p_organization_id" "uuid", "p_source_id" "uuid", "p_refresh_reason" "text", "p_deletion_evidence_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."delete_supplier_invoice"("p_organization_id" "uuid", "p_supplier_invoice_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_member public.organization_members%rowtype;
  v_invoice public.supplier_invoices%rowtype;
  v_accounting_document public.organization_accounting_documents%rowtype;
  v_storage_paths text[] := '{}'::text[];
begin
  if auth.uid() is null then
    raise exception 'You do not have permission to delete this Supplier Invoice.';
  end if;

  select *
  into v_member
  from public.organization_members
  where organization_id = p_organization_id
    and user_id = auth.uid()
  order by created_at
  limit 1;

  if not found
    or v_member.role not in ('owner', 'admin')
    or not public.has_org_permission(p_organization_id, 'supplier_invoices.capture') then
    raise exception 'You do not have permission to delete this Supplier Invoice.';
  end if;

  select *
  into v_invoice
  from public.supplier_invoices
  where id = p_supplier_invoice_id
    and organization_id = p_organization_id
  for update;

  if not found then
    raise exception 'This Supplier Invoice has already been deleted or no longer exists.';
  end if;

  if exists (
    select 1
    from public.project_actual_cost_events e
    where e.organization_id = p_organization_id
      and e.supplier_invoice_id = p_supplier_invoice_id
      and e.event_status = 'posted'
  ) then
    raise exception 'This invoice cannot be deleted because it has posted actual costs. Reverse those costs before deleting the invoice.';
  end if;

  select *
  into v_accounting_document
  from public.organization_accounting_documents d
  where d.organization_id = p_organization_id
    and d.local_document_type = 'supplier_invoice'
    and d.local_document_id = p_supplier_invoice_id
  order by d.created_at desc
  limit 1
  for update;

  if found then
    if coalesce(v_accounting_document.amount_paid, 0) > 0
      or v_accounting_document.fully_paid_at is not null
      or coalesce(v_accounting_document.normalized_external_status, '') in ('partially_paid', 'paid') then
      raise exception 'This Supplier Invoice cannot be deleted because a payment has been recorded against its Xero Bill.';
    end if;

    if v_accounting_document.external_document_id is not null
      or coalesce(v_accounting_document.export_status, '') in ('exported', 'attention_required')
      or coalesce(v_accounting_document.normalized_external_status, '') <> '' then
      raise exception 'This Supplier Invoice cannot be deleted because it has already been exported to Xero.';
    end if;

    raise exception 'This Supplier Invoice cannot be deleted because its Xero Bill export is queued or complete.';
  end if;

  select coalesce(array_agg(distinct d.file_path) filter (where char_length(trim(coalesce(d.file_path, ''))) > 0), '{}'::text[])
  into v_storage_paths
  from public.supplier_invoice_documents d
  where d.organization_id = p_organization_id
    and d.supplier_invoice_id = p_supplier_invoice_id;

  delete from public.supplier_invoice_site_review_decisions
  where organization_id = p_organization_id
    and supplier_invoice_id = p_supplier_invoice_id;

  delete from public.supplier_invoice_accounts_approvals
  where organization_id = p_organization_id
    and supplier_invoice_id = p_supplier_invoice_id;

  delete from public.supplier_invoice_site_review_submissions
  where organization_id = p_organization_id
    and supplier_invoice_id = p_supplier_invoice_id;

  delete from public.supplier_invoice_commercial_variances
  where organization_id = p_organization_id
    and supplier_invoice_id = p_supplier_invoice_id;

  delete from public.supplier_invoice_commercial_line_snapshots
  where organization_id = p_organization_id
    and supplier_invoice_id = p_supplier_invoice_id;

  delete from public.supplier_invoice_commercial_approvals
  where organization_id = p_organization_id
    and supplier_invoice_id = p_supplier_invoice_id;

  delete from public.supplier_invoice_approval_steps
  where organization_id = p_organization_id
    and supplier_invoice_id = p_supplier_invoice_id;

  delete from public.supplier_invoice_activity_events
  where organization_id = p_organization_id
    and supplier_invoice_id = p_supplier_invoice_id;

  delete from public.supplier_invoice_document_extractions
  where organization_id = p_organization_id
    and supplier_invoice_id = p_supplier_invoice_id;

  delete from public.supplier_invoice_purchase_order_matches
  where organization_id = p_organization_id
    and supplier_invoice_id = p_supplier_invoice_id;

  delete from public.supplier_invoice_line_allocations
  where organization_id = p_organization_id
    and supplier_invoice_id = p_supplier_invoice_id;

  delete from public.supplier_invoice_documents
  where organization_id = p_organization_id
    and supplier_invoice_id = p_supplier_invoice_id;

  delete from public.supplier_invoice_lines
  where organization_id = p_organization_id
    and supplier_invoice_id = p_supplier_invoice_id;

  delete from public.supplier_invoices
  where organization_id = p_organization_id
    and id = p_supplier_invoice_id;

  if not found then
    raise exception 'The Supplier Invoice could not be deleted. No records were removed.';
  end if;

  return jsonb_build_object(
    'deletedInvoiceId', p_supplier_invoice_id,
    'storagePaths', to_jsonb(v_storage_paths)
  );
end;
$$;


ALTER FUNCTION "public"."delete_supplier_invoice"("p_organization_id" "uuid", "p_supplier_invoice_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."delete_task_attachment"("p_attachment_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  actor_user_id uuid := auth.uid();
  old_attachment public.task_attachments%rowtype;
  updated_attachment public.task_attachments%rowtype;
  task_row public.project_job_todos%rowtype;
begin
  select *
  into old_attachment
  from public.task_attachments a
  where a.id = p_attachment_id;

  if old_attachment.id is null then
    raise exception 'Task attachment not found';
  end if;

  task_row := public._task_assert_task_access(old_attachment.task_id);

  update public.task_attachments a
  set
    deleted_at = coalesce(a.deleted_at, now()),
    deleted_by = coalesce(a.deleted_by, actor_user_id)
  where a.id = old_attachment.id
  returning * into updated_attachment;

  perform public._write_task_activity(
    task_row.organization_id,
    task_row.id,
    task_row.project_id,
    actor_user_id,
    'attachment_removed',
    null,
    to_jsonb(old_attachment.id),
    null,
    jsonb_build_object(
      'attachmentId', old_attachment.id,
      'fileName', old_attachment.file_name,
      'storagePath', old_attachment.storage_path
    )
  );

  return public._task_attachment_to_json(updated_attachment);
end;
$$;


ALTER FUNCTION "public"."delete_task_attachment"("p_attachment_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."delete_task_comment"("p_comment_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  actor_user_id uuid := auth.uid();
  old_comment public.task_comments%rowtype;
  updated_comment public.task_comments%rowtype;
begin
  select *
  into old_comment
  from public.task_comments c
  where c.id = p_comment_id;

  if old_comment.id is null then
    raise exception 'Comment not found';
  end if;

  perform public._task_assert_task_access(old_comment.task_id);

  update public.task_comments c
  set
    deleted_at = now(),
    deleted_by = actor_user_id
  where c.id = p_comment_id
  returning * into updated_comment;

  perform public._write_task_activity(updated_comment.organization_id, updated_comment.task_id, updated_comment.project_id, actor_user_id, 'comment_deleted', null, to_jsonb(old_comment.id), null, jsonb_build_object('commentId', updated_comment.id));

  return jsonb_build_object(
    'id', updated_comment.id,
    'deletedAt', updated_comment.deleted_at,
    'deletedBy', updated_comment.deleted_by
  );
end;
$$;


ALTER FUNCTION "public"."delete_task_comment"("p_comment_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."derive_material_estimating_price"("p_supplier_price_id" "uuid", "p_source_unit_cost" numeric, "p_source_unit" "text", "p_currency" "text", "p_source_tax_basis" "text", "p_source_tax_rate" numeric, "p_tax_jurisdiction_code" "text", "p_comparison_tax_basis" "text", "p_comparison_tax_rate" numeric, "p_tax_policy_snapshot" "jsonb", "p_price_effective_from" timestamp with time zone, "p_material_unit" "text", "p_organization_currency" "text", "p_evaluated_at" timestamp with time zone, "p_conversion_id" "uuid" DEFAULT NULL::"uuid", "p_conversion_supplier_quantity" numeric DEFAULT NULL::numeric, "p_conversion_supplier_unit" "text" DEFAULT NULL::"text", "p_conversion_material_quantity" numeric DEFAULT NULL::numeric, "p_conversion_material_unit" "text" DEFAULT NULL::"text", "p_conversion_source" "text" DEFAULT NULL::"text", "p_conversion_contract_version" "text" DEFAULT NULL::"text", "p_conversion_effective_from" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_conversion_confirmed_at" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" IMMUTABLE PARALLEL SAFE
    SET "search_path" TO ''
    AS $$
declare
  v_currency text := upper(btrim(coalesce(p_currency, '')));
  v_status text;
  v_normalized numeric;
  v_rate numeric := p_comparison_tax_rate;
  v_source_unit text := public.normalize_material_estimating_unit(p_source_unit);
  v_material_unit text := public.normalize_material_estimating_unit(p_material_unit);
  v_direct boolean;
  v_unit_cost numeric;
  v_derivation text;
  v_conversion jsonb := null;
  v_source jsonb;
begin
  v_source := jsonb_build_object(
    'supplierPriceId', p_supplier_price_id, 'unitCost', p_source_unit_cost,
    'unit', p_source_unit, 'currency', v_currency,
    'sourceTaxBasis', p_source_tax_basis, 'sourceTaxRate', p_source_tax_rate,
    'taxJurisdictionCode', p_tax_jurisdiction_code,
    'comparisonTaxBasis', p_comparison_tax_basis, 'comparisonTaxRate', p_comparison_tax_rate,
    'effectiveFrom', p_price_effective_from
  );

  if v_currency is distinct from upper(btrim(coalesce(p_organization_currency, ''))) then
    v_status := 'currency_incompatible';
  elsif p_source_tax_basis = 'unknown' then
    v_status := 'tax_incompatible';
  elsif p_tax_jurisdiction_code is null or p_comparison_tax_basis is null or p_comparison_tax_rate is null then
    v_status := 'missing_tax_policy';
  elsif coalesce((p_tax_policy_snapshot->>'supportsInclusiveExclusive')::boolean, false) is not true then
    v_status := 'tax_incompatible';
  elsif p_source_tax_basis in ('inclusive', 'exclusive') and p_source_tax_rate is not null
    and abs(p_source_tax_rate - p_comparison_tax_rate) > 0.0001 then
    v_status := 'tax_incompatible';
  else
    v_normalized := case when p_source_tax_basis = 'inclusive'
      then round(p_source_unit_cost / (1 + v_rate / 100), 6)
      else p_source_unit_cost end;
    if p_comparison_tax_basis = 'inclusive'
      and p_source_tax_basis not in ('zero_rated', 'exempt', 'no_tax') then
      v_normalized := round(v_normalized * (1 + v_rate / 100), 6);
    end if;

    v_direct := v_source_unit = v_material_unit;
    if v_direct then
      v_status := 'available'; v_derivation := 'direct_unit_match'; v_unit_cost := v_normalized;
    elsif p_conversion_id is null
      or public.normalize_material_estimating_unit(p_conversion_supplier_unit) <> v_source_unit
      or public.normalize_material_estimating_unit(p_conversion_material_unit) <> v_material_unit
      or coalesce(p_conversion_supplier_quantity, 0) <= 0
      or coalesce(p_conversion_material_quantity, 0) <= 0
      or p_conversion_source not in ('user_confirmed_ai', 'user_confirmed_manual') then
      v_status := 'conversion_required';
    else
      v_status := 'available'; v_derivation := 'confirmed_conversion';
      v_unit_cost := v_normalized * p_conversion_supplier_quantity / p_conversion_material_quantity;
      v_conversion := jsonb_build_object(
        'conversionId', p_conversion_id, 'supplierQuantity', p_conversion_supplier_quantity,
        'supplierUnit', p_conversion_supplier_unit, 'materialQuantity', p_conversion_material_quantity,
        'materialUnit', p_conversion_material_unit, 'confirmationSource', p_conversion_source,
        'contractVersion', p_conversion_contract_version, 'effectiveFrom', p_conversion_effective_from,
        'confirmedAt', p_conversion_confirmed_at
      );
    end if;
  end if;

  return jsonb_build_object(
    'sourcePricing', v_source,
    'estimatingPricing', jsonb_build_object(
      'status', v_status, 'derivationKind', v_derivation,
      'normalizedSourceUnitCost', case when v_status in ('available', 'conversion_required') then v_normalized else null end,
      'unitCost', case when v_status = 'available' then v_unit_cost else null end,
      'unit', p_material_unit, 'currency', v_currency,
      'taxBasis', p_comparison_tax_basis,
      'calculationVersion', 'material_estimating_price_v1', 'evaluatedAt', p_evaluated_at
    ),
    'conversion', case when v_status = 'available' then v_conversion else null end
  );
end;
$$;


ALTER FUNCTION "public"."derive_material_estimating_price"("p_supplier_price_id" "uuid", "p_source_unit_cost" numeric, "p_source_unit" "text", "p_currency" "text", "p_source_tax_basis" "text", "p_source_tax_rate" numeric, "p_tax_jurisdiction_code" "text", "p_comparison_tax_basis" "text", "p_comparison_tax_rate" numeric, "p_tax_policy_snapshot" "jsonb", "p_price_effective_from" timestamp with time zone, "p_material_unit" "text", "p_organization_currency" "text", "p_evaluated_at" timestamp with time zone, "p_conversion_id" "uuid", "p_conversion_supplier_quantity" numeric, "p_conversion_supplier_unit" "text", "p_conversion_material_quantity" numeric, "p_conversion_material_unit" "text", "p_conversion_source" "text", "p_conversion_contract_version" "text", "p_conversion_effective_from" timestamp with time zone, "p_conversion_confirmed_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."derive_supplier_invoice_commercial_snapshot_tax"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tax_resolution_status text;
  v_effective_rate numeric;
begin
  select
    allocation.tax_resolution_status,
    tax_rate.effective_rate
  into
    v_tax_resolution_status,
    v_effective_rate
  from public.supplier_invoice_line_allocations allocation
  left join public.organization_accounting_tax_rates tax_rate
    on tax_rate.id = allocation.accounting_tax_rate_id
    and tax_rate.organization_id = allocation.organization_id
    and tax_rate.is_active = true
  where allocation.id = new.allocation_id
    and allocation.organization_id = new.organization_id
    and allocation.supplier_invoice_id = new.supplier_invoice_id;

  if not found then
    raise exception 'The commercial snapshot allocation could not be resolved.';
  end if;

  if v_tax_resolution_status = 'not_applicable' then
    new.tax_amount := 0;
  elsif v_tax_resolution_status = 'resolved' and v_effective_rate is not null then
    new.tax_amount := round(new.amount * v_effective_rate / 100, 2);
  else
    raise exception 'The commercial snapshot requires a resolved Xero tax treatment.';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."derive_supplier_invoice_commercial_snapshot_tax"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."distribute_opportunity_primary_quote_core_v1"("p_organization_id" "uuid", "p_opportunity_id" "uuid", "p_recipient_client_id" "uuid") RETURNS TABLE("series_id" "uuid", "revision_id" "uuid", "base_quote_number" "text", "revision_number" integer, "created" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
declare
  actor_user_id uuid := auth.uid();
  opportunity public.organization_opportunities%rowtype;
  recipient public.organization_clients%rowtype;
  primary_series public.opportunity_quote_series%rowtype;
  source_quote public.project_quotes%rowtype;
  existing_series public.opportunity_quote_series%rowtype;
  created_series public.opportunity_quote_series%rowtype;
  created_quote public.project_quotes%rowtype;
  source_workbook public.opportunity_pricing_worksheets%rowtype;
  source_sheet public.opportunity_pricing_workbook_sheets%rowtype;
  created_workbook_id uuid;
  display_ref text;
  prefix text;
  next_sequence integer;
  resolved_number text;
  snapshot_hash text;
begin
  if actor_user_id is null or not public.has_org_permission(p_organization_id, 'quotes.write') then
    raise exception 'Not authorized for this organization' using errcode = '42501';
  end if;
  select * into opportunity from public.organization_opportunities candidate
  where candidate.organization_id = p_organization_id and candidate.id = p_opportunity_id for update;
  if not found or opportunity.client_id is null
    or opportunity.converted_at is not null or opportunity.stage = 'Won'
  then raise exception 'Opportunity and Primary Client are required for quotation creation' using errcode = 'TS422'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_organization_id::text || ':' || p_opportunity_id::text, 0));
  select * into existing_series from public.opportunity_quote_series series
  where series.organization_id = p_organization_id and series.opportunity_id = p_opportunity_id
    and series.recipient_client_id = p_recipient_client_id and series.archived_at is null
  order by series.created_at limit 1;
  if found then
    return query select existing_series.id, existing_series.current_revision_id,
      existing_series.base_quote_number,
      coalesce((select quote.revision_number from public.project_quotes quote
        where quote.id = existing_series.current_revision_id), 1), false;
    return;
  end if;
  if not exists (select 1 from public.opportunity_tender_clients tender
    where tender.organization_id = p_organization_id and tender.opportunity_id = p_opportunity_id
      and tender.client_id = p_recipient_client_id and tender.archived_at is null)
  then raise exception 'Recipient must be an active Tender Client' using errcode = 'TS422'; end if;
  select * into recipient from public.organization_clients client
  where client.organization_id = p_organization_id and client.id = p_recipient_client_id;
  if not found then raise exception 'Recipient client was not found' using errcode = 'TS422'; end if;

  display_ref := coalesce(nullif(opportunity.opportunity_code, ''),
    upper(left(regexp_replace(opportunity.slug, '[^a-zA-Z0-9]', '', 'g'), 8)));
  prefix := 'Q-' || display_ref || '-';

  -- base_quote_number is unique for the whole organization, so allocation must
  -- be serialized and calculated at that same scope. Include project_quotes to
  -- avoid colliding with legacy/non-series quote numbers that share the prefix.
  perform pg_advisory_xact_lock(
    hashtextextended('opportunity-quote-number:' || p_organization_id::text || ':' || lower(prefix), 0)
  );
  select coalesce(max(candidate.sequence_number), 0) + 1
  into next_sequence
  from (
    select (regexp_match(series.base_quote_number,
      '^' || regexp_replace(prefix, '([.\\+*?\[\](){}|^$])', '\\\1', 'g') || '([0-9]+)$'))[1]::integer
      as sequence_number
    from public.opportunity_quote_series series
    where series.organization_id = p_organization_id
    union all
    select (regexp_match(quote.quote_number,
      '^' || regexp_replace(prefix, '([.\\+*?\[\](){}|^$])', '\\\1', 'g') || '([0-9]+)$'))[1]::integer
      as sequence_number
    from public.project_quotes quote
    where quote.organization_id = p_organization_id
  ) candidate;
  resolved_number := prefix || next_sequence::text;

  if p_recipient_client_id <> opportunity.client_id then
    select * into primary_series from public.opportunity_quote_series series
    where series.organization_id = p_organization_id and series.opportunity_id = p_opportunity_id
      and series.recipient_client_id = opportunity.client_id and series.archived_at is null
    order by series.created_at limit 1;
    if not found or primary_series.current_revision_id is null then
      raise exception 'Create the Primary Client quote before creating Tender Client quotes' using errcode = 'TS422';
    end if;
    select * into source_quote from public.project_quotes quote
    where quote.organization_id = p_organization_id and quote.id = primary_series.current_revision_id
      and quote.quote_series_id = primary_series.id;
    if not found then raise exception 'Primary Client current quote revision is unavailable' using errcode = 'TS409'; end if;
    snapshot_hash := public.opportunity_quote_snapshot_hash_v1(p_organization_id, source_quote.id);
  end if;

  insert into public.opportunity_quote_series (
    organization_id, opportunity_id, recipient_client_id, base_quote_number,
    display_reference, source_quote_revision_id, source_quote_updated_at, source_quote_hash, created_by
  ) values (
    p_organization_id, p_opportunity_id, recipient.id, resolved_number, display_ref,
    source_quote.id, source_quote.updated_at, snapshot_hash, actor_user_id
  ) returning * into created_series;

  if p_recipient_client_id = opportunity.client_id then
    insert into public.project_quotes (
      organization_id, project_id, originating_opportunity_id, source_opportunity_id,
      created_by, quote_title, quote_number, client_name, company_name, contact_person,
      client_email, client_phone, site_address, project_name, quote_date, status,
      validity_period, revision_number, revision_kind, revision_created_by, quote_series_id
    ) values (
      p_organization_id, null, p_opportunity_id, p_opportunity_id, actor_user_id,
      opportunity.name || ' Quotation', resolved_number, recipient.name,
      coalesce(recipient.company_name, ''), recipient.name, coalesce(recipient.email, ''),
      coalesce(recipient.phone, ''), opportunity.location, opportunity.name, current_date,
      'Draft', '30 days', 1, 'tender', actor_user_id, created_series.id
    ) returning * into created_quote;
  else
    insert into public.project_quotes (
      organization_id, project_id, originating_opportunity_id, source_opportunity_id,
      source_opportunity_quote_id, source_opportunity_quote_number, created_by,
      quote_title, quote_number, client_name, company_name, contact_person, client_email,
      client_phone, site_address, project_name, quote_date, expiry_date, status,
      optional_items_notes, scope_exclusions, assumptions, scope_notes, subtotal,
      optional_subtotal, margin_percent, margin_amount, discount_amount, contingency_amount,
      gst_percent, gst_amount, total_quote_price, validity_period, payment_terms,
      retention_percent_default, lead_time, terms_inclusions, terms_exclusions,
      clarifications, acceptance_notes, revision_number, revision_kind,
      revision_created_by, pricing_basis_status, quote_series_id,
      source_quote_revision_id, source_quote_updated_at, source_quote_hash
    ) values (
      p_organization_id, null, p_opportunity_id, p_opportunity_id,
      source_quote.source_opportunity_quote_id, source_quote.source_opportunity_quote_number, actor_user_id,
      source_quote.quote_title, resolved_number, recipient.name, coalesce(recipient.company_name, ''),
      recipient.name, coalesce(recipient.email, ''), coalesce(recipient.phone, ''),
      source_quote.site_address, source_quote.project_name, current_date, source_quote.expiry_date, 'Draft',
      source_quote.optional_items_notes, source_quote.scope_exclusions, source_quote.assumptions,
      source_quote.scope_notes, source_quote.subtotal, source_quote.optional_subtotal,
      source_quote.margin_percent, source_quote.margin_amount, source_quote.discount_amount,
      source_quote.contingency_amount, source_quote.gst_percent, source_quote.gst_amount,
      source_quote.total_quote_price, source_quote.validity_period, source_quote.payment_terms,
      source_quote.retention_percent_default, source_quote.lead_time, source_quote.terms_inclusions,
      source_quote.terms_exclusions, source_quote.clarifications, source_quote.acceptance_notes,
      1, 'tender', actor_user_id, 'unpublished', created_series.id,
      source_quote.id, source_quote.updated_at, snapshot_hash
    ) returning * into created_quote;

    insert into public.project_quote_line_items (
      id, organization_id, project_id, quote_id, section, description, quantity, unit,
      rate, total, is_optional, sort_order, source_opportunity_quote_id,
      source_opportunity_quote_line_item_id, source_opportunity_quote_number, pricing_source_kind
    ) select md5(created_quote.id::text || ':source-line:' || line.id::text)::uuid,
      line.organization_id, null, created_quote.id, line.section, line.description,
      line.quantity, line.unit, line.rate, line.total, line.is_optional, line.sort_order,
      line.source_opportunity_quote_id, line.source_opportunity_quote_line_item_id,
      line.source_opportunity_quote_number, line.pricing_source_kind
    from public.project_quote_line_items line
    where line.organization_id = p_organization_id and line.quote_id = source_quote.id;

    insert into public.commercial_item_document_links (
      id, organization_id, commercial_item_id, document_kind, document_id,
      document_line_id, link_role, snapshot_at_link_json, created_by, created_at
    ) select md5(created_quote.id::text || ':source-link:' || link.id::text)::uuid,
      link.organization_id, link.commercial_item_id, link.document_kind, created_quote.id,
      case when link.document_line_id is null then null
        else md5(created_quote.id::text || ':source-line:' || link.document_line_id::text)::uuid end,
      link.link_role, link.snapshot_at_link_json, actor_user_id, timezone('utc', now())
    from public.commercial_item_document_links link
    where link.organization_id = p_organization_id
      and link.document_kind = 'quote_line' and link.document_id = source_quote.id;

    for source_workbook in select * from public.opportunity_pricing_worksheets workbook
      where workbook.organization_id = p_organization_id and workbook.quote_id = source_quote.id
        and workbook.variation_id is null and workbook.archived_at is null
    loop
      created_workbook_id := md5(created_quote.id::text || ':source-workbook:' || source_workbook.id::text)::uuid;
      insert into public.opportunity_pricing_worksheets (
        id, organization_id, opportunity_id, project_id, quote_id, variation_id, name,
        trade_package, sort_order, archived_at, worksheet_data, pricing_summary,
        extracted_pricing_data, version, created_by, updated_by, source_workbook_id,
        source_workbook_version, source_award_manifest_id, source_quote_id, clone_kind
      ) values (
        created_workbook_id, p_organization_id, source_workbook.opportunity_id, null,
        created_quote.id, null, source_workbook.name, source_workbook.trade_package,
        source_workbook.sort_order, null,
        public.regenerate_worksheet_material_binding_ids(source_workbook.worksheet_data),
        source_workbook.pricing_summary, source_workbook.extracted_pricing_data,
        source_workbook.version, actor_user_id, actor_user_id, source_workbook.id,
        source_workbook.version, source_workbook.source_award_manifest_id, source_quote.id,
        'quote_revision'
      );
      for source_sheet in select * from public.opportunity_pricing_workbook_sheets sheet
        where sheet.organization_id = p_organization_id and sheet.workbook_id = source_workbook.id
      loop
        insert into public.opportunity_pricing_workbook_sheets (
          id, workbook_id, organization_id, opportunity_id, name, sheet_order, is_default,
          worksheet_data, pricing_summary, extracted_pricing_data, version, created_by, updated_by
        ) values (
          md5(created_quote.id::text || ':source-sheet:' || source_sheet.id::text)::uuid,
          created_workbook_id, p_organization_id, source_sheet.opportunity_id, source_sheet.name,
          source_sheet.sheet_order, source_sheet.is_default,
          public.regenerate_worksheet_material_binding_ids(source_sheet.worksheet_data),
          source_sheet.pricing_summary, source_sheet.extracted_pricing_data,
          source_sheet.version, actor_user_id, actor_user_id
        );
      end loop;
    end loop;
  end if;
  update public.opportunity_quote_series set current_revision_id = created_quote.id
  where organization_id = p_organization_id and id = created_series.id;
  return query select created_series.id, created_quote.id, resolved_number, 1, true;
end;
$_$;


ALTER FUNCTION "public"."distribute_opportunity_primary_quote_core_v1"("p_organization_id" "uuid", "p_opportunity_id" "uuid", "p_recipient_client_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."document_cleanup_storage_object_exists"("p_job_id" "uuid", "p_claim_token" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'storage'
    AS $$
declare
  job_row public.document_storage_cleanup_jobs%rowtype;
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'Service role required.'
      using errcode = '42501';
  end if;

  select *
  into job_row
  from public.document_storage_cleanup_jobs job
  where job.id = p_job_id
    and job.processing_status = 'claimed'
    and job.claim_token = p_claim_token
    and job.claim_expires_at > now();

  if not found then
    raise exception 'Cleanup lease is not owned.'
      using errcode = '42501';
  end if;

  return exists (
    select 1
    from storage.objects object
    where object.bucket_id = job_row.storage_bucket
      and object.name = job_row.storage_key
  );
end;
$$;


ALTER FUNCTION "public"."document_cleanup_storage_object_exists"("p_job_id" "uuid", "p_claim_token" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."document_upload_mime_extension_allowed"("p_mime_type" "text", "p_extension" "text") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
  select (lower(btrim(coalesce(p_mime_type, ''))), lower(btrim(coalesce(p_extension, ''))))
    in (
      ('application/pdf', 'pdf'),
      ('text/plain', 'txt'),
      ('text/csv', 'csv'),
      ('image/jpeg', 'jpg'),
      ('image/jpeg', 'jpeg'),
      ('image/png', 'png'),
      ('image/webp', 'webp'),
      ('application/msword', 'doc'),
      ('application/vnd.openxmlformats-officedocument.wordprocessingml.document', 'docx'),
      ('application/vnd.ms-excel', 'xls'),
      ('application/vnd.openxmlformats-officedocument.spreadsheetml.sheet', 'xlsx'),
      ('application/vnd.ms-powerpoint', 'ppt'),
      ('application/vnd.openxmlformats-officedocument.presentationml.presentation', 'pptx')
    );
$$;


ALTER FUNCTION "public"."document_upload_mime_extension_allowed"("p_mime_type" "text", "p_extension" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."document_version_usage_bucket"("p_upload_state" "text", "p_byte_size" bigint, "p_node_deleted_at" timestamp with time zone) RETURNS TABLE("active_bytes" bigint, "deleted_bytes" bigint, "pending_bytes" bigint)
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
  select
    case
      when p_upload_state in ('active', 'purge_pending')
        and p_node_deleted_at is null
      then coalesce(p_byte_size, 0)
      else 0
    end,
    case
      when p_upload_state in ('active', 'purge_pending')
        and p_node_deleted_at is not null
      then coalesce(p_byte_size, 0)
      else 0
    end,
    case
      when p_upload_state in ('pending', 'uploaded')
      then coalesce(p_byte_size, 0)
      else 0
    end;
$$;


ALTER FUNCTION "public"."document_version_usage_bucket"("p_upload_state" "text", "p_byte_size" bigint, "p_node_deleted_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."duplicate_opportunity_pricing_workbook"("p_organization_id" "uuid", "p_opportunity_id" "uuid", "p_workbook_id" "uuid", "p_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  v_source_workbook public.opportunity_pricing_worksheets%rowtype;
  v_default_source_sheet public.opportunity_pricing_workbook_sheets%rowtype;
  v_inserted_workbook public.opportunity_pricing_worksheets%rowtype;
  v_inserted_default_sheet public.opportunity_pricing_workbook_sheets%rowtype;
  v_inserted_sheet public.opportunity_pricing_workbook_sheets%rowtype;
  v_sheet_record public.opportunity_pricing_workbook_sheets%rowtype;
  v_duplicate_name text;
  v_parent_worksheet_data jsonb;
  v_sheet_worksheet_data jsonb;
  v_parent_pricing_summary jsonb;
  v_parent_extracted_pricing_data jsonb;
  v_parent_version integer;
  v_payload_sheets jsonb := '[]'::jsonb;
begin
  if auth.uid() is null or p_user_id is distinct from auth.uid() then
    raise exception 'Pricing worksheet actor mismatch.' using errcode = '42501';
  end if;

  select *
  into v_source_workbook
  from public.opportunity_pricing_worksheets
  where id = p_workbook_id
    and organization_id = p_organization_id
    and opportunity_id = p_opportunity_id
    and archived_at is null;

  if not found then
    raise exception 'Pricing worksheet not found.';
  end if;

  select *
  into v_default_source_sheet
  from public.opportunity_pricing_workbook_sheets sheet
  where sheet.workbook_id = p_workbook_id
    and sheet.organization_id = p_organization_id
    and sheet.opportunity_id = p_opportunity_id
  order by sheet.is_default desc, sheet.sheet_order asc, sheet.created_at asc
  limit 1;

  v_duplicate_name := public._normalize_opportunity_pricing_workbook_name(
    v_source_workbook.name || ' Copy',
    'Worksheet Copy'
  );

  if v_default_source_sheet.id is null then
    v_parent_worksheet_data := public.regenerate_worksheet_material_binding_ids(
      public._sync_opportunity_pricing_workbook_sheet_name(
        v_source_workbook.worksheet_data,
        coalesce(nullif(trim(v_source_workbook.name), ''), 'Pricing Worksheet')
      )
    );
    v_parent_pricing_summary := v_source_workbook.pricing_summary;
    v_parent_extracted_pricing_data := v_source_workbook.extracted_pricing_data;
    v_parent_version := greatest(coalesce(v_source_workbook.version, 1), 1);
  else
    v_parent_worksheet_data := public.regenerate_worksheet_material_binding_ids(
      public._sync_opportunity_pricing_workbook_sheet_name(
        v_default_source_sheet.worksheet_data,
        v_default_source_sheet.name
      )
    );
    v_parent_pricing_summary := v_default_source_sheet.pricing_summary;
    v_parent_extracted_pricing_data := v_default_source_sheet.extracted_pricing_data;
    v_parent_version := greatest(coalesce(v_default_source_sheet.version, 1), 1);
  end if;

  insert into public.opportunity_pricing_worksheets (
    organization_id,
    opportunity_id,
    name,
    trade_package,
    worksheet_data,
    pricing_summary,
    extracted_pricing_data,
    version,
    created_by,
    updated_by
  )
  values (
    p_organization_id,
    p_opportunity_id,
    v_duplicate_name,
    v_source_workbook.trade_package,
    v_parent_worksheet_data,
    coalesce(v_parent_pricing_summary, '{}'::jsonb),
    coalesce(v_parent_extracted_pricing_data, '{}'::jsonb),
    v_parent_version,
    p_user_id,
    p_user_id
  )
  returning * into v_inserted_workbook;

  if v_default_source_sheet.id is null then
    insert into public.opportunity_pricing_workbook_sheets (
      workbook_id, organization_id, opportunity_id, name, sheet_order, is_default,
      worksheet_data, pricing_summary, extracted_pricing_data, version, created_by, updated_by
    )
    values (
      v_inserted_workbook.id,
      p_organization_id,
      p_opportunity_id,
      coalesce(nullif(trim(v_source_workbook.name), ''), 'Pricing Worksheet'),
      0,
      true,
      v_parent_worksheet_data,
      coalesce(v_parent_pricing_summary, '{}'::jsonb),
      coalesce(v_parent_extracted_pricing_data, '{}'::jsonb),
      v_parent_version,
      p_user_id,
      p_user_id
    )
    returning * into v_inserted_default_sheet;

    v_payload_sheets := jsonb_build_array(to_jsonb(v_inserted_default_sheet));
  else
    for v_sheet_record in
      select *
      from public.opportunity_pricing_workbook_sheets sheet
      where sheet.workbook_id = p_workbook_id
        and sheet.organization_id = p_organization_id
        and sheet.opportunity_id = p_opportunity_id
      order by sheet.sheet_order asc, sheet.created_at asc
    loop
      v_sheet_worksheet_data := case
        when v_sheet_record.id = v_default_source_sheet.id then v_parent_worksheet_data
        else public.regenerate_worksheet_material_binding_ids(
          public._sync_opportunity_pricing_workbook_sheet_name(
            v_sheet_record.worksheet_data,
            v_sheet_record.name
          )
        )
      end;

      insert into public.opportunity_pricing_workbook_sheets (
        workbook_id, organization_id, opportunity_id, name, sheet_order, is_default,
        worksheet_data, pricing_summary, extracted_pricing_data, version, created_by, updated_by
      )
      values (
        v_inserted_workbook.id,
        p_organization_id,
        p_opportunity_id,
        v_sheet_record.name,
        v_sheet_record.sheet_order,
        v_sheet_record.is_default,
        v_sheet_worksheet_data,
        coalesce(v_sheet_record.pricing_summary, '{}'::jsonb),
        coalesce(v_sheet_record.extracted_pricing_data, '{}'::jsonb),
        greatest(coalesce(v_sheet_record.version, 1), 1),
        p_user_id,
        p_user_id
      )
      returning * into v_inserted_sheet;

      v_payload_sheets := v_payload_sheets || jsonb_build_array(to_jsonb(v_inserted_sheet));
    end loop;
  end if;

  return jsonb_build_object(
    'workbook', to_jsonb(v_inserted_workbook),
    'sheets', v_payload_sheets
  );
end;
$$;


ALTER FUNCTION "public"."duplicate_opportunity_pricing_workbook"("p_organization_id" "uuid", "p_opportunity_id" "uuid", "p_workbook_id" "uuid", "p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."duplicate_pricing_workbook_v1"("p_organization_id" "uuid", "p_opportunity_id" "uuid", "p_project_id" "uuid", "p_workbook_id" "uuid", "p_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  source_workbook public.opportunity_pricing_worksheets%rowtype;
  payload jsonb;
  duplicate_id uuid;
  duplicated_workbook public.opportunity_pricing_worksheets%rowtype;
begin
  if auth.uid() is null or p_user_id is distinct from auth.uid() then
    raise exception 'Pricing worksheet actor mismatch.' using errcode = '42501';
  end if;

  select * into source_workbook from public.opportunity_pricing_worksheets candidate
  where candidate.id = p_workbook_id
    and candidate.organization_id = p_organization_id
    and candidate.opportunity_id = p_opportunity_id
    and candidate.archived_at is null
    and candidate.variation_id is null
    and (
      (p_project_id is null and candidate.project_id is null and candidate.quote_id is null)
      or (p_project_id is not null and candidate.project_id = p_project_id
        and (candidate.quote_id is null or candidate.clone_kind = 'project_working'))
    );

  if not found or not public.can_write_pricing_workbook_owner(
    source_workbook.organization_id, source_workbook.opportunity_id,
    source_workbook.project_id, source_workbook.quote_id, source_workbook.variation_id
  ) then
    raise exception 'Pricing worksheet not found or not writable.' using errcode = '42501';
  end if;

  payload := public.duplicate_opportunity_pricing_workbook(
    p_organization_id, p_opportunity_id, p_workbook_id, p_user_id
  );
  duplicate_id := (payload #>> '{workbook,id}')::uuid;

  if p_project_id is not null then
    update public.opportunity_pricing_worksheets
    set project_id = p_project_id, updated_by = p_user_id
    where id = duplicate_id returning * into duplicated_workbook;
  else
    select * into duplicated_workbook from public.opportunity_pricing_worksheets where id = duplicate_id;
  end if;

  return jsonb_set(payload, '{workbook}', to_jsonb(duplicated_workbook), false);
end;
$$;


ALTER FUNCTION "public"."duplicate_pricing_workbook_v1"("p_organization_id" "uuid", "p_opportunity_id" "uuid", "p_project_id" "uuid", "p_workbook_id" "uuid", "p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."duplicate_qa_template_v1"("p_organization_id" "uuid", "p_template_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare source public.qa_templates%rowtype; result_id uuid; s record; f record; o record; new_section uuid; new_field uuid; section_map jsonb := '{}'::jsonb; field_map jsonb := '{}'::jsonb;
begin
  if auth.uid() is null or not public.has_org_permission(p_organization_id,'qa.templates.write') then raise exception 'Not authorized' using errcode='42501'; end if;
  select * into source from public.qa_templates where organization_id=p_organization_id and id=p_template_id;
  if not found then raise exception 'QA template not found' using errcode='TS404'; end if;
  insert into public.qa_templates(organization_id,name,description,status,created_by,updated_by)
  values(p_organization_id,left(source.name || ' copy',160),source.description,'draft',auth.uid(),auth.uid()) returning id into result_id;
  for s in select * from public.qa_template_sections where organization_id=p_organization_id and template_id=source.id order by sort_order loop
    new_section:=gen_random_uuid(); section_map:=section_map||jsonb_build_object(s.id::text,new_section::text);
    insert into public.qa_template_sections(id,organization_id,template_id,title,description,sort_order) values(new_section,p_organization_id,result_id,s.title,s.description,s.sort_order);
  end loop;
  for f in select * from public.qa_template_fields where organization_id=p_organization_id and template_id=source.id order by section_id,sort_order loop
    new_field:=gen_random_uuid(); field_map:=field_map||jsonb_build_object(f.id::text,new_field::text);
    insert into public.qa_template_fields(id,organization_id,template_id,section_id,field_type,label,description,instructions,required,allow_na,requirement,acceptance_criteria,reference_text,photo_required,minimum_photos,file_required,require_comment_on_fail,require_photo_on_fail,create_issue_on_fail,require_rectification_on_fail,block_completion_on_fail,require_supervisor_review_on_fail,ai_review_enabled,ai_review_instruction,include_in_report,configuration,configuration_schema_version,sort_order)
    values(new_field,p_organization_id,result_id,(section_map->>f.section_id::text)::uuid,f.field_type,f.label,f.description,f.instructions,f.required,f.allow_na,f.requirement,f.acceptance_criteria,f.reference_text,f.photo_required,f.minimum_photos,f.file_required,f.require_comment_on_fail,f.require_photo_on_fail,f.create_issue_on_fail,f.require_rectification_on_fail,f.block_completion_on_fail,f.require_supervisor_review_on_fail,f.ai_review_enabled,f.ai_review_instruction,f.include_in_report,f.configuration,f.configuration_schema_version,f.sort_order);
  end loop;
  for o in select * from public.qa_template_field_options where organization_id=p_organization_id and template_id=source.id order by field_id,sort_order loop
    insert into public.qa_template_field_options(organization_id,template_id,field_id,label,value,sort_order) values(p_organization_id,result_id,(field_map->>o.field_id::text)::uuid,o.label,o.value,o.sort_order);
  end loop;
  return result_id;
end; $$;


ALTER FUNCTION "public"."duplicate_qa_template_v1"("p_organization_id" "uuid", "p_template_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_commercial_approval_allocation_shape"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
begin
  if new.status <> 'approved' then
    return new;
  end if;

  if exists (
    select 1
    from public.supplier_invoice_lines line
    left join public.supplier_invoice_line_allocations allocation
      on allocation.supplier_invoice_id = line.supplier_invoice_id
      and allocation.supplier_invoice_line_id = line.id
    where line.supplier_invoice_id = new.supplier_invoice_id
    group by line.id
    having count(allocation.id) <> 1
  ) then
    raise exception 'Every invoice line must have exactly one active allocation.';
  end if;

  if exists (
    select 1
    from public.supplier_invoice_line_allocations allocation
    join public.supplier_invoice_lines invoice_line
      on invoice_line.id = allocation.supplier_invoice_line_id
    join public.project_purchase_order_line_items po_line
      on po_line.id = allocation.purchase_order_line_item_id
    where allocation.supplier_invoice_id = new.supplier_invoice_id
      and lower(regexp_replace(
        regexp_replace(trim(invoice_line.description), '\s*\(\s*remaining\s+balance\s*\)\s*$', '', 'i'),
        '\s+', ' ', 'g'
      )) <> lower(regexp_replace(
        regexp_replace(trim(po_line.description), '\s*\(\s*remaining\s+balance\s*\)\s*$', '', 'i'),
        '\s+', ' ', 'g'
      ))
      and not exists (
        select 1
        from jsonb_array_elements(coalesce(new.accepted_variances, '[]'::jsonb)) accepted
        where accepted ->> 'type' = 'unexpected_line'
          and accepted ->> 'purchaseOrderLineItemId' = po_line.id::text
          and char_length(trim(coalesce(accepted ->> 'note', ''))) > 0
      )
  ) then
    raise exception 'Accept and explain every invoice and purchase order line description variance.';
  end if;

  return new;
end;
$_$;


ALTER FUNCTION "public"."enforce_commercial_approval_allocation_shape"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_commercial_snapshot_po_limits"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_purchase_order_id uuid;
  v_ordered_quantity numeric;
  v_ordered_value numeric;
  v_approved_quantity numeric;
  v_approved_value numeric;
  v_released_value numeric;
begin
  if not exists (
    select 1
    from public.supplier_invoice_line_allocations allocation
    left join public.organization_tradesstack_accounting_mappings legacy_mapping
      on legacy_mapping.id = allocation.accounting_mapping_id
      and legacy_mapping.is_active
      and legacy_mapping.organization_id = new.organization_id
      and legacy_mapping.tradesstack_cost_code = allocation.tradesstack_cost_code
      and (legacy_mapping.project_id is null
        or legacy_mapping.project_id is not distinct from allocation.project_id)
    left join public.organization_accounting_route_mappings route_mapping
      on route_mapping.id = allocation.accounting_route_mapping_id
      and route_mapping.is_active
      and route_mapping.organization_id = new.organization_id
      and route_mapping.accounting_route = 'supplier_bill_expense'
      and route_mapping.organization_cost_code_id = allocation.organization_cost_code_id
      and (route_mapping.project_id is null
        or route_mapping.project_id is not distinct from allocation.project_id)
    where allocation.id = new.allocation_id
      and allocation.organization_id = new.organization_id
      and (
        legacy_mapping.id is not null
        or (
          allocation.accounting_route = 'supplier_bill_expense'
          and (
            route_mapping.id is not null
            or allocation.account_override_organization_cost_code_id
              = allocation.organization_cost_code_id
          )
        )
      )
  ) then
    raise exception 'The allocation accounting route and account mapping are not consistent.';
  end if;

  if new.purchase_order_line_item_id is null then
    return new;
  end if;

  select purchase_order_id, quantity, total
  into v_purchase_order_id, v_ordered_quantity, v_ordered_value
  from public.project_purchase_order_line_items
  where id = new.purchase_order_line_item_id;

  if not found then
    raise exception 'Purchase order line not found.';
  end if;

  perform 1
  from public.project_purchase_orders
  where id = v_purchase_order_id
  for update;

  select
    coalesce(sum(snapshot.quantity), 0),
    coalesce(sum(snapshot.amount), 0)
  into v_approved_quantity, v_approved_value
  from public.supplier_invoice_commercial_line_snapshots snapshot
  join public.supplier_invoice_commercial_approvals approval
    on approval.id = snapshot.commercial_approval_id
  where snapshot.purchase_order_line_item_id = new.purchase_order_line_item_id
    and approval.status = 'approved';

  select coalesce(sum(released_amount), 0)
  into v_released_value
  from public.purchase_order_commitment_release_lines
  where purchase_order_line_item_id = new.purchase_order_line_item_id;

  if v_approved_quantity + new.quantity > v_ordered_quantity + 0.001 then
    raise exception 'Commercial approval would over-invoice the purchase order line quantity.';
  end if;

  if v_approved_value + v_released_value + new.amount > v_ordered_value + 0.01 then
    raise exception 'Commercial approval would exceed the remaining purchase order line commitment.';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."enforce_commercial_snapshot_po_limits"() OWNER TO "postgres";


