    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
begin
  if not public.is_project_delivery_eligible_v1(
    old.organization_id,
    old.id
  ) then
    raise exception 'Project is not delivery-eligible for deletion'
      using errcode = 'TS409';
  end if;

  return old;
end;
