CREATE OR REPLACE FUNCTION "public"."enforce_document_storage_quota"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  usage_row public.organization_document_storage_usage%rowtype;
begin
  if new.upload_state not in ('pending', 'uploaded') then
    return new;
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended(
      'document-storage-quota:' || new.organization_id::text,
      0
    )
  );
  perform public.ensure_document_storage_usage_row(new.organization_id);

  select *
  into usage_row
  from public.organization_document_storage_usage usage
  where usage.organization_id = new.organization_id
  for update;

  if usage_row.active_bytes
      + usage_row.deleted_bytes
      + usage_row.pending_bytes
      + coalesce(new.byte_size, 0)
    > usage_row.quota_bytes
  then
    raise exception 'Document storage quota exceeded.'
      using errcode = 'P0001';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."enforce_document_storage_quota"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_material_supplier_price_interval"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if new.supplier_product_id is null then
    return new;
  end if;

  perform 1
  from public.organization_material_supplier_products
  where organization_id = new.organization_id
    and id = new.supplier_product_id
  for update;

  if not found then
    raise exception 'materials_phase1i:supplier_product_not_found' using errcode = '23503';
  end if;

  if exists (
    select 1
    from public.organization_material_supplier_prices price
    where price.organization_id = new.organization_id
      and price.supplier_product_id = new.supplier_product_id
      and price.id <> new.id
      and tstzrange(price.effective_from, price.effective_to, '[)')
          && tstzrange(new.effective_from, new.effective_to, '[)')
  ) then
    raise exception 'materials_phase1i:effective_price_interval_overlap' using errcode = '23P01';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."enforce_material_supplier_price_interval"() OWNER TO "postgres";


