CREATE OR REPLACE FUNCTION "public"."enforce_phase2a_revision_identity"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  document public.organization_accounting_documents%rowtype;
  previous_revision public.organization_accounting_document_revisions%rowtype;
  reservation public.organization_accounting_number_reservations%rowtype;
  resolved_project_id uuid;
  source_claim_number text;
begin
  select * into document
  from public.organization_accounting_documents d
  where d.id = new.accounting_document_id;
  if not found
    or document.organization_id <> new.organization_id
    or document.provider <> new.provider
    or document.tenant_id <> new.tenant_id
    or document.accounting_connection_id <> new.connection_id
    or document.local_document_type <> new.source_document_type
    or coalesce(
      document.project_claim_id,
      document.retention_claim_id,
      document.local_document_id
    ) <> new.source_document_id then
    raise exception 'Accounting revision identity does not match its stable document.'
      using errcode = '23514';
  end if;

  if new.source_document_type = 'project_claim' then
    select c.project_id, c.claim_number
      into resolved_project_id, source_claim_number
    from public.project_claims c
    where c.id = new.source_document_id
      and c.organization_id = new.organization_id;
  elsif new.source_document_type = 'retention_claim' then
    select c.project_id into resolved_project_id
    from public.retention_claims c
    where c.id = new.source_document_id
      and c.organization_id = new.organization_id;
  end if;
  if new.source_document_type in ('project_claim', 'retention_claim')
    and (resolved_project_id is null or new.project_id is distinct from resolved_project_id)
  then
    raise exception 'Accounting revision project does not match its source claim.'
      using errcode = '23514';
  end if;

  if new.revision_sequence = 1 then
    if new.previous_revision_id is not null then
      raise exception 'First accounting revision cannot have a predecessor.'
        using errcode = '23514';
    end if;
  else
    select * into previous_revision
    from public.organization_accounting_document_revisions r
    where r.id = new.previous_revision_id;
    if not found
      or previous_revision.accounting_document_id <> new.accounting_document_id
      or previous_revision.organization_id <> new.organization_id
      or previous_revision.revision_sequence <> new.revision_sequence - 1 then
      raise exception 'Accounting revision predecessor must be the prior revision of the same document.'
        using errcode = '23514';
    end if;
  end if;

  if new.source_document_type = 'project_claim'
    and new.revision_intent = 'legacy_import'
    and new.resolution_strategy = 'legacy_preservation'
    and new.number_reservation_id is null then
    if nullif(trim(source_claim_number), '') is null
      or new.external_document_number <> source_claim_number
      or nullif(trim(new.external_document_id), '') is null then
      raise exception 'Legacy Payment Claim identity must preserve its source claim number and Xero InvoiceID.'
        using errcode = '23514';
    end if;
  elsif new.source_document_type = 'project_claim'
    and document.integration_contract = 'payment_claim_revision_v1'
    and new.revision_intent = 'initial_push'
    and new.number_reservation_id is null then
    if nullif(trim(source_claim_number), '') is null
      or new.external_document_number <> source_claim_number then
      raise exception 'Phase 2B Payment Claim revision number must equal its source claim number.'
        using errcode = '23514';
    end if;
  elsif new.source_document_type = 'project_claim'
    and document.integration_contract = 'payment_claim_revision_v1'
    and new.revision_intent = 'direct_update'
    and new.resolution_strategy = 'update_existing'
    and new.number_reservation_id is null then
    if nullif(trim(source_claim_number), '') is null
      or new.external_document_number <> source_claim_number
      or previous_revision.id is null
      or previous_revision.external_document_number <> source_claim_number
      or previous_revision.number_reservation_id is not null then
      raise exception 'Payment Claim update must preserve its reservation-free claim-number identity.'
        using errcode = '23514';
    end if;
  elsif new.source_document_type in ('project_claim', 'retention_claim') then
    select * into reservation
    from public.organization_accounting_number_reservations n
    where n.id = new.number_reservation_id;
    if not found
      or reservation.organization_id <> new.organization_id
      or reservation.provider <> new.provider
      or reservation.tenant_id <> new.tenant_id
      or reservation.accounting_document_id <> new.accounting_document_id
      or reservation.source_document_type <> new.source_document_type
      or reservation.source_document_id <> new.source_document_id
      or reservation.formatted_number <> new.external_document_number then
      raise exception 'Accounting revision number reservation does not match its tenant and document.'
        using errcode = '23514';
    end if;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."enforce_phase2a_revision_identity"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_project_members_integrity"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  project_organization_id uuid;
  member_organization_id uuid;
begin
  if tg_op = 'INSERT' and new.is_active = false then
    raise exception 'Cannot insert inactive project member';
  end if;

  select p.organization_id
  into project_organization_id
  from public.organization_projects p
  where p.id = new.project_id;

  if project_organization_id is null then
    raise exception 'Project not found for project_members row';
  end if;

  select m.organization_id
  into member_organization_id
  from public.organization_members m
  where m.id = new.organization_member_id;

  if member_organization_id is null then
    raise exception 'Organization member not found for project_members row';
  end if;

  if new.organization_id <> project_organization_id then
    raise exception 'project_members.organization_id must match organization_projects.organization_id';
  end if;

  if new.organization_id <> member_organization_id then
    raise exception 'project_members.organization_id must match organization_members.organization_id';
  end if;

  if tg_op = 'UPDATE' then
    if new.organization_id <> old.organization_id then
      raise exception 'project_members.organization_id cannot be changed after insert';
    end if;

    if new.project_id <> old.project_id then
      raise exception 'project_members.project_id cannot be changed after insert';
    end if;

    if new.organization_member_id <> old.organization_member_id then
      raise exception 'project_members.organization_member_id cannot be changed after insert';
    end if;

    if new.created_by <> old.created_by then
      raise exception 'project_members.created_by cannot be changed after insert';
    end if;

    if new.created_at <> old.created_at then
      raise exception 'project_members.created_at cannot be changed after insert';
    end if;
  end if;

  if new.is_active then
    new.removed_at := null;
    new.removed_by := null;
  else
    if tg_op = 'INSERT' then
      new.removed_at := coalesce(new.removed_at, now());
      new.removed_by := coalesce(new.removed_by, auth.uid(), new.created_by);
    else
      if old.is_active then
        new.removed_at := coalesce(new.removed_at, now());
        new.removed_by := coalesce(new.removed_by, auth.uid(), old.removed_by);
      else
        new.removed_at := coalesce(new.removed_at, old.removed_at, now());
        new.removed_by := coalesce(new.removed_by, old.removed_by, auth.uid());
      end if;
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."enforce_project_members_integrity"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_quote_line_pricing_source_kind_from_evidence"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  resolved_kind text;
begin
  if pg_trigger_depth() = 1 then
    select case item.source_type when 'takeoff_measurement' then 'takeoff' else 'worksheet' end
      into resolved_kind
    from public.commercial_item_document_links link
    join public.commercial_items item on item.id = link.commercial_item_id and item.organization_id = link.organization_id
    where link.organization_id = new.organization_id
      and link.document_kind = 'quote_line'
      and link.link_role = 'source'
      and link.document_id = new.quote_id
      and link.document_line_id = new.id
    limit 1;
    if resolved_kind is not null then new.pricing_source_kind := resolved_kind; end if;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."enforce_quote_line_pricing_source_kind_from_evidence"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_shared_rate_limit"("p_route_key" "text", "p_subject_key" "text", "p_limit" integer, "p_window_seconds" integer DEFAULT 60) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_window_seconds integer := greatest(coalesce(p_window_seconds, 60), 1);
  v_limit integer := greatest(coalesce(p_limit, 0), 0);
  v_window_start timestamptz;
  v_hit_count integer;
begin
  if v_limit = 0 then
    return true;
  end if;

  v_window_start := to_timestamp(floor(extract(epoch from now()) / v_window_seconds) * v_window_seconds);

  insert into public.request_rate_limits (route_key, subject_key, window_start, hit_count, updated_at)
  values (p_route_key, p_subject_key, v_window_start, 1, now())
  on conflict (route_key, subject_key, window_start)
  do update
    set hit_count = request_rate_limits.hit_count + 1,
        updated_at = now()
    where request_rate_limits.hit_count < v_limit
  returning hit_count into v_hit_count;

  return v_hit_count is not null;
end;
$$;


ALTER FUNCTION "public"."enforce_shared_rate_limit"("p_route_key" "text", "p_subject_key" "text", "p_limit" integer, "p_window_seconds" integer) OWNER TO "postgres";


