CREATE OR REPLACE FUNCTION "public"."enqueue_cost_construction_intelligence_event"("p_input" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_event_id uuid;
  v_inserted boolean := false;
begin
  insert into public.cost_construction_intelligence_events (
    idempotency_key,
    organization_id,
    project_id,
    source_type,
    source_id,
    source_line_id,
    tradesstack_cost_code,
    tradesstack_cost_code_label,
    accounting_mapping_id,
    description,
    supplier_id,
    supplier_name_snapshot,
    quantity,
    unit,
    rate,
    amount,
    document_context,
    event_payload,
    classification_version
  )
  values (
    p_input ->> 'idempotencyKey',
    (p_input ->> 'organizationId')::uuid,
    nullif(p_input ->> 'projectId', '')::uuid,
    p_input ->> 'sourceType',
    (p_input ->> 'sourceId')::uuid,
    nullif(p_input ->> 'sourceLineId', '')::uuid,
    p_input ->> 'tradesstackCostCode',
    p_input ->> 'tradesstackCostCodeLabel',
    nullif(p_input ->> 'accountingMappingId', '')::uuid,
    coalesce(p_input ->> 'description', ''),
    nullif(p_input ->> 'supplierId', '')::uuid,
    nullif(p_input ->> 'supplierName', ''),
    case when jsonb_typeof(p_input -> 'quantity') = 'number' then (p_input ->> 'quantity')::numeric else null end,
    nullif(p_input ->> 'unit', ''),
    case when jsonb_typeof(p_input -> 'rate') = 'number' then (p_input ->> 'rate')::numeric else null end,
    case when jsonb_typeof(p_input -> 'amount') = 'number' then (p_input ->> 'amount')::numeric else null end,
    coalesce(p_input -> 'documentContext', '{}'::jsonb),
    coalesce(p_input -> 'eventPayload', '{}'::jsonb),
    greatest(coalesce((p_input ->> 'classificationVersion')::integer, 1), 1)
  )
  on conflict (idempotency_key)
  do update set
    project_id = excluded.project_id,
    tradesstack_cost_code = excluded.tradesstack_cost_code,
    tradesstack_cost_code_label = excluded.tradesstack_cost_code_label,
    accounting_mapping_id = excluded.accounting_mapping_id,
    description = excluded.description,
    supplier_id = excluded.supplier_id,
    supplier_name_snapshot = excluded.supplier_name_snapshot,
    quantity = excluded.quantity,
    unit = excluded.unit,
    rate = excluded.rate,
    amount = excluded.amount,
    document_context = excluded.document_context,
    event_payload = excluded.event_payload,
    classification_status = 'pending',
    error_code = null,
    error_message = null,
    processed_at = null,
    updated_at = timezone('utc'::text, now())
  returning id, xmax = 0 into v_event_id, v_inserted;

  insert into public.cost_construction_intelligence_queue (
    event_id,
    organization_id,
    processing_status,
    attempt_count,
    max_attempts,
    claim_token,
    claim_expires_at,
    retry_after,
    last_error_code,
    last_error_message
  )
  values (
    v_event_id,
    (p_input ->> 'organizationId')::uuid,
    'pending',
    0,
    greatest(coalesce((p_input ->> 'maxAttempts')::integer, 5), 1),
    null,
    null,
    null,
    null,
    null
  )
  on conflict (event_id)
  do update set
    processing_status = 'pending',
    claim_token = null,
    claim_expires_at = null,
    retry_after = null,
    last_error_code = null,
    last_error_message = null,
    updated_at = timezone('utc'::text, now());

  return jsonb_build_object(
    'id', v_event_id,
    'inserted', v_inserted
  );
end;
$$;


ALTER FUNCTION "public"."enqueue_cost_construction_intelligence_event"("p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enqueue_current_cost_item_construction_intelligence"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if not new.is_current
    or new.status in ('deleted', 'superseded')
    or new.tradesstack_cost_code is null
    or nullif(btrim(coalesce(new.tradesstack_cost_code_label, '')), '') is null
    or nullif(btrim(coalesce(new.description, new.title, '')), '') is null then
    return new;
  end if;

  if tg_op = 'UPDATE'
    and new.source_revision_key is not distinct from old.source_revision_key
    and new.source_fingerprint is not distinct from old.source_fingerprint
    and new.description is not distinct from old.description
    and new.tradesstack_cost_code is not distinct from old.tradesstack_cost_code
    and new.tradesstack_cost_code_label is not distinct from old.tradesstack_cost_code_label
    and new.accounting_mapping_id is not distinct from old.accounting_mapping_id then
    return new;
  end if;

  perform public.enqueue_cost_construction_intelligence_event(jsonb_build_object(
    'idempotencyKey', concat_ws(':', 'cost-item', new.id::text, new.source_revision_key, new.source_fingerprint),
    'organizationId', new.organization_id,
    'projectId', new.project_id,
    'sourceType', 'cost_item',
    'sourceId', new.id,
    'tradesstackCostCode', new.tradesstack_cost_code::text,
    'tradesstackCostCodeLabel', new.tradesstack_cost_code_label,
    'accountingMappingId', new.accounting_mapping_id,
    'description', coalesce(nullif(btrim(new.description), ''), new.title),
    'supplierId', new.supplier_id,
    'supplierName', new.supplier_name_snapshot,
    'quantity', new.quantity,
    'unit', new.unit,
    'rate', new.unit_rate,
    'amount', new.line_total,
    'classificationVersion', 2,
    'documentContext', jsonb_strip_nulls(jsonb_build_object(
      'module', 'cost_items',
      'sourceDocumentKind', new.source_document_kind,
      'sourceDocumentId', new.source_document_id,
      'sourceDocumentSubtype', coalesce(new.source_line_table, new.origin_kind),
      'parentCostItemId', new.parent_cost_item_id,
      'title', new.title,
      'itemType', new.item_type,
      'category', new.category,
      'section', new.section,
      'priceSource', new.price_source,
      'projectType', new.project_type,
      'buildingType', new.building_type,
      'sector', new.sector,
      'locationRegion', new.location_region
    )),
    'eventPayload', jsonb_strip_nulls(jsonb_build_object(
      'rawDescription', new.raw_description,
      'normalizedDescription', new.normalized_description,
      'sourceDocumentKind', new.source_document_kind,
      'sourceDocumentSubtype', coalesce(new.source_line_table, new.origin_kind),
      'parentCostItemId', new.parent_cost_item_id
    ))
  ));

  return new;
end;
$$;


ALTER FUNCTION "public"."enqueue_current_cost_item_construction_intelligence"() OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."learning_review_queue" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "container_type" "text" NOT NULL,
    "review_month" "date" NOT NULL,
    "scope_key" "text" DEFAULT 'organization'::"text" NOT NULL,
    "queue_state" "text" DEFAULT 'pending'::"text" NOT NULL,
    "priority" integer DEFAULT 0 NOT NULL,
    "attempt_count" integer DEFAULT 0 NOT NULL,
    "max_attempts" integer DEFAULT 3 NOT NULL,
    "available_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "retry_after" timestamp with time zone,
    "claimed_at" timestamp with time zone,
    "claim_expires_at" timestamp with time zone,
    "claimed_by" "text",
    "claim_token" "uuid",
    "last_run_id" "uuid",
    "last_error_code" "text",
    "last_error_message" "text",
    "last_completed_at" timestamp with time zone,
    "eligibility_snapshot" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "budget_snapshot" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "learning_review_queue_attempts_check" CHECK ((("attempt_count" >= 0) AND ("max_attempts" > 0) AND ("priority" >= 0))),
    CONSTRAINT "learning_review_queue_budget_snapshot_object_check" CHECK (("jsonb_typeof"("budget_snapshot") = 'object'::"text")),
    CONSTRAINT "learning_review_queue_container_type_check" CHECK (("container_type" = ANY (ARRAY['pricing_workbook_sheet'::"text", 'takeoff_measurement'::"text", 'project_quote'::"text", 'project_variation'::"text", 'project_purchase_order'::"text", 'supplier_invoice'::"text", 'supplier_invoice_allocation'::"text", 'project_actual_cost_event'::"text", 'organization_material'::"text", 'material_import_batch'::"text", 'project_claim'::"text", 'project_time_sheet_entry'::"text", 'project_quality_issue'::"text", 'project_quality_inspection'::"text", 'project_quality_sign_off'::"text", 'task'::"text"]))),
    CONSTRAINT "learning_review_queue_eligibility_snapshot_object_check" CHECK (("jsonb_typeof"("eligibility_snapshot") = 'object'::"text")),
    CONSTRAINT "learning_review_queue_scope_key_not_blank" CHECK (("char_length"(TRIM(BOTH FROM "scope_key")) > 0)),
    CONSTRAINT "learning_review_queue_state_check" CHECK (("queue_state" = ANY (ARRAY['pending'::"text", 'claimed'::"text", 'retry_scheduled'::"text", 'completed'::"text", 'dead_lettered'::"text", 'skipped'::"text"])))
);

ALTER TABLE ONLY "public"."learning_review_queue" FORCE ROW LEVEL SECURITY;


ALTER TABLE "public"."learning_review_queue" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enqueue_learning_review_queue"("p_organization_id" "uuid", "p_container_type" "text", "p_review_month" "date", "p_scope_key" "text" DEFAULT 'organization'::"text", "p_priority" integer DEFAULT 0, "p_max_attempts" integer DEFAULT 3, "p_available_at" timestamp with time zone DEFAULT "now"(), "p_eligibility_snapshot" "jsonb" DEFAULT '{}'::"jsonb", "p_budget_snapshot" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "public"."learning_review_queue"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  queue_row public.learning_review_queue%rowtype;
begin
  insert into public.learning_review_queue (
    organization_id,
    container_type,
    review_month,
    scope_key,
    priority,
    max_attempts,
    available_at,
    eligibility_snapshot,
    budget_snapshot
  )
  values (
    p_organization_id,
    p_container_type,
    p_review_month,
    coalesce(nullif(btrim(coalesce(p_scope_key, '')), ''), 'organization'),
    greatest(coalesce(p_priority, 0), 0),
    greatest(coalesce(p_max_attempts, 3), 1),
    coalesce(p_available_at, now()),
    coalesce(p_eligibility_snapshot, '{}'::jsonb),
    coalesce(p_budget_snapshot, '{}'::jsonb)
  )
  on conflict (organization_id, container_type, scope_key, review_month)
  do update set
    priority = greatest(public.learning_review_queue.priority, excluded.priority),
    max_attempts = greatest(public.learning_review_queue.max_attempts, excluded.max_attempts),
    available_at = case
      when public.learning_review_queue.queue_state in ('completed', 'dead_lettered')
        then public.learning_review_queue.available_at
      else least(public.learning_review_queue.available_at, excluded.available_at)
    end,
    eligibility_snapshot = excluded.eligibility_snapshot,
    budget_snapshot = excluded.budget_snapshot
  returning * into queue_row;

  return queue_row;
end;
$$;


ALTER FUNCTION "public"."enqueue_learning_review_queue"("p_organization_id" "uuid", "p_container_type" "text", "p_review_month" "date", "p_scope_key" "text", "p_priority" integer, "p_max_attempts" integer, "p_available_at" timestamp with time zone, "p_eligibility_snapshot" "jsonb", "p_budget_snapshot" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enqueue_material_import_job"("p_organization_id" "uuid", "p_import_batch_id" "uuid") RETURNS TABLE("run_id" "uuid", "job_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_run_id uuid := gen_random_uuid();
  v_job_id uuid := gen_random_uuid();
begin
  if not public.has_org_permission(p_organization_id, 'materials.write') then
    raise exception 'materials.write required' using errcode = '42501';
  end if;
  if not exists (
    select 1 from public.organization_material_import_batches
    where id = p_import_batch_id and organization_id = p_organization_id
  ) then
    raise exception 'Import batch not found' using errcode = 'P0002';
  end if;
  if exists (
    select 1 from public.organization_material_import_jobs
    where organization_id = p_organization_id and import_batch_id = p_import_batch_id
      and state in ('queued', 'processing')
  ) then
    raise exception 'Import batch already has active work' using errcode = '23505';
  end if;

  insert into public.organization_material_import_runs (
    id, organization_id, import_batch_id, provider, contract_version, status
  ) values (
    v_run_id, p_organization_id, p_import_batch_id, 'anthropic', 'material_supplier_pricing_v1', 'queued'
  );
  insert into public.organization_material_import_jobs (
    id, organization_id, import_batch_id, run_id, state
  ) values (
    v_job_id, p_organization_id, p_import_batch_id, v_run_id, 'queued'
  );
  return query select v_run_id, v_job_id;
end;
$$;


ALTER FUNCTION "public"."enqueue_material_import_job"("p_organization_id" "uuid", "p_import_batch_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enqueue_organization_memory_retirement_queue"("p_limit" integer DEFAULT 200, "p_organization_id" "uuid" DEFAULT NULL::"uuid", "p_memory_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  touched_ids jsonb := '[]'::jsonb;
begin
  with eligible_memories as (
    select
      m.id as memory_id,
      m.organization_id,
      m.confidence_score,
      m.contradiction_count,
      coalesce(m.contradiction_strength_score, 0) as contradiction_strength_score,
      case
        when coalesce(m.contradiction_strength_score, 0) >= 0.9 then 300
        when m.confidence_score <= 0.15 then 250
        when m.contradiction_count >= 3 then 220
        else 180
      end as priority
    from public.organization_memory_items m
    where (p_organization_id is null or m.organization_id = p_organization_id)
      and (p_memory_id is null or m.id = p_memory_id)
      and m.is_active = true
      and m.retired_at is null
      and m.superseded_at is null
      and m.superseded_by_memory_id is null
      and m.is_user_confirmed = false
      and m.memory_domain_signature is not null
      and m.confidence_score <= 0.25
      and (
        m.contradiction_count >= 2
        or coalesce(m.contradiction_strength_score, 0) >= 0.8
      )
    order by
      coalesce(m.last_contradicted_at, m.updated_at) asc,
      m.confidence_score asc,
      m.updated_at asc
    limit greatest(coalesce(p_limit, 200), 1)
  ),
  upserted as (
    insert into public.organization_memory_retirement_queue (
      organization_id,
      memory_id,
      queue_state,
      attempt_count,
      max_attempts,
      priority,
      available_at,
      retry_after,
      claimed_at,
      claim_expires_at,
      claimed_by,
      claim_token,
      last_error_code,
      last_error_message,
      last_no_action_reason,
      last_attempt_at,
      last_completed_at,
      updated_at
    )
    select
      e.organization_id,
      e.memory_id,
      'pending',
      0,
      5,
      e.priority,
      now(),
      null,
      null,
      null,
      null,
      null,
      null,
      null,
      null,
      null,
      null,
      now()
    from eligible_memories e
    on conflict (organization_id, memory_id) do update
    set
      priority = greatest(public.organization_memory_retirement_queue.priority, excluded.priority),
      available_at = case
        when public.organization_memory_retirement_queue.queue_state = 'claimed'
          and public.organization_memory_retirement_queue.claim_expires_at is not null
          and public.organization_memory_retirement_queue.claim_expires_at > now()
          then public.organization_memory_retirement_queue.available_at
        else least(public.organization_memory_retirement_queue.available_at, now())
      end,
      retry_after = case
        when public.organization_memory_retirement_queue.queue_state in ('completed', 'dead_lettered')
          then null
        else public.organization_memory_retirement_queue.retry_after
      end,
      queue_state = case
        when public.organization_memory_retirement_queue.queue_state = 'claimed'
          and public.organization_memory_retirement_queue.claim_expires_at is not null
          and public.organization_memory_retirement_queue.claim_expires_at > now()
          then public.organization_memory_retirement_queue.queue_state
        when public.organization_memory_retirement_queue.queue_state = 'completed'
          then 'pending'
        when public.organization_memory_retirement_queue.queue_state = 'dead_lettered'
          then 'pending'
        else public.organization_memory_retirement_queue.queue_state
      end,
      claim_token = case
        when public.organization_memory_retirement_queue.queue_state = 'claimed'
          and public.organization_memory_retirement_queue.claim_expires_at is not null
          and public.organization_memory_retirement_queue.claim_expires_at > now()
          then public.organization_memory_retirement_queue.claim_token
        else null
      end,
      claim_expires_at = case
        when public.organization_memory_retirement_queue.queue_state = 'claimed'
          and public.organization_memory_retirement_queue.claim_expires_at is not null
          and public.organization_memory_retirement_queue.claim_expires_at > now()
          then public.organization_memory_retirement_queue.claim_expires_at
        else null
      end,
      claimed_at = case
        when public.organization_memory_retirement_queue.queue_state = 'claimed'
          and public.organization_memory_retirement_queue.claim_expires_at is not null
          and public.organization_memory_retirement_queue.claim_expires_at > now()
          then public.organization_memory_retirement_queue.claimed_at
        else null
      end,
      claimed_by = case
        when public.organization_memory_retirement_queue.queue_state = 'claimed'
          and public.organization_memory_retirement_queue.claim_expires_at is not null
          and public.organization_memory_retirement_queue.claim_expires_at > now()
          then public.organization_memory_retirement_queue.claimed_by
        else null
      end,
      last_error_code = null,
      last_error_message = null,
      last_no_action_reason = null,
      updated_at = now()
    returning id
  )
  select coalesce(jsonb_agg(id), '[]'::jsonb)
  into touched_ids
  from upserted;

  return jsonb_build_object(
    'count', jsonb_array_length(touched_ids),
    'ids', touched_ids
  );
end;
$$;


ALTER FUNCTION "public"."enqueue_organization_memory_retirement_queue"("p_limit" integer, "p_organization_id" "uuid", "p_memory_id" "uuid") OWNER TO "postgres";


