CREATE OR REPLACE FUNCTION "public"."enqueue_worksheet_event_classification_queue"("p_limit" integer DEFAULT 1000, "p_classification_version" integer DEFAULT 1, "p_organization_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  inserted_ids jsonb := '[]'::jsonb;
begin
  with latest_attempt as (
    select distinct on (c.source_event_id, c.classification_version)
      c.source_event_id,
      c.organization_id,
      c.classification_version,
      c.attempt_number,
      c.classification_status,
      c.retry_after,
      c.error_code,
      c.error_message,
      c.classified_at
    from public.worksheet_event_classifications c
    where c.classification_version = greatest(coalesce(p_classification_version, 1), 1)
    order by c.source_event_id, c.classification_version, c.attempt_number desc, c.classified_at desc
  ),
  eligible_events as (
    select
      e.id as source_event_id,
      e.organization_id,
      greatest(coalesce(p_classification_version, 1), 1) as classification_version,
      la.attempt_number,
      la.classification_status,
      la.retry_after,
      la.error_code,
      la.error_message,
      la.classified_at
    from public.intelligence_events e
    left join latest_attempt la
      on la.source_event_id = e.id
     and la.classification_version = greatest(coalesce(p_classification_version, 1), 1)
    where e.module = 'pricing_worksheets'
      and e.event_type in (
        'worksheet_cell_edited',
        'worksheet_formula_edited',
        'worksheet_rate_changed',
        'worksheet_assumption_changed',
        'worksheet_ai_rate_corrected',
        'worksheet_ai_assumption_corrected',
        'worksheet_ai_formula_corrected',
        'worksheet_ai_output_corrected'
      )
      and coalesce(e.diff_data->>'classificationStatus', '') = 'pending'
      and coalesce(nullif(e.diff_data->>'rawContextVersion', '')::integer, 1) = 1
      and (p_organization_id is null or e.organization_id = p_organization_id)
    order by e.occurred_at desc, e.created_at desc
    limit greatest(coalesce(p_limit, 1000), 1)
  ),
  inserted as (
    insert into public.worksheet_event_classification_queue (
      source_event_id,
      organization_id,
      classification_version,
      queue_state,
      attempt_count,
      max_attempts,
      available_at,
      claimed_at,
      claim_expires_at,
      claimed_by,
      claim_token,
      last_error_code,
      last_error_message,
      last_attempt_at,
      last_completed_at,
      priority,
      updated_at
    )
    select
      ee.source_event_id,
      ee.organization_id,
      ee.classification_version,
      case
        when ee.classification_status in ('classified', 'low_confidence') then 'completed'
        when ee.classification_status = 'failed' and coalesce(ee.attempt_number, 0) >= 5 then 'dead_lettered'
        when ee.classification_status = 'failed' then 'retry_scheduled'
        else 'pending'
      end,
      greatest(coalesce(ee.attempt_number, 0), 0),
      5,
      case
        when ee.classification_status = 'failed' then coalesce(ee.retry_after, now())
        else now()
      end,
      null,
      null,
      null,
      null,
      ee.error_code,
      ee.error_message,
      ee.classified_at,
      case
        when ee.classification_status in ('classified', 'low_confidence') then ee.classified_at
        else null
      end,
      0,
      now()
    from eligible_events ee
    on conflict (source_event_id, classification_version) do nothing
    returning id
  )
  select coalesce(jsonb_agg(id), '[]'::jsonb)
  into inserted_ids
  from inserted;

  return jsonb_build_object(
    'count', jsonb_array_length(inserted_ids),
    'ids', inserted_ids
  );
end;
$$;


ALTER FUNCTION "public"."enqueue_worksheet_event_classification_queue"("p_limit" integer, "p_classification_version" integer, "p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enqueue_worksheet_memory_evidence_pool_queue"("p_limit" integer DEFAULT 200, "p_organization_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  inserted_ids jsonb := '[]'::jsonb;
begin
  with eligible_classifications as (
    select
      c.id as classification_record_id,
      c.organization_id,
      c.source_event_id,
      c.classification_version,
      c.attempt_number,
      case
        when c.classification_status = 'classified' then 200
        when c.classification_status = 'low_confidence' then 100
        else 0
      end as priority
    from public.worksheet_event_classifications c
    left join public.worksheet_memory_evidence_pool_queue q
      on q.organization_id = c.organization_id
     and q.classification_record_id = c.id
    where c.classification_status in ('classified', 'low_confidence')
      and q.id is null
      and (p_organization_id is null or c.organization_id = p_organization_id)
    order by c.classified_at desc nulls last, c.created_at desc
    limit greatest(coalesce(p_limit, 200), 1)
  ),
  inserted as (
    insert into public.worksheet_memory_evidence_pool_queue (
      organization_id,
      source_event_id,
      classification_record_id,
      classification_version,
      classification_attempt_number,
      queue_state,
      attempt_count,
      max_attempts,
      priority,
      available_at,
      retry_after,
      claimed_at,
      claim_expires_at,
      claimed_by,
      claim_token,
      last_error_code,
      last_error_message,
      last_attempt_at,
      last_completed_at,
      updated_at
    )
    select
      e.organization_id,
      e.source_event_id,
      e.classification_record_id,
      e.classification_version,
      e.attempt_number,
      'pending',
      0,
      5,
      e.priority,
      now(),
      null,
      null,
      null,
      null,
      null,
      null,
      null,
      null,
      null,
      now()
    from eligible_classifications e
    on conflict (organization_id, classification_record_id) do nothing
    returning id
  )
  select coalesce(jsonb_agg(id), '[]'::jsonb)
  into inserted_ids
  from inserted;

  return jsonb_build_object(
    'count', jsonb_array_length(inserted_ids),
    'ids', inserted_ids
  );
end;
$$;


ALTER FUNCTION "public"."enqueue_worksheet_memory_evidence_pool_queue"("p_limit" integer, "p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enqueue_worksheet_memory_semantic_pool_queue"("p_limit" integer DEFAULT 200, "p_organization_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  inserted_ids jsonb := '[]'::jsonb;
begin
  with eligible_pools as (
    select
      p.id,
      p.organization_id,
      p.pool_signature,
      p.pool_revision_hash,
      p.maturity_status,
      case
        when p.maturity_status = 'durable' then 300
        when p.maturity_status = 'reinforced' then 200
        when p.maturity_status = 'ready_for_synthesis' then 100
        else 0
      end as priority
    from public.worksheet_memory_evidence_pools p
    where p.maturity_status in ('ready_for_synthesis', 'reinforced', 'durable')
      and (p_organization_id is null or p.organization_id = p_organization_id)
    order by
      case p.maturity_status
        when 'durable' then 3
        when 'reinforced' then 2
        when 'ready_for_synthesis' then 1
        else 0
      end desc,
      p.last_seen_at desc,
      p.updated_at desc
    limit greatest(coalesce(p_limit, 200), 1)
  ),
  inserted as (
    insert into public.worksheet_memory_semantic_pool_queue (
      organization_id,
      seed_pool_id,
      seed_pool_signature,
      seed_pool_revision_hash,
      seed_maturity_status,
      queue_state,
      attempt_count,
      max_attempts,
      priority,
      available_at,
      retry_after,
      claimed_at,
      claim_expires_at,
      claimed_by,
      claim_token,
      last_error_code,
      last_error_message,
      last_attempt_at,
      last_completed_at,
      updated_at
    )
    select
      e.organization_id,
      e.id,
      e.pool_signature,
      e.pool_revision_hash,
      e.maturity_status,
      'pending',
      0,
      5,
      e.priority,
      now(),
      null,
      null,
      null,
      null,
      null,
      null,
      null,
      null,
      null,
      now()
    from eligible_pools e
    on conflict (organization_id, seed_pool_id, seed_pool_revision_hash) do nothing
    returning id
  )
  select coalesce(jsonb_agg(id), '[]'::jsonb)
  into inserted_ids
  from inserted;

  return jsonb_build_object(
    'count', jsonb_array_length(inserted_ids),
    'ids', inserted_ids
  );
end;
$$;


ALTER FUNCTION "public"."enqueue_worksheet_memory_semantic_pool_queue"("p_limit" integer, "p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enqueue_worksheet_memory_synthesis_queue"("p_limit" integer DEFAULT 200, "p_organization_id" "uuid" DEFAULT NULL::"uuid", "p_semantic_pool_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  inserted_ids jsonb := '[]'::jsonb;
begin
  with eligible_pools as (
    select
      p.id,
      p.organization_id,
      p.semantic_signature,
      p.source_revision_hash,
      p.maturity_status,
      case
        when p.maturity_status = 'durable' then 300
        when p.maturity_status = 'reinforced' then 200
        when p.maturity_status = 'ready_for_synthesis' then 100
        else 0
      end as priority
    from public.worksheet_memory_semantic_pools p
    where p.pool_status = 'active'
      and p.maturity_status in ('ready_for_synthesis', 'reinforced', 'durable')
      and (p_organization_id is null or p.organization_id = p_organization_id)
      and (p_semantic_pool_id is null or p.id = p_semantic_pool_id)
    order by
      case p.maturity_status
        when 'durable' then 3
        when 'reinforced' then 2
        when 'ready_for_synthesis' then 1
        else 0
      end desc,
      p.last_seen_at desc,
      p.updated_at desc
    limit case
      when p_semantic_pool_id is null then greatest(coalesce(p_limit, 200), 1)
      else 1
    end
  ),
  inserted as (
    insert into public.worksheet_memory_synthesis_queue (
      organization_id,
      semantic_pool_id,
      semantic_pool_signature,
      source_revision_hash,
      maturity_status,
      queue_state,
      attempt_count,
      max_attempts,
      priority,
      available_at,
      retry_after,
      claimed_at,
      claim_expires_at,
      claimed_by,
      claim_token,
      last_error_code,
      last_error_message,
      last_attempt_at,
      last_completed_at,
      updated_at
    )
    select
      e.organization_id,
      e.id,
      e.semantic_signature,
      e.source_revision_hash,
      e.maturity_status,
      'pending',
      0,
      5,
      e.priority,
      now(),
      null,
      null,
      null,
      null,
      null,
      null,
      null,
      null,
      null,
      now()
    from eligible_pools e
    on conflict (organization_id, semantic_pool_id, source_revision_hash) do nothing
    returning id
  )
  select coalesce(jsonb_agg(id), '[]'::jsonb)
  into inserted_ids
  from inserted;

  return jsonb_build_object(
    'count', jsonb_array_length(inserted_ids),
    'ids', inserted_ids
  );
end;
$$;


ALTER FUNCTION "public"."enqueue_worksheet_memory_synthesis_queue"("p_limit" integer, "p_organization_id" "uuid", "p_semantic_pool_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enqueue_worksheet_mutation_evidence_v2_outbox"("p_input" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  member_row public.organization_members%rowtype;
  resolved_id uuid;
  resolved_organization_id uuid;
  resolved_project_id uuid;
  resolved_opportunity_id uuid;
  resolved_workbook_id uuid;
  resolved_sheet_id uuid;
  resolved_worksheet_id uuid;
  resolved_user_id uuid;
  resolved_client_mutation_id text;
  resolved_sheet_name text;
  resolved_worksheet_name text;
  resolved_source text;
  resolved_occurred_at timestamptz;
  inserted boolean := false;
begin
  if p_input is null or jsonb_typeof(p_input) <> 'object' then
    raise exception 'enqueue_worksheet_mutation_evidence_v2_outbox requires a JSON object payload';
  end if;

  resolved_organization_id := nullif(p_input->>'organizationId', '')::uuid;
  resolved_project_id := nullif(p_input->>'projectId', '')::uuid;
  resolved_opportunity_id := nullif(p_input->>'opportunityId', '')::uuid;
  resolved_workbook_id := nullif(p_input->>'workbookId', '')::uuid;
  resolved_sheet_id := nullif(p_input->>'sheetId', '')::uuid;
  resolved_worksheet_id := coalesce(nullif(p_input->>'worksheetId', '')::uuid, resolved_workbook_id);
  resolved_user_id := nullif(p_input->>'userId', '')::uuid;
  resolved_client_mutation_id := nullif(btrim(coalesce(p_input->>'clientMutationId', '')), '');
  resolved_sheet_name := nullif(btrim(coalesce(p_input->>'sheetName', '')), '');
  resolved_worksheet_name := nullif(btrim(coalesce(p_input->>'worksheetName', '')), '');
  resolved_source := coalesce(nullif(btrim(coalesce(p_input->>'source', '')), ''), 'manual');
  resolved_occurred_at := coalesce(nullif(p_input->>'occurredAt', '')::timestamptz, now());

  if resolved_organization_id is null then
    raise exception 'organizationId is required';
  end if;
  if resolved_opportunity_id is null then
    raise exception 'opportunityId is required';
  end if;
  if resolved_workbook_id is null then
    raise exception 'workbookId is required';
  end if;
  if resolved_sheet_id is null then
    raise exception 'sheetId is required';
  end if;
  if resolved_worksheet_id is null then
    raise exception 'worksheetId is required';
  end if;
  if resolved_client_mutation_id is null then
    raise exception 'clientMutationId is required';
  end if;
  if resolved_sheet_name is null then
    raise exception 'sheetName is required';
  end if;
  if resolved_worksheet_name is null then
    raise exception 'worksheetName is required';
  end if;
  if resolved_source not in ('manual', 'ai', 'system') then
    raise exception 'source must be manual, ai, or system';
  end if;
  if coalesce(jsonb_typeof(p_input->'previousWorksheet'), '') <> 'object' then
    raise exception 'previousWorksheet must be an object';
  end if;
  if coalesce(jsonb_typeof(p_input->'nextWorksheet'), '') <> 'object' then
    raise exception 'nextWorksheet must be an object';
  end if;

  member_row := public._intelligence_assert_organization_member(resolved_organization_id);
  perform public._intelligence_assert_project_in_organization(resolved_organization_id, resolved_project_id);
  perform public._intelligence_assert_opportunity_in_organization(resolved_organization_id, resolved_opportunity_id);

  insert into public.worksheet_mutation_evidence_v2_outbox (
    organization_id,
    project_id,
    opportunity_id,
    workbook_id,
    workbook_name,
    sheet_id,
    sheet_name,
    worksheet_id,
    worksheet_name,
    trade_package,
    user_id,
    source,
    client_mutation_id,
    occurred_at,
    previous_worksheet,
    next_worksheet
  )
  values (
    resolved_organization_id,
    resolved_project_id,
    resolved_opportunity_id,
    resolved_workbook_id,
    nullif(btrim(coalesce(p_input->>'workbookName', '')), ''),
    resolved_sheet_id,
    resolved_sheet_name,
    resolved_worksheet_id,
    resolved_worksheet_name,
    nullif(btrim(coalesce(p_input->>'tradePackage', '')), ''),
    coalesce(resolved_user_id, auth.uid()),
    resolved_source,
    resolved_client_mutation_id,
    resolved_occurred_at,
    p_input->'previousWorksheet',
    p_input->'nextWorksheet'
  )
  on conflict (organization_id, client_mutation_id) do nothing
  returning id into resolved_id;

  if resolved_id is not null then
    inserted := true;
  else
    select outbox.id
    into resolved_id
    from public.worksheet_mutation_evidence_v2_outbox outbox
    where outbox.organization_id = resolved_organization_id
      and outbox.client_mutation_id = resolved_client_mutation_id
    limit 1;
  end if;

  if resolved_id is null then
    raise exception 'Unable to enqueue worksheet mutation Evidence V2 outbox row.';
  end if;

  return jsonb_build_object(
    'id', resolved_id,
    'inserted', inserted
  );
end;
$$;


ALTER FUNCTION "public"."enqueue_worksheet_mutation_evidence_v2_outbox"("p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enqueue_worksheet_pricing_pattern_evidence_processing"("p_inputs" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  input_item jsonb;
  inserted_ids jsonb := '[]'::jsonb;
  inserted_id uuid;
begin
  if p_inputs is null or jsonb_typeof(p_inputs) <> 'array' then
    raise exception 'enqueue_worksheet_pricing_pattern_evidence_processing requires a JSON array payload';
  end if;

  for input_item in
    select value
    from jsonb_array_elements(p_inputs)
  loop
    insert into public.worksheet_pricing_pattern_evidence_processing (
      organization_id,
      source_event_id,
      classification_record_id,
      classification_version,
      classification_attempt_number,
      processing_status,
      processing_run_id,
      processed_at,
      failed_at,
      retry_after,
      error_code,
      error_message,
      attempt_count,
      max_attempts,
      claimed_at,
      claim_expires_at,
      claimed_by,
      claim_token,
      last_error_code,
      last_error_message
    )
    values (
      nullif(input_item->>'organizationId', '')::uuid,
      nullif(input_item->>'sourceEventId', '')::uuid,
      nullif(input_item->>'classificationRecordId', '')::uuid,
      greatest(coalesce(nullif(input_item->>'classificationVersion', '')::integer, 1), 1),
      greatest(coalesce(nullif(input_item->>'classificationAttemptNumber', '')::integer, 1), 1),
      'pending',
      null,
      null,
      null,
      null,
      null,
      null,
      0,
      5,
      null,
      null,
      null,
      null,
      null,
      null
    )
    on conflict (source_event_id, classification_version) do update
    set
      organization_id = excluded.organization_id,
      classification_record_id = coalesce(excluded.classification_record_id, public.worksheet_pricing_pattern_evidence_processing.classification_record_id),
      classification_attempt_number = greatest(
        public.worksheet_pricing_pattern_evidence_processing.classification_attempt_number,
        excluded.classification_attempt_number
      ),
      updated_at = now()
    returning id into inserted_id;

    inserted_ids := inserted_ids || jsonb_build_array(inserted_id);
  end loop;

  return jsonb_build_object(
    'count', jsonb_array_length(inserted_ids),
    'ids', inserted_ids
  );
end;
$$;


ALTER FUNCTION "public"."enqueue_worksheet_pricing_pattern_evidence_processing"("p_inputs" "jsonb") OWNER TO "postgres";


