CREATE OR REPLACE FUNCTION "public"."ensure_opportunity_project_document_workspace"("p_opportunity_id" "uuid", "p_project_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  workspace_id uuid;
begin
  if auth.uid() is null then
    raise exception 'Authentication required.'
      using errcode = '42501';
  end if;

  workspace_id := public.get_or_create_opportunity_document_workspace(
    p_opportunity_id
  );

  return public.link_project_to_opportunity_document_workspace(
    p_opportunity_id,
    p_project_id
  );
end;
$$;


