    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  perform public.sync_project_claim_line_items(
    new.organization_id,
    new.project_id,
    new.id,
    null,
    new.claim_amount
  );
  return new;
end;
$$;


ALTER FUNCTION "public"."ensure_project_claim_line_items_after_insert"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."evaluate_opportunity_promotion_shadow_v1"("p_organization_id" "uuid", "p_opportunity_id" "uuid", "p_accepted_quote_id" "uuid", "p_actor_user_id" "uuid") RETURNS TABLE("eligible" boolean, "failure_codes" "text"[], "workspace_project_id" "uuid", "lifecycle_strategy" "text", "lifecycle_strategy_version" smallint, "evaluator_version" "text", "snapshot" "jsonb", "payload_hash" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  opportunity_row public.organization_opportunities%rowtype;
  workspace_row public.organization_projects%rowtype;
  quote_row public.project_quotes%rowtype;
  lifecycle_row public.opportunity_lifecycles%rowtype;
  failures text[] := array[]::text[];
  accepted_count integer := 0;
  workspace_reference_count integer := 0;
  orphan_count integer := 0;
  document_workspace_count integer := 0;
  resolved_document_workspace_id uuid;
  currency_value text;
  snapshot_value jsonb;
begin
  if not exists (
    select 1 from public.organization_members member
    where member.organization_id = p_organization_id
      and member.user_id = p_actor_user_id
  ) then
    raise exception 'Not authorized for shadow evaluation' using errcode = '42501';
  end if;

  select * into opportunity_row
  from public.organization_opportunities opportunity
  where opportunity.organization_id = p_organization_id
    and opportunity.id = p_opportunity_id;
  if not found then
    failures := array_append(failures, 'opportunity_not_found');
  end if;

  select * into lifecycle_row
  from public.opportunity_lifecycles lifecycle
  where lifecycle.organization_id = p_organization_id
    and lifecycle.opportunity_id = p_opportunity_id;
  if lifecycle_row.id is null then
    failures := array_append(failures, 'lifecycle_missing');
  elsif lifecycle_row.strategy <> 'legacy_two_project_v1'
    or lifecycle_row.strategy_version <> 1
  then
    failures := array_append(failures, 'strategy_not_legacy');
  end if;

  if opportunity_row.workspace_project_id is null then
    failures := array_append(failures, 'workspace_missing');
  else
    select * into workspace_row
    from public.organization_projects project
    where project.organization_id = p_organization_id
      and project.id = opportunity_row.workspace_project_id;

    if workspace_row.id is null
      or workspace_row.source_opportunity_id is distinct from p_opportunity_id
      or lifecycle_row.original_workspace_project_id
        is distinct from opportunity_row.workspace_project_id
    then
      failures := array_append(failures, 'workspace_lineage_invalid');
    end if;

    select count(*)::integer into workspace_reference_count
    from public.organization_opportunities other_opportunity
    where other_opportunity.workspace_project_id = opportunity_row.workspace_project_id;
    if workspace_reference_count <> 1 then
      failures := array_append(failures, 'workspace_shared');
    end if;
  end if;

  if opportunity_row.converted_project_id is not null
    or exists (
      select 1 from public.opportunity_final_projects mapping
      where mapping.organization_id = p_organization_id
        and mapping.opportunity_id = p_opportunity_id
    )
  then
    failures := array_append(failures, 'existing_conversion_state');
  end if;

  select * into quote_row
  from public.project_quotes quote
  where quote.organization_id = p_organization_id
    and quote.id = p_accepted_quote_id
    and quote.originating_opportunity_id = p_opportunity_id;
  if quote_row.id is null then
    failures := array_append(failures, 'accepted_quote_missing');
  else
    if quote_row.status <> 'Accepted' then
      failures := array_append(failures, 'accepted_quote_not_accepted');
    end if;
    if quote_row.project_id is not null
      and quote_row.project_id is distinct from opportunity_row.workspace_project_id
    then
      failures := array_append(failures, 'quote_ownership_invalid');
    end if;
    if exists (
      select 1 from public.project_quotes newer_quote
      where newer_quote.organization_id = p_organization_id
        and newer_quote.originating_opportunity_id = p_opportunity_id
        and newer_quote.status = 'Accepted'
        and (
          newer_quote.updated_at > quote_row.updated_at
          or (newer_quote.updated_at = quote_row.updated_at and newer_quote.id > quote_row.id)
        )
    ) then
      failures := array_append(failures, 'accepted_quote_superseded');
    end if;
  end if;

  select count(*)::integer into accepted_count
  from public.project_quotes accepted_quote
  where accepted_quote.organization_id = p_organization_id
    and accepted_quote.originating_opportunity_id = p_opportunity_id
    and accepted_quote.status = 'Accepted';
  if accepted_count > 1 then
    failures := array_append(failures, 'multiple_accepted_quotes');
  end if;

  if exists (
    select 1 from public.project_quote_line_items line
    where line.organization_id = p_organization_id
      and line.quote_id = p_accepted_quote_id
      and line.project_id is not null
      and line.project_id is distinct from opportunity_row.workspace_project_id
  ) then
    failures := array_append(failures, 'quote_line_ownership_invalid');
  end if;

  if exists (
    select 1 from public.commercial_items item
    where item.organization_id = p_organization_id
      and item.opportunity_id = p_opportunity_id
      and item.project_id is not null
      and item.project_id is distinct from opportunity_row.workspace_project_id
  ) then
    failures := array_append(failures, 'commercial_ownership_invalid');
  end if;

  if exists (
    select 1 from public.cost_items cost
    where cost.organization_id = p_organization_id
      and cost.source_document_kind = 'project_quote'
      and cost.source_document_id = p_accepted_quote_id
      and cost.project_id is distinct from opportunity_row.workspace_project_id
  ) then
    failures := array_append(failures, 'cost_ownership_invalid');
  end if;

  select coalesce(
    nullif(upper(btrim(to_jsonb(organization) ->> 'default_currency')), ''),
    'NZD'
  ) into currency_value
  from public.organizations organization
  where organization.id = p_organization_id;
  if nullif(btrim(currency_value), '') is null
    or quote_row.gst_percent < 0
    or quote_row.gst_amount < 0
  then
    failures := array_append(failures, 'currency_or_tax_invalid');
  end if;

  select count(*)::integer, (array_agg(link.workspace_id order by link.workspace_id))[1]
  into document_workspace_count, resolved_document_workspace_id
  from public.document_workspace_entities link
  where link.organization_id = p_organization_id
    and link.opportunity_id = p_opportunity_id;
  if document_workspace_count = 0 then
    failures := array_append(failures, 'document_workspace_missing');
  elsif document_workspace_count <> 1 then
    failures := array_append(failures, 'document_workspace_ambiguous');
  end if;

  select count(*)::integer into orphan_count
  from public.organization_projects project
  where project.organization_id = p_organization_id
    and project.source_opportunity_id = p_opportunity_id
    and project.id is distinct from opportunity_row.workspace_project_id;
  if orphan_count > 0 then
    failures := array_append(failures, 'orphan_final_candidate');
  end if;

  snapshot_value := jsonb_build_object(
    'quote', jsonb_build_object(
      'id', p_accepted_quote_id,
      'currency', currency_value,
      'subtotal', coalesce(quote_row.subtotal, 0),
      'tax', coalesce(quote_row.gst_amount, 0),
      'total', coalesce(quote_row.total_quote_price, 0),
      'line_count', (select count(*) from public.project_quote_line_items line
        where line.organization_id = p_organization_id and line.quote_id = p_accepted_quote_id)
    ),
    'commercial', jsonb_build_object(
      'item_count', (select count(*) from public.commercial_items item
        where item.organization_id = p_organization_id and item.opportunity_id = p_opportunity_id),
      'total', (select coalesce(sum(item.total), 0) from public.commercial_items item
        where item.organization_id = p_organization_id and item.opportunity_id = p_opportunity_id)
    ),
    'cost', jsonb_build_object(
      'item_count', (select count(*) from public.cost_items cost
        where cost.organization_id = p_organization_id
          and cost.source_document_kind = 'project_quote'
          and cost.source_document_id = p_accepted_quote_id
          and cost.is_current),
      'total', (select coalesce(sum(cost.line_total), 0) from public.cost_items cost
        where cost.organization_id = p_organization_id
          and cost.source_document_kind = 'project_quote'
          and cost.source_document_id = p_accepted_quote_id
          and cost.is_current)
    ),
    'documents', jsonb_build_object(
      'workspace_id', resolved_document_workspace_id,
      'node_count', (select count(*) from public.document_nodes node
        where node.organization_id = p_organization_id
          and node.workspace_id = resolved_document_workspace_id
          and node.deleted_at is null),
      'version_count', (select count(*) from public.document_versions version
        where version.organization_id = p_organization_id
          and version.workspace_id = resolved_document_workspace_id
          and version.purged_at is null)
    ),
    'features', jsonb_build_object(
      'drawing_set_count', (select count(*) from public.project_drawing_sets drawing
        where drawing.organization_id = p_organization_id
          and drawing.project_id = opportunity_row.workspace_project_id),
      'takeoff_page_count', (select count(*) from public.takeoff_pages page
        where page.organization_id = p_organization_id
          and page.project_id = opportunity_row.workspace_project_id),
      'measurement_count', (select count(*) from public.takeoff_measurements measurement
        where measurement.organization_id = p_organization_id
          and measurement.project_id = opportunity_row.workspace_project_id
          and measurement.archived_at is null),
      'trade_pack_count', (select count(*) from public.trade_packs pack
        where pack.organization_id = p_organization_id
          and pack.project_id = opportunity_row.workspace_project_id),
      'scope_run_count', (select count(*) from public.scope_runs scope
        where scope.organization_id = p_organization_id
          and scope.project_id = opportunity_row.workspace_project_id),
      'task_count', (select count(*) from public.project_job_todos task
        where task.organization_id = p_organization_id
          and task.project_id = opportunity_row.workspace_project_id
          and task.deleted_at is null)
    ),
    'predicted', jsonb_build_object(
      'project_id', opportunity_row.workspace_project_id,
      'visible', true,
      'delivery_eligible', true
    )
  );

  return query select
    cardinality(failures) = 0,
    failures,
    opportunity_row.workspace_project_id,
    coalesce(lifecycle_row.strategy, 'legacy_two_project_v1'),
    coalesce(lifecycle_row.strategy_version, 1::smallint),
    'shadow-v1'::text,
    snapshot_value,
    encode(extensions.digest(convert_to(snapshot_value::text, 'UTF8'), 'sha256'), 'hex');
end;
$$;


ALTER FUNCTION "public"."evaluate_opportunity_promotion_shadow_v1"("p_organization_id" "uuid", "p_opportunity_id" "uuid", "p_accepted_quote_id" "uuid", "p_actor_user_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."evaluate_opportunity_promotion_shadow_v1"("p_organization_id" "uuid", "p_opportunity_id" "uuid", "p_accepted_quote_id" "uuid", "p_actor_user_id" "uuid") IS 'Pure Stage 4 legacy Opportunity promotion eligibility evaluator; performs no writes.';



CREATE OR REPLACE FUNCTION "public"."evaluate_opportunity_promotion_shadow_v2"("p_organization_id" "uuid", "p_opportunity_id" "uuid", "p_accepted_quote_id" "uuid", "p_actor_user_id" "uuid") RETURNS TABLE("eligible" boolean, "failure_codes" "text"[], "workspace_project_id" "uuid", "lifecycle_strategy" "text", "lifecycle_strategy_version" smallint, "evaluator_version" "text", "snapshot" "jsonb", "payload_hash" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  base record;
  snapshot_value jsonb;
begin
  select * into base
  from public.evaluate_opportunity_promotion_shadow_v1(
    p_organization_id, p_opportunity_id, p_accepted_quote_id, p_actor_user_id
  );

  snapshot_value := base.snapshot || jsonb_build_object(
    'permanent_workspace',
    public.get_opportunity_workspace_continuity_snapshot_v1(
      p_organization_id, p_opportunity_id, base.workspace_project_id
    )
  );

  return query select
    base.eligible,
    base.failure_codes,
    base.workspace_project_id,
    base.lifecycle_strategy,
    base.lifecycle_strategy_version,
    'shadow-v2'::text,
    snapshot_value,
    encode(extensions.digest(convert_to(snapshot_value::text, 'UTF8'), 'sha256'), 'hex');
end;
$$;


ALTER FUNCTION "public"."evaluate_opportunity_promotion_shadow_v2"("p_organization_id" "uuid", "p_opportunity_id" "uuid", "p_accepted_quote_id" "uuid", "p_actor_user_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."evaluate_opportunity_promotion_shadow_v2"("p_organization_id" "uuid", "p_opportunity_id" "uuid", "p_accepted_quote_id" "uuid", "p_actor_user_id" "uuid") IS 'Pure Stage 4 continuity evaluator. Permanent W-owned records are compared by identity and integrity, not by legacy F ownership.';



CREATE OR REPLACE FUNCTION "public"."evaluate_retention_ownership_phase2a"("p_organization_id" "uuid", "p_project_id" "uuid", "p_proposals" "jsonb" DEFAULT '[]'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'private'
    AS $$
declare
  position jsonb;
  payment_claim public.project_claims%rowtype;
  proposal jsonb;
  origins jsonb := '[]'::jsonb;
  native_submitted bigint;
  approved_legacy bigint;
  draft_committed bigint;
  exported bigint;
  paid bigint;
  held bigint;
  proposed_owned bigint;
  proposed_release bigint;
  previously_claimed bigint;
  remaining bigint;
  after_claim bigint;
  reasons jsonb;
  unresolved_legacy boolean;
begin
  if jsonb_typeof(p_proposals) <> 'array' then
    raise exception 'Retention ownership proposals must be a JSON array.';
  end if;
  if not exists (
    select 1
    from public.organization_projects project
    where project.id = p_project_id
      and project.organization_id = p_organization_id
  ) then
    raise exception 'Project does not belong to the organization.';
  end if;
  if exists (
    select 1
    from jsonb_array_elements(p_proposals) item
    where not exists (
      select 1
      from public.project_claims claim
      where claim.id = (item ->> 'originId')::uuid
        and claim.project_id = p_project_id
        and claim.organization_id = p_organization_id
    )
  ) then
    raise exception 'A proposed retention origin is outside the organization project.';
  end if;

  position := public.get_project_retention_position_summary(p_project_id);
  unresolved_legacy := coalesce(
    (position ->> 'legacyReconciliationRequired')::boolean,
    false
  );

  for payment_claim in
    select claim.*
    from public.project_claims claim
    where claim.organization_id = p_organization_id
      and claim.project_id = p_project_id
      and claim.status <> 'Cancelled'
    order by claim.claim_date nulls last, claim.created_at, claim.id
  loop
    select value
    into proposal
    from jsonb_array_elements(p_proposals)
    where value ->> 'originId' = payment_claim.id::text
    limit 1;

    held := round(greatest(
      coalesce(payment_claim.retention_withheld_amount, 0),
      0
    ) * 100);
    proposed_owned := round(coalesce(
      (proposal ->> 'proposedOwnedMinor')::numeric,
      held
    ));
    proposed_release := round(coalesce(
      (proposal ->> 'proposedReleaseMinor')::numeric,
      0
    ));

    select round(coalesce(sum(allocation.allocation_amount), 0) * 100)::bigint
    into native_submitted
    from public.retention_claim_allocations allocation
    join public.retention_claims retention_claim
      on retention_claim.id = allocation.retention_claim_id
    where allocation.originating_payment_claim_id = payment_claim.id
      and retention_claim.organization_id = p_organization_id
      and retention_claim.project_id = p_project_id
      and retention_claim.status = 'submitted';

    select round(coalesce(sum(allocation.allocation_amount), 0) * 100)::bigint
    into draft_committed
    from public.retention_claim_allocations allocation
    join public.retention_claims retention_claim
      on retention_claim.id = allocation.retention_claim_id
    where allocation.originating_payment_claim_id = payment_claim.id
      and retention_claim.organization_id = p_organization_id
      and retention_claim.project_id = p_project_id
      and retention_claim.status = 'draft';

    select round(coalesce(legacy.amount, 0) * 100)::bigint
    into approved_legacy
    from private.current_legacy_committed_by_origin(p_project_id) legacy
    where legacy.originating_payment_claim_id = payment_claim.id;
    approved_legacy := coalesce(approved_legacy, 0);

    select round(coalesce(sum(line.line_amount_excl_tax), 0) * 100)::bigint
    into exported
    from public.retention_claim_accounting_lines line
    join public.retention_claim_accounting_snapshots snapshot
      on snapshot.id = line.accounting_snapshot_id
    join public.organization_accounting_documents document
      on document.id = snapshot.accounting_document_id
    where line.originating_payment_claim_id = payment_claim.id
      and line.organization_id = p_organization_id
      and line.project_id = p_project_id
      and document.export_status = 'exported';

    select round(coalesce(sum(attribution.paid_amount), 0) * 100)::bigint
    into paid
    from public.retention_claim_payment_attributions attribution
    join public.retention_claim_payment_reconciliations reconciliation
      on reconciliation.id = attribution.payment_reconciliation_id
    where attribution.originating_payment_claim_id = payment_claim.id
      and attribution.organization_id = p_organization_id
      and attribution.project_id = p_project_id
      and reconciliation.id = (
        select latest.id
        from public.retention_claim_payment_reconciliations latest
        where latest.retention_claim_id = reconciliation.retention_claim_id
        order by latest.reconciliation_sequence desc
        limit 1
      );

    previously_claimed := native_submitted + approved_legacy;
    remaining := greatest(held - previously_claimed, 0);
    after_claim := greatest(remaining - proposed_release, 0);
    reasons := '[]'::jsonb;

    if unresolved_legacy then
      reasons := reasons || '"unresolved_legacy_retention"'::jsonb;
    end if;
    if proposed_owned > held then
      reasons := reasons || '"proposed_ownership_exceeds_current"'::jsonb;
    end if;
    if previously_claimed > proposed_owned then
      reasons := reasons ||
        '"committed_retention_exceeds_proposed_ownership"'::jsonb;
    end if;
    if proposed_release > remaining then
      reasons := reasons || '"proposed_release_exceeds_remaining"'::jsonb;
    end if;
    if proposed_release > 0 and previously_claimed > 0 then
      reasons := reasons || '"duplicate_release_path"'::jsonb;
    end if;
    if exported > native_submitted then
      reasons := reasons ||
        '"exported_retention_exceeds_native_commitment"'::jsonb;
    end if;
    if paid > exported then
      reasons := reasons ||
        '"paid_retention_exceeds_exported_retention"'::jsonb;
    end if;

    origins := origins || jsonb_build_array(jsonb_build_object(
      'originId', payment_claim.id,
      'retentionHeldMinor', held,
      'previouslyClaimedMinor', previously_claimed,
      'remainingMinor', remaining,
      'proposedMinor', proposed_release,
      'afterClaimMinor', after_claim,
      'currentOwnedMinor', held,
      'proposedOwnedMinor', proposed_owned,
      'nativeSubmittedMinor', native_submitted,
      'approvedLegacyMinor', approved_legacy,
      'draftCommittedMinor', draft_committed,
      'exportedMinor', exported,
      'paidMinor', paid,
      'scheduleEligibleMinor', remaining,
      'proposedReleaseMinor', proposed_release,
      'eligibilitySource', 'accumulated_retention',
      'unresolvedLegacy', unresolved_legacy,
      'blocker', reasons ->> 0,
      'blockingReasons', reasons,
      'valid', jsonb_array_length(reasons) = 0
    ));
  end loop;

  return jsonb_build_object(
    'organizationId', p_organization_id,
    'projectId', p_project_id,
    'readOnly', true,
    'eligibilityModel', 'accumulated_retention_v1',
    'origins', origins,
    'valid', not exists (
      select 1
      from jsonb_array_elements(origins) origin
      where not coalesce((origin ->> 'valid')::boolean, false)
    )
  );
end;
$$;


ALTER FUNCTION "public"."evaluate_retention_ownership_phase2a"("p_organization_id" "uuid", "p_project_id" "uuid", "p_proposals" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."evaluate_retention_variances"("p_project_id" "uuid", "p_origin_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_correlation_id" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare ctx jsonb; result jsonb;
begin
  ctx:=private.retention_phase5_context(
    p_project_id,'retention.variances.resolve',true);
  if not coalesce((ctx->>'succeeded')::boolean,false) then return ctx; end if;
  result:=private.evaluate_retention_variance_project(
    p_project_id,p_correlation_id,p_origin_ids);
  return result||private.retention_variance_blocking_details(p_project_id,p_origin_ids);
end;
$$;


ALTER FUNCTION "public"."evaluate_retention_variances"("p_project_id" "uuid", "p_origin_ids" "uuid"[], "p_correlation_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fail_document_storage_cleanup_job"("p_job_id" "uuid", "p_claim_token" "uuid", "p_error_code" "text", "p_error_message" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  job_row public.document_storage_cleanup_jobs%rowtype;
  next_status text;
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'Service role required.'
      using errcode = '42501';
  end if;

  select *
  into job_row
  from public.document_storage_cleanup_jobs job
  where job.id = p_job_id
  for update;

  if not found
    or job_row.processing_status <> 'claimed'
    or job_row.claim_token <> p_claim_token
  then
    raise exception 'Cleanup lease is not owned.'
      using errcode = '42501';
  end if;

  next_status := case
    when job_row.attempt_count >= job_row.max_attempts
      then 'dead_lettered'
    else 'retry_scheduled'
  end;

  update public.document_storage_cleanup_jobs job
  set
    processing_status = next_status,
    available_at = case
      when next_status = 'retry_scheduled'
      then now() + least(
        interval '24 hours',
        make_interval(mins => (power(2, least(job_row.attempt_count, 10)))::integer)
      )
      else job.available_at
    end,
    claimed_at = null,
    claim_expires_at = null,
    claimed_by = null,
    claim_token = null,
    last_error_code = left(nullif(btrim(p_error_code), ''), 100),
    last_error_message = left(nullif(btrim(p_error_message), ''), 1000),
    dead_lettered_at = case
      when next_status = 'dead_lettered' then now()
      else null
    end
  where job.id = job_row.id;

  if next_status = 'dead_lettered'
    and job_row.cleanup_batch_id is not null
  then
    update public.document_storage_cleanup_batches batch
    set
      processing_status = 'dead_lettered',
      dead_lettered_at = now()
    where batch.id = job_row.cleanup_batch_id
      and batch.processing_status <> 'completed';
  end if;

  return next_status;
end;
$$;


ALTER FUNCTION "public"."fail_document_storage_cleanup_job"("p_job_id" "uuid", "p_claim_token" "uuid", "p_error_code" "text", "p_error_message" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."finalize_accounting_revision_attempt_phase2a"("p_attempt_id" "uuid", "p_worker_id" "text", "p_lease_token" "uuid", "p_terminal_state" "text", "p_outcome_code" "text", "p_outcome_message" "text", "p_response_evidence" "jsonb") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare changed integer;
begin
  if p_terminal_state not in ('succeeded', 'failed', 'attention_required') then
    raise exception 'Invalid terminal accounting attempt state.';
  end if;
  perform set_config('app.accounting_phase2a_lease_write', 'true', true);
  update public.organization_accounting_revision_attempts set
    queue_state = p_terminal_state,
    response_evidence = p_response_evidence,
    completed_at = now(),
    outcome_code = p_outcome_code,
    outcome_message = p_outcome_message,
    updated_at = now()
  where id = p_attempt_id
    and queue_state = 'claimed'
    and worker_id = p_worker_id
    and lease_token = p_lease_token
    and lease_expires_at >= now();
  get diagnostics changed = row_count;
  perform set_config('app.accounting_phase2a_lease_write', '', true);
  if changed = 1 then return true; end if;
  return exists (
    select 1
    from public.organization_accounting_revision_attempts a
    where a.id = p_attempt_id
      and a.worker_id = p_worker_id
      and a.lease_token = p_lease_token
      and a.queue_state = p_terminal_state
      and a.outcome_code = p_outcome_code
      and a.response_evidence = p_response_evidence
  );
end;
$$;


ALTER FUNCTION "public"."finalize_accounting_revision_attempt_phase2a"("p_attempt_id" "uuid", "p_worker_id" "text", "p_lease_token" "uuid", "p_terminal_state" "text", "p_outcome_code" "text", "p_outcome_message" "text", "p_response_evidence" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."finalize_award_pricing_after_quote_attachment"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  final_mapping public.opportunity_final_projects%rowtype;
begin
  if current_setting('tradesstack.defer_award_pricing_finalize', true) = 'on' then
    return new;
  end if;

  select * into final_mapping
  from public.opportunity_final_projects mapping
  where mapping.organization_id = new.organization_id
    and mapping.accepted_quote_id = new.id
    and mapping.project_id = new.project_id;

  if found then
    perform * from public.finalize_opportunity_award_pricing_v1(
      new.organization_id,
      final_mapping.opportunity_id,
      final_mapping.project_id,
      final_mapping.accepted_quote_id
    );
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."finalize_award_pricing_after_quote_attachment"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."finalize_cost_construction_intelligence_batch"("p_inputs" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_item jsonb;
  v_count integer := 0;
  v_completed integer := 0;
  v_retried integer := 0;
  v_dead integer := 0;
begin
  for v_item in select * from jsonb_array_elements(coalesce(p_inputs, '[]'::jsonb))
  loop
    update public.cost_construction_intelligence_queue
    set
      processing_status = coalesce(v_item ->> 'processingStatus', processing_status),
      claim_token = null,
      claim_expires_at = null,
      retry_after = nullif(v_item ->> 'retryAfter', '')::timestamptz,
      last_error_code = nullif(v_item ->> 'errorCode', ''),
      last_error_message = nullif(v_item ->> 'errorMessage', ''),
      updated_at = timezone('utc'::text, now())
    where event_id = (v_item ->> 'eventId')::uuid
      and claim_token = coalesce(nullif(v_item ->> 'claimToken', ''), claim_token);

    if found then
      v_count := v_count + 1;
      if v_item ->> 'processingStatus' = 'completed' then
        v_completed := v_completed + 1;
      elsif v_item ->> 'processingStatus' = 'retry_scheduled' then
        v_retried := v_retried + 1;
      elsif v_item ->> 'processingStatus' = 'dead_lettered' then
        v_dead := v_dead + 1;
      end if;
    end if;
  end loop;

  return jsonb_build_object(
    'count', v_count,
    'completedCount', v_completed,
    'retriedCount', v_retried,
    'deadLetteredCount', v_dead
  );
end;
$$;


ALTER FUNCTION "public"."finalize_cost_construction_intelligence_batch"("p_inputs" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."finalize_drawn_project_qa_signature_v1"("p_upload_id" "uuid", "p_signer_name" "text", "p_attestation" "text", "p_sha256" "text", "p_metadata" "jsonb", "p_image_width" integer, "p_image_height" integer) RETURNS TABLE("evidence_id" "uuid", "response_lock_version" integer, "run_lock_version" integer, "signed_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
declare upload_row public.project_qa_evidence_uploads%rowtype; run_row public.project_qa_runs%rowtype; response_row public.project_qa_responses%rowtype; object_row storage.objects%rowtype; inserted_id uuid; actual_size bigint; actual_mime text; next_response integer; next_run integer; signed_time timestamptz:=now(); actor_name text;
begin
  select * into upload_row from public.project_qa_evidence_uploads where id=p_upload_id and initiated_by=auth.uid() for update;
  if not found or not public.can_access_qa_project(upload_row.organization_id,upload_row.project_id,'qa.inspect') then raise exception 'QA signature upload not found or access denied' using errcode='42501'; end if;
  if upload_row.status<>'pending' or upload_row.expires_at<=now() or upload_row.evidence_type<>'signature' then raise exception 'QA signature upload is not pending' using errcode='TS409'; end if;
  select * into run_row from public.project_qa_runs where id=upload_row.run_id for update;
  if run_row.status<>'in_progress' then raise exception 'Only an in-progress QA Record can be signed' using errcode='TS409'; end if;
  select * into response_row from public.project_qa_responses where id=upload_row.response_id and run_id=upload_row.run_id for update;
  if not found or response_row.field_type<>'signature' then raise exception 'Signature response not found' using errcode='TS404'; end if;
  if char_length(btrim(coalesce(p_signer_name,''))) not between 1 and 240 or char_length(btrim(coalesce(p_attestation,''))) not between 1 and 1000 then raise exception 'Signer name and acknowledgement are required' using errcode='TS422'; end if;
  if p_sha256 is null or p_sha256!~'^[a-f0-9]{64}$' or not public.qa_signature_metadata_is_valid_v1(p_metadata) then raise exception 'Invalid signature artifact metadata' using errcode='TS422'; end if;
  if p_image_width<>((p_metadata->>'pixelWidth')::integer) or p_image_height<>((p_metadata->>'pixelHeight')::integer) then raise exception 'Signature image dimensions do not match metadata' using errcode='TS422'; end if;
  select * into object_row from storage.objects where bucket_id='project-qa-evidence' and name=upload_row.storage_path;
  if not found then raise exception 'Uploaded signature object was not found' using errcode='TS409'; end if;
  actual_size:=nullif(object_row.metadata->>'size','')::bigint;
  actual_mime:=lower(btrim(coalesce(object_row.metadata->>'mimetype',object_row.metadata->>'contentType','')));
  if actual_size is distinct from upload_row.byte_size or actual_size>2097152 or actual_mime<>'image/png' then raise exception 'Uploaded signature does not match its reservation' using errcode='TS422'; end if;
  select coalesce(nullif(btrim(display_name),''),'TradesStack user') into actor_name from public.organization_members where organization_id=upload_row.organization_id and user_id=auth.uid() order by created_at limit 1;
  if actor_name is null then raise exception 'Authenticated QA actor not found' using errcode='42501'; end if;
  insert into public.project_qa_response_evidence(organization_id,project_id,project_qa_run_id,project_qa_response_id,upload_id,evidence_type,purpose,storage_path,original_filename,mime_type,byte_size,sort_order,uploaded_by,content_sha256,image_width,image_height)
  values(upload_row.organization_id,upload_row.project_id,upload_row.run_id,upload_row.response_id,upload_row.id,'signature','general',upload_row.storage_path,upload_row.original_filename,'image/png',upload_row.byte_size,
    (select count(*) from public.project_qa_response_evidence where project_qa_response_id=upload_row.response_id),auth.uid(),p_sha256,p_image_width,p_image_height)
  returning id into inserted_id;
  update public.project_qa_evidence_uploads set status='finalized',finalized_at=signed_time where id=upload_row.id;
  update public.project_qa_responses set signature_signer_name=btrim(p_signer_name),signature_method='drawn_signature',signature_attestation=btrim(p_attestation),signature_signed_by=auth.uid(),signature_signed_at=signed_time,signature_evidence_id=inserted_id,signature_artifact_sha256=p_sha256,signature_artifact_metadata=p_metadata,signature_recorded_by_name=actor_name,updated_by=auth.uid(),lock_version=lock_version+1 where id=response_row.id returning lock_version into next_response;
  update public.project_qa_runs set lock_version=lock_version+1 where id=upload_row.run_id returning lock_version into next_run;
  return query select inserted_id,next_response,next_run,signed_time;
end; $_$;


ALTER FUNCTION "public"."finalize_drawn_project_qa_signature_v1"("p_upload_id" "uuid", "p_signer_name" "text", "p_attestation" "text", "p_sha256" "text", "p_metadata" "jsonb", "p_image_width" integer, "p_image_height" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."finalize_learning_review_batch"("p_inputs" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  input_item jsonb;
  finalized_ids jsonb := '[]'::jsonb;
  queue_row public.learning_review_queue%rowtype;
  resolved_status text;
  resolved_retry_after timestamptz;
  completed_count integer := 0;
  retried_count integer := 0;
  dead_lettered_count integer := 0;
  skipped_count integer := 0;
begin
  if p_inputs is null or jsonb_typeof(p_inputs) <> 'array' then
    raise exception 'finalize_learning_review_batch requires a JSON array payload';
  end if;

  for input_item in
    select value
    from jsonb_array_elements(p_inputs)
  loop
    resolved_status := coalesce(nullif(input_item->>'queueState', ''), 'retry_scheduled');
    resolved_retry_after := nullif(input_item->>'retryAfter', '')::timestamptz;

    select q.*
    into queue_row
    from public.learning_review_queue q
    where q.id = nullif(input_item->>'id', '')::uuid
      and q.queue_state = 'claimed'
      and q.claim_token = nullif(input_item->>'claimToken', '')::uuid
    for update;

    if not found then
      continue;
    end if;

    finalized_ids := finalized_ids || jsonb_build_array(queue_row.id);

    if resolved_status = 'completed' then
      update public.learning_review_queue
      set
        queue_state = 'completed',
        available_at = now(),
        retry_after = null,
        claim_token = null,
        claim_expires_at = null,
        claimed_at = null,
        claimed_by = null,
        last_run_id = nullif(input_item->>'lastRunId', '')::uuid,
        last_error_code = nullif(input_item->>'errorCode', ''),
        last_error_message = nullif(input_item->>'errorMessage', ''),
        last_completed_at = now(),
        updated_at = now()
      where id = queue_row.id;

      completed_count := completed_count + 1;
    elsif resolved_status = 'skipped' then
      update public.learning_review_queue
      set
        queue_state = 'skipped',
        available_at = now(),
        retry_after = null,
        claim_token = null,
        claim_expires_at = null,
        claimed_at = null,
        claimed_by = null,
        last_run_id = nullif(input_item->>'lastRunId', '')::uuid,
        last_error_code = nullif(input_item->>'errorCode', ''),
        last_error_message = nullif(input_item->>'errorMessage', ''),
        updated_at = now()
      where id = queue_row.id;

      skipped_count := skipped_count + 1;
    elsif queue_row.attempt_count >= queue_row.max_attempts or resolved_status = 'dead_lettered' then
      update public.learning_review_queue
      set
        queue_state = 'dead_lettered',
        available_at = coalesce(resolved_retry_after, available_at),
        retry_after = resolved_retry_after,
        claim_token = null,
        claim_expires_at = null,
        claimed_at = null,
        claimed_by = null,
        last_run_id = nullif(input_item->>'lastRunId', '')::uuid,
        last_error_code = nullif(input_item->>'errorCode', ''),
        last_error_message = nullif(input_item->>'errorMessage', ''),
        updated_at = now()
      where id = queue_row.id;

      dead_lettered_count := dead_lettered_count + 1;
    else
      update public.learning_review_queue
      set
        queue_state = 'retry_scheduled',
        available_at = coalesce(resolved_retry_after, now()),
        retry_after = coalesce(resolved_retry_after, now()),
        claim_token = null,
        claim_expires_at = null,
        claimed_at = null,
        claimed_by = null,
        last_run_id = nullif(input_item->>'lastRunId', '')::uuid,
        last_error_code = nullif(input_item->>'errorCode', ''),
        last_error_message = nullif(input_item->>'errorMessage', ''),
        updated_at = now()
      where id = queue_row.id;

      retried_count := retried_count + 1;
    end if;
  end loop;

  return jsonb_build_object(
    'count', jsonb_array_length(finalized_ids),
    'ids', finalized_ids,
    'completedCount', completed_count,
    'retriedCount', retried_count,
    'deadLetteredCount', dead_lettered_count,
    'skippedCount', skipped_count
  );
end;
$$;


ALTER FUNCTION "public"."finalize_learning_review_batch"("p_inputs" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."finalize_material_import_job_v2"("p_job_id" "uuid", "p_lease_token" "uuid", "p_outcome" "text", "p_rows" "jsonb", "p_batch" "jsonb", "p_run" "jsonb", "p_retry_seconds" integer DEFAULT 0) RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  j public.organization_material_import_jobs%rowtype;
  outcome text := p_outcome;
  payload jsonb;
begin
  if auth.role() is distinct from 'service_role' then raise exception 'service_role required' using errcode='42501'; end if;
  select * into j from public.organization_material_import_jobs where id=p_job_id for update;
  if not found or p_lease_token is null or j.lease_expires_at is null or j.state<>'processing' or j.lease_token is distinct from p_lease_token or j.lease_expires_at<=now() then
    raise exception 'Material import lease lost' using errcode='40001';
  end if;
  if j.cancel_requested_at is not null then outcome := 'cancelled'; end if;
  if outcome is null or outcome not in ('completed','failed','queued','cancelled') then raise exception 'Invalid job outcome'; end if;
  perform 1 from public.organization_material_import_batches where id=j.import_batch_id and organization_id=j.organization_id for update;
  if not found then raise exception 'Import batch not found'; end if;
  if outcome='completed' then
    if jsonb_typeof(p_rows) is distinct from 'array' or jsonb_array_length(p_rows)>20000 then raise exception 'Invalid review rows'; end if;
    delete from public.organization_material_import_rows
      where organization_id=j.organization_id and import_batch_id=j.import_batch_id and status='pending_review';
    for payload in select value from jsonb_array_elements(p_rows) loop
      insert into public.organization_material_import_rows
      select (jsonb_populate_record(null::public.organization_material_import_rows,
        jsonb_build_object('id',gen_random_uuid(),'row_index',0,'action','pending','source_payload','{}'::jsonb,
          'classified_needs_review',false,'classified_ai_construction_intelligence','{}'::jsonb)
        || payload || jsonb_build_object('organization_id',j.organization_id,'import_batch_id',j.import_batch_id,
          'status','pending_review','created_at',now(),'updated_at',now()))).*;
    end loop;
    update public.organization_material_import_batches set status='ready_for_review',rows_extracted=jsonb_array_length(p_rows),
      extraction_method=p_batch->>'extraction_method',extraction_summary=coalesce(p_batch->'extraction_summary','{}'::jsonb)
      where id=j.import_batch_id and organization_id=j.organization_id;
  elsif outcome in ('failed','cancelled') then
    update public.organization_material_import_batches set status=outcome,
      extraction_summary=case when outcome='failed' then coalesce(p_batch->'extraction_summary','{}'::jsonb) else extraction_summary end
      where id=j.import_batch_id and organization_id=j.organization_id;
  end if;
  update public.organization_material_import_runs set
    status=case when outcome='completed' and coalesce((p_run->>'partial')::boolean,false) then 'partial' else outcome end,
    model=p_run->>'model',prompt_version=p_run->>'prompt_version',
    request_ids=coalesce(p_run->'request_ids','[]'::jsonb),usage_json=coalesce(p_run->'usage_json','{}'::jsonb),
    chunk_manifest=coalesce(p_run->'chunk_manifest','{}'::jsonb),partial=coalesce((p_run->>'partial')::boolean,false),
    error_code=p_run->>'error_code',error_message=p_run->>'error_message',
    completed_at=case when outcome='queued' then null else now() end,
    duration_ms=(p_run->>'duration_ms')::integer
    where id=j.run_id and organization_id=j.organization_id;
  if not found then raise exception 'Import run not found'; end if;
  update public.organization_material_import_jobs set state=outcome,
    run_after=case when outcome='queued' then now()+make_interval(secs=>greatest(15,least(coalesce(p_retry_seconds,15),3600))) else run_after end,
    lease_owner=null,lease_token=null,lease_expires_at=null,
    last_error_code=p_run->>'error_code',last_error_message=p_run->>'error_message'
    where id=j.id;
  return outcome;
end; $$;


ALTER FUNCTION "public"."finalize_material_import_job_v2"("p_job_id" "uuid", "p_lease_token" "uuid", "p_outcome" "text", "p_rows" "jsonb", "p_batch" "jsonb", "p_run" "jsonb", "p_retry_seconds" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."finalize_opportunity_award_pricing_core_v1"("p_organization_id" "uuid", "p_opportunity_id" "uuid", "p_project_id" "uuid", "p_accepted_quote_id" "uuid") RETURNS TABLE("manifest_id" "uuid", "working_quote_id" "uuid", "classification" "text", "source_workbook_count" integer, "worksheet_line_count" integer, "manual_line_count" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  actor_user_id uuid := auth.uid();
  accepted_quote public.project_quotes%rowtype;
  existing_manifest public.opportunity_award_pricing_manifests%rowtype;
  source_workbook public.opportunity_pricing_worksheets%rowtype;
  source_sheet public.opportunity_pricing_workbook_sheets%rowtype;
  default_source_sheet public.opportunity_pricing_workbook_sheets%rowtype;
  created_workbook public.opportunity_pricing_worksheets%rowtype;
  created_sheet public.opportunity_pricing_workbook_sheets%rowtype;
  resolved_manifest_id uuid := gen_random_uuid();
  resolved_working_quote_id uuid;
  resolved_classification text;
  resolved_source_workbook_count integer := 0;
  resolved_worksheet_line_count integer := 0;
  resolved_manual_line_count integer := 0;
  resolved_quote_line_count integer := 0;
  resolved_working_quote_number text;
  resolved_parent_worksheet_data jsonb;
begin
  if actor_user_id is null then
    raise exception 'Authentication is required' using errcode = '42501';
  end if;

  if not (
    public.has_org_permission(p_organization_id, 'leads.opportunities.write')
    and public.has_org_permission(p_organization_id, 'quotes.write')
  ) then
    raise exception 'Not authorized for this organization' using errcode = '42501';
  end if;

  select * into existing_manifest
  from public.opportunity_award_pricing_manifests manifest
  where manifest.organization_id = p_organization_id
    and manifest.opportunity_id = p_opportunity_id;

  if found then
    if existing_manifest.project_id is distinct from p_project_id
      or existing_manifest.accepted_quote_id is distinct from p_accepted_quote_id
      or existing_manifest.working_quote_id is null
    then
      raise exception 'Opportunity award pricing manifest conflicts with the final Project mapping'
        using errcode = 'TS409';
    end if;

    return query select
      existing_manifest.id,
      existing_manifest.working_quote_id,
      existing_manifest.classification,
      existing_manifest.source_workbook_count,
      existing_manifest.worksheet_line_count,
      existing_manifest.manual_line_count;
    return;
  end if;

  if not exists (
    select 1
    from public.opportunity_final_projects mapping
    where mapping.organization_id = p_organization_id
      and mapping.opportunity_id = p_opportunity_id
      and mapping.project_id = p_project_id
      and mapping.accepted_quote_id = p_accepted_quote_id
  ) then
    raise exception 'Final Project and accepted quote mapping is missing' using errcode = 'TS409';
  end if;

  select * into accepted_quote
  from public.project_quotes quote
  where quote.organization_id = p_organization_id
    and quote.id = p_accepted_quote_id
    and quote.originating_opportunity_id = p_opportunity_id
    and quote.project_id = p_project_id
  for update;

  if not found or accepted_quote.status <> 'Accepted' then
    raise exception 'Accepted quote pricing basis is unavailable' using errcode = 'TS422';
  end if;

  if accepted_quote.award_locked_at is not null then
    raise exception 'Accepted quote is locked without an award pricing manifest' using errcode = 'TS409';
  end if;

  if exists (
    select 1
    from public.project_quote_line_items line
    where line.organization_id = p_organization_id
      and line.quote_id = p_accepted_quote_id
      and line.pricing_source_kind = 'unresolved'
  ) then
    raise exception 'Accepted quote pricing basis requires reconciliation before award'
      using errcode = 'TS409';
  end if;

  if exists (
    select 1
    from public.project_quote_line_items line
    left join public.commercial_item_document_links link
      on link.organization_id = line.organization_id
     and link.document_kind = 'quote_line'
     and link.link_role = 'source'
     and link.document_id = line.quote_id
     and link.document_line_id = line.id
    left join public.commercial_items item
      on item.organization_id = link.organization_id
     and item.id = link.commercial_item_id
    left join public.opportunity_pricing_worksheets workbook
      on workbook.organization_id = item.organization_id
     and workbook.id = item.source_workbook_id
    left join public.opportunity_pricing_workbook_sheets sheet
      on sheet.organization_id = item.organization_id
     and sheet.workbook_id = item.source_workbook_id
     and sheet.id = item.source_sheet_id
    where line.organization_id = p_organization_id
      and line.quote_id = p_accepted_quote_id
      and (
        (line.pricing_source_kind = 'worksheet' and link.id is null)
        or (link.id is not null and (
          item.id is null
          or item.opportunity_id <> p_opportunity_id
          or workbook.id is null
          or workbook.opportunity_id <> p_opportunity_id
          or workbook.quote_id is not null
          or workbook.variation_id is not null
          or workbook.archived_at is not null
          or sheet.id is null
        ))
      )
  ) then
    raise exception 'Accepted quote pricing basis contains broken worksheet lineage'
      using errcode = 'TS409';
  end if;

  if exists (
    select 1
    from public.commercial_item_document_links link
    where link.organization_id = p_organization_id
      and link.document_kind = 'quote_line'
      and link.document_id = p_accepted_quote_id
      and link.link_role = 'source'
    group by link.document_line_id
    having count(*) <> 1
  ) then
    raise exception 'Accepted quote pricing basis contains duplicate line evidence'
      using errcode = 'TS409';
  end if;

  select count(*)::integer
  into resolved_quote_line_count
  from public.project_quote_line_items line
  where line.organization_id = p_organization_id
    and line.quote_id = p_accepted_quote_id;

  select
    count(distinct link.document_line_id)::integer,
    count(distinct item.source_workbook_id)::integer
  into resolved_worksheet_line_count, resolved_source_workbook_count
  from public.commercial_item_document_links link
  join public.commercial_items item
    on item.organization_id = link.organization_id
   and item.id = link.commercial_item_id
  where link.organization_id = p_organization_id
    and link.document_kind = 'quote_line'
    and link.document_id = p_accepted_quote_id
    and link.link_role = 'source';

  resolved_worksheet_line_count := coalesce(resolved_worksheet_line_count, 0);
  resolved_source_workbook_count := coalesce(resolved_source_workbook_count, 0);
  resolved_manual_line_count := resolved_quote_line_count - resolved_worksheet_line_count;

  if resolved_manual_line_count < 0 then
    raise exception 'Accepted quote pricing basis contains duplicate line evidence'
      using errcode = 'TS409';
  elsif resolved_quote_line_count = 0 then
    resolved_classification := 'NO_WORKSHEET';
  elsif resolved_worksheet_line_count = 0 then
    resolved_classification := 'MANUAL_ONLY';
  elsif resolved_manual_line_count > 0 then
    resolved_classification := 'MIXED';
  elsif resolved_source_workbook_count = 1 then
    resolved_classification := 'EXACT';
  else
    resolved_classification := 'DERIVABLE';
  end if;

  resolved_working_quote_id := md5(resolved_manifest_id::text || ':working-quote')::uuid;
  resolved_working_quote_number := accepted_quote.quote_number || '-P1';

  if exists (
    select 1 from public.project_quotes quote
    where quote.organization_id = p_organization_id
      and quote.quote_number = resolved_working_quote_number
  ) then
    raise exception 'Project working quote number already exists; reconciliation is required'
      using errcode = 'TS409';
  end if;

  insert into public.project_quotes (
    id, organization_id, project_id, originating_opportunity_id, source_opportunity_id,
    source_opportunity_quote_id, source_opportunity_quote_number, created_by,
    quote_title, quote_number, client_name, company_name, contact_person, client_email,
    client_phone, site_address, project_name, quote_date, expiry_date, status,
    optional_items_notes, scope_exclusions, assumptions, scope_notes, subtotal,
    optional_subtotal, margin_percent, margin_amount, discount_amount, contingency_amount,
    gst_percent, gst_amount, total_quote_price, validity_period, payment_terms,
    retention_percent_default, lead_time, terms_inclusions, terms_exclusions,
    clarifications, acceptance_notes, predecessor_quote_id, revision_number,
    revision_kind, revision_created_at, revision_created_by, publication_basis_hash, published_at
  ) values (
    resolved_working_quote_id, p_organization_id, p_project_id, p_opportunity_id,
    p_opportunity_id, accepted_quote.source_opportunity_quote_id,
    accepted_quote.source_opportunity_quote_number, actor_user_id,
    accepted_quote.quote_title, resolved_working_quote_number, accepted_quote.client_name,
    accepted_quote.company_name, accepted_quote.contact_person, accepted_quote.client_email,
    accepted_quote.client_phone, accepted_quote.site_address, accepted_quote.project_name,
    accepted_quote.quote_date, accepted_quote.expiry_date, 'Draft',
    accepted_quote.optional_items_notes, accepted_quote.scope_exclusions,
    accepted_quote.assumptions, accepted_quote.scope_notes, accepted_quote.subtotal,
    accepted_quote.optional_subtotal, accepted_quote.margin_percent, accepted_quote.margin_amount,
    accepted_quote.discount_amount, accepted_quote.contingency_amount, accepted_quote.gst_percent,
    accepted_quote.gst_amount, accepted_quote.total_quote_price, accepted_quote.validity_period,
    accepted_quote.payment_terms, accepted_quote.retention_percent_default,
    accepted_quote.lead_time, accepted_quote.terms_inclusions, accepted_quote.terms_exclusions,
    accepted_quote.clarifications, accepted_quote.acceptance_notes, accepted_quote.id,
    accepted_quote.revision_number + 1, 'project_working', timezone('utc', now()),
    actor_user_id, accepted_quote.publication_basis_hash, accepted_quote.published_at
  );

  insert into public.project_quote_line_items (
    id, organization_id, project_id, quote_id, section, description, quantity, unit,
    rate, total, is_optional, sort_order, source_opportunity_quote_id,
    source_opportunity_quote_line_item_id, source_opportunity_quote_number,
    pricing_source_kind
  )
  select
    md5(resolved_manifest_id::text || ':working-line:' || line.id::text)::uuid,
    line.organization_id, p_project_id, resolved_working_quote_id, line.section,
    line.description, line.quantity, line.unit, line.rate, line.total, line.is_optional,
    line.sort_order, line.source_opportunity_quote_id,
    line.source_opportunity_quote_line_item_id, line.source_opportunity_quote_number,
    line.pricing_source_kind
  from public.project_quote_line_items line
  where line.organization_id = p_organization_id
    and line.quote_id = p_accepted_quote_id;

  insert into public.opportunity_award_pricing_manifests (
    id, organization_id, opportunity_id, project_id, accepted_quote_id, working_quote_id,
    classification, source_workbook_count, worksheet_line_count, manual_line_count,
    quote_subtotal_snapshot, quote_gst_snapshot, quote_total_snapshot, created_by
  ) values (
    resolved_manifest_id, p_organization_id, p_opportunity_id, p_project_id,
    p_accepted_quote_id, resolved_working_quote_id, resolved_classification,
    resolved_source_workbook_count, resolved_worksheet_line_count,
    resolved_manual_line_count, accepted_quote.subtotal, accepted_quote.gst_amount,
    accepted_quote.total_quote_price, actor_user_id
  );

  insert into public.opportunity_award_pricing_manifest_sources (
    id, organization_id, manifest_id, source_workbook_id, source_sheet_id,
    source_workbook_version, source_sheet_version, source_range, source_signature,
    commercial_item_id, workbook_snapshot, sheet_snapshot, material_bindings_snapshot
  )
  select
    md5(resolved_manifest_id::text || ':source:' || item.id::text)::uuid,
    p_organization_id, resolved_manifest_id, workbook.id, sheet.id, workbook.version,
    sheet.version, item.source_range, item.source_signature, item.id,
    jsonb_build_object(
      'id', workbook.id, 'name', workbook.name, 'tradePackage', workbook.trade_package,
      'sortOrder', workbook.sort_order, 'version', workbook.version,
      'worksheetData', workbook.worksheet_data, 'pricingSummary', workbook.pricing_summary,
      'extractedPricingData', workbook.extracted_pricing_data,
      'capturedAt', timezone('utc', now())
    ),
    jsonb_build_object(
      'id', sheet.id, 'name', sheet.name, 'sheetOrder', sheet.sheet_order,
      'isDefault', sheet.is_default, 'version', sheet.version,
      'worksheetData', sheet.worksheet_data, 'pricingSummary', sheet.pricing_summary,
      'extractedPricingData', sheet.extracted_pricing_data,
      'capturedAt', timezone('utc', now())
    ),
    coalesce((
      select jsonb_agg(to_jsonb(binding) order by binding.inserted_at, binding.id)
      from public.worksheet_material_price_bindings binding
      where binding.organization_id = p_organization_id
        and binding.workbook_id = workbook.id
        and binding.sheet_id = sheet.id
    ), '[]'::jsonb)
  from public.commercial_item_document_links link
  join public.commercial_items item
    on item.organization_id = link.organization_id
   and item.id = link.commercial_item_id
  join public.opportunity_pricing_worksheets workbook
    on workbook.organization_id = item.organization_id
   and workbook.id = item.source_workbook_id
  join public.opportunity_pricing_workbook_sheets sheet
    on sheet.organization_id = item.organization_id
   and sheet.workbook_id = item.source_workbook_id
   and sheet.id = item.source_sheet_id
  where link.organization_id = p_organization_id
    and link.document_kind = 'quote_line'
    and link.document_id = p_accepted_quote_id
    and link.link_role = 'source';

  insert into public.opportunity_award_pricing_manifest_lines (
    id, organization_id, manifest_id, quote_line_id, source_kind,
    manifest_source_id, commercial_item_id, quote_line_snapshot
  )
  select
    md5(resolved_manifest_id::text || ':manifest-line:' || line.id::text)::uuid,
    p_organization_id, resolved_manifest_id, line.id,
    case when link.id is null then 'manual' else 'worksheet' end,
    case when link.id is null then null
      else md5(resolved_manifest_id::text || ':source:' || item.id::text)::uuid end,
    item.id,
    jsonb_build_object(
      'id', line.id, 'section', line.section, 'description', line.description,
      'quantity', line.quantity, 'unit', line.unit, 'rate', line.rate,
      'total', line.total, 'isOptional', line.is_optional,
      'sortOrder', line.sort_order, 'capturedAt', timezone('utc', now())
    )
  from public.project_quote_line_items line
  left join public.commercial_item_document_links link
    on link.organization_id = line.organization_id
   and link.document_kind = 'quote_line'
   and link.link_role = 'source'
   and link.document_id = line.quote_id
   and link.document_line_id = line.id
  left join public.commercial_items item
    on item.organization_id = link.organization_id
   and item.id = link.commercial_item_id
  where line.organization_id = p_organization_id
    and line.quote_id = p_accepted_quote_id;

  insert into public.commercial_item_document_links (
    id, organization_id, commercial_item_id, document_kind, document_id,
    document_line_id, link_role, snapshot_at_link_json, created_by, created_at
  )
  select
    md5(resolved_manifest_id::text || ':working-link:' || link.id::text)::uuid,
    link.organization_id, link.commercial_item_id, 'quote_line', resolved_working_quote_id,
    md5(resolved_manifest_id::text || ':working-line:' || link.document_line_id::text)::uuid,
    link.link_role, link.snapshot_at_link_json, actor_user_id, timezone('utc', now())
  from public.commercial_item_document_links link
  where link.organization_id = p_organization_id
    and link.document_kind = 'quote_line'
    and link.document_id = p_accepted_quote_id;

  for source_workbook in
    select distinct workbook.*
    from public.opportunity_award_pricing_manifest_sources source
    join public.opportunity_pricing_worksheets workbook
      on workbook.organization_id = source.organization_id
     and workbook.id = source.source_workbook_id
    where source.organization_id = p_organization_id
      and source.manifest_id = resolved_manifest_id
  loop
    select * into default_source_sheet
    from public.opportunity_pricing_workbook_sheets sheet
    where sheet.organization_id = p_organization_id
      and sheet.workbook_id = source_workbook.id
    order by sheet.is_default desc, sheet.sheet_order, sheet.created_at
    limit 1;

    resolved_parent_worksheet_data := public.regenerate_worksheet_material_binding_ids(
      coalesce(default_source_sheet.worksheet_data, source_workbook.worksheet_data)
    );

    insert into public.opportunity_pricing_worksheets (
      id, organization_id, opportunity_id, project_id, quote_id, variation_id,
      name, trade_package, sort_order, archived_at, last_active_sheet_id,
      worksheet_data, pricing_summary, extracted_pricing_data, version,
      created_by, updated_by, source_workbook_id, source_workbook_version,
      source_award_manifest_id, clone_kind
    ) values (
      md5(resolved_manifest_id::text || ':workbook:' || source_workbook.id::text)::uuid,
      p_organization_id, p_opportunity_id, p_project_id, resolved_working_quote_id, null,
      source_workbook.name, source_workbook.trade_package, source_workbook.sort_order,
      null,
      case when source_workbook.last_active_sheet_id is null then null
        else md5(resolved_manifest_id::text || ':sheet:' || source_workbook.last_active_sheet_id::text)::uuid end,
      resolved_parent_worksheet_data,
      coalesce(default_source_sheet.pricing_summary, source_workbook.pricing_summary),
      coalesce(default_source_sheet.extracted_pricing_data, source_workbook.extracted_pricing_data),
      greatest(coalesce(default_source_sheet.version, source_workbook.version, 1), 1),
      actor_user_id, actor_user_id, source_workbook.id, source_workbook.version,
      resolved_manifest_id, 'project_working'
    ) returning * into created_workbook;

    for source_sheet in
      select *
      from public.opportunity_pricing_workbook_sheets sheet
      where sheet.organization_id = p_organization_id
        and sheet.workbook_id = source_workbook.id
      order by sheet.sheet_order, sheet.created_at
    loop
      insert into public.opportunity_pricing_workbook_sheets (
        id, workbook_id, organization_id, opportunity_id, name, sheet_order,
        is_default, worksheet_data, pricing_summary, extracted_pricing_data,
        version, created_by, updated_by
      ) values (
        md5(resolved_manifest_id::text || ':sheet:' || source_sheet.id::text)::uuid,
        created_workbook.id, p_organization_id, p_opportunity_id, source_sheet.name,
        source_sheet.sheet_order, source_sheet.is_default,
        case when source_sheet.id = default_source_sheet.id then resolved_parent_worksheet_data
          else public.regenerate_worksheet_material_binding_ids(source_sheet.worksheet_data) end,
        source_sheet.pricing_summary, source_sheet.extracted_pricing_data,
        source_sheet.version, actor_user_id, actor_user_id
      ) returning * into created_sheet;
    end loop;
  end loop;

  update public.opportunity_pricing_worksheets workbook
  set award_locked_at = timezone('utc', now()),
      award_locked_reason = 'accepted_tender_basis',
      updated_by = actor_user_id
  where workbook.organization_id = p_organization_id
    and workbook.id in (
      select distinct source.source_workbook_id
      from public.opportunity_award_pricing_manifest_sources source
      where source.organization_id = p_organization_id
        and source.manifest_id = resolved_manifest_id
    );

  update public.project_quotes quote
  set award_locked_at = timezone('utc', now()),
      award_locked_reason = 'opportunity_award'
  where quote.organization_id = p_organization_id
    and quote.id = p_accepted_quote_id;

  return query select resolved_manifest_id, resolved_working_quote_id,
    resolved_classification, resolved_source_workbook_count,
    resolved_worksheet_line_count, resolved_manual_line_count;
end;
$$;


ALTER FUNCTION "public"."finalize_opportunity_award_pricing_core_v1"("p_organization_id" "uuid", "p_opportunity_id" "uuid", "p_project_id" "uuid", "p_accepted_quote_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."finalize_opportunity_award_pricing_v1"("p_organization_id" "uuid", "p_opportunity_id" "uuid", "p_project_id" "uuid", "p_accepted_quote_id" "uuid") RETURNS TABLE("manifest_id" "uuid", "working_quote_id" "uuid", "classification" "text", "source_workbook_count" integer, "worksheet_line_count" integer, "manual_line_count" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  actor_user_id uuid := auth.uid();
  accepted_quote public.project_quotes%rowtype;
  existing_manifest public.opportunity_award_pricing_manifests%rowtype;
  resolved_manifest_id uuid := gen_random_uuid();
  resolved_classification text;
  resolved_source_workbook_count integer := 0;
  resolved_worksheet_line_count integer := 0;
  resolved_manual_line_count integer := 0;
  resolved_quote_line_count integer := 0;
begin
  if actor_user_id is null then
    raise exception 'Authentication is required' using errcode = '42501';
  end if;

  if not (
    public.has_org_permission(p_organization_id, 'leads.opportunities.write')
    and public.has_org_permission(p_organization_id, 'quotes.write')
  ) then
    raise exception 'Not authorized for this organization' using errcode = '42501';
  end if;

  select * into existing_manifest
  from public.opportunity_award_pricing_manifests manifest
  where manifest.organization_id = p_organization_id
    and manifest.opportunity_id = p_opportunity_id;

  if found then
    if existing_manifest.project_id is distinct from p_project_id
      or existing_manifest.accepted_quote_id is distinct from p_accepted_quote_id
    then
      raise exception 'Opportunity award pricing manifest conflicts with the final Project mapping'
        using errcode = 'TS409';
    end if;

    perform * from public.ensure_opportunity_project_pricing_workbooks_v1(
      p_organization_id, p_opportunity_id, p_project_id, p_accepted_quote_id
    );

    return query select
      existing_manifest.id,
      existing_manifest.working_quote_id,
      existing_manifest.classification,
      existing_manifest.source_workbook_count,
      existing_manifest.worksheet_line_count,
      existing_manifest.manual_line_count;
    return;
  end if;

  if not exists (
    select 1 from public.opportunity_final_projects mapping
    where mapping.organization_id = p_organization_id
      and mapping.opportunity_id = p_opportunity_id
      and mapping.project_id = p_project_id
      and mapping.accepted_quote_id = p_accepted_quote_id
  ) then
    raise exception 'Final Project and accepted quote mapping is missing' using errcode = 'TS409';
  end if;

  select * into accepted_quote
  from public.project_quotes quote
  where quote.organization_id = p_organization_id
    and quote.id = p_accepted_quote_id
    and quote.originating_opportunity_id = p_opportunity_id
    and quote.project_id = p_project_id
  for update;

  if not found or accepted_quote.status <> 'Accepted' then
    raise exception 'Accepted quote pricing basis is unavailable' using errcode = 'TS422';
  end if;

  if accepted_quote.award_locked_at is not null then
    raise exception 'Accepted quote is locked without an award pricing manifest' using errcode = 'TS409';
  end if;

  if exists (
    select 1 from public.project_quote_line_items line
    where line.organization_id = p_organization_id
      and line.quote_id = p_accepted_quote_id
      and line.pricing_source_kind = 'unresolved'
  ) then
    raise exception 'Accepted quote pricing basis requires reconciliation before award'
      using errcode = 'TS409';
  end if;

  if exists (
    select 1
    from public.project_quote_line_items line
    left join public.commercial_item_document_links link
      on link.organization_id = line.organization_id
     and link.document_kind = 'quote_line'
     and link.link_role = 'source'
     and link.document_id = line.quote_id
     and link.document_line_id = line.id
    left join public.commercial_items item
      on item.organization_id = link.organization_id and item.id = link.commercial_item_id
    left join public.opportunity_pricing_worksheets workbook
      on workbook.organization_id = item.organization_id and workbook.id = item.source_workbook_id
    left join public.opportunity_pricing_workbook_sheets sheet
      on sheet.organization_id = item.organization_id
     and sheet.workbook_id = item.source_workbook_id and sheet.id = item.source_sheet_id
    where line.organization_id = p_organization_id
      and line.quote_id = p_accepted_quote_id
      and (
        (line.pricing_source_kind = 'worksheet' and link.id is null)
        or (link.id is not null and (
          item.id is null
          or item.opportunity_id <> p_opportunity_id
          or workbook.id is null
          or workbook.opportunity_id <> p_opportunity_id
          or workbook.quote_id is not null
          or workbook.variation_id is not null
          or workbook.archived_at is not null
          or sheet.id is null
        ))
      )
  ) then
    raise exception 'Accepted quote pricing basis contains broken worksheet lineage'
      using errcode = 'TS409';
  end if;

  if exists (
    select 1 from public.commercial_item_document_links link
    where link.organization_id = p_organization_id
      and link.document_kind = 'quote_line'
      and link.document_id = p_accepted_quote_id
      and link.link_role = 'source'
    group by link.document_line_id
    having count(*) <> 1
  ) then
    raise exception 'Accepted quote pricing basis contains duplicate line evidence'
      using errcode = 'TS409';
  end if;

  select count(*)::integer into resolved_quote_line_count
  from public.project_quote_line_items line
  where line.organization_id = p_organization_id and line.quote_id = p_accepted_quote_id;

  select count(distinct link.document_line_id)::integer,
    count(distinct item.source_workbook_id)::integer
  into resolved_worksheet_line_count, resolved_source_workbook_count
  from public.commercial_item_document_links link
  join public.commercial_items item
    on item.organization_id = link.organization_id and item.id = link.commercial_item_id
  where link.organization_id = p_organization_id
    and link.document_kind = 'quote_line'
    and link.document_id = p_accepted_quote_id
    and link.link_role = 'source';

  resolved_worksheet_line_count := coalesce(resolved_worksheet_line_count, 0);
  resolved_source_workbook_count := coalesce(resolved_source_workbook_count, 0);
  resolved_manual_line_count := resolved_quote_line_count - resolved_worksheet_line_count;

  if resolved_manual_line_count < 0 then
    raise exception 'Accepted quote pricing basis contains duplicate line evidence'
      using errcode = 'TS409';
  elsif resolved_quote_line_count = 0 then
    resolved_classification := 'NO_WORKSHEET';
  elsif resolved_worksheet_line_count = 0 then
    resolved_classification := 'MANUAL_ONLY';
  elsif resolved_manual_line_count > 0 then
    resolved_classification := 'MIXED';
  elsif resolved_source_workbook_count = 1 then
    resolved_classification := 'EXACT';
  else
    resolved_classification := 'DERIVABLE';
  end if;

  insert into public.opportunity_award_pricing_manifests (
    id, organization_id, opportunity_id, project_id, accepted_quote_id, working_quote_id,
    classification, source_workbook_count, worksheet_line_count, manual_line_count,
    quote_subtotal_snapshot, quote_gst_snapshot, quote_total_snapshot, created_by
  ) values (
    resolved_manifest_id, p_organization_id, p_opportunity_id, p_project_id,
    p_accepted_quote_id, null, resolved_classification, resolved_source_workbook_count,
    resolved_worksheet_line_count, resolved_manual_line_count, accepted_quote.subtotal,
    accepted_quote.gst_amount, accepted_quote.total_quote_price, actor_user_id
  );

  insert into public.opportunity_award_pricing_manifest_sources (
    id, organization_id, manifest_id, source_workbook_id, source_sheet_id,
    source_workbook_version, source_sheet_version, source_range, source_signature,
    commercial_item_id, workbook_snapshot, sheet_snapshot, material_bindings_snapshot
  )
  select md5(resolved_manifest_id::text || ':source:' || item.id::text)::uuid,
    p_organization_id, resolved_manifest_id, workbook.id, sheet.id, workbook.version,
    sheet.version, item.source_range, item.source_signature, item.id,
    jsonb_build_object(
      'id', workbook.id, 'name', workbook.name, 'tradePackage', workbook.trade_package,
      'sortOrder', workbook.sort_order, 'version', workbook.version,
      'worksheetData', workbook.worksheet_data, 'pricingSummary', workbook.pricing_summary,
      'extractedPricingData', workbook.extracted_pricing_data,
      'capturedAt', timezone('utc', now())
    ),
    jsonb_build_object(
      'id', sheet.id, 'name', sheet.name, 'sheetOrder', sheet.sheet_order,
      'isDefault', sheet.is_default, 'version', sheet.version,
      'worksheetData', sheet.worksheet_data, 'pricingSummary', sheet.pricing_summary,
      'extractedPricingData', sheet.extracted_pricing_data,
      'capturedAt', timezone('utc', now())
    ),
    coalesce((
      select jsonb_agg(to_jsonb(binding) order by binding.inserted_at, binding.id)
      from public.worksheet_material_price_bindings binding
      where binding.organization_id = p_organization_id
        and binding.workbook_id = workbook.id and binding.sheet_id = sheet.id
    ), '[]'::jsonb)
  from public.commercial_item_document_links link
  join public.commercial_items item
    on item.organization_id = link.organization_id and item.id = link.commercial_item_id
  join public.opportunity_pricing_worksheets workbook
    on workbook.organization_id = item.organization_id and workbook.id = item.source_workbook_id
  join public.opportunity_pricing_workbook_sheets sheet
    on sheet.organization_id = item.organization_id
   and sheet.workbook_id = item.source_workbook_id and sheet.id = item.source_sheet_id
  where link.organization_id = p_organization_id
    and link.document_kind = 'quote_line'
    and link.document_id = p_accepted_quote_id
    and link.link_role = 'source';

  insert into public.opportunity_award_pricing_manifest_lines (
    id, organization_id, manifest_id, quote_line_id, source_kind,
    manifest_source_id, commercial_item_id, quote_line_snapshot
  )
  select md5(resolved_manifest_id::text || ':manifest-line:' || line.id::text)::uuid,
    p_organization_id, resolved_manifest_id, line.id,
    case when link.id is null then 'manual' else 'worksheet' end,
    case when link.id is null then null
      else md5(resolved_manifest_id::text || ':source:' || item.id::text)::uuid end,
    item.id,
    jsonb_build_object(
      'id', line.id, 'section', line.section, 'description', line.description,
      'quantity', line.quantity, 'unit', line.unit, 'rate', line.rate,
      'total', line.total, 'isOptional', line.is_optional,
      'sortOrder', line.sort_order, 'capturedAt', timezone('utc', now())
    )
  from public.project_quote_line_items line
  left join public.commercial_item_document_links link
    on link.organization_id = line.organization_id
   and link.document_kind = 'quote_line' and link.link_role = 'source'
   and link.document_id = line.quote_id and link.document_line_id = line.id
  left join public.commercial_items item
    on item.organization_id = link.organization_id and item.id = link.commercial_item_id
  where line.organization_id = p_organization_id and line.quote_id = p_accepted_quote_id;

  update public.project_quotes quote
  set award_locked_at = timezone('utc', now()),
      award_locked_reason = 'opportunity_award'
  where quote.organization_id = p_organization_id and quote.id = p_accepted_quote_id;

  perform * from public.ensure_opportunity_project_pricing_workbooks_v1(
    p_organization_id, p_opportunity_id, p_project_id, p_accepted_quote_id
  );

  return query select resolved_manifest_id, null::uuid, resolved_classification,
    resolved_source_workbook_count, resolved_worksheet_line_count, resolved_manual_line_count;
end;
$$;


ALTER FUNCTION "public"."finalize_opportunity_award_pricing_v1"("p_organization_id" "uuid", "p_opportunity_id" "uuid", "p_project_id" "uuid", "p_accepted_quote_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."finalize_opportunity_promotion_shadow_v1"("p_organization_id" "uuid", "p_run_id" "uuid", "p_final_project_id" "uuid", "p_actor_user_id" "uuid") RETURNS TABLE("finalized" boolean, "comparison_result" "text", "mismatch_codes" "text"[])
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  control_row public.opportunity_promotion_shadow_controls%rowtype;
  run_row public.opportunity_promotion_shadow_runs%rowtype;
  mapping_row public.opportunity_final_projects%rowtype;
  final_row public.organization_projects%rowtype;
  baseline record;
  final_document_workspace_id uuid;
  post_value jsonb;
  mismatches text[] := array[]::text[];
  result_value text;
  pre_quote jsonb;
  pre_commercial jsonb;
  pre_cost jsonb;
  pre_documents jsonb;
  pre_features jsonb;
  actual_visible boolean := false;
  actual_delivery boolean := false;
begin
  if not exists (
    select 1 from public.organization_members member
    where member.organization_id = p_organization_id
      and member.user_id = p_actor_user_id
  ) then
    raise exception 'Not authorized for shadow comparison' using errcode = '42501';
  end if;

  select * into control_row
  from public.opportunity_promotion_shadow_controls control
  where control.organization_id = p_organization_id;
  if control_row.organization_id is null or not control_row.comparison_enabled then
    return query select false, null::text, '{}'::text[];
    return;
  end if;

  select * into run_row
  from public.opportunity_promotion_shadow_runs shadow_run
  where shadow_run.organization_id = p_organization_id
    and shadow_run.id = p_run_id
  for update;
  if run_row.id is null then
    return query select false, 'comparison_error'::text,
      array['comparison_failed']::text[];
    return;
  end if;
  if run_row.status <> 'pre_observed' then
    return query select false, run_row.comparison_result, run_row.mismatch_codes;
    return;
  end if;

  select * into mapping_row
  from public.opportunity_final_projects mapping
  where mapping.organization_id = p_organization_id
    and mapping.opportunity_id = run_row.opportunity_id;
  select * into final_row
  from public.organization_projects project
  where project.organization_id = p_organization_id
    and project.id = p_final_project_id;
  select * into baseline
  from public.resolve_project_contractual_baseline_v1(
    p_organization_id, p_final_project_id
  );
  select link.workspace_id into final_document_workspace_id
  from public.document_workspace_entities link
  where link.organization_id = p_organization_id
    and link.project_id = p_final_project_id;

  select exists (
    select 1 from public.get_visible_project_ids_v1(
      p_organization_id, array[p_final_project_id]::uuid[]
    ) visible where visible.project_id = p_final_project_id
  ) into actual_visible;
  actual_delivery := public.is_project_delivery_eligible_v1(
    p_organization_id, p_final_project_id
  );

  post_value := jsonb_build_object(
    'identity', jsonb_build_object(
      'opportunity_id', run_row.opportunity_id,
      'workspace_project_id', run_row.workspace_project_id,
      'final_project_id', p_final_project_id,
      'final_source_opportunity_id', final_row.source_opportunity_id,
      'mapped_project_id', mapping_row.project_id
    ),
    'quote', jsonb_build_object(
      'id', baseline.quote_id,
      'subtotal', (select coalesce(quote.subtotal, 0) from public.project_quotes quote
        where quote.organization_id = p_organization_id and quote.id = baseline.quote_id),
      'tax', (select coalesce(quote.gst_amount, 0) from public.project_quotes quote
        where quote.organization_id = p_organization_id and quote.id = baseline.quote_id),
      'total', (select coalesce(quote.total_quote_price, 0) from public.project_quotes quote
        where quote.organization_id = p_organization_id and quote.id = baseline.quote_id),
      'line_count', (select count(*) from public.project_quote_line_items line
        where line.organization_id = p_organization_id
          and line.quote_id = baseline.quote_id and line.project_id = p_final_project_id)
    ),
    'commercial', jsonb_build_object(
      'item_count', (select count(*) from public.commercial_items item
        where item.organization_id = p_organization_id
          and item.opportunity_id = run_row.opportunity_id
          and item.project_id = p_final_project_id),
      'total', (select coalesce(sum(item.total), 0) from public.commercial_items item
        where item.organization_id = p_organization_id
          and item.opportunity_id = run_row.opportunity_id
          and item.project_id = p_final_project_id)
    ),
    'cost', jsonb_build_object(
      'item_count', (select count(*) from public.cost_items cost
        where cost.organization_id = p_organization_id
          and cost.source_document_kind = 'project_quote'
          and cost.source_document_id = baseline.quote_id
          and cost.project_id = p_final_project_id and cost.is_current),
      'total', (select coalesce(sum(cost.line_total), 0) from public.cost_items cost
        where cost.organization_id = p_organization_id
          and cost.source_document_kind = 'project_quote'
          and cost.source_document_id = baseline.quote_id
          and cost.project_id = p_final_project_id and cost.is_current)
    ),
    'documents', jsonb_build_object(
      'workspace_id', final_document_workspace_id,
      'node_count', (select count(*) from public.document_nodes node
        where node.organization_id = p_organization_id
          and node.workspace_id = final_document_workspace_id and node.deleted_at is null),
      'version_count', (select count(*) from public.document_versions version
        where version.organization_id = p_organization_id
          and version.workspace_id = final_document_workspace_id and version.purged_at is null)
    ),
    'features', jsonb_build_object(
      'drawing_set_count', (select count(*) from public.project_drawing_sets drawing
        where drawing.organization_id = p_organization_id and drawing.project_id = p_final_project_id),
      'takeoff_page_count', (select count(*) from public.takeoff_pages page
        where page.organization_id = p_organization_id and page.project_id = p_final_project_id),
      'measurement_count', (select count(*) from public.takeoff_measurements measurement
        where measurement.organization_id = p_organization_id
          and measurement.project_id = p_final_project_id and measurement.archived_at is null),
      'trade_pack_count', (select count(*) from public.trade_packs pack
        where pack.organization_id = p_organization_id and pack.project_id = p_final_project_id),
      'scope_run_count', (select count(*) from public.scope_runs scope
        where scope.organization_id = p_organization_id and scope.project_id = p_final_project_id),
      'task_count', (select count(*) from public.project_job_todos task
        where task.organization_id = p_organization_id
          and task.project_id = p_final_project_id and task.deleted_at is null)
    ),
    'actual', jsonb_build_object(
      'visible', actual_visible,
      'delivery_eligible', actual_delivery
    )
  );

  pre_quote := run_row.pre_snapshot -> 'quote';
  pre_commercial := run_row.pre_snapshot -> 'commercial';
  pre_cost := run_row.pre_snapshot -> 'cost';
  pre_documents := run_row.pre_snapshot -> 'documents';
  pre_features := run_row.pre_snapshot -> 'features';

  if run_row.eligibility_result = 'ineligible' then
    result_value := 'ineligible';
  else
    if p_final_project_id = run_row.workspace_project_id
      or mapping_row.project_id is distinct from p_final_project_id
    then mismatches := array_append(mismatches, 'identity_mismatch'); end if;
    if final_row.source_opportunity_id is distinct from run_row.opportunity_id
    then mismatches := array_append(mismatches, 'lineage_mismatch'); end if;
    if baseline.is_valid is not true
      or baseline.quote_id is distinct from run_row.accepted_quote_id
    then mismatches := array_append(mismatches, 'baseline_quote_mismatch'); end if;
    if (post_value #>> '{quote,subtotal}')::numeric
        is distinct from (pre_quote ->> 'subtotal')::numeric
      or (post_value #>> '{quote,tax}')::numeric
        is distinct from (pre_quote ->> 'tax')::numeric
      or (post_value #>> '{quote,total}')::numeric
        is distinct from (pre_quote ->> 'total')::numeric
    then mismatches := array_append(mismatches, 'baseline_total_mismatch'); end if;
    if (post_value #>> '{quote,line_count}')::integer
      is distinct from (pre_quote ->> 'line_count')::integer
    then mismatches := array_append(mismatches, 'quote_line_count_mismatch'); end if;
    if post_value -> 'commercial' is distinct from pre_commercial
    then mismatches := array_append(mismatches, 'commercial_item_mismatch'); end if;
    if post_value -> 'cost' is distinct from pre_cost
    then mismatches := array_append(mismatches, 'cost_item_mismatch'); end if;
    if post_value #>> '{documents,workspace_id}'
      is distinct from pre_documents ->> 'workspace_id'
    then mismatches := array_append(mismatches, 'document_workspace_mismatch'); end if;
    if (post_value #>> '{documents,node_count}')::integer
        is distinct from (pre_documents ->> 'node_count')::integer
      or (post_value #>> '{documents,version_count}')::integer
        is distinct from (pre_documents ->> 'version_count')::integer
    then mismatches := array_append(mismatches, 'document_count_mismatch'); end if;
    if (post_value #>> '{features,drawing_set_count}')::integer
      is distinct from (pre_features ->> 'drawing_set_count')::integer
    then mismatches := array_append(mismatches, 'drawing_count_mismatch'); end if;
    if (post_value #>> '{features,takeoff_page_count}')::integer
        is distinct from (pre_features ->> 'takeoff_page_count')::integer
      or (post_value #>> '{features,measurement_count}')::integer
        is distinct from (pre_features ->> 'measurement_count')::integer
    then mismatches := array_append(mismatches, 'takeoff_count_mismatch'); end if;
    if (post_value #>> '{features,scope_run_count}')::integer
      is distinct from (pre_features ->> 'scope_run_count')::integer
    then mismatches := array_append(mismatches, 'scope_count_mismatch'); end if;
    if (post_value #>> '{features,trade_pack_count}')::integer
      is distinct from (pre_features ->> 'trade_pack_count')::integer
    then mismatches := array_append(mismatches, 'trade_pack_count_mismatch'); end if;
    if (post_value #>> '{features,task_count}')::integer
      is distinct from (pre_features ->> 'task_count')::integer
    then mismatches := array_append(mismatches, 'task_count_mismatch'); end if;
    if not actual_visible
    then mismatches := array_append(mismatches, 'visibility_mismatch'); end if;
    if not actual_delivery
    then mismatches := array_append(mismatches, 'delivery_eligibility_mismatch'); end if;

    result_value := case
      when cardinality(mismatches) > 0 then 'mismatch'
      when p_final_project_id <> run_row.workspace_project_id then 'expected_difference'
      else 'match'
    end;
  end if;

  update public.opportunity_promotion_shadow_runs shadow_run
  set final_project_id = p_final_project_id,
      status = 'completed',
      post_snapshot = post_value,
      comparison_result = result_value,
      mismatch_codes = mismatches,
      compared_at = timezone('utc', now())
  where shadow_run.id = run_row.id;

  return query select true, result_value, mismatches;
exception when others then
  if run_row.id is not null and run_row.status = 'pre_observed'
    and p_final_project_id is not null
  then
    update public.opportunity_promotion_shadow_runs shadow_run
    set final_project_id = p_final_project_id,
        status = 'comparison_error',
        post_snapshot = jsonb_build_object('error_code', sqlstate),
        comparison_result = 'comparison_error',
        mismatch_codes = array['comparison_failed']::text[],
        compared_at = timezone('utc', now())
    where shadow_run.id = run_row.id;
  end if;
  return query select false, 'comparison_error'::text,
    array['comparison_failed']::text[];
end;
$$;


ALTER FUNCTION "public"."finalize_opportunity_promotion_shadow_v1"("p_organization_id" "uuid", "p_run_id" "uuid", "p_final_project_id" "uuid", "p_actor_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."finalize_opportunity_promotion_shadow_v2"("p_organization_id" "uuid", "p_run_id" "uuid", "p_final_project_id" "uuid", "p_actor_user_id" "uuid") RETURNS TABLE("finalized" boolean, "comparison_result" "text", "mismatch_codes" "text"[], "expected_difference_codes" "text"[])
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  control_row public.opportunity_promotion_shadow_controls%rowtype;
  run_row public.opportunity_promotion_shadow_runs%rowtype;
  mapping_row public.opportunity_final_projects%rowtype;
  final_row public.organization_projects%rowtype;
  baseline record;
  final_document_workspace_id uuid;
  post_value jsonb;
  mismatches text[] := array[]::text[];
  expected_differences text[] := array[]::text[];
  result_value text;
  pre_quote jsonb;
  pre_commercial jsonb;
  pre_cost jsonb;
  pre_documents jsonb;
  pre_features jsonb;
  pre_permanent jsonb;
  post_permanent jsonb;
  actual_visible boolean := false;
  actual_delivery boolean := false;
  legacy_final_task_count integer := 0;
  legacy_final_page_count integer := 0;
  legacy_final_measurement_count integer := 0;
begin
  if not exists (
    select 1 from public.organization_members member
    where member.organization_id = p_organization_id
      and member.user_id = p_actor_user_id
  ) then
    raise exception 'Not authorized for shadow comparison' using errcode = '42501';
  end if;

  select * into control_row
  from public.opportunity_promotion_shadow_controls control
  where control.organization_id = p_organization_id;
  if control_row.organization_id is null
    or not control_row.comparison_enabled
    or control_row.evaluator_version <> 'shadow-v2'
  then
    return query select false, null::text, array[]::text[], array[]::text[];
    return;
  end if;

  select * into run_row
  from public.opportunity_promotion_shadow_runs shadow_run
  where shadow_run.organization_id = p_organization_id
    and shadow_run.id = p_run_id
  for update;
  if run_row.id is null or run_row.evaluator_version <> 'shadow-v2' then
    return query select false, 'comparison_error'::text,
      array['comparison_failed']::text[], array[]::text[];
    return;
  end if;
  if run_row.status <> 'pre_observed' then
    return query select false, run_row.comparison_result, run_row.mismatch_codes,
      run_row.expected_difference_codes;
    return;
  end if;

  select * into mapping_row
  from public.opportunity_final_projects mapping
  where mapping.organization_id = p_organization_id
    and mapping.opportunity_id = run_row.opportunity_id;
  select * into final_row
  from public.organization_projects project
  where project.organization_id = p_organization_id
    and project.id = p_final_project_id;
  select * into baseline
  from public.resolve_project_contractual_baseline_v1(p_organization_id, p_final_project_id);
  select link.workspace_id into final_document_workspace_id
  from public.document_workspace_entities link
  where link.organization_id = p_organization_id
    and link.project_id = p_final_project_id;

  select exists (
    select 1 from public.get_visible_project_ids_v1(
      p_organization_id, array[p_final_project_id]::uuid[]
    ) visible where visible.project_id = p_final_project_id
  ) into actual_visible;
  actual_delivery := public.is_project_delivery_eligible_v1(p_organization_id, p_final_project_id);

  post_permanent := public.get_opportunity_workspace_continuity_snapshot_v1(
    p_organization_id, run_row.opportunity_id, run_row.workspace_project_id
  );
  select count(*)::integer into legacy_final_task_count
  from public.project_job_todos task
  where task.organization_id = p_organization_id
    and task.project_id = p_final_project_id and task.deleted_at is null;
  select count(*)::integer into legacy_final_page_count
  from public.takeoff_pages page
  where page.organization_id = p_organization_id and page.project_id = p_final_project_id;
  select count(*)::integer into legacy_final_measurement_count
  from public.takeoff_measurements measurement
  where measurement.organization_id = p_organization_id
    and measurement.project_id = p_final_project_id and measurement.archived_at is null;

  post_value := jsonb_build_object(
    'identity', jsonb_build_object(
      'opportunity_id', run_row.opportunity_id,
      'workspace_project_id', run_row.workspace_project_id,
      'final_project_id', p_final_project_id,
      'final_source_opportunity_id', final_row.source_opportunity_id,
      'mapped_project_id', mapping_row.project_id
    ),
    'quote', jsonb_build_object(
      'id', baseline.quote_id,
      'subtotal', (select coalesce(quote.subtotal, 0) from public.project_quotes quote
        where quote.organization_id = p_organization_id and quote.id = baseline.quote_id),
      'tax', (select coalesce(quote.gst_amount, 0) from public.project_quotes quote
        where quote.organization_id = p_organization_id and quote.id = baseline.quote_id),
      'total', (select coalesce(quote.total_quote_price, 0) from public.project_quotes quote
        where quote.organization_id = p_organization_id and quote.id = baseline.quote_id),
      'line_count', (select count(*) from public.project_quote_line_items line
        where line.organization_id = p_organization_id
          and line.quote_id = baseline.quote_id and line.project_id = p_final_project_id)
    ),
    'commercial', jsonb_build_object(
      'item_count', (select count(*) from public.commercial_items item
        where item.organization_id = p_organization_id
          and item.opportunity_id = run_row.opportunity_id
          and item.project_id = p_final_project_id),
      'total', (select coalesce(sum(item.total), 0) from public.commercial_items item
        where item.organization_id = p_organization_id
          and item.opportunity_id = run_row.opportunity_id
          and item.project_id = p_final_project_id)
    ),
    'cost', jsonb_build_object(
      'item_count', (select count(*) from public.cost_items cost
        where cost.organization_id = p_organization_id
          and cost.source_document_kind = 'project_quote'
          and cost.source_document_id = baseline.quote_id
          and cost.project_id = p_final_project_id and cost.is_current),
      'total', (select coalesce(sum(cost.line_total), 0) from public.cost_items cost
        where cost.organization_id = p_organization_id
          and cost.source_document_kind = 'project_quote'
          and cost.source_document_id = baseline.quote_id
          and cost.project_id = p_final_project_id and cost.is_current)
    ),
    'documents', jsonb_build_object(
      'workspace_id', final_document_workspace_id,
      'node_count', (select count(*) from public.document_nodes node
        where node.organization_id = p_organization_id
          and node.workspace_id = final_document_workspace_id and node.deleted_at is null),
      'version_count', (select count(*) from public.document_versions version
        where version.organization_id = p_organization_id
          and version.workspace_id = final_document_workspace_id and version.purged_at is null)
    ),
    'features', jsonb_build_object(
      'drawing_set_count', (select count(*) from public.project_drawing_sets drawing
        where drawing.organization_id = p_organization_id and drawing.project_id = p_final_project_id),
      'trade_pack_count', (select count(*) from public.trade_packs pack
        where pack.organization_id = p_organization_id and pack.project_id = p_final_project_id),
      'scope_run_count', (select count(*) from public.scope_runs scope
        where scope.organization_id = p_organization_id and scope.project_id = p_final_project_id)
    ),
    'legacy_final_workspace_domains', jsonb_build_object(
      'task_count', legacy_final_task_count,
      'takeoff_page_count', legacy_final_page_count,
      'measurement_count', legacy_final_measurement_count
    ),
    'permanent_workspace', post_permanent,
    'actual', jsonb_build_object('visible', actual_visible, 'delivery_eligible', actual_delivery)
  );

  pre_quote := run_row.pre_snapshot -> 'quote';
  pre_commercial := run_row.pre_snapshot -> 'commercial';
  pre_cost := run_row.pre_snapshot -> 'cost';
  pre_documents := run_row.pre_snapshot -> 'documents';
  pre_features := run_row.pre_snapshot -> 'features';
  pre_permanent := run_row.pre_snapshot -> 'permanent_workspace';

  if run_row.eligibility_result = 'ineligible' then
    result_value := 'ineligible';
  else
    if p_final_project_id = run_row.workspace_project_id
      or mapping_row.project_id is distinct from p_final_project_id
    then mismatches := array_append(mismatches, 'identity_mismatch'); end if;
    if final_row.source_opportunity_id is distinct from run_row.opportunity_id
    then mismatches := array_append(mismatches, 'lineage_mismatch'); end if;
    if baseline.is_valid is not true or baseline.quote_id is distinct from run_row.accepted_quote_id
    then mismatches := array_append(mismatches, 'baseline_quote_mismatch'); end if;
    if (post_value #>> '{quote,subtotal}')::numeric is distinct from (pre_quote ->> 'subtotal')::numeric
      or (post_value #>> '{quote,tax}')::numeric is distinct from (pre_quote ->> 'tax')::numeric
      or (post_value #>> '{quote,total}')::numeric is distinct from (pre_quote ->> 'total')::numeric
    then mismatches := array_append(mismatches, 'baseline_total_mismatch'); end if;
    if (post_value #>> '{quote,line_count}')::integer is distinct from (pre_quote ->> 'line_count')::integer
    then mismatches := array_append(mismatches, 'quote_line_count_mismatch'); end if;
    if post_value -> 'commercial' is distinct from pre_commercial
    then mismatches := array_append(mismatches, 'commercial_item_mismatch'); end if;
    if post_value -> 'cost' is distinct from pre_cost
    then mismatches := array_append(mismatches, 'cost_item_mismatch'); end if;
    if post_value #>> '{documents,workspace_id}' is distinct from pre_documents ->> 'workspace_id'
    then mismatches := array_append(mismatches, 'document_workspace_mismatch'); end if;
    if (post_value #>> '{documents,node_count}')::integer is distinct from (pre_documents ->> 'node_count')::integer
      or (post_value #>> '{documents,version_count}')::integer is distinct from (pre_documents ->> 'version_count')::integer
    then mismatches := array_append(mismatches, 'document_count_mismatch'); end if;
    if (post_value #>> '{features,drawing_set_count}')::integer
      is distinct from (pre_features ->> 'drawing_set_count')::integer
    then mismatches := array_append(mismatches, 'drawing_count_mismatch'); end if;
    if (post_value #>> '{features,scope_run_count}')::integer
      is distinct from (pre_features ->> 'scope_run_count')::integer
    then mismatches := array_append(mismatches, 'scope_count_mismatch'); end if;
    if (post_value #>> '{features,trade_pack_count}')::integer
      is distinct from (pre_features ->> 'trade_pack_count')::integer
    then mismatches := array_append(mismatches, 'trade_pack_count_mismatch'); end if;

    if post_permanent #> '{tasks,ids}' is distinct from pre_permanent #> '{tasks,ids}'
      or (post_permanent #>> '{tasks,ownership_valid}')::boolean is not true
    then mismatches := array_append(mismatches, 'task_continuity_mismatch'); end if;
    if post_permanent #> '{takeoff,page_ids}' is distinct from pre_permanent #> '{takeoff,page_ids}'
    then mismatches := array_append(mismatches, 'takeoff_page_continuity_mismatch'); end if;
    if post_permanent #> '{takeoff,measurement_ids}' is distinct from pre_permanent #> '{takeoff,measurement_ids}'
      or (post_permanent #>> '{takeoff,quantity_total}')::numeric
        is distinct from (pre_permanent #>> '{takeoff,quantity_total}')::numeric
      or (post_permanent #>> '{takeoff,count_total}')::numeric
        is distinct from (pre_permanent #>> '{takeoff,count_total}')::numeric
    then mismatches := array_append(mismatches, 'measurement_continuity_mismatch'); end if;
    if post_permanent #> '{takeoff,calibration_ids}' is distinct from pre_permanent #> '{takeoff,calibration_ids}'
    then mismatches := array_append(mismatches, 'calibration_continuity_mismatch'); end if;
    if (post_permanent #>> '{takeoff,ownership_valid}')::boolean is not true
      or (post_permanent #>> '{takeoff,relationships_valid}')::boolean is not true
      or (post_permanent #>> '{takeoff,event_count}')::integer
        is distinct from (pre_permanent #>> '{takeoff,event_count}')::integer
      or (post_permanent #>> '{tasks,activity_count}')::integer
        is distinct from (pre_permanent #>> '{tasks,activity_count}')::integer
    then mismatches := array_append(mismatches, 'workspace_history_continuity_mismatch'); end if;
    if post_permanent -> 'pricing' is distinct from pre_permanent -> 'pricing'
    then mismatches := array_append(mismatches, 'pricing_workbook_continuity_mismatch'); end if;
    if not actual_visible then mismatches := array_append(mismatches, 'visibility_mismatch'); end if;
    if not actual_delivery then mismatches := array_append(mismatches, 'delivery_eligibility_mismatch'); end if;

    if cardinality(mismatches) = 0 then
      if legacy_final_task_count is distinct from (pre_permanent #>> '{tasks,count}')::integer then
        expected_differences := array_append(expected_differences, 'legacy_final_does_not_own_workspace_tasks');
      end if;
      if legacy_final_page_count is distinct from (pre_permanent #>> '{takeoff,page_count}')::integer then
        expected_differences := array_append(expected_differences, 'legacy_final_does_not_own_takeoff_pages');
      end if;
      if legacy_final_measurement_count is distinct from (pre_permanent #>> '{takeoff,measurement_count}')::integer then
        expected_differences := array_append(expected_differences, 'legacy_final_does_not_own_takeoff_measurements');
      end if;
      if coalesce((pre_permanent #>> '{tasks,count}')::integer, 0) > 0 then
        expected_differences := array_append(expected_differences, 'promoted_workspace_task_continuity_verified');
      end if;
      if coalesce((pre_permanent #>> '{takeoff,page_count}')::integer, 0) > 0 then
        expected_differences := array_append(expected_differences, 'promoted_workspace_takeoff_continuity_verified');
      end if;
      if coalesce((pre_permanent #>> '{takeoff,measurement_count}')::integer, 0) > 0 then
        expected_differences := array_append(expected_differences, 'promoted_workspace_measurement_continuity_verified');
      end if;
    end if;

    result_value := case
      when cardinality(mismatches) > 0 then 'mismatch'
      when p_final_project_id <> run_row.workspace_project_id then 'expected_difference'
      else 'match'
    end;
  end if;

  update public.opportunity_promotion_shadow_runs shadow_run
  set final_project_id = p_final_project_id,
      status = 'completed',
      post_snapshot = post_value,
      comparison_result = result_value,
      mismatch_codes = mismatches,
      expected_difference_codes = expected_differences,
      compared_at = timezone('utc', now())
  where shadow_run.id = run_row.id;

  return query select true, result_value, mismatches, expected_differences;
exception when others then
  if run_row.id is not null and run_row.status = 'pre_observed' and p_final_project_id is not null then
    update public.opportunity_promotion_shadow_runs shadow_run
    set final_project_id = p_final_project_id,
        status = 'comparison_error',
        post_snapshot = jsonb_build_object('error_code', sqlstate),
        comparison_result = 'comparison_error',
        mismatch_codes = array['comparison_failed']::text[],
        expected_difference_codes = array[]::text[],
        compared_at = timezone('utc', now())
    where shadow_run.id = run_row.id;
  end if;
  return query select false, 'comparison_error'::text,
    array['comparison_failed']::text[], array[]::text[];
end;
$$;


ALTER FUNCTION "public"."finalize_opportunity_promotion_shadow_v2"("p_organization_id" "uuid", "p_run_id" "uuid", "p_final_project_id" "uuid", "p_actor_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."finalize_organization_memory_retirement_batch"("p_inputs" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  input_item jsonb;
  finalized_ids jsonb := '[]'::jsonb;
  queue_row public.organization_memory_retirement_queue%rowtype;
  resolved_status text;
  resolved_retry_after timestamptz;
  completed_count integer := 0;
  retried_count integer := 0;
  dead_lettered_count integer := 0;
begin
  if p_inputs is null or jsonb_typeof(p_inputs) <> 'array' then
    raise exception 'finalize_organization_memory_retirement_batch requires a JSON array payload';
  end if;

  for input_item in
    select value
    from jsonb_array_elements(p_inputs)
  loop
    resolved_status := coalesce(nullif(input_item->>'queueState', ''), 'retry_scheduled');
    resolved_retry_after := nullif(input_item->>'retryAfter', '')::timestamptz;

    select q.*
    into queue_row
    from public.organization_memory_retirement_queue q
    where q.id = nullif(input_item->>'id', '')::uuid
      and q.queue_state = 'claimed'
      and q.claim_token = nullif(input_item->>'claimToken', '')::uuid
    for update;

    if not found then
      continue;
    end if;

    finalized_ids := finalized_ids || jsonb_build_array(queue_row.id);

    if resolved_status = 'completed' then
      update public.organization_memory_retirement_queue
      set
        queue_state = 'completed',
        available_at = now(),
        retry_after = null,
        claim_token = null,
        claim_expires_at = null,
        claimed_at = null,
        claimed_by = null,
        last_error_code = nullif(input_item->>'errorCode', ''),
        last_error_message = nullif(input_item->>'errorMessage', ''),
        last_no_action_reason = nullif(input_item->>'noActionReason', ''),
        last_completed_at = now(),
        updated_at = now()
      where id = queue_row.id;

      completed_count := completed_count + 1;
    elsif queue_row.attempt_count >= queue_row.max_attempts or resolved_status = 'dead_lettered' then
      update public.organization_memory_retirement_queue
      set
        queue_state = 'dead_lettered',
        available_at = coalesce(resolved_retry_after, available_at),
        retry_after = resolved_retry_after,
        claim_token = null,
        claim_expires_at = null,
        claimed_at = null,
        claimed_by = null,
        last_error_code = nullif(input_item->>'errorCode', ''),
        last_error_message = nullif(input_item->>'errorMessage', ''),
        last_no_action_reason = nullif(input_item->>'noActionReason', ''),
        updated_at = now()
      where id = queue_row.id;

      dead_lettered_count := dead_lettered_count + 1;
    else
      update public.organization_memory_retirement_queue
      set
        queue_state = 'retry_scheduled',
        available_at = coalesce(resolved_retry_after, now()),
        retry_after = coalesce(resolved_retry_after, now()),
        claim_token = null,
        claim_expires_at = null,
        claimed_at = null,
        claimed_by = null,
        last_error_code = nullif(input_item->>'errorCode', ''),
        last_error_message = nullif(input_item->>'errorMessage', ''),
        last_no_action_reason = nullif(input_item->>'noActionReason', ''),
        updated_at = now()
      where id = queue_row.id;

      retried_count := retried_count + 1;
    end if;
  end loop;

  return jsonb_build_object(
    'count', jsonb_array_length(finalized_ids),
    'ids', finalized_ids,
    'completedCount', completed_count,
    'retriedCount', retried_count,
    'deadLetteredCount', dead_lettered_count
  );
end;
$$;


ALTER FUNCTION "public"."finalize_organization_memory_retirement_batch"("p_inputs" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."finalize_project_qa_evidence_upload_v1"("p_upload_id" "uuid") RETURNS TABLE("evidence_id" "uuid", "run_lock_version" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare upload_row public.project_qa_evidence_uploads%rowtype; run_row public.project_qa_runs%rowtype; object_row storage.objects%rowtype; inserted_id uuid; actual_size bigint; actual_mime text; next_lock integer;
begin
  select * into upload_row from public.project_qa_evidence_uploads where id=p_upload_id and initiated_by=auth.uid() for update;
  if not found or not public.can_access_qa_project(upload_row.organization_id,upload_row.project_id,'qa.inspect') then raise exception 'QA evidence upload not found or access denied' using errcode='42501'; end if;
  if upload_row.evidence_type='signature' then raise exception 'Signature evidence requires signature finalization' using errcode='TS422'; end if;
  if upload_row.status='finalized' then select id into inserted_id from public.project_qa_response_evidence where upload_id=upload_row.id; select lock_version into next_lock from public.project_qa_runs where id=upload_row.run_id; return query select inserted_id,next_lock; return; end if;
  if upload_row.status<>'pending' or upload_row.expires_at<=now() then raise exception 'QA evidence upload is no longer pending' using errcode='TS409'; end if;
  select * into run_row from public.project_qa_runs where id=upload_row.run_id for update;
  if run_row.status<>'in_progress' then raise exception 'Evidence can only be finalized for an in-progress QA Record' using errcode='TS409'; end if;
  select * into object_row from storage.objects where bucket_id='project-qa-evidence' and name=upload_row.storage_path;
  if not found then raise exception 'Uploaded evidence object was not found' using errcode='TS409'; end if;
  actual_size:=nullif(object_row.metadata->>'size','')::bigint;
  actual_mime:=lower(btrim(coalesce(object_row.metadata->>'mimetype',object_row.metadata->>'contentType','')));
  if actual_size is distinct from upload_row.byte_size or actual_mime<>upload_row.mime_type then raise exception 'Uploaded evidence does not match its reservation' using errcode='TS422'; end if;
  insert into public.project_qa_response_evidence(organization_id,project_id,project_qa_run_id,project_qa_response_id,upload_id,evidence_type,purpose,storage_path,original_filename,mime_type,byte_size,sort_order,uploaded_by)
  values(upload_row.organization_id,upload_row.project_id,upload_row.run_id,upload_row.response_id,upload_row.id,upload_row.evidence_type,upload_row.purpose,upload_row.storage_path,upload_row.original_filename,upload_row.mime_type,upload_row.byte_size,
    (select count(*) from public.project_qa_response_evidence where project_qa_response_id=upload_row.response_id),auth.uid()) returning id into inserted_id;
  update public.project_qa_evidence_uploads set status='finalized',finalized_at=now() where id=upload_row.id;
  update public.project_qa_runs set lock_version=lock_version+1 where id=upload_row.run_id returning lock_version into next_lock;
  return query select inserted_id,next_lock;
end; $$;


ALTER FUNCTION "public"."finalize_project_qa_evidence_upload_v1"("p_upload_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."finalize_retention_variance_scan_item"("p_input" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare q public.retention_variance_scan_queue%rowtype; ok boolean;
begin
  if auth.role()<>'service_role' then
    return jsonb_build_object('succeeded',false,'errorCode','permission_denied');
  end if;
  select * into q from public.retention_variance_scan_queue
  where id=(p_input->>'queueId')::uuid and queue_state='claimed'
    and claim_token=(p_input->>'claimToken')::uuid for update;
  if not found then return jsonb_build_object('succeeded',false,'errorCode','scan_already_claimed'); end if;
  ok:=coalesce((p_input->>'completed')::boolean,false);
  update public.retention_variance_scan_queue set
    queue_state=case when ok then 'completed'
      when attempt_count>=max_attempts then 'dead_lettered' else 'retry_scheduled' end,
    available_at=case when ok then now()
      else now()+make_interval(mins=>least(attempt_count*5,60)) end,
    last_completed_at=case when ok then now() else last_completed_at end,
    last_error_code=case when ok then null else coalesce(p_input->>'errorCode','scan_failed') end,
    last_error_message=case when ok then null else left(coalesce(p_input->>'errorMessage','scan_failed'),1000) end,
    claimed_at=null,claim_expires_at=null,claimed_by=null,claim_token=null,updated_at=now()
  where id=q.id;
  return jsonb_build_object('succeeded',true,'errorCode',null,
    'queueId',q.id,'completed',ok);
end;
$$;


ALTER FUNCTION "public"."finalize_retention_variance_scan_item"("p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."finalize_supplier_bill_ucl_refresh"("p_queue_id" "uuid", "p_lease_token" "uuid", "p_outcome" "text", "p_retry_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_error_code" "text" DEFAULT NULL::"text", "p_error_summary" "text" DEFAULT NULL::"text", "p_schema_version" "text" DEFAULT NULL::"text", "p_builder_version" "text" DEFAULT NULL::"text", "p_content_hash" "text" DEFAULT NULL::"text", "p_canonical_updated_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_latest_dependency_updated_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_payload_bytes" integer DEFAULT NULL::integer) RETURNS "public"."supplier_bill_ucl_refresh_queue"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  queued public.supplier_bill_ucl_refresh_queue%rowtype;
  next_state text;
  result_code text;
begin
  select *
  into queued
  from public.supplier_bill_ucl_refresh_queue q
  where q.id = p_queue_id
    and q.queue_state = 'leased'
    and q.lease_token = p_lease_token
  for update;

  if not found then
    raise exception 'Supplier Bill refresh lease is not owned by this worker.'
      using errcode = 'P0001';
  end if;

  if p_outcome in ('changed', 'no_change', 'voided') then
    if p_schema_version <> 'supplier_bill.v2'
      or p_builder_version is null
      or p_content_hash is null
      or p_canonical_updated_at is null
      or p_latest_dependency_updated_at is null
      or p_payload_bytes is null
      or p_payload_bytes < 0 then
      raise exception 'Successful Supplier Bill refresh metadata is incomplete.';
    end if;

    insert into public.supplier_bill_ucl_current_state (
      organization_id,
      container_type,
      source_id,
      schema_version,
      builder_version,
      content_hash,
      canonical_updated_at,
      latest_dependency_updated_at,
      validated_at,
      payload_bytes,
      context_status,
      last_refresh_reason,
      deleted_at
    ) values (
      queued.organization_id,
      'supplier_invoice',
      queued.source_id,
      p_schema_version,
      p_builder_version,
      p_content_hash,
      p_canonical_updated_at,
      p_latest_dependency_updated_at,
      now(),
      p_payload_bytes,
      case when p_outcome = 'voided' then 'voided' else 'current' end,
      queued.reason_code,
      null
    )
    on conflict (organization_id, container_type, source_id)
    do update set
      schema_version = excluded.schema_version,
      builder_version = excluded.builder_version,
      content_hash = excluded.content_hash,
      canonical_updated_at = excluded.canonical_updated_at,
      latest_dependency_updated_at = excluded.latest_dependency_updated_at,
      validated_at = excluded.validated_at,
      payload_bytes = excluded.payload_bytes,
      context_status = excluded.context_status,
      last_refresh_reason = excluded.last_refresh_reason,
      deleted_at = null,
      updated_at = now();

    next_state := 'completed';
    result_code := p_outcome;
  elsif p_outcome = 'deleted' then
    if queued.deletion_evidence_at is null then
      raise exception 'Supplier Bill deletion cannot be finalized without atomic deletion evidence.';
    end if;
    if exists (
      select 1
      from public.supplier_invoices i
      where i.id = queued.source_id
    ) then
      raise exception 'Supplier Bill deletion cannot be finalized while a canonical source exists.';
    end if;

    insert into public.supplier_bill_ucl_current_state (
      organization_id,
      container_type,
      source_id,
      schema_version,
      builder_version,
      content_hash,
      canonical_updated_at,
      latest_dependency_updated_at,
      validated_at,
      payload_bytes,
      context_status,
      last_refresh_reason,
      deleted_at
    ) values (
      queued.organization_id,
      'supplier_invoice',
      queued.source_id,
      null,
      null,
      null,
      null,
      null,
      now(),
      null,
      'deleted',
      queued.reason_code,
      now()
    )
    on conflict (organization_id, container_type, source_id)
    do update set
      schema_version = null,
      builder_version = null,
      content_hash = null,
      canonical_updated_at = null,
      latest_dependency_updated_at = null,
      validated_at = now(),
      payload_bytes = null,
      context_status = 'deleted',
      last_refresh_reason = excluded.last_refresh_reason,
      deleted_at = now(),
      updated_at = now();

    next_state := 'deleted';
    result_code := 'deleted';
  elsif p_outcome = 'retry' then
    next_state := case when queued.attempt_count >= queued.max_attempts then 'dead_letter' else 'retry_wait' end;
    result_code := null;
  elsif p_outcome = 'dead_letter' then
    next_state := 'dead_letter';
    result_code := null;
  else
    raise exception 'Unsupported Supplier Bill refresh outcome.';
  end if;

  update public.supplier_bill_ucl_refresh_queue q
  set
    queue_state = next_state,
    available_at = case
      when next_state = 'retry_wait' then greatest(coalesce(p_retry_at, now()), now())
      else q.available_at
    end,
    lease_owner = null,
    lease_token = null,
    leased_at = null,
    lease_expires_at = null,
    completed_at = case when next_state in ('completed', 'deleted') then now() else null end,
    first_failed_at = case
      when next_state in ('retry_wait', 'dead_letter') then coalesce(q.first_failed_at, now())
      else q.first_failed_at
    end,
    last_failed_at = case when next_state in ('retry_wait', 'dead_letter') then now() else q.last_failed_at end,
    last_error_code = case
      when next_state in ('retry_wait', 'dead_letter') then left(nullif(p_error_code, ''), 120)
      else null
    end,
    last_error_summary = case
      when next_state in ('retry_wait', 'dead_letter') then left(nullif(p_error_summary, ''), 500)
      else null
    end,
    schema_version = case when next_state = 'completed' then p_schema_version when next_state = 'deleted' then null else q.schema_version end,
    builder_version = case when next_state = 'completed' then p_builder_version when next_state = 'deleted' then null else q.builder_version end,
    content_hash = case when next_state = 'completed' then p_content_hash when next_state = 'deleted' then null else q.content_hash end,
    canonical_updated_at = case when next_state = 'completed' then p_canonical_updated_at when next_state = 'deleted' then null else q.canonical_updated_at end,
    latest_dependency_updated_at = case when next_state = 'completed' then p_latest_dependency_updated_at when next_state = 'deleted' then null else q.latest_dependency_updated_at end,
    validated_at = case when next_state = 'completed' then now() when next_state = 'deleted' then now() else q.validated_at end,
    payload_bytes = case when next_state = 'completed' then p_payload_bytes when next_state = 'deleted' then null else q.payload_bytes end,
    refresh_result = result_code,
    updated_at = now()
  where q.id = queued.id
  returning * into queued;

  return queued;
end;
$$;


ALTER FUNCTION "public"."finalize_supplier_bill_ucl_refresh"("p_queue_id" "uuid", "p_lease_token" "uuid", "p_outcome" "text", "p_retry_at" timestamp with time zone, "p_error_code" "text", "p_error_summary" "text", "p_schema_version" "text", "p_builder_version" "text", "p_content_hash" "text", "p_canonical_updated_at" timestamp with time zone, "p_latest_dependency_updated_at" timestamp with time zone, "p_payload_bytes" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."finalize_supplier_bill_ucl_refresh_stale"("p_queue_id" "uuid", "p_lease_token" "uuid") RETURNS "public"."supplier_bill_ucl_refresh_queue"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  queued public.supplier_bill_ucl_refresh_queue%rowtype;
begin
  update public.supplier_bill_ucl_refresh_queue q
  set
    queue_state = 'completed',
    lease_owner = null,
    lease_token = null,
    leased_at = null,
    lease_expires_at = null,
    completed_at = now(),
    last_error_code = 'supplier_bill_ucl_stale_write_rejected',
    last_error_summary = 'An older validated rebuild was prevented from replacing newer current context.',
    refresh_result = 'stale',
    updated_at = now()
  where q.id = p_queue_id
    and q.queue_state = 'leased'
    and q.lease_token = p_lease_token
  returning * into queued;

  if queued.id is null then
    raise exception 'Supplier Bill refresh lease is not owned by this worker.'
      using errcode = 'P0001';
  end if;
  return queued;
end;
$$;


ALTER FUNCTION "public"."finalize_supplier_bill_ucl_refresh_stale"("p_queue_id" "uuid", "p_lease_token" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."finalize_worksheet_event_classification_claims"("p_inputs" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  input_item jsonb;
  inserted_ids jsonb := '[]'::jsonb;
  inserted_id uuid;
  resolved_source_event_id uuid;
  resolved_organization_id uuid;
  resolved_classification_version integer;
  resolved_attempt_number integer;
  resolved_claim_token uuid;
  resolved_status text;
  resolved_retry_after timestamptz;
  queue_row public.worksheet_event_classification_queue%rowtype;
  completed_count integer := 0;
  retried_count integer := 0;
  dead_lettered_count integer := 0;
begin
  if p_inputs is null or jsonb_typeof(p_inputs) <> 'array' then
    raise exception 'finalize_worksheet_event_classification_claims requires a JSON array payload';
  end if;

  for input_item in
    select value
    from jsonb_array_elements(p_inputs)
  loop
    resolved_source_event_id := nullif(input_item->>'sourceEventId', '')::uuid;
    resolved_organization_id := nullif(input_item->>'organizationId', '')::uuid;
    resolved_classification_version := greatest(coalesce(nullif(input_item->>'classificationVersion', '')::integer, 1), 1);
    resolved_attempt_number := greatest(coalesce(nullif(input_item->>'attemptNumber', '')::integer, 1), 1);
    resolved_claim_token := nullif(input_item->>'claimToken', '')::uuid;
    resolved_status := coalesce(nullif(btrim(coalesce(input_item->>'classificationStatus', '')), ''), 'failed');
    resolved_retry_after := nullif(input_item->>'retryAfter', '')::timestamptz;

    select *
    into queue_row
    from public.worksheet_event_classification_queue q
    where q.source_event_id = resolved_source_event_id
      and q.organization_id = resolved_organization_id
      and q.classification_version = resolved_classification_version
      and q.queue_state = 'claimed'
      and q.claim_token = resolved_claim_token
      and q.attempt_count = resolved_attempt_number
    for update;

    if not found then
      raise exception 'Worksheet event classification claim not found.';
    end if;

    select (result->'ids'->>0)::uuid
    into inserted_id
    from (
      select public.record_worksheet_event_classifications(jsonb_build_array(input_item)) as result
    ) recorded;

    inserted_ids := inserted_ids || jsonb_build_array(inserted_id);

    if resolved_status in ('classified', 'low_confidence') then
      update public.worksheet_event_classification_queue
      set
        queue_state = 'completed',
        available_at = now(),
        claimed_at = null,
        claim_expires_at = null,
        claimed_by = null,
        claim_token = null,
        last_error_code = null,
        last_error_message = null,
        last_completed_at = coalesce(nullif(input_item->>'classifiedAt', '')::timestamptz, now()),
        updated_at = now()
      where id = queue_row.id;

      insert into public.worksheet_memory_evidence_pool_queue (
        organization_id,
        source_event_id,
        classification_record_id,
        classification_version,
        classification_attempt_number,
        queue_state,
        attempt_count,
        max_attempts,
        priority,
        available_at,
        retry_after,
        claimed_at,
        claim_expires_at,
        claimed_by,
        claim_token,
        last_error_code,
        last_error_message,
        last_attempt_at,
        last_completed_at,
        updated_at
      )
      values (
        resolved_organization_id,
        resolved_source_event_id,
        inserted_id,
        resolved_classification_version,
        resolved_attempt_number,
        'pending',
        0,
        5,
        case
          when resolved_status = 'classified' then 200
          else 100
        end,
        now(),
        null,
        null,
        null,
        null,
        null,
        null,
        null,
        null,
        null,
        now()
      )
      on conflict (organization_id, classification_record_id) do nothing;

      completed_count := completed_count + 1;
    elsif queue_row.attempt_count >= queue_row.max_attempts then
      update public.worksheet_event_classification_queue
      set
        queue_state = 'dead_lettered',
        available_at = coalesce(resolved_retry_after, now()),
        claimed_at = null,
        claim_expires_at = null,
        claimed_by = null,
        claim_token = null,
        last_error_code = nullif(btrim(coalesce(input_item->>'errorCode', '')), ''),
        last_error_message = nullif(btrim(coalesce(input_item->>'errorMessage', '')), ''),
        updated_at = now()
      where id = queue_row.id;

      dead_lettered_count := dead_lettered_count + 1;
    else
      update public.worksheet_event_classification_queue
      set
        queue_state = 'retry_scheduled',
        available_at = coalesce(resolved_retry_after, now()),
        claimed_at = null,
        claim_expires_at = null,
        claimed_by = null,
        claim_token = null,
        last_error_code = nullif(btrim(coalesce(input_item->>'errorCode', '')), ''),
        last_error_message = nullif(btrim(coalesce(input_item->>'errorMessage', '')), ''),
        updated_at = now()
      where id = queue_row.id;

      retried_count := retried_count + 1;
    end if;
  end loop;

  return jsonb_build_object(
    'count', jsonb_array_length(inserted_ids),
    'ids', inserted_ids,
    'completedCount', completed_count,
    'retriedCount', retried_count,
    'deadLetteredCount', dead_lettered_count
  );
end;
$$;


ALTER FUNCTION "public"."finalize_worksheet_event_classification_claims"("p_inputs" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."finalize_worksheet_memory_evidence_pool_batch"("p_inputs" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  input_item jsonb;
  finalized_ids jsonb := '[]'::jsonb;
  queue_row public.worksheet_memory_evidence_pool_queue%rowtype;
  resolved_status text;
  resolved_retry_after timestamptz;
  completed_count integer := 0;
  retried_count integer := 0;
  dead_lettered_count integer := 0;
begin
  if p_inputs is null or jsonb_typeof(p_inputs) <> 'array' then
    raise exception 'finalize_worksheet_memory_evidence_pool_batch requires a JSON array payload';
  end if;

  for input_item in
    select value
    from jsonb_array_elements(p_inputs)
  loop
    resolved_status := coalesce(nullif(input_item->>'queueState', ''), 'retry_scheduled');
    resolved_retry_after := nullif(input_item->>'retryAfter', '')::timestamptz;

    select q.*
    into queue_row
    from public.worksheet_memory_evidence_pool_queue q
    where q.id = nullif(input_item->>'id', '')::uuid
      and q.queue_state = 'claimed'
      and q.claim_token = nullif(input_item->>'claimToken', '')::uuid
    for update;

    if not found then
      continue;
    end if;

    finalized_ids := finalized_ids || jsonb_build_array(queue_row.id);

    if resolved_status = 'completed' then
      update public.worksheet_memory_evidence_pool_queue
      set
        queue_state = 'completed',
        available_at = now(),
        retry_after = null,
        claimed_at = null,
        claim_expires_at = null,
        claimed_by = null,
        claim_token = null,
        last_error_code = null,
        last_error_message = null,
        last_completed_at = now(),
        updated_at = now()
      where id = queue_row.id;

      completed_count := completed_count + 1;
    elsif queue_row.attempt_count >= queue_row.max_attempts then
      update public.worksheet_memory_evidence_pool_queue
      set
        queue_state = 'dead_lettered',
        available_at = coalesce(resolved_retry_after, now()),
        retry_after = resolved_retry_after,
        claimed_at = null,
        claim_expires_at = null,
        claimed_by = null,
        claim_token = null,
        last_error_code = nullif(btrim(coalesce(input_item->>'errorCode', '')), ''),
        last_error_message = nullif(btrim(coalesce(input_item->>'errorMessage', '')), ''),
        updated_at = now()
      where id = queue_row.id;

      dead_lettered_count := dead_lettered_count + 1;
    else
      update public.worksheet_memory_evidence_pool_queue
      set
        queue_state = 'retry_scheduled',
        available_at = coalesce(resolved_retry_after, now()),
        retry_after = resolved_retry_after,
        claimed_at = null,
        claim_expires_at = null,
        claimed_by = null,
        claim_token = null,
        last_error_code = nullif(btrim(coalesce(input_item->>'errorCode', '')), ''),
        last_error_message = nullif(btrim(coalesce(input_item->>'errorMessage', '')), ''),
        updated_at = now()
      where id = queue_row.id;

      retried_count := retried_count + 1;
    end if;
  end loop;

  return jsonb_build_object(
    'count', jsonb_array_length(finalized_ids),
    'ids', finalized_ids,
    'completedCount', completed_count,
    'retriedCount', retried_count,
    'deadLetteredCount', dead_lettered_count
  );
end;
$$;


ALTER FUNCTION "public"."finalize_worksheet_memory_evidence_pool_batch"("p_inputs" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."finalize_worksheet_memory_semantic_pool_batch"("p_inputs" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  input_item jsonb;
  finalized_ids jsonb := '[]'::jsonb;
  queue_row public.worksheet_memory_semantic_pool_queue%rowtype;
  resolved_status text;
  resolved_retry_after timestamptz;
  completed_count integer := 0;
  retried_count integer := 0;
  dead_lettered_count integer := 0;
begin
  if p_inputs is null or jsonb_typeof(p_inputs) <> 'array' then
    raise exception 'finalize_worksheet_memory_semantic_pool_batch requires a JSON array payload';
  end if;

  for input_item in
    select value
    from jsonb_array_elements(p_inputs)
  loop
    resolved_status := coalesce(nullif(input_item->>'queueState', ''), 'retry_scheduled');
    resolved_retry_after := nullif(input_item->>'retryAfter', '')::timestamptz;

    select q.*
    into queue_row
    from public.worksheet_memory_semantic_pool_queue q
    where q.id = nullif(input_item->>'id', '')::uuid
      and q.queue_state = 'claimed'
      and q.claim_token = nullif(input_item->>'claimToken', '')::uuid
    for update;

    if not found then
      continue;
    end if;

    finalized_ids := finalized_ids || jsonb_build_array(queue_row.id);

    if resolved_status = 'completed' then
      update public.worksheet_memory_semantic_pool_queue
      set
        queue_state = 'completed',
        available_at = now(),
        retry_after = null,
        claim_token = null,
        claim_expires_at = null,
        claimed_at = null,
        claimed_by = null,
        last_error_code = null,
        last_error_message = null,
        last_completed_at = now(),
        updated_at = now()
      where id = queue_row.id;

      completed_count := completed_count + 1;
    elsif queue_row.attempt_count >= queue_row.max_attempts or resolved_status = 'dead_lettered' then
      update public.worksheet_memory_semantic_pool_queue
      set
        queue_state = 'dead_lettered',
        available_at = coalesce(resolved_retry_after, available_at),
        retry_after = resolved_retry_after,
        claim_token = null,
        claim_expires_at = null,
        claimed_at = null,
        claimed_by = null,
        last_error_code = nullif(input_item->>'errorCode', ''),
        last_error_message = nullif(input_item->>'errorMessage', ''),
        updated_at = now()
      where id = queue_row.id;

      dead_lettered_count := dead_lettered_count + 1;
    else
      update public.worksheet_memory_semantic_pool_queue
      set
        queue_state = 'retry_scheduled',
        available_at = coalesce(resolved_retry_after, now()),
        retry_after = coalesce(resolved_retry_after, now()),
        claim_token = null,
        claim_expires_at = null,
        claimed_at = null,
        claimed_by = null,
        last_error_code = nullif(input_item->>'errorCode', ''),
        last_error_message = nullif(input_item->>'errorMessage', ''),
        updated_at = now()
      where id = queue_row.id;

      retried_count := retried_count + 1;
    end if;
  end loop;

  return jsonb_build_object(
    'count', jsonb_array_length(finalized_ids),
    'ids', finalized_ids,
    'completedCount', completed_count,
    'retriedCount', retried_count,
    'deadLetteredCount', dead_lettered_count
  );
end;
$$;


