CREATE OR REPLACE FUNCTION "public"."finalize_worksheet_mutation_evidence_v2_outbox_batch"("p_inputs" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  input_item jsonb;
  resolved_id uuid;
  resolved_claim_token uuid;
  requested_status text;
  resolved_retry_after timestamptz;
  resolved_error_code text;
  resolved_error_message text;
  updated_id uuid;
  reached_max_attempts boolean;
  completed_count integer := 0;
  retried_count integer := 0;
  dead_lettered_count integer := 0;
  updated_ids jsonb := '[]'::jsonb;
begin
  if p_inputs is null or jsonb_typeof(p_inputs) <> 'array' then
    raise exception 'finalize_worksheet_mutation_evidence_v2_outbox_batch requires a JSON array payload';
  end if;

  for input_item in
    select value
    from jsonb_array_elements(p_inputs)
  loop
    resolved_id := nullif(input_item->>'id', '')::uuid;
    resolved_claim_token := nullif(input_item->>'claimToken', '')::uuid;
    requested_status := nullif(btrim(coalesce(input_item->>'processingStatus', '')), '');
    resolved_retry_after := nullif(input_item->>'retryAfter', '')::timestamptz;
    resolved_error_code := nullif(btrim(coalesce(input_item->>'errorCode', '')), '');
    resolved_error_message := nullif(btrim(coalesce(input_item->>'errorMessage', '')), '');

    if resolved_id is null or resolved_claim_token is null or requested_status is null then
      continue;
    end if;

    if requested_status = 'completed' then
      update public.worksheet_mutation_evidence_v2_outbox outbox
      set
        processing_status = 'completed',
        processed_at = now(),
        retry_after = null,
        dead_lettered_at = null,
        claimed_at = null,
        claim_expires_at = null,
        claimed_by = null,
        claim_token = null,
        last_error_code = null,
        last_error_message = null,
        updated_at = now()
      where outbox.id = resolved_id
        and outbox.claim_token = resolved_claim_token
      returning outbox.id into updated_id;

      if updated_id is not null then
        completed_count := completed_count + 1;
        updated_ids := updated_ids || jsonb_build_array(updated_id);
      end if;
    elsif requested_status = 'retry_scheduled' then
      reached_max_attempts := false;
      update public.worksheet_mutation_evidence_v2_outbox outbox
      set
        processing_status = case
          when outbox.attempt_count >= outbox.max_attempts then 'dead_lettered'
          else 'retry_scheduled'
        end,
        retry_after = case
          when outbox.attempt_count >= outbox.max_attempts then null
          else coalesce(resolved_retry_after, now())
        end,
        dead_lettered_at = case
          when outbox.attempt_count >= outbox.max_attempts then now()
          else null
        end,
        claimed_at = null,
        claim_expires_at = null,
        claimed_by = null,
        claim_token = null,
        last_error_code = coalesce(resolved_error_code, 'worksheet_mutation_processing_failed'),
        last_error_message = coalesce(resolved_error_message, 'Worksheet mutation Evidence V2 processing failed.'),
        updated_at = now()
      where outbox.id = resolved_id
        and outbox.claim_token = resolved_claim_token
      returning outbox.id, outbox.attempt_count >= outbox.max_attempts into updated_id, reached_max_attempts;

      if updated_id is not null then
        if reached_max_attempts then
          dead_lettered_count := dead_lettered_count + 1;
        else
          retried_count := retried_count + 1;
        end if;
        updated_ids := updated_ids || jsonb_build_array(updated_id);
      end if;
    elsif requested_status = 'dead_lettered' then
      update public.worksheet_mutation_evidence_v2_outbox outbox
      set
        processing_status = 'dead_lettered',
        retry_after = null,
        dead_lettered_at = now(),
        claimed_at = null,
        claim_expires_at = null,
        claimed_by = null,
        claim_token = null,
        last_error_code = coalesce(resolved_error_code, 'worksheet_mutation_dead_lettered'),
        last_error_message = coalesce(resolved_error_message, 'Worksheet mutation Evidence V2 processing dead-lettered.'),
        updated_at = now()
      where outbox.id = resolved_id
        and outbox.claim_token = resolved_claim_token
      returning outbox.id into updated_id;

      if updated_id is not null then
        dead_lettered_count := dead_lettered_count + 1;
        updated_ids := updated_ids || jsonb_build_array(updated_id);
      end if;
    end if;
  end loop;

  return jsonb_build_object(
    'count', jsonb_array_length(updated_ids),
    'ids', updated_ids,
    'completedCount', completed_count,
    'retriedCount', retried_count,
    'deadLetteredCount', dead_lettered_count
  );
end;
$$;


ALTER FUNCTION "public"."finalize_worksheet_mutation_evidence_v2_outbox_batch"("p_inputs" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."finalize_worksheet_pricing_pattern_evidence_processing_batch"("p_inputs" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  input_item jsonb;
  finalized_ids jsonb := '[]'::jsonb;
  queue_row public.worksheet_pricing_pattern_evidence_processing%rowtype;
  resolved_status text;
  resolved_retry_after timestamptz;
  processed_count integer := 0;
  retried_count integer := 0;
  dead_lettered_count integer := 0;
begin
  if p_inputs is null or jsonb_typeof(p_inputs) <> 'array' then
    raise exception 'finalize_worksheet_pricing_pattern_evidence_processing_batch requires a JSON array payload';
  end if;

  for input_item in
    select value
    from jsonb_array_elements(p_inputs)
  loop
    resolved_status := coalesce(nullif(btrim(coalesce(input_item->>'processingStatus', '')), ''), 'retry_scheduled');
    resolved_retry_after := nullif(input_item->>'retryAfter', '')::timestamptz;

    select *
    into queue_row
    from public.worksheet_pricing_pattern_evidence_processing q
    where q.source_event_id = nullif(input_item->>'sourceEventId', '')::uuid
      and q.organization_id = nullif(input_item->>'organizationId', '')::uuid
      and q.classification_version = greatest(coalesce(nullif(input_item->>'classificationVersion', '')::integer, 1), 1)
      and q.processing_status = 'claimed'
      and q.claim_token = nullif(input_item->>'claimToken', '')::uuid
      and q.attempt_count = greatest(coalesce(nullif(input_item->>'attemptCount', '')::integer, 1), 1)
    for update;

    if not found then
      raise exception 'Worksheet pricing pattern evidence processing claim not found.';
    end if;

    finalized_ids := finalized_ids || jsonb_build_array(queue_row.id);

    if resolved_status = 'processed' then
      update public.worksheet_pricing_pattern_evidence_processing
      set
        processing_status = 'processed',
        processed_at = coalesce(nullif(input_item->>'processedAt', '')::timestamptz, now()),
        failed_at = null,
        retry_after = null,
        error_code = null,
        error_message = null,
        claimed_at = null,
        claim_expires_at = null,
        claimed_by = null,
        claim_token = null,
        last_error_code = null,
        last_error_message = null,
        updated_at = now()
      where id = queue_row.id;

      processed_count := processed_count + 1;
    elsif queue_row.attempt_count >= queue_row.max_attempts or resolved_status = 'dead_lettered' then
      update public.worksheet_pricing_pattern_evidence_processing
      set
        processing_status = 'dead_lettered',
        failed_at = coalesce(nullif(input_item->>'failedAt', '')::timestamptz, now()),
        retry_after = coalesce(resolved_retry_after, retry_after),
        error_code = nullif(btrim(coalesce(input_item->>'errorCode', '')), ''),
        error_message = nullif(btrim(coalesce(input_item->>'errorMessage', '')), ''),
        claimed_at = null,
        claim_expires_at = null,
        claimed_by = null,
        claim_token = null,
        last_error_code = nullif(btrim(coalesce(input_item->>'errorCode', '')), ''),
        last_error_message = nullif(btrim(coalesce(input_item->>'errorMessage', '')), ''),
        updated_at = now()
      where id = queue_row.id;

      dead_lettered_count := dead_lettered_count + 1;
    else
      update public.worksheet_pricing_pattern_evidence_processing
      set
        processing_status = 'retry_scheduled',
        failed_at = coalesce(nullif(input_item->>'failedAt', '')::timestamptz, now()),
        retry_after = coalesce(resolved_retry_after, now()),
        error_code = nullif(btrim(coalesce(input_item->>'errorCode', '')), ''),
        error_message = nullif(btrim(coalesce(input_item->>'errorMessage', '')), ''),
        claimed_at = null,
        claim_expires_at = null,
        claimed_by = null,
        claim_token = null,
        last_error_code = nullif(btrim(coalesce(input_item->>'errorCode', '')), ''),
        last_error_message = nullif(btrim(coalesce(input_item->>'errorMessage', '')), ''),
        updated_at = now()
      where id = queue_row.id;

      retried_count := retried_count + 1;
    end if;
  end loop;

  return jsonb_build_object(
    'count', jsonb_array_length(finalized_ids),
    'ids', finalized_ids,
    'processedCount', processed_count,
    'retriedCount', retried_count,
    'deadLetteredCount', dead_lettered_count
  );
end;
$$;


