CREATE TABLE IF NOT EXISTS "public"."organization_xero_connections" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "status" "text" DEFAULT 'disconnected'::"text" NOT NULL,
    "tenant_id" "text",
    "tenant_name" "text",
    "tenant_type" "text",
    "tenant_connection_id" "text",
    "xero_user_id" "text",
    "scope" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "available_tenants_json" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "token_expires_at" timestamp with time zone,
    "refresh_token_expires_at" timestamp with time zone,
    "last_health_status" "text",
    "last_health_checked_at" timestamp with time zone,
    "last_sync_started_at" timestamp with time zone,
    "last_sync_completed_at" timestamp with time zone,
    "last_accounts_sync_at" timestamp with time zone,
    "last_tax_rates_sync_at" timestamp with time zone,
    "last_error" "text",
    "connected_by_user_id" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "last_contacts_sync_at" timestamp with time zone,
    CONSTRAINT "organization_xero_connections_available_tenants_json_check" CHECK (("jsonb_typeof"("available_tenants_json") = 'array'::"text")),
    CONSTRAINT "organization_xero_connections_last_health_status_check" CHECK ((("last_health_status" IS NULL) OR ("last_health_status" = ANY (ARRAY['healthy'::"text", 'degraded'::"text", 'disconnected'::"text", 'error'::"text"])))),
    CONSTRAINT "organization_xero_connections_status_check" CHECK (("status" = ANY (ARRAY['disconnected'::"text", 'pending_authorization'::"text", 'awaiting_tenant_selection'::"text", 'connected'::"text", 'attention_required'::"text", 'error'::"text"])))
);

