CREATE OR REPLACE FUNCTION "public"."finalize_xero_oauth_attempt"("p_attempt_id" "uuid", "p_organization_id" "uuid", "p_connection_id" "uuid", "p_encrypted_token_set" "text", "p_encryption_version" integer, "p_connection_status" "text", "p_tenant_id" "text", "p_tenant_name" "text", "p_tenant_type" "text", "p_tenant_connection_id" "text", "p_xero_user_id" "text", "p_scope" "text"[], "p_available_tenants_json" "jsonb", "p_token_expires_at" timestamp with time zone, "p_refresh_token_expires_at" timestamp with time zone, "p_connected_by_user_id" "uuid", "p_callback_outcome" "text") RETURNS "public"."organization_xero_connections"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_attempt public.organization_xero_oauth_states%rowtype;
  v_connection public.organization_xero_connections%rowtype;
begin
  if p_connection_status not in ('connected', 'awaiting_tenant_selection') then
    raise exception 'invalid xero callback connection status';
  end if;

  if p_encrypted_token_set is null or char_length(trim(p_encrypted_token_set)) = 0 then
    raise exception 'encrypted xero token set is required';
  end if;

  select *
  into v_attempt
  from public.organization_xero_oauth_states
  where id = p_attempt_id
    and organization_id = p_organization_id
    and connection_id = p_connection_id
  for update;

  if not found or v_attempt.status <> 'callback_received' then
    raise exception 'xero oauth attempt is not ready to finalize';
  end if;

  select *
  into v_connection
  from public.organization_xero_connections
  where id = p_connection_id
    and organization_id = p_organization_id
  for update;

  if not found then
    raise exception 'xero connection was not found';
  end if;

  insert into public.organization_xero_connection_secrets (
    connection_id,
    encrypted_token_set,
    encryption_version,
    updated_at
  ) values (
    p_connection_id,
    p_encrypted_token_set,
    p_encryption_version,
    now()
  )
  on conflict (connection_id) do update set
    encrypted_token_set = excluded.encrypted_token_set,
    encryption_version = excluded.encryption_version,
    updated_at = excluded.updated_at;

  update public.organization_xero_connections
  set
    status = p_connection_status,
    tenant_id = p_tenant_id,
    tenant_name = p_tenant_name,
    tenant_type = p_tenant_type,
    tenant_connection_id = p_tenant_connection_id,
    xero_user_id = p_xero_user_id,
    scope = coalesce(p_scope, '{}'::text[]),
    available_tenants_json = coalesce(p_available_tenants_json, '[]'::jsonb),
    token_expires_at = p_token_expires_at,
    refresh_token_expires_at = p_refresh_token_expires_at,
    last_health_status = case
      when p_connection_status = 'connected' then 'healthy'
      else null
    end,
    last_health_checked_at = case
      when p_connection_status = 'connected' then now()
      else null
    end,
    last_error = null,
    connected_by_user_id = p_connected_by_user_id,
    updated_at = now()
  where id = p_connection_id
    and organization_id = p_organization_id
  returning * into v_connection;

  update public.organization_xero_oauth_states
  set
    status = 'completed',
    completed_at = now(),
    used_at = coalesce(used_at, now()),
    callback_outcome = p_callback_outcome,
    failure_code = null,
    failure_message = null,
    failure_at = null,
    updated_at = now()
  where id = p_attempt_id
    and status = 'callback_received';

  if not found then
    raise exception 'xero oauth attempt completion conflict';
  end if;

  return v_connection;
end;
$$;


ALTER FUNCTION "public"."finalize_xero_oauth_attempt"("p_attempt_id" "uuid", "p_organization_id" "uuid", "p_connection_id" "uuid", "p_encrypted_token_set" "text", "p_encryption_version" integer, "p_connection_status" "text", "p_tenant_id" "text", "p_tenant_name" "text", "p_tenant_type" "text", "p_tenant_connection_id" "text", "p_xero_user_id" "text", "p_scope" "text"[], "p_available_tenants_json" "jsonb", "p_token_expires_at" timestamp with time zone, "p_refresh_token_expires_at" timestamp with time zone, "p_connected_by_user_id" "uuid", "p_callback_outcome" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."finish_material_source_cleanup_v1"("p_job_id" "uuid", "p_lease_token" "uuid", "p_success" boolean) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare j public.material_source_cleanup_jobs%rowtype;
begin
  if auth.role() is distinct from 'service_role' then raise exception 'service_role required' using errcode='42501'; end if;
  select * into j from public.material_source_cleanup_jobs where id=p_job_id for update;
  if not found or p_lease_token is null or j.lease_expires_at is null or j.lease_token is distinct from p_lease_token or j.lease_expires_at<=now() or j.completed_at is not null then
    raise exception 'Retention lease lost' using errcode='40001';
  end if;
  if p_success then
    update public.organization_material_import_batches set storage_path=null,source_deleted_at=now()
      where id=j.batch_id and storage_path=j.storage_path;
    if not found then raise exception 'Retention source path changed' using errcode='40001'; end if;
  end if;
  update public.material_source_cleanup_jobs set completed_at=case when p_success then now() else null end,
    dead_lettered_at=case when not p_success and attempt_count>=5 then now() else null end,
    next_attempt_at=now()+make_interval(secs=>least(3600,30*power(2,least(attempt_count,7)))::integer),
    last_error=case when p_success then null else 'Storage retention cleanup failed.' end,
    lease_token=null,lease_expires_at=null where id=j.id;
end; $$;


ALTER FUNCTION "public"."finish_material_source_cleanup_v1"("p_job_id" "uuid", "p_lease_token" "uuid", "p_success" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."finish_project_qa_cleanup_job_v1"("p_job_id" "uuid", "p_lease_token" "uuid", "p_success" boolean) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if auth.role() is distinct from 'service_role' then raise exception 'service_role required' using errcode='42501'; end if;
  update public.project_qa_evidence_cleanup_jobs
  set completed_at=case when p_success then now() else null end,
      last_error=case when p_success then null else 'Storage cleanup failed.' end,
      dead_lettered_at=case when not p_success and attempt_count>=5 then now() else null end,
      next_attempt_at=now()+make_interval(secs=>least(3600,30*power(2,least(attempt_count,7)))::integer),
      lease_token=null,lease_expires_at=null
  where id=p_job_id and lease_token=p_lease_token and lease_expires_at>now() and completed_at is null;
  if not found then raise exception 'Cleanup lease lost' using errcode='40001'; end if;
end; $$;


ALTER FUNCTION "public"."finish_project_qa_cleanup_job_v1"("p_job_id" "uuid", "p_lease_token" "uuid", "p_success" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."format_accounting_sales_invoice_number_phase2a"("p_sequence" bigint) RETURNS "text"
    LANGUAGE "sql" IMMUTABLE STRICT
    SET "search_path" TO 'public'
    AS $$
  select case
    when p_sequence < 1 then null
    else 'TSI-' || case
      when char_length(p_sequence::text) >= 8 then p_sequence::text
      else lpad(p_sequence::text, 8, '0')
    end
  end;
$$;


ALTER FUNCTION "public"."format_accounting_sales_invoice_number_phase2a"("p_sequence" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_opportunity_code"("p_organization_id" "uuid", "p_created_at" timestamp with time zone DEFAULT "now"()) RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
declare
  year_prefix text;
  next_sequence integer;
begin
  year_prefix := to_char(coalesce(p_created_at, now()) at time zone 'utc', 'YY');

  perform pg_advisory_xact_lock(hashtext(p_organization_id::text || ':opp:' || year_prefix));

  select coalesce(max(substring(opportunity_code from 3)::integer), 0) + 1
  into next_sequence
  from public.organization_opportunities
  where organization_id = p_organization_id
    and opportunity_code like (year_prefix || '%')
    and opportunity_code ~ '^[0-9]{5,}$';

  return year_prefix || lpad(next_sequence::text, 3, '0');
end;
$_$;


ALTER FUNCTION "public"."generate_opportunity_code"("p_organization_id" "uuid", "p_created_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_opportunity_quote_number"("p_organization_id" "uuid", "p_opportunity_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
declare
  resolved_opportunity_code text;
  next_sequence integer;
begin
  select opportunity_code
  into resolved_opportunity_code
  from public.organization_opportunities
  where id = p_opportunity_id
    and organization_id = p_organization_id;

  if resolved_opportunity_code is null then
    raise exception 'Could not resolve opportunity code for quote numbering';
  end if;

  perform pg_advisory_xact_lock(hashtext(p_organization_id::text || ':quote:' || resolved_opportunity_code));

  select coalesce(max(substring(quote_number from ('^Q-' || resolved_opportunity_code || '-([0-9]+)$'))::integer), 0) + 1
  into next_sequence
  from public.opportunity_quotes
  where organization_id = p_organization_id
    and quote_number like ('Q-' || resolved_opportunity_code || '-%');

  return format('Q-%s-%s', resolved_opportunity_code, next_sequence);
end;
$_$;


ALTER FUNCTION "public"."generate_opportunity_quote_number"("p_organization_id" "uuid", "p_opportunity_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_project_claim_number"("p_organization_id" "uuid", "p_project_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
declare
  resolved_project_code text;
  next_sequence integer;
begin
  if auth.uid() is null then
    raise exception 'Authentication is required';
  end if;
  if not public.is_member_of_organization(p_organization_id) then
    raise exception 'Not authorized for this organization';
  end if;
  if not exists (
    select 1
    from public.organization_projects p
    where p.id = p_project_id
      and p.organization_id = p_organization_id
  ) then
    raise exception 'Project not found for organization';
  end if;

  perform pg_advisory_xact_lock(hashtext(p_project_id::text || ':claim-number'));

  select coalesce(
           nullif(btrim(project_code), ''),
           nullif(regexp_replace(upper(coalesce(slug, '')), '[^A-Z0-9]+', '-', 'g'), ''),
           'JOB'
         )
    into resolved_project_code
  from public.organization_projects
  where id = p_project_id
    and organization_id = p_organization_id;
  if resolved_project_code is null then
    raise exception 'Could not resolve project code for claim numbering';
  end if;

  with used as (
    select distinct substring(c.claim_number from '([0-9]+)$')::integer as n
    from public.project_claims c
    where c.organization_id = p_organization_id
      and c.project_id = p_project_id
      and c.claim_number ~ '.*-(CL|PC)-[0-9]+$'
  ),
  bounds as (
    select coalesce(max(n), 0) as max_n from used
  ),
  candidates as (
    select generate_series(1, greatest((select max_n from bounds) + 1, 1)) as n
  )
  select min(c.n)
    into next_sequence
  from candidates c
  where not exists (select 1 from used u where u.n = c.n);

  return format('%s-PC-%s', resolved_project_code, lpad(next_sequence::text, 2, '0'));
end;
$_$;


ALTER FUNCTION "public"."generate_project_claim_number"("p_organization_id" "uuid", "p_project_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."generate_project_claim_number"("p_organization_id" "uuid", "p_project_id" "uuid") IS 'Allocates new <project>-PC-## Payment Claim numbers while preserving historical CL sequence occupancy.';



CREATE OR REPLACE FUNCTION "public"."generate_project_code"("p_organization_id" "uuid", "p_created_at" timestamp with time zone DEFAULT "now"()) RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
declare
  year_prefix text;
  next_sequence integer;
begin
  year_prefix := to_char(coalesce(p_created_at, now()) at time zone 'utc', 'YY');

  perform pg_advisory_xact_lock(hashtext(p_organization_id::text || ':' || year_prefix));

  select coalesce(max(substring(project_code from 3)::integer), 0) + 1
  into next_sequence
  from public.organization_projects
  where organization_id = p_organization_id
    and project_code like (year_prefix || '%')
    and project_code ~ '^[0-9]{5,}$';

  return year_prefix || lpad(next_sequence::text, 3, '0');
end;
$_$;


