CREATE OR REPLACE FUNCTION "public"."get_accounting_phase2a_health"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
  with expected_tables(name) as (
    values
      ('organization_accounting_number_counters'),
      ('organization_accounting_number_reservations'),
      ('organization_accounting_document_revisions'),
      ('organization_accounting_revision_lines'),
      ('organization_accounting_revision_attachments'),
      ('organization_accounting_revision_attempts'),
      ('organization_accounting_events'),
      ('organization_accounting_remote_observations'),
      ('organization_accounting_projections'),
      ('organization_accounting_legacy_classifications')
  ),
  table_state as (
    select e.name, c.oid is not null as exists,
      coalesce(c.relrowsecurity, false) as rls_enabled,
      coalesce(c.relforcerowsecurity, false) as rls_forced
    from expected_tables e
    left join pg_catalog.pg_class c
      on c.relname = e.name
      and c.relnamespace = 'public'::regnamespace
  ),
  function_state as (
    select p.proname as name,
      pg_catalog.pg_get_function_identity_arguments(p.oid) as arguments,
      p.prosecdef as security_definer,
      p.proconfig as configuration,
      p.proacl::text as acl
    from pg_catalog.pg_proc p
    where p.pronamespace = 'public'::regnamespace
      and (
        p.proname like '%accounting%phase2a%'
        or p.proname like '%phase2a%accounting%'
      )
  ),
  trigger_state as (
    select c.relname as table_name, t.tgname as trigger_name,
      t.tgenabled::text as enabled
    from pg_catalog.pg_trigger t
    join pg_catalog.pg_class c on c.oid = t.tgrelid
    where c.relnamespace = 'public'::regnamespace
      and not t.tgisinternal
      and (
        c.relname like 'organization_accounting_%'
        or t.tgname like '%accounting%'
      )
  ),
  index_state as (
    select c.relname as table_name, i.relname as index_name,
      x.indisvalid as valid, x.indisready as ready,
      pg_catalog.pg_get_indexdef(i.oid) as definition
    from pg_catalog.pg_index x
    join pg_catalog.pg_class i on i.oid = x.indexrelid
    join pg_catalog.pg_class c on c.oid = x.indrelid
    where c.relnamespace = 'public'::regnamespace
      and c.relname in (select name from expected_tables)
  ),
  policy_state as (
    select schemaname, tablename, policyname, cmd, roles
    from pg_catalog.pg_policies
    where schemaname = 'public'
      and tablename in (select name from expected_tables)
  ),
  grant_state as (
    select table_name, grantee, privilege_type
    from information_schema.role_table_grants
    where table_schema = 'public'
      and table_name in (select name from expected_tables)
      and grantee in ('anon', 'authenticated', 'service_role', 'PUBLIC')
  )
  select jsonb_build_object(
    'postgresVersion', current_setting('server_version'),
    'migrationCount', (
      select count(*) from supabase_migrations.schema_migrations
      where version = '20260725130000'
    ),
    'hardeningMigrationCount', (
      select count(*) from supabase_migrations.schema_migrations
      where version = '20260725140000'
    ),
    'tables', (select jsonb_agg(to_jsonb(t) order by name) from table_state t),
    'functions', (select jsonb_agg(to_jsonb(f) order by name, arguments) from function_state f),
    'triggers', (select jsonb_agg(to_jsonb(t) order by table_name, trigger_name) from trigger_state t),
    'indexes', (select jsonb_agg(to_jsonb(i) order by table_name, index_name) from index_state i),
    'policies', (select jsonb_agg(to_jsonb(p) order by tablename, policyname) from policy_state p),
    'grants', coalesce(
      (select jsonb_agg(to_jsonb(g) order by table_name, grantee, privilege_type)
       from grant_state g),
      '[]'::jsonb
    ),
    'foundationRows', jsonb_build_object(
      'revisions', (select count(*) from public.organization_accounting_document_revisions),
      'reservations', (select count(*) from public.organization_accounting_number_reservations),
      'attempts', (select count(*) from public.organization_accounting_revision_attempts),
      'events', (select count(*) from public.organization_accounting_events),
      'observations', (select count(*) from public.organization_accounting_remote_observations)
    ),
    'existingDocumentPointers', jsonb_build_object(
      'activeRevisionPointers', (
        select count(*) from public.organization_accounting_documents
        where active_accounting_revision_id is not null
      ),
      'projectionPointers', (
        select count(*) from public.organization_accounting_documents
        where current_accounting_projection_id is not null
      ),
      'legacyClassificationPointers', (
        select count(*) from public.organization_accounting_documents
        where current_legacy_classification_id is not null
      )
    ),
    'syncJobKinds', (
      select pg_catalog.pg_get_constraintdef(c.oid)
      from pg_catalog.pg_constraint c
      where c.conrelid = 'public.organization_accounting_sync_jobs'::regclass
        and c.conname = 'organization_accounting_sync_jobs_job_kind_check'
    )
  );
$$;


ALTER FUNCTION "public"."get_accounting_phase2a_health"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_accounting_sync_completion_evidence"("p_organization_id" "uuid", "p_job_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_job public.organization_accounting_sync_jobs%rowtype;
  v_document public.organization_accounting_documents%rowtype;
  v_revision public.organization_accounting_document_revisions%rowtype;
  v_attempt public.organization_accounting_revision_attempts%rowtype;
  v_observation public.organization_accounting_remote_observations%rowtype;
  v_projection public.organization_accounting_projections%rowtype;
  v_proposal public.organization_accounting_push_proposals%rowtype;
  v_source_matches boolean := false;
  v_revision_id uuid;
  v_document_id uuid;
  v_attempt_id uuid;
begin
  if p_organization_id is null or p_job_id is null then
    return null;
  end if;

  select *
  into v_job
  from public.organization_accounting_sync_jobs
  where organization_id = p_organization_id
    and id = p_job_id;

  if not found then
    return null;
  end if;

  v_revision_id := nullif(v_job.request_payload ->> 'accountingRevisionId', '')::uuid;
  v_document_id := nullif(v_job.request_payload ->> 'accountingDocumentId', '')::uuid;
  v_attempt_id := nullif(v_job.request_payload ->> 'attemptId', '')::uuid;

  if v_revision_id is not null then
    select *
    into v_revision
    from public.organization_accounting_document_revisions
    where organization_id = p_organization_id
      and id = v_revision_id;
    if found then
      v_document_id := v_revision.accounting_document_id;
    end if;
  end if;

  if v_document_id is null then
    return null;
  end if;

  select *
  into v_document
  from public.organization_accounting_documents
  where organization_id = p_organization_id
    and id = v_document_id;
  if not found then
    return null;
  end if;

  if v_revision_id is null then
    v_revision_id := v_document.active_accounting_revision_id;
    if v_revision_id is not null then
      select *
      into v_revision
      from public.organization_accounting_document_revisions
      where organization_id = p_organization_id
        and id = v_revision_id;
    end if;
  end if;

  if v_revision.id is null
    or v_document.active_accounting_revision_id is distinct from v_revision.id
    or v_revision.lifecycle_state <> 'succeeded'
    or v_revision.external_document_id is null
  then
    return null;
  end if;

  if v_attempt_id is not null then
    select *
    into v_attempt
    from public.organization_accounting_revision_attempts
    where organization_id = p_organization_id
      and id = v_attempt_id
      and accounting_revision_id = v_revision.id;
  else
    select *
    into v_attempt
    from public.organization_accounting_revision_attempts
    where organization_id = p_organization_id
      and accounting_revision_id = v_revision.id
      and attempt_intent in ('create', 'update', 'replace')
    order by attempt_sequence desc, id desc
    limit 1;
  end if;

  if v_attempt.id is null or v_attempt.queue_state <> 'succeeded' then
    return null;
  end if;

  select *
  into v_proposal
  from public.organization_accounting_push_proposals
  where organization_id = p_organization_id
    and source_document_type = v_revision.source_document_type
    and source_document_id = v_revision.source_document_id
    and preview_hash = v_revision.confirmation_preview_hash
  order by created_at desc, id desc
  limit 1;

  if v_proposal.id is not null then
    if v_revision.source_document_type = 'project_claim' then
      select claim.updated_at =
        v_proposal.source_optimistic_revision::timestamptz
      into v_source_matches
      from public.project_claims claim
      where claim.organization_id = p_organization_id
        and claim.id = v_revision.source_document_id;
    elsif v_revision.source_document_type = 'retention_claim' then
      select claim.submitted_at =
        v_proposal.source_optimistic_revision::timestamptz
      into v_source_matches
      from public.retention_claims claim
      where claim.organization_id = p_organization_id
        and claim.id = v_revision.source_document_id;
    end if;
  end if;

  select *
  into v_observation
  from public.organization_accounting_remote_observations
  where organization_id = p_organization_id
    and accounting_document_id = v_document.id
    and accounting_revision_id = v_revision.id
    and external_document_id = v_revision.external_document_id
  order by observed_at desc, id desc
  limit 1;

  select *
  into v_projection
  from public.organization_accounting_projections
  where organization_id = p_organization_id
    and accounting_document_id = v_document.id
    and accounting_revision_id = v_revision.id
    and remote_observation_id = v_observation.id;

  if v_observation.id is null
    or v_projection.id is null
    or v_projection.divergent
    or v_observation.content_hash is distinct from v_revision.provider_content_hash
    or v_observation.tenant_id is distinct from v_revision.tenant_id
    or v_observation.external_document_id is distinct from v_revision.external_document_id
  then
    return null;
  end if;

  return jsonb_build_object(
    'organizationId', v_job.organization_id,
    'projectId', v_revision.project_id,
    'claimId', v_revision.source_document_id,
    'sourceDocumentType', v_revision.source_document_type,
    'accountingDocumentId', v_document.id,
    'activeRevisionId', v_revision.id,
    'observationId', v_observation.id,
    'projectionId', v_projection.id,
    'attemptId', v_attempt.id,
    'jobId', v_job.id,
    'invoiceId', v_revision.external_document_id,
    'invoiceNumber', v_revision.external_document_number,
    'operation', v_revision.revision_intent,
    'providerStatus', coalesce(v_observation.raw_status, v_revision.requested_provider_status),
    'subtotalMinor', v_revision.subtotal_minor,
    'taxMinor', v_revision.tax_minor,
    'totalMinor', v_revision.total_minor,
    'paidMinor', coalesce(v_projection.amount_paid_minor, 0),
    'creditedMinor', coalesce(v_projection.amount_credited_minor, 0),
    'outstandingMinor', coalesce(v_projection.amount_due_minor, v_revision.total_minor),
    'observedAt', v_observation.observed_at,
    'completedAt', v_attempt.completed_at,
    'sourceMatches', coalesce(v_source_matches, false),
    'document', to_jsonb(v_document),
    'revision', to_jsonb(v_revision),
    'observation', to_jsonb(v_observation),
    'projection', to_jsonb(v_projection)
  );
end;
$$;


ALTER FUNCTION "public"."get_accounting_sync_completion_evidence"("p_organization_id" "uuid", "p_job_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_commercial_item"("p_commercial_item_id" "uuid") RETURNS TABLE("id" "uuid", "organization_id" "uuid", "opportunity_id" "uuid", "project_id" "uuid", "source_type" "text", "source_workbook_id" "uuid", "source_worksheet_id" "uuid", "source_sheet_id" "uuid", "source_range" "text", "source_signature" "text", "source_version" integer, "source_status" "text", "stale_reason_code" "text", "last_source_checked_at" timestamp with time zone, "last_source_changed_at" timestamp with time zone, "description" "text", "quantity" numeric, "unit" "text", "rate" numeric, "total" numeric, "snapshot_json" "jsonb", "source_link_json" "jsonb", "ucl_classification" "text", "ucl_validation_status" "text", "created_by" "uuid", "updated_by" "uuid", "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if auth.uid() is null then
    raise exception 'Authentication is required';
  end if;

  return query
  select
    item.id,
    item.organization_id,
    item.opportunity_id,
    item.project_id,
    item.source_type,
    item.source_workbook_id,
    item.source_worksheet_id,
    item.source_sheet_id,
    item.source_range,
    item.source_signature,
    item.source_version,
    item.source_status,
    item.stale_reason_code,
    item.last_source_checked_at,
    item.last_source_changed_at,
    item.description,
    item.quantity,
    item.unit,
    item.rate,
    item.total,
    item.snapshot_json,
    item.source_link_json,
