CREATE OR REPLACE FUNCTION "public"."get_company_payment_claims_register"("p_organization_id" "uuid", "p_month" "text" DEFAULT NULL::"text", "p_search" "text" DEFAULT NULL::"text", "p_project_id" "uuid" DEFAULT NULL::"uuid", "p_client_id" "uuid" DEFAULT NULL::"uuid", "p_claim_status" "text" DEFAULT NULL::"text", "p_xero_status" "text" DEFAULT NULL::"text", "p_external_status" "text" DEFAULT NULL::"text", "p_payment_status" "text" DEFAULT NULL::"text", "p_outstanding_only" boolean DEFAULT false, "p_overdue_only" boolean DEFAULT false, "p_attention_only" boolean DEFAULT false, "p_sort" "text" DEFAULT 'period'::"text", "p_direction" "text" DEFAULT 'desc'::"text", "p_page" integer DEFAULT 1, "p_page_size" integer DEFAULT 50) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
declare
  v_timezone text;
  v_currency text;
  v_month text;
  v_month_start date;
  v_next_month_start date;
  v_today date;
  v_page integer := greatest(coalesce(p_page, 1), 1);
  v_page_size integer := least(greatest(coalesce(p_page_size, 50), 1), 100);
  v_result jsonb;
begin
  if auth.uid() is null then
    raise exception 'Authentication is required' using errcode = '42501';
  end if;

  if not exists (
    select 1
    from public.organization_members member
    where member.organization_id = p_organization_id
      and member.user_id = auth.uid()
  ) then
    raise exception 'Active organization membership is required' using errcode = '42501';
  end if;

  if not public.has_org_permission(
    p_organization_id,
    'accounting.sales_invoices.view'
  ) then
    raise exception 'Payment Claims register access is denied' using errcode = '42501';
  end if;

  select
    case
      when exists (
        select 1 from pg_timezone_names zone where zone.name = organization.timezone
      ) then organization.timezone
      else 'UTC'
    end,
    coalesce(
      nullif(upper(trim(to_jsonb(organization)->>'default_currency')), ''),
      'NZD'
    )
  into v_timezone, v_currency
  from public.organizations organization
  where organization.id = p_organization_id;

  if v_timezone is null then
    raise exception 'Organization not found' using errcode = '42501';
  end if;

  v_today := (now() at time zone v_timezone)::date;
  v_month := case
    when lower(coalesce(p_month, '')) = 'all' then 'all'
    when coalesce(p_month, '') ~ '^[0-9]{4}-(0[1-9]|1[0-2])$' then p_month
    else to_char(v_today, 'YYYY-MM')
  end;
  if v_month <> 'all' then
    v_month_start := to_date(v_month || '-01', 'YYYY-MM-DD');
    v_next_month_start := (v_month_start + interval '1 month')::date;
  end if;

  with base as not materialized (
    select
      claim.id,
      claim.claim_number,
      claim.claim_title,
      claim.status as claim_status,
      claim.claim_date,
      claim.period_start,
      claim.period_end,
      claim.due_date as internal_due_date,
      claim.claim_amount,
      claim.retention_withheld_amount,
      claim.retention_released_amount,
      claim.net_claim_excl_gst,
      claim.gst_amount,
      claim.total_payable,
      claim.previous_claims_total,
      claim.created_at,
      project.id as project_id,
      project.slug as project_slug,
      project.project_code,
      project.name as project_name,
      client.id as client_id,
      coalesce(nullif(trim(client.company_name), ''), nullif(trim(client.name), ''))
        as client_name,
      document.id as accounting_document_id,
      coalesce(revision.external_document_number, document.external_document_number)
        as xero_invoice_number,
      coalesce(revision.external_document_id, document.external_document_id)
        as xero_invoice_id,
      coalesce(revision.currency_code, document.currency_code, v_currency) as currency,
      coalesce(
        nullif(revision.commercial_snapshot->>'invoiceDate', '')::date,
        claim.claim_date
      ) as invoice_date,
      coalesce(
        nullif(revision.commercial_snapshot->>'dueDate', '')::date,
        claim.due_date
      ) as effective_due_date,
      revision.subtotal_minor,
      revision.tax_minor,
      revision.total_minor,
      projection.projected_at,
      projection.divergent,
      case
        when projection.divergent then null
        else projection.amount_paid_minor
      end as trusted_paid_minor,
      case
        when projection.divergent then null
        else projection.amount_due_minor
      end as trusted_outstanding_minor,
      coalesce(
        projection.normalized_invoice_status,
        document.normalized_external_status
      ) as external_status,
      case
        when projection.divergent then 'attention_required'
        else projection.normalized_payment_status
      end as payment_status,
      case
        when document.id is null then 'not_exported'
        when projection.divergent
          or document.export_status in ('failed', 'attention_required')
          or revision.lifecycle_state = 'failed'
          or nullif(document.last_status_sync_error, '') is not null
          or (
            document.export_status = 'exported'
            and projection.id is null
          )
          then 'attention_required'
        when revision.lifecycle_state in ('queued', 'processing', 'succeeded', 'cancelled', 'superseded')
          then revision.lifecycle_state
        when document.export_status in ('queued', 'exporting', 'exported', 'cancelled')
          then document.export_status
        else coalesce(document.export_status, 'not_exported')
      end as xero_status,
      coalesce((
        projection.divergent
        or document.export_status in ('failed', 'attention_required')
        or revision.lifecycle_state = 'failed'
        or nullif(document.last_status_sync_error, '') is not null
        or (
          document.export_status = 'exported'
          and projection.id is null
        )
        or coalesce(
          projection.normalized_invoice_status,
          document.normalized_external_status
        ) in ('voided', 'deleted', 'unknown')
      ), false) as xero_attention,
      claim.claim_date as period_key
    from public.project_claims claim
    join public.organization_projects project
      on project.id = claim.project_id
     and project.organization_id = claim.organization_id
    left join public.organization_clients client
      on client.id = project.client_id
     and client.organization_id = project.organization_id
    left join public.organization_xero_connections connection
      on connection.organization_id = claim.organization_id
    left join lateral (
      select candidate.*
      from public.organization_accounting_documents candidate
      where candidate.organization_id = claim.organization_id
        and candidate.provider = 'xero'
        and candidate.local_document_type = 'project_claim'
        and candidate.project_claim_id = claim.id
        and candidate.accounting_connection_id = connection.id
        and candidate.tenant_id = connection.tenant_id
      order by candidate.created_at desc, candidate.id desc
      limit 1
    ) document on true
    left join public.organization_accounting_document_revisions revision
      on revision.id = document.active_accounting_revision_id
     and revision.organization_id = document.organization_id
     and revision.accounting_document_id = document.id
     and revision.connection_id = document.accounting_connection_id
     and revision.tenant_id = document.tenant_id
    left join public.organization_accounting_projections projection
      on projection.id = document.current_accounting_projection_id
     and projection.organization_id = document.organization_id
     and projection.accounting_document_id = document.id
     and projection.accounting_revision_id = revision.id
    where claim.organization_id = p_organization_id
      and claim.status <> 'Draft'
  ),
  filtered as materialized (
    select base.*
    from base
    where (
        v_month = 'all'
        or (
          base.period_key >= v_month_start
          and base.period_key < v_next_month_start
        )
      )
      and (
        nullif(trim(coalesce(p_search, '')), '') is null
        or base.claim_number ilike '%' || trim(p_search) || '%'
        or base.claim_title ilike '%' || trim(p_search) || '%'
        or base.project_code ilike '%' || trim(p_search) || '%'
        or base.project_name ilike '%' || trim(p_search) || '%'
        or coalesce(base.client_name, '') ilike '%' || trim(p_search) || '%'
        or coalesce(base.xero_invoice_number, '') ilike '%' || trim(p_search) || '%'
      )
      and (p_project_id is null or base.project_id = p_project_id)
      and (p_client_id is null or base.client_id = p_client_id)
      and (nullif(p_claim_status, '') is null or base.claim_status = p_claim_status)
      and (nullif(p_xero_status, '') is null or base.xero_status = p_xero_status)
      and (
        nullif(p_external_status, '') is null
        or base.external_status = p_external_status
      )
      and (
        nullif(p_payment_status, '') is null
        or base.payment_status = p_payment_status
      )
      and (
        not coalesce(p_outstanding_only, false)
        or (
          base.trusted_outstanding_minor > 0
          and coalesce(base.external_status, '') not in ('voided', 'deleted')
        )
      )
      and (
        not coalesce(p_overdue_only, false)
        or (
          base.trusted_outstanding_minor > 0
          and base.effective_due_date < v_today
          and base.claim_status <> 'Cancelled'
          and coalesce(base.external_status, '') not in ('voided', 'deleted')
        )
      )
      and (not coalesce(p_attention_only, false) or base.xero_attention)
  ),
  ordered as (
    select filtered.*
    from filtered
    order by
      case when p_sort = 'claim_number' and p_direction = 'asc' then lower(claim_number) end asc,
      case when p_sort = 'claim_number' and p_direction = 'desc' then lower(claim_number) end desc,
      case when p_sort = 'due' and p_direction = 'asc' then effective_due_date end asc nulls last,
      case when p_sort = 'due' and p_direction = 'desc' then effective_due_date end desc nulls last,
      case when p_sort = 'amount' and p_direction = 'asc' then total_payable end asc,
      case when p_sort = 'amount' and p_direction = 'desc' then total_payable end desc,
      case when p_sort = 'period' and p_direction = 'asc' then period_end end asc nulls last,
      case when p_sort = 'period' and p_direction = 'desc' then period_end end desc nulls last,
      claim_date desc nulls last,
      created_at desc,
      id desc
    limit v_page_size
    offset (v_page - 1) * v_page_size
  ),
  metrics as (
    select
      coalesce(sum(total_payable) filter (where claim_status <> 'Cancelled'), 0)
        as amount_payable,
      coalesce(sum(trusted_paid_minor) filter (
        where claim_status <> 'Cancelled'
          and coalesce(external_status, '') not in ('voided', 'deleted')
      ), 0) as paid_minor,
      coalesce(sum(trusted_outstanding_minor) filter (
        where claim_status <> 'Cancelled'
          and coalesce(external_status, '') not in ('voided', 'deleted')
      ), 0) as outstanding_minor,
      count(*) filter (
        where claim_status <> 'Cancelled'
          and coalesce(external_status, '') not in ('voided', 'deleted')
          and (
            payment_status is distinct from 'paid'
            and (
              trusted_outstanding_minor > 0
              or (
                trusted_outstanding_minor is null
                and claim_status in ('Submitted', 'Unpaid', 'Overdue')
              )
            )
          )
      ) as open_claims,
      count(*) filter (where xero_attention) as xero_attention
    from filtered
  ),
  options as (
    select
      coalesce((
        select jsonb_agg(option order by option->>'label')
        from (
          select distinct jsonb_build_object(
            'value', project_id,
            'label', trim(concat(project_code, ' ', project_name))
          ) as option
          from base
        ) project_options
      ), '[]'::jsonb) as projects,
      coalesce((
        select jsonb_agg(option order by option->>'label')
        from (
          select distinct jsonb_build_object('value', client_id, 'label', client_name) as option
          from base
          where client_id is not null and client_name is not null
        ) client_options
      ), '[]'::jsonb) as clients,
      coalesce((
        select jsonb_agg(month_key order by month_key desc)
        from (
          select distinct to_char(period_key, 'YYYY-MM') as month_key
          from base
          where period_key is not null
        ) month_options
      ), '[]'::jsonb) as months
  )
  select jsonb_build_object(
    'rows', coalesce((
      select jsonb_agg(to_jsonb(ordered) order by
        case when p_sort = 'claim_number' and p_direction = 'asc' then lower(claim_number) end asc,
        case when p_sort = 'claim_number' and p_direction = 'desc' then lower(claim_number) end desc,
        case when p_sort = 'due' and p_direction = 'asc' then effective_due_date end asc nulls last,
        case when p_sort = 'due' and p_direction = 'desc' then effective_due_date end desc nulls last,
        case when p_sort = 'amount' and p_direction = 'asc' then total_payable end asc,
        case when p_sort = 'amount' and p_direction = 'desc' then total_payable end desc,
        case when p_sort = 'period' and p_direction = 'asc' then period_end end asc nulls last,
        case when p_sort = 'period' and p_direction = 'desc' then period_end end desc nulls last,
        claim_date desc nulls last,
        created_at desc,
        id desc
      )
      from ordered
    ), '[]'::jsonb),
    'metrics', jsonb_build_object(
      'amountPayable', metrics.amount_payable,
      'paid', metrics.paid_minor::numeric / 100,
      'outstanding', metrics.outstanding_minor::numeric / 100,
      'openClaims', metrics.open_claims,
      'xeroAttention', metrics.xero_attention
    ),
    'pageInfo', jsonb_build_object(
      'page', v_page,
      'pageSize', v_page_size,
      'totalRows', (select count(*) from filtered),
      'totalPages', greatest(ceil((select count(*) from filtered)::numeric / v_page_size), 1)
    ),
    'options', jsonb_build_object(
      'projects', options.projects,
      'clients', options.clients,
      'months', options.months
    ),
    'context', jsonb_build_object(
      'month', v_month,
      'timezone', v_timezone,
      'currency', v_currency,
      'localToday', v_today
    )
  )
  into v_result
  from metrics
  cross join options;

  return v_result;
end;
$_$;


ALTER FUNCTION "public"."get_company_payment_claims_register"("p_organization_id" "uuid", "p_month" "text", "p_search" "text", "p_project_id" "uuid", "p_client_id" "uuid", "p_claim_status" "text", "p_xero_status" "text", "p_external_status" "text", "p_payment_status" "text", "p_outstanding_only" boolean, "p_overdue_only" boolean, "p_attention_only" boolean, "p_sort" "text", "p_direction" "text", "p_page" integer, "p_page_size" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_document_files_page_metadata"("p_workspace_id" "uuid") RETURNS TABLE("can_view" boolean, "can_write" boolean, "can_delete" boolean, "can_purge" boolean, "cleanup_attention_required" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  workspace_row public.document_workspaces%rowtype;
  monitor_allowed boolean;
begin
  workspace_row := public.assert_document_workspace_permission(
    p_workspace_id,
    'files.view'
  );
  monitor_allowed := public.has_org_permission(
    workspace_row.organization_id,
    'files.monitor'
  );

  return query select
    true,
    public.has_org_permission(workspace_row.organization_id, 'files.write'),
    public.has_org_permission(workspace_row.organization_id, 'files.delete'),
    public.has_org_permission(workspace_row.organization_id, 'files.purge'),
    monitor_allowed and (
      exists (
        select 1
        from public.document_storage_cleanup_jobs job
        where job.organization_id = workspace_row.organization_id
          and job.processing_status = 'dead_lettered'
      )
      or exists (
        select 1
        from public.document_storage_reconciliation_findings finding
        where finding.organization_id = workspace_row.organization_id
          and finding.finding_status = 'open'
      )
    );
end;
$$;


ALTER FUNCTION "public"."get_document_files_page_metadata"("p_workspace_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_document_folder_breadcrumbs"("p_workspace_id" "uuid", "p_folder_node_id" "uuid") RETURNS TABLE("node_id" "uuid", "parent_node_id" "uuid", "display_name" "text", "depth" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  perform public.assert_document_workspace_permission(p_workspace_id, 'files.view');

  if p_folder_node_id is null then
    return;
  end if;

  if not exists (
    select 1
    from public.document_nodes folder
    where folder.workspace_id = p_workspace_id
      and folder.id = p_folder_node_id
      and folder.kind = 'folder'
      and folder.lifecycle_state = 'active'
      and folder.deleted_at is null
  ) then
    raise exception 'Document folder not found.';
  end if;

  return query
  with recursive ancestors as (
    select folder.id, folder.parent_node_id, folder.display_name, 0 as depth
    from public.document_nodes folder
    where folder.workspace_id = p_workspace_id
      and folder.id = p_folder_node_id
    union all
    select parent.id, parent.parent_node_id, parent.display_name, child.depth + 1
    from public.document_nodes parent
    join ancestors child on child.parent_node_id = parent.id
    where parent.workspace_id = p_workspace_id
      and parent.kind = 'folder'
      and parent.lifecycle_state = 'active'
      and parent.deleted_at is null
  )
  select ancestors.id, ancestors.parent_node_id, ancestors.display_name, ancestors.depth
  from ancestors
  order by ancestors.depth desc;
end;
$$;


ALTER FUNCTION "public"."get_document_folder_breadcrumbs"("p_workspace_id" "uuid", "p_folder_node_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_document_storage_diagnostics"("p_workspace_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  workspace_row public.document_workspaces%rowtype;
  usage_row public.organization_document_storage_usage%rowtype;
begin
  workspace_row := public.assert_document_workspace_permission(
    p_workspace_id,
    'files.monitor'
  );
  perform public.ensure_document_storage_usage_row(workspace_row.organization_id);

  select *
  into usage_row
  from public.organization_document_storage_usage usage
  where usage.organization_id = workspace_row.organization_id;

  return jsonb_build_object(
    'pendingUploads', (
      select count(*)
      from public.document_versions version
      where version.organization_id = workspace_row.organization_id
        and version.upload_state in ('pending', 'uploaded')
    ),
    'abandonedUploads', (
      select count(*)
      from public.document_versions version
      where version.organization_id = workspace_row.organization_id
        and version.upload_state in ('failed', 'abandoned')
    ),
    'cleanupPending', (
      select count(*)
      from public.document_storage_cleanup_jobs job
      where job.organization_id = workspace_row.organization_id
        and job.processing_status in ('pending', 'claimed', 'retry_scheduled')
    ),
    'cleanupFailures', (
      select count(*)
      from public.document_storage_cleanup_jobs job
      where job.organization_id = workspace_row.organization_id
        and job.last_error_code is not null
    ),
    'deadLetterJobs', (
      select count(*)
      from public.document_storage_cleanup_jobs job
      where job.organization_id = workspace_row.organization_id
        and job.processing_status = 'dead_lettered'
    ),
    'orphanCount', (
      select count(*)
      from public.document_storage_reconciliation_findings finding
      where finding.organization_id = workspace_row.organization_id
        and finding.discrepancy_type = 'object_without_record'
        and finding.finding_status <> 'resolved'
    ),
    'reconciliationFailures', (
      select count(*)
      from public.document_storage_reconciliation_findings finding
      where finding.organization_id = workspace_row.organization_id
        and finding.finding_status <> 'resolved'
    ),
    'quotaBytes', usage_row.quota_bytes,
    'usedBytes',
      usage_row.active_bytes + usage_row.deleted_bytes + usage_row.pending_bytes,
    'activeBytes', usage_row.active_bytes,
    'deletedBytes', usage_row.deleted_bytes,
    'pendingBytes', usage_row.pending_bytes,
    'fileCount', usage_row.file_count,
    'folderCount', usage_row.folder_count,
    'currentVersionCount', usage_row.current_version_count,
    'historicalVersionCount', usage_row.historical_version_count,
    'reconciledAt', usage_row.reconciled_at
  );
end;
$$;


ALTER FUNCTION "public"."get_document_storage_diagnostics"("p_workspace_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_document_storage_usage"("p_workspace_id" "uuid") RETURNS TABLE("quota_bytes" bigint, "active_bytes" bigint, "deleted_bytes" bigint, "pending_bytes" bigint, "total_bytes" bigint, "remaining_bytes" bigint, "file_count" bigint, "folder_count" bigint, "current_version_count" bigint, "historical_version_count" bigint, "can_delete" boolean, "can_purge" boolean, "can_monitor" boolean, "cleanup_attention_required" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  workspace_row public.document_workspaces%rowtype;
  usage_row public.organization_document_storage_usage%rowtype;
  monitor_allowed boolean;
begin
  workspace_row := public.assert_document_workspace_permission(
    p_workspace_id,
    'files.view'
  );
  perform public.ensure_document_storage_usage_row(workspace_row.organization_id);

  select *
  into usage_row
  from public.organization_document_storage_usage usage
  where usage.organization_id = workspace_row.organization_id;

  monitor_allowed := public.has_org_permission(
    workspace_row.organization_id,
    'files.monitor'
  );

  return query
  select
    usage_row.quota_bytes,
    usage_row.active_bytes,
    usage_row.deleted_bytes,
    usage_row.pending_bytes,
    usage_row.active_bytes + usage_row.deleted_bytes + usage_row.pending_bytes,
    greatest(
      0,
      usage_row.quota_bytes
        - usage_row.active_bytes
        - usage_row.deleted_bytes
        - usage_row.pending_bytes
    ),
    usage_row.file_count,
    usage_row.folder_count,
    usage_row.current_version_count,
    usage_row.historical_version_count,
    public.has_org_permission(workspace_row.organization_id, 'files.delete'),
    public.has_org_permission(workspace_row.organization_id, 'files.purge'),
    monitor_allowed,
    monitor_allowed and (
      exists (
        select 1
        from public.document_storage_cleanup_jobs job
        where job.organization_id = workspace_row.organization_id
          and job.processing_status = 'dead_lettered'
      )
      or exists (
        select 1
        from public.document_storage_reconciliation_findings finding
        where finding.organization_id = workspace_row.organization_id
          and finding.finding_status = 'open'
      )
    );
end;
$$;


ALTER FUNCTION "public"."get_document_storage_usage"("p_workspace_id" "uuid") OWNER TO "postgres";


