CREATE OR REPLACE FUNCTION "public"."get_master_retention_claim_execution"("p_revision_id" "uuid", "p_attempt_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select jsonb_build_object(
    'document', to_jsonb(document),
    'revision', to_jsonb(revision),
    'previousRevision', to_jsonb(previous),
    'lines', coalesce((
      select jsonb_agg(to_jsonb(line) order by line.sequence)
      from public.organization_accounting_revision_lines line
      where line.accounting_revision_id = revision.id
    ), '[]'::jsonb),
    'attempt', to_jsonb(attempt)
  )
  from public.organization_accounting_document_revisions revision
  join public.organization_accounting_documents document
    on document.id = revision.accounting_document_id
   and document.organization_id = revision.organization_id
  join public.organization_accounting_revision_attempts attempt
    on attempt.id = p_attempt_id
   and attempt.accounting_revision_id = revision.id
  left join public.organization_accounting_document_revisions previous
    on previous.id = revision.previous_revision_id
  where revision.id = p_revision_id
    and revision.source_document_type = 'retention_claim'
    and document.integration_contract = 'retention_claim_revision_v1';
$$;


ALTER FUNCTION "public"."get_master_retention_claim_execution"("p_revision_id" "uuid", "p_attempt_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_mobile_project_purchase_order_detail_v2"("p_project_id" "uuid", "p_purchase_order_id" "uuid") RETURNS TABLE("purchase_order_id" "uuid", "project_id" "uuid", "purchase_order_number" "text", "purchase_order_title" "text", "status" "text", "origin" "text", "requested_by" "text", "requested_date" "date", "due_date" "date", "notes" "text", "issued_to_label" "text", "supplier_contact" "text", "supplier_name_snapshot" "text", "supplier_email_snapshot" "text", "supplier_phone_snapshot" "text", "subtotal" numeric, "gst_total" numeric, "total_purchase_order_price" numeric, "line_items" "jsonb", "attachments" "jsonb", "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
declare
  current_context record;
begin
  select *
  into current_context
  from public.resolve_mobile_project_member_context_v2(p_project_id);

  if not exists (
    select 1
    from public.project_purchase_orders po
    where po.organization_id = current_context.organization_id
      and po.project_id = p_project_id
      and po.id = p_purchase_order_id
  ) then
    raise exception 'Purchase order not found for this project';
  end if;

  return query
  select
    po.id as purchase_order_id,
    po.project_id,
    po.purchase_order_number,
    po.purchase_order_title,
    po.status,
    po.origin,
    po.requested_by,
    po.requested_date,
    po.due_date,
    po.notes,
    po.issued_to_label,
    po.supplier_contact,
    po.supplier_name_snapshot,
    po.supplier_email_snapshot,
    po.supplier_phone_snapshot,
    po.subtotal,
    po.gst_total,
    po.total_purchase_order_price,
    coalesce(
      (
        select jsonb_agg(
          jsonb_build_object(
            'id', li.id,
            'section', li.section,
            'description', li.description,
            'quantity', li.quantity,
            'unit', li.unit,
            'rate', li.rate,
            'total', li.total,
            'sort_order', li.sort_order
          )
          order by li.sort_order asc, li.created_at asc
        )
        from public.project_purchase_order_line_items li
        where li.organization_id = current_context.organization_id
          and li.project_id = p_project_id
          and li.purchase_order_id = po.id
      ),
      '[]'::jsonb
    ) as line_items,
    coalesce(
      (
        select jsonb_agg(
          jsonb_build_object(
            'id', att.id,
            'file_name', att.file_name,
            'file_kind', att.file_kind,
            'notes', att.notes,
            'has_file', att.storage_path is not null,
            'has_external_url', public.is_safe_mobile_https_url(att.external_url),
            'created_at', att.created_at
          )
          order by att.created_at asc
        )
        from public.project_purchase_order_attachments att
        where att.organization_id = current_context.organization_id
          and att.project_id = p_project_id
          and att.purchase_order_id = po.id
      ),
      '[]'::jsonb
    ) as attachments,
    po.created_at,
    po.updated_at
  from public.project_purchase_orders po
  where po.organization_id = current_context.organization_id
    and po.project_id = p_project_id
    and po.id = p_purchase_order_id
  limit 1;
end;
$$;


ALTER FUNCTION "public"."get_mobile_project_purchase_order_detail_v2"("p_project_id" "uuid", "p_purchase_order_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_mobile_worker_project_purchase_order_detail"("p_project_id" "uuid", "p_purchase_order_id" "uuid") RETURNS TABLE("purchase_order_id" "uuid", "project_id" "uuid", "purchase_order_number" "text", "purchase_order_title" "text", "status" "text", "origin" "text", "requested_by" "text", "requested_date" "date", "due_date" "date", "notes" "text", "issued_to_label" "text", "subtotal" numeric, "gst_total" numeric, "total_purchase_order_price" numeric, "line_items" "jsonb", "attachments" "jsonb", "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
declare
  current_context record;
begin
