  return query
  select
    po.id as purchase_order_id,
    po.project_id,
    po.purchase_order_number,
    po.purchase_order_title,
    po.status,
    po.origin,
    po.requested_by,
    po.requested_date,
    po.due_date,
    po.notes,
    po.issued_to_label,
    po.subtotal,
    po.gst_total,
    po.total_purchase_order_price,
    coalesce(
      (
        select jsonb_agg(
          jsonb_build_object(
            'id', li.id,
            'section', li.section,
            'description', li.description,
            'quantity', li.quantity,
            'unit', li.unit,
            'rate', li.rate,
            'total', li.total,
            'sort_order', li.sort_order
          )
          order by li.sort_order asc, li.created_at asc
        )
        from public.project_purchase_order_line_items li
        where li.organization_id = current_context.organization_id
          and li.project_id = p_project_id
          and li.purchase_order_id = po.id
      ),
      '[]'::jsonb
    ) as line_items,
    coalesce(
      (
        select jsonb_agg(
          jsonb_build_object(
            'id', att.id,
            'file_name', att.file_name,
            'file_kind', att.file_kind,
            'notes', att.notes,
            'has_file', att.storage_path is not null,
            'has_external_url', public.is_safe_mobile_https_url(att.external_url),
            'created_at', att.created_at
          )
          order by att.created_at asc
        )
        from public.project_purchase_order_attachments att
        where att.organization_id = current_context.organization_id
          and att.project_id = p_project_id
          and att.purchase_order_id = po.id
      ),
      '[]'::jsonb
    ) as attachments,
    po.created_at,
    po.updated_at
  from public.project_purchase_orders po
  where po.organization_id = current_context.organization_id
    and po.project_id = p_project_id
    and po.id = p_purchase_order_id
  limit 1;
end;
$$;


ALTER FUNCTION "public"."get_mobile_worker_project_purchase_order_detail"("p_project_id" "uuid", "p_purchase_order_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_mobile_worker_purchase_order_attachment_url"("p_project_id" "uuid", "p_attachment_id" "uuid") RETURNS TABLE("attachment_id" "uuid", "purchase_order_id" "uuid", "file_name" "text", "file_kind" "text", "url" "text", "expires_at" timestamp with time zone, "source" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
declare
  current_context record;
  attachment_row public.project_purchase_order_attachments%rowtype;
begin
  select *
  into current_context
  from public.resolve_mobile_worker_project_context(p_project_id);

  select att.*
  into attachment_row
  from public.project_purchase_order_attachments att
  join public.project_purchase_orders po
    on po.id = att.purchase_order_id
  where att.id = p_attachment_id
    and att.organization_id = current_context.organization_id
    and att.project_id = p_project_id
    and po.organization_id = current_context.organization_id
    and po.project_id = p_project_id
    and public.is_mobile_worker_assigned_purchase_order(
      p_project_id,
      att.purchase_order_id,
      current_context.organization_member_id
    )
  limit 1;

  if attachment_row.id is null then
    raise exception 'Attachment not found or not assigned to the current worker';
  end if;

  if attachment_row.storage_path is not null then
    raise exception 'Storage-backed attachment URLs are not available from this SQL contract';
  end if;

  if not public.is_safe_mobile_https_url(attachment_row.external_url) then
    raise exception 'Attachment URL is unavailable or uses an unsupported scheme';
  end if;

  return query
  select
    attachment_row.id as attachment_id,
    attachment_row.purchase_order_id,
    attachment_row.file_name,
    attachment_row.file_kind,
    btrim(attachment_row.external_url) as url,
    null::timestamptz as expires_at,
    'external_url'::text as source;
end;
$$;


ALTER FUNCTION "public"."get_mobile_worker_purchase_order_attachment_url"("p_project_id" "uuid", "p_attachment_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_opportunity_promotion_shadow_summary_v1"("p_organization_id" "uuid") RETURNS TABLE("evaluator_version" "text", "first_observed_at" timestamp with time zone, "last_observed_at" timestamp with time zone, "total_runs" bigint, "eligible_runs" bigint, "ineligible_runs" bigint, "completed_comparisons" bigint, "exact_matches" bigint, "expected_differences" bigint, "mismatches" bigint, "comparison_errors" bigint)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select
    coalesce(max(run.evaluator_version), 'shadow-v1'),
    min(run.pre_observed_at),
    max(run.pre_observed_at),
    count(*),
    count(*) filter (where run.eligibility_result = 'eligible'),
    count(*) filter (where run.eligibility_result = 'ineligible'),
    count(*) filter (where run.status = 'completed'),
    count(*) filter (where run.comparison_result = 'match'),
    count(*) filter (where run.comparison_result = 'expected_difference'),
    count(*) filter (where run.comparison_result = 'mismatch'),
    count(*) filter (where run.comparison_result = 'comparison_error')
  from public.opportunity_promotion_shadow_runs run
  where run.organization_id = p_organization_id;
$$;


ALTER FUNCTION "public"."get_opportunity_promotion_shadow_summary_v1"("p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_opportunity_quotation_workspace_v1"("p_organization_id" "uuid", "p_opportunity_id" "uuid") RETURNS TABLE("primary_quote" "jsonb", "tender_clients" "jsonb")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with opportunity as (
    select candidate.* from public.organization_opportunities candidate
    where candidate.organization_id = p_organization_id and candidate.id = p_opportunity_id
  ), primary_source as (
    select quote.*, series.id as primary_series_id,
      public.opportunity_quote_snapshot_hash_v1(p_organization_id, quote.id) as current_hash
    from opportunity
    join public.opportunity_quote_series series
      on series.organization_id = opportunity.organization_id
     and series.opportunity_id = opportunity.id
     and series.recipient_client_id = opportunity.client_id
     and series.archived_at is null
    join public.project_quotes quote
      on quote.organization_id = series.organization_id and quote.id = series.current_revision_id
    limit 1
  ), tender_rows as (
    select tender.id as tender_client_id, tender.client_id, tender.is_primary, true as is_tender_client,
      coalesce(nullif(client.company_name, ''), client.name) as client_name,
      client.name as contact_name, client.email, client.phone,
      series.id as series_id, series.base_quote_number, series.display_reference,
      current_quote.id as current_revision_id, current_quote.revision_number,
      greatest(coalesce(current_quote.revision_number, 1) - 1, 0) as display_revision_number,
      current_quote.status, current_quote.total_quote_price, current_quote.quote_date,
      current_quote.expiry_date, current_quote.updated_at,
      coalesce((select count(*)::integer from public.project_quotes history
        where history.organization_id = series.organization_id and history.quote_series_id = series.id), 0) as revision_count,
      opportunity.accepted_quote_revision_id,
      opportunity.accepted_quote_revision_id = current_quote.id as is_current_accepted,
      case when series.source_quote_revision_id is null then false
        else series.source_quote_hash is distinct from public.opportunity_quote_snapshot_hash_v1(
          p_organization_id, series.source_quote_revision_id) end as source_changed_since_distribution
    from public.opportunity_tender_clients tender
    join public.organization_clients client
      on client.organization_id = tender.organization_id and client.id = tender.client_id
    left join lateral (
      select candidate.* from public.opportunity_quote_series candidate
      where candidate.organization_id = tender.organization_id
        and candidate.opportunity_id = tender.opportunity_id
        and candidate.recipient_client_id = tender.client_id and candidate.archived_at is null
      order by candidate.created_at limit 1
    ) series on true
    left join public.project_quotes current_quote
      on current_quote.organization_id = series.organization_id and current_quote.id = series.current_revision_id
    join opportunity on opportunity.organization_id = tender.organization_id
      and opportunity.id = tender.opportunity_id
    where tender.organization_id = p_organization_id and tender.opportunity_id = p_opportunity_id
      and tender.archived_at is null
  ), orphan_rows as (
    select null::uuid as tender_client_id, series.recipient_client_id as client_id,
      false as is_primary, false as is_tender_client,
      coalesce(nullif(client.company_name, ''), client.name, 'Unresolved recipient') as client_name,
      client.name as contact_name, client.email, client.phone,
      series.id as series_id, series.base_quote_number, series.display_reference,
      current_quote.id as current_revision_id, current_quote.revision_number,
      greatest(current_quote.revision_number - 1, 0) as display_revision_number,
      current_quote.status, current_quote.total_quote_price, current_quote.quote_date,
      current_quote.expiry_date, current_quote.updated_at,
      (select count(*)::integer from public.project_quotes history
        where history.organization_id = series.organization_id and history.quote_series_id = series.id) as revision_count,
      opportunity.accepted_quote_revision_id,
      opportunity.accepted_quote_revision_id = current_quote.id as is_current_accepted,
      case when series.source_quote_revision_id is null then false
        else series.source_quote_hash is distinct from public.opportunity_quote_snapshot_hash_v1(
          p_organization_id, series.source_quote_revision_id) end as source_changed_since_distribution
    from public.opportunity_quote_series series
    join opportunity on opportunity.organization_id = series.organization_id and opportunity.id = series.opportunity_id
    join public.project_quotes current_quote
      on current_quote.organization_id = series.organization_id and current_quote.id = series.current_revision_id
    left join public.organization_clients client
      on client.organization_id = series.organization_id and client.id = series.recipient_client_id
    where series.organization_id = p_organization_id and series.opportunity_id = p_opportunity_id
      and series.archived_at is null and not exists (
        select 1 from public.opportunity_tender_clients tender
        where tender.organization_id = series.organization_id and tender.opportunity_id = series.opportunity_id
          and tender.client_id = series.recipient_client_id and tender.archived_at is null
      )
  ), all_rows as (select * from tender_rows union all select * from orphan_rows)
  select (select to_jsonb(primary_source) from primary_source),
    coalesce((select jsonb_agg(to_jsonb(all_rows) order by is_primary desc, client_name, client_id)
      from all_rows), '[]'::jsonb)
  where public.is_member_of_organization(p_organization_id)
    and exists (select 1 from opportunity);
$$;


ALTER FUNCTION "public"."get_opportunity_quotation_workspace_v1"("p_organization_id" "uuid", "p_opportunity_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_opportunity_quote_register_v1"("p_organization_id" "uuid", "p_opportunity_id" "uuid") RETURNS TABLE("series_id" "uuid", "base_quote_number" "text", "recipient_client_id" "uuid", "recipient_name" "text", "current_revision_id" "uuid", "revision_number" integer, "revision_count" bigint, "status" "text", "total_quote_price" numeric, "quote_date" "date", "expiry_date" "date", "updated_at" timestamp with time zone, "accepted_revision_id" "uuid", "is_current_accepted" boolean)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  select series.id, series.base_quote_number, series.recipient_client_id,
    coalesce(nullif(client.company_name, ''), client.name, 'Recipient reconciliation required'),
    current_quote.id, current_quote.revision_number,
    (select count(*) from public.project_quotes history
      where history.organization_id = series.organization_id and history.quote_series_id = series.id),
    current_quote.status, current_quote.total_quote_price, current_quote.quote_date,
    current_quote.expiry_date, current_quote.updated_at,
    opportunity.accepted_quote_revision_id,
    opportunity.accepted_quote_revision_id = current_quote.id
  from public.opportunity_quote_series series
  join public.organization_opportunities opportunity
    on opportunity.organization_id = series.organization_id and opportunity.id = series.opportunity_id
  join public.project_quotes current_quote
    on current_quote.organization_id = series.organization_id and current_quote.id = series.current_revision_id
  left join public.organization_clients client
    on client.organization_id = series.organization_id and client.id = series.recipient_client_id
  where series.organization_id = p_organization_id and series.opportunity_id = p_opportunity_id
    and series.archived_at is null
  order by series.updated_at desc, series.created_at desc;
$$;


ALTER FUNCTION "public"."get_opportunity_quote_register_v1"("p_organization_id" "uuid", "p_opportunity_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_opportunity_quote_revision_history_v1"("p_organization_id" "uuid", "p_opportunity_id" "uuid", "p_revision_id" "uuid") RETURNS TABLE("series_id" "uuid", "base_quote_number" "text", "recipient_client_id" "uuid", "recipient_name" "text", "current_revision_id" "uuid", "revision_id" "uuid", "revision_number" integer, "status" "text", "total_quote_price" numeric, "quote_date" "date", "expiry_date" "date", "updated_at" timestamp with time zone)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  select series.id, series.base_quote_number, series.recipient_client_id,
    coalesce(nullif(client.company_name, ''), client.name, 'Recipient reconciliation required'),
    series.current_revision_id, history.id, history.revision_number, history.status,
    history.total_quote_price, history.quote_date, history.expiry_date, history.updated_at
  from public.project_quotes requested
  join public.opportunity_quote_series series
    on series.organization_id = requested.organization_id and series.id = requested.quote_series_id
  join public.project_quotes history
    on history.organization_id = series.organization_id and history.quote_series_id = series.id
  left join public.organization_clients client
    on client.organization_id = series.organization_id and client.id = series.recipient_client_id
  where requested.organization_id = p_organization_id
    and requested.originating_opportunity_id = p_opportunity_id and requested.id = p_revision_id
  order by history.revision_number desc, history.created_at desc;
$$;


ALTER FUNCTION "public"."get_opportunity_quote_revision_history_v1"("p_organization_id" "uuid", "p_opportunity_id" "uuid", "p_revision_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_opportunity_workspace_continuity_snapshot_v1"("p_organization_id" "uuid", "p_opportunity_id" "uuid", "p_workspace_project_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with
  tasks as (
    select task.id
    from public.project_job_todos task
    where task.organization_id = p_organization_id
      and task.project_id = p_workspace_project_id
      and task.opportunity_id = p_opportunity_id
      and task.deleted_at is null
  ),
  pages as (
    select page.id
    from public.takeoff_pages page
    where page.organization_id = p_organization_id
      and page.project_id = p_workspace_project_id
      and page.opportunity_id = p_opportunity_id
  ),
  calibrations as (
    select calibration.id
    from public.takeoff_calibrations calibration
    join pages page on page.id = calibration.page_id
    where calibration.organization_id = p_organization_id
      and calibration.project_id = p_workspace_project_id
      and calibration.opportunity_id = p_opportunity_id
  ),
  measurements as (
    select measurement.id, measurement.quantity, measurement.count_value
    from public.takeoff_measurements measurement
    join pages page on page.id = measurement.page_id
    where measurement.organization_id = p_organization_id
      and measurement.project_id = p_workspace_project_id
      and measurement.opportunity_id = p_opportunity_id
      and measurement.archived_at is null
  )
  select jsonb_build_object(
    'tasks', jsonb_build_object(
      'ids', coalesce((select jsonb_agg(task.id order by task.id) from tasks task), '[]'::jsonb),
      'count', (select count(*) from tasks),
      'activity_count', (
        select count(*) from public.task_activity_log activity
        join tasks task on task.id = activity.task_id
        where activity.organization_id = p_organization_id
          and activity.project_id = p_workspace_project_id
      ),
      'ownership_valid', not exists (
        select 1 from public.project_job_todos task
        where task.organization_id = p_organization_id
          and task.opportunity_id = p_opportunity_id
          and task.deleted_at is null
          and task.project_id is distinct from p_workspace_project_id
      )
    ),
    'takeoff', jsonb_build_object(
      'page_ids', coalesce((select jsonb_agg(page.id order by page.id) from pages page), '[]'::jsonb),
      'calibration_ids', coalesce((select jsonb_agg(calibration.id order by calibration.id) from calibrations calibration), '[]'::jsonb),
      'measurement_ids', coalesce((select jsonb_agg(measurement.id order by measurement.id) from measurements measurement), '[]'::jsonb),
      'page_count', (select count(*) from pages),
      'calibration_count', (select count(*) from calibrations),
      'measurement_count', (select count(*) from measurements),
      'quantity_total', (select coalesce(sum(measurement.quantity), 0) from measurements measurement),
      'count_total', (select coalesce(sum(measurement.count_value), 0) from measurements measurement),
      'event_count', (
        select count(*) from public.takeoff_measurement_events event
        join measurements measurement on measurement.id = event.measurement_id
        where event.organization_id = p_organization_id
          and event.project_id = p_workspace_project_id
          and event.opportunity_id = p_opportunity_id
      ),
      'ownership_valid', not exists (
        select 1 from public.takeoff_pages page
        where page.organization_id = p_organization_id
          and page.opportunity_id = p_opportunity_id
          and page.project_id is distinct from p_workspace_project_id
      ) and not exists (
        select 1 from public.takeoff_calibrations calibration
        where calibration.organization_id = p_organization_id
          and calibration.opportunity_id = p_opportunity_id
          and calibration.project_id is distinct from p_workspace_project_id
      ) and not exists (
        select 1 from public.takeoff_measurements measurement
        where measurement.organization_id = p_organization_id
          and measurement.opportunity_id = p_opportunity_id
          and measurement.project_id is distinct from p_workspace_project_id
      ),
      'relationships_valid', not exists (
        select 1 from public.takeoff_measurements measurement
        left join public.takeoff_pages page
          on page.id = measurement.page_id
         and page.organization_id = measurement.organization_id
         and page.project_id = measurement.project_id
        left join public.takeoff_calibrations calibration
          on calibration.id = measurement.calibration_id
         and calibration.page_id = measurement.page_id
         and calibration.organization_id = measurement.organization_id
         and calibration.project_id = measurement.project_id
        where measurement.organization_id = p_organization_id
          and measurement.opportunity_id = p_opportunity_id
          and measurement.project_id = p_workspace_project_id
          and (
            page.id is null
            or (measurement.calibration_id is not null and calibration.id is null)
          )
      )
    ),
    'pricing', jsonb_build_object(
      'workbook_ids', coalesce((
        select jsonb_agg(workbook.id order by workbook.id)
        from public.opportunity_pricing_worksheets workbook
        where workbook.organization_id = p_organization_id
          and workbook.opportunity_id = p_opportunity_id
          and workbook.archived_at is null
      ), '[]'::jsonb),
      'workbook_count', (
        select count(*) from public.opportunity_pricing_worksheets workbook
        where workbook.organization_id = p_organization_id
          and workbook.opportunity_id = p_opportunity_id
          and workbook.archived_at is null
      ),
      'ownership_valid', not exists (
        select 1 from public.opportunity_pricing_worksheets workbook
        where workbook.organization_id = p_organization_id
          and workbook.opportunity_id = p_opportunity_id
          and workbook.archived_at is null
          and workbook.project_id is not null
          and workbook.project_id is distinct from p_workspace_project_id
      )
    )
  );
$$;


ALTER FUNCTION "public"."get_opportunity_workspace_continuity_snapshot_v1"("p_organization_id" "uuid", "p_opportunity_id" "uuid", "p_workspace_project_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_or_create_opportunity_document_workspace"("p_opportunity_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  actor_user_id uuid := auth.uid();
  opportunity_row public.organization_opportunities%rowtype;
  workspace_row public.document_workspaces%rowtype;
  entity_link_row public.document_workspace_entities%rowtype;
begin
  if actor_user_id is null then
    raise exception 'Authentication required.' using errcode = '42501';
  end if;

  select * into opportunity_row
  from public.organization_opportunities opportunity
  where opportunity.id = p_opportunity_id
  for key share;

  if not found
    or not public.has_org_permission(opportunity_row.organization_id, 'files.view')
  then
    raise exception 'Opportunity not found or access denied.' using errcode = '42501';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended('document-opportunity:' || opportunity_row.id::text, 0)
  );

  select workspace.* into workspace_row
  from public.document_workspace_entities entity_link
  join public.document_workspaces workspace
    on workspace.organization_id = entity_link.organization_id
   and workspace.id = entity_link.workspace_id
  where entity_link.opportunity_id = opportunity_row.id;

  if found then
    return workspace_row.id;
  end if;

  if not public.has_org_permission(opportunity_row.organization_id, 'files.write') then
    raise exception 'Opportunity document workspace creation is not authorized.'
      using errcode = '42501';
  end if;

  insert into public.document_workspaces (organization_id, created_by, updated_by)
  values (opportunity_row.organization_id, actor_user_id, actor_user_id)
  returning * into workspace_row;

  insert into public.document_workspace_entities (
    organization_id, workspace_id, opportunity_id, linked_by
  ) values (
    opportunity_row.organization_id, workspace_row.id, opportunity_row.id, actor_user_id
  ) returning * into entity_link_row;

  insert into public.document_activity_events (
    organization_id, workspace_id, entity_link_id, actor_user_id, event_type, metadata
  ) values
    (
      opportunity_row.organization_id, workspace_row.id, entity_link_row.id,
      actor_user_id, 'workspace_created', jsonb_build_object('source', 'opportunity')
    ),
    (
      opportunity_row.organization_id, workspace_row.id, entity_link_row.id,
      actor_user_id, 'opportunity_linked',
      jsonb_build_object('opportunityId', opportunity_row.id)
    );

  return workspace_row.id;
end;
$$;


ALTER FUNCTION "public"."get_or_create_opportunity_document_workspace"("p_opportunity_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_or_create_project_document_workspace"("p_project_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  actor_user_id uuid := auth.uid();
  project_row public.organization_projects%rowtype;
  workspace_row public.document_workspaces%rowtype;
  entity_link_row public.document_workspace_entities%rowtype;
  workspace_id uuid;
begin
  if actor_user_id is null then
    raise exception 'Authentication required.'
      using errcode = '42501';
  end if;

  select *
  into project_row
  from public.organization_projects project
  where project.id = p_project_id
  for key share;

  if not found
    or not public.has_org_permission(project_row.organization_id, 'files.view')
  then
    raise exception 'Project not found or access denied.'
      using errcode = '42501';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended('document-project:' || project_row.id::text, 0)
  );

  select entity_link.workspace_id
  into workspace_id
  from public.document_workspace_entities entity_link
  where entity_link.project_id = project_row.id;

  if found then
    return workspace_id;
  end if;

  if not public.has_org_permission(project_row.organization_id, 'files.write') then
    raise exception 'Project document workspace creation is not authorized.'
      using errcode = '42501';
  end if;

  if project_row.source_opportunity_id is not null then
    workspace_id := public.get_or_create_opportunity_document_workspace(
      project_row.source_opportunity_id
    );
    return public.link_project_to_opportunity_document_workspace(
      project_row.source_opportunity_id,
      project_row.id
    );
  end if;

  insert into public.document_workspaces (
    organization_id,
    created_by,
    updated_by
  )
  values (
    project_row.organization_id,
    actor_user_id,
    actor_user_id
  )
  returning * into workspace_row;

  insert into public.document_workspace_entities (
    organization_id,
    workspace_id,
    project_id,
    linked_by
  )
  values (
    project_row.organization_id,
    workspace_row.id,
    project_row.id,
    actor_user_id
  )
  returning * into entity_link_row;

  insert into public.document_activity_events (
    organization_id,
    workspace_id,
    entity_link_id,
    actor_user_id,
    event_type,
    metadata
  )
  values
    (
      project_row.organization_id,
      workspace_row.id,
      entity_link_row.id,
      actor_user_id,
      'workspace_created',
      jsonb_build_object('source', 'project')
    ),
    (
      project_row.organization_id,
      workspace_row.id,
      entity_link_row.id,
      actor_user_id,
      'project_linked',
      jsonb_build_object('projectId', project_row.id)
    );

  return workspace_row.id;
end;
$$;


ALTER FUNCTION "public"."get_or_create_project_document_workspace"("p_project_id" "uuid") OWNER TO "postgres";


