CREATE OR REPLACE FUNCTION "public"."get_organization_memory_context"("p_input" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  resolved_organization_id uuid;
  resolved_project_id uuid;
  resolved_opportunity_id uuid;
  resolved_limit integer := 50;
  resolved_categories text[];
  resolved_types text[];
  result jsonb;
begin
  if p_input is null or jsonb_typeof(p_input) <> 'object' then
    raise exception 'get_organization_memory_context requires a JSON object payload';
  end if;

  perform public._organization_memory_assert_platform_admin('viewer');

  resolved_organization_id := nullif(p_input->>'organizationId', '')::uuid;
  resolved_project_id := nullif(p_input->>'projectId', '')::uuid;
  resolved_opportunity_id := nullif(p_input->>'opportunityId', '')::uuid;
  resolved_limit := greatest(coalesce(nullif(p_input->>'limit', '')::integer, 50), 1);

  perform public._organization_memory_assert_organization_exists(resolved_organization_id);

  select array_agg(value)
  into resolved_categories
  from jsonb_array_elements_text(coalesce(p_input->'memoryCategories', '[]'::jsonb)) as value;

  select array_agg(value)
  into resolved_types
  from jsonb_array_elements_text(coalesce(p_input->'memoryTypes', '[]'::jsonb)) as value;

  select jsonb_build_object(
    'organizationId', resolved_organization_id,
    'projectId', resolved_project_id,
    'opportunityId', resolved_opportunity_id,
    'generatedAt', now(),
    'items', coalesce(
      jsonb_agg(
        jsonb_build_object(
          'id', m.id,
          'memoryCategory', m.memory_category,
          'memoryType', m.memory_type,
          'memoryKey', m.memory_key,
          'title', m.title,
          'summary', m.summary,
          'memoryValue', m.memory_value,
          'evidenceSummary', m.evidence_summary,
          'confidenceScore', m.confidence_score,
          'derivedFromTotalCount', m.derived_from_total_count,
          'reinforcementCount', m.reinforcement_count,
          'contradictionCount', m.contradiction_count,
          'isUserConfirmed', m.is_user_confirmed,
          'lastDerivedAt', m.last_derived_at,
          'updatedAt', m.updated_at
        )
        order by m.confidence_score desc, m.updated_at desc
      ),
      '[]'::jsonb
    )
  )
  into result
  from (
    select *
    from public.organization_memory_items omi
    where omi.organization_id = resolved_organization_id
      and omi.is_active
      and (
        resolved_categories is null
        or cardinality(resolved_categories) = 0
        or omi.memory_category = any (resolved_categories)
      )
      and (
        resolved_types is null
        or cardinality(resolved_types) = 0
        or omi.memory_type = any (resolved_types)
      )
      and (
        resolved_project_id is null
        or (omi.memory_value->>'projectId') is null
        or (omi.memory_value->>'projectId') = resolved_project_id::text
      )
      and (
        resolved_opportunity_id is null
        or (omi.memory_value->>'opportunityId') is null
        or (omi.memory_value->>'opportunityId') = resolved_opportunity_id::text
      )
    order by omi.confidence_score desc, omi.updated_at desc
    limit resolved_limit
  ) as m;

  return result;
end;
$$;


ALTER FUNCTION "public"."get_organization_memory_context"("p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_organization_permissions_batch"("p_organization_id" "uuid", "p_permission_keys" "text"[]) RETURNS TABLE("permission_key" "text", "is_allowed" boolean)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select requested.permission_key,
         public.has_org_permission(
           p_organization_id,
           requested.permission_key
         ) as is_allowed
  from (
    select distinct nullif(trim(value), '') as permission_key
    from unnest(coalesce(p_permission_keys, array[]::text[])) as value
  ) requested
  where requested.permission_key is not null
  order by requested.permission_key;
$$;


ALTER FUNCTION "public"."get_organization_permissions_batch"("p_organization_id" "uuid", "p_permission_keys" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_organization_retention_capability"() RETURNS TABLE("organization_id" "uuid", "capability_key" "text", "enabled" boolean, "enabled_by" "uuid", "enabled_at" timestamp with time zone, "disabled_by" "uuid", "disabled_at" timestamp with time zone, "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_organization_id uuid;
begin
  if auth.uid() is null then
    return;
  end if;

  select member.organization_id
  into v_organization_id
  from public.organization_members member
  where member.user_id = auth.uid()
  order by member.created_at, member.id
  limit 1;

  if v_organization_id is null
    or not public.has_org_permission(v_organization_id, 'retention.view') then
    return;
  end if;

  return query
  select
    capability.organization_id,
    capability.capability_key,
    capability.enabled,
    capability.enabled_by,
    capability.enabled_at,
    capability.disabled_by,
    capability.disabled_at,
    capability.created_at,
    capability.updated_at
  from public.organization_capabilities capability
  where capability.organization_id = v_organization_id
    and capability.capability_key = 'retention_management';
end;
$$;


ALTER FUNCTION "public"."get_organization_retention_capability"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_payment_claim_accounting_update_execution"("p_revision_id" "uuid", "p_attempt_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select jsonb_build_object(
    'document', to_jsonb(document),
    'revision', to_jsonb(revision),
    'previousRevision', to_jsonb(previous),
    'lines', coalesce((
      select jsonb_agg(to_jsonb(line) order by line.sequence)
      from public.organization_accounting_revision_lines line
      where line.accounting_revision_id = revision.id
    ), '[]'::jsonb),
    'attempt', to_jsonb(attempt)
  )
  from public.organization_accounting_document_revisions revision
  join public.organization_accounting_documents document
    on document.id = revision.accounting_document_id
   and document.organization_id = revision.organization_id
  join public.organization_accounting_revision_attempts attempt
    on attempt.id = p_attempt_id
   and attempt.accounting_revision_id = revision.id
  join public.organization_accounting_document_revisions previous
    on previous.id = revision.previous_revision_id
  where revision.id = p_revision_id
    and revision.source_document_type = 'project_claim'
    and document.integration_contract = 'payment_claim_revision_v1';
$$;


ALTER FUNCTION "public"."get_payment_claim_accounting_update_execution"("p_revision_id" "uuid", "p_attempt_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_payment_claim_initial_push_execution_phase2b"("p_revision_id" "uuid", "p_attempt_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select jsonb_build_object(
    'document', to_jsonb(d),
    'revision', to_jsonb(r),
    'lines', coalesce((
      select jsonb_agg(to_jsonb(l) order by l.sequence)
      from public.organization_accounting_revision_lines l
      where l.accounting_revision_id = r.id
    ), '[]'::jsonb),
    'attachment', to_jsonb(a),
    'pdfBase64', encode(b.content_bytes, 'base64'),
    'attempt', to_jsonb(at)
  )
  from public.organization_accounting_document_revisions r
  join public.organization_accounting_documents d on d.id = r.accounting_document_id
  join public.organization_accounting_revision_attempts at
    on at.id = p_attempt_id and at.accounting_revision_id = r.id
  join public.organization_accounting_revision_attachments a
    on a.accounting_revision_id = r.id and a.attachment_sequence = 1
  join public.organization_accounting_revision_blobs b
    on b.accounting_revision_id = r.id and b.attachment_id = a.id
  where r.id = p_revision_id
    and d.integration_contract = 'payment_claim_revision_v1';
$$;


ALTER FUNCTION "public"."get_payment_claim_initial_push_execution_phase2b"("p_revision_id" "uuid", "p_attempt_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_payment_claim_phase2b_health"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
  with expected_functions(name) as (
    values
      ('confirm_payment_claim_initial_push_phase2b'),
      ('confirm_payment_claim_initial_push_phase2b_impl'),
      ('claim_accounting_revision_attempt_phase2b'),
      ('get_payment_claim_initial_push_execution_phase2b'),
      ('complete_payment_claim_initial_push_phase2b'),
      ('record_payment_claim_initial_push_observation_phase2b')
  )
  select jsonb_build_object(
    'migrationCounts', jsonb_build_object(
      'foundation', (select count(*) from supabase_migrations.schema_migrations where version = '20260726100000'),
      'nameCorrection', (select count(*) from supabase_migrations.schema_migrations where version = '20260726110000'),
      'compatibilityCorrection', (select count(*) from supabase_migrations.schema_migrations where version = '20260726120000')
    ),
    'tables', jsonb_build_object(
      'settings', to_regclass('public.organization_accounting_phase2b_settings') is not null,
      'blobs', to_regclass('public.organization_accounting_revision_blobs') is not null
    ),
    'functions', (
      select jsonb_agg(jsonb_build_object(
        'name', e.name,
        'exists', p.oid is not null,
        'securityDefiner', coalesce(p.prosecdef, false),
        'searchPath', p.proconfig,
        'publicExecute', coalesce(has_function_privilege('public', p.oid, 'EXECUTE'), false),
        'authenticatedExecute', coalesce(has_function_privilege('authenticated', p.oid, 'EXECUTE'), false),
        'serviceExecute', coalesce(has_function_privilege('service_role', p.oid, 'EXECUTE'), false)
      ) order by e.name)
      from expected_functions e
      left join pg_proc p on p.proname = e.name and p.pronamespace = 'public'::regnamespace
    ),
    'jobConstraint', (
      select pg_get_constraintdef(c.oid)
      from pg_constraint c
      where c.conrelid = 'public.organization_accounting_sync_jobs'::regclass
        and c.conname = 'organization_accounting_sync_jobs_job_kind_check'
    ),
    'indexes', (
      select jsonb_agg(jsonb_build_object(
        'name', c.relname, 'valid', i.indisvalid, 'ready', i.indisready
      ) order by c.relname)
      from pg_index i
      join pg_class c on c.oid = i.indexrelid
      where c.relname in (
        'organization_accounting_revision_blobs_pkey',
        'organization_accounting_sync_jobs_active_phase2b_revision_uidx'
      )
    ),
    'rollout', jsonb_build_object(
      'enabledOrganizations', (
        select count(*) from public.organization_accounting_phase2b_settings
        where initial_payment_claim_push_enabled
      ),
      'revisionBackedDocuments', (
        select count(*) from public.organization_accounting_documents
        where integration_contract = 'payment_claim_revision_v1'
      ),
      'revisionBlobs', (select count(*) from public.organization_accounting_revision_blobs),
      'phase2bJobs', (
        select count(*) from public.organization_accounting_sync_jobs
        where job_kind in (
          'xero.payment_claim.initial_push',
          'xero.payment_claim.initial_push.attachment'
        )
      )
    )
  );
$$;


ALTER FUNCTION "public"."get_payment_claim_phase2b_health"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_phase2a_function_security_health"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'name', p.proname,
        'arguments', pg_catalog.pg_get_function_identity_arguments(p.oid),
        'securityDefiner', p.prosecdef,
        'configuration', p.proconfig,
        'acl', p.proacl::text,
        'publicExecute', pg_catalog.acldefault('f', p.proowner)
          <@ coalesce(p.proacl, pg_catalog.acldefault('f', p.proowner))
      )
      order by p.proname, pg_catalog.pg_get_function_identity_arguments(p.oid)
    ),
    '[]'::jsonb
  )
  from pg_catalog.pg_proc p
  where p.pronamespace = 'public'::regnamespace
    and p.proname like '%phase2a%';
$$;


ALTER FUNCTION "public"."get_phase2a_function_security_health"() OWNER TO "postgres";


