CREATE OR REPLACE FUNCTION "public"."get_project_claim_source_line_items"("p_organization_id" "uuid", "p_project_id" "uuid") RETURNS TABLE("source_kind" "text", "source_document_id" "uuid", "source_line_item_id" "uuid", "source_number" "text", "source_title" "text", "section" "text", "description" "text", "quantity" numeric, "unit" "text", "rate" numeric, "source_total" numeric, "sort_order" integer)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with base_quote as (
    select q.id, q.quote_number, q.quote_title
    from public.project_quotes q
    where q.organization_id = p_organization_id
      and q.project_id = p_project_id
    order by
      case
        when q.status = 'Accepted' then 0
        when q.status = 'Sent' then 1
        else 2
      end,
      q.updated_at desc
    limit 1
  ),
  quote_lines as (
    select
      'Quote'::text as source_kind,
      bq.id as source_document_id,
      li.id as source_line_item_id,
      bq.quote_number as source_number,
      bq.quote_title as source_title,
      li.section,
      li.description,
      li.quantity,
      li.unit,
      li.rate,
      coalesce(li.total, round(li.quantity * li.rate, 2)) as source_total,
      li.sort_order as sort_order
    from base_quote bq
    join public.project_quote_line_items li
      on li.organization_id = p_organization_id
     and li.project_id = p_project_id
     and li.quote_id = bq.id
    where coalesce(li.is_optional, false) = false
  ),
  variation_rows as (
    select
      'Variation'::text as source_kind,
      v.id as source_document_id,
      v.id as source_line_item_id,
      v.variation_number as source_number,
      v.variation_title as source_title,
      'Item'::text as section,
      coalesce(nullif(v.variation_title, ''), v.variation_number, 'Variation') as description,
      1::numeric as quantity,
      'Item'::text as unit,
      public.calculate_project_variation_pre_gst_total(
        v.subtotal,
        v.margin_percent,
        v.discount_amount,
        v.contingency_amount
      ) as rate,
      public.calculate_project_variation_pre_gst_total(
        v.subtotal,
        v.margin_percent,
        v.discount_amount,
        v.contingency_amount
      ) as source_total,
      (100000 + row_number() over (order by v.created_at, v.updated_at, v.variation_number, v.id))::integer as sort_order
    from public.project_variations v
    where v.organization_id = p_organization_id
      and v.project_id = p_project_id
      and v.status = 'Approved'
  )
  select * from quote_lines
  union all
  select * from variation_rows
  order by sort_order;
$$;


ALTER FUNCTION "public"."get_project_claim_source_line_items"("p_organization_id" "uuid", "p_project_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_project_dashboard_aggregate"("p_organization_id" "uuid", "p_project_slug" "text", "p_now" timestamp with time zone, "p_today" "date", "p_start_of_day" timestamp with time zone, "p_end_of_day" timestamp with time zone, "p_month_start" "date", "p_month_end" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_result jsonb;
  v_project_id uuid;
  v_claims_paid numeric := 0;
  v_claims_unpaid numeric := 0;
begin
  v_result := public.get_project_dashboard_aggregate_before_xero_claim_payment(
    p_organization_id,
    p_project_slug,
    p_now,
    p_today,
    p_start_of_day,
    p_end_of_day,
    p_month_start,
    p_month_end
  );

  select p.id into v_project_id
  from public.organization_projects p
  where p.organization_id = p_organization_id
    and p.slug = p_project_slug;

  select
    coalesce(sum(c.paid_amount) filter (
      where c.status in ('Submitted', 'Unpaid', 'Paid', 'Overdue')
    ), 0),
    coalesce(sum(greatest(c.claim_amount - c.paid_amount, 0)) filter (
      where c.status in ('Submitted', 'Unpaid', 'Overdue')
    ), 0)
  into v_claims_paid, v_claims_unpaid
  from public.project_claims c
  where c.organization_id = p_organization_id
    and c.project_id = v_project_id;

  v_result := jsonb_set(v_result, '{financials,claimsPaidAmount}', to_jsonb(v_claims_paid), true);
  v_result := jsonb_set(v_result, '{financials,claimsUnpaidAmount}', to_jsonb(v_claims_unpaid), true);
  return v_result;
end;
$$;


ALTER FUNCTION "public"."get_project_dashboard_aggregate"("p_organization_id" "uuid", "p_project_slug" "text", "p_now" timestamp with time zone, "p_today" "date", "p_start_of_day" timestamp with time zone, "p_end_of_day" timestamp with time zone, "p_month_start" "date", "p_month_end" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_project_dashboard_aggregate_before_xero_claim_payment"("p_organization_id" "uuid", "p_project_slug" "text", "p_now" timestamp with time zone, "p_today" "date", "p_start_of_day" timestamp with time zone, "p_end_of_day" timestamp with time zone, "p_month_start" "date", "p_month_end" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_project record;
  v_result jsonb;
begin
  if auth.uid() is null or not public.is_member_of_organization(p_organization_id) then
    raise exception 'Not authorized';
  end if;

  select
    p.id,
    p.name,
    p.stage,
    p.location,
    p.created_at,
    coalesce(c.name, 'Unassigned') as client_name
  into v_project
  from public.organization_projects p
  left join public.organization_clients c
    on c.id = p.client_id
   and c.organization_id = p.organization_id
  where p.organization_id = p_organization_id
    and p.slug = p_project_slug;

  if v_project.id is null then
    raise exception 'Project not found';
  end if;

  with
  todo_rows as (
    select id, title, status, due_at, due_date, updated_at
    from public.project_job_todos
    where organization_id = p_organization_id
      and project_id = v_project.id
      and status <> 'Done'
      and status <> 'Archived'
  ),
  issue_rows as (
    select id, title, status, updated_at
    from public.project_quality_issues
    where organization_id = p_organization_id
      and project_id = v_project.id
    order by updated_at desc
  ),
  variation_summary_rows as (
    select status, total_variation_price
    from public.project_variations
    where organization_id = p_organization_id
      and project_id = v_project.id
    limit 200
  ),
  variation_feed_rows as (
    select id, variation_number, status, updated_at
    from public.project_variations
    where organization_id = p_organization_id
      and project_id = v_project.id
    order by updated_at desc
    limit 6
  ),
  claim_summary_rows as (
    select status, claim_amount, paid_amount
    from public.project_claims
    where organization_id = p_organization_id
      and project_id = v_project.id
    limit 200
  ),
  claim_feed_rows as (
    select id, claim_number, status, updated_at
    from public.project_claims
    where organization_id = p_organization_id
      and project_id = v_project.id
    order by updated_at desc
    limit 6
  ),
  po_summary_rows as (
    select status, total_purchase_order_price
    from public.project_purchase_orders
    where organization_id = p_organization_id
      and project_id = v_project.id
    limit 200
  ),
  signoff_rows as (
    select id, title, status, updated_at
    from public.project_quality_sign_offs
    where organization_id = p_organization_id
      and project_id = v_project.id
    order by updated_at desc
    limit 200
  ),
  latest_quote as (
    select total_quote_price
    from public.project_quotes
    where organization_id = p_organization_id
      and project_id = v_project.id
    order by updated_at desc
    limit 1
  ),
  time_event_feed as (
    select id, event_type, message, created_at
    from public.project_time_sheet_events
    where organization_id = p_organization_id
      and project_id = v_project.id
    order by created_at desc
    limit 6
  )
  select jsonb_build_object(
    'project', jsonb_build_object(
      'projectId', v_project.id,
      'projectName', v_project.name,
      'stage', v_project.stage,
      'location', v_project.location,
      'createdAt', v_project.created_at,
      'clientName', v_project.client_name
    ),
    'metrics', jsonb_build_object(
      'overdueTasks', (
        select count(*)
        from todo_rows t
        where (t.due_at is not null and t.due_at < p_now)
           or (t.due_at is null and t.due_date is not null and t.due_date < p_today)
      ),
      'tasksDueToday', (
        select count(*)
        from todo_rows t
        where (t.due_at is not null and t.due_at >= p_start_of_day and t.due_at < p_end_of_day)
           or (t.due_at is null and t.due_date = p_today)
      ),
      'openIssues', (
        select count(*)
        from issue_rows i
        where i.status in ('Open', 'In Progress', 'Blocked', 'Requires Attention')
      ),
      'failedInspections', (
        select count(*)
        from public.project_quality_inspection_items pii
        where pii.organization_id = p_organization_id
          and pii.project_id = v_project.id
          and pii.status = 'fail'
      ),
      'awaitingVariationApproval', (
        select count(*)
        from public.project_variations v
        where v.organization_id = p_organization_id
          and v.project_id = v_project.id
          and v.status in ('Sent', 'Client Review')
      ),
      'pendingVariations', (
        select count(*)
        from public.project_variations v
        where v.organization_id = p_organization_id
          and v.project_id = v_project.id
          and v.status in ('Sent', 'Client Review')
      ),
      'claimReadyToSend', (
        select count(*)
        from public.project_claims c
        where c.organization_id = p_organization_id
          and c.project_id = v_project.id
          and c.status = 'Draft'
          and c.claim_amount > 0
      ),
      'claimsThisMonth', (
        select count(*)
        from public.project_claims c
        where c.organization_id = p_organization_id
          and c.project_id = v_project.id
          and c.claim_date >= p_month_start
          and c.claim_date < p_month_end
      ),
      'activeWorkers', (
        select count(*)
        from public.project_time_sheet_entries e
        where e.organization_id = p_organization_id
          and e.project_id = v_project.id
          and e.clock_in_at is not null
          and e.clock_out_at is null
      ),
      'pendingSignoffs', (
        select count(*)
        from signoff_rows s
        where s.status in ('Pending', 'Requested')
      ),
      'inspectionsToday', (
        select count(*)
        from public.project_quality_inspections i
        where i.organization_id = p_organization_id
          and i.project_id = v_project.id
          and i.scheduled_at >= p_start_of_day
          and i.scheduled_at < p_end_of_day
      )
    ),
    'financials', jsonb_build_object(
      'quoteValue', coalesce((select total_quote_price from latest_quote), 0),
      'variationTotal', (
        select coalesce(sum(coalesce(v.total_variation_price, 0)), 0)
        from variation_summary_rows v
      ),
      'claimsSubmitted', (
        select count(*)
        from claim_summary_rows c
        where c.status in ('Submitted', 'Unpaid', 'Paid', 'Overdue')
      ),
      'claimsPaidAmount', (
        select coalesce(sum(coalesce(c.paid_amount, 0)), 0)
        from claim_summary_rows c
      ),
      'claimsUnpaidAmount', (
        select coalesce(sum(greatest(coalesce(c.claim_amount, 0) - coalesce(c.paid_amount, 0), 0)), 0)
        from claim_summary_rows c
      ),
      'poOutstandingCount', (
        select count(*)
        from po_summary_rows p
        where p.status not in ('Invoiced', 'Cancelled', 'Received')
      ),
      'poOutstandingAmount', (
        select coalesce(sum(coalesce(p.total_purchase_order_price, 0)), 0)
        from po_summary_rows p
        where p.status not in ('Invoiced', 'Cancelled', 'Received')
      )
    ),
    'feeds', jsonb_build_object(
      'tasks', (
        select coalesce(
          jsonb_agg(jsonb_build_object(
            'id', t.id,
            'title', t.title,
            'status', t.status,
            'updated_at', t.updated_at
          ) order by t.updated_at desc),
          '[]'::jsonb
        )
        from (
          select id, title, status, updated_at
          from todo_rows
          order by updated_at desc
          limit 6
        ) t
      ),
      'issues', (
        select coalesce(
          jsonb_agg(jsonb_build_object(
            'id', i.id,
            'title', i.title,
            'status', i.status,
            'updated_at', i.updated_at
          ) order by i.updated_at desc),
          '[]'::jsonb
        )
        from (
          select id, title, status, updated_at
          from issue_rows
          limit 6
        ) i
      ),
      'variations', (
        select coalesce(
          jsonb_agg(jsonb_build_object(
            'id', v.id,
            'variation_number', v.variation_number,
            'status', v.status,
            'updated_at', v.updated_at
          ) order by v.updated_at desc),
          '[]'::jsonb
        )
        from variation_feed_rows v
      ),
      'claims', (
        select coalesce(
          jsonb_agg(jsonb_build_object(
            'id', c.id,
            'claim_number', c.claim_number,
            'status', c.status,
            'updated_at', c.updated_at
          ) order by c.updated_at desc),
          '[]'::jsonb
        )
        from claim_feed_rows c
      ),
      'time_events', (
        select coalesce(
          jsonb_agg(jsonb_build_object(
            'id', e.id,
            'event_type', e.event_type,
            'message', e.message,
            'created_at', e.created_at
          ) order by e.created_at desc),
          '[]'::jsonb
        )
        from time_event_feed e
      ),
      'signoffs', (
        select coalesce(
          jsonb_agg(jsonb_build_object(
            'id', s.id,
            'title', s.title,
            'status', s.status,
            'updated_at', s.updated_at
          ) order by s.updated_at desc),
          '[]'::jsonb
        )
        from (
          select id, title, status, updated_at
          from signoff_rows
          limit 6
        ) s
      )
    )
  ) into v_result;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."get_project_dashboard_aggregate_before_xero_claim_payment"("p_organization_id" "uuid", "p_project_slug" "text", "p_now" timestamp with time zone, "p_today" "date", "p_start_of_day" timestamp with time zone, "p_end_of_day" timestamp with time zone, "p_month_start" "date", "p_month_end" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_project_purchase_order_mobile_edit_snapshot_v2"("p_project_id" "uuid", "p_purchase_order_id" "uuid") RETURNS TABLE("purchase_order_id" "uuid", "project_id" "uuid", "updated_at" timestamp with time zone, "invoice_risk" "jsonb", "lines" "jsonb")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
declare
  current_context record;
  po_row public.project_purchase_orders%rowtype;
  has_invoice_matches boolean := false;
  has_blocking_matches boolean := false;
  has_accepted_or_adjusted_matches boolean := false;
  has_approved_or_disputed_matches boolean := false;
  match_count integer := 0;
begin
  select *
  into current_context
  from public.resolve_mobile_project_member_context_v2(p_project_id);

  if not public.has_org_permission(current_context.organization_id, 'purchase_orders.write') then
    raise exception 'Not authorized to edit purchase orders for this organization';
  end if;

  select *
  into po_row
  from public.project_purchase_orders po
  where po.organization_id = current_context.organization_id
    and po.project_id = p_project_id
    and po.id = p_purchase_order_id;

  if not found then
    raise exception 'Purchase order not found for this project';
  end if;

  select
    count(*)::integer,
    count(*) > 0,
    count(*) filter (where m.match_status in ('accepted', 'adjusted')) > 0,
    count(*) filter (where m.approval_status in ('approved', 'disputed')) > 0
  into
    match_count,
    has_invoice_matches,
    has_accepted_or_adjusted_matches,
    has_approved_or_disputed_matches
  from public.supplier_invoice_purchase_order_matches m
  where m.organization_id = current_context.organization_id
    and m.purchase_order_id = p_purchase_order_id;

  has_blocking_matches := has_invoice_matches;

  return query
  select
    po_row.id as purchase_order_id,
    po_row.project_id,
    po_row.updated_at,
    jsonb_build_object(
      'has_matches', has_invoice_matches,
      'has_blocking_matches', has_blocking_matches,
      'has_accepted_or_adjusted_matches', has_accepted_or_adjusted_matches,
      'has_approved_or_disputed_matches', has_approved_or_disputed_matches,
      'match_count', match_count
    ) as invoice_risk,
    coalesce(
      (
        select jsonb_agg(
          jsonb_build_object(
            'id', li.id,
            'section', li.section,
            'description', li.description,
            'quantity', li.quantity,
            'unit', li.unit,
            'rate', li.rate,
            'total', li.total,
            'sort_order', li.sort_order,
            'is_editable', case
              when li.source_time_sheet_entry_id is not null then false
              when has_blocking_matches then false
              else true
            end,
            'is_deletable', case
              when li.source_time_sheet_entry_id is not null then false
              when has_blocking_matches then false
              else true
            end,
            'lock_reason', case
              when li.source_time_sheet_entry_id is not null then 'timesheet_synced'
              when has_blocking_matches then 'supplier_invoice_match_risk'
              else null
            end
          )
          order by li.sort_order asc, li.created_at asc
        )
        from public.project_purchase_order_line_items li
        where li.organization_id = current_context.organization_id
          and li.project_id = p_project_id
          and li.purchase_order_id = po_row.id
      ),
      '[]'::jsonb
    ) as lines;
end;
$$;


ALTER FUNCTION "public"."get_project_purchase_order_mobile_edit_snapshot_v2"("p_project_id" "uuid", "p_purchase_order_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_project_purchase_order_summary"("p_organization_id" "uuid", "p_project_id" "uuid") RETURNS TABLE("total_value" numeric, "draft_count" integer, "awaiting_client_count" integer, "approved_count" integer, "invoice_ready_count" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if auth.uid() is null then
    raise exception 'Authentication is required';
  end if;

  if not public.is_member_of_organization(p_organization_id) then
    raise exception 'Not authorized for this organization';
  end if;

  return query
  select
    coalesce(sum(po.total_purchase_order_price), 0)::numeric as total_value,
    count(*) filter (where po.status = 'Draft')::integer as draft_count,
    count(*) filter (where po.status = 'Issued')::integer as awaiting_client_count,
    count(*) filter (where po.status = 'Approved')::integer as approved_count,
    count(*) filter (where po.invoice_ready is true)::integer as invoice_ready_count
  from public.project_purchase_orders po
  where po.organization_id = p_organization_id
    and po.project_id = p_project_id;
end;
$$;


ALTER FUNCTION "public"."get_project_purchase_order_summary"("p_organization_id" "uuid", "p_project_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_project_qa_run_lock_v1"("p_organization_id" "uuid", "p_project_id" "uuid", "p_run_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare result integer;
begin
  if auth.uid() is null or not public.can_access_qa_project(p_organization_id,p_project_id,'qa.inspect') then raise exception 'Not authorized' using errcode='42501'; end if;
  select lock_version into result from public.project_qa_runs where organization_id=p_organization_id and project_id=p_project_id and id=p_run_id;
  if result is null then raise exception 'QA Record not found' using errcode='TS404'; end if;
  return result;
end; $$;


ALTER FUNCTION "public"."get_project_qa_run_lock_v1"("p_organization_id" "uuid", "p_project_id" "uuid", "p_run_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_project_retention_claim_history"("p_project_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  context jsonb;
  can_view_xero boolean := false;
begin
  context := private.retention_claim_operation_context(
    p_project_id,
    'retention.view',
    false
  );
  if not coalesce((context ->> 'succeeded')::boolean, false) then
    return context || jsonb_build_object(
      'xeroVisible', false,
      'claims', '[]'::jsonb
    );
  end if;

  can_view_xero := public.has_org_permission(
    (context ->> 'organizationId')::uuid,
    'retention.claims.xero.view'
  );

  return jsonb_build_object(
    'succeeded', true,
    'errorCode', null,
    'xeroVisible', can_view_xero,
    'claims', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'claim', private.retention_claim_header_json(claim.id),
          'originCount', coalesce(origins.origin_count, 0),
          'paidAmount', coalesce(payment.paid_amount_excl_tax, 0),
          'outstandingAmount',
            greatest(
              claim.subtotal_excl_tax
              - coalesce(payment.paid_amount_excl_tax, 0),
              0
            ),
          'xeroStatus',
            case when can_view_xero then accounting.export_status else null end
        )
        order by claim.created_at desc, claim.id desc
      )
      from public.retention_claims claim
      left join lateral (
        select count(distinct represented.originating_payment_claim_id)
          as origin_count
        from (
          select allocation.originating_payment_claim_id
          from public.retention_claim_allocations allocation
          where allocation.retention_claim_id = claim.id
          union all
          select candidate.originating_payment_claim_id
          from public.retention_rolling_draft_origins candidate
          where candidate.retention_claim_id = claim.id
        ) represented
      ) origins on true
      left join lateral (
        select reconciliation.paid_amount_excl_tax
        from public.retention_claim_payment_reconciliations reconciliation
        where reconciliation.retention_claim_id = claim.id
          and reconciliation.projection_applied
        order by reconciliation.reconciliation_sequence desc
        limit 1
      ) payment on true
      left join lateral (
        select document.export_status
        from public.organization_accounting_documents document
        where can_view_xero
          and document.organization_id = claim.organization_id
          and document.local_document_type = 'retention_claim'
          and document.retention_claim_id = claim.id
        order by document.updated_at desc, document.id desc
        limit 1
      ) accounting on true
      where claim.organization_id = (context ->> 'organizationId')::uuid
        and claim.project_id = p_project_id
        and not (
          claim.status = 'draft'
          and claim.draft_kind = 'automatic_rolling'
        )
    ), '[]'::jsonb)
  );
end;
$$;


ALTER FUNCTION "public"."get_project_retention_claim_history"("p_project_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_project_retention_eligibility"("p_project_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_context jsonb; v_state jsonb;
begin
  v_context:=private.retention_phase4_context(p_project_id,'retention.view',false);
  if not coalesce((v_context->>'succeeded')::boolean,false) then return v_context; end if;
  v_state:=private.retention_eligibility_state(p_project_id);
  return jsonb_build_object('succeeded',true,'errorCode',null)
    || coalesce(v_state,'{}'::jsonb);
end;
$$;


ALTER FUNCTION "public"."get_project_retention_eligibility"("p_project_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_project_retention_position_page"("p_project_id" "uuid", "p_page_size" integer DEFAULT 50, "p_after_claim_date" "date" DEFAULT NULL::"date", "p_after_created_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_after_claim_id" "uuid" DEFAULT NULL::"uuid", "p_statuses" "text"[] DEFAULT NULL::"text"[], "p_positive_retention" boolean DEFAULT NULL::boolean, "p_legacy_release" boolean DEFAULT NULL::boolean, "p_diagnostic_codes" "text"[] DEFAULT NULL::"text"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_actor_user_id uuid := auth.uid();
  v_is_internal boolean :=
    auth.uid() is null and coalesce(auth.role(), '') = 'service_role';
  v_organization_id uuid;
  v_capability_enabled boolean := false;
  v_mode text := 'legacy';
  v_access_state text;
  v_page_size integer := greatest(1, least(coalesce(p_page_size, 50), 200));
  v_result jsonb;
begin
  if p_project_id is null then
    return jsonb_build_object(
      'accessState', 'project_not_found',
      'origins', '[]'::jsonb,
      'hasMore', false
    );
  end if;

  if v_is_internal then
    select project.organization_id
    into v_organization_id
    from public.organization_projects project
    where project.id = p_project_id;
  elsif v_actor_user_id is not null then
    select project.organization_id
    into v_organization_id
    from public.organization_projects project
    join public.organization_members member
      on member.organization_id = project.organization_id
     and member.user_id = v_actor_user_id
    where project.id = p_project_id;
  end if;

  if v_organization_id is null then
    return jsonb_build_object(
      'accessState',
      case
        when v_is_internal then 'project_not_found'
        else 'not_found_or_denied'
      end,
      'origins', '[]'::jsonb,
      'hasMore', false
    );
  end if;

  if not v_is_internal
    and not public.has_org_permission(v_organization_id, 'retention.view') then
    return jsonb_build_object(
      'accessState', 'permission_denied',
      'origins', '[]'::jsonb,
      'hasMore', false
    );
  end if;

  select coalesce(capability.enabled, false)
  into v_capability_enabled
  from public.organization_capabilities capability
  where capability.organization_id = v_organization_id
    and capability.capability_key = 'retention_management';

  select coalesce(state.mode, 'legacy')
  into v_mode
  from public.project_retention_workflow_states state
  where state.organization_id = v_organization_id
    and state.project_id = p_project_id;

  v_access_state := case
    when v_is_internal then 'internal_diagnostics'
    when not v_capability_enabled then 'capability_disabled'
    when v_mode = 'observe' then 'available'
    when v_mode = 'legacy' then 'legacy_mode'
    else 'inactive_mode'
  end;

  if not v_is_internal and (not v_capability_enabled or v_mode <> 'observe') then
    return jsonb_build_object(
      'organizationId', v_organization_id,
      'projectId', p_project_id,
      'capabilityEnabled', v_capability_enabled,
      'workflowMode', v_mode,
      'accessState', v_access_state,
      'origins', '[]'::jsonb,
      'hasMore', false
    );
  end if;

  with ordered_claims as (
    select
      claim.*,
      row_number() over (
        order by
          claim.claim_date asc nulls last,
          claim.created_at asc,
          claim.id asc
      )::integer as chronological_sequence,
      round(
        sum(
          case
            when claim.status <> 'Cancelled'
              then coalesce(claim.retention_withheld_amount, 0)
                   - coalesce(claim.retention_released_amount, 0)
            else 0
          end
        ) over (
          order by
            claim.claim_date asc nulls last,
            claim.created_at asc,
            claim.id asc
          rows between unbounded preceding and current row
        ),
        2
      ) as expected_cumulative_balance
    from public.project_claims claim
    where claim.organization_id = v_organization_id
      and claim.project_id = p_project_id
  ),
  classified_claims as (
    select
      claim.*,
      array_remove(array[
        case
          when claim.retention_balance < 0
            then 'negative_claim_retention_balance'
        end,
        case
          when claim.status <> 'Cancelled'
            and claim.expected_cumulative_balance < 0
            then 'legacy_release_exceeds_held_at_sequence'
        end,
        case
          when round(claim.retention_balance, 2)
            <> claim.expected_cumulative_balance
            then 'cumulative_snapshot_mismatch'
        end,
        case
          when claim.status = 'Cancelled'
            and (
              claim.retention_withheld_amount <> 0
              or claim.retention_released_amount <> 0
            )
            then 'cancelled_claim_has_retention_movement'
        end,
        case
          when claim.claim_date is null then 'missing_claim_date'
        end,
        case
          when claim.status not in (
            'Draft', 'Submitted', 'Unpaid', 'Paid', 'Overdue', 'Cancelled'
          ) then 'unexpected_claim_status'
        end,
        case
          when claim.retention_percent is null
            or claim.retention_withheld_amount is null
            or claim.retention_released_amount is null
            or claim.retention_held_to_date is null
            or claim.retention_released_to_date is null
            or claim.retention_balance is null
            or claim.claim_amount is null
            or claim.net_claim_excl_gst is null
            or claim.gst_amount is null
            or claim.total_payable is null
            then 'unexpected_null_financial_field'
        end
      ], null)::text[] as diagnostic_codes
    from ordered_claims claim
  ),
  filtered_claims as (
    select claim.*
    from classified_claims claim
    where
      (
        p_statuses is null
        or cardinality(p_statuses) = 0
        or claim.status = any(p_statuses)
      )
      and (
        p_positive_retention is null
        or (claim.retention_withheld_amount > 0) = p_positive_retention
      )
      and (
        p_legacy_release is null
        or (claim.retention_released_amount <> 0) = p_legacy_release
      )
      and (
        p_diagnostic_codes is null
        or cardinality(p_diagnostic_codes) = 0
        or claim.diagnostic_codes && p_diagnostic_codes
      )
      and (
        p_after_claim_id is null
        or (
          p_after_claim_date is not null
          and (
            claim.claim_date > p_after_claim_date
            or claim.claim_date is null
            or (
              claim.claim_date = p_after_claim_date
              and (
                claim.created_at > p_after_created_at
                or (
                  claim.created_at = p_after_created_at
                  and claim.id > p_after_claim_id
                )
              )
            )
          )
        )
        or (
          p_after_claim_date is null
          and claim.claim_date is null
          and (
            claim.created_at > p_after_created_at
            or (
              claim.created_at = p_after_created_at
              and claim.id > p_after_claim_id
            )
          )
        )
      )
    order by
      claim.claim_date asc nulls last,
      claim.created_at asc,
      claim.id asc
    limit v_page_size + 1
  ),
  page_rows as (
    select *
    from filtered_claims
    order by
      claim_date asc nulls last,
      created_at asc,
      id asc
    limit v_page_size
  ),
  page_metadata as (
    select
      (select count(*) > v_page_size from filtered_claims) as has_more,
      (
        select jsonb_build_object(
          'claimDate', last_row.claim_date,
          'createdAt', last_row.created_at,
          'paymentClaimId', last_row.id
        )
        from (
          select *
          from page_rows
          order by
            claim_date desc nulls first,
            created_at desc,
            id desc
          limit 1
        ) last_row
      ) as next_cursor
  )
  select jsonb_build_object(
    'organizationId', v_organization_id,
    'projectId', p_project_id,
    'capabilityEnabled', v_capability_enabled,
    'workflowMode', v_mode,
    'accessState', v_access_state,
    'pageSize', v_page_size,
    'hasMore', page_metadata.has_more,
    'nextCursor',
      case when page_metadata.has_more then page_metadata.next_cursor else null end,
    'origins',
      coalesce(
        (
          select jsonb_agg(
            jsonb_build_object(
              'organizationId', claim.organization_id,
              'projectId', claim.project_id,
              'paymentClaimId', claim.id,
              'claimNumber', claim.claim_number,
              'claimDate', claim.claim_date,
              'dueDate', claim.due_date,
              'status', claim.status,
              'createdAt', claim.created_at,
              'updatedAt', claim.updated_at,
              'chronologicalSequence', claim.chronological_sequence,
              'retentionMethod', claim.retention_method,
              'retentionRate', claim.retention_percent,
              'retentionScaleBands', claim.retention_scale_bands,
              'retentionWithheldAmount', claim.retention_withheld_amount,
              'retentionReleasedAmount', claim.retention_released_amount,
              'retentionHeldToDate', claim.retention_held_to_date,
              'retentionReleasedToDate', claim.retention_released_to_date,
              'retentionBalance', claim.retention_balance,
              'grossClaimAmount', claim.claim_amount,
              'netClaimExcludingGst', claim.net_claim_excl_gst,
              'gstAmount', claim.gst_amount,
              'totalPayable', claim.total_payable,
              'originatedPositiveRetention',
                claim.retention_withheld_amount > 0,
              'originatedRetentionAmount',
                greatest(claim.retention_withheld_amount, 0),
              'cancelled', claim.status = 'Cancelled',
              'containsLegacyRelease',
                claim.retention_released_amount <> 0,
              'negativeRetentionBalance',
                claim.retention_balance < 0,
              'internallyInconsistent',
                cardinality(claim.diagnostic_codes) > 0,
              'eligibleForFutureRetentionAnalysis',
                v_capability_enabled
                and v_mode = 'observe'
                and claim.status <> 'Cancelled'
                and claim.retention_withheld_amount > 0,
              'movementDerivedCumulativeBalance',
                claim.expected_cumulative_balance,
              'diagnostics',
                coalesce(
                  (
                    select jsonb_agg(
                      jsonb_build_object(
                        'code', code,
                        'severity',
                          case
                            when code in (
                              'negative_claim_retention_balance',
                              'legacy_release_exceeds_held_at_sequence',
                              'cumulative_snapshot_mismatch',
                              'unexpected_claim_status',
                              'unexpected_null_financial_field'
                            ) then 'blocking_for_future_cutover'
                            when code = 'cancelled_claim_has_retention_movement'
                              then 'warning'
                            else 'info'
                          end
                      )
                      order by code
                    )
                    from unnest(claim.diagnostic_codes) code
                  ),
                  '[]'::jsonb
                )
            )
            order by claim.chronological_sequence
          )
          from page_rows claim
        ),
        '[]'::jsonb
      )
  )
  into v_result
  from page_metadata;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."get_project_retention_position_page"("p_project_id" "uuid", "p_page_size" integer, "p_after_claim_date" "date", "p_after_created_at" timestamp with time zone, "p_after_claim_id" "uuid", "p_statuses" "text"[], "p_positive_retention" boolean, "p_legacy_release" boolean, "p_diagnostic_codes" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_project_retention_position_summary"("p_project_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare raw jsonb; current_case public.retention_legacy_reconciliation_cases%rowtype;
  reconciled boolean:=false; reconciliation_state text:='not_required';
begin
  raw:=private.retention_legacy_source_state(p_project_id);
  if not coalesce((raw->>'legacyReconciliationRequired')::boolean,false) then
    return raw||jsonb_build_object(
      'legacyReconciliationRequired',false,
      'legacyReconciliationState','not_required',
      'legacyReconciliationCaseId',null,
      'legacyReconciledAmount',0
    );
  end if;
  select * into current_case
  from public.retention_legacy_reconciliation_cases c
  where c.project_id=p_project_id
    and c.status in ('draft','in_review','approved')
  order by c.case_sequence desc limit 1;
  if current_case.id is not null then
    reconciled:=current_case.status='approved'
      and current_case.position_state_hash=raw->>'stateHash'
      and current_case.source_fingerprint=raw->>'sourceFingerprint'
      and current_case.total_legacy_released=
        round((raw->>'totalLegacyRetentionReleased')::numeric,2)
      and current_case.total_allocated=current_case.total_legacy_released;
    reconciliation_state:=case
      when reconciled then 'approved'
      when current_case.status='approved' then 'stale'
      else current_case.status end;
  else
    reconciliation_state:='required';
  end if;
  return raw||jsonb_build_object(
    'legacyReconciliationRequired',not reconciled,
    'legacyReconciliationState',reconciliation_state,
    'legacyReconciliationCaseId',current_case.id,
    'legacyReconciledAmount',case when reconciled
      then current_case.total_allocated else 0 end,
    'legacySourceFingerprint',raw->>'sourceFingerprint'
  );
end;
$$;


ALTER FUNCTION "public"."get_project_retention_position_summary"("p_project_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_project_retention_position_summary_phase2_pre_legacy_reconc"("p_project_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
declare
  v_actor_user_id uuid := auth.uid();
  v_is_internal boolean :=
    auth.uid() is null and coalesce(auth.role(), '') = 'service_role';
  v_organization_id uuid;
  v_capability_enabled boolean := false;
  v_mode text := 'legacy';
  v_access_state text;
  v_result jsonb;
begin
  if p_project_id is null then
    return jsonb_build_object(
      'accessState', 'project_not_found',
      'observationEligible', false
    );
  end if;

  if v_is_internal then
    select project.organization_id
    into v_organization_id
    from public.organization_projects project
    where project.id = p_project_id;
  elsif v_actor_user_id is not null then
    select project.organization_id
    into v_organization_id
    from public.organization_projects project
    join public.organization_members member
      on member.organization_id = project.organization_id
     and member.user_id = v_actor_user_id
    where project.id = p_project_id;
  end if;

  if v_organization_id is null then
    return jsonb_build_object(
      'accessState',
      case
        when v_is_internal then 'project_not_found'
        else 'not_found_or_denied'
      end,
      'observationEligible', false
    );
  end if;

  if not v_is_internal
    and not public.has_org_permission(v_organization_id, 'retention.view') then
    return jsonb_build_object(
      'accessState', 'permission_denied',
      'observationEligible', false
    );
  end if;

  select coalesce(capability.enabled, false)
  into v_capability_enabled
  from public.organization_capabilities capability
  where capability.organization_id = v_organization_id
    and capability.capability_key = 'retention_management';

  select coalesce(state.mode, 'legacy')
  into v_mode
  from public.project_retention_workflow_states state
  where state.organization_id = v_organization_id
    and state.project_id = p_project_id;

  v_access_state := case
    when v_is_internal then 'internal_diagnostics'
    when not v_capability_enabled then 'capability_disabled'
    when v_mode = 'observe' then 'available'
    when v_mode = 'legacy' then 'legacy_mode'
    else 'inactive_mode'
  end;

  if not v_is_internal and (not v_capability_enabled or v_mode <> 'observe') then
    return jsonb_build_object(
      'organizationId', v_organization_id,
      'projectId', p_project_id,
      'capabilityEnabled', v_capability_enabled,
      'workflowMode', v_mode,
      'accessState', v_access_state,
      'observationEligible', false
    );
  end if;

  with ordered_claims as (
    select
      claim.*,
      row_number() over (
        order by
          claim.claim_date asc nulls last,
          claim.created_at asc,
          claim.id asc
      )::integer as chronological_sequence,
      round(
        sum(
          case
            when claim.status <> 'Cancelled'
              then coalesce(claim.retention_withheld_amount, 0)
                   - coalesce(claim.retention_released_amount, 0)
            else 0
          end
        ) over (
          order by
            claim.claim_date asc nulls last,
            claim.created_at asc,
            claim.id asc
          rows between unbounded preceding and current row
        ),
        2
      ) as expected_cumulative_balance
    from public.project_claims claim
    where claim.organization_id = v_organization_id
      and claim.project_id = p_project_id
  ),
  aggregate_values as (
    select
      count(*)::integer as payment_claim_count,
      count(*) filter (where status <> 'Cancelled')::integer as active_claim_count,
      count(*) filter (
        where status <> 'Cancelled'
          and coalesce(retention_withheld_amount, 0) > 0
      )::integer as retention_origin_count,
      count(*) filter (
        where status <> 'Cancelled'
          and coalesce(retention_released_amount, 0) <> 0
      )::integer as legacy_release_claim_count,
      count(*) filter (
        where status <> 'Cancelled'
          and coalesce(retention_balance, 0) < 0
      )::integer as negative_retention_balance_claim_count,
      count(*) filter (where status = 'Cancelled')::integer as cancelled_claim_count,
      round(coalesce(sum(coalesce(retention_withheld_amount, 0)) filter (
        where status <> 'Cancelled'
      ), 0), 2) as total_retention_withheld,
      round(coalesce(sum(coalesce(retention_released_amount, 0)) filter (
        where status <> 'Cancelled'
      ), 0), 2) as total_legacy_retention_released,
      round(coalesce(sum(
        coalesce(retention_withheld_amount, 0)
        - coalesce(retention_released_amount, 0)
      ) filter (where status <> 'Cancelled'), 0), 2) as movement_derived_balance,
      max(claim_date) filter (
        where status <> 'Cancelled'
          and (
            coalesce(retention_withheld_amount, 0) <> 0
            or coalesce(retention_released_amount, 0) <> 0
          )
      ) as latest_relevant_claim_date,
      max(updated_at) as latest_persisted_update_at
    from ordered_claims
  ),
  latest_active_snapshot as (
    select retention_balance
    from ordered_claims
    where status <> 'Cancelled'
    order by
      claim_date desc nulls first,
      created_at desc,
      id desc
    limit 1
  ),
  project_diagnostics as (
    select jsonb_agg(diagnostic order by diagnostic ->> 'code')
      filter (where diagnostic is not null) as diagnostics
    from (
      select case
        when aggregate_values.movement_derived_balance < 0 then
          jsonb_build_object(
            'code', 'negative_project_retention_balance',
            'severity', 'blocking_for_future_cutover',
            'message', 'The movement-derived project retention balance is negative.'
          )
      end as diagnostic
      from aggregate_values

      union all

      select case
        when aggregate_values.total_legacy_retention_released > 0 then
          jsonb_build_object(
            'code', 'legacy_reconciliation_required',
            'severity', 'warning',
            'message', 'Persisted legacy retention releases require future reconciliation.'
          )
      end
      from aggregate_values

      union all

      select case
        when coalesce(latest_active_snapshot.retention_balance, 0)
          <> aggregate_values.movement_derived_balance then
          jsonb_build_object(
            'code', 'latest_cumulative_snapshot_mismatch',
            'severity', 'blocking_for_future_cutover',
            'message', 'The latest persisted cumulative balance differs from the movement-derived balance.'
          )
      end
      from aggregate_values
      left join latest_active_snapshot on true

      union all

      select case
        when exists (
          select 1
          from ordered_claims claim
          where claim.status <> 'Cancelled'
            and claim.expected_cumulative_balance < 0
        ) then
          jsonb_build_object(
            'code', 'legacy_releases_exceed_held',
            'severity', 'blocking_for_future_cutover',
            'message', 'A chronological legacy release movement exceeds retention held at that point.'
          )
      end

      union all

      select case
        when exists (
          select 1
          from ordered_claims claim
          where claim.status = 'Cancelled'
            and (
              coalesce(claim.retention_withheld_amount, 0) <> 0
              or coalesce(claim.retention_released_amount, 0) <> 0
            )
        ) then
          jsonb_build_object(
            'code', 'cancelled_claim_has_retention_movement',
            'severity', 'warning',
            'message', 'A cancelled Payment Claim retains persisted retention movements.'
          )
      end

      union all

      select case
        when exists (
          select 1 from ordered_claims claim where claim.claim_date is null
        ) then
          jsonb_build_object(
            'code', 'missing_claim_date',
            'severity', 'info',
            'message', 'A Payment Claim has no claim date and sorts after dated claims.'
          )
      end

      union all

      select case
        when exists (
          select 1
          from ordered_claims claim
          where claim.status not in (
            'Draft', 'Submitted', 'Unpaid', 'Paid', 'Overdue', 'Cancelled'
          )
        ) then
          jsonb_build_object(
            'code', 'unexpected_claim_status',
            'severity', 'blocking_for_future_cutover',
            'message', 'A Payment Claim has a status outside the supported persisted set.'
          )
      end

      union all

      select case
        when exists (
          select 1
          from ordered_claims claim
          where claim.retention_percent is null
             or claim.retention_withheld_amount is null
             or claim.retention_released_amount is null
             or claim.retention_held_to_date is null
             or claim.retention_released_to_date is null
             or claim.retention_balance is null
             or claim.claim_amount is null
             or claim.net_claim_excl_gst is null
             or claim.gst_amount is null
             or claim.total_payable is null
        ) then
          jsonb_build_object(
            'code', 'unexpected_null_financial_field',
            'severity', 'blocking_for_future_cutover',
            'message', 'A required persisted Payment Claim financial field is null.'
          )
      end

      union all

      select case
        when exists (
          select 1
          from ordered_claims claim
          where round(coalesce(claim.retention_balance, 0), 2)
            <> claim.expected_cumulative_balance
        ) then
          jsonb_build_object(
            'code', 'cumulative_snapshot_mismatch',
            'severity', 'blocking_for_future_cutover',
            'message', 'At least one persisted cumulative retention snapshot differs from chronological movements.'
          )
      end
    ) values_with_optional_diagnostics
  ),
  hash_input as (
    select concat_ws(
      '|',
      p_project_id::text,
      v_organization_id::text,
      case when v_capability_enabled then '1' else '0' end,
      v_mode,
      coalesce(
        string_agg(
          concat_ws(
            ':',
            claim.id::text,
            claim.chronological_sequence::text,
            claim.status,
            coalesce(claim.claim_date::text, ''),
            to_char(claim.created_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US'),
            to_char(claim.updated_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US'),
            to_char(round(claim.retention_percent, 3), 'FM999999999999999999990.000'),
            claim.retention_method,
            coalesce(claim.retention_scale_bands::text, ''),
            to_char(round(claim.retention_withheld_amount, 2), 'FM999999999999999999990.00'),
            to_char(round(claim.retention_released_amount, 2), 'FM999999999999999999990.00'),
            to_char(round(claim.retention_held_to_date, 2), 'FM999999999999999999990.00'),
            to_char(round(claim.retention_released_to_date, 2), 'FM999999999999999999990.00'),
            to_char(round(claim.retention_balance, 2), 'FM999999999999999999990.00')
          ),
          ',' order by claim.chronological_sequence
        ),
        ''
      )
    ) as serialized_state
    from ordered_claims claim
  ),
  legacy_release_origins as (
    select coalesce(
      jsonb_agg(
        jsonb_build_object(
          'paymentClaimId', claim.id,
          'claimNumber', claim.claim_number,
          'claimDate', claim.claim_date,
          'effectiveDate', claim.claim_date,
          'retentionReleasedAmount', claim.retention_released_amount,
          'chronologicalSequence', claim.chronological_sequence
        )
        order by claim.chronological_sequence
      ) filter (
        where claim.status <> 'Cancelled'
          and coalesce(claim.retention_released_amount, 0) <> 0
      ),
      '[]'::jsonb
    ) as origins
    from ordered_claims claim
  )
  select jsonb_build_object(
    'organizationId', v_organization_id,
    'projectId', p_project_id,
    'capabilityEnabled', v_capability_enabled,
    'workflowMode', v_mode,
    'accessState', v_access_state,
    'observationEligible', v_capability_enabled and v_mode = 'observe',
    'paymentClaimCount', aggregate_values.payment_claim_count,
    'activePaymentClaimCount', aggregate_values.active_claim_count,
    'retentionOriginCount', aggregate_values.retention_origin_count,
    'legacyReleaseClaimCount', aggregate_values.legacy_release_claim_count,
    'negativeRetentionBalanceClaimCount',
      aggregate_values.negative_retention_balance_claim_count,
    'cancelledClaimCount', aggregate_values.cancelled_claim_count,
    'totalRetentionWithheld', aggregate_values.total_retention_withheld,
    'totalLegacyRetentionReleased',
      aggregate_values.total_legacy_retention_released,
    'movementDerivedRetentionBalance',
      aggregate_values.movement_derived_balance,
    'latestPersistedCumulativeRetentionBalance',
      coalesce(latest_active_snapshot.retention_balance, 0),
    'latestRelevantPaymentClaimDate',
      aggregate_values.latest_relevant_claim_date,
    'latestPersistedUpdateAt',
      aggregate_values.latest_persisted_update_at,
    'legacyReconciliationRequired',
      aggregate_values.total_legacy_retention_released <> 0,
    'legacyReleaseOrigins', legacy_release_origins.origins,
    'diagnostics', coalesce(project_diagnostics.diagnostics, '[]'::jsonb),
    'stateHash', encode(
      extensions.digest(hash_input.serialized_state, 'sha256'),
      'hex'
    )
  )
  into v_result
  from aggregate_values
  left join latest_active_snapshot on true
  cross join project_diagnostics
  cross join hash_input
  cross join legacy_release_origins;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."get_project_retention_position_summary_phase2_pre_legacy_reconc"("p_project_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_project_retention_register"("p_project_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  eligibility jsonb;
begin
  eligibility := public.get_project_retention_eligibility(p_project_id);
  if not coalesce((eligibility->>'succeeded')::boolean, false) then
    return eligibility;
  end if;

  return jsonb_build_object(
    'succeeded', true,
    'errorCode', null,
    'organizationId', eligibility->>'organizationId',
    'projectId', eligibility->>'projectId',
    'positionStateHash', eligibility->>'positionStateHash',
    'eligibilityStateHash', eligibility->>'eligibilityStateHash',
    'rows', coalesce((
      select jsonb_agg(
        origin
        || jsonb_build_object(
          'nativeClaimedAmount', coalesce(native_claims.claimed_amount, 0),
          'legacyReconciledAmount', coalesce(legacy_claims.reconciled_amount, 0),
          'remainingAmount', greatest(
            (origin->>'currentRetentionOwned')::numeric
            - coalesce(native_claims.claimed_amount, 0)
            - coalesce(legacy_claims.reconciled_amount, 0),
            0
          ),
          'paidAmount', coalesce(paid_attribution.paid_amount, 0),
          'latestRetentionClaim', latest_claim.claim,
          'scheduleNames', coalesce(schedule_names.names, '[]'::jsonb),
          'nextEligibilityDate', schedule_names.next_eligibility_date,
          'variance', variance.current_variance,
          'legacyReconciliation', legacy_case.current_case
        )
        order by
          nullif(origin->>'claimDate', '')::date nulls last,
          origin->>'claimNumber',
          origin->>'originatingPaymentClaimId'
      )
      from jsonb_array_elements(
        coalesce(eligibility->'origins', '[]'::jsonb)
      ) origin
      left join lateral (
        select round(coalesce(sum(a.allocation_amount), 0), 2)
          as claimed_amount
        from public.retention_claim_allocations a
        join public.retention_claims c on c.id = a.retention_claim_id
        where a.originating_payment_claim_id =
          (origin->>'originatingPaymentClaimId')::uuid
          and c.status = 'submitted'
      ) native_claims on true
      left join lateral (
        select round(coalesce(sum(a.allocation_amount), 0), 2)
          as reconciled_amount
        from public.retention_legacy_release_allocations a
        join public.retention_legacy_reconciliation_cases c
          on c.id = a.reconciliation_case_id
        where a.originating_payment_claim_id =
          (origin->>'originatingPaymentClaimId')::uuid
          and c.status = 'approved'
      ) legacy_claims on true
      left join lateral (
        select round(coalesce(sum(attribution.paid_amount), 0), 2)
          as paid_amount
        from public.retention_claim_payment_attributions attribution
        join public.retention_claim_payment_reconciliations reconciliation
          on reconciliation.id =
            attribution.payment_reconciliation_id
        where attribution.originating_payment_claim_id =
          (origin->>'originatingPaymentClaimId')::uuid
          and reconciliation.id = (
            select current_reconciliation.id
            from public.retention_claim_payment_reconciliations
              current_reconciliation
            where current_reconciliation.retention_claim_id =
              attribution.retention_claim_id
              and current_reconciliation.projection_applied = true
            order by current_reconciliation.reconciliation_sequence desc
            limit 1
          )
      ) paid_attribution on true
      left join lateral (
        select jsonb_build_object(
          'id', c.id,
          'claimNumber', c.claim_number,
          'status', c.status,
          'issueDate', c.issue_date,
          'allocationAmount', a.allocation_amount
        ) as claim
        from public.retention_claim_allocations a
        join public.retention_claims c on c.id = a.retention_claim_id
        where a.originating_payment_claim_id =
          (origin->>'originatingPaymentClaimId')::uuid
          and c.status <> 'cancelled_draft'
        order by coalesce(c.submitted_at, c.created_at) desc, c.id desc
        limit 1
      ) latest_claim on true
      left join lateral (
        select
          coalesce(
            jsonb_agg(s.name order by s.schedule_sequence),
            '[]'::jsonb
          ) as names,
          (
            select min(nullif(schedule->>'eligibilityDate', '')::date)
            from jsonb_array_elements(
              coalesce(origin->'schedules', '[]'::jsonb)
            ) schedule
            where not coalesce(
              (schedule->>'currentlyEligible')::boolean,
              false
            )
          ) as next_eligibility_date
        from public.project_retention_schedule_origins so
        join public.project_retention_release_schedules s
          on s.id = so.schedule_id
        where so.originating_payment_claim_id =
          (origin->>'originatingPaymentClaimId')::uuid
          and s.status <> 'cancelled'
      ) schedule_names on true
      left join lateral (
        select jsonb_build_object(
          'id', v.id,
          'state', v.state,
          'severity', v.severity,
          'isBlocking', v.is_blocking,
          'primaryType', v.primary_type
        ) as current_variance
        from public.retention_variances v
        where v.originating_payment_claim_id =
          (origin->>'originatingPaymentClaimId')::uuid
        limit 1
      ) variance on true
      left join lateral (
        select jsonb_build_object(
          'id', c.id,
          'caseSequence', c.case_sequence,
          'status', c.status
        ) as current_case
        from public.retention_legacy_reconciliation_cases c
        where c.project_id = p_project_id
          and c.status in ('draft', 'in_review', 'approved')
        order by c.case_sequence desc
        limit 1
      ) legacy_case on true
    ), '[]'::jsonb)
  );
end;
$$;


ALTER FUNCTION "public"."get_project_retention_register"("p_project_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_project_retention_workflow_state"("p_project_id" "uuid") RETURNS TABLE("organization_id" "uuid", "project_id" "uuid", "mode" "text", "changed_by" "uuid", "changed_at" timestamp with time zone, "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_actor_user_id uuid := auth.uid();
  v_organization_id uuid;
begin
  if v_actor_user_id is null or p_project_id is null then
    return;
  end if;

  select project.organization_id
  into v_organization_id
  from public.organization_projects project
  join public.organization_members member
    on member.organization_id = project.organization_id
   and member.user_id = v_actor_user_id
  where project.id = p_project_id;

  if v_organization_id is null
    or not public.has_org_permission(v_organization_id, 'retention.view') then
    return;
  end if;

  return query
  select
    state.organization_id,
    state.project_id,
    state.mode,
    state.changed_by,
    state.changed_at,
    state.created_at,
    state.updated_at
  from public.project_retention_workflow_states state
  where state.project_id = p_project_id
    and state.organization_id = v_organization_id;
end;
$$;


ALTER FUNCTION "public"."get_project_retention_workflow_state"("p_project_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_project_rolling_retention_claim"("p_project_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  context jsonb;
  claim public.retention_claims%rowtype;
begin
  context := private.retention_claim_operation_context(p_project_id, 'retention.view', false);
  if not coalesce((context ->> 'succeeded')::boolean, false) then
    return context;
  end if;

  select * into claim
  from public.retention_claims
  where organization_id = (context ->> 'organizationId')::uuid
    and project_id = p_project_id
    and status = 'draft'
    and draft_kind = 'automatic_rolling'
  order by created_at desc, id desc
  limit 1;

  return jsonb_build_object(
    'succeeded', true,
    'errorCode', null,
    'claim', case when claim.id is null then null else private.retention_claim_header_json(claim.id) end,
    'originCount', case when claim.id is null then 0 else (
      select count(*) from public.retention_rolling_draft_origins where retention_claim_id = claim.id
    ) end,
    'availableAmount', case when claim.id is null then 0 else coalesce((
      select round(sum(coalesce((origin ->> 'availableRetention')::numeric, 0)), 2)
      from public.retention_rolling_draft_origins candidate
      left join lateral (
        select value as origin
        from jsonb_array_elements(
          coalesce(public.get_project_retention_eligibility(p_project_id) -> 'origins', '[]'::jsonb)
        )
        where value ->> 'originatingPaymentClaimId' = candidate.originating_payment_claim_id::text
      ) eligible_origin on true
      where candidate.retention_claim_id = claim.id
    ), 0) end
  );
end;
$$;


ALTER FUNCTION "public"."get_project_rolling_retention_claim"("p_project_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_retention_capability_events"("p_project_id" "uuid" DEFAULT NULL::"uuid", "p_limit" integer DEFAULT 100) RETURNS TABLE("id" "uuid", "organization_id" "uuid", "project_id" "uuid", "event_type" "text", "previous_state" "text", "new_state" "text", "actor_user_id" "uuid", "reason" "text", "correlation_id" "text", "metadata" "jsonb", "occurred_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_actor_user_id uuid := auth.uid();
  v_organization_id uuid;
begin
  if v_actor_user_id is null then
    return;
  end if;

  select member.organization_id
  into v_organization_id
  from public.organization_members member
  where member.user_id = v_actor_user_id
  order by member.created_at, member.id
  limit 1;

  if v_organization_id is null
    or not public.has_org_permission(v_organization_id, 'retention.view') then
    return;
  end if;

  if p_project_id is not null and not exists (
    select 1
    from public.organization_projects project
    where project.id = p_project_id
      and project.organization_id = v_organization_id
  ) then
    return;
  end if;

  return query
  select
    event.id,
    event.organization_id,
    event.project_id,
    event.event_type,
    event.previous_state,
    event.new_state,
    event.actor_user_id,
    event.reason,
    event.correlation_id,
    event.metadata,
    event.occurred_at
  from public.retention_capability_events event
  where event.organization_id = v_organization_id
    and (p_project_id is null or event.project_id = p_project_id)
  order by event.occurred_at desc, event.id desc
  limit greatest(1, least(coalesce(p_limit, 100), 500));
end;
$$;


ALTER FUNCTION "public"."get_retention_capability_events"("p_project_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_retention_claim"("p_retention_claim_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_claim public.retention_claims%rowtype;
  v_context jsonb;
  v_position jsonb;
begin
  select * into v_claim
  from public.retention_claims claim
  where claim.id = p_retention_claim_id;
  if not found then
    return jsonb_build_object('succeeded', false, 'errorCode', 'claim_not_found');
  end if;

  v_context := private.retention_claim_operation_context(
    v_claim.project_id,
    'retention.view',
    false
  );
  if not coalesce((v_context ->> 'succeeded')::boolean, false)
    or (v_context ->> 'organizationId')::uuid is distinct from v_claim.organization_id then
    return jsonb_build_object(
      'succeeded', false,
      'errorCode',
        case
          when v_context ->> 'errorCode' in (
            'capability_disabled',
            'project_mode_not_supported',
            'permission_denied'
          ) then v_context ->> 'errorCode'
          else 'claim_not_found'
        end
    );
  end if;

  v_position := public.get_project_retention_position_summary(v_claim.project_id);

  return jsonb_build_object(
    'succeeded', true,
    'errorCode', null,
    'claim', private.retention_claim_header_json(v_claim.id),
    'allocations', private.retention_claim_current_origin_details(v_claim.id),
    'currentPosition', v_position,
    'positionStateStale',
      v_claim.last_position_state_hash is distinct from (v_position ->> 'stateHash')
  );
end;
$$;


ALTER FUNCTION "public"."get_retention_claim"("p_retention_claim_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_retention_claim_document"("p_retention_claim_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  claim_row public.retention_claims%rowtype;
  context jsonb;
  document_row public.retention_claim_documents%rowtype;
begin
  select * into claim_row
  from public.retention_claims
  where id = p_retention_claim_id;
  if not found then
    return jsonb_build_object(
      'succeeded', false, 'errorCode', 'document_not_found'
    );
  end if;

  context := private.retention_phase8_context(
    claim_row.project_id,
    'retention.view',
    false
  );
  if not coalesce((context->>'succeeded')::boolean, false) then
    return context;
  end if;

  select * into document_row
  from public.retention_claim_documents
  where retention_claim_id = claim_row.id
    and document_kind = 'submitted_claim_pdf'
    and document_version = 1;

  return jsonb_build_object(
    'succeeded', true,
    'errorCode', null,
    'document',
      case when document_row.id is null then null
      else to_jsonb(document_row) end
  );
end;
$$;


ALTER FUNCTION "public"."get_retention_claim_document"("p_retention_claim_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_retention_claim_document_source"("p_retention_claim_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
declare
  claim_row public.retention_claims%rowtype;
  context jsonb;
  source jsonb;
  source_hash text;
begin
  select * into claim_row
  from public.retention_claims
  where id = p_retention_claim_id;

  if not found then
    return jsonb_build_object(
      'succeeded', false, 'errorCode', 'document_not_found'
    );
  end if;

  context := private.retention_phase8_context(
    claim_row.project_id,
    'retention.claims.documents.generate',
    true
  );
  if not coalesce((context->>'succeeded')::boolean, false) then
    return context;
  end if;

  if claim_row.status <> 'submitted' then
    return jsonb_build_object(
      'succeeded', false, 'errorCode', 'claim_not_submitted'
    );
  end if;

  source := private.retention_claim_document_source(claim_row.id);
  source_hash := encode(
    extensions.digest(convert_to(source::text, 'UTF8'), 'sha256'),
    'hex'
  );

  return jsonb_build_object(
    'succeeded', true,
    'errorCode', null,
    'actorUserId', context->>'actorUserId',
    'sourceEvidenceHash', source_hash,
    'source', source
  );
end;
$$;


ALTER FUNCTION "public"."get_retention_claim_document_source"("p_retention_claim_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_retention_claim_draft_origin_set_hash"("p_retention_claim_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private', 'pg_temp'
    AS $$
declare
  v_claim public.retention_claims%rowtype;
  v_context jsonb;
begin
  select *
  into v_claim
  from public.retention_claims
  where id = p_retention_claim_id;
  if not found then
    raise exception using
      errcode = 'P0001',
      message = 'retention_claim_not_found';
  end if;

  v_context := private.retention_claim_operation_context(
    v_claim.project_id,
    'retention.view',
    false
  );
  if not coalesce((v_context ->> 'succeeded')::boolean, false)
    or (v_context ->> 'organizationId')::uuid <> v_claim.organization_id
  then
    return v_context;
  end if;

  return jsonb_build_object(
    'retentionClaimId', v_claim.id,
    'originSetHash',
      private.retention_claim_draft_origin_set_hash(v_claim.id),
    'originStateHashes', coalesce((
      select jsonb_object_agg(
        origin.id::text,
        private.retention_claim_origin_state_hash(origin.id)
      )
      from public.project_claims origin
      where origin.organization_id = v_claim.organization_id
        and origin.project_id = v_claim.project_id
        and origin.status <> 'Cancelled'
        and round(
          greatest(coalesce(origin.retention_withheld_amount, 0), 0),
          2
        ) > 0
    ), '{}'::jsonb)
  );
end;
$$;


ALTER FUNCTION "public"."get_retention_claim_draft_origin_set_hash"("p_retention_claim_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_retention_claim_events"("p_retention_claim_id" "uuid", "p_limit" integer DEFAULT 200) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_claim public.retention_claims%rowtype;
  v_context jsonb;
  v_events jsonb;
begin
  select * into v_claim
  from public.retention_claims claim
  where claim.id = p_retention_claim_id;
  if not found then
    return jsonb_build_object('succeeded', false, 'errorCode', 'claim_not_found');
  end if;

  v_context := private.retention_claim_operation_context(
    v_claim.project_id,
    'retention.view',
    false
  );
  if not coalesce((v_context ->> 'succeeded')::boolean, false)
    or (v_context ->> 'organizationId')::uuid is distinct from v_claim.organization_id then
    return jsonb_build_object('succeeded', false, 'errorCode', 'claim_not_found');
  end if;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id', event.id,
        'organizationId', event.organization_id,
        'projectId', event.project_id,
        'retentionClaimId', event.retention_claim_id,
        'eventType', event.event_type,
        'previousStatus', event.previous_status,
        'newStatus', event.new_status,
        'actorUserId', event.actor_user_id,
        'reason', event.reason,
        'correlationId', event.correlation_id,
        'metadata', event.metadata,
        'occurredAt', event.occurred_at
      )
      order by event.occurred_at, event.id
    ),
    '[]'::jsonb
  )
  into v_events
  from (
    select *
    from public.retention_claim_events event
    where event.retention_claim_id = v_claim.id
    order by event.occurred_at desc, event.id desc
    limit greatest(1, least(coalesce(p_limit, 200), 500))
  ) event;

  return jsonb_build_object(
    'succeeded', true,
    'errorCode', null,
    'events', v_events
  );
end;
$$;


ALTER FUNCTION "public"."get_retention_claim_events"("p_retention_claim_id" "uuid", "p_limit" integer) OWNER TO "postgres";


