    'retention.claims.payments.manage'
  );
$$;


ALTER FUNCTION "public"."get_retention_claim_payment_manage_access"("p_retention_claim_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_retention_claim_payment_state"("p_retention_claim_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  context jsonb;
  claim_row public.retention_claims%rowtype;
  latest_row public.retention_claim_payment_reconciliations%rowtype;
  applied_row public.retention_claim_payment_reconciliations%rowtype;
begin
  context := private.retention_phase10_context(
    p_retention_claim_id,
    'retention.claims.payments.view'
  );
  if not coalesce((context->>'succeeded')::boolean, false) then
    return context;
  end if;

  select * into claim_row
  from public.retention_claims
  where id = p_retention_claim_id;
  if claim_row.status <> 'submitted' then
    return jsonb_build_object(
      'succeeded', false, 'errorCode', 'claim_not_submitted'
    );
  end if;

  select * into latest_row
  from public.retention_claim_payment_reconciliations
  where retention_claim_id = claim_row.id
  order by reconciliation_sequence desc
  limit 1;

  select * into applied_row
  from public.retention_claim_payment_reconciliations
  where retention_claim_id = claim_row.id
    and projection_applied = true
  order by reconciliation_sequence desc
  limit 1;

  return jsonb_build_object(
    'succeeded', true,
    'errorCode', null,
    'actorUserId', context->>'actorUserId',
    'organizationId', claim_row.organization_id,
    'projectId', claim_row.project_id,
    'retentionClaimId', claim_row.id,
    'subtotalExclTax', claim_row.subtotal_excl_tax,
    'latestReconciliation', case when latest_row.id is null then null else
      to_jsonb(latest_row) end,
    'currentAppliedReconciliation', case when applied_row.id is null then null
      else to_jsonb(applied_row) end,
    'attributions', coalesce((
      select jsonb_agg(to_jsonb(attribution)
        order by attribution.allocation_sequence)
      from public.retention_claim_payment_attributions attribution
      where attribution.payment_reconciliation_id = applied_row.id
    ), '[]'::jsonb)
  );
end;
$$;


ALTER FUNCTION "public"."get_retention_claim_payment_state"("p_retention_claim_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_retention_claim_push_execution_phase2c"("p_revision_id" "uuid", "p_attempt_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select jsonb_build_object(
    'document', to_jsonb(d),
    'revision', to_jsonb(r),
    'previousRevision', to_jsonb(previous),
    'lines', coalesce((
      select jsonb_agg(to_jsonb(l) order by l.sequence)
      from public.organization_accounting_revision_lines l
      where l.accounting_revision_id = r.id
    ), '[]'::jsonb),
    'attachment', to_jsonb(a),
    'pdfBase64', encode(b.content_bytes, 'base64'),
    'attempt', to_jsonb(attempt)
  )
  from public.organization_accounting_document_revisions r
  join public.organization_accounting_documents d
    on d.id = r.accounting_document_id
   and d.organization_id = r.organization_id
  join public.organization_accounting_revision_attempts attempt
    on attempt.id = p_attempt_id
   and attempt.accounting_revision_id = r.id
  join public.organization_accounting_revision_attachments a
    on a.accounting_revision_id = r.id
   and a.attachment_sequence = 1
  join public.organization_accounting_revision_blobs b
    on b.accounting_revision_id = r.id
   and b.attachment_id = a.id
  left join public.organization_accounting_document_revisions previous
    on previous.id = r.previous_revision_id
  where r.id = p_revision_id
    and r.source_document_type = 'retention_claim'
    and d.integration_contract = 'retention_claim_revision_v1';
$$;


