CREATE OR REPLACE FUNCTION "public"."get_retention_claim_xero_source"("p_retention_claim_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
declare
  context jsonb;
  claim_row public.retention_claims%rowtype;
  source jsonb;
  source_hash text;
begin
  context := private.retention_phase9_context(
    p_retention_claim_id,
    'retention.claims.xero.manage'
  );
  if not coalesce((context->>'succeeded')::boolean, false) then
    return context;
  end if;

  select * into claim_row
  from public.retention_claims
  where id = p_retention_claim_id;
  if claim_row.status <> 'submitted' then
    return jsonb_build_object(
      'succeeded', false, 'errorCode', 'claim_not_submitted'
    );
  end if;

  source := private.retention_claim_document_source(claim_row.id);
  source_hash := encode(
    extensions.digest(convert_to(source::text, 'UTF8'), 'sha256'),
    'hex'
  );

  return jsonb_build_object(
    'succeeded', true,
    'errorCode', null,
    'actorUserId', context->>'actorUserId',
    'organizationId', claim_row.organization_id,
    'projectId', claim_row.project_id,
    'retentionSourceEvidenceHash', source_hash,
    'source', source
  );
end;
$$;


ALTER FUNCTION "public"."get_retention_claim_xero_source"("p_retention_claim_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_retention_claim_xero_source_phase2c"("p_retention_claim_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'private', 'extensions'
    AS $$
declare
  v_claim public.retention_claims%rowtype;
  v_source jsonb;
  v_hash text;
begin
  if auth.role() <> 'service_role' then
    raise exception 'Immutable Retention Claim source evidence is server-only.';
  end if;
  select * into v_claim from public.retention_claims
  where id = p_retention_claim_id;
  if not found then
    return jsonb_build_object(
      'succeeded', false, 'errorCode', 'claim_not_found'
    );
  end if;
  if v_claim.master_role <> 'master_retention_claim' then
    return jsonb_build_object(
      'succeeded', false, 'errorCode', 'not_master_retention_claim'
    );
  end if;
  if not exists (
    select 1 from public.organization_accounting_phase2b_settings setting
    where setting.organization_id = v_claim.organization_id
      and setting.retention_claim_immutable_xero_enabled
  ) then
    return jsonb_build_object(
      'succeeded', false, 'errorCode', 'feature_disabled'
    );
  end if;
  v_source := private.master_retention_claim_source(v_claim.id);
  if v_source is null
    or jsonb_array_length(v_source->'allocations') = 0 then
    return jsonb_build_object(
      'succeeded', false, 'errorCode', 'no_submitted_retention'
    );
  end if;
  v_hash := encode(digest(convert_to(v_source::text, 'UTF8'), 'sha256'), 'hex');
  return jsonb_build_object(
    'succeeded', true,
    'errorCode', null,
    'organizationId', v_claim.organization_id,
    'projectId', v_claim.project_id,
    'retentionSourceEvidenceHash', v_hash,
    'source', v_source
  );
end;
$$;


