CREATE OR REPLACE FUNCTION "public"."get_trade_pack_monthly_limit_for_organization"("p_organization_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_plan_tier text;
  v_limit integer;
begin
  if p_organization_id is null then
    return 4;
  end if;

  select s.plan_tier, s.monthly_trade_pack_limit
  into v_plan_tier, v_limit
  from public.organization_plan_settings s
  where s.organization_id = p_organization_id
  limit 1;

  if v_limit is not null and v_limit > 0 then
    return v_limit;
  end if;

  return public.default_trade_pack_monthly_limit(v_plan_tier);
end;
$$;


