CREATE OR REPLACE FUNCTION "public"."get_trade_pack_workspace_quota"("p_organization_id" "uuid", "p_reference_at" timestamp with time zone DEFAULT "now"()) RETURNS TABLE("plan_tier" "text", "monthly_limit" integer, "created_count" integer, "remaining" integer, "month_start" timestamp with time zone, "month_end" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_month_start timestamptz;
  v_month_end timestamptz;
  v_plan_tier text;
  v_limit integer;
  v_created integer;
begin
  if auth.uid() is null then
    return;
  end if;

  if not public.is_member_of_organization(p_organization_id) then
    return;
  end if;

  v_month_start := date_trunc('month', coalesce(p_reference_at, now()));
  v_month_end := v_month_start + interval '1 month';

  select s.plan_tier, s.monthly_trade_pack_limit
  into v_plan_tier, v_limit
  from public.organization_plan_settings s
  where s.organization_id = p_organization_id
  limit 1;

  if v_plan_tier is null then
    v_plan_tier := 'starter';
  end if;

  if v_limit is null or v_limit <= 0 then
    v_limit := public.default_trade_pack_monthly_limit(v_plan_tier);
  end if;

  v_created := public.count_trade_pack_workspaces_created_in_month(p_organization_id, p_reference_at);

  return query
  select
    v_plan_tier,
    v_limit,
    v_created,
    greatest(v_limit - v_created, 0),
    v_month_start,
    v_month_end;
