CREATE OR REPLACE FUNCTION "public"."handle_material_purchase_order_change"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  changed_fields text[] := array[]::text[];
begin
  if new.supplier_id is distinct from old.supplier_id then
    changed_fields := array_append(changed_fields, 'supplier_id');
  end if;
  if new.issued_to_label is distinct from old.issued_to_label then
    changed_fields := array_append(changed_fields, 'issued_to_label');
  end if;
  if new.supplier_name_snapshot is distinct from old.supplier_name_snapshot then
    changed_fields := array_append(changed_fields, 'supplier_name_snapshot');
  end if;
  if new.supplier_email_snapshot is distinct from old.supplier_email_snapshot then
    changed_fields := array_append(changed_fields, 'supplier_email_snapshot');
  end if;
  if new.supplier_phone_snapshot is distinct from old.supplier_phone_snapshot then
    changed_fields := array_append(changed_fields, 'supplier_phone_snapshot');
  end if;
  if new.status is distinct from old.status then
    changed_fields := array_append(changed_fields, 'status');
  end if;
  if new.subtotal is distinct from old.subtotal then
    changed_fields := array_append(changed_fields, 'subtotal');
  end if;
  if new.margin_percent is distinct from old.margin_percent then
    changed_fields := array_append(changed_fields, 'margin_percent');
  end if;
  if new.discount_amount is distinct from old.discount_amount then
    changed_fields := array_append(changed_fields, 'discount_amount');
  end if;
  if new.contingency_amount is distinct from old.contingency_amount then
    changed_fields := array_append(changed_fields, 'contingency_amount');
  end if;
  if new.gst_percent is distinct from old.gst_percent then
    changed_fields := array_append(changed_fields, 'gst_percent');
  end if;
  if new.gst_total is distinct from old.gst_total then
    changed_fields := array_append(changed_fields, 'gst_total');
  end if;
  if new.total_purchase_order_price is distinct from old.total_purchase_order_price then
    changed_fields := array_append(changed_fields, 'total_purchase_order_price');
  end if;

  if array_length(changed_fields, 1) is not null then
    perform public.reset_supplier_invoice_match_approvals_for_purchase_order_change(
      new.organization_id,
      new.id,
      changed_fields
    );
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."handle_material_purchase_order_change"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."handle_new_user"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  org_name text;
  member_name text;
  new_org_id uuid;
  invite_row public.organization_invites%rowtype;
  supplied_invite_token uuid;
begin
  org_name := nullif(trim(coalesce(new.raw_user_meta_data ->> 'organization_name', '')), '');
  member_name := nullif(trim(coalesce(new.raw_user_meta_data ->> 'full_name', '')), '');

  begin
    supplied_invite_token := nullif(trim(coalesce(new.raw_user_meta_data ->> 'invite_token', '')), '')::uuid;
  exception
    when invalid_text_representation then
      supplied_invite_token := null;
  end;

  -- Invited-user join path: only honor a matching, non-expired token.
  if supplied_invite_token is not null then
    select i.*
    into invite_row
    from public.organization_invites i
    where i.token = supplied_invite_token
      and lower(i.invited_email) = lower(new.email)
      and i.status = 'pending'
      and i.expires_at > now()
    limit 1;

    if not found then
      raise exception 'Invite token is invalid, expired, or does not match this email address.';
    end if;

    if member_name is null then
      member_name := nullif(trim(coalesce(invite_row.invited_name, '')), '');
    end if;

    if member_name is null then
      member_name := split_part(new.email, '@', 1);
    end if;

    insert into public.organization_members (organization_id, user_id, role, display_name)
    values (invite_row.organization_id, new.id, invite_row.role, member_name)
    on conflict (organization_id, user_id) do update
    set
      role = excluded.role,
      display_name = excluded.display_name,
      updated_at = now();

    update public.organization_invites
    set status = 'accepted', accepted_at = now(), updated_at = now()
    where id = invite_row.id;

    return new;
  end if;

  -- Normal self-signup path: create a fresh organization and owner membership.
  if member_name is null then
    member_name := split_part(new.email, '@', 1);
  end if;

  if org_name is null then
    org_name := split_part(new.email, '@', 1) || ' Organization';
  end if;

  insert into public.organizations (name, created_by)
  values (org_name, new.id)
  returning id into new_org_id;

  insert into public.organization_members (organization_id, user_id, role, display_name)
  values (new_org_id, new.id, 'owner', member_name)
  on conflict (organization_id, user_id) do update
  set
    role = excluded.role,
    display_name = excluded.display_name,
    updated_at = now();

  return new;
end;
$$;


ALTER FUNCTION "public"."handle_new_user"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."handle_new_user"() IS 'Signup hardening: invited users only join an organization when signup carries a matching invite_token. Non-invited users still create a fresh owner workspace.';



CREATE OR REPLACE FUNCTION "public"."handle_supplier_invoice_match_activity"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  purchase_order_number_value text;
  event_type text;
  event_message text;
  event_metadata jsonb;
begin
  if tg_op = 'DELETE' then
    select ppo.purchase_order_number
    into purchase_order_number_value
    from public.project_purchase_orders as ppo
    where ppo.id = old.purchase_order_id;

    event_type := 'match_removed';
    event_message := format(
      'Purchase order %s removed from the invoice match list.',
      coalesce(purchase_order_number_value, old.purchase_order_id::text)
    );
    event_metadata := jsonb_build_object(
      'purchase_order_id', old.purchase_order_id,
      'matched_amount', old.matched_amount,
      'match_status', old.match_status
    );

    perform public.record_supplier_invoice_activity_event(
      old.organization_id,
      old.supplier_invoice_id,
      event_type,
      event_message,
      event_metadata,
      auth.uid()
    );

    perform public.rollup_supplier_invoice_status_from_matches(
      old.organization_id,
      old.supplier_invoice_id
    );

    return old;
  end if;

  select ppo.purchase_order_number
  into purchase_order_number_value
  from public.project_purchase_orders as ppo
  where ppo.id = new.purchase_order_id;

  if tg_op = 'INSERT' then
    event_type := 'match_added';
    event_message := format(
      'Purchase order %s matched to the invoice.',
      coalesce(purchase_order_number_value, new.purchase_order_id::text)
    );
    event_metadata := jsonb_build_object(
      'purchase_order_id', new.purchase_order_id,
      'matched_amount', new.matched_amount,
      'match_status', new.match_status
    );
  else
    if new.matched_amount is not distinct from old.matched_amount
      and new.match_status is not distinct from old.match_status
      and new.purchase_order_id is not distinct from old.purchase_order_id
      and new.approval_status is not distinct from old.approval_status
      and new.approved_by_user_id is not distinct from old.approved_by_user_id
      and new.approved_at is not distinct from old.approved_at
      and new.approval_notes is not distinct from old.approval_notes
      and new.approval_checks_json is not distinct from old.approval_checks_json then
      return new;
    end if;

    event_type := 'match_updated';
    event_message := format(
      'Purchase order %s match updated.',
      coalesce(purchase_order_number_value, new.purchase_order_id::text)
    );
    event_metadata := jsonb_build_object(
      'purchase_order_id', new.purchase_order_id,
      'matched_amount', new.matched_amount,
      'match_status', new.match_status,
      'previous_matched_amount', old.matched_amount,
      'previous_match_status', old.match_status
    );
  end if;

  perform public.record_supplier_invoice_activity_event(
    new.organization_id,
    new.supplier_invoice_id,
    event_type,
    event_message,
    event_metadata,
    auth.uid()
  );

  if tg_op = 'UPDATE'
    and new.approval_status is distinct from old.approval_status then
    if new.approval_status in ('approved', 'disputed') then
      insert into public.supplier_invoice_match_approval_steps (
        organization_id,
        supplier_invoice_purchase_order_match_id,
        supplier_invoice_id,
        purchase_order_id,
        approver_user_id,
        approver_role,
        status,
        decision_notes,
        checks_json,
        decided_at
      )
      values (
        new.organization_id,
        new.id,
        new.supplier_invoice_id,
        new.purchase_order_id,
        new.approved_by_user_id,
        (
          select om.role
          from public.organization_members om
          where om.organization_id = new.organization_id
            and om.user_id = new.approved_by_user_id
          order by om.created_at asc
          limit 1
        ),
        new.approval_status,
        new.approval_notes,
        new.approval_checks_json,
        new.approved_at
      );
    end if;

    perform public.record_supplier_invoice_activity_event(
      new.organization_id,
      new.supplier_invoice_id,
      case
        when new.approval_status = 'approved' then 'allocation_approved'
        when new.approval_status = 'disputed' then 'allocation_disputed'
        else 'allocation_approval_changed'
      end,
      case
        when new.approval_status = 'approved' then format(
          'Allocation for purchase order %s approved.',
          coalesce(purchase_order_number_value, new.purchase_order_id::text)
        )
        when new.approval_status = 'disputed' then format(
          'Allocation for purchase order %s disputed.',
          coalesce(purchase_order_number_value, new.purchase_order_id::text)
        )
        else format(
          'Allocation review for purchase order %s changed.',
          coalesce(purchase_order_number_value, new.purchase_order_id::text)
        )
      end,
      jsonb_build_object(
        'purchase_order_id', new.purchase_order_id,
        'approval_status', new.approval_status,
        'matched_amount', new.matched_amount
      ),
      auth.uid()
    );
  end if;

  perform public.rollup_supplier_invoice_status_from_matches(
    new.organization_id,
    new.supplier_invoice_id
  );

  return new;
end;
$$;


ALTER FUNCTION "public"."handle_supplier_invoice_match_activity"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."has_org_permission"("p_organization_id" "uuid", "p_permission_key" "text") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  has_explicit_allow boolean := false;
  has_explicit_deny boolean := false;
  has_role_allow boolean := false;
  has_fallback_allow boolean := false;
begin
  if auth.uid() is null or p_organization_id is null then
    return false;
  end if;

  if not exists (
    select 1
    from public.organization_members m
    where m.organization_id = p_organization_id
      and m.user_id = auth.uid()
  ) then
    return false;
  end if;

  select exists (
    select 1
    from public.organization_members m
    join public.member_permission_overrides o
      on o.organization_member_id = m.id
    where m.organization_id = p_organization_id
      and m.user_id = auth.uid()
      and o.permission_key = p_permission_key
      and o.is_allowed = true
  )
  into has_explicit_allow;

  if has_explicit_allow then
    return true;
  end if;

  select exists (
    select 1
    from public.organization_members m
    join public.member_permission_overrides o
      on o.organization_member_id = m.id
    where m.organization_id = p_organization_id
      and m.user_id = auth.uid()
      and o.permission_key = p_permission_key
      and o.is_allowed = false
  )
  into has_explicit_deny;

  if has_explicit_deny then
    return false;
  end if;

  select exists (
    select 1
    from public.organization_members m
    join public.role_permissions rp
      on rp.role = m.role
    where m.organization_id = p_organization_id
      and m.user_id = auth.uid()
      and rp.permission_key = p_permission_key
      and rp.is_allowed = true
  )
  into has_role_allow;

  if has_role_allow then
    return true;
  end if;

  select exists (
    select 1
    from public.organization_members m
    where m.organization_id = p_organization_id
      and m.user_id = auth.uid()
      and (
        (p_permission_key = 'settings.organization.update' and m.role in ('owner', 'admin'))
        or
        (p_permission_key = 'leads.clients.write' and m.role in ('owner', 'admin', 'qs', 'project_manager'))
        or
        (p_permission_key = 'leads.opportunities.write' and m.role in ('owner', 'admin', 'qs', 'project_manager'))
        or
        (p_permission_key = 'quotes.write' and m.role in ('owner', 'admin', 'qs', 'project_manager'))
        or
        (p_permission_key = 'variations.write' and m.role in ('owner', 'admin', 'qs', 'project_manager'))
        or
        (p_permission_key = 'purchase_orders.write' and m.role in ('owner', 'admin', 'qs', 'project_manager'))
        or
        (p_permission_key = 'suppliers.write' and m.role in ('owner', 'admin', 'qs', 'project_manager'))
        or
        (p_permission_key = 'supplier_invoices.view' and m.role in ('owner', 'admin', 'qs', 'project_manager'))
        or
        (p_permission_key = 'supplier_invoices.write' and m.role in ('owner', 'admin', 'qs', 'project_manager'))
        or
        (p_permission_key = 'supplier_invoices.review' and m.role in ('owner', 'admin', 'qs', 'project_manager'))
        or
        (p_permission_key = 'materials.view' and m.role in ('owner', 'admin', 'qs', 'project_manager'))
        or
        (p_permission_key = 'materials.write' and m.role in ('owner', 'admin', 'qs', 'project_manager'))
      )
  )
  into has_fallback_allow;

  return has_fallback_allow;
end;
$$;


ALTER FUNCTION "public"."has_org_permission"("p_organization_id" "uuid", "p_permission_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."has_permission"("p_permission_key" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  current_member_id uuid;
  current_role text;
  override_value boolean;
  role_default boolean;
begin
  if auth.uid() is null then
    return false;
  end if;

  if p_permission_key is null or btrim(p_permission_key) = '' then
    return false;
  end if;

  select m.id, m.role
  into current_member_id, current_role
  from public.organization_members m
  where m.user_id = auth.uid()
  order by m.created_at asc
  limit 1;

  if current_member_id is null then
    return false;
  end if;

  if p_permission_key in ('settings.users_permissions.manage') then
    return current_role = 'owner';
  end if;

  select o.is_allowed
  into override_value
  from public.member_permission_overrides o
  where o.organization_member_id = current_member_id
    and o.permission_key = p_permission_key
  limit 1;

  if found then
    return coalesce(override_value, false);
  end if;

  select rp.is_allowed
  into role_default
  from public.role_permissions rp
  where rp.role = current_role
    and rp.permission_key = p_permission_key
  limit 1;

  return coalesce(role_default, false);
end;
$$;


ALTER FUNCTION "public"."has_permission"("p_permission_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."has_platform_admin_role"("required_role" "text") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  current_role text;
  required_rank integer;
begin
  if current_user in ('postgres', 'service_role', 'supabase_admin', 'supabase_auth_admin') then
    return true;
  end if;

  if coalesce(auth.role(), '') = 'service_role' then
    return true;
  end if;

  if auth.uid() is null then
    return false;
  end if;

  required_rank := public._platform_admin_role_rank(required_role);
  if required_rank = 0 then
    return false;
  end if;

  select pau.role
  into current_role
  from public.platform_admin_users pau
  where pau.user_id = auth.uid()
    and pau.is_active
  limit 1;

  if current_role is null then
    return false;
  end if;

  return public._platform_admin_role_rank(current_role) >= required_rank;
end;
$$;


ALTER FUNCTION "public"."has_platform_admin_role"("required_role" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."heartbeat_accounting_revision_attempt_phase2a"("p_attempt_id" "uuid", "p_worker_id" "text", "p_lease_token" "uuid", "p_lease_seconds" integer DEFAULT 60) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare changed integer;
begin
  if p_lease_seconds not between 10 and 900 then
    raise exception 'Invalid accounting attempt lease duration.';
  end if;
  perform set_config('app.accounting_phase2a_lease_write', 'true', true);
  update public.organization_accounting_revision_attempts set
    heartbeat_at = now(),
    lease_expires_at = now() + make_interval(secs => p_lease_seconds),
    updated_at = now()
  where id = p_attempt_id
    and queue_state = 'claimed'
    and worker_id = p_worker_id
    and lease_token = p_lease_token
    and lease_expires_at >= now();
  get diagnostics changed = row_count;
  perform set_config('app.accounting_phase2a_lease_write', '', true);
  return changed = 1;
end;
$$;


ALTER FUNCTION "public"."heartbeat_accounting_revision_attempt_phase2a"("p_attempt_id" "uuid", "p_worker_id" "text", "p_lease_token" "uuid", "p_lease_seconds" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."initialize_primary_opportunity_quote_v1"("p_organization_id" "uuid", "p_opportunity_id" "uuid") RETURNS TABLE("series_id" "uuid", "revision_id" "uuid", "base_quote_number" "text", "revision_number" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare primary_client_id uuid;
begin
  select opportunity.client_id into primary_client_id
  from public.organization_opportunities opportunity
  where opportunity.organization_id = p_organization_id and opportunity.id = p_opportunity_id;
  if primary_client_id is null then
    raise exception 'Select a Primary Client before creating a quote' using errcode = 'TS422';
  end if;
  return query select result.series_id, result.revision_id, result.base_quote_number, result.revision_number
  from public.create_opportunity_quote_series_v1(
    p_organization_id, p_opportunity_id, primary_client_id
  ) result;
end;
$$;


ALTER FUNCTION "public"."initialize_primary_opportunity_quote_v1"("p_organization_id" "uuid", "p_opportunity_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."initiate_document_upload"("p_opportunity_id" "uuid", "p_project_id" "uuid", "p_parent_node_id" "uuid", "p_display_name" "text", "p_claimed_mime_type" "text", "p_file_extension" "text", "p_byte_size" bigint, "p_existing_node_id" "uuid", "p_idempotency_key" "uuid") RETURNS TABLE("node_id" "uuid", "version_id" "uuid", "version_number" integer, "storage_key" "text", "upload_state" "text", "upload_expires_at" timestamp with time zone, "display_name" "text", "claimed_mime_type" "text", "byte_size" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
declare
  caller_id uuid := auth.uid();
  resolved_workspace_id uuid;
  resolved_organization_id uuid;
  normalized_display_name text := btrim(coalesce(p_display_name, ''));
  normalized_mime_type text := lower(btrim(coalesce(p_claimed_mime_type, '')));
  normalized_extension text := lower(btrim(coalesce(p_file_extension, '')));
  request_fingerprint text;
  existing_version public.document_versions%rowtype;
  target_node public.document_nodes%rowtype;
  parent_node public.document_nodes%rowtype;
  new_version_id uuid := gen_random_uuid();
  next_version_number integer;
  previous_version_id uuid;
begin
  if caller_id is null then
    raise exception 'Unauthorized.';
  end if;

  if p_idempotency_key is null then
    raise exception 'An idempotency key is required.';
  end if;

  if p_byte_size is null or p_byte_size < 1 then
    raise exception 'Document files cannot be empty.';
  end if;

  if p_byte_size > 2147483648 then
    raise exception 'Document file exceeds the 2 GiB limit.';
  end if;

  if normalized_display_name = ''
    or char_length(normalized_display_name) > 250
    or normalized_display_name in ('.', '..')
    or normalized_display_name ~ '[[:cntrl:]]'
    or normalized_display_name ~ E'[/\\\\]'
  then
    raise exception 'Invalid document file name.';
  end if;

  if normalized_extension = ''
    or normalized_extension !~ '^[a-z0-9]{1,16}$'
    or right(lower(normalized_display_name), char_length(normalized_extension) + 1)
      <> '.' || normalized_extension
  then
    raise exception 'Document extension does not match the file name.';
  end if;

  if lower(normalized_display_name) ~
    '\.(exe|com|bat|cmd|msi|msp|scr|ps1|psm1|sh|bash|zsh|js|mjs|cjs|html?|svg|zip|rar|7z|tar|gz|bz2|xz|iso|dmg|pkg|app|apk|jar|docm|dotm|xlsm|xltm|pptm|potm)(\.|$)'
  then
    raise exception 'Blocked document file type.';
  end if;

  if not public.document_upload_mime_extension_allowed(
    normalized_mime_type,
    normalized_extension
  ) then
    raise exception 'Document MIME type and extension are not allowed.';
  end if;

  resolved_workspace_id :=
    public.resolve_document_upload_workspace(p_opportunity_id, p_project_id);

  select workspace.organization_id
  into resolved_organization_id
  from public.document_workspaces workspace
  where workspace.id = resolved_workspace_id;

  perform pg_advisory_xact_lock(
    hashtextextended('document-upload:' || resolved_workspace_id::text, 0)
  );

  request_fingerprint := encode(
    extensions.digest(
      concat_ws(
        '|',
        resolved_workspace_id::text,
        coalesce(p_parent_node_id::text, ''),
        normalized_display_name,
        normalized_mime_type,
        normalized_extension,
        p_byte_size::text,
        coalesce(p_existing_node_id::text, '')
      ),
      'sha256'
    ),
    'hex'
  );

  select version.*
  into existing_version
  from public.document_versions version
  where version.uploaded_by = caller_id
    and version.upload_idempotency_key = p_idempotency_key;

  if found then
    if existing_version.workspace_id <> resolved_workspace_id
      or existing_version.upload_request_fingerprint <> request_fingerprint
    then
      raise exception 'Idempotency key was already used for another upload.';
    end if;

    return query
    select
      node.id,
      existing_version.id,
      existing_version.version_number,
      existing_version.storage_key,
      existing_version.upload_state,
      existing_version.upload_expires_at,
      node.display_name,
      existing_version.claimed_mime_type,
      existing_version.byte_size
    from public.document_nodes node
    where node.id = existing_version.node_id;
    return;
  end if;

  if p_parent_node_id is not null then
    select node.*
    into parent_node
    from public.document_nodes node
    where node.organization_id = resolved_organization_id
      and node.workspace_id = resolved_workspace_id
      and node.id = p_parent_node_id
    for update;

    if not found
      or parent_node.kind <> 'folder'
      or parent_node.deleted_at is not null
      or parent_node.lifecycle_state <> 'active'
    then
      raise exception 'Parent folder not found.';
    end if;
  end if;

  if p_existing_node_id is null then
    insert into public.document_nodes (
      organization_id,
      workspace_id,
      parent_node_id,
      kind,
      display_name,
      lifecycle_state,
      created_by,
      updated_by
    )
    values (
      resolved_organization_id,
      resolved_workspace_id,
      p_parent_node_id,
      'file',
      normalized_display_name,
      'pending',
      caller_id,
      caller_id
    )
    returning * into target_node;

    next_version_number := 1;
    previous_version_id := null;
  else
    select node.*
    into target_node
    from public.document_nodes node
    where node.organization_id = resolved_organization_id
      and node.workspace_id = resolved_workspace_id
      and node.id = p_existing_node_id
    for update;

    if not found
      or target_node.kind <> 'file'
      or target_node.deleted_at is not null
      or target_node.lifecycle_state <> 'active'
      or target_node.current_version_id is null
    then
      raise exception 'Replacement target must be a live active file.';
    end if;

    if target_node.parent_node_id is distinct from p_parent_node_id
      or target_node.display_name <> normalized_display_name
    then
      raise exception 'Replacement must preserve the file name and parent folder.';
    end if;

    select coalesce(max(version.version_number), 0) + 1
    into next_version_number
    from public.document_versions version
    where version.node_id = target_node.id;

    previous_version_id := target_node.current_version_id;
  end if;

  insert into public.document_versions (
    id,
    organization_id,
    workspace_id,
    node_id,
    version_number,
    storage_key,
    upload_state,
    byte_size,
    claimed_mime_type,
    file_extension,
    uploaded_by,
    upload_idempotency_key,
    upload_expires_at,
    upload_request_fingerprint,
    replaces_version_id
  )
  values (
    new_version_id,
    resolved_organization_id,
    resolved_workspace_id,
    target_node.id,
    next_version_number,
    resolved_organization_id::text
      || '/' || resolved_workspace_id::text
      || '/' || new_version_id::text,
    'pending',
    p_byte_size,
    normalized_mime_type,
    normalized_extension,
    caller_id,
    p_idempotency_key,
    now() + interval '24 hours',
    request_fingerprint,
    previous_version_id
  )
  returning * into existing_version;

  insert into public.document_activity_events (
    organization_id,
    workspace_id,
    node_id,
    version_id,
    actor_user_id,
    event_type,
    metadata
  )
  values (
    resolved_organization_id,
    resolved_workspace_id,
    target_node.id,
    existing_version.id,
    caller_id,
    'file_upload_initiated',
    jsonb_build_object(
      'version_number', existing_version.version_number,
      'replacement', p_existing_node_id is not null,
      'byte_size', p_byte_size
    )
  );

  return query
  select
    target_node.id,
    existing_version.id,
    existing_version.version_number,
    existing_version.storage_key,
    existing_version.upload_state,
    existing_version.upload_expires_at,
    target_node.display_name,
    existing_version.claimed_mime_type,
    existing_version.byte_size;
end;
$_$;


ALTER FUNCTION "public"."initiate_document_upload"("p_opportunity_id" "uuid", "p_project_id" "uuid", "p_parent_node_id" "uuid", "p_display_name" "text", "p_claimed_mime_type" "text", "p_file_extension" "text", "p_byte_size" bigint, "p_existing_node_id" "uuid", "p_idempotency_key" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."initiate_project_qa_evidence_upload_v1"("p_organization_id" "uuid", "p_project_id" "uuid", "p_run_id" "uuid", "p_response_id" "uuid", "p_evidence_type" "text", "p_purpose" "text", "p_original_filename" "text", "p_mime_type" "text", "p_byte_size" bigint, "p_idempotency_key" "uuid") RETURNS TABLE("upload_id" "uuid", "storage_path" "text", "expires_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare run_row public.project_qa_runs%rowtype; response_row public.project_qa_responses%rowtype; existing public.project_qa_evidence_uploads%rowtype; new_id uuid:=gen_random_uuid(); clean_name text:=btrim(coalesce(p_original_filename,'')); clean_mime text:=lower(btrim(coalesce(p_mime_type,''))); object_path text; maximum_size bigint;
begin
  if auth.uid() is null or not public.can_access_qa_project(p_organization_id,p_project_id,'qa.inspect') then raise exception 'Not authorized to upload QA evidence' using errcode='42501'; end if;
  select * into run_row from public.project_qa_runs where organization_id=p_organization_id and project_id=p_project_id and id=p_run_id for update;
  if not found then raise exception 'QA Record not found' using errcode='TS404'; end if;
  if run_row.status<>'in_progress' then raise exception 'Evidence can only be added to an in-progress QA Record' using errcode='TS409'; end if;
  select * into response_row from public.project_qa_responses where organization_id=p_organization_id and project_id=p_project_id and run_id=p_run_id and id=p_response_id;
  if not found then raise exception 'QA response not found' using errcode='TS404'; end if;
  if p_evidence_type='photo' and response_row.field_type not in ('photo','inspection_check') then raise exception 'Photo evidence is not valid for this response' using errcode='TS422'; end if;
  if p_evidence_type='file' and response_row.field_type not in ('file','inspection_check') then raise exception 'File evidence is not valid for this response' using errcode='TS422'; end if;
  if p_evidence_type='signature' and response_row.field_type<>'signature' then raise exception 'Signature evidence is not valid for this response' using errcode='TS422'; end if;
  if p_purpose not in ('general','failure') then raise exception 'Invalid QA evidence purpose' using errcode='TS422'; end if;
  if char_length(clean_name) not between 1 and 250 or clean_name~'[[:cntrl:]]' or position('/' in clean_name)>0 or position(chr(92) in clean_name)>0 then raise exception 'Invalid evidence filename' using errcode='TS422'; end if;
  maximum_size:=case when p_evidence_type='signature' then 2097152 else 104857600 end;
  if p_byte_size is null or p_byte_size<1 or p_byte_size>maximum_size then
    if p_evidence_type='signature' then raise exception 'QA signature evidence must be 2 MB or smaller' using errcode='TS422';
    else raise exception 'QA evidence must be 100 MB or smaller' using errcode='TS422'; end if;
  end if;
  if not public.qa_evidence_mime_allowed_v1(p_evidence_type,clean_mime) then raise exception 'Unsupported QA evidence file type' using errcode='TS422'; end if;
  select * into existing from public.project_qa_evidence_uploads where initiated_by=auth.uid() and idempotency_key=p_idempotency_key;
  if found then
    if existing.run_id<>p_run_id or existing.response_id<>p_response_id or existing.evidence_type<>p_evidence_type or existing.original_filename<>clean_name or existing.mime_type<>clean_mime or existing.byte_size<>p_byte_size then raise exception 'Upload idempotency key conflict' using errcode='TS409'; end if;
    return query select existing.id,existing.storage_path,existing.expires_at; return;
  end if;
  object_path:=p_organization_id::text||'/'||p_project_id::text||'/'||p_run_id::text||'/'||p_response_id::text||'/'||new_id::text;
  insert into public.project_qa_evidence_uploads(id,organization_id,project_id,run_id,response_id,evidence_type,purpose,storage_path,original_filename,mime_type,byte_size,idempotency_key,initiated_by)
  values(new_id,p_organization_id,p_project_id,p_run_id,p_response_id,p_evidence_type,p_purpose,object_path,clean_name,clean_mime,p_byte_size,p_idempotency_key,auth.uid()) returning project_qa_evidence_uploads.expires_at into expires_at;
  return query select new_id,object_path,expires_at;
end; $$;


