CREATE OR REPLACE FUNCTION "public"."is_opportunity_lifecycle_override_active_v1"("p_pilot_scope" "text", "p_pilot_environment" "text") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE PARALLEL SAFE
    SET "search_path" TO 'public'
    AS $$
  select public.is_opportunity_promotion_rollout_scope_v1(
    p_pilot_scope,
    p_pilot_environment
  );
$$;


