CREATE OR REPLACE FUNCTION "public"."link_organization_memory_evidence"("p_input" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  resolved_organization_id uuid;
  resolved_memory_item_id uuid;
  resolved_source_event_id uuid;
  resolved_source_ai_interaction_id uuid;
  resolved_source_correction_event_id uuid;
  resolved_source_validation_case_id uuid;
  resolved_link_type text;
  resolved_confidence_delta numeric;
  existing_link_id uuid;
  inserted_id uuid;
begin
  if p_input is null or jsonb_typeof(p_input) <> 'object' then
    raise exception 'link_organization_memory_evidence requires a JSON object payload';
  end if;

  perform public._organization_memory_assert_platform_admin('admin');

  resolved_organization_id := nullif(p_input->>'organizationId', '')::uuid;
  resolved_memory_item_id := nullif(p_input->>'organizationMemoryItemId', '')::uuid;
  resolved_source_event_id := nullif(p_input->>'sourceEventId', '')::uuid;
  resolved_source_ai_interaction_id := nullif(p_input->>'sourceAiInteractionId', '')::uuid;
  resolved_source_correction_event_id := nullif(p_input->>'sourceCorrectionEventId', '')::uuid;
  resolved_source_validation_case_id := nullif(p_input->>'sourceValidationCaseId', '')::uuid;
  resolved_link_type := coalesce(nullif(btrim(coalesce(p_input->>'linkType', '')), ''), 'supporting');
  resolved_confidence_delta := coalesce(
    nullif(p_input->>'confidenceDelta', '')::numeric,
    public._organization_memory_default_confidence_delta(resolved_link_type)
  );

  perform public._organization_memory_assert_organization_exists(resolved_organization_id);
  perform public._organization_memory_assert_item_in_organization(resolved_memory_item_id, resolved_organization_id);
  perform public._organization_memory_assert_source_in_organization(
    resolved_organization_id,
    resolved_source_event_id,
    resolved_source_ai_interaction_id,
    resolved_source_correction_event_id,
    resolved_source_validation_case_id
  );

  select oml.id
  into existing_link_id
  from public.organization_memory_links oml
  where oml.organization_memory_item_id = resolved_memory_item_id
    and (
      (resolved_source_event_id is not null and oml.source_event_id = resolved_source_event_id)
      or (resolved_source_ai_interaction_id is not null and oml.source_ai_interaction_id = resolved_source_ai_interaction_id)
      or (resolved_source_correction_event_id is not null and oml.source_correction_event_id = resolved_source_correction_event_id)
      or (resolved_source_validation_case_id is not null and oml.source_validation_case_id = resolved_source_validation_case_id)
    )
  limit 1;

  if existing_link_id is not null then
    return existing_link_id;
  end if;

  insert into public.organization_memory_links (
    organization_memory_item_id,
    organization_id,
    link_type,
    source_event_id,
    source_ai_interaction_id,
    source_correction_event_id,
    source_validation_case_id,
    source_entity_type,
    source_entity_id,
    weight,
    confidence_delta,
    note,
    created_by_user_id
  )
  values (
    resolved_memory_item_id,
    resolved_organization_id,
    resolved_link_type,
    resolved_source_event_id,
    resolved_source_ai_interaction_id,
    resolved_source_correction_event_id,
    resolved_source_validation_case_id,
    nullif(btrim(coalesce(p_input->>'sourceEntityType', '')), ''),
    nullif(p_input->>'sourceEntityId', '')::uuid,
    coalesce(nullif(p_input->>'weight', '')::numeric, 1),
    resolved_confidence_delta,
    nullif(p_input->>'note', ''),
    auth.uid()
  )
  returning id into inserted_id;

  update public.organization_memory_items
  set
    confidence_score = least(greatest(confidence_score + resolved_confidence_delta, 0), 1),
    derived_from_event_count = derived_from_event_count + case when resolved_source_event_id is not null then 1 else 0 end,
    derived_from_ai_interaction_count = derived_from_ai_interaction_count + case when resolved_source_ai_interaction_id is not null then 1 else 0 end,
    derived_from_correction_count = derived_from_correction_count + case when resolved_source_correction_event_id is not null then 1 else 0 end,
    derived_from_validation_count = derived_from_validation_count + case when resolved_source_validation_case_id is not null then 1 else 0 end,
    derived_from_total_count = derived_from_total_count + 1,
    reinforcement_count = reinforcement_count + case when resolved_link_type in ('seed', 'supporting', 'confirmation') then 1 else 0 end,
    contradiction_count = contradiction_count + case when resolved_link_type in ('contradiction', 'supersession') then 1 else 0 end,
    first_derived_at = coalesce(first_derived_at, now()),
    last_derived_at = now(),
    last_reinforced_at = case
      when resolved_link_type in ('seed', 'supporting', 'confirmation') then now()
      else last_reinforced_at
    end,
    last_contradicted_at = case
      when resolved_link_type in ('contradiction', 'supersession') then now()
      else last_contradicted_at
    end,
    updated_at = now()
  where id = resolved_memory_item_id
    and organization_id = resolved_organization_id;

  return inserted_id;
end;
$$;


ALTER FUNCTION "public"."link_organization_memory_evidence"("p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."link_project_to_opportunity_document_workspace"("p_opportunity_id" "uuid", "p_project_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  actor_user_id uuid := auth.uid();
  opportunity_row public.organization_opportunities%rowtype;
  project_row public.organization_projects%rowtype;
  opportunity_link public.document_workspace_entities%rowtype;
  existing_project_link public.document_workspace_entities%rowtype;
  project_link public.document_workspace_entities%rowtype;
begin
  if actor_user_id is null then
    raise exception 'Authentication required.'
      using errcode = '42501';
  end if;

  select *
  into opportunity_row
  from public.organization_opportunities opportunity
  where opportunity.id = p_opportunity_id
  for key share;

  select *
  into project_row
  from public.organization_projects project
  where project.id = p_project_id
  for key share;

  if opportunity_row.id is null
    or project_row.id is null
    or opportunity_row.organization_id <> project_row.organization_id
    or project_row.source_opportunity_id is distinct from opportunity_row.id
    or not public.has_org_permission(opportunity_row.organization_id, 'files.write')
  then
    raise exception 'Opportunity and Project workspace linkage is not authorized.'
      using errcode = '42501';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended('document-project:' || project_row.id::text, 0)
  );

  select *
  into opportunity_link
  from public.document_workspace_entities entity_link
  where entity_link.opportunity_id = opportunity_row.id;

  if not found then
    raise exception 'Opportunity document workspace does not exist.'
      using errcode = 'P0002';
  end if;

  select *
  into existing_project_link
  from public.document_workspace_entities entity_link
  where entity_link.project_id = project_row.id;

  if found then
    if existing_project_link.workspace_id <> opportunity_link.workspace_id then
      raise exception 'Project is already linked to a different document workspace.'
        using errcode = '23505';
    end if;

    return existing_project_link.workspace_id;
  end if;

  insert into public.document_workspace_entities (
    organization_id,
    workspace_id,
    project_id,
    linked_by
  )
  values (
    opportunity_row.organization_id,
    opportunity_link.workspace_id,
    project_row.id,
    actor_user_id
  )
  returning * into project_link;

  insert into public.document_activity_events (
    organization_id,
    workspace_id,
    entity_link_id,
    actor_user_id,
    event_type,
    metadata
  )
  values (
    opportunity_row.organization_id,
    opportunity_link.workspace_id,
    project_link.id,
    actor_user_id,
    'project_linked',
    jsonb_build_object(
      'opportunityId', opportunity_row.id,
      'projectId', project_row.id
    )
  );

  return opportunity_link.workspace_id;
end;
$$;


ALTER FUNCTION "public"."link_project_to_opportunity_document_workspace"("p_opportunity_id" "uuid", "p_project_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_classified_worksheet_memory_events"("p_organization_id" "uuid" DEFAULT NULL::"uuid", "p_limit" integer DEFAULT 1000) RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with latest_classification as (
    select distinct on (c.source_event_id)
      c.id as classification_record_id,
      c.source_event_id,
      c.organization_id,
      c.classification_version,
      c.attempt_number,
      c.classification_status,
      c.classification_source,
      c.classification_provider,
      c.classification_model,
      c.classification_model_version,
      c.overall_confidence,
      c.reasoning_summary,
      c.semantic_fields,
      c.interpretation_schema_version,
      c.interpretation_payload,
      c.request_context,
      c.classified_at
    from public.worksheet_event_classifications c
    where c.classification_status = 'classified'
      and (p_organization_id is null or c.organization_id = p_organization_id)
    order by c.source_event_id, c.classification_version desc, c.attempt_number desc, c.classified_at desc
  ),
  joined as (
    select
      e.id as event_id,
      e.organization_id,
      e.project_id,
      e.opportunity_id,
      e.event_type,
      e.occurred_at,
      e.metadata,
      e.diff_data,
      lc.classification_record_id,
      lc.classification_version,
      lc.attempt_number,
      lc.classification_source,
      lc.classification_provider,
      lc.classification_model,
      lc.classification_model_version,
      lc.overall_confidence,
      lc.reasoning_summary,
      lc.semantic_fields,
      lc.interpretation_schema_version,
      lc.interpretation_payload,
      lc.request_context,
      lc.classified_at
    from latest_classification lc
    join public.intelligence_events e
      on e.id = lc.source_event_id
     and e.organization_id = lc.organization_id
    where e.module = 'pricing_worksheets'
      and e.event_type in (
        'worksheet_cell_edited',
        'worksheet_formula_edited',
        'worksheet_rate_changed',
        'worksheet_assumption_changed',
        'worksheet_ai_rate_corrected',
        'worksheet_ai_assumption_corrected',
        'worksheet_ai_formula_corrected',
        'worksheet_ai_output_corrected'
      )
      and coalesce(e.diff_data->>'classificationStatus', '') = 'pending'
  )
  select coalesce(jsonb_agg(
    jsonb_build_object(
      'eventId', j.event_id,
      'organizationId', j.organization_id,
      'classificationRecordId', j.classification_record_id,
      'classificationAttemptNumber', j.attempt_number,
      'projectId', j.project_id,
      'opportunityId', j.opportunity_id,
      'eventType', j.event_type,
      'occurredAt', j.occurred_at,
      'metadata', j.metadata,
      'diffData', j.diff_data,
      'classificationVersion', j.classification_version,
      'classificationSource', j.classification_source,
      'classificationProvider', j.classification_provider,
      'classificationModel', j.classification_model,
      'classificationModelVersion', j.classification_model_version,
      'overallConfidence', j.overall_confidence,
      'reasoningSummary', j.reasoning_summary,
      'semanticFields', j.semantic_fields,
      'interpretationSchemaVersion', j.interpretation_schema_version,
      'interpretationPayload', j.interpretation_payload,
      'requestContext', j.request_context,
      'classifiedAt', j.classified_at
    )
    order by j.classified_at desc, j.occurred_at desc
  ), '[]'::jsonb)
  from (
    select *
    from joined
    order by classified_at desc, occurred_at desc
    limit greatest(coalesce(p_limit, 1000), 1)
  ) j;
$$;


ALTER FUNCTION "public"."list_classified_worksheet_memory_events"("p_organization_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_commercial_items_for_opportunity"("p_organization_id" "uuid", "p_opportunity_id" "uuid") RETURNS TABLE("id" "uuid", "organization_id" "uuid", "opportunity_id" "uuid", "project_id" "uuid", "source_type" "text", "source_workbook_id" "uuid", "source_worksheet_id" "uuid", "source_sheet_id" "uuid", "source_range" "text", "source_signature" "text", "source_version" integer, "source_status" "text", "stale_reason_code" "text", "last_source_checked_at" timestamp with time zone, "last_source_changed_at" timestamp with time zone, "description" "text", "quantity" numeric, "unit" "text", "rate" numeric, "total" numeric, "snapshot_json" "jsonb", "source_link_json" "jsonb", "ucl_classification" "text", "ucl_validation_status" "text", "created_by" "uuid", "updated_by" "uuid", "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if auth.uid() is null then
    raise exception 'Authentication is required';
  end if;

  if not public.is_member_of_organization(p_organization_id) then
    raise exception 'Not authorized for this organization';
  end if;

  return query
  select
    item.id,
    item.organization_id,
    item.opportunity_id,
    item.project_id,
    item.source_type,
    item.source_workbook_id,
    item.source_worksheet_id,
    item.source_sheet_id,
    item.source_range,
    item.source_signature,
    item.source_version,
    item.source_status,
    item.stale_reason_code,
    item.last_source_checked_at,
    item.last_source_changed_at,
    item.description,
    item.quantity,
    item.unit,
    item.rate,
    item.total,
    item.snapshot_json,
    item.source_link_json,
    item.ucl_classification,
    item.ucl_validation_status,
    item.created_by,
    item.updated_by,
    item.created_at,
    item.updated_at
  from public.commercial_items item
  where item.organization_id = p_organization_id
    and item.opportunity_id = p_opportunity_id
  order by item.created_at desc;
end;
$$;


