CREATE OR REPLACE FUNCTION "public"."list_deleted_document_batches"("p_workspace_id" "uuid", "p_search" "text" DEFAULT NULL::"text", "p_file_type" "text" DEFAULT 'all'::"text", "p_sort" "text" DEFAULT 'modified'::"text", "p_direction" "text" DEFAULT 'desc'::"text", "p_limit" integer DEFAULT 100, "p_offset" integer DEFAULT 0) RETURNS TABLE("deletion_batch_id" "uuid", "root_node_id" "uuid", "kind" "text", "display_name" "text", "deleted_by_user_id" "uuid", "deleted_by_name" "text", "deleted_at" timestamp with time zone, "original_parent_node_id" "uuid", "original_parent_name" "text", "item_count" bigint, "byte_size" bigint, "total_count" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  normalized_search text := nullif(lower(btrim(coalesce(p_search, ''))), '');
  normalized_type text := lower(btrim(coalesce(p_file_type, 'all')));
  normalized_sort text := lower(btrim(coalesce(p_sort, 'modified')));
  normalized_direction text := lower(btrim(coalesce(p_direction, 'desc')));
begin
  perform public.assert_document_workspace_permission(
    p_workspace_id,
    'files.delete'
  );

  if p_limit < 1 or p_limit > 200 or p_offset < 0 then
    raise exception 'Invalid deleted document page.';
  end if;
  if normalized_type not in (
    'all', 'folders', 'pdf', 'images', 'documents', 'spreadsheets',
    'presentations', 'text', 'other'
  ) then
    raise exception 'Invalid deleted document filter.';
  end if;
  if normalized_sort not in ('name', 'modified', 'owner', 'size')
    or normalized_direction not in ('asc', 'desc')
  then
    raise exception 'Invalid deleted document sort.';
  end if;

  return query
  with roots as (
    select root.*
    from public.document_nodes root
    left join public.document_nodes parent
      on parent.id = root.parent_node_id
      and parent.workspace_id = root.workspace_id
    where root.workspace_id = p_workspace_id
      and root.deleted_at is not null
      and root.deletion_batch_id is not null
      and parent.deletion_batch_id is distinct from root.deletion_batch_id
  ),
  batch_counts as (
    select
      member_node.deletion_batch_id,
      count(*) as item_count
    from public.document_nodes member_node
    where member_node.workspace_id = p_workspace_id
      and member_node.deleted_at is not null
      and member_node.deletion_batch_id is not null
    group by member_node.deletion_batch_id
  ),
  batch_sizes as (
    select
      member_node.deletion_batch_id,
      coalesce(sum(version.byte_size), 0)::bigint as byte_size
    from public.document_nodes member_node
    join public.document_versions version
      on version.node_id = member_node.id
    where member_node.workspace_id = p_workspace_id
      and member_node.deleted_at is not null
      and member_node.deletion_batch_id is not null
      and version.upload_state in ('active', 'purge_pending')
    group by member_node.deletion_batch_id
  ),
  summarized as (
    select
      root.deletion_batch_id,
      root.id as root_node_id,
      root.kind,
      root.display_name,
      root.deleted_by,
      coalesce(nullif(member.display_name, ''), 'Unknown user') as deleted_by_name,
      root.deleted_at,
      root.parent_node_id,
      parent.display_name as original_parent_name,
      batch_counts.item_count,
      coalesce(batch_sizes.byte_size, 0)::bigint as byte_size
    from roots root
    left join public.document_nodes parent
      on parent.id = root.parent_node_id
      and parent.workspace_id = root.workspace_id
    left join public.organization_members member
      on member.organization_id = root.organization_id
      and member.user_id = root.deleted_by
    join batch_counts
      on batch_counts.deletion_batch_id = root.deletion_batch_id
    left join batch_sizes
      on batch_sizes.deletion_batch_id = root.deletion_batch_id
    where (
      normalized_search is null
      or exists (
        select 1
        from public.document_nodes member_node
        where member_node.workspace_id = root.workspace_id
          and member_node.deletion_batch_id = root.deletion_batch_id
          and member_node.normalized_name like '%' || normalized_search || '%'
      )
    )
    and (
      normalized_type = 'all'
      or (normalized_type = 'folders' and root.kind = 'folder')
      or exists (
        select 1
        from public.document_nodes member_node
        join public.document_versions version
          on version.node_id = member_node.id
        where member_node.workspace_id = root.workspace_id
          and member_node.deletion_batch_id = root.deletion_batch_id
          and member_node.kind = 'file'
          and case normalized_type
            when 'pdf' then version.file_extension = 'pdf'
            when 'images' then version.file_extension in ('jpg', 'jpeg', 'png', 'webp')
            when 'documents' then version.file_extension in ('doc', 'docx')
            when 'spreadsheets' then version.file_extension in ('xls', 'xlsx', 'csv')
            when 'presentations' then version.file_extension in ('ppt', 'pptx')
            when 'text' then version.file_extension = 'txt'
            when 'other' then version.file_extension not in (
              'pdf', 'jpg', 'jpeg', 'png', 'webp', 'doc', 'docx',
              'xls', 'xlsx', 'csv', 'ppt', 'pptx', 'txt'
            )
            else false
          end
      )
    )
  )
  select
    summarized.deletion_batch_id,
    summarized.root_node_id,
    summarized.kind,
    summarized.display_name,
    summarized.deleted_by,
    summarized.deleted_by_name,
    summarized.deleted_at,
    summarized.parent_node_id,
    summarized.original_parent_name,
    summarized.item_count,
    summarized.byte_size,
    count(*) over()
  from summarized
  order by
    case when normalized_sort = 'name' and normalized_direction = 'asc'
      then lower(summarized.display_name) end asc,
    case when normalized_sort = 'name' and normalized_direction = 'desc'
      then lower(summarized.display_name) end desc,
    case when normalized_sort = 'modified' and normalized_direction = 'asc'
      then summarized.deleted_at end asc,
    case when normalized_sort = 'modified' and normalized_direction = 'desc'
      then summarized.deleted_at end desc,
    case when normalized_sort = 'owner' and normalized_direction = 'asc'
      then lower(summarized.deleted_by_name) end asc,
    case when normalized_sort = 'owner' and normalized_direction = 'desc'
      then lower(summarized.deleted_by_name) end desc,
    case when normalized_sort = 'size' and normalized_direction = 'asc'
      then summarized.byte_size end asc,
    case when normalized_sort = 'size' and normalized_direction = 'desc'
      then summarized.byte_size end desc,
    summarized.root_node_id
  limit p_limit
  offset p_offset;
end;
$$;


ALTER FUNCTION "public"."list_deleted_document_batches"("p_workspace_id" "uuid", "p_search" "text", "p_file_type" "text", "p_sort" "text", "p_direction" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_document_workspace_folders"("p_workspace_id" "uuid") RETURNS TABLE("node_id" "uuid", "parent_node_id" "uuid", "display_name" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  perform public.assert_document_workspace_permission(p_workspace_id, 'files.view');

  return query
  select folder.id, folder.parent_node_id, folder.display_name
  from public.document_nodes folder
  where folder.workspace_id = p_workspace_id
    and folder.kind = 'folder'
    and folder.lifecycle_state = 'active'
    and folder.deleted_at is null
  order by folder.normalized_name, folder.id
  limit 1000;
end;
$$;


ALTER FUNCTION "public"."list_document_workspace_folders"("p_workspace_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_document_workspace_nodes"("p_workspace_id" "uuid", "p_parent_node_id" "uuid" DEFAULT NULL::"uuid", "p_search" "text" DEFAULT NULL::"text", "p_file_type" "text" DEFAULT 'all'::"text", "p_sort" "text" DEFAULT 'name'::"text", "p_direction" "text" DEFAULT 'asc'::"text", "p_limit" integer DEFAULT 100, "p_offset" integer DEFAULT 0) RETURNS TABLE("node_id" "uuid", "kind" "text", "display_name" "text", "parent_node_id" "uuid", "owner_user_id" "uuid", "owner_name" "text", "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "byte_size" bigint, "mime_type" "text", "file_extension" "text", "version_number" integer, "upload_state" "text", "sha256_checksum" "text", "parent_name" "text", "total_count" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  normalized_search text := nullif(lower(btrim(coalesce(p_search, ''))), '');
  normalized_type text := lower(btrim(coalesce(p_file_type, 'all')));
  normalized_sort text := lower(btrim(coalesce(p_sort, 'name')));
  normalized_direction text := lower(btrim(coalesce(p_direction, 'asc')));
begin
  perform public.assert_document_workspace_permission(p_workspace_id, 'files.view');

  if p_limit < 1 or p_limit > 200 or p_offset < 0 then
    raise exception 'Invalid document listing page.';
  end if;
  if normalized_type not in (
    'all', 'folders', 'pdf', 'images', 'documents', 'spreadsheets',
    'presentations', 'text', 'other'
  ) then
    raise exception 'Invalid document file-type filter.';
  end if;
  if normalized_sort not in ('name', 'modified', 'owner', 'size')
    or normalized_direction not in ('asc', 'desc')
  then
    raise exception 'Invalid document sort.';
  end if;

  if normalized_search is null and p_parent_node_id is not null
    and not exists (
      select 1
      from public.document_nodes parent
      where parent.workspace_id = p_workspace_id
        and parent.id = p_parent_node_id
        and parent.kind = 'folder'
        and parent.lifecycle_state = 'active'
        and parent.deleted_at is null
    )
  then
    raise exception 'Document folder not found.';
  end if;

  return query
  select
    node.id,
    node.kind,
    node.display_name,
    node.parent_node_id,
    node.created_by,
    coalesce(nullif(member.display_name, ''), 'Unknown user'),
    node.created_at,
    node.updated_at,
    version.byte_size,
    coalesce(version.verified_mime_type, version.claimed_mime_type),
    version.file_extension,
    version.version_number,
    version.upload_state,
    version.sha256_checksum,
    parent.display_name,
    count(*) over()
  from public.document_nodes node
  left join public.document_versions version
    on version.id = node.current_version_id
    and version.organization_id = node.organization_id
    and version.workspace_id = node.workspace_id
    and version.node_id = node.id
  left join public.organization_members member
    on member.organization_id = node.organization_id
    and member.user_id = node.created_by
  left join public.document_nodes parent
    on parent.organization_id = node.organization_id
    and parent.workspace_id = node.workspace_id
    and parent.id = node.parent_node_id
  where node.workspace_id = p_workspace_id
    and node.deleted_at is null
    and node.lifecycle_state = 'active'
    and (node.kind = 'folder' or (
      node.kind = 'file'
      and version.upload_state = 'active'
      and version.id = node.current_version_id
    ))
    and (
      (normalized_search is null and node.parent_node_id is not distinct from p_parent_node_id)
      or
      (normalized_search is not null and node.normalized_name like '%' || normalized_search || '%')
    )
    and (
      normalized_type = 'all'
      or (normalized_type = 'folders' and node.kind = 'folder')
      or (node.kind = 'file' and case normalized_type
        when 'pdf' then version.file_extension = 'pdf'
        when 'images' then version.file_extension in ('jpg', 'jpeg', 'png', 'webp')
        when 'documents' then version.file_extension in ('doc', 'docx')
        when 'spreadsheets' then version.file_extension in ('xls', 'xlsx', 'csv')
        when 'presentations' then version.file_extension in ('ppt', 'pptx')
        when 'text' then version.file_extension = 'txt'
        when 'other' then version.file_extension not in (
          'pdf', 'jpg', 'jpeg', 'png', 'webp', 'doc', 'docx',
          'xls', 'xlsx', 'csv', 'ppt', 'pptx', 'txt'
        )
        else false
      end)
    )
  order by
    case when normalized_sort = 'name' and normalized_direction = 'asc'
      then node.normalized_name end asc,
    case when normalized_sort = 'name' and normalized_direction = 'desc'
      then node.normalized_name end desc,
    case when normalized_sort = 'modified' and normalized_direction = 'asc'
      then node.updated_at end asc,
    case when normalized_sort = 'modified' and normalized_direction = 'desc'
      then node.updated_at end desc,
    case when normalized_sort = 'owner' and normalized_direction = 'asc'
      then lower(coalesce(member.display_name, '')) end asc,
    case when normalized_sort = 'owner' and normalized_direction = 'desc'
      then lower(coalesce(member.display_name, '')) end desc,
    case when normalized_sort = 'size' and normalized_direction = 'asc'
      then version.byte_size end asc nulls first,
    case when normalized_sort = 'size' and normalized_direction = 'desc'
      then version.byte_size end desc nulls last,
    node.id
  limit p_limit
  offset p_offset;
end;
$$;


ALTER FUNCTION "public"."list_document_workspace_nodes"("p_workspace_id" "uuid", "p_parent_node_id" "uuid", "p_search" "text", "p_file_type" "text", "p_sort" "text", "p_direction" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_mobile_project_purchase_orders_v2"("p_project_id" "uuid") RETURNS TABLE("purchase_order_id" "uuid", "project_id" "uuid", "purchase_order_number" "text", "purchase_order_title" "text", "status" "text", "origin" "text", "requested_by" "text", "requested_date" "date", "due_date" "date", "notes" "text", "issued_to_label" "text", "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
declare
  current_context record;
begin
  select *
  into current_context
  from public.resolve_mobile_project_member_context_v2(p_project_id);

  return query
  select
    po.id as purchase_order_id,
    po.project_id,
    po.purchase_order_number,
    po.purchase_order_title,
    po.status,
    po.origin,
    po.requested_by,
    po.requested_date,
    po.due_date,
    po.notes,
    po.issued_to_label,
    po.created_at,
    po.updated_at
  from public.project_purchase_orders po
  where po.organization_id = current_context.organization_id
    and po.project_id = p_project_id
  order by po.created_at desc;
end;
$$;


