CREATE OR REPLACE FUNCTION "public"."list_mobile_worker_project_purchase_orders"("p_project_id" "uuid") RETURNS TABLE("purchase_order_id" "uuid", "project_id" "uuid", "purchase_order_number" "text", "purchase_order_title" "text", "status" "text", "origin" "text", "requested_by" "text", "requested_date" "date", "due_date" "date", "notes" "text", "issued_to_label" "text", "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
declare
  current_context record;
begin
  select *
  into current_context
  from public.resolve_mobile_worker_project_context(p_project_id);

  return query
  select
    po.id as purchase_order_id,
    po.project_id,
    po.purchase_order_number,
    po.purchase_order_title,
    po.status,
    po.origin,
    po.requested_by,
    po.requested_date,
    po.due_date,
    po.notes,
    po.issued_to_label,
