CREATE OR REPLACE FUNCTION "public"."list_project_retention_claims"("p_project_id" "uuid", "p_limit" integer DEFAULT 50, "p_before_created_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_before_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_context jsonb;
  v_limit integer := greatest(1, least(coalesce(p_limit, 50), 200));
  v_rows jsonb;
  v_has_more boolean;
  v_cursor jsonb;
begin
  v_context := private.retention_claim_operation_context(
    p_project_id,
    'retention.view',
    false
  );
  if not coalesce((v_context ->> 'succeeded')::boolean, false) then
    return v_context || jsonb_build_object('claims', '[]'::jsonb, 'hasMore', false);
  end if;

  with filtered as (
    select claim.*
    from public.retention_claims claim
    where claim.organization_id = (v_context ->> 'organizationId')::uuid
      and claim.project_id = p_project_id
      and (
        p_before_id is null
        or claim.created_at < p_before_created_at
        or (
          claim.created_at = p_before_created_at
          and claim.id < p_before_id
        )
      )
    order by claim.created_at desc, claim.id desc
    limit v_limit + 1
  ),
  page as (
    select *
    from filtered
    order by created_at desc, id desc
    limit v_limit
  )
  select
    coalesce(
      jsonb_agg(
        private.retention_claim_header_json(page.id)
        order by page.created_at desc, page.id desc
      ),
      '[]'::jsonb
    ),
    (select count(*) > v_limit from filtered),
    (
      select jsonb_build_object(
        'createdAt', last_claim.created_at,
        'id', last_claim.id
      )
      from (
        select *
        from page
        order by created_at asc, id asc
        limit 1
      ) last_claim
    )
  into v_rows, v_has_more, v_cursor
  from page;

  return jsonb_build_object(
    'succeeded', true,
    'errorCode', null,
    'claims', v_rows,
    'hasMore', v_has_more,
    'nextCursor', case when v_has_more then v_cursor else null end
  );
end;
$$;


ALTER FUNCTION "public"."list_project_retention_claims"("p_project_id" "uuid", "p_limit" integer, "p_before_created_at" timestamp with time zone, "p_before_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_project_retention_legacy_reconciliation_cases"("p_project_id" "uuid", "p_limit" integer DEFAULT 100, "p_before_sequence" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare ctx jsonb;
begin
  ctx:=private.retention_phase6_context(p_project_id,'retention.view',false);
  if not coalesce((ctx->>'succeeded')::boolean,false) then return ctx; end if;
  return jsonb_build_object('succeeded',true,'errorCode',null,'cases',coalesce((
    select jsonb_agg(private.retention_legacy_case_json(x.id)
      order by x.case_sequence desc,x.id desc)
    from (
      select c.id,c.case_sequence
      from public.retention_legacy_reconciliation_cases c
      where c.project_id=p_project_id
        and (p_before_sequence is null or c.case_sequence<p_before_sequence)
      order by c.case_sequence desc,c.id desc
      limit least(greatest(coalesce(p_limit,100),1),500)
    ) x
  ),'[]'::jsonb));
end;
$$;


ALTER FUNCTION "public"."list_project_retention_legacy_reconciliation_cases"("p_project_id" "uuid", "p_limit" integer, "p_before_sequence" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_project_retention_variances"("p_project_id" "uuid", "p_limit" integer DEFAULT 100, "p_after_detected_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_after_id" "uuid" DEFAULT NULL::"uuid", "p_states" "text"[] DEFAULT NULL::"text"[], "p_blocking" boolean DEFAULT NULL::boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare ctx jsonb;
begin
  ctx:=private.retention_phase5_context(p_project_id,'retention.variances.view',false);
  if not coalesce((ctx->>'succeeded')::boolean,false) then return ctx; end if;
  return jsonb_build_object('succeeded',true,'errorCode',null,'variances',coalesce((
    select jsonb_agg(private.retention_variance_read_json(q.id)
      order by q.last_detected_at desc,q.id desc)
    from (
      select v.id,v.last_detected_at from public.retention_variances v
      where v.project_id=p_project_id
        and (p_states is null or v.state=any(p_states))
        and (p_blocking is null or v.is_blocking=p_blocking)
        and (p_after_detected_at is null or
          (v.last_detected_at,v.id)<(p_after_detected_at,p_after_id))
      order by v.last_detected_at desc,v.id desc
      limit least(greatest(coalesce(p_limit,100),1),500)
    ) q
  ),'[]'::jsonb),'nextCursor',(
    select jsonb_build_object('lastDetectedAt',q.last_detected_at,'id',q.id)
    from (
      select v.id,v.last_detected_at from public.retention_variances v
      where v.project_id=p_project_id
        and (p_states is null or v.state=any(p_states))
        and (p_blocking is null or v.is_blocking=p_blocking)
        and (p_after_detected_at is null or
          (v.last_detected_at,v.id)<(p_after_detected_at,p_after_id))
      order by v.last_detected_at desc,v.id desc
      limit least(greatest(coalesce(p_limit,100),1),500)
    ) q order by q.last_detected_at,q.id limit 1
  ));
end;
$$;


