CREATE OR REPLACE FUNCTION "public"."list_worker_assigned_purchase_orders"("p_organization_id" "uuid", "p_project_id" "uuid", "p_organization_member_id" "uuid") RETURNS TABLE("id" "uuid", "purchase_order_number" "text", "title" "text", "status" "text", "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if auth.uid() is null then
    raise exception 'Authentication is required';
  end if;

  if not public.is_member_of_organization(p_organization_id) then
    raise exception 'Not authorized for this organization';
  end if;

  if not exists (
    select 1
    from public.organization_projects p
    where p.id = p_project_id
      and p.organization_id = p_organization_id
  ) then
    raise exception 'Project not found for organization';
  end if;

  return query
  select
    po.id,
    po.purchase_order_number,
    po.purchase_order_title as title,
    po.status,
    po.created_at
  from public.project_purchase_order_assignments a
  join public.project_purchase_orders po
    on po.id = a.purchase_order_id
  where a.organization_id = p_organization_id
    and a.project_id = p_project_id
    and a.organization_member_id = p_organization_member_id
    and a.is_active = true
    and po.organization_id = p_organization_id
    and po.project_id = p_project_id
  order by po.created_at desc;
end;
$$;


ALTER FUNCTION "public"."list_worker_assigned_purchase_orders"("p_organization_id" "uuid", "p_project_id" "uuid", "p_organization_member_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."log_organization_invite_audit"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  event_name text;
  payload jsonb;
begin
  if tg_op = 'INSERT' then
    event_name := 'created';
    payload := jsonb_build_object(
      'invited_email', new.invited_email,
      'role', new.role,
      'status', new.status,
      'expires_at', new.expires_at
    );

    insert into public.organization_invite_audit_logs (organization_id, invite_id, actor_user_id, event_type, details)
    values (new.organization_id, new.id, auth.uid(), event_name, payload);
    return new;
  elsif tg_op = 'UPDATE' then
    if old.role is distinct from new.role then
      event_name := 'role_changed';
    elsif old.expires_at is distinct from new.expires_at and new.status = 'pending' then
      event_name := 'resent';
    elsif old.status is distinct from new.status then
      event_name := 'status_changed';
    else
      event_name := 'updated';
    end if;

    payload := jsonb_build_object(
      'from', jsonb_build_object('role', old.role, 'status', old.status, 'expires_at', old.expires_at),
      'to', jsonb_build_object('role', new.role, 'status', new.status, 'expires_at', new.expires_at),
      'invited_email', new.invited_email
    );

    insert into public.organization_invite_audit_logs (organization_id, invite_id, actor_user_id, event_type, details)
    values (new.organization_id, new.id, auth.uid(), event_name, payload);
    return new;
  elsif tg_op = 'DELETE' then
    event_name := 'deleted';
    payload := jsonb_build_object(
      'deleted_invite_id', old.id,
      'invited_email', old.invited_email,
      'role', old.role,
      'status', old.status
    );

    -- critical fix
    insert into public.organization_invite_audit_logs (organization_id, invite_id, actor_user_id, event_type, details)
    values (old.organization_id, null, auth.uid(), event_name, payload);

    return old;
  end if;

  return null;
end;
$$;


ALTER FUNCTION "public"."log_organization_invite_audit"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."log_supplier_invoice_approval_step"() RETURNS "trigger"
