CREATE OR REPLACE FUNCTION "public"."log_supplier_invoice_changes"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  changed_fields text[] := array[]::text[];
  material_fields text[] := array[]::text[];
begin
  if tg_op = 'INSERT' then
    perform public.record_supplier_invoice_activity_event(
      new.organization_id,
      new.id,
      'created',
      case
        when coalesce(trim(new.invoice_number), '') <> '' then format('Supplier invoice %s created.', new.invoice_number)
        else 'Supplier invoice created.'
      end,
      jsonb_build_object(
        'status', new.status,
        'supplier_id', new.supplier_id
      ),
      new.created_by
    );
    return new;
  end if;

  if new.supplier_id is distinct from old.supplier_id then
    changed_fields := array_append(changed_fields, 'supplier');
    material_fields := array_append(material_fields, 'supplier');
  end if;
  if new.invoice_number is distinct from old.invoice_number then
    changed_fields := array_append(changed_fields, 'invoice_number');
  end if;
  if new.invoice_date is distinct from old.invoice_date then
    changed_fields := array_append(changed_fields, 'invoice_date');
    material_fields := array_append(material_fields, 'invoice_date');
  end if;
  if new.due_date is distinct from old.due_date then
    changed_fields := array_append(changed_fields, 'due_date');
    material_fields := array_append(material_fields, 'due_date');
  end if;
  if new.subtotal is distinct from old.subtotal then
    changed_fields := array_append(changed_fields, 'subtotal');
    material_fields := array_append(material_fields, 'subtotal');
  end if;
  if new.tax_total is distinct from old.tax_total then
    changed_fields := array_append(changed_fields, 'tax_total');
    material_fields := array_append(material_fields, 'tax_total');
  end if;
  if new.total is distinct from old.total then
    changed_fields := array_append(changed_fields, 'total');
    material_fields := array_append(material_fields, 'total');
  end if;
  if new.notes is distinct from old.notes then
    changed_fields := array_append(changed_fields, 'notes');
  end if;

  if array_length(changed_fields, 1) is not null then
    perform public.record_supplier_invoice_activity_event(
      new.organization_id,
      new.id,
      'edited',
      'Supplier invoice details updated.',
      jsonb_build_object('changed_fields', changed_fields),
      auth.uid()
    );
  end if;

  if new.status is distinct from old.status then
    if old.status = 'Approved'
      and new.status = 'Needs Review'
      and array_length(material_fields, 1) is not null then
      perform public.record_supplier_invoice_activity_event(
        new.organization_id,
        new.id,
        'reverted_to_needs_review',
        'Invoice changes require the invoice to be reviewed again.',
        jsonb_build_object(
          'changed_fields', material_fields,
          'from_status', old.status,
          'to_status', new.status
        ),
        auth.uid()
      );
    elsif new.status = 'Needs Review' and old.status <> 'Approved' then
      perform public.record_supplier_invoice_activity_event(
        new.organization_id,
        new.id,
        'sent_for_review',
        'Supplier invoice sent to review.',
        jsonb_build_object('from_status', old.status, 'to_status', new.status),
        auth.uid()
      );
    elsif new.status = 'Approved' then
      perform public.record_supplier_invoice_activity_event(
        new.organization_id,
        new.id,
        'approved',
        'Supplier invoice approved.',
        jsonb_build_object('from_status', old.status, 'to_status', new.status),
        auth.uid()
      );
    elsif new.status = 'Disputed' then
      perform public.record_supplier_invoice_activity_event(
        new.organization_id,
        new.id,
        'disputed',
        'Supplier invoice marked disputed.',
        jsonb_build_object('from_status', old.status, 'to_status', new.status),
        auth.uid()
      );
    else
      perform public.record_supplier_invoice_activity_event(
        new.organization_id,
        new.id,
        'status_changed',
        format('Supplier invoice status changed from %s to %s.', old.status, new.status),
        jsonb_build_object('from_status', old.status, 'to_status', new.status),
        auth.uid()
      );
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."log_supplier_invoice_changes"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."make_project_qa_ready_v1"("p_organization_id" "uuid", "p_project_id" "uuid", "p_project_qa_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare qa_row public.project_qas%rowtype; section_count integer; field_count integer; current_sections jsonb;
begin
  if auth.uid() is null or not public.can_access_qa_project(p_organization_id,p_project_id,'qa.write') then
    raise exception 'Not authorized' using errcode='42501';
  end if;
  select * into qa_row from public.project_qas
  where organization_id=p_organization_id and project_id=p_project_id and id=p_project_qa_id for update;
  if not found then raise exception 'Project QA not found' using errcode='TS404'; end if;
  if qa_row.status <> 'draft' then raise exception 'Only a Draft Project QA can be made Ready' using errcode='TS409'; end if;
  select count(*) into section_count from public.project_qa_sections
    where organization_id=p_organization_id and project_id=p_project_id and project_qa_id=p_project_qa_id;
  select count(*) into field_count from public.project_qa_fields
    where organization_id=p_organization_id and project_id=p_project_id and project_qa_id=p_project_qa_id;
  if section_count = 0 and field_count = 0 then
    raise exception E'Cannot make this QA ready yet.\n- Add at least one section.\n- Add at least one QA field.' using errcode='TS422';
  elsif section_count = 0 then
    raise exception E'Cannot make this QA ready yet.\n- Add at least one section.' using errcode='TS422';
  elsif field_count = 0 then
    raise exception E'Cannot make this QA ready yet.\n- Add at least one QA field.' using errcode='TS422';
  end if;
  select coalesce(jsonb_agg(jsonb_build_object(
    'id',s.id,'title',s.title,
    'fields',coalesce((select jsonb_agg(jsonb_build_object(
      'id',f.id,'fieldType',f.field_type,'label',f.label,'minimumPhotos',f.minimum_photos,
      'options',coalesce((select jsonb_agg(jsonb_build_object('id',o.id,'label',o.label,'value',o.value))
        from public.project_qa_field_options o
        where o.organization_id=p_organization_id and o.project_id=p_project_id
          and o.project_qa_id=p_project_qa_id and o.field_id=f.id),'[]'::jsonb)
    ) order by f.sort_order,f.id) from public.project_qa_fields f
      where f.organization_id=p_organization_id and f.project_id=p_project_id
        and f.project_qa_id=p_project_qa_id and f.section_id=s.id),'[]'::jsonb)
  ) order by s.sort_order,s.id),'[]'::jsonb) into current_sections
  from public.project_qa_sections s
  where s.organization_id=p_organization_id and s.project_id=p_project_id and s.project_qa_id=p_project_qa_id;
  perform public.qa_assert_definition(current_sections);
  if exists (
    select 1 from public.project_qa_fields f
    where f.organization_id=p_organization_id and f.project_id=p_project_id and f.project_qa_id=p_project_qa_id
      and f.field_type='measurement' and (
        (f.configuration ? 'minimum' and f.configuration->'minimum'<>'null'::jsonb and jsonb_typeof(f.configuration->'minimum')<>'number')
        or (f.configuration ? 'maximum' and f.configuration->'maximum'<>'null'::jsonb and jsonb_typeof(f.configuration->'maximum')<>'number')
        or (f.configuration ? 'tolerance' and f.configuration->'tolerance'<>'null'::jsonb and jsonb_typeof(f.configuration->'tolerance')<>'number')
        or (jsonb_typeof(f.configuration->'minimum')='number' and jsonb_typeof(f.configuration->'maximum')='number'
          and (f.configuration->>'minimum')::numeric>(f.configuration->>'maximum')::numeric)
        or (jsonb_typeof(f.configuration->'tolerance')='number' and (f.configuration->>'tolerance')::numeric<0)
      )
  ) then
    raise exception E'Cannot make this QA ready yet.\n- Correct invalid measurement limits.' using errcode='TS422';
  end if;
  update public.project_qas set status='active',archived_at=null,updated_by=auth.uid()
  where organization_id=p_organization_id and project_id=p_project_id and id=p_project_qa_id;
  return qa_row.definition_version;
end; $$;


ALTER FUNCTION "public"."make_project_qa_ready_v1"("p_organization_id" "uuid", "p_project_id" "uuid", "p_project_qa_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mark_document_upload_failed"("p_version_id" "uuid", "p_failure_code" "text", "p_failure_message" "text", "p_abandon" boolean DEFAULT false) RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  caller_id uuid := auth.uid();
  version_row public.document_versions%rowtype;
  next_state text := case when p_abandon then 'abandoned' else 'failed' end;
begin
  if caller_id is null then
    raise exception 'Unauthorized.';
  end if;

  select version.*
  into version_row
  from public.document_versions version
  where version.id = p_version_id
  for update;

  if not found
    or version_row.uploaded_by <> caller_id
    or not public.has_org_permission(version_row.organization_id, 'files.write')
  then
    raise exception 'Pending upload not found or access denied.';
  end if;

  if version_row.upload_state in ('failed', 'abandoned') then
    return version_row.upload_state;
  end if;

  if version_row.upload_state <> 'pending' then
    raise exception 'Only pending uploads can be failed or abandoned.';
  end if;

  update public.document_versions version
  set
    upload_state = next_state,
    failed_at = case when next_state = 'failed' then now() else null end,
    abandoned_at = case when next_state = 'abandoned' then now() else null end,
    failure_code = left(nullif(btrim(p_failure_code), ''), 100),
    failure_message = left(nullif(btrim(p_failure_message), ''), 1000)
  where version.id = version_row.id;

  if version_row.replaces_version_id is null then
    update public.document_nodes node
    set
      lifecycle_state = 'abandoned',
      updated_by = caller_id,
      updated_at = now()
    where node.id = version_row.node_id
      and node.current_version_id is null;
  end if;

  insert into public.document_storage_cleanup_jobs (
    organization_id,
    workspace_id,
    version_id,
    job_type,
    job_identity,
    storage_key
  )
  values (
    version_row.organization_id,
    version_row.workspace_id,
    version_row.id,
    'abandoned_upload',
    'document-version:' || version_row.id::text || ':abandoned-upload',
    version_row.storage_key
  )
  on conflict (job_identity) do nothing;

  return next_state;
end;
$$;


ALTER FUNCTION "public"."mark_document_upload_failed"("p_version_id" "uuid", "p_failure_code" "text", "p_failure_message" "text", "p_abandon" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mark_project_quote_pricing_basis_stale_from_line_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  target_line public.project_quote_line_items%rowtype := case when tg_op = 'DELETE' then old else new end;
begin
  update public.project_quotes quote
  set pricing_basis_status = 'stale',
      pricing_basis_checked_at = timezone('utc', now())
  where quote.organization_id = target_line.organization_id
    and quote.id = target_line.quote_id
    and quote.award_locked_at is null
    and quote.pricing_basis_status = 'current';
  return case when tg_op = 'DELETE' then old else new end;
end;
$$;


ALTER FUNCTION "public"."mark_project_quote_pricing_basis_stale_from_line_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mark_project_quote_pricing_basis_stale_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  target_workbook_id uuid;
begin
  if tg_table_name = 'opportunity_pricing_workbook_sheets' then
    target_workbook_id := nullif(to_jsonb(new)->>'workbook_id', '')::uuid;
  else
    target_workbook_id := new.id;
  end if;

  update public.project_quotes quote
  set pricing_basis_status = 'stale',
      pricing_basis_checked_at = timezone('utc', now())
  where quote.organization_id = new.organization_id
    and quote.award_locked_at is null
    and quote.pricing_basis_status = 'current'
    and quote.publication_basis_json->'workbookIds' @> jsonb_build_array(target_workbook_id::text);

  return new;
end;
$$;


ALTER FUNCTION "public"."mark_project_quote_pricing_basis_stale_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."materials_phase1f_add_price_internal"("p_organization_id" "uuid", "p_supplier_product_id" "uuid", "p_unit_cost" numeric, "p_currency" "text", "p_effective_from" timestamp with time zone, "p_effective_was_explicit" boolean, "p_source" "text", "p_idempotency_key" "text", "p_import_batch_id" "uuid", "p_import_row_id" "uuid", "p_observation_metadata" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_product public.organization_material_supplier_products%rowtype;
  v_existing public.organization_material_supplier_prices%rowtype;
  v_current public.organization_material_supplier_prices%rowtype;
  v_new public.organization_material_supplier_prices%rowtype;
  v_currency text := pg_catalog.upper(pg_catalog.btrim(p_currency));
  v_key text := pg_catalog.btrim(p_idempotency_key);
  v_now timestamptz := statement_timestamp();
  v_constraint_name text;
begin
  if p_unit_cost is null or p_unit_cost < 0 then
    perform public.materials_phase1f_error('invalid_price');
  end if;
  if v_currency is null or v_currency = '' then
    perform public.materials_phase1f_error('invalid_currency');
  end if;
  if v_key is null or v_key = '' then
    perform public.materials_phase1f_error('idempotency_key_required');
  end if;
  if p_source not in ('manual', 'import', 'supplier_invoice', 'purchase_order', 'api') then
    perform public.materials_phase1f_error('invalid_source');
  end if;

  select * into v_product
  from public.organization_material_supplier_products
  where organization_id = p_organization_id and id = p_supplier_product_id
  for update;
  if not found then
    perform public.materials_phase1f_error('supplier_product_not_found');
  end if;
  if not v_product.is_active or v_product.archived_at is not null then
    perform public.materials_phase1f_error('supplier_product_inactive');
  end if;

  select * into v_existing
  from public.organization_material_supplier_prices
  where organization_id = p_organization_id
    and supplier_product_id = p_supplier_product_id
    and idempotency_key = v_key;

  if v_existing.id is not null then
    if v_existing.unit_cost is distinct from p_unit_cost
      or v_existing.currency is distinct from v_currency
      or (p_effective_was_explicit and v_existing.effective_from is distinct from p_effective_from)
      or v_existing.source is distinct from p_source
      or v_existing.import_batch_id is distinct from p_import_batch_id
      or v_existing.import_row_id is distinct from p_import_row_id then
      perform public.materials_phase1f_error('idempotency_conflict');
    end if;
    return pg_catalog.jsonb_build_object(
      'supplier_product_id', p_supplier_product_id,
      'price_id', v_existing.id,
      'idempotent_replay', true
    );
  end if;

  if p_effective_from > v_now + interval '1 second' then
    perform public.materials_phase1f_error('future_price_requires_read_cutover');
  end if;

  if p_import_batch_id is not null and not exists (
    select 1 from public.organization_material_import_batches
    where organization_id = p_organization_id and id = p_import_batch_id
  ) then
    perform public.materials_phase1f_error('organization_mismatch');
  end if;
  if p_import_row_id is not null and not exists (
    select 1 from public.organization_material_import_rows
    where organization_id = p_organization_id
      and id = p_import_row_id
      and (p_import_batch_id is null or import_batch_id = p_import_batch_id)
  ) then
    perform public.materials_phase1f_error('organization_mismatch');
  end if;

  select * into v_current
  from public.organization_material_supplier_prices
  where organization_id = p_organization_id
    and supplier_product_id = p_supplier_product_id
    and is_current = true
  order by effective_from desc, id
  limit 1
  for update;

  if v_current.id is not null and p_effective_from = v_current.effective_from then
    perform public.materials_phase1f_error('price_effective_start_conflict');
  end if;
  if v_current.id is not null and p_effective_from < v_current.effective_from then
    perform public.materials_phase1f_error('unsupported_backdated_price');
  end if;
  if v_current.id is null and exists (
    select 1 from public.organization_material_supplier_prices
    where organization_id = p_organization_id
      and supplier_product_id = p_supplier_product_id
      and effective_from > p_effective_from
  ) then
    perform public.materials_phase1f_error('unsupported_backdated_price');
  end if;

  if v_current.id is not null then
    begin
      update public.organization_material_supplier_prices
      set is_current = false,
          is_preferred = false,
          effective_to = p_effective_from
      where organization_id = p_organization_id and id = v_current.id;
    exception when exclusion_violation then
      perform public.materials_phase1f_error('price_interval_conflict');
    end;
  end if;

  if v_product.is_preferred then
    update public.organization_material_supplier_prices
    set is_preferred = false
    where organization_id = p_organization_id
      and material_id = v_product.material_id
      and is_current = true
      and is_preferred = true;
  end if;

  begin
    insert into public.organization_material_supplier_prices (
      organization_id, material_id, supplier_id, supplier_product_id,
      import_batch_id, import_row_id, supersedes_price_id, idempotency_key,
      supplier_sku, supplier_description, unit, unit_cost, currency,
      is_preferred, is_current, source, effective_from, effective_to,
      created_by, observation_metadata
    ) values (
      p_organization_id, v_product.material_id, v_product.supplier_id, v_product.id,
      p_import_batch_id, p_import_row_id, v_current.id, v_key,
      v_product.supplier_sku, v_product.supplier_description, v_product.supplier_unit,
      p_unit_cost, v_currency, v_product.is_preferred, true, p_source,
      p_effective_from, null, auth.uid(), p_observation_metadata
    ) returning * into v_new;
  exception
    when exclusion_violation then
      perform public.materials_phase1f_error('price_interval_conflict');
    when unique_violation then
      get stacked diagnostics v_constraint_name = CONSTRAINT_NAME;
      if v_constraint_name = 'organization_material_supplier_prices_current_product_key' then
        perform public.materials_phase1f_error('current_price_identity_conflict');
      end if;
      perform public.materials_phase1f_error('constraint_failure');
  end;

  return pg_catalog.jsonb_build_object(
    'supplier_product_id', v_product.id,
    'price_id', v_new.id,
    'supersedes_price_id', v_new.supersedes_price_id,
    'idempotent_replay', false
  );
end;
$$;


ALTER FUNCTION "public"."materials_phase1f_add_price_internal"("p_organization_id" "uuid", "p_supplier_product_id" "uuid", "p_unit_cost" numeric, "p_currency" "text", "p_effective_from" timestamp with time zone, "p_effective_was_explicit" boolean, "p_source" "text", "p_idempotency_key" "text", "p_import_batch_id" "uuid", "p_import_row_id" "uuid", "p_observation_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."materials_phase1f_error"("p_code" "text") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  raise exception using
    errcode = 'P0001',
    message = 'materials_phase1f:' || p_code;
end;
$$;


ALTER FUNCTION "public"."materials_phase1f_error"("p_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."materials_phase1f_require_writer"("p_organization_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_actor uuid := auth.uid();
begin
  if v_actor is null or not public.has_org_permission(p_organization_id, 'materials.write') then
    perform public.materials_phase1f_error('permission_denied');
  end if;
  return v_actor;
end;
$$;


ALTER FUNCTION "public"."materials_phase1f_require_writer"("p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."materials_phase1f_set_preferred_internal"("p_organization_id" "uuid", "p_material_id" "uuid", "p_supplier_product_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_product public.organization_material_supplier_products%rowtype;
  v_price_id uuid;
begin
  perform 1
  from public.organization_materials
  where organization_id = p_organization_id and id = p_material_id
  for update;
  if not found then
    perform public.materials_phase1f_error('material_not_found');
  end if;

  select * into v_product
  from public.organization_material_supplier_products
  where organization_id = p_organization_id and id = p_supplier_product_id
  for update;
  if not found then
    perform public.materials_phase1f_error('supplier_product_not_found');
  end if;
  if v_product.material_id <> p_material_id then
    perform public.materials_phase1f_error('preferred_product_mismatch');
  end if;
  if not v_product.is_active or v_product.archived_at is not null then
    perform public.materials_phase1f_error('preferred_product_inactive');
  end if;

  update public.organization_material_supplier_products
  set is_preferred = false, updated_by = auth.uid()
  where organization_id = p_organization_id
    and material_id = p_material_id
    and is_preferred = true
    and id <> p_supplier_product_id;

  update public.organization_material_supplier_products
  set is_preferred = true, updated_by = auth.uid()
  where organization_id = p_organization_id and id = p_supplier_product_id;

  update public.organization_material_supplier_prices
  set is_preferred = false
  where organization_id = p_organization_id
    and material_id = p_material_id
    and is_current = true
    and is_preferred = true;

  select id into v_price_id
  from public.organization_material_supplier_prices
  where organization_id = p_organization_id
    and supplier_product_id = p_supplier_product_id
    and is_current = true
  order by effective_from desc, id
  limit 1
  for update;

  if v_price_id is not null then
    update public.organization_material_supplier_prices
    set is_preferred = true
    where organization_id = p_organization_id and id = v_price_id;
  end if;

  return pg_catalog.jsonb_build_object(
    'supplier_product_id', p_supplier_product_id,
    'material_id', p_material_id,
    'legacy_preferred_price_id', v_price_id
  );
end;
$$;


ALTER FUNCTION "public"."materials_phase1f_set_preferred_internal"("p_organization_id" "uuid", "p_material_id" "uuid", "p_supplier_product_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."materials_validate_price_tax_idempotency"("p_input" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_snapshot jsonb := p_input->'observation_metadata'->'tax_snapshot';
  v_existing public.organization_material_supplier_prices%rowtype;
begin
  if v_snapshot is null then return; end if;
  select * into v_existing
  from public.organization_material_supplier_prices price
  where price.organization_id = (p_input->>'organization_id')::uuid
    and (
      (p_input ? 'import_row_id' and price.import_row_id = (p_input->>'import_row_id')::uuid)
      or (not (p_input ? 'import_row_id') and price.idempotency_key = p_input->>'idempotency_key')
    )
    and (not (p_input ? 'supplier_product_id') or price.supplier_product_id = (p_input->>'supplier_product_id')::uuid)
  order by price.created_at desc limit 1;
  if v_existing.id is null then return; end if;
  if v_existing.source_tax_basis is distinct from coalesce(v_snapshot->>'sourceTaxBasis', 'unknown')
    or v_existing.source_tax_rate is distinct from nullif(v_snapshot->>'sourceTaxRate', '')::numeric
    or v_existing.tax_jurisdiction_code is distinct from nullif(v_snapshot->>'taxJurisdictionCode', '')
    or v_existing.comparison_tax_basis is distinct from nullif(v_snapshot->>'comparisonTaxBasis', '')
    or v_existing.comparison_tax_rate is distinct from nullif(v_snapshot->>'comparisonTaxRate', '')::numeric
    or v_existing.tax_policy_snapshot is distinct from coalesce(v_snapshot->'taxPolicySnapshot', '{}'::jsonb)
    or v_existing.tax_evidence is distinct from coalesce(v_snapshot->'taxEvidence', '{}'::jsonb) then
    perform public.materials_phase1f_error('idempotency_conflict');
  end if;
end;
$$;


ALTER FUNCTION "public"."materials_validate_price_tax_idempotency"("p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."materials_validate_price_tax_review_state"("p_input" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_snapshot jsonb := p_input #> '{observation_metadata,tax_snapshot}';
  v_review jsonb := p_input #> '{observation_metadata,tax_review}';
  v_basis text := v_snapshot->>'sourceTaxBasis';
  v_source_rate numeric := nullif(v_snapshot->>'sourceTaxRate', '')::numeric;
  v_comparison_rate numeric := nullif(v_snapshot->>'comparisonTaxRate', '')::numeric;
  v_complete boolean;
begin
  v_complete := v_snapshot is not null
    and v_basis in ('exclusive', 'inclusive', 'zero_rated', 'exempt', 'no_tax')
    and nullif(pg_catalog.btrim(v_snapshot->>'taxJurisdictionCode'), '') is not null
    and v_snapshot->>'comparisonTaxBasis' in ('exclusive', 'inclusive')
    and v_comparison_rate is not null
    and v_snapshot #>> '{taxPolicySnapshot,supportsInclusiveExclusive}' = 'true'
    and nullif(pg_catalog.btrim(v_snapshot #>> '{taxPolicySnapshot,policyId}'), '') is not null
    and v_snapshot #>> '{taxPolicySnapshot,jurisdictionCode}' = v_snapshot->>'taxJurisdictionCode'
    and v_snapshot #>> '{taxPolicySnapshot,comparisonBasis}' = v_snapshot->>'comparisonTaxBasis'
    and nullif(v_snapshot #>> '{taxPolicySnapshot,standardRate}', '')::numeric = v_comparison_rate
    and not (
      v_basis in ('exclusive', 'inclusive')
      and v_source_rate is not null
      and pg_catalog.abs(v_source_rate - v_comparison_rate) > 0.0001
    );

  if v_complete then
    if v_review is not null and coalesce(v_review->>'status', 'complete') <> 'complete' then
      perform public.materials_phase1f_error('tax_review_state_conflict');
    end if;
    return;
  end if;

  if v_review->>'status' <> 'needs_review'
    or coalesce((v_review->>'acknowledged')::boolean, false) is not true
    or nullif(pg_catalog.btrim(v_review->>'reason'), '') is null then
    perform public.materials_phase1f_error('incomplete_tax_review_acknowledgement_required');
  end if;
end;
$$;


ALTER FUNCTION "public"."materials_validate_price_tax_review_state"("p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mobile_mutate_project_purchase_order_manual_line_v2"("p_project_id" "uuid", "p_purchase_order_id" "uuid", "p_expected_updated_at" timestamp with time zone, "p_operation" "text", "p_line_id" "uuid", "p_section" "text", "p_description" "text", "p_quantity" numeric, "p_unit" "text", "p_rate" numeric) RETURNS TABLE("purchase_order_id" "uuid", "project_id" "uuid", "purchase_order_number" "text", "purchase_order_title" "text", "status" "text", "origin" "text", "requested_by" "text", "requested_date" "date", "due_date" "date", "notes" "text", "issued_to_label" "text", "supplier_contact" "text", "supplier_name_snapshot" "text", "supplier_email_snapshot" "text", "supplier_phone_snapshot" "text", "subtotal" numeric, "gst_total" numeric, "total_purchase_order_price" numeric, "line_items" "jsonb", "attachments" "jsonb", "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
declare
  current_context record;
  po_row public.project_purchase_orders%rowtype;
  target_line public.project_purchase_order_line_items%rowtype;
  mutable_line_items jsonb := '[]'::jsonb;
  preserved_attachments jsonb := '[]'::jsonb;
  next_line_id uuid;
  next_line_uid uuid;
  operation_normalized text := lower(coalesce(p_operation, ''));
  section_normalized text;
  description_normalized text;
  unit_normalized text;
  blocking_match_count integer := 0;
begin
  if auth.uid() is null then
    raise exception 'Authentication is required';
  end if;

  if p_expected_updated_at is null then
    raise exception 'Purchase order version is required. Please refresh and try again.'
      using errcode = '40001';
  end if;

  if operation_normalized not in ('add', 'update', 'delete') then
    raise exception 'Operation must be add, update, or delete';
  end if;

  select *
  into current_context
  from public.resolve_mobile_project_member_context_v2(p_project_id);

  if not public.has_org_permission(current_context.organization_id, 'purchase_orders.write') then
    raise exception 'Not authorized to edit purchase orders for this organization';
  end if;

  select *
  into po_row
  from public.project_purchase_orders po
  where po.organization_id = current_context.organization_id
    and po.project_id = p_project_id
    and po.id = p_purchase_order_id
  for update;

  if not found then
    raise exception 'Purchase order not found for this project';
  end if;

  if po_row.updated_at is distinct from p_expected_updated_at then
    raise exception 'This purchase order was updated by another user. Refresh and try again.'
      using errcode = '40001';
  end if;

  select count(*)::integer
  into blocking_match_count
  from public.supplier_invoice_purchase_order_matches m
  where m.organization_id = current_context.organization_id
    and m.purchase_order_id = p_purchase_order_id;

  if blocking_match_count > 0 then
    raise exception 'This purchase order has supplier invoice match activity and cannot be edited from mobile yet.';
  end if;

  if operation_normalized in ('update', 'delete') and p_line_id is null then
    raise exception 'Line id is required for update or delete';
  end if;

  if operation_normalized in ('add', 'update') then
    section_normalized := case
      when p_section in ('Labour', 'Materials', 'Subcontractors', 'Plant', 'Margin') then p_section
      else null
    end;

    if section_normalized is null then
      raise exception 'Section must be one of Labour, Materials, Subcontractors, Plant, or Margin';
    end if;

    if p_quantity is null then
      raise exception 'Quantity is required';
    end if;

    if p_rate is null then
      raise exception 'Rate is required';
    end if;

    description_normalized := coalesce(p_description, '');
    unit_normalized := coalesce(p_unit, '');
  end if;

  if operation_normalized in ('update', 'delete') then
    select *
    into target_line
    from public.project_purchase_order_line_items li
    where li.organization_id = current_context.organization_id
      and li.project_id = p_project_id
      and li.purchase_order_id = p_purchase_order_id
      and li.id = p_line_id;

    if not found then
      raise exception 'Line item not found for this purchase order';
    end if;

    if target_line.source_time_sheet_entry_id is not null then
      raise exception 'Timesheet-synced labour lines cannot be edited from mobile';
    end if;
  end if;

  select
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'id', li.id,
          'line_uid', li.line_uid,
          'cost_item_id', li.cost_item_id,
          'source_cost_item_id', li.source_cost_item_id,
          'section', li.section,
          'description', li.description,
          'quantity', li.quantity,
          'unit', li.unit,
          'rate', li.rate,
          'source_time_sheet_entry_id', li.source_time_sheet_entry_id
        )
        order by li.sort_order asc, li.created_at asc
      ),
      '[]'::jsonb
    )
  into mutable_line_items
  from public.project_purchase_order_line_items li
  where li.organization_id = current_context.organization_id
    and li.project_id = p_project_id
    and li.purchase_order_id = p_purchase_order_id;

  select
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'id', att.id,
          'name', att.file_name,
          'type', att.file_kind,
          'storagePath', att.storage_path,
          'externalUrl', att.external_url,
          'notes', att.notes
        )
        order by att.created_at asc
      ),
      '[]'::jsonb
    )
  into preserved_attachments
  from public.project_purchase_order_attachments att
  where att.organization_id = current_context.organization_id
    and att.project_id = p_project_id
    and att.purchase_order_id = p_purchase_order_id;

  if operation_normalized = 'add' then
    next_line_id := gen_random_uuid();
    next_line_uid := gen_random_uuid();

    mutable_line_items := mutable_line_items || jsonb_build_array(
      jsonb_build_object(
        'id', next_line_id,
        'line_uid', next_line_uid,
        'cost_item_id', null,
        'source_cost_item_id', null,
        'section', section_normalized,
        'description', description_normalized,
        'quantity', p_quantity,
        'unit', unit_normalized,
        'rate', p_rate,
        'source_time_sheet_entry_id', null
      )
    );
  elsif operation_normalized = 'update' then
    select coalesce(
      jsonb_agg(
        case
          when item->>'id' = p_line_id::text then
            jsonb_set(
              jsonb_set(
                jsonb_set(
                  jsonb_set(
                    jsonb_set(item, '{section}', to_jsonb(section_normalized), false),
                    '{description}',
                    to_jsonb(description_normalized),
                    false
                  ),
                  '{quantity}',
                  to_jsonb(p_quantity),
                  false
                ),
                '{unit}',
                to_jsonb(unit_normalized),
                false
              ),
              '{rate}',
              to_jsonb(p_rate),
              false
            )
          else item
        end
        order by ordinality
      ),
      '[]'::jsonb
    )
    into mutable_line_items
    from jsonb_array_elements(mutable_line_items) with ordinality as line(item, ordinality);
  else
    select coalesce(
      jsonb_agg(item order by ordinality),
      '[]'::jsonb
    )
    into mutable_line_items
    from jsonb_array_elements(mutable_line_items) with ordinality as line(item, ordinality)
    where item->>'id' <> p_line_id::text;
  end if;

  perform 1
  from public.save_project_purchase_order_draft(
    current_context.organization_id,
    p_project_id,
    p_purchase_order_id,
    p_expected_updated_at,
    po_row.purchase_order_title,
    po_row.purchase_order_number,
    po_row.status,
    po_row.origin,
    po_row.supplier_id,
    po_row.issued_to_label,
    po_row.supplier_contact,
    po_row.supplier_name_snapshot,
    po_row.supplier_email_snapshot,
    po_row.supplier_phone_snapshot,
    po_row.requested_by,
    po_row.requested_date,
    po_row.due_date,
    po_row.sent_to_client_at,
    po_row.approved_at,
    po_row.invoice_ready,
    po_row.notes,
    po_row.margin_percent,
    po_row.discount_amount,
    po_row.contingency_amount,
    po_row.gst_percent,
    po_row.include_margin_in_export,
    po_row.include_discount_in_export,
    po_row.include_contingency_in_export,
    mutable_line_items,
    preserved_attachments
  );

  return query
  select *
  from public.get_mobile_project_purchase_order_detail_v2(p_project_id, p_purchase_order_id);
end;
$$;


ALTER FUNCTION "public"."mobile_mutate_project_purchase_order_manual_line_v2"("p_project_id" "uuid", "p_purchase_order_id" "uuid", "p_expected_updated_at" timestamp with time zone, "p_operation" "text", "p_line_id" "uuid", "p_section" "text", "p_description" "text", "p_quantity" numeric, "p_unit" "text", "p_rate" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."move_document_node"("p_node_id" "uuid", "p_target_parent_node_id" "uuid") RETURNS "public"."document_nodes"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  actor_user_id uuid := auth.uid();
  node_row public.document_nodes%rowtype;
  old_parent_id uuid;
  creates_cycle boolean := false;
begin
  select *
  into node_row
  from public.document_nodes node
  where node.id = p_node_id;

  if not found then
    raise exception 'Document node not found.'
      using errcode = 'P0002';
  end if;

  perform public.assert_document_workspace_permission(
    node_row.workspace_id,
    'files.write'
  );
  perform pg_advisory_xact_lock(
    hashtextextended('document-workspace:' || node_row.workspace_id::text, 0)
  );

  select *
  into node_row
  from public.document_nodes node
  where node.id = p_node_id
    and node.deleted_at is null
  for update;

  if not found then
    raise exception 'Active document node not found.'
      using errcode = 'P0002';
  end if;

  if p_target_parent_node_id is not null then
    perform 1
    from public.document_nodes parent
    where parent.organization_id = node_row.organization_id
      and parent.workspace_id = node_row.workspace_id
      and parent.id = p_target_parent_node_id
      and parent.kind = 'folder'
      and parent.deleted_at is null
    for update;

    if not found then
      raise exception 'Target folder not found in this workspace.'
        using errcode = '23503';
    end if;
  end if;

  if node_row.kind = 'folder' and p_target_parent_node_id is not null then
    with recursive descendants as (
      select child.id
      from public.document_nodes child
      where child.id = node_row.id
      union all
      select child.id
      from public.document_nodes child
      join descendants ancestor on child.parent_node_id = ancestor.id
      where child.organization_id = node_row.organization_id
        and child.workspace_id = node_row.workspace_id
    )
    select exists (
      select 1
      from descendants
      where id = p_target_parent_node_id
    )
    into creates_cycle;

    if creates_cycle then
      raise exception 'A folder cannot be moved into itself or its descendant.'
        using errcode = '23514';
    end if;
  end if;

  old_parent_id := node_row.parent_node_id;
  if old_parent_id is not distinct from p_target_parent_node_id then
    return node_row;
  end if;

  update public.document_nodes node
  set
    parent_node_id = p_target_parent_node_id,
    updated_by = actor_user_id
  where node.id = node_row.id
  returning * into node_row;

  insert into public.document_activity_events (
    organization_id,
    workspace_id,
    node_id,
    actor_user_id,
    event_type,
    metadata
  )
  values (
    node_row.organization_id,
    node_row.workspace_id,
    node_row.id,
    actor_user_id,
    'moved',
    jsonb_build_object(
      'oldParentNodeId', old_parent_id,
      'newParentNodeId', node_row.parent_node_id
    )
  );

  return node_row;
end;
$$;


ALTER FUNCTION "public"."move_document_node"("p_node_id" "uuid", "p_target_parent_node_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."next_project_document_number"("p_organization_id" "uuid", "p_project_id" "uuid", "p_document_kind" "text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
declare
  next_number integer;
  seeded_last integer := 0;
begin
  if p_document_kind not in ('variation', 'purchase_order', 'claim') then
    raise exception 'Unsupported document kind: %', p_document_kind;
  end if;

  if auth.uid() is null then
    raise exception 'Authentication is required';
  end if;

  if not public.is_member_of_organization(p_organization_id) then
    raise exception 'Not authorized for this organization';
  end if;

  if not exists (
    select 1
    from public.organization_projects p
    where p.id = p_project_id
      and p.organization_id = p_organization_id
  ) then
    raise exception 'Project not found for organization';
  end if;

  perform pg_advisory_xact_lock(hashtext(p_project_id::text || ':' || p_document_kind));

  if p_document_kind = 'variation' then
    select coalesce(max(substring(v.variation_number from '([0-9]+)$')::integer), 0)
      into seeded_last
    from public.project_variations v
    where v.organization_id = p_organization_id
      and v.project_id = p_project_id
      and v.variation_number ~ '.*-VAR-[0-9]+$';
  elsif p_document_kind = 'purchase_order' then
    select coalesce(max(substring(po.purchase_order_number from '([0-9]+)$')::integer), 0)
      into seeded_last
    from public.project_purchase_orders po
    where po.organization_id = p_organization_id
      and po.project_id = p_project_id
      and po.purchase_order_number ~ '.*-PO-[0-9]+$';
  else
    select coalesce(max(substring(c.claim_number from '([0-9]+)$')::integer), 0)
      into seeded_last
    from public.project_claims c
    where c.organization_id = p_organization_id
      and c.project_id = p_project_id
      and c.claim_number ~ '.*-CL-[0-9]+$';
  end if;

  insert into public.project_document_counters (
    organization_id,
    project_id,
    document_kind,
    last_number
  )
  values (
    p_organization_id,
    p_project_id,
    p_document_kind,
    seeded_last + 1
  )
  on conflict (project_id, document_kind)
  do update
    set last_number = greatest(public.project_document_counters.last_number + 1, excluded.last_number),
        updated_at = now()
  returning last_number
  into next_number;

  return next_number;
end;
$_$;


ALTER FUNCTION "public"."next_project_document_number"("p_organization_id" "uuid", "p_project_id" "uuid", "p_document_kind" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."normalize_material_estimating_unit"("p_unit" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE PARALLEL SAFE
    SET "search_path" TO ''
    AS $$
  select case lower(regexp_replace(btrim(coalesce(p_unit, '')), '\s+', ' ', 'g'))
    when 'ea' then 'each' when 'item' then 'each' when 'items' then 'each'
    when 'pc' then 'each' when 'pcs' then 'each' when 'piece' then 'each'
    when 'pieces' then 'each' when 'unit' then 'each' when 'units' then 'each'
    when 'sheets' then 'sheet' when 'sht' then 'sheet' when 'shts' then 'sheet'
    when 'boxes' then 'box' when 'bx' then 'box'
    when 'packs' then 'pack' when 'pkt' then 'pack' when 'pkts' then 'pack'
    when 'rolls' then 'roll' when 'bags' then 'bag' when 'pallets' then 'pallet'
    when 'cartons' then 'carton'
    when 'l/m' then 'lm' when 'l m' then 'lm' when 'lin m' then 'lm'
    when 'linear m' then 'lm' when 'linear metre' then 'lm' when 'linear metres' then 'lm'
    when 'linear meter' then 'lm' when 'linear meters' then 'lm'
    when 'lineal metre' then 'lm' when 'lineal metres' then 'lm'
    when 'lineal meter' then 'lm' when 'lineal meters' then 'lm'
    when 'metre' then 'm' when 'metres' then 'm' when 'meter' then 'm' when 'meters' then 'm'
    when 'millimetre' then 'mm' when 'millimetres' then 'mm' when 'millimeter' then 'mm' when 'millimeters' then 'mm'
    when 'centimetre' then 'cm' when 'centimetres' then 'cm' when 'centimeter' then 'cm' when 'centimeters' then 'cm'
    when 'm²' then 'm2' when 'm^2' then 'm2' when 'sqm' then 'm2' when 'sq m' then 'm2'
    when 'square metre' then 'm2' when 'square metres' then 'm2' when 'square meter' then 'm2' when 'square meters' then 'm2'
    when 'm³' then 'm3' when 'm^3' then 'm3' when 'cubic metre' then 'm3' when 'cubic metres' then 'm3'
    when 'cubic meter' then 'm3' when 'cubic meters' then 'm3'
    when 'kilogram' then 'kg' when 'kilograms' then 'kg' when 'gram' then 'g' when 'grams' then 'g'
    when 'tonnes' then 'tonne' when 'ton' then 'tonne' when 'tons' then 'tonne' when 't' then 'tonne'
    else lower(regexp_replace(btrim(coalesce(p_unit, '')), '\s+', ' ', 'g'))
  end
$$;


ALTER FUNCTION "public"."normalize_material_estimating_unit"("p_unit" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."normalize_supplier_invoice_number"("p_value" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE STRICT
    SET "search_path" TO 'public'
    AS $$
  select upper(regexp_replace(trim(p_value), '[[:space:]]+', '', 'g'));
$$;


ALTER FUNCTION "public"."normalize_supplier_invoice_number"("p_value" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."normalize_supported_tax_jurisdiction"("p_country" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select case upper(regexp_replace(trim(coalesce(p_country, '')), '\s+', ' ', 'g'))
    when 'NZ' then 'NZ'
    when 'NZL' then 'NZ'
    when 'NEW ZEALAND' then 'NZ'
    when 'AU' then 'AU'
    when 'AUS' then 'AU'
    when 'AUSTRALIA' then 'AU'
    else 'unsupported'
  end;
$$;


ALTER FUNCTION "public"."normalize_supported_tax_jurisdiction"("p_country" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."opportunity_quote_has_meaningful_state_v1"("p_organization_id" "uuid", "p_quote_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select coalesce(
    quote.total_quote_price <> 0
    or quote.subtotal <> 0
    or quote.optional_subtotal <> 0
    or quote.margin_amount <> 0
    or quote.discount_amount <> 0
    or quote.contingency_amount <> 0
    or exists (select 1 from public.project_quote_line_items line
      where line.organization_id = p_organization_id and line.quote_id = p_quote_id)
    or exists (select 1 from public.opportunity_pricing_worksheets workbook
      where workbook.organization_id = p_organization_id and workbook.quote_id = p_quote_id
        and workbook.archived_at is null)
    or coalesce(nullif(btrim(quote.optional_items_notes), ''),
      nullif(btrim(quote.scope_exclusions), ''), nullif(btrim(quote.assumptions), ''),
      nullif(btrim(quote.scope_notes), ''), nullif(btrim(quote.payment_terms), ''),
      nullif(btrim(quote.lead_time), ''), nullif(btrim(quote.terms_inclusions), ''),
      nullif(btrim(quote.terms_exclusions), ''), nullif(btrim(quote.clarifications), ''),
      nullif(btrim(quote.acceptance_notes), '')) is not null,
    false
  )
  from public.project_quotes quote
  where quote.organization_id = p_organization_id and quote.id = p_quote_id;
$$;


ALTER FUNCTION "public"."opportunity_quote_has_meaningful_state_v1"("p_organization_id" "uuid", "p_quote_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."opportunity_quote_snapshot_hash_v1"("p_organization_id" "uuid", "p_quote_id" "uuid") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select md5(jsonb_build_object(
    'quote', jsonb_build_object(
      'quote_title', quote.quote_title,
      'site_address', quote.site_address,
      'project_name', quote.project_name,
      'expiry_date', quote.expiry_date,
      'optional_items_notes', quote.optional_items_notes,
      'scope_exclusions', quote.scope_exclusions,
      'assumptions', quote.assumptions,
      'scope_notes', quote.scope_notes,
      'subtotal', quote.subtotal,
      'optional_subtotal', quote.optional_subtotal,
      'margin_percent', quote.margin_percent,
      'margin_amount', quote.margin_amount,
      'discount_amount', quote.discount_amount,
      'contingency_amount', quote.contingency_amount,
      'gst_percent', quote.gst_percent,
      'gst_amount', quote.gst_amount,
      'total_quote_price', quote.total_quote_price,
      'validity_period', quote.validity_period,
      'payment_terms', quote.payment_terms,
      'retention_percent_default', quote.retention_percent_default,
      'lead_time', quote.lead_time,
      'terms_inclusions', quote.terms_inclusions,
      'terms_exclusions', quote.terms_exclusions,
      'clarifications', quote.clarifications,
      'acceptance_notes', quote.acceptance_notes
    ),
    'lines', coalesce((
      select jsonb_agg(jsonb_build_object(
        'section', line.section,
        'description', line.description,
        'quantity', line.quantity,
        'unit', line.unit,
        'rate', line.rate,
        'total', line.total,
        'is_optional', line.is_optional,
        'sort_order', line.sort_order,
        'source_opportunity_quote_id', line.source_opportunity_quote_id,
        'source_opportunity_quote_line_item_id', line.source_opportunity_quote_line_item_id,
        'source_opportunity_quote_number', line.source_opportunity_quote_number,
        'pricing_source_kind', line.pricing_source_kind
      ) order by line.sort_order, line.id)
      from public.project_quote_line_items line
      where line.organization_id = p_organization_id and line.quote_id = p_quote_id
    ), '[]'::jsonb)
  )::text)
  from public.project_quotes quote
  where quote.organization_id = p_organization_id and quote.id = p_quote_id;
$$;


ALTER FUNCTION "public"."opportunity_quote_snapshot_hash_v1"("p_organization_id" "uuid", "p_quote_id" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."organization_accounting_document_revisions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "project_id" "uuid",
    "accounting_document_id" "uuid" NOT NULL,
    "revision_sequence" bigint NOT NULL,
    "source_document_type" "text" NOT NULL,
    "source_document_id" "uuid" NOT NULL,
    "revision_intent" "text" NOT NULL,
    "resolution_strategy" "text" NOT NULL,
    "previous_revision_id" "uuid",
    "provider" "text" NOT NULL,
    "connection_id" "uuid" NOT NULL,
    "tenant_id" "text" NOT NULL,
    "number_reservation_id" "uuid",
    "external_document_id" "text",
    "external_document_number" "text" NOT NULL,
    "commercial_snapshot" "jsonb" NOT NULL,
    "contact_snapshot" "jsonb" NOT NULL,
    "routing_snapshot" "jsonb" NOT NULL,
    "tax_snapshot" "jsonb" NOT NULL,
    "attachment_snapshot" "jsonb" NOT NULL,
    "payload_snapshot" "jsonb" NOT NULL,
    "canonical_schema_version" "text" NOT NULL,
    "source_evidence_hash" "text" NOT NULL,
    "commercial_hash" "text" NOT NULL,
    "lines_hash" "text" NOT NULL,
    "payload_hash" "text" NOT NULL,
    "provider_content_hash" "text" NOT NULL,
    "pdf_hash" "text",
    "currency_code" "text" NOT NULL,
    "provider_document_type" "text" NOT NULL,
    "requested_provider_status" "text" NOT NULL,
    "line_amount_type" "text" NOT NULL,
    "subtotal_minor" bigint NOT NULL,
    "tax_minor" bigint NOT NULL,
    "total_minor" bigint NOT NULL,
    "confirmation_preview_hash" "text" NOT NULL,
    "confirmed_by" "uuid" NOT NULL,
    "confirmed_at" timestamp with time zone NOT NULL,
    "confirmation_reason" "text",
    "lifecycle_state" "text" DEFAULT 'confirmed'::"text" NOT NULL,
    "succeeded_at" timestamp with time zone,
    "activated_at" timestamp with time zone,
    "superseded_at" timestamp with time zone,
    "superseded_by_revision_id" "uuid",
    "failure_code" "text",
    "failure_message" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "accounting_revision_amounts_check" CHECK ((("subtotal_minor" >= 0) AND ("tax_minor" >= 0) AND ("total_minor" = ("subtotal_minor" + "tax_minor")))),
    CONSTRAINT "accounting_revision_confirmation_check" CHECK ((("confirmed_at" <= "created_at") AND (("confirmation_reason" IS NULL) OR ("char_length"(TRIM(BOTH FROM "confirmation_reason")) > 0)))),
    CONSTRAINT "accounting_revision_hashes_check" CHECK ((("source_evidence_hash" ~ '^[a-f0-9]{64}$'::"text") AND ("commercial_hash" ~ '^[a-f0-9]{64}$'::"text") AND ("lines_hash" ~ '^[a-f0-9]{64}$'::"text") AND ("payload_hash" ~ '^[a-f0-9]{64}$'::"text") AND ("provider_content_hash" ~ '^[a-f0-9]{64}$'::"text") AND (("pdf_hash" IS NULL) OR ("pdf_hash" ~ '^[a-f0-9]{64}$'::"text")) AND ("confirmation_preview_hash" ~ '^[a-f0-9]{64}$'::"text"))),
    CONSTRAINT "accounting_revision_intent_check" CHECK (("revision_intent" = ANY (ARRAY['initial_push'::"text", 'direct_update'::"text", 'amendment'::"text", 'credit'::"text", 'void_and_replace'::"text", 'replacement'::"text", 'legacy_import'::"text"]))),
    CONSTRAINT "accounting_revision_lifecycle_check" CHECK (("lifecycle_state" = ANY (ARRAY['confirmed'::"text", 'queued'::"text", 'processing'::"text", 'succeeded'::"text", 'failed'::"text", 'attention_required'::"text", 'superseded'::"text"]))),
    CONSTRAINT "accounting_revision_provider_contract_check" CHECK ((("provider" <> 'xero'::"text") OR (("provider_document_type" = 'ACCREC'::"text") AND ("requested_provider_status" = 'AUTHORISED'::"text")))),
    CONSTRAINT "accounting_revision_resolution_check" CHECK (("resolution_strategy" = ANY (ARRAY['new_document'::"text", 'update_existing'::"text", 'amendment'::"text", 'credit'::"text", 'void_and_replace'::"text", 'replacement'::"text", 'legacy_preservation'::"text"]))),
    CONSTRAINT "accounting_revision_sequence_check" CHECK (("revision_sequence" > 0)),
    CONSTRAINT "accounting_revision_snapshot_objects_check" CHECK ((("jsonb_typeof"("commercial_snapshot") = 'object'::"text") AND ("jsonb_typeof"("contact_snapshot") = 'object'::"text") AND ("jsonb_typeof"("routing_snapshot") = 'object'::"text") AND ("jsonb_typeof"("tax_snapshot") = 'object'::"text") AND ("jsonb_typeof"("attachment_snapshot") = 'object'::"text") AND ("jsonb_typeof"("payload_snapshot") = 'object'::"text"))),
    CONSTRAINT "accounting_revision_source_check" CHECK (("source_document_type" = ANY (ARRAY['supplier_invoice'::"text", 'project_claim'::"text", 'retention_claim'::"text"]))),
    CONSTRAINT "accounting_revision_success_shape_check" CHECK (((("lifecycle_state" = ANY (ARRAY['succeeded'::"text", 'superseded'::"text"])) AND ("succeeded_at" IS NOT NULL)) OR ("lifecycle_state" <> ALL (ARRAY['succeeded'::"text", 'superseded'::"text"])))),
    CONSTRAINT "accounting_revision_supersession_shape_check" CHECK (((("lifecycle_state" = 'superseded'::"text") AND ("superseded_at" IS NOT NULL) AND ("superseded_by_revision_id" IS NOT NULL)) OR (("lifecycle_state" <> 'superseded'::"text") AND ("superseded_at" IS NULL) AND ("superseded_by_revision_id" IS NULL)))),
    CONSTRAINT "accounting_revision_text_check" CHECK ((("char_length"(TRIM(BOTH FROM "provider")) > 0) AND ("char_length"(TRIM(BOTH FROM "tenant_id")) > 0) AND ("char_length"(TRIM(BOTH FROM "external_document_number")) > 0) AND ("char_length"(TRIM(BOTH FROM "canonical_schema_version")) > 0) AND ("char_length"(TRIM(BOTH FROM "currency_code")) = 3) AND ("char_length"(TRIM(BOTH FROM "line_amount_type")) > 0)))
);

ALTER TABLE ONLY "public"."organization_accounting_document_revisions" FORCE ROW LEVEL SECURITY;


ALTER TABLE "public"."organization_accounting_document_revisions" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."persist_confirmed_accounting_revision_phase2a"("p_input" "jsonb") RETURNS "public"."organization_accounting_document_revisions"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  document public.organization_accounting_documents%rowtype;
  reservation public.organization_accounting_number_reservations%rowtype;
  previous_revision public.organization_accounting_document_revisions%rowtype;
  source_claim_number text;
  revision public.organization_accounting_document_revisions%rowtype;
  line jsonb;
  attachment jsonb;
  next_sequence bigint;
  line_subtotal bigint := 0;
  line_tax bigint := 0;
  reservation_free_payment_update boolean := false;
begin
  select * into document
  from public.organization_accounting_documents
  where id = (p_input->>'accountingDocumentId')::uuid
    and organization_id = (p_input->>'organizationId')::uuid
  for update;
  if not found then raise exception 'Accounting document not found in organization.'; end if;
  if document.provider <> p_input->>'provider'
    or document.tenant_id <> p_input->>'tenantId'
    or document.accounting_connection_id <> (p_input->>'connectionId')::uuid
    or document.local_document_type <> p_input->>'sourceDocumentType'
    or coalesce(document.project_claim_id, document.retention_claim_id, document.local_document_id)
      <> (p_input->>'sourceDocumentId')::uuid then
    raise exception 'Confirmed accounting identity does not match the stable document.';
  end if;

  next_sequence := coalesce((
    select max(r.revision_sequence) + 1
    from public.organization_accounting_document_revisions r
    where r.accounting_document_id = document.id
  ), 1);

  if next_sequence = 1 and nullif(p_input->>'previousRevisionId', '') is not null then
    raise exception 'The first accounting revision cannot have a predecessor.';
  elsif next_sequence > 1 then
    select * into previous_revision
    from public.organization_accounting_document_revisions
    where id = (p_input->>'previousRevisionId')::uuid
      and accounting_document_id = document.id;
    if not found or previous_revision.revision_sequence <> next_sequence - 1 then
      raise exception 'Accounting revision predecessor is not the prior document revision.';
    end if;
  end if;

  reservation_free_payment_update :=
    document.local_document_type = 'project_claim'
    and document.integration_contract = 'payment_claim_revision_v1'
    and p_input->>'revisionIntent' = 'direct_update'
    and p_input->>'resolutionStrategy' = 'update_existing'
    and nullif(p_input->>'numberReservationId', '') is null
    and previous_revision.id is not null
    and previous_revision.number_reservation_id is null;

  if reservation_free_payment_update then
    select claim.claim_number into source_claim_number
    from public.project_claims claim
    where claim.id = document.project_claim_id
      and claim.organization_id = document.organization_id;
    if nullif(trim(source_claim_number), '') is null
      or p_input->>'externalDocumentNumber' <> source_claim_number
      or previous_revision.external_document_number <> source_claim_number
      or p_input#>>'{payloadSnapshot,InvoiceNumber}' <> source_claim_number then
      raise exception 'Payment Claim update must preserve its reservation-free claim-number identity.';
    end if;
  elsif document.local_document_type in ('project_claim', 'retention_claim') then
    select * into reservation
    from public.organization_accounting_number_reservations n
    where n.id = (p_input->>'numberReservationId')::uuid
      and n.organization_id = document.organization_id
      and n.provider = document.provider
      and n.tenant_id = document.tenant_id
      and n.accounting_document_id = document.id
      and n.source_document_type = document.local_document_type
      and n.source_document_id =
        coalesce(document.project_claim_id, document.retention_claim_id);
    if not found or reservation.formatted_number <> p_input->>'externalDocumentNumber' then
      raise exception 'Confirmed sales-invoice number is not the reserved tenant number.';
    end if;
  end if;

  if jsonb_typeof(p_input->'lines') <> 'array'
    or jsonb_array_length(p_input->'lines') = 0 then
    raise exception 'A confirmed accounting revision requires line evidence.';
  end if;
  for line in select value from jsonb_array_elements(p_input->'lines')
  loop
    line_subtotal := line_subtotal + (line->>'lineAmountMinor')::bigint;
    line_tax := line_tax + (line->>'taxMinor')::bigint;
  end loop;
  if line_subtotal <> (p_input->>'subtotalMinor')::bigint
    or line_tax <> (p_input->>'taxMinor')::bigint
    or line_subtotal + line_tax <> (p_input->>'totalMinor')::bigint then
    raise exception 'Confirmed accounting line totals do not reconcile.';
  end if;

  insert into public.organization_accounting_document_revisions(
    organization_id, project_id, accounting_document_id, revision_sequence,
    source_document_type, source_document_id, revision_intent,
    resolution_strategy, previous_revision_id, provider, connection_id,
    tenant_id, number_reservation_id, external_document_number,
    commercial_snapshot, contact_snapshot, routing_snapshot, tax_snapshot,
    attachment_snapshot, payload_snapshot, canonical_schema_version,
    source_evidence_hash, commercial_hash, lines_hash, payload_hash,
    provider_content_hash, pdf_hash,
    currency_code, provider_document_type, requested_provider_status,
    line_amount_type, subtotal_minor, tax_minor, total_minor,
    confirmation_preview_hash, confirmed_by, confirmed_at, confirmation_reason
  ) values (
    document.organization_id,
    nullif(p_input->>'projectId', '')::uuid,
    document.id,
    next_sequence,
    document.local_document_type,
    coalesce(document.project_claim_id, document.retention_claim_id, document.local_document_id),
    p_input->>'revisionIntent',
    p_input->>'resolutionStrategy',
    nullif(p_input->>'previousRevisionId', '')::uuid,
    document.provider,
    (p_input->>'connectionId')::uuid,
    document.tenant_id,
    nullif(p_input->>'numberReservationId', '')::uuid,
    p_input->>'externalDocumentNumber',
    p_input->'commercialSnapshot',
    p_input->'contactSnapshot',
    p_input->'routingSnapshot',
    p_input->'taxSnapshot',
    p_input->'attachmentSnapshot',
    p_input->'payloadSnapshot',
    p_input->>'canonicalSchemaVersion',
    p_input->>'sourceEvidenceHash',
    p_input->>'commercialHash',
    p_input->>'linesHash',
    p_input->>'payloadHash',
    p_input->>'providerContentHash',
    nullif(p_input->>'pdfHash', ''),
    p_input->>'currencyCode',
    p_input->>'providerDocumentType',
    p_input->>'requestedProviderStatus',
    p_input->>'lineAmountType',
    (p_input->>'subtotalMinor')::bigint,
    (p_input->>'taxMinor')::bigint,
    (p_input->>'totalMinor')::bigint,
    p_input->>'confirmationPreviewHash',
    (p_input->>'confirmedBy')::uuid,
    coalesce((p_input->>'confirmedAt')::timestamptz, now()),
    nullif(p_input->>'confirmationReason', '')
  ) returning * into revision;

  for line in select value from jsonb_array_elements(p_input->'lines')
  loop
    insert into public.organization_accounting_revision_lines(
      organization_id, accounting_revision_id, sequence, line_kind,
      source_line_type, source_line_id, originating_payment_claim_id,
      description, quantity, unit_amount_minor, line_amount_minor, tax_minor,
      total_minor, account_snapshot, tax_snapshot, tracking_snapshot,
      source_snapshot
    ) values (
      revision.organization_id, revision.id, (line->>'sequence')::integer,
      line->>'lineKind', line->>'sourceLineType',
      nullif(line->>'sourceLineId', '')::uuid,
      nullif(line->>'originatingPaymentClaimId', '')::uuid,
      line->>'description', (line->>'quantity')::numeric,
      (line->>'unitAmountMinor')::bigint, (line->>'lineAmountMinor')::bigint,
      (line->>'taxMinor')::bigint, (line->>'totalMinor')::bigint,
      line->'accountSnapshot', line->'taxSnapshot',
      coalesce(line->'trackingSnapshot', '{}'::jsonb),
      line->'sourceSnapshot'
    );
  end loop;

  for attachment in
    select value from jsonb_array_elements(coalesce(p_input->'attachments', '[]'::jsonb))
  loop
    insert into public.organization_accounting_revision_attachments(
      organization_id, accounting_revision_id, attachment_sequence,
      attachment_kind, source_document_id, filename, content_type, byte_size,
      content_sha256, storage_bucket, storage_path
    ) values (
      revision.organization_id, revision.id,
      (attachment->>'sequence')::integer, attachment->>'kind',
      nullif(attachment->>'sourceDocumentId', '')::uuid,
      attachment->>'filename', attachment->>'contentType',
      (attachment->>'byteSize')::bigint, attachment->>'contentSha256',
      attachment->>'storageBucket', attachment->>'storagePath'
    );
  end loop;

  insert into public.organization_accounting_events(
    organization_id, accounting_document_id, accounting_revision_id,
    event_type, actor_user_id, correlation_id, event_evidence
  ) values (
    revision.organization_id, revision.accounting_document_id, revision.id,
    'revision_confirmed', revision.confirmed_by, p_input->>'correlationId',
    jsonb_build_object(
      'revisionSequence', revision.revision_sequence,
      'confirmationPreviewHash', revision.confirmation_preview_hash,
      'sourceEvidenceHash', revision.source_evidence_hash
    )
  );
  return revision;
end;
$$;


ALTER FUNCTION "public"."persist_confirmed_accounting_revision_phase2a"("p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."persist_payment_claim_initial_revision_phase2b"("p_input" "jsonb") RETURNS "public"."organization_accounting_document_revisions"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  document public.organization_accounting_documents%rowtype;
  claim public.project_claims%rowtype;
  revision public.organization_accounting_document_revisions%rowtype;
  line jsonb;
  attachment jsonb;
  line_subtotal bigint := 0;
  line_tax bigint := 0;
begin
  select * into document
  from public.organization_accounting_documents
  where id = (p_input->>'accountingDocumentId')::uuid
    and organization_id = (p_input->>'organizationId')::uuid
  for update;
  if not found
    or document.provider <> 'xero'
    or document.local_document_type <> 'project_claim'
    or document.integration_contract <> 'payment_claim_revision_v1'
    or document.tenant_id <> p_input->>'tenantId'
    or document.accounting_connection_id <> (p_input->>'connectionId')::uuid
    or document.project_claim_id <> (p_input->>'sourceDocumentId')::uuid then
    raise exception 'Payment Claim accounting identity does not match the immutable document.';
  end if;
  if document.external_document_id is not null
    or document.active_accounting_revision_id is not null then
    raise exception 'Payment Claim accounting identity is already linked.';
  end if;

  select * into claim
  from public.project_claims c
  where c.id = document.project_claim_id
    and c.organization_id = document.organization_id
    and c.project_id = (p_input->>'projectId')::uuid;
  if not found then
    raise exception 'Payment Claim source identity was not found.';
  end if;
  if nullif(trim(claim.claim_number), '') is null
    or p_input->>'externalDocumentNumber' <> claim.claim_number
    or p_input#>>'{payloadSnapshot,InvoiceNumber}' <> claim.claim_number
    or p_input#>>'{commercialSnapshot,commercialClaimNumber}' <> claim.claim_number then
    raise exception 'Immutable Xero InvoiceNumber must equal the Payment Claim number.';
  end if;
  if nullif(p_input->>'numberReservationId', '') is not null then
    raise exception 'Standard Payment Claim initial pushes must not use an accounting number reservation.';
  end if;
  if p_input->>'revisionIntent' <> 'initial_push'
    or p_input->>'resolutionStrategy' <> 'new_document'
    or nullif(p_input->>'previousRevisionId', '') is not null
    or p_input->>'providerDocumentType' <> 'ACCREC'
    or p_input->>'requestedProviderStatus' <> 'AUTHORISED' then
    raise exception 'Invalid standard Payment Claim initial revision contract.';
  end if;
  if exists (
    select 1 from public.organization_accounting_document_revisions r
    where r.accounting_document_id = document.id
  ) then
    raise exception 'A Payment Claim accounting revision already exists.';
  end if;

  if jsonb_typeof(p_input->'lines') <> 'array'
    or jsonb_array_length(p_input->'lines') = 0 then
    raise exception 'A confirmed accounting revision requires line evidence.';
  end if;
  for line in select value from jsonb_array_elements(p_input->'lines')
  loop
    line_subtotal := line_subtotal + (line->>'lineAmountMinor')::bigint;
    line_tax := line_tax + (line->>'taxMinor')::bigint;
  end loop;
  if line_subtotal <> (p_input->>'subtotalMinor')::bigint
    or line_tax <> (p_input->>'taxMinor')::bigint
    or line_subtotal + line_tax <> (p_input->>'totalMinor')::bigint then
    raise exception 'Confirmed accounting line totals do not reconcile.';
  end if;

  if jsonb_array_length(coalesce(p_input->'attachments', '[]'::jsonb)) <> 1
    or p_input#>>'{attachments,0,filename}' <> claim.claim_number || '-r0001.pdf' then
    raise exception 'Immutable Payment Claim PDF filename must use the Payment Claim number.';
  end if;

  insert into public.organization_accounting_document_revisions(
    organization_id, project_id, accounting_document_id, revision_sequence,
    source_document_type, source_document_id, revision_intent,
    resolution_strategy, previous_revision_id, provider, connection_id,
    tenant_id, number_reservation_id, external_document_number,
    commercial_snapshot, contact_snapshot, routing_snapshot, tax_snapshot,
    attachment_snapshot, payload_snapshot, canonical_schema_version,
    source_evidence_hash, commercial_hash, lines_hash, payload_hash,
    provider_content_hash, pdf_hash, currency_code, provider_document_type,
    requested_provider_status, line_amount_type, subtotal_minor, tax_minor,
    total_minor, confirmation_preview_hash, confirmed_by, confirmed_at,
    confirmation_reason
  ) values (
    document.organization_id, (p_input->>'projectId')::uuid, document.id, 1,
    'project_claim', document.project_claim_id, 'initial_push',
    'new_document', null, 'xero', document.accounting_connection_id,
    document.tenant_id, null, claim.claim_number,
    p_input->'commercialSnapshot', p_input->'contactSnapshot',
    p_input->'routingSnapshot', p_input->'taxSnapshot',
    p_input->'attachmentSnapshot', p_input->'payloadSnapshot',
    p_input->>'canonicalSchemaVersion', p_input->>'sourceEvidenceHash',
    p_input->>'commercialHash', p_input->>'linesHash',
    p_input->>'payloadHash', p_input->>'providerContentHash',
    nullif(p_input->>'pdfHash', ''), p_input->>'currencyCode', 'ACCREC',
    'AUTHORISED', p_input->>'lineAmountType',
    (p_input->>'subtotalMinor')::bigint, (p_input->>'taxMinor')::bigint,
    (p_input->>'totalMinor')::bigint, p_input->>'confirmationPreviewHash',
    (p_input->>'confirmedBy')::uuid,
    coalesce((p_input->>'confirmedAt')::timestamptz, now()),
    nullif(p_input->>'confirmationReason', '')
  ) returning * into revision;

  for line in select value from jsonb_array_elements(p_input->'lines')
  loop
    insert into public.organization_accounting_revision_lines(
      organization_id, accounting_revision_id, sequence, line_kind,
      source_line_type, source_line_id, originating_payment_claim_id,
      description, quantity, unit_amount_minor, line_amount_minor, tax_minor,
      total_minor, account_snapshot, tax_snapshot, tracking_snapshot,
      source_snapshot
    ) values (
      revision.organization_id, revision.id, (line->>'sequence')::integer,
      line->>'lineKind', line->>'sourceLineType',
      nullif(line->>'sourceLineId', '')::uuid,
      nullif(line->>'originatingPaymentClaimId', '')::uuid,
      line->>'description', (line->>'quantity')::numeric,
      (line->>'unitAmountMinor')::bigint, (line->>'lineAmountMinor')::bigint,
      (line->>'taxMinor')::bigint, (line->>'totalMinor')::bigint,
      line->'accountSnapshot', line->'taxSnapshot',
      coalesce(line->'trackingSnapshot', '{}'::jsonb),
      line->'sourceSnapshot'
    );
  end loop;

  for attachment in
    select value from jsonb_array_elements(p_input->'attachments')
  loop
    insert into public.organization_accounting_revision_attachments(
      organization_id, accounting_revision_id, attachment_sequence,
      attachment_kind, source_document_id, filename, content_type, byte_size,
      content_sha256, storage_bucket, storage_path
    ) values (
      revision.organization_id, revision.id,
      (attachment->>'sequence')::integer, attachment->>'kind',
      nullif(attachment->>'sourceDocumentId', '')::uuid,
      attachment->>'filename', attachment->>'contentType',
      (attachment->>'byteSize')::bigint, attachment->>'contentSha256',
      attachment->>'storageBucket', attachment->>'storagePath'
    );
  end loop;

  insert into public.organization_accounting_events(
    organization_id, accounting_document_id, accounting_revision_id,
    event_type, actor_user_id, correlation_id, event_evidence
  ) values (
    revision.organization_id, revision.accounting_document_id, revision.id,
    'revision_confirmed', revision.confirmed_by, p_input->>'correlationId',
    jsonb_build_object(
      'revisionSequence', revision.revision_sequence,
      'confirmationPreviewHash', revision.confirmation_preview_hash,
      'sourceEvidenceHash', revision.source_evidence_hash
    )
  );
  return revision;
end;
$$;


ALTER FUNCTION "public"."persist_payment_claim_initial_revision_phase2b"("p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."persist_payment_claim_push_proposal_phase2c"("p_input" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_id uuid := (p_input->>'proposalId')::uuid;
  v_operation text := p_input->>'operation';
  v_document_id uuid := nullif(p_input->>'accountingDocumentId', '')::uuid;
begin
  insert into public.organization_accounting_push_proposals(
    id, organization_id, project_id, source_document_type, source_document_id,
    accounting_document_id, active_revision_id, operation, external_document_number,
    preview_hash, source_optimistic_revision, decision_snapshot, evidence_hashes,
    expires_at, created_by
  ) values (
    v_id,
    (p_input->>'organizationId')::uuid,
    (p_input->>'projectId')::uuid,
    'project_claim',
    (p_input->>'claimId')::uuid,
    v_document_id,
    nullif(p_input->>'activeRevisionId', '')::uuid,
    v_operation,
    p_input->>'externalDocumentNumber',
    p_input->>'previewHash',
    p_input->>'sourceOptimisticRevision',
    p_input->'decisionSnapshot',
    p_input->'evidenceHashes',
    (p_input->>'expiresAt')::timestamptz,
    (p_input->>'createdBy')::uuid
  );

  if v_operation = 'REPLACEMENT_EXPORT' and v_document_id is not null then
    insert into public.organization_accounting_events(
      organization_id, accounting_document_id, accounting_revision_id,
      event_type, actor_user_id, correlation_id, event_evidence
    ) values (
      (p_input->>'organizationId')::uuid,
      v_document_id,
      nullif(p_input->>'activeRevisionId', '')::uuid,
      'replacement_proposed',
      (p_input->>'createdBy')::uuid,
      v_id::text,
      jsonb_build_object(
        'operation', v_operation,
        'previousInvoiceId', p_input#>>'{decisionSnapshot,previousInvoiceId}',
        'previousInvoiceNumber', p_input#>>'{decisionSnapshot,previousInvoiceNumber}',
        'replacementInvoiceNumber', p_input->>'externalDocumentNumber',
        'previewHash', p_input->>'previewHash'
      )
    );
  end if;

  return v_id;
end;
$$;


ALTER FUNCTION "public"."persist_payment_claim_push_proposal_phase2c"("p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."persist_retention_claim_push_proposal_phase2c"("p_input" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_id uuid := (p_input->>'proposalId')::uuid;
begin
  if auth.role() <> 'service_role' then
    raise exception 'Retention Claim accounting proposals are server-only.';
  end if;
  insert into public.organization_accounting_push_proposals(
    id, organization_id, project_id, source_document_type, source_document_id,
    accounting_document_id, active_revision_id, operation,
    external_document_number, preview_hash, source_optimistic_revision,
    decision_snapshot, evidence_hashes, expires_at, created_by
  ) values (
    v_id,
    (p_input->>'organizationId')::uuid,
    (p_input->>'projectId')::uuid,
    'retention_claim',
    (p_input->>'retentionClaimId')::uuid,
    nullif(p_input->>'accountingDocumentId', '')::uuid,
    nullif(p_input->>'activeRevisionId', '')::uuid,
    p_input->>'operation',
    p_input->>'externalDocumentNumber',
    p_input->>'previewHash',
    p_input->>'sourceOptimisticRevision',
    p_input->'decisionSnapshot',
    p_input->'evidenceHashes',
    (p_input->>'expiresAt')::timestamptz,
    (p_input->>'createdBy')::uuid
  );
  return v_id;
end;
$$;


ALTER FUNCTION "public"."persist_retention_claim_push_proposal_phase2c"("p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."persist_supplier_bill_ucl_container"("p_queue_id" "uuid", "p_lease_token" "uuid", "p_organization_id" "uuid", "p_source_id" "uuid", "p_container_type" "text", "p_schema_version" "text", "p_builder_version" "text", "p_content_hash" "text", "p_payload_integrity_hash" "text", "p_canonical_updated_at" timestamp with time zone, "p_latest_dependency_updated_at" timestamp with time zone, "p_assembled_at" timestamp with time zone, "p_validated_at" timestamp with time zone, "p_payload_bytes" integer, "p_payload_json" "jsonb", "p_visibility_json" "jsonb", "p_project_ids" "uuid"[], "p_primary_project_id" "uuid", "p_supplier_id" "uuid", "p_visibility_scope_hash" "text", "p_context_status" "text", "p_refresh_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
declare
  queue_row public.supplier_bill_ucl_refresh_queue%rowtype;
  current_row public.supplier_bill_ucl_current_state%rowtype;
  version_id uuid;
  inserted_version_id uuid;
  normalized_project_ids uuid[];
  payload_project_ids uuid[];
  created_version boolean := false;
  content_changed boolean := true;
  stale_write boolean := false;
  milestone_codes text[] := '{}';
  version_count integer := 0;
begin
  select *
  into queue_row
  from public.supplier_bill_ucl_refresh_queue q
  where q.id = p_queue_id
    and q.queue_state = 'leased'
    and q.lease_token = p_lease_token
    and q.organization_id = p_organization_id
    and q.source_id = p_source_id
    and q.container_type = 'supplier_invoice'
  for update;

  if not found then
    raise exception 'Supplier Bill UCL persistence lease is not owned by this worker.'
      using errcode = 'P0001';
  end if;
  if p_refresh_reason is distinct from queue_row.reason_code then
    raise exception 'Supplier Bill UCL refresh reason does not match the leased request.'
      using errcode = '22023';
  end if;

  if p_container_type <> 'supplier_invoice' or p_schema_version <> 'supplier_bill.v2' then
    raise exception 'Unsupported Supplier Bill UCL container identity.'
      using errcode = '22023';
  end if;
  if p_context_status not in ('current', 'voided') then
    raise exception 'Unsupported Supplier Bill UCL context status.'
      using errcode = '22023';
  end if;
  if p_builder_version is null or char_length(btrim(p_builder_version)) not between 1 and 120
    or p_content_hash !~ '^[0-9a-f]{64}$'
    or p_payload_integrity_hash !~ '^[0-9a-f]{64}$'
    or p_visibility_scope_hash !~ '^[0-9a-f]{64}$'
    or p_payload_bytes not between 1 and 65536
    or jsonb_typeof(p_payload_json) <> 'object'
    or jsonb_typeof(p_visibility_json) <> 'object'
    or p_canonical_updated_at is null
    or p_latest_dependency_updated_at is null
    or p_latest_dependency_updated_at < p_canonical_updated_at
    or p_assembled_at is null
    or p_validated_at is null then
    raise exception 'Supplier Bill UCL persistence metadata is invalid.'
      using errcode = '22023';
  end if;

  if not exists (
    select 1
    from public.supplier_invoices i
    where i.id = p_source_id
      and i.organization_id = p_organization_id
  ) then
    raise exception 'Canonical Supplier Bill identity does not match persistence scope.'
      using errcode = '23503';
  end if;

  if p_payload_json->>'containerType' <> 'supplier_invoice'
    or p_payload_json->>'organizationId' <> p_organization_id::text
    or p_payload_json #>> '{source,sourceId}' <> p_source_id::text
    or p_payload_json #>> '{payload,schemaVersion}' <> 'supplier_bill.v2'
    or p_payload_json #>> '{payload,lineage,supplierBillId}' <> p_source_id::text
    or p_payload_json #>> '{payload,provenance,builderVersion}' <> p_builder_version
    or p_payload_json #>> '{payload,provenance,contentHash}' <> p_content_hash
    or p_payload_json #>> '{payload,visibility,organizationId}' <> p_organization_id::text
    or p_payload_json #> '{payload,visibility}' <> p_visibility_json then
    raise exception 'Supplier Bill UCL payload identity does not match persistence metadata.'
      using errcode = '22023';
  end if;

  if nullif(p_payload_json->>'supplierId', '') is distinct from p_supplier_id::text
    or nullif(p_payload_json->>'projectId', '') is distinct from p_primary_project_id::text then
    raise exception 'Supplier Bill UCL relationship identity does not match persistence metadata.'
      using errcode = '22023';
  end if;

  select coalesce(array_agg(project_id order by project_id), '{}'::uuid[])
  into normalized_project_ids
  from (
    select distinct unnest(coalesce(p_project_ids, '{}'::uuid[])) as project_id
  ) normalized;

  select coalesce(array_agg(value::uuid order by value::uuid), '{}'::uuid[])
  into payload_project_ids
  from jsonb_array_elements_text(p_payload_json #> '{payload,visibility,projectIds}') value;

  if normalized_project_ids is distinct from payload_project_ids then
    raise exception 'Supplier Bill UCL project visibility does not match persistence metadata.'
      using errcode = '22023';
  end if;

  -- Serialize every writer for this stable identity, including the first
  -- version where no current row exists yet. This makes equal-timestamp hash
  -- precedence deterministic under concurrent workers.
  perform pg_advisory_xact_lock(hashtextextended(
    p_organization_id::text || ':supplier_invoice:' || p_source_id::text,
    0
  ));

  select *
  into current_row
  from public.supplier_bill_ucl_current_state c
  where c.organization_id = p_organization_id
    and c.container_type = 'supplier_invoice'
    and c.source_id = p_source_id
  for update;

  if found and current_row.current_version_id is not null then
    content_changed := current_row.content_hash is distinct from p_content_hash;
    stale_write :=
      p_latest_dependency_updated_at < current_row.latest_dependency_updated_at
      or (
        p_latest_dependency_updated_at = current_row.latest_dependency_updated_at
        and p_canonical_updated_at < current_row.canonical_updated_at
      )
      or (
        p_latest_dependency_updated_at = current_row.latest_dependency_updated_at
        and p_canonical_updated_at = current_row.canonical_updated_at
        and p_content_hash < current_row.content_hash
      );
  end if;

  if stale_write then
    return jsonb_build_object(
      'createdVersion', false,
      'reusedVersion', false,
      'currentUpdated', false,
      'contentChanged', false,
      'staleWriteRejected', true,
      'versionId', current_row.current_version_id,
      'currentHash', current_row.content_hash,
      'versionCount', null,
      'payloadBytes', current_row.payload_bytes,
      'contextStatus', current_row.context_status
    );
  end if;

  if p_refresh_reason in (
    'supplier_bill_accounts_approval_changed',
    'supplier_bill_commercial_approval_changed',
    'supplier_bill_commercial_snapshot_changed',
    'supplier_bill_actual_cost_changed',
    'supplier_bill_xero_export_changed',
    'supplier_bill_payment_changed',
    'supplier_bill_voided'
  ) then
    milestone_codes := array[p_refresh_reason];
  end if;

  insert into public.supplier_bill_ucl_container_versions (
    organization_id,
    container_type,
    source_id,
    schema_version,
    builder_version,
    content_hash,
    payload_integrity_hash,
    canonical_updated_at,
    latest_dependency_updated_at,
    assembled_at,
    validated_at,
    payload_bytes,
    payload_json,
    visibility_json,
    project_ids,
    primary_project_id,
    supplier_id,
    visibility_scope_hash,
    context_status,
    milestone_codes
  ) values (
    p_organization_id,
    'supplier_invoice',
    p_source_id,
    'supplier_bill.v2',
    p_builder_version,
    p_content_hash,
    p_payload_integrity_hash,
    p_canonical_updated_at,
    p_latest_dependency_updated_at,
    p_assembled_at,
    p_validated_at,
    p_payload_bytes,
    p_payload_json,
    p_visibility_json,
    normalized_project_ids,
    p_primary_project_id,
    p_supplier_id,
    p_visibility_scope_hash,
    p_context_status,
    milestone_codes
  )
  on conflict (organization_id, container_type, source_id, schema_version, content_hash)
  do nothing
  returning id into inserted_version_id;

  if inserted_version_id is not null then
    version_id := inserted_version_id;
    created_version := true;
  else
    select v.id
    into version_id
    from public.supplier_bill_ucl_container_versions v
    where v.organization_id = p_organization_id
      and v.container_type = 'supplier_invoice'
      and v.source_id = p_source_id
      and v.schema_version = 'supplier_bill.v2'
      and v.content_hash = p_content_hash;
  end if;

  if version_id is null then
    raise exception 'Supplier Bill UCL version could not be resolved.'
      using errcode = 'P0001';
  end if;

  insert into public.supplier_bill_ucl_current_state (
    organization_id,
    container_type,
    source_id,
    current_version_id,
    schema_version,
    builder_version,
    content_hash,
    canonical_updated_at,
    latest_dependency_updated_at,
    validated_at,
    payload_bytes,
    context_status,
    supplier_id,
    project_ids,
    primary_project_id,
    visibility_scope_hash,
    last_refresh_reason,
    deleted_at
  ) values (
    p_organization_id,
    'supplier_invoice',
    p_source_id,
    version_id,
    'supplier_bill.v2',
    p_builder_version,
    p_content_hash,
    p_canonical_updated_at,
    p_latest_dependency_updated_at,
    p_validated_at,
    p_payload_bytes,
    p_context_status,
    p_supplier_id,
    normalized_project_ids,
    p_primary_project_id,
    p_visibility_scope_hash,
    p_refresh_reason,
    null
  )
  on conflict (organization_id, container_type, source_id)
  do update set
    current_version_id = excluded.current_version_id,
    schema_version = excluded.schema_version,
    builder_version = excluded.builder_version,
    content_hash = excluded.content_hash,
    canonical_updated_at = excluded.canonical_updated_at,
    latest_dependency_updated_at = excluded.latest_dependency_updated_at,
    validated_at = excluded.validated_at,
    payload_bytes = excluded.payload_bytes,
    context_status = excluded.context_status,
    supplier_id = excluded.supplier_id,
    project_ids = excluded.project_ids,
    primary_project_id = excluded.primary_project_id,
    visibility_scope_hash = excluded.visibility_scope_hash,
    last_refresh_reason = excluded.last_refresh_reason,
    deleted_at = null,
    updated_at = now();

  select count(*)::integer
  into version_count
  from public.supplier_bill_ucl_container_versions v
  where v.organization_id = p_organization_id
    and v.container_type = 'supplier_invoice'
    and v.source_id = p_source_id;

  return jsonb_build_object(
    'createdVersion', created_version,
    'reusedVersion', not created_version,
    'currentUpdated', true,
    'contentChanged', content_changed,
    'staleWriteRejected', false,
    'versionId', version_id,
    'currentHash', p_content_hash,
    'versionCount', version_count,
    'payloadBytes', p_payload_bytes,
    'contextStatus', p_context_status
  );
end;
$_$;


ALTER FUNCTION "public"."persist_supplier_bill_ucl_container"("p_queue_id" "uuid", "p_lease_token" "uuid", "p_organization_id" "uuid", "p_source_id" "uuid", "p_container_type" "text", "p_schema_version" "text", "p_builder_version" "text", "p_content_hash" "text", "p_payload_integrity_hash" "text", "p_canonical_updated_at" timestamp with time zone, "p_latest_dependency_updated_at" timestamp with time zone, "p_assembled_at" timestamp with time zone, "p_validated_at" timestamp with time zone, "p_payload_bytes" integer, "p_payload_json" "jsonb", "p_visibility_json" "jsonb", "p_project_ids" "uuid"[], "p_primary_project_id" "uuid", "p_supplier_id" "uuid", "p_visibility_scope_hash" "text", "p_context_status" "text", "p_refresh_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prepare_retention_claim_xero_sync"("p_retention_claim_id" "uuid", "p_actor_user_id" "uuid", "p_connection_id" "uuid", "p_tenant_id" "text", "p_retention_document_id" "uuid", "p_retention_source_evidence_hash" "text", "p_retention_pdf_sha256" "text", "p_payload_sha256" "text", "p_idempotency_key" "text", "p_contact_id" "text", "p_invoice_number" "text", "p_reference" "text", "p_invoice_date" "date", "p_due_date" "date", "p_subtotal_excl_tax" numeric, "p_tax_total" numeric, "p_total" numeric, "p_retention_mapping_id" "uuid", "p_organization_cost_code_id" "uuid", "p_xero_account_id" "text", "p_xero_account_code" "text", "p_tax_rate_id" "uuid", "p_xero_tax_type" "text", "p_tax_rate_basis_points" integer, "p_payload_snapshot" "jsonb", "p_lines" "jsonb", "p_correlation_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $_$
declare
  claim_row public.retention_claims%rowtype;
  project_row public.organization_projects%rowtype;
  retention_document_row public.retention_claim_documents%rowtype;
  connection_row public.organization_xero_connections%rowtype;
  accounting_document_row public.organization_accounting_documents%rowtype;
  accounting_snapshot_row public.retention_claim_accounting_snapshots%rowtype;
  current_source jsonb;
  current_source_hash text;
  active_job_id uuid;
  created_snapshot boolean := false;
  created_job boolean := false;
  supplied_line_count integer;
  allocation_count integer;
  supplied_subtotal numeric;
  supplied_tax numeric;
begin
  if auth.role() is distinct from 'service_role' then
    return jsonb_build_object(
      'succeeded', false, 'errorCode', 'permission_denied'
    );
  end if;

  select * into claim_row
  from public.retention_claims
  where id = p_retention_claim_id
  for update;
  if not found then
    return jsonb_build_object(
      'succeeded', false, 'errorCode', 'claim_not_found'
    );
  end if;

  if not private.retention_phase8_actor_has_permission(
    claim_row.organization_id,
    p_actor_user_id,
    'retention.claims.xero.manage'
  ) then
    return jsonb_build_object(
      'succeeded', false, 'errorCode', 'permission_denied'
    );
  end if;

  if claim_row.status <> 'submitted' then
    return jsonb_build_object(
      'succeeded', false, 'errorCode', 'claim_not_submitted'
    );
  end if;
  if claim_row.issue_date is null or claim_row.due_date is null then
    return jsonb_build_object(
      'succeeded', false, 'errorCode', 'invoice_dates_missing'
    );
  end if;

  if not exists (
    select 1 from public.organization_capabilities capability
    where capability.organization_id = claim_row.organization_id
      and capability.capability_key = 'retention_management'
      and capability.enabled = true
  ) or not exists (
    select 1 from public.project_retention_workflow_states state
    where state.organization_id = claim_row.organization_id
      and state.project_id = claim_row.project_id
      and state.mode = 'observe'
  ) then
    return jsonb_build_object(
      'succeeded', false, 'errorCode', 'project_mode_not_supported'
    );
  end if;

  select * into project_row
  from public.organization_projects
  where id = claim_row.project_id
    and organization_id = claim_row.organization_id;
  if project_row.client_id is null then
    return jsonb_build_object(
      'succeeded', false, 'errorCode', 'client_missing'
    );
  end if;

  select * into connection_row
  from public.organization_xero_connections
  where id = p_connection_id
    and organization_id = claim_row.organization_id
    and status = 'connected'
    and tenant_id = p_tenant_id;
  if not found then
    return jsonb_build_object(
      'succeeded', false, 'errorCode', 'xero_connection_invalid'
    );
  end if;

  if not exists (
    select 1
    from public.organization_external_contacts link
    join public.organization_xero_contacts contact
      on contact.organization_id = link.organization_id
     and contact.connection_id = link.accounting_connection_id
     and contact.tenant_id = link.tenant_id
     and contact.contact_id = link.external_contact_id
    where link.organization_id = claim_row.organization_id
      and link.provider = 'xero'
      and link.local_entity_type = 'client'
      and link.local_entity_id = project_row.client_id
      and link.accounting_connection_id = connection_row.id
      and link.tenant_id = connection_row.tenant_id
      and link.external_contact_id = p_contact_id
      and link.link_status = 'linked'
      and contact.contact_status not in ('ARCHIVED', 'GDPRREQUEST')
  ) then
    return jsonb_build_object(
      'succeeded', false, 'errorCode', 'client_contact_invalid'
    );
  end if;

  if not exists (
    select 1
    from public.organization_tradesstack_accounting_mappings mapping
    join public.organization_cost_codes cost_code
      on cost_code.id = mapping.organization_cost_code_id
     and cost_code.organization_id = mapping.organization_id
    where mapping.id = p_retention_mapping_id
      and mapping.organization_id = claim_row.organization_id
      and mapping.provider = 'xero'
      and mapping.tradesstack_cost_code = 700
      and mapping.is_active = true
      and (
        mapping.project_id = claim_row.project_id
        or mapping.project_id is null
      )
      and cost_code.id = p_organization_cost_code_id
      and cost_code.is_active = true
      and cost_code.external_provider = 'xero'
      and cost_code.external_code = p_xero_account_code
      and cost_code.metadata->>'accountId' = p_xero_account_id
      and cost_code.metadata->>'tenantId' = p_tenant_id
      and upper(cost_code.metadata->>'class') = 'ASSET'
      and upper(cost_code.metadata->>'type') = 'CURRENT'
  ) then
    return jsonb_build_object(
      'succeeded', false, 'errorCode', 'retention_mapping_invalid'
    );
  end if;

  if not exists (
    select 1
    from public.organization_accounting_tax_rates tax_rate
    where tax_rate.id = p_tax_rate_id
      and tax_rate.organization_id = claim_row.organization_id
      and tax_rate.provider = 'xero'
      and tax_rate.accounting_connection_id = connection_row.id
      and tax_rate.tenant_id = p_tenant_id
      and tax_rate.jurisdiction_code = 'NZ'
      and tax_rate.is_active = true
      and upper(tax_rate.status) = 'ACTIVE'
      and tax_rate.tax_type = p_xero_tax_type
      and round(tax_rate.effective_rate * 100)::integer =
        p_tax_rate_basis_points
      and p_tax_rate_basis_points = 1500
      and coalesce(
        (tax_rate.metadata->>'canApplyToRevenue')::boolean,
        false
      ) = true
  ) then
    return jsonb_build_object(
      'succeeded', false, 'errorCode', 'tax_mapping_invalid'
    );
  end if;

  select * into retention_document_row
  from public.retention_claim_documents
  where id = p_retention_document_id
    and organization_id = claim_row.organization_id
    and project_id = claim_row.project_id
    and retention_claim_id = claim_row.id
    and source_evidence_hash = p_retention_source_evidence_hash
    and pdf_sha256 = p_retention_pdf_sha256;
  if not found then
    return jsonb_build_object(
      'succeeded', false, 'errorCode', 'retention_document_invalid'
    );
  end if;

  current_source := private.retention_claim_document_source(claim_row.id);
  current_source_hash := encode(
    extensions.digest(convert_to(current_source::text, 'UTF8'), 'sha256'),
    'hex'
  );
  if current_source_hash is distinct from p_retention_source_evidence_hash then
    return jsonb_build_object(
      'succeeded', false,
      'errorCode', 'stale_retention_evidence',
      'currentRetentionSourceEvidenceHash', current_source_hash
    );
  end if;

  if p_invoice_number is distinct from claim_row.claim_number
     or p_invoice_date is distinct from claim_row.issue_date
     or p_due_date is distinct from claim_row.due_date
     or round(p_subtotal_excl_tax, 2)
       is distinct from claim_row.subtotal_excl_tax
     or round(p_tax_total, 2) < 0
     or round(p_total, 2) is distinct from
       round(p_subtotal_excl_tax + p_tax_total, 2)
     or p_payload_sha256 !~ '^[a-f0-9]{64}$'
     or p_idempotency_key !~ '^[a-f0-9]{64}$'
     or p_payload_snapshot is null
     or jsonb_typeof(p_payload_snapshot) <> 'object'
     or p_lines is null
     or jsonb_typeof(p_lines) <> 'array'
     or jsonb_array_length(p_lines) = 0 then
    return jsonb_build_object(
      'succeeded', false, 'errorCode', 'invalid_accounting_evidence'
    );
  end if;

  if p_payload_snapshot->>'Type' <> 'ACCREC'
     or p_payload_snapshot->>'InvoiceNumber' <> p_invoice_number
     or p_payload_snapshot->>'Reference' <> p_reference
     or p_payload_snapshot->>'Date' <> p_invoice_date::text
     or p_payload_snapshot->>'DueDate' <> p_due_date::text
     or p_payload_snapshot->>'CurrencyCode' <> 'NZD'
     or p_payload_snapshot->>'LineAmountTypes' <> 'Exclusive'
     or p_payload_snapshot->>'Status' <> 'AUTHORISED'
     or p_payload_snapshot#>>'{Contact,ContactID}' <> p_contact_id
     or jsonb_typeof(p_payload_snapshot->'LineItems') <> 'array'
     or jsonb_array_length(p_payload_snapshot->'LineItems')
       <> jsonb_array_length(p_lines)
     or exists (
       select 1
       from jsonb_array_elements(p_payload_snapshot->'LineItems')
         with ordinality payload_line(value, ordinal)
       full join jsonb_array_elements(p_lines)
         with ordinality evidence_line(value, ordinal)
         using(ordinal)
       where payload_line.value is null
          or evidence_line.value is null
          or payload_line.value->>'Description' <>
            evidence_line.value->>'description'
          or round((payload_line.value->>'Quantity')::numeric, 4) <> 1
          or round((payload_line.value->>'UnitAmount')::numeric, 2) <>
            round(
              (evidence_line.value->>'lineAmountExclTax')::numeric,
              2
            )
          or payload_line.value->>'AccountCode' <> p_xero_account_code
          or payload_line.value->>'TaxType' <> p_xero_tax_type
     ) then
    return jsonb_build_object(
      'succeeded', false, 'errorCode', 'invalid_xero_payload'
    );
  end if;

  with supplied as (
    select *
    from jsonb_to_recordset(p_lines) as line(
      "allocationId" uuid,
      "originatingPaymentClaimId" uuid,
      "sequence" integer,
      "description" text,
      "lineAmountExclTax" numeric,
      "taxAmount" numeric,
      "grossAmount" numeric,
      "originClaimNumber" text
    )
  )
  select
    count(*)::integer,
    coalesce(sum(round("lineAmountExclTax", 2)), 0),
    coalesce(sum(round("taxAmount", 2)), 0)
  into supplied_line_count, supplied_subtotal, supplied_tax
  from supplied;

  select count(*)::integer into allocation_count
  from public.retention_claim_allocations allocation
  where allocation.retention_claim_id = claim_row.id;

  if supplied_line_count <> allocation_count
     or supplied_subtotal <> claim_row.subtotal_excl_tax
     or supplied_tax <> round(p_tax_total, 2)
     or exists (
       with supplied as (
         select *
         from jsonb_to_recordset(p_lines) as line(
           "allocationId" uuid,
           "originatingPaymentClaimId" uuid,
           "sequence" integer,
           "description" text,
           "lineAmountExclTax" numeric,
           "taxAmount" numeric,
           "grossAmount" numeric,
           "originClaimNumber" text
         )
       )
       select 1
       from supplied line
       left join public.retention_claim_allocations allocation
         on allocation.id = line."allocationId"
        and allocation.retention_claim_id = claim_row.id
        and allocation.originating_payment_claim_id =
          line."originatingPaymentClaimId"
        and allocation.allocation_sequence = line."sequence"
        and allocation.allocation_amount =
          round(line."lineAmountExclTax", 2)
        and allocation.origin_claim_number_snapshot =
          line."originClaimNumber"
       where allocation.id is null
          or line."lineAmountExclTax" <= 0
          or line."taxAmount" < 0
          or round(line."taxAmount", 2) <>
            round(line."lineAmountExclTax" * 0.15, 2)
          or round(line."grossAmount", 2) <>
            round(line."lineAmountExclTax" + line."taxAmount", 2)
          or nullif(trim(line."description"), '') is null
     ) then
    return jsonb_build_object(
      'succeeded', false, 'errorCode', 'allocation_evidence_mismatch'
    );
  end if;

  select * into accounting_document_row
  from public.organization_accounting_documents
  where organization_id = claim_row.organization_id
    and provider = 'xero'
    and tenant_id = p_tenant_id
    and local_document_type = 'retention_claim'
    and retention_claim_id = claim_row.id
  for update;

  if found then
    if accounting_document_row.accounting_connection_id <> p_connection_id
       or accounting_document_row.external_document_id is not null then
      return jsonb_build_object(
        'succeeded', false, 'errorCode', 'accounting_document_locked'
      );
    end if;
  else
    insert into public.organization_accounting_documents(
      organization_id,
      accounting_connection_id,
      provider,
      tenant_id,
      local_document_type,
      local_document_id,
      project_claim_id,
      retention_claim_id,
      current_version_id,
      export_status,
      currency_code
    )
    values(
      claim_row.organization_id,
      p_connection_id,
      'xero',
      p_tenant_id,
      'retention_claim',
      null,
      null,
      claim_row.id,
      null,
      'not_ready',
      'NZD'
    )
    returning * into accounting_document_row;
  end if;

  select * into accounting_snapshot_row
  from public.retention_claim_accounting_snapshots
  where retention_claim_id = claim_row.id;
  if found then
    if accounting_snapshot_row.payload_sha256 <> p_payload_sha256
       or accounting_snapshot_row.retention_source_evidence_hash <>
         p_retention_source_evidence_hash
       or accounting_snapshot_row.retention_pdf_sha256 <>
         p_retention_pdf_sha256
       or accounting_snapshot_row.accounting_document_id <>
         accounting_document_row.id then
      return jsonb_build_object(
        'succeeded', false, 'errorCode', 'accounting_snapshot_conflict'
      );
    end if;
  else
    insert into public.retention_claim_accounting_snapshots(
      organization_id,
      project_id,
      retention_claim_id,
      accounting_document_id,
      retention_document_id,
      retention_source_evidence_hash,
      retention_pdf_sha256,
      payload_sha256,
      idempotency_key,
      connection_id_snapshot,
      tenant_id_snapshot,
      contact_id_snapshot,
      invoice_number_snapshot,
      reference_snapshot,
      invoice_date_snapshot,
      due_date_snapshot,
      subtotal_excl_tax_snapshot,
      tax_total_snapshot,
      total_snapshot,
      retention_mapping_id_snapshot,
      organization_cost_code_id_snapshot,
      xero_account_id_snapshot,
      xero_account_code_snapshot,
      tax_rate_id_snapshot,
      xero_tax_type_snapshot,
      tax_rate_basis_points_snapshot,
      payload_snapshot,
      created_by
    )
    values(
      claim_row.organization_id,
      claim_row.project_id,
      claim_row.id,
      accounting_document_row.id,
      retention_document_row.id,
      p_retention_source_evidence_hash,
      p_retention_pdf_sha256,
      p_payload_sha256,
      p_idempotency_key,
      p_connection_id,
      p_tenant_id,
      p_contact_id,
      p_invoice_number,
      p_reference,
      p_invoice_date,
      p_due_date,
      round(p_subtotal_excl_tax, 2),
      round(p_tax_total, 2),
      round(p_total, 2),
      p_retention_mapping_id,
      p_organization_cost_code_id,
      p_xero_account_id,
      p_xero_account_code,
      p_tax_rate_id,
      p_xero_tax_type,
      p_tax_rate_basis_points,
      p_payload_snapshot,
      p_actor_user_id
    )
    returning * into accounting_snapshot_row;
    created_snapshot := true;

    insert into public.retention_claim_accounting_lines(
      organization_id,
      project_id,
      retention_claim_id,
      accounting_snapshot_id,
      retention_claim_allocation_id,
      originating_payment_claim_id,
      sequence,
      description,
      line_amount_excl_tax,
      tax_amount,
      gross_amount,
      origin_claim_number_snapshot,
      retention_mapping_id_snapshot,
      organization_cost_code_id_snapshot,
      xero_account_id_snapshot,
      xero_account_code_snapshot,
      xero_tax_type_snapshot
    )
    select
      claim_row.organization_id,
      claim_row.project_id,
      claim_row.id,
      accounting_snapshot_row.id,
      line."allocationId",
      line."originatingPaymentClaimId",
      line."sequence",
      trim(line."description"),
      round(line."lineAmountExclTax", 2),
      round(line."taxAmount", 2),
      round(line."grossAmount", 2),
      line."originClaimNumber",
      p_retention_mapping_id,
      p_organization_cost_code_id,
      p_xero_account_id,
      p_xero_account_code,
      p_xero_tax_type
    from jsonb_to_recordset(p_lines) as line(
      "allocationId" uuid,
      "originatingPaymentClaimId" uuid,
      "sequence" integer,
      "description" text,
      "lineAmountExclTax" numeric,
      "taxAmount" numeric,
      "grossAmount" numeric,
      "originClaimNumber" text
    )
    order by line."sequence";

    insert into public.retention_claim_accounting_events(
      organization_id,
      project_id,
      retention_claim_id,
      accounting_document_id,
      accounting_snapshot_id,
      event_type,
      actor_user_id,
      correlation_id,
      metadata
    )
    values(
      claim_row.organization_id,
      claim_row.project_id,
      claim_row.id,
      accounting_document_row.id,
      accounting_snapshot_row.id,
      'accounting_snapshot_prepared',
      p_actor_user_id,
      p_correlation_id,
      jsonb_build_object(
        'payloadSha256', p_payload_sha256,
        'retentionSourceEvidenceHash', p_retention_source_evidence_hash,
        'retentionPdfSha256', p_retention_pdf_sha256,
        'subtotalExclTax', round(p_subtotal_excl_tax, 2),
        'taxTotal', round(p_tax_total, 2),
        'total', round(p_total, 2),
        'lineCount', supplied_line_count
      )
    );
  end if;

  select job.id into active_job_id
  from public.organization_accounting_sync_jobs job
  where job.organization_id = claim_row.organization_id
    and job.provider = 'xero'
    and job.connection_id = p_connection_id
    and job.job_kind = 'xero.retention_claim.sync'
    and job.queue_state in ('pending', 'claimed', 'retry_scheduled')
    and job.request_payload->>'accountingDocumentId' =
      accounting_document_row.id::text
  order by job.created_at desc
  limit 1;

  if active_job_id is null then
    insert into public.organization_accounting_sync_jobs(
      organization_id,
      provider,
      connection_id,
      job_kind,
      trigger_source,
      queue_state,
      request_payload,
      result_summary,
      idempotency_key,
      max_attempts,
      created_by_user_id
    )
    values(
      claim_row.organization_id,
      'xero',
      p_connection_id,
      'xero.retention_claim.sync',
      case when accounting_document_row.export_status in (
        'failed', 'attention_required'
      ) then 'user_retry' else 'user_export' end,
      'pending',
      jsonb_build_object(
        'accountingDocumentId', accounting_document_row.id,
        'accountingSnapshotId', accounting_snapshot_row.id,
        'payloadSha256', p_payload_sha256
      ),
      '{}'::jsonb,
      null,
      3,
      p_actor_user_id
    )
    returning id into active_job_id;
    created_job := true;

    insert into public.retention_claim_accounting_events(
      organization_id,
      project_id,
      retention_claim_id,
      accounting_document_id,
      accounting_snapshot_id,
      event_type,
      actor_user_id,
      correlation_id,
      metadata
    )
    values(
      claim_row.organization_id,
      claim_row.project_id,
      claim_row.id,
      accounting_document_row.id,
      accounting_snapshot_row.id,
      'xero_sync_queued',
      p_actor_user_id,
      p_correlation_id,
      jsonb_build_object('jobId', active_job_id)
    );
  end if;

  update public.organization_accounting_documents
  set
    export_status = case
      when exists (
        select 1 from public.organization_accounting_sync_jobs job
        where job.id = active_job_id and job.queue_state = 'claimed'
      ) then 'exporting'
      else 'queued'
    end,
    last_error_code = null,
    last_error_message = null
  where id = accounting_document_row.id;

  return jsonb_build_object(
    'succeeded', true,
    'errorCode', null,
    'createdSnapshot', created_snapshot,
    'createdJob', created_job,
    'accountingDocumentId', accounting_document_row.id,
    'accountingSnapshotId', accounting_snapshot_row.id,
    'jobId', active_job_id
  );
end;
$_$;


ALTER FUNCTION "public"."prepare_retention_claim_xero_sync"("p_retention_claim_id" "uuid", "p_actor_user_id" "uuid", "p_connection_id" "uuid", "p_tenant_id" "text", "p_retention_document_id" "uuid", "p_retention_source_evidence_hash" "text", "p_retention_pdf_sha256" "text", "p_payload_sha256" "text", "p_idempotency_key" "text", "p_contact_id" "text", "p_invoice_number" "text", "p_reference" "text", "p_invoice_date" "date", "p_due_date" "date", "p_subtotal_excl_tax" numeric, "p_tax_total" numeric, "p_total" numeric, "p_retention_mapping_id" "uuid", "p_organization_cost_code_id" "uuid", "p_xero_account_id" "text", "p_xero_account_code" "text", "p_tax_rate_id" "uuid", "p_xero_tax_type" "text", "p_tax_rate_basis_points" integer, "p_payload_snapshot" "jsonb", "p_lines" "jsonb", "p_correlation_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prepare_supplier_invoice_line_allocation_review_transition"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  review_fields_changed boolean := false;
begin
  new.approval_notes := coalesce(new.approval_notes, '');
  new.approval_checks_json := coalesce(new.approval_checks_json, '{}'::jsonb);
  new.ai_suggestion_metadata_json := coalesce(new.ai_suggestion_metadata_json, '{}'::jsonb);

  if tg_op = 'INSERT' then
    review_fields_changed := true;
  else
    review_fields_changed := (
      new.review_status is distinct from old.review_status
      or new.approval_status is distinct from old.approval_status
      or new.approval_notes is distinct from old.approval_notes
      or new.reviewed_by_user_id is distinct from old.reviewed_by_user_id
      or new.reviewed_at is distinct from old.reviewed_at
      or new.approved_by_user_id is distinct from old.approved_by_user_id
      or new.approved_at is distinct from old.approved_at
      or new.approval_checks_json is distinct from old.approval_checks_json
    );
  end if;

  if review_fields_changed
    and new.review_status in (
      'reviewed',
      'needs_cost_review',
      'needs_accounting_review',
      'resolved',
      'needs_routing_review',
      'needs_accounting_mapping',
      'high_value_review',
      'disputed'
    )
    and auth.uid() is not null
    and not public.has_org_permission(new.organization_id, 'supplier_invoices.review') then
    raise exception 'You do not have permission to review supplier invoice line allocations.';
  end if;

  if review_fields_changed
    and new.approval_status in ('approved', 'disputed')
    and auth.uid() is not null
    and not public.has_org_permission(new.organization_id, 'supplier_invoices.review') then
    raise exception 'You do not have permission to approve supplier invoice line allocations.';
  end if;

  if new.approval_status = 'pending' then
    new.approved_by_user_id := null;
    new.approved_at := null;
  elsif new.approved_at is null then
    new.approved_at := now();
  end if;

  if new.review_status in ('pending', 'auto_approved') then
    new.reviewed_by_user_id := null;
    new.reviewed_at := null;
  elsif new.reviewed_at is null then
    new.reviewed_at := now();
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."prepare_supplier_invoice_line_allocation_review_transition"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prepare_supplier_invoice_match_review_transition"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
begin
  new.approval_status := coalesce(new.approval_status, 'pending');
  new.approval_notes := coalesce(new.approval_notes, '');
  new.approval_checks_json := coalesce(new.approval_checks_json, '{}'::jsonb);

  if new.approval_status in ('approved', 'disputed')
    and not public.has_org_permission(new.organization_id, 'supplier_invoices.review') then
    raise exception 'You do not have permission to review supplier invoice allocations.';
  end if;

  if tg_op = 'UPDATE'
    and (
      new.matched_amount is distinct from old.matched_amount
      or new.match_status is distinct from old.match_status
      or new.purchase_order_id is distinct from old.purchase_order_id
    )
    and new.approval_status = old.approval_status
    and old.approval_status in ('approved', 'disputed') then
    new.approval_status := 'pending';
    new.approved_by_user_id := null;
    new.approved_at := null;
    new.approval_notes := '';
    new.approval_checks_json := '{}'::jsonb;
  end if;

  if new.approval_status = 'pending' then
    new.approved_by_user_id := null;
    new.approved_at := null;
  elsif new.approved_at is null then
    new.approved_at := now();
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."prepare_supplier_invoice_match_review_transition"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prepare_supplier_invoice_re_review"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  material_change_detected boolean := false;
  reviewed_allocation_count integer := 0;
begin
  material_change_detected :=
    new.supplier_id is distinct from old.supplier_id
    or new.invoice_date is distinct from old.invoice_date
    or new.due_date is distinct from old.due_date
    or new.subtotal is distinct from old.subtotal
    or new.tax_total is distinct from old.tax_total
    or new.total is distinct from old.total;

  if material_change_detected then
    select count(*)
    into reviewed_allocation_count
    from public.supplier_invoice_purchase_order_matches
    where organization_id = old.organization_id
      and supplier_invoice_id = old.id
      and match_status in ('accepted', 'adjusted')
      and approval_status in ('approved', 'disputed');

    if old.status in ('Approved', 'Disputed') or reviewed_allocation_count > 0 then
      new.status := 'Needs Review';
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."prepare_supplier_invoice_re_review"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prepare_supplier_invoice_xero_bill_export"("p_organization_id" "uuid", "p_supplier_invoice_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
declare
  v_invoice public.supplier_invoices%rowtype;
  v_approval public.supplier_invoice_commercial_approvals%rowtype;
  v_connection public.organization_xero_connections%rowtype;
  v_link public.organization_external_contacts%rowtype;
  v_contact public.organization_xero_contacts%rowtype;
  v_document_id uuid;
  v_version_id uuid;
  v_job_id uuid;
  v_finance_hash text;
  v_content_hash text;
  v_idempotency_key text;
  v_line_count integer;
  v_line_net numeric(14,2);
  v_line_tax numeric(14,2);
  v_po_numbers text[];
  v_line_amount_type text;
  v_existing_status text;
  v_document_status text;
begin
  if auth.uid() is null then
    raise exception 'Authentication is required.';
  end if;
  if not public.has_org_permission(p_organization_id, 'accounting.ap_bills.export') then
    raise exception 'You do not have permission to export Supplier Invoices to Xero.';
  end if;

  select * into v_invoice
  from public.supplier_invoices
  where id = p_supplier_invoice_id
    and organization_id = p_organization_id
  for update;
  if not found then
    raise exception 'Supplier invoice not found.';
  end if;

  select * into v_approval
  from public.supplier_invoice_commercial_approvals
  where supplier_invoice_id = v_invoice.id
    and organization_id = p_organization_id
    and status = 'approved'
  for update;
  if not found then
    raise exception 'An active commercial approval is required before Xero export.';
  end if;

  v_finance_hash := public.supplier_invoice_finance_version_hash(v_invoice.id);
  if v_finance_hash is null or v_finance_hash <> v_approval.finance_version_hash then
    raise exception 'The commercial approval no longer matches the current invoice finance version.';
  end if;
  if v_invoice.supplier_id is null then
    raise exception 'Select a supplier before Xero export.';
  end if;
  if char_length(trim(v_invoice.invoice_number)) = 0 then
    raise exception 'Enter an invoice number before Xero export.';
  end if;
  if v_invoice.invoice_date is null or v_invoice.due_date is null then
    raise exception 'Invoice and due dates are required before Xero export.';
  end if;
  if upper(trim(v_invoice.currency)) <> 'NZD' then
    raise exception 'Phase 3A supports NZD Supplier Invoices only.';
  end if;
  if abs((v_invoice.subtotal + v_invoice.tax_total) - v_invoice.total) > 0.01 then
    raise exception 'Invoice totals do not reconcile for Xero export.';
  end if;

  select * into v_connection
  from public.organization_xero_connections
  where organization_id = p_organization_id
    and status = 'connected'
    and tenant_id is not null
  for update;
  if not found
    or v_connection.last_health_status is distinct from 'healthy' then
    raise exception 'A healthy Xero connection is required before export.';
  end if;
  if not ('accounting.transactions' = any(v_connection.scope)) then
    raise exception 'Reconnect Xero to grant accounting.transactions before exporting Bills.';
  end if;

  select * into v_link
  from public.organization_external_contacts
  where organization_id = p_organization_id
    and accounting_connection_id = v_connection.id
    and provider = 'xero'
    and local_entity_type = 'supplier'
    and local_entity_id = v_invoice.supplier_id
    and tenant_id = v_connection.tenant_id
    and link_status = 'linked';
  if not found then
    raise exception 'The Supplier must be linked to an active Xero Contact before export.';
  end if;

  select * into v_contact
  from public.organization_xero_contacts
  where organization_id = p_organization_id
    and connection_id = v_connection.id
    and tenant_id = v_connection.tenant_id
    and contact_id = v_link.external_contact_id
    and coalesce(contact_status, 'ACTIVE') = 'ACTIVE';
  if not found then
    raise exception 'The linked Xero Contact is missing, archived, or belongs to another tenant.';
  end if;

  select
    count(*),
    coalesce(sum(snapshot.amount), 0),
    coalesce(sum(snapshot.tax_amount), 0),
    array_agg(distinct po.purchase_order_number order by po.purchase_order_number)
      filter (where po.purchase_order_number is not null)
  into v_line_count, v_line_net, v_line_tax, v_po_numbers
  from public.supplier_invoice_commercial_line_snapshots snapshot
  left join public.organization_tradesstack_accounting_mappings mapping
    on mapping.id = snapshot.accounting_mapping_id
    and mapping.organization_id = p_organization_id
    and mapping.is_active = true
  left join public.organization_accounting_route_mappings route_mapping
    on route_mapping.id = snapshot.accounting_route_mapping_id
    and route_mapping.organization_id = p_organization_id
    and route_mapping.accounting_route = snapshot.accounting_route
    and route_mapping.organization_cost_code_id = snapshot.organization_cost_code_id
    and route_mapping.is_active = true
  join public.organization_cost_codes cost_code
    on cost_code.id = coalesce(snapshot.organization_cost_code_id, mapping.organization_cost_code_id)
    and cost_code.organization_id = p_organization_id
    and cost_code.is_active = true
    and cost_code.external_provider = 'xero'
    and nullif(trim(cost_code.metadata ->> 'accountId'), '') is not null
    and nullif(trim(cost_code.external_code), '') is not null
    and coalesce(cost_code.metadata ->> 'tenantId', v_connection.tenant_id) = v_connection.tenant_id
  left join public.organization_accounting_tax_rates tax_rate
    on tax_rate.id = snapshot.accounting_tax_rate_id
    and tax_rate.organization_id = p_organization_id
    and tax_rate.provider = 'xero'
    and tax_rate.is_active = true
  left join public.project_purchase_orders po on po.id = snapshot.purchase_order_id
  where snapshot.organization_id = p_organization_id
    and snapshot.commercial_approval_id = v_approval.id
    and (
      (snapshot.accounting_mapping_id is not null and mapping.id is not null)
      or
      (snapshot.accounting_route = 'supplier_bill_expense'
        and (route_mapping.id is not null
          or snapshot.account_override_organization_cost_code_id = snapshot.organization_cost_code_id))
    )
    and (
      (snapshot.tax_resolution_status = 'not_applicable' and snapshot.accounting_tax_rate_id is null)
      or (
        snapshot.tax_resolution_status = 'resolved'
        and tax_rate.id is not null
        and nullif(trim(tax_rate.tax_type), '') is not null
      )
    );

  if v_line_count = 0 then
    raise exception 'The commercial approval has no Xero-ready line snapshots.';
  end if;
  if v_line_count <> (
    select count(*)
    from public.supplier_invoice_commercial_line_snapshots
    where commercial_approval_id = v_approval.id
  ) then
    raise exception 'Every approved commercial line requires an active Xero AccountID, AccountCode, and TaxType.';
  end if;
  if abs(v_line_net - v_invoice.subtotal) > 0.01
    or abs(v_line_tax - v_invoice.tax_total) > 0.01 then
    raise exception 'The approved commercial lines do not reconcile to the invoice totals.';
  end if;

  v_line_amount_type := case
    when v_invoice.tax_total <= 0.01 then 'NoTax'
    else 'Exclusive'
  end;
  v_po_numbers := coalesce(v_po_numbers, '{}'::text[]);
  v_idempotency_key := encode(
    extensions.digest(
      concat_ws(
        ':',
        p_organization_id::text,
        v_connection.id::text,
        v_connection.tenant_id,
        v_invoice.id::text,
        v_approval.id::text
      ),
      'sha256'
    ),
    'hex'
  );

  insert into public.organization_accounting_documents (
    organization_id,
    accounting_connection_id,
    provider,
    tenant_id,
    local_document_type,
    local_document_id,
    export_status,
    currency_code
  )
  values (
    p_organization_id,
    v_connection.id,
    'xero',
    v_connection.tenant_id,
    'supplier_invoice',
    v_invoice.id,
    'not_ready',
    'NZD'
  )
  on conflict (organization_id, provider, tenant_id, local_document_type, local_document_id)
  do update set accounting_connection_id = excluded.accounting_connection_id
  returning id, export_status into v_document_id, v_document_status;

  if v_document_status in ('queued', 'exporting', 'exported', 'attention_required') then
    raise exception 'This Supplier Invoice already has an active, exported, or uncertain Xero Bill operation.';
  end if;

  select id, status into v_version_id, v_existing_status
  from public.organization_accounting_document_versions
  where commercial_approval_id = v_approval.id;

  if v_version_id is null then
    v_content_hash := encode(
      extensions.digest(
        concat_ws(
          '|',
          v_finance_hash,
          v_link.external_contact_id,
          v_connection.id::text,
          v_connection.tenant_id,
          v_invoice.invoice_number,
          v_invoice.invoice_date::text,
          v_invoice.due_date::text,
          v_invoice.currency,
          v_invoice.subtotal::text,
          v_invoice.tax_total::text,
          v_invoice.total::text,
          array_to_string(v_po_numbers, ','),
          coalesce((
            select string_agg(
              concat_ws(
                ':',
                snapshot.id::text,
                snapshot.description,
                snapshot.quantity::text,
                snapshot.unit_rate::text,
                snapshot.amount::text,
                snapshot.tax_amount::text,
                coalesce(snapshot.accounting_route, mapping.tradesstack_cost_code::text),
                cost_code.metadata ->> 'accountId',
                cost_code.external_code,
                case
                  when snapshot.tax_resolution_status = 'not_applicable' then 'NONE'
                  else tax_rate.tax_type
                end
              ),
              ',' order by invoice_line.sort_order, snapshot.id
            )
            from public.supplier_invoice_commercial_line_snapshots snapshot
            left join public.supplier_invoice_lines invoice_line
              on invoice_line.id = snapshot.supplier_invoice_line_id
            left join public.organization_tradesstack_accounting_mappings mapping
              on mapping.id = snapshot.accounting_mapping_id
            left join public.organization_accounting_route_mappings route_mapping
              on route_mapping.id = snapshot.accounting_route_mapping_id
            join public.organization_cost_codes cost_code
              on cost_code.id = coalesce(snapshot.organization_cost_code_id, mapping.organization_cost_code_id)
            left join public.organization_accounting_tax_rates tax_rate
              on tax_rate.id = snapshot.accounting_tax_rate_id
            where snapshot.commercial_approval_id = v_approval.id
          ), '')
        ),
        'sha256'
      ),
      'hex'
    );

    insert into public.organization_accounting_document_versions (
      organization_id,
      document_id,
      commercial_approval_id,
      finance_hash,
      content_hash,
      idempotency_key,
      requested_external_status,
      contact_id_snapshot,
      contact_name_snapshot,
      supplier_link_id,
      connection_id_snapshot,
      tenant_id_snapshot,
      invoice_number_snapshot,
      invoice_date_snapshot,
      due_date_snapshot,
      currency_code_snapshot,
      subtotal_snapshot,
      tax_total_snapshot,
      total_snapshot,
      line_amount_type_snapshot,
      po_numbers_snapshot,
      readiness_snapshot,
      status,
      created_by
    )
    values (
      p_organization_id,
      v_document_id,
      v_approval.id,
      v_finance_hash,
      v_content_hash,
      v_idempotency_key,
      'DRAFT',
      v_link.external_contact_id,
      coalesce(nullif(trim(v_link.external_contact_name), ''), v_contact.name),
      v_link.id,
      v_connection.id,
      v_connection.tenant_id,
      trim(v_invoice.invoice_number),
      v_invoice.invoice_date,
      v_invoice.due_date,
      'NZD',
      v_invoice.subtotal,
      v_invoice.tax_total,
      v_invoice.total,
      v_line_amount_type,
      v_po_numbers,
      jsonb_build_object(
        'ready', true,
        'financeHash', v_finance_hash,
        'commercialApprovalId', v_approval.id,
        'supplierLinkId', v_link.id,
        'connectionId', v_connection.id,
        'tenantId', v_connection.tenant_id,
        'lineCount', v_line_count
      ),
      'prepared',
      auth.uid()
    )
    returning id into v_version_id;

    insert into public.organization_accounting_document_lines (
      organization_id,
      version_id,
      commercial_line_snapshot_id,
      source_invoice_line_id,
      source_allocation_id,
      sequence,
      description,
      quantity,
      unit_amount,
      line_amount,
      tax_amount,
      gross_amount,
      routing_code,
      accounting_mapping_id,
      accounting_route,
      accounting_route_mapping_id,
      accounting_source,
      organization_cost_code_id,
      xero_account_id,
      xero_account_code,
      xero_tax_type,
      project_id,
      purchase_order_id,
      purchase_order_line_item_id,
      purchase_order_number_snapshot
    )
    select
      p_organization_id,
      v_version_id,
      snapshot.id,
      snapshot.supplier_invoice_line_id,
      snapshot.allocation_id,
      row_number() over (order by invoice_line.sort_order, snapshot.id),
      trim(snapshot.description),
      snapshot.quantity,
      snapshot.unit_rate,
      snapshot.amount,
      snapshot.tax_amount,
      snapshot.amount + snapshot.tax_amount,
      case when snapshot.accounting_route is null then mapping.tradesstack_cost_code else null end,
      mapping.id,
      snapshot.accounting_route,
      snapshot.accounting_route_mapping_id,
      case
        when snapshot.account_override_organization_cost_code_id is not null then 'line_override'
        else 'route_mapping'
      end,
      cost_code.id,
      trim(cost_code.metadata ->> 'accountId'),
      trim(cost_code.external_code),
      case
        when snapshot.tax_resolution_status = 'not_applicable' then 'NONE'
        else trim(tax_rate.tax_type)
      end,
      snapshot.project_id,
      snapshot.purchase_order_id,
      snapshot.purchase_order_line_item_id,
      po.purchase_order_number
    from public.supplier_invoice_commercial_line_snapshots snapshot
    left join public.supplier_invoice_lines invoice_line
      on invoice_line.id = snapshot.supplier_invoice_line_id
    left join public.organization_tradesstack_accounting_mappings mapping
      on mapping.id = snapshot.accounting_mapping_id
    left join public.organization_accounting_route_mappings route_mapping
      on route_mapping.id = snapshot.accounting_route_mapping_id
    join public.organization_cost_codes cost_code
      on cost_code.id = coalesce(snapshot.organization_cost_code_id, mapping.organization_cost_code_id)
    left join public.organization_accounting_tax_rates tax_rate
      on tax_rate.id = snapshot.accounting_tax_rate_id
    left join public.project_purchase_orders po on po.id = snapshot.purchase_order_id
    where snapshot.commercial_approval_id = v_approval.id
    order by invoice_line.sort_order, snapshot.id;
  end if;

  select id into v_job_id
  from public.organization_accounting_sync_jobs
  where organization_id = p_organization_id
    and provider = 'xero'
    and connection_id = v_connection.id
    and job_kind = 'xero.bill.export'
    and request_payload ->> 'documentVersionId' = v_version_id::text
    and queue_state in ('pending', 'claimed', 'retry_scheduled')
  order by created_at desc
  limit 1;

  if v_existing_status = 'exported' then
    return jsonb_build_object(
      'documentId', v_document_id,
      'versionId', v_version_id,
      'jobId', v_job_id,
      'status', 'exported',
      'reused', true
    );
  end if;

  if v_job_id is null then
    select id into v_job_id
    from public.organization_accounting_sync_jobs
    where organization_id = p_organization_id
      and provider = 'xero'
      and connection_id = v_connection.id
      and job_kind = 'xero.bill.export'
      and request_payload ->> 'documentVersionId' = v_version_id::text
    order by created_at desc
    limit 1;
    if v_job_id is not null then
      update public.organization_accounting_sync_jobs
      set queue_state = 'pending',
          trigger_source = 'user_retry',
          result_summary = '{}'::jsonb,
          attempt_count = 0,
          available_at = now(),
          retry_after = null,
          claimed_at = null,
          claimed_by = null,
          claim_expires_at = null,
          last_completed_at = null,
          last_error = null,
          created_by_user_id = auth.uid()
      where id = v_job_id
        and queue_state = 'completed'
        and coalesce((result_summary ->> 'cancelled')::boolean, false) = true;
      if not found then
        raise exception 'The prior Xero Bill operation cannot be retried automatically.';
      end if;
    else
      insert into public.organization_accounting_sync_jobs (
        organization_id,
        provider,
        connection_id,
        job_kind,
        trigger_source,
        queue_state,
        request_payload,
        result_summary,
        idempotency_key,
        max_attempts,
        created_by_user_id
      )
      values (
        p_organization_id,
        'xero',
        v_connection.id,
        'xero.bill.export',
        'user_export',
        'pending',
        jsonb_build_object(
          'documentId', v_document_id,
          'documentVersionId', v_version_id,
          'supplierInvoiceId', v_invoice.id
        ),
        '{}'::jsonb,
        'xero.bill.export:' || v_idempotency_key,
        3,
        auth.uid()
      )
      returning id into v_job_id;
    end if;
  end if;

  update public.organization_accounting_documents
  set current_version_id = v_version_id,
      export_status = 'queued',
      last_error_code = null,
      last_error_message = null
  where id = v_document_id;

  update public.organization_accounting_document_versions
  set status = 'queued'
  where id = v_version_id;

  insert into public.supplier_invoice_activity_events (
    organization_id,
    supplier_invoice_id,
    event_type,
    message,
    metadata,
    created_by
  )
  values (
    p_organization_id,
    v_invoice.id,
    'xero_export_queued',
    'Draft Xero Bill export queued.',
    jsonb_build_object(
      'accounting_document_id', v_document_id,
      'accounting_document_version_id', v_version_id,
      'job_id', v_job_id
    ),
    auth.uid()
  );

  return jsonb_build_object(
    'documentId', v_document_id,
    'versionId', v_version_id,
    'jobId', v_job_id,
    'status', 'queued',
    'reused', v_existing_status is not null
  );
end;
$$;


ALTER FUNCTION "public"."prepare_supplier_invoice_xero_bill_export"("p_organization_id" "uuid", "p_supplier_invoice_id" "uuid") OWNER TO "postgres";


