CREATE OR REPLACE FUNCTION "public"."preview_supplier_bill_ucl_container_retention"("p_organization_id" "uuid" DEFAULT NULL::"uuid", "p_source_id" "uuid" DEFAULT NULL::"uuid", "p_as_of" timestamp with time zone DEFAULT "now"()) RETURNS TABLE("version_id" "uuid", "organization_id" "uuid", "source_id" "uuid", "content_hash" "text", "created_at" timestamp with time zone, "age_days" integer, "version_rank" bigint)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with ranked as (
    select
      v.*,
      row_number() over (
        partition by v.organization_id, v.container_type, v.source_id
        order by v.created_at desc, v.id desc
      ) as version_rank
    from public.supplier_bill_ucl_container_versions v
    where (p_organization_id is null or v.organization_id = p_organization_id)
      and (p_source_id is null or v.source_id = p_source_id)
  )
  select
    r.id,
    r.organization_id,
    r.source_id,
    r.content_hash,
    r.created_at,
    floor(extract(epoch from (p_as_of - r.created_at)) / 86400)::integer,
    r.version_rank
  from ranked r
  left join public.supplier_bill_ucl_current_state c
    on c.organization_id = r.organization_id
    and c.container_type = r.container_type
    and c.source_id = r.source_id
  where r.created_at < p_as_of - interval '90 days'
    and r.version_rank > 25
    and r.retention_hold = false
    and cardinality(r.milestone_codes) = 0
    and r.id is distinct from c.current_version_id
    and not exists (
      select 1
      from public.supplier_bill_ucl_container_version_holds h
      where h.version_id = r.id
        and h.organization_id = r.organization_id
    )
  order by r.organization_id, r.source_id, r.created_at, r.id;
$$;


ALTER FUNCTION "public"."preview_supplier_bill_ucl_container_retention"("p_organization_id" "uuid", "p_source_id" "uuid", "p_as_of" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."process_project_time_sheet_rules"("p_now" timestamp with time zone DEFAULT "now"(), "p_project_id" "uuid" DEFAULT NULL::"uuid", "p_max_rows" integer DEFAULT 2000) RETURNS TABLE("processed_warnings" integer, "processed_auto_clock_outs" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_now timestamptz := coalesce(p_now, now());
  v_limit integer := greatest(1, coalesce(p_max_rows, 2000));
begin
  return query
  with candidate_entries as (
    select
      e.id,
      e.organization_id,
      e.project_id,
      e.worker_name,
      e.notes,
      extract(epoch from (v_now - e.clock_in_at)) / 3600.0 as elapsed_hours
    from public.project_time_sheet_entries e
    where e.clock_out_at is null
      and e.clock_in_at <= (v_now - interval '8 hours 30 minutes')
      and (p_project_id is null or e.project_id = p_project_id)
    order by e.clock_in_at asc
    limit v_limit
  ),
  warning_targets as (
    select c.*
    from candidate_entries c
    join public.project_time_sheet_entries e on e.id = c.id
    where c.elapsed_hours >= 8.5
      and c.elapsed_hours < 10
      and e.warning_8h5_at is null
  ),
  warning_updates as (
    update public.project_time_sheet_entries e
      set warning_8h5_at = v_now
    from warning_targets t
    where e.id = t.id
    returning e.id, e.organization_id, e.project_id, e.worker_name
  ),
  warning_events as (
    insert into public.project_time_sheet_events (
      organization_id,
      project_id,
      entry_id,
      actor_user_id,
      worker_name,
      event_type,
      message
    )
    select
      w.organization_id,
      w.project_id,
      w.id,
      null,
      w.worker_name,
      'warning_8h5',
      w.worker_name || ' - 8.5h warning triggered'
    from warning_updates w
    returning id
  ),
  auto_targets as (
    select c.*
    from candidate_entries c
    where c.elapsed_hours >= 10
  ),
  auto_updates as (
    update public.project_time_sheet_entries e
      set clock_out_at = v_now,
          auto_clocked_out = true,
          auto_clocked_out_at = v_now,
          total_hours = round(t.elapsed_hours::numeric, 2),
          notes = case
            when position('Auto clock-out applied at 10 hour limit.' in coalesce(e.notes, '')) > 0 then e.notes
            when char_length(trim(coalesce(e.notes, ''))) = 0 then 'Auto clock-out applied at 10 hour limit.'
            else e.notes || E'\n' || 'Auto clock-out applied at 10 hour limit.'
          end
    from auto_targets t
    where e.id = t.id
      and e.clock_out_at is null
    returning e.id, e.organization_id, e.project_id, e.worker_name
  ),
  auto_events as (
    insert into public.project_time_sheet_events (
      organization_id,
      project_id,
      entry_id,
      actor_user_id,
      worker_name,
      event_type,
      message
    )
    select
      a.organization_id,
      a.project_id,
      a.id,
      null,
      a.worker_name,
      'auto_clock_out',
      'Auto clock-out applied - ' || a.worker_name || ' reached 10 hours'
    from auto_updates a
    returning id
  )
  select
    (select count(*)::integer from warning_updates) as processed_warnings,
    (select count(*)::integer from auto_updates) as processed_auto_clock_outs;
end;
$$;


ALTER FUNCTION "public"."process_project_time_sheet_rules"("p_now" timestamp with time zone, "p_project_id" "uuid", "p_max_rows" integer) OWNER TO "postgres";


