CREATE OR REPLACE FUNCTION "public"."publish_takeoff_commercial_purchase_order_v1"("p_input" "jsonb") RETURNS TABLE("purchase_order_id" "uuid", "purchase_order_line_id" "uuid", "purchase_order_number" "text", "commercial_item_id" "uuid", "target_mode" "text", "reused_commercial_item" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
#variable_conflict use_variable
declare
  actor_user_id uuid := auth.uid();
  org_id uuid := nullif(p_input->>'organizationId', '')::uuid;
  opp_id uuid := nullif(p_input->>'opportunityId', '')::uuid;
  project_id uuid := nullif(p_input->>'projectId', '')::uuid;
  data_project_id uuid := nullif(p_input->>'dataProjectId', '')::uuid;
  measurement_id uuid := nullif(p_input->>'measurementId', '')::uuid;
  supplier_id uuid := nullif(p_input->>'supplierId', '')::uuid;
  requested_po_id uuid := nullif(p_input->>'purchaseOrderId', '')::uuid;
  expected_updated_at timestamptz := nullif(p_input->>'expectedUpdatedAt', '')::timestamptz;
  description text := btrim(coalesce(p_input->>'description', ''));
  rate numeric := round(coalesce(nullif(p_input->>'rate', '')::numeric, 0), 2);
  mode text := btrim(coalesce(p_input->>'targetMode', ''));
  section_name text := btrim(coalesce(p_input->>'section', ''));
  requested_title text := coalesce(nullif(btrim(p_input->>'purchaseOrderTitle'), ''), 'New Purchase Order');
  request_key_value text := btrim(coalesce(p_input->>'requestKey', ''));
  request_fingerprint_value text;
  prior_result jsonb;
  po public.project_purchase_orders%rowtype;
  supplier public.organization_suppliers%rowtype;
  item record;
  created_po record;
  saved_po record;
  linked_row record;
  line_items jsonb := '[]'::jsonb;
  attachments jsonb := '[]'::jsonb;
  new_line_id uuid := gen_random_uuid();
  new_line_uid uuid := gen_random_uuid();
  existing_item_ids uuid[] := array[]::uuid[];
  was_reused boolean := false;
  result_value jsonb;
begin
  if actor_user_id is null then raise exception 'Authentication is required'; end if;
  if org_id is null or opp_id is null or project_id is null or data_project_id is null or measurement_id is null then
    raise exception 'organizationId, opportunityId, projectId, dataProjectId, and measurementId are required' using errcode = 'TS422';
  end if;
  if supplier_id is null then raise exception 'supplierId is required' using errcode = 'TS422'; end if;
  if description = '' then raise exception 'Description is required' using errcode = 'TS422'; end if;
  if rate < 0 then raise exception 'Rate must be non-negative' using errcode = 'TS422'; end if;
  if mode not in ('new', 'existing') then raise exception 'targetMode must be new or existing' using errcode = 'TS422'; end if;
  if section_name not in ('Labour', 'Materials', 'Subcontractors', 'Plant') then
    raise exception 'section must be Labour, Materials, Subcontractors, or Plant' using errcode = 'TS422';
  end if;
  if request_key_value = '' then raise exception 'requestKey is required' using errcode = 'TS422'; end if;
  if not public.has_org_permission(org_id, 'leads.opportunities.write')
    or not public.has_org_permission(org_id, 'purchase_orders.write') then
    raise exception 'Not authorized to publish Takeoff measurements to Purchase Orders';
  end if;
  if not exists (
    select 1 from public.organization_opportunities o
    where o.organization_id = org_id and o.id = opp_id
      and o.workspace_project_id = data_project_id and o.converted_project_id = project_id
  ) or not exists (
    select 1 from public.organization_projects p
    where p.organization_id = org_id and p.id = project_id and p.source_opportunity_id = opp_id
  ) then
    raise exception 'The Purchase Order Project is not the converted Project for this Takeoff Opportunity';
  end if;

  select s.* into supplier from public.organization_suppliers s
  where s.organization_id = org_id and s.id = supplier_id and s.is_active = true;
  if not found then raise exception 'Active supplier not found for organization'; end if;

  request_fingerprint_value := md5((p_input - 'requestKey')::text);
  perform pg_advisory_xact_lock(hashtextextended(org_id::text || ':' || request_key_value, 0));
  select r.result_json into prior_result
  from public.takeoff_purchase_order_publication_requests r
  where r.organization_id = org_id and r.request_key = request_key_value
    and r.request_fingerprint = request_fingerprint_value;
  if found then
    return query select
      (prior_result->>'purchaseOrderId')::uuid,
      (prior_result->>'purchaseOrderLineId')::uuid,
      prior_result->>'purchaseOrderNumber',
      (prior_result->>'commercialItemId')::uuid,
      prior_result->>'targetMode',
      coalesce((prior_result->>'reusedCommercialItem')::boolean, false);
    return;
  end if;
  if exists (
    select 1 from public.takeoff_purchase_order_publication_requests r
    where r.organization_id = org_id and r.request_key = request_key_value
  ) then raise exception 'requestKey was already used for a different Purchase Order publication' using errcode = 'TS409'; end if;

  if mode = 'new' then
    select * into created_po from public.create_project_purchase_order_draft(
      org_id, project_id, requested_title, 'Material Supply'
    );
    requested_po_id := created_po.id;
  elsif requested_po_id is null or expected_updated_at is null then
    raise exception 'purchaseOrderId and expectedUpdatedAt are required for an existing Purchase Order' using errcode = 'TS422';
  end if;

  select p.* into po from public.project_purchase_orders p
  where p.organization_id = org_id and p.project_id = project_id and p.id = requested_po_id
  for update;
  if not found then raise exception 'Draft Purchase Order not found for the converted Project' using errcode = 'TS404'; end if;
  if po.status <> 'Draft' then raise exception 'Only Draft Purchase Orders can receive Takeoff measurements' using errcode = 'TS409'; end if;
  if mode = 'existing' and po.updated_at is distinct from expected_updated_at then
    raise exception 'This Purchase Order was updated by another user. Refresh and try again.' using errcode = 'TS409';
  end if;
  if po.supplier_id is not null and po.supplier_id <> supplier_id then
    raise exception 'Selected supplier does not match the existing Purchase Order supplier' using errcode = 'TS409';
  end if;

  select coalesce(array_agg(ci.id), array[]::uuid[]) into existing_item_ids
  from public.commercial_items ci
  where ci.organization_id = org_id and ci.opportunity_id = opp_id
    and ci.source_type = 'takeoff_measurement' and ci.source_takeoff_measurement_id = measurement_id;

  select * into item from public.create_takeoff_commercial_item(jsonb_build_object(
    'organizationId', org_id, 'opportunityId', opp_id, 'projectId', project_id,
    'dataProjectId', data_project_id, 'measurementId', measurement_id,
    'description', description, 'rate', rate
  ));
  was_reused := item.id = any(existing_item_ids);

  select coalesce(jsonb_agg(jsonb_build_object(
    'id', li.id, 'line_uid', li.line_uid, 'cost_item_id', li.cost_item_id,
    'source_cost_item_id', li.source_cost_item_id, 'section', li.section,
    'description', li.description, 'quantity', li.quantity, 'unit', li.unit,
    'rate', li.rate, 'sort_order', li.sort_order,
    'source_time_sheet_entry_id', li.source_time_sheet_entry_id
  ) order by li.sort_order, li.created_at, li.id), '[]'::jsonb)
  into line_items
  from public.project_purchase_order_line_items li
  where li.organization_id = org_id and li.project_id = project_id and li.purchase_order_id = po.id;

  line_items := line_items || jsonb_build_array(jsonb_build_object(
    'id', new_line_id, 'line_uid', new_line_uid, 'cost_item_id', null,
    'source_cost_item_id', null, 'section', section_name, 'description', item.description,
    'quantity', item.quantity, 'unit', item.unit, 'rate', item.rate,
    'sort_order', jsonb_array_length(line_items), 'source_time_sheet_entry_id', null
  ));

  select coalesce(jsonb_agg(jsonb_build_object(
    'id', a.id, 'type', a.file_kind, 'name', a.file_name,
    'storagePath', a.storage_path, 'externalUrl', a.external_url, 'notes', a.notes
  ) order by a.created_at, a.id), '[]'::jsonb)
  into attachments
  from public.project_purchase_order_attachments a
  where a.organization_id = org_id and a.project_id = project_id and a.purchase_order_id = po.id;

  select * into saved_po from public.save_project_purchase_order_draft(
    org_id, project_id, po.id, po.updated_at, po.purchase_order_title,
    po.purchase_order_number, 'Draft', po.origin, supplier.id,
    coalesce(nullif(btrim(supplier.company_name), ''), supplier.name),
    coalesce(nullif(btrim(supplier.primary_contact_email), ''), supplier.email, ''),
    coalesce(nullif(btrim(supplier.company_name), ''), supplier.name),
    coalesce(nullif(btrim(supplier.primary_contact_email), ''), supplier.email, ''),
    coalesce(nullif(btrim(supplier.primary_contact_phone), ''), supplier.phone, ''),
    po.requested_by, po.requested_date, po.due_date, po.sent_to_client_at,
    po.approved_at, po.invoice_ready, po.notes, po.margin_percent,
    po.discount_amount, po.contingency_amount, po.gst_percent,
    po.include_margin_in_export, po.include_discount_in_export,
    po.include_contingency_in_export, line_items, attachments
  );

  select * into linked_row from public.link_commercial_item_to_purchase_order_line(jsonb_build_object(
    'organizationId', org_id, 'commercialItemId', item.id,
    'purchaseOrderId', po.id, 'purchaseOrderLineId', new_line_id,
    'linkRole', 'source',
    'snapshotAtLinkJson', jsonb_build_object(
      'description', item.description, 'quantity', item.quantity, 'unit', item.unit,
      'rate', item.rate, 'total', item.total, 'sourceType', item.source_type,
      'sourceTakeoffMeasurementId', item.source_takeoff_measurement_id,
      'sourceVersion', item.source_version, 'sourceLink', item.source_link_json
    )
  ));

  result_value := jsonb_build_object(
    'purchaseOrderId', po.id, 'purchaseOrderLineId', new_line_id,
    'purchaseOrderNumber', po.purchase_order_number, 'commercialItemId', item.id,
    'targetMode', mode, 'reusedCommercialItem', was_reused
  );
  insert into public.takeoff_purchase_order_publication_requests (
    organization_id, request_key, request_fingerprint, purchase_order_id,
    result_json, created_by
  ) values (org_id, request_key_value, request_fingerprint_value, po.id, result_value, actor_user_id);

  return query select po.id, new_line_id, po.purchase_order_number, item.id, mode, was_reused;
end;
$$;


ALTER FUNCTION "public"."publish_takeoff_commercial_purchase_order_v1"("p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."publish_takeoff_commercial_variation_v1"("p_input" "jsonb") RETURNS TABLE("variation_id" "uuid", "variation_line_id" "uuid", "variation_number" "text", "commercial_item_id" "uuid", "target_mode" "text", "status" "text", "reused_commercial_item" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
#variable_conflict use_variable
declare
  actor_user_id uuid := auth.uid();
  org_id uuid := nullif(p_input->>'organizationId', '')::uuid;
  opp_id uuid := nullif(p_input->>'opportunityId', '')::uuid;
  commercial_project_id uuid := nullif(p_input->>'projectId', '')::uuid;
  data_project_id uuid := nullif(p_input->>'dataProjectId', '')::uuid;
  measurement_id uuid := nullif(p_input->>'measurementId', '')::uuid;
  requested_variation_id uuid := nullif(p_input->>'variationId', '')::uuid;
  expected_updated_at timestamptz := nullif(p_input->>'expectedUpdatedAt', '')::timestamptz;
  commercial_description text := btrim(coalesce(p_input->>'description', ''));
  commercial_rate numeric := round(coalesce(nullif(p_input->>'rate', '')::numeric, 0), 2);
  mode text := btrim(coalesce(p_input->>'targetMode', ''));
  section_name text := btrim(coalesce(p_input->>'section', ''));
  requested_title text := btrim(coalesce(p_input->>'variationTitle', ''));
  request_key_value text := btrim(coalesce(p_input->>'requestKey', ''));
  request_fingerprint_value text;
  prior_result jsonb;
  variation_row public.project_variations%rowtype;
  commercial_item record;
  created_variation record;
  saved_variation record;
  linked_row record;
  line_items jsonb := '[]'::jsonb;
  attachments jsonb := '[]'::jsonb;
  new_line_id uuid := gen_random_uuid();
  existing_item_ids uuid[] := array[]::uuid[];
  was_reused boolean := false;
  result_value jsonb;
begin
  if actor_user_id is null then raise exception 'Authentication is required'; end if;
  if org_id is null or opp_id is null or commercial_project_id is null
    or data_project_id is null or measurement_id is null then
    raise exception 'organizationId, opportunityId, projectId, dataProjectId, and measurementId are required' using errcode = 'TS422';
  end if;
  if commercial_description = '' then raise exception 'Description is required' using errcode = 'TS422'; end if;
  if commercial_rate < 0 then raise exception 'Rate must be non-negative' using errcode = 'TS422'; end if;
  if mode not in ('new', 'existing') then raise exception 'targetMode must be new or existing' using errcode = 'TS422'; end if;
  if section_name not in ('Labour', 'Materials', 'Subcontractors', 'Plant', 'Margin') then
    raise exception 'section must be Labour, Materials, Subcontractors, Plant, or Margin' using errcode = 'TS422';
  end if;
  if mode = 'new' and requested_title = '' then raise exception 'variationTitle is required for a new Variation' using errcode = 'TS422'; end if;
  if request_key_value = '' then raise exception 'requestKey is required' using errcode = 'TS422'; end if;
  if not public.has_org_permission(org_id, 'leads.opportunities.write')
    or not public.has_org_permission(org_id, 'variations.write') then
    raise exception 'Not authorized to publish Takeoff measurements to Variations' using errcode = '42501';
  end if;

  if not exists (
    select 1 from public.organization_opportunities o
    where o.organization_id = org_id and o.id = opp_id
      and o.workspace_project_id = data_project_id
      and o.converted_project_id = commercial_project_id
  ) or not exists (
    select 1 from public.organization_projects p
    where p.organization_id = org_id and p.id = commercial_project_id
      and p.source_opportunity_id = opp_id
  ) then
    raise exception 'The Variation Project is not the converted Project for this Takeoff Opportunity' using errcode = 'TS404';
  end if;

  request_fingerprint_value := md5((p_input - 'requestKey')::text);
  perform pg_advisory_xact_lock(hashtextextended(org_id::text || ':' || request_key_value, 0));
  select request.result_json into prior_result
  from public.takeoff_variation_publication_requests request
  where request.organization_id = org_id and request.request_key = request_key_value
    and request.request_fingerprint = request_fingerprint_value;
  if found then
    return query select
      (prior_result->>'variationId')::uuid,
      (prior_result->>'variationLineId')::uuid,
      prior_result->>'variationNumber',
      (prior_result->>'commercialItemId')::uuid,
      prior_result->>'targetMode',
      prior_result->>'status',
      coalesce((prior_result->>'reusedCommercialItem')::boolean, false);
    return;
  end if;
  if exists (
    select 1 from public.takeoff_variation_publication_requests request
    where request.organization_id = org_id and request.request_key = request_key_value
  ) then
    raise exception 'requestKey was already used for a different Variation publication' using errcode = 'TS409';
  end if;

  if mode = 'new' then
    select * into created_variation
    from public.create_project_variation_draft(org_id, commercial_project_id, requested_title);
    requested_variation_id := created_variation.id;
  elsif requested_variation_id is null or expected_updated_at is null then
    raise exception 'variationId and expectedUpdatedAt are required for an existing Variation' using errcode = 'TS422';
  end if;

  select variation.* into variation_row
  from public.project_variations variation
  where variation.organization_id = org_id
    and variation.project_id = commercial_project_id
    and variation.id = requested_variation_id
  for update;
  if not found then raise exception 'Variation not found for the converted Project' using errcode = 'TS404'; end if;
  if variation_row.status not in ('Draft', 'Priced') then
    raise exception 'Only Draft or Priced Variations can receive Takeoff measurements' using errcode = 'TS409';
  end if;
  if mode = 'existing' and variation_row.updated_at is distinct from expected_updated_at then
    raise exception 'This Variation was updated by another user. Refresh and try again.' using errcode = 'TS409';
  end if;

  select coalesce(array_agg(item.id), array[]::uuid[]) into existing_item_ids
  from public.commercial_items item
  where item.organization_id = org_id and item.opportunity_id = opp_id
    and item.source_type = 'takeoff_measurement'
    and item.source_takeoff_measurement_id = measurement_id;

  select * into commercial_item
  from public.create_takeoff_commercial_item(jsonb_build_object(
    'organizationId', org_id, 'opportunityId', opp_id,
    'projectId', commercial_project_id, 'dataProjectId', data_project_id,
    'measurementId', measurement_id, 'description', commercial_description,
    'rate', commercial_rate
  ));
  was_reused := commercial_item.id = any(existing_item_ids);

  select coalesce(jsonb_agg(jsonb_build_object(
    'id', line.id, 'section', line.section, 'description', line.description,
    'quantity', line.quantity, 'unit', line.unit, 'rate', line.rate, 'total', line.total,
    'sourceProjectQuoteId', line.source_project_quote_id,
    'sourceProjectQuoteLineItemId', line.source_project_quote_line_item_id,
    'sourceProjectQuoteNumber', coalesce(line.source_project_quote_number, ''),
    'sourcePurchaseOrderId', line.source_purchase_order_id,
    'sourcePurchaseOrderLineItemId', line.source_purchase_order_line_item_id,
    'sourcePurchaseOrderNumber', coalesce(line.source_purchase_order_number, '')
  ) order by line.sort_order, line.created_at, line.id), '[]'::jsonb)
  into line_items
  from public.project_variation_line_items line
  where line.organization_id = org_id and line.project_id = commercial_project_id
    and line.variation_id = variation_row.id;

  line_items := line_items || jsonb_build_array(jsonb_build_object(
    'id', new_line_id, 'section', section_name,
    'description', commercial_item.description, 'quantity', commercial_item.quantity,
    'unit', commercial_item.unit, 'rate', commercial_item.rate, 'total', commercial_item.total,
    'sourceProjectQuoteId', null, 'sourceProjectQuoteLineItemId', null,
    'sourceProjectQuoteNumber', '', 'sourcePurchaseOrderId', null,
    'sourcePurchaseOrderLineItemId', null, 'sourcePurchaseOrderNumber', ''
  ));

  select coalesce(jsonb_agg(jsonb_build_object(
    'id', attachment.id, 'type', attachment.file_kind, 'name', attachment.file_name,
    'storagePath', attachment.storage_path, 'externalUrl', attachment.external_url
  ) order by attachment.created_at, attachment.id), '[]'::jsonb)
  into attachments
  from public.project_variation_attachments attachment
  where attachment.organization_id = org_id and attachment.project_id = commercial_project_id
    and attachment.variation_id = variation_row.id;

  select * into saved_variation
  from public.save_project_variation_draft(
    p_organization_id => org_id,
    p_project_id => commercial_project_id,
    p_variation_id => variation_row.id,
    p_expected_updated_at => variation_row.updated_at,
    p_variation_title => variation_row.variation_title,
    p_variation_number => variation_row.variation_number,
    p_status => variation_row.status,
    p_origin => variation_row.origin,
    p_requested_by => variation_row.requested_by,
    p_requested_date => variation_row.requested_date,
    p_due_date => variation_row.due_date,
    p_sent_to_client_at => variation_row.sent_to_client_at,
    p_approved_at => variation_row.approved_at,
    p_invoice_ready => variation_row.invoice_ready,
    p_notes => variation_row.notes,
    p_margin_percent => variation_row.margin_percent,
    p_discount_amount => variation_row.discount_amount,
    p_contingency_amount => variation_row.contingency_amount,
    p_gst_percent => variation_row.gst_percent,
    p_include_margin_in_export => variation_row.include_margin_in_export,
    p_include_discount_in_export => variation_row.include_discount_in_export,
    p_include_contingency_in_export => variation_row.include_contingency_in_export,
    p_validity_period => variation_row.validity_period,
    p_payment_terms => variation_row.payment_terms,
    p_lead_time => variation_row.lead_time,
    p_terms_inclusions => variation_row.terms_inclusions,
    p_terms_exclusions => variation_row.terms_exclusions,
    p_clarifications => variation_row.clarifications,
    p_assumptions => variation_row.assumptions,
    p_line_items => line_items,
    p_attachments => attachments
  );

  select * into linked_row
  from public.link_commercial_item_to_variation_line(jsonb_build_object(
    'organizationId', org_id, 'commercialItemId', commercial_item.id,
    'variationId', variation_row.id, 'variationLineId', new_line_id,
    'linkRole', 'source',
    'snapshotAtLinkJson', jsonb_build_object(
      'version', 1, 'commercialItemId', commercial_item.id,
      'description', commercial_item.description, 'quantity', commercial_item.quantity,
      'unit', commercial_item.unit, 'rate', commercial_item.rate,
      'total', commercial_item.total, 'sourceStatus', commercial_item.source_status,
      'sourceType', commercial_item.source_type,
      'sourceTakeoffMeasurementId', commercial_item.source_takeoff_measurement_id,
      'sourceVersion', commercial_item.source_version,
      'sourceLink', commercial_item.source_link_json
    )
  ));

  result_value := jsonb_build_object(
    'variationId', variation_row.id, 'variationLineId', new_line_id,
    'variationNumber', variation_row.variation_number,
    'commercialItemId', commercial_item.id, 'targetMode', mode,
    'status', saved_variation.status, 'reusedCommercialItem', was_reused
  );
  insert into public.takeoff_variation_publication_requests (
    organization_id, request_key, request_fingerprint, variation_id, result_json, created_by
  ) values (
    org_id, request_key_value, request_fingerprint_value,
    variation_row.id, result_value, actor_user_id
  );

  return query select variation_row.id, new_line_id, variation_row.variation_number,
    commercial_item.id, mode, saved_variation.status, was_reused;
end;
$$;


ALTER FUNCTION "public"."publish_takeoff_commercial_variation_v1"("p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."publish_worksheet_commercial_quote_v1"("p_input" "jsonb") RETURNS TABLE("id" "uuid", "updated_at" timestamp with time zone, "subtotal" numeric, "optional_subtotal" numeric, "gst_amount" numeric, "total_quote_price" numeric, "status" "text", "originating_opportunity_id" "uuid", "project_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  actor_user_id uuid := auth.uid();
  resolved_organization_id uuid := nullif(p_input->>'organizationId', '')::uuid;
  resolved_opportunity_id uuid := nullif(p_input->>'originatingOpportunityId', '')::uuid;
  resolved_quote_id uuid := nullif(p_input->>'quoteId', '')::uuid;
  resolved_request_key text := nullif(p_input->>'requestKey', '');
  existing_request public.worksheet_quote_publication_requests%rowtype;
  destination_quote public.project_quotes%rowtype;
  saved_row record;
  link jsonb;
begin
  if actor_user_id is null then
    raise exception 'Authentication is required';
  end if;
  if resolved_organization_id is null or resolved_request_key is null then
    raise exception 'organizationId and requestKey are required';
  end if;
  if not public.has_org_permission(resolved_organization_id, 'quotes.write') then
    raise exception 'Not authorized for this organization';
  end if;

  select request.* into existing_request
  from public.worksheet_quote_publication_requests request
  where request.organization_id = resolved_organization_id
    and request.request_key = resolved_request_key;

  if found then
    return query
    select quote.id, quote.updated_at, quote.subtotal, quote.optional_subtotal,
      quote.gst_amount, quote.total_quote_price, quote.status,
      quote.originating_opportunity_id, quote.project_id
    from public.project_quotes quote
    where quote.organization_id = resolved_organization_id
      and quote.id = existing_request.quote_id;
    return;
  end if;

  -- The picker is not an authorization boundary. Lock the submitted revision
  -- and its active series head so a concurrent revision cannot make this target
  -- historical between validation and save.
  if resolved_quote_id is not null then
    if resolved_opportunity_id is null then
      raise exception 'originatingOpportunityId is required for an existing quote destination'
        using errcode = 'TS422';
    end if;

    select quote.* into destination_quote
    from public.project_quotes quote
    join public.opportunity_quote_series series
      on series.organization_id = quote.organization_id
     and series.id = quote.quote_series_id
    where quote.organization_id = resolved_organization_id
      and quote.id = resolved_quote_id
      and quote.originating_opportunity_id = resolved_opportunity_id
      and quote.revision_kind = 'tender'
      and quote.status = 'Draft'
      and quote.award_locked_at is null
      and series.opportunity_id = resolved_opportunity_id
      and series.recipient_client_id is not null
      and series.current_revision_id = quote.id
      and series.archived_at is null
    for update of quote, series;

    if not found then
      raise exception 'Selected quote is not the current mutable Draft revision for this Opportunity'
        using errcode = 'TS409';
    end if;
  end if;

  select * into saved_row
  from public.save_commercial_quote_draft(
    p_organization_id => resolved_organization_id,
    p_originating_opportunity_id => resolved_opportunity_id,
    p_project_id => nullif(p_input->>'projectId', '')::uuid,
    p_quote_id => resolved_quote_id,
    p_expected_updated_at => nullif(p_input->>'expectedUpdatedAt', '')::timestamptz,
    p_quote_title => coalesce(p_input->>'quoteTitle', ''),
    p_quote_number => coalesce(p_input->>'quoteNumber', ''),
    p_client_name => coalesce(p_input->>'clientName', ''),
    p_company_name => coalesce(p_input->>'companyName', ''),
    p_contact_person => coalesce(p_input->>'contactPerson', ''),
    p_client_email => coalesce(p_input->>'clientEmail', ''),
    p_client_phone => coalesce(p_input->>'clientPhone', ''),
    p_site_address => coalesce(p_input->>'siteAddress', ''),
    p_project_name => coalesce(p_input->>'projectName', ''),
    p_quote_date => nullif(p_input->>'quoteDate', '')::date,
    p_expiry_date => nullif(p_input->>'expiryDate', '')::date,
    p_status => coalesce(p_input->>'status', 'Draft'),
    p_optional_items_notes => coalesce(p_input->>'optionalItemsNotes', ''),
    p_scope_exclusions => coalesce(p_input->>'scopeExclusions', ''),
    p_assumptions => coalesce(p_input->>'assumptions', ''),
    p_scope_notes => coalesce(p_input->>'scopeNotes', ''),
    p_margin_percent => coalesce(nullif(p_input->>'marginPercent', '')::numeric, 0),
    p_discount_amount => coalesce(nullif(p_input->>'discountAmount', '')::numeric, 0),
    p_contingency_amount => coalesce(nullif(p_input->>'contingencyAmount', '')::numeric, 0),
    p_gst_percent => coalesce(nullif(p_input->>'gstPercent', '')::numeric, 0),
    p_validity_period => coalesce(p_input->>'validityPeriod', ''),
    p_payment_terms => coalesce(p_input->>'paymentTerms', ''),
    p_retention_percent_default => coalesce(nullif(p_input->>'retentionPercentDefault', '')::numeric, 0),
    p_lead_time => coalesce(p_input->>'leadTime', ''),
    p_terms_inclusions => coalesce(p_input->>'termsInclusions', ''),
    p_terms_exclusions => coalesce(p_input->>'termsExclusions', ''),
    p_clarifications => coalesce(p_input->>'clarifications', ''),
    p_acceptance_notes => coalesce(p_input->>'acceptanceNotes', ''),
    p_line_items => coalesce(p_input->'lineItems', '[]'::jsonb)
  );

  perform public.repair_project_quote_source_opportunity_lineage(
    resolved_organization_id,
    saved_row.id
  );

  for link in
    select value from jsonb_array_elements(coalesce(p_input->'commercialItemLinks', '[]'::jsonb))
  loop
    perform public.link_commercial_item_to_quote_line(jsonb_build_object(
      'organizationId', resolved_organization_id,
      'commercialItemId', link->>'commercialItemId',
      'quoteId', saved_row.id,
      'quoteLineId', link->>'quoteLineId',
      'linkRole', 'source',
      'snapshotAtLinkJson', coalesce(link->'snapshotAtLinkJson', '{}'::jsonb)
    ));
  end loop;

  perform public.validate_and_record_quote_publication_v1(
    resolved_organization_id,
    saved_row.id
  );

  insert into public.worksheet_quote_publication_requests (
    organization_id,
    request_key,
    quote_id,
    created_by
  ) values (
    resolved_organization_id,
    resolved_request_key,
    saved_row.id,
    actor_user_id
  );

  return query
  select quote.id, quote.updated_at, quote.subtotal, quote.optional_subtotal,
    quote.gst_amount, quote.total_quote_price, quote.status,
    quote.originating_opportunity_id, quote.project_id
  from public.project_quotes quote
  where quote.organization_id = resolved_organization_id
    and quote.id = saved_row.id;
end;
$$;


ALTER FUNCTION "public"."publish_worksheet_commercial_quote_v1"("p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."publish_worksheet_commercial_quotes_v1"("p_input" "jsonb") RETURNS TABLE("id" "uuid", "updated_at" timestamp with time zone, "subtotal" numeric, "optional_subtotal" numeric, "gst_amount" numeric, "total_quote_price" numeric, "status" "text", "originating_opportunity_id" "uuid", "project_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  actor_user_id uuid := auth.uid();
  resolved_organization_id uuid := nullif(p_input->>'organizationId', '')::uuid;
  resolved_opportunity_id uuid := nullif(p_input->>'originatingOpportunityId', '')::uuid;
  destinations jsonb := coalesce(p_input->'destinations', '[]'::jsonb);
  destination jsonb;
  replay_request public.worksheet_quote_publication_requests%rowtype;
  locked_quote_id uuid;
begin
  if actor_user_id is null then
    raise exception 'Authentication is required';
  end if;
  if resolved_organization_id is null or resolved_opportunity_id is null then
    raise exception 'organizationId and originatingOpportunityId are required'
      using errcode = 'TS422';
  end if;
  if not public.has_org_permission(resolved_organization_id, 'quotes.write') then
    raise exception 'Not authorized for this organization';
  end if;
  if jsonb_typeof(destinations) <> 'array' or jsonb_array_length(destinations) = 0 then
    raise exception 'At least one Quote destination is required'
      using errcode = 'TS422';
  end if;
  if jsonb_array_length(destinations) > 50 then
    raise exception 'No more than 50 Quote destinations may be published at once'
      using errcode = 'TS422';
  end if;
  if exists (
    select 1
    from jsonb_array_elements(destinations) item
    group by item->>'quoteId'
    having count(*) > 1
  ) or exists (
    select 1
    from jsonb_array_elements(destinations) item
    group by item->>'requestKey'
    having count(*) > 1
  ) then
    raise exception 'Quote destinations and request keys must be unique'
      using errcode = 'TS422';
  end if;

  -- Validate and lock every fresh destination before the first mutation. The
  -- canonical quote-id order prevents two overlapping requests from acquiring
  -- the same Quote/series locks in different orders.
  for destination in
    select item.value
    from jsonb_array_elements(destinations) item
    order by item.value->>'quoteId'
  loop
    if nullif(destination->>'quoteId', '') is null
      or nullif(destination->>'requestKey', '') is null
      or nullif(destination->>'expectedUpdatedAt', '') is null
      or nullif(destination->>'organizationId', '')::uuid is distinct from resolved_organization_id
      or nullif(destination->>'originatingOpportunityId', '')::uuid is distinct from resolved_opportunity_id
    then
      raise exception 'Every destination requires matching organization, Opportunity, Quote, request key, and expected version'
        using errcode = 'TS422';
    end if;

    select request.* into replay_request
    from public.worksheet_quote_publication_requests request
    where request.organization_id = resolved_organization_id
      and request.request_key = destination->>'requestKey';

    if found then
      if replay_request.quote_id is distinct from (destination->>'quoteId')::uuid then
        raise exception 'Publication request key belongs to a different Quote destination'
          using errcode = 'TS409';
      end if;
      continue;
    end if;

    locked_quote_id := null;
    select quote.id into locked_quote_id
    from public.project_quotes quote
    join public.opportunity_quote_series series
      on series.organization_id = quote.organization_id
     and series.id = quote.quote_series_id
    where quote.organization_id = resolved_organization_id
      and quote.id = (destination->>'quoteId')::uuid
      and quote.originating_opportunity_id = resolved_opportunity_id
      and quote.revision_kind = 'tender'
      and quote.status = 'Draft'
      and quote.award_locked_at is null
      and quote.updated_at = (destination->>'expectedUpdatedAt')::timestamptz
      and series.opportunity_id = resolved_opportunity_id
      and series.recipient_client_id is not null
      and series.current_revision_id = quote.id
      and series.archived_at is null
    for update of quote, series;

    if locked_quote_id is null then
      raise exception 'A selected Quote is no longer a current mutable Draft at the expected version'
        using errcode = 'TS409';
    end if;
  end loop;

  -- Each call retains destination-scoped idempotency and concurrency checks,
  -- while the enclosing function makes the complete destination set atomic.
  for destination in
    select item.value
    from jsonb_array_elements(destinations) item
    order by item.value->>'quoteId'
  loop
    return query
    select published.*
    from public.publish_worksheet_commercial_quote_v1(destination) published;
  end loop;
end;
$$;


ALTER FUNCTION "public"."publish_worksheet_commercial_quotes_v1"("p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."publish_worksheet_commercial_variation_v1"("p_input" "jsonb") RETURNS TABLE("id" "uuid", "updated_at" timestamp with time zone, "status" "text", "variation_number" "text", "added_line_count" integer, "skipped_row_count" integer, "variation_line_ids" "uuid"[], "commercial_item_ids" "uuid"[])
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  actor_user_id uuid := auth.uid();
  resolved_organization_id uuid := nullif(p_input->>'organizationId', '')::uuid;
  resolved_opportunity_id uuid := nullif(p_input->>'opportunityId', '')::uuid;
  resolved_project_id uuid := nullif(p_input->>'projectId', '')::uuid;
  resolved_variation_id uuid := nullif(p_input->>'variationId', '')::uuid;
  resolved_workbook_id uuid := nullif(p_input->>'workbookId', '')::uuid;
  resolved_worksheet_id uuid := nullif(p_input->>'worksheetId', '')::uuid;
  resolved_sheet_id uuid := nullif(p_input->>'sheetId', '')::uuid;
  resolved_request_key text := nullif(p_input->>'requestKey', '');
  resolved_expected_updated_at timestamptz := nullif(p_input->>'expectedUpdatedAt', '')::timestamptz;
  resolved_source_version integer := coalesce(nullif(p_input->>'worksheetVersion', '')::integer, 1);
  resolved_skipped_count integer := coalesce(nullif(p_input->>'skippedRowCount', '')::integer, 0);
  existing_request public.worksheet_variation_publication_requests%rowtype;
  variation_row public.project_variations%rowtype;
  saved_row record;
  source_row jsonb;
  source_ordinality bigint;
  source_line_id uuid;
  source_section text;
  commercial_item_id uuid;
  accumulated_line_items jsonb := coalesce(p_input->'existingLineItems', '[]'::jsonb);
  accumulated_line_ids uuid[] := array[]::uuid[];
  accumulated_commercial_item_ids uuid[] := array[]::uuid[];
  result_payload jsonb;
begin
  if actor_user_id is null then
    raise exception 'Authentication is required';
  end if;
  if resolved_organization_id is null or resolved_opportunity_id is null or resolved_project_id is null
    or resolved_variation_id is null or resolved_workbook_id is null or resolved_worksheet_id is null
    or resolved_sheet_id is null or resolved_request_key is null or resolved_expected_updated_at is null then
    raise exception 'Organization, opportunity, project, Variation, worksheet, sheet, request key, and expected version are required';
  end if;
  if not public.has_org_permission(resolved_organization_id, 'variations.write') then
    raise exception 'Not authorized to publish worksheet lines to this Variation' using errcode = '42501';
  end if;
  if not public.has_org_permission(resolved_organization_id, 'leads.opportunities.write') then
    raise exception 'Not authorized to create worksheet commercial items' using errcode = '42501';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(resolved_organization_id::text || ':' || resolved_request_key, 0));

  select request.* into existing_request
  from public.worksheet_variation_publication_requests request
  where request.organization_id = resolved_organization_id
    and request.request_key = resolved_request_key;

  if found then
    if existing_request.variation_id <> resolved_variation_id then
      raise exception 'Variation publication request key belongs to another Variation' using errcode = 'TS409';
    end if;
    return query select
      existing_request.variation_id,
      (existing_request.result_json->>'updatedAt')::timestamptz,
      existing_request.result_json->>'status',
      existing_request.result_json->>'variationNumber',
      (existing_request.result_json->>'addedLineCount')::integer,
      (existing_request.result_json->>'skippedRowCount')::integer,
      array(select jsonb_array_elements_text(existing_request.result_json->'variationLineIds')::uuid),
      array(select jsonb_array_elements_text(existing_request.result_json->'commercialItemIds')::uuid);
    return;
  end if;

  select variation.* into variation_row
  from public.project_variations variation
  where variation.organization_id = resolved_organization_id
    and variation.project_id = resolved_project_id
    and variation.id = resolved_variation_id
  for update;

  if not found then
    raise exception 'Variation not found for organization and project';
  end if;
  if variation_row.status not in ('Draft', 'Priced') then
    raise exception 'This variation can no longer be changed from the pricing worksheet.' using errcode = 'TS409';
  end if;
  if variation_row.updated_at is distinct from resolved_expected_updated_at then
    raise exception 'This variation changed while the worksheet mapping was open. Refresh and try again.' using errcode = 'TS409';
  end if;
  if not exists (
    select 1 from public.organization_projects project
    where project.organization_id = resolved_organization_id
      and project.id = resolved_project_id
      and project.source_opportunity_id = resolved_opportunity_id
  ) then
    raise exception 'Project and opportunity lineage do not match';
  end if;
  if not exists (
    select 1 from public.opportunity_pricing_worksheets workbook
    where workbook.organization_id = resolved_organization_id
      and workbook.opportunity_id = resolved_opportunity_id
      and workbook.project_id = resolved_project_id
      and workbook.variation_id = resolved_variation_id
      and workbook.id = resolved_workbook_id
  ) then
    raise exception 'Worksheet does not belong to the target Variation';
  end if;
  if resolved_worksheet_id <> resolved_workbook_id then
    raise exception 'Worksheet identity must match its workbook identity';
  end if;
  if not exists (
    select 1 from public.opportunity_pricing_workbook_sheets sheet
    where sheet.organization_id = resolved_organization_id
      and sheet.opportunity_id = resolved_opportunity_id
      and sheet.workbook_id = resolved_workbook_id
      and sheet.id = resolved_sheet_id
  ) then
    raise exception 'Worksheet sheet does not belong to the source workbook';
  end if;
  if jsonb_typeof(coalesce(p_input->'commercialRows', '[]'::jsonb)) <> 'array'
    or jsonb_array_length(coalesce(p_input->'commercialRows', '[]'::jsonb)) = 0 then
    raise exception 'At least one mapped commercial row is required';
  end if;

  for source_row in select value from jsonb_array_elements(p_input->'commercialRows')
  loop
    source_line_id := nullif(source_row->>'lineId', '')::uuid;
    source_section := nullif(source_row->>'section', '');
    if source_line_id is null then
      raise exception 'Every mapped Variation row requires a stable line ID';
    end if;
    if source_section not in ('Labour', 'Materials', 'Subcontractors', 'Plant', 'Margin') then
      raise exception 'Variation section is invalid';
    end if;
    if coalesce(nullif(btrim(source_row->>'sourceRange'), ''), '') = ''
      or coalesce(nullif(btrim(source_row->>'sourceSignature'), ''), '') = '' then
      raise exception 'Mapped worksheet provenance is incomplete';
    end if;

    select item.id into commercial_item_id
    from public.commercial_items item
    where item.organization_id = resolved_organization_id
      and item.opportunity_id = resolved_opportunity_id
      and item.project_id = resolved_project_id
      and item.source_workbook_id = resolved_workbook_id
      and item.source_worksheet_id = resolved_worksheet_id
      and item.source_sheet_id = resolved_sheet_id
      and item.source_range = source_row->>'sourceRange'
      and item.source_signature = source_row->>'sourceSignature'
    order by item.created_at asc
    limit 1;

    if commercial_item_id is null then
      select created.id into commercial_item_id
      from public.create_commercial_item(jsonb_build_object(
        'organizationId', resolved_organization_id,
        'opportunityId', resolved_opportunity_id,
        'projectId', resolved_project_id,
        'sourceType', 'worksheet_selection',
        'sourceWorkbookId', resolved_workbook_id,
        'sourceWorksheetId', resolved_worksheet_id,
        'sourceSheetId', resolved_sheet_id,
        'sourceRange', source_row->>'sourceRange',
        'sourceSignature', source_row->>'sourceSignature',
        'sourceVersion', resolved_source_version,
        'sourceStatus', 'current',
        'description', coalesce(source_row->>'description', ''),
        'quantity', source_row->'quantity',
        'unit', source_row->'unit',
        'rate', source_row->'rate',
        'total', source_row->'total',
        'snapshotJson', coalesce(source_row->'snapshotJson', '{}'::jsonb),
        'sourceLinkJson', coalesce(source_row->'sourceLinkJson', '{}'::jsonb),
        'lockedMetadataJson', coalesce(source_row->'lockedMetadataJson', '{}'::jsonb),
        'uclValidationStatus', 'not_reviewed'
      )) created;
    end if;

    accumulated_line_items := accumulated_line_items || jsonb_build_array(jsonb_build_object(
      'id', source_line_id,
      'section', source_section,
      'description', coalesce(source_row->>'description', ''),
      'quantity', source_row->'quantity',
      'unit', source_row->'unit',
      'rate', source_row->'rate',
      'total', source_row->'total',
      'sourceProjectQuoteId', null,
      'sourceProjectQuoteLineItemId', null,
      'sourceProjectQuoteNumber', '',
      'sourcePurchaseOrderId', null,
      'sourcePurchaseOrderLineItemId', null,
      'sourcePurchaseOrderNumber', ''
    ));
    accumulated_line_ids := array_append(accumulated_line_ids, source_line_id);
    accumulated_commercial_item_ids := array_append(accumulated_commercial_item_ids, commercial_item_id);
  end loop;

  select * into saved_row
  from public.save_project_variation_draft(
    p_organization_id => resolved_organization_id,
    p_project_id => resolved_project_id,
    p_variation_id => resolved_variation_id,
    p_expected_updated_at => resolved_expected_updated_at,
    p_variation_title => coalesce(p_input->'variation'->>'title', variation_row.variation_title),
    p_variation_number => coalesce(p_input->'variation'->>'number', variation_row.variation_number),
    p_status => variation_row.status,
    p_origin => coalesce(p_input->'variation'->>'origin', variation_row.origin),
    p_requested_by => coalesce(p_input->'variation'->>'requestedBy', variation_row.requested_by),
    p_requested_date => nullif(p_input->'variation'->>'requestedDate', '')::date,
    p_due_date => nullif(p_input->'variation'->>'dueDate', '')::date,
    p_sent_to_client_at => nullif(p_input->'variation'->>'sentToClientAt', '')::timestamptz,
    p_approved_at => nullif(p_input->'variation'->>'approvedAt', '')::timestamptz,
    p_invoice_ready => coalesce((p_input->'variation'->>'invoiceReady')::boolean, false),
    p_notes => coalesce(p_input->'variation'->>'notes', ''),
    p_margin_percent => coalesce((p_input->'variation'->>'marginPercent')::numeric, 0),
    p_discount_amount => coalesce((p_input->'variation'->>'discountAmount')::numeric, 0),
    p_contingency_amount => coalesce((p_input->'variation'->>'contingencyAmount')::numeric, 0),
    p_gst_percent => coalesce((p_input->'variation'->>'gstPercent')::numeric, 0),
    p_include_margin_in_export => coalesce((p_input->'variation'->>'includeMarginInExport')::boolean, true),
    p_include_discount_in_export => coalesce((p_input->'variation'->>'includeDiscountInExport')::boolean, false),
    p_include_contingency_in_export => coalesce((p_input->'variation'->>'includeContingencyInExport')::boolean, false),
    p_validity_period => coalesce(p_input->'variation'->>'validityPeriod', ''),
    p_payment_terms => coalesce(p_input->'variation'->>'paymentTerms', ''),
    p_lead_time => coalesce(p_input->'variation'->>'leadTime', ''),
    p_terms_inclusions => coalesce(p_input->'variation'->>'termsInclusions', ''),
    p_terms_exclusions => coalesce(p_input->'variation'->>'termsExclusions', ''),
    p_clarifications => coalesce(p_input->'variation'->>'clarifications', ''),
    p_assumptions => coalesce(p_input->'variation'->>'assumptions', ''),
    p_line_items => accumulated_line_items,
    p_attachments => coalesce(p_input->'attachments', '[]'::jsonb)
  );

  for source_row, source_ordinality in
    select value, ordinality
    from jsonb_array_elements(p_input->'commercialRows') with ordinality
  loop
    perform public.link_commercial_item_to_variation_line(jsonb_build_object(
      'organizationId', resolved_organization_id,
      'commercialItemId', accumulated_commercial_item_ids[source_ordinality::integer],
      'variationId', resolved_variation_id,
      'variationLineId', accumulated_line_ids[source_ordinality::integer],
      'linkRole', 'source',
      'snapshotAtLinkJson', jsonb_build_object(
        'version', 1,
        'commercialItemId', accumulated_commercial_item_ids[source_ordinality::integer],
        'description', source_row->>'description',
        'quantity', source_row->'quantity',
        'unit', source_row->'unit',
        'rate', source_row->'rate',
        'total', source_row->'total',
        'sourceStatus', 'current',
        'sourceRange', source_row->>'sourceRange',
        'sourceWorkbookId', resolved_workbook_id,
        'sourceWorksheetId', resolved_worksheet_id,
        'sourceSheetId', resolved_sheet_id,
        'sourceLink', coalesce(source_row->'sourceLinkJson', '{}'::jsonb)
      )
    ));
  end loop;

  result_payload := jsonb_build_object(
    'updatedAt', saved_row.updated_at,
    'status', saved_row.status,
    'variationNumber', variation_row.variation_number,
    'addedLineCount', cardinality(accumulated_line_ids),
    'skippedRowCount', resolved_skipped_count,
    'variationLineIds', to_jsonb(accumulated_line_ids),
    'commercialItemIds', to_jsonb(accumulated_commercial_item_ids)
  );

  insert into public.worksheet_variation_publication_requests (
    organization_id, request_key, variation_id, result_json, created_by
  ) values (
    resolved_organization_id, resolved_request_key, resolved_variation_id, result_payload, actor_user_id
  );

  return query select
    resolved_variation_id,
    saved_row.updated_at::timestamptz,
    saved_row.status::text,
    variation_row.variation_number,
    cardinality(accumulated_line_ids),
    resolved_skipped_count,
    accumulated_line_ids,
    accumulated_commercial_item_ids;
end;
$$;


ALTER FUNCTION "public"."publish_worksheet_commercial_variation_v1"("p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."purge_document_node"("p_node_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  actor_user_id uuid := auth.uid();
  node_row public.document_nodes%rowtype;
  root_row public.document_nodes%rowtype;
  existing_batch public.document_storage_cleanup_batches%rowtype;
  cleanup_batch public.document_storage_cleanup_batches%rowtype;
  object_count bigint := 0;
  byte_count bigint := 0;
begin
  if actor_user_id is null then
    raise exception 'Authentication required.'
      using errcode = '42501';
  end if;

  select *
  into node_row
  from public.document_nodes node
  where node.id = p_node_id;

  if not found then
    select *
    into existing_batch
    from public.document_storage_cleanup_batches batch
    where batch.root_node_id = p_node_id;

    if not found then
      raise exception 'Deleted document not found.'
        using errcode = 'P0002';
    end if;

    perform public.assert_document_workspace_permission(
      existing_batch.workspace_id,
      'files.purge'
    );
    return existing_batch.id;
  end if;

  perform public.assert_document_workspace_permission(
    node_row.workspace_id,
    'files.purge'
  );
  perform pg_advisory_xact_lock(
    hashtextextended('document-workspace:' || node_row.workspace_id::text, 0)
  );

  select *
  into node_row
  from public.document_nodes node
  where node.id = p_node_id
  for update;

  if node_row.deleted_at is null or node_row.deletion_batch_id is null then
    raise exception 'Only deleted documents can be permanently purged.'
      using errcode = '23514';
  end if;

  select root.*
  into root_row
  from public.document_nodes root
  left join public.document_nodes parent
    on parent.id = root.parent_node_id
    and parent.workspace_id = root.workspace_id
  where root.workspace_id = node_row.workspace_id
    and root.deletion_batch_id = node_row.deletion_batch_id
    and parent.deletion_batch_id is distinct from root.deletion_batch_id
  order by root.id
  limit 1
  for update of root;

  select count(*), coalesce(sum(version.byte_size), 0)
  into object_count, byte_count
  from public.document_versions version
  join public.document_nodes member_node on member_node.id = version.node_id
  where member_node.workspace_id = root_row.workspace_id
    and member_node.deletion_batch_id = root_row.deletion_batch_id
    and version.upload_state <> 'purged';

  insert into public.document_storage_cleanup_batches (
    organization_id,
    workspace_id,
    deletion_batch_id,
    root_node_id,
    root_display_name,
    requested_by,
    object_count,
    byte_count,
    processing_status,
    completed_at
  )
  values (
    root_row.organization_id,
    root_row.workspace_id,
    root_row.deletion_batch_id,
    root_row.id,
    root_row.display_name,
    actor_user_id,
    object_count,
    byte_count,
    case when object_count = 0 then 'completed' else 'pending' end,
    case when object_count = 0 then now() else null end
  )
  on conflict (workspace_id, deletion_batch_id)
  do update set deletion_batch_id = excluded.deletion_batch_id
  returning * into cleanup_batch;

  insert into public.document_activity_events (
    organization_id,
    workspace_id,
    node_id,
    actor_user_id,
    event_type,
    metadata
  )
  values (
    root_row.organization_id,
    root_row.workspace_id,
    root_row.id,
    actor_user_id,
    'purge_requested',
    jsonb_build_object(
      'cleanupBatchId', cleanup_batch.id,
      'deletionBatchId', root_row.deletion_batch_id,
      'rootNodeId', root_row.id,
      'objectCount', object_count,
      'byteCount', byte_count
    )
  )
  on conflict do nothing;

  -- Reuse any active abandoned-upload job for the same immutable object so
  -- there is never more than one active delete identity per Storage key.
  update public.document_storage_cleanup_jobs job
  set
    cleanup_batch_id = cleanup_batch.id,
    byte_size = greatest(job.byte_size, version.byte_size)
  from public.document_versions version
  join public.document_nodes member_node on member_node.id = version.node_id
  where member_node.workspace_id = root_row.workspace_id
    and member_node.deletion_batch_id = root_row.deletion_batch_id
    and job.storage_bucket = 'organization-documents'
    and job.storage_key = version.storage_key
    and job.processing_status <> 'completed';

  insert into public.document_storage_cleanup_jobs (
    organization_id,
    workspace_id,
    version_id,
    cleanup_batch_id,
    job_type,
    job_identity,
    storage_bucket,
    storage_key,
    byte_size
  )
  select
    version.organization_id,
    version.workspace_id,
    version.id,
    cleanup_batch.id,
    'version_purge',
    'document-version:' || version.id::text || ':version-purge',
    'organization-documents',
    version.storage_key,
    coalesce(version.byte_size, 0)
  from public.document_versions version
  join public.document_nodes member_node on member_node.id = version.node_id
  where member_node.workspace_id = root_row.workspace_id
    and member_node.deletion_batch_id = root_row.deletion_batch_id
    and not exists (
      select 1
      from public.document_storage_cleanup_jobs existing
      where existing.storage_bucket = 'organization-documents'
        and existing.storage_key = version.storage_key
        and existing.processing_status <> 'completed'
    )
  on conflict (job_identity) do nothing;

  update public.document_nodes node
  set current_version_id = null
  where node.workspace_id = root_row.workspace_id
    and node.deletion_batch_id = root_row.deletion_batch_id
    and node.current_version_id is not null;

  -- Delete versions while their deleted node rows still exist so the usage
  -- trigger can classify retained bytes as deleted rather than active.
  delete from public.document_versions version
  using public.document_nodes member_node
  where version.node_id = member_node.id
    and member_node.workspace_id = root_row.workspace_id
    and member_node.deletion_batch_id = root_row.deletion_batch_id;

  delete from public.document_nodes node
  where node.workspace_id = root_row.workspace_id
    and node.deletion_batch_id = root_row.deletion_batch_id;

  if object_count = 0 then
    insert into public.document_activity_events (
      organization_id,
      workspace_id,
      actor_user_id,
      event_type,
      metadata
    )
    values (
      root_row.organization_id,
      root_row.workspace_id,
      actor_user_id,
      'purged',
      jsonb_build_object(
        'cleanupBatchId', cleanup_batch.id,
        'deletionBatchId', root_row.deletion_batch_id,
        'rootNodeId', root_row.id,
        'objectCount', 0
      )
    );
  end if;

  return cleanup_batch.id;
end;
$$;


ALTER FUNCTION "public"."purge_document_node"("p_node_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."qa_assert_definition"("p_sections" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
declare s jsonb; f jsonb; o jsonb; seen_sections uuid[] := '{}'; seen_fields uuid[] := '{}';
begin
  if p_sections is null or jsonb_typeof(p_sections) <> 'array' then raise exception 'QA sections must be an array' using errcode='TS422'; end if;
  for s in select value from jsonb_array_elements(p_sections) loop
    if nullif(btrim(s->>'title'),'') is null or (s->>'id')::uuid = any(seen_sections) then raise exception 'Invalid or duplicate QA section' using errcode='TS422'; end if;
    seen_sections := array_append(seen_sections,(s->>'id')::uuid);
    if jsonb_typeof(coalesce(s->'fields','[]'::jsonb)) <> 'array' then raise exception 'QA fields must be an array' using errcode='TS422'; end if;
    for f in select value from jsonb_array_elements(coalesce(s->'fields','[]'::jsonb)) loop
      if nullif(btrim(f->>'label'),'') is null or (f->>'id')::uuid = any(seen_fields) then raise exception 'Invalid or duplicate QA field' using errcode='TS422'; end if;
      if f->>'fieldType' not in ('short_text','long_text','number','measurement','date','yes_no','single_select','multi_select','checkbox','inspection_check','photo','file','person','location','product_material','signature') then raise exception 'Invalid QA field type' using errcode='TS422'; end if;
      if coalesce((f->>'minimumPhotos')::integer,0) < 0 or coalesce((f->>'minimumPhotos')::integer,0) > 50 then raise exception 'Invalid minimum photo count' using errcode='TS422'; end if;
      if (coalesce((f->>'photoRequired')::boolean,false) or coalesce((f->>'requirePhotoOnFail')::boolean,false))
        and coalesce((f->>'minimumPhotos')::integer,0) < 1 then raise exception 'Required photo evidence needs at least one photo' using errcode='TS422'; end if;
      if f ? 'configuration' and not public.qa_field_configuration_is_valid(f->>'fieldType',f->'configuration') then raise exception 'Invalid QA field configuration' using errcode='TS422'; end if;
      seen_fields := array_append(seen_fields,(f->>'id')::uuid);
      if f->>'fieldType' in ('single_select','multi_select') then
        if jsonb_array_length(coalesce(f->'options','[]'::jsonb)) = 0 then raise exception 'Select fields require an option' using errcode='TS422'; end if;
        for o in select value from jsonb_array_elements(coalesce(f->'options','[]'::jsonb)) loop
          if nullif(btrim(o->>'label'),'') is null or nullif(btrim(o->>'value'),'') is null then raise exception 'Invalid QA option' using errcode='TS422'; end if;
        end loop;
      end if;
    end loop;
  end loop;
end;
$$;


ALTER FUNCTION "public"."qa_assert_definition"("p_sections" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."qa_evidence_mime_allowed_v1"("p_type" "text", "p_mime" "text") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select case p_type
    when 'photo' then lower(p_mime) in ('image/jpeg','image/png','image/webp','image/heic','image/heif')
    when 'signature' then lower(p_mime)='image/png'
    when 'file' then lower(p_mime) in (
      'image/jpeg','image/png','image/webp','image/heic','image/heif','application/pdf','text/plain','text/csv',
      'application/msword','application/vnd.openxmlformats-officedocument.wordprocessingml.document',
      'application/vnd.ms-excel','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
      'application/vnd.ms-powerpoint','application/vnd.openxmlformats-officedocument.presentationml.presentation'
    ) else false end;
$$;


ALTER FUNCTION "public"."qa_evidence_mime_allowed_v1"("p_type" "text", "p_mime" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."qa_field_configuration_is_valid"("p_field_type" "text", "p_configuration" "jsonb") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select coalesce((case
    when jsonb_typeof(p_configuration) <> 'object' then false
    when p_field_type = 'inspection_check' then
      (not (p_configuration ? 'commentRule') or p_configuration->>'commentRule' in ('optional','required','required_on_fail'))
      and (not (p_configuration ? 'holdPointEnabled') or jsonb_typeof(p_configuration->'holdPointEnabled') = 'boolean')
    when p_field_type = 'product_material' then
      jsonb_typeof(p_configuration->'productMaterial') = 'object'
      and jsonb_typeof(p_configuration->'productMaterial'->'captureBatchLot') = 'boolean'
      and jsonb_typeof(p_configuration->'productMaterial'->'captureManufacturer') = 'boolean'
      and jsonb_typeof(p_configuration->'productMaterial'->'captureSupplier') = 'boolean'
      and jsonb_typeof(p_configuration->'productMaterial'->'captureProductCode') = 'boolean'
      and jsonb_typeof(p_configuration->'productMaterial'->'suggestMaterials') = 'boolean'
    when p_field_type = 'measurement' and p_configuration ? 'unit' then
      jsonb_typeof(p_configuration->'unit') = 'string'
      and char_length(btrim(p_configuration->>'unit')) between 1 and 32
    else true
  end), false);
$$;


ALTER FUNCTION "public"."qa_field_configuration_is_valid"("p_field_type" "text", "p_configuration" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."qa_product_material_value_is_valid"("p_value" "jsonb") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $_$
  select coalesce((jsonb_typeof(p_value) = 'object'
    and jsonb_typeof(p_value->'schemaVersion') = 'number' and p_value->>'schemaVersion' = '1'
    and jsonb_typeof(p_value->'source') = 'string' and p_value->>'source' in ('manual','material')
    and (jsonb_typeof(p_value->'organizationMaterialId') = 'null' or (jsonb_typeof(p_value->'organizationMaterialId') = 'string' and p_value->>'organizationMaterialId' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'))
    and (jsonb_typeof(p_value->'supplierProductId') = 'null' or (jsonb_typeof(p_value->'supplierProductId') = 'string' and p_value->>'supplierProductId' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'))
    and (jsonb_typeof(p_value->'supplierId') = 'null' or (jsonb_typeof(p_value->'supplierId') = 'string' and p_value->>'supplierId' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'))
    and jsonb_typeof(p_value->'productName') = 'string' and char_length(p_value->>'productName') <= 500
    and jsonb_typeof(p_value->'materialNameSnapshot') = 'string' and char_length(p_value->>'materialNameSnapshot') <= 1000
    and jsonb_typeof(p_value->'manufacturerName') = 'string' and char_length(p_value->>'manufacturerName') <= 500
    and jsonb_typeof(p_value->'supplierName') = 'string' and char_length(p_value->>'supplierName') <= 500
    and jsonb_typeof(p_value->'batchLot') = 'string' and char_length(p_value->>'batchLot') <= 500
    and jsonb_typeof(p_value->'productCode') = 'string' and char_length(p_value->>'productCode') <= 500), false);
$_$;


ALTER FUNCTION "public"."qa_product_material_value_is_valid"("p_value" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."qa_signature_metadata_is_valid_v1"("p_metadata" "jsonb") RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
begin
  return coalesce(
    jsonb_typeof(p_metadata)='object'
    and p_metadata->>'schemaVersion'='1'
    and p_metadata->>'rendererVersion'='1'
    and p_metadata->>'mimeType'='image/png'
    and (p_metadata->>'logicalWidth')::numeric between 100 and 2000
    and (p_metadata->>'logicalHeight')::numeric between 100 and 800
    and (p_metadata->>'pixelWidth')::integer between 100 and 4096
    and (p_metadata->>'pixelHeight')::integer between 100 and 2048
    and (p_metadata->>'devicePixelRatio')::numeric between 1 and 3
    and abs((p_metadata->>'pixelWidth')::integer-round((p_metadata->>'logicalWidth')::numeric*(p_metadata->>'devicePixelRatio')::numeric))<=1
    and abs((p_metadata->>'pixelHeight')::integer-round((p_metadata->>'logicalHeight')::numeric*(p_metadata->>'devicePixelRatio')::numeric))<=1
    and (p_metadata->>'strokeCount')::integer >= 1
    and (p_metadata->>'pointCount')::integer >= 3
    and (p_metadata->>'totalDistance')::numeric >= 20
    and jsonb_typeof(p_metadata->'bounds')='object'
    and (p_metadata->'bounds'->>'width')::numeric >= 12
    and (p_metadata->'bounds'->>'height')::numeric >= 8,
    false
  );
exception when others then
  return false;
end;
$$;


ALTER FUNCTION "public"."qa_signature_metadata_is_valid_v1"("p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."queue_expired_project_qa_evidence_uploads_v1"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare queued integer;
begin
  with expired as (
    update public.project_qa_evidence_uploads set status='abandoned',abandoned_at=now()
    where status='pending' and expires_at<=now()
    returning storage_path
  ), inserted as (
    insert into public.project_qa_evidence_cleanup_jobs(storage_path,reason)
    select storage_path,'expired' from expired on conflict(storage_path) do nothing returning 1
  ) select count(*) into queued from inserted;
  return queued;
end; $$;


ALTER FUNCTION "public"."queue_expired_project_qa_evidence_uploads_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."queue_retention_claim_attachment_retry_phase2c"("p_revision_id" "uuid", "p_actor_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
declare
  v_revision public.organization_accounting_document_revisions%rowtype;
  v_document public.organization_accounting_documents%rowtype;
  v_attachment public.organization_accounting_revision_attachments%rowtype;
  v_attempt public.organization_accounting_revision_attempts%rowtype;
  v_retry_sequence bigint;
  v_key text;
  v_job_id uuid;
begin
  if auth.role() <> 'service_role' then
    raise exception 'Retention Claim attachment retry is server-only.';
  end if;
  select * into v_revision
  from public.organization_accounting_document_revisions
  where id = p_revision_id
  for update;
  if not found
    or v_revision.source_document_type <> 'retention_claim'
    or v_revision.lifecycle_state <> 'succeeded'
    or v_revision.revision_intent not in ('initial_push', 'replacement') then
    raise exception 'The Retention Claim revision is not attachment-retry eligible.';
  end if;
  if not private.retention_phase2c_actor_can_push(
    v_revision.organization_id, p_actor_id
  ) then
    raise exception 'Retention Claim Push to Xero permission is required.';
  end if;
  if not exists (
    select 1
    from public.organization_accounting_phase2b_settings s
    where s.organization_id = v_revision.organization_id
      and s.retention_claim_immutable_xero_enabled
  ) then
    raise exception 'Immutable Retention Claim Push to Xero is not enabled.';
  end if;
  select * into v_document
  from public.organization_accounting_documents
  where id = v_revision.accounting_document_id
    and organization_id = v_revision.organization_id
    and active_accounting_revision_id = v_revision.id
    and integration_contract = 'retention_claim_revision_v1'
  for update;
  if not found
    or v_document.external_document_id <> v_revision.external_document_id then
    raise exception 'The Retention Claim revision is no longer active.';
  end if;
  select * into v_attachment
  from public.organization_accounting_revision_attachments
  where accounting_revision_id = v_revision.id
    and attachment_sequence = 1
  for update;
  if not found or v_attachment.upload_state <> 'failed' then
    raise exception 'The immutable Retention Claim PDF does not require retry.';
  end if;
  if exists (
    select 1
    from public.organization_accounting_sync_jobs j
    where j.organization_id = v_revision.organization_id
      and j.job_kind in (
        'xero.retention_claim.initial_push.attachment',
        'xero.retention_claim.replacement.attachment'
      )
      and j.queue_state in ('pending', 'claimed', 'retry_scheduled')
      and j.request_payload->>'accountingRevisionId' = v_revision.id::text
  ) then
    raise exception 'A Retention Claim PDF attachment job is already active.';
  end if;
  select count(*) + 1 into v_retry_sequence
  from public.organization_accounting_revision_attempts
  where accounting_revision_id = v_revision.id
    and attempt_intent = 'attach';
  v_key := encode(digest((
    'xero:retention_claim:attachment:retry:'
    || v_revision.id || ':' || v_retry_sequence
  )::bytea, 'sha256'), 'hex');
  select * into v_attempt
  from public.create_accounting_revision_attempt_phase2a(
    v_revision.id, 'attach', v_key,
    jsonb_build_object(
      'accountingDocumentId', v_document.id,
      'accountingRevisionId', v_revision.id,
      'attachmentId', v_attachment.id,
      'tenantId', v_revision.tenant_id,
      'retrySequence', v_retry_sequence
    )
  );
  insert into public.organization_accounting_sync_jobs(
    organization_id, provider, connection_id, job_kind, trigger_source,
    request_payload, result_summary, idempotency_key, max_attempts,
    created_by_user_id
  ) values (
    v_revision.organization_id, 'xero', v_revision.connection_id,
    case when v_revision.revision_intent = 'initial_push'
      then 'xero.retention_claim.initial_push.attachment'
      else 'xero.retention_claim.replacement.attachment' end,
    'user_retry',
    jsonb_build_object(
      'accountingDocumentId', v_document.id,
      'accountingRevisionId', v_revision.id,
      'attemptId', v_attempt.id,
      'tenantId', v_revision.tenant_id
    ),
    '{}'::jsonb, v_key, 5, p_actor_id
  )
  returning id into v_job_id;
  return jsonb_build_object(
    'accountingRevisionId', v_revision.id,
    'attemptId', v_attempt.id,
    'jobId', v_job_id
  );
end;
$$;


ALTER FUNCTION "public"."queue_retention_claim_attachment_retry_phase2c"("p_revision_id" "uuid", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."queue_retention_claim_payment_refresh"("p_accounting_document_id" "uuid", "p_actor_user_id" "uuid", "p_trigger_source" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  document_row public.organization_accounting_documents%rowtype;
  claim_row public.retention_claims%rowtype;
  active_job_id uuid;
  created_job boolean := false;
begin
  if auth.role() is distinct from 'service_role' then
    return jsonb_build_object(
      'succeeded', false, 'errorCode', 'permission_denied'
    );
  end if;
  if p_trigger_source not in ('manual_refresh', 'scheduled') then
    return jsonb_build_object(
      'succeeded', false, 'errorCode', 'invalid_trigger_source'
    );
  end if;

  select * into document_row
  from public.organization_accounting_documents
  where id = p_accounting_document_id
    and provider = 'xero'
    and local_document_type = 'retention_claim'
    and external_document_id is not null
    and export_status = 'exported'
  for update;
  if not found then
    return jsonb_build_object(
      'succeeded', false, 'errorCode', 'accounting_document_not_found'
    );
  end if;

  select * into claim_row
  from public.retention_claims
  where id = document_row.retention_claim_id
    and organization_id = document_row.organization_id
    and status = 'submitted';
  if not found then
    return jsonb_build_object(
      'succeeded', false, 'errorCode', 'claim_not_submitted'
    );
  end if;

  if p_trigger_source = 'manual_refresh' and (
    p_actor_user_id is null
    or not private.retention_phase8_actor_has_permission(
      document_row.organization_id,
      p_actor_user_id,
      'retention.claims.payments.manage'
    )
  ) then
    return jsonb_build_object(
      'succeeded', false, 'errorCode', 'permission_denied'
    );
  end if;

  if not exists (
    select 1 from public.organization_capabilities capability
    where capability.organization_id = document_row.organization_id
      and capability.capability_key = 'retention_management'
      and capability.enabled = true
  ) or not exists (
    select 1 from public.project_retention_workflow_states state
    where state.organization_id = document_row.organization_id
      and state.project_id = claim_row.project_id
      and state.mode = 'observe'
  ) then
    return jsonb_build_object(
      'succeeded', false, 'errorCode', 'project_mode_not_supported'
    );
  end if;

  if exists (
    select 1
    from public.organization_accounting_sync_jobs job
    where job.organization_id = document_row.organization_id
      and job.provider = 'xero'
      and job.job_kind in (
        'xero.retention_claim.sync',
        'xero.retention_claim.attachment'
      )
      and job.queue_state in ('pending', 'claimed', 'retry_scheduled')
      and job.request_payload->>'accountingDocumentId' =
        document_row.id::text
  ) then
    return jsonb_build_object(
      'succeeded', false, 'errorCode', 'outbound_operation_in_progress'
    );
  end if;

  select job.id into active_job_id
  from public.organization_accounting_sync_jobs job
  where job.organization_id = document_row.organization_id
    and job.provider = 'xero'
    and job.job_kind = 'xero.retention_claim.refresh'
    and job.queue_state in ('pending', 'claimed', 'retry_scheduled')
    and job.request_payload->>'accountingDocumentId' =
      document_row.id::text
  order by job.created_at desc
  limit 1;

  if active_job_id is null then
    insert into public.organization_accounting_sync_jobs(
      organization_id,
      provider,
      connection_id,
      job_kind,
      trigger_source,
      queue_state,
      request_payload,
      result_summary,
      idempotency_key,
      max_attempts,
      created_by_user_id
    )
    values(
      document_row.organization_id,
      'xero',
      document_row.accounting_connection_id,
      'xero.retention_claim.refresh',
      p_trigger_source,
      'pending',
      jsonb_build_object(
        'accountingDocumentId', document_row.id,
        'retentionClaimId', claim_row.id
      ),
      '{}'::jsonb,
      null,
      3,
      p_actor_user_id
    )
    returning id into active_job_id;
    created_job := true;
  end if;

  return jsonb_build_object(
    'succeeded', true,
    'errorCode', null,
    'createdJob', created_job,
    'jobId', active_job_id,
    'accountingDocumentId', document_row.id
  );
end;
$$;


ALTER FUNCTION "public"."queue_retention_claim_payment_refresh"("p_accounting_document_id" "uuid", "p_actor_user_id" "uuid", "p_trigger_source" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."queue_retention_claim_xero_attachment"("p_accounting_document_id" "uuid", "p_actor_user_id" "uuid", "p_correlation_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  document_row public.organization_accounting_documents%rowtype;
  snapshot_row public.retention_claim_accounting_snapshots%rowtype;
  active_job_id uuid;
  created_job boolean := false;
begin
  if auth.role() is distinct from 'service_role' then
    return jsonb_build_object(
      'succeeded', false, 'errorCode', 'permission_denied'
    );
  end if;

  select * into document_row
  from public.organization_accounting_documents
  where id = p_accounting_document_id
    and provider = 'xero'
    and local_document_type = 'retention_claim'
  for update;
  if not found then
    return jsonb_build_object(
      'succeeded', false, 'errorCode', 'accounting_document_not_found'
    );
  end if;

  if not private.retention_phase8_actor_has_permission(
    document_row.organization_id,
    p_actor_user_id,
    'retention.claims.xero.manage'
  ) then
    return jsonb_build_object(
      'succeeded', false, 'errorCode', 'permission_denied'
    );
  end if;

  if document_row.external_document_id is null
     or document_row.export_status <> 'exported' then
    return jsonb_build_object(
      'succeeded', false, 'errorCode', 'invoice_not_synchronized'
    );
  end if;

  select * into snapshot_row
  from public.retention_claim_accounting_snapshots
  where accounting_document_id = document_row.id;
  if not found then
    return jsonb_build_object(
      'succeeded', false, 'errorCode', 'accounting_snapshot_missing'
    );
  end if;

  if exists (
    select 1
    from public.organization_accounting_sync_jobs job
    where job.organization_id = document_row.organization_id
      and job.provider = 'xero'
      and job.job_kind = 'xero.retention_claim.sync'
      and job.queue_state in ('pending', 'claimed', 'retry_scheduled')
      and job.request_payload->>'accountingDocumentId' =
        document_row.id::text
  ) then
    return jsonb_build_object(
      'succeeded', false, 'errorCode', 'sync_in_progress'
    );
  end if;

  select job.id into active_job_id
  from public.organization_accounting_sync_jobs job
  where job.organization_id = document_row.organization_id
    and job.provider = 'xero'
    and job.job_kind = 'xero.retention_claim.attachment'
    and job.queue_state in ('pending', 'claimed', 'retry_scheduled')
    and job.request_payload->>'accountingDocumentId' =
      document_row.id::text
  order by job.created_at desc
  limit 1;

  if active_job_id is null then
    insert into public.organization_accounting_sync_jobs(
      organization_id,
      provider,
      connection_id,
      job_kind,
      trigger_source,
      queue_state,
      request_payload,
      result_summary,
      idempotency_key,
      max_attempts,
      created_by_user_id
    )
    values(
      document_row.organization_id,
      'xero',
      document_row.accounting_connection_id,
      'xero.retention_claim.attachment',
      case when document_row.attachment_status = 'failed'
        then 'user_retry' else 'user_export' end,
      'pending',
      jsonb_build_object(
        'accountingDocumentId', document_row.id,
        'accountingSnapshotId', snapshot_row.id,
        'pdfSha256', snapshot_row.retention_pdf_sha256
      ),
      '{}'::jsonb,
      null,
      3,
      p_actor_user_id
    )
    returning id into active_job_id;
    created_job := true;

    update public.organization_accounting_documents
    set
      attachment_status = 'queued',
      attachment_error_code = null,
      attachment_error_message = null
    where id = document_row.id;

    insert into public.retention_claim_accounting_events(
      organization_id,
      project_id,
      retention_claim_id,
      accounting_document_id,
      accounting_snapshot_id,
      event_type,
      actor_user_id,
      correlation_id,
      metadata
    )
    values(
      snapshot_row.organization_id,
      snapshot_row.project_id,
      snapshot_row.retention_claim_id,
      document_row.id,
      snapshot_row.id,
      'xero_attachment_queued',
      p_actor_user_id,
      p_correlation_id,
      jsonb_build_object(
        'jobId', active_job_id,
        'pdfSha256', snapshot_row.retention_pdf_sha256
      )
    );
  end if;

  return jsonb_build_object(
    'succeeded', true,
    'errorCode', null,
    'createdJob', created_job,
    'jobId', active_job_id,
    'accountingDocumentId', document_row.id
  );
end;
$$;


ALTER FUNCTION "public"."queue_retention_claim_xero_attachment"("p_accounting_document_id" "uuid", "p_actor_user_id" "uuid", "p_correlation_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."recalculate_project_claim_snapshots"("p_organization_id" "uuid", "p_project_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  claim_row public.project_claims%rowtype;
  resolved_quote_value numeric := 0;
  resolved_approved_variations numeric := 0;
  resolved_revised_contract_value numeric := 0;
  resolved_claim_amount numeric := 0;
  resolved_previous_claims_total numeric := 0;
  resolved_percent_complete numeric := 0;
  resolved_retention_percent numeric := 0;
  resolved_retention_method text := 'flat';
  resolved_retention_scale_bands jsonb := '[]'::jsonb;
  certified_value_to_date numeric := 0;
  required_retention_to_date numeric := 0;
  prior_retention_balance numeric := 0;
  resolved_retention_withheld_amount numeric := 0;
  resolved_retention_released_amount numeric := 0;
  resolved_retention_held_to_date numeric := 0;
  resolved_retention_released_to_date numeric := 0;
  resolved_retention_balance numeric := 0;
  resolved_net_claim_excl_gst numeric := 0;
  resolved_gst_amount numeric := 0;
  resolved_total_payable numeric := 0;
  running_previous_claims_total numeric := 0;
  running_retention_held_total numeric := 0;
  running_retention_released_total numeric := 0;
  current_claim_counts boolean := true;
  claim_gst_rate numeric := 0.15;
  tier_row jsonb;
  tier_lower_bound numeric := 0;
  tier_upper_bound numeric := 0;
  tier_rate_percent numeric := 0;
  tier_covered_amount numeric := 0;
  cost_item_revision_key text;
begin
  if auth.uid() is null then
    if current_user <> 'postgres' then
      raise exception 'Authentication is required';
    end if;
  elsif not public.is_member_of_organization(p_organization_id) then
    raise exception 'Not authorized for this organization';
  end if;

  if not exists (
    select 1
    from public.organization_projects p
    where p.id = p_project_id
      and p.organization_id = p_organization_id
  ) then
    raise exception 'Project not found for organization';
  end if;

  resolved_quote_value := public.get_project_claim_base_quote_total(
    p_organization_id,
    p_project_id
  );

  resolved_approved_variations := public.get_project_claim_approved_variations_total(
    p_organization_id,
    p_project_id
  );

  resolved_revised_contract_value := resolved_quote_value + resolved_approved_variations;

  for claim_row in
    select c.*
    from public.project_claims c
    where c.organization_id = p_organization_id
      and c.project_id = p_project_id
    order by
      c.claim_date asc nulls last,
      c.created_at asc,
      c.id asc
  loop
    resolved_claim_amount := public.sync_project_claim_line_items(
      p_organization_id,
      p_project_id,
      claim_row.id,
      null,
      null
    );

    resolved_previous_claims_total := running_previous_claims_total;
    resolved_percent_complete := case
      when resolved_revised_contract_value <= 0 then 0
      else least(
        100,
        greatest(
          0,
          ((resolved_previous_claims_total + resolved_claim_amount) / resolved_revised_contract_value) * 100
        )
      )
    end;

    current_claim_counts := claim_row.status <> 'Cancelled';
    resolved_retention_percent := greatest(0, least(100, coalesce(claim_row.retention_percent, 0)));
    resolved_retention_method := case
      when coalesce(claim_row.retention_method, 'flat') = 'sliding_scale' then 'sliding_scale'
      else 'flat'
    end;
    resolved_retention_scale_bands := coalesce(claim_row.retention_scale_bands, '[]'::jsonb);
    resolved_retention_released_amount := greatest(0, coalesce(claim_row.retention_released_amount, 0));
    certified_value_to_date := resolved_previous_claims_total + resolved_claim_amount;

    if resolved_retention_method = 'flat' then
      required_retention_to_date := certified_value_to_date * (resolved_retention_percent / 100);
    else
      required_retention_to_date := 0;
      tier_lower_bound := 0;

      for tier_row in
        select value
        from jsonb_array_elements(resolved_retention_scale_bands)
      loop
        tier_upper_bound := case
          when jsonb_typeof(tier_row -> 'up_to') = 'number' then greatest(0, (tier_row ->> 'up_to')::numeric)
          else null
        end;
        tier_rate_percent := case
          when jsonb_typeof(tier_row -> 'rate_percent') = 'number' then greatest(0, least(100, (tier_row ->> 'rate_percent')::numeric))
          else 0
        end;

        tier_covered_amount := case
          when tier_upper_bound is null then greatest(0, certified_value_to_date - tier_lower_bound)
          else greatest(0, least(certified_value_to_date, tier_upper_bound) - tier_lower_bound)
        end;

        required_retention_to_date := required_retention_to_date + (tier_covered_amount * (tier_rate_percent / 100));

        if tier_upper_bound is null then
          exit;
        end if;

        tier_lower_bound := greatest(tier_lower_bound, tier_upper_bound);
      end loop;
    end if;

    prior_retention_balance := running_retention_held_total - running_retention_released_total;
    resolved_retention_withheld_amount := round(
      greatest(0, required_retention_to_date - prior_retention_balance),
      2
    );
    resolved_net_claim_excl_gst := round(
      resolved_claim_amount
      - resolved_retention_withheld_amount
      + resolved_retention_released_amount,
      2
    );
    resolved_gst_amount := round(resolved_net_claim_excl_gst * claim_gst_rate, 2);
    resolved_total_payable := round(resolved_net_claim_excl_gst + resolved_gst_amount, 2);
    resolved_retention_held_to_date := round(
      running_retention_held_total
      + case when current_claim_counts then resolved_retention_withheld_amount else 0 end,
      2
    );
    resolved_retention_released_to_date := round(
      running_retention_released_total
      + case when current_claim_counts then resolved_retention_released_amount else 0 end,
      2
    );
    resolved_retention_balance := round(
      resolved_retention_held_to_date - resolved_retention_released_to_date,
      2
    );

    update public.project_claims c
    set
      claim_amount = round(resolved_claim_amount, 2),
      linked_quote_value = round(resolved_quote_value, 2),
      linked_approved_variations = round(resolved_approved_variations, 2),
      previous_claims_total = round(resolved_previous_claims_total, 2),
      revised_contract_value = round(resolved_revised_contract_value, 2),
      percent_complete = round(resolved_percent_complete, 3),
      retention_percent = round(resolved_retention_percent, 3),
      retention_withheld_amount = round(resolved_retention_withheld_amount, 2),
      retention_released_amount = round(resolved_retention_released_amount, 2),
      retention_held_to_date = round(resolved_retention_held_to_date, 2),
      retention_released_to_date = round(resolved_retention_released_to_date, 2),
      retention_balance = round(resolved_retention_balance, 2),
      net_claim_excl_gst = round(resolved_net_claim_excl_gst, 2),
      gst_amount = round(resolved_gst_amount, 2),
      total_payable = round(resolved_total_payable, 2)
    where c.id = claim_row.id
      and c.organization_id = p_organization_id
      and c.project_id = p_project_id;

    cost_item_revision_key := public.begin_cost_item_revision('project_claim', claim_row.id);
    perform public.supersede_previous_cost_items('project_claim', claim_row.id, cost_item_revision_key);
    perform public.upsert_cost_items_for_project_claim(claim_row.id, cost_item_revision_key);

    if current_claim_counts then
      running_previous_claims_total := running_previous_claims_total + resolved_claim_amount;
      running_retention_held_total := running_retention_held_total + resolved_retention_withheld_amount;
      running_retention_released_total := running_retention_released_total + resolved_retention_released_amount;
    end if;
  end loop;
end;
$$;


ALTER FUNCTION "public"."recalculate_project_claim_snapshots"("p_organization_id" "uuid", "p_project_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."recalculate_project_purchase_order_totals"("p_purchase_order_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  purchase_order_row public.project_purchase_orders%rowtype;
  computed_subtotal numeric := 0;
  computed_labour_total numeric := 0;
  computed_materials_total numeric := 0;
  computed_subcontractors_total numeric := 0;
  computed_plant_total numeric := 0;
  computed_margin_lines_total numeric := 0;
  computed_margin numeric := 0;
  computed_discount numeric := 0;
  computed_contingency numeric := 0;
  pre_gst_total numeric := 0;
  computed_gst_total numeric := 0;
  computed_grand_total numeric := 0;
begin
  select *
  into purchase_order_row
  from public.project_purchase_orders
  where id = p_purchase_order_id
  for update;

  if not found then
    return;
  end if;

  select
    coalesce(sum(li.total), 0),
    coalesce(sum(li.total) filter (where li.section = 'Labour'), 0),
    coalesce(sum(li.total) filter (where li.section = 'Materials'), 0),
    coalesce(sum(li.total) filter (where li.section = 'Subcontractors'), 0),
    coalesce(sum(li.total) filter (where li.section = 'Plant'), 0),
    coalesce(sum(li.total) filter (where li.section = 'Margin'), 0)
  into
    computed_subtotal,
    computed_labour_total,
    computed_materials_total,
    computed_subcontractors_total,
    computed_plant_total,
    computed_margin_lines_total
  from public.project_purchase_order_line_items li
  where li.purchase_order_id = p_purchase_order_id;

  computed_margin := computed_subtotal * (coalesce(purchase_order_row.margin_percent, 0) / 100);
  computed_discount := coalesce(purchase_order_row.discount_amount, 0);
  computed_contingency := coalesce(purchase_order_row.contingency_amount, 0);
  pre_gst_total := greatest(0, computed_subtotal + computed_margin + computed_contingency - computed_discount);
  computed_gst_total := pre_gst_total * (coalesce(purchase_order_row.gst_percent, 0) / 100);
  computed_grand_total := pre_gst_total + computed_gst_total;

  update public.project_purchase_orders
  set
    labour_total = round(computed_labour_total, 2),
    materials_total = round(computed_materials_total, 2),
    subcontractors_total = round(computed_subcontractors_total, 2),
    plant_total = round(computed_plant_total, 2),
    margin_total = round(computed_margin_lines_total, 2),
    subtotal = round(computed_subtotal, 2),
    gst_total = round(computed_gst_total, 2),
    total_purchase_order_price = round(computed_grand_total, 2)
  where id = p_purchase_order_id;
end;
$$;


ALTER FUNCTION "public"."recalculate_project_purchase_order_totals"("p_purchase_order_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reconcile_cost_items_after_accounting_mapping_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if tg_op in ('UPDATE', 'DELETE') then
    perform public.reconcile_current_cost_item_accounting_mappings(
      old.organization_id,
      old.tradesstack_cost_code
    );
  end if;

  if tg_op in ('INSERT', 'UPDATE')
    and (
      tg_op = 'INSERT'
      or new.organization_id is distinct from old.organization_id
      or new.tradesstack_cost_code is distinct from old.tradesstack_cost_code
      or new.provider is distinct from old.provider
      or new.project_id is distinct from old.project_id
      or new.organization_cost_code_id is distinct from old.organization_cost_code_id
      or new.is_active is distinct from old.is_active
    ) then
    perform public.reconcile_current_cost_item_accounting_mappings(
      new.organization_id,
      new.tradesstack_cost_code
    );
  end if;

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."reconcile_cost_items_after_accounting_mapping_change"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reconcile_current_cost_item_accounting_mappings"("p_organization_id" "uuid", "p_tradesstack_cost_code" integer DEFAULT NULL::integer) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  rows_reconciled integer := 0;
begin
  if p_organization_id is null then
    raise exception 'Organization is required for Cost Item accounting reconciliation.';
  end if;

  with resolved as (
    select
      cost_item.id,
      public.resolve_default_tradesstack_accounting_mapping(
        cost_item.organization_id,
        cost_item.tradesstack_cost_code,
        cost_item.project_id
      ) as accounting_mapping_id
    from public.cost_items cost_item
    where cost_item.organization_id = p_organization_id
      and cost_item.is_current
      and cost_item.status not in ('deleted', 'superseded')
      and cost_item.tradesstack_cost_code is not null
      and (
        p_tradesstack_cost_code is null
        or cost_item.tradesstack_cost_code = p_tradesstack_cost_code
      )
  )
  update public.cost_items cost_item
  set
    accounting_mapping_id = resolved.accounting_mapping_id,
    review_status = case
      when cost_item.review_status in ('needs_routing_review', 'high_value_review')
        then cost_item.review_status
      when resolved.accounting_mapping_id is null
        then 'needs_accounting_mapping'
      when cost_item.review_status = 'needs_accounting_mapping'
        then 'auto_approved'
      else coalesce(cost_item.review_status, 'auto_approved')
    end,
    review_reason = case
      when cost_item.review_status in ('needs_routing_review', 'high_value_review')
        then cost_item.review_reason
      when resolved.accounting_mapping_id is null
        then 'Missing accounting mapping for TradesStack routing code.'
      when cost_item.review_status = 'needs_accounting_mapping'
        then null
      else cost_item.review_reason
    end
  from resolved
  where cost_item.id = resolved.id
    and (
      cost_item.accounting_mapping_id is distinct from resolved.accounting_mapping_id
      or cost_item.review_status is distinct from case
        when cost_item.review_status in ('needs_routing_review', 'high_value_review')
          then cost_item.review_status
        when resolved.accounting_mapping_id is null
          then 'needs_accounting_mapping'
        when cost_item.review_status = 'needs_accounting_mapping'
          then 'auto_approved'
        else coalesce(cost_item.review_status, 'auto_approved')
      end
      or cost_item.review_reason is distinct from case
        when cost_item.review_status in ('needs_routing_review', 'high_value_review')
          then cost_item.review_reason
        when resolved.accounting_mapping_id is null
          then 'Missing accounting mapping for TradesStack routing code.'
        when cost_item.review_status = 'needs_accounting_mapping'
          then null
        else cost_item.review_reason
      end
    );

  get diagnostics rows_reconciled = row_count;
  return rows_reconciled;
end;
$$;


ALTER FUNCTION "public"."reconcile_current_cost_item_accounting_mappings"("p_organization_id" "uuid", "p_tradesstack_cost_code" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reconcile_document_storage_catalog"("p_limit" integer DEFAULT 500) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'storage', 'extensions'
    AS $_$
declare
  record_row record;
  missing_count integer := 0;
  mismatch_count integer := 0;
  orphan_count integer := 0;
  finding_key text;
  parsed_organization_id uuid;
  parsed_workspace_id uuid;
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'Service role required.'
      using errcode = '42501';
  end if;
  if p_limit < 1 or p_limit > 5000 then
    raise exception 'Reconciliation limit must be between 1 and 5000.';
  end if;

  for record_row in
    select
      version.organization_id,
      version.workspace_id,
      version.id as version_id,
      version.storage_key,
      version.byte_size,
      object.id as object_id,
      nullif(object.metadata ->> 'size', '')::bigint as actual_size
    from public.document_versions version
    left join storage.objects object
      on object.bucket_id = 'organization-documents'
      and object.name = version.storage_key
    where version.upload_state in ('active', 'purge_pending')
      and object.id is null
    order by exists (
      select 1
      from public.document_storage_reconciliation_findings finding
      where finding.version_id = version.id
        and finding.discrepancy_type = 'database_without_object'
        and finding.finding_status = 'open'
    ), version.created_at, version.id
    limit p_limit
  loop
    finding_key := md5('database_without_object:' || record_row.version_id::text);
    insert into public.document_storage_reconciliation_findings (
      organization_id,
      workspace_id,
      finding_fingerprint,
      discrepancy_type,
      storage_bucket,
      storage_key,
      version_id,
      expected_byte_size,
      details
    )
    values (
      record_row.organization_id,
      record_row.workspace_id,
      finding_key,
      'database_without_object',
      'organization-documents',
      record_row.storage_key,
      record_row.version_id,
      record_row.byte_size,
      jsonb_build_object('action', 'manual_review_required')
    )
    on conflict (finding_fingerprint) do update
    set
      finding_status = 'open',
      occurrence_count =
        public.document_storage_reconciliation_findings.occurrence_count + 1,
      last_detected_at = now(),
      resolved_at = null;
    missing_count := missing_count + 1;
  end loop;

  for record_row in
    select
      version.organization_id,
      version.workspace_id,
      version.id as version_id,
      version.storage_key,
      version.byte_size,
      object.bucket_id,
      object.name,
      nullif(object.metadata ->> 'size', '')::bigint as actual_size
    from public.document_versions version
    join storage.objects object on object.id = version.storage_object_id
    where version.upload_state in ('active', 'purge_pending')
      and (
        object.bucket_id <> 'organization-documents'
        or object.name <> version.storage_key
        or nullif(object.metadata ->> 'size', '')::bigint
          is distinct from version.byte_size
      )
    order by exists (
      select 1
      from public.document_storage_reconciliation_findings finding
      where finding.version_id = version.id
        and finding.discrepancy_type in (
          'wrong_bucket', 'wrong_key', 'wrong_size'
        )
        and finding.finding_status = 'open'
    ), version.created_at, version.id
    limit p_limit
  loop
    if record_row.bucket_id <> 'organization-documents' then
      finding_key := md5('wrong_bucket:' || record_row.version_id::text);
      insert into public.document_storage_reconciliation_findings (
        organization_id, workspace_id, finding_fingerprint,
        discrepancy_type, storage_bucket, storage_key, version_id,
        expected_byte_size, actual_byte_size, details
      ) values (
        record_row.organization_id, record_row.workspace_id, finding_key,
        'wrong_bucket', record_row.bucket_id, record_row.name,
        record_row.version_id, record_row.byte_size, record_row.actual_size,
        jsonb_build_object('action', 'manual_review_required')
      )
      on conflict (finding_fingerprint) do update
      set
        finding_status = 'open',
        occurrence_count =
          public.document_storage_reconciliation_findings.occurrence_count + 1,
        last_detected_at = now(),
        resolved_at = null;
    end if;

    if record_row.name <> record_row.storage_key then
      finding_key := md5('wrong_key:' || record_row.version_id::text);
      insert into public.document_storage_reconciliation_findings (
        organization_id, workspace_id, finding_fingerprint,
        discrepancy_type, storage_bucket, storage_key, version_id,
        expected_byte_size, actual_byte_size, details
      ) values (
        record_row.organization_id, record_row.workspace_id, finding_key,
        'wrong_key', record_row.bucket_id, record_row.name,
        record_row.version_id, record_row.byte_size, record_row.actual_size,
        jsonb_build_object('expectedKey', record_row.storage_key)
      )
      on conflict (finding_fingerprint) do update
      set
        finding_status = 'open',
        occurrence_count =
          public.document_storage_reconciliation_findings.occurrence_count + 1,
        last_detected_at = now(),
        resolved_at = null;
    end if;

    if record_row.actual_size is distinct from record_row.byte_size then
      finding_key := md5('wrong_size:' || record_row.version_id::text);
      insert into public.document_storage_reconciliation_findings (
        organization_id, workspace_id, finding_fingerprint,
        discrepancy_type, storage_bucket, storage_key, version_id,
        expected_byte_size, actual_byte_size, details
      ) values (
        record_row.organization_id, record_row.workspace_id, finding_key,
        'wrong_size', record_row.bucket_id, record_row.name,
        record_row.version_id, record_row.byte_size, record_row.actual_size,
        jsonb_build_object('action', 'manual_review_required')
      )
      on conflict (finding_fingerprint) do update
      set
        finding_status = 'open',
        occurrence_count =
          public.document_storage_reconciliation_findings.occurrence_count + 1,
        last_detected_at = now(),
        resolved_at = null;
    end if;
    mismatch_count := mismatch_count + 1;
  end loop;

  for record_row in
    select
      version.organization_id,
      version.workspace_id,
      version.id as version_id,
      version.storage_key,
      version.byte_size,
      version.upload_state,
      object.id as object_id,
      nullif(object.metadata ->> 'size', '')::bigint as actual_size
    from public.document_versions version
    join storage.objects object
      on object.bucket_id = 'organization-documents'
      and object.name = version.storage_key
    where version.upload_state in ('failed', 'abandoned', 'purged')
    order by exists (
      select 1
      from public.document_storage_reconciliation_findings finding
      where finding.version_id = version.id
        and finding.discrepancy_type = 'wrong_state'
        and finding.finding_status = 'open'
    ), version.created_at, version.id
    limit p_limit
  loop
    finding_key := md5('wrong_state:' || record_row.version_id::text);
    insert into public.document_storage_reconciliation_findings (
      organization_id, workspace_id, finding_fingerprint,
      discrepancy_type, storage_bucket, storage_key, version_id,
      expected_byte_size, actual_byte_size, details
    ) values (
      record_row.organization_id, record_row.workspace_id, finding_key,
      'wrong_state', 'organization-documents', record_row.storage_key,
      record_row.version_id, record_row.byte_size, record_row.actual_size,
      jsonb_build_object(
        'uploadState',
        record_row.upload_state,
        'action',
        'expected_object_cleanup'
      )
    )
    on conflict (finding_fingerprint) do update
    set
      finding_status = 'open',
      occurrence_count =
        public.document_storage_reconciliation_findings.occurrence_count + 1,
      last_detected_at = now(),
      resolved_at = null;

    insert into public.document_storage_cleanup_jobs (
      organization_id,
      workspace_id,
      version_id,
      job_type,
      job_identity,
      storage_bucket,
      storage_key,
      byte_size
    )
    values (
      record_row.organization_id,
      record_row.workspace_id,
      record_row.version_id,
      'abandoned_upload',
      'document-version:' || record_row.version_id::text
        || ':state-reconciliation:' || record_row.object_id::text,
      'organization-documents',
      record_row.storage_key,
      coalesce(record_row.actual_size, record_row.byte_size, 0)
    )
    on conflict do nothing;
    mismatch_count := mismatch_count + 1;
  end loop;

  for record_row in
    select
      object.id as object_id,
      object.bucket_id,
      object.name,
      nullif(object.metadata ->> 'size', '')::bigint as actual_size
    from storage.objects object
    where object.bucket_id = 'organization-documents'
      and not exists (
        select 1
        from public.document_versions version
        where version.storage_key = object.name
      )
    order by exists (
      select 1
      from public.document_storage_reconciliation_findings finding
      where finding.finding_fingerprint =
        md5('object_without_record:' || object.id::text)
        and finding.finding_status = 'open'
    ), object.created_at, object.id
    limit p_limit
  loop
    parsed_organization_id := null;
    parsed_workspace_id := null;
    if record_row.name ~
      '^[0-9a-f-]{36}/[0-9a-f-]{36}/[0-9a-f-]{36}$'
    then
      begin
        parsed_organization_id := split_part(record_row.name, '/', 1)::uuid;
        parsed_workspace_id := split_part(record_row.name, '/', 2)::uuid;
      exception when invalid_text_representation then
        parsed_organization_id := null;
        parsed_workspace_id := null;
      end;
    end if;

    if not exists (
      select 1
      from public.document_workspaces workspace
      where workspace.id = parsed_workspace_id
        and workspace.organization_id = parsed_organization_id
    ) then
      parsed_organization_id := null;
      parsed_workspace_id := null;
    end if;

    finding_key := md5('object_without_record:' || record_row.object_id::text);
    insert into public.document_storage_reconciliation_findings (
      organization_id,
      workspace_id,
      finding_fingerprint,
      discrepancy_type,
      storage_bucket,
      storage_key,
      actual_byte_size,
      details
    )
    values (
      parsed_organization_id,
      parsed_workspace_id,
      finding_key,
      'object_without_record',
      record_row.bucket_id,
      record_row.name,
      record_row.actual_size,
      jsonb_build_object(
        'action',
        'manual_review_required',
        'destructiveRepairAllowed',
        false
      )
    )
    on conflict (finding_fingerprint) do update
    set
      finding_status = 'open',
      occurrence_count =
        public.document_storage_reconciliation_findings.occurrence_count + 1,
      last_detected_at = now(),
      resolved_at = null;

    if parsed_workspace_id is not null then
      insert into public.document_storage_cleanup_jobs (
        organization_id,
        workspace_id,
        job_type,
        job_identity,
        storage_bucket,
        storage_key,
        byte_size
      )
      values (
        parsed_organization_id,
        parsed_workspace_id,
        'orphan_reconciliation',
        'document-orphan-review:' || record_row.object_id::text,
        record_row.bucket_id,
        record_row.name,
        coalesce(record_row.actual_size, 0)
      )
      on conflict do nothing;
    end if;
    orphan_count := orphan_count + 1;
  end loop;

  return jsonb_build_object(
    'databaseWithoutObjectCount', missing_count,
    'metadataMismatchCount', mismatch_count,
    'orphanObjectCount', orphan_count
  );
end;
$_$;


ALTER FUNCTION "public"."reconcile_document_storage_catalog"("p_limit" integer) OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."organization_document_storage_usage" (
    "organization_id" "uuid" NOT NULL,
    "quota_bytes" bigint DEFAULT '107374182400'::bigint NOT NULL,
    "active_bytes" bigint DEFAULT 0 NOT NULL,
    "deleted_bytes" bigint DEFAULT 0 NOT NULL,
    "pending_bytes" bigint DEFAULT 0 NOT NULL,
    "file_count" bigint DEFAULT 0 NOT NULL,
    "folder_count" bigint DEFAULT 0 NOT NULL,
    "current_version_count" bigint DEFAULT 0 NOT NULL,
    "historical_version_count" bigint DEFAULT 0 NOT NULL,
    "version_count" bigint DEFAULT 0 NOT NULL,
    "reconciled_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "organization_document_storage_usage_counters_check" CHECK ((("active_bytes" >= 0) AND ("deleted_bytes" >= 0) AND ("pending_bytes" >= 0) AND ("file_count" >= 0) AND ("folder_count" >= 0) AND ("current_version_count" >= 0) AND ("historical_version_count" >= 0) AND ("version_count" >= 0) AND ("historical_version_count" = ("version_count" - "current_version_count")))),
    CONSTRAINT "organization_document_storage_usage_quota_check" CHECK (("quota_bytes" >= 0))
);

ALTER TABLE ONLY "public"."organization_document_storage_usage" FORCE ROW LEVEL SECURITY;


ALTER TABLE "public"."organization_document_storage_usage" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reconcile_document_storage_usage"("p_organization_id" "uuid") RETURNS "public"."organization_document_storage_usage"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  usage_row public.organization_document_storage_usage%rowtype;
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'Service role required.'
      using errcode = '42501';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended(
      'document-storage-quota:' || p_organization_id::text,
      0
    )
  );
  perform public.ensure_document_storage_usage_row(p_organization_id);

  update public.organization_document_storage_usage usage
  set
    active_bytes = (
      select coalesce(sum(version.byte_size), 0)
      from public.document_versions version
      join public.document_nodes node on node.id = version.node_id
      where version.organization_id = p_organization_id
        and version.upload_state in ('active', 'purge_pending')
        and node.deleted_at is null
    ),
    deleted_bytes = (
      select coalesce(sum(version.byte_size), 0)
      from public.document_versions version
      join public.document_nodes node on node.id = version.node_id
      where version.organization_id = p_organization_id
        and version.upload_state in ('active', 'purge_pending')
        and node.deleted_at is not null
    ) + (
      select coalesce(sum(job.byte_size), 0)
      from public.document_storage_cleanup_jobs job
      where job.organization_id = p_organization_id
        and job.job_type = 'version_purge'
        and job.processing_status <> 'completed'
    ),
    pending_bytes = (
      select coalesce(sum(version.byte_size), 0)
      from public.document_versions version
      where version.organization_id = p_organization_id
        and version.upload_state in ('pending', 'uploaded')
    ),
    file_count = (
      select count(*)
      from public.document_nodes node
      where node.organization_id = p_organization_id
        and node.kind = 'file'
        and node.lifecycle_state = 'active'
        and node.deleted_at is null
    ),
    folder_count = (
      select count(*)
      from public.document_nodes node
      where node.organization_id = p_organization_id
        and node.kind = 'folder'
        and node.lifecycle_state = 'active'
        and node.deleted_at is null
    ),
    current_version_count = (
      select count(*)
      from public.document_nodes node
      where node.organization_id = p_organization_id
        and node.kind = 'file'
        and node.lifecycle_state = 'active'
        and node.deleted_at is null
        and node.current_version_id is not null
    ),
    version_count = (
      select count(*)
      from public.document_versions version
      where version.organization_id = p_organization_id
    ),
    historical_version_count = greatest(
      0,
      (
        select count(*)
        from public.document_versions version
        where version.organization_id = p_organization_id
      ) - (
        select count(*)
        from public.document_nodes node
        where node.organization_id = p_organization_id
          and node.kind = 'file'
          and node.lifecycle_state = 'active'
          and node.deleted_at is null
          and node.current_version_id is not null
      )
    ),
    reconciled_at = now()
  where usage.organization_id = p_organization_id
  returning * into usage_row;

  return usage_row;
end;
$$;


ALTER FUNCTION "public"."reconcile_document_storage_usage"("p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reconcile_project_pricing_workbooks_v1"("p_dry_run" boolean DEFAULT true, "p_organization_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("organization_id" "uuid", "opportunity_id" "uuid", "project_id" "uuid", "source_workbook_count" integer, "existing_continuation_count" integer, "missing_continuation_count" integer, "applied" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  mapping public.opportunity_final_projects%rowtype;
  source_total integer;
  existing_total integer;
  caller_is_service boolean := coalesce(auth.role(), '') = 'service_role';
  original_claims text := current_setting('request.jwt.claims', true);
begin
  if auth.uid() is null and not caller_is_service then
    raise exception 'Authentication is required' using errcode = '42501';
  end if;

  for mapping in
    select final_mapping.* from public.opportunity_final_projects final_mapping
    where (p_organization_id is null or final_mapping.organization_id = p_organization_id)
      and (
        caller_is_service
        or (
          public.is_member_of_organization(final_mapping.organization_id)
          and public.has_org_permission(final_mapping.organization_id, 'leads.opportunities.write')
          and public.has_org_permission(final_mapping.organization_id, 'quotes.write')
        )
      )
    order by final_mapping.created_at, final_mapping.opportunity_id
  loop
    select count(*)::integer into source_total
    from public.opportunity_pricing_worksheets source
    where source.organization_id = mapping.organization_id
      and source.opportunity_id = mapping.opportunity_id
      and source.project_id is null and source.quote_id is null and source.variation_id is null
      and source.clone_kind is null and source.archived_at is null;

    select count(*)::integer into existing_total
    from public.opportunity_pricing_worksheets source
    where source.organization_id = mapping.organization_id
      and source.opportunity_id = mapping.opportunity_id
      and source.project_id is null and source.quote_id is null and source.variation_id is null
      and source.clone_kind is null and source.archived_at is null
      and exists (
        select 1 from public.opportunity_pricing_worksheets continuation
        where continuation.organization_id = mapping.organization_id
          and continuation.project_id = mapping.project_id
          and continuation.source_workbook_id = source.id
          and continuation.clone_kind in ('project_working', 'project_workspace')
          and continuation.archived_at is null
      );

    if not p_dry_run and source_total > existing_total then
      if caller_is_service then
        perform set_config(
          'request.jwt.claims',
          jsonb_build_object('sub', mapping.created_by::text, 'role', 'authenticated')::text,
          true
        );
      end if;

      if mapping.accepted_quote_id is null then
        perform * from public.ensure_legacy_project_pricing_workbooks_v1(
          mapping.organization_id, mapping.opportunity_id, mapping.project_id, mapping.created_by
        );
      else
        perform * from public.finalize_opportunity_award_pricing_v1(
          mapping.organization_id, mapping.opportunity_id,
          mapping.project_id, mapping.accepted_quote_id
        );
      end if;

      if caller_is_service then
        perform set_config('request.jwt.claims', coalesce(original_claims, '{}'), true);
      end if;
    end if;

    organization_id := mapping.organization_id;
    opportunity_id := mapping.opportunity_id;
    project_id := mapping.project_id;
    source_workbook_count := source_total;
    existing_continuation_count := existing_total;
    missing_continuation_count := greatest(source_total - existing_total, 0);
    applied := not p_dry_run and source_total > existing_total;
    return next;
  end loop;

  if caller_is_service then
    perform set_config('request.jwt.claims', coalesce(original_claims, '{}'), true);
  end if;
exception when others then
  if caller_is_service then
    perform set_config('request.jwt.claims', coalesce(original_claims, '{}'), true);
  end if;
  raise;
end;
$$;


ALTER FUNCTION "public"."reconcile_project_pricing_workbooks_v1"("p_dry_run" boolean, "p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reconcile_worksheet_material_price_bindings"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_cells jsonb := coalesce(new.worksheet_data->'cells', '{}'::jsonb);
  v_cell record;
  v_metadata jsonb;
  v_version integer;
  v_binding_id uuid;
  v_material_id uuid;
  v_supplier_id uuid;
  v_product_id uuid;
  v_price_id uuid;
  v_conversion_id uuid;
  v_evaluated_at timestamptz;
  v_workbook public.opportunity_pricing_worksheets%rowtype;
  v_material public.organization_materials%rowtype;
  v_supplier public.organization_suppliers%rowtype;
  v_product public.organization_material_supplier_products%rowtype;
  v_price public.organization_material_supplier_prices%rowtype;
  v_conversion public.organization_material_supplier_product_unit_conversions%rowtype;
  v_existing public.worksheet_material_price_bindings%rowtype;
  v_derived jsonb;
  v_organization_currency text;
begin
  if jsonb_typeof(v_cells) is distinct from 'object' then
    raise exception 'worksheet_material_pricing:cells_must_be_an_object' using errcode = '22023';
  end if;
  if not jsonb_path_exists(v_cells, '$.*.metadata.materialPricing') and not exists (
    select 1 from public.worksheet_material_price_bindings binding
    where binding.organization_id = new.organization_id and binding.workbook_id = new.workbook_id
      and binding.sheet_id = new.id and binding.binding_state = 'active'
  ) then return new; end if;
  if v_actor is null or new.updated_by is distinct from v_actor then
    raise exception 'worksheet_material_pricing:actor_mismatch' using errcode = '42501';
  end if;
  if not public.has_org_permission(new.organization_id, 'materials.view') then
    raise exception 'worksheet_material_pricing:materials_view_permission_required' using errcode = '42501';
  end if;
  select * into v_workbook from public.opportunity_pricing_worksheets workbook
  where workbook.id = new.workbook_id and workbook.organization_id = new.organization_id
    and workbook.opportunity_id = new.opportunity_id and workbook.archived_at is null;
  if v_workbook.id is null or not public.can_write_pricing_workbook_owner(
    v_workbook.organization_id, v_workbook.opportunity_id, v_workbook.project_id,
    v_workbook.quote_id, v_workbook.variation_id
  ) then raise exception 'worksheet_material_pricing:invalid_workbook_scope' using errcode = '42501'; end if;
  select public.resolve_material_estimating_currency(to_jsonb(organization)) into v_organization_currency
  from public.organizations organization where organization.id = new.organization_id;

  if exists (
    select 1 from jsonb_each(v_cells) cell where cell.value #> '{metadata,materialPricing}' is not null
    group by cell.value #>> '{metadata,materialPricing,bindingId}' having count(*) > 1
  ) then raise exception 'worksheet_material_pricing:duplicate_binding_id' using errcode = '22023'; end if;

  -- Validate the complete set before changing any binding lifecycle state.
  for v_cell in select cell.key as cell_address, cell.value as cell_data
    from jsonb_each(v_cells) cell where cell.value #> '{metadata,materialPricing}' is not null
  loop
    v_metadata := v_cell.cell_data #> '{metadata,materialPricing}';
    begin
      v_version := (v_metadata->>'version')::integer;
      v_binding_id := (v_metadata->>'bindingId')::uuid;
      v_material_id := (v_metadata->>'organizationMaterialId')::uuid;
      v_supplier_id := (v_metadata->>'supplierId')::uuid;
      v_product_id := (v_metadata->>'supplierProductId')::uuid;
      if v_version = 1 then
        v_price_id := (v_metadata->>'supplierPriceId')::uuid;
        v_evaluated_at := (v_metadata #>> '{snapshot,evaluatedAt}')::timestamptz;
        v_conversion_id := null;
      elsif v_version = 2 then
        v_price_id := (v_metadata #>> '{sourcePricing,supplierPriceId}')::uuid;
        v_evaluated_at := (v_metadata #>> '{estimatingPricing,evaluatedAt}')::timestamptz;
        v_conversion_id := nullif(v_metadata #>> '{conversion,conversionId}', '')::uuid;
      else raise exception 'unsupported_version'; end if;
    exception when others then
      raise exception 'worksheet_material_pricing:malformed_metadata:%', v_cell.cell_address using errcode = '22023';
    end;
    if v_cell.cell_address !~ '^[A-Z]+[1-9][0-9]*$'
      or jsonb_typeof(v_cell.cell_data->'value') is distinct from 'number'
      or coalesce(v_cell.cell_data->>'type', '') <> 'number'
      or nullif(v_cell.cell_data->>'formula', '') is not null then
      raise exception 'worksheet_material_pricing:bound_cell_must_be_numeric:%', v_cell.cell_address using errcode = '22023';
    end if;

    select * into v_material from public.organization_materials
      where organization_id = new.organization_id and id = v_material_id;
    select * into v_supplier from public.organization_suppliers
      where organization_id = new.organization_id and id = v_supplier_id;
    select * into v_product from public.organization_material_supplier_products
      where organization_id = new.organization_id and id = v_product_id;
    select * into v_price from public.organization_material_supplier_prices
      where organization_id = new.organization_id and id = v_price_id;
    select * into v_existing from public.worksheet_material_price_bindings where id = v_binding_id;
    if v_material.id is null or v_supplier.id is null or v_product.id is null or v_price.id is null
      or v_product.material_id <> v_material.id or v_product.supplier_id <> v_supplier.id
      or v_price.supplier_product_id <> v_product.id or v_price.material_id <> v_material.id
      or v_price.supplier_id <> v_supplier.id
      or not exists (select 1 from public.resolve_material_supplier_product_prices(
        new.organization_id, v_evaluated_at, array[v_product.id]
      ) resolved where resolved.price_id = v_price.id)
      or (v_existing.id is not null and (v_existing.organization_id <> new.organization_id
        or v_existing.workbook_id <> new.workbook_id or v_existing.sheet_id <> new.id
        or v_existing.organization_material_id <> v_material.id or v_existing.supplier_id <> v_supplier.id
        or v_existing.supplier_product_id <> v_product.id or v_existing.supplier_price_id <> v_price.id)) then
      raise exception 'worksheet_material_pricing:invalid_binding_evidence:%', v_cell.cell_address using errcode = '42501';
    end if;
    if public.validate_worksheet_material_pricing_evidence(
      new.organization_id, (v_cell.cell_data->>'value')::numeric, v_metadata
    ) is not true then
      raise exception 'worksheet_material_pricing:invalid_binding_evidence:%', v_cell.cell_address using errcode = '42501';
    end if;

    if v_version = 1 then
      if (v_cell.cell_data->>'value')::numeric is distinct from v_price.unit_cost
        or (v_metadata #>> '{snapshot,unitCost}')::numeric is distinct from v_price.unit_cost
        or v_metadata #>> '{snapshot,unit}' is distinct from v_price.unit
        or upper(v_metadata #>> '{snapshot,currency}') is distinct from upper(v_price.currency)
        or (v_metadata #>> '{snapshot,priceEffectiveFrom}')::timestamptz is distinct from v_price.effective_from then
        raise exception 'worksheet_material_pricing:invalid_binding_evidence:%', v_cell.cell_address using errcode = '42501';
      end if;
    else
      v_conversion := null;
      if v_conversion_id is not null then
        select * into v_conversion from public.organization_material_supplier_product_unit_conversions conversion
        where conversion.organization_id = new.organization_id and conversion.id = v_conversion_id
          and conversion.supplier_product_id = v_product.id
          and conversion.effective_from <= v_evaluated_at
          and (conversion.effective_to is null or conversion.effective_to > v_evaluated_at)
          and conversion.source in ('user_confirmed_ai','user_confirmed_manual');
        if v_conversion.id is null then
          raise exception 'worksheet_material_pricing:invalid_conversion_evidence:%', v_cell.cell_address using errcode = '42501';
        end if;
      end if;
      v_derived := public.derive_material_estimating_price(
        v_price.id, v_price.unit_cost, v_price.unit, v_price.currency, v_price.source_tax_basis,
        v_price.source_tax_rate, v_price.tax_jurisdiction_code, v_price.comparison_tax_basis,
        v_price.comparison_tax_rate, v_price.tax_policy_snapshot, v_price.effective_from,
        v_material.default_unit, v_organization_currency, v_evaluated_at,
        v_conversion.id, v_conversion.supplier_quantity, v_conversion.supplier_unit,
        v_conversion.material_quantity, v_conversion.material_unit, v_conversion.source,
        v_conversion.contract_version, v_conversion.effective_from, v_conversion.confirmed_at
      );
	      if v_derived #>> '{estimatingPricing,status}' <> 'available'
	        or ((v_derived #>> '{estimatingPricing,derivationKind}') = 'direct_unit_match'
	          and v_metadata->'conversion' is distinct from 'null'::jsonb)
        or abs((v_cell.cell_data->>'value')::numeric - (v_derived #>> '{estimatingPricing,unitCost}')::numeric) > 0.0000000001
        or abs((v_metadata #>> '{estimatingPricing,unitCost}')::numeric - (v_derived #>> '{estimatingPricing,unitCost}')::numeric) > 0.0000000001
        or abs((v_metadata #>> '{estimatingPricing,normalizedSourceUnitCost}')::numeric - (v_derived #>> '{estimatingPricing,normalizedSourceUnitCost}')::numeric) > 0.0000000001
        or v_metadata #>> '{estimatingPricing,unit}' is distinct from v_derived #>> '{estimatingPricing,unit}'
        or v_metadata #>> '{estimatingPricing,currency}' is distinct from v_derived #>> '{estimatingPricing,currency}'
        or v_metadata #>> '{estimatingPricing,taxBasis}' is distinct from v_derived #>> '{estimatingPricing,taxBasis}'
        or v_metadata #>> '{estimatingPricing,derivationKind}' is distinct from v_derived #>> '{estimatingPricing,derivationKind}'
        or v_metadata #>> '{estimatingPricing,calculationVersion}' is distinct from 'material_estimating_price_v1'
        or (v_metadata #>> '{sourcePricing,unitCost}')::numeric is distinct from v_price.unit_cost
        or v_metadata #>> '{sourcePricing,unit}' is distinct from v_price.unit
        or upper(v_metadata #>> '{sourcePricing,currency}') is distinct from upper(v_price.currency)
        or v_metadata #>> '{sourcePricing,sourceTaxBasis}' is distinct from v_price.source_tax_basis
        or (v_metadata #>> '{sourcePricing,sourceTaxRate}')::numeric is distinct from v_price.source_tax_rate
        or v_metadata #>> '{sourcePricing,taxJurisdictionCode}' is distinct from v_price.tax_jurisdiction_code
        or v_metadata #>> '{sourcePricing,comparisonTaxBasis}' is distinct from v_price.comparison_tax_basis
        or (v_metadata #>> '{sourcePricing,comparisonTaxRate}')::numeric is distinct from v_price.comparison_tax_rate
        or (v_metadata #>> '{sourcePricing,priceEffectiveFrom}')::timestamptz is distinct from v_price.effective_from
        or (v_conversion_id is not null and (
          (v_metadata #>> '{conversion,supplierQuantity}')::numeric is distinct from v_conversion.supplier_quantity
          or v_metadata #>> '{conversion,supplierUnit}' is distinct from v_conversion.supplier_unit
          or (v_metadata #>> '{conversion,materialQuantity}')::numeric is distinct from v_conversion.material_quantity
          or v_metadata #>> '{conversion,materialUnit}' is distinct from v_conversion.material_unit
          or v_metadata #>> '{conversion,confirmationSource}' is distinct from v_conversion.source
          or v_metadata #>> '{conversion,contractVersion}' is distinct from v_conversion.contract_version
          or (v_metadata #>> '{conversion,effectiveFrom}')::timestamptz is distinct from v_conversion.effective_from
          or (v_metadata #>> '{conversion,confirmedAt}')::timestamptz is distinct from v_conversion.confirmed_at
        )) then
        raise exception 'worksheet_material_pricing:invalid_estimating_evidence:%', v_cell.cell_address using errcode = '42501';
      end if;
    end if;
  end loop;

  update public.worksheet_material_price_bindings binding
  set binding_state = case
      when exists (select 1 from jsonb_each(v_cells) cell where cell.key = binding.current_cell_address
        and cell.value #>> '{metadata,materialPricing,bindingId}' is not null) then 'replaced'
      when (v_cells -> binding.current_cell_address) is null then 'removed' else 'detached' end,
    replaced_by_binding_id = (select (cell.value #>> '{metadata,materialPricing,bindingId}')::uuid
      from jsonb_each(v_cells) cell where cell.key = binding.current_cell_address
        and cell.value #>> '{metadata,materialPricing,bindingId}' is not null limit 1),
    state_changed_at = statement_timestamp()
  where binding.organization_id = new.organization_id and binding.workbook_id = new.workbook_id
    and binding.sheet_id = new.id and binding.binding_state = 'active'
    and not exists (select 1 from jsonb_each(v_cells) cell
      where cell.value #>> '{metadata,materialPricing,bindingId}' = binding.id::text);

  insert into public.worksheet_material_price_bindings (
    id, organization_id, workbook_id, sheet_id, current_cell_address, insertion_cell_address,
    organization_material_id, supplier_id, supplier_product_id, supplier_price_id,
    inserted_unit_cost, unit_snapshot, currency_snapshot, source_tax_basis_snapshot,
    source_tax_rate_snapshot, tax_jurisdiction_code_snapshot, material_name_snapshot,
    supplier_name_snapshot, supplier_product_description_snapshot, supplier_sku_snapshot,
    price_effective_from, effective_price_evaluated_at, inserted_by, inserted_at,
    binding_state, state_changed_at, provenance_version, pricing_derivation_kind,
    worksheet_rate_snapshot, worksheet_unit_snapshot, normalized_source_unit_cost_snapshot,
    comparison_tax_basis_snapshot, comparison_tax_rate_snapshot, calculation_version,
    unit_conversion_id, conversion_supplier_quantity_snapshot, conversion_supplier_unit_snapshot,
    conversion_material_quantity_snapshot, conversion_material_unit_snapshot,
    conversion_contract_version_snapshot, conversion_source_snapshot,
    conversion_effective_from_snapshot, conversion_confirmed_at_snapshot
  )
  select
    (metadata->>'bindingId')::uuid, new.organization_id, new.workbook_id, new.id,
    cell_address, cell_address, (metadata->>'organizationMaterialId')::uuid,
    (metadata->>'supplierId')::uuid, (metadata->>'supplierProductId')::uuid,
    coalesce(metadata->>'supplierPriceId', metadata #>> '{sourcePricing,supplierPriceId}')::uuid,
    coalesce(metadata #>> '{snapshot,unitCost}', metadata #>> '{sourcePricing,unitCost}')::numeric,
    coalesce(metadata #>> '{snapshot,unit}', metadata #>> '{sourcePricing,unit}'),
    coalesce(metadata #>> '{snapshot,currency}', metadata #>> '{sourcePricing,currency}'),
    coalesce(metadata #>> '{snapshot,sourceTaxBasis}', metadata #>> '{sourcePricing,sourceTaxBasis}'),
    coalesce(metadata #>> '{snapshot,sourceTaxRate}', metadata #>> '{sourcePricing,sourceTaxRate}')::numeric,
    coalesce(metadata #>> '{snapshot,taxJurisdictionCode}', metadata #>> '{sourcePricing,taxJurisdictionCode}'),
    coalesce(metadata #>> '{snapshot,materialName}', metadata #>> '{labels,materialName}'),
    coalesce(metadata #>> '{snapshot,supplierName}', metadata #>> '{labels,supplierName}'),
    coalesce(metadata #>> '{snapshot,supplierProductDescription}', metadata #>> '{labels,supplierProductDescription}'),
    coalesce(metadata #>> '{snapshot,supplierSku}', metadata #>> '{labels,supplierSku}'),
    coalesce(metadata #>> '{snapshot,priceEffectiveFrom}', metadata #>> '{sourcePricing,priceEffectiveFrom}')::timestamptz,
    coalesce(metadata #>> '{snapshot,evaluatedAt}', metadata #>> '{estimatingPricing,evaluatedAt}')::timestamptz,
    v_actor, statement_timestamp(), 'active', statement_timestamp(), (metadata->>'version')::smallint,
    metadata #>> '{estimatingPricing,derivationKind}', (metadata #>> '{estimatingPricing,unitCost}')::numeric,
    metadata #>> '{estimatingPricing,unit}', (metadata #>> '{estimatingPricing,normalizedSourceUnitCost}')::numeric,
    metadata #>> '{sourcePricing,comparisonTaxBasis}', (metadata #>> '{sourcePricing,comparisonTaxRate}')::numeric,
    metadata #>> '{estimatingPricing,calculationVersion}', nullif(metadata #>> '{conversion,conversionId}', '')::uuid,
    (metadata #>> '{conversion,supplierQuantity}')::numeric, metadata #>> '{conversion,supplierUnit}',
    (metadata #>> '{conversion,materialQuantity}')::numeric, metadata #>> '{conversion,materialUnit}',
    metadata #>> '{conversion,contractVersion}', metadata #>> '{conversion,confirmationSource}',
    (metadata #>> '{conversion,effectiveFrom}')::timestamptz, (metadata #>> '{conversion,confirmedAt}')::timestamptz
  from (select entry.key as cell_address, entry.value #> '{metadata,materialPricing}' as metadata
    from jsonb_each(v_cells) entry where entry.value #> '{metadata,materialPricing}' is not null) cells
  on conflict (id) do update set current_cell_address = excluded.current_cell_address,
    binding_state = 'active', replaced_by_binding_id = null, state_changed_at = statement_timestamp();
  return new;
end;
$_$;


