CREATE TABLE IF NOT EXISTS "public"."organization_accounting_remote_observations" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "accounting_document_id" "uuid" NOT NULL,
    "accounting_revision_id" "uuid" NOT NULL,
    "provider" "text" NOT NULL,
    "tenant_id" "text" NOT NULL,
    "external_document_id" "text" NOT NULL,
    "observed_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "provider_updated_at" timestamp with time zone,
    "raw_status" "text",
    "normalized_status" "text",
    "content_hash" "text" NOT NULL,
    "settlement_hash" "text" NOT NULL,
    "raw_observation" "jsonb" NOT NULL,
    CONSTRAINT "accounting_remote_observation_hashes_check" CHECK ((("content_hash" ~ '^[a-f0-9]{64}$'::"text") AND ("settlement_hash" ~ '^[a-f0-9]{64}$'::"text"))),
    CONSTRAINT "accounting_remote_observation_object_check" CHECK (("jsonb_typeof"("raw_observation") = 'object'::"text")),
    CONSTRAINT "accounting_remote_observation_text_check" CHECK ((("char_length"(TRIM(BOTH FROM "provider")) > 0) AND ("char_length"(TRIM(BOTH FROM "tenant_id")) > 0) AND ("char_length"(TRIM(BOTH FROM "external_document_id")) > 0)))
);

ALTER TABLE ONLY "public"."organization_accounting_remote_observations" FORCE ROW LEVEL SECURITY;


ALTER TABLE "public"."organization_accounting_remote_observations" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_accounting_remote_observation_phase2a"("p_input" "jsonb") RETURNS "public"."organization_accounting_remote_observations"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  revision public.organization_accounting_document_revisions%rowtype;
  observation public.organization_accounting_remote_observations%rowtype;
  projection public.organization_accounting_projections%rowtype;
  is_divergent boolean;
begin
  select r.* into revision
  from public.organization_accounting_document_revisions r
  join public.organization_accounting_documents d
    on d.id = r.accounting_document_id
    and d.organization_id = r.organization_id
  where r.id = (p_input->>'accountingRevisionId')::uuid
    and r.organization_id = (p_input->>'organizationId')::uuid
    and d.active_accounting_revision_id = r.id;
  if not found then
    raise exception 'Remote observation revision is not active for its accounting document.';
  end if;
  if revision.lifecycle_state <> 'succeeded'
    or revision.accounting_document_id <> (p_input->>'accountingDocumentId')::uuid
    or revision.provider <> p_input->>'provider'
    or revision.tenant_id <> p_input->>'tenantId'
    or revision.external_document_id <> p_input->>'externalDocumentId' then
    raise exception 'Remote observation does not match the bound successful revision.';
  end if;

  is_divergent :=
    (p_input->>'contentHash') is distinct from revision.provider_content_hash;
  insert into public.organization_accounting_remote_observations(
    organization_id, accounting_document_id, accounting_revision_id,
    provider, tenant_id, external_document_id, provider_updated_at,
    raw_status, normalized_status, content_hash, settlement_hash,
    raw_observation
  ) values (
    revision.organization_id, revision.accounting_document_id, revision.id,
    revision.provider, revision.tenant_id, revision.external_document_id,
    nullif(p_input->>'providerUpdatedAt', '')::timestamptz,
    p_input->>'rawStatus', p_input->>'normalizedStatus',
    p_input->>'contentHash', p_input->>'settlementHash',
    p_input->'rawObservation'
  ) returning * into observation;

  insert into public.organization_accounting_projections(
    organization_id, accounting_document_id, accounting_revision_id,
    remote_observation_id, raw_provider_status, normalized_invoice_status,
    normalized_payment_status, amount_paid_minor, amount_due_minor,
    amount_credited_minor, divergent, divergence_reasons,
    observed_content_hash, projected_at, updated_at
  ) values (
    revision.organization_id, revision.accounting_document_id, revision.id,
    observation.id, p_input->>'rawStatus', p_input->>'normalizedInvoiceStatus',
    p_input->>'normalizedPaymentStatus',
    nullif(p_input->>'amountPaidMinor', '')::bigint,
    nullif(p_input->>'amountDueMinor', '')::bigint,
    nullif(p_input->>'amountCreditedMinor', '')::bigint,
    is_divergent,
    case when is_divergent then
      jsonb_build_array('remote_content_differs_from_export_revision')
    else '[]'::jsonb end,
    observation.content_hash, observation.observed_at, now()
  )
  on conflict (accounting_document_id) do update set
    accounting_revision_id = excluded.accounting_revision_id,
    remote_observation_id = excluded.remote_observation_id,
    raw_provider_status = excluded.raw_provider_status,
    normalized_invoice_status = excluded.normalized_invoice_status,
    normalized_payment_status = excluded.normalized_payment_status,
    amount_paid_minor = excluded.amount_paid_minor,
    amount_due_minor = excluded.amount_due_minor,
    amount_credited_minor = excluded.amount_credited_minor,
    divergent = excluded.divergent,
    divergence_reasons = excluded.divergence_reasons,
    observed_content_hash = excluded.observed_content_hash,
    projected_at = excluded.projected_at,
    updated_at = now()
  returning * into projection;

  perform set_config('app.accounting_phase2a_pointer_write', 'true', true);
  update public.organization_accounting_documents set
    current_accounting_projection_id = projection.id
  where id = revision.accounting_document_id
    and organization_id = revision.organization_id;
  perform set_config('app.accounting_phase2a_pointer_write', '', true);

  insert into public.organization_accounting_events(
    organization_id, accounting_document_id, accounting_revision_id,
    event_type, correlation_id, event_evidence
  ) values (
    revision.organization_id, revision.accounting_document_id, revision.id,
    case when is_divergent then 'remote_divergence_observed'
      else 'remote_status_observed' end,
    p_input->>'correlationId',
    jsonb_build_object(
      'remoteObservationId', observation.id,
      'projectionId', projection.id,
      'contentHash', observation.content_hash,
      'settlementHash', observation.settlement_hash,
      'divergent', is_divergent
    )
  );
  return observation;
end;
$$;


ALTER FUNCTION "public"."record_accounting_remote_observation_phase2a"("p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_ai_interaction_validation"("p_input" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  resolved_organization_id uuid;
  resolved_ai_interaction_id uuid;
  validation_case_id uuid;
  resolved_validation_status text;
begin
  if p_input is null or jsonb_typeof(p_input) <> 'object' then
    raise exception 'record_ai_interaction_validation requires a JSON object payload';
  end if;

  resolved_organization_id := nullif(p_input->>'organizationId', '')::uuid;
  resolved_ai_interaction_id := nullif(p_input->>'aiInteractionId', '')::uuid;
  resolved_validation_status := coalesce(nullif(btrim(coalesce(p_input->>'validationStatus', '')), ''), 'warning');

  if resolved_organization_id is null then
    raise exception 'organizationId is required';
  end if;

  if resolved_ai_interaction_id is null then
    raise exception 'aiInteractionId is required';
  end if;

  perform public._intelligence_assert_ai_interaction_in_organization(
    resolved_organization_id,
    resolved_ai_interaction_id
  );

  validation_case_id := public.create_validation_case(
    jsonb_build_object(
      'organizationId', resolved_organization_id,
      'projectId', p_input->>'projectId',
      'opportunityId', p_input->>'opportunityId',
      'module', p_input->>'module',
      'scopeEntityType', p_input->>'scopeEntityType',
      'scopeEntityId', p_input->>'scopeEntityId',
      'linkedAiInteractionId', resolved_ai_interaction_id,
      'ruleKey', p_input->>'ruleKey',
      'ruleVersion', coalesce(p_input->>'ruleVersion', 'v1'),
      'validationType', p_input->>'validationType',
      'severity', p_input->>'severity',
      'result', p_input->>'result',
      'expectedValue', coalesce(p_input->'expectedValue', 'null'::jsonb),
      'observedValue', coalesce(p_input->'observedValue', 'null'::jsonb),
      'details', coalesce(p_input->'details', '{}'::jsonb),
      'requiresApproval', coalesce(p_input->'requiresApproval', 'false'::jsonb),
      'approvalStatus', coalesce(p_input->>'approvalStatus', 'not_required'),
      'approvalNote', p_input->>'approvalNote',
      'privacyClassification', coalesce(p_input->>'privacyClassification', 'commercial_sensitive'),
      'visibilityScope', coalesce(p_input->>'visibilityScope', 'organization')
    )
  );

  update public.ai_interactions
  set
    validation_status = resolved_validation_status,
    lifecycle_state = case
      when lifecycle_state in ('requested', 'generated') then 'validated'
      else lifecycle_state
    end,
    updated_at = now()
  where id = resolved_ai_interaction_id
    and organization_id = resolved_organization_id;

  return validation_case_id;
end;
$$;


ALTER FUNCTION "public"."record_ai_interaction_validation"("p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_payment_claim_initial_push_observation_phase2b"("p_revision_id" "uuid", "p_observation" "jsonb", "p_reason" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
declare
  v_revision public.organization_accounting_document_revisions%rowtype;
  v_id uuid;
  v_external_id text;
begin
  select * into v_revision
  from public.organization_accounting_document_revisions
  where id = p_revision_id;
  if not found or v_revision.revision_intent <> 'initial_push' then
    raise exception 'Immutable initial-push revision not found.';
  end if;
  v_external_id := coalesce(
    nullif(trim(p_observation->>'InvoiceID'), ''),
    nullif(trim(p_observation->>'invoiceID'), '')
  );
  if v_external_id is null then
    raise exception 'Unverified provider observation requires an InvoiceID.';
  end if;
  insert into public.organization_accounting_remote_observations(
    organization_id, accounting_document_id, accounting_revision_id,
    provider, tenant_id, external_document_id, provider_updated_at,
    raw_status, normalized_status, content_hash, settlement_hash,
    raw_observation
  ) values (
    v_revision.organization_id, v_revision.accounting_document_id, v_revision.id,
    'xero', v_revision.tenant_id, v_external_id, null,
    coalesce(p_observation->>'Status', p_observation->>'status'),
    'unverified',
    encode(digest(p_observation::text::bytea, 'sha256'), 'hex'),
    encode(digest(jsonb_build_object('unverified', true)::text::bytea, 'sha256'), 'hex'),
    p_observation
  ) returning id into v_id;
  insert into public.organization_accounting_events(
    organization_id, accounting_document_id, accounting_revision_id,
    event_type, event_evidence
  ) values (
    v_revision.organization_id, v_revision.accounting_document_id, v_revision.id,
    'initial_push_provider_mismatch',
    jsonb_build_object('remoteObservationId', v_id, 'reason', p_reason)
  );
  return v_id;
end;
$$;


ALTER FUNCTION "public"."record_payment_claim_initial_push_observation_phase2b"("p_revision_id" "uuid", "p_observation" "jsonb", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_retention_capability_event"("p_organization_id" "uuid", "p_project_id" "uuid", "p_event_type" "text", "p_previous_state" "text", "p_new_state" "text", "p_actor_user_id" "uuid", "p_reason" "text", "p_correlation_id" "text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_event_id uuid;
begin
  insert into public.retention_capability_events (
    organization_id,
    project_id,
    event_type,
    previous_state,
    new_state,
    actor_user_id,
    reason,
    correlation_id,
    metadata
  )
  values (
    p_organization_id,
    p_project_id,
    p_event_type,
    p_previous_state,
    p_new_state,
    p_actor_user_id,
    left(coalesce(nullif(trim(p_reason), ''), 'Retention management action recorded.'), 1000),
    nullif(left(trim(coalesce(p_correlation_id, '')), 200), ''),
    coalesce(p_metadata, '{}'::jsonb)
  )
  returning id into v_event_id;

  return v_event_id;
end;
$$;


ALTER FUNCTION "public"."record_retention_capability_event"("p_organization_id" "uuid", "p_project_id" "uuid", "p_event_type" "text", "p_previous_state" "text", "p_new_state" "text", "p_actor_user_id" "uuid", "p_reason" "text", "p_correlation_id" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_retention_claim_document"("p_retention_claim_id" "uuid", "p_source_evidence_hash" "text", "p_pdf_sha256" "text", "p_file_name" "text", "p_storage_path" "text", "p_byte_length" bigint, "p_render_model_snapshot" "jsonb", "p_actor_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $_$
declare
  claim_row public.retention_claims%rowtype;
  source jsonb;
  expected_source_hash text;
  expected_storage_path text;
  document_row public.retention_claim_documents%rowtype;
  inserted boolean := false;
  capability_enabled boolean;
  workflow_mode text;
begin
  select * into claim_row
  from public.retention_claims
  where id = p_retention_claim_id;

  if not found then
    return jsonb_build_object(
      'succeeded', false, 'errorCode', 'document_not_found'
    );
  end if;

  if auth.role() is distinct from 'service_role' then
    return jsonb_build_object(
      'succeeded', false, 'errorCode', 'permission_denied'
    );
  end if;

  if not private.retention_phase8_actor_has_permission(
    claim_row.organization_id,
    p_actor_user_id,
    'retention.claims.documents.generate'
  ) then
    return jsonb_build_object(
      'succeeded', false, 'errorCode', 'permission_denied'
    );
  end if;

  select coalesce(capability.enabled, false)
  into capability_enabled
  from public.organization_capabilities capability
  where capability.organization_id = claim_row.organization_id
    and capability.capability_key = 'retention_management';
  if not coalesce(capability_enabled, false) then
    return jsonb_build_object(
      'succeeded', false, 'errorCode', 'capability_disabled'
    );
  end if;

  select coalesce(state.mode, 'legacy')
  into workflow_mode
  from public.project_retention_workflow_states state
  where state.organization_id = claim_row.organization_id
    and state.project_id = claim_row.project_id;
  if coalesce(workflow_mode, 'legacy') <> 'observe' then
    return jsonb_build_object(
      'succeeded', false, 'errorCode', 'project_mode_not_supported',
      'workflowMode', coalesce(workflow_mode, 'legacy')
    );
  end if;

  if claim_row.status <> 'submitted' then
    return jsonb_build_object(
      'succeeded', false, 'errorCode', 'claim_not_submitted'
    );
  end if;

  source := private.retention_claim_document_source(claim_row.id);
  expected_source_hash := encode(
    extensions.digest(convert_to(source::text, 'UTF8'), 'sha256'),
    'hex'
  );
  expected_storage_path := concat(
    claim_row.organization_id, '/',
    claim_row.project_id, '/',
    claim_row.id, '/',
    expected_source_hash, '.pdf'
  );

  if p_source_evidence_hash is distinct from expected_source_hash then
    return jsonb_build_object(
      'succeeded', false, 'errorCode', 'stale_document_source',
      'currentSourceEvidenceHash', expected_source_hash
    );
  end if;

  if p_pdf_sha256 is null
     or p_pdf_sha256 !~ '^[a-f0-9]{64}$'
     or p_byte_length is null
     or p_byte_length <= 0
     or p_byte_length > 10485760
     or nullif(trim(coalesce(p_file_name, '')), '') is null
     or char_length(p_file_name) > 250
     or p_storage_path is distinct from expected_storage_path
     or p_render_model_snapshot is null
     or jsonb_typeof(p_render_model_snapshot) <> 'object' then
    return jsonb_build_object(
      'succeeded', false, 'errorCode', 'invalid_document_evidence'
    );
  end if;

  begin
    insert into public.retention_claim_documents(
      organization_id,
      project_id,
      retention_claim_id,
      source_evidence_hash,
      pdf_sha256,
      file_name,
      storage_path,
      byte_length,
      render_model_snapshot,
      created_by
    )
    values (
      claim_row.organization_id,
      claim_row.project_id,
      claim_row.id,
      expected_source_hash,
      p_pdf_sha256,
      trim(p_file_name),
      expected_storage_path,
      p_byte_length,
      p_render_model_snapshot,
      p_actor_user_id
    )
    returning * into document_row;
    inserted := true;
  exception when unique_violation then
    select * into document_row
    from public.retention_claim_documents
    where retention_claim_id = claim_row.id
      and document_kind = 'submitted_claim_pdf'
      and document_version = 1;
  end;

  if document_row.id is null
     or document_row.source_evidence_hash <> expected_source_hash
     or document_row.pdf_sha256 <> p_pdf_sha256
     or document_row.storage_path <> expected_storage_path
     or document_row.byte_length <> p_byte_length then
    return jsonb_build_object(
      'succeeded', false, 'errorCode', 'document_conflict'
    );
  end if;

  if inserted then
    insert into public.retention_claim_document_events(
      organization_id,
      project_id,
      retention_claim_id,
      retention_claim_document_id,
      event_type,
      actor_user_id,
      source_evidence_hash,
      pdf_sha256,
      metadata
    )
    values (
      document_row.organization_id,
      document_row.project_id,
      document_row.retention_claim_id,
      document_row.id,
      'document_generated',
      p_actor_user_id,
      document_row.source_evidence_hash,
      document_row.pdf_sha256,
      jsonb_build_object(
        'documentKind', document_row.document_kind,
        'documentVersion', document_row.document_version,
        'fileName', document_row.file_name,
        'byteLength', document_row.byte_length
      )
    );
  end if;

  return jsonb_build_object(
    'succeeded', true,
    'errorCode', null,
    'created', inserted,
    'reused', not inserted,
    'document', to_jsonb(document_row)
  );
end;
$_$;


ALTER FUNCTION "public"."record_retention_claim_document"("p_retention_claim_id" "uuid", "p_source_evidence_hash" "text", "p_pdf_sha256" "text", "p_file_name" "text", "p_storage_path" "text", "p_byte_length" bigint, "p_render_model_snapshot" "jsonb", "p_actor_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_retention_claim_payment_reconciliation"("p_retention_claim_id" "uuid", "p_source" "text", "p_actor_user_id" "uuid", "p_expected_previous_reconciliation_id" "uuid", "p_payment_status" "text", "p_projection_applied" boolean, "p_paid_amount_excl_tax" numeric, "p_invoice_total_gross" numeric, "p_amount_paid_gross" numeric, "p_amount_due_gross" numeric, "p_amount_credited_gross" numeric, "p_raw_provider_status" "text", "p_normalized_provider_status" "text", "p_fully_paid_at" timestamp with time zone, "p_provider_updated_at" timestamp with time zone, "p_accounting_document_id" "uuid", "p_accounting_snapshot_id" "uuid", "p_external_document_id" "text", "p_attention_code" "text", "p_attention_message" "text", "p_attributions" "jsonb", "p_correlation_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
declare
  claim_row public.retention_claims%rowtype;
  document_row public.organization_accounting_documents%rowtype;
  snapshot_row public.retention_claim_accounting_snapshots%rowtype;
  latest_id uuid;
  next_sequence integer;
  reconciliation_id uuid;
  source_hash text;
  supplied_count integer;
  allocation_count integer;
  supplied_paid numeric;
  paid_cents bigint;
  subtotal_cents bigint;
  residual_cents bigint;
begin
  if auth.role() is distinct from 'service_role' then
    return jsonb_build_object(
      'succeeded', false, 'errorCode', 'permission_denied'
    );
  end if;
  if p_source not in ('manual', 'xero') then
    return jsonb_build_object(
      'succeeded', false, 'errorCode', 'invalid_source'
    );
  end if;

  select * into claim_row
  from public.retention_claims
  where id = p_retention_claim_id
  for update;
  if not found or claim_row.status <> 'submitted' then
    return jsonb_build_object(
      'succeeded', false, 'errorCode', 'claim_not_submitted'
    );
  end if;

  if not exists (
    select 1 from public.organization_capabilities capability
    where capability.organization_id = claim_row.organization_id
      and capability.capability_key = 'retention_management'
      and capability.enabled = true
  ) or not exists (
    select 1 from public.project_retention_workflow_states state
    where state.organization_id = claim_row.organization_id
      and state.project_id = claim_row.project_id
      and state.mode = 'observe'
  ) then
    return jsonb_build_object(
      'succeeded', false, 'errorCode', 'project_mode_not_supported'
    );
  end if;

  if p_source = 'manual' and (
    p_actor_user_id is null
    or not private.retention_phase8_actor_has_permission(
      claim_row.organization_id,
      p_actor_user_id,
      'retention.claims.payments.manage'
    )
  ) then
    return jsonb_build_object(
      'succeeded', false, 'errorCode', 'permission_denied'
    );
  end if;

  select reconciliation.id into latest_id
  from public.retention_claim_payment_reconciliations reconciliation
  where reconciliation.retention_claim_id = claim_row.id
  order by reconciliation.reconciliation_sequence desc
  limit 1;
  if latest_id is distinct from p_expected_previous_reconciliation_id then
    return jsonb_build_object(
      'succeeded', false, 'errorCode', 'concurrent_reconciliation'
    );
  end if;

  select coalesce(max(reconciliation_sequence), 0) + 1
  into next_sequence
  from public.retention_claim_payment_reconciliations
  where retention_claim_id = claim_row.id;

  if p_source = 'manual' then
    if not p_projection_applied
       or p_paid_amount_excl_tax is null
       or round(p_paid_amount_excl_tax, 2) < 0
       or round(p_paid_amount_excl_tax, 2) > claim_row.subtotal_excl_tax
       or p_invoice_total_gross is not null
       or p_accounting_document_id is not null
       or p_attention_code is not null
       or p_payment_status <> (case
         when round(p_paid_amount_excl_tax, 2) = 0 then 'unpaid'
         when round(p_paid_amount_excl_tax, 2) =
           claim_row.subtotal_excl_tax then 'paid'
         else 'partially_paid'
       end) then
      return jsonb_build_object(
        'succeeded', false, 'errorCode', 'invalid_manual_payment'
      );
    end if;
  else
    select * into document_row
    from public.organization_accounting_documents
    where id = p_accounting_document_id
      and organization_id = claim_row.organization_id
      and provider = 'xero'
      and local_document_type = 'retention_claim'
      and retention_claim_id = claim_row.id
      and external_document_id = p_external_document_id
    for update;
    if not found then
      return jsonb_build_object(
        'succeeded', false, 'errorCode', 'accounting_document_invalid'
      );
    end if;
    select * into snapshot_row
    from public.retention_claim_accounting_snapshots
    where id = p_accounting_snapshot_id
      and accounting_document_id = document_row.id
      and retention_claim_id = claim_row.id;
    if not found then
      return jsonb_build_object(
        'succeeded', false, 'errorCode', 'accounting_snapshot_invalid'
      );
    end if;
    if p_invoice_total_gross is null
       or p_amount_paid_gross is null
       or p_amount_due_gross is null
       or p_amount_credited_gross is null
       or least(
         p_invoice_total_gross,
         p_amount_paid_gross,
         p_amount_due_gross,
         p_amount_credited_gross
       ) < 0 then
      return jsonb_build_object(
        'succeeded', false, 'errorCode', 'invalid_provider_payment'
      );
    end if;
    if p_projection_applied and (
      round(p_invoice_total_gross, 2) <> snapshot_row.total_snapshot
      or round(p_amount_credited_gross, 2) <> 0
      or round(p_amount_paid_gross, 2) > snapshot_row.total_snapshot
      or round(p_amount_paid_gross + p_amount_due_gross, 2) <>
        snapshot_row.total_snapshot
      or p_paid_amount_excl_tax is null
      or round(p_paid_amount_excl_tax, 2) < 0
      or round(p_paid_amount_excl_tax, 2) >
        snapshot_row.subtotal_excl_tax_snapshot
      or round(p_paid_amount_excl_tax, 2) <> round(
        p_amount_paid_gross
        * snapshot_row.subtotal_excl_tax_snapshot
        / snapshot_row.total_snapshot,
        2
      )
      or p_attention_code is not null
    ) then
      return jsonb_build_object(
        'succeeded', false, 'errorCode', 'invalid_xero_projection'
      );
    end if;
    if not p_projection_applied and (
      p_payment_status <> 'attention_required'
      or p_paid_amount_excl_tax is not null
      or nullif(trim(coalesce(p_attention_code, '')), '') is null
      or nullif(trim(coalesce(p_attention_message, '')), '') is null
    ) then
      return jsonb_build_object(
        'succeeded', false, 'errorCode', 'invalid_attention_state'
      );
    end if;
  end if;

  if p_projection_applied then
    if p_payment_status <> (case
      when round(p_paid_amount_excl_tax, 2) = 0 then 'unpaid'
      when round(p_paid_amount_excl_tax, 2) =
        claim_row.subtotal_excl_tax then 'paid'
      else 'partially_paid'
    end) then
      return jsonb_build_object(
        'succeeded', false, 'errorCode', 'payment_status_mismatch'
      );
    end if;

    if p_attributions is null
       or jsonb_typeof(p_attributions) <> 'array' then
      return jsonb_build_object(
        'succeeded', false, 'errorCode', 'invalid_attributions'
      );
    end if;

    with supplied as (
      select *
      from jsonb_to_recordset(p_attributions) as attribution(
        "allocationId" uuid,
        "originatingPaymentClaimId" uuid,
        "sequence" integer,
        "allocationAmount" numeric,
        "paidAmount" numeric,
        "floorPaidAmount" numeric,
        "residualCentAwarded" boolean,
        "remainderNumerator" numeric
      )
    )
    select count(*)::integer, coalesce(sum(round("paidAmount", 2)), 0)
    into supplied_count, supplied_paid
    from supplied;

    select count(*)::integer into allocation_count
    from public.retention_claim_allocations
    where retention_claim_id = claim_row.id;

    paid_cents := round(p_paid_amount_excl_tax * 100)::bigint;
    subtotal_cents := round(claim_row.subtotal_excl_tax * 100)::bigint;
    select paid_cents - coalesce(sum(
      (paid_cents * round(allocation.allocation_amount * 100)::bigint)
        / subtotal_cents
    ), 0)
    into residual_cents
    from public.retention_claim_allocations allocation
    where allocation.retention_claim_id = claim_row.id;

    if supplied_count <> allocation_count
       or supplied_paid <> round(p_paid_amount_excl_tax, 2)
       or exists (
         with expected as (
           select
             allocation.*,
             round(allocation.allocation_amount * 100)::bigint
               as allocation_cents,
             (
               paid_cents
               * round(allocation.allocation_amount * 100)::bigint
             ) / subtotal_cents as floor_cents,
             (
               paid_cents
               * round(allocation.allocation_amount * 100)::bigint
             ) % subtotal_cents as remainder,
             row_number() over (
               order by
                 (
                   paid_cents
                   * round(allocation.allocation_amount * 100)::bigint
                 ) % subtotal_cents desc,
                 allocation.allocation_sequence,
                 allocation.id
             ) as residual_rank
           from public.retention_claim_allocations allocation
           where allocation.retention_claim_id = claim_row.id
         ),
         supplied as (
           select *
           from jsonb_to_recordset(p_attributions) as attribution(
             "allocationId" uuid,
             "originatingPaymentClaimId" uuid,
             "sequence" integer,
             "allocationAmount" numeric,
             "paidAmount" numeric,
             "floorPaidAmount" numeric,
             "residualCentAwarded" boolean,
             "remainderNumerator" numeric
           )
         )
         select 1
         from expected
         full join supplied
           on supplied."allocationId" = expected.id
         where expected.id is null
            or supplied."allocationId" is null
            or supplied."originatingPaymentClaimId" is distinct from
              expected.originating_payment_claim_id
            or supplied."sequence" is distinct from
              expected.allocation_sequence
            or round(supplied."allocationAmount", 2) is distinct from
              expected.allocation_amount
            or round(supplied."floorPaidAmount" * 100)::bigint
              is distinct from
              expected.floor_cents
            or round(supplied."paidAmount" * 100)::bigint
              is distinct from
              expected.floor_cents
              + case when expected.residual_rank <= residual_cents
                then 1 else 0 end
            or supplied."residualCentAwarded" is distinct from
              (expected.residual_rank <= residual_cents)
            or supplied."remainderNumerator" is distinct from
              expected.remainder
       ) then
      return jsonb_build_object(
        'succeeded', false, 'errorCode', 'attribution_mismatch'
      );
    end if;
  elsif p_attributions is not null
    and p_attributions <> '[]'::jsonb then
    return jsonb_build_object(
      'succeeded', false, 'errorCode', 'attention_has_attributions'
    );
  end if;

  source_hash := encode(extensions.digest(convert_to(jsonb_build_object(
    'schemaVersion', 1,
    'retentionClaimId', claim_row.id,
    'sequence', next_sequence,
    'source', p_source,
    'paymentStatus', p_payment_status,
    'projectionApplied', p_projection_applied,
    'paidAmountExclTax', p_paid_amount_excl_tax,
    'invoiceTotalGross', p_invoice_total_gross,
    'amountPaidGross', p_amount_paid_gross,
    'amountDueGross', p_amount_due_gross,
    'amountCreditedGross', p_amount_credited_gross,
    'rawProviderStatus', p_raw_provider_status,
    'normalizedProviderStatus', p_normalized_provider_status,
    'fullyPaidAt', p_fully_paid_at,
    'providerUpdatedAt', p_provider_updated_at,
    'accountingDocumentId', p_accounting_document_id,
    'accountingSnapshotId', p_accounting_snapshot_id,
    'externalDocumentId', p_external_document_id,
    'expectedPreviousReconciliationId',
      p_expected_previous_reconciliation_id,
    'attentionCode', p_attention_code,
    'attentionMessage', p_attention_message,
    'actorUserId', p_actor_user_id,
    'correlationId', p_correlation_id,
    'attributions', coalesce(p_attributions, '[]'::jsonb)
  )::text, 'UTF8'), 'sha256'), 'hex');

  insert into public.retention_claim_payment_reconciliations(
    organization_id,
    project_id,
    retention_claim_id,
    reconciliation_sequence,
    source,
    payment_status,
    projection_applied,
    paid_amount_excl_tax,
    outstanding_amount_excl_tax,
    invoice_total_gross,
    amount_paid_gross,
    amount_due_gross,
    amount_credited_gross,
    raw_provider_status,
    normalized_provider_status,
    fully_paid_at,
    provider_updated_at,
    accounting_document_id,
    accounting_snapshot_id,
    external_document_id_snapshot,
    expected_previous_reconciliation_id,
    attention_code,
    attention_message,
    source_evidence_hash,
    actor_user_id,
    correlation_id
  )
  values(
    claim_row.organization_id,
    claim_row.project_id,
    claim_row.id,
    next_sequence,
    p_source,
    p_payment_status,
    p_projection_applied,
    case when p_projection_applied
      then round(p_paid_amount_excl_tax, 2) else null end,
    case when p_projection_applied
      then round(claim_row.subtotal_excl_tax - p_paid_amount_excl_tax, 2)
      else null end,
    p_invoice_total_gross,
    p_amount_paid_gross,
    p_amount_due_gross,
    p_amount_credited_gross,
    p_raw_provider_status,
    p_normalized_provider_status,
    p_fully_paid_at,
    p_provider_updated_at,
    p_accounting_document_id,
    p_accounting_snapshot_id,
    p_external_document_id,
    p_expected_previous_reconciliation_id,
    p_attention_code,
    p_attention_message,
    source_hash,
    p_actor_user_id,
    p_correlation_id
  )
  returning id into reconciliation_id;

  if p_projection_applied then
    insert into public.retention_claim_payment_attributions(
      organization_id,
      project_id,
      retention_claim_id,
      payment_reconciliation_id,
      retention_claim_allocation_id,
      originating_payment_claim_id,
      allocation_sequence,
      allocation_amount_snapshot,
      paid_amount,
      floor_paid_amount,
      residual_cent_awarded,
      remainder_numerator
    )
    select
      claim_row.organization_id,
      claim_row.project_id,
      claim_row.id,
      reconciliation_id,
      attribution."allocationId",
      attribution."originatingPaymentClaimId",
      attribution."sequence",
      round(attribution."allocationAmount", 2),
      round(attribution."paidAmount", 2),
      round(attribution."floorPaidAmount", 2),
      attribution."residualCentAwarded",
      attribution."remainderNumerator"
    from jsonb_to_recordset(p_attributions) as attribution(
      "allocationId" uuid,
      "originatingPaymentClaimId" uuid,
      "sequence" integer,
      "allocationAmount" numeric,
      "paidAmount" numeric,
      "floorPaidAmount" numeric,
      "residualCentAwarded" boolean,
      "remainderNumerator" numeric
    );
  end if;

  insert into public.retention_claim_payment_events(
    organization_id,
    project_id,
    retention_claim_id,
    payment_reconciliation_id,
    event_type,
    actor_user_id,
    correlation_id,
    metadata
  )
  values(
    claim_row.organization_id,
    claim_row.project_id,
    claim_row.id,
    reconciliation_id,
    case
      when not p_projection_applied then 'payment_reconciliation_attention'
      when p_source = 'manual' then 'manual_payment_reconciled'
      else 'xero_payment_reconciled'
    end,
    p_actor_user_id,
    p_correlation_id,
    jsonb_build_object(
      'source', p_source,
      'paymentStatus', p_payment_status,
      'projectionApplied', p_projection_applied,
      'paidAmountExclTax', p_paid_amount_excl_tax,
      'sourceEvidenceHash', source_hash
    )
  );

  if p_source = 'xero' then
    update public.organization_accounting_documents
    set
      raw_external_status = p_raw_provider_status,
      normalized_external_status = p_normalized_provider_status,
      amount_paid = round(p_amount_paid_gross, 2),
      amount_due = round(p_amount_due_gross, 2),
      amount_credited = round(p_amount_credited_gross, 2),
      fully_paid_at = p_fully_paid_at,
      provider_updated_at = coalesce(
        p_provider_updated_at,
        provider_updated_at
      ),
      last_status_synced_at = now(),
      last_status_sync_error = p_attention_message
    where id = document_row.id;
  end if;

  return jsonb_build_object(
    'succeeded', true,
    'errorCode', null,
    'reconciliationId', reconciliation_id,
    'reconciliationSequence', next_sequence,
    'sourceEvidenceHash', source_hash,
    'projectionApplied', p_projection_applied
  );
end;
$$;


ALTER FUNCTION "public"."record_retention_claim_payment_reconciliation"("p_retention_claim_id" "uuid", "p_source" "text", "p_actor_user_id" "uuid", "p_expected_previous_reconciliation_id" "uuid", "p_payment_status" "text", "p_projection_applied" boolean, "p_paid_amount_excl_tax" numeric, "p_invoice_total_gross" numeric, "p_amount_paid_gross" numeric, "p_amount_due_gross" numeric, "p_amount_credited_gross" numeric, "p_raw_provider_status" "text", "p_normalized_provider_status" "text", "p_fully_paid_at" timestamp with time zone, "p_provider_updated_at" timestamp with time zone, "p_accounting_document_id" "uuid", "p_accounting_snapshot_id" "uuid", "p_external_document_id" "text", "p_attention_code" "text", "p_attention_message" "text", "p_attributions" "jsonb", "p_correlation_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_retention_claim_xero_event"("p_accounting_document_id" "uuid", "p_event_type" "text", "p_actor_user_id" "uuid", "p_correlation_id" "text", "p_metadata" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  snapshot_row public.retention_claim_accounting_snapshots%rowtype;
  event_id uuid;
begin
  if auth.role() is distinct from 'service_role' then
    return jsonb_build_object(
      'succeeded', false, 'errorCode', 'permission_denied'
    );
  end if;

  if p_event_type not in (
    'xero_invoice_created',
    'xero_sync_failed',
    'xero_attachment_queued',
    'xero_attachment_attached',
    'xero_attachment_failed'
  ) or p_metadata is null or jsonb_typeof(p_metadata) <> 'object' then
    return jsonb_build_object(
      'succeeded', false, 'errorCode', 'invalid_event'
    );
  end if;

  select * into snapshot_row
  from public.retention_claim_accounting_snapshots
  where accounting_document_id = p_accounting_document_id;
  if not found then
    return jsonb_build_object(
      'succeeded', false, 'errorCode', 'accounting_document_not_found'
    );
  end if;

  insert into public.retention_claim_accounting_events(
    organization_id,
    project_id,
    retention_claim_id,
    accounting_document_id,
    accounting_snapshot_id,
    event_type,
    actor_user_id,
    correlation_id,
    metadata
  )
  values(
    snapshot_row.organization_id,
    snapshot_row.project_id,
    snapshot_row.retention_claim_id,
    snapshot_row.accounting_document_id,
    snapshot_row.id,
    p_event_type,
    p_actor_user_id,
    p_correlation_id,
    p_metadata
  )
  returning id into event_id;

  return jsonb_build_object(
    'succeeded', true, 'errorCode', null, 'eventId', event_id
  );
end;
$$;


ALTER FUNCTION "public"."record_retention_claim_xero_event"("p_accounting_document_id" "uuid", "p_event_type" "text", "p_actor_user_id" "uuid", "p_correlation_id" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_retention_reminder_delivery_result"("p_input" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_r public.retention_reminders%rowtype; v_success boolean; v_next_date date;
  v_new public.retention_reminders%rowtype;
begin
  if auth.role()<>'service_role' then
    return jsonb_build_object('succeeded',false,'errorCode','permission_denied');
  end if;
  select * into v_r from public.retention_reminders
  where id=(p_input->>'reminderId')::uuid for update;
  if not found then return jsonb_build_object('succeeded',false,'errorCode','reminder_not_found'); end if;
  if v_r.state<>'queued' or v_r.delivery_claim_token is distinct from (p_input->>'claimToken')::uuid then
    return jsonb_build_object('succeeded',false,'errorCode','delivery_not_confirmed');
  end if;
  v_success:=coalesce((p_input->>'delivered')::boolean,false);
  if v_success then
    update public.retention_reminders set state='sent',last_delivery_at=now(),
      attempt_count=attempt_count+1,next_delivery_at=null,failure_reason=null,
      delivery_claimed_at=null,delivery_claim_token=null,revision=revision+1
    where id=v_r.id returning * into v_r;
    perform private.record_retention_reminder_event(
      v_r.id,'delivery_succeeded','queued','sent','Reminder delivery confirmed.',
      p_input->>'claimToken',jsonb_build_object('adapter',p_input->>'adapter')
    );
    if v_r.recurrence_type<>'none' then
      v_next_date:=case v_r.recurrence_type
        when 'daily' then v_r.contractual_due_date+1
        when 'weekly' then v_r.contractual_due_date+7
        when 'monthly' then (v_r.contractual_due_date+interval '1 month')::date
        else v_r.contractual_due_date+v_r.recurrence_interval end;
      insert into public.retention_reminders(
        organization_id,project_id,schedule_id,retention_claim_id,reminder_type,
        contractual_due_date,organization_timezone,due_at,assigned_user_id,
        assigned_permission_key,use_project_owner_fallback,recurrence_type,
        recurrence_interval,escalation_after_days,escalation_level,state,
        next_delivery_at,maximum_attempts,occurrence_key,created_by
      ) values (
        v_r.organization_id,v_r.project_id,v_r.schedule_id,v_r.retention_claim_id,
        v_r.reminder_type,v_next_date,v_r.organization_timezone,
        (v_next_date::timestamp at time zone v_r.organization_timezone),
        v_r.assigned_user_id,v_r.assigned_permission_key,v_r.use_project_owner_fallback,
        v_r.recurrence_type,v_r.recurrence_interval,v_r.escalation_after_days,
        v_r.escalation_level,'scheduled',
        (v_next_date::timestamp at time zone v_r.organization_timezone),
        v_r.maximum_attempts,format('recurrence:%s:%s',v_r.id,v_next_date),v_r.created_by
      ) on conflict(schedule_id,occurrence_key) do nothing returning * into v_new;
      if v_new.id is not null then
        perform private.record_retention_reminder_event(
          v_new.id,'recurrence_generated',null,'scheduled','Recurring reminder generated.',
          p_input->>'claimToken',jsonb_build_object('sourceReminderId',v_r.id)
        );
      end if;
    end if;
  else
    update public.retention_reminders set state='failed',attempt_count=attempt_count+1,
      failure_reason=left(coalesce(p_input->>'failureReason','delivery_failed'),1000),
      next_delivery_at=case when attempt_count+1<maximum_attempts
        then now()+make_interval(mins=>least((attempt_count+1)*5,60)) else null end,
      delivery_claimed_at=null,delivery_claim_token=null,revision=revision+1
    where id=v_r.id returning * into v_r;
    perform private.record_retention_reminder_event(
      v_r.id,'delivery_failed','queued','failed',v_r.failure_reason,
      p_input->>'claimToken',jsonb_build_object('attemptCount',v_r.attempt_count)
    );
  end if;
  return jsonb_build_object('succeeded',true,'errorCode',null,'reminder',to_jsonb(v_r),
    'recurrence',case when v_new.id is null then null else to_jsonb(v_new) end);
end;
$$;


ALTER FUNCTION "public"."record_retention_reminder_delivery_result"("p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_retention_variance_corrective_evidence"("p_input" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v public.retention_variances%rowtype; ctx jsonb; old_state text;
  amount numeric; evidence jsonb;
begin
  select * into v from public.retention_variances where id=(p_input->>'varianceId')::uuid;
  if not found then return jsonb_build_object('succeeded',false,'errorCode','variance_not_found'); end if;
  ctx:=private.retention_phase5_context(v.project_id,'retention.variances.resolve',true);
  if not coalesce((ctx->>'succeeded')::boolean,false) then return ctx; end if;
  if nullif(trim(coalesce(p_input->>'externalReferenceId','')),'') is null
    or nullif(trim(coalesce(p_input->>'evidenceNote','')),'') is null then
    return jsonb_build_object('succeeded',false,'errorCode','corrective_evidence_required');
  end if;
  begin amount:=(p_input->>'correctiveAmountProposed')::numeric;
  exception when others then
    return jsonb_build_object('succeeded',false,'errorCode','invalid_corrective_amount');
  end;
  if amount is null or amount<=0 then
    return jsonb_build_object('succeeded',false,'errorCode','invalid_corrective_amount');
  end if;
  evidence:=jsonb_build_object(
    'externalReferenceId',trim(p_input->>'externalReferenceId'),
    'evidenceNote',trim(p_input->>'evidenceNote'),
    'evidenceTimestamp',coalesce((p_input->>'evidenceTimestamp')::timestamptz,now()),
    'approverUserId',p_input->>'approverUserId');
  select * into v from public.retention_variances where id=v.id for update;
  if v.revision<>(p_input->>'expectedRevision')::bigint then
    return jsonb_build_object('succeeded',false,'errorCode','concurrent_update',
      'currentRevision',v.revision);
  end if;
  if v.state in ('resolved','accepted_contractual_override') then
    return jsonb_build_object('succeeded',false,'errorCode','variance_already_resolved');
  end if;
  old_state:=v.state;
  perform set_config('app.retention_phase5_internal_write','true',true);
  update public.retention_variances set state='resolution_pending',is_blocking=true,
    resolution_type='manual_external_corrective_evidence',
    resolution_reason=trim(p_input->>'evidenceNote'),resolution_evidence=evidence,
    corrective_reference_id=trim(p_input->>'externalReferenceId'),
    corrective_amount_proposed=amount,evidence_recorded_at=now(),
    resolution_proposed_by=auth.uid(),last_correlation_id=p_input->>'correlationId',
    revision=revision+1,updated_at=now() where id=v.id returning * into v;
  perform set_config('app.retention_phase5_internal_write','',true);
  perform private.record_retention_variance_event(v.id,'resolution_pending',
    old_state,v.state,v.severity,v.severity,
    'External corrective evidence recorded; no financial availability restored.',
    p_input->>'correlationId',jsonb_build_object(
      'externalReferenceId',v.corrective_reference_id,
      'correctiveAmountProposed',v.corrective_amount_proposed));
  return jsonb_build_object('succeeded',true,'errorCode',null,
    'availabilityRestored',false,'variance',private.retention_variance_read_json(v.id));
end;
$$;


ALTER FUNCTION "public"."record_retention_variance_corrective_evidence"("p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_supplier_invoice_accounts_approval"("p_supplier_invoice_id" "uuid", "p_site_review_submission_id" "uuid", "p_expected_finance_hash" "text", "p_approval_note" "text" DEFAULT ''::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_organization_id uuid;
  v_approval_id uuid;
begin
  perform pg_advisory_xact_lock(hashtextextended(p_supplier_invoice_id::text, 1));
  select m.organization_id into v_organization_id
  from public.organization_members m where m.user_id = auth.uid()
  order by m.created_at limit 1;
  if v_organization_id is null
    or not public.has_org_permission(v_organization_id, 'supplier_invoices.accounts_approve') then
    raise exception 'You do not have permission to perform final Accounts approval.';
  end if;
  select a.id into v_approval_id
  from public.supplier_invoice_accounts_approvals a
  where a.organization_id = v_organization_id
    and a.supplier_invoice_id = p_supplier_invoice_id
    and a.finance_hash = p_expected_finance_hash
    and a.site_review_submission_id is not distinct from p_site_review_submission_id
    and a.status = 'approved'
  order by a.created_at desc limit 1;
  if v_approval_id is not null then return v_approval_id; end if;
  return private.record_supplier_invoice_accounts_approval_phase_ab_legacy(
    p_supplier_invoice_id, p_site_review_submission_id, p_expected_finance_hash, p_approval_note
  );
end;
$$;


