CREATE OR REPLACE FUNCTION "public"."refresh_retention_claim_eligibility_state"("p_retention_claim_id" "uuid", "p_expected_draft_revision" bigint, "p_correlation_id" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare c public.retention_claims%rowtype; ctx jsonb; origins uuid[];
begin
  if not private.retention_phase5_gate_enabled() then
    return public.refresh_retention_claim_eligibility_state_phase4_pre_variance(
      p_retention_claim_id,p_expected_draft_revision,p_correlation_id);
  end if;
  select * into c from public.retention_claims where id=p_retention_claim_id;
  if not found then return jsonb_build_object('succeeded',false,'errorCode','claim_not_found'); end if;
  ctx:=private.retention_phase5_context(c.project_id,'retention.claims.create',true);
  if not coalesce((ctx->>'succeeded')::boolean,false) then return ctx; end if;
  select coalesce(array_agg(a.originating_payment_claim_id order by a.originating_payment_claim_id),
    '{}'::uuid[]) into origins
  from public.retention_claim_allocations a where a.retention_claim_id=c.id;
  perform private.evaluate_retention_variance_project(c.project_id,p_correlation_id,origins);
  return public.refresh_retention_claim_eligibility_state_phase4_pre_variance(
    p_retention_claim_id,p_expected_draft_revision,p_correlation_id);
end;
$$;


ALTER FUNCTION "public"."refresh_retention_claim_eligibility_state"("p_retention_claim_id" "uuid", "p_expected_draft_revision" bigint, "p_correlation_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."refresh_retention_claim_eligibility_state_phase4_pre_variance"("p_retention_claim_id" "uuid", "p_expected_draft_revision" bigint, "p_correlation_id" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_c public.retention_claims%rowtype; v_context jsonb; v_state jsonb;
begin
  select * into v_c from public.retention_claims where id=p_retention_claim_id;
  if not found then return jsonb_build_object('succeeded',false,'errorCode','claim_not_found'); end if;
  v_context:=private.retention_phase4_context(v_c.project_id,'retention.claims.create',true);
  if not coalesce((v_context->>'succeeded')::boolean,false) then return v_context; end if;
  select * into v_c from public.retention_claims where id=v_c.id for update;
  if v_c.status<>'draft' then return jsonb_build_object('succeeded',false,'errorCode','claim_not_draft'); end if;
  if v_c.draft_revision<>p_expected_draft_revision then
    return jsonb_build_object('succeeded',false,'errorCode','concurrent_update',
      'currentDraftRevision',v_c.draft_revision);
  end if;
  v_state:=private.retention_eligibility_state(v_c.project_id);
  update public.retention_claims set
    last_eligibility_state_hash=v_state->>'eligibilityStateHash',
    last_position_state_hash=v_state->>'positionStateHash',
    draft_revision=draft_revision+1
  where id=v_c.id returning * into v_c;
  perform private.record_retention_claim_event(
    v_c.organization_id,v_c.project_id,v_c.id,'draft_updated','draft','draft',auth.uid(),
    'Retention eligibility state refreshed.',p_correlation_id,
    jsonb_build_object('eligibilityStateHash',v_c.last_eligibility_state_hash,
      'positionStateHash',v_c.last_position_state_hash,'draftRevision',v_c.draft_revision)
  );
  return jsonb_build_object('succeeded',true,'errorCode',null,'claim',
    private.retention_claim_header_json(v_c.id),'eligibility',v_state,
    'eligibilityStateHash',v_c.last_eligibility_state_hash);
end;
$$;


ALTER FUNCTION "public"."refresh_retention_claim_eligibility_state_phase4_pre_variance"("p_retention_claim_id" "uuid", "p_expected_draft_revision" bigint, "p_correlation_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."refresh_retention_legacy_reconciliation_case"("p_case_id" "uuid", "p_expected_revision" bigint, "p_correlation_id" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare c public.retention_legacy_reconciliation_cases%rowtype; ctx jsonb;
  source_state jsonb; source_count integer;
begin
  select * into c from public.retention_legacy_reconciliation_cases where id=p_case_id;
  if not found then return jsonb_build_object('succeeded',false,'errorCode','legacy_case_not_found'); end if;
  ctx:=private.retention_phase6_context(
    c.project_id,'retention.legacy.reconcile',true);
  if not coalesce((ctx->>'succeeded')::boolean,false) then return ctx; end if;
  select * into c from public.retention_legacy_reconciliation_cases
  where id=c.id for update;
  if c.status not in ('draft','rejected') then
    return jsonb_build_object('succeeded',false,'errorCode','legacy_case_not_editable');
  end if;
  if c.revision<>p_expected_revision then
    return jsonb_build_object('succeeded',false,'errorCode','concurrent_update',
      'currentRevision',c.revision);
  end if;
  source_state:=private.retention_legacy_source_state(c.project_id);
  if not coalesce((source_state->>'legacyReconciliationRequired')::boolean,false) then
    return jsonb_build_object('succeeded',false,'errorCode','legacy_reconciliation_not_required');
  end if;
  perform set_config('app.retention_phase6_internal_write','true',true);
  delete from public.retention_legacy_release_allocations where reconciliation_case_id=c.id;
  delete from public.retention_legacy_release_sources where reconciliation_case_id=c.id;
  update public.retention_legacy_reconciliation_cases set
    status='draft',position_state_hash=source_state->>'stateHash',
    source_fingerprint=source_state->>'sourceFingerprint',
    total_legacy_released=round((source_state->>'totalLegacyRetentionReleased')::numeric,2),
    total_allocated=0,
    source_count=jsonb_array_length(source_state->'legacyReleaseOrigins'),
    allocation_count=0,submitted_by=null,submitted_at=null,
    rejected_by=null,rejected_at=null,rejection_reason=null,
    revision=revision+1,updated_at=now()
  where id=c.id returning * into c;
  perform set_config('app.retention_phase6_internal_write','',true);
  source_count:=private.populate_retention_legacy_sources(c.id,source_state);
  perform private.record_retention_legacy_event(
    c.id,'case_refreshed',null,'draft',
    'Legacy reconciliation case refreshed; draft allocations were removed.',
    p_correlation_id,jsonb_build_object('sourceCount',source_count));
  return jsonb_build_object('succeeded',true,'errorCode',null,
    'case',private.retention_legacy_case_json(c.id));
end;
$$;


ALTER FUNCTION "public"."refresh_retention_legacy_reconciliation_case"("p_case_id" "uuid", "p_expected_revision" bigint, "p_correlation_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."regenerate_worksheet_material_binding_ids"("p_worksheet_data" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_result jsonb := coalesce(p_worksheet_data, '{}'::jsonb);
  v_cell record;
begin
  for v_cell in
    select cell.key
    from jsonb_each(coalesce(v_result->'cells', '{}'::jsonb)) cell
    where cell.value #> '{metadata,materialPricing}' is not null
  loop
    v_result := jsonb_set(
      v_result,
      array['cells', v_cell.key, 'metadata', 'materialPricing', 'bindingId'],
      to_jsonb(gen_random_uuid()::text),
      false
    );
  end loop;
  return v_result;
end;
$$;


