CREATE OR REPLACE FUNCTION "public"."release_purchase_order_commitment"("p_organization_id" "uuid", "p_purchase_order_id" "uuid", "p_expected_remaining_amount" numeric, "p_reason" "text", "p_note" "text" DEFAULT ''::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_po public.project_purchase_orders%rowtype;
  v_approved numeric;
  v_released numeric;
  v_po_value numeric;
  v_remaining numeric;
  v_release_id uuid;
begin
  if auth.uid() is null
    or not public.has_org_permission(p_organization_id, 'purchase_orders.write') then
    raise exception 'You do not have permission to release purchase order commitments.';
  end if;

  select * into v_po
  from public.project_purchase_orders
  where id = p_purchase_order_id
    and organization_id = p_organization_id
  for update;

  if not found then
    raise exception 'Purchase order not found.';
  end if;
  if v_po.status in ('Draft', 'Pending Approval', 'Cancelled') then
    raise exception 'Only active approved purchase orders can release remaining commitment.';
  end if;

  select coalesce(sum(s.amount), 0) into v_approved
  from public.supplier_invoice_commercial_line_snapshots s
  join public.supplier_invoice_commercial_approvals a on a.id = s.commercial_approval_id
  where s.purchase_order_id = v_po.id
    and a.status = 'approved';

  select coalesce(sum(released_amount), 0) into v_released
  from public.purchase_order_commitment_releases
  where purchase_order_id = v_po.id;

  select coalesce(sum(line.total), 0) into v_po_value
  from public.project_purchase_order_line_items line
  where line.purchase_order_id = v_po.id;

  v_remaining := round(v_po_value - v_approved - v_released, 2);
  if v_remaining <= 0 then
    raise exception 'This purchase order has no positive commitment remaining to release.';
  end if;
  if abs(v_remaining - p_expected_remaining_amount) > 0.01 then
    raise exception 'The remaining commitment changed. Refresh and confirm the release again.';
  end if;
  if char_length(trim(coalesce(p_reason, ''))) = 0 then
    raise exception 'Add a reason for releasing the remaining commitment.';
  end if;

  insert into public.purchase_order_commitment_releases (
    organization_id,
    purchase_order_id,
    released_amount,
    reason,
    note,
    released_by
  )
  values (
    p_organization_id,
    v_po.id,
    v_remaining,
    trim(p_reason),
    coalesce(p_note, ''),
    auth.uid()
  )
  returning id into v_release_id;

  insert into public.purchase_order_commitment_release_lines (
    organization_id,
    commitment_release_id,
    purchase_order_id,
    purchase_order_line_item_id,
    released_amount
  )
  select
    p_organization_id,
    v_release_id,
    v_po.id,
    po_line.id,
    greatest(
      0,
      round(
        po_line.total
        - coalesce(approved.approved_amount, 0)
        - coalesce(previous_release.released_amount, 0),
        2
      )
    )
  from public.project_purchase_order_line_items po_line
  left join lateral (
    select coalesce(sum(snapshot.amount), 0) as approved_amount
    from public.supplier_invoice_commercial_line_snapshots snapshot
    join public.supplier_invoice_commercial_approvals approval
      on approval.id = snapshot.commercial_approval_id
    where snapshot.purchase_order_line_item_id = po_line.id
      and approval.status = 'approved'
  ) approved on true
  left join lateral (
    select coalesce(sum(release_line.released_amount), 0) as released_amount
    from public.purchase_order_commitment_release_lines release_line
    where release_line.purchase_order_line_item_id = po_line.id
  ) previous_release on true
  where po_line.purchase_order_id = v_po.id;

  return v_release_id;
end;
$$;


ALTER FUNCTION "public"."release_purchase_order_commitment"("p_organization_id" "uuid", "p_purchase_order_id" "uuid", "p_expected_remaining_amount" numeric, "p_reason" "text", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."release_shared_concurrency_slot"("p_route_key" "text", "p_subject_key" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_active_count integer;
begin
  update public.request_concurrency_limits
  set active_count = greatest(active_count - 1, 0),
      updated_at = now()
  where route_key = p_route_key
    and subject_key = p_subject_key
  returning active_count into v_active_count;

  if v_active_count is null then
    return false;
  end if;

  if v_active_count = 0 then
    delete from public.request_concurrency_limits
    where route_key = p_route_key
      and subject_key = p_subject_key;
  end if;

  return true;
end;
$$;


ALTER FUNCTION "public"."release_shared_concurrency_slot"("p_route_key" "text", "p_subject_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."remap_supplier_product_material"("p_input" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_org uuid := (p_input->>'organization_id')::uuid;
  v_product public.organization_material_supplier_products%rowtype;
  v_new_material_id uuid := (p_input->>'new_material_id')::uuid;
  v_reason text := pg_catalog.btrim(p_input->>'reason');
begin
  perform public.materials_phase1f_require_writer(v_org);
  select * into v_product
  from public.organization_material_supplier_products
  where organization_id = v_org and id = (p_input->>'supplier_product_id')::uuid
  for update;
  if not found then
    perform public.materials_phase1f_error('supplier_product_not_found');
  end if;
  if not exists (select 1 from public.organization_materials where organization_id = v_org and id = v_new_material_id) then
    perform public.materials_phase1f_error('material_not_found');
  end if;
  if v_product.material_id = v_new_material_id then
    return pg_catalog.jsonb_build_object('supplier_product_id', v_product.id, 'no_op', true);
  end if;
  if v_reason is null or v_reason = '' then
    perform public.materials_phase1f_error('remap_reason_required');
  end if;
  if exists (
    select 1 from public.organization_material_supplier_prices
    where organization_id = v_org and supplier_product_id = v_product.id
  ) then
    perform public.materials_phase1f_error('remap_price_history_not_supported');
  end if;

  begin
    update public.organization_material_supplier_products
    set material_id = v_new_material_id, updated_by = auth.uid()
    where organization_id = v_org and id = v_product.id;
  exception when unique_violation then
    perform public.materials_phase1f_error('identity_conflict');
  end;

  insert into public.organization_material_supplier_product_assignments (
    organization_id, supplier_product_id, previous_material_id, new_material_id,
    reason, created_by, metadata
  ) values (
    v_org, v_product.id, v_product.material_id, v_new_material_id,
    v_reason, auth.uid(), pg_catalog.jsonb_build_object('operation', 'phase1f_remap')
  );

  return pg_catalog.jsonb_build_object(
    'supplier_product_id', v_product.id,
    'previous_material_id', v_product.material_id,
    'new_material_id', v_new_material_id,
    'no_op', false
  );
end;
$$;


ALTER FUNCTION "public"."remap_supplier_product_material"("p_input" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."remap_supplier_product_material"("p_input" "jsonb") IS 'Phase 1F controlled remap. Products with price history are intentionally rejected to preserve price snapshot evidence.';



CREATE OR REPLACE FUNCTION "public"."remove_project_member"("p_organization_id" "uuid", "p_project_id" "uuid", "p_organization_member_id" "uuid") RETURNS TABLE("id" "uuid", "organization_id" "uuid", "project_id" "uuid", "organization_member_id" "uuid", "created_by" "uuid", "is_active" boolean, "removed_at" timestamp with time zone, "removed_by" "uuid", "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  updated_row public.project_members%rowtype;
begin
  if auth.uid() is null then
    raise exception 'Authentication is required';
  end if;

  if not public.is_owner_of_organization(p_organization_id) then
    raise exception 'Not authorized to manage project members for this organization';
  end if;

  if not exists (
    select 1
    from public.organization_projects p
    where p.id = p_project_id
      and p.organization_id = p_organization_id
  ) then
    raise exception 'Project not found for organization';
  end if;

  if not exists (
    select 1
    from public.organization_members m
    where m.id = p_organization_member_id
      and m.organization_id = p_organization_id
  ) then
    raise exception 'Organization member not found for organization';
  end if;

  update public.project_members pm
  set
    is_active = false,
    removed_at = now(),
    removed_by = auth.uid()
  where pm.organization_id = p_organization_id
    and pm.project_id = p_project_id
    and pm.organization_member_id = p_organization_member_id
    and pm.is_active = true
  returning pm.* into updated_row;

  if updated_row.id is null then
    raise exception 'Active project membership not found';
  end if;

  return query
  select
    updated_row.id,
    updated_row.organization_id,
    updated_row.project_id,
    updated_row.organization_member_id,
    updated_row.created_by,
    updated_row.is_active,
    updated_row.removed_at,
    updated_row.removed_by,
    updated_row.created_at,
    updated_row.updated_at;
end;
$$;


ALTER FUNCTION "public"."remove_project_member"("p_organization_id" "uuid", "p_project_id" "uuid", "p_organization_member_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."remove_project_qa_evidence_v1"("p_evidence_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare evidence_row public.project_qa_response_evidence%rowtype; run_status text;
begin
  select * into evidence_row from public.project_qa_response_evidence where id=p_evidence_id for update;
  if not found or evidence_row.uploaded_by<>auth.uid() or not public.can_access_qa_project(evidence_row.organization_id,evidence_row.project_id,'qa.inspect') then raise exception 'QA evidence not found or access denied' using errcode='42501'; end if;
  select status into run_status from public.project_qa_runs where id=evidence_row.project_qa_run_id for update;
  if run_status<>'in_progress' then raise exception 'Completed or cancelled QA evidence is immutable' using errcode='TS409'; end if;
  insert into public.project_qa_evidence_cleanup_jobs(storage_path,reason) values(evidence_row.storage_path,'removed') on conflict(storage_path) do nothing;
  delete from public.project_qa_response_evidence where id=evidence_row.id;
  update public.project_qa_runs set lock_version=lock_version+1 where id=evidence_row.project_qa_run_id;
  return evidence_row.storage_path;
end; $$;


ALTER FUNCTION "public"."remove_project_qa_evidence_v1"("p_evidence_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."remove_purchase_order_assignment"("p_organization_id" "uuid", "p_project_id" "uuid", "p_purchase_order_id" "uuid", "p_organization_member_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if auth.uid() is null then
    raise exception 'Authentication is required';
  end if;

  if not public.has_org_permission(p_organization_id, 'purchase_orders.write') then
    raise exception 'You do not have permission to manage purchase order assignments';
  end if;

  delete from public.project_purchase_order_assignments a
  where a.organization_id = p_organization_id
    and a.project_id = p_project_id
    and a.purchase_order_id = p_purchase_order_id
    and a.organization_member_id = p_organization_member_id;
end;
$$;


