CREATE OR REPLACE FUNCTION "public"."remove_retention_claim_allocation"("p_allocation_id" "uuid", "p_expected_draft_revision" bigint, "p_correlation_id" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_allocation public.retention_claim_allocations%rowtype;
  v_claim public.retention_claims%rowtype;
  v_context jsonb;
begin
  select * into v_allocation
  from public.retention_claim_allocations allocation
  where allocation.id = p_allocation_id;
  if not found then
    return jsonb_build_object('succeeded', false, 'errorCode', 'claim_not_found');
  end if;

  select * into v_claim
  from public.retention_claims claim
  where claim.id = v_allocation.retention_claim_id;
  v_context := private.retention_claim_operation_context(
    v_claim.project_id,
    'retention.claims.create',
    true
  );
  if not coalesce((v_context ->> 'succeeded')::boolean, false) then
    return v_context;
  end if;

  select * into v_claim
  from public.retention_claims claim
  where claim.id = v_allocation.retention_claim_id
    and claim.organization_id = (v_context ->> 'organizationId')::uuid
  for update;
  if not found then
    return jsonb_build_object('succeeded', false, 'errorCode', 'claim_not_found');
  end if;
  if v_claim.status <> 'draft' then
    return jsonb_build_object('succeeded', false, 'errorCode', 'claim_not_draft');
  end if;
  if v_claim.draft_revision <> p_expected_draft_revision then
    return jsonb_build_object(
      'succeeded', false,
      'errorCode', 'concurrent_update',
      'currentDraftRevision', v_claim.draft_revision
    );
  end if;

  delete from public.retention_claim_allocations allocation
  where allocation.id = v_allocation.id;

  update public.retention_claims claim
  set draft_revision = claim.draft_revision + 1
  where claim.id = v_claim.id
  returning * into v_claim;

  perform private.record_retention_claim_event(
    v_claim.organization_id, v_claim.project_id, v_claim.id,
    'allocation_removed', 'draft', 'draft', auth.uid(),
    'Retention Claim allocation removed.', p_correlation_id,
    jsonb_build_object(
      'allocationId', v_allocation.id,
      'originatingPaymentClaimId', v_allocation.originating_payment_claim_id,
      'allocationAmount', v_allocation.allocation_amount,
      'draftRevision', v_claim.draft_revision
    )
  );

  return jsonb_build_object(
    'succeeded', true,
    'errorCode', null,
    'claim', private.retention_claim_header_json(v_claim.id)
  );
end;
$$;


ALTER FUNCTION "public"."remove_retention_claim_allocation"("p_allocation_id" "uuid", "p_expected_draft_revision" bigint, "p_correlation_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."remove_retention_legacy_release_allocation"("p_allocation_id" "uuid", "p_expected_revision" bigint, "p_correlation_id" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare a public.retention_legacy_release_allocations%rowtype;
  c public.retention_legacy_reconciliation_cases%rowtype; ctx jsonb;
begin
  select * into a from public.retention_legacy_release_allocations where id=p_allocation_id;
  if not found then return jsonb_build_object('succeeded',false,'errorCode','legacy_allocation_not_found'); end if;
  select * into c from public.retention_legacy_reconciliation_cases where id=a.reconciliation_case_id;
  ctx:=private.retention_phase6_context(c.project_id,'retention.legacy.reconcile',true);
  if not coalesce((ctx->>'succeeded')::boolean,false) then return ctx; end if;
  select * into c from public.retention_legacy_reconciliation_cases where id=c.id for update;
  if c.status not in ('draft','rejected') then
    return jsonb_build_object('succeeded',false,'errorCode','legacy_case_not_editable');
  end if;
  if c.revision<>p_expected_revision then
    return jsonb_build_object('succeeded',false,'errorCode','concurrent_update',
      'currentRevision',c.revision);
  end if;
  perform set_config('app.retention_phase6_internal_write','true',true);
  delete from public.retention_legacy_release_allocations where id=a.id;
  update public.retention_legacy_reconciliation_cases set
    revision=revision+1,updated_at=now() where id=c.id returning * into c;
  perform set_config('app.retention_phase6_internal_write','',true);
  perform private.refresh_retention_legacy_case_totals(c.id);
  perform private.record_retention_legacy_event(
    c.id,'allocation_removed',c.status,c.status,
    'Legacy release allocation removed.',p_correlation_id,
    jsonb_build_object('allocationId',a.id));
  return jsonb_build_object('succeeded',true,'errorCode',null,
    'case',private.retention_legacy_case_json(c.id));
end;
$$;


ALTER FUNCTION "public"."remove_retention_legacy_release_allocation"("p_allocation_id" "uuid", "p_expected_revision" bigint, "p_correlation_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."remove_retention_schedule_origin"("p_input" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_o public.project_retention_schedule_origins%rowtype; v_s public.project_retention_release_schedules%rowtype; v_context jsonb;
begin
  select * into v_o from public.project_retention_schedule_origins where id=(p_input->>'originId')::uuid;
  if not found then return jsonb_build_object('succeeded',false,'errorCode','origin_not_found'); end if;
  select * into v_s from public.project_retention_release_schedules where id=v_o.schedule_id;
  v_context:=private.retention_phase4_context(v_s.project_id,'retention.schedules.manage',true);
  if not coalesce((v_context->>'succeeded')::boolean,false) then return v_context; end if;
  select * into v_s from public.project_retention_release_schedules where id=v_s.id for update;
  if v_s.status not in ('draft','scheduled','awaiting_confirmation') then
    return jsonb_build_object('succeeded',false,'errorCode','schedule_immutable');
  end if;
  if v_s.revision<>(p_input->>'expectedRevision')::bigint then
    return jsonb_build_object('succeeded',false,'errorCode','concurrent_update','currentRevision',v_s.revision);
  end if;
  delete from public.project_retention_schedule_origins where id=v_o.id;
  update public.project_retention_release_schedules set revision=revision+1 where id=v_s.id returning * into v_s;
  perform private.record_retention_schedule_event(
    v_s.id,'origin_removed',v_s.status,v_s.status,'Schedule origin removed.',
    p_input->>'correlationId',jsonb_build_object('originId',v_o.originating_payment_claim_id)
  );
  return jsonb_build_object('succeeded',true,'errorCode',null,'schedule',to_jsonb(v_s));
end;
$$;


ALTER FUNCTION "public"."remove_retention_schedule_origin"("p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."remove_task_link"("p_task_link_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  actor_user_id uuid := auth.uid();
  link_row public.task_links%rowtype;
  task_row public.project_job_todos%rowtype;
begin
  select *
  into link_row
  from public.task_links l
  where l.id = p_task_link_id;

  if link_row.id is null then
    raise exception 'Task link not found';
  end if;

  task_row := public._task_assert_task_access(link_row.task_id);

  delete from public.task_links l
  where l.id = link_row.id;

  perform public._write_task_activity(task_row.organization_id, task_row.id, task_row.project_id, actor_user_id, 'source_unlinked', 'task_links', to_jsonb(link_row.linked_id), null, jsonb_build_object('taskLinkId', link_row.id, 'linkedType', link_row.linked_type));

  return jsonb_build_object('id', link_row.id, 'removed', true);
end;
$$;


ALTER FUNCTION "public"."remove_task_link"("p_task_link_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rename_document_node"("p_node_id" "uuid", "p_display_name" "text") RETURNS "public"."document_nodes"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  actor_user_id uuid := auth.uid();
  node_row public.document_nodes%rowtype;
  old_name text;
begin
  select *
  into node_row
  from public.document_nodes node
  where node.id = p_node_id;

  if not found then
    raise exception 'Document node not found.'
      using errcode = 'P0002';
  end if;

  perform public.assert_document_workspace_permission(
    node_row.workspace_id,
    'files.write'
  );
  perform pg_advisory_xact_lock(
    hashtextextended('document-workspace:' || node_row.workspace_id::text, 0)
  );

  select *
  into node_row
  from public.document_nodes node
  where node.id = p_node_id
    and node.deleted_at is null
  for update;

  if not found then
    raise exception 'Active document node not found.'
      using errcode = 'P0002';
  end if;

  old_name := node_row.display_name;
  if old_name = btrim(p_display_name) then
    return node_row;
  end if;

  update public.document_nodes node
  set
    display_name = btrim(p_display_name),
    updated_by = actor_user_id
  where node.id = node_row.id
  returning * into node_row;

  insert into public.document_activity_events (
    organization_id,
    workspace_id,
    node_id,
    actor_user_id,
    event_type,
    metadata
  )
  values (
    node_row.organization_id,
    node_row.workspace_id,
    node_row.id,
    actor_user_id,
    'renamed',
    jsonb_build_object(
      'oldDisplayName', old_name,
      'newDisplayName', node_row.display_name
    )
  );

  return node_row;
end;
$$;


ALTER FUNCTION "public"."rename_document_node"("p_node_id" "uuid", "p_display_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rename_opportunity_pricing_workbook"("p_organization_id" "uuid", "p_opportunity_id" "uuid", "p_workbook_id" "uuid", "p_user_id" "uuid", "p_next_name" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  v_workbook public.opportunity_pricing_worksheets%rowtype;
  v_sheet public.opportunity_pricing_workbook_sheets%rowtype;
  v_next_name text;
  v_worksheet_data jsonb;
begin
  select *
  into v_workbook
  from public.opportunity_pricing_worksheets
  where id = p_workbook_id
    and organization_id = p_organization_id
    and opportunity_id = p_opportunity_id
    and archived_at is null;

  if not found then
    raise exception 'Pricing worksheet not found.';
  end if;

  v_next_name := public._normalize_opportunity_pricing_workbook_name(
    p_next_name,
    coalesce(nullif(trim(v_workbook.name), ''), 'Pricing Worksheet')
  );
  v_worksheet_data := public._sync_opportunity_pricing_workbook_sheet_name(v_workbook.worksheet_data, v_next_name);

  return public.save_opportunity_pricing_workbook_active_sheet(
    p_organization_id := p_organization_id,
    p_opportunity_id := p_opportunity_id,
    p_user_id := p_user_id,
    p_workbook_id := p_workbook_id,
    p_sheet_id := (
      select sheet.id
      from public.opportunity_pricing_workbook_sheets sheet
      where sheet.workbook_id = p_workbook_id
        and sheet.organization_id = p_organization_id
        and sheet.opportunity_id = p_opportunity_id
      order by sheet.is_default desc, sheet.sheet_order asc, sheet.created_at asc
      limit 1
    ),
    p_name := v_next_name,
    p_trade_package := v_workbook.trade_package,
    p_worksheet_data := v_worksheet_data,
    p_pricing_summary := v_workbook.pricing_summary,
    p_extracted_pricing_data := v_workbook.extracted_pricing_data,
    p_version := v_workbook.version
  );
end;
$$;


ALTER FUNCTION "public"."rename_opportunity_pricing_workbook"("p_organization_id" "uuid", "p_opportunity_id" "uuid", "p_workbook_id" "uuid", "p_user_id" "uuid", "p_next_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rename_pricing_workbook_v1"("p_organization_id" "uuid", "p_opportunity_id" "uuid", "p_project_id" "uuid", "p_workbook_id" "uuid", "p_user_id" "uuid", "p_next_name" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  workbook public.opportunity_pricing_worksheets%rowtype;
  primary_sheet public.opportunity_pricing_workbook_sheets%rowtype;
  next_name text;
  next_worksheet jsonb;
begin
  if auth.uid() is null or p_user_id is distinct from auth.uid() then
    raise exception 'Pricing worksheet actor mismatch.' using errcode = '42501';
  end if;

  select * into workbook from public.opportunity_pricing_worksheets candidate
  where candidate.id = p_workbook_id
    and candidate.organization_id = p_organization_id
    and candidate.opportunity_id = p_opportunity_id
    and candidate.archived_at is null
    and candidate.variation_id is null
    and (
      (p_project_id is null and candidate.project_id is null and candidate.quote_id is null)
      or (p_project_id is not null and candidate.project_id = p_project_id
        and (candidate.quote_id is null or candidate.clone_kind = 'project_working'))
    );

  if not found or not public.can_write_pricing_workbook_owner(
    workbook.organization_id, workbook.opportunity_id, workbook.project_id,
    workbook.quote_id, workbook.variation_id
  ) then
    raise exception 'Pricing worksheet not found or not writable.' using errcode = '42501';
  end if;

  next_name := public._normalize_opportunity_pricing_workbook_name(
    p_next_name, coalesce(nullif(trim(workbook.name), ''), 'Pricing Worksheet')
  );
  next_worksheet := public._sync_opportunity_pricing_workbook_sheet_name(workbook.worksheet_data, next_name);

  update public.opportunity_pricing_worksheets
  set name = next_name, worksheet_data = next_worksheet, updated_by = p_user_id
  where id = workbook.id returning * into workbook;

  select * into primary_sheet from public.opportunity_pricing_workbook_sheets sheet
  where sheet.workbook_id = workbook.id and sheet.organization_id = p_organization_id
  order by sheet.is_default desc, sheet.sheet_order, sheet.created_at limit 1;

  if found then
    update public.opportunity_pricing_workbook_sheets
    set name = next_name,
        worksheet_data = public._sync_opportunity_pricing_workbook_sheet_name(primary_sheet.worksheet_data, next_name),
        updated_by = p_user_id
    where id = primary_sheet.id returning * into primary_sheet;
  end if;

  return jsonb_build_object(
    'workbook', to_jsonb(workbook),
    'sheets', (select coalesce(jsonb_agg(to_jsonb(sheet) order by sheet.sheet_order, sheet.created_at), '[]'::jsonb)
      from public.opportunity_pricing_workbook_sheets sheet where sheet.workbook_id = workbook.id)
  );
end;
$$;


ALTER FUNCTION "public"."rename_pricing_workbook_v1"("p_organization_id" "uuid", "p_opportunity_id" "uuid", "p_project_id" "uuid", "p_workbook_id" "uuid", "p_user_id" "uuid", "p_next_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reopen_retention_variance"("p_input" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v public.retention_variances%rowtype; ctx jsonb; s jsonb; result jsonb;
begin
  select * into v from public.retention_variances where id=(p_input->>'varianceId')::uuid;
  if not found then return jsonb_build_object('succeeded',false,'errorCode','variance_not_found'); end if;
  ctx:=private.retention_phase5_context(v.project_id,'retention.variances.override',true);
  if not coalesce((ctx->>'succeeded')::boolean,false) then
    return jsonb_build_object('succeeded',false,'errorCode','override_permission_required');
  end if;
  if nullif(trim(coalesce(p_input->>'reason','')),'') is null then
    return jsonb_build_object('succeeded',false,'errorCode','override_reason_required');
  end if;
  if v.state not in ('resolved','accepted_contractual_override') then
    return jsonb_build_object('succeeded',false,'errorCode','invalid_variance_transition');
  end if;
  s:=private.retention_variance_snapshot(v.project_id,v.originating_payment_claim_id);
  if not coalesce((s->>'hasVariance')::boolean,false) then
    return jsonb_build_object('succeeded',false,'errorCode','variance_not_resolvable');
  end if;
  perform set_config('app.retention_phase5_internal_write','true',true);
  update public.retention_variances set override_basis_hash=null where id=v.id;
  perform set_config('app.retention_phase5_internal_write','',true);
  result:=private.evaluate_retention_variance_origin(
    v.project_id,v.originating_payment_claim_id,p_input->>'correlationId');
  perform private.record_retention_variance_event(v.id,'variance_reopened',
    v.state,result->>'state',v.severity,result->>'severity',
    trim(p_input->>'reason'),p_input->>'correlationId','{}'::jsonb);
  return result;
end;
$$;


