CREATE OR REPLACE FUNCTION "public"."reorder_client_notes"("p_client_id" "uuid", "p_ordered_ids" "uuid"[]) RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
begin
  if p_ordered_ids is null or cardinality(p_ordered_ids) = 0 then
    raise exception 'Ordered note ids are required.';
  end if;

  if not exists (
    select 1
    from public.organization_clients as c
    where c.id = p_client_id
  ) then
    raise exception 'Client not found';
  end if;

  if not exists (
    select 1
    from public.organization_clients as c
    where c.id = p_client_id
      and public.has_org_permission(c.organization_id, 'leads.clients.write')
  ) then
    raise exception 'You do not have permission to reorder client notes.';
  end if;

  if exists (
    select 1
    from unnest(p_ordered_ids) as ordered_ids(note_id)
    group by note_id
    having count(*) > 1
  ) then
    raise exception 'Ordered note ids must be unique.';
  end if;

  if exists (
    select 1
    from public.client_notes
    where client_id = p_client_id
      and not (id = any (p_ordered_ids))
  ) then
    raise exception 'Ordered note ids must include every saved note for the client.';
  end if;

  if exists (
    select 1
    from unnest(p_ordered_ids) as ordered_ids(note_id)
    where not exists (
      select 1
      from public.client_notes
      where client_id = p_client_id
        and id = note_id
    )
  ) then
    raise exception 'Ordered note ids must belong to the client.';
  end if;

  with ordered_notes as (
    select
      note_id as id,
      ordinality - 1 as next_sort_order
    from unnest(p_ordered_ids) with ordinality as ordered(note_id, ordinality)
  )
  update public.client_notes as client_notes
  set sort_order = ordered_notes.next_sort_order
  from ordered_notes
  where client_notes.id = ordered_notes.id
    and client_notes.client_id = p_client_id;
end;
$$;


ALTER FUNCTION "public"."reorder_client_notes"("p_client_id" "uuid", "p_ordered_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reorder_retention_claim_allocations"("p_retention_claim_id" "uuid", "p_expected_draft_revision" bigint, "p_allocation_ids" "uuid"[], "p_correlation_id" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_claim public.retention_claims%rowtype;
  v_context jsonb;
  v_existing_count integer;
begin
  select * into v_claim
  from public.retention_claims claim
  where claim.id = p_retention_claim_id;
  if not found then
    return jsonb_build_object('succeeded', false, 'errorCode', 'claim_not_found');
  end if;

  v_context := private.retention_claim_operation_context(
    v_claim.project_id,
    'retention.claims.create',
    true
  );
  if not coalesce((v_context ->> 'succeeded')::boolean, false) then
    return v_context;
  end if;

  select * into v_claim
  from public.retention_claims claim
  where claim.id = p_retention_claim_id
    and claim.organization_id = (v_context ->> 'organizationId')::uuid
  for update;
  if not found then
    return jsonb_build_object('succeeded', false, 'errorCode', 'claim_not_found');
  end if;
  if v_claim.status <> 'draft' then
    return jsonb_build_object('succeeded', false, 'errorCode', 'claim_not_draft');
  end if;
  if v_claim.draft_revision <> p_expected_draft_revision then
    return jsonb_build_object(
      'succeeded', false,
      'errorCode', 'concurrent_update',
      'currentDraftRevision', v_claim.draft_revision
    );
  end if;

  select count(*)::integer into v_existing_count
  from public.retention_claim_allocations allocation
  where allocation.retention_claim_id = v_claim.id;

  if coalesce(cardinality(p_allocation_ids), 0) <> v_existing_count
    or (
      select count(distinct allocation_id)
      from unnest(coalesce(p_allocation_ids, '{}'::uuid[])) allocation_id
    ) <> v_existing_count
    or exists (
      select 1
      from unnest(coalesce(p_allocation_ids, '{}'::uuid[])) allocation_id
      where not exists (
        select 1
        from public.retention_claim_allocations allocation
        where allocation.id = allocation_id
          and allocation.retention_claim_id = v_claim.id
      )
    ) then
    return jsonb_build_object(
      'succeeded', false,
      'errorCode', 'invalid_allocation_order'
    );
  end if;

  set constraints retention_claim_allocations_sequence_unique deferred;

  update public.retention_claim_allocations allocation
  set allocation_sequence = array_position(p_allocation_ids, allocation.id)
  where allocation.retention_claim_id = v_claim.id;

  update public.retention_claims claim
  set draft_revision = claim.draft_revision + 1
  where claim.id = v_claim.id
  returning * into v_claim;

  perform private.record_retention_claim_event(
    v_claim.organization_id, v_claim.project_id, v_claim.id,
    'draft_updated', 'draft', 'draft', auth.uid(),
    'Retention Claim allocations reordered.', p_correlation_id,
    jsonb_build_object(
      'operation', 'reorder_allocations',
      'draftRevision', v_claim.draft_revision,
      'allocationCount', v_existing_count
    )
  );

  return jsonb_build_object(
    'succeeded', true,
    'errorCode', null,
    'claim', private.retention_claim_header_json(v_claim.id),
    'allocations', private.retention_claim_current_origin_details(v_claim.id)
  );
end;
$$;


ALTER FUNCTION "public"."reorder_retention_claim_allocations"("p_retention_claim_id" "uuid", "p_expected_draft_revision" bigint, "p_allocation_ids" "uuid"[], "p_correlation_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reorder_retention_schedule_origins"("p_input" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_s public.project_retention_release_schedules%rowtype; v_context jsonb; v_ids uuid[]; v_count integer;
begin
  select * into v_s from public.project_retention_release_schedules where id=(p_input->>'scheduleId')::uuid;
  if not found then return jsonb_build_object('succeeded',false,'errorCode','schedule_not_found'); end if;
  v_context:=private.retention_phase4_context(v_s.project_id,'retention.schedules.manage',true);
  if not coalesce((v_context->>'succeeded')::boolean,false) then return v_context; end if;
  select * into v_s from public.project_retention_release_schedules where id=v_s.id for update;
  if v_s.status not in ('draft','scheduled','awaiting_confirmation') then
    return jsonb_build_object('succeeded',false,'errorCode','schedule_immutable');
  end if;
  if v_s.revision<>(p_input->>'expectedRevision')::bigint then
    return jsonb_build_object('succeeded',false,'errorCode','concurrent_update','currentRevision',v_s.revision);
  end if;
  select array_agg(value::uuid order by ordinality) into v_ids
  from jsonb_array_elements_text(coalesce(p_input->'originIds','[]'::jsonb)) with ordinality;
  select count(*) into v_count from public.project_retention_schedule_origins where schedule_id=v_s.id;
  if cardinality(coalesce(v_ids,'{}'::uuid[]))<>v_count
    or (select count(distinct x) from unnest(coalesce(v_ids,'{}'::uuid[])) x)<>v_count
    or exists(select 1 from unnest(coalesce(v_ids,'{}'::uuid[])) x
      where not exists(select 1 from public.project_retention_schedule_origins o where o.id=x and o.schedule_id=v_s.id))
  then return jsonb_build_object('succeeded',false,'errorCode','invalid_schedule_scope'); end if;
  set constraints project_retention_schedule_origins_sequence_unique deferred;
  update public.project_retention_schedule_origins set origin_sequence=array_position(v_ids,id) where schedule_id=v_s.id;
  update public.project_retention_release_schedules set revision=revision+1 where id=v_s.id returning * into v_s;
  perform private.record_retention_schedule_event(
    v_s.id,'origins_reordered',v_s.status,v_s.status,'Schedule origins reordered.',
    p_input->>'correlationId',jsonb_build_object('originCount',v_count)
  );
  return jsonb_build_object('succeeded',true,'errorCode',null,'schedule',to_jsonb(v_s),
    'origins',private.retention_schedule_origins_json(v_s.id));
end;
$$;


ALTER FUNCTION "public"."reorder_retention_schedule_origins"("p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."repair_project_quote_opportunity_lineage"("p_project_quote_id" "uuid") RETURNS TABLE("repaired_line_count" integer, "mirrored_cost_item_count" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  project_quote_row public.project_quotes%rowtype;
  missing_line_count integer := 0;
  unresolved_line_count integer := 0;
  duplicate_source_match_count integer := 0;
  cost_item_revision_key text;
begin
  if auth.uid() is null then
    if current_user <> 'postgres' then
      raise exception 'Authentication is required';
    end if;
  end if;

  select *
  into project_quote_row
  from public.project_quotes pq
  where pq.id = p_project_quote_id;

  if not found then
    raise exception 'Project quote not found';
  end if;

  if auth.uid() is not null and not public.has_org_permission(project_quote_row.organization_id, 'quotes.write') then
    raise exception 'Not authorized for this organization';
  end if;

  if project_quote_row.source_opportunity_quote_id is null then
    raise exception 'Project quote does not have a source opportunity quote';
  end if;

  select count(*)
  into missing_line_count
  from public.project_quote_line_items pqli
  where pqli.organization_id = project_quote_row.organization_id
    and pqli.project_id = project_quote_row.project_id
    and pqli.quote_id = project_quote_row.id
    and pqli.source_opportunity_quote_line_item_id is null;

  if missing_line_count = 0 then
    repaired_line_count := 0;
    cost_item_revision_key := public.begin_cost_item_revision('project_quote', project_quote_row.id);
    perform public.supersede_previous_cost_items('project_quote', project_quote_row.id, cost_item_revision_key);
    mirrored_cost_item_count := public.upsert_cost_items_for_document('project_quote', project_quote_row.id, cost_item_revision_key);
    return next;
    return;
  end if;

  create temporary table tmp_project_quote_lineage_matches (
    project_line_id uuid primary key,
    opportunity_line_id uuid not null
  ) on commit drop;

  with target_lines as (
    select
      pqli.id,
      pqli.sort_order,
      pqli.section,
      pqli.description,
      pqli.quantity,
      pqli.unit,
      pqli.rate,
      pqli.total,
      pqli.is_optional
    from public.project_quote_line_items pqli
    where pqli.organization_id = project_quote_row.organization_id
      and pqli.project_id = project_quote_row.project_id
      and pqli.quote_id = project_quote_row.id
      and pqli.source_opportunity_quote_line_item_id is null
  ),
  available_source_lines as (
    select
      oqli.id,
      oqli.sort_order,
      oqli.section,
      oqli.description,
      oqli.quantity,
      oqli.unit,
      oqli.rate,
      oqli.total,
      oqli.is_optional
    from public.opportunity_quote_line_items oqli
    where oqli.organization_id = project_quote_row.organization_id
      and oqli.quote_id = project_quote_row.source_opportunity_quote_id
      and not exists (
        select 1
        from public.project_quote_line_items existing
        where existing.quote_id = project_quote_row.id
          and existing.source_opportunity_quote_line_item_id = oqli.id
      )
  ),
  exact_candidates as (
    select
      tl.id as project_line_id,
      asl.id as opportunity_line_id
    from target_lines tl
    join available_source_lines asl
      on asl.sort_order = tl.sort_order
     and asl.section = tl.section
     and asl.is_optional = tl.is_optional
     and round(asl.quantity::numeric, 2) = round(tl.quantity::numeric, 2)
     and lower(regexp_replace(btrim(asl.unit), '\s+', ' ', 'g')) = lower(regexp_replace(btrim(tl.unit), '\s+', ' ', 'g'))
     and round(asl.rate::numeric, 2) = round(tl.rate::numeric, 2)
     and round(coalesce(asl.total, round(asl.quantity * asl.rate, 2))::numeric, 2)
         = round(coalesce(tl.total, round(tl.quantity * tl.rate, 2))::numeric, 2)
     and lower(regexp_replace(btrim(asl.description), '\s+', ' ', 'g')) = lower(regexp_replace(btrim(tl.description), '\s+', ' ', 'g'))
  ),
  exact_candidate_counts as (
    select
      ec.project_line_id,
      count(*) as candidate_count,
      (array_agg(ec.opportunity_line_id order by ec.opportunity_line_id))[1] as chosen_opportunity_line_id
    from exact_candidates ec
    group by ec.project_line_id
  ),
  broad_candidates as (
    select
      tl.id as project_line_id,
      asl.id as opportunity_line_id
    from target_lines tl
    join available_source_lines asl
      on asl.sort_order = tl.sort_order
     and asl.section = tl.section
     and asl.is_optional = tl.is_optional
     and round(asl.quantity::numeric, 2) = round(tl.quantity::numeric, 2)
     and lower(regexp_replace(btrim(asl.unit), '\s+', ' ', 'g')) = lower(regexp_replace(btrim(tl.unit), '\s+', ' ', 'g'))
     and round(asl.rate::numeric, 2) = round(tl.rate::numeric, 2)
     and round(coalesce(asl.total, round(asl.quantity * asl.rate, 2))::numeric, 2)
         = round(coalesce(tl.total, round(tl.quantity * tl.rate, 2))::numeric, 2)
    where not exists (
      select 1
      from exact_candidate_counts ecc
      where ecc.project_line_id = tl.id
        and ecc.candidate_count = 1
    )
  ),
  broad_candidate_counts as (
    select
      bc.project_line_id,
      count(*) as candidate_count,
      (array_agg(bc.opportunity_line_id order by bc.opportunity_line_id))[1] as chosen_opportunity_line_id
    from broad_candidates bc
    group by bc.project_line_id
  ),
  chosen_matches as (
    select
      tl.id as project_line_id,
      case
        when ecc.candidate_count = 1 then ecc.chosen_opportunity_line_id
        when coalesce(ecc.candidate_count, 0) = 0 and bcc.candidate_count = 1 then bcc.chosen_opportunity_line_id
        else null
      end as opportunity_line_id
    from target_lines tl
    left join exact_candidate_counts ecc
      on ecc.project_line_id = tl.id
    left join broad_candidate_counts bcc
      on bcc.project_line_id = tl.id
  )
  insert into tmp_project_quote_lineage_matches (project_line_id, opportunity_line_id)
  select
    cm.project_line_id,
    cm.opportunity_line_id
  from chosen_matches cm
  where cm.opportunity_line_id is not null;

  select count(*)
  into unresolved_line_count
  from public.project_quote_line_items pqli
  where pqli.organization_id = project_quote_row.organization_id
    and pqli.project_id = project_quote_row.project_id
    and pqli.quote_id = project_quote_row.id
    and pqli.source_opportunity_quote_line_item_id is null
    and not exists (
      select 1
      from tmp_project_quote_lineage_matches m
      where m.project_line_id = pqli.id
    );

  if unresolved_line_count > 0 then
    raise exception 'Lineage repair failed: one or more project quote lines could not be matched safely to the source opportunity quote';
  end if;

  select count(*)
  into duplicate_source_match_count
  from (
    select m.opportunity_line_id
    from tmp_project_quote_lineage_matches m
    group by m.opportunity_line_id
    having count(*) > 1
  ) duplicates;

  if duplicate_source_match_count > 0 then
    raise exception 'Lineage repair failed: one or more source opportunity quote lines matched multiple project quote lines';
  end if;

  update public.project_quote_line_items pqli
  set
    source_opportunity_quote_id = project_quote_row.source_opportunity_quote_id,
    source_opportunity_quote_line_item_id = m.opportunity_line_id,
    source_opportunity_quote_number = project_quote_row.source_opportunity_quote_number
  from tmp_project_quote_lineage_matches m
  where pqli.id = m.project_line_id
    and pqli.quote_id = project_quote_row.id;

  get diagnostics repaired_line_count = row_count;

  cost_item_revision_key := public.begin_cost_item_revision('project_quote', project_quote_row.id);
  perform public.supersede_previous_cost_items('project_quote', project_quote_row.id, cost_item_revision_key);
  mirrored_cost_item_count := public.upsert_cost_items_for_document('project_quote', project_quote_row.id, cost_item_revision_key);

  return next;
end;
$$;


ALTER FUNCTION "public"."repair_project_quote_opportunity_lineage"("p_project_quote_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."repair_project_quote_source_opportunity_lineage"("p_organization_id" "uuid", "p_quote_id" "uuid") RETURNS TABLE("id" "uuid", "source_opportunity_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  actor_user_id uuid := auth.uid();
  quote_row public.project_quotes%rowtype;
  resolved_project_source_opportunity_id uuid;
begin
  if actor_user_id is null then
    raise exception 'Authentication is required';
  end if;

  if not public.has_org_permission(p_organization_id, 'quotes.write') then
    raise exception 'Not authorized for this organization';
  end if;

  select q.*
  into quote_row
  from public.project_quotes q
  where q.id = p_quote_id
    and q.organization_id = p_organization_id
  for update;

  if not found then
    raise exception 'Quote not found';
  end if;

  if quote_row.project_id is not null then
    select p.source_opportunity_id
    into resolved_project_source_opportunity_id
    from public.organization_projects p
    where p.id = quote_row.project_id
      and p.organization_id = quote_row.organization_id;

    if resolved_project_source_opportunity_id is not null
      and quote_row.originating_opportunity_id is not null
      and resolved_project_source_opportunity_id <> quote_row.originating_opportunity_id then
      raise exception 'This quote belongs to a different opportunity.';
    end if;
  else
    resolved_project_source_opportunity_id := quote_row.originating_opportunity_id;
  end if;

  if quote_row.source_opportunity_id is null then
    update public.project_quotes q
    set source_opportunity_id = coalesce(resolved_project_source_opportunity_id, q.originating_opportunity_id)
    where q.id = quote_row.id
    returning * into quote_row;
  end if;

  return query
  select quote_row.id, quote_row.source_opportunity_id;
end;
$$;


ALTER FUNCTION "public"."repair_project_quote_source_opportunity_lineage"("p_organization_id" "uuid", "p_quote_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."repair_project_source_opportunity_lineage"("p_project_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  project_row public.organization_projects%rowtype;
  resolved_opportunity_id uuid;
  candidate_count integer;
begin
  select *
  into project_row
  from public.organization_projects
  where id = p_project_id;

  if not found then
    raise exception 'Project % does not exist.', p_project_id;
  end if;

  if project_row.source_opportunity_id is not null then
    return project_row.source_opportunity_id;
  end if;

  with distinct_candidates as (
    select distinct opportunity.id as opportunity_id
    from public.organization_opportunities as opportunity
    where opportunity.organization_id = project_row.organization_id
      and (
        opportunity.workspace_project_id = project_row.id
        or opportunity.converted_project_id = project_row.id
      )
  )
  select candidate.opportunity_id, count(*) over ()
  into resolved_opportunity_id, candidate_count
  from distinct_candidates as candidate
  limit 1;

  if candidate_count is null or candidate_count = 0 then
    return null;
  end if;

  if candidate_count > 1 then
    raise exception 'Project source opportunity lineage is ambiguous for project %.', p_project_id;
  end if;

  update public.organization_projects
  set source_opportunity_id = resolved_opportunity_id
  where id = project_row.id
    and source_opportunity_id is null;

  return resolved_opportunity_id;
end;
$$;


ALTER FUNCTION "public"."repair_project_source_opportunity_lineage"("p_project_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."repair_supplier_invoice_allocation_tax"("p_organization_id" "uuid", "p_supplier_invoice_id" "uuid", "p_expected_finance_hash" "text", "p_resolutions" "jsonb", "p_resolver_version" "text", "p_dry_run" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_invoice public.supplier_invoices%rowtype;
  v_current_hash text;
  v_item jsonb;
  v_scanned integer := 0;
  v_resolved integer := 0;
  v_already integer := 0;
  v_locked integer := 0;
  v_exported integer := 0;
  v_review integer := 0;
begin
  if not public.has_org_permission(p_organization_id, 'supplier_invoices.accounts_approve') then
    raise exception 'You do not have permission to repair Supplier Invoice GST.';
  end if;
  select * into v_invoice from public.supplier_invoices
  where id = p_supplier_invoice_id and organization_id = p_organization_id
  for update;
  if not found then raise exception 'Supplier Invoice not found.'; end if;
  v_current_hash := public.supplier_invoice_finance_version_hash(p_supplier_invoice_id);
  if v_current_hash is null or v_current_hash <> p_expected_finance_hash then
    raise exception 'The Supplier Invoice changed before GST repair. Refresh and run the dry-run again.';
  end if;
  if exists (
    select 1 from public.organization_accounting_documents d
    where d.organization_id = p_organization_id
      and d.local_document_type = 'supplier_invoice'
      and d.local_document_id = p_supplier_invoice_id
      and d.export_status in ('queued', 'exporting', 'exported', 'attention_required')
  ) then
    v_exported := 1;
    return jsonb_build_object('scanned', 0, 'automaticallyResolved', 0, 'alreadyResolved', 0,
      'accountsReviewRequired', 0, 'locked', 0, 'exported', v_exported, 'dryRun', p_dry_run);
  end if;
  if jsonb_typeof(coalesce(p_resolutions, '[]'::jsonb)) <> 'array' then
    raise exception 'GST repair resolutions must be an array.';
  end if;
  for v_item in select value from jsonb_array_elements(coalesce(p_resolutions, '[]'::jsonb)) loop
    v_scanned := v_scanned + 1;
    if coalesce(v_item ->> 'status', '') <> 'resolved' then
      v_review := v_review + 1;
      continue;
    end if;
    if exists (
      select 1 from public.supplier_invoice_line_allocations a
      where a.organization_id = p_organization_id
        and a.supplier_invoice_id = p_supplier_invoice_id
        and a.supplier_invoice_line_id = (v_item ->> 'lineId')::uuid
        and a.tax_resolution_status in ('resolved', 'not_applicable')
    ) then
      v_already := v_already + 1;
      continue;
    end if;
    if exists (
      select 1 from public.project_actual_cost_events e
      where e.organization_id = p_organization_id
        and e.supplier_invoice_id = p_supplier_invoice_id
        and e.source_invoice_line_id = (v_item ->> 'lineId')::uuid
        and e.event_status = 'active'
    ) then
      v_locked := v_locked + 1;
      continue;
    end if;
    v_resolved := v_resolved + 1;
    if not p_dry_run then
      update public.supplier_invoice_line_allocations
      set accounting_tax_rate_id = (v_item ->> 'accountingTaxRateId')::uuid,
          tax_resolution_status = 'resolved',
          approval_status = 'pending',
          reviewed_by_user_id = null,
          reviewed_at = null,
          updated_at = now()
      where organization_id = p_organization_id
        and supplier_invoice_id = p_supplier_invoice_id
        and supplier_invoice_line_id = (v_item ->> 'lineId')::uuid
        and tax_resolution_status = 'unresolved';
    end if;
  end loop;
  if not p_dry_run and v_resolved > 0 then
    perform public.invalidate_supplier_invoice_commercial_approval(
      p_supplier_invoice_id, 'GST treatment repaired.', 'supplier_invoice_tax_repair', auth.uid());
    perform public.invalidate_supplier_invoice_role_workflow(
      p_supplier_invoice_id, 'GST treatment repaired.');
    insert into public.supplier_invoice_activity_events (
      organization_id, supplier_invoice_id, event_type, message, metadata, created_by
    ) values (
      p_organization_id, p_supplier_invoice_id, 'supplier_invoice_tax_repaired',
      'Supplier Invoice GST treatments were resolved automatically.',
      jsonb_build_object('resolved_count', v_resolved, 'resolver_version', p_resolver_version,
        'previous_finance_hash', v_current_hash), auth.uid()
    );
  end if;
  return jsonb_build_object(
    'scanned', v_scanned, 'automaticallyResolved', v_resolved,
    'alreadyResolved', v_already, 'accountsReviewRequired', v_review,
    'locked', v_locked, 'exported', v_exported, 'dryRun', p_dry_run
  );
end;
$$;


ALTER FUNCTION "public"."repair_supplier_invoice_allocation_tax"("p_organization_id" "uuid", "p_supplier_invoice_id" "uuid", "p_expected_finance_hash" "text", "p_resolutions" "jsonb", "p_resolver_version" "text", "p_dry_run" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."repair_takeoff_calibration_unit_integrity"("arg_calibration_id" "uuid", "arg_expected_updated_at" timestamp with time zone, "arg_intended_display_unit" "text", "arg_reference_length_base" numeric, "arg_scale_ratio" numeric, "arg_measurement_repairs" "jsonb", "arg_reason" "text", "arg_repair_version" "text", "arg_dry_run" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  calibration_row public.takeoff_calibrations%rowtype;
  measurement_repair jsonb;
  shape_repair jsonb;
  path_repair jsonb;
  dependent_ids uuid[];
  proposed_ids uuid[];
  before_snapshot jsonb;
  after_snapshot jsonb;
begin
  if current_user not in ('service_role', 'postgres') then
    raise exception 'Takeoff unit repair requires the service role.';
  end if;

  if arg_intended_display_unit not in ('mm', 'cm', 'm', 'in', 'ft') then
    raise exception 'Unsupported intended calibration display unit.';
  end if;
  if arg_reference_length_base <= 0 or arg_scale_ratio <= 0 then
    raise exception 'Repaired calibration values must be positive.';
  end if;
  if jsonb_typeof(arg_measurement_repairs) <> 'array' then
    raise exception 'Measurement repairs must be a JSON array.';
  end if;
  if nullif(btrim(arg_reason), '') is null or nullif(btrim(arg_repair_version), '') is null then
    raise exception 'Repair reason and version are required.';
  end if;

  select * into calibration_row
  from public.takeoff_calibrations
  where id = arg_calibration_id
  for update;

  if calibration_row.id is null then
    raise exception 'Allowlisted calibration does not exist.';
  end if;
  if calibration_row.updated_at <> arg_expected_updated_at then
    raise exception 'Calibration changed after dry-run; generate a new report.';
  end if;
  if (calibration_row.unit_system = 'metric' and arg_intended_display_unit not in ('mm', 'cm', 'm'))
     or (calibration_row.unit_system = 'imperial' and arg_intended_display_unit not in ('in', 'ft')) then
    raise exception 'Intended unit does not match the stored unit system.';
  end if;

  select coalesce(array_agg(id order by id), '{}'::uuid[]) into dependent_ids
  from public.takeoff_measurements
  where calibration_id = arg_calibration_id;

  select coalesce(array_agg((item->>'id')::uuid order by (item->>'id')::uuid), '{}'::uuid[])
  into proposed_ids
  from jsonb_array_elements(arg_measurement_repairs) item;

  if dependent_ids <> proposed_ids then
    raise exception 'Repair payload must include every dependent measurement exactly once.';
  end if;

  select jsonb_build_object(
    'calibration', to_jsonb(calibration_row),
    'measurements', coalesce(jsonb_agg(to_jsonb(m) order by m.id), '[]'::jsonb)
  ) into before_snapshot
  from public.takeoff_measurements m
  where m.calibration_id = arg_calibration_id;

  after_snapshot := jsonb_build_object(
    'calibration', to_jsonb(calibration_row) || jsonb_build_object(
      'display_unit', arg_intended_display_unit,
      'reference_length_base', arg_reference_length_base,
      'scale_ratio', arg_scale_ratio
    ),
    'measurements', arg_measurement_repairs
  );

  if arg_dry_run then
    return jsonb_build_object(
      'dryRun', true,
      'calibrationId', arg_calibration_id,
      'dependentMeasurementCount', cardinality(dependent_ids),
      'before', before_snapshot,
      'after', after_snapshot
    );
  end if;

  update public.takeoff_calibrations
  set display_unit = arg_intended_display_unit,
      reference_length_base = arg_reference_length_base,
      scale_ratio = arg_scale_ratio
  where id = arg_calibration_id;

  for measurement_repair in select value from jsonb_array_elements(arg_measurement_repairs)
  loop
    update public.takeoff_measurements
    set measured_length_base = nullif(measurement_repair->>'measured_length_base', '')::numeric,
        measured_area_base = nullif(measurement_repair->>'measured_area_base', '')::numeric,
        measured_perimeter_base = nullif(measurement_repair->>'measured_perimeter_base', '')::numeric,
        display_value = nullif(measurement_repair->>'display_value', '')::numeric,
        display_unit = measurement_repair->>'display_unit'
    where id = (measurement_repair->>'id')::uuid
      and calibration_id = arg_calibration_id;

    if not found then
      raise exception 'Dependent measurement changed during repair.';
    end if;

    for shape_repair in select value from jsonb_array_elements(coalesce(measurement_repair->'area_shapes', '[]'::jsonb))
    loop
      update public.takeoff_measurement_area_shapes
      set measured_area_base = (shape_repair->>'measured_area_base')::numeric,
          measured_perimeter_base = (shape_repair->>'measured_perimeter_base')::numeric
      where id = (shape_repair->>'id')::uuid
        and measurement_id = (measurement_repair->>'id')::uuid;
      if not found then raise exception 'Dependent area shape changed during repair.'; end if;
    end loop;

    for path_repair in select value from jsonb_array_elements(coalesce(measurement_repair->'line_paths', '[]'::jsonb))
    loop
      update public.takeoff_measurement_line_paths
      set measured_length_base = (path_repair->>'measured_length_base')::numeric
      where id = (path_repair->>'id')::uuid
        and measurement_id = (measurement_repair->>'id')::uuid;
      if not found then raise exception 'Dependent line path changed during repair.'; end if;
    end loop;
  end loop;

  insert into public.takeoff_data_repair_audit (
    repair_version, repair_kind, calibration_id, organization_id, project_id,
    opportunity_id, page_id, reason, before_data, after_data
  ) values (
    arg_repair_version, 'takeoff_calibration_unit_integrity', calibration_row.id,
    calibration_row.organization_id, calibration_row.project_id, calibration_row.opportunity_id,
    calibration_row.page_id, btrim(arg_reason), before_snapshot, after_snapshot
  );

  return jsonb_build_object(
    'dryRun', false,
    'calibrationId', arg_calibration_id,
    'dependentMeasurementCount', cardinality(dependent_ids),
    'auditRecorded', true,
    'before', before_snapshot,
    'after', after_snapshot
  );
end;
$$;


ALTER FUNCTION "public"."repair_takeoff_calibration_unit_integrity"("arg_calibration_id" "uuid", "arg_expected_updated_at" timestamp with time zone, "arg_intended_display_unit" "text", "arg_reference_length_base" numeric, "arg_scale_ratio" numeric, "arg_measurement_repairs" "jsonb", "arg_reason" "text", "arg_repair_version" "text", "arg_dry_run" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."replace_organization_memory_provenance_links"("p_organization_memory_item_id" "uuid", "p_organization_id" "uuid", "p_records" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  inserted_ids jsonb := '[]'::jsonb;
begin
  if p_records is null or jsonb_typeof(p_records) <> 'array' then
    raise exception 'replace_organization_memory_provenance_links requires a JSON array payload';
  end if;

  perform public._organization_memory_assert_item_in_organization(
    p_memory_item_id := p_organization_memory_item_id,
    p_organization_id := p_organization_id
  );

  delete from public.organization_memory_links
  where organization_memory_item_id = p_organization_memory_item_id
    and organization_id = p_organization_id
    and (
      source_event_id is not null
      or (
        source_entity_type in ('worksheet_memory_semantic_pool', 'worksheet_event_classification', 'organization_memory_item')
        and link_type in ('seed', 'supporting', 'contradiction', 'supersession', 'uncertain', 'adjacent', 'excluded')
      )
    );

  if jsonb_array_length(p_records) = 0 then
    return jsonb_build_object(
      'count', 0,
      'ids', '[]'::jsonb
    );
  end if;

  with inserted as (
    insert into public.organization_memory_links (
      organization_memory_item_id,
      organization_id,
      link_type,
      source_event_id,
      source_entity_type,
      source_entity_id,
      weight,
      confidence_delta,
      note
    )
    select
      p_organization_memory_item_id,
      p_organization_id,
      coalesce(nullif(trim(record->>'link_type'), ''), 'supporting'),
      nullif(record->>'source_event_id', '')::uuid,
      nullif(record->>'source_entity_type', ''),
      nullif(record->>'source_entity_id', '')::uuid,
      coalesce(nullif(record->>'weight', '')::numeric, 1),
      nullif(record->>'confidence_delta', '')::numeric,
      nullif(record->>'note', '')
    from jsonb_array_elements(p_records) as record
    returning id
  )
  select coalesce(jsonb_agg(id), '[]'::jsonb)
  into inserted_ids
  from inserted;

  return jsonb_build_object(
    'count', jsonb_array_length(inserted_ids),
    'ids', inserted_ids
  );
end;
$$;


ALTER FUNCTION "public"."replace_organization_memory_provenance_links"("p_organization_memory_item_id" "uuid", "p_organization_id" "uuid", "p_records" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."replace_worksheet_memory_semantic_pool_events"("p_semantic_pool_id" "uuid", "p_organization_id" "uuid", "p_records" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  input_item jsonb;
  inserted_ids jsonb := '[]'::jsonb;
  inserted_id uuid;
begin
  if p_records is null or jsonb_typeof(p_records) <> 'array' then
    raise exception 'replace_worksheet_memory_semantic_pool_events requires a JSON array payload';
  end if;

  delete from public.worksheet_memory_semantic_pool_events
  where semantic_pool_id = p_semantic_pool_id
    and organization_id = p_organization_id;

  for input_item in
    select value
    from jsonb_array_elements(p_records)
  loop
    insert into public.worksheet_memory_semantic_pool_events (
      semantic_pool_id,
      organization_id,
      source_event_id,
      classification_record_id,
      evidence_role,
      linked_by_run_id
    )
    values (
      p_semantic_pool_id,
      p_organization_id,
      nullif(input_item->>'source_event_id', '')::uuid,
      nullif(input_item->>'classification_record_id', '')::uuid,
      coalesce(nullif(btrim(coalesce(input_item->>'evidence_role', '')), ''), 'excluded'),
      nullif(input_item->>'linked_by_run_id', '')::uuid
    )
    returning id into inserted_id;

    inserted_ids := inserted_ids || jsonb_build_array(inserted_id);
  end loop;

  return jsonb_build_object(
    'count', jsonb_array_length(inserted_ids),
    'ids', inserted_ids
  );
end;
$$;


ALTER FUNCTION "public"."replace_worksheet_memory_semantic_pool_events"("p_semantic_pool_id" "uuid", "p_organization_id" "uuid", "p_records" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."report_project_quote_line_pricing_source_kind_mismatches"("p_organization_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("organization_id" "uuid", "quote_id" "uuid", "quote_line_id" "uuid", "recorded_source_kind" "text", "evidence_source_kind" "text", "quote_status" "text", "award_locked" boolean, "award_classification" "text")
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  select
    line.organization_id,
    line.quote_id,
    line.id,
    line.pricing_source_kind,
    'worksheet'::text,
    quote.status,
    quote.award_locked_at is not null,
    manifest.classification
  from public.project_quote_line_items line
  join public.project_quotes quote
    on quote.organization_id = line.organization_id
   and quote.id = line.quote_id
  left join public.opportunity_award_pricing_manifests manifest
    on manifest.organization_id = line.organization_id
   and manifest.accepted_quote_id = line.quote_id
  where (p_organization_id is null or line.organization_id = p_organization_id)
    and line.pricing_source_kind <> 'worksheet'
    and exists (
      select 1
      from public.commercial_item_document_links link
      where link.organization_id = line.organization_id
        and link.document_kind = 'quote_line'
        and link.link_role = 'source'
        and link.document_id = line.quote_id
        and link.document_line_id = line.id
    )
  order by line.organization_id, line.quote_id, line.id;
$$;


ALTER FUNCTION "public"."report_project_quote_line_pricing_source_kind_mismatches"("p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."requeue_supplier_bill_ucl_refresh_dead_letter"("p_queue_id" "uuid") RETURNS "public"."supplier_bill_ucl_refresh_queue"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  queued public.supplier_bill_ucl_refresh_queue%rowtype;
begin
  update public.supplier_bill_ucl_refresh_queue q
  set
    queue_state = 'pending',
    attempt_count = 0,
    available_at = now(),
    lease_owner = null,
    lease_token = null,
    leased_at = null,
    lease_expires_at = null,
    last_error_code = null,
    last_error_summary = null,
    updated_at = now()
  where q.id = p_queue_id
    and q.queue_state = 'dead_letter'
  returning * into queued;

  if queued.id is null then
    raise exception 'Dead-lettered Supplier Bill refresh row not found.';
  end if;
  return queued;
end;
$$;


ALTER FUNCTION "public"."requeue_supplier_bill_ucl_refresh_dead_letter"("p_queue_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."require_series_for_opportunity_quote_insert"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
begin
  if new.originating_opportunity_id is not null and new.project_id is null
    and new.revision_kind = 'tender' and new.quote_series_id is null
  then
    raise exception 'Opportunity quotes must be created through an atomic Quote Series operation'
      using errcode = 'TS422';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."require_series_for_opportunity_quote_insert"() OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."organization_accounting_number_reservations" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "provider" "text" NOT NULL,
    "tenant_id" "text" NOT NULL,
    "document_class" "text" NOT NULL,
    "sequence_number" bigint NOT NULL,
    "formatted_number" "text" NOT NULL,
    "accounting_document_id" "uuid",
    "source_document_type" "text" NOT NULL,
    "source_document_id" "uuid" NOT NULL,
    "reservation_reason" "text" NOT NULL,
    "reserved_by" "uuid" NOT NULL,
    "reserved_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "accounting_number_reservation_class_check" CHECK (("document_class" = 'sales_invoice'::"text")),
    CONSTRAINT "accounting_number_reservation_number_check" CHECK (((("source_document_type" = 'project_claim'::"text") AND (("formatted_number" ~ '^TSI-[0-9]{8,}$'::"text") OR ("formatted_number" ~ '^.+-CL-[0-9]+$'::"text") OR ("formatted_number" ~ '^.+-R[1-9][0-9]*$'::"text"))) OR (("source_document_type" = 'retention_claim'::"text") AND ("char_length"(TRIM(BOTH FROM "formatted_number")) > 0)))),
    CONSTRAINT "accounting_number_reservation_sequence_check" CHECK (("sequence_number" > 0)),
    CONSTRAINT "accounting_number_reservation_source_check" CHECK (("source_document_type" = ANY (ARRAY['project_claim'::"text", 'retention_claim'::"text"]))),
    CONSTRAINT "accounting_number_reservation_text_check" CHECK ((("char_length"(TRIM(BOTH FROM "provider")) > 0) AND ("char_length"(TRIM(BOTH FROM "tenant_id")) > 0) AND ("char_length"(TRIM(BOTH FROM "reservation_reason")) > 0)))
);

ALTER TABLE ONLY "public"."organization_accounting_number_reservations" FORCE ROW LEVEL SECURITY;


ALTER TABLE "public"."organization_accounting_number_reservations" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reserve_accounting_sales_invoice_number_phase2a"("p_organization_id" "uuid", "p_provider" "text", "p_tenant_id" "text", "p_source_document_type" "text", "p_source_document_id" "uuid", "p_accounting_document_id" "uuid", "p_reserved_by" "uuid", "p_reason" "text") RETURNS "public"."organization_accounting_number_reservations"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  next_sequence bigint;
  reservation public.organization_accounting_number_reservations%rowtype;
begin
  if p_source_document_type = 'project_claim' then
    if not exists (
      select 1 from public.project_claims c
      where c.id = p_source_document_id
        and c.organization_id = p_organization_id
    ) then
      raise exception 'Payment Claim does not belong to the reservation organization.';
    end if;
  elsif p_source_document_type = 'retention_claim' then
    if not exists (
      select 1 from public.retention_claims c
      where c.id = p_source_document_id
        and c.organization_id = p_organization_id
    ) then
      raise exception 'Retention Claim does not belong to the reservation organization.';
    end if;
  else
    raise exception 'Only Payment Claims and Retention Claims share the sales-invoice sequence.';
  end if;

  if p_accounting_document_id is not null and not exists (
    select 1 from public.organization_accounting_documents d
    where d.id = p_accounting_document_id
      and d.organization_id = p_organization_id
      and d.provider = p_provider
      and d.tenant_id = p_tenant_id
      and d.local_document_type = p_source_document_type
      and coalesce(d.project_claim_id, d.retention_claim_id) = p_source_document_id
  ) then
    raise exception 'Accounting document identity does not match the reservation scope.';
  end if;

  insert into public.organization_accounting_number_counters(
    organization_id, provider, tenant_id, document_class, last_sequence
  ) values (
    p_organization_id, p_provider, trim(p_tenant_id), 'sales_invoice', 1
  )
  on conflict (organization_id, provider, tenant_id, document_class)
  do update set
    last_sequence = organization_accounting_number_counters.last_sequence + 1,
    updated_at = now()
  returning last_sequence into next_sequence;

  insert into public.organization_accounting_number_reservations(
    organization_id, provider, tenant_id, document_class, sequence_number,
    formatted_number, accounting_document_id, source_document_type,
    source_document_id, reservation_reason, reserved_by
  ) values (
    p_organization_id, p_provider, trim(p_tenant_id), 'sales_invoice',
    next_sequence,
    public.format_accounting_sales_invoice_number_phase2a(next_sequence),
    p_accounting_document_id, p_source_document_type, p_source_document_id,
    p_reason, p_reserved_by
  ) returning * into reservation;
  return reservation;
end;
$$;


ALTER FUNCTION "public"."reserve_accounting_sales_invoice_number_phase2a"("p_organization_id" "uuid", "p_provider" "text", "p_tenant_id" "text", "p_source_document_type" "text", "p_source_document_id" "uuid", "p_accounting_document_id" "uuid", "p_reserved_by" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reserve_ai_chat_usage_quota"("p_user_id" "uuid", "p_organization_id" "uuid", "p_project_slug" "text", "p_plan_tier" "text", "p_month_start" timestamp with time zone, "p_monthly_limit" integer) RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_month_start timestamptz := date_trunc('month', coalesce(p_month_start, now()));
  v_usage_id uuid;
  v_lock_namespace integer := hashtext('ai_chat_usage_quota');
  v_lock_key integer;
begin
  if auth.uid() is distinct from p_user_id then
    return null;
  end if;

  if coalesce(p_monthly_limit, 0) <= 0 then
    return null;
  end if;

  v_lock_key := hashtext(p_user_id::text || ':' || to_char(v_month_start, 'YYYY-MM'));
  perform pg_advisory_xact_lock(v_lock_namespace, v_lock_key);

  if (
    select count(*)
    from public.ai_chat_usage u
    where u.user_id = p_user_id
      and u.created_at >= v_month_start
      and u.reservation_state in ('pending', 'committed')
  ) >= p_monthly_limit then
    return null;
  end if;

  insert into public.ai_chat_usage (
    user_id,
    organization_id,
    project_slug,
    plan_tier,
    tokens_used,
    response_chars,
    created_at,
    reservation_state
  )
  values (
    p_user_id,
    p_organization_id,
    p_project_slug,
    coalesce(nullif(trim(p_plan_tier), ''), 'starter'),
    0,
    0,
    now(),
    'pending'
  )
  returning id into v_usage_id;

  return v_usage_id;
end;
$$;


