CREATE OR REPLACE FUNCTION "public"."resolve_default_tradesstack_accounting_mapping"("p_organization_id" "uuid", "p_tradesstack_cost_code" integer, "p_project_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  resolved_mapping_id uuid := null;
  provider_count integer := 0;
begin
  -- An exact project override wins before organization-level mappings are
  -- considered. A scope with multiple providers is intentionally ambiguous.
  if p_project_id is not null then
    select count(distinct mapping.provider)
    into provider_count
    from public.organization_tradesstack_accounting_mappings mapping
    join public.organization_cost_codes cost_code
      on cost_code.id = mapping.organization_cost_code_id
     and cost_code.organization_id = mapping.organization_id
     and cost_code.is_active
     and cost_code.external_provider = mapping.provider
    where mapping.organization_id = p_organization_id
      and mapping.tradesstack_cost_code = p_tradesstack_cost_code
      and mapping.project_id = p_project_id
      and mapping.is_active;

    if provider_count = 1 then
      select mapping.id
      into resolved_mapping_id
      from public.organization_tradesstack_accounting_mappings mapping
      join public.organization_cost_codes cost_code
        on cost_code.id = mapping.organization_cost_code_id
       and cost_code.organization_id = mapping.organization_id
       and cost_code.is_active
       and cost_code.external_provider = mapping.provider
      where mapping.organization_id = p_organization_id
        and mapping.tradesstack_cost_code = p_tradesstack_cost_code
        and mapping.project_id = p_project_id
        and mapping.is_active
      order by mapping.updated_at desc, mapping.id desc
      limit 1;

      return resolved_mapping_id;
    elsif provider_count > 1 then
      return null;
    end if;
  end if;

  select count(distinct mapping.provider)
  into provider_count
  from public.organization_tradesstack_accounting_mappings mapping
  join public.organization_cost_codes cost_code
    on cost_code.id = mapping.organization_cost_code_id
   and cost_code.organization_id = mapping.organization_id
   and cost_code.is_active
   and cost_code.external_provider = mapping.provider
  where mapping.organization_id = p_organization_id
    and mapping.tradesstack_cost_code = p_tradesstack_cost_code
    and mapping.project_id is null
    and mapping.is_active;

  if provider_count = 1 then
    select mapping.id
    into resolved_mapping_id
    from public.organization_tradesstack_accounting_mappings mapping
    join public.organization_cost_codes cost_code
      on cost_code.id = mapping.organization_cost_code_id
     and cost_code.organization_id = mapping.organization_id
     and cost_code.is_active
     and cost_code.external_provider = mapping.provider
    where mapping.organization_id = p_organization_id
      and mapping.tradesstack_cost_code = p_tradesstack_cost_code
      and mapping.project_id is null
      and mapping.is_active
    order by mapping.updated_at desc, mapping.id desc
    limit 1;
  end if;

  return resolved_mapping_id;
end;
$$;


ALTER FUNCTION "public"."resolve_default_tradesstack_accounting_mapping"("p_organization_id" "uuid", "p_tradesstack_cost_code" integer, "p_project_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_document_download"("p_node_id" "uuid", "p_version_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("node_id" "uuid", "version_id" "uuid", "storage_key" "text", "display_name" "text", "verified_mime_type" "text", "byte_size" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  node_row public.document_nodes%rowtype;
  resolved_version_id uuid;
begin
  if auth.uid() is null then
    raise exception 'Unauthorized.';
  end if;

  select node.*
  into node_row
  from public.document_nodes node
  where node.id = p_node_id;

  if not found
    or node_row.kind <> 'file'
    or node_row.lifecycle_state <> 'active'
    or node_row.deleted_at is not null
    or node_row.current_version_id is null
    or not public.can_access_document_workspace(
      node_row.workspace_id,
      'files.view'
    )
  then
    raise exception 'Document file not found or access denied.';
  end if;

  resolved_version_id := coalesce(p_version_id, node_row.current_version_id);

  return query
  select
    node_row.id,
    version.id,
    version.storage_key,
    node_row.display_name,
    version.verified_mime_type,
    version.byte_size
  from public.document_versions version
  where version.organization_id = node_row.organization_id
    and version.workspace_id = node_row.workspace_id
    and version.node_id = node_row.id
    and version.id = resolved_version_id
    and version.id = node_row.current_version_id
    and version.upload_state = 'active'
    and version.storage_object_id is not null;

  if not found then
    raise exception 'Active document version not found or access denied.';
  end if;
end;
$$;


ALTER FUNCTION "public"."resolve_document_download"("p_node_id" "uuid", "p_version_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_document_upload_workspace"("p_opportunity_id" "uuid", "p_project_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  workspace_id uuid;
  entity_organization_id uuid;
begin
  if auth.uid() is null then
    raise exception 'Unauthorized.';
  end if;

  if (p_opportunity_id is not null)::integer
    + (p_project_id is not null)::integer <> 1
  then
    raise exception 'Exactly one Opportunity or Project identifier is required.';
  end if;

  if p_opportunity_id is not null then
    select opportunity.organization_id
    into entity_organization_id
    from public.organization_opportunities opportunity
    where opportunity.id = p_opportunity_id;

    if not found
      or not public.has_org_permission(entity_organization_id, 'files.write')
    then
      raise exception 'Opportunity not found or access denied.';
    end if;

    workspace_id :=
      public.get_or_create_opportunity_document_workspace(p_opportunity_id);
  else
    select project.organization_id, link.workspace_id
    into entity_organization_id, workspace_id
    from public.organization_projects project
    left join public.document_workspace_entities link
      on link.organization_id = project.organization_id
     and link.project_id = project.id
    where project.id = p_project_id;

    if not found
      or workspace_id is null
      or not public.has_org_permission(entity_organization_id, 'files.write')
    then
      raise exception 'Project document workspace not found or access denied.';
    end if;
  end if;

  return workspace_id;
end;
$$;


ALTER FUNCTION "public"."resolve_document_upload_workspace"("p_opportunity_id" "uuid", "p_project_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_material_estimating_currency"("p_organization" "jsonb") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE PARALLEL SAFE
    SET "search_path" TO ''
    AS $_$
  select case upper(btrim(coalesce(p_organization->>'country', '')))
    when 'NEW ZEALAND' then 'NZD' when 'NZ' then 'NZD' when 'NZL' then 'NZD'
    when 'AUSTRALIA' then 'AUD' when 'AU' then 'AUD' when 'AUS' then 'AUD'
    else case when upper(btrim(coalesce(p_organization->>'default_currency', ''))) ~ '^[A-Z]{3}$'
      then upper(btrim(p_organization->>'default_currency')) else 'NZD' end
  end
$_$;


ALTER FUNCTION "public"."resolve_material_estimating_currency"("p_organization" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_material_supplier_product_prices"("p_organization_id" "uuid", "p_evaluation_time" timestamp with time zone DEFAULT "now"(), "p_supplier_product_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS TABLE("supplier_product_id" "uuid", "price_id" "uuid")
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare
  v_conflicting_supplier_product_id uuid;
begin
  if p_organization_id is null then
    raise exception 'materials_phase1h:organization_required';
  end if;

  if p_evaluation_time is null then
    raise exception 'materials_phase1h:evaluation_time_required';
  end if;

  select price.supplier_product_id
  into v_conflicting_supplier_product_id
  from public.organization_material_supplier_prices price
  where price.organization_id = p_organization_id
    and price.supplier_product_id is not null
    and (p_supplier_product_ids is null or price.supplier_product_id = any(p_supplier_product_ids))
    and price.effective_from <= p_evaluation_time
    and (price.effective_to is null or price.effective_to > p_evaluation_time)
  group by price.supplier_product_id
  having count(*) > 1
  order by price.supplier_product_id
  limit 1;

  if v_conflicting_supplier_product_id is not null then
    raise exception 'materials_phase1h:effective_price_interval_conflict:%',
      v_conflicting_supplier_product_id;
  end if;

  return query
  select price.supplier_product_id, price.id
  from public.organization_material_supplier_prices price
  where price.organization_id = p_organization_id
    and price.supplier_product_id is not null
    and (p_supplier_product_ids is null or price.supplier_product_id = any(p_supplier_product_ids))
    and price.effective_from <= p_evaluation_time
    and (price.effective_to is null or price.effective_to > p_evaluation_time)
  order by price.supplier_product_id;
end;
$$;


ALTER FUNCTION "public"."resolve_material_supplier_product_prices"("p_organization_id" "uuid", "p_evaluation_time" timestamp with time zone, "p_supplier_product_ids" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."resolve_material_supplier_product_prices"("p_organization_id" "uuid", "p_evaluation_time" timestamp with time zone, "p_supplier_product_ids" "uuid"[]) IS 'Canonical Phase 1H half-open [effective_from, effective_to) price resolver. Raises instead of choosing when more than one price is effective for a Supplier Product.';



CREATE OR REPLACE FUNCTION "public"."resolve_mobile_project_member_context_v2"("p_project_id" "uuid") RETURNS TABLE("organization_id" "uuid", "organization_member_id" "uuid")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
declare
  project_org_id uuid;
  current_member_id uuid;
begin
  if auth.uid() is null then
    raise exception 'Authentication is required';
  end if;

  select p.organization_id
  into project_org_id
  from public.organization_projects p
  where p.id = p_project_id;

  if project_org_id is null then
    raise exception 'Project not found';
  end if;

  select m.id
  into current_member_id
  from public.organization_members m
  where m.organization_id = project_org_id
    and m.user_id = auth.uid()
  limit 1;

  if current_member_id is null then
    raise exception 'Not authorized for this project';
  end if;

  if not exists (
    select 1
    from public.project_members pm
    where pm.organization_id = project_org_id
      and pm.project_id = p_project_id
      and pm.organization_member_id = current_member_id
      and pm.is_active = true
  ) then
    raise exception 'You do not have active access to this project';
  end if;

  return query
  select project_org_id, current_member_id;
end;
$$;


ALTER FUNCTION "public"."resolve_mobile_project_member_context_v2"("p_project_id" "uuid") OWNER TO "postgres";


