CREATE OR REPLACE FUNCTION "public"."resolve_organization_accounting_route_mapping"("p_organization_id" "uuid", "p_provider" "text", "p_accounting_route" "text", "p_project_id" "uuid" DEFAULT NULL::"uuid") RETURNS "public"."organization_accounting_route_mappings"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  select mapping
  from public.organization_accounting_route_mappings mapping
  where mapping.organization_id = p_organization_id
    and mapping.provider = lower(trim(p_provider))
    and mapping.accounting_route = p_accounting_route
    and mapping.is_active
    and (mapping.project_id = p_project_id or mapping.project_id is null)
