CREATE OR REPLACE FUNCTION "public"."resolve_retention_variance"("p_input" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v public.retention_variances%rowtype; ctx jsonb; s jsonb; old_state text;
begin
  select * into v from public.retention_variances where id=(p_input->>'varianceId')::uuid;
  if not found then return jsonb_build_object('succeeded',false,'errorCode','variance_not_found'); end if;
  ctx:=private.retention_phase5_context(v.project_id,'retention.variances.resolve',true);
  if not coalesce((ctx->>'succeeded')::boolean,false) then return ctx; end if;
  select * into v from public.retention_variances where id=v.id for update;
  if v.revision<>(p_input->>'expectedRevision')::bigint then
    return jsonb_build_object('succeeded',false,'errorCode','concurrent_update',
      'currentRevision',v.revision);
  end if;
  if v.state='resolved' then
    return jsonb_build_object('succeeded',false,'errorCode','variance_already_resolved');
  end if;
  if nullif(trim(coalesce(p_input->>'reason','')),'') is null then
    return jsonb_build_object('succeeded',false,'errorCode','variance_not_resolvable');
  end if;
  s:=private.retention_variance_snapshot(v.project_id,v.originating_payment_claim_id);
  if (s->>'committedRetention')::numeric>(s->>'currentOwnership')::numeric
    or (s->>'committedRetention')::numeric>(s->>'currentEligibility')::numeric
    or s->>'originStatus'='Cancelled' then
    perform private.record_retention_variance_event(v.id,'resolution_rejected',
      v.state,v.state,v.severity,v.severity,
      'Live financial position still does not support committed allocations.',
      p_input->>'correlationId',s);
    return jsonb_build_object('succeeded',false,'errorCode','live_position_still_invalid',
      'details',s);
  end if;
  old_state:=v.state;
  perform set_config('app.retention_phase5_internal_write','true',true);
  update public.retention_variances set
    prior_phase2_state_hash=latest_phase2_state_hash,
    prior_phase4_eligibility_hash=latest_phase4_eligibility_hash,
    prior_committed_allocation_hash=committed_allocation_hash,
    current_ownership=(s->>'currentOwnership')::numeric,
    current_eligibility=(s->>'currentEligibility')::numeric,
    committed_retention=(s->>'committedRetention')::numeric,
    ownership_variance=(s->>'ownershipVariance')::numeric,
    eligibility_variance=(s->>'eligibilityVariance')::numeric,
    diagnostic_remaining=(s->>'diagnosticRemaining')::numeric,
    latest_phase2_state_hash=s->>'phase2StateHash',
    latest_phase4_eligibility_hash=s->>'phase4EligibilityHash',
    committed_allocation_hash=s->>'committedAllocationHash',
    state='resolved',severity='low',is_blocking=false,
    resolution_type='live_position_reconciled',
    resolution_reason=trim(p_input->>'reason'),
    resolution_approved_by=auth.uid(),resolved_at=now(),
    last_evaluated_at=now(),last_correlation_id=p_input->>'correlationId',
    revision=revision+1,updated_at=now()
  where id=v.id returning * into v;
  perform set_config('app.retention_phase5_internal_write','',true);
  perform private.record_retention_variance_event(v.id,'variance_resolved',
    old_state,'resolved',v.severity,'low',v.resolution_reason,
    p_input->>'correlationId',jsonb_build_object('liveSnapshot',s));
  return jsonb_build_object('succeeded',true,'errorCode',null,
    'availabilityRestored',false,'variance',private.retention_variance_read_json(v.id));
end;
$$;


ALTER FUNCTION "public"."resolve_retention_variance"("p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."restore_document_node"("p_node_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  actor_user_id uuid := auth.uid();
  node_row public.document_nodes%rowtype;
  restored_count integer := 0;
  restore_time timestamptz := now();
begin
  select *
  into node_row
  from public.document_nodes node
  where node.id = p_node_id;

  if not found then
    raise exception 'Document node not found.'
      using errcode = 'P0002';
  end if;

  perform public.assert_document_workspace_permission(
    node_row.workspace_id,
    'files.delete'
  );
  perform pg_advisory_xact_lock(
    hashtextextended('document-workspace:' || node_row.workspace_id::text, 0)
  );

  select *
  into node_row
  from public.document_nodes node
  where node.id = p_node_id
  for update;

  if node_row.deleted_at is null then
    return 0;
  end if;

  if exists (
    select 1
    from public.document_nodes restoring
    join public.document_nodes parent
      on parent.id = restoring.parent_node_id
    where restoring.workspace_id = node_row.workspace_id
      and restoring.deletion_batch_id = node_row.deletion_batch_id
      and parent.deletion_batch_id is distinct from node_row.deletion_batch_id
      and parent.deleted_at is not null
  ) then
    raise exception 'Document subtree cannot be restored into a deleted parent.'
      using errcode = '23514';
  end if;

  if exists (
    select 1
    from public.document_nodes restoring
    join public.document_nodes active
      on active.workspace_id = restoring.workspace_id
     and active.parent_node_id is not distinct from restoring.parent_node_id
     and active.normalized_name = restoring.normalized_name
     and active.deleted_at is null
    where restoring.workspace_id = node_row.workspace_id
      and restoring.deletion_batch_id = node_row.deletion_batch_id
  ) then
    raise exception 'A document with the same name already exists in the restore destination.'
      using errcode = '23505';
  end if;

  with restored_nodes as (
    update public.document_nodes restoring
    set
      deleted_at = null,
      deleted_by = null,
      deletion_batch_id = null,
      updated_by = actor_user_id
    where restoring.workspace_id = node_row.workspace_id
      and restoring.deletion_batch_id = node_row.deletion_batch_id
    returning restoring.*
  ),
  inserted_events as (
    insert into public.document_activity_events (
      organization_id,
      workspace_id,
      node_id,
      actor_user_id,
      event_type,
      metadata,
      occurred_at
    )
    select
      restored.organization_id,
      restored.workspace_id,
      restored.id,
      actor_user_id,
      'restored',
      jsonb_build_object(
        'deletionBatchId', node_row.deletion_batch_id,
        'rootNodeId', node_row.id
      ),
      restore_time
    from restored_nodes restored
    returning 1
  )
  select count(*)::integer
  into restored_count
  from inserted_events;

  return restored_count;
end;
$$;


ALTER FUNCTION "public"."restore_document_node"("p_node_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."restore_material_supplier_product"("p_input" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_org uuid := (p_input->>'organization_id')::uuid;
  v_material_id uuid := (p_input->>'material_id')::uuid;
  v_product_id uuid := (p_input->>'supplier_product_id')::uuid;
  v_reason text := coalesce(nullif(pg_catalog.btrim(p_input->>'reason'), ''), 'Restored supplier item.');
  v_actor uuid;
  v_product public.organization_material_supplier_products%rowtype;
begin
  v_actor := public.materials_phase1f_require_writer(v_org);

  perform 1
  from public.organization_materials
  where organization_id = v_org and id = v_material_id
  for update;
  if not found then
    perform public.materials_phase1f_error('material_not_found');
  end if;

  select * into v_product
  from public.organization_material_supplier_products
  where organization_id = v_org and id = v_product_id
  for update;
  if not found or v_product.material_id <> v_material_id then
    perform public.materials_phase1f_error('supplier_product_not_found');
  end if;

  if v_product.is_active and v_product.archived_at is null then
    return pg_catalog.jsonb_build_object(
      'supplier_product_id', v_product.id,
      'material_id', v_product.material_id,
      'is_active', true,
      'is_preferred', v_product.is_preferred,
      'archived_at', null,
      'idempotent_replay', true
    );
  end if;

  if v_product.identity_status = 'confirmed' and exists (
    select 1
    from public.organization_material_supplier_products candidate
    where candidate.organization_id = v_org
      and candidate.material_id = v_product.material_id
      and candidate.supplier_id = v_product.supplier_id
      and candidate.normalized_supplier_unit = v_product.normalized_supplier_unit
      and candidate.identity_variant = v_product.identity_variant
      and candidate.identity_status = 'confirmed'
      and candidate.archived_at is null
      and candidate.id <> v_product.id
      and (
        (
          v_product.normalized_supplier_sku is not null
          and candidate.normalized_supplier_sku = v_product.normalized_supplier_sku
        )
        or (
          v_product.normalized_supplier_sku is null
          and candidate.normalized_supplier_sku is null
          and candidate.normalized_supplier_description = v_product.normalized_supplier_description
        )
      )
  ) then
    perform public.materials_phase1f_error('supplier_product_restore_identity_conflict');
  end if;

  begin
    update public.organization_material_supplier_products
    set is_active = true,
        is_preferred = false,
        archived_at = null,
        archived_by = null,
        updated_by = v_actor
    where organization_id = v_org and id = v_product.id;
  exception when unique_violation then
    perform public.materials_phase1f_error('supplier_product_restore_identity_conflict');
  end;

  insert into public.organization_material_supplier_product_lifecycle_events (
    organization_id,
    supplier_product_id,
    event_type,
    reason,
    previous_is_active,
    previous_is_preferred,
    actor_user_id,
    metadata
  ) values (
    v_org,
    v_product.id,
    'restored',
    v_reason,
    v_product.is_active,
    v_product.is_preferred,
    v_actor,
    coalesce(p_input->'metadata', '{}'::jsonb)
  );

  return pg_catalog.jsonb_build_object(
    'supplier_product_id', v_product.id,
    'material_id', v_product.material_id,
    'is_active', true,
    'is_preferred', false,
    'archived_at', null,
    'idempotent_replay', false
  );
end;
$$;


ALTER FUNCTION "public"."restore_material_supplier_product"("p_input" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."restore_material_supplier_product"("p_input" "jsonb") IS 'Restores an archived Supplier Product as nonpreferred after checking active identity conflicts.';



CREATE OR REPLACE FUNCTION "public"."restore_task"("p_task_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  actor_user_id uuid := auth.uid();
  old_row public.project_job_todos%rowtype;
  updated_row public.project_job_todos%rowtype;
begin
  old_row := public._task_assert_task_access(p_task_id);

  update public.project_job_todos t
  set
    status = case when t.status = 'Archived' then 'To Do' else t.status end,
    archived_at = null,
    archived_by = null,
    archive_reason = null,
    deleted_at = null,
    deleted_by = null,
    delete_reason = null,
    updated_by = actor_user_id
  where t.id = p_task_id
    and t.organization_id = old_row.organization_id
  returning * into updated_row;

  perform public._write_task_activity(updated_row.organization_id, updated_row.id, updated_row.project_id, actor_user_id, 'restored', null, public._task_to_json(old_row), public._task_to_json(updated_row), '{}'::jsonb);

  return public._task_to_json(updated_row);
end;
$$;


ALTER FUNCTION "public"."restore_task"("p_task_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."retire_purchase_order_line_cost_item"("p_cost_item_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if p_cost_item_id is null then
    return;
  end if;

  update public.cost_items
  set
    status = case when status = 'snapshot' then status else 'deleted' end,
    effective_to = coalesce(effective_to, clock_timestamp()),
    is_current = false,
    source_line_id = null,
    linked_purchase_order_line_item_id = null
  where id = p_cost_item_id
    and source_document_kind = 'project_purchase_order'
    and is_current = true;
end;
$$;


ALTER FUNCTION "public"."retire_purchase_order_line_cost_item"("p_cost_item_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."retry_supplier_invoice_xero_bill_export"("p_organization_id" "uuid", "p_supplier_invoice_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_document public.organization_accounting_documents%rowtype;
  v_job public.organization_accounting_sync_jobs%rowtype;
begin
  if auth.uid() is null
    or not public.has_org_permission(p_organization_id, 'accounting.ap_bills.retry') then
    raise exception 'You do not have permission to retry this Xero export.';
  end if;

  select * into v_document
  from public.organization_accounting_documents
  where organization_id = p_organization_id
    and local_document_type = 'supplier_invoice'
    and local_document_id = p_supplier_invoice_id
    and export_status = 'failed'
    and current_version_id is not null
  for update;
  if not found then
    raise exception 'Only a proven pre-request Xero export failure can be retried.';
  end if;

  select * into v_job
  from public.organization_accounting_sync_jobs
  where organization_id = p_organization_id
    and provider = 'xero'
    and job_kind = 'xero.bill.export'
    and request_payload ->> 'documentVersionId' = v_document.current_version_id::text
    and queue_state = 'dead_lettered'
  order by created_at desc
  limit 1
  for update;
  if not found then
    raise exception 'The failed Xero Bill job is not available for retry.';
  end if;

  update public.organization_accounting_sync_jobs
  set queue_state = 'pending',
      trigger_source = 'user_retry',
      attempt_count = 0,
      available_at = now(),
      retry_after = null,
      claimed_at = null,
      claimed_by = null,
      claim_expires_at = null,
      last_completed_at = null,
      last_error = null,
      result_summary = '{}'::jsonb,
      created_by_user_id = auth.uid()
  where id = v_job.id;

  update public.organization_accounting_documents
  set export_status = 'queued',
      last_error_code = null,
      last_error_message = null
  where id = v_document.id;

  update public.organization_accounting_document_versions
  set status = 'queued',
      request_started_at = null
  where id = v_document.current_version_id
    and status = 'failed';
  if not found then
    raise exception 'The failed Xero Bill version is not available for retry.';
  end if;

  insert into public.supplier_invoice_activity_events (
    organization_id,
    supplier_invoice_id,
    event_type,
    message,
    metadata,
    created_by
  )
  values (
    p_organization_id,
    p_supplier_invoice_id,
    'xero_export_retry_requested',
    'Draft Xero Bill export retry requested.',
    jsonb_build_object(
      'accounting_document_id', v_document.id,
      'accounting_document_version_id', v_document.current_version_id,
      'job_id', v_job.id
    ),
    auth.uid()
  );

  return jsonb_build_object(
    'documentId', v_document.id,
    'versionId', v_document.current_version_id,
    'jobId', v_job.id,
    'status', 'queued'
  );
end;
$$;


ALTER FUNCTION "public"."retry_supplier_invoice_xero_bill_export"("p_organization_id" "uuid", "p_supplier_invoice_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reverse_supplier_invoice_actual_cost_event"("p_organization_id" "uuid", "p_supplier_invoice_id" "uuid", "p_event_id" "uuid", "p_reversal_reason" "text" DEFAULT NULL::"text", "p_reversal_note" "text" DEFAULT NULL::"text") RETURNS TABLE("original_event_id" "uuid", "reversal_event_id" "uuid", "successor_allocation_id" "uuid", "supplier_invoice_id" "uuid", "project_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  original_event public.project_actual_cost_events%rowtype;
  reversal_event public.project_actual_cost_events%rowtype;
  source_allocation public.supplier_invoice_line_allocations%rowtype;
  successor_allocation public.supplier_invoice_line_allocations%rowtype;
  next_allocation_sequence integer;
  successor_review_status text;
  successor_review_reason text;
  normalized_reason text;
  normalized_note text;
  correction_root_id uuid;
begin
  if auth.uid() is null then raise exception 'Authentication is required.'; end if;
  if p_organization_id is null then raise exception 'Organization is required.'; end if;
  if p_supplier_invoice_id is null then raise exception 'Supplier invoice is required.'; end if;
  if p_event_id is null then raise exception 'Actual cost event is required.'; end if;
  if not public.has_org_permission(p_organization_id, 'actual_costs.reverse') then
    raise exception 'You do not have permission to reverse actual costs.';
  end if;

  normalized_reason := nullif(btrim(coalesce(p_reversal_reason, '')), '');
  normalized_note := nullif(btrim(coalesce(p_reversal_note, '')), '');

  if not exists (
    select 1 from public.supplier_invoices invoice
    where invoice.id = p_supplier_invoice_id and invoice.organization_id = p_organization_id
  ) then raise exception 'Supplier invoice not found.'; end if;

  select * into original_event
  from public.project_actual_cost_events event
  where event.id = p_event_id
    and event.organization_id = p_organization_id
    and event.supplier_invoice_id = p_supplier_invoice_id
  for update;

  if not found then raise exception 'Actual cost event not found.'; end if;
  if original_event.event_type <> 'posting' then raise exception 'Only posting actual cost events can be reversed.'; end if;
  if original_event.event_status <> 'posted' then raise exception 'Only posted actual cost events can be reversed.'; end if;
  if original_event.source_type <> 'supplier_invoice' then raise exception 'Only supplier invoice actual cost events can be reversed.'; end if;
  if exists (
    select 1 from public.project_actual_cost_events reversal
    where reversal.organization_id = p_organization_id
      and reversal.event_type = 'reversal'
      and reversal.reverses_event_id = original_event.id
  ) then raise exception 'This actual cost event has already been reversed.'; end if;

  select * into source_allocation
  from public.supplier_invoice_line_allocations allocation
  where allocation.id = coalesce(original_event.source_invoice_allocation_id, original_event.supplier_invoice_line_allocation_id)
    and allocation.organization_id = p_organization_id
    and allocation.supplier_invoice_id = p_supplier_invoice_id
  for update;

  if not found then raise exception 'Source allocation not found for actual cost event.'; end if;
  if source_allocation.project_id is distinct from original_event.project_id then
    raise exception 'Source allocation project does not match the actual cost event.';
  end if;
  if source_allocation.supplier_invoice_line_id is distinct from original_event.supplier_invoice_line_id then
    raise exception 'Source allocation invoice line does not match the actual cost event.';
  end if;

  correction_root_id := coalesce(original_event.correction_root_event_id, original_event.id);

  insert into public.project_actual_cost_events (
    organization_id, supplier_invoice_id, supplier_invoice_line_id,
    supplier_invoice_line_allocation_id, purchase_order_id, purchase_order_line_item_id,
    project_id, supplier_id, cost_item_id, source_cost_item_id,
    tradesstack_cost_code, tradesstack_cost_code_label,
    financial_routing_confidence, financial_routing_source,
    organization_cost_code_id, accounting_mapping_id, accounting_route, accounting_route_mapping_id,
    amount, tax_amount, total_amount, quantity, event_date, event_status, event_type,
    posting_source, reverses_event_id, correction_root_event_id, reversal_reason, reversal_note,
    source_invoice_line_id, source_invoice_allocation_id, source_type, source_reference,
    ai_construction_intelligence, created_by_user_id
  ) values (
    original_event.organization_id, original_event.supplier_invoice_id, original_event.supplier_invoice_line_id,
    source_allocation.id, original_event.purchase_order_id, original_event.purchase_order_line_item_id,
    original_event.project_id, original_event.supplier_id, original_event.cost_item_id, original_event.source_cost_item_id,
    original_event.tradesstack_cost_code, original_event.tradesstack_cost_code_label,
    original_event.financial_routing_confidence, original_event.financial_routing_source,
    original_event.organization_cost_code_id, original_event.accounting_mapping_id,
    original_event.accounting_route, original_event.accounting_route_mapping_id,
    original_event.amount * -1, original_event.tax_amount * -1, original_event.total_amount * -1,
    case when original_event.quantity is null then null else original_event.quantity * -1 end,
    original_event.event_date, 'posted', 'reversal', original_event.posting_source,
    original_event.id, correction_root_id, normalized_reason, normalized_note,
    original_event.source_invoice_line_id, coalesce(original_event.source_invoice_allocation_id, source_allocation.id),
    original_event.source_type, original_event.source_reference,
    original_event.ai_construction_intelligence, auth.uid()
  ) returning * into reversal_event;

  update public.supplier_invoice_line_allocations set edit_state = 'reversed'
  where id = source_allocation.id;

  select coalesce(max(allocation_sequence), 0) + 1 into next_allocation_sequence
  from public.supplier_invoice_line_allocations
  where organization_id = p_organization_id
    and supplier_invoice_line_id = source_allocation.supplier_invoice_line_id
    and purchase_order_line_item_id is not distinct from source_allocation.purchase_order_line_item_id;

  successor_review_status := case
    when source_allocation.accounting_route = 'supplier_bill_expense'
      and (
        source_allocation.accounting_route_mapping_id is not null
        or source_allocation.account_override_organization_cost_code_id is not null
      ) then 'resolved'
    when source_allocation.accounting_mapping_id is not null then 'resolved'
    else 'needs_accounting_mapping'
  end;
  successor_review_reason := case
    when successor_review_status = 'needs_accounting_mapping'
      then coalesce(source_allocation.review_reason, 'missing_accounting_route')
    else source_allocation.review_reason
  end;

  insert into public.supplier_invoice_line_allocations (
    organization_id, supplier_invoice_id, supplier_invoice_line_id,
    purchase_order_id, purchase_order_line_item_id, project_id,
    allocation_group_id, supersedes_allocation_id, allocation_sequence,
    allocated_quantity, allocated_amount, matched_amount,
    cost_item_id, source_cost_item_id,
    tradesstack_cost_code, tradesstack_cost_code_label,
    financial_routing_confidence, financial_routing_source,
    organization_cost_code_id, accounting_mapping_id, accounting_route,
    accounting_route_mapping_id, account_override_organization_cost_code_id,
    accounting_resolution_status,
    accounting_tax_rate_id, tax_resolution_status,
    allocation_status, match_status, review_status, review_reason,
    approval_status, approval_notes, approval_checks_json,
    reviewed_by_user_id, reviewed_at, approved_by_user_id, approved_at,
    allocation_source, ai_suggested_purchase_order_line_item_id, ai_suggested_cost_item_id,
    ai_confidence_score, ai_reasoning_summary, accepted_ai_suggestion,
    ai_suggestion_metadata_json, ai_construction_intelligence, edit_state
  ) values (
    source_allocation.organization_id, source_allocation.supplier_invoice_id, source_allocation.supplier_invoice_line_id,
    source_allocation.purchase_order_id, source_allocation.purchase_order_line_item_id, source_allocation.project_id,
    coalesce(source_allocation.allocation_group_id, source_allocation.id), source_allocation.id, next_allocation_sequence,
    source_allocation.allocated_quantity, source_allocation.allocated_amount, source_allocation.matched_amount,
    source_allocation.cost_item_id, source_allocation.source_cost_item_id,
    source_allocation.tradesstack_cost_code, source_allocation.tradesstack_cost_code_label,
    source_allocation.financial_routing_confidence, source_allocation.financial_routing_source,
    source_allocation.organization_cost_code_id, source_allocation.accounting_mapping_id,
    source_allocation.accounting_route, source_allocation.accounting_route_mapping_id,
    source_allocation.account_override_organization_cost_code_id,
    source_allocation.accounting_resolution_status, source_allocation.accounting_tax_rate_id,
    source_allocation.tax_resolution_status, source_allocation.allocation_status,
    source_allocation.match_status, successor_review_status, successor_review_reason,
    'pending', '', source_allocation.approval_checks_json,
    null, null, null, null, source_allocation.allocation_source,
    source_allocation.ai_suggested_purchase_order_line_item_id, source_allocation.ai_suggested_cost_item_id,
    source_allocation.ai_confidence_score, source_allocation.ai_reasoning_summary,
    source_allocation.accepted_ai_suggestion, source_allocation.ai_suggestion_metadata_json,
    source_allocation.ai_construction_intelligence, 'editable'
  ) returning * into successor_allocation;

  insert into public.supplier_invoice_activity_events (
    organization_id, supplier_invoice_id, event_type, message, metadata, created_by
  ) values
  (
    p_organization_id, p_supplier_invoice_id, 'actual_cost_reversed',
    case when normalized_reason is null then 'Actual cost event reversed.' else format('Actual cost event reversed: %s.', normalized_reason) end,
    jsonb_build_object('original_event_id', original_event.id, 'reversal_event_id', reversal_event.id,
      'source_allocation_id', source_allocation.id, 'reason', normalized_reason, 'note', normalized_note),
    auth.uid()
  ),
  (
    p_organization_id, p_supplier_invoice_id, 'actual_cost_correction_started',
    'Correction draft allocation created from reversed actual cost event.',
    jsonb_build_object('original_event_id', original_event.id, 'reversal_event_id', reversal_event.id,
      'source_allocation_id', source_allocation.id, 'successor_allocation_id', successor_allocation.id,
      'reason', normalized_reason, 'note', normalized_note),
    auth.uid()
  );

  return query select original_event.id, reversal_event.id, successor_allocation.id,
    p_supplier_invoice_id, original_event.project_id;
end;
$$;


ALTER FUNCTION "public"."reverse_supplier_invoice_actual_cost_event"("p_organization_id" "uuid", "p_supplier_invoice_id" "uuid", "p_event_id" "uuid", "p_reversal_reason" "text", "p_reversal_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."review_pricing_worksheet_material_prices"("p_workbook_id" "uuid", "p_active_sheet_id" "uuid" DEFAULT NULL::"uuid", "p_local_bindings" "jsonb" DEFAULT NULL::"jsonb", "p_sheet_id" "uuid" DEFAULT NULL::"uuid", "p_page" integer DEFAULT 1, "p_page_size" integer DEFAULT 20, "p_target_binding_id" "uuid" DEFAULT NULL::"uuid", "p_expected_current_price_id" "uuid" DEFAULT NULL::"uuid", "p_require_write" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_workbook public.opportunity_pricing_worksheets%rowtype;
  v_evaluated_at timestamptz := statement_timestamp();
  v_page integer := greatest(1, coalesce(p_page, 1));
  v_page_size integer := least(50, greatest(1, coalesce(p_page_size, 20)));
  v_org_currency text;
  v_result jsonb;
begin
  select * into v_workbook from public.opportunity_pricing_worksheets workbook
    where workbook.id = p_workbook_id and workbook.archived_at is null;
  if v_workbook.id is null or not public.is_member_of_organization(v_workbook.organization_id) then
    raise exception 'pricing_material_review:invalid_workbook_scope' using errcode = '42501';
  end if;
  if not public.has_org_permission(v_workbook.organization_id, 'materials.view') then
    raise exception 'pricing_material_review:materials_view_permission_required' using errcode = '42501';
  end if;
  if p_require_write and not public.can_write_pricing_workbook_owner(
    v_workbook.organization_id, v_workbook.opportunity_id, v_workbook.project_id,
    v_workbook.quote_id, v_workbook.variation_id
  ) then raise exception 'pricing_material_review:workbook_write_permission_required' using errcode = '42501'; end if;
  if p_sheet_id is not null and not exists (select 1 from public.opportunity_pricing_workbook_sheets sheet
    where sheet.organization_id = v_workbook.organization_id and sheet.workbook_id = v_workbook.id and sheet.id = p_sheet_id)
  then raise exception 'pricing_material_review:invalid_sheet_scope' using errcode = '42501'; end if;
  select public.resolve_material_estimating_currency(to_jsonb(organization)) into v_org_currency
    from public.organizations organization where organization.id = v_workbook.organization_id;

  if p_local_bindings is not null then
    if p_active_sheet_id is null or jsonb_typeof(p_local_bindings) <> 'array'
      or not exists (select 1 from public.opportunity_pricing_workbook_sheets sheet
        where sheet.organization_id = v_workbook.organization_id and sheet.workbook_id = v_workbook.id and sheet.id = p_active_sheet_id)
    then raise exception 'pricing_material_review:invalid_overlay_scope' using errcode = '22023'; end if;
    if exists (select 1 from jsonb_array_elements(p_local_bindings) entry group by entry->>'bindingId' having count(*) > 1)
      or exists (select 1 from jsonb_array_elements(p_local_bindings) entry group by entry->>'cellAddress' having count(*) > 1)
    then raise exception 'pricing_material_review:duplicate_overlay_binding' using errcode = '22023'; end if;
    if exists (select 1 from jsonb_array_elements(p_local_bindings) entry
      where jsonb_typeof(entry->'value') <> 'number' or entry->>'type' <> 'number'
        or coalesce(jsonb_typeof(entry->'formula'), 'null') <> 'null'
        or coalesce(entry->>'cellAddress','') !~ '^[A-Z]+[1-9][0-9]*$'
        or entry->>'bindingId' is distinct from entry #>> '{provenance,bindingId}'
	        or public.validate_worksheet_material_pricing_evidence(
	          v_workbook.organization_id, (entry->>'value')::numeric, entry->'provenance'
	        ) is not true
        or exists (select 1 from public.worksheet_material_price_bindings existing
          where existing.id = (entry->>'bindingId')::uuid
            and (existing.organization_id <> v_workbook.organization_id
              or existing.workbook_id <> v_workbook.id or existing.sheet_id <> p_active_sheet_id)))
    then raise exception 'pricing_material_review:forged_overlay_binding' using errcode = '42501'; end if;
  elsif p_active_sheet_id is not null then
    raise exception 'pricing_material_review:overlay_required_for_active_sheet' using errcode = '22023';
  end if;

  with source_bindings as materialized (
    select binding.id as binding_id, binding.sheet_id, sheet.name as sheet_name,
      binding.current_cell_address as cell_address, binding.organization_material_id as material_id,
      binding.supplier_id, binding.supplier_product_id, binding.supplier_price_id,
      binding.inserted_unit_cost, binding.unit_snapshot, binding.currency_snapshot,
      binding.source_tax_basis_snapshot, binding.source_tax_rate_snapshot,
      binding.tax_jurisdiction_code_snapshot, binding.material_name_snapshot,
      binding.supplier_name_snapshot, binding.supplier_product_description_snapshot,
      binding.supplier_sku_snapshot, binding.price_effective_from,
      binding.effective_price_evaluated_at, binding.provenance_version,
      binding.pricing_derivation_kind, binding.worksheet_rate_snapshot,
      binding.worksheet_unit_snapshot, binding.normalized_source_unit_cost_snapshot,
      binding.comparison_tax_basis_snapshot, binding.comparison_tax_rate_snapshot,
      binding.calculation_version, binding.unit_conversion_id,
      binding.conversion_supplier_quantity_snapshot, binding.conversion_supplier_unit_snapshot,
      binding.conversion_material_quantity_snapshot, binding.conversion_material_unit_snapshot,
      binding.conversion_contract_version_snapshot, binding.conversion_source_snapshot,
      binding.conversion_effective_from_snapshot, binding.conversion_confirmed_at_snapshot
    from public.worksheet_material_price_bindings binding
    join public.opportunity_pricing_workbook_sheets sheet on sheet.organization_id = binding.organization_id
      and sheet.workbook_id = binding.workbook_id and sheet.id = binding.sheet_id
    where binding.organization_id = v_workbook.organization_id and binding.workbook_id = v_workbook.id
      and binding.binding_state = 'active' and (p_local_bindings is null or binding.sheet_id <> p_active_sheet_id)
    union all
    select (entry->>'bindingId')::uuid, p_active_sheet_id, sheet.name, entry->>'cellAddress',
      (entry #>> '{provenance,organizationMaterialId}')::uuid,
      (entry #>> '{provenance,supplierId}')::uuid, (entry #>> '{provenance,supplierProductId}')::uuid,
      coalesce(entry #>> '{provenance,supplierPriceId}', entry #>> '{provenance,sourcePricing,supplierPriceId}')::uuid,
      coalesce(entry #>> '{provenance,snapshot,unitCost}', entry #>> '{provenance,sourcePricing,unitCost}')::numeric,
      coalesce(entry #>> '{provenance,snapshot,unit}', entry #>> '{provenance,sourcePricing,unit}'),
      coalesce(entry #>> '{provenance,snapshot,currency}', entry #>> '{provenance,sourcePricing,currency}'),
      coalesce(entry #>> '{provenance,snapshot,sourceTaxBasis}', entry #>> '{provenance,sourcePricing,sourceTaxBasis}'),
      coalesce(entry #>> '{provenance,snapshot,sourceTaxRate}', entry #>> '{provenance,sourcePricing,sourceTaxRate}')::numeric,
      coalesce(entry #>> '{provenance,snapshot,taxJurisdictionCode}', entry #>> '{provenance,sourcePricing,taxJurisdictionCode}'),
      coalesce(entry #>> '{provenance,snapshot,materialName}', entry #>> '{provenance,labels,materialName}'),
      coalesce(entry #>> '{provenance,snapshot,supplierName}', entry #>> '{provenance,labels,supplierName}'),
      coalesce(entry #>> '{provenance,snapshot,supplierProductDescription}', entry #>> '{provenance,labels,supplierProductDescription}'),
      coalesce(entry #>> '{provenance,snapshot,supplierSku}', entry #>> '{provenance,labels,supplierSku}'),
      coalesce(entry #>> '{provenance,snapshot,priceEffectiveFrom}', entry #>> '{provenance,sourcePricing,priceEffectiveFrom}')::timestamptz,
      coalesce(entry #>> '{provenance,snapshot,evaluatedAt}', entry #>> '{provenance,estimatingPricing,evaluatedAt}')::timestamptz,
      (entry #>> '{provenance,version}')::smallint, entry #>> '{provenance,estimatingPricing,derivationKind}',
      (entry #>> '{provenance,estimatingPricing,unitCost}')::numeric, entry #>> '{provenance,estimatingPricing,unit}',
      (entry #>> '{provenance,estimatingPricing,normalizedSourceUnitCost}')::numeric,
      entry #>> '{provenance,sourcePricing,comparisonTaxBasis}',
      (entry #>> '{provenance,sourcePricing,comparisonTaxRate}')::numeric,
      entry #>> '{provenance,estimatingPricing,calculationVersion}',
      nullif(entry #>> '{provenance,conversion,conversionId}', '')::uuid,
      (entry #>> '{provenance,conversion,supplierQuantity}')::numeric,
      entry #>> '{provenance,conversion,supplierUnit}',
      (entry #>> '{provenance,conversion,materialQuantity}')::numeric,
      entry #>> '{provenance,conversion,materialUnit}', entry #>> '{provenance,conversion,contractVersion}',
      entry #>> '{provenance,conversion,confirmationSource}',
      (entry #>> '{provenance,conversion,effectiveFrom}')::timestamptz,
      (entry #>> '{provenance,conversion,confirmedAt}')::timestamptz
    from jsonb_array_elements(coalesce(p_local_bindings, '[]'::jsonb)) entry
    join public.opportunity_pricing_workbook_sheets sheet on sheet.organization_id = v_workbook.organization_id
      and sheet.workbook_id = v_workbook.id and sheet.id = p_active_sheet_id
  ), scoped as materialized (
    select * from source_bindings source where (p_sheet_id is null or source.sheet_id = p_sheet_id)
      and (p_target_binding_id is null or source.binding_id = p_target_binding_id)
  ), product_ids as materialized (
    select array_agg(distinct supplier_product_id) ids from scoped
  ), effective_prices as materialized (
    select resolved.supplier_product_id, resolved.price_id from product_ids products
    cross join lateral public.resolve_material_supplier_product_prices(
      v_workbook.organization_id, v_evaluated_at, products.ids
    ) resolved where coalesce(cardinality(products.ids),0) > 0
  ), enriched as materialized (
    select scoped.*, material.id as live_material_id, material.default_unit as current_material_unit,
      material.is_active as material_is_active, material.archived_at as material_archived_at,
      supplier.id as live_supplier_id, supplier.is_active as supplier_is_active,
      product.id as live_product_id, product.is_active as product_is_active, product.archived_at as product_archived_at,
      price.id as current_price_id, price.unit_cost as current_unit_cost, price.unit as current_unit,
      price.currency as current_currency, price.source_tax_basis as current_tax_basis,
      price.source_tax_rate as current_tax_rate, price.tax_jurisdiction_code as current_tax_jurisdiction,
      price.comparison_tax_basis as current_comparison_tax_basis,
      price.comparison_tax_rate as current_comparison_tax_rate, price.tax_policy_snapshot as current_tax_policy_snapshot,
      price.effective_from as current_effective_from,
      conversion.id as current_conversion_id, conversion.supplier_quantity as current_conversion_supplier_quantity,
      conversion.supplier_unit as current_conversion_supplier_unit,
      conversion.material_quantity as current_conversion_material_quantity,
      conversion.material_unit as current_conversion_material_unit,
      conversion.source as current_conversion_source, conversion.contract_version as current_conversion_contract_version,
      conversion.effective_from as current_conversion_effective_from,
      conversion.confirmed_at as current_conversion_confirmed_at
    from scoped
    left join public.organization_materials material on material.organization_id = v_workbook.organization_id and material.id = scoped.material_id
    left join public.organization_suppliers supplier on supplier.organization_id = v_workbook.organization_id and supplier.id = scoped.supplier_id
    left join public.organization_material_supplier_products product on product.organization_id = v_workbook.organization_id and product.id = scoped.supplier_product_id
    left join effective_prices effective on effective.supplier_product_id = scoped.supplier_product_id
    left join public.organization_material_supplier_prices price on price.organization_id = v_workbook.organization_id and price.id = effective.price_id
    left join public.organization_material_supplier_product_unit_conversions conversion
      on conversion.organization_id = v_workbook.organization_id and conversion.supplier_product_id = scoped.supplier_product_id
      and public.normalize_material_estimating_unit(conversion.supplier_unit) = public.normalize_material_estimating_unit(price.unit)
      and public.normalize_material_estimating_unit(conversion.material_unit) = public.normalize_material_estimating_unit(material.default_unit)
      and conversion.effective_from <= v_evaluated_at and (conversion.effective_to is null or conversion.effective_to > v_evaluated_at)
  ), derived as materialized (
    select enriched.*, case when current_price_id is null then null else public.derive_material_estimating_price(
      current_price_id, current_unit_cost, current_unit, current_currency, current_tax_basis,
      current_tax_rate, current_tax_jurisdiction, current_comparison_tax_basis, current_comparison_tax_rate,
      current_tax_policy_snapshot, current_effective_from, current_material_unit, v_org_currency, v_evaluated_at,
      current_conversion_id, current_conversion_supplier_quantity, current_conversion_supplier_unit,
      current_conversion_material_quantity, current_conversion_material_unit, current_conversion_source,
      current_conversion_contract_version, current_conversion_effective_from, current_conversion_confirmed_at
    ) end current_pricing,
    case when provenance_version = 2 then jsonb_build_object(
      'sourcePricing', jsonb_build_object('supplierPriceId', supplier_price_id, 'unitCost', inserted_unit_cost,
        'unit', unit_snapshot, 'currency', currency_snapshot, 'sourceTaxBasis', source_tax_basis_snapshot,
        'sourceTaxRate', source_tax_rate_snapshot, 'taxJurisdictionCode', tax_jurisdiction_code_snapshot,
        'comparisonTaxBasis', comparison_tax_basis_snapshot, 'comparisonTaxRate', comparison_tax_rate_snapshot,
        'effectiveFrom', price_effective_from),
      'estimatingPricing', jsonb_build_object('status','available','derivationKind',pricing_derivation_kind,
        'normalizedSourceUnitCost',normalized_source_unit_cost_snapshot,'unitCost',worksheet_rate_snapshot,
        'unit',worksheet_unit_snapshot,'currency',currency_snapshot,'taxBasis',comparison_tax_basis_snapshot,
        'calculationVersion',calculation_version,'evaluatedAt',effective_price_evaluated_at),
      'conversion', case when unit_conversion_id is null then null else jsonb_build_object(
        'conversionId',unit_conversion_id,'supplierQuantity',conversion_supplier_quantity_snapshot,
        'supplierUnit',conversion_supplier_unit_snapshot,'materialQuantity',conversion_material_quantity_snapshot,
        'materialUnit',conversion_material_unit_snapshot,'confirmationSource',conversion_source_snapshot,
        'contractVersion',conversion_contract_version_snapshot,'effectiveFrom',conversion_effective_from_snapshot,
        'confirmedAt',conversion_confirmed_at_snapshot) end
    ) else null end historical_pricing
    from enriched
  ), classified as materialized (
    select derived.*,
      case
        when live_material_id is null or live_supplier_id is null or live_product_id is null then 'source_unavailable'
        when not material_is_active or material_archived_at is not null or not supplier_is_active
          or not product_is_active or product_archived_at is not null then 'source_inactive'
        when current_price_id is null then 'no_current_price'
        when provenance_version = 1 and public.normalize_material_estimating_unit(unit_snapshot)
          <> public.normalize_material_estimating_unit(current_material_unit)
          and current_pricing #>> '{estimatingPricing,status}' = 'available' then 'estimating_unit_mismatch'
        when provenance_version = 1 and current_price_id = supplier_price_id then 'current'
        when provenance_version = 1 and (public.normalize_material_estimating_unit(unit_snapshot)
          <> public.normalize_material_estimating_unit(current_unit) or upper(currency_snapshot) <> upper(current_currency)
          or source_tax_basis_snapshot <> current_tax_basis or source_tax_rate_snapshot is distinct from current_tax_rate
          or tax_jurisdiction_code_snapshot is distinct from current_tax_jurisdiction) then 'commercial_terms_changed'
        when provenance_version = 1 and inserted_unit_cost = current_unit_cost then 'version_changed_same_terms'
        when provenance_version = 1 then 'price_changed'
        when public.normalize_material_estimating_unit(worksheet_unit_snapshot)
          <> public.normalize_material_estimating_unit(current_material_unit) then 'commercial_terms_changed'
        when current_pricing #>> '{estimatingPricing,status}' = 'conversion_required' then 'conversion_unavailable'
        when current_pricing #>> '{estimatingPricing,status}' <> 'available' then 'commercial_terms_changed'
        when public.normalize_material_estimating_unit(unit_snapshot) <> public.normalize_material_estimating_unit(current_unit)
          or upper(currency_snapshot) <> upper(current_currency) or source_tax_basis_snapshot <> current_tax_basis
          or source_tax_rate_snapshot is distinct from current_tax_rate
          or tax_jurisdiction_code_snapshot is distinct from current_tax_jurisdiction
          or comparison_tax_basis_snapshot is distinct from current_comparison_tax_basis
          or comparison_tax_rate_snapshot is distinct from current_comparison_tax_rate then 'commercial_terms_changed'
        when inserted_unit_cost = current_unit_cost and (
          (pricing_derivation_kind = 'direct_unit_match' and current_pricing #>> '{estimatingPricing,derivationKind}' = 'direct_unit_match')
          or (pricing_derivation_kind = 'confirmed_conversion'
            and conversion_supplier_quantity_snapshot = current_conversion_supplier_quantity
            and public.normalize_material_estimating_unit(conversion_supplier_unit_snapshot) = public.normalize_material_estimating_unit(current_conversion_supplier_unit)
            and conversion_material_quantity_snapshot = current_conversion_material_quantity
            and public.normalize_material_estimating_unit(conversion_material_unit_snapshot) = public.normalize_material_estimating_unit(current_conversion_material_unit))
        ) and abs(worksheet_rate_snapshot - (current_pricing #>> '{estimatingPricing,unitCost}')::numeric) <= 0.0000000001
          then case when current_price_id = supplier_price_id and unit_conversion_id is not distinct from current_conversion_id
            then 'current' else 'version_changed_same_terms' end
        when inserted_unit_cost <> current_unit_cost and (
          (pricing_derivation_kind = 'direct_unit_match' and current_pricing #>> '{estimatingPricing,derivationKind}' = 'direct_unit_match')
          or (conversion_supplier_quantity_snapshot = current_conversion_supplier_quantity
            and public.normalize_material_estimating_unit(conversion_supplier_unit_snapshot) = public.normalize_material_estimating_unit(current_conversion_supplier_unit)
            and conversion_material_quantity_snapshot = current_conversion_material_quantity
            and public.normalize_material_estimating_unit(conversion_material_unit_snapshot) = public.normalize_material_estimating_unit(current_conversion_material_unit))
        ) then 'price_changed'
        when inserted_unit_cost = current_unit_cost then 'conversion_changed'
        else 'price_and_conversion_changed'
      end classification
    from derived
  ), grouped as materialized (
    select supplier_product_id::text || ':' || supplier_price_id::text || ':' || classification as group_key,
      classification, provenance_version, material_id, material_name_snapshot, supplier_id, supplier_name_snapshot,
      supplier_product_id, supplier_product_description_snapshot, supplier_sku_snapshot,
      supplier_price_id, inserted_unit_cost, unit_snapshot, currency_snapshot, source_tax_basis_snapshot,
      source_tax_rate_snapshot, tax_jurisdiction_code_snapshot, price_effective_from, effective_price_evaluated_at,
      current_price_id, current_unit_cost, current_unit, current_currency, current_tax_basis, current_tax_rate,
      current_tax_jurisdiction, current_effective_from, historical_pricing, current_pricing,
      case when classification = 'price_changed' then
        case when provenance_version = 2 then (current_pricing #>> '{estimatingPricing,unitCost}')::numeric - worksheet_rate_snapshot
          else current_unit_cost - inserted_unit_cost end else null end absolute_difference,
      case when classification = 'price_changed' then
        case when provenance_version = 2 and worksheet_rate_snapshot <> 0 then
          (((current_pricing #>> '{estimatingPricing,unitCost}')::numeric - worksheet_rate_snapshot) / worksheet_rate_snapshot) * 100
        when provenance_version = 1 and inserted_unit_cost <> 0 then ((current_unit_cost-inserted_unit_cost)/inserted_unit_cost)*100 else null end
      else null end percentage_difference,
      array_remove(array[
        case when classification = 'commercial_terms_changed' and public.normalize_material_estimating_unit(worksheet_unit_snapshot) <> public.normalize_material_estimating_unit(current_material_unit) then 'estimating_unit' end,
        case when classification in ('conversion_changed','price_and_conversion_changed','conversion_unavailable') then 'conversion' end
      ],null) reason_codes,
      jsonb_agg(jsonb_build_object('bindingId',binding_id,'sheetId',sheet_id,'sheetName',sheet_name,'cellAddress',cell_address)
        order by lower(sheet_name),cell_address,binding_id) targets
    from classified group by classification, provenance_version, material_id, material_name_snapshot, supplier_id,
      supplier_name_snapshot, supplier_product_id, supplier_product_description_snapshot, supplier_sku_snapshot,
      supplier_price_id, inserted_unit_cost, unit_snapshot, currency_snapshot, source_tax_basis_snapshot,
      source_tax_rate_snapshot, tax_jurisdiction_code_snapshot, price_effective_from, effective_price_evaluated_at,
      current_price_id,current_unit_cost,current_unit,current_currency,current_tax_basis,current_tax_rate,
      current_tax_jurisdiction,current_effective_from,historical_pricing,current_pricing,worksheet_rate_snapshot,
      worksheet_unit_snapshot,current_material_unit
  ), visible as materialized (
    select *, count(*) over () visible_total from grouped
    where classification not in ('current','version_changed_same_terms')
    order by case classification when 'price_changed' then 0 when 'estimating_unit_mismatch' then 1 else 2 end,
      lower(material_name_snapshot),lower(supplier_name_snapshot),group_key
  ), paged as materialized (
    select * from visible limit v_page_size offset ((v_page-1)*v_page_size)
  ), summary as (
    select count(*) filter (where classification in ('price_changed','estimating_unit_mismatch'))::integer price_updates,
      count(*) filter (where classification in ('commercial_terms_changed','conversion_changed','price_and_conversion_changed',
        'conversion_unavailable','no_current_price','source_inactive','source_unavailable','invalid_binding'))::integer needs_review,
      count(*) filter (where classification='current')::integer current_count,
      count(*) filter (where classification='version_changed_same_terms')::integer same_terms_count from grouped
  )
  select jsonb_build_object(
    'items',coalesce((select jsonb_agg(jsonb_build_object(
      'groupKey',group_key,'classification',classification,'reasonCodes',to_jsonb(reason_codes),
      'provenanceVersion',provenance_version,'materialId',material_id,'materialName',material_name_snapshot,
      'supplierId',supplier_id,'supplierName',supplier_name_snapshot,'supplierProductId',supplier_product_id,
      'supplierProductDescription',supplier_product_description_snapshot,'supplierSku',supplier_sku_snapshot,
      'historicalPrice',jsonb_build_object('id',supplier_price_id,'unitCost',inserted_unit_cost,'unit',unit_snapshot,
        'currency',currency_snapshot,'sourceTaxBasis',source_tax_basis_snapshot,'sourceTaxRate',source_tax_rate_snapshot,
        'taxJurisdictionCode',tax_jurisdiction_code_snapshot,'effectiveFrom',price_effective_from,'evaluatedAt',effective_price_evaluated_at),
      'currentPrice',case when current_price_id is null then null else jsonb_build_object('id',current_price_id,
        'unitCost',current_unit_cost,'unit',current_unit,'currency',current_currency,'sourceTaxBasis',current_tax_basis,
        'sourceTaxRate',current_tax_rate,'taxJurisdictionCode',current_tax_jurisdiction,
        'effectiveFrom',current_effective_from,'evaluatedAt',v_evaluated_at) end,
      'historicalPricing',historical_pricing,'currentPricing',current_pricing,
      'absoluteDifference',absolute_difference,'percentageDifference',percentage_difference,'targets',targets
    ) order by lower(material_name_snapshot),lower(supplier_name_snapshot),group_key) from paged),'[]'::jsonb),
    'summary',jsonb_build_object('priceUpdates',coalesce(summary.price_updates,0),'needsReview',coalesce(summary.needs_review,0),
      'current',coalesce(summary.current_count,0),'versionChangedSameTerms',coalesce(summary.same_terms_count,0)),
    'page',v_page,'pageSize',v_page_size,'total',coalesce((select max(visible_total) from visible),0),
    'hasMore',coalesce((select max(visible_total) from visible),0)>v_page*v_page_size,'evaluatedAt',v_evaluated_at
  ) into v_result from summary;

  if p_target_binding_id is not null then
    if jsonb_array_length(v_result->'items') <> 1
      or v_result #>> '{items,0,classification}' not in ('price_changed','estimating_unit_mismatch')
      or (p_expected_current_price_id is not null and v_result #>> '{items,0,currentPrice,id}' <> p_expected_current_price_id::text)
    then raise exception 'pricing_material_review:stale_update' using errcode = '40001'; end if;
  end if;
  return v_result;
end;
$_$;


ALTER FUNCTION "public"."review_pricing_worksheet_material_prices"("p_workbook_id" "uuid", "p_active_sheet_id" "uuid", "p_local_bindings" "jsonb", "p_sheet_id" "uuid", "p_page" integer, "p_page_size" integer, "p_target_binding_id" "uuid", "p_expected_current_price_id" "uuid", "p_require_write" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."review_pricing_worksheet_material_prices"("p_workbook_id" "uuid", "p_active_sheet_id" "uuid", "p_local_bindings" "jsonb", "p_sheet_id" "uuid", "p_page" integer, "p_page_size" integer, "p_target_binding_id" "uuid", "p_expected_current_price_id" "uuid", "p_require_write" boolean) IS 'Set-oriented V1/V2 Material pricing review with conversion-aware classification and validated dirty-sheet evidence.';



CREATE OR REPLACE FUNCTION "public"."rollup_supplier_invoice_status_from_matches"("p_organization_id" "uuid", "p_supplier_invoice_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  active_match_count integer := 0;
  disputed_match_count integer := 0;
  approved_allocation_total numeric := 0;
  invoice_total numeric := 0;
  current_status text;
  next_status text;
  can_review boolean := false;
begin
  select
    si.status,
    coalesce(si.total, 0)
  into current_status, invoice_total
  from public.supplier_invoices si
  where si.id = p_supplier_invoice_id
    and si.organization_id = p_organization_id;

  if current_status is null then
    return;
  end if;

  select
    count(*) filter (where match_status in ('accepted', 'adjusted')),
    count(*) filter (
      where match_status in ('accepted', 'adjusted')
        and approval_status = 'disputed'
    ),
    coalesce(
      sum(
        case
          when match_status in ('accepted', 'adjusted')
            and approval_status = 'approved'
          then matched_amount
          else 0
        end
      ),
      0
    )
  into active_match_count, disputed_match_count, approved_allocation_total
  from public.supplier_invoice_purchase_order_matches
  where supplier_invoice_id = p_supplier_invoice_id
    and organization_id = p_organization_id;

  can_review := public.has_org_permission(p_organization_id, 'supplier_invoices.review');

  if active_match_count = 0 then
    if current_status in ('Approved', 'Disputed') then
      next_status := 'Needs Review';
    else
      next_status := current_status;
    end if;
  elsif disputed_match_count > 0 then
    next_status := 'Disputed';
  elsif approved_allocation_total >= invoice_total - 0.0001 then
    next_status := 'Approved';
  else
    next_status := 'Needs Review';
  end if;

  if next_status in ('Approved', 'Disputed') and not can_review then
    next_status := 'Needs Review';
  end if;

  if next_status is distinct from current_status then
    update public.supplier_invoices
    set status = next_status
    where id = p_supplier_invoice_id
      and organization_id = p_organization_id;
  end if;
end;
$$;


ALTER FUNCTION "public"."rollup_supplier_invoice_status_from_matches"("p_organization_id" "uuid", "p_supplier_invoice_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."run_organization_memory_derivation"("p_input" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  resolved_organization_id uuid;
  resolved_limit integer := 500;
  module_cost_item_count integer := 0;
  module_cost_item_superseded integer := 0;
  module_cost_code_count integer := 0;
  module_cost_code_superseded integer := 0;
  module_worksheet_count integer := 0;
  module_worksheet_superseded integer := 0;
  module_supplier_invoice_count integer := 0;
  module_supplier_invoice_superseded integer := 0;
  module_takeoff_count integer := 0;
  module_takeoff_superseded integer := 0;
  candidate record;
  memory_item_id uuid;
  source_event_id uuid;
  pattern_note text;
begin
  if p_input is not null and jsonb_typeof(p_input) <> 'object' then
    raise exception 'run_organization_memory_derivation requires a JSON object payload';
  end if;

  perform public._organization_memory_assert_platform_admin('admin');

  resolved_organization_id := nullif(p_input->>'organizationId', '')::uuid;
  if resolved_organization_id is not null then
    perform public._organization_memory_assert_organization_exists(resolved_organization_id);
  end if;

  resolved_limit := greatest(coalesce(nullif(p_input->>'patternLimit', '')::integer, 500), 1);

  for candidate in
    with base as (
      select
        e.organization_id,
        nullif(btrim(coalesce(e.metadata->>'workbookId', e.metadata->>'worksheetId', '')), '') as workbook_id,
        nullif(btrim(coalesce(e.metadata->>'sheetId', e.entity_id::text, '')), '') as sheet_id,
        nullif(btrim(coalesce(e.metadata->>'sheetName', e.metadata->>'worksheetName', '')), '') as sheet_name,
        nullif(btrim(coalesce(e.metadata->>'worksheetName', '')), '') as worksheet_name,
        nullif(btrim(coalesce(e.metadata->>'tradePackage', '')), '') as trade_package,
        coalesce(nullif(e.metadata->'structureSummary'->>'rowCount', '')::integer, 0) as row_count,
        coalesce(nullif(e.metadata->'structureSummary'->>'columnCount', '')::integer, 0) as column_count,
        coalesce(nullif(e.metadata->'structureSummary'->>'formulaCount', '')::integer, 0) as formula_count,
        coalesce(nullif(e.metadata->'structureSummary'->>'populatedCellCount', '')::integer, 0) as populated_cell_count,
        e.entity_id as worksheet_entity_id,
        e.id as event_id
      from public.intelligence_events e
      where e.module = 'pricing_worksheets'
        and e.event_type = 'worksheet_saved'
        and (resolved_organization_id is null or e.organization_id = resolved_organization_id)
    ),
    filtered as (
      select
        b.*,
        concat_ws(
          '|',
          'workbookId=' || lower(coalesce(b.workbook_id, 'unknown')),
          'sheetId=' || lower(coalesce(b.sheet_id, 'unknown')),
          'tradePackage=' || lower(coalesce(b.trade_package, 'none'))
        ) as pattern_scope_key,
        concat_ws(
          '|',
          'rowCount=' || b.row_count::text,
          'columnCount=' || b.column_count::text,
          'formulaCount=' || b.formula_count::text,
          'populatedCellCount=' || b.populated_cell_count::text
        ) as target_signature
      from base b
      where b.sheet_id is not null
        and b.row_count > 0
        and b.column_count > 0
    ),
    aggregated as (
      select
        f.organization_id,
        f.pattern_scope_key,
        f.target_signature,
        min(f.workbook_id) as workbook_id,
        min(f.sheet_id) as sheet_id,
        min(f.sheet_name) as sheet_name,
        min(f.worksheet_name) as worksheet_name,
        min(f.trade_package) as trade_package,
        min(f.row_count) as row_count,
        min(f.column_count) as column_count,
        min(f.formula_count) as formula_count,
        min(f.populated_cell_count) as populated_cell_count,
        count(*)::integer as save_count,
        count(distinct f.sheet_id)::integer as distinct_sheet_count,
        array_agg(f.event_id order by f.event_id) as source_event_ids
      from filtered f
      group by f.organization_id, f.pattern_scope_key, f.target_signature
    ),
    ranked as (
      select
        a.*,
        sum(a.save_count) over (partition by a.organization_id, a.pattern_scope_key) as total_save_count,
        count(*) over (partition by a.organization_id, a.pattern_scope_key) as distinct_structure_count,
        row_number() over (
          partition by a.organization_id, a.pattern_scope_key
          order by a.save_count desc, a.target_signature asc
        ) as pattern_rank
      from aggregated a
    )
    select
      r.*,
      (r.save_count::numeric / nullif(r.total_save_count, 0)) as dominance_ratio
    from ranked r
    where r.pattern_rank = 1
      and r.save_count >= 2
      and (r.save_count::numeric / nullif(r.total_save_count, 0)) >= 0.60
    order by r.save_count desc, r.pattern_scope_key asc
    limit resolved_limit
  loop
    pattern_note := 'Derived from repeated worksheet saves with the same compact structure signature.';

    memory_item_id := public._organization_memory_upsert_derived_item(
      candidate.organization_id,
      'worksheet_structure',
      'pricing_worksheet_layout',
      candidate.pattern_scope_key || '|' || candidate.target_signature,
      candidate.worksheet_name || ': preferred worksheet structure',
      'Repeated worksheet saves indicate this organization reuses a common structure for '
        || candidate.worksheet_name
        || case when candidate.trade_package is not null then ' (' || candidate.trade_package || ')' else '' end
        || '.',
      jsonb_build_object(
        'patternScopeKey', candidate.pattern_scope_key,
        'workbookId', candidate.workbook_id,
        'sheetId', candidate.sheet_id,
        'sheetName', candidate.sheet_name,
        'worksheetName', candidate.worksheet_name,
        'tradePackage', candidate.trade_package,
        'rowCount', candidate.row_count,
        'columnCount', candidate.column_count,
        'formulaCount', candidate.formula_count,
        'populatedCellCount', candidate.populated_cell_count
      ),
      jsonb_build_object(
        'sourceType', 'intelligence_events',
        'sourceEventType', 'worksheet_saved',
        'saveCount', candidate.save_count,
        'distinctSheetCount', candidate.distinct_sheet_count,
        'totalSaveCount', candidate.total_save_count,
        'distinctStructureCount', candidate.distinct_structure_count,
        'dominanceRatio', round(candidate.dominance_ratio, 4)
      ),
      public._organization_memory_confidence_from_signal(candidate.save_count, candidate.dominance_ratio),
      'financial_sensitive',
      'organization'
    );

    foreach source_event_id in array candidate.source_event_ids
    loop
      perform public.link_organization_memory_evidence(jsonb_build_object(
        'organizationId', candidate.organization_id,
        'organizationMemoryItemId', memory_item_id,
        'sourceEventId', source_event_id,
        'linkType', 'supporting',
        'note', pattern_note
      ));
    end loop;

    module_worksheet_superseded := module_worksheet_superseded + public._organization_memory_mark_superseded_conflicts(
      candidate.organization_id,
      'worksheet_structure',
      'pricing_worksheet_layout',
      candidate.pattern_scope_key,
      memory_item_id,
      'Superseded by a stronger repeated worksheet structure pattern.'
    );
    module_worksheet_count := module_worksheet_count + 1;
  end loop;

  for candidate in
    with base as (
      select
        e.organization_id,
        nullif(coalesce(e.after_data->>'supplierInvoiceId', e.before_data->>'supplierInvoiceId', e.metadata->>'supplierInvoiceId', ''), '')::uuid as supplier_invoice_id,
        nullif(coalesce(e.after_data->>'purchaseOrderId', e.before_data->>'purchaseOrderId', ''), '')::uuid as purchase_order_id,
        case
          when e.event_type = 'supplier_invoice_match_confirmed' then 'confirmed'
          when e.event_type = 'supplier_invoice_match_rejected' then 'rejected'
          else null
        end as disposition,
        coalesce(
          nullif(e.after_data->>'confidenceScore', '')::numeric,
          nullif(e.before_data->>'confidenceScore', '')::numeric
        ) as confidence_score,
        e.id as event_id
      from public.intelligence_events e
      where e.module = 'supplier_invoices'
        and e.event_type in ('supplier_invoice_match_confirmed', 'supplier_invoice_match_rejected')
        and (resolved_organization_id is null or e.organization_id = resolved_organization_id)
    ),
    joined as (
      select
        b.organization_id,
        si.supplier_id,
        b.supplier_invoice_id,
        b.purchase_order_id,
        b.disposition,
        b.confidence_score,
        b.event_id
      from base b
      join public.supplier_invoices si
        on si.id = b.supplier_invoice_id
       and si.organization_id = b.organization_id
      where b.purchase_order_id is not null
        and b.disposition is not null
    ),
    filtered as (
      select
        j.*,
        concat_ws(
          '|',
          'supplierId=' || j.supplier_id::text,
          'purchaseOrderId=' || j.purchase_order_id::text
        ) as pattern_scope_key,
        'disposition=' || j.disposition as target_signature
      from joined j
    ),
    aggregated as (
      select
        f.organization_id,
        f.pattern_scope_key,
        f.target_signature,
        (array_agg(f.supplier_id order by f.supplier_id))[1] as supplier_id,
        (array_agg(f.purchase_order_id order by f.purchase_order_id))[1] as purchase_order_id,
        min(f.disposition) as disposition,
        count(*)::integer as evidence_count,
        count(distinct f.supplier_invoice_id)::integer as distinct_invoice_count,
        avg(f.confidence_score) as avg_confidence_score,
        array_agg(f.event_id order by f.event_id) as source_event_ids
      from filtered f
      group by f.organization_id, f.pattern_scope_key, f.target_signature
    ),
    ranked as (
      select
        a.*,
        sum(a.evidence_count) over (partition by a.organization_id, a.pattern_scope_key) as total_evidence_count,
        count(*) over (partition by a.organization_id, a.pattern_scope_key) as distinct_disposition_count,
        row_number() over (
          partition by a.organization_id, a.pattern_scope_key
          order by a.distinct_invoice_count desc, a.evidence_count desc, a.target_signature asc
        ) as pattern_rank
      from aggregated a
    )
    select
      r.*,
      (r.evidence_count::numeric / nullif(r.total_evidence_count, 0)) as dominance_ratio
    from ranked r
    where r.pattern_rank = 1
      and r.distinct_invoice_count >= 2
      and (r.evidence_count::numeric / nullif(r.total_evidence_count, 0)) >= 0.60
    order by r.distinct_invoice_count desc, r.evidence_count desc, r.pattern_scope_key asc
    limit resolved_limit
  loop
    pattern_note := 'Derived from repeated supplier invoice match approvals or rejections.';

    memory_item_id := public._organization_memory_upsert_derived_item(
      candidate.organization_id,
      'supplier_matching_pattern',
      'supplier_invoice_purchase_order_match_disposition',
      candidate.pattern_scope_key || '|' || candidate.target_signature,
      'Supplier invoice match: prefer ' || candidate.disposition,
      'Repeated supplier invoice matching outcomes indicate this organization usually '
        || candidate.disposition
        || 's the supplier-to-purchase-order pairing captured in this pattern.',
      jsonb_build_object(
        'patternScopeKey', candidate.pattern_scope_key,
        'supplierId', candidate.supplier_id,
        'purchaseOrderId', candidate.purchase_order_id,
        'preferredDisposition', candidate.disposition
      ),
      jsonb_build_object(
        'sourceType', 'intelligence_events',
        'sourceEventTypes', jsonb_build_array('supplier_invoice_match_confirmed', 'supplier_invoice_match_rejected'),
        'evidenceCount', candidate.evidence_count,
        'distinctInvoiceCount', candidate.distinct_invoice_count,
        'totalEvidenceCount', candidate.total_evidence_count,
        'distinctDispositionCount', candidate.distinct_disposition_count,
        'dominanceRatio', round(candidate.dominance_ratio, 4),
        'averageConfidenceScore', round(coalesce(candidate.avg_confidence_score, 0), 4)
      ),
      public._organization_memory_confidence_from_signal(candidate.distinct_invoice_count, candidate.dominance_ratio),
      'financial_sensitive',
      'organization'
    );

    foreach source_event_id in array candidate.source_event_ids
    loop
      perform public.link_organization_memory_evidence(jsonb_build_object(
        'organizationId', candidate.organization_id,
        'organizationMemoryItemId', memory_item_id,
        'sourceEventId', source_event_id,
        'linkType', 'confirmation',
        'note', pattern_note
      ));
    end loop;

    module_supplier_invoice_superseded := module_supplier_invoice_superseded + public._organization_memory_mark_superseded_conflicts(
      candidate.organization_id,
      'supplier_matching_pattern',
      'supplier_invoice_purchase_order_match_disposition',
      candidate.pattern_scope_key,
      memory_item_id,
      'Superseded by a stronger repeated supplier invoice match disposition pattern.'
    );
    module_supplier_invoice_count := module_supplier_invoice_count + 1;
  end loop;

  for candidate in
    with base as (
      select
        e.organization_id,
        e.project_id,
        nullif(coalesce(e.after_data->>'pageId', e.before_data->>'pageId', ''), '')::uuid as page_id,
        coalesce(nullif(e.after_data->>'scaleRatio', '')::numeric, nullif(e.before_data->>'scaleRatio', '')::numeric) as scale_ratio,
        nullif(btrim(coalesce(e.after_data->>'displayUnit', e.before_data->>'displayUnit', '')), '') as display_unit,
        nullif(btrim(coalesce(e.after_data->>'baseUnit', e.before_data->>'baseUnit', '')), '') as base_unit,
        nullif(btrim(coalesce(e.after_data->>'unitSystem', e.before_data->>'unitSystem', '')), '') as unit_system,
        e.id as event_id
      from public.intelligence_events e
      where e.module = 'takeoff'
        and e.event_type in ('takeoff_calibration_created', 'takeoff_calibration_corrected')
        and (resolved_organization_id is null or e.organization_id = resolved_organization_id)
    ),
    joined as (
      select
        b.organization_id,
        b.project_id,
        b.page_id,
        tp.drawing_set_id,
        b.scale_ratio,
        b.display_unit,
        b.base_unit,
        b.unit_system,
        b.event_id
      from base b
      left join public.takeoff_pages tp
        on tp.id = b.page_id
       and tp.organization_id = b.organization_id
      where b.page_id is not null
        and b.scale_ratio is not null
        and b.display_unit is not null
    ),
    filtered as (
      select
        j.*,
        concat_ws(
          '|',
          'projectId=' || coalesce(j.project_id::text, 'none'),
          'pageId=' || j.page_id::text
        ) as pattern_scope_key,
        concat_ws(
          '|',
          'scaleRatio=' || j.scale_ratio::text,
          'displayUnit=' || lower(j.display_unit),
          'baseUnit=' || lower(coalesce(j.base_unit, 'unknown')),
          'unitSystem=' || lower(coalesce(j.unit_system, 'unknown'))
        ) as target_signature
      from joined j
    ),
    aggregated as (
      select
        f.organization_id,
        f.pattern_scope_key,
        f.target_signature,
        (array_agg(f.project_id order by f.project_id))[1] as project_id,
        (array_agg(f.page_id order by f.page_id))[1] as page_id,
        (array_agg(f.drawing_set_id order by f.drawing_set_id))[1] as drawing_set_id,
        min(f.scale_ratio) as scale_ratio,
        min(f.display_unit) as display_unit,
        min(f.base_unit) as base_unit,
        min(f.unit_system) as unit_system,
        count(*)::integer as evidence_count,
        array_agg(f.event_id order by f.event_id) as source_event_ids
      from filtered f
      group by f.organization_id, f.pattern_scope_key, f.target_signature
    ),
    ranked as (
      select
        a.*,
        sum(a.evidence_count) over (partition by a.organization_id, a.pattern_scope_key) as total_evidence_count,
        count(*) over (partition by a.organization_id, a.pattern_scope_key) as distinct_convention_count,
        row_number() over (
          partition by a.organization_id, a.pattern_scope_key
          order by a.evidence_count desc, a.target_signature asc
        ) as pattern_rank
      from aggregated a
    )
    select
      r.*,
      (r.evidence_count::numeric / nullif(r.total_evidence_count, 0)) as dominance_ratio
    from ranked r
    where r.pattern_rank = 1
      and r.evidence_count >= 2
      and (r.evidence_count::numeric / nullif(r.total_evidence_count, 0)) >= 0.60
    order by r.evidence_count desc, r.pattern_scope_key asc
    limit resolved_limit
  loop
    pattern_note := 'Derived from repeated takeoff calibration events for the same page.';

    memory_item_id := public._organization_memory_upsert_derived_item(
      candidate.organization_id,
      'takeoff_convention',
      'takeoff_page_calibration_convention',
      candidate.pattern_scope_key || '|' || candidate.target_signature,
      'Takeoff calibration convention for page ' || candidate.page_id::text,
      'Repeated takeoff calibration events indicate this project/page uses a stable calibration convention.',
      jsonb_build_object(
        'patternScopeKey', candidate.pattern_scope_key,
        'projectId', candidate.project_id,
        'pageId', candidate.page_id,
        'drawingSetId', candidate.drawing_set_id,
        'scaleRatio', candidate.scale_ratio,
        'displayUnit', candidate.display_unit,
        'baseUnit', candidate.base_unit,
        'unitSystem', candidate.unit_system
      ),
      jsonb_build_object(
        'sourceType', 'intelligence_events',
        'sourceEventTypes', jsonb_build_array('takeoff_calibration_created', 'takeoff_calibration_corrected'),
        'evidenceCount', candidate.evidence_count,
        'totalEvidenceCount', candidate.total_evidence_count,
        'distinctConventionCount', candidate.distinct_convention_count,
        'dominanceRatio', round(candidate.dominance_ratio, 4)
      ),
      public._organization_memory_confidence_from_signal(candidate.evidence_count, candidate.dominance_ratio),
      'commercial_sensitive',
      'organization'
    );

    foreach source_event_id in array candidate.source_event_ids
    loop
      perform public.link_organization_memory_evidence(jsonb_build_object(
        'organizationId', candidate.organization_id,
        'organizationMemoryItemId', memory_item_id,
        'sourceEventId', source_event_id,
        'linkType', 'supporting',
        'note', pattern_note
      ));
    end loop;

    module_takeoff_superseded := module_takeoff_superseded + public._organization_memory_mark_superseded_conflicts(
      candidate.organization_id,
      'takeoff_convention',
      'takeoff_page_calibration_convention',
      candidate.pattern_scope_key,
      memory_item_id,
      'Superseded by a stronger repeated takeoff calibration convention.'
    );
    module_takeoff_count := module_takeoff_count + 1;
  end loop;

  return jsonb_build_object(
    'organizationId', resolved_organization_id,
    'ranAt', now(),
    'modules', jsonb_build_object(
      'costItemClassificationCorrections', jsonb_build_object(
        'patternsApplied', module_cost_item_count,
        'patternsSuperseded', module_cost_item_superseded
      ),
      'costCodeMappings', jsonb_build_object(
        'patternsApplied', module_cost_code_count,
        'patternsSuperseded', module_cost_code_superseded
      ),
      'pricingWorksheetStructures', jsonb_build_object(
        'patternsApplied', module_worksheet_count,
        'patternsSuperseded', module_worksheet_superseded
      ),
      'supplierInvoiceMatching', jsonb_build_object(
        'patternsApplied', module_supplier_invoice_count,
        'patternsSuperseded', module_supplier_invoice_superseded
      ),
      'takeoffCalibrations', jsonb_build_object(
        'patternsApplied', module_takeoff_count,
        'patternsSuperseded', module_takeoff_superseded
      )
    )
  );
end;
$$;


ALTER FUNCTION "public"."run_organization_memory_derivation"("p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."run_retention_variance_scan_batch"("p_limit" integer DEFAULT 25, "p_worker_id" "text" DEFAULT 'retention-variance-scanner'::"text", "p_after_project_id" "uuid" DEFAULT NULL::"uuid", "p_organization_id" "uuid" DEFAULT NULL::"uuid", "p_correlation_id" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare enqueued jsonb; claimed jsonb; item jsonb; result jsonb; results jsonb:='[]'::jsonb;
  run_id uuid; correlation text:=coalesce(nullif(trim(p_correlation_id),''),gen_random_uuid()::text);
  total_origins integer:=0; errors integer:=0;
begin
  if auth.role()<>'service_role' then
    return jsonb_build_object('succeeded',false,'errorCode','permission_denied');
  end if;
  insert into public.retention_variance_scan_runs(
    organization_id,worker_id,correlation_id,after_project_id,project_limit
  ) values(p_organization_id,coalesce(nullif(trim(p_worker_id),''),'retention-variance-scanner'),
    correlation,p_after_project_id,least(greatest(coalesce(p_limit,25),1),100))
  on conflict(correlation_id) do nothing returning id into run_id;
  if run_id is null then
    return jsonb_build_object('succeeded',false,'errorCode','scan_already_claimed');
  end if;
  enqueued:=public.enqueue_retention_variance_scan_projects(
    least(greatest(coalesce(p_limit,25),1),100),p_after_project_id,p_organization_id);
  claimed:=public.claim_retention_variance_scan_batch(
    least(greatest(coalesce(p_limit,25),1),100),p_worker_id,600,p_organization_id);
  for item in select value from jsonb_array_elements(claimed->'projects')
  loop
    result:=public.process_retention_variance_scan_item(
      (item->>'id')::uuid,(item->>'claimToken')::uuid,correlation);
    results:=results||jsonb_build_array(result);
    total_origins:=total_origins+coalesce((result->>'originCount')::integer,0);
    if not coalesce((result->>'succeeded')::boolean,false) then errors:=errors+1; end if;
    perform public.finalize_retention_variance_scan_item(jsonb_build_object(
      'queueId',item->>'id','claimToken',item->>'claimToken',
      'completed',coalesce((result->>'succeeded')::boolean,false),
      'errorCode',result->>'errorCode','errorMessage',result->>'message'));
  end loop;
  update public.retention_variance_scan_runs set
    state=case when errors=0 then 'completed' else 'failed' end,
    next_project_id=(enqueued->>'nextProjectId')::uuid,
    project_count=jsonb_array_length(claimed->'projects'),origin_count=total_origins,
    error_count=errors,error_code=case when errors>0 then 'scan_failed' end,
    error_message=case when errors>0 then 'One or more project scans failed.' end,
    completed_at=now() where id=run_id;
  return jsonb_build_object('succeeded',errors=0,
    'errorCode',case when errors=0 then null else 'scan_failed' end,
    'runId',run_id,'correlationId',correlation,
    'projectCount',jsonb_array_length(claimed->'projects'),
    'originCount',total_origins,'errorCount',errors,
    'nextProjectId',enqueued->'nextProjectId','results',results);
end;
$$;


ALTER FUNCTION "public"."run_retention_variance_scan_batch"("p_limit" integer, "p_worker_id" "text", "p_after_project_id" "uuid", "p_organization_id" "uuid", "p_correlation_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_commercial_quote_draft"("p_organization_id" "uuid", "p_originating_opportunity_id" "uuid", "p_project_id" "uuid" DEFAULT NULL::"uuid", "p_quote_id" "uuid" DEFAULT NULL::"uuid", "p_expected_updated_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_quote_title" "text" DEFAULT ''::"text", "p_quote_number" "text" DEFAULT ''::"text", "p_client_name" "text" DEFAULT ''::"text", "p_company_name" "text" DEFAULT ''::"text", "p_contact_person" "text" DEFAULT ''::"text", "p_client_email" "text" DEFAULT ''::"text", "p_client_phone" "text" DEFAULT ''::"text", "p_site_address" "text" DEFAULT ''::"text", "p_project_name" "text" DEFAULT ''::"text", "p_quote_date" "date" DEFAULT NULL::"date", "p_expiry_date" "date" DEFAULT NULL::"date", "p_status" "text" DEFAULT 'Draft'::"text", "p_optional_items_notes" "text" DEFAULT ''::"text", "p_scope_exclusions" "text" DEFAULT ''::"text", "p_assumptions" "text" DEFAULT ''::"text", "p_scope_notes" "text" DEFAULT ''::"text", "p_margin_percent" numeric DEFAULT 0, "p_discount_amount" numeric DEFAULT 0, "p_contingency_amount" numeric DEFAULT 0, "p_gst_percent" numeric DEFAULT 15, "p_validity_period" "text" DEFAULT ''::"text", "p_payment_terms" "text" DEFAULT ''::"text", "p_retention_percent_default" numeric DEFAULT 0, "p_lead_time" "text" DEFAULT ''::"text", "p_terms_inclusions" "text" DEFAULT ''::"text", "p_terms_exclusions" "text" DEFAULT ''::"text", "p_clarifications" "text" DEFAULT ''::"text", "p_acceptance_notes" "text" DEFAULT ''::"text", "p_line_items" "jsonb" DEFAULT '[]'::"jsonb") RETURNS TABLE("id" "uuid", "updated_at" timestamp with time zone, "subtotal" numeric, "optional_subtotal" numeric, "gst_amount" numeric, "total_quote_price" numeric, "status" "text", "originating_opportunity_id" "uuid", "project_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  existing_row public.project_quotes%rowtype;
  saved_row public.project_quotes%rowtype;
  computed_subtotal numeric := 0;
  computed_optional_subtotal numeric := 0;
  computed_margin numeric := 0;
  computed_discount numeric := 0;
  computed_contingency numeric := 0;
  pre_gst_total numeric := 0;
  computed_gst numeric := 0;
  computed_grand_total numeric := 0;
  resolved_retention_percent_default numeric := 0;
  saved_status text := 'Draft';
  cost_item_revision_key text;
  resolved_project_source_opportunity_id uuid;
  resolved_attached_project_id uuid;
begin
  if auth.uid() is null then
    raise exception 'Authentication is required';
  end if;

  if p_originating_opportunity_id is null then
    raise exception 'originating_opportunity_id is required';
  end if;

  if not public.has_org_permission(p_organization_id, 'quotes.write') then
    raise exception 'Not authorized for this organization';
  end if;

  if not exists (
    select 1
    from public.organization_opportunities opportunity
    where opportunity.id = p_originating_opportunity_id
      and opportunity.organization_id = p_organization_id
  ) then
    raise exception 'Originating opportunity not found for organization';
  end if;

  if p_project_id is not null then
    select project.source_opportunity_id
    into resolved_project_source_opportunity_id
    from public.organization_projects project
    where project.id = p_project_id
      and project.organization_id = p_organization_id;

    if not found then
      raise exception 'Project not found for organization';
    end if;

    if resolved_project_source_opportunity_id is not null
      and resolved_project_source_opportunity_id <> p_originating_opportunity_id then
      raise exception 'Project must belong to the same originating opportunity';
    end if;
  else
    resolved_project_source_opportunity_id := null;
  end if;

  if coalesce(nullif(btrim(p_quote_title), ''), '') = '' then
    raise exception 'Quote title is required';
  end if;

  if coalesce(nullif(btrim(p_quote_number), ''), '') = '' then
    raise exception 'Quote number is required';
  end if;

  select
    coalesce(sum(
      case
        when coalesce((line.item->>'isOptional')::boolean, false) then 0
        else round(
          coalesce(nullif(line.item->>'quantity', '')::numeric, 0)
          * coalesce(nullif(line.item->>'rate', '')::numeric, 0),
          2
        )
      end
    ), 0),
    coalesce(sum(
      case
        when coalesce((line.item->>'isOptional')::boolean, false) then round(
          coalesce(nullif(line.item->>'quantity', '')::numeric, 0)
          * coalesce(nullif(line.item->>'rate', '')::numeric, 0),
          2
        )
        else 0
      end
    ), 0)
  into computed_subtotal, computed_optional_subtotal
  from jsonb_array_elements(coalesce(p_line_items, '[]'::jsonb)) as line(item);

  computed_margin := computed_subtotal * (coalesce(p_margin_percent, 0) / 100);
  computed_discount := coalesce(p_discount_amount, 0);
  computed_contingency := coalesce(p_contingency_amount, 0);
  pre_gst_total := greatest(0, computed_subtotal + computed_margin + computed_contingency - computed_discount);
  computed_gst := pre_gst_total * (coalesce(p_gst_percent, 0) / 100);
  computed_grand_total := pre_gst_total + computed_gst;
  resolved_retention_percent_default := greatest(0, least(100, coalesce(p_retention_percent_default, 0)));

  if p_quote_id is not null then
    select *
    into existing_row
    from public.project_quotes quote
    where quote.id = p_quote_id
      and quote.organization_id = p_organization_id
    for update;

    if not found then
      raise exception 'Quote not found';
    end if;

    if existing_row.originating_opportunity_id is not null
      and existing_row.originating_opportunity_id <> p_originating_opportunity_id then
      raise exception 'Quote belongs to a different originating opportunity';
    end if;

    if p_expected_updated_at is null then
      raise exception 'Quote version is required. Please refresh and try again.'
        using errcode = '40001';
    end if;

    if existing_row.updated_at is distinct from p_expected_updated_at then
      raise exception 'This quote was updated by another user. Refresh and try again.'
        using errcode = '40001';
    end if;

    resolved_attached_project_id := coalesce(p_project_id, existing_row.project_id);

    update public.project_quotes quote
    set
      project_id = resolved_attached_project_id,
      originating_opportunity_id = coalesce(quote.originating_opportunity_id, p_originating_opportunity_id),
      source_opportunity_id = coalesce(quote.source_opportunity_id, p_originating_opportunity_id),
      quote_title = btrim(p_quote_title),
      quote_number = btrim(p_quote_number),
      client_name = coalesce(p_client_name, ''),
      company_name = coalesce(p_company_name, ''),
      contact_person = coalesce(p_contact_person, ''),
      client_email = coalesce(p_client_email, ''),
      client_phone = coalesce(p_client_phone, ''),
      site_address = coalesce(p_site_address, ''),
      project_name = coalesce(p_project_name, ''),
      quote_date = p_quote_date,
      expiry_date = p_expiry_date,
      status = case
        when p_status in ('Draft', 'Ready to Send', 'Sent', 'Viewed', 'Accepted', 'Rejected', 'Expired') then p_status
        else quote.status
      end,
      optional_items_notes = coalesce(p_optional_items_notes, ''),
      scope_exclusions = coalesce(p_scope_exclusions, ''),
      assumptions = coalesce(p_assumptions, ''),
      scope_notes = coalesce(p_scope_notes, ''),
      subtotal = round(computed_subtotal, 2),
      optional_subtotal = round(computed_optional_subtotal, 2),
      margin_percent = round(coalesce(p_margin_percent, 0), 3),
      margin_amount = round(computed_margin, 2),
      discount_amount = round(coalesce(p_discount_amount, 0), 2),
      contingency_amount = round(coalesce(p_contingency_amount, 0), 2),
      gst_percent = round(coalesce(p_gst_percent, 0), 3),
      gst_amount = round(computed_gst, 2),
      total_quote_price = round(computed_grand_total, 2),
      validity_period = coalesce(p_validity_period, ''),
      payment_terms = coalesce(p_payment_terms, ''),
      retention_percent_default = round(resolved_retention_percent_default, 3),
      lead_time = coalesce(p_lead_time, ''),
      terms_inclusions = coalesce(p_terms_inclusions, ''),
      terms_exclusions = coalesce(p_terms_exclusions, ''),
      clarifications = coalesce(p_clarifications, ''),
      acceptance_notes = coalesce(p_acceptance_notes, '')
    where quote.id = p_quote_id
      and quote.organization_id = p_organization_id
    returning * into saved_row;
  else
    saved_status := case
      when p_status in ('Draft', 'Ready to Send', 'Sent', 'Viewed', 'Accepted', 'Rejected', 'Expired') then p_status
      else 'Draft'
    end;

    insert into public.project_quotes (
      organization_id,
      project_id,
      originating_opportunity_id,
      source_opportunity_id,
      created_by,
      quote_title,
      quote_number,
      client_name,
      company_name,
      contact_person,
      client_email,
      client_phone,
      site_address,
      project_name,
      quote_date,
      expiry_date,
      status,
      optional_items_notes,
      scope_exclusions,
      assumptions,
      scope_notes,
      subtotal,
      optional_subtotal,
      margin_percent,
      margin_amount,
      discount_amount,
      contingency_amount,
      gst_percent,
      gst_amount,
      total_quote_price,
      validity_period,
      payment_terms,
      retention_percent_default,
      lead_time,
      terms_inclusions,
      terms_exclusions,
      clarifications,
      acceptance_notes
    ) values (
      p_organization_id,
      p_project_id,
      p_originating_opportunity_id,
      p_originating_opportunity_id,
      auth.uid(),
      btrim(p_quote_title),
      btrim(p_quote_number),
      coalesce(p_client_name, ''),
      coalesce(p_company_name, ''),
      coalesce(p_contact_person, ''),
      coalesce(p_client_email, ''),
      coalesce(p_client_phone, ''),
      coalesce(p_site_address, ''),
      coalesce(p_project_name, ''),
      p_quote_date,
      p_expiry_date,
      saved_status,
      coalesce(p_optional_items_notes, ''),
      coalesce(p_scope_exclusions, ''),
      coalesce(p_assumptions, ''),
      coalesce(p_scope_notes, ''),
      round(computed_subtotal, 2),
      round(computed_optional_subtotal, 2),
      round(coalesce(p_margin_percent, 0), 3),
      round(computed_margin, 2),
      round(coalesce(p_discount_amount, 0), 2),
      round(coalesce(p_contingency_amount, 0), 2),
      round(coalesce(p_gst_percent, 0), 3),
      round(computed_gst, 2),
      round(computed_grand_total, 2),
      coalesce(p_validity_period, ''),
      coalesce(p_payment_terms, ''),
      round(resolved_retention_percent_default, 3),
      coalesce(p_lead_time, ''),
      coalesce(p_terms_inclusions, ''),
      coalesce(p_terms_exclusions, ''),
      coalesce(p_clarifications, ''),
      coalesce(p_acceptance_notes, '')
    )
    returning * into saved_row;
  end if;

  delete from public.project_quote_line_items line
  where line.organization_id = p_organization_id
    and line.quote_id = saved_row.id;

  insert into public.project_quote_line_items (
    id,
    organization_id,
    project_id,
    quote_id,
    section,
    description,
    quantity,
    unit,
    rate,
    total,
    is_optional,
    sort_order,
    source_opportunity_quote_id,
    source_opportunity_quote_line_item_id,
    source_opportunity_quote_number
  )
  select
    case
      when nullif(line.item->>'id', '') is not null then (line.item->>'id')::uuid
      else gen_random_uuid()
    end,
    p_organization_id,
    saved_row.project_id,
    saved_row.id,
    case
      when line.item->>'section' in ('Item', 'Materials', 'Labour', 'Plant', 'Subcontractors', 'Preliminaries') then line.item->>'section'
      else 'Labour'
    end,
    coalesce(line.item->>'description', ''),
    coalesce(nullif(line.item->>'quantity', '')::numeric, 0),
    coalesce(line.item->>'unit', ''),
    coalesce(nullif(line.item->>'rate', '')::numeric, 0),
    round(
      coalesce(nullif(line.item->>'quantity', '')::numeric, 0)
      * coalesce(nullif(line.item->>'rate', '')::numeric, 0),
      2
    ),
    coalesce((line.item->>'isOptional')::boolean, false),
    row_number() over (),
    case
      when nullif(line.item->>'sourceOpportunityQuoteId', '') is not null then (line.item->>'sourceOpportunityQuoteId')::uuid
      else null
    end,
    case
      when nullif(line.item->>'sourceOpportunityQuoteLineItemId', '') is not null then (line.item->>'sourceOpportunityQuoteLineItemId')::uuid
      else null
    end,
    nullif(line.item->>'sourceOpportunityQuoteNumber', '')
  from jsonb_array_elements(coalesce(p_line_items, '[]'::jsonb)) as line(item);

  cost_item_revision_key := public.begin_cost_item_revision('project_quote', saved_row.id);
  perform public.supersede_previous_cost_items('project_quote', saved_row.id, cost_item_revision_key);
  perform public.upsert_cost_items_for_document('project_quote', saved_row.id, cost_item_revision_key);

  return query
  select
    saved_row.id,
    saved_row.updated_at,
    saved_row.subtotal,
    saved_row.optional_subtotal,
    saved_row.gst_amount,
    saved_row.total_quote_price,
    saved_row.status,
    saved_row.originating_opportunity_id,
    saved_row.project_id;
end;
$$;


ALTER FUNCTION "public"."save_commercial_quote_draft"("p_organization_id" "uuid", "p_originating_opportunity_id" "uuid", "p_project_id" "uuid", "p_quote_id" "uuid", "p_expected_updated_at" timestamp with time zone, "p_quote_title" "text", "p_quote_number" "text", "p_client_name" "text", "p_company_name" "text", "p_contact_person" "text", "p_client_email" "text", "p_client_phone" "text", "p_site_address" "text", "p_project_name" "text", "p_quote_date" "date", "p_expiry_date" "date", "p_status" "text", "p_optional_items_notes" "text", "p_scope_exclusions" "text", "p_assumptions" "text", "p_scope_notes" "text", "p_margin_percent" numeric, "p_discount_amount" numeric, "p_contingency_amount" numeric, "p_gst_percent" numeric, "p_validity_period" "text", "p_payment_terms" "text", "p_retention_percent_default" numeric, "p_lead_time" "text", "p_terms_inclusions" "text", "p_terms_exclusions" "text", "p_clarifications" "text", "p_acceptance_notes" "text", "p_line_items" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_opportunity_pricing_workbook_active_sheet"("p_organization_id" "uuid", "p_opportunity_id" "uuid", "p_user_id" "uuid", "p_workbook_id" "uuid" DEFAULT NULL::"uuid", "p_sheet_id" "uuid" DEFAULT NULL::"uuid", "p_name" "text" DEFAULT NULL::"text", "p_trade_package" "text" DEFAULT NULL::"text", "p_worksheet_data" "jsonb" DEFAULT '{}'::"jsonb", "p_pricing_summary" "jsonb" DEFAULT '{}'::"jsonb", "p_extracted_pricing_data" "jsonb" DEFAULT '{}'::"jsonb", "p_version" integer DEFAULT 1, "p_save_request_id" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  v_workbook public.opportunity_pricing_worksheets%rowtype;
  v_sheet public.opportunity_pricing_workbook_sheets%rowtype;
  v_target_sheet public.opportunity_pricing_workbook_sheets%rowtype;
  v_sheet_name text;
  v_worksheet_data jsonb;
  v_version integer;
  v_should_sync_parent boolean := false;
  v_actor_member_id uuid;
  v_actor_role text;
  v_save_request_id text;
begin
  v_sheet_name := public._normalize_opportunity_pricing_workbook_name(
    p_name,
    coalesce(nullif(trim(p_worksheet_data->>'sheetName'), ''), 'Pricing Worksheet')
  );
  v_worksheet_data := public._sync_opportunity_pricing_workbook_sheet_name(
    coalesce(p_worksheet_data, '{}'::jsonb),
    v_sheet_name
  );
  v_version := greatest(coalesce(p_version, nullif((v_worksheet_data->>'version')::integer, 0), 1), 1);
  v_save_request_id := nullif(btrim(coalesce(p_save_request_id, '')), '');

  if auth.uid() is not null then
    select member.id, member.role
    into v_actor_member_id, v_actor_role
    from public.organization_members member
    where member.organization_id = p_organization_id
      and member.user_id = auth.uid()
    limit 1;
  end if;

  if p_workbook_id is null then
    insert into public.opportunity_pricing_worksheets (
      organization_id,
      opportunity_id,
      name,
      trade_package,
      worksheet_data,
      pricing_summary,
      extracted_pricing_data,
      version,
      created_by,
      updated_by
    )
    values (
      p_organization_id,
      p_opportunity_id,
      v_sheet_name,
      p_trade_package,
      v_worksheet_data,
      coalesce(p_pricing_summary, '{}'::jsonb),
      coalesce(p_extracted_pricing_data, '{}'::jsonb),
      v_version,
      p_user_id,
      p_user_id
    )
    returning * into v_workbook;
    v_should_sync_parent := true;
  else
    select *
    into v_workbook
    from public.opportunity_pricing_worksheets
    where id = p_workbook_id
      and organization_id = p_organization_id
      and opportunity_id = p_opportunity_id
      and archived_at is null;

    if not found then
      raise exception 'Pricing worksheet not found.';
    end if;

    if p_sheet_id is not null then
      select *
      into v_target_sheet
      from public.opportunity_pricing_workbook_sheets
      where id = p_sheet_id
        and workbook_id = v_workbook.id
        and organization_id = p_organization_id
        and opportunity_id = p_opportunity_id;

      if not found then
        raise exception 'Worksheet page not found.';
      end if;

      v_should_sync_parent := coalesce(v_target_sheet.is_default, false);
    else
      v_should_sync_parent := true;
    end if;

    if v_should_sync_parent then
      update public.opportunity_pricing_worksheets
      set
        name = v_sheet_name,
        trade_package = p_trade_package,
        worksheet_data = v_worksheet_data,
        pricing_summary = coalesce(p_pricing_summary, '{}'::jsonb),
        extracted_pricing_data = coalesce(p_extracted_pricing_data, '{}'::jsonb),
        version = v_version,
        updated_by = p_user_id
      where id = p_workbook_id
        and organization_id = p_organization_id
        and opportunity_id = p_opportunity_id
        and archived_at is null
      returning * into v_workbook;
    else
      update public.opportunity_pricing_worksheets
      set
        trade_package = p_trade_package,
        updated_by = p_user_id
      where id = p_workbook_id
        and organization_id = p_organization_id
        and opportunity_id = p_opportunity_id
        and archived_at is null
      returning * into v_workbook;
    end if;
  end if;

  if p_sheet_id is not null then
    update public.opportunity_pricing_workbook_sheets
    set
      name = v_sheet_name,
      worksheet_data = v_worksheet_data,
      pricing_summary = coalesce(p_pricing_summary, '{}'::jsonb),
      extracted_pricing_data = coalesce(p_extracted_pricing_data, '{}'::jsonb),
      version = v_version,
      updated_by = p_user_id
    where id = p_sheet_id
      and workbook_id = v_workbook.id
      and organization_id = p_organization_id
      and opportunity_id = p_opportunity_id
    returning * into v_sheet;
  end if;

  if v_sheet.id is null then
    update public.opportunity_pricing_workbook_sheets
    set
      name = v_sheet_name,
      worksheet_data = v_worksheet_data,
      pricing_summary = coalesce(p_pricing_summary, '{}'::jsonb),
      extracted_pricing_data = coalesce(p_extracted_pricing_data, '{}'::jsonb),
      version = v_version,
      updated_by = p_user_id
    where workbook_id = v_workbook.id
      and organization_id = p_organization_id
      and opportunity_id = p_opportunity_id
      and is_default = true
    returning * into v_sheet;
  end if;

  if v_sheet.id is null then
    insert into public.opportunity_pricing_workbook_sheets (
      workbook_id,
      organization_id,
      opportunity_id,
      name,
      sheet_order,
      is_default,
      worksheet_data,
      pricing_summary,
      extracted_pricing_data,
      version,
      created_by,
      updated_by
    )
    values (
      v_workbook.id,
      p_organization_id,
      p_opportunity_id,
      v_sheet_name,
      0,
      true,
      v_worksheet_data,
      coalesce(p_pricing_summary, '{}'::jsonb),
      coalesce(p_extracted_pricing_data, '{}'::jsonb),
      v_version,
      p_user_id,
      p_user_id
    )
    returning * into v_sheet;
  end if;

  perform public.write_intelligence_event(
    jsonb_build_object(
      'organizationId', p_organization_id,
      'userId', auth.uid(),
      'projectId', null,
      'opportunityId', p_opportunity_id,
      'module', 'pricing_worksheets',
      'eventFamily', 'commercial_action',
      'eventType', 'worksheet_saved',
      'action', 'saved',
      'entityType', 'pricing_worksheet_page',
      'entityId', v_sheet.id,
      'parentEntityType', 'pricing_workbook',
      'parentEntityId', v_workbook.id,
      'relatedEntities', '[]'::jsonb,
      'lineageRefs', '[]'::jsonb,
      'sourceChannel', 'system',
      'sourceRequestId', v_save_request_id,
      'diffData', '{}'::jsonb,
      'metadata', jsonb_build_object(
        'workbookId', v_workbook.id,
        'workbookName', v_workbook.name,
        'worksheetId', v_workbook.id,
        'sheetId', v_sheet.id,
        'sheetName', v_sheet.name,
        'worksheetName', v_sheet.name,
        'tradePackage', v_workbook.trade_package,
        'userId', p_user_id,
        'projectId', null,
        'source', 'system',
        'structureSummary', public._pricing_worksheet_structure_summary(v_sheet.worksheet_data)
      ),
      'privacyClassification', 'financial_sensitive',
      'visibilityScope', 'organization',
      'containsFinancialData', true,
      'containsPersonalData', false,
      'containsAttachmentContent', false,
      'occurredAt', now()
    )
  );

  return jsonb_build_object(
    'workbook', to_jsonb(v_workbook),
    'sheet', to_jsonb(v_sheet)
  );
end;
$$;


ALTER FUNCTION "public"."save_opportunity_pricing_workbook_active_sheet"("p_organization_id" "uuid", "p_opportunity_id" "uuid", "p_user_id" "uuid", "p_workbook_id" "uuid", "p_sheet_id" "uuid", "p_name" "text", "p_trade_package" "text", "p_worksheet_data" "jsonb", "p_pricing_summary" "jsonb", "p_extracted_pricing_data" "jsonb", "p_version" integer, "p_save_request_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_opportunity_quote_draft"("p_organization_id" "uuid", "p_opportunity_id" "uuid", "p_quote_id" "uuid", "p_expected_updated_at" timestamp with time zone, "p_quote_title" "text", "p_quote_number" "text", "p_client_name" "text", "p_company_name" "text", "p_contact_person" "text", "p_client_email" "text", "p_client_phone" "text", "p_site_address" "text", "p_project_name" "text", "p_quote_date" "date", "p_expiry_date" "date", "p_status" "text", "p_optional_items_notes" "text", "p_scope_exclusions" "text", "p_assumptions" "text", "p_scope_notes" "text", "p_margin_percent" numeric, "p_discount_amount" numeric, "p_contingency_amount" numeric, "p_gst_percent" numeric, "p_validity_period" "text", "p_payment_terms" "text", "p_lead_time" "text", "p_terms_inclusions" "text", "p_terms_exclusions" "text", "p_clarifications" "text", "p_acceptance_notes" "text", "p_line_items" "jsonb") RETURNS TABLE("id" "uuid", "updated_at" timestamp with time zone, "subtotal" numeric, "optional_subtotal" numeric, "gst_amount" numeric, "total_quote_price" numeric, "status" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  existing_row public.opportunity_quotes%rowtype;
  saved_row public.opportunity_quotes%rowtype;
  workspace_project_id uuid;
  computed_subtotal numeric := 0;
  computed_optional_subtotal numeric := 0;
  computed_margin numeric := 0;
  computed_discount numeric := 0;
  computed_contingency numeric := 0;
  pre_gst_total numeric := 0;
  computed_gst numeric := 0;
  computed_grand_total numeric := 0;
  saved_status text := 'Draft';
  cost_item_revision_key text;
begin
  if auth.uid() is null then
    raise exception 'Authentication is required';
  end if;

  if not public.has_org_permission(p_organization_id, 'leads.opportunities.write') then
    raise exception 'Not authorized for this organization';
  end if;

  select o.workspace_project_id
  into workspace_project_id
  from public.organization_opportunities o
  where o.id = p_opportunity_id
    and o.organization_id = p_organization_id;

  if workspace_project_id is null then
    raise exception 'Opportunity not found for organization or missing workspace project';
  end if;

  if coalesce(nullif(btrim(p_quote_title), ''), '') = '' then
    raise exception 'Quote title is required';
  end if;

  if coalesce(nullif(btrim(p_quote_number), ''), '') = '' then
    raise exception 'Quote number is required';
  end if;

  select
    coalesce(sum(
      case
        when coalesce((line.item->>'isOptional')::boolean, false) then 0
        else round(
          coalesce(nullif(line.item->>'quantity', '')::numeric, 0)
          * coalesce(nullif(line.item->>'rate', '')::numeric, 0),
          2
        )
      end
    ), 0),
    coalesce(sum(
      case
        when coalesce((line.item->>'isOptional')::boolean, false) then round(
          coalesce(nullif(line.item->>'quantity', '')::numeric, 0)
          * coalesce(nullif(line.item->>'rate', '')::numeric, 0),
          2
        )
        else 0
      end
    ), 0)
  into computed_subtotal, computed_optional_subtotal
  from jsonb_array_elements(coalesce(p_line_items, '[]'::jsonb)) as line(item);

  computed_margin := computed_subtotal * (coalesce(p_margin_percent, 0) / 100);
  computed_discount := coalesce(p_discount_amount, 0);
  computed_contingency := coalesce(p_contingency_amount, 0);
  pre_gst_total := greatest(
    0,
    computed_subtotal + computed_margin + computed_contingency - computed_discount
  );
  computed_gst := pre_gst_total * (coalesce(p_gst_percent, 0) / 100);
  computed_grand_total := pre_gst_total + computed_gst;

  if p_quote_id is not null then
    select *
    into existing_row
    from public.opportunity_quotes q
    where q.id = p_quote_id
      and q.organization_id = p_organization_id
      and q.opportunity_id = p_opportunity_id
    for update;

    if not found then
      raise exception 'Quote not found';
    end if;

    if p_expected_updated_at is null then
      raise exception 'Quote version is required. Please refresh and try again.'
        using errcode = '40001';
    end if;

    if existing_row.updated_at is distinct from p_expected_updated_at then
      raise exception 'This quote was updated by another user. Refresh and try again.'
        using errcode = '40001';
    end if;

    update public.opportunity_quotes q
    set
      quote_title = btrim(p_quote_title),
      quote_number = btrim(p_quote_number),
      client_name = coalesce(p_client_name, ''),
      company_name = coalesce(p_company_name, ''),
      contact_person = coalesce(p_contact_person, ''),
      client_email = coalesce(p_client_email, ''),
      client_phone = coalesce(p_client_phone, ''),
      site_address = coalesce(p_site_address, ''),
      project_name = coalesce(p_project_name, ''),
      quote_date = p_quote_date,
      expiry_date = p_expiry_date,
      status = case
        when p_status in ('Draft', 'Ready to Send', 'Sent', 'Viewed', 'Accepted', 'Rejected', 'Expired') then p_status
        else q.status
      end,
      optional_items_notes = coalesce(p_optional_items_notes, ''),
      scope_exclusions = coalesce(p_scope_exclusions, ''),
      assumptions = coalesce(p_assumptions, ''),
      scope_notes = coalesce(p_scope_notes, ''),
      subtotal = round(computed_subtotal, 2),
      optional_subtotal = round(computed_optional_subtotal, 2),
      margin_percent = round(coalesce(p_margin_percent, 0), 3),
      margin_amount = round(computed_margin, 2),
      discount_amount = round(coalesce(p_discount_amount, 0), 2),
      contingency_amount = round(coalesce(p_contingency_amount, 0), 2),
      gst_percent = round(coalesce(p_gst_percent, 0), 3),
      gst_amount = round(computed_gst, 2),
      total_quote_price = round(computed_grand_total, 2),
      validity_period = coalesce(p_validity_period, ''),
      payment_terms = coalesce(p_payment_terms, ''),
      lead_time = coalesce(p_lead_time, ''),
      terms_inclusions = coalesce(p_terms_inclusions, ''),
      terms_exclusions = coalesce(p_terms_exclusions, ''),
      clarifications = coalesce(p_clarifications, ''),
      acceptance_notes = coalesce(p_acceptance_notes, '')
    where q.id = p_quote_id
      and q.organization_id = p_organization_id
      and q.opportunity_id = p_opportunity_id
    returning * into saved_row;
  else
    saved_status := case
      when p_status in ('Draft', 'Ready to Send', 'Sent', 'Viewed', 'Accepted', 'Rejected', 'Expired') then p_status
      else 'Draft'
    end;

    insert into public.opportunity_quotes (
      organization_id,
      opportunity_id,
      created_by,
      quote_title,
      quote_number,
      client_name,
      company_name,
      contact_person,
      client_email,
      client_phone,
      site_address,
      project_name,
      quote_date,
      expiry_date,
      status,
      optional_items_notes,
      scope_exclusions,
      assumptions,
      scope_notes,
      subtotal,
      optional_subtotal,
      margin_percent,
      margin_amount,
      discount_amount,
      contingency_amount,
      gst_percent,
      gst_amount,
      total_quote_price,
      validity_period,
      payment_terms,
      lead_time,
      terms_inclusions,
      terms_exclusions,
      clarifications,
      acceptance_notes
    ) values (
      p_organization_id,
      p_opportunity_id,
      auth.uid(),
      btrim(p_quote_title),
      btrim(p_quote_number),
      coalesce(p_client_name, ''),
      coalesce(p_company_name, ''),
      coalesce(p_contact_person, ''),
      coalesce(p_client_email, ''),
      coalesce(p_client_phone, ''),
      coalesce(p_site_address, ''),
      coalesce(p_project_name, ''),
      p_quote_date,
      p_expiry_date,
      saved_status,
      coalesce(p_optional_items_notes, ''),
      coalesce(p_scope_exclusions, ''),
      coalesce(p_assumptions, ''),
      coalesce(p_scope_notes, ''),
      round(computed_subtotal, 2),
      round(computed_optional_subtotal, 2),
      round(coalesce(p_margin_percent, 0), 3),
      round(computed_margin, 2),
      round(coalesce(p_discount_amount, 0), 2),
      round(coalesce(p_contingency_amount, 0), 2),
      round(coalesce(p_gst_percent, 0), 3),
      round(computed_gst, 2),
      round(computed_grand_total, 2),
      coalesce(p_validity_period, ''),
      coalesce(p_payment_terms, ''),
      coalesce(p_lead_time, ''),
      coalesce(p_terms_inclusions, ''),
      coalesce(p_terms_exclusions, ''),
      coalesce(p_clarifications, ''),
      coalesce(p_acceptance_notes, '')
    )
    returning * into saved_row;
  end if;

  delete from public.opportunity_quote_line_items li
  where li.organization_id = p_organization_id
    and li.quote_id = saved_row.id;

  insert into public.opportunity_quote_line_items (
    id,
    organization_id,
    quote_id,
    section,
    description,
    quantity,
    unit,
    rate,
    total,
    is_optional,
    sort_order
  )
  select
    case
      when nullif(line.item->>'id', '') is not null then (line.item->>'id')::uuid
      else gen_random_uuid()
    end,
    p_organization_id,
    saved_row.id,
    case
      when line.item->>'section' in ('Item', 'Materials', 'Labour', 'Plant', 'Subcontractors', 'Preliminaries') then line.item->>'section'
      else 'Labour'
    end,
    coalesce(line.item->>'description', ''),
    coalesce(nullif(line.item->>'quantity', '')::numeric, 0),
    coalesce(line.item->>'unit', ''),
    coalesce(nullif(line.item->>'rate', '')::numeric, 0),
    round(
      coalesce(nullif(line.item->>'quantity', '')::numeric, 0)
      * coalesce(nullif(line.item->>'rate', '')::numeric, 0),
      2
    ),
    coalesce((line.item->>'isOptional')::boolean, false),
    row_number() over ()
  from jsonb_array_elements(coalesce(p_line_items, '[]'::jsonb)) as line(item);

  cost_item_revision_key := public.begin_cost_item_revision('opportunity_quote', saved_row.id);
  perform public.supersede_previous_cost_items('opportunity_quote', saved_row.id, cost_item_revision_key);
  perform public.upsert_opportunity_quote_cost_items(saved_row.id, cost_item_revision_key);

  return query
  select
    saved_row.id,
    saved_row.updated_at,
    saved_row.subtotal,
    saved_row.optional_subtotal,
    saved_row.gst_amount,
    saved_row.total_quote_price,
    saved_row.status;
end;
$$;


ALTER FUNCTION "public"."save_opportunity_quote_draft"("p_organization_id" "uuid", "p_opportunity_id" "uuid", "p_quote_id" "uuid", "p_expected_updated_at" timestamp with time zone, "p_quote_title" "text", "p_quote_number" "text", "p_client_name" "text", "p_company_name" "text", "p_contact_person" "text", "p_client_email" "text", "p_client_phone" "text", "p_site_address" "text", "p_project_name" "text", "p_quote_date" "date", "p_expiry_date" "date", "p_status" "text", "p_optional_items_notes" "text", "p_scope_exclusions" "text", "p_assumptions" "text", "p_scope_notes" "text", "p_margin_percent" numeric, "p_discount_amount" numeric, "p_contingency_amount" numeric, "p_gst_percent" numeric, "p_validity_period" "text", "p_payment_terms" "text", "p_lead_time" "text", "p_terms_inclusions" "text", "p_terms_exclusions" "text", "p_clarifications" "text", "p_acceptance_notes" "text", "p_line_items" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_pricing_workbook_active_sheet"("p_organization_id" "uuid", "p_opportunity_id" "uuid", "p_project_id" "uuid" DEFAULT NULL::"uuid", "p_quote_id" "uuid" DEFAULT NULL::"uuid", "p_user_id" "uuid" DEFAULT NULL::"uuid", "p_variation_id" "uuid" DEFAULT NULL::"uuid", "p_workbook_id" "uuid" DEFAULT NULL::"uuid", "p_sheet_id" "uuid" DEFAULT NULL::"uuid", "p_name" "text" DEFAULT NULL::"text", "p_trade_package" "text" DEFAULT NULL::"text", "p_worksheet_data" "jsonb" DEFAULT '{}'::"jsonb", "p_pricing_summary" "jsonb" DEFAULT '{}'::"jsonb", "p_extracted_pricing_data" "jsonb" DEFAULT '{}'::"jsonb", "p_version" integer DEFAULT 1, "p_save_request_id" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  v_workbook public.opportunity_pricing_worksheets%rowtype;
  v_sheet public.opportunity_pricing_workbook_sheets%rowtype;
  v_target_sheet public.opportunity_pricing_workbook_sheets%rowtype;
  v_sheet_name text;
  v_worksheet_data jsonb;
  v_version integer;
  v_should_sync_parent boolean := false;
  v_save_request_id text;
begin
  v_sheet_name := public._normalize_opportunity_pricing_workbook_name(
    p_name,
    coalesce(nullif(trim(p_worksheet_data->>'sheetName'), ''), 'Pricing Worksheet')
  );
  v_worksheet_data := public._sync_opportunity_pricing_workbook_sheet_name(
    coalesce(p_worksheet_data, '{}'::jsonb),
    v_sheet_name
  );
  v_version := greatest(coalesce(p_version, nullif((v_worksheet_data->>'version')::integer, 0), 1), 1);
  v_save_request_id := nullif(btrim(coalesce(p_save_request_id, '')), '');

  if p_workbook_id is null then
    insert into public.opportunity_pricing_worksheets (
      organization_id,
      opportunity_id,
      project_id,
      quote_id,
      variation_id,
      name,
      trade_package,
      worksheet_data,
      pricing_summary,
      extracted_pricing_data,
      version,
      created_by,
      updated_by
    )
    values (
      p_organization_id,
      p_opportunity_id,
      p_project_id,
      p_quote_id,
      p_variation_id,
      v_sheet_name,
      p_trade_package,
      v_worksheet_data,
      coalesce(p_pricing_summary, '{}'::jsonb),
      coalesce(p_extracted_pricing_data, '{}'::jsonb),
      v_version,
      p_user_id,
      p_user_id
    )
    returning * into v_workbook;
    v_should_sync_parent := true;
  else
    select *
    into v_workbook
    from public.opportunity_pricing_worksheets workbook
    where workbook.id = p_workbook_id
      and workbook.organization_id = p_organization_id
      and workbook.opportunity_id = p_opportunity_id
      and workbook.archived_at is null
      and (
        (p_quote_id is null and workbook.quote_id is null)
        or workbook.quote_id = p_quote_id
      )
      and (
        (p_variation_id is null and workbook.variation_id is null)
        or workbook.variation_id = p_variation_id
      )
      and (
        (p_project_id is null and workbook.project_id is null)
        or workbook.project_id = p_project_id
      );

    if not found then
      raise exception 'Pricing worksheet not found.';
    end if;

    if p_sheet_id is not null then
      select *
      into v_target_sheet
      from public.opportunity_pricing_workbook_sheets
      where id = p_sheet_id
        and workbook_id = v_workbook.id
        and organization_id = p_organization_id
        and opportunity_id = p_opportunity_id;

      if not found then
        raise exception 'Worksheet page not found.';
      end if;

      v_should_sync_parent := coalesce(v_target_sheet.is_default, false);
    else
      v_should_sync_parent := true;
    end if;

    if v_should_sync_parent then
      update public.opportunity_pricing_worksheets
      set
        name = v_sheet_name,
        trade_package = p_trade_package,
        worksheet_data = v_worksheet_data,
        pricing_summary = coalesce(p_pricing_summary, '{}'::jsonb),
        extracted_pricing_data = coalesce(p_extracted_pricing_data, '{}'::jsonb),
        version = v_version,
        updated_by = p_user_id
      where id = p_workbook_id
        and organization_id = p_organization_id
        and opportunity_id = p_opportunity_id
        and archived_at is null
      returning * into v_workbook;
    else
      update public.opportunity_pricing_worksheets
      set
        trade_package = p_trade_package,
        updated_by = p_user_id
      where id = p_workbook_id
        and organization_id = p_organization_id
        and opportunity_id = p_opportunity_id
        and archived_at is null
      returning * into v_workbook;
    end if;
  end if;

  if p_sheet_id is not null then
    update public.opportunity_pricing_workbook_sheets
    set
      name = v_sheet_name,
      worksheet_data = v_worksheet_data,
      pricing_summary = coalesce(p_pricing_summary, '{}'::jsonb),
      extracted_pricing_data = coalesce(p_extracted_pricing_data, '{}'::jsonb),
      version = v_version,
      updated_by = p_user_id
    where id = p_sheet_id
      and workbook_id = v_workbook.id
      and organization_id = p_organization_id
      and opportunity_id = p_opportunity_id
    returning * into v_sheet;
  end if;

  if v_sheet.id is null then
    update public.opportunity_pricing_workbook_sheets
    set
      name = v_sheet_name,
      worksheet_data = v_worksheet_data,
      pricing_summary = coalesce(p_pricing_summary, '{}'::jsonb),
      extracted_pricing_data = coalesce(p_extracted_pricing_data, '{}'::jsonb),
      version = v_version,
      updated_by = p_user_id
    where workbook_id = v_workbook.id
      and organization_id = p_organization_id
      and opportunity_id = p_opportunity_id
      and is_default = true
    returning * into v_sheet;
  end if;

  if v_sheet.id is null then
    insert into public.opportunity_pricing_workbook_sheets (
      workbook_id,
      organization_id,
      opportunity_id,
      name,
      sheet_order,
      is_default,
      worksheet_data,
      pricing_summary,
      extracted_pricing_data,
      version,
      created_by,
      updated_by
    )
    values (
      v_workbook.id,
      p_organization_id,
      p_opportunity_id,
      v_sheet_name,
      0,
      true,
      v_worksheet_data,
      coalesce(p_pricing_summary, '{}'::jsonb),
      coalesce(p_extracted_pricing_data, '{}'::jsonb),
      v_version,
      p_user_id,
      p_user_id
    )
    returning * into v_sheet;
  end if;

  perform public.write_intelligence_event(
    jsonb_build_object(
      'organizationId', p_organization_id,
      'userId', auth.uid(),
      'projectId', v_workbook.project_id,
      'opportunityId', p_opportunity_id,
      'module', 'pricing_worksheets',
      'eventFamily', 'commercial_action',
      'eventType', 'worksheet_saved',
      'action', 'saved',
      'entityType', 'pricing_worksheet_page',
      'entityId', v_sheet.id,
      'parentEntityType', 'pricing_workbook',
      'parentEntityId', v_workbook.id,
      'relatedEntities', '[]'::jsonb,
      'lineageRefs', '[]'::jsonb,
      'sourceChannel', 'system',
      'sourceRequestId', v_save_request_id,
      'diffData', '{}'::jsonb,
      'metadata', jsonb_build_object(
        'workbookId', v_workbook.id,
        'workbookName', v_workbook.name,
        'sheetId', v_sheet.id,
        'sheetName', v_sheet.name,
        'worksheetId', v_workbook.id,
        'worksheetName', v_workbook.name,
        'version', v_version,
        'tradePackage', v_workbook.trade_package,
        'userId', p_user_id,
        'projectId', v_workbook.project_id,
        'source', 'system',
        'ownerType',
        case
          when v_workbook.variation_id is not null then 'variation'
          when v_workbook.quote_id is not null then 'quote'
          else 'opportunity'
        end,
        'ownerVariationId', v_workbook.variation_id,
        'ownerQuoteId', v_workbook.quote_id,
        'structureSummary', public._pricing_worksheet_structure_summary(v_worksheet_data)
      ),
      'privacyClassification', 'financial_sensitive',
      'visibilityScope', 'organization',
      'containsFinancialData', true,
      'containsPersonalData', false,
      'containsAttachmentContent', false,
      'occurredAt', now()
    )
  );

  return jsonb_build_object(
    'workbook', row_to_json(v_workbook),
    'sheet', row_to_json(v_sheet),
    'sheets', (
      select coalesce(jsonb_agg(row_to_json(sheet) order by sheet.sheet_order asc, sheet.created_at asc), '[]'::jsonb)
      from public.opportunity_pricing_workbook_sheets sheet
      where sheet.workbook_id = v_workbook.id
        and sheet.organization_id = p_organization_id
        and sheet.opportunity_id = p_opportunity_id
    )
  );
end;
$$;


ALTER FUNCTION "public"."save_pricing_workbook_active_sheet"("p_organization_id" "uuid", "p_opportunity_id" "uuid", "p_project_id" "uuid", "p_quote_id" "uuid", "p_user_id" "uuid", "p_variation_id" "uuid", "p_workbook_id" "uuid", "p_sheet_id" "uuid", "p_name" "text", "p_trade_package" "text", "p_worksheet_data" "jsonb", "p_pricing_summary" "jsonb", "p_extracted_pricing_data" "jsonb", "p_version" integer, "p_save_request_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_project_claim_draft"("p_organization_id" "uuid", "p_project_id" "uuid", "p_claim_id" "uuid", "p_expected_updated_at" timestamp with time zone, "p_claim_title" "text", "p_claim_type" "text", "p_status" "text", "p_claim_date" "date", "p_due_date" "date", "p_period_start" "date", "p_period_end" "date", "p_percent_complete" numeric, "p_paid_amount" numeric, "p_retention_method" "text", "p_retention_scale_bands" "jsonb", "p_retention_percent" numeric, "p_retention_released_amount" numeric, "p_notes" "text", "p_line_items" "jsonb") RETURNS TABLE("id" "uuid", "updated_at" timestamp with time zone, "claim_amount" numeric, "linked_quote_value" numeric, "linked_approved_variations" numeric, "previous_claims_total" numeric, "revised_contract_value" numeric, "percent_complete" numeric, "paid_amount" numeric, "status" "text", "retention_percent" numeric, "retention_withheld_amount" numeric, "retention_released_amount" numeric, "retention_held_to_date" numeric, "retention_released_to_date" numeric, "retention_balance" numeric, "net_claim_excl_gst" numeric, "gst_amount" numeric, "total_payable" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  resolved_retention_method text := case
    when coalesce(p_retention_method, 'flat') = 'sliding_scale' then 'sliding_scale'
    else 'flat'
  end;
begin
  if auth.uid() is null then
    raise exception 'Authentication is required';
  end if;

  if not public.is_member_of_organization(p_organization_id) then
    raise exception 'Not authorized for this organization';
  end if;

  if p_expected_updated_at is null then
    raise exception 'Claim version is required. Please refresh and try again.'
      using errcode = '40001';
  end if;

  if not exists (
    select 1
    from public.organization_projects p
    where p.id = p_project_id
      and p.organization_id = p_organization_id
  ) then
    raise exception 'Project not found for organization';
  end if;

  if not exists (
    select 1
    from public.project_claims c
    where c.id = p_claim_id
      and c.organization_id = p_organization_id
      and c.project_id = p_project_id
  ) then
    raise exception 'Claim not found';
  end if;

  if exists (
    select 1
    from public.project_claims c
    where c.id = p_claim_id
      and c.organization_id = p_organization_id
      and c.project_id = p_project_id
      and c.updated_at is distinct from p_expected_updated_at
  ) then
    raise exception 'This claim was updated by another user. Refresh and try again.'
      using errcode = '40001';
  end if;

  perform public.sync_project_claim_line_items(
    p_organization_id,
    p_project_id,
    p_claim_id,
    p_line_items,
    null
  );

  update public.project_claims c
  set
    claim_title = coalesce(nullif(btrim(p_claim_title), ''), c.claim_title),
    claim_type = case
      when p_claim_type in ('Progress', 'Deposit', 'Final') then p_claim_type
      else c.claim_type
    end,
    status = case
      when p_status in ('Draft', 'Submitted', 'Unpaid', 'Paid', 'Overdue', 'Cancelled') then p_status
      else c.status
    end,
    claim_date = p_claim_date,
    due_date = p_due_date,
    period_start = p_period_start,
    period_end = p_period_end,
    paid_amount = round(greatest(0, coalesce(p_paid_amount, 0)), 2),
    retention_method = resolved_retention_method,
    retention_scale_bands = case
      when resolved_retention_method = 'sliding_scale' then coalesce(p_retention_scale_bands, '[]'::jsonb)
      else null
    end,
    retention_percent = round(
      greatest(0, least(100, coalesce(p_retention_percent, c.retention_percent, 0))),
      3
    ),
    retention_released_amount = round(
      greatest(0, coalesce(p_retention_released_amount, c.retention_released_amount, 0)),
      2
    ),
    notes = coalesce(p_notes, '')
  where c.id = p_claim_id
    and c.organization_id = p_organization_id
    and c.project_id = p_project_id;

  perform public.recalculate_project_claim_snapshots(
    p_organization_id,
    p_project_id
  );

  return query
  select
    c.id,
    c.updated_at,
    c.claim_amount,
    c.linked_quote_value,
    c.linked_approved_variations,
    c.previous_claims_total,
    c.revised_contract_value,
    c.percent_complete,
    c.paid_amount,
    c.status,
    c.retention_percent,
    c.retention_withheld_amount,
    c.retention_released_amount,
    c.retention_held_to_date,
    c.retention_released_to_date,
    c.retention_balance,
    c.net_claim_excl_gst,
    c.gst_amount,
    c.total_payable
  from public.project_claims c
  where c.id = p_claim_id
    and c.organization_id = p_organization_id
    and c.project_id = p_project_id;
end;
$$;


ALTER FUNCTION "public"."save_project_claim_draft"("p_organization_id" "uuid", "p_project_id" "uuid", "p_claim_id" "uuid", "p_expected_updated_at" timestamp with time zone, "p_claim_title" "text", "p_claim_type" "text", "p_status" "text", "p_claim_date" "date", "p_due_date" "date", "p_period_start" "date", "p_period_end" "date", "p_percent_complete" numeric, "p_paid_amount" numeric, "p_retention_method" "text", "p_retention_scale_bands" "jsonb", "p_retention_percent" numeric, "p_retention_released_amount" numeric, "p_notes" "text", "p_line_items" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_project_purchase_order_draft"("p_organization_id" "uuid", "p_project_id" "uuid", "p_purchase_order_id" "uuid", "p_expected_updated_at" timestamp with time zone, "p_purchase_order_title" "text", "p_purchase_order_number" "text", "p_status" "text", "p_origin" "text", "p_supplier_id" "uuid", "p_issued_to_label" "text", "p_supplier_contact" "text", "p_supplier_name_snapshot" "text", "p_supplier_email_snapshot" "text", "p_supplier_phone_snapshot" "text", "p_requested_by" "text", "p_requested_date" "date", "p_due_date" "date", "p_sent_to_client_at" timestamp with time zone, "p_approved_at" timestamp with time zone, "p_invoice_ready" boolean, "p_notes" "text", "p_margin_percent" numeric, "p_discount_amount" numeric, "p_contingency_amount" numeric, "p_gst_percent" numeric, "p_include_margin_in_export" boolean, "p_include_discount_in_export" boolean, "p_include_contingency_in_export" boolean, "p_line_items" "jsonb", "p_attachments" "jsonb") RETURNS TABLE("id" "uuid", "updated_at" timestamp with time zone, "subtotal" numeric, "gst_total" numeric, "total_purchase_order_price" numeric, "status" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  existing_row public.project_purchase_orders%rowtype;
  updated_row public.project_purchase_orders%rowtype;
  normalized_line_items_json jsonb := '[]'::jsonb;
  existing_line_item_signature jsonb := '[]'::jsonb;
  incoming_line_item_signature jsonb := '[]'::jsonb;
  section_labour_total numeric := 0;
  section_materials_total numeric := 0;
  section_subcontractors_total numeric := 0;
  section_plant_total numeric := 0;
  section_margin_total numeric := 0;
  computed_subtotal numeric := 0;
  computed_margin numeric := 0;
  computed_discount numeric := 0;
  computed_contingency numeric := 0;
  pre_gst_total numeric := 0;
  computed_gst_total numeric := 0;
  computed_grand_total numeric := 0;
  invalid_attachment_count integer := 0;
  cost_item_revision_key text;
begin
  if auth.uid() is null then
    raise exception 'Authentication is required';
  end if;

  if not public.has_org_permission(p_organization_id, 'purchase_orders.write') then
    raise exception 'Not authorized for this organization';
  end if;

  if p_expected_updated_at is null then
    raise exception 'Purchase order version is required. Please refresh and try again.'
      using errcode = '40001';
  end if;

  if not exists (
    select 1
    from public.organization_projects p
    where p.id = p_project_id
      and p.organization_id = p_organization_id
  ) then
    raise exception 'Project not found for organization';
  end if;

  if p_supplier_id is not null and not exists (
    select 1
    from public.organization_suppliers s
    where s.id = p_supplier_id
      and s.organization_id = p_organization_id
  ) then
    raise exception 'Supplier does not belong to this organization';
  end if;

  select *
  into existing_row
  from public.project_purchase_orders po
  where po.id = p_purchase_order_id
    and po.organization_id = p_organization_id
    and po.project_id = p_project_id
  for update;

  if not found then
    raise exception 'Purchase order not found';
  end if;

  if existing_row.updated_at is distinct from p_expected_updated_at then
    raise exception 'This purchase order was updated by another user. Refresh and try again.'
      using errcode = '40001';
  end if;

  with normalized_line_items as (
    select
      coalesce(
        existing_synced_line.id,
        parsed.line_id,
        gen_random_uuid()
      ) as resolved_id,
      coalesce(
        existing_synced_line.line_uid,
        existing_line_by_id.line_uid,
        parsed.line_uid,
        gen_random_uuid()
      ) as line_uid,
      coalesce(
        existing_synced_line.cost_item_id,
        existing_line_by_id.cost_item_id,
        parsed.cost_item_id
      ) as cost_item_id,
      coalesce(
        existing_synced_line.source_cost_item_id,
        existing_line_by_id.source_cost_item_id,
        parsed.source_cost_item_id
      ) as source_cost_item_id,
      coalesce(
        existing_synced_line.section,
        case
          when line.item->>'section' in ('Labour', 'Materials', 'Subcontractors', 'Plant', 'Margin') then line.item->>'section'
          else 'Labour'
        end
      ) as section,
      coalesce(existing_synced_line.description, coalesce(line.item->>'description', '')) as description,
      coalesce(existing_synced_line.quantity, coalesce(nullif(line.item->>'quantity', '')::numeric, 0)) as quantity,
      coalesce(existing_synced_line.unit, coalesce(line.item->>'unit', '')) as unit,
      coalesce(nullif(line.item->>'rate', '')::numeric, 0) as rate,
      (line.ordinality - 1)::integer as sort_order,
      parsed.source_time_sheet_entry_id
    from jsonb_array_elements(coalesce(p_line_items, '[]'::jsonb)) with ordinality as line(item, ordinality)
    left join lateral (
      select
        case
          when nullif(line.item->>'id', '') is null then null
          else (line.item->>'id')::uuid
        end as line_id,
        case
          when nullif(line.item->>'line_uid', '') is null then null
          else (line.item->>'line_uid')::uuid
        end as line_uid,
        case
          when nullif(line.item->>'cost_item_id', '') is null then null
          else (line.item->>'cost_item_id')::uuid
        end as cost_item_id,
        case
          when nullif(line.item->>'source_cost_item_id', '') is null then null
          else (line.item->>'source_cost_item_id')::uuid
        end as source_cost_item_id,
        case
          when nullif(line.item->>'source_time_sheet_entry_id', '') is null then null
          else (line.item->>'source_time_sheet_entry_id')::uuid
        end as source_time_sheet_entry_id
    ) parsed on true
    left join public.project_purchase_order_line_items existing_synced_line
      on existing_synced_line.organization_id = p_organization_id
      and existing_synced_line.project_id = p_project_id
      and existing_synced_line.purchase_order_id = p_purchase_order_id
      and existing_synced_line.source_time_sheet_entry_id = parsed.source_time_sheet_entry_id
    left join public.project_purchase_order_line_items existing_line_by_id
      on existing_line_by_id.organization_id = p_organization_id
      and existing_line_by_id.project_id = p_project_id
      and existing_line_by_id.purchase_order_id = p_purchase_order_id
      and existing_line_by_id.id = parsed.line_id
  )
  select
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'id', resolved_id,
          'line_uid', line_uid,
          'cost_item_id', cost_item_id,
          'source_cost_item_id', source_cost_item_id,
          'section', section,
          'description', description,
          'quantity', quantity,
          'unit', unit,
          'rate', rate,
          'sort_order', sort_order,
          'source_time_sheet_entry_id', source_time_sheet_entry_id
        )
        order by sort_order
      ),
      '[]'::jsonb
    ),
    coalesce(sum(case when section = 'Labour' then round(quantity * rate, 2) else 0 end), 0),
    coalesce(sum(case when section = 'Materials' then round(quantity * rate, 2) else 0 end), 0),
    coalesce(sum(case when section = 'Subcontractors' then round(quantity * rate, 2) else 0 end), 0),
    coalesce(sum(case when section = 'Plant' then round(quantity * rate, 2) else 0 end), 0),
    coalesce(sum(case when section = 'Margin' then round(quantity * rate, 2) else 0 end), 0),
    coalesce(sum(round(quantity * rate, 2)), 0)
  into
    normalized_line_items_json,
    section_labour_total,
    section_materials_total,
    section_subcontractors_total,
    section_plant_total,
    section_margin_total,
    computed_subtotal
  from normalized_line_items;

  computed_margin := computed_subtotal * (coalesce(p_margin_percent, 0) / 100);
  computed_discount := coalesce(p_discount_amount, 0);
  computed_contingency := coalesce(p_contingency_amount, 0);
  pre_gst_total := greatest(0, computed_subtotal + computed_margin + computed_contingency - computed_discount);
  computed_gst_total := round(pre_gst_total * (coalesce(p_gst_percent, 0) / 100), 2);
  computed_grand_total := round(pre_gst_total + computed_gst_total, 2);

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'line_key', coalesce(li.line_uid::text, li.id::text),
        'section', li.section,
        'quantity', round(li.quantity, 3),
        'unit', li.unit,
        'rate', round(li.rate, 2),
        'total', round(li.total, 2)
      )
      order by coalesce(li.line_uid::text, li.id::text)
    ),
    '[]'::jsonb
  )
  into existing_line_item_signature
  from public.project_purchase_order_line_items li
  where li.organization_id = p_organization_id
    and li.project_id = p_project_id
    and li.purchase_order_id = p_purchase_order_id;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'line_key', coalesce(line.item->>'line_uid', line.item->>'id'),
        'section', line.item->>'section',
        'quantity', round(coalesce(nullif(line.item->>'quantity', '')::numeric, 0), 3),
        'unit', coalesce(line.item->>'unit', ''),
        'rate', round(coalesce(nullif(line.item->>'rate', '')::numeric, 0), 2),
        'total', round(
          coalesce(nullif(line.item->>'quantity', '')::numeric, 0)
          * coalesce(nullif(line.item->>'rate', '')::numeric, 0),
          2
        )
      )
      order by coalesce(line.item->>'line_uid', line.item->>'id')
    ),
    '[]'::jsonb
  )
  into incoming_line_item_signature
  from jsonb_array_elements(normalized_line_items_json) as line(item);

  select count(*)
  into invalid_attachment_count
  from jsonb_array_elements(coalesce(p_attachments, '[]'::jsonb)) as att(item)
  where nullif(att.item->>'storagePath', '') is null
    and nullif(att.item->>'externalUrl', '') is null;

  if invalid_attachment_count > 0 then
    raise exception 'Each attachment must include storagePath or externalUrl';
  end if;

  update public.project_purchase_orders po
  set
    purchase_order_title = coalesce(nullif(btrim(p_purchase_order_title), ''), po.purchase_order_number),
    purchase_order_number = coalesce(nullif(btrim(p_purchase_order_number), ''), po.purchase_order_number),
    status = p_status,
    origin = p_origin,
    supplier_id = p_supplier_id,
    issued_to_label = coalesce(p_issued_to_label, ''),
    supplier_contact = coalesce(p_supplier_contact, ''),
    supplier_name_snapshot = coalesce(p_supplier_name_snapshot, ''),
    supplier_email_snapshot = coalesce(p_supplier_email_snapshot, ''),
    supplier_phone_snapshot = coalesce(p_supplier_phone_snapshot, ''),
    requested_by = coalesce(p_requested_by, ''),
    requested_date = p_requested_date,
    due_date = p_due_date,
    sent_to_client_at = p_sent_to_client_at,
    approved_at = p_approved_at,
    invoice_ready = coalesce(p_invoice_ready, false),
    notes = coalesce(p_notes, ''),
    labour_total = round(section_labour_total, 2),
    materials_total = round(section_materials_total, 2),
    subcontractors_total = round(section_subcontractors_total, 2),
    plant_total = round(section_plant_total, 2),
    margin_total = round(section_margin_total, 2),
    subtotal = round(computed_subtotal, 2),
    margin_percent = round(coalesce(p_margin_percent, 0), 3),
    discount_amount = round(coalesce(p_discount_amount, 0), 2),
    contingency_amount = round(coalesce(p_contingency_amount, 0), 2),
    gst_percent = round(coalesce(p_gst_percent, 0), 3),
    include_margin_in_export = coalesce(p_include_margin_in_export, true),
    include_discount_in_export = coalesce(p_include_discount_in_export, false),
    include_contingency_in_export = coalesce(p_include_contingency_in_export, false),
    gst_total = round(computed_gst_total, 2),
    total_purchase_order_price = computed_grand_total,
    updated_at = statement_timestamp()
  where po.id = p_purchase_order_id
    and po.organization_id = p_organization_id
    and po.project_id = p_project_id
  returning * into updated_row;

  delete from public.project_purchase_order_line_items li
  where li.organization_id = p_organization_id
    and li.project_id = p_project_id
    and li.purchase_order_id = p_purchase_order_id;

  insert into public.project_purchase_order_line_items (
    id,
    organization_id,
    project_id,
    purchase_order_id,
    line_uid,
    cost_item_id,
    source_cost_item_id,
    section,
    description,
    quantity,
    unit,
    rate,
    total,
    sort_order,
    source_time_sheet_entry_id
  )
  select
    (item->>'id')::uuid,
    p_organization_id,
    p_project_id,
    p_purchase_order_id,
    (item->>'line_uid')::uuid,
    case
      when nullif(item->>'cost_item_id', '') is null then null
      else (item->>'cost_item_id')::uuid
    end,
    case
      when nullif(item->>'source_cost_item_id', '') is null then null
      else (item->>'source_cost_item_id')::uuid
    end,
    item->>'section',
    coalesce(item->>'description', ''),
    coalesce(nullif(item->>'quantity', '')::numeric, 0),
    coalesce(item->>'unit', ''),
    coalesce(nullif(item->>'rate', '')::numeric, 0),
    round(
      coalesce(nullif(item->>'quantity', '')::numeric, 0)
      * coalesce(nullif(item->>'rate', '')::numeric, 0),
      2
    ),
    coalesce(nullif(item->>'sort_order', '')::integer, 0),
    case
      when nullif(item->>'source_time_sheet_entry_id', '') is null then null
      else (item->>'source_time_sheet_entry_id')::uuid
    end
  from jsonb_array_elements(normalized_line_items_json) as line(item);

  delete from public.project_purchase_order_attachments a
  where a.organization_id = p_organization_id
    and a.project_id = p_project_id
    and a.purchase_order_id = p_purchase_order_id;

  insert into public.project_purchase_order_attachments (
    id,
    organization_id,
    project_id,
    purchase_order_id,
    file_kind,
    file_name,
    storage_path,
    external_url,
    notes,
    uploaded_by
  )
  select
    case
      when nullif(att.item->>'id', '') is null then gen_random_uuid()
      else (att.item->>'id')::uuid
    end,
    p_organization_id,
    p_project_id,
    p_purchase_order_id,
    case
      when att.item->>'type' in ('Drawing', 'Email', 'Site Instruction', 'Other') then att.item->>'type'
      else 'Other'
    end,
    coalesce(nullif(att.item->>'name', ''), 'Attachment'),
    nullif(att.item->>'storagePath', ''),
    nullif(att.item->>'externalUrl', ''),
    coalesce(att.item->>'notes', ''),
    auth.uid()
  from jsonb_array_elements(coalesce(p_attachments, '[]'::jsonb)) as att(item);

  if existing_row.status is distinct from updated_row.status then
    insert into public.project_purchase_order_status_events (
      organization_id,
      project_id,
      purchase_order_id,
      from_status,
      to_status,
      changed_by
    ) values (
      p_organization_id,
      p_project_id,
      p_purchase_order_id,
      existing_row.status,
      updated_row.status,
      auth.uid()
    );
  end if;

  if updated_row.invoice_ready then
    insert into public.project_purchase_order_invoice_items (
      organization_id,
      project_id,
      purchase_order_id,
      amount,
      status
    ) values (
      p_organization_id,
      p_project_id,
      p_purchase_order_id,
      round(computed_grand_total, 2),
      'Ready'
    )
    on conflict (purchase_order_id)
    do update set
      amount = excluded.amount,
      status = excluded.status,
      updated_at = now();
  else
    delete from public.project_purchase_order_invoice_items ii
    where ii.organization_id = p_organization_id
      and ii.project_id = p_project_id
      and ii.purchase_order_id = p_purchase_order_id;
  end if;

  if existing_line_item_signature is distinct from incoming_line_item_signature then
    perform public.reset_supplier_invoice_match_approvals_for_purchase_order_change(
      p_organization_id,
      p_purchase_order_id,
      array['line_items']
    );
  end if;

  cost_item_revision_key := public.begin_cost_item_revision('project_purchase_order', p_purchase_order_id);
  perform public.supersede_previous_cost_items('project_purchase_order', p_purchase_order_id, cost_item_revision_key);
  perform public.upsert_cost_items_for_project_purchase_order(p_purchase_order_id, cost_item_revision_key);

  return query
  select
    updated_row.id,
    updated_row.updated_at,
    updated_row.subtotal,
    updated_row.gst_total,
    updated_row.total_purchase_order_price,
    updated_row.status;
end;
$$;


ALTER FUNCTION "public"."save_project_purchase_order_draft"("p_organization_id" "uuid", "p_project_id" "uuid", "p_purchase_order_id" "uuid", "p_expected_updated_at" timestamp with time zone, "p_purchase_order_title" "text", "p_purchase_order_number" "text", "p_status" "text", "p_origin" "text", "p_supplier_id" "uuid", "p_issued_to_label" "text", "p_supplier_contact" "text", "p_supplier_name_snapshot" "text", "p_supplier_email_snapshot" "text", "p_supplier_phone_snapshot" "text", "p_requested_by" "text", "p_requested_date" "date", "p_due_date" "date", "p_sent_to_client_at" timestamp with time zone, "p_approved_at" timestamp with time zone, "p_invoice_ready" boolean, "p_notes" "text", "p_margin_percent" numeric, "p_discount_amount" numeric, "p_contingency_amount" numeric, "p_gst_percent" numeric, "p_include_margin_in_export" boolean, "p_include_discount_in_export" boolean, "p_include_contingency_in_export" boolean, "p_line_items" "jsonb", "p_attachments" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_project_qa_definition_internal_v1"("p_organization_id" "uuid", "p_project_id" "uuid", "p_project_qa_id" "uuid", "p_name" "text", "p_description" "text", "p_status" "text", "p_sections" "jsonb") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare s jsonb; f jsonb; o jsonb; next_version integer;
begin
  if auth.uid() is null or not public.can_access_qa_project(p_organization_id,p_project_id,'qa.write') then raise exception 'Not authorized' using errcode='42501'; end if;
  if p_status not in ('draft','active') then raise exception 'Invalid editable Project QA status' using errcode='TS422'; end if;
  perform public.qa_assert_definition(p_sections);
  update public.project_qas set name=btrim(p_name),description=coalesce(p_description,''),status=p_status,archived_at=null,updated_by=auth.uid(),definition_version=definition_version+1
  where organization_id=p_organization_id and project_id=p_project_id and id=p_project_qa_id and status<>'archived' returning definition_version into next_version;
  if next_version is null then raise exception 'Project QA not found or archived' using errcode='TS404'; end if;
  delete from public.project_qa_sections where organization_id=p_organization_id and project_id=p_project_id and project_qa_id=p_project_qa_id;
  for s in select value from jsonb_array_elements(p_sections) loop
    insert into public.project_qa_sections(id,organization_id,project_id,project_qa_id,title,description,sort_order) values((s->>'id')::uuid,p_organization_id,p_project_id,p_project_qa_id,btrim(s->>'title'),coalesce(s->>'description',''),coalesce((s->>'sortOrder')::integer,0));
    for f in select value from jsonb_array_elements(coalesce(s->'fields','[]'::jsonb)) loop
      insert into public.project_qa_fields(id,organization_id,project_id,project_qa_id,section_id,field_type,label,description,instructions,required,allow_na,requirement,acceptance_criteria,reference_text,photo_required,minimum_photos,file_required,require_comment_on_fail,require_photo_on_fail,create_issue_on_fail,require_rectification_on_fail,block_completion_on_fail,require_supervisor_review_on_fail,ai_review_enabled,ai_review_instruction,include_in_report,configuration,configuration_schema_version,sort_order)
      values((f->>'id')::uuid,p_organization_id,p_project_id,p_project_qa_id,(s->>'id')::uuid,f->>'fieldType',btrim(f->>'label'),coalesce(f->>'description',''),coalesce(f->>'instructions',''),coalesce((f->>'required')::boolean,false),coalesce((f->>'allowNa')::boolean,false),coalesce(f->>'requirement',''),coalesce(f->>'acceptanceCriteria',''),coalesce(f->>'referenceText',''),coalesce((f->>'photoRequired')::boolean,false),coalesce((f->>'minimumPhotos')::integer,0),coalesce((f->>'fileRequired')::boolean,false),coalesce((f->>'requireCommentOnFail')::boolean,false),coalesce((f->>'requirePhotoOnFail')::boolean,false),coalesce((f->>'createIssueOnFail')::boolean,false),coalesce((f->>'requireRectificationOnFail')::boolean,false),coalesce((f->>'blockCompletionOnFail')::boolean,false),coalesce((f->>'requireSupervisorReviewOnFail')::boolean,false),coalesce((f->>'aiReviewEnabled')::boolean,false),coalesce(f->>'aiReviewInstruction',''),coalesce((f->>'includeInReport')::boolean,true),coalesce(f->'configuration','{}'::jsonb),coalesce((f->>'configurationSchemaVersion')::integer,1),coalesce((f->>'sortOrder')::integer,0));
      for o in select value from jsonb_array_elements(coalesce(f->'options','[]'::jsonb)) loop
        insert into public.project_qa_field_options(id,organization_id,project_id,project_qa_id,field_id,label,value,sort_order) values((o->>'id')::uuid,p_organization_id,p_project_id,p_project_qa_id,(f->>'id')::uuid,btrim(o->>'label'),btrim(o->>'value'),coalesce((o->>'sortOrder')::integer,0));
      end loop;
    end loop;
  end loop;
  return next_version;
end; $$;


ALTER FUNCTION "public"."save_project_qa_definition_internal_v1"("p_organization_id" "uuid", "p_project_id" "uuid", "p_project_qa_id" "uuid", "p_name" "text", "p_description" "text", "p_status" "text", "p_sections" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_project_qa_definition_v1"("p_organization_id" "uuid", "p_project_id" "uuid", "p_project_qa_id" "uuid", "p_name" "text", "p_description" "text", "p_status" "text", "p_sections" "jsonb", "p_expected_version" integer) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  qa_row public.project_qas%rowtype;
begin
  if auth.uid() is null
    or not public.can_access_qa_project(p_organization_id, p_project_id, 'qa.write')
  then
    raise exception 'Not authorized' using errcode = '42501';
  end if;

  select * into qa_row
  from public.project_qas project_qa
  where project_qa.organization_id = p_organization_id
    and project_qa.project_id = p_project_id
    and project_qa.id = p_project_qa_id
  for update;

  if not found then
    raise exception 'Project QA not found' using errcode = 'TS404';
  end if;
  if qa_row.status = 'archived' then
    raise exception 'Archived Project QA is read-only' using errcode = 'TS409';
  end if;
  if qa_row.status <> p_status then
    raise exception 'Use the explicit Project QA lifecycle action to change status' using errcode = 'TS409';
  end if;
  if qa_row.definition_version is distinct from p_expected_version then
    raise exception E'This QA definition has been updated by someone else.\n\nReload the latest version before saving your changes.' using errcode = 'TS409';
  end if;

  return public.save_project_qa_definition_internal_v1(
    p_organization_id, p_project_id, p_project_qa_id, p_name,
    p_description, p_status, p_sections
  );
end;
$$;


ALTER FUNCTION "public"."save_project_qa_definition_v1"("p_organization_id" "uuid", "p_project_id" "uuid", "p_project_qa_id" "uuid", "p_name" "text", "p_description" "text", "p_status" "text", "p_sections" "jsonb", "p_expected_version" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_project_qa_response_v1"("p_organization_id" "uuid", "p_project_id" "uuid", "p_run_id" "uuid", "p_response_id" "uuid", "p_expected_lock_version" integer, "p_value" "jsonb") RETURNS TABLE("response_lock_version" integer, "response_updated_at" timestamp with time zone, "run_lock_version" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  response_row public.project_qa_responses%rowtype;
  run_row public.project_qa_runs%rowtype;
  next_lock integer;
  next_updated timestamptz;
  next_run_lock integer;
  selected_values jsonb;
  captured_options jsonb;
  selected_count integer;
  matched_count integer;
  person_name text;
  product_value jsonb;
begin
  if auth.uid() is null or not public.can_access_qa_project(p_organization_id,p_project_id,'qa.inspect') then
    raise exception 'Not authorized to update QA Record' using errcode='42501';
  end if;
  select * into run_row from public.project_qa_runs run
  where run.organization_id=p_organization_id and run.project_id=p_project_id and run.id=p_run_id for update;
  if not found then raise exception 'QA Record not found' using errcode='TS404'; end if;
  if run_row.status<>'in_progress' then raise exception 'Only an in-progress QA Record can be updated' using errcode='TS409'; end if;
  select * into response_row from public.project_qa_responses response
  where response.organization_id=p_organization_id and response.project_id=p_project_id
    and response.run_id=p_run_id and response.id=p_response_id for update;
  if not found then raise exception 'QA response not found' using errcode='TS404'; end if;
  if response_row.lock_version<>p_expected_lock_version then raise exception 'This QA response changed elsewhere. Reload before retrying.' using errcode='TS409'; end if;

  if response_row.field_type in ('single_select','multi_select') then
    selected_values:=coalesce(p_value->'selectedOptionValues','[]'::jsonb);
    if jsonb_typeof(selected_values)<>'array' then raise exception 'Selected options must be an array' using errcode='TS422'; end if;
    select count(*),count(distinct value) into selected_count,matched_count from jsonb_array_elements_text(selected_values);
    if selected_count<>matched_count then raise exception 'Selected options must be unique' using errcode='TS422'; end if;
    if response_row.field_type='single_select' and selected_count>1 then raise exception 'Single Select accepts one option' using errcode='TS422'; end if;
    select coalesce(jsonb_agg(option_value order by (option_value->>'sortOrder')::integer,option_value->>'id'),'[]'::jsonb),count(*)
      into captured_options,matched_count
    from jsonb_array_elements(coalesce(response_row.field_snapshot->'options','[]'::jsonb)) option_value
    where option_value->>'value' in (select value from jsonb_array_elements_text(selected_values));
    if matched_count<>selected_count then raise exception 'A selected option is not part of this QA Record snapshot' using errcode='TS422'; end if;
  else captured_options:='[]'::jsonb; end if;

  if response_row.field_type='inspection_check' and nullif(p_value->>'inspectionResult','') is not null then
    if p_value->>'inspectionResult' not in ('pass','fail','na') then raise exception 'Invalid check result' using errcode='TS422'; end if;
    if p_value->>'inspectionResult'='na' and coalesce((response_row.field_snapshot->>'allowNa')::boolean,false)=false then raise exception 'N/A is not allowed for this check' using errcode='TS422'; end if;
  end if;
  if response_row.field_type in ('number','measurement') and nullif(p_value->>'numericValue','') is not null then
    if lower(p_value->>'numericValue') in ('nan','infinity','-infinity','inf','-inf') then raise exception 'Numeric responses must be finite' using errcode='TS422'; end if;
    perform (p_value->>'numericValue')::numeric;
  end if;
  if response_row.field_type='date' and nullif(p_value->>'dateValue','') is not null then perform (p_value->>'dateValue')::date; end if;

  if response_row.field_type='person' then
    if nullif(p_value->>'personUserId','') is not null then
      select member.display_name into person_name from public.organization_members member
      where member.organization_id=p_organization_id and member.user_id=(p_value->>'personUserId')::uuid limit 1;
      if person_name is null then raise exception 'Selected person is not an organization member' using errcode='TS422'; end if;
    else
      person_name:=left(btrim(coalesce(p_value->>'personDisplayName','')),240);
    end if;
  end if;

  if response_row.field_type='product_material' then
    product_value:=case when p_value ? 'productMaterialValue' and jsonb_typeof(p_value->'productMaterialValue')<>'null' then p_value->'productMaterialValue' else null end;
    if product_value is not null and not public.qa_product_material_value_is_valid(product_value) then raise exception 'Invalid Product / Material response' using errcode='TS422'; end if;
  end if;

  update public.project_qa_responses response set
    text_value=case when response_row.field_type in ('short_text','long_text') then coalesce(p_value->>'textValue','') else null end,
    numeric_value=case when response_row.field_type in ('number','measurement') and nullif(p_value->>'numericValue','') is not null then (p_value->>'numericValue')::numeric else null end,
    boolean_value=case when response_row.field_type in ('yes_no','checkbox') and p_value ? 'booleanValue' and jsonb_typeof(p_value->'booleanValue')='boolean' then (p_value->>'booleanValue')::boolean else null end,
    date_value=case when response_row.field_type='date' and nullif(p_value->>'dateValue','') is not null then (p_value->>'dateValue')::date else null end,
    inspection_result=case when response_row.field_type='inspection_check' then nullif(p_value->>'inspectionResult','') else null end,
    selected_options=captured_options,
    person_user_id=case when response_row.field_type='person' and nullif(p_value->>'personUserId','') is not null then (p_value->>'personUserId')::uuid else null end,
    person_display_name=case when response_row.field_type='person' then nullif(person_name,'') else null end,
    location_label=case when response_row.field_type='location' then coalesce(p_value->>'locationLabel','') else null end,
    product_material_value=case when response_row.field_type='product_material' then product_value else null end,
    comment=case when response_row.field_type='inspection_check' then coalesce(p_value->>'comment','') else response_row.comment end,
    updated_by=auth.uid(),lock_version=response.lock_version+1
  where response.id=response_row.id returning response.lock_version,response.updated_at into next_lock,next_updated;

  update public.project_qa_runs run set lock_version=run.lock_version+1
  where run.id=run_row.id returning run.lock_version into next_run_lock;
  return query select next_lock,next_updated,next_run_lock;
end;
$$;


ALTER FUNCTION "public"."save_project_qa_response_v1"("p_organization_id" "uuid", "p_project_id" "uuid", "p_run_id" "uuid", "p_response_id" "uuid", "p_expected_lock_version" integer, "p_value" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_project_quote_draft"("p_organization_id" "uuid", "p_project_id" "uuid", "p_quote_id" "uuid", "p_expected_updated_at" timestamp with time zone, "p_quote_title" "text", "p_quote_number" "text", "p_client_name" "text", "p_company_name" "text", "p_contact_person" "text", "p_client_email" "text", "p_client_phone" "text", "p_site_address" "text", "p_project_name" "text", "p_quote_date" "date", "p_expiry_date" "date", "p_status" "text", "p_optional_items_notes" "text", "p_scope_exclusions" "text", "p_assumptions" "text", "p_scope_notes" "text", "p_margin_percent" numeric, "p_discount_amount" numeric, "p_contingency_amount" numeric, "p_gst_percent" numeric, "p_validity_period" "text", "p_payment_terms" "text", "p_retention_percent_default" numeric, "p_lead_time" "text", "p_terms_inclusions" "text", "p_terms_exclusions" "text", "p_clarifications" "text", "p_acceptance_notes" "text", "p_line_items" "jsonb") RETURNS TABLE("id" "uuid", "updated_at" timestamp with time zone, "subtotal" numeric, "optional_subtotal" numeric, "gst_amount" numeric, "total_quote_price" numeric, "status" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  existing_row public.project_quotes%rowtype;
  saved_row public.project_quotes%rowtype;
  computed_subtotal numeric := 0;
  computed_optional_subtotal numeric := 0;
  computed_margin numeric := 0;
  computed_discount numeric := 0;
  computed_contingency numeric := 0;
  pre_gst_total numeric := 0;
  computed_gst numeric := 0;
  computed_grand_total numeric := 0;
  resolved_retention_percent_default numeric := 0;
  saved_status text := 'Draft';
  cost_item_revision_key text;
  resolved_project_source_opportunity_id uuid;
begin
  if auth.uid() is null then
    raise exception 'Authentication is required';
  end if;

  if not public.has_org_permission(p_organization_id, 'quotes.write') then
    raise exception 'Not authorized for this organization';
  end if;

  select p.source_opportunity_id
  into resolved_project_source_opportunity_id
  from public.organization_projects p
  where p.id = p_project_id
    and p.organization_id = p_organization_id;

  if not found then
    raise exception 'Project not found for organization';
  end if;

  if coalesce(nullif(btrim(p_quote_title), ''), '') = '' then
    raise exception 'Quote title is required';
  end if;

  if coalesce(nullif(btrim(p_quote_number), ''), '') = '' then
    raise exception 'Quote number is required';
  end if;

  select
    coalesce(sum(
      case
        when coalesce((line.item->>'isOptional')::boolean, false) then 0
        else round(
          coalesce(nullif(line.item->>'quantity', '')::numeric, 0)
          * coalesce(nullif(line.item->>'rate', '')::numeric, 0),
          2
        )
      end
    ), 0),
    coalesce(sum(
      case
        when coalesce((line.item->>'isOptional')::boolean, false) then round(
          coalesce(nullif(line.item->>'quantity', '')::numeric, 0)
          * coalesce(nullif(line.item->>'rate', '')::numeric, 0),
          2
        )
        else 0
      end
    ), 0)
  into computed_subtotal, computed_optional_subtotal
  from jsonb_array_elements(coalesce(p_line_items, '[]'::jsonb)) as line(item);

  computed_margin := computed_subtotal * (coalesce(p_margin_percent, 0) / 100);
  computed_discount := coalesce(p_discount_amount, 0);
  computed_contingency := coalesce(p_contingency_amount, 0);
  pre_gst_total := greatest(0, computed_subtotal + computed_margin + computed_contingency - computed_discount);
  computed_gst := pre_gst_total * (coalesce(p_gst_percent, 0) / 100);
  computed_grand_total := pre_gst_total + computed_gst;
  resolved_retention_percent_default := greatest(0, least(100, coalesce(p_retention_percent_default, 0)));

  if p_quote_id is not null then
    select *
    into existing_row
    from public.project_quotes q
    where q.id = p_quote_id
      and q.organization_id = p_organization_id
      and q.project_id = p_project_id
    for update;

    if not found then
      raise exception 'Quote not found';
    end if;

    if p_expected_updated_at is null then
      raise exception 'Quote version is required. Please refresh and try again.'
        using errcode = '40001';
    end if;

    if existing_row.updated_at is distinct from p_expected_updated_at then
      raise exception 'This quote was updated by another user. Refresh and try again.'
        using errcode = '40001';
    end if;

    update public.project_quotes q
    set
      quote_title = btrim(p_quote_title),
      quote_number = btrim(p_quote_number),
      client_name = coalesce(p_client_name, ''),
      company_name = coalesce(p_company_name, ''),
      contact_person = coalesce(p_contact_person, ''),
      client_email = coalesce(p_client_email, ''),
      client_phone = coalesce(p_client_phone, ''),
      site_address = coalesce(p_site_address, ''),
      project_name = coalesce(p_project_name, ''),
      quote_date = p_quote_date,
      expiry_date = p_expiry_date,
      status = case
        when p_status in ('Draft', 'Ready to Send', 'Sent', 'Viewed', 'Accepted', 'Rejected', 'Expired') then p_status
        else q.status
      end,
      optional_items_notes = coalesce(p_optional_items_notes, ''),
      scope_exclusions = coalesce(p_scope_exclusions, ''),
      assumptions = coalesce(p_assumptions, ''),
      scope_notes = coalesce(p_scope_notes, ''),
      subtotal = round(computed_subtotal, 2),
      optional_subtotal = round(computed_optional_subtotal, 2),
      margin_percent = round(coalesce(p_margin_percent, 0), 3),
      margin_amount = round(computed_margin, 2),
      discount_amount = round(coalesce(p_discount_amount, 0), 2),
      contingency_amount = round(coalesce(p_contingency_amount, 0), 2),
      gst_percent = round(coalesce(p_gst_percent, 0), 3),
      gst_amount = round(computed_gst, 2),
      total_quote_price = round(computed_grand_total, 2),
      validity_period = coalesce(p_validity_period, ''),
      payment_terms = coalesce(p_payment_terms, ''),
      retention_percent_default = round(resolved_retention_percent_default, 3),
      lead_time = coalesce(p_lead_time, ''),
      terms_inclusions = coalesce(p_terms_inclusions, ''),
      terms_exclusions = coalesce(p_terms_exclusions, ''),
      clarifications = coalesce(p_clarifications, ''),
      acceptance_notes = coalesce(p_acceptance_notes, ''),
      source_opportunity_id = coalesce(q.source_opportunity_id, resolved_project_source_opportunity_id)
    where q.id = p_quote_id
      and q.organization_id = p_organization_id
      and q.project_id = p_project_id
    returning * into saved_row;
  else
    saved_status := case
      when p_status in ('Draft', 'Ready to Send', 'Sent', 'Viewed', 'Accepted', 'Rejected', 'Expired') then p_status
      else 'Draft'
    end;

    insert into public.project_quotes (
      organization_id, project_id, source_opportunity_id, created_by, quote_title, quote_number, client_name, company_name, contact_person,
      client_email, client_phone, site_address, project_name, quote_date, expiry_date, status, optional_items_notes,
      scope_exclusions, assumptions, scope_notes, subtotal, optional_subtotal, margin_percent, margin_amount,
      discount_amount, contingency_amount, gst_percent, gst_amount, total_quote_price, validity_period,
      payment_terms, retention_percent_default, lead_time, terms_inclusions, terms_exclusions, clarifications, acceptance_notes
    ) values (
      p_organization_id, p_project_id, resolved_project_source_opportunity_id, auth.uid(), btrim(p_quote_title), btrim(p_quote_number), coalesce(p_client_name, ''),
      coalesce(p_company_name, ''), coalesce(p_contact_person, ''), coalesce(p_client_email, ''), coalesce(p_client_phone, ''),
      coalesce(p_site_address, ''), coalesce(p_project_name, ''), p_quote_date, p_expiry_date, saved_status,
      coalesce(p_optional_items_notes, ''), coalesce(p_scope_exclusions, ''), coalesce(p_assumptions, ''),
      coalesce(p_scope_notes, ''), round(computed_subtotal, 2), round(computed_optional_subtotal, 2),
      round(coalesce(p_margin_percent, 0), 3), round(computed_margin, 2), round(coalesce(p_discount_amount, 0), 2),
      round(coalesce(p_contingency_amount, 0), 2), round(coalesce(p_gst_percent, 0), 3), round(computed_gst, 2),
      round(computed_grand_total, 2), coalesce(p_validity_period, ''), coalesce(p_payment_terms, ''),
      round(resolved_retention_percent_default, 3), coalesce(p_lead_time, ''), coalesce(p_terms_inclusions, ''),
      coalesce(p_terms_exclusions, ''), coalesce(p_clarifications, ''), coalesce(p_acceptance_notes, '')
    )
    returning * into saved_row;
  end if;

  delete from public.project_quote_line_items li
  where li.organization_id = p_organization_id
    and li.project_id = p_project_id
    and li.quote_id = saved_row.id;

  insert into public.project_quote_line_items (
    id,
    organization_id,
    project_id,
    quote_id,
    section,
    description,
    quantity,
    unit,
    rate,
    total,
    is_optional,
    sort_order,
    source_opportunity_quote_id,
    source_opportunity_quote_line_item_id,
    source_opportunity_quote_number
  )
  select
    case
      when nullif(line.item->>'id', '') is not null then (line.item->>'id')::uuid
      else gen_random_uuid()
    end,
    p_organization_id,
    p_project_id,
    saved_row.id,
    case
      when line.item->>'section' in ('Item', 'Materials', 'Labour', 'Plant', 'Subcontractors', 'Preliminaries') then line.item->>'section'
      else 'Labour'
    end,
    coalesce(line.item->>'description', ''),
    coalesce(nullif(line.item->>'quantity', '')::numeric, 0),
    coalesce(line.item->>'unit', ''),
    coalesce(nullif(line.item->>'rate', '')::numeric, 0),
    round(
      coalesce(nullif(line.item->>'quantity', '')::numeric, 0)
      * coalesce(nullif(line.item->>'rate', '')::numeric, 0),
      2
    ),
    coalesce((line.item->>'isOptional')::boolean, false),
    row_number() over (),
    case
      when nullif(line.item->>'sourceOpportunityQuoteId', '') is not null then (line.item->>'sourceOpportunityQuoteId')::uuid
      else null
    end,
    case
      when nullif(line.item->>'sourceOpportunityQuoteLineItemId', '') is not null then (line.item->>'sourceOpportunityQuoteLineItemId')::uuid
      else null
    end,
    nullif(line.item->>'sourceOpportunityQuoteNumber', '')
  from jsonb_array_elements(coalesce(p_line_items, '[]'::jsonb)) as line(item);

  cost_item_revision_key := public.begin_cost_item_revision('project_quote', saved_row.id);
  perform public.supersede_previous_cost_items('project_quote', saved_row.id, cost_item_revision_key);
  perform public.upsert_cost_items_for_document('project_quote', saved_row.id, cost_item_revision_key);

  return query
  select
    saved_row.id,
    saved_row.updated_at,
    saved_row.subtotal,
    saved_row.optional_subtotal,
    saved_row.gst_amount,
    saved_row.total_quote_price,
    saved_row.status;
end;
$$;


ALTER FUNCTION "public"."save_project_quote_draft"("p_organization_id" "uuid", "p_project_id" "uuid", "p_quote_id" "uuid", "p_expected_updated_at" timestamp with time zone, "p_quote_title" "text", "p_quote_number" "text", "p_client_name" "text", "p_company_name" "text", "p_contact_person" "text", "p_client_email" "text", "p_client_phone" "text", "p_site_address" "text", "p_project_name" "text", "p_quote_date" "date", "p_expiry_date" "date", "p_status" "text", "p_optional_items_notes" "text", "p_scope_exclusions" "text", "p_assumptions" "text", "p_scope_notes" "text", "p_margin_percent" numeric, "p_discount_amount" numeric, "p_contingency_amount" numeric, "p_gst_percent" numeric, "p_validity_period" "text", "p_payment_terms" "text", "p_retention_percent_default" numeric, "p_lead_time" "text", "p_terms_inclusions" "text", "p_terms_exclusions" "text", "p_clarifications" "text", "p_acceptance_notes" "text", "p_line_items" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_project_variation_draft"("p_organization_id" "uuid", "p_project_id" "uuid", "p_variation_id" "uuid", "p_expected_updated_at" timestamp with time zone, "p_variation_title" "text", "p_variation_number" "text", "p_status" "text", "p_origin" "text", "p_requested_by" "text", "p_requested_date" "date", "p_due_date" "date", "p_sent_to_client_at" timestamp with time zone, "p_approved_at" timestamp with time zone, "p_invoice_ready" boolean, "p_notes" "text", "p_margin_percent" numeric, "p_discount_amount" numeric, "p_contingency_amount" numeric, "p_gst_percent" numeric, "p_include_margin_in_export" boolean, "p_include_discount_in_export" boolean, "p_include_contingency_in_export" boolean, "p_validity_period" "text", "p_payment_terms" "text", "p_lead_time" "text", "p_terms_inclusions" "text", "p_terms_exclusions" "text", "p_clarifications" "text", "p_assumptions" "text", "p_line_items" "jsonb", "p_attachments" "jsonb") RETURNS TABLE("id" "uuid", "updated_at" timestamp with time zone, "subtotal" numeric, "gst_total" numeric, "total_variation_price" numeric, "status" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  existing_row public.project_variations%rowtype;
  saved_row public.project_variations%rowtype;
  section_labour_total numeric := 0;
  section_materials_total numeric := 0;
  section_subcontractors_total numeric := 0;
  section_plant_total numeric := 0;
  section_margin_total numeric := 0;
  computed_subtotal numeric := 0;
  computed_margin numeric := 0;
  computed_discount numeric := 0;
  computed_contingency numeric := 0;
  pre_gst_total numeric := 0;
  computed_gst_total numeric := 0;
  computed_grand_total numeric := 0;
  cost_item_revision_key text;
begin
  if auth.uid() is null then
    raise exception 'Authentication is required';
  end if;

  if not public.has_org_permission(p_organization_id, 'variations.write') then
    raise exception 'You do not have permission to save variations for this organization';
  end if;

  if p_variation_id is null then
    raise exception 'Variation id is required';
  end if;

  if p_expected_updated_at is null then
    raise exception 'Variation version is required. Please refresh and try again.'
      using errcode = '40001';
  end if;

  if coalesce(btrim(p_variation_title), '') = '' then
    raise exception 'Variation title is required';
  end if;

  if coalesce(btrim(p_variation_number), '') = '' then
    raise exception 'Variation number is required';
  end if;

  if p_status not in ('Draft', 'Priced', 'Sent', 'Client Review', 'Approved', 'Rejected', 'Invoiced') then
    raise exception 'Variation status must be Draft, Priced, Sent, Client Review, Approved, Rejected, or Invoiced';
  end if;

  if p_origin not in ('Client Request', 'Drawing Revision', 'Site Instruction', 'RFI', 'Unknown') then
    raise exception 'Variation origin must be one of: Client Request, Drawing Revision, Site Instruction, RFI, Unknown';
  end if;

  select *
  into existing_row
  from public.project_variations v
  where v.id = p_variation_id
    and v.organization_id = p_organization_id
    and v.project_id = p_project_id
  for update;

  if not found then
    raise exception 'Variation not found';
  end if;

  if existing_row.updated_at is distinct from p_expected_updated_at then
    raise exception 'This variation was updated by someone else. Please reload and try again.'
      using errcode = '40001';
  end if;

  create temporary table if not exists _incoming_variation_line_values (
    incoming_id uuid,
    resolved_section text,
    resolved_description text,
    resolved_quantity numeric,
    resolved_unit text,
    resolved_rate numeric,
    resolved_total numeric,
    resolved_sort_order integer,
    resolved_source_project_quote_id uuid,
    resolved_source_project_quote_line_item_id uuid,
    resolved_source_project_quote_number text,
    resolved_source_purchase_order_id uuid,
    resolved_source_purchase_order_line_item_id uuid,
    resolved_source_purchase_order_number text
  ) on commit drop;
  truncate _incoming_variation_line_values;

  insert into _incoming_variation_line_values (
    incoming_id,
    resolved_section,
    resolved_description,
    resolved_quantity,
    resolved_unit,
    resolved_rate,
    resolved_total,
    resolved_sort_order,
    resolved_source_project_quote_id,
    resolved_source_project_quote_line_item_id,
    resolved_source_project_quote_number,
    resolved_source_purchase_order_id,
    resolved_source_purchase_order_line_item_id,
    resolved_source_purchase_order_number
  )
  with incoming_lines as (
    select
      case
        when nullif(line.item->>'id', '') is null then null
        else (line.item->>'id')::uuid
      end as incoming_id,
      case
        when line.item->>'section' in ('Labour', 'Materials', 'Subcontractors', 'Plant', 'Margin') then line.item->>'section'
        else 'Labour'
      end as resolved_section,
      coalesce(line.item->>'description', '') as resolved_description,
      nullif(btrim(coalesce(line.item->>'quantity', '')), '')::numeric as resolved_quantity,
      nullif(btrim(coalesce(line.item->>'unit', '')), '') as resolved_unit,
      nullif(btrim(coalesce(line.item->>'rate', '')), '')::numeric as resolved_rate,
      nullif(btrim(coalesce(line.item->>'total', '')), '')::numeric as explicit_total,
      (line.ordinality - 1)::integer as resolved_sort_order,
      case
        when nullif(line.item->>'sourceProjectQuoteId', '') is null then null
        else (line.item->>'sourceProjectQuoteId')::uuid
      end as resolved_source_project_quote_id,
      case
        when nullif(line.item->>'sourceProjectQuoteLineItemId', '') is null then null
        else (line.item->>'sourceProjectQuoteLineItemId')::uuid
      end as resolved_source_project_quote_line_item_id,
      nullif(btrim(coalesce(line.item->>'sourceProjectQuoteNumber', '')), '') as resolved_source_project_quote_number,
      case
        when nullif(line.item->>'sourcePurchaseOrderId', '') is null then null
        else (line.item->>'sourcePurchaseOrderId')::uuid
      end as resolved_source_purchase_order_id,
      case
        when nullif(line.item->>'sourcePurchaseOrderLineItemId', '') is null then null
        else (line.item->>'sourcePurchaseOrderLineItemId')::uuid
      end as resolved_source_purchase_order_line_item_id,
      nullif(btrim(coalesce(line.item->>'sourcePurchaseOrderNumber', '')), '') as resolved_source_purchase_order_number
    from jsonb_array_elements(coalesce(p_line_items, '[]'::jsonb)) with ordinality as line(item, ordinality)
  )
  select
    incoming_id,
    resolved_section,
    resolved_description,
    resolved_quantity,
    resolved_unit,
    resolved_rate,
    case
      when explicit_total is not null then round(explicit_total, 2)
      when resolved_quantity is not null and resolved_rate is not null then round(resolved_quantity * resolved_rate, 2)
      else null
    end,
    resolved_sort_order,
    resolved_source_project_quote_id,
    resolved_source_project_quote_line_item_id,
    resolved_source_project_quote_number,
    resolved_source_purchase_order_id,
    resolved_source_purchase_order_line_item_id,
    resolved_source_purchase_order_number
  from incoming_lines;

  select
    coalesce(sum(case when resolved_section = 'Labour' then coalesce(resolved_total, 0) else 0 end), 0),
    coalesce(sum(case when resolved_section = 'Materials' then coalesce(resolved_total, 0) else 0 end), 0),
    coalesce(sum(case when resolved_section = 'Subcontractors' then coalesce(resolved_total, 0) else 0 end), 0),
    coalesce(sum(case when resolved_section = 'Plant' then coalesce(resolved_total, 0) else 0 end), 0),
    coalesce(sum(case when resolved_section = 'Margin' then coalesce(resolved_total, 0) else 0 end), 0),
    coalesce(sum(coalesce(resolved_total, 0)), 0)
  into
    section_labour_total,
    section_materials_total,
    section_subcontractors_total,
    section_plant_total,
    section_margin_total,
    computed_subtotal
  from _incoming_variation_line_values;

  computed_margin := computed_subtotal * (coalesce(p_margin_percent, 0) / 100);
  computed_discount := coalesce(p_discount_amount, 0);
  computed_contingency := coalesce(p_contingency_amount, 0);
  pre_gst_total := greatest(0, computed_subtotal + computed_margin + computed_contingency - computed_discount);
  computed_gst_total := round(pre_gst_total * (coalesce(p_gst_percent, 0) / 100), 2);
  computed_grand_total := round(pre_gst_total + computed_gst_total, 2);

  update public.project_variations v
  set
    variation_title = btrim(p_variation_title),
    variation_number = btrim(p_variation_number),
    status = p_status,
    origin = p_origin,
    requested_by = coalesce(p_requested_by, ''),
    requested_date = p_requested_date,
    due_date = p_due_date,
    sent_to_client_at = p_sent_to_client_at,
    approved_at = p_approved_at,
    invoice_ready = coalesce(p_invoice_ready, false),
    notes = coalesce(p_notes, ''),
    labour_total = round(section_labour_total, 2),
    materials_total = round(section_materials_total, 2),
    subcontractors_total = round(section_subcontractors_total, 2),
    plant_total = round(section_plant_total, 2),
    margin_total = round(section_margin_total, 2),
    subtotal = round(computed_subtotal, 2),
    margin_percent = round(coalesce(p_margin_percent, 0), 3),
    discount_amount = round(coalesce(p_discount_amount, 0), 2),
    contingency_amount = round(coalesce(p_contingency_amount, 0), 2),
    gst_percent = round(coalesce(p_gst_percent, 0), 3),
    include_margin_in_export = coalesce(p_include_margin_in_export, true),
    include_discount_in_export = coalesce(p_include_discount_in_export, false),
    include_contingency_in_export = coalesce(p_include_contingency_in_export, false),
    validity_period = coalesce(p_validity_period, ''),
    payment_terms = coalesce(p_payment_terms, ''),
    lead_time = coalesce(p_lead_time, ''),
    terms_inclusions = coalesce(p_terms_inclusions, ''),
    terms_exclusions = coalesce(p_terms_exclusions, ''),
    clarifications = coalesce(p_clarifications, ''),
    assumptions = coalesce(p_assumptions, ''),
    gst_total = round(computed_gst_total, 2),
    total_variation_price = computed_grand_total,
    updated_at = statement_timestamp()
  where v.id = p_variation_id
    and v.organization_id = p_organization_id
    and v.project_id = p_project_id
  returning * into saved_row;

  create temporary table if not exists _existing_variation_line_items (
    id uuid,
    section text,
    description text,
    quantity numeric,
    unit text,
    rate numeric,
    total numeric,
    sort_order integer,
    source_project_quote_line_item_id uuid,
    source_purchase_order_line_item_id uuid
  ) on commit drop;
  truncate _existing_variation_line_items;

  insert into _existing_variation_line_items (
    id,
    section,
    description,
    quantity,
    unit,
    rate,
    total,
    sort_order,
    source_project_quote_line_item_id,
    source_purchase_order_line_item_id
  )
  select
    li.id,
    li.section,
    li.description,
    li.quantity,
    li.unit,
    li.rate,
    li.total,
    li.sort_order,
    li.source_project_quote_line_item_id,
    li.source_purchase_order_line_item_id
  from public.project_variation_line_items li
  where li.organization_id = p_organization_id
    and li.project_id = p_project_id
    and li.variation_id = p_variation_id;

  delete from public.project_variation_line_items li
  where li.organization_id = p_organization_id
    and li.project_id = p_project_id
    and li.variation_id = p_variation_id;

  insert into public.project_variation_line_items (
    id,
    organization_id,
    project_id,
    variation_id,
    section,
    description,
    quantity,
    unit,
    rate,
    total,
    sort_order,
    source_project_quote_id,
    source_project_quote_line_item_id,
    source_project_quote_number,
    source_purchase_order_id,
    source_purchase_order_line_item_id,
    source_purchase_order_number
  )
  with reconciled_lines as (
    select
      coalesce(
        il.incoming_id,
        quote_line_match.matched_id,
        source_line_match.matched_id,
        signature_match.matched_id,
        gen_random_uuid()
      ) as resolved_id,
      il.resolved_section,
      il.resolved_description,
      il.resolved_quantity,
      il.resolved_unit,
      il.resolved_rate,
      il.resolved_total,
      il.resolved_sort_order,
      il.resolved_source_project_quote_id,
      il.resolved_source_project_quote_line_item_id,
      il.resolved_source_project_quote_number,
      il.resolved_source_purchase_order_id,
      il.resolved_source_purchase_order_line_item_id,
      il.resolved_source_purchase_order_number
    from _incoming_variation_line_values il
    left join lateral (
      select matches.candidate_id as matched_id
      from (
        select
          e.id as candidate_id,
          count(*) over () as candidate_count
        from _existing_variation_line_items e
        where il.resolved_source_project_quote_line_item_id is not null
          and e.source_project_quote_line_item_id = il.resolved_source_project_quote_line_item_id
      ) matches
      where matches.candidate_count = 1
      limit 1
    ) quote_line_match on true
    left join lateral (
      select matches.candidate_id as matched_id
      from (
        select
          e.id as candidate_id,
          count(*) over () as candidate_count
        from _existing_variation_line_items e
        where il.resolved_source_purchase_order_line_item_id is not null
          and e.source_purchase_order_line_item_id = il.resolved_source_purchase_order_line_item_id
      ) matches
      where matches.candidate_count = 1
      limit 1
    ) source_line_match on true
    left join lateral (
      select matches.candidate_id as matched_id
      from (
        select
          e.id as candidate_id,
          count(*) over () as candidate_count
        from _existing_variation_line_items e
        where e.section = il.resolved_section
          and e.description = il.resolved_description
          and e.quantity is not distinct from il.resolved_quantity
          and e.unit is not distinct from il.resolved_unit
          and e.rate is not distinct from il.resolved_rate
          and e.total is not distinct from il.resolved_total
          and e.sort_order = il.resolved_sort_order
      ) matches
      where matches.candidate_count = 1
      limit 1
    ) signature_match on true
  )
  select
    rl.resolved_id,
    p_organization_id,
    p_project_id,
    p_variation_id,
    rl.resolved_section,
    rl.resolved_description,
    rl.resolved_quantity,
    rl.resolved_unit,
    rl.resolved_rate,
    rl.resolved_total,
    rl.resolved_sort_order,
    rl.resolved_source_project_quote_id,
    rl.resolved_source_project_quote_line_item_id,
    rl.resolved_source_project_quote_number,
    rl.resolved_source_purchase_order_id,
    rl.resolved_source_purchase_order_line_item_id,
    rl.resolved_source_purchase_order_number
  from reconciled_lines rl;

  delete from public.project_variation_attachments a
  where a.organization_id = p_organization_id
    and a.project_id = p_project_id
    and a.variation_id = p_variation_id;

  insert into public.project_variation_attachments (
    id,
    organization_id,
    project_id,
    variation_id,
    file_kind,
    file_name,
    storage_path,
    external_url,
    uploaded_by
  )
  select
    case
      when nullif(att.item->>'id', '') is null then gen_random_uuid()
      else (att.item->>'id')::uuid
    end,
    p_organization_id,
    p_project_id,
    p_variation_id,
    case
      when att.item->>'type' in ('Drawing', 'Email', 'Site Instruction', 'Other') then att.item->>'type'
      else 'Other'
    end,
    coalesce(nullif(att.item->>'name', ''), 'Attachment'),
    nullif(att.item->>'storagePath', ''),
    nullif(att.item->>'externalUrl', ''),
    auth.uid()
  from jsonb_array_elements(coalesce(p_attachments, '[]'::jsonb)) as att(item);

  if existing_row.status is distinct from saved_row.status then
    insert into public.project_variation_status_events (
      organization_id,
      project_id,
      variation_id,
      from_status,
      to_status,
      changed_by,
      event_type,
      occurred_at,
      metadata,
      created_by
    ) values (
      p_organization_id,
      p_project_id,
      p_variation_id,
      existing_row.status,
      saved_row.status,
      auth.uid(),
      case when saved_row.status = 'Approved' then 'approved' else 'status_changed' end,
      case when saved_row.status = 'Approved' then coalesce(saved_row.approved_at, now()) else now() end,
      jsonb_build_object('source', 'save_project_variation_draft'),
      auth.uid()
    );
  end if;

  if saved_row.invoice_ready then
    insert into public.project_variation_invoice_items (
      organization_id,
      project_id,
      variation_id,
      amount,
      status
    ) values (
      p_organization_id,
      p_project_id,
      p_variation_id,
      round(saved_row.total_variation_price, 2),
      'Ready'
    )
    on conflict (variation_id) do update
    set
      amount = excluded.amount,
      status = excluded.status;
  else
    delete from public.project_variation_invoice_items ii
    where ii.organization_id = p_organization_id
      and ii.project_id = p_project_id
      and ii.variation_id = p_variation_id;
  end if;

  cost_item_revision_key := public.begin_cost_item_revision('project_variation', saved_row.id);
  perform public.supersede_previous_cost_items('project_variation', saved_row.id, cost_item_revision_key);
  perform public.upsert_cost_items_for_project_variation(saved_row.id, cost_item_revision_key);

  return query
  select
    saved_row.id,
    saved_row.updated_at,
    saved_row.subtotal,
    saved_row.gst_total,
    saved_row.total_variation_price,
    saved_row.status;
end;
$$;


ALTER FUNCTION "public"."save_project_variation_draft"("p_organization_id" "uuid", "p_project_id" "uuid", "p_variation_id" "uuid", "p_expected_updated_at" timestamp with time zone, "p_variation_title" "text", "p_variation_number" "text", "p_status" "text", "p_origin" "text", "p_requested_by" "text", "p_requested_date" "date", "p_due_date" "date", "p_sent_to_client_at" timestamp with time zone, "p_approved_at" timestamp with time zone, "p_invoice_ready" boolean, "p_notes" "text", "p_margin_percent" numeric, "p_discount_amount" numeric, "p_contingency_amount" numeric, "p_gst_percent" numeric, "p_include_margin_in_export" boolean, "p_include_discount_in_export" boolean, "p_include_contingency_in_export" boolean, "p_validity_period" "text", "p_payment_terms" "text", "p_lead_time" "text", "p_terms_inclusions" "text", "p_terms_exclusions" "text", "p_clarifications" "text", "p_assumptions" "text", "p_line_items" "jsonb", "p_attachments" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_qa_template_definition_internal_v1"("p_organization_id" "uuid", "p_template_id" "uuid", "p_name" "text", "p_description" "text", "p_status" "text", "p_sections" "jsonb") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare s jsonb; f jsonb; o jsonb; next_version integer;
begin
  if auth.uid() is null or not public.has_org_permission(p_organization_id,'qa.templates.write') then raise exception 'Not authorized' using errcode='42501'; end if;
  if p_status not in ('draft','active') then raise exception 'Invalid editable template status' using errcode='TS422'; end if;
  perform public.qa_assert_definition(p_sections);
  update public.qa_templates set name=btrim(p_name), description=coalesce(p_description,''), status=p_status, archived_at=null,
    updated_by=auth.uid(), definition_version=definition_version+1
  where organization_id=p_organization_id and id=p_template_id and status <> 'archived'
  returning definition_version into next_version;
  if next_version is null then raise exception 'QA template not found or archived' using errcode='TS404'; end if;
  delete from public.qa_template_sections where organization_id=p_organization_id and template_id=p_template_id;
  for s in select value from jsonb_array_elements(p_sections) loop
    insert into public.qa_template_sections(id,organization_id,template_id,title,description,sort_order)
    values((s->>'id')::uuid,p_organization_id,p_template_id,btrim(s->>'title'),coalesce(s->>'description',''),coalesce((s->>'sortOrder')::integer,0));
    for f in select value from jsonb_array_elements(coalesce(s->'fields','[]'::jsonb)) loop
      insert into public.qa_template_fields(id,organization_id,template_id,section_id,field_type,label,description,instructions,required,allow_na,requirement,acceptance_criteria,reference_text,photo_required,minimum_photos,file_required,require_comment_on_fail,require_photo_on_fail,create_issue_on_fail,require_rectification_on_fail,block_completion_on_fail,require_supervisor_review_on_fail,ai_review_enabled,ai_review_instruction,include_in_report,configuration,configuration_schema_version,sort_order)
      values((f->>'id')::uuid,p_organization_id,p_template_id,(s->>'id')::uuid,f->>'fieldType',btrim(f->>'label'),coalesce(f->>'description',''),coalesce(f->>'instructions',''),coalesce((f->>'required')::boolean,false),coalesce((f->>'allowNa')::boolean,false),coalesce(f->>'requirement',''),coalesce(f->>'acceptanceCriteria',''),coalesce(f->>'referenceText',''),coalesce((f->>'photoRequired')::boolean,false),coalesce((f->>'minimumPhotos')::integer,0),coalesce((f->>'fileRequired')::boolean,false),coalesce((f->>'requireCommentOnFail')::boolean,false),coalesce((f->>'requirePhotoOnFail')::boolean,false),coalesce((f->>'createIssueOnFail')::boolean,false),coalesce((f->>'requireRectificationOnFail')::boolean,false),coalesce((f->>'blockCompletionOnFail')::boolean,false),coalesce((f->>'requireSupervisorReviewOnFail')::boolean,false),coalesce((f->>'aiReviewEnabled')::boolean,false),coalesce(f->>'aiReviewInstruction',''),coalesce((f->>'includeInReport')::boolean,true),coalesce(f->'configuration','{}'::jsonb),coalesce((f->>'configurationSchemaVersion')::integer,1),coalesce((f->>'sortOrder')::integer,0));
      for o in select value from jsonb_array_elements(coalesce(f->'options','[]'::jsonb)) loop
        insert into public.qa_template_field_options(id,organization_id,template_id,field_id,label,value,sort_order)
        values((o->>'id')::uuid,p_organization_id,p_template_id,(f->>'id')::uuid,btrim(o->>'label'),btrim(o->>'value'),coalesce((o->>'sortOrder')::integer,0));
      end loop;
    end loop;
  end loop;
  return next_version;
end; $$;


ALTER FUNCTION "public"."save_qa_template_definition_internal_v1"("p_organization_id" "uuid", "p_template_id" "uuid", "p_name" "text", "p_description" "text", "p_status" "text", "p_sections" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_qa_template_definition_v1"("p_organization_id" "uuid", "p_template_id" "uuid", "p_name" "text", "p_description" "text", "p_status" "text", "p_sections" "jsonb", "p_expected_version" integer) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  template_row public.qa_templates%rowtype;
begin
  if auth.uid() is null
    or not public.has_org_permission(p_organization_id, 'qa.templates.write')
  then
    raise exception 'Not authorized' using errcode = '42501';
  end if;

  select * into template_row
  from public.qa_templates template
  where template.organization_id = p_organization_id
    and template.id = p_template_id
  for update;

  if not found then
    raise exception 'QA template not found' using errcode = 'TS404';
  end if;
  if template_row.status = 'archived' then
    raise exception 'Archived QA template is read-only' using errcode = 'TS409';
  end if;
  if template_row.definition_version is distinct from p_expected_version then
    raise exception E'This QA definition has been updated by someone else.\n\nReload the latest version before saving your changes.' using errcode = 'TS409';
  end if;

  return public.save_qa_template_definition_internal_v1(
    p_organization_id, p_template_id, p_name, p_description, p_status, p_sections
  );
end;
$$;


ALTER FUNCTION "public"."save_qa_template_definition_v1"("p_organization_id" "uuid", "p_template_id" "uuid", "p_name" "text", "p_description" "text", "p_status" "text", "p_sections" "jsonb", "p_expected_version" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_retention_claim_draft_document"("p_retention_claim_id" "uuid", "p_expected_draft_revision" bigint, "p_title" "text", "p_reference" "text", "p_issue_date" "date", "p_due_date" "date", "p_expected_position_state_hash" "text", "p_expected_eligibility_state_hash" "text", "p_expected_origin_set_hash" "text", "p_lines" "jsonb", "p_correlation_id" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private'
    AS $_$
declare
  claim public.retention_claims%rowtype;
  invalid_lines jsonb;
begin
  select *
  into claim
  from public.retention_claims
  where id = p_retention_claim_id
  for update;

  if not found then
    return jsonb_build_object(
      'succeeded', false,
      'errorCode', 'claim_not_found',
      'changed', false
    );
  end if;

  if p_lines is not null
    and jsonb_typeof(p_lines) = 'array'
    and not exists (
      select 1
      from jsonb_array_elements(p_lines) item
      where jsonb_typeof(item) <> 'object'
        or coalesce(item ->> 'originatingPaymentClaimId', '') !~
          '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
        or coalesce(item ->> 'proposedAmountCents', '') !~ '^[0-9]+$'
    )
  then
    perform origin.id
    from public.project_claims origin
    where origin.id in (
      select (item ->> 'originatingPaymentClaimId')::uuid
      from jsonb_array_elements(p_lines) item
    )
    order by origin.id
    for update;

    with requested as (
      select
        (item ->> 'originatingPaymentClaimId')::uuid as origin_id,
        (item ->> 'proposedAmountCents')::bigint as proposed_cents
      from jsonb_array_elements(p_lines) item
    ),
    submitted as (
      select
        allocation.originating_payment_claim_id as origin_id,
        round(coalesce(sum(allocation.allocation_amount), 0) * 100)::bigint
          as submitted_cents
      from public.retention_claim_allocations allocation
      join public.retention_claims submitted_claim
        on submitted_claim.id = allocation.retention_claim_id
      where submitted_claim.organization_id = claim.organization_id
        and submitted_claim.project_id = claim.project_id
        and submitted_claim.status = 'submitted'
      group by allocation.originating_payment_claim_id
    ),
    legacy as (
      select
        committed.originating_payment_claim_id as origin_id,
        round(coalesce(committed.amount, 0) * 100)::bigint as legacy_cents
      from private.current_legacy_committed_by_origin(claim.project_id) committed
    )
    select jsonb_agg(jsonb_build_object(
      'originatingPaymentClaimId', requested.origin_id,
      'errorCode', case
        when origin.id is null then 'origin_not_found'
        when origin.organization_id <> claim.organization_id
          or origin.project_id <> claim.project_id then 'cross_project_origin'
        when origin.status not in ('Submitted', 'Unpaid', 'Paid', 'Overdue')
          then 'origin_cancelled'
        else 'allocation_exceeds_eligibility'
      end,
      'retentionHeldCents',
        round(greatest(coalesce(origin.retention_withheld_amount, 0), 0) * 100),
      'previouslyClaimedCents',
        coalesce(submitted.submitted_cents, 0) + coalesce(legacy.legacy_cents, 0),
      'currentLimitCents', greatest(
        round(greatest(coalesce(origin.retention_withheld_amount, 0), 0) * 100)
        - coalesce(submitted.submitted_cents, 0)
        - coalesce(legacy.legacy_cents, 0),
        0
      ),
      'proposedAmountCents', requested.proposed_cents
    ) order by requested.origin_id)
    into invalid_lines
    from requested
    left join public.project_claims origin on origin.id = requested.origin_id
    left join submitted on submitted.origin_id = requested.origin_id
    left join legacy on legacy.origin_id = requested.origin_id
    where origin.id is null
      or origin.organization_id <> claim.organization_id
      or origin.project_id <> claim.project_id
      or origin.status not in ('Submitted', 'Unpaid', 'Paid', 'Overdue')
      or requested.proposed_cents > greatest(
        round(greatest(coalesce(origin.retention_withheld_amount, 0), 0) * 100)
        - coalesce(submitted.submitted_cents, 0)
        - coalesce(legacy.legacy_cents, 0),
        0
      );

    if invalid_lines is not null then
      return private.reject_retention_document_save(
        claim,
        coalesce(invalid_lines -> 0 ->> 'errorCode',
          'allocation_exceeds_eligibility'),
        p_correlation_id,
        jsonb_build_object('rowErrors', invalid_lines)
      );
    end if;
  end if;

  return public.save_retention_claim_draft_document_pre_accumulated_eligibility(
    p_retention_claim_id,
    p_expected_draft_revision,
    p_title,
    p_reference,
    p_issue_date,
    p_due_date,
    p_expected_position_state_hash,
    p_expected_eligibility_state_hash,
    p_expected_origin_set_hash,
    p_lines,
    p_correlation_id
  );
end;
$_$;


ALTER FUNCTION "public"."save_retention_claim_draft_document"("p_retention_claim_id" "uuid", "p_expected_draft_revision" bigint, "p_title" "text", "p_reference" "text", "p_issue_date" "date", "p_due_date" "date", "p_expected_position_state_hash" "text", "p_expected_eligibility_state_hash" "text", "p_expected_origin_set_hash" "text", "p_lines" "jsonb", "p_correlation_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_retention_claim_draft_document_pre_accumulated_eligibility"("p_retention_claim_id" "uuid", "p_expected_draft_revision" bigint, "p_title" "text", "p_reference" "text", "p_issue_date" "date", "p_due_date" "date", "p_expected_position_state_hash" "text", "p_expected_eligibility_state_hash" "text", "p_expected_origin_set_hash" "text", "p_lines" "jsonb", "p_correlation_id" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $_$
declare
  v_claim public.retention_claims%rowtype;
  v_context jsonb;
  v_position jsonb;
  v_eligibility jsonb;
  v_position_hash text;
  v_eligibility_hash text;
  v_origin_set_hash text;
  v_changed boolean := false;
  v_old_total bigint := 0;
  v_new_total bigint := 0;
  v_added uuid[] := '{}'::uuid[];
  v_updated uuid[] := '{}'::uuid[];
  v_removed uuid[] := '{}'::uuid[];
  v_line_count integer;
  v_invalid jsonb;
  v_lines_result jsonb;
begin
  if auth.uid() is null then
    return jsonb_build_object('succeeded', false, 'errorCode', 'permission_denied');
  end if;

  select * into v_claim
  from public.retention_claims
  where id = p_retention_claim_id;
  if not found then
    return jsonb_build_object('succeeded', false, 'errorCode', 'claim_not_found');
  end if;

  v_context := private.retention_claim_operation_context(
    v_claim.project_id, 'retention.claims.create', true
  );
  if not coalesce((v_context ->> 'succeeded')::boolean, false) then
    return v_context;
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended(v_claim.project_id::text || ':automatic_retention_draft', 7)
  );
  select * into v_claim
  from public.retention_claims claim
  where claim.id = p_retention_claim_id
    and claim.organization_id = (v_context ->> 'organizationId')::uuid
  for update;

  if v_claim.status <> 'draft' then
    return private.reject_retention_document_save(
      v_claim, 'claim_not_draft', p_correlation_id
    );
  end if;
  if v_claim.draft_revision <> p_expected_draft_revision then
    return private.reject_retention_document_save(
      v_claim, 'concurrent_update', p_correlation_id,
      jsonb_build_object('currentDraftRevision', v_claim.draft_revision)
    );
  end if;
  if nullif(trim(coalesce(p_title, '')), '') is null
    or length(p_title) > 250
    or length(coalesce(p_reference, '')) > 250
    or length(coalesce(p_correlation_id, '')) > 250
    or (p_issue_date is not null and p_due_date is not null and p_due_date < p_issue_date)
    or p_lines is null
    or jsonb_typeof(p_lines) <> 'array'
    or jsonb_array_length(p_lines) > 500
    or octet_length(p_lines::text) > 524288 then
    return private.reject_retention_document_save(
      v_claim, 'invalid_line_set', p_correlation_id
    );
  end if;

  create temporary table if not exists _retention_document_lines (
    origin_id uuid primary key,
    candidate_id uuid null,
    existing_allocation_id uuid null,
    expected_origin_state_hash text not null,
    requested_sequence integer not null,
    proposed_amount_cents bigint not null
  ) on commit drop;
  truncate _retention_document_lines;

  begin
    insert into _retention_document_lines
    select
      (item ->> 'originatingPaymentClaimId')::uuid,
      nullif(item ->> 'candidateId', '')::uuid,
      nullif(item ->> 'existingAllocationId', '')::uuid,
      item ->> 'expectedOriginStateHash',
      (item ->> 'sequence')::integer,
      (item ->> 'proposedAmountCents')::bigint
    from jsonb_array_elements(p_lines) item
    where jsonb_typeof(item) = 'object'
      and (item - array[
        'originatingPaymentClaimId', 'candidateId', 'existingAllocationId',
        'expectedOriginStateHash', 'sequence', 'proposedAmountCents'
      ]) = '{}'::jsonb
      and coalesce(item ->> 'originatingPaymentClaimId', '') ~
        '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
      and coalesce(item ->> 'expectedOriginStateHash', '') ~ '^[a-f0-9]{64}$'
      and coalesce(item ->> 'sequence', '') ~ '^[1-9][0-9]*$'
      and coalesce(item ->> 'proposedAmountCents', '') ~ '^[0-9]+$';
  exception when others then
    return private.reject_retention_document_save(
      v_claim, 'invalid_line_set', p_correlation_id
    );
  end;

  select count(*) into v_line_count from _retention_document_lines;
  if v_line_count <> jsonb_array_length(p_lines) then
    return private.reject_retention_document_save(
      v_claim, 'invalid_line_set', p_correlation_id
    );
  end if;
  if exists (
    select 1 from _retention_document_lines
    where proposed_amount_cents > 99999999999999
      or requested_sequence > 500
  ) then
    return private.reject_retention_document_save(
      v_claim, 'invalid_line_set', p_correlation_id
    );
  end if;

  perform 1 from public.retention_rolling_draft_origins candidate
  where candidate.retention_claim_id = v_claim.id
  order by candidate.origin_sequence, candidate.originating_payment_claim_id
  for update;
  perform 1 from public.project_claims origin
  where origin.id in (
    select line.origin_id from _retention_document_lines line
    union
    select candidate.originating_payment_claim_id
    from public.retention_rolling_draft_origins candidate
    where candidate.retention_claim_id = v_claim.id
  )
  order by origin.id
  for update;
  perform 1 from public.retention_claim_allocations allocation
  where allocation.retention_claim_id = v_claim.id
  order by allocation.originating_payment_claim_id, allocation.id
  for update;

  v_origin_set_hash := private.retention_claim_draft_origin_set_hash(v_claim.id);
  if p_expected_origin_set_hash is null
    or p_expected_origin_set_hash <> v_origin_set_hash then
    return private.reject_retention_document_save(
      v_claim, 'origin_set_changed', p_correlation_id,
      jsonb_build_object('currentOriginSetHash', v_origin_set_hash)
    );
  end if;

  if v_claim.draft_kind = 'automatic_rolling' and (
    exists (
      select 1 from public.retention_rolling_draft_origins candidate
      left join _retention_document_lines line
        on line.origin_id = candidate.originating_payment_claim_id
       and line.candidate_id = candidate.id
       and line.requested_sequence = candidate.origin_sequence
      where candidate.retention_claim_id = v_claim.id and line.origin_id is null
    )
    or exists (
      select 1 from _retention_document_lines line
      left join public.retention_rolling_draft_origins candidate
        on candidate.retention_claim_id = v_claim.id
       and candidate.id = line.candidate_id
       and candidate.originating_payment_claim_id = line.origin_id
      where candidate.id is null
    )
  ) then
    return private.reject_retention_document_save(
      v_claim, 'origin_set_changed', p_correlation_id,
      jsonb_build_object('currentOriginSetHash', v_origin_set_hash)
    );
  end if;
  if v_claim.draft_kind = 'automatic_rolling' and exists (
    select 1
    from _retention_document_lines line
    left join public.retention_claim_allocations allocation
      on allocation.retention_claim_id = v_claim.id
     and allocation.originating_payment_claim_id = line.origin_id
    where line.existing_allocation_id is distinct from allocation.id
  ) then
    return private.reject_retention_document_save(
      v_claim, 'invalid_line_set', p_correlation_id
    );
  end if;

  if v_claim.draft_kind = 'manual' and exists (
    select 1 from public.retention_claim_allocations allocation
    left join _retention_document_lines line
      on line.origin_id = allocation.originating_payment_claim_id
    where allocation.retention_claim_id = v_claim.id and line.origin_id is null
  ) then
    return private.reject_retention_document_save(
      v_claim, 'invalid_line_set', p_correlation_id
    );
  end if;
  if v_claim.draft_kind = 'manual' and exists (
    select 1
    from _retention_document_lines line
    join public.retention_claim_allocations allocation
      on allocation.retention_claim_id = v_claim.id
     and allocation.originating_payment_claim_id = line.origin_id
    where line.requested_sequence <> allocation.allocation_sequence
      or line.existing_allocation_id is distinct from allocation.id
      or line.candidate_id is not null
  ) then
    return private.reject_retention_document_save(
      v_claim, 'invalid_line_set', p_correlation_id
    );
  end if;

  v_position := public.get_project_retention_position_summary(v_claim.project_id);
  v_eligibility := public.get_project_retention_eligibility(v_claim.project_id);
  v_position_hash := v_position ->> 'stateHash';
  v_eligibility_hash := v_eligibility ->> 'eligibilityStateHash';

  if p_expected_position_state_hash is null
    or p_expected_position_state_hash <> v_position_hash then
    return private.reject_retention_document_save(
      v_claim, 'position_changed', p_correlation_id,
      jsonb_build_object('currentPositionStateHash', v_position_hash)
    );
  end if;
  if p_expected_eligibility_state_hash is null
    or p_expected_eligibility_state_hash <> v_eligibility_hash then
    return private.reject_retention_document_save(
      v_claim, 'eligibility_changed', p_correlation_id,
      jsonb_build_object('currentEligibilityStateHash', v_eligibility_hash)
    );
  end if;

  create temporary table if not exists _retention_document_authority (
    origin_id uuid primary key,
    current_origin_state_hash text not null,
    retention_owned_cents bigint not null,
    available_cents bigint not null,
    origin_updated_at timestamptz not null
  ) on commit drop;
  truncate _retention_document_authority;
  insert into _retention_document_authority
  select
    origin.id,
    private.retention_claim_origin_state_hash(origin.id),
    round(greatest(coalesce((eligible.value ->> 'currentRetentionOwned')::numeric,
      origin.retention_withheld_amount, 0), 0) * 100)::bigint,
    round(greatest(
      coalesce((eligible.value ->> 'availableRetention')::numeric, 0)
      + coalesce(existing.allocation_amount, 0),
      0
    ) * 100)::bigint,
    origin.updated_at
  from _retention_document_lines line
  join public.project_claims origin
    on origin.id = line.origin_id
   and origin.organization_id = v_claim.organization_id
   and origin.project_id = v_claim.project_id
   and origin.status in ('Submitted', 'Unpaid', 'Paid', 'Overdue')
  left join lateral (
    select value from jsonb_array_elements(coalesce(v_eligibility -> 'origins', '[]'::jsonb))
    where value ->> 'originatingPaymentClaimId' = origin.id::text
  ) eligible on true
  left join public.retention_claim_allocations existing
    on existing.retention_claim_id = v_claim.id
   and existing.originating_payment_claim_id = origin.id;

  if (select count(*) from _retention_document_authority) <> v_line_count then
    return private.reject_retention_document_save(
      v_claim, 'invalid_line_set', p_correlation_id
    );
  end if;

  select jsonb_agg(jsonb_build_object(
    'originatingPaymentClaimId', line.origin_id,
    'errorCode', case
      when line.expected_origin_state_hash <> authority.current_origin_state_hash
        then 'stale_draft'
      when line.proposed_amount_cents > authority.retention_owned_cents
        then 'allocation_exceeds_ownership'
      when line.proposed_amount_cents > authority.available_cents
        then 'allocation_exceeds_eligibility'
    end,
    'currentLimitCents', least(authority.retention_owned_cents, authority.available_cents)
  ) order by line.origin_id)
  into v_invalid
  from _retention_document_lines line
  join _retention_document_authority authority on authority.origin_id = line.origin_id
  where line.expected_origin_state_hash <> authority.current_origin_state_hash
     or line.proposed_amount_cents > authority.retention_owned_cents
     or line.proposed_amount_cents > authority.available_cents;

  if v_invalid is not null then
    return private.reject_retention_document_save(
      v_claim,
      case
        when exists(select 1 from jsonb_array_elements(v_invalid) x
          where x ->> 'errorCode' = 'stale_draft') then 'stale_draft'
        when exists(select 1 from jsonb_array_elements(v_invalid) x
          where x ->> 'errorCode' = 'allocation_exceeds_ownership')
          then 'allocation_exceeds_ownership'
        else 'allocation_exceeds_eligibility'
      end,
      p_correlation_id,
      jsonb_build_object('rowErrors', v_invalid)
    );
  end if;

  select coalesce(sum(round(allocation_amount * 100)::bigint), 0)
  into v_old_total
  from public.retention_claim_allocations
  where retention_claim_id = v_claim.id;
  select coalesce(sum(proposed_amount_cents), 0)
  into v_new_total
  from _retention_document_lines;

  select coalesce(array_agg(line.origin_id order by line.origin_id), '{}'::uuid[])
  into v_added
  from _retention_document_lines line
  left join public.retention_claim_allocations allocation
    on allocation.retention_claim_id = v_claim.id
   and allocation.originating_payment_claim_id = line.origin_id
  where line.proposed_amount_cents > 0 and allocation.id is null;
  select coalesce(array_agg(line.origin_id order by line.origin_id), '{}'::uuid[])
  into v_updated
  from _retention_document_lines line
  join public.retention_claim_allocations allocation
    on allocation.retention_claim_id = v_claim.id
   and allocation.originating_payment_claim_id = line.origin_id
  where line.proposed_amount_cents > 0
    and (
      round(allocation.allocation_amount * 100)::bigint <> line.proposed_amount_cents
      or allocation.allocation_sequence <> line.requested_sequence
      or allocation.draft_origin_state_hash <>
        (select current_origin_state_hash from _retention_document_authority
         where origin_id = line.origin_id)
    );
  select coalesce(array_agg(line.origin_id order by line.origin_id), '{}'::uuid[])
  into v_removed
  from _retention_document_lines line
  join public.retention_claim_allocations allocation
    on allocation.retention_claim_id = v_claim.id
   and allocation.originating_payment_claim_id = line.origin_id
  where line.proposed_amount_cents = 0;

  v_changed :=
    trim(p_title) is distinct from v_claim.title
    or nullif(trim(coalesce(p_reference, '')), '') is distinct from v_claim.reference
    or p_issue_date is distinct from v_claim.issue_date
    or p_due_date is distinct from v_claim.due_date
    or v_claim.last_position_state_hash is distinct from v_position_hash
    or v_claim.last_eligibility_state_hash is distinct from v_eligibility_hash
    or cardinality(v_added) > 0 or cardinality(v_updated) > 0 or cardinality(v_removed) > 0;

  if v_changed then
    set constraints retention_claim_allocations_sequence_unique deferred;
    delete from public.retention_claim_allocations allocation
    using _retention_document_lines line
    where allocation.retention_claim_id = v_claim.id
      and allocation.originating_payment_claim_id = line.origin_id
      and line.proposed_amount_cents = 0;

    update public.retention_claim_allocations allocation
    set
      allocation_amount = line.proposed_amount_cents::numeric / 100,
      allocation_sequence = line.requested_sequence,
      draft_origin_state_hash = authority.current_origin_state_hash,
      draft_origin_updated_at = authority.origin_updated_at,
      draft_origin_retention_owned = authority.retention_owned_cents::numeric / 100
    from _retention_document_lines line
    join _retention_document_authority authority on authority.origin_id = line.origin_id
    where allocation.retention_claim_id = v_claim.id
      and allocation.originating_payment_claim_id = line.origin_id
      and line.proposed_amount_cents > 0;

    insert into public.retention_claim_allocations (
      organization_id, project_id, retention_claim_id,
      originating_payment_claim_id, allocation_sequence, allocation_amount,
      draft_origin_state_hash, draft_origin_updated_at,
      draft_origin_retention_owned, created_by
    )
    select
      v_claim.organization_id, v_claim.project_id, v_claim.id,
      line.origin_id, line.requested_sequence,
      line.proposed_amount_cents::numeric / 100,
      authority.current_origin_state_hash, authority.origin_updated_at,
      authority.retention_owned_cents::numeric / 100, auth.uid()
    from _retention_document_lines line
    join _retention_document_authority authority on authority.origin_id = line.origin_id
    left join public.retention_claim_allocations allocation
      on allocation.retention_claim_id = v_claim.id
     and allocation.originating_payment_claim_id = line.origin_id
    where line.proposed_amount_cents > 0 and allocation.id is null;

    update public.retention_claims claim
    set
      title = trim(p_title),
      reference = nullif(trim(coalesce(p_reference, '')), ''),
      issue_date = p_issue_date,
      due_date = p_due_date,
      last_position_state_hash = v_position_hash,
      last_eligibility_state_hash = v_eligibility_hash,
      draft_revision = claim.draft_revision + 1
    where claim.id = v_claim.id
    returning * into v_claim;

    v_origin_set_hash := private.retention_claim_draft_origin_set_hash(v_claim.id);
    perform private.record_retention_claim_event(
      v_claim.organization_id, v_claim.project_id, v_claim.id,
      'draft_document_saved', 'draft', 'draft', auth.uid(),
      'Retention Claim Draft document saved.', p_correlation_id,
      jsonb_build_object(
        'newRevision', v_claim.draft_revision,
        'positionStateHash', v_position_hash,
        'eligibilityStateHash', v_eligibility_hash,
        'originSetHash', v_origin_set_hash,
        'addedOriginIds', to_jsonb(v_added),
        'updatedOriginIds', to_jsonb(v_updated),
        'removedAllocationOriginIds', to_jsonb(v_removed),
        'previousTotalCents', v_old_total,
        'newTotalCents', v_new_total,
        'lineCount', v_line_count
      )
    );
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
    'originatingPaymentClaimId', line.origin_id,
    'candidateId', line.candidate_id,
    'existingAllocationId', allocation.id,
    'expectedOriginStateHash', authority.current_origin_state_hash,
    'sequence', line.requested_sequence,
    'proposedAmountCents', line.proposed_amount_cents,
    'retentionOwnedCents', authority.retention_owned_cents,
    'availableCents', authority.available_cents
  ) order by line.requested_sequence, line.origin_id), '[]'::jsonb)
  into v_lines_result
  from _retention_document_lines line
  join _retention_document_authority authority on authority.origin_id = line.origin_id
  left join public.retention_claim_allocations allocation
    on allocation.retention_claim_id = v_claim.id
   and allocation.originating_payment_claim_id = line.origin_id;

  return jsonb_build_object(
    'succeeded', true,
    'errorCode', null,
    'changed', v_changed,
    'requiresReload', false,
    'claim', private.retention_claim_header_json(v_claim.id),
    'draftRevision', v_claim.draft_revision,
    'positionStateHash', v_position_hash,
    'eligibilityStateHash', v_eligibility_hash,
    'originSetHash', v_origin_set_hash,
    'lines', v_lines_result,
    'totals', jsonb_build_object('thisClaimCents', v_new_total),
    'affectedOriginIds', to_jsonb(v_added || v_updated || v_removed),
    'rowErrors', '[]'::jsonb
  );
end;
$_$;


ALTER FUNCTION "public"."save_retention_claim_draft_document_pre_accumulated_eligibility"("p_retention_claim_id" "uuid", "p_expected_draft_revision" bigint, "p_title" "text", "p_reference" "text", "p_issue_date" "date", "p_due_date" "date", "p_expected_position_state_hash" "text", "p_expected_eligibility_state_hash" "text", "p_expected_origin_set_hash" "text", "p_lines" "jsonb", "p_correlation_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_supplier_invoice_capture"("p_invoice_id" "uuid", "p_supplier_id" "uuid", "p_invoice_number" "text", "p_supplier_po_reference" "text", "p_invoice_date" "date", "p_due_date" "date", "p_currency" "text", "p_subtotal" numeric, "p_tax_total" numeric, "p_total" numeric, "p_notes" "text", "p_source" "text", "p_lines" "jsonb" DEFAULT '[]'::"jsonb", "p_create" boolean DEFAULT false) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_organization_id uuid;
  v_jurisdiction text;
  v_currency text := upper(trim(coalesce(p_currency, '')));
  v_tax_amount_mode text := 'unknown';
  v_line_amount_total numeric := 0;
  v_line_tax_total numeric := 0;
  v_line jsonb;
  v_line_id uuid;
  v_keep_line_ids uuid[] := '{}';
begin
  select m.organization_id into v_organization_id
  from public.organization_members m
  where m.user_id = auth.uid()
  order by m.created_at limit 1;

  if v_organization_id is null
    or not public.has_org_permission(v_organization_id, 'supplier_invoices.capture') then
    raise exception 'You do not have permission to capture Supplier Invoices.';
  end if;
  select public.normalize_supported_tax_jurisdiction(to_jsonb(organization) ->> 'country')
    into v_jurisdiction from public.organizations organization where id = v_organization_id;
  if (v_jurisdiction = 'NZ' and v_currency <> 'NZD')
    or (v_jurisdiction = 'AU' and v_currency <> 'AUD')
    or v_jurisdiction = 'unsupported' then
    raise exception 'Supplier Invoice currency must match the supported organization jurisdiction.';
  end if;
  if p_invoice_id is null then raise exception 'Supplier Invoice ID is required.'; end if;
  if p_supplier_id is null or not exists (
    select 1 from public.organization_suppliers s
    where s.id = p_supplier_id and s.organization_id = v_organization_id
  ) then raise exception 'Select a valid Supplier.'; end if;
  if char_length(trim(coalesce(p_invoice_number, ''))) = 0 then raise exception 'Enter an invoice number.'; end if;
  if p_invoice_date is null then raise exception 'Enter an invoice date.'; end if;
  if p_due_date is not null and p_due_date < p_invoice_date then raise exception 'Due date cannot be before the invoice date.'; end if;
  if p_subtotal < 0 or p_tax_total < 0 or p_total < 0
    or abs((p_subtotal + p_tax_total) - p_total) > 0.01 then
    raise exception 'Invoice subtotal, tax and total do not reconcile.';
  end if;
  if p_supplier_po_reference is not null and char_length(trim(p_supplier_po_reference)) > 120 then
    raise exception 'Supplier PO reference must be 120 characters or fewer.';
  end if;
  if jsonb_typeof(coalesce(p_lines, '[]'::jsonb)) <> 'array' then
    raise exception 'Supplier Invoice lines must be an array.';
  end if;

  select
    coalesce(sum(coalesce((value ->> 'lineTotal')::numeric, 0)), 0),
    coalesce(sum(coalesce((value ->> 'taxAmount')::numeric, 0)), 0)
  into v_line_amount_total, v_line_tax_total
  from jsonb_array_elements(coalesce(p_lines, '[]'::jsonb));
  v_tax_amount_mode := case
    when p_tax_total <= 0.01 then 'no_tax'
    when abs(v_line_amount_total - p_subtotal) <= 0.01 then 'exclusive'
    when abs(v_line_amount_total - p_total) <= 0.01 then 'inclusive'
    else 'unknown'
  end;

  if exists (
    select 1 from public.supplier_invoices duplicate
    where duplicate.organization_id = v_organization_id
      and duplicate.supplier_id = p_supplier_id
      and public.normalize_supplier_invoice_number(duplicate.invoice_number)
        = public.normalize_supplier_invoice_number(p_invoice_number)
      and duplicate.id <> p_invoice_id
  ) then raise exception 'A Supplier Invoice with this invoice number already exists for the Supplier.'; end if;

  if p_create then
    insert into public.supplier_invoices (
      id, organization_id, supplier_id, invoice_number, supplier_po_reference,
      invoice_date, due_date, currency, subtotal, tax_total, total, tax_amount_mode, tax_evidence_json, notes,
      status, source, created_by
    ) values (
      p_invoice_id, v_organization_id, p_supplier_id, trim(p_invoice_number),
      nullif(trim(coalesce(p_supplier_po_reference, '')), ''), p_invoice_date,
      p_due_date, v_currency, p_subtotal, p_tax_total, p_total, v_tax_amount_mode,
      jsonb_build_object('headerTaxSource', case when p_source = 'upload' then 'document_header' else 'manual' end,
        'amountMode', v_tax_amount_mode, 'lineTaxPreserved', v_line_tax_total > 0),
      trim(coalesce(p_notes, '')), 'Captured',
      case when p_source = 'upload' then 'upload' else 'manual' end, auth.uid()
    );
  else
    if exists (
      select 1 from public.organization_accounting_documents d
      where d.organization_id = v_organization_id and d.local_document_id = p_invoice_id
        and d.export_status in ('queued', 'exporting', 'exported', 'attention_required')
    ) then raise exception 'This Supplier Invoice is locked by its Xero export state.'; end if;
    update public.supplier_invoices
    set supplier_id = p_supplier_id, invoice_number = trim(p_invoice_number),
        supplier_po_reference = nullif(trim(coalesce(p_supplier_po_reference, '')), ''),
        invoice_date = p_invoice_date, due_date = p_due_date, currency = v_currency,
        subtotal = p_subtotal, tax_total = p_tax_total, total = p_total,
        tax_amount_mode = v_tax_amount_mode,
        tax_evidence_json = jsonb_build_object(
          'headerTaxSource', case when p_source = 'upload' then 'document_header' else 'manual' end,
          'amountMode', v_tax_amount_mode, 'lineTaxPreserved', v_line_tax_total > 0),
        notes = trim(coalesce(p_notes, ''))
    where id = p_invoice_id and organization_id = v_organization_id;
    if not found then raise exception 'Supplier Invoice not found.'; end if;
  end if;

  for v_line in select value from jsonb_array_elements(coalesce(p_lines, '[]'::jsonb)) loop
    v_line_id := coalesce(nullif(v_line ->> 'id', '')::uuid, gen_random_uuid());
    if exists (
      select 1 from public.supplier_invoice_lines l where l.id = v_line_id
        and (l.supplier_invoice_id <> p_invoice_id or l.organization_id <> v_organization_id)
    ) then raise exception 'A Supplier Invoice line does not belong to this invoice.'; end if;
    if char_length(trim(coalesce(v_line ->> 'description', ''))) = 0 then
      raise exception 'Every Supplier Invoice line requires a description.';
    end if;
    if nullif(v_line ->> 'costCodeId', '') is not null and not exists (
      select 1 from public.organization_cost_codes c
      where c.id = (v_line ->> 'costCodeId')::uuid and c.organization_id = v_organization_id
    ) then raise exception 'A Supplier Invoice line cost code does not belong to this organization.'; end if;
    if nullif(v_line ->> 'projectId', '') is not null and not exists (
      select 1 from public.organization_projects p
      where p.id = (v_line ->> 'projectId')::uuid and p.organization_id = v_organization_id
    ) then raise exception 'A Supplier Invoice line project does not belong to this organization.'; end if;
    if coalesce((v_line ->> 'quantity')::numeric, 0) < 0
      or coalesce((v_line ->> 'unitPrice')::numeric, 0) < 0
      or coalesce((v_line ->> 'lineTotal')::numeric, 0) < 0
      or coalesce((v_line ->> 'taxAmount')::numeric, 0) < 0 then
      raise exception 'Supplier Invoice line values cannot be negative.';
    end if;

    insert into public.supplier_invoice_lines (
      id, organization_id, supplier_invoice_id, description, supplier_item_code,
      quantity, unit_price, line_total, tax_amount, cost_code_id, project_id, sort_order, source_metadata_json
    ) values (
      v_line_id, v_organization_id, p_invoice_id, trim(v_line ->> 'description'),
      nullif(trim(coalesce(v_line ->> 'supplierItemCode', '')), ''),
      coalesce((v_line ->> 'quantity')::numeric, 0), coalesce((v_line ->> 'unitPrice')::numeric, 0),
      coalesce((v_line ->> 'lineTotal')::numeric, 0), coalesce((v_line ->> 'taxAmount')::numeric, 0),
      nullif(v_line ->> 'costCodeId', '')::uuid, nullif(v_line ->> 'projectId', '')::uuid,
      coalesce((v_line ->> 'sortOrder')::integer, cardinality(v_keep_line_ids)),
      jsonb_build_object(
        'taxEvidenceSource', coalesce(nullif(v_line ->> 'taxEvidenceSource', ''), 'unknown'),
        'grossLineTotal', nullif(v_line ->> 'grossLineTotal', '')::numeric,
        'taxAmountMode', v_tax_amount_mode
      )
    )
    on conflict (id) do update set
      description = excluded.description, supplier_item_code = excluded.supplier_item_code,
      quantity = excluded.quantity, unit_price = excluded.unit_price,
      line_total = excluded.line_total, tax_amount = excluded.tax_amount,
      cost_code_id = excluded.cost_code_id, project_id = excluded.project_id,
      sort_order = excluded.sort_order,
      source_metadata_json = coalesce(public.supplier_invoice_lines.source_metadata_json, '{}'::jsonb)
        || excluded.source_metadata_json;
    v_keep_line_ids := array_append(v_keep_line_ids, v_line_id);
  end loop;

  if not p_create then
    delete from public.supplier_invoice_lines l
    where l.organization_id = v_organization_id and l.supplier_invoice_id = p_invoice_id
      and not (l.id = any(v_keep_line_ids));
  end if;

  insert into public.supplier_invoice_activity_events (
    organization_id, supplier_invoice_id, event_type, message, metadata, created_by
  ) values (
    v_organization_id, p_invoice_id,
    case when p_create then 'invoice_created' else 'invoice_updated' end,
    case when p_create then 'Supplier Invoice captured by Accounts.' else 'Supplier Invoice capture details updated.' end,
    jsonb_build_object(
      'supplier_po_reference', nullif(trim(coalesce(p_supplier_po_reference, '')), ''),
      'line_count', jsonb_array_length(coalesce(p_lines, '[]'::jsonb)),
      'tax_amount_mode', v_tax_amount_mode,
      'currency', v_currency
    ), auth.uid()
  );
  return p_invoice_id;
end;
$$;


ALTER FUNCTION "public"."save_supplier_invoice_capture"("p_invoice_id" "uuid", "p_supplier_id" "uuid", "p_invoice_number" "text", "p_supplier_po_reference" "text", "p_invoice_date" "date", "p_due_date" "date", "p_currency" "text", "p_subtotal" numeric, "p_tax_total" numeric, "p_total" numeric, "p_notes" "text", "p_source" "text", "p_lines" "jsonb", "p_create" boolean) OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."takeoff_calibrations" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "project_id" "uuid" NOT NULL,
    "opportunity_id" "uuid",
    "page_id" "uuid" NOT NULL,
    "name" "text" DEFAULT 'Default calibration'::"text" NOT NULL,
    "scale_ratio" numeric(20,10) NOT NULL,
    "unit_system" "text" DEFAULT 'metric'::"text" NOT NULL,
    "base_unit" "text" NOT NULL,
    "display_unit" "text" NOT NULL,
    "reference_length_input" numeric(20,6) NOT NULL,
    "reference_length_base" numeric(20,6) NOT NULL,
    "point_a_x" numeric(12,8) NOT NULL,
    "point_a_y" numeric(12,8) NOT NULL,
    "point_b_x" numeric(12,8) NOT NULL,
    "point_b_y" numeric(12,8) NOT NULL,
    "is_active" boolean DEFAULT true NOT NULL,
    "superseded_by" "uuid",
    "notes" "text" DEFAULT ''::"text" NOT NULL,
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_by" "uuid" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "takeoff_calibrations_metadata_object" CHECK (("jsonb_typeof"("metadata") = 'object'::"text")),
    CONSTRAINT "takeoff_calibrations_name_not_blank" CHECK (("char_length"(TRIM(BOTH FROM "name")) > 0)),
    CONSTRAINT "takeoff_calibrations_points_normalized" CHECK ((("point_a_x" >= (0)::numeric) AND ("point_a_x" <= (1)::numeric) AND ("point_a_y" >= (0)::numeric) AND ("point_a_y" <= (1)::numeric) AND ("point_b_x" >= (0)::numeric) AND ("point_b_x" <= (1)::numeric) AND ("point_b_y" >= (0)::numeric) AND ("point_b_y" <= (1)::numeric))),
    CONSTRAINT "takeoff_calibrations_reference_positive" CHECK ((("reference_length_input" > (0)::numeric) AND ("reference_length_base" > (0)::numeric))),
    CONSTRAINT "takeoff_calibrations_scale_positive" CHECK (("scale_ratio" > (0)::numeric)),
    CONSTRAINT "takeoff_calibrations_unit_system_valid" CHECK (("unit_system" = ANY (ARRAY['metric'::"text", 'imperial'::"text"])))
);


ALTER TABLE "public"."takeoff_calibrations" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_takeoff_calibration_fast"("arg_id" "uuid", "arg_organization_id" "uuid", "arg_project_id" "uuid", "arg_opportunity_id" "uuid", "arg_page_id" "uuid", "arg_name" "text", "arg_scale_ratio" numeric, "arg_unit_system" "text", "arg_base_unit" "text", "arg_display_unit" "text", "arg_reference_length_input" numeric, "arg_reference_length_base" numeric, "arg_point_a_x" numeric, "arg_point_a_y" numeric, "arg_point_b_x" numeric, "arg_point_b_y" numeric, "arg_notes" "text", "arg_created_by" "uuid") RETURNS "public"."takeoff_calibrations"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  previous_active_ids uuid[] := '{}';
  calibration_row public.takeoff_calibrations%rowtype;
begin
  previous_active_ids := coalesce(
    array(
      select id
      from public.takeoff_calibrations
      where organization_id = arg_organization_id
        and project_id = arg_project_id
        and opportunity_id = arg_opportunity_id
        and page_id = arg_page_id
        and is_active = true
      for update
    ),
    '{}'
  );

  if coalesce(array_length(previous_active_ids, 1), 0) > 0 then
    update public.takeoff_calibrations
    set
      is_active = false,
      superseded_by = null
    where id = any(previous_active_ids);
  end if;

  insert into public.takeoff_calibrations (
    id,
    organization_id,
    project_id,
    opportunity_id,
    page_id,
    name,
    scale_ratio,
    unit_system,
    base_unit,
    display_unit,
    reference_length_input,
    reference_length_base,
    point_a_x,
    point_a_y,
    point_b_x,
    point_b_y,
    is_active,
    superseded_by,
    notes,
    metadata,
    created_by
  )
  values (
    arg_id,
    arg_organization_id,
    arg_project_id,
    arg_opportunity_id,
    arg_page_id,
    arg_name,
    arg_scale_ratio,
    arg_unit_system,
    arg_base_unit,
    arg_display_unit,
    arg_reference_length_input,
    arg_reference_length_base,
    arg_point_a_x,
    arg_point_a_y,
    arg_point_b_x,
    arg_point_b_y,
    true,
    null,
    coalesce(arg_notes, ''),
    '{}'::jsonb,
    arg_created_by
  )
  returning * into calibration_row;

  if coalesce(array_length(previous_active_ids, 1), 0) > 0 then
    update public.takeoff_calibrations
    set superseded_by = arg_id
    where id = any(previous_active_ids);
  end if;

  return calibration_row;
exception
  when others then
    if coalesce(array_length(previous_active_ids, 1), 0) > 0 then
      update public.takeoff_calibrations
      set
        is_active = true,
        superseded_by = null
      where id = any(previous_active_ids);
    end if;

    raise;
end;
$$;


ALTER FUNCTION "public"."save_takeoff_calibration_fast"("arg_id" "uuid", "arg_organization_id" "uuid", "arg_project_id" "uuid", "arg_opportunity_id" "uuid", "arg_page_id" "uuid", "arg_name" "text", "arg_scale_ratio" numeric, "arg_unit_system" "text", "arg_base_unit" "text", "arg_display_unit" "text", "arg_reference_length_input" numeric, "arg_reference_length_base" numeric, "arg_point_a_x" numeric, "arg_point_a_y" numeric, "arg_point_b_x" numeric, "arg_point_b_y" numeric, "arg_notes" "text", "arg_created_by" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."search_organization_supplier_materials"("p_organization_id" "uuid", "p_search" "text" DEFAULT NULL::"text", "p_page" integer DEFAULT 1, "p_page_size" integer DEFAULT 20, "p_evaluation_time" timestamp with time zone DEFAULT "statement_timestamp"()) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_organization jsonb;
  v_organization_currency text;
  v_search text := lower(regexp_replace(btrim(coalesce(p_search, '')), '\s+', ' ', 'g'));
  v_page integer := greatest(1, coalesce(p_page, 1));
  v_page_size integer := least(50, greatest(1, coalesce(p_page_size, 20)));
  v_evaluated_at timestamptz := coalesce(p_evaluation_time, statement_timestamp());
  v_result jsonb;
begin
  select to_jsonb(organization)
  into v_organization
  from public.organizations organization
  where organization.id = p_organization_id;

  if v_organization is null or not public.is_member_of_organization(p_organization_id) then
    raise exception 'organization_material_picker:invalid_organization_scope' using errcode = '42501';
  end if;
  if not public.has_org_permission(p_organization_id, 'materials.view') then
    raise exception 'organization_material_picker:materials_view_permission_required' using errcode = '42501';
  end if;
  v_organization_currency := public.resolve_material_estimating_currency(v_organization);

  with candidates as materialized (
    select material.id as material_id, material.name as material_name,
      material.description as material_description, material.category, material.default_unit,
      product.id as supplier_product_id, product.supplier_id,
      coalesce(
        nullif(btrim(supplier.company_name), ''),
        nullif(btrim(supplier.name), ''),
        'Unknown supplier'
      ) as supplier_name,
      product.supplier_description, product.supplier_sku, product.supplier_unit, product.is_preferred,
      case when v_search = '' then 2 when material.normalized_name = v_search then 0
        when material.normalized_name like v_search || '%' then 1 else 2 end as relevance
    from public.organization_material_supplier_products product
    join public.organization_materials material
      on material.organization_id = product.organization_id and material.id = product.material_id
    join public.organization_suppliers supplier
      on supplier.organization_id = product.organization_id and supplier.id = product.supplier_id
    where product.organization_id = p_organization_id
      and product.is_active and product.archived_at is null
      and material.is_active and material.archived_at is null and supplier.is_active
      and (v_search = '' or material.normalized_name like '%' || v_search || '%'
        or lower(coalesce(material.description, '')) like '%' || v_search || '%'
        or lower(coalesce(material.category, '')) like '%' || v_search || '%'
        or lower(coalesce(supplier.company_name, '')) like '%' || v_search || '%'
        or lower(coalesce(supplier.name, '')) like '%' || v_search || '%'
        or coalesce(product.normalized_supplier_description, '') like '%' || v_search || '%'
        or coalesce(product.normalized_supplier_sku, '') like '%' || v_search || '%')
  ), paged as materialized (
    select candidate.*, count(*) over () as total_count from candidates candidate
    order by relevance, lower(material_name), is_preferred desc, lower(supplier_name),
      lower(coalesce(supplier_description, '')), lower(coalesce(supplier_sku, '')), supplier_product_id
    limit v_page_size offset ((v_page - 1) * v_page_size)
  ), effective_prices as materialized (
    select resolved.supplier_product_id, resolved.price_id
    from public.resolve_material_supplier_product_prices(
      p_organization_id, v_evaluated_at,
      coalesce((select array_agg(supplier_product_id order by supplier_product_id) from paged), array[]::uuid[])
    ) resolved
  ), rows as materialized (
    select paged.*, price.id as price_id, price.unit_cost, price.unit as price_unit, price.currency,
      price.source_tax_basis, price.source_tax_rate, price.tax_jurisdiction_code,
      price.comparison_tax_basis, price.comparison_tax_rate, price.tax_policy_snapshot,
      price.effective_from as price_effective_from,
      conversion.id as conversion_id, conversion.supplier_quantity as conversion_supplier_quantity,
      conversion.supplier_unit as conversion_supplier_unit,
      conversion.material_quantity as conversion_material_quantity,
      conversion.material_unit as conversion_material_unit, conversion.source as conversion_source,
      conversion.contract_version as conversion_contract_version,
      conversion.effective_from as conversion_effective_from, conversion.confirmed_at as conversion_confirmed_at
    from paged
    left join effective_prices on effective_prices.supplier_product_id = paged.supplier_product_id
    left join public.organization_material_supplier_prices price
      on price.organization_id = p_organization_id and price.id = effective_prices.price_id
    left join public.organization_material_supplier_product_unit_conversions conversion
      on conversion.organization_id = p_organization_id
      and conversion.supplier_product_id = paged.supplier_product_id
      and public.normalize_material_estimating_unit(conversion.supplier_unit) = public.normalize_material_estimating_unit(coalesce(price.unit, paged.supplier_unit))
      and public.normalize_material_estimating_unit(conversion.material_unit) = public.normalize_material_estimating_unit(paged.default_unit)
      and conversion.effective_from <= v_evaluated_at
      and (conversion.effective_to is null or conversion.effective_to > v_evaluated_at)
  ), derived as materialized (
    select rows.*,
      case when rows.price_id is null then null else public.derive_material_estimating_price(
        rows.price_id, rows.unit_cost, rows.price_unit, rows.currency, rows.source_tax_basis,
        rows.source_tax_rate, rows.tax_jurisdiction_code, rows.comparison_tax_basis,
        rows.comparison_tax_rate, rows.tax_policy_snapshot, rows.price_effective_from,
        rows.default_unit, v_organization_currency, v_evaluated_at,
        rows.conversion_id, rows.conversion_supplier_quantity, rows.conversion_supplier_unit,
        rows.conversion_material_quantity, rows.conversion_material_unit, rows.conversion_source,
        rows.conversion_contract_version, rows.conversion_effective_from, rows.conversion_confirmed_at
      ) end as pricing
    from rows
  )
  select jsonb_build_object(
    'items', coalesce(jsonb_agg(jsonb_build_object(
      'materialId', material_id, 'materialName', material_name,
      'materialDescription', material_description, 'category', category,
      'defaultUnit', default_unit, 'supplierId', supplier_id, 'supplierName', supplier_name,
      'supplierProductId', supplier_product_id, 'supplierProductDescription', supplier_description,
      'supplierSku', supplier_sku, 'supplierUnit', supplier_unit,
      'isPreferred', is_preferred, 'pricing', pricing
    ) order by relevance, lower(material_name), is_preferred desc, lower(supplier_name),
      lower(coalesce(supplier_description, '')), lower(coalesce(supplier_sku, '')), supplier_product_id), '[]'::jsonb),
    'page', v_page, 'pageSize', v_page_size, 'total', coalesce(max(total_count), 0),
    'hasMore', coalesce(max(total_count), 0) > v_page * v_page_size, 'evaluatedAt', v_evaluated_at
  ) into v_result from derived;
  return v_result;
end;
$$;


ALTER FUNCTION "public"."search_organization_supplier_materials"("p_organization_id" "uuid", "p_search" "text", "p_page" integer, "p_page_size" integer, "p_evaluation_time" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."search_organization_supplier_materials"("p_organization_id" "uuid", "p_search" "text", "p_page" integer, "p_page_size" integer, "p_evaluation_time" timestamp with time zone) IS 'Authenticated organization-scoped supplier Material picker shared by non-workbook commercial destinations.';



CREATE OR REPLACE FUNCTION "public"."search_pricing_worksheet_materials"("p_workbook_id" "uuid", "p_search" "text" DEFAULT NULL::"text", "p_page" integer DEFAULT 1, "p_page_size" integer DEFAULT 20, "p_evaluation_time" timestamp with time zone DEFAULT "statement_timestamp"()) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_organization_id uuid;
begin
  select workbook.organization_id
  into v_organization_id
  from public.opportunity_pricing_worksheets workbook
  where workbook.id = p_workbook_id and workbook.archived_at is null;

  if v_organization_id is null or not public.is_member_of_organization(v_organization_id) then
    raise exception 'pricing_material_picker:invalid_workbook_scope' using errcode = '42501';
  end if;

  return public.search_organization_supplier_materials(
    v_organization_id,
    p_search,
    p_page,
    p_page_size,
    p_evaluation_time
  );
end;
$$;


