CREATE OR REPLACE FUNCTION "public"."set_organization_accounting_route_mapping"("p_organization_id" "uuid", "p_provider" "text", "p_accounting_route" "text", "p_organization_cost_code_id" "uuid", "p_project_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_mapping_id uuid;
begin
  if auth.uid() is null
    or not public.has_org_permission(p_organization_id, 'settings.organization.update') then
    raise exception 'You do not have permission to configure accounting routes.';
  end if;

  perform 1 from public.organization_cost_codes account
  where account.id = p_organization_cost_code_id
    and account.organization_id = p_organization_id
    and account.is_active
    and account.external_provider = lower(trim(p_provider));
  if not found then
    raise exception 'Select an active account for this organization and provider.';
  end if;

  update public.organization_accounting_route_mappings
  set is_active = false, updated_at = now()
  where organization_id = p_organization_id
    and provider = lower(trim(p_provider))
    and accounting_route = p_accounting_route
    and project_id is not distinct from p_project_id
    and is_active;

  insert into public.organization_accounting_route_mappings (
    organization_id, project_id, provider, accounting_route,
    organization_cost_code_id, created_by_user_id
  ) values (
    p_organization_id, p_project_id, lower(trim(p_provider)), p_accounting_route,
    p_organization_cost_code_id, auth.uid()
  ) returning id into v_mapping_id;

  return v_mapping_id;
end;
$$;


ALTER FUNCTION "public"."set_organization_accounting_route_mapping"("p_organization_id" "uuid", "p_provider" "text", "p_accounting_route" "text", "p_organization_cost_code_id" "uuid", "p_project_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_organization_retention_capability"("p_enabled" boolean, "p_reason" "text", "p_correlation_id" "text" DEFAULT NULL::"text") RETURNS TABLE("succeeded" boolean, "error_code" "text", "changed" boolean, "organization_id" "uuid", "capability_key" "text", "enabled" boolean, "enabled_by" "uuid", "enabled_at" timestamp with time zone, "disabled_by" "uuid", "disabled_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_actor_user_id uuid := auth.uid();
  v_organization_id uuid;
  v_capability public.organization_capabilities%rowtype;
  v_reason text := nullif(trim(coalesce(p_reason, '')), '');
begin
  if v_actor_user_id is null then
    return query
    select false, 'unauthenticated'::text, false, null::uuid, 'retention_management'::text,
      false, null::uuid, null::timestamptz, null::uuid, null::timestamptz, null::timestamptz;
    return;
  end if;

  select member.organization_id
  into v_organization_id
  from public.organization_members member
  where member.user_id = v_actor_user_id
  order by member.created_at, member.id
  limit 1;

  if v_organization_id is null then
    return query
    select false, 'organization_membership_required'::text, false, null::uuid,
      'retention_management'::text, false, null::uuid, null::timestamptz,
      null::uuid, null::timestamptz, null::timestamptz;
    return;
  end if;

  insert into public.organization_capabilities (organization_id, capability_key, enabled)
  values (v_organization_id, 'retention_management', false)
  on conflict on constraint organization_capabilities_pkey do nothing;

  select *
  into v_capability
  from public.organization_capabilities capability
  where capability.organization_id = v_organization_id
    and capability.capability_key = 'retention_management'
  for update;

  if not public.has_org_permission(v_organization_id, 'retention.cutover.manage') then
    perform public.record_retention_capability_event(
      v_organization_id,
      null,
      'management_permission_denied',
      case when v_capability.enabled then 'enabled' else 'disabled' end,
      case when p_enabled then 'enabled' else 'disabled' end,
      v_actor_user_id,
      coalesce(v_reason, 'Permission denied while managing Retention capability.'),
      p_correlation_id,
      jsonb_build_object('action', 'set_organization_retention_capability')
    );

    return query
    select false, 'permission_denied'::text, false,
      v_capability.organization_id, v_capability.capability_key, v_capability.enabled,
      v_capability.enabled_by, v_capability.enabled_at,
      v_capability.disabled_by, v_capability.disabled_at, v_capability.updated_at;
    return;
  end if;

  if v_reason is null then
    return query
    select false, 'reason_required'::text, false,
      v_capability.organization_id, v_capability.capability_key, v_capability.enabled,
      v_capability.enabled_by, v_capability.enabled_at,
      v_capability.disabled_by, v_capability.disabled_at, v_capability.updated_at;
    return;
  end if;

  if v_capability.enabled = p_enabled then
    return query
    select true, null::text, false,
      v_capability.organization_id, v_capability.capability_key, v_capability.enabled,
      v_capability.enabled_by, v_capability.enabled_at,
      v_capability.disabled_by, v_capability.disabled_at, v_capability.updated_at;
    return;
  end if;

  if p_enabled then
    update public.organization_capabilities capability
    set
      enabled = true,
      enabled_by = v_actor_user_id,
      enabled_at = now(),
      disabled_by = null,
      disabled_at = null
    where capability.organization_id = v_organization_id
      and capability.capability_key = 'retention_management'
    returning * into v_capability;
  else
    update public.organization_capabilities capability
    set
      enabled = false,
      disabled_by = v_actor_user_id,
      disabled_at = now()
    where capability.organization_id = v_organization_id
      and capability.capability_key = 'retention_management'
    returning * into v_capability;
  end if;

  perform public.record_retention_capability_event(
    v_organization_id,
    null,
    case
      when p_enabled then 'organization_capability_enabled'
      else 'organization_capability_disabled'
    end,
    case when p_enabled then 'disabled' else 'enabled' end,
    case when p_enabled then 'enabled' else 'disabled' end,
    v_actor_user_id,
    v_reason,
    p_correlation_id,
    jsonb_build_object('capabilityKey', 'retention_management')
  );

  return query
  select true, null::text, true,
    v_capability.organization_id, v_capability.capability_key, v_capability.enabled,
    v_capability.enabled_by, v_capability.enabled_at,
    v_capability.disabled_by, v_capability.disabled_at, v_capability.updated_at;
end;
$$;


ALTER FUNCTION "public"."set_organization_retention_capability"("p_enabled" boolean, "p_reason" "text", "p_correlation_id" "text") OWNER TO "postgres";


