CREATE OR REPLACE FUNCTION "public"."set_project_qa_hold_release_v1"("p_organization_id" "uuid", "p_project_id" "uuid", "p_run_id" "uuid", "p_response_id" "uuid", "p_status" "text", "p_comment" "text" DEFAULT ''::"text") RETURNS TABLE("release_status" "text", "released_at" timestamp with time zone, "run_lock_version" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare response_row public.project_qa_responses%rowtype; run_status text; next_time timestamptz:=now(); next_lock integer;
begin
  if auth.uid() is null or not public.can_access_qa_project(p_organization_id,p_project_id,'qa.verify') then raise exception 'Not authorized to verify QA' using errcode='42501'; end if;
  if p_status not in ('released','rejected') then raise exception 'Invalid Hold Point decision' using errcode='TS422'; end if;
  select status into run_status from public.project_qa_runs where organization_id=p_organization_id and project_id=p_project_id and id=p_run_id for update;
  if run_status<>'in_progress' then raise exception 'Hold Points can only be decided while QA is in progress' using errcode='TS409'; end if;
  select * into response_row from public.project_qa_responses where run_id=p_run_id and id=p_response_id for update;
  if not found or response_row.field_type<>'inspection_check' or coalesce((response_row.field_snapshot->'configuration'->>'holdPointEnabled')::boolean,false)=false or response_row.inspection_result is null then raise exception 'Completed Hold Point response not found' using errcode='TS422'; end if;
  insert into public.project_qa_hold_releases(organization_id,project_id,run_id,response_id,status,comment,released_by,released_at)
  values(p_organization_id,p_project_id,p_run_id,p_response_id,p_status,left(btrim(coalesce(p_comment,'')),1000),auth.uid(),next_time)
  on conflict(response_id) do update set status=excluded.status,comment=excluded.comment,released_by=excluded.released_by,released_at=excluded.released_at,revision=project_qa_hold_releases.revision+1,updated_at=now();
  update public.project_qa_runs set lock_version=lock_version+1 where id=p_run_id returning lock_version into next_lock;
  return query select p_status,next_time,next_lock;
end; $$;


ALTER FUNCTION "public"."set_project_qa_hold_release_v1"("p_organization_id" "uuid", "p_project_id" "uuid", "p_run_id" "uuid", "p_response_id" "uuid", "p_status" "text", "p_comment" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_project_qa_lifecycle_v1"("p_organization_id" "uuid", "p_project_id" "uuid", "p_project_qa_id" "uuid", "p_action" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare next_status text;
begin
  if auth.uid() is null or not public.can_access_qa_project(p_organization_id,p_project_id,'qa.write') then raise exception 'Not authorized' using errcode='42501'; end if;
  if p_action='archive' then
    update public.project_qas set status='archived',archived_at=now(),updated_by=auth.uid()
      where organization_id=p_organization_id and project_id=p_project_id and id=p_project_qa_id and status<>'archived'
      returning status into next_status;
  elsif p_action='delete' then
    delete from public.project_qas where organization_id=p_organization_id and project_id=p_project_id and id=p_project_qa_id and status='draft'
      returning 'deleted' into next_status;
  else raise exception 'Invalid lifecycle action' using errcode='TS422'; end if;
  if next_status is null then raise exception 'Project QA cannot be changed' using errcode='TS409'; end if;
  return next_status;
end; $$;


ALTER FUNCTION "public"."set_project_qa_lifecycle_v1"("p_organization_id" "uuid", "p_project_id" "uuid", "p_project_qa_id" "uuid", "p_action" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_qa_template_lifecycle_v1"("p_organization_id" "uuid", "p_template_id" "uuid", "p_action" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare next_status text;
begin
  if auth.uid() is null or not public.has_org_permission(p_organization_id,'qa.templates.write') then raise exception 'Not authorized' using errcode='42501'; end if;
  if p_action='archive' then
    update public.qa_templates set status='archived',archived_at=now(),updated_by=auth.uid() where organization_id=p_organization_id and id=p_template_id returning status into next_status;
  elsif p_action='delete' then
    delete from public.qa_templates t where t.organization_id=p_organization_id and t.id=p_template_id and t.status='draft'
      and not exists(select 1 from public.project_qas q where q.organization_id=p_organization_id and q.source_template_id=t.id)
      returning 'deleted' into next_status;
  else raise exception 'Invalid lifecycle action' using errcode='TS422'; end if;
  if next_status is null then raise exception 'Template cannot be changed' using errcode='TS409'; end if;
  return next_status;
end; $$;


ALTER FUNCTION "public"."set_qa_template_lifecycle_v1"("p_organization_id" "uuid", "p_template_id" "uuid", "p_action" "text") OWNER TO "postgres";


