CREATE OR REPLACE FUNCTION "public"."sign_project_qa_response_v1"("p_organization_id" "uuid", "p_project_id" "uuid", "p_run_id" "uuid", "p_response_id" "uuid", "p_signer_name" "text", "p_attestation" "text") RETURNS TABLE("response_lock_version" integer, "run_lock_version" integer, "signed_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare response_row public.project_qa_responses%rowtype; run_status text; next_response integer; next_run integer; signed_time timestamptz:=now(); actor_name text;
begin
  if auth.uid() is null or not public.can_access_qa_project(p_organization_id,p_project_id,'qa.inspect') then raise exception 'Not authorized to sign QA' using errcode='42501'; end if;
  select status into run_status from public.project_qa_runs where organization_id=p_organization_id and project_id=p_project_id and id=p_run_id for update;
  if run_status<>'in_progress' then raise exception 'Only an in-progress QA Record can be signed' using errcode='TS409'; end if;
  select * into response_row from public.project_qa_responses where organization_id=p_organization_id and project_id=p_project_id and run_id=p_run_id and id=p_response_id for update;
  if not found or response_row.field_type<>'signature' then raise exception 'Signature response not found' using errcode='TS404'; end if;
  if char_length(btrim(coalesce(p_signer_name,''))) not between 1 and 240 or char_length(btrim(coalesce(p_attestation,''))) not between 1 and 1000 then raise exception 'Signer name and acknowledgement are required' using errcode='TS422'; end if;
  select coalesce(nullif(btrim(display_name),''),'TradesStack user') into actor_name from public.organization_members where organization_id=p_organization_id and user_id=auth.uid() order by created_at limit 1;
  if actor_name is null then raise exception 'Authenticated QA actor not found' using errcode='42501'; end if;
  update public.project_qa_responses set signature_signer_name=btrim(p_signer_name),signature_method='typed_acknowledgement',signature_attestation=btrim(p_attestation),signature_signed_by=auth.uid(),signature_signed_at=signed_time,signature_evidence_id=null,signature_artifact_sha256=null,signature_artifact_metadata=null,signature_recorded_by_name=actor_name,updated_by=auth.uid(),lock_version=lock_version+1 where id=response_row.id returning lock_version into next_response;
  update public.project_qa_runs set lock_version=lock_version+1 where id=p_run_id returning lock_version into next_run;
  return query select next_response,next_run,signed_time;
end; $$;


ALTER FUNCTION "public"."sign_project_qa_response_v1"("p_organization_id" "uuid", "p_project_id" "uuid", "p_run_id" "uuid", "p_response_id" "uuid", "p_signer_name" "text", "p_attestation" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."signoff_project_qa_run_v1"("p_organization_id" "uuid", "p_project_id" "uuid", "p_run_id" "uuid", "p_signer_name" "text", "p_attestation" "text") RETURNS TABLE("signoff_id" "uuid", "signed_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare run_status text; inserted_id uuid; next_time timestamptz:=now();
begin
  if auth.uid() is null or not public.can_access_qa_project(p_organization_id,p_project_id,'qa.signoff') then raise exception 'Not authorized to sign off QA' using errcode='42501'; end if;
  select run.status into run_status from public.project_qa_runs run where run.organization_id=p_organization_id and run.project_id=p_project_id and run.id=p_run_id;
  if run_status<>'completed' then raise exception 'Only a completed QA Record can be signed off' using errcode='TS409'; end if;
  if char_length(btrim(coalesce(p_signer_name,''))) not between 1 and 240 or char_length(btrim(coalesce(p_attestation,''))) not between 1 and 1000 then raise exception 'Sign-off name and acknowledgement are required' using errcode='TS422'; end if;
  insert into public.project_qa_signoffs(organization_id,project_id,run_id,signer_name,attestation,signed_by,signed_at)
  values(p_organization_id,p_project_id,p_run_id,btrim(p_signer_name),btrim(p_attestation),auth.uid(),next_time)
  on conflict(run_id) do nothing returning id into inserted_id;
  if inserted_id is null then select signoff.id,signoff.signed_at into inserted_id,next_time from public.project_qa_signoffs signoff where signoff.run_id=p_run_id; end if;
  return query select inserted_id,next_time;
end; $$;


ALTER FUNCTION "public"."signoff_project_qa_run_v1"("p_organization_id" "uuid", "p_project_id" "uuid", "p_run_id" "uuid", "p_signer_name" "text", "p_attestation" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."snooze_retention_reminder"("p_input" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_r public.retention_reminders%rowtype; v_context jsonb; v_until timestamptz;
begin
  select * into v_r from public.retention_reminders where id=(p_input->>'reminderId')::uuid;
  if not found then return jsonb_build_object('succeeded',false,'errorCode','reminder_not_found'); end if;
  v_context:=private.retention_phase4_context(v_r.project_id,'retention.reminders.manage',true);
  if not coalesce((v_context->>'succeeded')::boolean,false) then return v_context; end if;
  select * into v_r from public.retention_reminders where id=v_r.id for update;
  if v_r.revision<>(p_input->>'expectedRevision')::bigint then
    return jsonb_build_object('succeeded',false,'errorCode','concurrent_update','currentRevision',v_r.revision);
  end if;
  if v_r.state in ('completed','cancelled','sent') then
    return jsonb_build_object('succeeded',false,'errorCode','reminder_immutable');
  end if;
  v_until:=(p_input->>'snoozedUntil')::timestamptz;
  if v_until is null or v_until<=now() then
    return jsonb_build_object('succeeded',false,'errorCode','invalid_reminder_time');
  end if;
  update public.retention_reminders set state='snoozed',snoozed_until=v_until,
    next_delivery_at=v_until,delivery_claimed_at=null,delivery_claim_token=null,
    revision=revision+1 where id=v_r.id returning * into v_r;
  perform private.record_retention_reminder_event(
    v_r.id,'reminder_snoozed',null,'snoozed','Retention reminder snoozed.',
    p_input->>'correlationId',jsonb_build_object('snoozedUntil',v_until)
  );
  return jsonb_build_object('succeeded',true,'errorCode',null,'reminder',to_jsonb(v_r));
end;
$$;


ALTER FUNCTION "public"."snooze_retention_reminder"("p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."soft_delete_document_node"("p_node_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  actor_user_id uuid := auth.uid();
  node_row public.document_nodes%rowtype;
  deletion_batch uuid := gen_random_uuid();
  deletion_time timestamptz := now();
begin
  select *
  into node_row
  from public.document_nodes node
  where node.id = p_node_id;

  if not found then
    raise exception 'Document node not found.'
      using errcode = 'P0002';
  end if;

  perform public.assert_document_workspace_permission(
    node_row.workspace_id,
    'files.delete'
  );
  perform pg_advisory_xact_lock(
    hashtextextended('document-workspace:' || node_row.workspace_id::text, 0)
  );

  select *
  into node_row
  from public.document_nodes node
  where node.id = p_node_id
  for update;

  if node_row.deleted_at is not null then
    return node_row.deletion_batch_id;
  end if;

  with recursive subtree as (
    select node.id
    from public.document_nodes node
    where node.id = node_row.id
    union all
    select child.id
    from public.document_nodes child
    join subtree parent on child.parent_node_id = parent.id
    where child.organization_id = node_row.organization_id
      and child.workspace_id = node_row.workspace_id
      and child.deleted_at is null
  ),
  deleted_nodes as (
    update public.document_nodes node
    set
      deleted_at = deletion_time,
      deleted_by = actor_user_id,
      deletion_batch_id = deletion_batch,
      updated_by = actor_user_id
    where node.id in (select id from subtree)
      and node.deleted_at is null
    returning node.*
  )
  insert into public.document_activity_events (
    organization_id,
    workspace_id,
    node_id,
    actor_user_id,
    event_type,
    metadata,
    occurred_at
  )
  select
    deleted.organization_id,
    deleted.workspace_id,
    deleted.id,
    actor_user_id,
    'soft_deleted',
    jsonb_build_object(
      'deletionBatchId', deletion_batch,
      'rootNodeId', node_row.id
    ),
    deletion_time
  from deleted_nodes deleted;

  return deletion_batch;
end;
$$;


ALTER FUNCTION "public"."soft_delete_document_node"("p_node_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."soft_delete_task"("p_task_id" "uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  actor_user_id uuid := auth.uid();
  old_row public.project_job_todos%rowtype;
  updated_row public.project_job_todos%rowtype;
begin
  old_row := public._task_assert_task_access(p_task_id);

  update public.project_job_todos t
  set
    deleted_at = now(),
    deleted_by = actor_user_id,
    delete_reason = nullif(btrim(coalesce(p_reason, '')), ''),
    updated_by = actor_user_id
  where t.id = p_task_id
    and t.organization_id = old_row.organization_id
  returning * into updated_row;

  perform public._write_task_activity(updated_row.organization_id, updated_row.id, updated_row.project_id, actor_user_id, 'deleted', 'deleted_at', null, to_jsonb(updated_row.deleted_at), jsonb_build_object('reason', updated_row.delete_reason));

  return public._task_to_json(updated_row);
end;
$$;


ALTER FUNCTION "public"."soft_delete_task"("p_task_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."stamp_material_supplier_price_tax_snapshot"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_snapshot jsonb := new.observation_metadata->'tax_snapshot';
begin
  if v_snapshot is null and new.import_row_id is not null then
    select source_payload->'approvedTaxSnapshot' into v_snapshot
    from public.organization_material_import_rows
    where organization_id = new.organization_id and id = new.import_row_id;
  end if;
  if v_snapshot is null then return new; end if;
  new.source_tax_basis := coalesce(v_snapshot->>'sourceTaxBasis', 'unknown');
  new.source_tax_rate := nullif(v_snapshot->>'sourceTaxRate', '')::numeric;
  new.tax_jurisdiction_code := nullif(v_snapshot->>'taxJurisdictionCode', '');
  new.comparison_tax_basis := nullif(v_snapshot->>'comparisonTaxBasis', '');
  new.comparison_tax_rate := nullif(v_snapshot->>'comparisonTaxRate', '')::numeric;
  new.tax_policy_snapshot := coalesce(v_snapshot->'taxPolicySnapshot', '{}'::jsonb);
  new.tax_evidence := coalesce(v_snapshot->'taxEvidence', '{}'::jsonb);
  return new;
end;
$$;


ALTER FUNCTION "public"."stamp_material_supplier_price_tax_snapshot"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."stamp_xero_tax_rate_provenance"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_connection public.organization_xero_connections%rowtype;
  v_country text;
begin
  if new.provider <> 'xero' then
    raise exception 'Unsupported accounting tax-rate provider.';
  end if;

  select * into v_connection
  from public.organization_xero_connections
  where organization_id = new.organization_id
    and status = 'connected'
    and tenant_id is not null;

  if not found then
    raise exception 'A connected Xero tenant is required before synchronizing tax rates.';
  end if;

  select to_jsonb(organization) ->> 'country' into v_country
  from public.organizations organization where id = new.organization_id;
  new.accounting_connection_id := v_connection.id;
  new.tenant_id := v_connection.tenant_id;
  new.jurisdiction_code := public.normalize_supported_tax_jurisdiction(v_country);
  new.can_apply_to_expenses := coalesce((new.metadata ->> 'canApplyToExpenses')::boolean, false);
  new.is_active := upper(coalesce(new.status, '')) = 'ACTIVE';
  new.synced_at := now();
  return new;
end;
$$;


ALTER FUNCTION "public"."stamp_xero_tax_rate_provenance"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."start_project_qa_run_v1"("p_organization_id" "uuid", "p_project_id" "uuid", "p_project_qa_id" "uuid", "p_start_idempotency_key" "uuid", "p_title" "text" DEFAULT ''::"text", "p_location_label" "text" DEFAULT ''::"text") RETURNS TABLE("run_id" "uuid", "created" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  qa_row public.project_qas%rowtype;
  snapshot jsonb;
  snapshot_hash text;
  inserted_id uuid;
  existing_row public.project_qa_runs%rowtype;
  field_count integer;
begin
  if auth.uid() is null or not public.can_access_qa_project(p_organization_id,p_project_id,'qa.inspect') then
    raise exception 'Not authorized to Start QA' using errcode='42501';
  end if;
  if p_start_idempotency_key is null then raise exception 'Start idempotency key is required' using errcode='TS422'; end if;

  select * into existing_row from public.project_qa_runs
  where organization_id=p_organization_id and started_by=auth.uid() and start_idempotency_key=p_start_idempotency_key;
  if found then
    if existing_row.project_id<>p_project_id or existing_row.project_qa_id<>p_project_qa_id then
      raise exception 'Start idempotency key was already used for another QA Record' using errcode='TS409';
    end if;
    return query select existing_row.id,false;
    return;
  end if;

  select * into qa_row from public.project_qas
  where organization_id=p_organization_id and project_id=p_project_id and id=p_project_qa_id for share;
  if not found then raise exception 'Project QA not found' using errcode='TS404'; end if;
  if qa_row.status <> 'active' then raise exception 'Only a Ready Project QA can be started' using errcode='TS409'; end if;

  select count(*) into field_count from public.project_qa_fields
  where organization_id=p_organization_id and project_id=p_project_id and project_qa_id=p_project_qa_id;
  if field_count=0 then raise exception 'Ready Project QA has no executable fields' using errcode='TS422'; end if;

  select jsonb_build_object(
    'schemaVersion',1,
    'projectQaId',qa_row.id,
    'name',qa_row.name,
    'description',qa_row.description,
    'status',qa_row.status,
    'definitionVersion',qa_row.definition_version,
    'sourceTemplateId',qa_row.source_template_id,
    'sourceTemplateName',qa_row.source_template_name,
    'sourceTemplateVersion',qa_row.source_template_version,
    'copiedAt',qa_row.copied_at,
    'sections',coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',s.id,'title',s.title,'description',s.description,'sortOrder',s.sort_order,
        'fields',coalesce((
          select jsonb_agg(jsonb_build_object(
            'id',f.id,'sectionId',f.section_id,'fieldType',f.field_type,'label',f.label,
            'description',f.description,'instructions',f.instructions,'required',f.required,
            'allowNa',f.allow_na,'requirement',f.requirement,'acceptanceCriteria',f.acceptance_criteria,
            'referenceText',f.reference_text,'photoRequired',f.photo_required,'minimumPhotos',f.minimum_photos,
            'fileRequired',f.file_required,'requireCommentOnFail',f.require_comment_on_fail,
            'requirePhotoOnFail',f.require_photo_on_fail,'createIssueOnFail',f.create_issue_on_fail,
            'requireRectificationOnFail',f.require_rectification_on_fail,'blockCompletionOnFail',f.block_completion_on_fail,
            'requireSupervisorReviewOnFail',f.require_supervisor_review_on_fail,'aiReviewEnabled',f.ai_review_enabled,
            'aiReviewInstruction',f.ai_review_instruction,'includeInReport',f.include_in_report,
            'configuration',f.configuration,'configurationSchemaVersion',f.configuration_schema_version,
            'sortOrder',f.sort_order,
            'options',coalesce((select jsonb_agg(jsonb_build_object('id',o.id,'label',o.label,'value',o.value,'sortOrder',o.sort_order) order by o.sort_order,o.id)
              from public.project_qa_field_options o where o.organization_id=p_organization_id and o.project_id=p_project_id and o.project_qa_id=p_project_qa_id and o.field_id=f.id),'[]'::jsonb)
          ) order by f.sort_order,f.id)
          from public.project_qa_fields f where f.organization_id=p_organization_id and f.project_id=p_project_id and f.project_qa_id=p_project_qa_id and f.section_id=s.id
        ),'[]'::jsonb)
      ) order by s.sort_order,s.id)
      from public.project_qa_sections s where s.organization_id=p_organization_id and s.project_id=p_project_id and s.project_qa_id=p_project_qa_id
    ),'[]'::jsonb)
  ) into snapshot;
  snapshot_hash:=encode(extensions.digest(convert_to(snapshot::text,'UTF8'),'sha256'),'hex');

  insert into public.project_qa_runs(
    organization_id,project_id,project_qa_id,project_qa_definition_version,
    definition_snapshot_schema_version,definition_snapshot,definition_snapshot_hash,status,
    title,location_label,started_by,start_idempotency_key
  ) values (
    p_organization_id,p_project_id,p_project_qa_id,qa_row.definition_version,
    1,snapshot,snapshot_hash,'in_progress',left(btrim(coalesce(p_title,'')),240),left(btrim(coalesce(p_location_label,'')),240),auth.uid(),p_start_idempotency_key
  ) on conflict (organization_id,started_by,start_idempotency_key) do nothing returning id into inserted_id;

  if inserted_id is null then
    select * into existing_row from public.project_qa_runs
    where organization_id=p_organization_id and started_by=auth.uid() and start_idempotency_key=p_start_idempotency_key;
    if existing_row.project_id<>p_project_id or existing_row.project_qa_id<>p_project_qa_id then
      raise exception 'Start idempotency key was already used for another QA Record' using errcode='TS409';
    end if;
    return query select existing_row.id,false;
    return;
  end if;

  insert into public.project_qa_responses(
    organization_id,project_id,run_id,captured_section_id,captured_field_id,
    section_sort_order,field_sort_order,field_type,field_snapshot,updated_by
  )
  select p_organization_id,p_project_id,inserted_id,s.id,f.id,s.sort_order,f.sort_order,f.field_type,
    jsonb_build_object(
      'id',f.id,'sectionId',f.section_id,'fieldType',f.field_type,'label',f.label,
      'description',f.description,'instructions',f.instructions,'required',f.required,'allowNa',f.allow_na,
      'requirement',f.requirement,'acceptanceCriteria',f.acceptance_criteria,'referenceText',f.reference_text,
      'photoRequired',f.photo_required,'minimumPhotos',f.minimum_photos,'fileRequired',f.file_required,
      'requireCommentOnFail',f.require_comment_on_fail,'requirePhotoOnFail',f.require_photo_on_fail,
      'createIssueOnFail',f.create_issue_on_fail,'requireRectificationOnFail',f.require_rectification_on_fail,
      'blockCompletionOnFail',f.block_completion_on_fail,'requireSupervisorReviewOnFail',f.require_supervisor_review_on_fail,
      'aiReviewEnabled',f.ai_review_enabled,'aiReviewInstruction',f.ai_review_instruction,
      'includeInReport',f.include_in_report,'configuration',f.configuration,
      'configurationSchemaVersion',f.configuration_schema_version,'sortOrder',f.sort_order,
      'options',coalesce((select jsonb_agg(jsonb_build_object('id',o.id,'label',o.label,'value',o.value,'sortOrder',o.sort_order) order by o.sort_order,o.id)
        from public.project_qa_field_options o where o.organization_id=p_organization_id and o.project_id=p_project_id and o.project_qa_id=p_project_qa_id and o.field_id=f.id),'[]'::jsonb)
    ),auth.uid()
  from public.project_qa_sections s join public.project_qa_fields f on f.organization_id=s.organization_id and f.project_id=s.project_id and f.project_qa_id=s.project_qa_id and f.section_id=s.id
  where s.organization_id=p_organization_id and s.project_id=p_project_id and s.project_qa_id=p_project_qa_id
  order by s.sort_order,s.id,f.sort_order,f.id;

  return query select inserted_id,true;
end; $$;


ALTER FUNCTION "public"."start_project_qa_run_v1"("p_organization_id" "uuid", "p_project_id" "uuid", "p_project_qa_id" "uuid", "p_start_idempotency_key" "uuid", "p_title" "text", "p_location_label" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_retention_claim"("p_retention_claim_id" "uuid", "p_expected_draft_revision" bigint, "p_expected_position_state_hash" "text", "p_correlation_id" "text" DEFAULT NULL::"text", "p_expected_eligibility_state_hash" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_project_id uuid;
  v_result jsonb;
  v_successor jsonb;
begin
  select project_id into v_project_id
  from public.retention_claims where id = p_retention_claim_id;
  if v_project_id is not null then
    perform pg_advisory_xact_lock(
      hashtextextended(v_project_id::text || ':automatic_retention_draft', 7)
    );
    perform 1 from public.retention_claims
    where id = p_retention_claim_id for update;
  end if;
  v_result := public.submit_retention_claim_pre_document_successor(
    p_retention_claim_id, p_expected_draft_revision,
    p_expected_position_state_hash, p_correlation_id,
    p_expected_eligibility_state_hash
  );
  if coalesce((v_result ->> 'succeeded')::boolean, false) then
    v_successor := private.create_retention_successor_draft(
      p_retention_claim_id, p_correlation_id
    );
    v_result := v_result || jsonb_build_object('successorDraft', v_successor);
  end if;
  return v_result;
end;
$$;


ALTER FUNCTION "public"."submit_retention_claim"("p_retention_claim_id" "uuid", "p_expected_draft_revision" bigint, "p_expected_position_state_hash" "text", "p_correlation_id" "text", "p_expected_eligibility_state_hash" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_retention_claim_phase3_pre_schedule"("p_retention_claim_id" "uuid", "p_expected_draft_revision" bigint, "p_expected_position_state_hash" "text", "p_correlation_id" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_claim public.retention_claims%rowtype;
  v_context jsonb;
  v_position jsonb;
  v_current_state_hash text;
  v_allocation_count integer;
  v_subtotal numeric(14,2);
  v_invalid_details jsonb;
  v_overallocated_details jsonb;
begin
  select * into v_claim
  from public.retention_claims claim
  where claim.id = p_retention_claim_id;
  if not found then
    return jsonb_build_object('succeeded', false, 'errorCode', 'claim_not_found');
  end if;

  v_context := private.retention_claim_operation_context(
    v_claim.project_id,
    'retention.claims.submit',
    true
  );
  if not coalesce((v_context ->> 'succeeded')::boolean, false) then
    if (v_context ->> 'organizationId')::uuid is not distinct from v_claim.organization_id then
      perform private.record_retention_claim_event(
        v_claim.organization_id, v_claim.project_id, v_claim.id,
        'permission_denied', v_claim.status, v_claim.status, auth.uid(),
        v_context ->> 'errorCode', p_correlation_id,
        jsonb_build_object('operation', 'submit_retention_claim')
      );
    end if;
    return v_context;
  end if;

  select * into v_claim
  from public.retention_claims claim
  where claim.id = p_retention_claim_id
    and claim.organization_id = (v_context ->> 'organizationId')::uuid
  for update;
  if not found then
    return jsonb_build_object('succeeded', false, 'errorCode', 'claim_not_found');
  end if;
  if v_claim.status <> 'draft' then
    return private.reject_retention_claim_submission(
      v_claim.id,
      case
        when v_claim.status = 'submitted' then 'submitted_claim_immutable'
        else 'claim_not_draft'
      end,
      jsonb_build_object('status', v_claim.status),
      p_correlation_id
    );
  end if;
  if v_claim.draft_revision <> p_expected_draft_revision then
    return private.reject_retention_claim_submission(
      v_claim.id,
      'concurrent_update',
      jsonb_build_object('currentDraftRevision', v_claim.draft_revision),
      p_correlation_id
    );
  end if;

  select count(*)::integer, round(coalesce(sum(allocation_amount), 0), 2)
  into v_allocation_count, v_subtotal
  from public.retention_claim_allocations allocation
  where allocation.retention_claim_id = v_claim.id;

  if v_allocation_count = 0 then
    return private.reject_retention_claim_submission(
      v_claim.id,
      'invalid_allocation_amount',
      jsonb_build_object('reason', 'allocation_required'),
      p_correlation_id
    );
  end if;

  -- Origin Payment Claim locks are acquired deterministically. They serialize
  -- competing submissions without invoking any Payment Claim workflow.
  perform origin.id
  from public.project_claims origin
  join public.retention_claim_allocations allocation
    on allocation.originating_payment_claim_id = origin.id
  where allocation.retention_claim_id = v_claim.id
    and origin.organization_id = v_claim.organization_id
    and origin.project_id = v_claim.project_id
  order by origin.id
  for update of origin;

  select jsonb_agg(
    jsonb_build_object(
      'allocationId', allocation.id,
      'originatingPaymentClaimId', allocation.originating_payment_claim_id,
      'errorCode',
        case
          when origin.id is null then 'origin_not_found'
          when origin.organization_id <> v_claim.organization_id
            or origin.project_id <> v_claim.project_id then 'cross_project_origin'
          when origin.status = 'Cancelled' then 'origin_cancelled'
          when allocation.allocation_amount <= 0 then 'invalid_allocation_amount'
          else null
        end
    )
    order by allocation.originating_payment_claim_id
  ) filter (
    where origin.id is null
      or origin.organization_id <> v_claim.organization_id
      or origin.project_id <> v_claim.project_id
      or origin.status = 'Cancelled'
      or allocation.allocation_amount <= 0
  )
  into v_invalid_details
  from public.retention_claim_allocations allocation
  left join public.project_claims origin
    on origin.id = allocation.originating_payment_claim_id
  where allocation.retention_claim_id = v_claim.id;

  if v_invalid_details is not null then
    return private.reject_retention_claim_submission(
      v_claim.id,
      coalesce(v_invalid_details -> 0 ->> 'errorCode', 'origin_not_found'),
      jsonb_build_object('origins', v_invalid_details),
      p_correlation_id
    );
  end if;

  v_position := public.get_project_retention_position_summary(v_claim.project_id);
  v_current_state_hash := v_position ->> 'stateHash';

  if coalesce(v_position ->> 'accessState', '') <> 'available' then
    return private.reject_retention_claim_submission(
      v_claim.id,
      case
        when coalesce((v_position ->> 'capabilityEnabled')::boolean, false)
          then 'project_mode_not_supported'
        else 'capability_disabled'
      end,
      jsonb_build_object(
        'accessState', v_position ->> 'accessState',
        'workflowMode', v_position ->> 'workflowMode'
      ),
      p_correlation_id
    );
  end if;

  if p_expected_position_state_hash is null
    or p_expected_position_state_hash <> v_current_state_hash
    or v_claim.last_position_state_hash <> v_current_state_hash then
    return private.reject_retention_claim_submission(
      v_claim.id,
      'stale_draft',
      jsonb_build_object(
        'draftPositionStateHash', v_claim.last_position_state_hash,
        'expectedPositionStateHash', p_expected_position_state_hash,
        'currentPositionStateHash', v_current_state_hash,
        'origins', private.retention_claim_current_origin_details(v_claim.id)
      ),
      p_correlation_id
    );
  end if;

  if coalesce(
    (v_position ->> 'legacyReconciliationRequired')::boolean,
    false
  ) then
    return private.reject_retention_claim_submission(
      v_claim.id,
      'unresolved_legacy_release',
      jsonb_build_object(
        'totalLegacyRetentionReleased',
          v_position -> 'totalLegacyRetentionReleased',
        'legacyReleaseOrigins', v_position -> 'legacyReleaseOrigins'
      ),
      p_correlation_id
    );
  end if;

  with committed as (
    select
      existing.originating_payment_claim_id,
      round(coalesce(sum(existing.allocation_amount), 0), 2)
        as submitted_total
    from public.retention_claim_allocations existing
    join public.retention_claims submitted_claim
      on submitted_claim.id = existing.retention_claim_id
    where submitted_claim.status = 'submitted'
      and submitted_claim.id <> v_claim.id
    group by existing.originating_payment_claim_id
  )
  select jsonb_agg(
    jsonb_build_object(
      'originatingPaymentClaimId', origin.id,
      'currentRetentionOwned', greatest(origin.retention_withheld_amount, 0),
      'existingSubmittedAllocation',
        coalesce(committed.submitted_total, 0),
      'proposedAllocation', allocation.allocation_amount,
      'currentAvailableBeforeSchedules',
        greatest(
          greatest(origin.retention_withheld_amount, 0)
          - coalesce(committed.submitted_total, 0),
          0
        )
    )
    order by origin.id
  )
  into v_overallocated_details
  from public.retention_claim_allocations allocation
  join public.project_claims origin
    on origin.id = allocation.originating_payment_claim_id
  left join committed
    on committed.originating_payment_claim_id = origin.id
  where allocation.retention_claim_id = v_claim.id
    and coalesce(committed.submitted_total, 0) + allocation.allocation_amount
      > greatest(origin.retention_withheld_amount, 0);

  if v_overallocated_details is not null then
    return private.reject_retention_claim_submission(
      v_claim.id,
      'retention_overallocated',
      jsonb_build_object('origins', v_overallocated_details),
      p_correlation_id
    );
  end if;

  with committed as (
    select
      existing.originating_payment_claim_id,
      round(coalesce(sum(existing.allocation_amount), 0), 2)
        as submitted_total
    from public.retention_claim_allocations existing
    join public.retention_claims submitted_claim
      on submitted_claim.id = existing.retention_claim_id
    where submitted_claim.status = 'submitted'
      and submitted_claim.id <> v_claim.id
    group by existing.originating_payment_claim_id
  )
  update public.retention_claim_allocations allocation
  set
    origin_claim_number_snapshot = origin.claim_number,
    origin_claim_date_snapshot = origin.claim_date,
    origin_claim_status_snapshot = origin.status,
    origin_claim_created_at_snapshot = origin.created_at,
    origin_claim_updated_at_snapshot = origin.updated_at,
    retention_method_snapshot = origin.retention_method,
    retention_rate_snapshot = origin.retention_percent,
    retention_scale_bands_snapshot = origin.retention_scale_bands,
    retention_withheld_snapshot = origin.retention_withheld_amount,
    retention_released_snapshot = origin.retention_released_amount,
    retention_held_to_date_snapshot = origin.retention_held_to_date,
    retention_released_to_date_snapshot = origin.retention_released_to_date,
    retention_balance_snapshot = origin.retention_balance,
    existing_submitted_allocation_before =
      coalesce(committed.submitted_total, 0),
    remaining_after_allocation = round(
      greatest(origin.retention_withheld_amount, 0)
      - coalesce(committed.submitted_total, 0)
      - allocation.allocation_amount,
      2
    ),
    gross_claim_amount_snapshot = origin.claim_amount,
    net_claim_excl_gst_snapshot = origin.net_claim_excl_gst,
    gst_amount_snapshot = origin.gst_amount,
    total_payable_snapshot = origin.total_payable,
    project_state_hash_snapshot = v_current_state_hash,
    origin_state_hash_snapshot =
      private.retention_claim_origin_state_hash(origin.id),
    submitted_by = auth.uid(),
    submitted_at = now()
  from public.project_claims origin
  left join committed
    on committed.originating_payment_claim_id = origin.id
  where allocation.retention_claim_id = v_claim.id
    and origin.id = allocation.originating_payment_claim_id;

  update public.retention_claims claim
  set
    status = 'submitted',
    subtotal_excl_tax = v_subtotal,
    submission_state_hash = v_current_state_hash,
    submitted_by = auth.uid(),
    submitted_at = now()
  where claim.id = v_claim.id
  returning * into v_claim;

  perform private.record_retention_claim_event(
    v_claim.organization_id, v_claim.project_id, v_claim.id,
    'claim_submitted', 'draft', 'submitted', auth.uid(),
    'Retention Claim submitted.', p_correlation_id,
    jsonb_build_object(
      'allocationCount', v_allocation_count,
      'subtotalExclTax', v_subtotal,
      'submissionStateHash', v_current_state_hash,
      'draftRevision', v_claim.draft_revision
    )
  );

  return jsonb_build_object(
    'succeeded', true,
    'errorCode', null,
    'claim', private.retention_claim_header_json(v_claim.id),
    'allocations', private.retention_claim_current_origin_details(v_claim.id)
  );
end;
$$;


ALTER FUNCTION "public"."submit_retention_claim_phase3_pre_schedule"("p_retention_claim_id" "uuid", "p_expected_draft_revision" bigint, "p_expected_position_state_hash" "text", "p_correlation_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_retention_claim_phase4_pre_variance"("p_retention_claim_id" "uuid", "p_expected_draft_revision" bigint, "p_expected_position_state_hash" "text", "p_correlation_id" "text" DEFAULT NULL::"text", "p_expected_eligibility_state_hash" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private'
    AS $$
declare
  claim public.retention_claims%rowtype;
  state jsonb;
  state_hash text;
  invalid_lines jsonb;
  result jsonb;
begin
  select *
  into claim
  from public.retention_claims
  where id = p_retention_claim_id
  for update;

  if not found then
    return jsonb_build_object(
      'succeeded', false,
      'errorCode', 'claim_not_found'
    );
  end if;

  -- Serialize every submission path that can consume the same originating
  -- Payment Claim before recomputing immutable prior allocations.
  perform origin.id
  from public.project_claims origin
  join public.retention_claim_allocations allocation
    on allocation.originating_payment_claim_id = origin.id
  where allocation.retention_claim_id = claim.id
    and origin.organization_id = claim.organization_id
    and origin.project_id = claim.project_id
  order by origin.id
  for update of origin;

  state := private.retention_eligibility_state(claim.project_id);
  state_hash := state ->> 'eligibilityStateHash';

  if p_expected_eligibility_state_hash is null
    or p_expected_eligibility_state_hash <> state_hash
    or claim.last_eligibility_state_hash <> state_hash
  then
    return private.reject_retention_claim_submission(
      claim.id,
      'stale_eligibility',
      jsonb_build_object(
        'eligibilityModel', 'accumulated_retention_v1',
        'draftEligibilityStateHash', claim.last_eligibility_state_hash,
        'expectedEligibilityStateHash', p_expected_eligibility_state_hash,
        'currentEligibilityStateHash', state_hash,
        'origins', state -> 'origins'
      ),
      p_correlation_id
    );
  end if;

  select jsonb_agg(jsonb_build_object(
    'originatingPaymentClaimId', allocation.originating_payment_claim_id,
    'proposedAllocation', allocation.allocation_amount,
    'retentionHeld', coalesce((eligible ->> 'retentionHeld')::numeric, 0),
    'previouslyClaimed',
      coalesce((eligible ->> 'previouslyClaimed')::numeric, 0),
    'remainingRetention',
      coalesce((eligible ->> 'remainingRetention')::numeric, 0)
  ) order by allocation.originating_payment_claim_id)
  into invalid_lines
  from public.retention_claim_allocations allocation
  left join lateral (
    select value as eligible
    from jsonb_array_elements(coalesce(state -> 'origins', '[]'::jsonb))
    where value ->> 'originatingPaymentClaimId' =
      allocation.originating_payment_claim_id::text
  ) eligibility on true
  where allocation.retention_claim_id = claim.id
    and allocation.allocation_amount >
      coalesce((eligible ->> 'remainingRetention')::numeric, 0);

  if invalid_lines is not null then
    return private.reject_retention_claim_submission(
      claim.id,
      case
        when exists (
          select 1
          from jsonb_array_elements(invalid_lines) line
          where coalesce((line ->> 'remainingRetention')::numeric, 0) = 0
        ) then 'retention_not_eligible'
        else 'allocation_exceeds_eligibility'
      end,
      jsonb_build_object(
        'eligibilityModel', 'accumulated_retention_v1',
        'origins', invalid_lines,
        'eligibilityStateHash', state_hash
      ),
      p_correlation_id
    );
  end if;

  result := public.submit_retention_claim_phase3_pre_schedule(
    p_retention_claim_id,
    p_expected_draft_revision,
    p_expected_position_state_hash,
    p_correlation_id
  );
  if not coalesce((result ->> 'succeeded')::boolean, false) then
    return result;
  end if;

  perform set_config('app.retention_phase4_submission_write', 'true', true);
  update public.retention_claim_allocations allocation
  set
    eligibility_state_hash_snapshot = state_hash,
    eligibility_schedule_ids_snapshot = '{}'::uuid[]
  where allocation.retention_claim_id = claim.id;

  update public.retention_claims
  set submission_eligibility_state_hash = state_hash
  where id = claim.id;
  perform set_config('app.retention_phase4_submission_write', '', true);

  return result || jsonb_build_object(
    'eligibilityStateHash', state_hash,
    'eligibilityModel', 'accumulated_retention_v1',
    'eligibility', state
  );
end;
$$;


ALTER FUNCTION "public"."submit_retention_claim_phase4_pre_variance"("p_retention_claim_id" "uuid", "p_expected_draft_revision" bigint, "p_expected_position_state_hash" "text", "p_correlation_id" "text", "p_expected_eligibility_state_hash" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_retention_claim_phase5_pre_legacy_reconciliation"("p_retention_claim_id" "uuid", "p_expected_draft_revision" bigint, "p_expected_position_state_hash" "text", "p_correlation_id" "text" DEFAULT NULL::"text", "p_expected_eligibility_state_hash" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare c public.retention_claims%rowtype; ctx jsonb; origins uuid[]; blocks jsonb;
begin
  if not private.retention_phase5_gate_enabled() then
    return public.submit_retention_claim_phase4_pre_variance(
      p_retention_claim_id,p_expected_draft_revision,p_expected_position_state_hash,
      p_correlation_id,p_expected_eligibility_state_hash);
  end if;
  select * into c from public.retention_claims where id=p_retention_claim_id;
  if not found then return jsonb_build_object('succeeded',false,'errorCode','claim_not_found'); end if;
  ctx:=private.retention_phase5_context(c.project_id,'retention.claims.submit',true);
  if not coalesce((ctx->>'succeeded')::boolean,false) then return ctx; end if;
  select coalesce(array_agg(a.originating_payment_claim_id order by a.originating_payment_claim_id),
    '{}'::uuid[]) into origins
  from public.retention_claim_allocations a where a.retention_claim_id=c.id;
  perform private.evaluate_retention_variance_project(c.project_id,p_correlation_id,origins);
  blocks:=private.retention_variance_blocking_details(c.project_id,origins);
  if coalesce((blocks->>'blocking')::boolean,false) then
    return private.reject_retention_claim_submission(c.id,'variance_blocking',blocks,p_correlation_id);
  end if;
  return public.submit_retention_claim_phase4_pre_variance(
    p_retention_claim_id,p_expected_draft_revision,p_expected_position_state_hash,
    p_correlation_id,p_expected_eligibility_state_hash);
end;
$$;


ALTER FUNCTION "public"."submit_retention_claim_phase5_pre_legacy_reconciliation"("p_retention_claim_id" "uuid", "p_expected_draft_revision" bigint, "p_expected_position_state_hash" "text", "p_correlation_id" "text", "p_expected_eligibility_state_hash" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_retention_claim_pre_document_successor"("p_retention_claim_id" "uuid", "p_expected_draft_revision" bigint, "p_expected_position_state_hash" "text", "p_correlation_id" "text" DEFAULT NULL::"text", "p_expected_eligibility_state_hash" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare result jsonb; claim_row public.retention_claims%rowtype;
begin
  if not private.retention_phase6_gate_enabled() then
    return public.submit_retention_claim_phase5_pre_legacy_reconciliation(
      p_retention_claim_id,p_expected_draft_revision,p_expected_position_state_hash,
      p_correlation_id,p_expected_eligibility_state_hash);
  end if;
  result:=public.submit_retention_claim_phase5_pre_legacy_reconciliation(
    p_retention_claim_id,p_expected_draft_revision,p_expected_position_state_hash,
    p_correlation_id,p_expected_eligibility_state_hash);
  if not coalesce((result->>'succeeded')::boolean,false) then return result; end if;
  select * into claim_row from public.retention_claims where id=p_retention_claim_id;
  perform set_config('app.retention_phase4_submission_write','true',true);
  update public.retention_claim_allocations a set
    existing_submitted_allocation_before=round(
      a.existing_submitted_allocation_before+coalesce(l.amount,0),2),
    remaining_after_allocation=round(
      a.retention_withheld_snapshot
      -a.existing_submitted_allocation_before-coalesce(l.amount,0)
      -a.allocation_amount,2)
  from private.current_legacy_committed_by_origin(claim_row.project_id) l
  where a.retention_claim_id=p_retention_claim_id
    and l.originating_payment_claim_id=a.originating_payment_claim_id;
  perform set_config('app.retention_phase4_submission_write','',true);
  return result||jsonb_build_object(
    'allocations',private.retention_claim_current_origin_details(p_retention_claim_id),
    'effectiveLegacyReconciliationCaseId',
      private.current_effective_retention_legacy_case(claim_row.project_id)
  );
end;
$$;


ALTER FUNCTION "public"."submit_retention_claim_pre_document_successor"("p_retention_claim_id" "uuid", "p_expected_draft_revision" bigint, "p_expected_position_state_hash" "text", "p_correlation_id" "text", "p_expected_eligibility_state_hash" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_retention_legacy_reconciliation_case"("p_input" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare c public.retention_legacy_reconciliation_cases%rowtype; ctx jsonb;
  validation jsonb; note text; evidence_ref text; evidence_value jsonb;
begin
  select * into c from public.retention_legacy_reconciliation_cases
  where id=(p_input->>'caseId')::uuid;
  if not found then return jsonb_build_object('succeeded',false,'errorCode','legacy_case_not_found'); end if;
  ctx:=private.retention_phase6_context(c.project_id,'retention.legacy.reconcile',true);
  if not coalesce((ctx->>'succeeded')::boolean,false) then return ctx; end if;
  select * into c from public.retention_legacy_reconciliation_cases where id=c.id for update;
  if c.status not in ('draft','rejected') then
    return jsonb_build_object('succeeded',false,'errorCode','invalid_legacy_transition');
  end if;
  if c.revision<>(p_input->>'expectedRevision')::bigint then
    return jsonb_build_object('succeeded',false,'errorCode','concurrent_update',
      'currentRevision',c.revision);
  end if;
  note:=nullif(trim(coalesce(p_input->>'reconciliationNote','')),'');
  evidence_ref:=nullif(trim(coalesce(p_input->>'evidenceReference','')),'');
  evidence_value:=p_input->'evidence';
  if note is null or evidence_ref is null or evidence_value is null
    or jsonb_typeof(evidence_value)<>'object' or evidence_value='{}'::jsonb then
    return jsonb_build_object('succeeded',false,'errorCode','reconciliation_evidence_required');
  end if;
  validation:=private.validate_retention_legacy_case(c.id);
  if not coalesce((validation->>'succeeded')::boolean,false) then
    perform private.record_retention_legacy_event(
      c.id,'submission_rejected',c.status,c.status,
      validation->>'errorCode',p_input->>'correlationId',validation);
    return validation;
  end if;
  perform set_config('app.retention_phase6_internal_write','true',true);
  update public.retention_legacy_release_allocations a set
    origin_claim_number_snapshot=p.claim_number,
    origin_claim_date_snapshot=p.claim_date,
    origin_claim_status_snapshot=p.status,
    origin_claim_created_at_snapshot=p.created_at,
    origin_claim_updated_at_snapshot=p.updated_at,
    origin_retention_owned_snapshot=greatest(p.retention_withheld_amount,0),
    origin_state_hash_snapshot=private.retention_claim_origin_state_hash(p.id),
    position_state_hash_snapshot=c.position_state_hash,
    updated_at=now()
  from public.project_claims p
  where a.reconciliation_case_id=c.id and p.id=a.originating_payment_claim_id;
  update public.retention_legacy_reconciliation_cases set
    status='in_review',reconciliation_note=note,evidence_reference=evidence_ref,
    evidence=evidence_value,submitted_by=auth.uid(),submitted_at=now(),
    rejected_by=null,rejected_at=null,rejection_reason=null,
    total_allocated=(validation->>'totalAllocated')::numeric,
    allocation_count=(validation->>'allocationCount')::integer,
    revision=revision+1,updated_at=now()
  where id=c.id returning * into c;
  perform set_config('app.retention_phase6_internal_write','',true);
  perform private.record_retention_legacy_event(
    c.id,'submitted_for_approval','draft','in_review',
    'Legacy retention reconciliation submitted for approval.',
    p_input->>'correlationId',jsonb_build_object(
      'evidenceReference',evidence_ref,'validation',validation));
  return jsonb_build_object('succeeded',true,'errorCode',null,
    'case',private.retention_legacy_case_json(c.id));
end;
$$;


ALTER FUNCTION "public"."submit_retention_legacy_reconciliation_case"("p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_supplier_invoice_for_site_review"("p_supplier_invoice_id" "uuid", "p_expected_finance_hash" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_organization_id uuid;
  v_submission_id uuid;
begin
  perform pg_advisory_xact_lock(hashtextextended(p_supplier_invoice_id::text, 0));
  select m.organization_id into v_organization_id
  from public.organization_members m where m.user_id = auth.uid()
  order by m.created_at limit 1;
  if v_organization_id is null
    or not public.has_org_permission(v_organization_id, 'supplier_invoices.submit_site_review') then
    raise exception 'You do not have permission to submit Supplier Invoices for site review.';
  end if;
  select s.id into v_submission_id
  from public.supplier_invoice_site_review_submissions s
  where s.organization_id = v_organization_id
    and s.supplier_invoice_id = p_supplier_invoice_id
    and s.finance_hash = p_expected_finance_hash
    and s.status in ('submitted', 'partially_reviewed', 'approved', 'disputed')
  order by s.submitted_at desc limit 1;
  if v_submission_id is not null then return v_submission_id; end if;
  return private.submit_supplier_invoice_for_site_review_phase_ab_legacy(
    p_supplier_invoice_id, p_expected_finance_hash
  );
end;
$$;


ALTER FUNCTION "public"."submit_supplier_invoice_for_site_review"("p_supplier_invoice_id" "uuid", "p_expected_finance_hash" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."supersede_previous_cost_items"("p_document_kind" "text", "p_document_id" "uuid", "p_source_revision_key" "text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  resolved_context record;
  affected_count integer := 0;
begin
  select *
  into resolved_context
  from public.resolve_cost_item_document_context(p_document_kind, p_document_id)
  limit 1;

  if resolved_context.organization_id is null then
    raise exception 'Document not found or not authorized for CostItem supersede';
  end if;

  update public.cost_items ci
  set
    is_current = false,
    effective_to = coalesce(ci.effective_to, clock_timestamp()),
    status = case
      when ci.status = 'deleted' then ci.status
      else 'superseded'
    end
  where ci.source_document_kind = p_document_kind
    and ci.source_document_id = p_document_id
    and ci.is_current = true
    and ci.source_revision_key is distinct from p_source_revision_key;

  get diagnostics affected_count = row_count;
  return affected_count;
end;
$$;


ALTER FUNCTION "public"."supersede_previous_cost_items"("p_document_kind" "text", "p_document_id" "uuid", "p_source_revision_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."supplier_invoice_finance_version_hash"("p_invoice_id" "uuid") RETURNS "text"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'extensions'
    AS $$
  select encode(extensions.digest(concat_ws('|',
    i.id::text,
    coalesce(i.supplier_id::text, ''),
    public.normalize_supplier_invoice_number(coalesce(i.invoice_number, '')),
    coalesce(nullif(lower(regexp_replace(trim(coalesce(i.supplier_po_reference, '')), '[[:space:]]+', ' ', 'g')), ''), ''),
    coalesce(i.invoice_date::text, ''), coalesce(i.due_date::text, ''),
    coalesce(i.currency, ''), coalesce(i.subtotal::text, ''),
    coalesce(i.tax_total::text, ''), coalesce(i.total::text, ''),
    coalesce((select string_agg(concat_ws(':', l.id::text, l.description, l.quantity::text,
      l.unit_price::text, l.line_total::text, l.tax_amount::text, l.sort_order::text),
      ',' order by l.sort_order, l.id) from public.supplier_invoice_lines l
      where l.supplier_invoice_id = i.id), ''),
    coalesce((select string_agg(concat_ws(':', a.id::text,
      coalesce(a.purchase_order_id::text, ''), coalesce(a.purchase_order_line_item_id::text, ''),
      coalesce(a.project_id::text, ''), coalesce(a.allocated_quantity::text, ''),
      a.allocated_amount::text, coalesce(a.accounting_mapping_id::text, ''),
      coalesce(a.accounting_tax_rate_id::text, ''), a.tax_resolution_status),
      ',' order by a.supplier_invoice_line_id, a.allocation_sequence, a.id)
      from public.supplier_invoice_line_allocations a where a.supplier_invoice_id = i.id), ''),
    coalesce((select string_agg(concat_ws(':', po.id::text, coalesce(po.supplier_id::text, ''),
      po.status, po.total_purchase_order_price::text, po_line.id::text, po_line.description,
      po_line.quantity::text, po_line.rate::text, po_line.total::text), ',' order by po.id, po_line.id)
      from public.supplier_invoice_line_allocations a
      join public.project_purchase_orders po on po.id = a.purchase_order_id
      join public.project_purchase_order_line_items po_line on po_line.id = a.purchase_order_line_item_id
      where a.supplier_invoice_id = i.id), '')
  ), 'sha256'), 'hex')
  from public.supplier_invoices i where i.id = p_invoice_id;
$$;


ALTER FUNCTION "public"."supplier_invoice_finance_version_hash"("p_invoice_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_commercial_item_lineage"("p_commercial_item_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  item_organization_id uuid;
begin
  select organization_id into item_organization_id
  from public.commercial_items where id = p_commercial_item_id;
  if item_organization_id is null then
    raise exception 'commercial_lineage:commercial_item_not_found' using errcode = 'P0002';
  end if;
  if auth.role() <> 'service_role'
    and not public.is_member_of_organization(item_organization_id) then
    raise exception 'commercial_lineage:permission_denied' using errcode = '42501';
  end if;
  return public.sync_commercial_item_lineage_internal(p_commercial_item_id, null);
end;
$$;


ALTER FUNCTION "public"."sync_commercial_item_lineage"("p_commercial_item_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_commercial_item_lineage_internal"("p_commercial_item_id" "uuid", "p_evidence_batch_id" "uuid" DEFAULT NULL::"uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  item public.commercial_items%rowtype;
  cell jsonb;
  material jsonb;
  measure jsonb;
  source_price_id uuid;
  inserted_count integer := 0;
  affected integer := 0;
  owner_id uuid;
begin
  select * into item from public.commercial_items where id = p_commercial_item_id;
  if not found then
    raise exception 'commercial_lineage:commercial_item_not_found' using errcode = 'P0002';
  end if;

  if jsonb_typeof(item.locked_metadata_json -> 'cells') = 'array' then
    for cell in select value from jsonb_array_elements(item.locked_metadata_json -> 'cells') loop
      material := cell -> 'metadata' -> 'materialPricing';
      if jsonb_typeof(material) = 'object' and (material ->> 'version') in ('1', '2') then
        source_price_id := case
          when material ->> 'version' = '2' then nullif(material #>> '{sourcePricing,supplierPriceId}', '')::uuid
          else nullif(material ->> 'supplierPriceId', '')::uuid
        end;

        if exists (
          select 1
          from public.worksheet_material_price_bindings binding
          where binding.id = nullif(material ->> 'bindingId', '')::uuid
            and binding.organization_id = item.organization_id
            and binding.workbook_id = item.source_workbook_id
            and binding.sheet_id = item.source_sheet_id
            and binding.current_cell_address = cell ->> 'cellKey'
            and binding.organization_material_id = nullif(material ->> 'organizationMaterialId', '')::uuid
            and binding.supplier_product_id = nullif(material ->> 'supplierProductId', '')::uuid
            and binding.supplier_price_id = source_price_id
            and binding.binding_state = 'active'
        ) then
          insert into public.commercial_lineage_edges (
            organization_id, project_id, from_entity_type, from_entity_id,
            to_entity_type, to_entity_id, relationship_type,
            evidence_source, evidence_version, evidence_ref, evidence_batch_id, created_by
          ) values
          (item.organization_id, item.project_id, 'commercial_item', item.id,
            'organization_material', (material ->> 'organizationMaterialId')::uuid, 'derived_from_material',
            'commercial_item_locked_metadata', 'material_pricing_v' || (material ->> 'version'),
            jsonb_build_object('cellKey', cell ->> 'cellKey', 'bindingId', material ->> 'bindingId',
              'worksheetVersion', item.locked_metadata_json -> 'worksheetVersion'), p_evidence_batch_id, item.created_by),
          (item.organization_id, item.project_id, 'commercial_item', item.id,
            'organization_material_supplier_product', (material ->> 'supplierProductId')::uuid, 'priced_from_supplier_product',
            'commercial_item_locked_metadata', 'material_pricing_v' || (material ->> 'version'),
            jsonb_build_object('cellKey', cell ->> 'cellKey', 'bindingId', material ->> 'bindingId',
              'worksheetVersion', item.locked_metadata_json -> 'worksheetVersion'), p_evidence_batch_id, item.created_by),
          (item.organization_id, item.project_id, 'commercial_item', item.id,
            'organization_material_supplier_price', source_price_id, 'priced_from_supplier_price',
            'commercial_item_locked_metadata', 'material_pricing_v' || (material ->> 'version'),
            jsonb_build_object('cellKey', cell ->> 'cellKey', 'bindingId', material ->> 'bindingId',
              'worksheetVersion', item.locked_metadata_json -> 'worksheetVersion'), p_evidence_batch_id, item.created_by)
          on conflict (organization_id, from_entity_type, from_entity_id, to_entity_type, to_entity_id, relationship_type)
            where superseded_at is null do nothing;
          get diagnostics affected = row_count;
          inserted_count := inserted_count + affected;
        end if;
      end if;

      measure := cell -> 'metadata' -> 'measureSource';
      if jsonb_typeof(measure) = 'object' and measure ->> 'version' = '1'
        and exists (
          select 1
          from public.takeoff_measurements measurement
          where measurement.id = nullif(measure ->> 'measurementId', '')::uuid
            and measurement.organization_id = item.organization_id
            and measurement.project_id = nullif(measure ->> 'projectId', '')::uuid
            and (item.project_id is null or measurement.project_id = item.project_id)
            and (item.project_id is not null or measurement.opportunity_id = item.opportunity_id)
            and measurement.drawing_set_id = nullif(measure ->> 'drawingSetId', '')::uuid
            and measurement.page_id = nullif(measure ->> 'pageId', '')::uuid
            and measurement.group_id is not distinct from nullif(measure ->> 'groupId', '')::uuid
            and measurement.version = (measure ->> 'measurementVersion')::integer
            and measurement.archived_at is null
        ) then
        insert into public.commercial_lineage_edges (
          organization_id, project_id, from_entity_type, from_entity_id,
          to_entity_type, to_entity_id, relationship_type,
          evidence_source, evidence_version, evidence_ref, evidence_batch_id,
          contribution_quantity, created_by
        ) values (
          item.organization_id, coalesce(item.project_id, (measure ->> 'projectId')::uuid),
          'commercial_item', item.id, 'takeoff_measurement', (measure ->> 'measurementId')::uuid, 'measured_from',
          'commercial_item_locked_metadata', 'measure_source_v1',
          jsonb_build_object(
            'cellKey', cell ->> 'cellKey', 'bindingId', measure ->> 'bindingId',
            'worksheetVersion', item.locked_metadata_json -> 'worksheetVersion',
            'measurementVersion', measure -> 'measurementVersion',
            'insertedField', measure -> 'insertedField', 'insertedUnit', measure -> 'insertedUnit'
          ), p_evidence_batch_id, (measure ->> 'insertedQuantity')::numeric, item.created_by
        )
        on conflict (organization_id, from_entity_type, from_entity_id, to_entity_type, to_entity_id, relationship_type)
          where superseded_at is null do nothing;
        get diagnostics affected = row_count;
        inserted_count := inserted_count + affected;
      end if;
    end loop;
  end if;

  owner_id := nullif(item.source_link_json ->> 'variationId', '')::uuid;
  if owner_id is not null and exists (
    select 1 from public.project_variations variation
    where variation.id = owner_id and variation.organization_id = item.organization_id
      and (item.project_id is null or variation.project_id = item.project_id)
  ) then
    insert into public.commercial_lineage_edges (
      organization_id, project_id, from_entity_type, from_entity_id, to_entity_type, to_entity_id,
      relationship_type, evidence_source, evidence_version, evidence_ref, evidence_batch_id, created_by
    ) values (
      item.organization_id, item.project_id, 'commercial_item', item.id, 'project_variation', owner_id,
      'scoped_by', 'commercial_item_source_link', 'worksheet_selection_v1',
      jsonb_build_object('sourceRange', item.source_range, 'sourceVersion', item.source_version),
      p_evidence_batch_id, item.created_by
    ) on conflict (organization_id, from_entity_type, from_entity_id, to_entity_type, to_entity_id, relationship_type)
      where superseded_at is null do nothing;
    get diagnostics affected = row_count;
    inserted_count := inserted_count + affected;
  end if;

  owner_id := nullif(item.source_link_json ->> 'quoteId', '')::uuid;
  if owner_id is not null and exists (
    select 1 from public.project_quotes quote
    where quote.id = owner_id and quote.organization_id = item.organization_id
      and (item.project_id is null or quote.project_id = item.project_id)
      and (quote.source_opportunity_id is null or quote.source_opportunity_id = item.opportunity_id)
  ) then
    insert into public.commercial_lineage_edges (
      organization_id, project_id, from_entity_type, from_entity_id, to_entity_type, to_entity_id,
      relationship_type, evidence_source, evidence_version, evidence_ref, evidence_batch_id, created_by
    ) values (
      item.organization_id, item.project_id, 'commercial_item', item.id, 'project_quote', owner_id,
      'scoped_by', 'commercial_item_source_link', 'worksheet_selection_v1',
      jsonb_build_object('sourceRange', item.source_range, 'sourceVersion', item.source_version),
      p_evidence_batch_id, item.created_by
    ) on conflict (organization_id, from_entity_type, from_entity_id, to_entity_type, to_entity_id, relationship_type)
      where superseded_at is null do nothing;
    get diagnostics affected = row_count;
    inserted_count := inserted_count + affected;
  end if;

  return inserted_count;
exception
  when invalid_text_representation or numeric_value_out_of_range then
    return inserted_count;
end;
$$;


ALTER FUNCTION "public"."sync_commercial_item_lineage_internal"("p_commercial_item_id" "uuid", "p_evidence_batch_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_opportunity_legacy_quote_on_conversion"("p_organization_id" "uuid", "p_opportunity_id" "uuid", "p_project_id" "uuid", "p_actor_user_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  latest_legacy_quote_id uuid;
begin
  if auth.uid() is null then
    raise exception 'Authentication is required'
      using errcode = '42501';
  end if;

  if not public.has_org_permission(p_organization_id, 'quotes.write') then
    raise exception 'Not authorized for this organization'
      using errcode = '42501';
  end if;

  -- Canonical history is authoritative. The pre-canonical opportunity quote is
  -- converted only when no canonical Project quote was attached.
  if exists (
    select 1
    from public.project_quotes quote
    where quote.organization_id = p_organization_id
      and quote.project_id = p_project_id
  ) then
    return;
  end if;

  select quote.id
  into latest_legacy_quote_id
  from public.opportunity_quotes quote
  where quote.organization_id = p_organization_id
    and quote.opportunity_id = p_opportunity_id
  order by quote.updated_at desc, quote.id desc
  limit 1;

  if latest_legacy_quote_id is not null then
    perform *
    from public.convert_opportunity_quote_to_project_quote(
      p_organization_id,
      p_opportunity_id,
      latest_legacy_quote_id,
      p_project_id,
      p_actor_user_id
    );
  end if;
end;
$$;


ALTER FUNCTION "public"."sync_opportunity_legacy_quote_on_conversion"("p_organization_id" "uuid", "p_opportunity_id" "uuid", "p_project_id" "uuid", "p_actor_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_opportunity_tender_clients_v1"("p_organization_id" "uuid", "p_opportunity_id" "uuid", "p_client_ids" "uuid"[], "p_primary_client_id" "uuid") RETURNS TABLE("active_count" integer, "archived_count" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  actor_user_id uuid := auth.uid();
  normalized_ids uuid[];
  archived_rows integer := 0;
begin
  if actor_user_id is null
    or not public.has_org_permission(p_organization_id, 'leads.opportunities.write')
  then
    raise exception 'Not authorized for this organization' using errcode = '42501';
  end if;

  select coalesce(array_agg(distinct value), '{}'::uuid[])
  into normalized_ids
  from unnest(coalesce(p_client_ids, '{}'::uuid[])) value
  where value is not null;

  if p_primary_client_id is null
    or not (p_primary_client_id = any(normalized_ids))
    or coalesce(array_length(normalized_ids, 1), 0) = 0
  then
    raise exception 'Tender Clients must include the primary client' using errcode = 'TS422';
  end if;

  perform 1 from public.organization_opportunities opportunity
  where opportunity.organization_id = p_organization_id
    and opportunity.id = p_opportunity_id
  for update;
  if not found then
    raise exception 'Opportunity was not found' using errcode = 'TS422';
  end if;

  if exists (
    select 1 from unnest(normalized_ids) value
    where not exists (
      select 1 from public.organization_clients client
      where client.organization_id = p_organization_id and client.id = value
    )
  ) then
    raise exception 'A Tender Client was not found for this organization' using errcode = 'TS422';
  end if;

  update public.opportunity_tender_clients relationship
  set archived_at = timezone('utc', now()), is_primary = false
  where relationship.organization_id = p_organization_id
    and relationship.opportunity_id = p_opportunity_id
    and relationship.archived_at is null
    and not (relationship.client_id = any(normalized_ids));
  get diagnostics archived_rows = row_count;

  update public.opportunity_tender_clients relationship
  set is_primary = false
  where relationship.organization_id = p_organization_id
    and relationship.opportunity_id = p_opportunity_id
    and relationship.archived_at is null
    and relationship.is_primary;

  insert into public.opportunity_tender_clients (
    organization_id, opportunity_id, client_id, is_primary, created_by
  )
  select p_organization_id, p_opportunity_id, value,
    value = p_primary_client_id, actor_user_id
  from unnest(normalized_ids) value
  on conflict (organization_id, opportunity_id, client_id) where archived_at is null
  do update set is_primary = excluded.is_primary;

  update public.organization_opportunities opportunity
  set client_id = p_primary_client_id
  where opportunity.organization_id = p_organization_id
    and opportunity.id = p_opportunity_id;

  return query select coalesce(array_length(normalized_ids, 1), 0), archived_rows;
end;
$$;


ALTER FUNCTION "public"."sync_opportunity_tender_clients_v1"("p_organization_id" "uuid", "p_opportunity_id" "uuid", "p_client_ids" "uuid"[], "p_primary_client_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_organization_tax_policy_version"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_now timestamptz := statement_timestamp();
  v_country text := upper(coalesce(nullif((to_jsonb(new)->>'country'), ''), 'UNKNOWN'));
  v_rate numeric := coalesce(nullif(to_jsonb(new)->>'default_tax_rate', '')::numeric, 0);
  v_basis text := case when lower(coalesce((to_jsonb(new)->>'default_tax_mode'), '')) like '%incl%' then 'inclusive' else 'exclusive' end;
  v_registration text := case lower(coalesce((to_jsonb(new)->>'tax_registration_status'), '')) when 'registered' then 'registered' when 'unregistered' then 'unregistered' else 'unknown' end;
begin
  if (to_jsonb(new)->>'country') is not distinct from (to_jsonb(old)->>'country')
    and (to_jsonb(new)->>'default_tax_mode') is not distinct from (to_jsonb(old)->>'default_tax_mode')
    and nullif(to_jsonb(new)->>'default_tax_rate', '')::numeric is not distinct from nullif(to_jsonb(old)->>'default_tax_rate', '')::numeric
    and (to_jsonb(new)->>'tax_registration_status') is not distinct from (to_jsonb(old)->>'tax_registration_status') then return new; end if;
  update public.organization_tax_policies set effective_to = v_now
  where organization_id = new.id and effective_to is null;
  insert into public.organization_tax_policies (
    organization_id, jurisdiction_code, tax_name, registration_status,
    comparison_basis, standard_rate, supports_inclusive_exclusive,
    effective_from, policy_source, created_by
  ) values (
    new.id, v_country,
    case when v_country in ('NZ', 'NEW ZEALAND', 'AU', 'AUSTRALIA') then 'GST' else 'Tax' end,
    v_registration, v_basis, v_rate,
    v_country in ('NZ', 'NEW ZEALAND', 'AU', 'AUSTRALIA'),
    v_now, 'organization_settings', auth.uid()
  );
  return new;
end;
$$;


ALTER FUNCTION "public"."sync_organization_tax_policy_version"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_project_claim_line_items"("p_organization_id" "uuid", "p_project_id" "uuid", "p_claim_id" "uuid", "p_input_line_items" "jsonb" DEFAULT NULL::"jsonb", "p_target_claim_amount" numeric DEFAULT NULL::numeric) RETURNS numeric
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  computed_claim_amount numeric := 0;
begin
  if auth.uid() is not null and not public.is_member_of_organization(p_organization_id) then
    raise exception 'Not authorized for this organization';
  end if;

  create temporary table if not exists _claim_line_input (
    source_kind text,
    source_document_id uuid,
    source_line_item_id uuid,
    claim_percent numeric
  ) on commit drop;
  truncate _claim_line_input;

  if p_input_line_items is not null then
    insert into _claim_line_input (source_kind, source_document_id, source_line_item_id, claim_percent)
    select
      case
        when item->>'source_kind' in ('Quote', 'Variation') then item->>'source_kind'
        else 'Quote'
      end,
      (item->>'source_document_id')::uuid,
      (item->>'source_line_item_id')::uuid,
      greatest(0, least(100, coalesce((item->>'claim_percent')::numeric, 0)))
    from jsonb_array_elements(coalesce(p_input_line_items, '[]'::jsonb)) as item
    where nullif(item->>'source_document_id', '') is not null
      and nullif(item->>'source_line_item_id', '') is not null;
  end if;

  create temporary table if not exists _claim_line_prepared (
    source_kind text,
    source_document_id uuid,
    source_line_item_id uuid,
    source_number text,
    source_title text,
    line_uid uuid,
    cost_item_id uuid,
    source_cost_item_id uuid,
    section text,
    description text,
    quantity numeric,
    unit text,
    rate numeric,
    source_total numeric,
    previously_claimed_amount numeric,
    previously_claimed_percent numeric,
    claim_percent numeric,
    claim_amount numeric,
    cumulative_claimed_amount numeric,
    cumulative_claimed_percent numeric,
    sort_order integer
  ) on commit drop;
  truncate _claim_line_prepared;

  insert into _claim_line_prepared (
    source_kind,
    source_document_id,
    source_line_item_id,
    source_number,
    source_title,
    line_uid,
    cost_item_id,
    source_cost_item_id,
    section,
    description,
    quantity,
    unit,
    rate,
    source_total,
    previously_claimed_amount,
    previously_claimed_percent,
    claim_percent,
    claim_amount,
    cumulative_claimed_amount,
    cumulative_claimed_percent,
    sort_order
  )
  with claim_row as (
    select
      c.id,
      c.claim_amount,
      c.claim_date,
      c.created_at
    from public.project_claims c
    where c.id = p_claim_id
      and c.organization_id = p_organization_id
      and c.project_id = p_project_id
    limit 1
  ),
  live_source_lines as (
    select *
    from public.get_project_claim_source_line_items(p_organization_id, p_project_id)
  ),
  existing_claim_snapshot_rows as (
    select
      cli.source_kind,
      cli.source_document_id,
      cli.source_line_item_id,
      cli.source_number,
      cli.source_title,
      cli.line_uid,
      cli.cost_item_id,
      cli.source_cost_item_id,
      cli.section,
      cli.description,
      cli.quantity,
      cli.unit,
      cli.rate,
      cli.source_total,
      cli.previously_claimed_amount,
      cli.previously_claimed_percent,
      cli.claim_percent,
      cli.claim_amount,
      cli.cumulative_claimed_amount,
      cli.cumulative_claimed_percent,
      cli.sort_order
    from public.project_claim_line_items cli
    where cli.organization_id = p_organization_id
      and cli.project_id = p_project_id
      and cli.claim_id = p_claim_id
  ),
  source_lines as (
    select
      ls.source_kind,
      ls.source_document_id,
      ls.source_line_item_id,
      ls.source_number,
      ls.source_title,
      ls.section,
      ls.description,
      ls.quantity,
      ls.unit,
      ls.rate,
      ls.source_total,
      ls.sort_order
    from live_source_lines ls

    union all

    select
      ex.source_kind,
      ex.source_document_id,
      ex.source_line_item_id,
      ex.source_number,
      ex.source_title,
      ex.section,
      ex.description,
      ex.quantity,
      ex.unit,
      ex.rate,
      ex.source_total,
      ex.sort_order
    from existing_claim_snapshot_rows ex
    where not exists (
      select 1
      from live_source_lines ls
      where ls.source_kind = ex.source_kind
        and ls.source_document_id = ex.source_document_id
        and ls.source_line_item_id = ex.source_line_item_id
    )
  ),
  previous_claims as (
    select
      cli.source_kind,
      cli.source_document_id,
      cli.source_line_item_id,
      coalesce(sum(cli.claim_amount), 0) as previous_amount
    from public.project_claim_line_items cli
    join public.project_claims c
      on c.id = cli.claim_id
     and c.organization_id = p_organization_id
     and c.project_id = p_project_id
     and c.id <> p_claim_id
     and c.status <> 'Cancelled'
    cross join claim_row current_claim
    where cli.organization_id = p_organization_id
      and cli.project_id = p_project_id
      and (
        row(
          coalesce(c.claim_date, 'infinity'::date),
          c.created_at,
          c.id
        ) < row(
          coalesce(current_claim.claim_date, 'infinity'::date),
          current_claim.created_at,
          current_claim.id
        )
      )
    group by cli.source_kind, cli.source_document_id, cli.source_line_item_id
  ),
  existing_lines as (
    select *
    from existing_claim_snapshot_rows
  ),
  quote_source_cost_items as (
    select
      ci.source_document_id,
      ci.linked_quote_line_item_id as source_line_item_id,
      ci.id
    from public.cost_items ci
    where ci.organization_id = p_organization_id
      and ci.project_id = p_project_id
      and ci.source_document_kind = 'project_quote'
      and ci.is_current = true
      and ci.linked_quote_line_item_id is not null
  ),
  variation_source_cost_items as (
    select distinct on (ci.source_document_id)
      ci.source_document_id,
      ci.id
    from public.cost_items ci
    where ci.organization_id = p_organization_id
      and ci.project_id = p_project_id
      and ci.source_document_kind = 'project_variation'
      and ci.is_current = true
    order by
      ci.source_document_id,
      ci.sort_order asc,
      ci.effective_from desc,
      ci.created_at desc,
      ci.id asc
  ),
  totals as (
    select
      coalesce(sum(greatest(0, coalesce(s.source_total, 0) - coalesce(pc.previous_amount, 0))), 0) as total_remaining,
      greatest(0, coalesce(p_target_claim_amount, (select claim_amount from claim_row), 0)) as target_claim_amount
    from source_lines s
    left join previous_claims pc
      on pc.source_kind = s.source_kind
     and pc.source_document_id = s.source_document_id
     and pc.source_line_item_id = s.source_line_item_id
  )
  select
    s.source_kind,
    coalesce(ex.source_document_id, s.source_document_id) as source_document_id,
    coalesce(ex.source_line_item_id, s.source_line_item_id) as source_line_item_id,
    coalesce(nullif(ex.source_number, ''), s.source_number, '') as source_number,
    coalesce(nullif(ex.source_title, ''), s.source_title, '') as source_title,
    coalesce(ex.line_uid, gen_random_uuid()) as line_uid,
    ex.cost_item_id,
    coalesce(
      ex.source_cost_item_id,
      ex_source.id,
      case
        when s.source_kind = 'Quote' then qci.id
        when s.source_kind = 'Variation' then vci.id
        else null
      end
    ) as source_cost_item_id,
    coalesce(nullif(ex.section, ''), s.section, 'Item') as section,
    coalesce(nullif(ex.description, ''), s.description, '') as description,
    coalesce(ex.quantity, s.quantity, 0) as quantity,
    coalesce(nullif(ex.unit, ''), s.unit, '') as unit,
    coalesce(ex.rate, s.rate, 0) as rate,
    round(coalesce(ex.source_total, s.source_total, 0), 2) as source_total,
    round(coalesce(pc.previous_amount, 0), 2) as previously_claimed_amount,
    case
      when coalesce(ex.source_total, s.source_total, 0) <= 0 then 0
      else round(
        least(
          100,
          greatest(0, (coalesce(pc.previous_amount, 0) / coalesce(ex.source_total, s.source_total, 0)) * 100)
        ),
        3
      )
    end as previously_claimed_percent,
    greatest(
      0,
      least(
        100,
        coalesce(
          inp.claim_percent,
          ex.claim_percent,
          case
            when t.total_remaining <= 0 then 0
            else (t.target_claim_amount / t.total_remaining) * 100
          end
        )
      )
    ) as claim_percent,
    round(
      greatest(0, coalesce(ex.source_total, s.source_total, 0) - coalesce(pc.previous_amount, 0))
      * (
        greatest(
          0,
          least(
            100,
            coalesce(
              inp.claim_percent,
              ex.claim_percent,
              case
                when t.total_remaining <= 0 then 0
                else (t.target_claim_amount / t.total_remaining) * 100
              end
            )
          )
        ) / 100
      ),
      2
    ) as claim_amount,
    round(
      coalesce(pc.previous_amount, 0)
      + (
        greatest(0, coalesce(ex.source_total, s.source_total, 0) - coalesce(pc.previous_amount, 0))
        * (
          greatest(
            0,
            least(
              100,
              coalesce(
                inp.claim_percent,
                ex.claim_percent,
                case
                  when t.total_remaining <= 0 then 0
                  else (t.target_claim_amount / t.total_remaining) * 100
                end
              )
            )
          ) / 100
        )
      ),
      2
    ) as cumulative_claimed_amount,
    case
      when coalesce(ex.source_total, s.source_total, 0) <= 0 then 0
      else round(
        least(
          100,
          greatest(
            0,
            (
              coalesce(pc.previous_amount, 0)
              + (
                greatest(0, coalesce(ex.source_total, s.source_total, 0) - coalesce(pc.previous_amount, 0))
                * (
                  greatest(
                    0,
                    least(
                      100,
                      coalesce(
                        inp.claim_percent,
                        ex.claim_percent,
                        case
                          when t.total_remaining <= 0 then 0
                          else (t.target_claim_amount / t.total_remaining) * 100
                        end
                      )
                    )
                  ) / 100
                )
              )
            ) / coalesce(ex.source_total, s.source_total, 0) * 100
          )
        ),
        3
      )
    end as cumulative_claimed_percent,
    coalesce(ex.sort_order, s.sort_order, 0) as sort_order
  from source_lines s
  cross join totals t
  left join previous_claims pc
    on pc.source_kind = s.source_kind
   and pc.source_document_id = s.source_document_id
   and pc.source_line_item_id = s.source_line_item_id
  left join _claim_line_input inp
    on inp.source_kind = s.source_kind
   and inp.source_document_id = s.source_document_id
   and inp.source_line_item_id = s.source_line_item_id
  left join existing_lines ex
    on ex.source_kind = s.source_kind
   and ex.source_document_id = s.source_document_id
   and ex.source_line_item_id = s.source_line_item_id
  left join public.cost_items ex_source
    on ex_source.id = ex.source_cost_item_id
   and ex_source.organization_id = p_organization_id
   and ex_source.project_id = p_project_id
   and ex_source.is_current = true
  left join quote_source_cost_items qci
    on s.source_kind = 'Quote'
   and qci.source_document_id = s.source_document_id
   and qci.source_line_item_id = s.source_line_item_id
  left join variation_source_cost_items vci
    on s.source_kind = 'Variation'
   and vci.source_document_id = s.source_document_id;

  update public.project_claim_line_items cli
  set
    source_number = p.source_number,
    source_title = p.source_title,
    line_uid = p.line_uid,
    cost_item_id = p.cost_item_id,
    source_cost_item_id = p.source_cost_item_id,
    section = p.section,
    description = p.description,
    quantity = p.quantity,
    unit = p.unit,
    rate = p.rate,
    source_total = p.source_total,
    previously_claimed_amount = p.previously_claimed_amount,
    previously_claimed_percent = p.previously_claimed_percent,
    claim_percent = p.claim_percent,
    claim_amount = p.claim_amount,
    cumulative_claimed_amount = p.cumulative_claimed_amount,
    cumulative_claimed_percent = p.cumulative_claimed_percent,
    sort_order = p.sort_order
  from _claim_line_prepared p
  where cli.organization_id = p_organization_id
    and cli.project_id = p_project_id
    and cli.claim_id = p_claim_id
    and cli.source_kind = p.source_kind
    and cli.source_document_id = p.source_document_id
    and cli.source_line_item_id = p.source_line_item_id;

  insert into public.project_claim_line_items (
    organization_id,
    project_id,
    claim_id,
    source_kind,
    source_document_id,
    source_line_item_id,
    source_number,
    source_title,
    line_uid,
    cost_item_id,
    source_cost_item_id,
    section,
    description,
    quantity,
    unit,
    rate,
    source_total,
    previously_claimed_amount,
    previously_claimed_percent,
    claim_percent,
    claim_amount,
    cumulative_claimed_amount,
    cumulative_claimed_percent,
    sort_order
  )
  select
    p_organization_id,
    p_project_id,
    p_claim_id,
    p.source_kind,
    p.source_document_id,
    p.source_line_item_id,
    p.source_number,
    p.source_title,
    p.line_uid,
    p.cost_item_id,
    p.source_cost_item_id,
    p.section,
    p.description,
    p.quantity,
    p.unit,
    p.rate,
    p.source_total,
    p.previously_claimed_amount,
    p.previously_claimed_percent,
    p.claim_percent,
    p.claim_amount,
    p.cumulative_claimed_amount,
    p.cumulative_claimed_percent,
    p.sort_order
  from _claim_line_prepared p
  where not exists (
    select 1
    from public.project_claim_line_items cli
    where cli.organization_id = p_organization_id
      and cli.project_id = p_project_id
      and cli.claim_id = p_claim_id
      and cli.source_kind = p.source_kind
      and cli.source_document_id = p.source_document_id
      and cli.source_line_item_id = p.source_line_item_id
  );

  select coalesce(sum(p.claim_amount), 0)
  into computed_claim_amount
  from _claim_line_prepared p;

  return computed_claim_amount;
end;
$$;


ALTER FUNCTION "public"."sync_project_claim_line_items"("p_organization_id" "uuid", "p_project_id" "uuid", "p_claim_id" "uuid", "p_input_line_items" "jsonb", "p_target_claim_amount" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_project_job_todo_completion_fields"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
begin
  if tg_op = 'INSERT' then
    if new.status is null then
      new.status := case when new.is_completed then 'Done' else 'To Do' end;
    end if;
  end if;

  if tg_op = 'UPDATE' and new.status = old.status and new.is_completed is distinct from old.is_completed then
    if new.is_completed then
      new.status := 'Done';
    elsif old.status in ('Done', 'Archived', 'Complete') then
      new.status := 'To Do';
    end if;
  end if;

  new.is_completed := new.status in ('Done', 'Archived', 'Complete');

  if new.is_completed then
    new.completed_at := coalesce(new.completed_at, now());
  else
    new.completed_at := null;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."sync_project_job_todo_completion_fields"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_project_quality_issue_closed_at"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
begin
  if new.status in ('Complete', 'Verified') then
    if tg_op = 'INSERT' or old.status is distinct from new.status or new.closed_at is null then
      new.closed_at := coalesce(new.closed_at, now());
    end if;
  elsif tg_op <> 'INSERT' and new.status is distinct from old.status then
    new.closed_at := null;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."sync_project_quality_issue_closed_at"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_project_quality_signoff_approval_fields"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
begin
  if new.status = 'Signed' then
    new.approved_at := coalesce(new.approved_at, new.signed_at, now());
    new.approved_by_user_id := coalesce(new.approved_by_user_id, new.signed_by_user_id);
  elsif tg_op <> 'INSERT' and new.status is distinct from old.status then
    new.approved_at := null;
    new.approved_by_user_id := null;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."sync_project_quality_signoff_approval_fields"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_project_quality_work_proof_completed_at"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
begin
  if new.status in ('completed', 'linked_to_signoff') then
    new.completed_at := coalesce(new.completed_at, now());
  elsif tg_op <> 'INSERT' and new.status is distinct from old.status then
    new.completed_at := null;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."sync_project_quality_work_proof_completed_at"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_project_todo_from_inspection_item"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  inspection_title text;
  inspection_scheduled_at timestamptz;
  inspection_opportunity_id uuid;
  is_failed boolean;
begin
  select i.title, i.scheduled_at, p.source_opportunity_id
  into inspection_title, inspection_scheduled_at, inspection_opportunity_id
  from public.project_quality_inspections i
  join public.organization_projects p on p.id = i.project_id
  where i.id = new.inspection_id;

  is_failed := new.status = 'fail';

  insert into public.project_job_todos (
    organization_id,
    project_id,
    opportunity_id,
    created_by,
    title,
    description,
    due_date,
    is_completed,
    completed_at,
    status,
    source_type,
    source_id,
    linked_inspection_item_id
  )
  values (
    new.organization_id,
    new.project_id,
    inspection_opportunity_id,
    new.created_by,
    concat(coalesce(inspection_title, 'Inspection'), ' - ', new.label),
    'Auto-linked from failed inspection checklist item.',
    inspection_scheduled_at::date,
    not is_failed,
    case when is_failed then null else now() end,
    case when is_failed then 'To Do' else 'Done' end,
    'quality_inspection_item',
    new.id,
    new.id
  )
  on conflict (project_id, source_type, source_id) where source_type is not null and source_id is not null
  do update set
    title = excluded.title,
    description = excluded.description,
    due_date = excluded.due_date,
    linked_inspection_item_id = excluded.linked_inspection_item_id,
    is_completed = excluded.is_completed,
    completed_at = case
      when excluded.is_completed then coalesce(project_job_todos.completed_at, now())
      else null
    end,
    status = excluded.status,
    updated_at = now();

  return new;
end;
$$;


ALTER FUNCTION "public"."sync_project_todo_from_inspection_item"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_project_todo_from_quality_issue"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  is_closed boolean;
begin
  is_closed := new.status in ('Complete', 'Verified');

  insert into public.project_job_todos (
    organization_id,
    project_id,
    opportunity_id,
    created_by,
    title,
    description,
    due_date,
    is_completed,
    completed_at,
    status,
    source_type,
    source_id,
    linked_issue_id
  )
  values (
    new.organization_id,
    new.project_id,
    (
      select o.id
      from public.organization_opportunities o
      where o.workspace_project_id = new.project_id
        and o.organization_id = new.organization_id
      limit 1
    ),
    new.created_by,
    new.title,
    format('Auto-linked from Quality Assurance issue (%s - %s).', nullif(new.trade, ''), nullif(new.location, '')),
    new.due_date,
    is_closed,
    case when is_closed then coalesce(now(), now()) else null end,
    case when is_closed then 'Done' else 'To Do' end,
    'quality_issue',
    new.id,
    new.id
  )
  on conflict (project_id, source_type, source_id) where source_type is not null and source_id is not null
  do update set
    title = excluded.title,
    description = excluded.description,
    due_date = excluded.due_date,
    linked_issue_id = excluded.linked_issue_id,
    is_completed = excluded.is_completed,
    completed_at = case
      when excluded.is_completed then coalesce(project_job_todos.completed_at, now())
      else null
    end,
    status = excluded.status,
    updated_at = now();

  return new;
end;
$$;


ALTER FUNCTION "public"."sync_project_todo_from_quality_issue"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_purchase_order_line_cost_item"("p_purchase_order_line_item_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  line_row record;
  resolved_cost_item_id uuid;
  resolved_parent_cost_item_id uuid;
  resolved_fingerprint text;
  resolved_routing record;
begin
  select
    po.organization_id,
    po.project_id,
    po.id as purchase_order_id,
    po.purchase_order_number,
    po.purchase_order_title,
    po.supplier_id,
    po.issued_to_label,
    li.id as line_item_id,
    li.line_uid,
    li.cost_item_id,
    li.source_cost_item_id,
    li.section,
    li.description,
    li.quantity,
    li.unit,
    li.rate as unit_rate,
    coalesce(li.total, round(li.quantity * li.rate, 2)) as line_total,
    li.sort_order,
    li.source_time_sheet_entry_id
  into line_row
  from public.project_purchase_order_line_items li
  join public.project_purchase_orders po
    on po.id = li.purchase_order_id
   and po.organization_id = li.organization_id
   and po.project_id = li.project_id
  where li.id = p_purchase_order_line_item_id;

  if not found then
    return null;
  end if;

  select *
  into resolved_routing
  from public.resolve_cost_item_financial_routing_defaults(
    line_row.organization_id,
    line_row.project_id,
    'project_purchase_order',
    'project_purchase_order_line_items',
    case when line_row.source_time_sheet_entry_id is not null then 'time_sheet_sync' else 'manual' end,
    'line_item',
    line_row.section,
    line_row.section,
    line_row.description,
    line_row.description,
    line_row.line_total
  );

  resolved_fingerprint := public.compute_cost_item_source_fingerprint(
    'project_purchase_order',
    'project_purchase_order_line_items',
    line_row.section,
    line_row.description,
    line_row.quantity,
    line_row.unit,
    line_row.unit_rate,
    line_row.line_total,
    false,
    line_row.sort_order,
    coalesce(line_row.source_time_sheet_entry_id::text, ''),
    coalesce(line_row.line_uid::text, '')
  );

  resolved_parent_cost_item_id := null;

  if line_row.source_time_sheet_entry_id is not null then
    select ci.id
    into resolved_parent_cost_item_id
    from public.cost_items ci
    where ci.organization_id = line_row.organization_id
      and ci.project_id = line_row.project_id
      and ci.is_current = true
      and ci.source_document_kind <> 'project_purchase_order'
      and ci.source_snapshot ->> 'source_time_sheet_entry_id' = line_row.source_time_sheet_entry_id::text
    order by ci.effective_from desc, ci.created_at desc
    limit 1;
  end if;

  if resolved_parent_cost_item_id is null and line_row.source_cost_item_id is not null then
    select ci.id
    into resolved_parent_cost_item_id
    from public.cost_items ci
    where ci.id = line_row.source_cost_item_id
      and ci.organization_id = line_row.organization_id
      and ci.project_id = line_row.project_id
      and ci.is_current = true
    limit 1;
  end if;

  resolved_cost_item_id := line_row.cost_item_id;

  if resolved_cost_item_id is not null then
    update public.cost_items
    set
      organization_id = line_row.organization_id,
      project_id = line_row.project_id,
      source_document_kind = 'project_purchase_order',
      source_document_id = line_row.purchase_order_id,
      source_line_table = 'project_purchase_order_line_items',
      source_line_id = line_row.line_item_id,
      parent_cost_item_id = resolved_parent_cost_item_id,
      origin_kind = case
        when line_row.source_time_sheet_entry_id is not null then 'time_sheet_sync'
        else 'manual'
      end,
      source_snapshot = jsonb_build_object(
        'document_kind', 'project_purchase_order',
        'document_number', line_row.purchase_order_number,
        'document_title', line_row.purchase_order_title,
        'line_item_id', line_row.line_item_id,
        'line_uid', line_row.line_uid,
        'supplier_id', line_row.supplier_id,
        'issued_to_label', line_row.issued_to_label,
        'source_cost_item_id', line_row.source_cost_item_id,
        'source_time_sheet_entry_id', line_row.source_time_sheet_entry_id
      ),
      supplier_id = line_row.supplier_id,
      supplier_name_snapshot = line_row.issued_to_label,
      tradesstack_cost_code = resolved_routing.tradesstack_cost_code,
      tradesstack_cost_code_label = resolved_routing.tradesstack_cost_code_label,
      financial_routing_confidence = resolved_routing.financial_routing_confidence,
      financial_routing_source = resolved_routing.financial_routing_source,
      accounting_mapping_id = resolved_routing.accounting_mapping_id,
      review_status = resolved_routing.review_status,
      review_reason = resolved_routing.review_reason,
      ai_construction_intelligence = coalesce(ai_construction_intelligence, '{}'::jsonb),
      title = coalesce(nullif(btrim(line_row.description), ''), 'Untitled line item'),
      description = coalesce(line_row.description, ''),
      quantity = line_row.quantity,
      unit = line_row.unit,
      unit_rate = line_row.unit_rate,
      line_total = line_row.line_total,
      sort_order = line_row.sort_order,
      source_fingerprint = resolved_fingerprint,
      linked_purchase_order_line_item_id = line_row.line_item_id,
      status = 'active',
      effective_to = null,
      is_current = true
    where id = resolved_cost_item_id;

    if found then
      update public.project_purchase_order_line_items
      set cost_item_id = resolved_cost_item_id
      where id = line_row.line_item_id
        and cost_item_id is distinct from resolved_cost_item_id;

      return resolved_cost_item_id;
    end if;
  end if;

  insert into public.cost_items (
    organization_id,
    project_id,
    source_document_kind,
    source_document_id,
    source_line_table,
    source_line_id,
    parent_cost_item_id,
    origin_kind,
    source_snapshot,
    item_code,
    item_type,
    section,
    category,
    trade_id,
    trade_label,
    supplier_id,
    supplier_name_snapshot,
    tradesstack_cost_code,
    tradesstack_cost_code_label,
    financial_routing_confidence,
    financial_routing_source,
    accounting_mapping_id,
    review_status,
    review_reason,
    ai_construction_intelligence,
    title,
    description,
    quantity,
    unit,
    unit_rate,
    line_total,
    is_optional,
    sort_order,
    status,
    effective_from,
    effective_to,
    is_current,
    source_revision_key,
    source_fingerprint,
    linked_quote_line_item_id,
    linked_variation_line_item_id,
    linked_purchase_order_line_item_id,
    linked_claim_line_item_id,
    created_by
  )
  values (
    line_row.organization_id,
    line_row.project_id,
    'project_purchase_order',
    line_row.purchase_order_id,
    'project_purchase_order_line_items',
    line_row.line_item_id,
    resolved_parent_cost_item_id,
    case
      when line_row.source_time_sheet_entry_id is not null then 'time_sheet_sync'
      else 'manual'
    end,
    jsonb_build_object(
      'document_kind', 'project_purchase_order',
      'document_number', line_row.purchase_order_number,
      'document_title', line_row.purchase_order_title,
      'line_item_id', line_row.line_item_id,
      'line_uid', line_row.line_uid,
      'supplier_id', line_row.supplier_id,
      'issued_to_label', line_row.issued_to_label,
      'source_cost_item_id', line_row.source_cost_item_id,
      'source_time_sheet_entry_id', line_row.source_time_sheet_entry_id
    ),
    '',
    'line_item',
    line_row.section,
    line_row.section,
    null,
    null,
    line_row.supplier_id,
    line_row.issued_to_label,
    resolved_routing.tradesstack_cost_code,
    resolved_routing.tradesstack_cost_code_label,
    resolved_routing.financial_routing_confidence,
    resolved_routing.financial_routing_source,
    resolved_routing.accounting_mapping_id,
    resolved_routing.review_status,
    resolved_routing.review_reason,
    '{}'::jsonb,
    coalesce(nullif(btrim(line_row.description), ''), 'Untitled line item'),
    coalesce(line_row.description, ''),
    line_row.quantity,
    line_row.unit,
    line_row.unit_rate,
    line_row.line_total,
    false,
    line_row.sort_order,
    'active',
    clock_timestamp(),
    null,
    true,
    'line-sync',
    resolved_fingerprint,
    null,
    null,
    line_row.line_item_id,
    null,
    auth.uid()
  )
  returning id into resolved_cost_item_id;

  update public.project_purchase_order_line_items
  set cost_item_id = resolved_cost_item_id
  where id = line_row.line_item_id
    and cost_item_id is distinct from resolved_cost_item_id;

  return resolved_cost_item_id;
end;
$$;


ALTER FUNCTION "public"."sync_purchase_order_line_cost_item"("p_purchase_order_line_item_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_purchase_order_line_from_time_sheet_entry"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  previous_purchase_order_id uuid;
  next_purchase_order_id uuid;
  preserved_rate numeric := 0;
  preserved_sort_order integer;
  preserved_line_uid uuid;
  preserved_cost_item_id uuid;
  preserved_source_cost_item_id uuid;
  deleted_cost_item_id uuid;
  computed_hours numeric := 0;
  line_description text;
  synced_line_id uuid;
begin
  if tg_op = 'DELETE' then
    previous_purchase_order_id := old.purchase_order_id;

    delete from public.project_purchase_order_line_items
    where source_time_sheet_entry_id = old.id
    returning cost_item_id into deleted_cost_item_id;

    perform public.retire_purchase_order_line_cost_item(deleted_cost_item_id);

    if previous_purchase_order_id is not null then
      perform public.recalculate_project_purchase_order_totals(previous_purchase_order_id);
    end if;

    return old;
  end if;

  previous_purchase_order_id := case when tg_op = 'UPDATE' then old.purchase_order_id else null end;
  next_purchase_order_id := new.purchase_order_id;

  select li.rate, li.sort_order, li.line_uid, li.cost_item_id, li.source_cost_item_id
  into preserved_rate, preserved_sort_order, preserved_line_uid, preserved_cost_item_id, preserved_source_cost_item_id
  from public.project_purchase_order_line_items li
  where li.source_time_sheet_entry_id = new.id
  limit 1;

  if previous_purchase_order_id is not null and previous_purchase_order_id is distinct from next_purchase_order_id then
    delete from public.project_purchase_order_line_items
    where source_time_sheet_entry_id = new.id
    returning cost_item_id into deleted_cost_item_id;

    perform public.recalculate_project_purchase_order_totals(previous_purchase_order_id);

    if next_purchase_order_id is null then
      perform public.retire_purchase_order_line_cost_item(deleted_cost_item_id);
    end if;
  end if;

  if next_purchase_order_id is null then
    return new;
  end if;

  computed_hours := greatest(0, coalesce(new.total_hours, 0));
  line_description := public.build_time_sheet_entry_labour_line_description(
    new.organization_id,
    new.worker_name,
    new.clock_in_at
  );

  insert into public.project_purchase_order_line_items (
    organization_id,
    project_id,
    purchase_order_id,
    line_uid,
    cost_item_id,
    source_cost_item_id,
    section,
    description,
    quantity,
    unit,
    rate,
    total,
    sort_order,
    source_time_sheet_entry_id
  )
  values (
    new.organization_id,
    new.project_id,
    next_purchase_order_id,
    coalesce(
      preserved_line_uid,
      (
        select li.line_uid
        from public.project_purchase_order_line_items li
        where li.source_time_sheet_entry_id = new.id
        limit 1
      ),
      gen_random_uuid()
    ),
    coalesce(
      preserved_cost_item_id,
      (
        select li.cost_item_id
        from public.project_purchase_order_line_items li
        where li.source_time_sheet_entry_id = new.id
        limit 1
      )
    ),
    coalesce(
      preserved_source_cost_item_id,
      (
        select li.source_cost_item_id
        from public.project_purchase_order_line_items li
        where li.source_time_sheet_entry_id = new.id
        limit 1
      )
    ),
    'Labour',
    line_description,
    computed_hours,
    'hrs',
    coalesce(preserved_rate, 0),
    round(computed_hours * coalesce(preserved_rate, 0), 2),
    coalesce(
      preserved_sort_order,
      (
        select coalesce(max(li.sort_order), -1) + 1
        from public.project_purchase_order_line_items li
        where li.purchase_order_id = next_purchase_order_id
      )
    ),
    new.id
  )
  on conflict (source_time_sheet_entry_id) do update
  set
    organization_id = excluded.organization_id,
    project_id = excluded.project_id,
    purchase_order_id = excluded.purchase_order_id,
    line_uid = coalesce(public.project_purchase_order_line_items.line_uid, excluded.line_uid),
    cost_item_id = coalesce(public.project_purchase_order_line_items.cost_item_id, excluded.cost_item_id),
    source_cost_item_id = coalesce(public.project_purchase_order_line_items.source_cost_item_id, excluded.source_cost_item_id),
    section = 'Labour',
    description = excluded.description,
    quantity = excluded.quantity,
    unit = 'hrs',
    total = round(excluded.quantity * public.project_purchase_order_line_items.rate, 2)
  returning id into synced_line_id;

  perform public.sync_purchase_order_line_cost_item(synced_line_id);
  perform public.recalculate_project_purchase_order_totals(next_purchase_order_id);

  return new;
end;
$$;


ALTER FUNCTION "public"."sync_purchase_order_line_from_time_sheet_entry"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_quote_line_pricing_source_kind"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  target_link public.commercial_item_document_links%rowtype;
  resolved_kind text;
begin
  target_link := case when tg_op = 'DELETE' then old else new end;
  if target_link.document_kind <> 'quote_line' or target_link.link_role <> 'source' then
    return case when tg_op = 'DELETE' then old else new end;
  end if;
  if exists (
    select 1 from public.project_quotes quote
    where quote.organization_id = target_link.organization_id
      and quote.id = target_link.document_id
      and quote.award_locked_at is not null
  ) then
    raise exception 'Source links belonging to an award-locked quote are immutable' using errcode = 'TS409';
  end if;

  if tg_op = 'DELETE' then
    select case item.source_type when 'takeoff_measurement' then 'takeoff' else 'worksheet' end
      into resolved_kind
    from public.commercial_item_document_links link
    join public.commercial_items item on item.id = link.commercial_item_id and item.organization_id = link.organization_id
    where link.organization_id = target_link.organization_id
      and link.document_kind = 'quote_line'
      and link.document_id = target_link.document_id
      and link.document_line_id = target_link.document_line_id
      and link.link_role = 'source'
      and link.id <> target_link.id
    limit 1;
    resolved_kind := coalesce(resolved_kind, 'manual');
  else
    select case item.source_type when 'takeoff_measurement' then 'takeoff' else 'worksheet' end
      into resolved_kind
    from public.commercial_items item
    where item.organization_id = target_link.organization_id
      and item.id = target_link.commercial_item_id;
  end if;

  update public.project_quote_line_items line
  set pricing_source_kind = resolved_kind
  where line.organization_id = target_link.organization_id
    and line.quote_id = target_link.document_id
    and line.id = target_link.document_line_id;
  return case when tg_op = 'DELETE' then old else new end;
end;
$$;


ALTER FUNCTION "public"."sync_quote_line_pricing_source_kind"() OWNER TO "postgres";


