CREATE OR REPLACE FUNCTION "public"."track_document_node_storage_usage"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  old_visible boolean := false;
  new_visible boolean := false;
  old_current boolean := false;
  new_current boolean := false;
  retained_bytes bigint := 0;
  active_delta bigint := 0;
  deleted_delta bigint := 0;
  organization_id uuid := coalesce(new.organization_id, old.organization_id);
begin
  if tg_op <> 'INSERT' then
    old_visible := old.deleted_at is null
      and old.lifecycle_state = 'active';
    old_current := old_visible
      and old.kind = 'file'
      and old.current_version_id is not null;
  end if;

  if tg_op <> 'DELETE' then
    new_visible := new.deleted_at is null
      and new.lifecycle_state = 'active';
    new_current := new_visible
      and new.kind = 'file'
      and new.current_version_id is not null;
  end if;

  if tg_op = 'UPDATE'
    and old.kind = 'file'
    and old.deleted_at is distinct from new.deleted_at
  then
    select coalesce(sum(version.byte_size), 0)
    into retained_bytes
    from public.document_versions version
    where version.node_id = new.id
      and version.upload_state in ('active', 'purge_pending');

    if old.deleted_at is null and new.deleted_at is not null then
      active_delta := -retained_bytes;
      deleted_delta := retained_bytes;
    elsif old.deleted_at is not null and new.deleted_at is null then
      active_delta := retained_bytes;
      deleted_delta := -retained_bytes;
    end if;
  end if;

  perform public.adjust_document_storage_usage(
    organization_id,
    active_delta,
    deleted_delta,
    0,
    (case when new_visible and coalesce(new.kind, '') = 'file' then 1 else 0 end)
      - (case when old_visible and coalesce(old.kind, '') = 'file' then 1 else 0 end),
    (case when new_visible and coalesce(new.kind, '') = 'folder' then 1 else 0 end)
      - (case when old_visible and coalesce(old.kind, '') = 'folder' then 1 else 0 end),
    (case when new_current then 1 else 0 end)
      - (case when old_current then 1 else 0 end),
    0
  );

  return coalesce(new, old);
end;
$$;


ALTER FUNCTION "public"."track_document_node_storage_usage"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."track_document_purge_job_storage_usage"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  old_bytes bigint := 0;
  new_bytes bigint := 0;
  organization_id uuid := coalesce(new.organization_id, old.organization_id);
begin
  if tg_op <> 'INSERT'
    and old.job_type = 'version_purge'
    and old.processing_status <> 'completed'
  then
    old_bytes := old.byte_size;
  end if;

  if tg_op <> 'DELETE'
    and new.job_type = 'version_purge'
    and new.processing_status <> 'completed'
  then
    new_bytes := new.byte_size;
  end if;

  if new_bytes <> old_bytes then
    perform public.adjust_document_storage_usage(
      organization_id,
      0,
      new_bytes - old_bytes
    );
  end if;

  return coalesce(new, old);
end;
$$;


ALTER FUNCTION "public"."track_document_purge_job_storage_usage"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."track_document_version_storage_usage"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  old_deleted_at timestamptz;
  new_deleted_at timestamptz;
  old_usage record;
  new_usage record;
  organization_id uuid := coalesce(new.organization_id, old.organization_id);
begin
  if tg_op <> 'INSERT' then
    select node.deleted_at
    into old_deleted_at
    from public.document_nodes node
    where node.id = old.node_id;

    select *
    into old_usage
    from public.document_version_usage_bucket(
      old.upload_state,
      old.byte_size,
      old_deleted_at
    );
  else
    select 0::bigint as active_bytes, 0::bigint as deleted_bytes,
      0::bigint as pending_bytes
    into old_usage;
  end if;

  if tg_op <> 'DELETE' then
    select node.deleted_at
    into new_deleted_at
    from public.document_nodes node
    where node.id = new.node_id;

    select *
    into new_usage
    from public.document_version_usage_bucket(
      new.upload_state,
      new.byte_size,
      new_deleted_at
    );
  else
    select 0::bigint as active_bytes, 0::bigint as deleted_bytes,
      0::bigint as pending_bytes
    into new_usage;
  end if;

  perform public.adjust_document_storage_usage(
    organization_id,
    new_usage.active_bytes - old_usage.active_bytes,
    new_usage.deleted_bytes - old_usage.deleted_bytes,
    new_usage.pending_bytes - old_usage.pending_bytes,
    0,
    0,
    0,
    case when tg_op = 'INSERT' then 1 when tg_op = 'DELETE' then -1 else 0 end
  );

  return coalesce(new, old);
end;
$$;


ALTER FUNCTION "public"."track_document_version_storage_usage"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."transition_accounting_attachment_phase2a"("p_attachment_id" "uuid", "p_target_state" "text", "p_provider_attachment_id" "text" DEFAULT NULL::"text", "p_failure_code" "text" DEFAULT NULL::"text", "p_failure_message" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare attachment public.organization_accounting_revision_attachments%rowtype;
begin
  select * into attachment
  from public.organization_accounting_revision_attachments
  where id = p_attachment_id for update;
  if not found then raise exception 'Accounting attachment not found.'; end if;
  if not (
    (attachment.upload_state = 'pending' and p_target_state = 'uploading')
    or (attachment.upload_state = 'uploading' and p_target_state in ('uploaded', 'failed'))
    or (attachment.upload_state = 'failed' and p_target_state = 'uploading')
  ) then
    raise exception 'Invalid controlled accounting attachment transition.';
  end if;

  perform set_config('app.accounting_phase2a_attachment_write', 'true', true);
  update public.organization_accounting_revision_attachments set
    upload_state = p_target_state,
    provider_attachment_id = case when p_target_state = 'uploaded'
      then p_provider_attachment_id else null end,
    uploaded_at = case when p_target_state = 'uploaded' then now() else null end,
    failure_code = case when p_target_state = 'failed' then p_failure_code else null end,
    failure_message = case when p_target_state = 'failed' then p_failure_message else null end,
    updated_at = now()
  where id = attachment.id;
  perform set_config('app.accounting_phase2a_attachment_write', '', true);
  return true;
end;
$$;


ALTER FUNCTION "public"."transition_accounting_attachment_phase2a"("p_attachment_id" "uuid", "p_target_state" "text", "p_provider_attachment_id" "text", "p_failure_code" "text", "p_failure_message" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."transition_accounting_revision_lifecycle_phase2a"("p_revision_id" "uuid", "p_target_state" "text", "p_failure_code" "text" DEFAULT NULL::"text", "p_failure_message" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare revision public.organization_accounting_document_revisions%rowtype;
begin
  select * into revision
  from public.organization_accounting_document_revisions
  where id = p_revision_id for update;
  if not found then raise exception 'Accounting revision not found.'; end if;
  if not (
    (revision.lifecycle_state = 'confirmed' and p_target_state = 'queued')
    or (revision.lifecycle_state = 'queued' and p_target_state in ('processing', 'failed'))
    or (revision.lifecycle_state = 'processing'
      and p_target_state in ('failed', 'attention_required'))
    or (revision.lifecycle_state in ('failed', 'attention_required')
      and p_target_state = 'queued')
  ) then
    raise exception 'Invalid controlled accounting revision lifecycle transition.';
  end if;
  if p_target_state in ('failed', 'attention_required')
    and nullif(trim(p_failure_code), '') is null then
    raise exception 'Failed accounting lifecycle evidence requires a failure code.';
  end if;

  perform set_config('app.accounting_phase2a_lifecycle_write', 'true', true);
  update public.organization_accounting_document_revisions set
    lifecycle_state = p_target_state,
    failure_code = case when p_target_state in ('failed', 'attention_required')
      then p_failure_code else null end,
    failure_message = case when p_target_state in ('failed', 'attention_required')
      then p_failure_message else null end,
    updated_at = now()
  where id = revision.id;
  perform set_config('app.accounting_phase2a_lifecycle_write', '', true);

  insert into public.organization_accounting_events(
    organization_id, accounting_document_id, accounting_revision_id,
    event_type, event_evidence
  ) values (
    revision.organization_id, revision.accounting_document_id, revision.id,
    'revision_lifecycle_transitioned',
    jsonb_build_object(
      'previousState', revision.lifecycle_state,
      'newState', p_target_state,
      'failureCode', p_failure_code
    )
  );
  return true;
end;
$$;


ALTER FUNCTION "public"."transition_accounting_revision_lifecycle_phase2a"("p_revision_id" "uuid", "p_target_state" "text", "p_failure_code" "text", "p_failure_message" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."transition_ai_interaction_lifecycle"("p_input" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  member_row public.organization_members%rowtype;
  resolved_organization_id uuid;
  resolved_interaction_id uuid;
  resolved_project_id uuid;
  resolved_opportunity_id uuid;
  resolved_lifecycle_state text;
  resolved_run_status text;
  resolved_human_disposition text;
  resolved_validation_status text;
  resolved_superseded_by_interaction_id uuid;
begin
  if p_input is null or jsonb_typeof(p_input) <> 'object' then
    raise exception 'transition_ai_interaction_lifecycle requires a JSON object payload';
  end if;

  resolved_organization_id := nullif(p_input->>'organizationId', '')::uuid;
  resolved_interaction_id := nullif(p_input->>'aiInteractionId', '')::uuid;
  resolved_project_id := nullif(p_input->>'projectId', '')::uuid;
  resolved_opportunity_id := nullif(p_input->>'opportunityId', '')::uuid;
  resolved_lifecycle_state := nullif(btrim(coalesce(p_input->>'lifecycleState', '')), '');
  resolved_run_status := nullif(btrim(coalesce(p_input->>'runStatus', '')), '');
  resolved_human_disposition := nullif(btrim(coalesce(p_input->>'humanDisposition', '')), '');
  resolved_validation_status := nullif(btrim(coalesce(p_input->>'validationStatus', '')), '');
  resolved_superseded_by_interaction_id := nullif(p_input->>'supersededByInteractionId', '')::uuid;

  if resolved_organization_id is null then
    raise exception 'organizationId is required';
  end if;

  if resolved_interaction_id is null then
    raise exception 'aiInteractionId is required';
  end if;

  if resolved_lifecycle_state is null then
    raise exception 'lifecycleState is required';
  end if;

  member_row := public._intelligence_assert_organization_member(resolved_organization_id);

  perform public._intelligence_assert_project_in_organization(resolved_organization_id, resolved_project_id);
  perform public._intelligence_assert_opportunity_in_organization(resolved_organization_id, resolved_opportunity_id);
  perform public._intelligence_assert_ai_interaction_in_organization(resolved_organization_id, resolved_interaction_id);
  perform public._intelligence_assert_ai_interaction_in_organization(
    resolved_organization_id,
    resolved_superseded_by_interaction_id
  );

  update public.ai_interactions
  set
    project_id = coalesce(resolved_project_id, project_id),
    opportunity_id = coalesce(resolved_opportunity_id, opportunity_id),
    run_status = coalesce(resolved_run_status, run_status),
    lifecycle_state = resolved_lifecycle_state,
    validation_status = coalesce(resolved_validation_status, validation_status),
    output_text = coalesce(nullif(p_input->>'outputText', ''), output_text),
    output_structured = case
      when p_input ? 'outputStructured' then p_input->'outputStructured'
      else output_structured
    end,
    output_refs = case
      when p_input ? 'outputRefs' then coalesce(p_input->'outputRefs', '[]'::jsonb)
      else output_refs
    end,
    confidence = coalesce(nullif(p_input->>'confidence', '')::numeric, confidence),
    latency_ms = coalesce(nullif(p_input->>'latencyMs', '')::integer, latency_ms),
    usage_input_tokens = coalesce(nullif(p_input->>'usageInputTokens', '')::integer, usage_input_tokens),
    usage_output_tokens = coalesce(nullif(p_input->>'usageOutputTokens', '')::integer, usage_output_tokens),
    usage_total_tokens = coalesce(nullif(p_input->>'usageTotalTokens', '')::integer, usage_total_tokens),
    human_disposition = coalesce(resolved_human_disposition, human_disposition),
    human_feedback_summary = coalesce(nullif(p_input->>'humanFeedbackSummary', ''), human_feedback_summary),
    edited_output = case
      when p_input ? 'editedOutput' then p_input->'editedOutput'
      else edited_output
    end,
    finalized_by_user_id = case
      when resolved_lifecycle_state in ('accepted', 'edited', 'rejected', 'superseded') then auth.uid()
      else finalized_by_user_id
    end,
    finalized_at = case
      when resolved_lifecycle_state in ('accepted', 'edited', 'rejected', 'superseded') then now()
      else finalized_at
    end,
    superseded_by_interaction_id = coalesce(resolved_superseded_by_interaction_id, superseded_by_interaction_id),
    updated_at = now()
  where id = resolved_interaction_id
    and organization_id = resolved_organization_id;

  if not found then
    raise exception 'AI interaction not found';
  end if;

  return resolved_interaction_id;
end;
$$;


ALTER FUNCTION "public"."transition_ai_interaction_lifecycle"("p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."transition_project_retention_workflow_mode"("p_project_id" "uuid", "p_new_mode" "text", "p_reason" "text", "p_correlation_id" "text" DEFAULT NULL::"text") RETURNS TABLE("succeeded" boolean, "error_code" "text", "changed" boolean, "organization_id" "uuid", "project_id" "uuid", "previous_mode" "text", "mode" "text", "changed_by" "uuid", "changed_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_actor_user_id uuid := auth.uid();
  v_organization_id uuid;
  v_state public.project_retention_workflow_states%rowtype;
  v_previous_mode text;
  v_reason text := nullif(trim(coalesce(p_reason, '')), '');
  v_capability_enabled boolean := false;
  v_error_code text;
begin
  if v_actor_user_id is null then
    return query
    select false, 'unauthenticated'::text, false, null::uuid, p_project_id,
      null::text, null::text, null::uuid, null::timestamptz, null::timestamptz;
    return;
  end if;

  select project.organization_id
  into v_organization_id
  from public.organization_projects project
  join public.organization_members member
    on member.organization_id = project.organization_id
   and member.user_id = v_actor_user_id
  where project.id = p_project_id;

  if v_organization_id is null then
    return query
    select false, 'project_not_found'::text, false, null::uuid, p_project_id,
      null::text, null::text, null::uuid, null::timestamptz, null::timestamptz;
    return;
  end if;

  insert into public.project_retention_workflow_states (organization_id, project_id, mode)
  values (v_organization_id, p_project_id, 'legacy')
  on conflict on constraint project_retention_workflow_states_pkey do nothing;

  select *
  into v_state
  from public.project_retention_workflow_states state
  where state.organization_id = v_organization_id
    and state.project_id = p_project_id
  for update;

  v_previous_mode := v_state.mode;

  if not public.has_org_permission(v_organization_id, 'retention.cutover.manage') then
    perform public.record_retention_capability_event(
      v_organization_id,
      p_project_id,
      'management_permission_denied',
      v_previous_mode,
      p_new_mode,
      v_actor_user_id,
      coalesce(v_reason, 'Permission denied while managing project Retention mode.'),
      p_correlation_id,
      jsonb_build_object('action', 'transition_project_retention_workflow_mode')
    );

    return query
    select false, 'permission_denied'::text, false,
      v_state.organization_id, v_state.project_id, v_previous_mode, v_state.mode,
      v_state.changed_by, v_state.changed_at, v_state.updated_at;
    return;
  end if;

  if v_reason is null then
    v_error_code := 'reason_required';
  elsif p_new_mode is null
    or p_new_mode not in ('legacy', 'observe', 'ready', 'cutover', 'blocked') then
    v_error_code := 'invalid_mode';
  elsif p_new_mode = v_previous_mode then
    return query
    select true, null::text, false,
      v_state.organization_id, v_state.project_id, v_previous_mode, v_state.mode,
      v_state.changed_by, v_state.changed_at, v_state.updated_at;
    return;
  elsif p_new_mode in ('ready', 'cutover') then
    v_error_code := 'reserved_until_readiness';
  else
    select capability.enabled
    into v_capability_enabled
    from public.organization_capabilities capability
    where capability.organization_id = v_organization_id
      and capability.capability_key = 'retention_management';

    if p_new_mode <> 'legacy' and not coalesce(v_capability_enabled, false) then
      v_error_code := 'capability_disabled';
    elsif not (
      (v_previous_mode = 'legacy' and p_new_mode = 'observe')
      or (v_previous_mode = 'observe' and p_new_mode = 'legacy')
      or (v_previous_mode = 'observe' and p_new_mode = 'blocked')
      or (v_previous_mode = 'blocked' and p_new_mode = 'observe')
    ) then
      v_error_code := 'transition_not_allowed';
    end if;
  end if;

  if v_error_code is not null then
    perform public.record_retention_capability_event(
      v_organization_id,
      p_project_id,
      'project_mode_transition_rejected',
      v_previous_mode,
      p_new_mode,
      v_actor_user_id,
      coalesce(v_reason, 'Project Retention mode transition rejected.'),
      p_correlation_id,
      jsonb_build_object('errorCode', v_error_code)
    );

    return query
    select false, v_error_code, false,
      v_state.organization_id, v_state.project_id, v_previous_mode, v_state.mode,
      v_state.changed_by, v_state.changed_at, v_state.updated_at;
    return;
  end if;

  update public.project_retention_workflow_states state
  set
    mode = p_new_mode,
    changed_by = v_actor_user_id,
    changed_at = now()
  where state.organization_id = v_organization_id
    and state.project_id = p_project_id
  returning * into v_state;

  perform public.record_retention_capability_event(
    v_organization_id,
    p_project_id,
    'project_mode_changed',
    v_previous_mode,
    v_state.mode,
    v_actor_user_id,
    v_reason,
    p_correlation_id,
    jsonb_build_object('transition', v_previous_mode || '_to_' || v_state.mode)
  );

  return query
  select true, null::text, true,
    v_state.organization_id, v_state.project_id, v_previous_mode, v_state.mode,
    v_state.changed_by, v_state.changed_at, v_state.updated_at;
end;
$$;


ALTER FUNCTION "public"."transition_project_retention_workflow_mode"("p_project_id" "uuid", "p_new_mode" "text", "p_reason" "text", "p_correlation_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_master_retention_claim_dates"("p_retention_claim_id" "uuid", "p_claim_date" "date", "p_due_date" "date", "p_expected_revision" bigint, "p_correlation_id" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private'
    AS $$
declare
  v_context jsonb;
  v_claim public.retention_claims%rowtype;
  v_previous_claim_date date;
  v_previous_due_date date;
begin
  if p_claim_date is null or p_due_date is null
    or p_due_date < p_claim_date then
    return jsonb_build_object(
      'succeeded', false,
      'errorCode', 'RETENTION_DATES_INVALID'
    );
  end if;

  v_context := private.master_retention_date_edit_context(
    p_retention_claim_id,
    true
  );
  if not coalesce((v_context->>'succeeded')::boolean, false) then
    return v_context;
  end if;

  select claim.* into v_claim
  from public.retention_claims claim
  where claim.id = p_retention_claim_id
    and claim.organization_id = (v_context->>'organizationId')::uuid
    and claim.project_id = (v_context->>'projectId')::uuid
    and claim.status = 'submitted'
    and claim.master_role = 'master_retention_claim'
  for update;
  if not found or v_claim.draft_revision <> p_expected_revision then
    return jsonb_build_object(
      'succeeded', false,
      'errorCode', 'RETENTION_DATES_STALE',
      'currentRevision', v_claim.draft_revision
    );
  end if;

  if v_claim.issue_date = p_claim_date
    and v_claim.due_date = p_due_date then
    return jsonb_build_object(
      'succeeded', true,
      'errorCode', 'RETENTION_DATES_UNCHANGED',
      'changed', false,
      'claimDate', v_claim.issue_date,
      'dueDate', v_claim.due_date,
      'optimisticRevision', v_claim.draft_revision
    );
  end if;

  v_previous_claim_date := v_claim.issue_date;
  v_previous_due_date := v_claim.due_date;
  perform set_config('app.retention_phase4_submission_write', 'true', true);
  update public.retention_claims
  set issue_date = p_claim_date,
      due_date = p_due_date,
      draft_revision = draft_revision + 1
  where id = v_claim.id
  returning * into v_claim;
  perform set_config('app.retention_phase4_submission_write', '', true);

  perform private.record_retention_claim_event(
    v_claim.organization_id,
    v_claim.project_id,
    v_claim.id,
    'master_dates_updated',
    'submitted',
    'submitted',
    (v_context->>'actorUserId')::uuid,
    'Master Retention Claim dates updated.',
    p_correlation_id,
    jsonb_build_object(
      'previousClaimDate', v_previous_claim_date,
      'claimDate', v_claim.issue_date,
      'previousDueDate', v_previous_due_date,
      'dueDate', v_claim.due_date,
      'activeAccountingRevisionId',
        v_context->>'activeAccountingRevisionId'
    )
  );

  return jsonb_build_object(
    'succeeded', true,
    'errorCode', null,
    'changed', true,
    'claimDate', v_claim.issue_date,
    'dueDate', v_claim.due_date,
    'optimisticRevision', v_claim.draft_revision,
    'activeAccountingRevisionId',
      v_context->>'activeAccountingRevisionId',
    'invoiceId', v_context->>'invoiceId',
    'invoiceNumber', v_context->>'invoiceNumber'
  );
end;
$$;


ALTER FUNCTION "public"."update_master_retention_claim_dates"("p_retention_claim_id" "uuid", "p_claim_date" "date", "p_due_date" "date", "p_expected_revision" bigint, "p_correlation_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_mobile_project_purchase_order_header_v2"("p_project_id" "uuid", "p_purchase_order_id" "uuid", "p_expected_updated_at" timestamp with time zone, "p_notes" "text", "p_due_date" "date", "p_requested_date" "date", "p_requested_by" "text") RETURNS TABLE("purchase_order_id" "uuid", "project_id" "uuid", "purchase_order_number" "text", "purchase_order_title" "text", "status" "text", "origin" "text", "requested_by" "text", "requested_date" "date", "due_date" "date", "notes" "text", "issued_to_label" "text", "supplier_contact" "text", "supplier_name_snapshot" "text", "supplier_email_snapshot" "text", "supplier_phone_snapshot" "text", "subtotal" numeric, "gst_total" numeric, "total_purchase_order_price" numeric, "line_items" "jsonb", "attachments" "jsonb", "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
declare
  current_context record;
  existing_row public.project_purchase_orders%rowtype;
  updated_row public.project_purchase_orders%rowtype;
  normalized_notes text := coalesce(p_notes, '');
  normalized_requested_by text := coalesce(nullif(btrim(coalesce(p_requested_by, '')), ''), '');
begin
  if auth.uid() is null then
    raise exception 'Authentication is required';
  end if;

  if p_expected_updated_at is null then
    raise exception 'Purchase order version is required. Please refresh and try again.'
      using errcode = '40001';
  end if;

  select *
  into current_context
  from public.resolve_mobile_project_member_context_v2(p_project_id);

  if not public.has_org_permission(current_context.organization_id, 'purchase_orders.write') then
    raise exception 'Not authorized to edit purchase orders for this organization';
  end if;

  select *
  into existing_row
  from public.project_purchase_orders po
  where po.organization_id = current_context.organization_id
    and po.project_id = p_project_id
    and po.id = p_purchase_order_id
  for update;

  if not found then
    raise exception 'Purchase order not found for this project';
  end if;

  if existing_row.updated_at is distinct from p_expected_updated_at then
    raise exception 'This purchase order was updated by another user. Refresh and try again.'
      using errcode = '40001';
  end if;

  if existing_row.notes is not distinct from normalized_notes
    and existing_row.due_date is not distinct from p_due_date
    and existing_row.requested_date is not distinct from p_requested_date
    and existing_row.requested_by is not distinct from normalized_requested_by then
    return query
    select *
    from public.get_mobile_project_purchase_order_detail_v2(p_project_id, p_purchase_order_id);
    return;
  end if;

  update public.project_purchase_orders po
  set
    notes = normalized_notes,
    due_date = p_due_date,
    requested_date = p_requested_date,
    requested_by = normalized_requested_by,
    updated_at = statement_timestamp()
  where po.organization_id = current_context.organization_id
    and po.project_id = p_project_id
    and po.id = p_purchase_order_id
  returning * into updated_row;

  if existing_row.notes is distinct from updated_row.notes then
    perform public._write_purchase_order_activity(
      current_context.organization_id,
      p_project_id,
      p_purchase_order_id,
      auth.uid(),
      'header_field_changed',
      'notes',
      to_jsonb(existing_row.notes),
      to_jsonb(updated_row.notes),
      'Purchase order notes updated from mobile',
      jsonb_build_object('source', 'update_mobile_project_purchase_order_header_v2')
    );
  end if;

  if existing_row.due_date is distinct from updated_row.due_date then
    perform public._write_purchase_order_activity(
      current_context.organization_id,
      p_project_id,
      p_purchase_order_id,
      auth.uid(),
      'header_field_changed',
      'due_date',
      to_jsonb(existing_row.due_date),
      to_jsonb(updated_row.due_date),
      'Purchase order due date updated from mobile',
      jsonb_build_object('source', 'update_mobile_project_purchase_order_header_v2')
    );
  end if;

  if existing_row.requested_date is distinct from updated_row.requested_date then
    perform public._write_purchase_order_activity(
      current_context.organization_id,
      p_project_id,
      p_purchase_order_id,
      auth.uid(),
      'header_field_changed',
      'requested_date',
      to_jsonb(existing_row.requested_date),
      to_jsonb(updated_row.requested_date),
      'Purchase order requested date updated from mobile',
      jsonb_build_object('source', 'update_mobile_project_purchase_order_header_v2')
    );
  end if;

  if existing_row.requested_by is distinct from updated_row.requested_by then
    perform public._write_purchase_order_activity(
      current_context.organization_id,
      p_project_id,
      p_purchase_order_id,
      auth.uid(),
      'header_field_changed',
      'requested_by',
      to_jsonb(existing_row.requested_by),
      to_jsonb(updated_row.requested_by),
      'Purchase order requested by updated from mobile',
      jsonb_build_object('source', 'update_mobile_project_purchase_order_header_v2')
    );
  end if;

  return query
  select *
  from public.get_mobile_project_purchase_order_detail_v2(p_project_id, p_purchase_order_id);
end;
$$;


ALTER FUNCTION "public"."update_mobile_project_purchase_order_header_v2"("p_project_id" "uuid", "p_purchase_order_id" "uuid", "p_expected_updated_at" timestamp with time zone, "p_notes" "text", "p_due_date" "date", "p_requested_date" "date", "p_requested_by" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_mobile_project_purchase_order_status_v2"("p_project_id" "uuid", "p_purchase_order_id" "uuid", "p_expected_updated_at" timestamp with time zone, "p_status" "text") RETURNS TABLE("purchase_order_id" "uuid", "project_id" "uuid", "purchase_order_number" "text", "purchase_order_title" "text", "status" "text", "origin" "text", "requested_by" "text", "requested_date" "date", "due_date" "date", "notes" "text", "issued_to_label" "text", "supplier_contact" "text", "supplier_name_snapshot" "text", "supplier_email_snapshot" "text", "supplier_phone_snapshot" "text", "subtotal" numeric, "gst_total" numeric, "total_purchase_order_price" numeric, "line_items" "jsonb", "attachments" "jsonb", "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
declare
  current_context record;
  existing_row public.project_purchase_orders%rowtype;
begin
  if auth.uid() is null then
    raise exception 'Authentication is required';
  end if;

  if p_expected_updated_at is null then
    raise exception 'Purchase order version is required. Please refresh and try again.'
      using errcode = '40001';
  end if;

  select *
  into current_context
  from public.resolve_mobile_project_member_context_v2(p_project_id);

  select *
  into existing_row
  from public.project_purchase_orders po
  where po.organization_id = current_context.organization_id
    and po.project_id = p_project_id
    and po.id = p_purchase_order_id
  for update;

  if not found then
    raise exception 'Purchase order not found for this project';
  end if;

  if existing_row.updated_at is distinct from p_expected_updated_at then
    raise exception 'This purchase order was updated by another user. Refresh and try again.'
      using errcode = '40001';
  end if;

  perform 1
  from public.update_purchase_order_status(
    current_context.organization_id,
    p_project_id,
    p_purchase_order_id,
    p_status
  );

  return query
  select *
  from public.get_mobile_project_purchase_order_detail_v2(p_project_id, p_purchase_order_id);
end;
$$;


ALTER FUNCTION "public"."update_mobile_project_purchase_order_status_v2"("p_project_id" "uuid", "p_purchase_order_id" "uuid", "p_expected_updated_at" timestamp with time zone, "p_status" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_opportunity_details_and_tender_clients_v1"("p_organization_id" "uuid", "p_opportunity_id" "uuid", "p_name" "text", "p_location" "text", "p_due_date" "date", "p_client_ids" "uuid"[], "p_primary_client_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if coalesce(nullif(btrim(p_name), ''), '') = '' then
    raise exception 'Opportunity name is required' using errcode = 'TS422';
  end if;
  perform public.sync_opportunity_tender_clients_v1(
    p_organization_id, p_opportunity_id, p_client_ids, p_primary_client_id
  );
  update public.organization_opportunities opportunity
  set name = btrim(p_name),
    location = coalesce(nullif(btrim(p_location), ''), 'Unspecified'),
    due_date = p_due_date
  where opportunity.organization_id = p_organization_id
    and opportunity.id = p_opportunity_id;
end;
$$;


