CREATE OR REPLACE FUNCTION "public"."update_organization_settings"("p_organization_id" "uuid", "p_name" "text" DEFAULT NULL::"text", "p_logo_path" "text" DEFAULT NULL::"text", "p_brand_primary_color" "text" DEFAULT NULL::"text", "p_brand_accent_color" "text" DEFAULT NULL::"text", "p_business_number" "text" DEFAULT NULL::"text", "p_bank_account_details" "text" DEFAULT NULL::"text", "p_gst_number" "text" DEFAULT NULL::"text", "p_address_line_1" "text" DEFAULT NULL::"text", "p_address_line_2" "text" DEFAULT NULL::"text", "p_city" "text" DEFAULT NULL::"text", "p_postcode" "text" DEFAULT NULL::"text", "p_country" "text" DEFAULT NULL::"text", "p_contact_name" "text" DEFAULT NULL::"text", "p_contact_email" "text" DEFAULT NULL::"text", "p_contact_phone" "text" DEFAULT NULL::"text", "p_default_currency" "text" DEFAULT NULL::"text", "p_timezone" "text" DEFAULT NULL::"text", "p_default_tax_mode" "text" DEFAULT NULL::"text", "p_default_tax_rate" numeric DEFAULT NULL::numeric, "p_construction_profile" "text" DEFAULT NULL::"text") RETURNS "public"."organizations"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  updated_row public.organizations;
  normalized_name text;
  normalized_construction_profile text;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated';
  end if;

  if not public.has_org_permission(p_organization_id, 'settings.organization.update') then
    raise exception 'Not authorized for this organization';
  end if;

  normalized_name := nullif(trim(coalesce(p_name, '')), '');
  normalized_construction_profile := case
    when p_construction_profile is null then null
    else nullif(trim(p_construction_profile), '')
  end;

  if p_logo_path is not null and p_logo_path <> '' and p_logo_path not like p_organization_id::text || '/%' then
    raise exception 'Logo path must be scoped to organization';
  end if;

  update public.organizations o
  set
    name = coalesce(normalized_name, o.name),
    logo_path = coalesce(p_logo_path, o.logo_path),
    brand_primary_color = coalesce(p_brand_primary_color, o.brand_primary_color),
    brand_accent_color = coalesce(p_brand_accent_color, o.brand_accent_color),
    business_number = coalesce(p_business_number, o.business_number),
    bank_account_details = coalesce(p_bank_account_details, o.bank_account_details),
    gst_number = coalesce(p_gst_number, o.gst_number),
    address_line_1 = coalesce(p_address_line_1, o.address_line_1),
    address_line_2 = coalesce(p_address_line_2, o.address_line_2),
    city = coalesce(p_city, o.city),
    postcode = coalesce(p_postcode, o.postcode),
    country = coalesce(p_country, o.country),
    contact_name = coalesce(p_contact_name, o.contact_name),
    contact_email = coalesce(p_contact_email, o.contact_email),
    contact_phone = coalesce(p_contact_phone, o.contact_phone),
    default_currency = coalesce(p_default_currency, o.default_currency),
    timezone = coalesce(p_timezone, o.timezone),
    default_tax_mode = coalesce(p_default_tax_mode, o.default_tax_mode),
    default_tax_rate = coalesce(p_default_tax_rate, o.default_tax_rate),
    construction_profile = case
      when p_construction_profile is null then o.construction_profile
      else normalized_construction_profile
    end,
    updated_at = now()
  where o.id = p_organization_id
  returning o.* into updated_row;

  if updated_row.id is null then
    raise exception 'Organization not found';
  end if;

  return updated_row;
end;
$$;


ALTER FUNCTION "public"."update_organization_settings"("p_organization_id" "uuid", "p_name" "text", "p_logo_path" "text", "p_brand_primary_color" "text", "p_brand_accent_color" "text", "p_business_number" "text", "p_bank_account_details" "text", "p_gst_number" "text", "p_address_line_1" "text", "p_address_line_2" "text", "p_city" "text", "p_postcode" "text", "p_country" "text", "p_contact_name" "text", "p_contact_email" "text", "p_contact_phone" "text", "p_default_currency" "text", "p_timezone" "text", "p_default_tax_mode" "text", "p_default_tax_rate" numeric, "p_construction_profile" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_organization_tax_registration_status"("p_organization_id" "uuid", "p_tax_registration_status" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_status text := lower(trim(coalesce(p_tax_registration_status, '')));
begin
  if not public.has_org_permission(p_organization_id, 'settings.organization.update') then
    raise exception 'You do not have permission to update organization settings.';
  end if;
  if v_status not in ('registered', 'unregistered', 'unknown') then
    raise exception 'Select a valid tax-registration status.';
  end if;
  update public.organizations
  set tax_registration_status = v_status, updated_at = now()
  where id = p_organization_id;
  if not found then raise exception 'Organization not found.'; end if;
  return v_status;
end;
$$;


ALTER FUNCTION "public"."update_organization_tax_registration_status"("p_organization_id" "uuid", "p_tax_registration_status" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_project_claim_status"("p_organization_id" "uuid", "p_project_id" "uuid", "p_claim_id" "uuid", "p_status" "text") RETURNS TABLE("id" "uuid", "claim_number" "text", "claim_title" "text", "claim_type" "text", "status" "text", "claim_date" "date", "period_start" "date", "period_end" "date", "due_date" "date", "percent_complete" numeric, "claim_amount" numeric, "paid_amount" numeric, "retention_percent" numeric, "retention_withheld_amount" numeric, "retention_released_amount" numeric, "retention_held_to_date" numeric, "retention_released_to_date" numeric, "retention_balance" numeric, "net_claim_excl_gst" numeric, "gst_amount" numeric, "total_payable" numeric, "linked_quote_value" numeric, "linked_approved_variations" numeric, "revised_contract_value" numeric, "previous_claims_total" numeric, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if auth.uid() is null then
    raise exception 'Authentication is required';
  end if;

  if not public.is_member_of_organization(p_organization_id) then
    raise exception 'Not authorized for this organization';
  end if;

  if not exists (
    select 1
    from public.organization_projects p
    where p.id = p_project_id
      and p.organization_id = p_organization_id
  ) then
    raise exception 'Project not found for organization';
  end if;

  if not exists (
    select 1
    from public.project_claims c
    where c.id = p_claim_id
      and c.organization_id = p_organization_id
      and c.project_id = p_project_id
  ) then
    raise exception 'Claim not found';
  end if;

  update public.project_claims c
  set status = case
    when p_status in ('Draft', 'Submitted', 'Unpaid', 'Paid', 'Overdue', 'Cancelled') then p_status
    else c.status
  end
  where c.id = p_claim_id
    and c.organization_id = p_organization_id
    and c.project_id = p_project_id;

  perform public.recalculate_project_claim_snapshots(
    p_organization_id,
    p_project_id
  );

  return query
  select
    c.id,
    c.claim_number,
    c.claim_title,
    c.claim_type,
    c.status,
    c.claim_date,
    c.period_start,
    c.period_end,
    c.due_date,
    c.percent_complete,
    c.claim_amount,
    c.paid_amount,
    c.retention_percent,
    c.retention_withheld_amount,
    c.retention_released_amount,
    c.retention_held_to_date,
    c.retention_released_to_date,
    c.retention_balance,
    c.net_claim_excl_gst,
    c.gst_amount,
    c.total_payable,
    c.linked_quote_value,
    c.linked_approved_variations,
    c.revised_contract_value,
    c.previous_claims_total,
    c.updated_at
  from public.project_claims c
  where c.id = p_claim_id
    and c.organization_id = p_organization_id
    and c.project_id = p_project_id;
end;
$$;


ALTER FUNCTION "public"."update_project_claim_status"("p_organization_id" "uuid", "p_project_id" "uuid", "p_claim_id" "uuid", "p_status" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_purchase_order_status"("p_organization_id" "uuid", "p_project_id" "uuid", "p_purchase_order_id" "uuid", "p_status" "text") RETURNS TABLE("id" "uuid", "status" "text", "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  existing_row public.project_purchase_orders%rowtype;
  updated_row public.project_purchase_orders%rowtype;
begin
  if auth.uid() is null then
    raise exception 'Authentication is required';
  end if;

  if not public.has_org_permission(p_organization_id, 'purchase_orders.write') then
    raise exception 'Not authorized for this organization';
  end if;

  if p_status not in ('Draft', 'Pending Approval', 'Approved', 'Issued', 'Received', 'Invoiced', 'Cancelled') then
    raise exception 'Purchase order status must be Draft, Pending Approval, Approved, Issued, Received, Invoiced, or Cancelled';
  end if;

  if not exists (
    select 1
    from public.organization_projects p
    where p.id = p_project_id
      and p.organization_id = p_organization_id
  ) then
    raise exception 'Project not found for organization';
  end if;

  select *
  into existing_row
  from public.project_purchase_orders po
  where po.id = p_purchase_order_id
    and po.organization_id = p_organization_id
    and po.project_id = p_project_id
  for update;

  if not found then
    raise exception 'Purchase order not found';
  end if;

  if existing_row.status is not distinct from p_status then
    return query
    select existing_row.id, existing_row.status, existing_row.updated_at;
    return;
  end if;

  update public.project_purchase_orders po
  set status = p_status
  where po.id = p_purchase_order_id
    and po.organization_id = p_organization_id
    and po.project_id = p_project_id
  returning * into updated_row;

  insert into public.project_purchase_order_status_events (
    organization_id,
    project_id,
    purchase_order_id,
    from_status,
    to_status,
    changed_by
  ) values (
    p_organization_id,
    p_project_id,
    p_purchase_order_id,
    existing_row.status,
    updated_row.status,
    auth.uid()
  );

  perform public._write_purchase_order_activity(
    p_organization_id,
    p_project_id,
    p_purchase_order_id,
    auth.uid(),
    'status_changed',
    'status',
    to_jsonb(existing_row.status),
    to_jsonb(updated_row.status),
    format('Status changed from %s to %s', existing_row.status, updated_row.status),
    jsonb_build_object('source', 'update_purchase_order_status_rpc')
  );

  return query
  select updated_row.id, updated_row.status, updated_row.updated_at;
end;
$$;


ALTER FUNCTION "public"."update_purchase_order_status"("p_organization_id" "uuid", "p_project_id" "uuid", "p_purchase_order_id" "uuid", "p_status" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_retention_claim_allocation"("p_allocation_id" "uuid", "p_expected_draft_revision" bigint, "p_allocation_amount" numeric, "p_correlation_id" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_allocation public.retention_claim_allocations%rowtype;
  v_claim public.retention_claims%rowtype;
  v_origin public.project_claims%rowtype;
  v_context jsonb;
begin
  select * into v_allocation
  from public.retention_claim_allocations allocation
  where allocation.id = p_allocation_id;
  if not found then
    return jsonb_build_object('succeeded', false, 'errorCode', 'claim_not_found');
  end if;

  select * into v_claim
  from public.retention_claims claim
  where claim.id = v_allocation.retention_claim_id;

  v_context := private.retention_claim_operation_context(
    v_claim.project_id,
    'retention.claims.create',
    true
  );
  if not coalesce((v_context ->> 'succeeded')::boolean, false) then
    return v_context;
  end if;

  select * into v_claim
  from public.retention_claims claim
  where claim.id = v_allocation.retention_claim_id
    and claim.organization_id = (v_context ->> 'organizationId')::uuid
  for update;
  if not found then
    return jsonb_build_object('succeeded', false, 'errorCode', 'claim_not_found');
  end if;
  if v_claim.status <> 'draft' then
    return jsonb_build_object('succeeded', false, 'errorCode', 'claim_not_draft');
  end if;
  if v_claim.draft_revision <> p_expected_draft_revision then
    return jsonb_build_object(
      'succeeded', false,
      'errorCode', 'concurrent_update',
      'currentDraftRevision', v_claim.draft_revision
    );
  end if;
  if p_allocation_amount is null or round(p_allocation_amount, 2) <= 0 then
    return jsonb_build_object(
      'succeeded', false,
      'errorCode', 'invalid_allocation_amount'
    );
  end if;

  select * into v_origin
  from public.project_claims origin
  where origin.id = v_allocation.originating_payment_claim_id
    and origin.organization_id = v_claim.organization_id
    and origin.project_id = v_claim.project_id;
  if not found then
    return jsonb_build_object('succeeded', false, 'errorCode', 'origin_not_found');
  end if;
  if v_origin.status = 'Cancelled' then
    return jsonb_build_object('succeeded', false, 'errorCode', 'origin_cancelled');
  end if;
  if round(p_allocation_amount, 2) > greatest(v_origin.retention_withheld_amount, 0) then
    return jsonb_build_object(
      'succeeded', false,
      'errorCode', 'invalid_allocation_amount',
      'currentRetentionOwned', greatest(v_origin.retention_withheld_amount, 0)
    );
  end if;

  update public.retention_claim_allocations allocation
  set
    allocation_amount = round(p_allocation_amount, 2),
    draft_origin_state_hash =
      private.retention_claim_origin_state_hash(v_origin.id),
    draft_origin_updated_at = v_origin.updated_at,
    draft_origin_retention_owned =
      greatest(v_origin.retention_withheld_amount, 0)
  where allocation.id = v_allocation.id
  returning * into v_allocation;

  update public.retention_claims claim
  set draft_revision = claim.draft_revision + 1
  where claim.id = v_claim.id
  returning * into v_claim;

  perform private.record_retention_claim_event(
    v_claim.organization_id, v_claim.project_id, v_claim.id,
    'allocation_updated', 'draft', 'draft', auth.uid(),
    'Retention Claim allocation updated.', p_correlation_id,
    jsonb_build_object(
      'allocationId', v_allocation.id,
      'allocationAmount', v_allocation.allocation_amount,
      'draftRevision', v_claim.draft_revision
    )
  );

  return jsonb_build_object(
    'succeeded', true,
    'errorCode', null,
    'claim', private.retention_claim_header_json(v_claim.id),
    'allocationId', v_allocation.id
  );
end;
$$;


ALTER FUNCTION "public"."update_retention_claim_allocation"("p_allocation_id" "uuid", "p_expected_draft_revision" bigint, "p_allocation_amount" numeric, "p_correlation_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_retention_claim_draft"("p_retention_claim_id" "uuid", "p_expected_draft_revision" bigint, "p_title" "text", "p_reference" "text", "p_issue_date" "date", "p_due_date" "date", "p_refresh_position" boolean DEFAULT false, "p_correlation_id" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_claim public.retention_claims%rowtype;
  v_context jsonb;
  v_position jsonb;
begin
  select * into v_claim
  from public.retention_claims claim
  where claim.id = p_retention_claim_id;

  if not found then
    return jsonb_build_object('succeeded', false, 'errorCode', 'claim_not_found');
  end if;

  v_context := private.retention_claim_operation_context(
    v_claim.project_id,
    'retention.claims.create',
    true
  );
  if not coalesce((v_context ->> 'succeeded')::boolean, false) then
    return v_context;
  end if;

  select * into v_claim
  from public.retention_claims claim
  where claim.id = p_retention_claim_id
    and claim.organization_id = (v_context ->> 'organizationId')::uuid
  for update;

  if not found then
    return jsonb_build_object('succeeded', false, 'errorCode', 'claim_not_found');
  end if;
  if v_claim.status <> 'draft' then
    perform private.record_retention_claim_event(
      v_claim.organization_id, v_claim.project_id, v_claim.id,
      'invalid_transition_attempted', v_claim.status, v_claim.status, auth.uid(),
      'claim_not_draft', p_correlation_id,
      jsonb_build_object('operation', 'update_retention_claim_draft')
    );
    return jsonb_build_object('succeeded', false, 'errorCode', 'claim_not_draft');
  end if;
  if v_claim.draft_revision <> p_expected_draft_revision then
    return jsonb_build_object(
      'succeeded', false,
      'errorCode', 'concurrent_update',
      'currentDraftRevision', v_claim.draft_revision
    );
  end if;
  if nullif(trim(coalesce(p_title, '')), '') is null
    or (
      p_issue_date is not null
      and p_due_date is not null
      and p_due_date < p_issue_date
    ) then
    return jsonb_build_object('succeeded', false, 'errorCode', 'invalid_transition');
  end if;

  if p_refresh_position then
    v_position := public.get_project_retention_position_summary(v_claim.project_id);
  end if;

  update public.retention_claims claim
  set
    title = trim(p_title),
    reference = nullif(trim(coalesce(p_reference, '')), ''),
    issue_date = p_issue_date,
    due_date = p_due_date,
    last_position_state_hash = case
      when p_refresh_position then v_position ->> 'stateHash'
      else claim.last_position_state_hash
    end,
    draft_revision = claim.draft_revision + 1
  where claim.id = v_claim.id
  returning * into v_claim;

  perform private.record_retention_claim_event(
    v_claim.organization_id, v_claim.project_id, v_claim.id,
    'draft_updated', 'draft', 'draft', auth.uid(),
    'Retention Claim Draft updated.', p_correlation_id,
    jsonb_build_object(
      'draftRevision', v_claim.draft_revision,
      'positionRefreshed', p_refresh_position
    )
  );

  return jsonb_build_object(
    'succeeded', true,
    'errorCode', null,
    'claim', private.retention_claim_header_json(v_claim.id)
  );
end;
$$;


ALTER FUNCTION "public"."update_retention_claim_draft"("p_retention_claim_id" "uuid", "p_expected_draft_revision" bigint, "p_title" "text", "p_reference" "text", "p_issue_date" "date", "p_due_date" "date", "p_refresh_position" boolean, "p_correlation_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_retention_legacy_release_allocation"("p_input" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare a public.retention_legacy_release_allocations%rowtype;
  c public.retention_legacy_reconciliation_cases%rowtype;
  s public.retention_legacy_release_sources%rowtype; origin public.project_claims%rowtype;
  ctx jsonb; amount numeric; source_other numeric; origin_other numeric;
begin
  select * into a from public.retention_legacy_release_allocations
  where id=(p_input->>'allocationId')::uuid;
  if not found then return jsonb_build_object('succeeded',false,'errorCode','legacy_allocation_not_found'); end if;
  select * into c from public.retention_legacy_reconciliation_cases
  where id=a.reconciliation_case_id;
  ctx:=private.retention_phase6_context(c.project_id,'retention.legacy.reconcile',true);
  if not coalesce((ctx->>'succeeded')::boolean,false) then return ctx; end if;
  select * into c from public.retention_legacy_reconciliation_cases where id=c.id for update;
  if c.status not in ('draft','rejected') then
    return jsonb_build_object('succeeded',false,'errorCode','legacy_case_not_editable');
  end if;
  if c.revision<>(p_input->>'expectedRevision')::bigint then
    return jsonb_build_object('succeeded',false,'errorCode','concurrent_update',
      'currentRevision',c.revision);
  end if;
  begin amount:=round((p_input->>'allocationAmount')::numeric,2);
  exception when others then
    return jsonb_build_object('succeeded',false,'errorCode','invalid_allocation_amount');
  end;
  if amount is null or amount<=0 then
    return jsonb_build_object('succeeded',false,'errorCode','invalid_allocation_amount');
  end if;
  select * into s from public.retention_legacy_release_sources where id=a.legacy_release_source_id;
  select * into origin from public.project_claims where id=a.originating_payment_claim_id;
  select round(coalesce(sum(x.allocation_amount),0),2) into source_other
  from public.retention_legacy_release_allocations x
  where x.legacy_release_source_id=s.id and x.id<>a.id;
  if source_other+amount>s.retention_released_amount_snapshot then
    return jsonb_build_object('succeeded',false,'errorCode','source_overallocated');
  end if;
  select round(coalesce(sum(x.allocation_amount),0),2) into origin_other
  from public.retention_legacy_release_allocations x
  where x.reconciliation_case_id=c.id
    and x.originating_payment_claim_id=origin.id and x.id<>a.id;
  if origin_other+amount>greatest(origin.retention_withheld_amount,0) then
    return jsonb_build_object('succeeded',false,'errorCode','origin_overallocated');
  end if;
  perform set_config('app.retention_phase6_internal_write','true',true);
  update public.retention_legacy_release_allocations set
    allocation_amount=amount,
    allocation_sequence=coalesce((p_input->>'allocationSequence')::integer,allocation_sequence),
    updated_at=now() where id=a.id;
  update public.retention_legacy_reconciliation_cases set
    revision=revision+1,updated_at=now() where id=c.id returning * into c;
  perform set_config('app.retention_phase6_internal_write','',true);
  perform private.refresh_retention_legacy_case_totals(c.id);
  perform private.record_retention_legacy_event(
    c.id,'allocation_updated',c.status,c.status,
    'Legacy release allocation updated.',p_input->>'correlationId',
    jsonb_build_object('allocationId',a.id,'allocationAmount',amount));
  return jsonb_build_object('succeeded',true,'errorCode',null,
    'case',private.retention_legacy_case_json(c.id));
exception when unique_violation then
  return jsonb_build_object('succeeded',false,'errorCode','invalid_allocation_order');
end;
$$;


ALTER FUNCTION "public"."update_retention_legacy_release_allocation"("p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_retention_release_schedule_draft"("p_input" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_s public.project_retention_release_schedules%rowtype; v_context jsonb; v_target text;
begin
  select * into v_s from public.project_retention_release_schedules
  where id=(p_input->>'scheduleId')::uuid;
  if not found then return jsonb_build_object('succeeded',false,'errorCode','schedule_not_found'); end if;
  v_context:=private.retention_phase4_context(v_s.project_id,'retention.schedules.manage',true);
  if not coalesce((v_context->>'succeeded')::boolean,false) then return v_context; end if;
  select * into v_s from public.project_retention_release_schedules
  where id=v_s.id and organization_id=(v_context->>'organizationId')::uuid for update;
  if v_s.revision<>(p_input->>'expectedRevision')::bigint then
    return jsonb_build_object('succeeded',false,'errorCode','concurrent_update','currentRevision',v_s.revision);
  end if;
  if v_s.status not in ('draft','scheduled','awaiting_confirmation') then
    return jsonb_build_object('succeeded',false,'errorCode','schedule_immutable');
  end if;
  v_target:=coalesce(p_input->>'status',v_s.status);
  if not (
    v_target=v_s.status or (v_s.status='draft' and v_target='scheduled')
    or (v_s.status='awaiting_confirmation' and v_target='scheduled')
  ) then return jsonb_build_object('succeeded',false,'errorCode','schedule_not_draft'); end if;
  begin
    update public.project_retention_release_schedules s set
      name=coalesce(nullif(trim(p_input->>'name'),''),s.name),
      status=v_target,
      trigger_type=coalesce(p_input->>'triggerType',s.trigger_type),
      entitlement_method=coalesce(p_input->>'entitlementMethod',s.entitlement_method),
      percentage_bps=case when p_input ? 'percentageBps' then (p_input->>'percentageBps')::integer else s.percentage_bps end,
      fixed_amount=case when p_input ? 'fixedAmount' then (p_input->>'fixedAmount')::numeric else s.fixed_amount end,
      cap_amount=case when p_input ? 'capAmount' then (p_input->>'capAmount')::numeric else s.cap_amount end,
      scope_policy=coalesce(p_input->>'scopePolicy',s.scope_policy),
      scheduled_trigger_date=case when p_input ? 'scheduledTriggerDate' then (p_input->>'scheduledTriggerDate')::date else s.scheduled_trigger_date end,
      delay_days=coalesce((p_input->>'delayDays')::integer,s.delay_days),
      confirmation_required=coalesce((p_input->>'confirmationRequired')::boolean,s.confirmation_required),
      reminder_rules=coalesce(p_input->'reminderRules',s.reminder_rules),
      revision=s.revision+1
    where s.id=v_s.id returning * into v_s;
  exception when check_violation or invalid_text_representation then
    return jsonb_build_object('succeeded',false,'errorCode','invalid_entitlement_method');
  end;
  perform private.record_retention_schedule_event(
    v_s.id,'schedule_updated',v_s.status,v_target,'Retention release schedule updated.',
    p_input->>'correlationId',jsonb_build_object('revision',v_s.revision)
  );
  return jsonb_build_object('succeeded',true,'errorCode',null,'schedule',to_jsonb(v_s));
end;
$$;


ALTER FUNCTION "public"."update_retention_release_schedule_draft"("p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_retention_reminder"("p_input" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_r public.retention_reminders%rowtype; v_context jsonb; v_due date;
begin
  select * into v_r from public.retention_reminders where id=(p_input->>'reminderId')::uuid;
  if not found then return jsonb_build_object('succeeded',false,'errorCode','reminder_not_found'); end if;
  v_context:=private.retention_phase4_context(v_r.project_id,'retention.reminders.manage',true);
  if not coalesce((v_context->>'succeeded')::boolean,false) then return v_context; end if;
  select * into v_r from public.retention_reminders where id=v_r.id for update;
  if v_r.revision<>(p_input->>'expectedRevision')::bigint then
    return jsonb_build_object('succeeded',false,'errorCode','concurrent_update','currentRevision',v_r.revision);
  end if;
  if v_r.state in ('completed','cancelled') then
    return jsonb_build_object('succeeded',false,'errorCode','reminder_immutable');
  end if;
  v_due:=coalesce((p_input->>'contractualDueDate')::date,v_r.contractual_due_date);
  begin
    update public.retention_reminders set
      reminder_type=coalesce(p_input->>'reminderType',reminder_type),
      contractual_due_date=v_due,due_at=(v_due::timestamp at time zone organization_timezone),
      assigned_user_id=case when p_input ? 'assignedUserId' then (p_input->>'assignedUserId')::uuid else assigned_user_id end,
      assigned_permission_key=case when p_input ? 'assignedPermissionKey' then p_input->>'assignedPermissionKey' else assigned_permission_key end,
      use_project_owner_fallback=coalesce((p_input->>'useProjectOwnerFallback')::boolean,use_project_owner_fallback),
      recurrence_type=coalesce(p_input->>'recurrenceType',recurrence_type),
      recurrence_interval=case when p_input ? 'recurrenceInterval' then (p_input->>'recurrenceInterval')::integer else recurrence_interval end,
      escalation_after_days=case when p_input ? 'escalationAfterDays' then (p_input->>'escalationAfterDays')::integer else escalation_after_days end,
      next_delivery_at=(v_due::timestamp at time zone organization_timezone),
      revision=revision+1
    where id=v_r.id returning * into v_r;
  exception when check_violation then
    return jsonb_build_object('succeeded',false,'errorCode','invalid_assignment');
  end;
  return jsonb_build_object('succeeded',true,'errorCode',null,'reminder',to_jsonb(v_r));
end;
$$;


ALTER FUNCTION "public"."update_retention_reminder"("p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_task"("p_task_id" "uuid", "p_patch" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  actor_user_id uuid := auth.uid();
  old_row public.project_job_todos%rowtype;
  updated_row public.project_job_todos%rowtype;
  next_assigned_user_id uuid;
  next_status text;
  next_priority text;
begin
  old_row := public._task_assert_task_access(p_task_id);

  next_assigned_user_id := case
    when p_patch ? 'assignedUserId' then nullif(p_patch->>'assignedUserId', '')::uuid
    else old_row.assigned_user_id
  end;

  perform public._task_validate_assignee(old_row.organization_id, next_assigned_user_id);

  next_status := case
    when p_patch ? 'status' then public._task_normalize_status(p_patch->>'status')
    else old_row.status
  end;

  next_priority := case
    when p_patch ? 'priority' then public._task_normalize_priority(p_patch->>'priority')
    else old_row.priority
  end;

  update public.project_job_todos t
  set
    title = case when p_patch ? 'title' then nullif(btrim(coalesce(p_patch->>'title', '')), '') else t.title end,
    description = case when p_patch ? 'description' then coalesce(p_patch->>'description', '') else t.description end,
    due_date = case when p_patch ? 'dueDate' then nullif(p_patch->>'dueDate', '')::date else t.due_date end,
    due_at = case when p_patch ? 'dueAt' then nullif(p_patch->>'dueAt', '')::timestamptz else t.due_at end,
    assigned_user_id = next_assigned_user_id,
    trade = case when p_patch ? 'trade' then coalesce(p_patch->>'trade', '') else t.trade end,
    priority = next_priority,
    status = next_status,
    is_completed = next_status = 'Done',
    completed_by = case
      when next_status = 'Done' and t.completed_by is null then actor_user_id
      when next_status <> 'Done' then null
      else t.completed_by
    end,
    completed_at = case
      when next_status = 'Done' then coalesce(t.completed_at, now())
      else null
    end,
    linked_issue_id = case when p_patch ? 'linkedIssueId' then nullif(p_patch->>'linkedIssueId', '')::uuid else t.linked_issue_id end,
    linked_inspection_id = case when p_patch ? 'linkedInspectionId' then nullif(p_patch->>'linkedInspectionId', '')::uuid else t.linked_inspection_id end,
    linked_inspection_item_id = case when p_patch ? 'linkedInspectionItemId' then nullif(p_patch->>'linkedInspectionItemId', '')::uuid else t.linked_inspection_item_id end,
    linked_variation_id = case when p_patch ? 'linkedVariationId' then nullif(p_patch->>'linkedVariationId', '')::uuid else t.linked_variation_id end,
    linked_purchase_order_id = case when p_patch ? 'linkedPurchaseOrderId' then nullif(p_patch->>'linkedPurchaseOrderId', '')::uuid else t.linked_purchase_order_id end,
    linked_quote_id = case when p_patch ? 'linkedQuoteId' then nullif(p_patch->>'linkedQuoteId', '')::uuid else t.linked_quote_id end,
    linked_client_id = case when p_patch ? 'linkedClientId' then nullif(p_patch->>'linkedClientId', '')::uuid else t.linked_client_id end,
    task_type = case when p_patch ? 'taskType' then nullif(p_patch->>'taskType', '') else t.task_type end,
    metadata = case when p_patch ? 'metadata' then coalesce(p_patch->'metadata', '{}'::jsonb) else t.metadata end,
    updated_by = actor_user_id
  where t.id = p_task_id
    and t.organization_id = old_row.organization_id
  returning * into updated_row;

  if updated_row.id is null then
    raise exception 'Task not found';
  end if;

  if old_row.title is distinct from updated_row.title then
    perform public._write_task_activity(updated_row.organization_id, updated_row.id, updated_row.project_id, actor_user_id, 'title_changed', 'title', to_jsonb(old_row.title), to_jsonb(updated_row.title), '{}'::jsonb);
  end if;

  if old_row.description is distinct from updated_row.description then
    perform public._write_task_activity(updated_row.organization_id, updated_row.id, updated_row.project_id, actor_user_id, 'description_changed', 'description', to_jsonb(old_row.description), to_jsonb(updated_row.description), '{}'::jsonb);
  end if;

  if old_row.due_date is distinct from updated_row.due_date then
    perform public._write_task_activity(updated_row.organization_id, updated_row.id, updated_row.project_id, actor_user_id, 'due_date_changed', 'due_date', to_jsonb(old_row.due_date), to_jsonb(updated_row.due_date), '{}'::jsonb);
  end if;

  if old_row.due_at is distinct from updated_row.due_at then
    perform public._write_task_activity(updated_row.organization_id, updated_row.id, updated_row.project_id, actor_user_id, 'due_time_changed', 'due_at', to_jsonb(old_row.due_at), to_jsonb(updated_row.due_at), '{}'::jsonb);
  end if;

  if old_row.assigned_user_id is distinct from updated_row.assigned_user_id then
    perform public._write_task_activity(
      updated_row.organization_id,
      updated_row.id,
      updated_row.project_id,
      actor_user_id,
      case
        when old_row.assigned_user_id is null and updated_row.assigned_user_id is not null then 'assigned'
        when old_row.assigned_user_id is not null and updated_row.assigned_user_id is null then 'unassigned'
        else 'reassigned'
      end,
      'assigned_user_id',
      to_jsonb(old_row.assigned_user_id),
      to_jsonb(updated_row.assigned_user_id),
      '{}'::jsonb
    );
  end if;

  if old_row.status is distinct from updated_row.status then
    perform public._write_task_activity(updated_row.organization_id, updated_row.id, updated_row.project_id, actor_user_id, 'status_changed', 'status', to_jsonb(old_row.status), to_jsonb(updated_row.status), '{}'::jsonb);

    if updated_row.status = 'Done' then
      perform public._write_task_activity(updated_row.organization_id, updated_row.id, updated_row.project_id, actor_user_id, 'completed', 'status', to_jsonb(old_row.status), to_jsonb(updated_row.status), '{}'::jsonb);
    elsif old_row.status = 'Done' and updated_row.status <> 'Done' then
      perform public._write_task_activity(updated_row.organization_id, updated_row.id, updated_row.project_id, actor_user_id, 'reopened', 'status', to_jsonb(old_row.status), to_jsonb(updated_row.status), '{}'::jsonb);
    end if;
  end if;

  if old_row.priority is distinct from updated_row.priority then
    perform public._write_task_activity(updated_row.organization_id, updated_row.id, updated_row.project_id, actor_user_id, 'priority_changed', 'priority', to_jsonb(old_row.priority), to_jsonb(updated_row.priority), '{}'::jsonb);
  end if;

  return public._task_to_json(updated_row);
end;
$$;


ALTER FUNCTION "public"."update_task"("p_task_id" "uuid", "p_patch" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_task_comment"("p_comment_id" "uuid", "p_comment" "text", "p_metadata" "jsonb" DEFAULT NULL::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  actor_user_id uuid := auth.uid();
  old_comment public.task_comments%rowtype;
  updated_comment public.task_comments%rowtype;
begin
  select *
  into old_comment
  from public.task_comments c
  where c.id = p_comment_id;

  if old_comment.id is null then
    raise exception 'Comment not found';
  end if;

  perform public._task_assert_task_access(old_comment.task_id);

  if old_comment.user_id <> actor_user_id then
    raise exception 'Only the comment author can update this comment';
  end if;

  update public.task_comments c
  set
    comment = nullif(btrim(coalesce(p_comment, '')), ''),
    metadata = coalesce(p_metadata, c.metadata)
  where c.id = p_comment_id
  returning * into updated_comment;

  perform public._write_task_activity(updated_comment.organization_id, updated_comment.task_id, updated_comment.project_id, actor_user_id, 'comment_updated', 'comment', to_jsonb(old_comment.comment), to_jsonb(updated_comment.comment), jsonb_build_object('commentId', updated_comment.id));

  return jsonb_build_object(
    'id', updated_comment.id,
    'organizationId', updated_comment.organization_id,
    'taskId', updated_comment.task_id,
    'projectId', updated_comment.project_id,
    'userId', updated_comment.user_id,
    'comment', updated_comment.comment,
    'metadata', updated_comment.metadata,
    'createdAt', updated_comment.created_at,
    'updatedAt', updated_comment.updated_at,
    'deletedAt', updated_comment.deleted_at,
    'deletedBy', updated_comment.deleted_by
  );
end;
$$;


ALTER FUNCTION "public"."update_task_comment"("p_comment_id" "uuid", "p_comment" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_cost_items_for_document"("p_document_kind" "text", "p_document_id" "uuid", "p_source_revision_key" "text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  resolved_context record;
  rows_written integer := 0;
  missing_parent_count integer := 0;
begin
  if p_document_kind = 'project_variation' then
    return public.upsert_cost_items_for_project_variation(p_document_id, p_source_revision_key);
  end if;

  if p_document_kind = 'project_purchase_order' then
    return public.upsert_cost_items_for_project_purchase_order(p_document_id, p_source_revision_key);
  end if;

  if p_document_kind = 'project_claim' then
    return public.upsert_cost_items_for_project_claim(p_document_id, p_source_revision_key);
  end if;

  if p_document_kind <> 'project_quote' then
    raise exception 'Unsupported CostItem document kind for mirror write: %', p_document_kind;
  end if;

  select *
  into resolved_context
  from public.resolve_cost_item_document_context(p_document_kind, p_document_id)
  limit 1;

  if resolved_context.organization_id is null then
    raise exception 'Document not found or not authorized for CostItem mirror write';
  end if;

  delete from public.cost_items ci
  where ci.source_document_kind = p_document_kind
    and ci.source_document_id = p_document_id
    and ci.source_revision_key = p_source_revision_key;

  select count(*)
  into missing_parent_count
  from public.project_quote_line_items li
  where li.organization_id = resolved_context.organization_id
    and li.project_id = resolved_context.project_id
    and li.quote_id = p_document_id
    and li.source_opportunity_quote_line_item_id is not null
    and not exists (
      select 1
      from public.cost_items oci
      where oci.source_document_kind = 'opportunity_quote'
        and oci.source_document_id = li.source_opportunity_quote_id
        and oci.is_current = true
        and oci.linked_opportunity_quote_line_item_id = li.source_opportunity_quote_line_item_id
    );

  if missing_parent_count > 0 then
    raise exception 'Cannot mirror project quote CostItems: one or more converted quote lines have no matching current opportunity baseline CostItem';
  end if;

  with current_lines as (
    select
      q.organization_id,
      q.project_id,
      q.id as document_id,
      q.quote_number as document_number,
      q.quote_title as document_title,
      q.source_opportunity_id,
      q.source_opportunity_quote_id,
      q.source_opportunity_quote_number,
      li.id as line_item_id,
      li.section,
      li.description,
      li.quantity,
      li.unit,
      li.rate as unit_rate,
      coalesce(li.total, round(li.quantity * li.rate, 2)) as line_total,
      coalesce(li.is_optional, false) as is_optional,
      li.sort_order,
      li.source_opportunity_quote_id as source_quote_id,
      li.source_opportunity_quote_line_item_id as source_line_item_id,
      li.source_opportunity_quote_number as source_quote_number,
      public.compute_cost_item_source_fingerprint(
        'project_quote',
        'project_quote_line_items',
        li.section,
        li.description,
        li.quantity,
        li.unit,
        li.rate,
        coalesce(li.total, round(li.quantity * li.rate, 2)),
        coalesce(li.is_optional, false),
        li.sort_order,
        coalesce(li.source_opportunity_quote_line_item_id::text, ''),
        coalesce(li.source_opportunity_quote_number, '')
      ) as source_fingerprint
    from public.project_quotes q
    join public.project_quote_line_items li
      on li.organization_id = q.organization_id
     and li.project_id = q.project_id
     and li.quote_id = q.id
    where q.id = p_document_id
      and q.organization_id = resolved_context.organization_id
      and q.project_id = resolved_context.project_id
  ), classified_lines as (
    select
      cl.*,
      routing.tradesstack_cost_code,
      routing.tradesstack_cost_code_label,
      routing.financial_routing_confidence,
      routing.financial_routing_source,
      routing.review_status,
      routing.review_reason,
      routing.accounting_mapping_id
    from current_lines cl
    cross join lateral public.resolve_cost_item_financial_routing_defaults(
      cl.organization_id,
      cl.project_id,
      'project_quote',
      'project_quote_line_items',
      'manual',
      'line_item',
      cl.section,
      cl.section,
      cl.description,
      cl.description,
      cl.line_total
    ) routing
  )
  insert into public.cost_items (
    organization_id,
    project_id,
    source_document_kind,
    source_document_id,
    source_line_table,
    source_line_id,
    parent_cost_item_id,
    origin_kind,
    source_snapshot,
    item_code,
    item_type,
    section,
    category,
    trade_id,
    trade_label,
    tradesstack_cost_code,
    tradesstack_cost_code_label,
    financial_routing_confidence,
    financial_routing_source,
    accounting_mapping_id,
    review_status,
    review_reason,
    ai_construction_intelligence,
    title,
    description,
    quantity,
    unit,
    unit_rate,
    line_total,
    is_optional,
    sort_order,
    status,
    effective_from,
    effective_to,
    is_current,
    source_revision_key,
    source_fingerprint,
    linked_quote_line_item_id,
    linked_variation_line_item_id,
    linked_purchase_order_line_item_id,
    linked_claim_line_item_id,
    created_by
  )
  select
    cl.organization_id,
    cl.project_id,
    'project_quote',
    cl.document_id,
    'project_quote_line_items',
    cl.line_item_id,
    coalesce(oci.id, prev.id),
    'manual',
    jsonb_build_object(
      'document_kind', 'project_quote',
      'document_number', cl.document_number,
      'document_title', cl.document_title,
      'source_opportunity_id', cl.source_opportunity_id,
      'source_opportunity_quote_id', cl.source_opportunity_quote_id,
      'source_opportunity_quote_number', cl.source_opportunity_quote_number,
      'source_opportunity_quote_line_item_id', cl.source_line_item_id,
      'line_item_id', cl.line_item_id,
      'section', cl.section,
      'is_optional', cl.is_optional
    ),
    '',
    'line_item',
    cl.section,
    cl.section,
    null,
    null,
    cl.tradesstack_cost_code,
    cl.tradesstack_cost_code_label,
    cl.financial_routing_confidence,
    cl.financial_routing_source,
    cl.accounting_mapping_id,
    cl.review_status,
    cl.review_reason,
    '{}'::jsonb,
    coalesce(nullif(btrim(cl.description), ''), 'Untitled line item'),
    coalesce(cl.description, ''),
    cl.quantity,
    cl.unit,
    cl.unit_rate,
    cl.line_total,
    cl.is_optional,
    cl.sort_order,
    'active',
    clock_timestamp(),
    null,
    true,
    p_source_revision_key,
    cl.source_fingerprint,
    cl.line_item_id,
    null,
    null,
    null,
    auth.uid()
  from classified_lines cl
  left join public.cost_items oci
    on oci.source_document_kind = 'opportunity_quote'
   and oci.source_document_id = cl.source_quote_id
   and oci.is_current = true
   and oci.linked_opportunity_quote_line_item_id = cl.source_line_item_id
  left join lateral (
    select ci.id
    from public.cost_items ci
    where ci.source_document_kind = 'project_quote'
      and ci.source_document_id = cl.document_id
      and ci.source_revision_key <> p_source_revision_key
      and ci.source_fingerprint = cl.source_fingerprint
    order by ci.effective_from desc, ci.created_at desc
    limit 1
  ) prev on true;

  get diagnostics rows_written = row_count;
  return rows_written;
end;
$$;


ALTER FUNCTION "public"."upsert_cost_items_for_document"("p_document_kind" "text", "p_document_id" "uuid", "p_source_revision_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_cost_items_for_project_claim"("p_document_id" "uuid", "p_source_revision_key" "text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  resolved_context record;
  rows_written integer := 0;
begin
  select *
  into resolved_context
  from public.resolve_cost_item_document_context('project_claim', p_document_id)
  limit 1;

  if resolved_context.organization_id is null then
    raise exception 'Document not found or not authorized for claim CostItem mirror write';
  end if;

  delete from public.cost_items ci
  where ci.source_document_kind = 'project_claim'
    and ci.source_document_id = p_document_id
    and ci.source_revision_key = p_source_revision_key;

  with current_lines as (
    select
      c.organization_id,
      c.project_id,
      c.id as document_id,
      c.claim_number as document_number,
      c.claim_title as document_title,
      cli.id as claim_line_item_id,
      cli.line_uid,
      cli.source_kind,
      cli.source_document_id,
      cli.source_line_item_id,
      cli.source_number,
      cli.source_title,
      cli.source_cost_item_id,
      cli.section,
      cli.description,
      cli.quantity,
      cli.unit,
      cli.rate as unit_rate,
      cli.source_total,
      cli.previously_claimed_amount,
      cli.previously_claimed_percent,
      cli.claim_percent,
      cli.claim_amount,
      cli.cumulative_claimed_amount,
      cli.cumulative_claimed_percent,
      cli.sort_order,
      public.compute_cost_item_source_fingerprint(
        'project_claim',
        'project_claim_line_items',
        cli.section,
        cli.description,
        cli.quantity,
        cli.unit,
        cli.rate,
        cli.claim_amount,
        false,
        cli.sort_order,
        cli.source_kind,
        coalesce(cli.line_uid::text, cli.source_line_item_id::text)
      ) as source_fingerprint
    from public.project_claims c
    join public.project_claim_line_items cli
      on cli.organization_id = c.organization_id
     and cli.project_id = c.project_id
     and cli.claim_id = c.id
    where c.id = p_document_id
      and c.organization_id = resolved_context.organization_id
      and c.project_id = resolved_context.project_id
  ), classified_lines as (
    select
      cl.*,
      routing.tradesstack_cost_code,
      routing.tradesstack_cost_code_label,
      routing.financial_routing_confidence,
      routing.financial_routing_source,
      routing.review_status,
      routing.review_reason,
      routing.accounting_mapping_id
    from current_lines cl
    cross join lateral public.resolve_cost_item_financial_routing_defaults(
      cl.organization_id,
      cl.project_id,
      'project_claim',
      'project_claim_line_items',
      'claim_snapshot',
      'claim_snapshot',
      cl.section,
      cl.section,
      cl.description,
      cl.description,
      cl.claim_amount
    ) routing
  ), inserted_cost_items as (
    insert into public.cost_items (
      organization_id,
      project_id,
      source_document_kind,
      source_document_id,
      source_line_table,
      source_line_id,
      parent_cost_item_id,
      origin_kind,
      source_snapshot,
      item_code,
      item_type,
      section,
      category,
      trade_id,
      trade_label,
      tradesstack_cost_code,
      tradesstack_cost_code_label,
      financial_routing_confidence,
      financial_routing_source,
      accounting_mapping_id,
      review_status,
      review_reason,
      ai_construction_intelligence,
      title,
      description,
      quantity,
      unit,
      unit_rate,
      line_total,
      is_optional,
      sort_order,
      status,
      effective_from,
      effective_to,
      is_current,
      source_revision_key,
      source_fingerprint,
      linked_quote_line_item_id,
      linked_variation_line_item_id,
      linked_purchase_order_line_item_id,
      linked_claim_line_item_id,
      created_by
    )
    select
      cl.organization_id,
      cl.project_id,
      'project_claim',
      cl.document_id,
      'project_claim_line_items',
      cl.claim_line_item_id,
      parent_ci.id,
      'claim_snapshot',
      jsonb_build_object(
        'document_kind', 'project_claim',
        'document_number', cl.document_number,
        'document_title', cl.document_title,
        'claim_line_item_id', cl.claim_line_item_id,
        'line_uid', cl.line_uid,
        'source_kind', cl.source_kind,
        'source_document_id', cl.source_document_id,
        'source_line_item_id', cl.source_line_item_id,
        'source_number', cl.source_number,
        'source_title', cl.source_title,
        'source_cost_item_id', cl.source_cost_item_id,
        'source_total', cl.source_total,
        'previously_claimed_amount', cl.previously_claimed_amount,
        'previously_claimed_percent', cl.previously_claimed_percent,
        'claim_percent', cl.claim_percent,
        'claim_amount', cl.claim_amount,
        'cumulative_claimed_amount', cl.cumulative_claimed_amount,
        'cumulative_claimed_percent', cl.cumulative_claimed_percent
      ),
      '',
      'claim_snapshot',
      cl.section,
      cl.section,
      null,
      null,
      cl.tradesstack_cost_code,
      cl.tradesstack_cost_code_label,
      cl.financial_routing_confidence,
      cl.financial_routing_source,
      cl.accounting_mapping_id,
      cl.review_status,
      cl.review_reason,
      '{}'::jsonb,
      coalesce(nullif(btrim(cl.description), ''), 'Untitled claim line item'),
      coalesce(cl.description, ''),
      cl.quantity,
      cl.unit,
      cl.unit_rate,
      cl.claim_amount,
      false,
      cl.sort_order,
      'snapshot',
      clock_timestamp(),
      null,
      true,
      p_source_revision_key,
      cl.source_fingerprint,
      null,
      null,
      null,
      cl.claim_line_item_id,
      auth.uid()
    from classified_lines cl
    left join public.cost_items parent_ci
      on parent_ci.id = cl.source_cost_item_id
     and parent_ci.organization_id = cl.organization_id
     and parent_ci.project_id = cl.project_id
     and parent_ci.is_current = true
    returning id, linked_claim_line_item_id
  )
  update public.project_claim_line_items cli
  set cost_item_id = inserted_cost_items.id
  from inserted_cost_items
  where cli.id = inserted_cost_items.linked_claim_line_item_id
    and cli.cost_item_id is distinct from inserted_cost_items.id;

  get diagnostics rows_written = row_count;
  return rows_written;
end;
$$;


ALTER FUNCTION "public"."upsert_cost_items_for_project_claim"("p_document_id" "uuid", "p_source_revision_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_cost_items_for_project_purchase_order"("p_document_id" "uuid", "p_source_revision_key" "text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  resolved_context record;
  rows_written integer := 0;
begin
  if auth.uid() is null then
    raise exception 'Authentication is required';
  end if;

  select *
  into resolved_context
  from public.resolve_cost_item_document_context('project_purchase_order', p_document_id);

  if resolved_context.organization_id is null then
    raise exception 'Document context not found for cost item sync.';
  end if;

  with current_lines as (
    select
      po.organization_id,
      po.project_id,
      po.id as document_id,
      po.purchase_order_number as document_number,
      po.purchase_order_title as document_title,
      po.supplier_id,
      po.issued_to_label,
      li.id as line_item_id,
      li.line_uid,
      li.cost_item_id as previous_cost_item_id,
      li.source_cost_item_id,
      li.section,
      li.description,
      li.quantity,
      li.unit,
      li.rate as unit_rate,
      coalesce(li.total, round(li.quantity * li.rate, 2)) as line_total,
      li.sort_order,
      li.source_time_sheet_entry_id,
      public.compute_cost_item_source_fingerprint(
        'project_purchase_order',
        'project_purchase_order_line_items',
        li.section,
        li.description,
        li.quantity,
        li.unit,
        li.rate,
        coalesce(li.total, round(li.quantity * li.rate, 2)),
        false,
        li.sort_order,
        coalesce(li.source_time_sheet_entry_id::text, ''),
        coalesce(li.line_uid::text, '')
      ) as source_fingerprint
    from public.project_purchase_orders po
    join public.project_purchase_order_line_items li
      on li.organization_id = po.organization_id
     and li.project_id = po.project_id
     and li.purchase_order_id = po.id
    where po.id = p_document_id
      and po.organization_id = resolved_context.organization_id
      and po.project_id = resolved_context.project_id
  ), classified_lines as (
    select
      cl.*,
      routing.tradesstack_cost_code,
      routing.tradesstack_cost_code_label,
      routing.financial_routing_confidence,
      routing.financial_routing_source,
      routing.review_status,
      routing.review_reason,
      routing.accounting_mapping_id
    from current_lines cl
    cross join lateral public.resolve_cost_item_financial_routing_defaults(
      cl.organization_id,
      cl.project_id,
      'project_purchase_order',
      'project_purchase_order_line_items',
      case when cl.source_time_sheet_entry_id is not null then 'time_sheet_sync' else 'manual' end,
      'line_item',
      cl.section,
      cl.section,
      cl.description,
      cl.description,
      cl.line_total
    ) routing
  ), inserted_cost_items as (
    insert into public.cost_items (
      organization_id,
      project_id,
      source_document_kind,
      source_document_id,
      source_line_table,
      source_line_id,
      parent_cost_item_id,
      origin_kind,
      source_snapshot,
      item_code,
      item_type,
      section,
      category,
      trade_id,
      trade_label,
      supplier_id,
      supplier_name_snapshot,
      tradesstack_cost_code,
      tradesstack_cost_code_label,
      financial_routing_confidence,
      financial_routing_source,
      accounting_mapping_id,
      review_status,
      review_reason,
      ai_construction_intelligence,
      title,
      description,
      quantity,
      unit,
      unit_rate,
      line_total,
      is_optional,
      sort_order,
      status,
      effective_from,
      effective_to,
      is_current,
      source_revision_key,
      source_fingerprint,
      linked_quote_line_item_id,
      linked_variation_line_item_id,
      linked_purchase_order_line_item_id,
      linked_claim_line_item_id,
      created_by
    )
    select
      cl.organization_id,
      cl.project_id,
      'project_purchase_order',
      cl.document_id,
      'project_purchase_order_line_items',
      cl.line_item_id,
      coalesce(time_sheet_parent.id, explicit_parent.id),
      case
        when cl.source_time_sheet_entry_id is not null then 'time_sheet_sync'
        else 'manual'
      end,
      jsonb_build_object(
        'document_kind', 'project_purchase_order',
        'document_number', cl.document_number,
        'document_title', cl.document_title,
        'line_item_id', cl.line_item_id,
        'line_uid', cl.line_uid,
        'supplier_id', cl.supplier_id,
        'issued_to_label', cl.issued_to_label,
        'source_cost_item_id', cl.source_cost_item_id,
        'source_time_sheet_entry_id', cl.source_time_sheet_entry_id
      ),
      '',
      'line_item',
      cl.section,
      cl.section,
      null,
      null,
      cl.supplier_id,
      cl.issued_to_label,
      cl.tradesstack_cost_code,
      cl.tradesstack_cost_code_label,
      cl.financial_routing_confidence,
      cl.financial_routing_source,
      cl.accounting_mapping_id,
      cl.review_status,
      cl.review_reason,
      '{}'::jsonb,
      coalesce(nullif(btrim(cl.description), ''), 'Untitled line item'),
      coalesce(cl.description, ''),
      cl.quantity,
      cl.unit,
      cl.unit_rate,
      cl.line_total,
      false,
      cl.sort_order,
      'active',
      clock_timestamp(),
      null,
      true,
      p_source_revision_key,
      cl.source_fingerprint,
      null,
      null,
      cl.line_item_id,
      null,
      auth.uid()
    from classified_lines cl
    left join lateral (
      select ci.id
      from public.cost_items ci
      where ci.organization_id = cl.organization_id
        and ci.project_id = cl.project_id
        and ci.is_current = true
        and ci.source_document_kind <> 'project_purchase_order'
        and cl.source_time_sheet_entry_id is not null
        and ci.source_snapshot ->> 'source_time_sheet_entry_id' = cl.source_time_sheet_entry_id::text
      order by ci.effective_from desc, ci.created_at desc
      limit 1
    ) time_sheet_parent on true
    left join lateral (
      select ci.id
      from public.cost_items ci
      where ci.id = cl.source_cost_item_id
        and ci.organization_id = cl.organization_id
        and ci.project_id = cl.project_id
        and ci.is_current = true
      limit 1
    ) explicit_parent on true
    returning id, linked_purchase_order_line_item_id
  )
  update public.project_purchase_order_line_items li
  set cost_item_id = inserted_cost_items.id
  from inserted_cost_items
  where li.id = inserted_cost_items.linked_purchase_order_line_item_id
    and li.cost_item_id is distinct from inserted_cost_items.id;

  get diagnostics rows_written = row_count;
  return rows_written;
end;
$$;


ALTER FUNCTION "public"."upsert_cost_items_for_project_purchase_order"("p_document_id" "uuid", "p_source_revision_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_cost_items_for_project_variation"("p_variation_id" "uuid", "p_source_revision_key" "text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  resolved_context record;
  rows_written integer := 0;
  missing_parent_count integer := 0;
begin
  select *
  into resolved_context
  from public.resolve_cost_item_document_context('project_variation', p_variation_id)
  limit 1;

  if resolved_context.organization_id is null then
    raise exception 'Document not found or not authorized for project variation CostItem mirror write';
  end if;

  delete from public.cost_items ci
  where ci.source_document_kind = 'project_variation'
    and ci.source_document_id = p_variation_id
    and ci.source_revision_key = p_source_revision_key;

  select count(*)
  into missing_parent_count
  from public.project_variation_line_items li
  where li.organization_id = resolved_context.organization_id
    and li.project_id = resolved_context.project_id
    and li.variation_id = p_variation_id
    and li.source_project_quote_line_item_id is not null
    and not exists (
      select 1
      from public.cost_items qci
      where qci.source_document_kind = 'project_quote'
        and qci.source_document_id = li.source_project_quote_id
        and qci.is_current = true
        and qci.linked_quote_line_item_id = li.source_project_quote_line_item_id
    );

  if missing_parent_count > 0 then
    raise exception 'Cannot mirror project variation CostItems: one or more quote-linked variation lines have no matching current project quote CostItem';
  end if;

  with current_lines as (
    select
      v.organization_id,
      v.project_id,
      v.id as document_id,
      v.variation_number as document_number,
      v.variation_title as document_title,
      li.id as line_item_id,
      li.section,
      li.description,
      li.quantity,
      li.unit,
      li.rate as unit_rate,
      coalesce(li.total, round(li.quantity * li.rate, 2)) as line_total,
      li.sort_order,
      li.source_project_quote_id,
      li.source_project_quote_line_item_id,
      li.source_project_quote_number,
      li.source_purchase_order_id,
      li.source_purchase_order_line_item_id,
      li.source_purchase_order_number,
      public.compute_cost_item_source_fingerprint(
        'project_variation',
        'project_variation_line_items',
        li.section,
        li.description,
        li.quantity,
        li.unit,
        li.rate,
        coalesce(li.total, round(li.quantity * li.rate, 2)),
        false,
        li.sort_order,
        coalesce(li.source_project_quote_line_item_id::text, coalesce(li.source_purchase_order_line_item_id::text, '')),
        coalesce(nullif(li.source_project_quote_number, ''), coalesce(li.source_purchase_order_number, ''))
      ) as source_fingerprint
    from public.project_variations v
    join public.project_variation_line_items li
      on li.organization_id = v.organization_id
     and li.project_id = v.project_id
     and li.variation_id = v.id
    where v.id = p_variation_id
      and v.organization_id = resolved_context.organization_id
      and v.project_id = resolved_context.project_id
  ), classified_lines as (
    select
      cl.*,
      routing.tradesstack_cost_code,
      routing.tradesstack_cost_code_label,
      routing.financial_routing_confidence,
      routing.financial_routing_source,
      routing.review_status,
      routing.review_reason,
      routing.accounting_mapping_id
    from current_lines cl
    cross join lateral public.resolve_cost_item_financial_routing_defaults(
      cl.organization_id,
      cl.project_id,
      'project_variation',
      'project_variation_line_items',
      case
        when cl.source_project_quote_line_item_id is not null then 'system'
        when cl.source_purchase_order_line_item_id is not null then 'purchase_order_import'
        else 'manual'
      end,
      'line_item',
      cl.section,
      cl.section,
      cl.description,
      cl.description,
      cl.line_total
    ) routing
  )
  insert into public.cost_items (
    organization_id,
    project_id,
    source_document_kind,
    source_document_id,
    source_line_table,
    source_line_id,
    parent_cost_item_id,
    origin_kind,
    source_snapshot,
    item_code,
    item_type,
    section,
    category,
    trade_id,
    trade_label,
    tradesstack_cost_code,
    tradesstack_cost_code_label,
    financial_routing_confidence,
    financial_routing_source,
    accounting_mapping_id,
    review_status,
    review_reason,
    ai_construction_intelligence,
    title,
    description,
    quantity,
    unit,
    unit_rate,
    line_total,
    is_optional,
    sort_order,
    status,
    effective_from,
    effective_to,
    is_current,
    source_revision_key,
    source_fingerprint,
    linked_quote_line_item_id,
    linked_variation_line_item_id,
    linked_purchase_order_line_item_id,
    linked_claim_line_item_id,
    created_by
  )
  select
    cl.organization_id,
    cl.project_id,
    'project_variation',
    cl.document_id,
    'project_variation_line_items',
    cl.line_item_id,
    coalesce(qci.id, prev.id),
    case
      when cl.source_project_quote_line_item_id is not null then 'system'
      when cl.source_purchase_order_line_item_id is not null then 'purchase_order_import'
      else 'manual'
    end,
    jsonb_build_object(
      'document_kind', 'project_variation',
      'document_number', cl.document_number,
      'document_title', cl.document_title,
      'line_item_id', cl.line_item_id,
      'source_project_quote_id', cl.source_project_quote_id,
      'source_project_quote_line_item_id', cl.source_project_quote_line_item_id,
      'source_project_quote_number', cl.source_project_quote_number,
      'source_purchase_order_id', cl.source_purchase_order_id,
      'source_purchase_order_line_item_id', cl.source_purchase_order_line_item_id,
      'source_purchase_order_number', cl.source_purchase_order_number
    ),
    '',
    'line_item',
    cl.section,
    cl.section,
    null,
    null,
    cl.tradesstack_cost_code,
    cl.tradesstack_cost_code_label,
    cl.financial_routing_confidence,
    cl.financial_routing_source,
    cl.accounting_mapping_id,
    cl.review_status,
    cl.review_reason,
    '{}'::jsonb,
    coalesce(nullif(btrim(cl.description), ''), 'Untitled line item'),
    coalesce(cl.description, ''),
    cl.quantity,
    cl.unit,
    cl.unit_rate,
    cl.line_total,
    false,
    cl.sort_order,
    'active',
    clock_timestamp(),
    null,
    true,
    p_source_revision_key,
    cl.source_fingerprint,
    null,
    cl.line_item_id,
    null,
    null,
    auth.uid()
  from classified_lines cl
  left join public.cost_items qci
    on qci.source_document_kind = 'project_quote'
   and qci.source_document_id = cl.source_project_quote_id
   and qci.is_current = true
   and qci.linked_quote_line_item_id = cl.source_project_quote_line_item_id
  left join lateral (
    select ci.id
    from public.cost_items ci
    where ci.source_document_kind = 'project_variation'
      and ci.source_document_id = cl.document_id
      and ci.source_revision_key <> p_source_revision_key
      and ci.linked_variation_line_item_id = cl.line_item_id
    order by ci.effective_from desc, ci.created_at desc
    limit 1
  ) prev on true;

  get diagnostics rows_written = row_count;
  return rows_written;
end;
$$;


ALTER FUNCTION "public"."upsert_cost_items_for_project_variation"("p_variation_id" "uuid", "p_source_revision_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_opportunity_quote_cost_items"("p_document_id" "uuid", "p_source_revision_key" "text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  resolved_context record;
  rows_written integer := 0;
begin
  select *
  into resolved_context
  from public.resolve_cost_item_document_context('opportunity_quote', p_document_id)
  limit 1;

  if resolved_context.organization_id is null or resolved_context.project_id is null then
    raise exception 'Opportunity quote not found, not authorized, or missing workspace project for CostItem mirror write';
  end if;

  delete from public.cost_items ci
  where ci.source_document_kind = 'opportunity_quote'
    and ci.source_document_id = p_document_id
    and ci.source_revision_key = p_source_revision_key;

  with current_lines as (
    select
      q.organization_id,
      o.workspace_project_id as project_id,
      q.id as document_id,
      q.quote_number as document_number,
      q.quote_title as document_title,
      q.opportunity_id,
      o.opportunity_code,
      o.name as opportunity_name,
      li.id as line_item_id,
      li.section,
      li.description,
      li.quantity,
      li.unit,
      li.rate as unit_rate,
      coalesce(li.total, round(li.quantity * li.rate, 2)) as line_total,
      coalesce(li.is_optional, false) as is_optional,
      li.sort_order,
      public.compute_cost_item_source_fingerprint(
        'opportunity_quote',
        'opportunity_quote_line_items',
        li.section,
        li.description,
        li.quantity,
        li.unit,
        li.rate,
        coalesce(li.total, round(li.quantity * li.rate, 2)),
        coalesce(li.is_optional, false),
        li.sort_order,
        '',
        ''
      ) as source_fingerprint
    from public.opportunity_quotes q
    join public.organization_opportunities o
      on o.id = q.opportunity_id
     and o.organization_id = q.organization_id
    join public.opportunity_quote_line_items li
      on li.organization_id = q.organization_id
     and li.quote_id = q.id
    where q.id = p_document_id
      and q.organization_id = resolved_context.organization_id
      and o.workspace_project_id = resolved_context.project_id
  ), classified_lines as (
    select
      cl.*,
      routing.tradesstack_cost_code,
      routing.tradesstack_cost_code_label,
      routing.financial_routing_confidence,
      routing.financial_routing_source,
      routing.review_status,
      routing.review_reason,
      routing.accounting_mapping_id
    from current_lines cl
    cross join lateral public.resolve_cost_item_financial_routing_defaults(
      cl.organization_id,
      cl.project_id,
      'opportunity_quote',
      'opportunity_quote_line_items',
      'manual',
      'line_item',
      cl.section,
      cl.section,
      cl.description,
      cl.description,
      cl.line_total
    ) routing
  )
  insert into public.cost_items (
    organization_id,
    project_id,
    source_document_kind,
    source_document_id,
    source_line_table,
    source_line_id,
    parent_cost_item_id,
    origin_kind,
    source_snapshot,
    item_code,
    item_type,
    section,
    category,
    trade_id,
    trade_label,
    tradesstack_cost_code,
    tradesstack_cost_code_label,
    financial_routing_confidence,
    financial_routing_source,
    accounting_mapping_id,
    review_status,
    review_reason,
    ai_construction_intelligence,
    title,
    description,
    quantity,
    unit,
    unit_rate,
    line_total,
    is_optional,
    sort_order,
    status,
    effective_from,
    effective_to,
    is_current,
    source_revision_key,
    source_fingerprint,
    linked_opportunity_quote_line_item_id,
    created_by
  )
  select
    cl.organization_id,
    cl.project_id,
    'opportunity_quote',
    cl.document_id,
    'opportunity_quote_line_items',
    cl.line_item_id,
    prev.id,
    'manual',
    jsonb_build_object(
      'document_kind', 'opportunity_quote',
      'document_number', cl.document_number,
      'document_title', cl.document_title,
      'opportunity_id', cl.opportunity_id,
      'opportunity_code', cl.opportunity_code,
      'opportunity_name', cl.opportunity_name,
      'line_item_id', cl.line_item_id,
      'section', cl.section,
      'is_optional', cl.is_optional
    ),
    '',
    'line_item',
    cl.section,
    cl.section,
    null,
    null,
    cl.tradesstack_cost_code,
    cl.tradesstack_cost_code_label,
    cl.financial_routing_confidence,
    cl.financial_routing_source,
    cl.accounting_mapping_id,
    cl.review_status,
    cl.review_reason,
    '{}'::jsonb,
    coalesce(nullif(btrim(cl.description), ''), 'Untitled line item'),
    coalesce(cl.description, ''),
    cl.quantity,
    cl.unit,
    cl.unit_rate,
    cl.line_total,
    cl.is_optional,
    cl.sort_order,
    'active',
    clock_timestamp(),
    null,
    true,
    p_source_revision_key,
    cl.source_fingerprint,
    cl.line_item_id,
    auth.uid()
  from classified_lines cl
  left join lateral (
    select ci.id
    from public.cost_items ci
    where ci.source_document_kind = 'opportunity_quote'
      and ci.source_document_id = cl.document_id
      and ci.source_revision_key <> p_source_revision_key
      and ci.source_fingerprint = cl.source_fingerprint
    order by ci.effective_from desc, ci.created_at desc
    limit 1
  ) prev on true;

  get diagnostics rows_written = row_count;
  return rows_written;
end;
$$;


ALTER FUNCTION "public"."upsert_opportunity_quote_cost_items"("p_document_id" "uuid", "p_source_revision_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_organization_memory_item"("p_input" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  resolved_organization_id uuid;
  resolved_id uuid;
  existing_id uuid;
begin
  if p_input is null or jsonb_typeof(p_input) <> 'object' then
    raise exception 'upsert_organization_memory_item requires a JSON object payload';
  end if;

  perform public._organization_memory_assert_platform_admin('admin');

  resolved_organization_id := nullif(p_input->>'organizationId', '')::uuid;
  perform public._organization_memory_assert_organization_exists(resolved_organization_id);

  select omi.id
  into existing_id
  from public.organization_memory_items omi
  where omi.organization_id = resolved_organization_id
    and omi.memory_category = nullif(btrim(coalesce(p_input->>'memoryCategory', '')), '')
    and omi.memory_type = nullif(btrim(coalesce(p_input->>'memoryType', '')), '')
    and omi.memory_key = nullif(btrim(coalesce(p_input->>'memoryKey', '')), '')
  limit 1;

  insert into public.organization_memory_items (
    id,
    organization_id,
    memory_category,
    memory_type,
    memory_key,
    title,
    summary,
    memory_value,
    evidence_summary,
    confidence_score,
    derived_from_event_count,
    derived_from_ai_interaction_count,
    derived_from_correction_count,
    derived_from_validation_count,
    derived_from_total_count,
    reinforcement_count,
    contradiction_count,
    is_active,
    is_user_confirmed,
    user_confirmed_by_user_id,
    user_confirmed_at,
    first_derived_at,
    last_derived_at,
    last_reinforced_at,
    last_contradicted_at,
    privacy_classification,
    visibility_scope,
    retention_policy_key,
    retention_expires_at
  )
  values (
    coalesce(existing_id, gen_random_uuid()),
    resolved_organization_id,
    nullif(btrim(coalesce(p_input->>'memoryCategory', '')), ''),
    nullif(btrim(coalesce(p_input->>'memoryType', '')), ''),
    nullif(btrim(coalesce(p_input->>'memoryKey', '')), ''),
    nullif(btrim(coalesce(p_input->>'title', '')), ''),
    coalesce(p_input->>'summary', ''),
    coalesce(p_input->'memoryValue', '{}'::jsonb),
    coalesce(p_input->'evidenceSummary', '{}'::jsonb),
    coalesce(nullif(p_input->>'confidenceScore', '')::numeric, 0),
    greatest(coalesce(nullif(p_input->>'derivedFromEventCount', '')::integer, 0), 0),
    greatest(coalesce(nullif(p_input->>'derivedFromAiInteractionCount', '')::integer, 0), 0),
    greatest(coalesce(nullif(p_input->>'derivedFromCorrectionCount', '')::integer, 0), 0),
    greatest(coalesce(nullif(p_input->>'derivedFromValidationCount', '')::integer, 0), 0),
    greatest(coalesce(nullif(p_input->>'derivedFromTotalCount', '')::integer, 0), 0),
    greatest(coalesce(nullif(p_input->>'reinforcementCount', '')::integer, 0), 0),
    greatest(coalesce(nullif(p_input->>'contradictionCount', '')::integer, 0), 0),
    coalesce(nullif(p_input->>'isActive', '')::boolean, true),
    coalesce(nullif(p_input->>'isUserConfirmed', '')::boolean, false),
    case
      when coalesce(nullif(p_input->>'isUserConfirmed', '')::boolean, false) then auth.uid()
      else null
    end,
    case
      when coalesce(nullif(p_input->>'isUserConfirmed', '')::boolean, false) then now()
      else null
    end,
    coalesce(nullif(p_input->>'firstDerivedAt', '')::timestamptz, now()),
    coalesce(nullif(p_input->>'lastDerivedAt', '')::timestamptz, now()),
    nullif(p_input->>'lastReinforcedAt', '')::timestamptz,
    nullif(p_input->>'lastContradictedAt', '')::timestamptz,
    coalesce(nullif(btrim(coalesce(p_input->>'privacyClassification', '')), ''), 'commercial_sensitive'),
    coalesce(nullif(btrim(coalesce(p_input->>'visibilityScope', '')), ''), 'organization'),
    nullif(btrim(coalesce(p_input->>'retentionPolicyKey', '')), ''),
    nullif(p_input->>'retentionExpiresAt', '')::timestamptz
  )
  on conflict (organization_id, memory_category, memory_type, memory_key)
  do update set
    title = excluded.title,
    summary = excluded.summary,
    memory_value = excluded.memory_value,
    evidence_summary = excluded.evidence_summary,
    confidence_score = excluded.confidence_score,
    derived_from_event_count = excluded.derived_from_event_count,
    derived_from_ai_interaction_count = excluded.derived_from_ai_interaction_count,
    derived_from_correction_count = excluded.derived_from_correction_count,
    derived_from_validation_count = excluded.derived_from_validation_count,
    derived_from_total_count = excluded.derived_from_total_count,
    reinforcement_count = excluded.reinforcement_count,
    contradiction_count = excluded.contradiction_count,
    is_active = excluded.is_active,
    is_user_confirmed = excluded.is_user_confirmed,
    user_confirmed_by_user_id = excluded.user_confirmed_by_user_id,
    user_confirmed_at = excluded.user_confirmed_at,
    first_derived_at = least(
      coalesce(public.organization_memory_items.first_derived_at, excluded.first_derived_at),
      coalesce(excluded.first_derived_at, public.organization_memory_items.first_derived_at)
    ),
    last_derived_at = greatest(
      coalesce(public.organization_memory_items.last_derived_at, excluded.last_derived_at),
      coalesce(excluded.last_derived_at, public.organization_memory_items.last_derived_at)
    ),
    last_reinforced_at = coalesce(excluded.last_reinforced_at, public.organization_memory_items.last_reinforced_at),
    last_contradicted_at = coalesce(excluded.last_contradicted_at, public.organization_memory_items.last_contradicted_at),
    privacy_classification = excluded.privacy_classification,
    visibility_scope = excluded.visibility_scope,
    retention_policy_key = excluded.retention_policy_key,
    retention_expires_at = excluded.retention_expires_at,
    updated_at = now()
  returning id into resolved_id;

  return resolved_id;
end;
$$;


ALTER FUNCTION "public"."upsert_organization_memory_item"("p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_project_quote_cost_items_from_opportunity"("p_organization_id" "uuid", "p_project_quote_id" "uuid", "p_opportunity_quote_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  resolved_context record;
  cost_item_revision_key text;
  rows_written integer := 0;
  missing_parent_count integer := 0;
begin
  if auth.uid() is null then
    raise exception 'Authentication is required';
  end if;

  if not public.has_org_permission(p_organization_id, 'quotes.write') then
    raise exception 'Not authorized for this organization';
  end if;

  select *
  into resolved_context
  from public.resolve_cost_item_document_context('project_quote', p_project_quote_id)
  limit 1;

  if resolved_context.organization_id is null then
    raise exception 'Project quote not found or not authorized for CostItem conversion';
  end if;

  select count(*)
  into missing_parent_count
  from public.project_quote_line_items pqli
  left join public.cost_items oci
    on oci.source_document_kind = 'opportunity_quote'
   and oci.source_document_id = p_opportunity_quote_id
   and oci.is_current = true
   and oci.linked_opportunity_quote_line_item_id = pqli.source_opportunity_quote_line_item_id
  where pqli.organization_id = p_organization_id
    and pqli.project_id = resolved_context.project_id
    and pqli.quote_id = p_project_quote_id
    and pqli.source_opportunity_quote_id = p_opportunity_quote_id
    and oci.id is null;

  if missing_parent_count > 0 then
    raise exception 'Cannot create project quote CostItems: one or more opportunity quote lines have no current baseline CostItem';
  end if;

  cost_item_revision_key := public.begin_cost_item_revision('project_quote', p_project_quote_id);
  perform public.supersede_previous_cost_items('project_quote', p_project_quote_id, cost_item_revision_key);

  delete from public.cost_items ci
  where ci.source_document_kind = 'project_quote'
    and ci.source_document_id = p_project_quote_id
    and ci.source_revision_key = cost_item_revision_key;

  rows_written := public.upsert_cost_items_for_document(
    'project_quote',
    p_project_quote_id,
    cost_item_revision_key
  );
  return rows_written;
end;
$$;


ALTER FUNCTION "public"."upsert_project_quote_cost_items_from_opportunity"("p_organization_id" "uuid", "p_project_quote_id" "uuid", "p_opportunity_quote_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_worksheet_pricing_pattern_shadow_candidate"("p_input" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  resolved_organization_id uuid;
  resolved_candidate_signature text;
  existing_row public.worksheet_pricing_pattern_shadow_candidates%rowtype;
  inserted_row public.worksheet_pricing_pattern_shadow_candidates%rowtype;
begin
  if p_input is null or jsonb_typeof(p_input) <> 'object' then
    raise exception 'upsert_worksheet_pricing_pattern_shadow_candidate requires a JSON object payload';
  end if;

  resolved_organization_id := nullif(p_input->>'organization_id', '')::uuid;
  resolved_candidate_signature := nullif(btrim(coalesce(p_input->>'candidate_signature', '')), '');

  if resolved_organization_id is null then
    raise exception 'organization_id is required';
  end if;

  if resolved_candidate_signature is null then
    raise exception 'candidate_signature is required';
  end if;

  select *
  into existing_row
  from public.worksheet_pricing_pattern_shadow_candidates c
  where c.organization_id = resolved_organization_id
    and c.candidate_signature = resolved_candidate_signature
    and c.candidate_status <> 'retired'
  order by c.signature_uniqueness_enabled desc, c.created_at asc, c.id asc
  limit 1;

  if found then
    return jsonb_build_object(
      'candidate', to_jsonb(existing_row),
      'inserted', false
    );
  end if;

  insert into public.worksheet_pricing_pattern_shadow_candidates (
    organization_id,
    candidate_status,
    pattern_family,
    pattern_type,
    current_strength,
    confidence,
    title,
    summary,
    retrieval_guidance,
    scope,
    pattern_value,
    scope_signature,
    pattern_value_signature,
    candidate_signature,
    signature_uniqueness_enabled,
    support_count,
    contradiction_count,
    ignored_count,
    support_diversity,
    contradiction_diversity,
    last_reinforced_at,
    last_contradicted_at,
    stale_after,
    created_by_run_id,
    last_updated_by_run_id
  )
  values (
    nullif(p_input->>'organization_id', '')::uuid,
    coalesce(nullif(btrim(coalesce(p_input->>'candidate_status', '')), ''), 'active'),
    nullif(btrim(coalesce(p_input->>'pattern_family', '')), ''),
    nullif(btrim(coalesce(p_input->>'pattern_type', '')), ''),
    nullif(btrim(coalesce(p_input->>'current_strength', '')), ''),
    nullif(p_input->>'confidence', '')::numeric,
    nullif(btrim(coalesce(p_input->>'title', '')), ''),
    nullif(btrim(coalesce(p_input->>'summary', '')), ''),
    nullif(btrim(coalesce(p_input->>'retrieval_guidance', '')), ''),
    coalesce(p_input->'scope', '{}'::jsonb),
    coalesce(p_input->'pattern_value', '{}'::jsonb),
    nullif(btrim(coalesce(p_input->>'scope_signature', '')), ''),
    nullif(btrim(coalesce(p_input->>'pattern_value_signature', '')), ''),
    resolved_candidate_signature,
    coalesce((p_input->>'signature_uniqueness_enabled')::boolean, true),
    greatest(coalesce(nullif(p_input->>'support_count', '')::integer, 0), 0),
    greatest(coalesce(nullif(p_input->>'contradiction_count', '')::integer, 0), 0),
    greatest(coalesce(nullif(p_input->>'ignored_count', '')::integer, 0), 0),
    coalesce(p_input->'support_diversity', '{}'::jsonb),
    coalesce(p_input->'contradiction_diversity', 'null'::jsonb),
    nullif(p_input->>'last_reinforced_at', '')::timestamptz,
    nullif(p_input->>'last_contradicted_at', '')::timestamptz,
    nullif(p_input->>'stale_after', '')::timestamptz,
    nullif(p_input->>'created_by_run_id', '')::uuid,
    nullif(p_input->>'last_updated_by_run_id', '')::uuid
  )
  on conflict (organization_id, candidate_signature)
  where candidate_status <> 'retired' and signature_uniqueness_enabled
  do nothing
  returning *
  into inserted_row;

  if inserted_row.id is null then
    select *
    into existing_row
    from public.worksheet_pricing_pattern_shadow_candidates c
    where c.organization_id = resolved_organization_id
      and c.candidate_signature = resolved_candidate_signature
      and c.candidate_status <> 'retired'
    order by c.signature_uniqueness_enabled desc, c.created_at asc, c.id asc
    limit 1;

    if found then
      return jsonb_build_object(
        'candidate', to_jsonb(existing_row),
        'inserted', false
      );
    end if;
  end if;

  return jsonb_build_object(
    'candidate', to_jsonb(inserted_row),
    'inserted', true
  );
end;
$$;


ALTER FUNCTION "public"."upsert_worksheet_pricing_pattern_shadow_candidate"("p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_and_record_quote_publication_v1"("p_organization_id" "uuid", "p_quote_id" "uuid") RETURNS TABLE("quote_id" "uuid", "publication_basis_hash" "text", "pricing_basis_status" "text", "persisted_total" numeric, "quote_updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  quote_row public.project_quotes%rowtype;
  computed_subtotal numeric := 0;
  computed_optional_subtotal numeric := 0;
  computed_margin numeric := 0;
  computed_gst numeric := 0;
  computed_total numeric := 0;
  invalid_line_count integer := 0;
  invalid_source_value_count integer := 0;
  duplicate_source_link_count integer := 0;
  basis jsonb := '{}'::jsonb;
  basis_hash text;
begin
  if auth.uid() is null then raise exception 'Authentication is required'; end if;
  if not public.has_org_permission(p_organization_id, 'quotes.write') then
    raise exception 'Not authorized for this organization';
  end if;
  select * into quote_row from public.project_quotes quote
  where quote.organization_id = p_organization_id and quote.id = p_quote_id for update;
  if not found then raise exception 'Quote not found for organization'; end if;
  if quote_row.award_locked_at is not null then
    raise exception 'Award-locked quote revisions cannot be republished' using errcode = 'TS409';
  end if;

  select
    coalesce(sum(case when line.is_optional then 0 else round(line.quantity * line.rate, 2) end), 0),
    coalesce(sum(case when line.is_optional then round(line.quantity * line.rate, 2) else 0 end), 0),
    count(*) filter (where line.total <> round(line.quantity * line.rate, 2))
  into computed_subtotal, computed_optional_subtotal, invalid_line_count
  from public.project_quote_line_items line
  where line.organization_id = p_organization_id and line.quote_id = p_quote_id;

  select count(*)::integer into invalid_source_value_count
  from public.project_quote_line_items line
  join public.commercial_item_document_links link
    on link.organization_id = line.organization_id and link.document_kind = 'quote_line'
   and link.document_id = line.quote_id and link.document_line_id = line.id and link.link_role = 'source'
  join public.commercial_items item
    on item.organization_id = link.organization_id and item.id = link.commercial_item_id
  cross join lateral (
    select coalesce(item.quantity, 1::numeric) quantity,
      coalesce(item.unit, 'Item') unit,
      case when item.rate is not null then item.rate
        when item.total is not null and coalesce(item.quantity, 1::numeric) <> 0
          then item.total / coalesce(item.quantity, 1::numeric)
        else 0::numeric end rate
  ) effective_source
  where line.organization_id = p_organization_id and line.quote_id = p_quote_id
    and (
      line.pricing_source_kind <> case item.source_type
        when 'takeoff_measurement' then 'takeoff' else 'worksheet' end
      or round(effective_source.quantity, 3) <> round(line.quantity, 3)
      or effective_source.unit <> line.unit
      or round(effective_source.rate, 2) <> round(line.rate, 2)
      or round(effective_source.quantity * effective_source.rate, 2) <> line.total
    );

  select count(*)::integer into duplicate_source_link_count from (
    select link.document_line_id
    from public.commercial_item_document_links link
    where link.organization_id = p_organization_id and link.document_kind = 'quote_line'
      and link.document_id = p_quote_id and link.link_role = 'source'
    group by link.document_line_id having count(*) <> 1
  ) duplicates;

  computed_margin := computed_subtotal * (quote_row.margin_percent / 100);
  computed_gst := greatest(0, computed_subtotal + computed_margin + quote_row.contingency_amount - quote_row.discount_amount)
    * (quote_row.gst_percent / 100);
  computed_total := greatest(0, computed_subtotal + computed_margin + quote_row.contingency_amount - quote_row.discount_amount)
    + computed_gst;
  if invalid_line_count > 0 or invalid_source_value_count > 0 or duplicate_source_link_count > 0
    or quote_row.subtotal <> round(computed_subtotal, 2)
    or quote_row.optional_subtotal <> round(computed_optional_subtotal, 2)
    or quote_row.margin_amount <> round(computed_margin, 2)
    or quote_row.gst_amount <> round(computed_gst, 2)
    or quote_row.total_quote_price <> round(computed_total, 2)
  then raise exception 'Quote publication totals do not reconcile with persisted quote lines' using errcode = 'TS422';
  end if;

  select jsonb_build_object(
    'version', 2, 'quoteId', quote_row.id, 'lineCount', count(distinct line.id),
    'manualLineIds', coalesce(jsonb_agg(distinct line.id order by line.id)
      filter (where line.pricing_source_kind = 'manual'), '[]'::jsonb),
    'commercialItems', coalesce(jsonb_agg(distinct jsonb_build_object(
      'lineId', line.id, 'commercialItemId', item.id, 'sourceType', item.source_type,
      'workbookId', item.source_workbook_id, 'sheetId', item.source_sheet_id,
      'range', item.source_range, 'measurementId', item.source_takeoff_measurement_id,
      'sourceSignature', item.source_signature, 'sourceVersion', item.source_version
    )) filter (where item.id is not null), '[]'::jsonb),
    'workbookIds', coalesce(jsonb_agg(distinct item.source_workbook_id::text)
      filter (where item.source_workbook_id is not null), '[]'::jsonb),
    'takeoffMeasurementIds', coalesce(jsonb_agg(distinct item.source_takeoff_measurement_id::text)
      filter (where item.source_takeoff_measurement_id is not null), '[]'::jsonb),
    'subtotal', quote_row.subtotal, 'gst', quote_row.gst_amount,
    'total', quote_row.total_quote_price
  ) into basis
  from public.project_quote_line_items line
  left join public.commercial_item_document_links link
    on link.organization_id = line.organization_id and link.document_kind = 'quote_line'
   and link.document_id = line.quote_id and link.document_line_id = line.id and link.link_role = 'source'
  left join public.commercial_items item
    on item.organization_id = link.organization_id and item.id = link.commercial_item_id
  where line.organization_id = p_organization_id and line.quote_id = p_quote_id;

  basis_hash := md5(basis::text);
  update public.project_quotes quote set publication_basis_json = basis,
    publication_basis_hash = basis_hash, pricing_basis_status = 'current',
    pricing_basis_checked_at = timezone('utc', now()), published_at = timezone('utc', now())
  where quote.organization_id = p_organization_id and quote.id = p_quote_id
  returning quote.* into quote_row;
  return query select quote_row.id, basis_hash, 'current'::text,
    quote_row.total_quote_price, quote_row.updated_at;
end;
$$;


