CREATE OR REPLACE FUNCTION "public"."validate_commercial_item_locked_metadata_json"("p_locked_metadata" "jsonb") RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
declare
  locked_cell jsonb;
begin
  if jsonb_typeof(p_locked_metadata) <> 'object' then
    return false;
  end if;

  if not public.commercial_item_json_object_has_only_keys(
    p_locked_metadata,
    array[
      'version',
      'worksheetVersion',
      'sheetName',
      'rangeLabel',
      'worksheetMetadata',
      'cells'
    ]
  )
    or not public.commercial_item_json_object_has_required_keys(
      p_locked_metadata,
      array[
        'version',
        'worksheetVersion',
        'sheetName',
        'rangeLabel',
        'worksheetMetadata',
        'cells'
      ]
    ) then
    return false;
  end if;

  if p_locked_metadata->>'version' <> '1'
    or not public.commercial_item_json_is_non_negative_integer_like(p_locked_metadata->'worksheetVersion')
    or not public.commercial_item_json_value_is_type(p_locked_metadata->'sheetName', array['string'])
    or not public.commercial_item_json_value_is_type(p_locked_metadata->'rangeLabel', array['string'])
    or jsonb_typeof(p_locked_metadata->'worksheetMetadata') <> 'object'
    or jsonb_typeof(p_locked_metadata->'cells') <> 'array' then
    return false;
  end if;

  if btrim(coalesce(p_locked_metadata->>'sheetName', '')) = ''
    or btrim(coalesce(p_locked_metadata->>'rangeLabel', '')) = '' then
    return false;
  end if;

  for locked_cell in
    select value
    from jsonb_array_elements(p_locked_metadata->'cells')
  loop
    if jsonb_typeof(locked_cell) <> 'object' then
      return false;
    end if;

    if not public.commercial_item_json_object_has_only_keys(
      locked_cell,
      array[
        'cellKey',
        'rowId',
        'rowIndex',
        'columnId',
        'columnIndex',
        'formula',
        'value',
        'computedValue',
        'displayValue',
        'metadata'
      ]
    )
      or not public.commercial_item_json_object_has_required_keys(
        locked_cell,
        array[
          'cellKey',
          'rowId',
          'rowIndex',
          'columnId',
          'columnIndex',
          'formula',
          'value',
          'computedValue',
          'displayValue',
          'metadata'
        ]
      )
      or not public.commercial_item_json_value_is_type(locked_cell->'cellKey', array['string'])
      or not public.commercial_item_json_value_is_type(locked_cell->'rowId', array['string'])
      or not public.commercial_item_json_is_non_negative_integer_like(locked_cell->'rowIndex')
      or not public.commercial_item_json_value_is_type(locked_cell->'columnId', array['string'])
      or not public.commercial_item_json_is_non_negative_integer_like(locked_cell->'columnIndex')
      or not public.commercial_item_json_value_is_type(locked_cell->'formula', array['string', 'null'])
      or not public.commercial_item_json_value_is_type(locked_cell->'value', array['string', 'number', 'null'])
      or not public.commercial_item_json_value_is_type(locked_cell->'computedValue', array['string', 'number', 'null'])
      or not public.commercial_item_json_value_is_type(locked_cell->'displayValue', array['string'])
      or jsonb_typeof(coalesce(locked_cell->'metadata', '{}'::jsonb)) <> 'object' then
      return false;
    end if;
  end loop;

  return true;
end;
$$;


ALTER FUNCTION "public"."validate_commercial_item_locked_metadata_json"("p_locked_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_commercial_item_record"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
declare
  linked_project_source_opportunity_id uuid;
begin
  if new.project_id is not null then
    select p.source_opportunity_id
    into linked_project_source_opportunity_id
    from public.organization_projects p
    where p.id = new.project_id
      and p.organization_id = new.organization_id;

    if not found then
      raise exception 'Project not found for organization';
    end if;

    if linked_project_source_opportunity_id is distinct from new.opportunity_id then
      raise exception 'Commercial item project_id must belong to the same opportunity';
    end if;
  end if;

  if not public.validate_commercial_item_snapshot_json(new.snapshot_json) then
    raise exception 'snapshot_json failed commercial item validation';
  end if;

  if not public.validate_commercial_item_source_link_json(new.source_link_json) then
    raise exception 'source_link_json failed commercial item validation';
  end if;

  if new.source_type = 'worksheet_selection' then
    if not public.validate_commercial_item_locked_metadata_json(new.locked_metadata_json) then
      raise exception 'locked_metadata_json failed commercial item validation';
    end if;

    if new.source_takeoff_measurement_id is not null then
      raise exception 'Worksheet commercial items cannot contain Takeoff source identity';
    end if;

    if coalesce(new.source_link_json->>'workbookId', '') <> new.source_workbook_id::text then
      raise exception 'source_link_json workbookId must match source_workbook_id';
    end if;

    if coalesce(new.source_link_json->>'worksheetId', '') <> new.source_worksheet_id::text then
      raise exception 'source_link_json worksheetId must match source_worksheet_id';
    end if;

    if coalesce(new.source_link_json->>'sheetId', '') <> new.source_sheet_id::text then
      raise exception 'source_link_json sheetId must match source_sheet_id';
    end if;

    if coalesce(new.source_link_json->>'range', '') <> new.source_range then
      raise exception 'source_link_json range must match source_range';
    end if;

    if coalesce(nullif(new.source_link_json->>'worksheetVersion', ''), '0')::integer <> new.source_version then
      raise exception 'source_link_json worksheetVersion must match source_version';
    end if;

    if coalesce(new.snapshot_json->>'rangeLabel', '') <> new.source_range then
      raise exception 'snapshot_json rangeLabel must match source_range';
    end if;

    if coalesce(new.locked_metadata_json->>'rangeLabel', '') <> new.source_range then
      raise exception 'locked_metadata_json rangeLabel must match source_range';
    end if;

    if coalesce(nullif(new.locked_metadata_json->>'worksheetVersion', ''), '0')::integer <> new.source_version then
      raise exception 'locked_metadata_json worksheetVersion must match source_version';
    end if;
  elsif new.source_type = 'takeoff_measurement' then
    if not public.validate_takeoff_commercial_item_locked_metadata_json(new.locked_metadata_json) then
      raise exception 'locked_metadata_json failed Takeoff commercial item validation';
    end if;

    if new.source_takeoff_measurement_id is null
      or new.source_workbook_id is not null
      or new.source_worksheet_id is not null
      or new.source_sheet_id is not null
      or new.source_range is not null then
      raise exception 'Takeoff commercial items must contain only Takeoff source identity';
    end if;

    if new.snapshot_json->>'sourceType' <> new.source_type
      or new.source_link_json->>'sourceType' <> new.source_type then
      raise exception 'Takeoff JSON sourceType must match source_type';
    end if;

    if (new.snapshot_json->>'measurementId')::uuid <> new.source_takeoff_measurement_id
      or (new.source_link_json->>'measurementId')::uuid <> new.source_takeoff_measurement_id then
      raise exception 'Takeoff measurementId must match source_takeoff_measurement_id';
    end if;

    if (new.snapshot_json->>'measurementVersion')::integer <> new.source_version
      or (new.source_link_json->>'measurementVersion')::integer <> new.source_version then
      raise exception 'Takeoff measurementVersion must match source_version';
    end if;

    if (new.snapshot_json->>'drawingSetId')::uuid <> (new.source_link_json->>'drawingSetId')::uuid
      or (new.snapshot_json->>'pageId')::uuid <> (new.source_link_json->>'pageId')::uuid
      or (new.snapshot_json->>'measurementUpdatedAt')::timestamptz
        <> (new.source_link_json->>'measurementUpdatedAt')::timestamptz then
      raise exception 'Takeoff snapshot and source link provenance must match';
    end if;

    if (new.source_link_json->>'opportunityId')::uuid <> new.opportunity_id then
      raise exception 'Takeoff source link opportunityId must match opportunity_id';
    end if;

    if new.project_id is null then
      if new.source_link_json->>'ownerType' <> 'opportunity'
        or jsonb_typeof(new.source_link_json->'projectId') <> 'null' then
        raise exception 'Opportunity Takeoff source link must not contain project identity';
      end if;
    elsif new.source_link_json->>'ownerType' <> 'project'
      or (new.source_link_json->>'projectId')::uuid <> new.project_id then
      raise exception 'Project Takeoff source link must match project_id';
    end if;
  else
    raise exception 'Unsupported commercial item source_type';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."validate_commercial_item_record"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_commercial_item_snapshot_json"("p_snapshot" "jsonb") RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
declare
  snapshot_cell jsonb;
  snapshot_column jsonb;
  snapshot_row jsonb;
begin
  if p_snapshot->>'sourceType' = 'takeoff_measurement' then
    return public.validate_takeoff_commercial_item_snapshot_json(p_snapshot);
  end if;

  if jsonb_typeof(p_snapshot) <> 'object' then
    return false;
  end if;

  if not public.commercial_item_json_object_has_only_keys(
    p_snapshot,
    array[
      'version',
      'sheetName',
      'rangeLabel',
      'rowCount',
      'columnCount',
      'cellCount',
      'nonEmptyCellCount',
      'columns',
      'rows',
      'cells'
    ]
  )
    or not public.commercial_item_json_object_has_required_keys(
      p_snapshot,
      array[
        'version',
        'sheetName',
        'rangeLabel',
        'rowCount',
        'columnCount',
        'cellCount',
        'nonEmptyCellCount',
        'columns',
        'rows',
        'cells'
      ]
    ) then
    return false;
  end if;

  if p_snapshot->>'version' <> '1'
    or not public.commercial_item_json_value_is_type(p_snapshot->'sheetName', array['string'])
    or not public.commercial_item_json_value_is_type(p_snapshot->'rangeLabel', array['string'])
    or not public.commercial_item_json_is_non_negative_integer_like(p_snapshot->'rowCount')
    or not public.commercial_item_json_is_non_negative_integer_like(p_snapshot->'columnCount')
    or not public.commercial_item_json_is_non_negative_integer_like(p_snapshot->'cellCount')
    or not public.commercial_item_json_is_non_negative_integer_like(p_snapshot->'nonEmptyCellCount') then
    return false;
  end if;

  if btrim(coalesce(p_snapshot->>'sheetName', '')) = ''
    or btrim(coalesce(p_snapshot->>'rangeLabel', '')) = '' then
    return false;
  end if;

  if jsonb_typeof(p_snapshot->'columns') <> 'array'
    or jsonb_typeof(p_snapshot->'rows') <> 'array'
    or jsonb_typeof(p_snapshot->'cells') <> 'array' then
    return false;
  end if;

  for snapshot_column in
    select value
    from jsonb_array_elements(p_snapshot->'columns')
  loop
    if jsonb_typeof(snapshot_column) <> 'object' then
      return false;
    end if;

    if not public.commercial_item_json_object_has_only_keys(snapshot_column, array['id', 'index', 'label'])
      or not public.commercial_item_json_object_has_required_keys(snapshot_column, array['id', 'index', 'label'])
      or not public.commercial_item_json_value_is_type(snapshot_column->'id', array['string'])
      or not public.commercial_item_json_value_is_type(snapshot_column->'label', array['string'])
      or not public.commercial_item_json_is_non_negative_integer_like(snapshot_column->'index') then
      return false;
    end if;
  end loop;

  for snapshot_row in
    select value
    from jsonb_array_elements(p_snapshot->'rows')
  loop
    if jsonb_typeof(snapshot_row) <> 'object' then
      return false;
    end if;

    if not public.commercial_item_json_object_has_only_keys(snapshot_row, array['id', 'index'])
      or not public.commercial_item_json_object_has_required_keys(snapshot_row, array['id', 'index'])
      or not public.commercial_item_json_value_is_type(snapshot_row->'id', array['string'])
      or not public.commercial_item_json_is_non_negative_integer_like(snapshot_row->'index') then
      return false;
    end if;
  end loop;

  for snapshot_cell in
    select value
    from jsonb_array_elements(p_snapshot->'cells')
  loop
    if jsonb_typeof(snapshot_cell) <> 'object' then
      return false;
    end if;

    if not public.commercial_item_json_object_has_only_keys(
      snapshot_cell,
      array[
        'cellKey',
        'rowId',
        'rowIndex',
        'columnId',
        'columnIndex',
        'type',
        'value',
        'computedValue',
        'displayValue',
        'format'
      ]
    )
      or not public.commercial_item_json_object_has_required_keys(
        snapshot_cell,
        array[
          'cellKey',
          'rowId',
          'rowIndex',
          'columnId',
          'columnIndex',
          'type',
          'value',
          'computedValue',
          'displayValue',
          'format'
        ]
      ) then
      return false;
    end if;

    if snapshot_cell ? 'formula' or snapshot_cell ? 'metadata' then
      return false;
    end if;

    if not public.commercial_item_json_value_is_type(snapshot_cell->'cellKey', array['string'])
      or not public.commercial_item_json_value_is_type(snapshot_cell->'rowId', array['string'])
      or not public.commercial_item_json_is_non_negative_integer_like(snapshot_cell->'rowIndex')
      or not public.commercial_item_json_value_is_type(snapshot_cell->'columnId', array['string'])
      or not public.commercial_item_json_is_non_negative_integer_like(snapshot_cell->'columnIndex')
      or not public.commercial_item_json_value_is_type(snapshot_cell->'type', array['string'])
      or not public.commercial_item_json_value_is_type(snapshot_cell->'value', array['string', 'number', 'null'])
      or not public.commercial_item_json_value_is_type(snapshot_cell->'computedValue', array['string', 'number', 'null'])
      or not public.commercial_item_json_value_is_type(snapshot_cell->'displayValue', array['string'])
      or jsonb_typeof(coalesce(snapshot_cell->'format', '{}'::jsonb)) <> 'object' then
      return false;
    end if;

    if not public.commercial_item_json_object_has_only_keys(
      coalesce(snapshot_cell->'format', '{}'::jsonb),
      array['numberKind', 'textAlign', 'textWrapMode']
    )
      or not public.commercial_item_json_object_has_required_keys(
        coalesce(snapshot_cell->'format', '{}'::jsonb),
        array['numberKind', 'textAlign', 'textWrapMode']
      )
      or not public.commercial_item_json_value_is_type(snapshot_cell->'format'->'numberKind', array['string', 'null'])
      or not public.commercial_item_json_value_is_type(snapshot_cell->'format'->'textAlign', array['string', 'null'])
      or not public.commercial_item_json_value_is_type(snapshot_cell->'format'->'textWrapMode', array['string', 'null']) then
      return false;
    end if;
  end loop;

  return true;
end;
$$;


ALTER FUNCTION "public"."validate_commercial_item_snapshot_json"("p_snapshot" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_commercial_item_source_link_json"("p_source_link" "jsonb") RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
begin
  if p_source_link->>'sourceType' = 'takeoff_measurement' then
    return public.validate_takeoff_commercial_item_source_link_json(p_source_link);
  end if;

  if jsonb_typeof(p_source_link) <> 'object' then
    return false;
  end if;

  if not public.commercial_item_json_object_has_only_keys(
    p_source_link,
    array[
      'version',
      'sourceType',
      'ownerType',
      'opportunityId',
      'opportunitySlug',
      'projectId',
      'projectSlug',
      'quoteId',
      'variationId',
      'worksheetId',
      'workbookId',
      'sheetId',
      'worksheetName',
      'sheetName',
      'range',
      'rowCount',
      'columnCount',
      'cellCount',
      'worksheetVersion',
      'capturedAt'
    ]
  )
    or not public.commercial_item_json_object_has_required_keys(
      p_source_link,
      array[
        'version',
        'sourceType',
        'worksheetId',
        'workbookId',
        'sheetId',
        'worksheetName',
        'sheetName',
        'range',
        'rowCount',
        'columnCount',
        'cellCount',
        'worksheetVersion',
        'capturedAt'
      ]
    ) then
    return false;
  end if;

  if p_source_link->>'version' <> '1'
    or p_source_link->>'sourceType' <> 'worksheet_selection'
    or not public.commercial_item_json_value_is_type(p_source_link->'ownerType', array['string', 'null'])
    or not public.commercial_item_json_value_is_type(p_source_link->'opportunityId', array['string', 'null'])
    or not public.commercial_item_json_value_is_type(p_source_link->'opportunitySlug', array['string', 'null'])
    or not public.commercial_item_json_value_is_type(p_source_link->'projectId', array['string', 'null'])
    or not public.commercial_item_json_value_is_type(p_source_link->'projectSlug', array['string', 'null'])
    or not public.commercial_item_json_value_is_type(p_source_link->'quoteId', array['string', 'null'])
    or not public.commercial_item_json_value_is_type(p_source_link->'variationId', array['string', 'null'])
    or not public.commercial_item_json_value_is_type(p_source_link->'worksheetId', array['string'])
    or not public.commercial_item_json_value_is_type(p_source_link->'workbookId', array['string'])
    or not public.commercial_item_json_value_is_type(p_source_link->'sheetId', array['string'])
    or not public.commercial_item_json_value_is_type(p_source_link->'worksheetName', array['string'])
    or not public.commercial_item_json_value_is_type(p_source_link->'sheetName', array['string'])
    or not public.commercial_item_json_value_is_type(p_source_link->'range', array['string'])
    or not public.commercial_item_json_is_non_negative_integer_like(p_source_link->'rowCount')
    or not public.commercial_item_json_is_non_negative_integer_like(p_source_link->'columnCount')
    or not public.commercial_item_json_is_non_negative_integer_like(p_source_link->'cellCount')
    or not public.commercial_item_json_is_non_negative_integer_like(p_source_link->'worksheetVersion') then
    return false;
  end if;

  if coalesce(p_source_link->>'ownerType', '') not in ('', 'opportunity', 'variation') then
    return false;
  end if;

  if btrim(coalesce(p_source_link->>'worksheetName', '')) = ''
    or btrim(coalesce(p_source_link->>'sheetName', '')) = ''
    or btrim(coalesce(p_source_link->>'range', '')) = '' then
    return false;
  end if;

  if p_source_link ? 'formula'
    or p_source_link ? 'metadata'
    or p_source_link ? 'worksheetMetadata'
    or p_source_link ? 'cells' then
    return false;
  end if;

  begin
    perform (p_source_link->>'capturedAt')::timestamptz;
  exception
    when others then
      return false;
  end;

  return true;
end;
$$;


ALTER FUNCTION "public"."validate_commercial_item_source_link_json"("p_source_link" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_commercial_lineage_edge"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  from_scope record;
  to_scope record;
begin
  if not public.commercial_lineage_relationship_is_allowed(
    new.from_entity_type, new.to_entity_type, new.relationship_type
  ) then
    raise exception 'commercial_lineage:unsupported_relationship_pair' using errcode = '23514';
  end if;

  select * into from_scope
  from public.resolve_commercial_lineage_entity_scope(new.from_entity_type, new.from_entity_id);
  if not found then
    raise exception 'commercial_lineage:missing_from_entity' using errcode = '23503';
  end if;

  select * into to_scope
  from public.resolve_commercial_lineage_entity_scope(new.to_entity_type, new.to_entity_id);
  if not found then
    raise exception 'commercial_lineage:missing_to_entity' using errcode = '23503';
  end if;

  if from_scope.organization_id is distinct from new.organization_id
    or to_scope.organization_id is distinct from new.organization_id then
    raise exception 'commercial_lineage:cross_organization_edge' using errcode = '23514';
  end if;

  if from_scope.project_id is not null and to_scope.project_id is not null
    and from_scope.project_id is distinct from to_scope.project_id then
    raise exception 'commercial_lineage:project_mismatch' using errcode = '23514';
  end if;

  if new.project_id is not null
    and new.project_id is distinct from coalesce(from_scope.project_id, to_scope.project_id) then
    raise exception 'commercial_lineage:edge_project_mismatch' using errcode = '23514';
  end if;

  new.project_id := coalesce(new.project_id, from_scope.project_id, to_scope.project_id);
  return new;
end;
$$;


ALTER FUNCTION "public"."validate_commercial_lineage_edge"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_document_activity_event_scope"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
begin
  if new.entity_link_id is not null and not exists (
    select 1
    from public.document_workspace_entities entity_link
    where entity_link.id = new.entity_link_id
      and entity_link.organization_id = new.organization_id
      and entity_link.workspace_id = new.workspace_id
  ) then
    raise exception 'Document activity entity link is outside the event workspace.'
      using errcode = '23503';
  end if;

  if new.node_id is not null and not exists (
    select 1
    from public.document_nodes node
    where node.id = new.node_id
      and node.organization_id = new.organization_id
      and node.workspace_id = new.workspace_id
  ) then
    raise exception 'Document activity node is outside the event workspace.'
      using errcode = '23503';
  end if;

  if new.version_id is not null and not exists (
    select 1
    from public.document_versions version
    where version.id = new.version_id
      and version.organization_id = new.organization_id
      and version.workspace_id = new.workspace_id
  ) then
    raise exception 'Document activity version is outside the event workspace.'
      using errcode = '23503';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."validate_document_activity_event_scope"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_document_current_version_progression"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  previous_version_number integer;
  next_version_number integer;
begin
  if old.current_version_id is null
    or new.current_version_id is null
    or old.current_version_id = new.current_version_id
  then
    return new;
  end if;

  select version.version_number
  into previous_version_number
  from public.document_versions version
  where version.organization_id = old.organization_id
    and version.workspace_id = old.workspace_id
    and version.node_id = old.id
    and version.id = old.current_version_id;

  select version.version_number
  into next_version_number
  from public.document_versions version
  where version.organization_id = new.organization_id
    and version.workspace_id = new.workspace_id
    and version.node_id = new.id
    and version.id = new.current_version_id;

  if previous_version_number is null
    or next_version_number is null
    or next_version_number <= previous_version_number
  then
    raise exception 'Current document version must advance monotonically.'
      using errcode = '23514';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."validate_document_current_version_progression"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_document_node_active_hierarchy"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
begin
  if new.deleted_at is null
    and new.parent_node_id is not null
    and not exists (
      select 1
      from public.document_nodes parent
      where parent.organization_id = new.organization_id
        and parent.workspace_id = new.workspace_id
        and parent.id = new.parent_node_id
        and parent.kind = 'folder'
        and parent.deleted_at is null
    )
  then
    raise exception 'An active document node requires an active parent folder.'
      using errcode = '23514';
  end if;

  if new.kind = 'folder'
    and new.deleted_at is not null
    and exists (
      select 1
      from public.document_nodes child
      where child.organization_id = new.organization_id
        and child.workspace_id = new.workspace_id
        and child.parent_node_id = new.id
        and child.deleted_at is null
    )
  then
    raise exception 'A deleted folder cannot contain active document nodes.'
      using errcode = '23514';
  end if;

  return null;
end;
$$;


ALTER FUNCTION "public"."validate_document_node_active_hierarchy"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_document_node_hierarchy"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  parent_row public.document_nodes%rowtype;
  version_row public.document_versions%rowtype;
begin
  if tg_op = 'UPDATE' and (
    new.organization_id <> old.organization_id
    or new.workspace_id <> old.workspace_id
    or new.kind <> old.kind
  ) then
    raise exception 'Document node organization, workspace, and kind are immutable.'
      using errcode = '55000';
  end if;

  if new.parent_node_id is not null and (
    tg_op = 'INSERT'
    or old.parent_node_id is distinct from new.parent_node_id
  ) then
    select *
    into parent_row
    from public.document_nodes parent
    where parent.organization_id = new.organization_id
      and parent.workspace_id = new.workspace_id
      and parent.id = new.parent_node_id;

    if not found then
      raise exception 'Document parent folder was not found in this workspace.'
        using errcode = '23503';
    end if;

    if parent_row.kind <> 'folder' then
      raise exception 'A file cannot be used as a document parent.'
        using errcode = '23514';
    end if;

    if parent_row.deleted_at is not null then
      raise exception 'A deleted folder cannot be used as a document parent.'
        using errcode = '23514';
    end if;
  end if;

  if new.kind = 'folder' and new.current_version_id is not null then
    raise exception 'Folders cannot have a current file version.'
      using errcode = '23514';
  end if;

  if new.current_version_id is not null
    and (
      tg_op = 'INSERT'
      or old.current_version_id is distinct from new.current_version_id
    )
  then
    select *
    into version_row
    from public.document_versions version
    where version.organization_id = new.organization_id
      and version.workspace_id = new.workspace_id
      and version.node_id = new.id
      and version.id = new.current_version_id;

    if not found or version_row.upload_state <> 'active' then
      raise exception 'Current document version must be an active version of this file.'
        using errcode = '23514';
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."validate_document_node_hierarchy"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_document_version"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  node_row public.document_nodes%rowtype;
begin
  select node.*
  into node_row
  from public.document_nodes node
  where node.organization_id = new.organization_id
    and node.workspace_id = new.workspace_id
    and node.id = new.node_id;

  if not found or node_row.kind <> 'file' then
    raise exception 'Document versions must belong to a file node.';
  end if;

  if tg_op = 'UPDATE' then
    if new.organization_id <> old.organization_id
      or new.workspace_id <> old.workspace_id
      or new.node_id <> old.node_id
      or new.version_number <> old.version_number
      or new.storage_key <> old.storage_key
      or new.uploaded_by <> old.uploaded_by
      or new.initiated_at <> old.initiated_at
      or new.created_at <> old.created_at
      or new.upload_idempotency_key is distinct from old.upload_idempotency_key
      or new.upload_expires_at is distinct from old.upload_expires_at
      or new.upload_request_fingerprint is distinct from old.upload_request_fingerprint
      or new.replaces_version_id is distinct from old.replaces_version_id
    then
      raise exception 'Document version identity is immutable; upload reservation metadata is immutable.';
    end if;

    if old.upload_state in ('active', 'purge_pending', 'purged')
      and (
        new.byte_size is distinct from old.byte_size
        or new.claimed_mime_type is distinct from old.claimed_mime_type
        or new.verified_mime_type is distinct from old.verified_mime_type
        or new.file_extension is distinct from old.file_extension
        or new.sha256_checksum is distinct from old.sha256_checksum
        or new.uploaded_at is distinct from old.uploaded_at
        or new.verified_at is distinct from old.verified_at
        or new.storage_object_id is distinct from old.storage_object_id
        or new.storage_etag is distinct from old.storage_etag
        or new.activated_at is distinct from old.activated_at
      )
    then
      raise exception 'Activated document content metadata is immutable.';
    end if;

    if old.upload_state in ('failed', 'abandoned', 'purged')
      and new.upload_state <> old.upload_state
    then
      raise exception 'Terminal document upload states cannot transition.';
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."validate_document_version"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_opportunity_accepted_quote_revision"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  accepted public.project_quotes%rowtype;
  series public.opportunity_quote_series%rowtype;
begin
  if new.accepted_quote_revision_id is null then
    return new;
  end if;
  select * into accepted
  from public.project_quotes quote
  where quote.organization_id = new.organization_id
    and quote.id = new.accepted_quote_revision_id;
  if not found or accepted.originating_opportunity_id is distinct from new.id
    or accepted.quote_series_id is null or accepted.status <> 'Accepted'
  then
    raise exception 'Accepted revision must be an Accepted tender revision for this Opportunity'
      using errcode = 'TS422';
  end if;
  select * into series
  from public.opportunity_quote_series candidate
  where candidate.organization_id = new.organization_id
    and candidate.id = accepted.quote_series_id
    and candidate.opportunity_id = new.id
    and candidate.recipient_client_id is not null;
  if not found then
    raise exception 'Accepted revision does not have an authoritative recipient series'
      using errcode = 'TS422';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."validate_opportunity_accepted_quote_revision"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_opportunity_lifecycle_insert"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  opportunity_workspace_id uuid;
  project_source_opportunity_id uuid;
begin
  select opportunity.workspace_project_id
  into opportunity_workspace_id
  from public.organization_opportunities opportunity
  where opportunity.organization_id = new.organization_id
    and opportunity.id = new.opportunity_id
  for key share;

  if not found
    or opportunity_workspace_id is distinct from new.original_workspace_project_id
  then
    raise exception
      'Lifecycle workspace must equal the Opportunity workspace at creation'
      using errcode = 'TS409';
  end if;

  select project.source_opportunity_id
  into project_source_opportunity_id
  from public.organization_projects project
  where project.organization_id = new.organization_id
    and project.id = new.original_workspace_project_id
  for key share;

  if not found
    or project_source_opportunity_id is distinct from new.opportunity_id
  then
    raise exception
      'Lifecycle workspace must belong to the Opportunity'
      using errcode = 'TS409';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."validate_opportunity_lifecycle_insert"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_opportunity_promotion_event_insert"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  lifecycle_row public.opportunity_lifecycles%rowtype;
  opportunity_row public.organization_opportunities%rowtype;
  quote_row public.project_quotes%rowtype;
  mapping_row public.opportunity_final_projects%rowtype;
  currency_value text;
  evidence_value jsonb;
begin
  select * into lifecycle_row
  from public.opportunity_lifecycles lifecycle
  where lifecycle.organization_id = new.organization_id
    and lifecycle.id = new.lifecycle_id;

  if not found
    or lifecycle_row.opportunity_id <> new.opportunity_id
    or lifecycle_row.original_workspace_project_id <> new.project_id
    or lifecycle_row.strategy <> new.strategy
    or lifecycle_row.strategy_version <> new.strategy_version
  then
    raise exception 'Promotion event contradicts its lifecycle record'
      using errcode = 'TS409';
  end if;

  select * into opportunity_row
  from public.organization_opportunities opportunity
  where opportunity.organization_id = new.organization_id
    and opportunity.id = new.opportunity_id;

  if not found
    or opportunity_row.workspace_project_id is distinct from new.project_id
    or opportunity_row.converted_project_id is distinct from new.project_id
    or opportunity_row.stage <> 'Won'
  then
    raise exception 'Promotion event contradicts Opportunity state'
      using errcode = 'TS409';
  end if;

  select * into quote_row
  from public.project_quotes quote
  where quote.organization_id = new.organization_id
    and quote.id = new.accepted_quote_id;

  if not found
    or quote_row.originating_opportunity_id is distinct from new.opportunity_id
    or quote_row.project_id is distinct from new.project_id
    or quote_row.status <> 'Accepted'
    or quote_row.subtotal < 0
    or quote_row.gst_amount < 0
    or quote_row.total_quote_price < 0
  then
    raise exception 'Promotion event contradicts accepted quote state'
      using errcode = 'TS409';
  end if;

  select * into mapping_row
  from public.opportunity_final_projects final_project
  where final_project.organization_id = new.organization_id
    and final_project.opportunity_id = new.opportunity_id;

  if not found
    or mapping_row.project_id <> new.project_id
    or mapping_row.accepted_quote_id is distinct from new.accepted_quote_id
  then
    raise exception 'Promotion event contradicts final Project mapping'
      using errcode = 'TS409';
  end if;

  select coalesce(
    nullif(upper(btrim(to_jsonb(organization) ->> 'default_currency')), ''),
    'NZD'
  ) into currency_value
  from public.organizations organization
  where organization.id = new.organization_id;

  evidence_value := jsonb_build_object(
    'quote_line_count', (select count(*) from public.project_quote_line_items line
      where line.organization_id = new.organization_id
        and line.quote_id = new.accepted_quote_id
        and line.project_id = new.project_id),
    'commercial_item_count', (select count(*) from public.commercial_items item
      where item.organization_id = new.organization_id
        and item.opportunity_id = new.opportunity_id
        and item.project_id = new.project_id),
    'cost_item_count', (select count(*) from public.cost_items cost
      where cost.organization_id = new.organization_id
        and cost.source_document_kind = 'project_quote'
        and cost.source_document_id = new.accepted_quote_id
        and cost.project_id = new.project_id
        and cost.is_current),
    'task_count', (select count(*) from public.project_job_todos task
      where task.organization_id = new.organization_id
        and task.project_id = new.project_id
        and task.deleted_at is null),
    'takeoff_page_count', (select count(*) from public.takeoff_pages page
      where page.organization_id = new.organization_id
        and page.project_id = new.project_id),
    'measurement_count', (select count(*) from public.takeoff_measurements measurement
      where measurement.organization_id = new.organization_id
        and measurement.project_id = new.project_id
        and measurement.archived_at is null),
    'drawing_set_count', (select count(*) from public.project_drawing_sets drawing
      where drawing.organization_id = new.organization_id
        and drawing.project_id = new.project_id),
    'scope_run_count', (select count(*) from public.scope_runs scope
      where scope.organization_id = new.organization_id
        and scope.project_id = new.project_id),
    'trade_pack_count', (select count(*) from public.trade_packs pack
      where pack.organization_id = new.organization_id
        and pack.project_id = new.project_id),
    'document_workspace_ids', coalesce((
      select jsonb_agg(link.workspace_id order by link.workspace_id)
      from public.document_workspace_entities link
      where link.organization_id = new.organization_id
        and (link.opportunity_id = new.opportunity_id or link.project_id = new.project_id)
    ), '[]'::jsonb)
  );

  new.contract_subtotal := quote_row.subtotal;
  new.contract_tax := quote_row.gst_amount;
  new.contract_total := quote_row.total_quote_price;
  new.contract_currency := currency_value;
  new.structural_evidence := evidence_value;
  new.evidence_hash := encode(extensions.digest(convert_to(
    jsonb_build_object(
      'organization_id', new.organization_id,
      'opportunity_id', new.opportunity_id,
      'project_id', new.project_id,
      'accepted_quote_id', new.accepted_quote_id,
      'subtotal', quote_row.subtotal,
      'tax', quote_row.gst_amount,
      'total', quote_row.total_quote_price,
      'currency', currency_value,
      'structure', evidence_value
    )::text,
    'UTF8'
  ), 'sha256'), 'hex');

  return new;
end;
$$;


ALTER FUNCTION "public"."validate_opportunity_promotion_event_insert"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_opportunity_promotion_shadow_update"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
begin
  if old.status <> 'pre_observed'
    or new.status not in ('completed', 'comparison_error')
    or new.id is distinct from old.id
    or new.organization_id is distinct from old.organization_id
    or new.opportunity_id is distinct from old.opportunity_id
    or new.workspace_project_id is distinct from old.workspace_project_id
    or new.accepted_quote_id is distinct from old.accepted_quote_id
    or new.lifecycle_strategy is distinct from old.lifecycle_strategy
    or new.lifecycle_strategy_version is distinct from old.lifecycle_strategy_version
    or new.evaluator_version is distinct from old.evaluator_version
    or new.conversion_correlation_id is distinct from old.conversion_correlation_id
    or new.observation_kind is distinct from old.observation_kind
    or new.eligibility_result is distinct from old.eligibility_result
    or new.eligibility_failure_codes is distinct from old.eligibility_failure_codes
    or new.predicted_final_project_identity_rule
      is distinct from old.predicted_final_project_identity_rule
    or new.pre_snapshot is distinct from old.pre_snapshot
    or new.immutable_payload_hash is distinct from old.immutable_payload_hash
    or new.pre_observed_at is distinct from old.pre_observed_at
    or new.created_by is distinct from old.created_by
    or new.created_at is distinct from old.created_at
  then
    raise exception 'Opportunity promotion shadow observations are immutable'
      using errcode = 'TS409';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."validate_opportunity_promotion_shadow_update"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_opportunity_quote_series_revision"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  revision public.project_quotes%rowtype;
begin
  if new.current_revision_id is null then
    return new;
  end if;

  select * into revision
  from public.project_quotes quote
  where quote.organization_id = new.organization_id
    and quote.id = new.current_revision_id;

  if not found
    or revision.quote_series_id is distinct from new.id
    or revision.originating_opportunity_id is distinct from new.opportunity_id
    or revision.revision_kind <> 'tender'
  then
    raise exception 'Current quote revision must be a tender revision in the same Opportunity Quote Series'
      using errcode = '23514';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."validate_opportunity_quote_series_revision"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_organization_accounting_route_mapping"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  v_account public.organization_cost_codes%rowtype;
  v_project_organization_id uuid;
begin
  new.provider := lower(trim(new.provider));

  select * into v_account
  from public.organization_cost_codes
  where id = new.organization_cost_code_id;

  if not found
    or v_account.organization_id <> new.organization_id
    or v_account.external_provider is distinct from new.provider then
    raise exception 'The accounting account must belong to the same organization and provider.';
  end if;

  if new.project_id is not null then
    select organization_id into v_project_organization_id
    from public.organization_projects
    where id = new.project_id;
    if v_project_organization_id is distinct from new.organization_id then
      raise exception 'The accounting route project must belong to the same organization.';
    end if;
  end if;

  new.updated_at := now();
  return new;
end;
$$;


ALTER FUNCTION "public"."validate_organization_accounting_route_mapping"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_pricing_workbook_owner_lineage"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  resolved_project_source_opportunity_id uuid;
begin
  if new.project_id is not null then
    select project.source_opportunity_id into resolved_project_source_opportunity_id
    from public.organization_projects project
    where project.id = new.project_id and project.organization_id = new.organization_id;

    if not found or resolved_project_source_opportunity_id is distinct from new.opportunity_id then
      raise exception 'Project worksheet opportunity lineage is invalid.';
    end if;
  end if;

  if new.variation_id is not null and not exists (
    select 1 from public.project_variations variation
    where variation.id = new.variation_id
      and variation.organization_id = new.organization_id
      and variation.project_id = new.project_id
  ) then
    raise exception 'Variation worksheet lineage is invalid.';
  end if;

  if new.quote_id is not null and not exists (
    select 1 from public.project_quotes quote
    where quote.id = new.quote_id
      and quote.organization_id = new.organization_id
      and quote.project_id = new.project_id
      and quote.originating_opportunity_id = new.opportunity_id
  ) then
    raise exception 'Quote worksheet lineage is invalid.';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."validate_pricing_workbook_owner_lineage"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_project_purchase_order_assignment"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  purchase_order_project_id uuid;
  purchase_order_organization_id uuid;
  member_organization_id uuid;
begin
  select po.project_id, po.organization_id
  into purchase_order_project_id, purchase_order_organization_id
  from public.project_purchase_orders po
  where po.id = new.purchase_order_id;

  if purchase_order_project_id is null then
    raise exception 'Purchase order not found for assignment.';
  end if;

  select m.organization_id
  into member_organization_id
  from public.organization_members m
  where m.id = new.organization_member_id;

  if member_organization_id is null then
    raise exception 'Organization member not found for assignment.';
  end if;

  if purchase_order_organization_id <> new.organization_id then
    raise exception 'Assignment organization does not match purchase order organization.';
  end if;

  if purchase_order_project_id <> new.project_id then
    raise exception 'Assignment project does not match purchase order project.';
  end if;

  if member_organization_id <> new.organization_id then
    raise exception 'Assignment organization does not match member organization.';
  end if;

  if not exists (
    select 1
    from public.project_members pm
    where pm.organization_id = new.organization_id
      and pm.project_id = new.project_id
      and pm.organization_member_id = new.organization_member_id
      and pm.is_active = true
  ) then
    raise exception 'Organization member must be assigned to the project before being assigned to the purchase order.';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."validate_project_purchase_order_assignment"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_project_quote_canonical_ownership"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  resolved_project_source_opportunity_id uuid;
begin
  if new.originating_opportunity_id is null and new.project_id is null then
    raise exception 'Commercial quote must have either originating_opportunity_id or project_id';
  end if;

  if new.originating_opportunity_id is not null and not exists (
    select 1
    from public.organization_opportunities opportunity
    where opportunity.id = new.originating_opportunity_id
      and opportunity.organization_id = new.organization_id
  ) then
    raise exception 'Originating opportunity not found for organization';
  end if;

  if new.project_id is not null then
    select project.source_opportunity_id
    into resolved_project_source_opportunity_id
    from public.organization_projects project
    where project.id = new.project_id
      and project.organization_id = new.organization_id;

    if not found then
      raise exception 'Project not found for organization';
    end if;

    if resolved_project_source_opportunity_id is not null
      and new.originating_opportunity_id is not null
      and resolved_project_source_opportunity_id <> new.originating_opportunity_id then
      raise exception 'Project must belong to the same originating opportunity';
    end if;
  end if;

  if new.source_opportunity_id is null then
    new.source_opportunity_id := new.originating_opportunity_id;
  elsif new.originating_opportunity_id is not null and new.source_opportunity_id <> new.originating_opportunity_id then
    raise exception 'source_opportunity_id must match originating_opportunity_id';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."validate_project_quote_canonical_ownership"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_project_quote_line_item_canonical_ownership"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  quote_row public.project_quotes%rowtype;
begin
  select *
  into quote_row
  from public.project_quotes quote
  where quote.id = new.quote_id
    and quote.organization_id = new.organization_id;

  if not found then
    raise exception 'Quote not found for organization';
  end if;

  if new.project_id is distinct from quote_row.project_id then
    raise exception 'Quote line project_id must match quote project_id';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."validate_project_quote_line_item_canonical_ownership"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_project_quote_revision_lineage"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  predecessor public.project_quotes%rowtype;
begin
  if new.predecessor_quote_id is null then
    if new.revision_number <> 1 then
      raise exception 'Root quote revision_number must be 1' using errcode = '23514';
    end if;
    return new;
  end if;

  if new.predecessor_quote_id = new.id then
    raise exception 'Quote revision cannot be its own predecessor' using errcode = '23514';
  end if;

  select * into predecessor
  from public.project_quotes quote
  where quote.organization_id = new.organization_id
    and quote.id = new.predecessor_quote_id;

  if not found
    or predecessor.originating_opportunity_id is distinct from new.originating_opportunity_id
    or predecessor.project_id is distinct from new.project_id
  then
    raise exception 'Quote predecessor must belong to the same organization, Opportunity, and Project'
      using errcode = '23514';
  end if;

  if new.revision_number <> predecessor.revision_number + 1 then
    raise exception 'Quote revision_number must follow its predecessor' using errcode = '23514';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."validate_project_quote_revision_lineage"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_project_quote_series_ownership"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  series public.opportunity_quote_series%rowtype;
begin
  if new.quote_series_id is null then
    return new;
  end if;

  select * into series
  from public.opportunity_quote_series candidate
  where candidate.organization_id = new.organization_id
    and candidate.id = new.quote_series_id;

  if not found
    or new.originating_opportunity_id is distinct from series.opportunity_id
    or new.revision_kind <> 'tender'
  then
    raise exception 'Quote revision must belong to the same organization, Opportunity, and tender series'
      using errcode = '23514';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."validate_project_quote_series_ownership"() OWNER TO "postgres";


