CREATE OR REPLACE FUNCTION "public"."validate_takeoff_commercial_item_snapshot_json"("p_snapshot" "jsonb") RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
declare
  commercial_quantity numeric;
  commercial_rate numeric;
  commercial_total numeric;
begin
  if jsonb_typeof(p_snapshot) <> 'object' then
    return false;
  end if;

  if not public.commercial_item_json_object_has_only_keys(
    p_snapshot,
    array[
      'version',
      'sourceType',
      'measurementId',
      'measurementVersion',
      'measurementUpdatedAt',
      'measurementKind',
      'drawingSetId',
      'pageId',
      'measurementName',
      'measurementDescription',
      'displayQuantity',
      'displayUnit',
      'commercialDescription',
      'commercialQuantity',
      'commercialRate',
      'commercialTotal'
    ]
  )
    or not public.commercial_item_json_object_has_required_keys(
      p_snapshot,
      array[
        'version',
        'sourceType',
        'measurementId',
        'measurementVersion',
        'measurementUpdatedAt',
        'measurementKind',
        'drawingSetId',
        'pageId',
        'measurementName',
        'measurementDescription',
        'displayQuantity',
        'displayUnit',
        'commercialDescription',
        'commercialQuantity',
        'commercialRate',
        'commercialTotal'
      ]
    ) then
    return false;
  end if;

  if jsonb_typeof(p_snapshot->'version') <> 'number'
    or p_snapshot->>'version' <> '1'
    or p_snapshot->>'sourceType' <> 'takeoff_measurement'
    or not public.commercial_item_json_is_uuid_string(p_snapshot->'measurementId')
    or not public.commercial_item_json_is_positive_integer(p_snapshot->'measurementVersion')
    or not public.commercial_item_json_is_timestamp_string(p_snapshot->'measurementUpdatedAt')
    or coalesce(p_snapshot->>'measurementKind', '') not in ('line', 'area', 'count')
    or not public.commercial_item_json_is_uuid_string(p_snapshot->'drawingSetId')
    or not public.commercial_item_json_is_uuid_string(p_snapshot->'pageId')
    or not public.commercial_item_json_value_is_type(p_snapshot->'measurementName', array['string'])
    or not public.commercial_item_json_value_is_type(p_snapshot->'measurementDescription', array['string'])
    or not public.commercial_item_json_is_non_negative_number(p_snapshot->'displayQuantity')
    or not public.commercial_item_json_value_is_type(p_snapshot->'displayUnit', array['string'])
    or not public.commercial_item_json_value_is_type(p_snapshot->'commercialDescription', array['string'])
    or not public.commercial_item_json_is_non_negative_number(p_snapshot->'commercialQuantity')
    or not public.commercial_item_json_is_non_negative_number(p_snapshot->'commercialRate')
    or not public.commercial_item_json_is_non_negative_number(p_snapshot->'commercialTotal') then
    return false;
  end if;

  if btrim(coalesce(p_snapshot->>'measurementName', '')) = ''
    or btrim(coalesce(p_snapshot->>'displayUnit', '')) = ''
    or btrim(coalesce(p_snapshot->>'commercialDescription', '')) = '' then
    return false;
  end if;

  commercial_quantity := (p_snapshot->>'commercialQuantity')::numeric;
  commercial_rate := (p_snapshot->>'commercialRate')::numeric;
  commercial_total := (p_snapshot->>'commercialTotal')::numeric;

  if (p_snapshot->>'displayQuantity')::numeric <> commercial_quantity
    or round(commercial_quantity * commercial_rate, 2) <> commercial_total then
    return false;
  end if;

  return true;
exception
  when others then
    return false;
end;
$$;


ALTER FUNCTION "public"."validate_takeoff_commercial_item_snapshot_json"("p_snapshot" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_takeoff_commercial_item_source_link_json"("p_source_link" "jsonb") RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
begin
  if jsonb_typeof(p_source_link) <> 'object' then
    return false;
  end if;

  if not public.commercial_item_json_object_has_only_keys(
    p_source_link,
    array[
      'sourceType',
      'measurementId',
      'measurementVersion',
      'drawingSetId',
      'measurementUpdatedAt',
      'pageId',
      'ownerType',
      'ownerSlug',
      'opportunityId',
      'projectId',
      'dataProjectId',
      'capturedAt'
    ]
  )
    or not public.commercial_item_json_object_has_required_keys(
      p_source_link,
      array[
        'sourceType',
        'measurementId',
        'measurementVersion',
        'drawingSetId',
        'measurementUpdatedAt',
        'pageId',
        'ownerType',
        'ownerSlug',
        'opportunityId',
        'projectId',
        'dataProjectId',
        'capturedAt'
      ]
    ) then
    return false;
  end if;

  if p_source_link->>'sourceType' <> 'takeoff_measurement'
    or not public.commercial_item_json_is_uuid_string(p_source_link->'measurementId')
    or not public.commercial_item_json_is_positive_integer(p_source_link->'measurementVersion')
    or not public.commercial_item_json_is_uuid_string(p_source_link->'drawingSetId')
    or not public.commercial_item_json_is_timestamp_string(p_source_link->'measurementUpdatedAt')
    or not public.commercial_item_json_is_uuid_string(p_source_link->'pageId')
    or coalesce(p_source_link->>'ownerType', '') not in ('opportunity', 'project')
    or not public.commercial_item_json_value_is_type(p_source_link->'ownerSlug', array['string'])
    or not public.commercial_item_json_is_uuid_string(p_source_link->'opportunityId')
    or not public.commercial_item_json_value_is_type(p_source_link->'projectId', array['string', 'null'])
    or not public.commercial_item_json_is_uuid_string(p_source_link->'dataProjectId')
    or not public.commercial_item_json_is_timestamp_string(p_source_link->'capturedAt') then
    return false;
  end if;

  if btrim(coalesce(p_source_link->>'ownerSlug', '')) = '' then
    return false;
  end if;

  if p_source_link->>'ownerType' = 'opportunity'
    and jsonb_typeof(p_source_link->'projectId') <> 'null' then
    return false;
  end if;

  if p_source_link->>'ownerType' = 'project'
    and not public.commercial_item_json_is_uuid_string(p_source_link->'projectId') then
    return false;
  end if;

  return true;
end;
$$;


ALTER FUNCTION "public"."validate_takeoff_commercial_item_source_link_json"("p_source_link" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_takeoff_measurement_consistency"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  page_row public.takeoff_pages%rowtype;
  calibration_row public.takeoff_calibrations%rowtype;
  group_row public.takeoff_measurement_groups%rowtype;
begin
  select *
  into page_row
  from public.takeoff_pages
  where id = new.page_id;

  if page_row.id is null then
    raise exception 'Takeoff measurement page does not exist.';
  end if;

  if page_row.organization_id <> new.organization_id then
    raise exception 'Takeoff measurement organization_id must match page organization_id.';
  end if;

  if page_row.project_id <> new.project_id then
    raise exception 'Takeoff measurement project_id must match page project_id.';
  end if;

  if page_row.drawing_set_id <> new.drawing_set_id then
    raise exception 'Takeoff measurement drawing_set_id must match page drawing_set_id.';
  end if;

  if new.calibration_id is not null then
    select *
    into calibration_row
    from public.takeoff_calibrations
    where id = new.calibration_id;

    if calibration_row.id is null then
      raise exception 'Takeoff measurement calibration does not exist.';
    end if;

    if calibration_row.page_id <> new.page_id then
      raise exception 'Takeoff measurement calibration must belong to the same page.';
    end if;

    if calibration_row.project_id <> new.project_id or calibration_row.organization_id <> new.organization_id then
      raise exception 'Takeoff measurement calibration must belong to the same organization and project.';
    end if;
  end if;

  if new.group_id is not null then
    select *
    into group_row
    from public.takeoff_measurement_groups
    where id = new.group_id;

    if group_row.id is null then
      raise exception 'Takeoff measurement group does not exist.';
    end if;

    if group_row.project_id <> new.project_id or group_row.organization_id <> new.organization_id then
      raise exception 'Takeoff measurement group must belong to the same organization and project.';
    end if;
  end if;

  if new.opportunity_id is not null and page_row.opportunity_id is not null and new.opportunity_id <> page_row.opportunity_id then
    raise exception 'Takeoff measurement opportunity_id must match page opportunity_id when page opportunity_id is present.';
  end if;

  if not public.takeoff_opportunity_matches_project(new.organization_id, new.project_id, new.opportunity_id) then
    raise exception 'Takeoff measurement opportunity_id must reference an opportunity whose workspace_project_id matches project_id.';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."validate_takeoff_measurement_consistency"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_takeoff_measurement_event_consistency"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  measurement_row public.takeoff_measurements%rowtype;
begin
  select *
  into measurement_row
  from public.takeoff_measurements
  where id = new.measurement_id;

  if measurement_row.id is null then
    raise exception 'Takeoff measurement event measurement does not exist.';
  end if;

  if measurement_row.organization_id <> new.organization_id then
    raise exception 'Takeoff measurement event organization_id must match measurement organization_id.';
  end if;

  if measurement_row.project_id <> new.project_id then
    raise exception 'Takeoff measurement event project_id must match measurement project_id.';
  end if;

  if measurement_row.opportunity_id is null and new.opportunity_id is not null then
    raise exception 'Takeoff measurement event opportunity_id must be null when measurement opportunity_id is null.';
  end if;

  if measurement_row.opportunity_id is not null and new.opportunity_id is not null and new.opportunity_id <> measurement_row.opportunity_id then
    raise exception 'Takeoff measurement event opportunity_id must match measurement opportunity_id when provided.';
  end if;

  if not public.takeoff_opportunity_matches_project(new.organization_id, new.project_id, new.opportunity_id) then
    raise exception 'Takeoff measurement event opportunity_id must reference an opportunity whose workspace_project_id matches project_id.';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."validate_takeoff_measurement_event_consistency"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_takeoff_measurement_group_consistency"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  parent_group_row public.takeoff_measurement_groups%rowtype;
begin
  if not public.takeoff_opportunity_matches_project(new.organization_id, new.project_id, new.opportunity_id) then
