  if drawing_set_row.project_id <> new.project_id then
    raise exception 'Takeoff page project_id must match drawing set project_id.';
  end if;

  if not public.takeoff_opportunity_matches_project(new.organization_id, new.project_id, new.opportunity_id) then
    raise exception 'Takeoff page opportunity_id must reference an opportunity whose workspace_project_id matches project_id.';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."validate_takeoff_page_consistency"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_takeoff_render_job_consistency"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  drawing_set_row public.project_drawing_sets%rowtype;
begin
  select *
  into drawing_set_row
  from public.project_drawing_sets
  where id = new.drawing_set_id;

  if drawing_set_row.id is null then
    raise exception 'Takeoff render job drawing set does not exist.';
  end if;

  if drawing_set_row.organization_id <> new.organization_id then
    raise exception 'Takeoff render job organization_id must match drawing set organization_id.';
  end if;

  if drawing_set_row.project_id <> new.project_id then
    raise exception 'Takeoff render job project_id must match drawing set project_id.';
  end if;

  if not public.takeoff_opportunity_matches_project(new.organization_id, new.project_id, new.opportunity_id) then
    raise exception 'Takeoff render job opportunity_id must match project_id.';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."validate_takeoff_render_job_consistency"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_worksheet_material_pricing_evidence"("p_organization_id" "uuid", "p_cell_value" numeric, "p_metadata" "jsonb") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_version integer;
  v_material public.organization_materials%rowtype;
  v_supplier public.organization_suppliers%rowtype;
  v_product public.organization_material_supplier_products%rowtype;
  v_price public.organization_material_supplier_prices%rowtype;
  v_conversion public.organization_material_supplier_product_unit_conversions%rowtype;
  v_evaluated_at timestamptz;
  v_derived jsonb;
  v_currency text;
begin
  v_version := (p_metadata->>'version')::integer;
  select * into v_material from public.organization_materials
    where organization_id = p_organization_id and id = (p_metadata->>'organizationMaterialId')::uuid;
  select * into v_supplier from public.organization_suppliers
    where organization_id = p_organization_id and id = (p_metadata->>'supplierId')::uuid;
  select * into v_product from public.organization_material_supplier_products
    where organization_id = p_organization_id and id = (p_metadata->>'supplierProductId')::uuid;
  if v_version = 1 then
    v_evaluated_at := (p_metadata #>> '{snapshot,evaluatedAt}')::timestamptz;
    select * into v_price from public.organization_material_supplier_prices
      where organization_id = p_organization_id and id = (p_metadata->>'supplierPriceId')::uuid;
  elsif v_version = 2 then
    v_evaluated_at := (p_metadata #>> '{estimatingPricing,evaluatedAt}')::timestamptz;
    select * into v_price from public.organization_material_supplier_prices
      where organization_id = p_organization_id and id = (p_metadata #>> '{sourcePricing,supplierPriceId}')::uuid;
  else return false; end if;
  if v_material.id is null or v_supplier.id is null or v_product.id is null or v_price.id is null
    or v_product.material_id <> v_material.id or v_product.supplier_id <> v_supplier.id
    or v_price.supplier_product_id <> v_product.id or v_price.material_id <> v_material.id
    or v_price.supplier_id <> v_supplier.id
    or not exists (select 1 from public.resolve_material_supplier_product_prices(
      p_organization_id, v_evaluated_at, array[v_product.id]
    ) resolved where resolved.price_id = v_price.id) then return false; end if;
  if v_version = 1 then
    return p_cell_value = v_price.unit_cost
      and (p_metadata #>> '{snapshot,unitCost}')::numeric = v_price.unit_cost
      and p_metadata #>> '{snapshot,unit}' = v_price.unit
      and upper(p_metadata #>> '{snapshot,currency}') = upper(v_price.currency);
  end if;
  if p_metadata #>> '{conversion,conversionId}' is not null then
    select * into v_conversion from public.organization_material_supplier_product_unit_conversions conversion
    where conversion.organization_id = p_organization_id
      and conversion.id = (p_metadata #>> '{conversion,conversionId}')::uuid
      and conversion.supplier_product_id = v_product.id
      and conversion.effective_from <= v_evaluated_at
      and (conversion.effective_to is null or conversion.effective_to > v_evaluated_at)
      and conversion.source in ('user_confirmed_ai','user_confirmed_manual');
    if v_conversion.id is null then return false; end if;
  end if;
  select public.resolve_material_estimating_currency(to_jsonb(organization)) into v_currency
    from public.organizations organization where organization.id = p_organization_id;
  v_derived := public.derive_material_estimating_price(
    v_price.id, v_price.unit_cost, v_price.unit, v_price.currency, v_price.source_tax_basis,
    v_price.source_tax_rate, v_price.tax_jurisdiction_code, v_price.comparison_tax_basis,
    v_price.comparison_tax_rate, v_price.tax_policy_snapshot, v_price.effective_from,
    v_material.default_unit, v_currency, v_evaluated_at,
    v_conversion.id, v_conversion.supplier_quantity, v_conversion.supplier_unit,
    v_conversion.material_quantity, v_conversion.material_unit, v_conversion.source,
    v_conversion.contract_version, v_conversion.effective_from, v_conversion.confirmed_at
  );
  return v_derived #>> '{estimatingPricing,status}' = 'available'
    and abs(p_cell_value - (v_derived #>> '{estimatingPricing,unitCost}')::numeric) <= 0.0000000001
    and abs((p_metadata #>> '{estimatingPricing,unitCost}')::numeric - (v_derived #>> '{estimatingPricing,unitCost}')::numeric) <= 0.0000000001
    and abs((p_metadata #>> '{estimatingPricing,normalizedSourceUnitCost}')::numeric - (v_derived #>> '{estimatingPricing,normalizedSourceUnitCost}')::numeric) <= 0.0000000001
    and p_metadata #>> '{estimatingPricing,derivationKind}' = v_derived #>> '{estimatingPricing,derivationKind}'
    and p_metadata #>> '{estimatingPricing,unit}' = v_material.default_unit
    and p_metadata #>> '{estimatingPricing,currency}' = v_derived #>> '{estimatingPricing,currency}'
    and p_metadata #>> '{estimatingPricing,taxBasis}' = v_derived #>> '{estimatingPricing,taxBasis}'
    and p_metadata #>> '{estimatingPricing,calculationVersion}' = 'material_estimating_price_v1'
    and (p_metadata #>> '{sourcePricing,unitCost}')::numeric = v_price.unit_cost
    and p_metadata #>> '{sourcePricing,unit}' = v_price.unit
    and upper(p_metadata #>> '{sourcePricing,currency}') = upper(v_price.currency)
    and p_metadata #>> '{sourcePricing,sourceTaxBasis}' = v_price.source_tax_basis
    and (p_metadata #>> '{sourcePricing,sourceTaxRate}')::numeric is not distinct from v_price.source_tax_rate
    and p_metadata #>> '{sourcePricing,taxJurisdictionCode}' is not distinct from v_price.tax_jurisdiction_code
    and p_metadata #>> '{sourcePricing,comparisonTaxBasis}' is not distinct from v_price.comparison_tax_basis
    and (p_metadata #>> '{sourcePricing,comparisonTaxRate}')::numeric is not distinct from v_price.comparison_tax_rate
    and (p_metadata #>> '{sourcePricing,priceEffectiveFrom}')::timestamptz is not distinct from v_price.effective_from
    and ((v_conversion.id is null and p_metadata->'conversion' = 'null'::jsonb) or (
      (p_metadata #>> '{conversion,conversionId}')::uuid = v_conversion.id
      and (p_metadata #>> '{conversion,supplierQuantity}')::numeric = v_conversion.supplier_quantity
      and p_metadata #>> '{conversion,supplierUnit}' = v_conversion.supplier_unit
      and (p_metadata #>> '{conversion,materialQuantity}')::numeric = v_conversion.material_quantity
      and p_metadata #>> '{conversion,materialUnit}' = v_conversion.material_unit
      and p_metadata #>> '{conversion,confirmationSource}' = v_conversion.source
      and p_metadata #>> '{conversion,contractVersion}' = v_conversion.contract_version
      and (p_metadata #>> '{conversion,effectiveFrom}')::timestamptz = v_conversion.effective_from
      and (p_metadata #>> '{conversion,confirmedAt}')::timestamptz = v_conversion.confirmed_at
    ));
exception when others then return false;
end;
$$;


ALTER FUNCTION "public"."validate_worksheet_material_pricing_evidence"("p_organization_id" "uuid", "p_cell_value" numeric, "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."write_correction_event"("p_input" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  member_row public.organization_members%rowtype;
  inserted_id uuid;
  resolved_organization_id uuid;
  resolved_project_id uuid;
  resolved_opportunity_id uuid;
  resolved_linked_event_id uuid;
  resolved_linked_ai_interaction_id uuid;
  resolved_linked_validation_case_id uuid;
begin
  if p_input is null or jsonb_typeof(p_input) <> 'object' then
    raise exception 'write_correction_event requires a JSON object payload';
  end if;

  resolved_organization_id := nullif(p_input->>'organizationId', '')::uuid;
  if resolved_organization_id is null then
    raise exception 'organizationId is required';
  end if;

  member_row := public._intelligence_assert_organization_member(resolved_organization_id);
  resolved_project_id := nullif(p_input->>'projectId', '')::uuid;
  resolved_opportunity_id := nullif(p_input->>'opportunityId', '')::uuid;
  resolved_linked_event_id := nullif(p_input->>'linkedEventId', '')::uuid;
  resolved_linked_ai_interaction_id := nullif(p_input->>'linkedAiInteractionId', '')::uuid;
  resolved_linked_validation_case_id := nullif(p_input->>'linkedValidationCaseId', '')::uuid;

  perform public._intelligence_assert_project_in_organization(resolved_organization_id, resolved_project_id);
  perform public._intelligence_assert_opportunity_in_organization(resolved_organization_id, resolved_opportunity_id);
  perform public._intelligence_assert_event_in_organization(resolved_organization_id, resolved_linked_event_id);
  perform public._intelligence_assert_ai_interaction_in_organization(resolved_organization_id, resolved_linked_ai_interaction_id);
  perform public._intelligence_assert_validation_case_in_organization(resolved_organization_id, resolved_linked_validation_case_id);

  insert into public.correction_events (
    organization_id,
    project_id,
    opportunity_id,
    module,
    correction_type,
    target_entity_type,
    target_entity_id,
    linked_event_id,
    linked_ai_interaction_id,
    linked_validation_case_id,
    corrected_field_name,
    incorrect_value,
    corrected_value,
    correction_reason,
    feedback_label,
    is_training_eligible,
    corrected_by_user_id,
    corrected_by_member_id,
    privacy_classification,
    visibility_scope
  )
  values (
    resolved_organization_id,
    resolved_project_id,
    resolved_opportunity_id,
    nullif(btrim(coalesce(p_input->>'module', '')), ''),
    nullif(btrim(coalesce(p_input->>'correctionType', '')), ''),
    nullif(btrim(coalesce(p_input->>'targetEntityType', '')), ''),
    nullif(p_input->>'targetEntityId', '')::uuid,
    resolved_linked_event_id,
    resolved_linked_ai_interaction_id,
    resolved_linked_validation_case_id,
    nullif(btrim(coalesce(p_input->>'correctedFieldName', '')), ''),
    p_input->'incorrectValue',
    p_input->'correctedValue',
    nullif(p_input->>'correctionReason', ''),
    nullif(btrim(coalesce(p_input->>'feedbackLabel', '')), ''),
    coalesce(nullif(p_input->>'isTrainingEligible', '')::boolean, true),
    auth.uid(),
    member_row.id,
    coalesce(nullif(btrim(coalesce(p_input->>'privacyClassification', '')), ''), 'commercial_sensitive'),
    coalesce(nullif(btrim(coalesce(p_input->>'visibilityScope', '')), ''), 'organization')
  )
  returning id into inserted_id;

  return inserted_id;
end;
$$;


ALTER FUNCTION "public"."write_correction_event"("p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."write_intelligence_event"("p_input" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  member_row public.organization_members%rowtype;
  inserted_id uuid;
  resolved_organization_id uuid;
  resolved_project_id uuid;
  resolved_opportunity_id uuid;
  resolved_module text;
  resolved_event_type text;
  resolved_source_request_id text;
begin
  if p_input is null or jsonb_typeof(p_input) <> 'object' then
    raise exception 'write_intelligence_event requires a JSON object payload';
  end if;

  resolved_organization_id := nullif(p_input->>'organizationId', '')::uuid;
  if resolved_organization_id is null then
    raise exception 'organizationId is required';
  end if;

  member_row := public._intelligence_assert_organization_member(resolved_organization_id);
  resolved_project_id := nullif(p_input->>'projectId', '')::uuid;
  resolved_opportunity_id := nullif(p_input->>'opportunityId', '')::uuid;
  resolved_module := nullif(btrim(coalesce(p_input->>'module', '')), '');
  resolved_event_type := nullif(btrim(coalesce(p_input->>'eventType', '')), '');
  resolved_source_request_id := nullif(btrim(coalesce(p_input->>'sourceRequestId', '')), '');

  perform public._intelligence_assert_project_in_organization(resolved_organization_id, resolved_project_id);
  perform public._intelligence_assert_opportunity_in_organization(resolved_organization_id, resolved_opportunity_id);

  insert into public.intelligence_events (
    organization_id,
    project_id,
    opportunity_id,
    module,
    submodule,
    event_family,
    event_type,
    action,
    entity_type,
    entity_id,
    entity_version,
    parent_entity_type,
    parent_entity_id,
    related_entities,
    lineage_refs,
    actor_user_id,
    actor_member_id,
    actor_role,
    source_channel,
    source_surface,
    source_request_id,
    source_session_id,
    source_device_id,
    status_before,
    status_after,
    field_name,
    before_data,
    after_data,
    diff_data,
    reason,
    metadata,
    privacy_classification,
    visibility_scope,
    contains_financial_data,
    contains_personal_data,
    contains_attachment_content,
    retention_policy_key,
    retention_expires_at,
    legal_hold,
    occurred_at
  )
  values (
    resolved_organization_id,
    resolved_project_id,
    resolved_opportunity_id,
    resolved_module,
    nullif(btrim(coalesce(p_input->>'submodule', '')), ''),
    nullif(btrim(coalesce(p_input->>'eventFamily', '')), ''),
    resolved_event_type,
    nullif(btrim(coalesce(p_input->>'action', '')), ''),
    nullif(btrim(coalesce(p_input->>'entityType', '')), ''),
    nullif(p_input->>'entityId', '')::uuid,
    nullif(p_input->>'entityVersion', '')::integer,
    nullif(btrim(coalesce(p_input->>'parentEntityType', '')), ''),
    nullif(p_input->>'parentEntityId', '')::uuid,
    coalesce(p_input->'relatedEntities', '[]'::jsonb),
    coalesce(p_input->'lineageRefs', '[]'::jsonb),
    auth.uid(),
    member_row.id,
    member_row.role,
    coalesce(nullif(btrim(coalesce(p_input->>'sourceChannel', '')), ''), 'web'),
    nullif(btrim(coalesce(p_input->>'sourceSurface', '')), ''),
    resolved_source_request_id,
    nullif(btrim(coalesce(p_input->>'sourceSessionId', '')), ''),
    nullif(btrim(coalesce(p_input->>'sourceDeviceId', '')), ''),
    nullif(btrim(coalesce(p_input->>'statusBefore', '')), ''),
    nullif(btrim(coalesce(p_input->>'statusAfter', '')), ''),
    nullif(btrim(coalesce(p_input->>'fieldName', '')), ''),
    p_input->'beforeData',
    p_input->'afterData',
    coalesce(p_input->'diffData', '{}'::jsonb),
    nullif(btrim(coalesce(p_input->>'reason', '')), ''),
    coalesce(p_input->'metadata', '{}'::jsonb),
    coalesce(nullif(btrim(coalesce(p_input->>'privacyClassification', '')), ''), 'internal_operational'),
    coalesce(nullif(btrim(coalesce(p_input->>'visibilityScope', '')), ''), 'organization'),
    coalesce(nullif(p_input->>'containsFinancialData', '')::boolean, false),
    coalesce(nullif(p_input->>'containsPersonalData', '')::boolean, false),
    coalesce(nullif(p_input->>'containsAttachmentContent', '')::boolean, false),
    nullif(btrim(coalesce(p_input->>'retentionPolicyKey', '')), ''),
    nullif(p_input->>'retentionExpiresAt', '')::timestamptz,
    coalesce(nullif(p_input->>'legalHold', '')::boolean, false),
    coalesce(nullif(p_input->>'occurredAt', '')::timestamptz, now())
  )
  on conflict do nothing
  returning id into inserted_id;

  if inserted_id is null and resolved_source_request_id is not null then
    select e.id
    into inserted_id
    from public.intelligence_events e
    where e.organization_id = resolved_organization_id
      and e.module = resolved_module
      and e.event_type = resolved_event_type
      and e.source_request_id = resolved_source_request_id
    order by e.created_at asc
    limit 1;
  end if;

  if inserted_id is null then
    raise exception 'Unable to persist intelligence event.';
  end if;

  return inserted_id;
end;
$$;


ALTER FUNCTION "public"."write_intelligence_event"("p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."write_intelligence_events"("p_events" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  event_item jsonb;
  inserted_ids jsonb := '[]'::jsonb;
  inserted_id uuid;
begin
  if p_events is null or jsonb_typeof(p_events) <> 'array' then
    raise exception 'write_intelligence_events requires a JSON array payload';
  end if;

  for event_item in
    select value
    from jsonb_array_elements(p_events)
  loop
    inserted_id := public.write_intelligence_event(event_item);
    inserted_ids := inserted_ids || jsonb_build_array(inserted_id);
  end loop;

  return jsonb_build_object(
    'count', jsonb_array_length(inserted_ids),
    'ids', inserted_ids
  );
end;
$$;


ALTER FUNCTION "public"."write_intelligence_events"("p_events" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."write_worksheet_mutation_outbox_intelligence_events"("p_events" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  event_item jsonb;
  inserted_ids jsonb := '[]'::jsonb;
  inserted_id uuid;
  resolved_actor_user_id uuid;
  resolved_actor_member_id uuid;
  resolved_actor_role text;
  resolved_organization_id uuid;
  resolved_project_id uuid;
  resolved_opportunity_id uuid;
  resolved_module text;
  resolved_event_type text;
  resolved_source_request_id text;
begin
  if p_events is null or jsonb_typeof(p_events) <> 'array' then
    raise exception 'write_worksheet_mutation_outbox_intelligence_events requires a JSON array payload';
  end if;

  for event_item in
    select value
    from jsonb_array_elements(p_events)
  loop
    resolved_organization_id := nullif(event_item->>'organizationId', '')::uuid;
    resolved_project_id := nullif(event_item->>'projectId', '')::uuid;
    resolved_opportunity_id := nullif(event_item->>'opportunityId', '')::uuid;
    resolved_module := nullif(btrim(coalesce(event_item->>'module', '')), '');
    resolved_event_type := nullif(btrim(coalesce(event_item->>'eventType', '')), '');
    resolved_source_request_id := nullif(btrim(coalesce(event_item->>'sourceRequestId', '')), '');
    resolved_actor_user_id := coalesce(
      nullif(event_item->>'userId', '')::uuid,
      nullif(event_item->'metadata'->>'userId', '')::uuid
    );

    resolved_actor_member_id := null;
    resolved_actor_role := null;
    if resolved_actor_user_id is not null and resolved_organization_id is not null then
      select member.id, member.role
      into resolved_actor_member_id, resolved_actor_role
      from public.organization_members member
      where member.organization_id = resolved_organization_id
        and member.user_id = resolved_actor_user_id
      limit 1;
    end if;

    insert into public.intelligence_events (
      organization_id,
      project_id,
      opportunity_id,
      module,
      submodule,
      event_family,
      event_type,
      action,
      entity_type,
      entity_id,
      entity_version,
      parent_entity_type,
      parent_entity_id,
      related_entities,
      lineage_refs,
      actor_user_id,
      actor_member_id,
      actor_role,
      source_channel,
      source_surface,
      source_request_id,
      source_session_id,
      source_device_id,
      status_before,
      status_after,
      field_name,
      before_data,
      after_data,
      diff_data,
      reason,
      metadata,
      privacy_classification,
      visibility_scope,
      contains_financial_data,
      contains_personal_data,
      contains_attachment_content,
      retention_policy_key,
      retention_expires_at,
      legal_hold,
      occurred_at
    )
    values (
      resolved_organization_id,
      resolved_project_id,
      resolved_opportunity_id,
      resolved_module,
      nullif(btrim(coalesce(event_item->>'submodule', '')), ''),
      nullif(btrim(coalesce(event_item->>'eventFamily', '')), ''),
      resolved_event_type,
      nullif(btrim(coalesce(event_item->>'action', '')), ''),
      nullif(btrim(coalesce(event_item->>'entityType', '')), ''),
      nullif(event_item->>'entityId', '')::uuid,
      nullif(event_item->>'entityVersion', '')::integer,
      nullif(btrim(coalesce(event_item->>'parentEntityType', '')), ''),
      nullif(event_item->>'parentEntityId', '')::uuid,
      coalesce(event_item->'relatedEntities', '[]'::jsonb),
      coalesce(event_item->'lineageRefs', '[]'::jsonb),
      resolved_actor_user_id,
      resolved_actor_member_id,
      resolved_actor_role,
      coalesce(nullif(btrim(coalesce(event_item->>'sourceChannel', '')), ''), 'web'),
      nullif(btrim(coalesce(event_item->>'sourceSurface', '')), ''),
      resolved_source_request_id,
      nullif(btrim(coalesce(event_item->>'sourceSessionId', '')), ''),
      nullif(btrim(coalesce(event_item->>'sourceDeviceId', '')), ''),
      nullif(btrim(coalesce(event_item->>'statusBefore', '')), ''),
      nullif(btrim(coalesce(event_item->>'statusAfter', '')), ''),
      nullif(btrim(coalesce(event_item->>'fieldName', '')), ''),
      event_item->'beforeData',
      event_item->'afterData',
      coalesce(event_item->'diffData', '{}'::jsonb),
      nullif(btrim(coalesce(event_item->>'reason', '')), ''),
      coalesce(event_item->'metadata', '{}'::jsonb),
      coalesce(nullif(btrim(coalesce(event_item->>'privacyClassification', '')), ''), 'internal_operational'),
      coalesce(nullif(btrim(coalesce(event_item->>'visibilityScope', '')), ''), 'organization'),
      coalesce(nullif(event_item->>'containsFinancialData', '')::boolean, false),
      coalesce(nullif(event_item->>'containsPersonalData', '')::boolean, false),
      coalesce(nullif(event_item->>'containsAttachmentContent', '')::boolean, false),
      nullif(btrim(coalesce(event_item->>'retentionPolicyKey', '')), ''),
      nullif(event_item->>'retentionExpiresAt', '')::timestamptz,
      coalesce(nullif(event_item->>'legalHold', '')::boolean, false),
      coalesce(nullif(event_item->>'occurredAt', '')::timestamptz, now())
    )
    on conflict do nothing
    returning id into inserted_id;

    if inserted_id is null and resolved_source_request_id is not null then
      select e.id
      into inserted_id
      from public.intelligence_events e
      where e.organization_id = resolved_organization_id
        and e.module = resolved_module
        and e.event_type = resolved_event_type
        and e.source_request_id = resolved_source_request_id
      order by e.created_at asc
      limit 1;
    end if;

    if inserted_id is null then
      raise exception 'Unable to persist worksheet mutation outbox intelligence event.';
    end if;

    inserted_ids := inserted_ids || jsonb_build_array(inserted_id);
  end loop;

  return jsonb_build_object(
    'count', jsonb_array_length(inserted_ids),
    'ids', inserted_ids
  );
end;
$$;


