    CONSTRAINT "commercial_lineage_edges_type_values_check" CHECK ((("from_entity_type" = ANY (ARRAY['commercial_item'::"text", 'organization_material'::"text", 'organization_material_supplier_product'::"text", 'organization_material_supplier_price'::"text", 'takeoff_measurement'::"text", 'project_quote'::"text", 'project_quote_line_item'::"text", 'project_variation'::"text", 'project_variation_line_item'::"text", 'project_purchase_order_line_item'::"text"])) AND ("to_entity_type" = ANY (ARRAY['commercial_item'::"text", 'organization_material'::"text", 'organization_material_supplier_product'::"text", 'organization_material_supplier_price'::"text", 'takeoff_measurement'::"text", 'project_quote'::"text", 'project_quote_line_item'::"text", 'project_variation'::"text", 'project_variation_line_item'::"text", 'project_purchase_order_line_item'::"text"]))))
);

