    CONSTRAINT "document_storage_cleanup_jobs_storage_key_check" CHECK ((("char_length"("btrim"("storage_key")) >= 1) AND ("char_length"("btrim"("storage_key")) <= 1000))),
    CONSTRAINT "document_storage_cleanup_jobs_type_check" CHECK (("job_type" = ANY (ARRAY['abandoned_upload'::"text", 'version_purge'::"text", 'orphan_reconciliation'::"text"])))
);

