CREATE TABLE IF NOT EXISTS "public"."document_storage_reconciliation_findings" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid",
    "workspace_id" "uuid",
    "finding_fingerprint" "text" NOT NULL,
    "discrepancy_type" "text" NOT NULL,
    "storage_bucket" "text",
    "storage_key" "text",
    "version_id" "uuid",
    "expected_byte_size" bigint,
    "actual_byte_size" bigint,
    "finding_status" "text" DEFAULT 'open'::"text" NOT NULL,
    "occurrence_count" integer DEFAULT 1 NOT NULL,
    "details" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "first_detected_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "last_detected_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "resolved_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "document_storage_reconciliation_findings_details_check" CHECK (("jsonb_typeof"("details") = 'object'::"text")),
    CONSTRAINT "document_storage_reconciliation_findings_occurrence_check" CHECK (("occurrence_count" >= 1)),
    CONSTRAINT "document_storage_reconciliation_findings_size_check" CHECK (((("expected_byte_size" IS NULL) OR ("expected_byte_size" >= 0)) AND (("actual_byte_size" IS NULL) OR ("actual_byte_size" >= 0)))),
    CONSTRAINT "document_storage_reconciliation_findings_status_check" CHECK (("finding_status" = ANY (ARRAY['open'::"text", 'acknowledged'::"text", 'resolved'::"text"]))),
    CONSTRAINT "document_storage_reconciliation_findings_type_check" CHECK (("discrepancy_type" = ANY (ARRAY['database_without_object'::"text", 'object_without_record'::"text", 'wrong_bucket'::"text", 'wrong_key'::"text", 'wrong_size'::"text", 'wrong_state'::"text"])))
);

