CREATE TABLE IF NOT EXISTS "public"."document_versions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "workspace_id" "uuid" NOT NULL,
    "node_id" "uuid" NOT NULL,
    "version_number" integer NOT NULL,
    "storage_key" "text" NOT NULL,
    "upload_state" "text" DEFAULT 'pending'::"text" NOT NULL,
    "byte_size" bigint,
    "claimed_mime_type" "text",
    "verified_mime_type" "text",
    "file_extension" "text",
    "sha256_checksum" "text",
    "uploaded_by" "uuid" NOT NULL,
    "initiated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "uploaded_at" timestamp with time zone,
    "verified_at" timestamp with time zone,
    "failed_at" timestamp with time zone,
    "abandoned_at" timestamp with time zone,
    "purged_at" timestamp with time zone,
    "failure_code" "text",
    "failure_message" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "upload_idempotency_key" "uuid",
    "upload_expires_at" timestamp with time zone,
    "upload_request_fingerprint" "text",
    "replaces_version_id" "uuid",
    "storage_object_id" "uuid",
    "storage_etag" "text",
    "activated_at" timestamp with time zone,
    CONSTRAINT "document_versions_activation_check" CHECK ((("upload_state" <> 'active'::"text") OR (("storage_object_id" IS NOT NULL) AND ("activated_at" IS NOT NULL) AND ("uploaded_at" IS NOT NULL) AND ("verified_at" IS NOT NULL)))),
    CONSTRAINT "document_versions_byte_size_check" CHECK ((("byte_size" IS NULL) OR ("byte_size" >= 0))),
    CONSTRAINT "document_versions_claimed_mime_type_check" CHECK ((("claimed_mime_type" IS NULL) OR (("char_length"("btrim"("claimed_mime_type")) >= 1) AND ("char_length"("btrim"("claimed_mime_type")) <= 255)))),
    CONSTRAINT "document_versions_extension_check" CHECK ((("file_extension" IS NULL) OR (("file_extension" = "lower"("btrim"("file_extension"))) AND ("file_extension" ~ '^[a-z0-9][a-z0-9._+-]{0,31}$'::"text")))),
    CONSTRAINT "document_versions_failure_code_check" CHECK ((("failure_code" IS NULL) OR (("char_length"("btrim"("failure_code")) >= 1) AND ("char_length"("btrim"("failure_code")) <= 100)))),
    CONSTRAINT "document_versions_sha256_check" CHECK ((("sha256_checksum" IS NULL) OR ("sha256_checksum" ~ '^[a-f0-9]{64}$'::"text"))),
    CONSTRAINT "document_versions_state_timestamp_check" CHECK (((("upload_state" <> 'uploaded'::"text") OR ("uploaded_at" IS NOT NULL)) AND (("upload_state" <> 'active'::"text") OR (("uploaded_at" IS NOT NULL) AND ("verified_at" IS NOT NULL))) AND (("upload_state" <> 'failed'::"text") OR ("failed_at" IS NOT NULL)) AND (("upload_state" <> 'abandoned'::"text") OR ("abandoned_at" IS NOT NULL)) AND (("upload_state" <> 'purged'::"text") OR ("purged_at" IS NOT NULL)))),
    CONSTRAINT "document_versions_storage_etag_check" CHECK ((("storage_etag" IS NULL) OR (("char_length"("btrim"("storage_etag")) >= 1) AND ("char_length"("btrim"("storage_etag")) <= 512)))),
    CONSTRAINT "document_versions_storage_key_check" CHECK (((("char_length"("btrim"("storage_key")) >= 1) AND ("char_length"("btrim"("storage_key")) <= 1000)) AND ("storage_key" = "btrim"("storage_key")))),
    CONSTRAINT "document_versions_upload_reservation_check" CHECK (((("upload_idempotency_key" IS NULL) AND ("upload_expires_at" IS NULL) AND ("upload_request_fingerprint" IS NULL)) OR (("upload_idempotency_key" IS NOT NULL) AND ("upload_expires_at" IS NOT NULL) AND ("upload_request_fingerprint" ~ '^[a-f0-9]{64}$'::"text") AND ("byte_size" IS NOT NULL) AND (("byte_size" >= 1) AND ("byte_size" <= '2147483648'::bigint))))),
    CONSTRAINT "document_versions_upload_state_check" CHECK (("upload_state" = ANY (ARRAY['pending'::"text", 'uploaded'::"text", 'active'::"text", 'failed'::"text", 'abandoned'::"text", 'purge_pending'::"text", 'purged'::"text"]))),
    CONSTRAINT "document_versions_verified_mime_type_check" CHECK ((("verified_mime_type" IS NULL) OR (("char_length"("btrim"("verified_mime_type")) >= 1) AND ("char_length"("btrim"("verified_mime_type")) <= 255)))),
    CONSTRAINT "document_versions_version_number_check" CHECK (("version_number" >= 1))
);

