CREATE TABLE IF NOT EXISTS "public"."intelligence_events" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "project_id" "uuid",
    "opportunity_id" "uuid",
    "module" "text" NOT NULL,
