    "after_data" "jsonb",
    "diff_data" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "reason" "text",
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "privacy_classification" "text" DEFAULT 'internal_operational'::"text" NOT NULL,
    "visibility_scope" "text" DEFAULT 'organization'::"text" NOT NULL,
    "contains_financial_data" boolean DEFAULT false NOT NULL,
    "contains_personal_data" boolean DEFAULT false NOT NULL,
    "contains_attachment_content" boolean DEFAULT false NOT NULL,
