    CONSTRAINT "intelligence_events_after_data_valid_check" CHECK ((("after_data" IS NULL) OR ("jsonb_typeof"("after_data") = ANY (ARRAY['object'::"text", 'array'::"text", 'string'::"text", 'number'::"text", 'boolean'::"text", 'null'::"text"])))),
    CONSTRAINT "intelligence_events_before_data_valid_check" CHECK ((("before_data" IS NULL) OR ("jsonb_typeof"("before_data") = ANY (ARRAY['object'::"text", 'array'::"text", 'string'::"text", 'number'::"text", 'boolean'::"text", 'null'::"text"])))),
    CONSTRAINT "intelligence_events_diff_data_object_check" CHECK (("jsonb_typeof"("diff_data") = 'object'::"text")),
    CONSTRAINT "intelligence_events_entity_type_not_blank" CHECK (("char_length"(TRIM(BOTH FROM "entity_type")) > 0)),
    CONSTRAINT "intelligence_events_entity_version_positive" CHECK ((("entity_version" IS NULL) OR ("entity_version" > 0))),
    CONSTRAINT "intelligence_events_event_family_check" CHECK (("event_family" = ANY (ARRAY['entity_lifecycle'::"text", 'field_change'::"text", 'status_change'::"text", 'commercial_action'::"text", 'ai_interaction'::"text", 'validation'::"text", 'correction'::"text", 'approval'::"text", 'file_lifecycle'::"text", 'lineage'::"text", 'system_event'::"text"]))),
    CONSTRAINT "intelligence_events_event_type_not_blank" CHECK (("char_length"(TRIM(BOTH FROM "event_type")) > 0)),
    CONSTRAINT "intelligence_events_lineage_refs_array_check" CHECK (("jsonb_typeof"("lineage_refs") = 'array'::"text")),
    CONSTRAINT "intelligence_events_metadata_object_check" CHECK (("jsonb_typeof"("metadata") = 'object'::"text")),
    CONSTRAINT "intelligence_events_module_not_blank" CHECK (("char_length"(TRIM(BOTH FROM "module")) > 0)),
    CONSTRAINT "intelligence_events_privacy_classification_check" CHECK (("privacy_classification" = ANY (ARRAY['public_safe'::"text", 'internal_operational'::"text", 'commercial_sensitive'::"text", 'financial_sensitive'::"text", 'personal_sensitive'::"text", 'restricted'::"text"]))),
    CONSTRAINT "intelligence_events_related_entities_array_check" CHECK (("jsonb_typeof"("related_entities") = 'array'::"text")),
    CONSTRAINT "intelligence_events_source_channel_check" CHECK (("source_channel" = ANY (ARRAY['web'::"text", 'mobile'::"text", 'api'::"text", 'rpc'::"text", 'ai'::"text", 'system'::"text", 'cron'::"text", 'backfill'::"text"]))),
    CONSTRAINT "intelligence_events_visibility_scope_check" CHECK (("visibility_scope" = ANY (ARRAY['organization'::"text", 'restricted_role'::"text", 'system'::"text"])))
);

