CREATE OR REPLACE VIEW "public"."intelligence_observability_ai_confidence_daily" WITH ("security_invoker"='true') AS
 WITH "corrections_by_interaction" AS (
         SELECT "c"."linked_ai_interaction_id" AS "ai_interaction_id",
            "count"(*) AS "correction_count"
           FROM "public"."correction_events" "c"
          WHERE ("c"."linked_ai_interaction_id" IS NOT NULL)
          GROUP BY "c"."linked_ai_interaction_id"
        )
 SELECT "ai"."organization_id",
    ("date_trunc"('day'::"text", ("ai"."created_at" AT TIME ZONE 'utc'::"text")))::"date" AS "event_date",
    "ai"."module",
    "ai"."interaction_type",
        CASE
            WHEN ("ai"."confidence" IS NULL) THEN 'unknown'::"text"
            WHEN ("ai"."confidence" < 0.40) THEN '0.00-0.39'::"text"
            WHEN ("ai"."confidence" < 0.60) THEN '0.40-0.59'::"text"
            WHEN ("ai"."confidence" < 0.80) THEN '0.60-0.79'::"text"
            ELSE '0.80-1.00'::"text"
        END AS "confidence_band",
    "count"(*) AS "interaction_count",
    "count"(*) FILTER (WHERE ("ai"."human_disposition" = 'accepted'::"text")) AS "accepted_count",
    "count"(*) FILTER (WHERE ("ai"."human_disposition" = 'rejected'::"text")) AS "rejected_count",
    "count"(*) FILTER (WHERE ("ai"."human_disposition" = 'edited'::"text")) AS "edited_count",
    "count"(*) FILTER (WHERE (COALESCE("cbi"."correction_count", (0)::bigint) > 0)) AS "corrected_interaction_count",
    "round"((("count"(*) FILTER (WHERE (COALESCE("cbi"."correction_count", (0)::bigint) > 0)))::numeric / NULLIF(("count"(*))::numeric, (0)::numeric)), 4) AS "correction_rate"
   FROM ("public"."ai_interactions" "ai"
     LEFT JOIN "corrections_by_interaction" "cbi" ON (("cbi"."ai_interaction_id" = "ai"."id")))
  WHERE (("ai"."visibility_scope" <> 'system'::"text") AND "public"."_intelligence_can_view_analytics"("ai"."organization_id"))
  GROUP BY "ai"."organization_id", (("date_trunc"('day'::"text", ("ai"."created_at" AT TIME ZONE 'utc'::"text")))::"date"), "ai"."module", "ai"."interaction_type",
        CASE
            WHEN ("ai"."confidence" IS NULL) THEN 'unknown'::"text"
            WHEN ("ai"."confidence" < 0.40) THEN '0.00-0.39'::"text"
            WHEN ("ai"."confidence" < 0.60) THEN '0.40-0.59'::"text"
            WHEN ("ai"."confidence" < 0.80) THEN '0.60-0.79'::"text"
            ELSE '0.80-1.00'::"text"
        END;


ALTER VIEW "public"."intelligence_observability_ai_confidence_daily" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."intelligence_observability_ai_daily" WITH ("security_invoker"='true') AS
 WITH "corrections_by_interaction" AS (
         SELECT "c"."linked_ai_interaction_id" AS "ai_interaction_id",
            "count"(*) AS "correction_count"
           FROM "public"."correction_events" "c"
          WHERE ("c"."linked_ai_interaction_id" IS NOT NULL)
          GROUP BY "c"."linked_ai_interaction_id"
        )
 SELECT "ai"."organization_id",
    ("date_trunc"('day'::"text", ("ai"."created_at" AT TIME ZONE 'utc'::"text")))::"date" AS "event_date",
    "ai"."module",
    "ai"."interaction_type",
    "count"(*) AS "interaction_count",
    "count"(*) FILTER (WHERE ("ai"."human_disposition" = 'accepted'::"text")) AS "accepted_count",
    "count"(*) FILTER (WHERE ("ai"."human_disposition" = 'rejected'::"text")) AS "rejected_count",
    "count"(*) FILTER (WHERE ("ai"."human_disposition" = 'edited'::"text")) AS "edited_count",
    "count"(*) FILTER (WHERE ("ai"."human_disposition" = 'partially_accepted'::"text")) AS "partially_accepted_count",
    "count"(*) FILTER (WHERE ("ai"."human_disposition" = 'ignored'::"text")) AS "ignored_count",
    "count"(*) FILTER (WHERE (COALESCE("cbi"."correction_count", (0)::bigint) > 0)) AS "corrected_interaction_count",
    "avg"("ai"."confidence") AS "avg_confidence",
    "avg"("ai"."confidence") FILTER (WHERE ("ai"."human_disposition" = 'accepted'::"text")) AS "avg_confidence_accepted",
    "avg"("ai"."confidence") FILTER (WHERE ("ai"."human_disposition" = 'rejected'::"text")) AS "avg_confidence_rejected",
    "avg"("ai"."confidence") FILTER (WHERE ("ai"."human_disposition" = 'edited'::"text")) AS "avg_confidence_edited",
    "avg"("ai"."confidence") FILTER (WHERE (COALESCE("cbi"."correction_count", (0)::bigint) > 0)) AS "avg_confidence_corrected",
    "round"((("count"(*) FILTER (WHERE (COALESCE("cbi"."correction_count", (0)::bigint) > 0)))::numeric / NULLIF(("count"(*))::numeric, (0)::numeric)), 4) AS "correction_rate"
   FROM ("public"."ai_interactions" "ai"
     LEFT JOIN "corrections_by_interaction" "cbi" ON (("cbi"."ai_interaction_id" = "ai"."id")))
  WHERE (("ai"."visibility_scope" <> 'system'::"text") AND "public"."_intelligence_can_view_analytics"("ai"."organization_id"))
  GROUP BY "ai"."organization_id", (("date_trunc"('day'::"text", ("ai"."created_at" AT TIME ZONE 'utc'::"text")))::"date"), "ai"."module", "ai"."interaction_type";


ALTER VIEW "public"."intelligence_observability_ai_daily" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."intelligence_observability_correction_daily" WITH ("security_invoker"='true') AS
 SELECT "organization_id",
    ("date_trunc"('day'::"text", ("created_at" AT TIME ZONE 'utc'::"text")))::"date" AS "event_date",
    "module",
    "correction_type",
    "target_entity_type",
    "corrected_field_name",
    "feedback_label",
    "is_training_eligible",
    "count"(*) AS "correction_count",
    "count"(DISTINCT "target_entity_id") AS "distinct_target_count",
    "count"(DISTINCT "corrected_by_user_id") AS "distinct_actor_count",
    "min"("created_at") AS "first_created_at",
    "max"("created_at") AS "last_created_at"
   FROM "public"."correction_events" "c"
  WHERE (("visibility_scope" <> 'system'::"text") AND "public"."_intelligence_can_view_analytics"("organization_id"))
  GROUP BY "organization_id", (("date_trunc"('day'::"text", ("created_at" AT TIME ZONE 'utc'::"text")))::"date"), "module", "correction_type", "target_entity_type", "corrected_field_name", "feedback_label", "is_training_eligible";


ALTER VIEW "public"."intelligence_observability_correction_daily" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."intelligence_observability_cost_item_daily" AS
 SELECT "organization_id",
    ("date_trunc"('day'::"text", ("updated_at" AT TIME ZONE 'utc'::"text")))::"date" AS "event_date",
    'cost_items'::"text" AS "module",
    COALESCE("review_status", 'unreviewed'::"text") AS "event_type",
    "project_id",
    "tradesstack_cost_code",
    "tradesstack_cost_code_label",
    "financial_routing_source",
    "source_document_kind",
    "count"(*) AS "event_count",
    "count"(DISTINCT "id") AS "distinct_entity_count",
    "avg"("financial_routing_confidence") AS "avg_routing_confidence",
    "count"(*) FILTER (WHERE ("accounting_mapping_id" IS NULL)) AS "unmapped_count"
   FROM "public"."cost_items" "ci"
  WHERE ("is_current" AND ("status" <> ALL (ARRAY['deleted'::"text", 'superseded'::"text"])) AND "public"."_intelligence_can_view_analytics"("organization_id"))
  GROUP BY "organization_id", (("date_trunc"('day'::"text", ("updated_at" AT TIME ZONE 'utc'::"text")))::"date"), 'cost_items'::"text", COALESCE("review_status", 'unreviewed'::"text"), "project_id", "tradesstack_cost_code", "tradesstack_cost_code_label", "financial_routing_source", "source_document_kind";


ALTER VIEW "public"."intelligence_observability_cost_item_daily" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."intelligence_observability_cost_item_review_backlog" AS
 SELECT "organization_id",
    "project_id",
    "source_document_kind",
    "tradesstack_cost_code",
    "tradesstack_cost_code_label",
    "review_status",
    "count"(*) AS "unresolved_review_count",
    "avg"("financial_routing_confidence") AS "avg_routing_confidence",
    "max"("updated_at") AS "last_updated_at"
   FROM "public"."cost_items" "ci"
  WHERE ("is_current" AND ("status" <> ALL (ARRAY['deleted'::"text", 'superseded'::"text"])) AND ("review_status" = ANY (ARRAY['needs_routing_review'::"text", 'needs_accounting_mapping'::"text", 'high_value_review'::"text"])) AND "public"."_intelligence_can_view_analytics"("organization_id"))
  GROUP BY "organization_id", "project_id", "source_document_kind", "tradesstack_cost_code", "tradesstack_cost_code_label", "review_status";


ALTER VIEW "public"."intelligence_observability_cost_item_review_backlog" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."validation_cases" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "project_id" "uuid",
    "opportunity_id" "uuid",
    "module" "text" NOT NULL,
    "scope_entity_type" "text" NOT NULL,
    "scope_entity_id" "uuid",
    "linked_event_id" "uuid",
    "linked_ai_interaction_id" "uuid",
    "rule_key" "text" NOT NULL,
    "rule_version" "text",
    "validation_type" "text" NOT NULL,
    "severity" "text" NOT NULL,
    "result" "text" NOT NULL,
    "expected_value" "jsonb",
    "observed_value" "jsonb",
    "details" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "requires_approval" boolean DEFAULT false NOT NULL,
    "approval_status" "text" DEFAULT 'not_required'::"text" NOT NULL,
    "approved_by_user_id" "uuid",
    "approved_at" timestamp with time zone,
    "approval_note" "text",
    "privacy_classification" "text" DEFAULT 'internal_operational'::"text" NOT NULL,
    "visibility_scope" "text" DEFAULT 'organization'::"text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "validation_cases_approval_status_check" CHECK (("approval_status" = ANY (ARRAY['not_required'::"text", 'pending'::"text", 'approved'::"text", 'rejected'::"text"]))),
    CONSTRAINT "validation_cases_details_object_check" CHECK (("jsonb_typeof"("details") = 'object'::"text")),
    CONSTRAINT "validation_cases_expected_value_valid_check" CHECK ((("expected_value" IS NULL) OR ("jsonb_typeof"("expected_value") = ANY (ARRAY['object'::"text", 'array'::"text", 'string'::"text", 'number'::"text", 'boolean'::"text", 'null'::"text"])))),
    CONSTRAINT "validation_cases_module_not_blank" CHECK (("char_length"(TRIM(BOTH FROM "module")) > 0)),
    CONSTRAINT "validation_cases_observed_value_valid_check" CHECK ((("observed_value" IS NULL) OR ("jsonb_typeof"("observed_value") = ANY (ARRAY['object'::"text", 'array'::"text", 'string'::"text", 'number'::"text", 'boolean'::"text", 'null'::"text"])))),
    CONSTRAINT "validation_cases_privacy_classification_check" CHECK (("privacy_classification" = ANY (ARRAY['public_safe'::"text", 'internal_operational'::"text", 'commercial_sensitive'::"text", 'financial_sensitive'::"text", 'personal_sensitive'::"text", 'restricted'::"text"]))),
    CONSTRAINT "validation_cases_result_check" CHECK (("result" = ANY (ARRAY['passed'::"text", 'failed'::"text", 'warning'::"text", 'overridden'::"text"]))),
    CONSTRAINT "validation_cases_rule_key_not_blank" CHECK (("char_length"(TRIM(BOTH FROM "rule_key")) > 0)),
    CONSTRAINT "validation_cases_scope_entity_type_not_blank" CHECK (("char_length"(TRIM(BOTH FROM "scope_entity_type")) > 0)),
    CONSTRAINT "validation_cases_severity_check" CHECK (("severity" = ANY (ARRAY['info'::"text", 'warning'::"text", 'error'::"text", 'critical'::"text"]))),
    CONSTRAINT "validation_cases_validation_type_check" CHECK (("validation_type" = ANY (ARRAY['schema'::"text", 'business_rule'::"text", 'workflow_gate'::"text", 'financial_check'::"text", 'ai_confidence'::"text", 'duplicate_detection'::"text", 'permission_check'::"text", 'consistency_check'::"text"]))),
    CONSTRAINT "validation_cases_visibility_scope_check" CHECK (("visibility_scope" = ANY (ARRAY['organization'::"text", 'restricted_role'::"text", 'system'::"text"])))
);

ALTER TABLE ONLY "public"."validation_cases" FORCE ROW LEVEL SECURITY;


ALTER TABLE "public"."validation_cases" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."intelligence_observability_daily_overview" WITH ("security_invoker"='true') AS
 SELECT "organization_id",
    "activity_date",
    "module",
    "sum"("intelligence_event_count") AS "intelligence_event_count",
    "sum"("correction_event_count") AS "correction_event_count",
    "sum"("ai_interaction_count") AS "ai_interaction_count",
    "sum"("validation_case_count") AS "validation_case_count",
    "max"("latest_activity_at") AS "latest_activity_at"
   FROM ( SELECT "e"."organization_id",
            ("date_trunc"('day'::"text", ("e"."occurred_at" AT TIME ZONE 'utc'::"text")))::"date" AS "activity_date",
            "e"."module",
            "count"(*) AS "intelligence_event_count",
            (0)::bigint AS "correction_event_count",
            (0)::bigint AS "ai_interaction_count",
            (0)::bigint AS "validation_case_count",
            "max"("e"."occurred_at") AS "latest_activity_at"
           FROM "public"."intelligence_events" "e"
          WHERE (("e"."visibility_scope" <> 'system'::"text") AND "public"."_intelligence_can_view_analytics"("e"."organization_id"))
          GROUP BY "e"."organization_id", (("date_trunc"('day'::"text", ("e"."occurred_at" AT TIME ZONE 'utc'::"text")))::"date"), "e"."module"
        UNION ALL
         SELECT "c"."organization_id",
            ("date_trunc"('day'::"text", ("c"."created_at" AT TIME ZONE 'utc'::"text")))::"date" AS "activity_date",
            "c"."module",
            (0)::bigint AS "intelligence_event_count",
            "count"(*) AS "correction_event_count",
            (0)::bigint AS "ai_interaction_count",
            (0)::bigint AS "validation_case_count",
            "max"("c"."created_at") AS "latest_activity_at"
           FROM "public"."correction_events" "c"
          WHERE (("c"."visibility_scope" <> 'system'::"text") AND "public"."_intelligence_can_view_analytics"("c"."organization_id"))
          GROUP BY "c"."organization_id", (("date_trunc"('day'::"text", ("c"."created_at" AT TIME ZONE 'utc'::"text")))::"date"), "c"."module"
        UNION ALL
         SELECT "ai"."organization_id",
            ("date_trunc"('day'::"text", ("ai"."created_at" AT TIME ZONE 'utc'::"text")))::"date" AS "activity_date",
            "ai"."module",
            (0)::bigint AS "intelligence_event_count",
            (0)::bigint AS "correction_event_count",
            "count"(*) AS "ai_interaction_count",
            (0)::bigint AS "validation_case_count",
            "max"("ai"."created_at") AS "latest_activity_at"
           FROM "public"."ai_interactions" "ai"
          WHERE (("ai"."visibility_scope" <> 'system'::"text") AND "public"."_intelligence_can_view_analytics"("ai"."organization_id"))
          GROUP BY "ai"."organization_id", (("date_trunc"('day'::"text", ("ai"."created_at" AT TIME ZONE 'utc'::"text")))::"date"), "ai"."module"
        UNION ALL
         SELECT "vc"."organization_id",
            ("date_trunc"('day'::"text", ("vc"."created_at" AT TIME ZONE 'utc'::"text")))::"date" AS "activity_date",
            "vc"."module",
            (0)::bigint AS "intelligence_event_count",
            (0)::bigint AS "correction_event_count",
            (0)::bigint AS "ai_interaction_count",
            "count"(*) AS "validation_case_count",
            "max"("vc"."created_at") AS "latest_activity_at"
           FROM "public"."validation_cases" "vc"
          WHERE (("vc"."visibility_scope" <> 'system'::"text") AND "public"."_intelligence_can_view_analytics"("vc"."organization_id"))
          GROUP BY "vc"."organization_id", (("date_trunc"('day'::"text", ("vc"."created_at" AT TIME ZONE 'utc'::"text")))::"date"), "vc"."module") "activity"
  GROUP BY "organization_id", "activity_date", "module";


ALTER VIEW "public"."intelligence_observability_daily_overview" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."intelligence_observability_event_daily" WITH ("security_invoker"='true') AS
 SELECT "organization_id",
    ("date_trunc"('day'::"text", ("occurred_at" AT TIME ZONE 'utc'::"text")))::"date" AS "event_date",
    "module",
    "event_family",
    "event_type",
    "privacy_classification",
    "bool_or"("contains_financial_data") AS "contains_financial_data",
    "count"(*) AS "event_count",
    "count"(DISTINCT "entity_id") AS "distinct_entity_count",
    "count"(DISTINCT "actor_user_id") AS "distinct_actor_count",
    "count"(DISTINCT "project_id") AS "distinct_project_count",
    "count"(DISTINCT "opportunity_id") AS "distinct_opportunity_count",
    "min"("occurred_at") AS "first_occurred_at",
    "max"("occurred_at") AS "last_occurred_at"
   FROM "public"."intelligence_events" "e"
  WHERE (("visibility_scope" <> 'system'::"text") AND "public"."_intelligence_can_view_analytics"("organization_id"))
  GROUP BY "organization_id", (("date_trunc"('day'::"text", ("occurred_at" AT TIME ZONE 'utc'::"text")))::"date"), "module", "event_family", "event_type", "privacy_classification";


ALTER VIEW "public"."intelligence_observability_event_daily" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."intelligence_observability_pricing_worksheet_daily" WITH ("security_invoker"='true') AS
 SELECT "organization_id",
    ("date_trunc"('day'::"text", ("occurred_at" AT TIME ZONE 'utc'::"text")))::"date" AS "event_date",
    NULLIF("btrim"(COALESCE(("metadata" ->> 'workbookId'::"text"), ("metadata" ->> 'worksheetId'::"text"), ''::"text")), ''::"text") AS "workbook_id",
    NULLIF("btrim"(COALESCE(("metadata" ->> 'sheetId'::"text"), ("entity_id")::"text", ''::"text")), ''::"text") AS "sheet_id",
    COALESCE(NULLIF("btrim"(("metadata" ->> 'sheetName'::"text")), ''::"text"), NULLIF("btrim"(("metadata" ->> 'worksheetName'::"text")), ''::"text"), '(unnamed worksheet)'::"text") AS "sheet_name",
    COALESCE(NULLIF("btrim"(("metadata" ->> 'worksheetName'::"text")), ''::"text"), '(unnamed worksheet)'::"text") AS "worksheet_name",
    NULLIF("btrim"(("metadata" ->> 'tradePackage'::"text")), ''::"text") AS "trade_package",
    "count"(*) FILTER (WHERE ("event_type" = 'worksheet_created'::"text")) AS "worksheet_created_count",
    "count"(*) FILTER (WHERE ("event_type" = 'worksheet_renamed'::"text")) AS "worksheet_renamed_count",
    "count"(*) FILTER (WHERE ("event_type" = 'worksheet_duplicated'::"text")) AS "worksheet_duplicated_count",
    "count"(*) FILTER (WHERE ("event_type" = 'worksheet_archived'::"text")) AS "worksheet_archived_count",
    "count"(*) FILTER (WHERE ("event_type" = 'worksheet_saved'::"text")) AS "worksheet_saved_count",
    "avg"((NULLIF((("metadata" -> 'structureSummary'::"text") ->> 'rowCount'::"text"), ''::"text"))::numeric) FILTER (WHERE ("event_type" = 'worksheet_saved'::"text")) AS "avg_row_count_on_save",
    "avg"((NULLIF((("metadata" -> 'structureSummary'::"text") ->> 'columnCount'::"text"), ''::"text"))::numeric) FILTER (WHERE ("event_type" = 'worksheet_saved'::"text")) AS "avg_column_count_on_save",
    "avg"((NULLIF((("metadata" -> 'structureSummary'::"text") ->> 'formulaCount'::"text"), ''::"text"))::numeric) FILTER (WHERE ("event_type" = 'worksheet_saved'::"text")) AS "avg_formula_count_on_save",
    "avg"((NULLIF((("metadata" -> 'structureSummary'::"text") ->> 'populatedCellCount'::"text"), ''::"text"))::numeric) FILTER (WHERE ("event_type" = 'worksheet_saved'::"text")) AS "avg_populated_cell_count_on_save"
   FROM "public"."intelligence_events" "e"
  WHERE (("module" = 'pricing_worksheets'::"text") AND ("visibility_scope" <> 'system'::"text") AND "public"."_intelligence_can_view_analytics"("organization_id"))
  GROUP BY "organization_id", (("date_trunc"('day'::"text", ("occurred_at" AT TIME ZONE 'utc'::"text")))::"date"), NULLIF("btrim"(COALESCE(("metadata" ->> 'workbookId'::"text"), ("metadata" ->> 'worksheetId'::"text"), ''::"text")), ''::"text"), NULLIF("btrim"(COALESCE(("metadata" ->> 'sheetId'::"text"), ("entity_id")::"text", ''::"text")), ''::"text"), COALESCE(NULLIF("btrim"(("metadata" ->> 'sheetName'::"text")), ''::"text"), NULLIF("btrim"(("metadata" ->> 'worksheetName'::"text")), ''::"text"), '(unnamed worksheet)'::"text"), COALESCE(NULLIF("btrim"(("metadata" ->> 'worksheetName'::"text")), ''::"text"), '(unnamed worksheet)'::"text"), NULLIF("btrim"(("metadata" ->> 'tradePackage'::"text")), ''::"text");


ALTER VIEW "public"."intelligence_observability_pricing_worksheet_daily" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."intelligence_observability_supplier_invoice_daily" WITH ("security_invoker"='true') AS
 SELECT "organization_id",
    ("date_trunc"('day'::"text", ("occurred_at" AT TIME ZONE 'utc'::"text")))::"date" AS "event_date",
    "project_id",
    "count"(*) FILTER (WHERE ("event_type" = 'supplier_invoice_created'::"text")) AS "invoice_created_count",
    "count"(*) FILTER (WHERE ("event_type" = 'supplier_invoice_match_suggested'::"text")) AS "match_suggested_count",
    "count"(*) FILTER (WHERE ("event_type" = 'supplier_invoice_match_confirmed'::"text")) AS "match_confirmed_count",
    "count"(*) FILTER (WHERE ("event_type" = 'supplier_invoice_match_rejected'::"text")) AS "match_rejected_count",
    "round"((("count"(*) FILTER (WHERE ("event_type" = 'supplier_invoice_match_confirmed'::"text")))::numeric / NULLIF((("count"(*) FILTER (WHERE ("event_type" = 'supplier_invoice_match_confirmed'::"text")) + "count"(*) FILTER (WHERE ("event_type" = 'supplier_invoice_match_rejected'::"text"))))::numeric, (0)::numeric)), 4) AS "match_acceptance_rate",
    "count"(*) FILTER (WHERE ("event_type" = 'supplier_invoice_allocation_suggested'::"text")) AS "allocation_suggested_count",
    "count"(*) FILTER (WHERE ("event_type" = 'supplier_invoice_allocation_approved'::"text")) AS "allocation_approved_count",
    "count"(*) FILTER (WHERE ("event_type" = 'supplier_invoice_allocation_corrected'::"text")) AS "allocation_corrected_count",
    "round"((("count"(*) FILTER (WHERE ("event_type" = 'supplier_invoice_allocation_approved'::"text")))::numeric / NULLIF((("count"(*) FILTER (WHERE ("event_type" = 'supplier_invoice_allocation_approved'::"text")) + "count"(*) FILTER (WHERE ("event_type" = 'supplier_invoice_allocation_corrected'::"text"))))::numeric, (0)::numeric)), 4) AS "allocation_approval_rate",
    "count"(*) FILTER (WHERE ("event_type" = 'supplier_invoice_approval_requested'::"text")) AS "approval_requested_count",
    "count"(*) FILTER (WHERE ("event_type" = 'supplier_invoice_approved'::"text")) AS "invoice_approved_count",
    "count"(*) FILTER (WHERE ("event_type" = 'supplier_invoice_rejected'::"text")) AS "invoice_rejected_count",
    "count"(*) FILTER (WHERE ("event_type" = 'supplier_invoice_actual_cost_posted'::"text")) AS "actual_cost_posted_count",
    "count"(*) FILTER (WHERE ("event_type" = 'supplier_invoice_actual_cost_reversed'::"text")) AS "actual_cost_reversed_count",
    "count"(*) FILTER (WHERE ("event_type" = 'ai_supplier_invoice_match_accepted'::"text")) AS "ai_match_accepted_count",
    "count"(*) FILTER (WHERE ("event_type" = 'ai_supplier_invoice_match_rejected'::"text")) AS "ai_match_rejected_count",
    "count"(*) FILTER (WHERE ("event_type" = 'ai_supplier_invoice_match_edited'::"text")) AS "ai_match_edited_count"
   FROM "public"."intelligence_events" "e"
  WHERE (("module" = 'supplier_invoices'::"text") AND ("visibility_scope" <> 'system'::"text") AND "public"."_intelligence_can_view_analytics"("organization_id"))
  GROUP BY "organization_id", (("date_trunc"('day'::"text", ("occurred_at" AT TIME ZONE 'utc'::"text")))::"date"), "project_id";


ALTER VIEW "public"."intelligence_observability_supplier_invoice_daily" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."intelligence_observability_takeoff_daily" WITH ("security_invoker"='true') AS
 SELECT "organization_id",
    ("date_trunc"('day'::"text", ("occurred_at" AT TIME ZONE 'utc'::"text")))::"date" AS "event_date",
    "project_id",
    "opportunity_id",
    COALESCE(NULLIF("btrim"(("after_data" ->> 'measurementKind'::"text")), ''::"text"), NULLIF("btrim"(("before_data" ->> 'measurementKind'::"text")), ''::"text")) AS "measurement_kind",
    "count"(*) FILTER (WHERE ("event_type" = 'takeoff_measurement_created'::"text")) AS "measurement_created_count",
    "count"(*) FILTER (WHERE ("event_type" = 'takeoff_measurement_updated'::"text")) AS "measurement_updated_count",
    "count"(*) FILTER (WHERE ("event_type" = 'takeoff_measurement_corrected'::"text")) AS "measurement_corrected_count",
    "count"(*) FILTER (WHERE ("event_type" = 'takeoff_measurement_archived'::"text")) AS "measurement_archived_count",
    "count"(*) FILTER (WHERE ("event_type" = 'takeoff_measurement_deleted'::"text")) AS "measurement_deleted_count",
    "count"(*) FILTER (WHERE ("event_type" = 'takeoff_measurement_restored'::"text")) AS "measurement_restored_count",
    "count"(*) FILTER (WHERE ("event_type" = 'takeoff_calibration_created'::"text")) AS "calibration_created_count",
    "count"(*) FILTER (WHERE ("event_type" = 'takeoff_calibration_corrected'::"text")) AS "calibration_corrected_count"
   FROM "public"."intelligence_events" "e"
  WHERE (("module" = 'takeoff'::"text") AND ("visibility_scope" <> 'system'::"text") AND "public"."_intelligence_can_view_analytics"("organization_id"))
  GROUP BY "organization_id", (("date_trunc"('day'::"text", ("occurred_at" AT TIME ZONE 'utc'::"text")))::"date"), "project_id", "opportunity_id", COALESCE(NULLIF("btrim"(("after_data" ->> 'measurementKind'::"text")), ''::"text"), NULLIF("btrim"(("before_data" ->> 'measurementKind'::"text")), ''::"text"));


ALTER VIEW "public"."intelligence_observability_takeoff_daily" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."intelligence_observability_validation_daily" WITH ("security_invoker"='true') AS
 SELECT "organization_id",
    ("date_trunc"('day'::"text", ("created_at" AT TIME ZONE 'utc'::"text")))::"date" AS "event_date",
    "module",
    "rule_key",
    "validation_type",
    "severity",
    "count"(*) AS "validation_case_count",
    "count"(*) FILTER (WHERE ("result" = 'failed'::"text")) AS "failed_count",
    "count"(*) FILTER (WHERE ("result" = 'warning'::"text")) AS "warning_count",
    "count"(*) FILTER (WHERE ("result" = 'passed'::"text")) AS "passed_count",
    "count"(*) FILTER (WHERE ("result" = 'overridden'::"text")) AS "overridden_count",
    "count"(*) FILTER (WHERE "requires_approval") AS "requires_approval_count",
    "count"(*) FILTER (WHERE ("approval_status" = 'pending'::"text")) AS "approval_pending_count",
    "count"(*) FILTER (WHERE ("approval_status" = 'approved'::"text")) AS "approval_approved_count",
    "count"(*) FILTER (WHERE ("approval_status" = 'rejected'::"text")) AS "approval_rejected_count",
    "round"((("count"(*) FILTER (WHERE ("result" = 'overridden'::"text")))::numeric / NULLIF(("count"(*))::numeric, (0)::numeric)), 4) AS "override_rate"
   FROM "public"."validation_cases" "vc"
  WHERE (("visibility_scope" <> 'system'::"text") AND "public"."_intelligence_can_view_analytics"("organization_id"))
  GROUP BY "organization_id", (("date_trunc"('day'::"text", ("created_at" AT TIME ZONE 'utc'::"text")))::"date"), "module", "rule_key", "validation_type", "severity";


ALTER VIEW "public"."intelligence_observability_validation_daily" OWNER TO "postgres";


