    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "review_run_id" "uuid" NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "learning_id" "text" NOT NULL,
    "action_key" "text" NOT NULL,
    "action_type" "text" NOT NULL,
    "target_memory_id" "uuid",
    "result_status" "text" DEFAULT 'applied'::"text" NOT NULL,
    "reason" "text",
    "confidence_adjustment" numeric,
    "created_memory_id" "uuid",
    "updated_memory_id" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "learning_review_action_results_action_key_not_blank" CHECK (("char_length"(TRIM(BOTH FROM "action_key")) > 0)),
    CONSTRAINT "learning_review_action_results_action_type_check" CHECK (("action_type" = ANY (ARRAY['create'::"text", 'reinforce'::"text", 'update'::"text", 'contradict'::"text", 'retire'::"text", 'no_action'::"text"]))),
    CONSTRAINT "learning_review_action_results_confidence_adjustment_range_chec" CHECK ((("confidence_adjustment" IS NULL) OR (("confidence_adjustment" >= ('-1'::integer)::numeric) AND ("confidence_adjustment" <= (1)::numeric)))),
    CONSTRAINT "learning_review_action_results_learning_id_not_blank" CHECK (("char_length"(TRIM(BOTH FROM "learning_id")) > 0)),
    CONSTRAINT "learning_review_action_results_result_status_check" CHECK (("result_status" = ANY (ARRAY['applied'::"text", 'skipped'::"text", 'deduplicated'::"text", 'failed'::"text"])))
);

