CREATE TABLE IF NOT EXISTS "public"."learning_review_runs" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "container_type" "text" NOT NULL,
