    "previous_cursor_id" "text",
    "candidate_next_cursor_updated_at" timestamp with time zone,
    "candidate_next_cursor_id" "text",
    "final_next_cursor_updated_at" timestamp with time zone,
    "final_next_cursor_id" "text",
    "selected_record_count" integer DEFAULT 0 NOT NULL,
    "memory_pack_count" integer DEFAULT 0 NOT NULL,
    "model_provider" "text",
    "model_name" "text",
    "prompt_version" "text" DEFAULT 'ucl-v1'::"text" NOT NULL,
    "prompt_hash" "text" DEFAULT ''::"text" NOT NULL,
    "response_hash" "text",
    "input_token_count" integer,
    "output_token_count" integer,
    "total_token_count" integer,
    "duration_ms" integer,
    "error_code" "text",
    "error_message" "text",
    "started_at" timestamp with time zone,
    "completed_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "learning_review_runs_container_type_not_blank" CHECK (("char_length"(TRIM(BOTH FROM "container_type")) > 0)),
    CONSTRAINT "learning_review_runs_duration_ms_nonnegative" CHECK ((("duration_ms" IS NULL) OR ("duration_ms" >= 0))),
    CONSTRAINT "learning_review_runs_input_token_count_nonnegative" CHECK ((("input_token_count" IS NULL) OR ("input_token_count" >= 0))),
    CONSTRAINT "learning_review_runs_memory_pack_count_nonnegative" CHECK (("memory_pack_count" >= 0)),
    CONSTRAINT "learning_review_runs_output_token_count_nonnegative" CHECK ((("output_token_count" IS NULL) OR ("output_token_count" >= 0))),
    CONSTRAINT "learning_review_runs_prompt_hash_not_blank" CHECK (("char_length"(TRIM(BOTH FROM "prompt_hash")) > 0)),
    CONSTRAINT "learning_review_runs_prompt_version_not_blank" CHECK (("char_length"(TRIM(BOTH FROM "prompt_version")) > 0)),
