CREATE OR REPLACE VIEW "public"."opportunity_award_pricing_reconciliation_v1" WITH ("security_invoker"='true') AS
 WITH "facts" AS (
         SELECT "mapping"."organization_id",
            "mapping"."opportunity_id",
            "mapping"."project_id",
            "mapping"."accepted_quote_id",
            "opportunity"."slug" AS "opportunity_slug",
            "opportunity"."converted_project_id",
            "quote"."originating_opportunity_id",
            "quote"."project_id" AS "quote_project_id",
            "quote"."quote_number",
            "quote"."total_quote_price",
            (COALESCE("workbooks"."candidate_count", (0)::bigint))::integer AS "candidate_workbook_count",
            (COALESCE("lines"."line_count", (0)::bigint))::integer AS "quote_line_count",
            (COALESCE("lines"."unresolved_line_count", (0)::bigint))::integer AS "unresolved_line_count",
            (COALESCE("links"."linked_line_count", (0)::bigint))::integer AS "worksheet_linked_quote_line_count",
            (COALESCE("links"."linked_workbook_count", (0)::bigint))::integer AS "distinct_linked_workbook_count",
            (COALESCE("links"."invalid_count", (0)::bigint))::integer AS "invalid_worksheet_link_count",
            COALESCE("workbooks"."workbook_ids", '[]'::"jsonb") AS "candidate_workbook_ids",
            COALESCE("links"."link_evidence", '[]'::"jsonb") AS "candidate_source_links"
           FROM ((((("public"."opportunity_final_projects" "mapping"
             LEFT JOIN "public"."organization_opportunities" "opportunity" ON ((("opportunity"."organization_id" = "mapping"."organization_id") AND ("opportunity"."id" = "mapping"."opportunity_id"))))
             LEFT JOIN "public"."project_quotes" "quote" ON ((("quote"."organization_id" = "mapping"."organization_id") AND ("quote"."id" = "mapping"."accepted_quote_id"))))
             LEFT JOIN LATERAL ( SELECT "count"(*) AS "candidate_count",
                    "jsonb_agg"("workbook"."id" ORDER BY "workbook"."created_at") AS "workbook_ids"
                   FROM "public"."opportunity_pricing_worksheets" "workbook"
                  WHERE (("workbook"."organization_id" = "mapping"."organization_id") AND ("workbook"."opportunity_id" = "mapping"."opportunity_id") AND ("workbook"."quote_id" IS NULL) AND ("workbook"."variation_id" IS NULL) AND ("workbook"."archived_at" IS NULL))) "workbooks" ON (true))
             LEFT JOIN LATERAL ( SELECT "count"(*) AS "line_count",
                    "count"(*) FILTER (WHERE ("line"."pricing_source_kind" = 'unresolved'::"text")) AS "unresolved_line_count"
                   FROM "public"."project_quote_line_items" "line"
                  WHERE (("line"."organization_id" = "mapping"."organization_id") AND ("line"."quote_id" = "mapping"."accepted_quote_id"))) "lines" ON (true))
             LEFT JOIN LATERAL ( SELECT "count"(DISTINCT "link"."document_line_id") AS "linked_line_count",
                    "count"(DISTINCT "item"."source_workbook_id") AS "linked_workbook_count",
                    "count"(*) FILTER (WHERE (("item"."id" IS NULL) OR ("workbook"."id" IS NULL) OR ("sheet"."id" IS NULL) OR ("line"."id" IS NULL))) AS "invalid_count",
                    "jsonb_agg"("jsonb_build_object"('lineId', "link"."document_line_id", 'commercialItemId', "item"."id", 'workbookId', "item"."source_workbook_id", 'sheetId', "item"."source_sheet_id", 'range', "item"."source_range") ORDER BY "link"."document_line_id") AS "link_evidence"
                   FROM (((("public"."commercial_item_document_links" "link"
                     LEFT JOIN "public"."commercial_items" "item" ON ((("item"."organization_id" = "link"."organization_id") AND ("item"."id" = "link"."commercial_item_id"))))
                     LEFT JOIN "public"."opportunity_pricing_worksheets" "workbook" ON ((("workbook"."organization_id" = "item"."organization_id") AND ("workbook"."id" = "item"."source_workbook_id"))))
                     LEFT JOIN "public"."opportunity_pricing_workbook_sheets" "sheet" ON ((("sheet"."organization_id" = "item"."organization_id") AND ("sheet"."workbook_id" = "item"."source_workbook_id") AND ("sheet"."id" = "item"."source_sheet_id"))))
                     LEFT JOIN "public"."project_quote_line_items" "line" ON ((("line"."organization_id" = "link"."organization_id") AND ("line"."quote_id" = "link"."document_id") AND ("line"."id" = "link"."document_line_id"))))
                  WHERE (("link"."organization_id" = "mapping"."organization_id") AND ("link"."document_kind" = 'quote_line'::"text") AND ("link"."document_id" = "mapping"."accepted_quote_id") AND ("link"."link_role" = 'source'::"text"))) "links" ON (true))
        )
 SELECT "organization_id",
    "opportunity_id",
    "project_id",
    "accepted_quote_id",
    "opportunity_slug",
    "converted_project_id",
    "originating_opportunity_id",
    "quote_project_id",
    "quote_number",
    "total_quote_price",
    "candidate_workbook_count",
    "quote_line_count",
    "unresolved_line_count",
    "worksheet_linked_quote_line_count",
    "distinct_linked_workbook_count",
    "invalid_worksheet_link_count",
    "candidate_workbook_ids",
    "candidate_source_links",
        CASE
            WHEN (("converted_project_id" IS DISTINCT FROM "project_id") OR ("accepted_quote_id" IS NULL) OR ("originating_opportunity_id" IS DISTINCT FROM "opportunity_id") OR ("quote_project_id" IS DISTINCT FROM "project_id") OR ("invalid_worksheet_link_count" > 0) OR ("worksheet_linked_quote_line_count" > "quote_line_count") OR ("distinct_linked_workbook_count" > "candidate_workbook_count")) THEN 'BROKEN_LINEAGE'::"text"
            WHEN ("unresolved_line_count" > 0) THEN 'AMBIGUOUS'::"text"
            WHEN (("candidate_workbook_count" = 0) AND ("quote_line_count" > 0)) THEN 'MANUAL_ONLY'::"text"
            WHEN (("candidate_workbook_count" = 0) AND ("quote_line_count" = 0)) THEN 'NO_WORKSHEET'::"text"
            WHEN (("quote_line_count" = 0) OR ("worksheet_linked_quote_line_count" = 0)) THEN 'AMBIGUOUS'::"text"
            WHEN ("worksheet_linked_quote_line_count" < "quote_line_count") THEN 'MIXED'::"text"
            WHEN ("distinct_linked_workbook_count" = 0) THEN 'BROKEN_LINEAGE'::"text"
            WHEN (("candidate_workbook_count" = 1) AND ("distinct_linked_workbook_count" = 1)) THEN 'EXACT'::"text"
            ELSE 'DERIVABLE'::"text"
        END AS "classification"
   FROM "facts";


