CREATE OR REPLACE VIEW "public"."opportunity_lifecycle_reconciliation_v1" WITH ("security_invoker"='true') AS
 SELECT "opportunity"."organization_id",
    "opportunity"."id" AS "opportunity_id",
    "opportunity"."workspace_project_id",
    "opportunity"."converted_project_id",
    "lifecycle"."id" AS "lifecycle_id",
    "lifecycle"."strategy",
    "lifecycle"."strategy_version",
    "final_project"."project_id" AS "mapped_project_id",
    "final_project"."accepted_quote_id" AS "mapped_accepted_quote_id",
        CASE
            WHEN (("lifecycle"."id" IS NOT NULL) AND ("lifecycle"."strategy" = 'promote_workspace_v1'::"text") AND ("opportunity"."workspace_project_id" = "opportunity"."converted_project_id") AND ("final_project"."project_id" = "opportunity"."workspace_project_id") AND ("promotion_event"."id" IS NOT NULL)) THEN 'completed_promoted_opportunity'::"text"
            WHEN (("lifecycle"."id" IS NOT NULL) AND ("lifecycle"."strategy" = 'promote_workspace_v1'::"text")) THEN 'marked_for_workspace_promotion'::"text"
            WHEN (("lifecycle"."id" IS NOT NULL) AND ("lifecycle"."strategy" = 'legacy_two_project_v1'::"text")) THEN 'marked_for_legacy_conversion'::"text"
            WHEN (("opportunity"."workspace_project_id" IS NOT NULL) AND ("opportunity"."converted_project_id" IS NOT NULL) AND ("opportunity"."workspace_project_id" <> "opportunity"."converted_project_id") AND ("final_project"."project_id" = "opportunity"."converted_project_id")) THEN 'historical_two_project'::"text"
            WHEN ("lifecycle"."id" IS NULL) THEN 'unmarked_pre_cutover'::"text"
            ELSE 'unclassified'::"text"
        END AS "record_shape",
    (("lifecycle"."id" IS NOT NULL) AND ("lifecycle"."original_workspace_project_id" IS DISTINCT FROM "opportunity"."workspace_project_id")) AS "lifecycle_workspace_contradiction",
    (("lifecycle"."id" IS NOT NULL) AND (("workspace"."id" IS NULL) OR ("workspace"."organization_id" <> "opportunity"."organization_id") OR ("workspace"."source_opportunity_id" IS DISTINCT FROM "opportunity"."id"))) AS "workspace_lineage_contradiction",
    (("final_project"."project_id" IS NOT NULL) AND ("final_project"."project_id" IS DISTINCT FROM "opportunity"."converted_project_id")) AS "final_mapping_contradiction",
    ( SELECT ("count"(*))::integer AS "count"
           FROM "public"."project_quotes" "accepted_quote"
          WHERE (("accepted_quote"."organization_id" = "opportunity"."organization_id") AND ("accepted_quote"."originating_opportunity_id" = "opportunity"."id") AND ("accepted_quote"."status" = 'Accepted'::"text"))) AS "accepted_quote_count",
    ( SELECT ("count"(*))::integer AS "count"
           FROM "public"."organization_projects" "candidate"
          WHERE (("candidate"."organization_id" = "opportunity"."organization_id") AND ("candidate"."source_opportunity_id" = "opportunity"."id") AND ("candidate"."id" <> "opportunity"."workspace_project_id") AND ("candidate"."id" IS DISTINCT FROM "opportunity"."converted_project_id"))) AS "orphan_final_candidate_count",
    (EXISTS ( SELECT 1
           FROM "public"."organization_opportunities" "other_opportunity"
          WHERE (("other_opportunity"."workspace_project_id" = "opportunity"."workspace_project_id") AND ("other_opportunity"."id" <> "opportunity"."id")))) AS "workspace_is_shared",
    (EXISTS ( SELECT 1
           FROM "public"."project_quotes" "quote"
          WHERE (("quote"."organization_id" = "opportunity"."organization_id") AND ("quote"."originating_opportunity_id" = "opportunity"."id") AND ("quote"."project_id" IS NOT NULL) AND ("quote"."project_id" <> ALL (ARRAY["opportunity"."workspace_project_id", "opportunity"."converted_project_id"]))))) AS "has_unrelated_quote_ownership",
    (EXISTS ( SELECT 1
           FROM "public"."commercial_items" "item"
          WHERE (("item"."organization_id" = "opportunity"."organization_id") AND ("item"."opportunity_id" = "opportunity"."id") AND ("item"."project_id" IS NOT NULL) AND ("item"."project_id" <> ALL (ARRAY["opportunity"."workspace_project_id", "opportunity"."converted_project_id"]))))) AS "has_unrelated_commercial_ownership",
    (EXISTS ( SELECT 1
           FROM ("public"."cost_items" "cost_item"
             JOIN "public"."project_quotes" "quote" ON ((("quote"."id" = "cost_item"."source_document_id") AND ("cost_item"."source_document_kind" = 'project_quote'::"text") AND ("quote"."organization_id" = "cost_item"."organization_id"))))
          WHERE (("quote"."organization_id" = "opportunity"."organization_id") AND ("quote"."originating_opportunity_id" = "opportunity"."id") AND ("cost_item"."project_id" <> ALL (ARRAY["opportunity"."workspace_project_id", "opportunity"."converted_project_id"]))))) AS "has_unrelated_cost_ownership"
   FROM (((("public"."organization_opportunities" "opportunity"
     LEFT JOIN "public"."opportunity_lifecycles" "lifecycle" ON ((("lifecycle"."organization_id" = "opportunity"."organization_id") AND ("lifecycle"."opportunity_id" = "opportunity"."id"))))
     LEFT JOIN "public"."organization_projects" "workspace" ON (("workspace"."id" = "opportunity"."workspace_project_id")))
     LEFT JOIN "public"."opportunity_final_projects" "final_project" ON ((("final_project"."organization_id" = "opportunity"."organization_id") AND ("final_project"."opportunity_id" = "opportunity"."id"))))
     LEFT JOIN "public"."opportunity_promotion_events" "promotion_event" ON ((("promotion_event"."organization_id" = "opportunity"."organization_id") AND ("promotion_event"."opportunity_id" = "opportunity"."id"))));


ALTER VIEW "public"."opportunity_lifecycle_reconciliation_v1" OWNER TO "postgres";


