    CONSTRAINT "opportunity_lifecycle_rollout_promotion_pilot_check" CHECK ((("promotion_enabled" IS FALSE) OR ("creation_enabled" AND ("allowed_strategy" = 'promote_workspace_v1'::"text") AND ((("pilot_scope" = 'local_admin_pilot'::"text") AND ("pilot_environment" = 'local_development'::"text")) OR (("pilot_scope" = 'hosted_development_allowlist'::"text") AND ("pilot_environment" = 'hosted_development'::"text")))))),
    CONSTRAINT "opportunity_lifecycle_rollout_strategy_check" CHECK (("allowed_strategy" = ANY (ARRAY['legacy_two_project_v1'::"text", 'promote_workspace_v1'::"text"])))
);

