    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "opportunity_id" "uuid" NOT NULL,
    "workspace_project_id" "uuid",
    "accepted_quote_id" "uuid" NOT NULL,
    "final_project_id" "uuid",
    "lifecycle_strategy" "text" NOT NULL,
    "lifecycle_strategy_version" smallint NOT NULL,
    "evaluator_version" "text" NOT NULL,
    "conversion_correlation_id" "uuid" NOT NULL,
    "observation_kind" "text" DEFAULT 'prospective'::"text" NOT NULL,
    "status" "text" DEFAULT 'pre_observed'::"text" NOT NULL,
    "eligibility_result" "text" NOT NULL,
    "eligibility_failure_codes" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "predicted_final_project_identity_rule" "text" DEFAULT 'workspace_project_id'::"text" NOT NULL,
    "pre_snapshot" "jsonb" NOT NULL,
    "post_snapshot" "jsonb",
    "comparison_result" "text",
    "mismatch_codes" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "immutable_payload_hash" "text" NOT NULL,
    "pre_observed_at" timestamp with time zone DEFAULT "timezone"('utc'::"text", "now"()) NOT NULL,
    "compared_at" timestamp with time zone,
    "created_by" "uuid" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "timezone"('utc'::"text", "now"()) NOT NULL,
    "expected_difference_codes" "text"[] DEFAULT ARRAY[]::"text"[] NOT NULL,
    CONSTRAINT "opportunity_promotion_shadow_comparison_result_check" CHECK ((("comparison_result" IS NULL) OR ("comparison_result" = ANY (ARRAY['match'::"text", 'expected_difference'::"text", 'ineligible'::"text", 'mismatch'::"text", 'comparison_error'::"text"])))),
    CONSTRAINT "opportunity_promotion_shadow_completion_shape_check" CHECK (((("status" = 'pre_observed'::"text") AND ("final_project_id" IS NULL) AND ("post_snapshot" IS NULL) AND ("comparison_result" IS NULL) AND ("compared_at" IS NULL)) OR (("status" = ANY (ARRAY['completed'::"text", 'comparison_error'::"text"])) AND ("final_project_id" IS NOT NULL) AND ("post_snapshot" IS NOT NULL) AND ("comparison_result" IS NOT NULL) AND ("compared_at" IS NOT NULL)))),
    CONSTRAINT "opportunity_promotion_shadow_eligibility_check" CHECK (("eligibility_result" = ANY (ARRAY['eligible'::"text", 'ineligible'::"text"]))),
    CONSTRAINT "opportunity_promotion_shadow_evaluator_version_check" CHECK (("evaluator_version" = ANY (ARRAY['shadow-v1'::"text", 'shadow-v2'::"text"]))),
    CONSTRAINT "opportunity_promotion_shadow_expected_difference_codes_check" CHECK (("expected_difference_codes" <@ ARRAY['legacy_final_does_not_own_workspace_tasks'::"text", 'legacy_final_does_not_own_takeoff_pages'::"text", 'legacy_final_does_not_own_takeoff_measurements'::"text", 'promoted_workspace_task_continuity_verified'::"text", 'promoted_workspace_takeoff_continuity_verified'::"text", 'promoted_workspace_measurement_continuity_verified'::"text"])),
    CONSTRAINT "opportunity_promotion_shadow_failure_codes_check" CHECK (("eligibility_failure_codes" <@ ARRAY['opportunity_not_found'::"text", 'lifecycle_missing'::"text", 'strategy_not_legacy'::"text", 'workspace_missing'::"text", 'workspace_lineage_invalid'::"text", 'workspace_shared'::"text", 'existing_conversion_state'::"text", 'accepted_quote_missing'::"text", 'accepted_quote_not_accepted'::"text", 'accepted_quote_superseded'::"text", 'multiple_accepted_quotes'::"text", 'quote_ownership_invalid'::"text", 'quote_line_ownership_invalid'::"text", 'commercial_ownership_invalid'::"text", 'cost_ownership_invalid'::"text", 'currency_or_tax_invalid'::"text", 'document_workspace_missing'::"text", 'document_workspace_ambiguous'::"text", 'orphan_final_candidate'::"text"])),
    CONSTRAINT "opportunity_promotion_shadow_hash_check" CHECK (("immutable_payload_hash" ~ '^[a-f0-9]{64}$'::"text")),
    CONSTRAINT "opportunity_promotion_shadow_identity_rule_check" CHECK (("predicted_final_project_identity_rule" = 'workspace_project_id'::"text")),
    CONSTRAINT "opportunity_promotion_shadow_kind_check" CHECK (("observation_kind" = 'prospective'::"text")),
    CONSTRAINT "opportunity_promotion_shadow_mismatch_codes_check" CHECK (("mismatch_codes" <@ ARRAY['identity_mismatch'::"text", 'baseline_quote_mismatch'::"text", 'baseline_total_mismatch'::"text", 'quote_line_count_mismatch'::"text", 'commercial_item_mismatch'::"text", 'cost_item_mismatch'::"text", 'document_workspace_mismatch'::"text", 'document_count_mismatch'::"text", 'drawing_count_mismatch'::"text", 'takeoff_count_mismatch'::"text", 'scope_count_mismatch'::"text", 'trade_pack_count_mismatch'::"text", 'task_count_mismatch'::"text", 'visibility_mismatch'::"text", 'delivery_eligibility_mismatch'::"text", 'lineage_mismatch'::"text", 'ambiguous_source_state'::"text", 'comparison_failed'::"text", 'task_continuity_mismatch'::"text", 'takeoff_page_continuity_mismatch'::"text", 'measurement_continuity_mismatch'::"text", 'calibration_continuity_mismatch'::"text", 'workspace_history_continuity_mismatch'::"text", 'pricing_workbook_continuity_mismatch'::"text"])),
    CONSTRAINT "opportunity_promotion_shadow_post_snapshot_check" CHECK ((("post_snapshot" IS NULL) OR ("jsonb_typeof"("post_snapshot") = 'object'::"text"))),
    CONSTRAINT "opportunity_promotion_shadow_pre_snapshot_check" CHECK (("jsonb_typeof"("pre_snapshot") = 'object'::"text")),
    CONSTRAINT "opportunity_promotion_shadow_status_check" CHECK (("status" = ANY (ARRAY['pre_observed'::"text", 'completed'::"text", 'comparison_error'::"text"]))),
    CONSTRAINT "opportunity_promotion_shadow_strategy_check" CHECK (("lifecycle_strategy" = 'legacy_two_project_v1'::"text")),
    CONSTRAINT "opportunity_promotion_shadow_strategy_version_check" CHECK (("lifecycle_strategy_version" = 1))
);

