    CONSTRAINT "organization_accounting_documents_attachment_status_check" CHECK (("attachment_status" = ANY (ARRAY['not_attached'::"text", 'queued'::"text", 'attaching'::"text", 'attached'::"text", 'failed'::"text"]))),
    CONSTRAINT "organization_accounting_documents_export_status_check" CHECK (("export_status" = ANY (ARRAY['not_ready'::"text", 'queued'::"text", 'exporting'::"text", 'exported'::"text", 'failed'::"text", 'attention_required'::"text", 'cancelled'::"text"]))),
    CONSTRAINT "organization_accounting_documents_external_identity_check" CHECK ((("external_document_id" IS NULL) OR ("char_length"(TRIM(BOTH FROM "external_document_id")) > 0))),
    CONSTRAINT "organization_accounting_documents_inbound_amounts_non_negative" CHECK (((("amount_paid" IS NULL) OR ("amount_paid" >= (0)::numeric)) AND (("amount_due" IS NULL) OR ("amount_due" >= (0)::numeric)) AND (("amount_credited" IS NULL) OR ("amount_credited" >= (0)::numeric)))),
    CONSTRAINT "organization_accounting_documents_integration_contract_check" CHECK ((("integration_contract" IS NULL) OR ("integration_contract" = ANY (ARRAY['payment_claim_revision_v1'::"text", 'retention_claim_revision_v1'::"text"])))),
    CONSTRAINT "organization_accounting_documents_last_synced_hash_not_blank" CHECK ((("last_synced_hash" IS NULL) OR ("char_length"(TRIM(BOTH FROM "last_synced_hash")) > 0))),
    CONSTRAINT "organization_accounting_documents_local_identity_shape_check" CHECK (((("local_document_type" = 'supplier_invoice'::"text") AND ("local_document_id" IS NOT NULL) AND ("project_claim_id" IS NULL) AND ("retention_claim_id" IS NULL)) OR (("local_document_type" = 'project_claim'::"text") AND ("local_document_id" IS NULL) AND ("project_claim_id" IS NOT NULL) AND ("retention_claim_id" IS NULL) AND ("current_version_id" IS NULL)) OR (("local_document_type" = 'retention_claim'::"text") AND ("local_document_id" IS NULL) AND ("project_claim_id" IS NULL) AND ("retention_claim_id" IS NOT NULL) AND ("current_version_id" IS NULL)))),
    CONSTRAINT "organization_accounting_documents_normalized_external_status_ch" CHECK ((("normalized_external_status" IS NULL) OR ("normalized_external_status" = ANY (ARRAY['draft'::"text", 'awaiting_approval'::"text", 'awaiting_payment'::"text", 'partially_paid'::"text", 'paid'::"text", 'voided'::"text", 'deleted'::"text", 'unknown'::"text"])))),
    CONSTRAINT "organization_accounting_documents_provider_check" CHECK (("provider" = 'xero'::"text")),
    CONSTRAINT "organization_accounting_documents_tenant_not_blank" CHECK (("char_length"(TRIM(BOTH FROM "tenant_id")) > 0)),
    CONSTRAINT "organization_accounting_documents_type_check" CHECK (("local_document_type" = ANY (ARRAY['supplier_invoice'::"text", 'project_claim'::"text", 'retention_claim'::"text"])))
);

