    "organization_id" "uuid" NOT NULL,
    "import_batch_id" "uuid" NOT NULL,
    "row_index" integer DEFAULT 0 NOT NULL,
    "extracted_name" "text",
    "extracted_description" "text",
    "extracted_unit" "text",
    "extracted_unit_cost" numeric(14,4),
    "extracted_currency" "text",
    "supplier_description" "text",
    "supplier_sku" "text",
    "matched_material_id" "uuid",
    "action" "text" DEFAULT 'pending'::"text" NOT NULL,
    "status" "text" DEFAULT 'pending_review'::"text" NOT NULL,
    "confidence" numeric(5,4),
    "reviewed_name" "text",
    "reviewed_description" "text",
    "reviewed_unit" "text",
    "reviewed_unit_cost" numeric(14,4),
    "reviewed_currency" "text",
    "reviewed_supplier_description" "text",
    "reviewed_supplier_sku" "text",
    "reviewed_by" "uuid",
    "reviewed_at" timestamp with time zone,
    "source_payload" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "classified_work_type" "text",
    "classified_cost_type" "text",
    "classified_cost_code" "text",
    "classified_confidence" numeric,
    "classified_source" "text",
    "classified_needs_review" boolean DEFAULT false NOT NULL,
    "classified_original_classification" "jsonb",
    "classified_final_classification" "jsonb",
    "classified_organization_cost_code_id" "uuid",
    "classification_reason_summary" "text",
    "classified_tradesstack_cost_code" integer,
    "classified_tradesstack_cost_code_label" "text",
    "classified_accounting_mapping_id" "uuid",
    "classified_review_status" "text",
    "classified_review_reason" "text",
    "classified_ai_construction_intelligence" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "approved_supplier_product_id" "uuid",
    "approved_supplier_price_id" "uuid",
    "approved_unit_conversion_id" "uuid",
    CONSTRAINT "organization_material_import_rows_action_check" CHECK (("action" = ANY (ARRAY['pending'::"text", 'create_material'::"text", 'match_material'::"text", 'skip'::"text"]))),
    CONSTRAINT "organization_material_import_rows_classified_confidence_check" CHECK ((("classified_confidence" IS NULL) OR (("classified_confidence" >= (0)::numeric) AND ("classified_confidence" <= (1)::numeric)))),
    CONSTRAINT "organization_material_import_rows_classified_final_object_check" CHECK ((("classified_final_classification" IS NULL) OR ("jsonb_typeof"("classified_final_classification") = 'object'::"text"))),
    CONSTRAINT "organization_material_import_rows_classified_original_object_ch" CHECK ((("classified_original_classification" IS NULL) OR ("jsonb_typeof"("classified_original_classification") = 'object'::"text"))),
    CONSTRAINT "organization_material_import_rows_classified_source_check" CHECK ((("classified_source" IS NULL) OR ("classified_source" = ANY (ARRAY['rules'::"text", 'user_confirmed'::"text", 'ai'::"text", 'imported'::"text"])))),
    CONSTRAINT "organization_material_import_rows_confidence_check" CHECK ((("confidence" IS NULL) OR (("confidence" >= (0)::numeric) AND ("confidence" <= (1)::numeric)))),
    CONSTRAINT "organization_material_import_rows_reviewed_unit_cost_check" CHECK ((("reviewed_unit_cost" IS NULL) OR ("reviewed_unit_cost" >= (0)::numeric))),
    CONSTRAINT "organization_material_import_rows_status_check" CHECK (("status" = ANY (ARRAY['pending_review'::"text", 'approved'::"text", 'rejected'::"text", 'error'::"text"]))),
    CONSTRAINT "organization_material_import_rows_unit_cost_check" CHECK ((("extracted_unit_cost" IS NULL) OR ("extracted_unit_cost" >= (0)::numeric)))
);

ALTER TABLE ONLY "public"."organization_material_import_rows" FORCE ROW LEVEL SECURITY;


ALTER TABLE "public"."organization_material_import_rows" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."organization_material_import_runs" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "import_batch_id" "uuid" NOT NULL,
    "provider" "text" DEFAULT 'anthropic'::"text" NOT NULL,
    "model" "text",
    "contract_version" "text" DEFAULT 'material_supplier_pricing_v1'::"text" NOT NULL,
    "prompt_version" "text",
    "status" "text" DEFAULT 'queued'::"text" NOT NULL,
    "attempt" integer DEFAULT 0 NOT NULL,
    "request_ids" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "usage_json" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "chunk_manifest" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "partial" boolean DEFAULT false NOT NULL,
    "raw_provider_response_retained" boolean DEFAULT false NOT NULL,
    "error_code" "text",
    "error_message" "text",
    "started_at" timestamp with time zone,
    "completed_at" timestamp with time zone,
    "duration_ms" integer,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "organization_material_import_runs_attempt_check" CHECK (("attempt" >= 0)),
    CONSTRAINT "organization_material_import_runs_duration_check" CHECK ((("duration_ms" IS NULL) OR ("duration_ms" >= 0))),
    CONSTRAINT "organization_material_import_runs_status_check" CHECK (("status" = ANY (ARRAY['queued'::"text", 'processing'::"text", 'completed'::"text", 'partial'::"text", 'failed'::"text", 'cancelled'::"text"])))
);


ALTER TABLE "public"."organization_material_import_runs" OWNER TO "postgres";


