CREATE TABLE IF NOT EXISTS "public"."organization_material_supplier_prices" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "material_id" "uuid" NOT NULL,
    "supplier_id" "uuid" NOT NULL,
    "import_batch_id" "uuid",
    "supplier_sku" "text",
    "supplier_description" "text",
    "unit" "text" NOT NULL,
    "unit_cost" numeric(14,4) NOT NULL,
    "currency" "text" DEFAULT 'NZD'::"text" NOT NULL,
    "is_preferred" boolean DEFAULT false NOT NULL,
    "is_current" boolean DEFAULT true NOT NULL,
    "source" "text" DEFAULT 'manual'::"text" NOT NULL,
    "effective_from" timestamp with time zone DEFAULT "now"() NOT NULL,
    "effective_to" timestamp with time zone,
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "supplier_product_id" "uuid" NOT NULL,
    "import_row_id" "uuid",
    "supersedes_price_id" "uuid",
    "idempotency_key" "text",
    "observation_metadata" "jsonb",
    "source_tax_basis" "text" DEFAULT 'unknown'::"text" NOT NULL,
    "source_tax_rate" numeric(12,8),
    "tax_jurisdiction_code" "text",
    "comparison_tax_basis" "text",
    "comparison_tax_rate" numeric(12,8),
    "tax_policy_snapshot" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "tax_evidence" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    CONSTRAINT "organization_material_supplier_price_comparison_tax_basis_check" CHECK ((("comparison_tax_basis" IS NULL) OR ("comparison_tax_basis" = ANY (ARRAY['exclusive'::"text", 'inclusive'::"text"])))),
    CONSTRAINT "organization_material_supplier_prices_comparison_tax_rate_check" CHECK ((("comparison_tax_rate" IS NULL) OR (("comparison_tax_rate" >= (0)::numeric) AND ("comparison_tax_rate" < (100)::numeric)))),
    CONSTRAINT "organization_material_supplier_prices_currency_not_blank" CHECK (("char_length"(TRIM(BOTH FROM "currency")) > 0)),
    CONSTRAINT "organization_material_supplier_prices_effective_window_check" CHECK ((("effective_to" IS NULL) OR ("effective_to" > "effective_from"))),
    CONSTRAINT "organization_material_supplier_prices_idempotency_key_not_blank" CHECK ((("idempotency_key" IS NULL) OR ("char_length"("btrim"("idempotency_key")) > 0))),
    CONSTRAINT "organization_material_supplier_prices_no_self_supersession_chec" CHECK ((("supersedes_price_id" IS NULL) OR ("supersedes_price_id" <> "id"))),
    CONSTRAINT "organization_material_supplier_prices_source_check" CHECK (("source" = ANY (ARRAY['manual'::"text", 'import'::"text", 'supplier_invoice'::"text", 'purchase_order'::"text", 'api'::"text"]))),
    CONSTRAINT "organization_material_supplier_prices_source_tax_basis_check" CHECK (("source_tax_basis" = ANY (ARRAY['exclusive'::"text", 'inclusive'::"text", 'zero_rated'::"text", 'exempt'::"text", 'no_tax'::"text", 'unknown'::"text"]))),
    CONSTRAINT "organization_material_supplier_prices_source_tax_rate_check" CHECK ((("source_tax_rate" IS NULL) OR (("source_tax_rate" >= (0)::numeric) AND ("source_tax_rate" < (100)::numeric)))),
    CONSTRAINT "organization_material_supplier_prices_unit_cost_check" CHECK (("unit_cost" >= (0)::numeric)),
    CONSTRAINT "organization_material_supplier_prices_unit_not_blank" CHECK (("char_length"(TRIM(BOTH FROM "unit")) > 0))
);

ALTER TABLE ONLY "public"."organization_material_supplier_prices" FORCE ROW LEVEL SECURITY;


ALTER TABLE "public"."organization_material_supplier_prices" OWNER TO "postgres";


COMMENT ON COLUMN "public"."organization_material_supplier_prices"."is_preferred" IS 'Legacy compatibility cache synchronized from Supplier Product preference; never authoritative for reads.';



COMMENT ON COLUMN "public"."organization_material_supplier_prices"."is_current" IS 'Legacy compatibility cache maintained by atomic writers; never authoritative for reads.';



COMMENT ON COLUMN "public"."organization_material_supplier_prices"."supplier_product_id" IS 'Required durable Supplier Product identity for every Phase 1 price observation.';



