    "material_unit" "text" NOT NULL,
    "normalized_material_unit" "text" GENERATED ALWAYS AS ("lower"("regexp_replace"("btrim"("material_unit"), '\s+'::"text", ' '::"text", 'g'::"text"))) STORED,
    "supplier_quantity" numeric(18,6) NOT NULL,
    "material_quantity" numeric(18,6) NOT NULL,
    "source" "text" NOT NULL,
    "contract_version" "text" NOT NULL,
    "proposal_metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "source_import_row_id" "uuid",
    "confirmed_by" "uuid" NOT NULL,
    "confirmed_at" timestamp with time zone DEFAULT "statement_timestamp"() NOT NULL,
    "effective_from" timestamp with time zone DEFAULT "statement_timestamp"() NOT NULL,
    "effective_to" timestamp with time zone,
    "supersedes_conversion_id" "uuid",
    "created_at" timestamp with time zone DEFAULT "statement_timestamp"() NOT NULL,
    CONSTRAINT "organization_material_supplier_product_unit_conversions_contrac" CHECK (("char_length"("btrim"("contract_version")) > 0)),
    CONSTRAINT "organization_material_supplier_product_unit_conversions_materia" CHECK (("char_length"("btrim"("material_unit")) > 0)),
    CONSTRAINT "organization_material_supplier_product_unit_conversions_quantit" CHECK ((("supplier_quantity" > (0)::numeric) AND ("material_quantity" > (0)::numeric))),
    CONSTRAINT "organization_material_supplier_product_unit_conversions_source_" CHECK (("source" = ANY (ARRAY['user_confirmed_ai'::"text", 'user_confirmed_manual'::"text"]))),
    CONSTRAINT "organization_material_supplier_product_unit_conversions_supplie" CHECK (("char_length"("btrim"("supplier_unit")) > 0)),
    CONSTRAINT "organization_material_supplier_product_unit_conversions_window_" CHECK ((("effective_to" IS NULL) OR ("effective_to" > "effective_from")))
);

ALTER TABLE ONLY "public"."organization_material_supplier_product_unit_conversions" FORCE ROW LEVEL SECURITY;


ALTER TABLE "public"."organization_material_supplier_product_unit_conversions" OWNER TO "postgres";


