CREATE TABLE IF NOT EXISTS "public"."organization_material_supplier_products" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "material_id" "uuid" NOT NULL,
    "supplier_id" "uuid" NOT NULL,
    "supplier_sku" "text",
    "normalized_supplier_sku" "text" GENERATED ALWAYS AS (NULLIF("lower"("regexp_replace"("btrim"("supplier_sku"), '\s+'::"text", ' '::"text", 'g'::"text")), ''::"text")) STORED,
    "supplier_description" "text",
    "normalized_supplier_description" "text" GENERATED ALWAYS AS (NULLIF("lower"("regexp_replace"("btrim"("supplier_description"), '\s+'::"text", ' '::"text", 'g'::"text")), ''::"text")) STORED,
    "supplier_unit" "text" NOT NULL,
    "normalized_supplier_unit" "text" GENERATED ALWAYS AS ("lower"("regexp_replace"("btrim"("supplier_unit"), '\s+'::"text", ' '::"text", 'g'::"text"))) STORED,
    "identity_variant" "text" DEFAULT 'default'::"text" NOT NULL,
    "identity_status" "text" DEFAULT 'confirmed'::"text" NOT NULL,
    "is_preferred" boolean DEFAULT false NOT NULL,
    "is_active" boolean DEFAULT true NOT NULL,
    "archived_at" timestamp with time zone,
    "archived_by" "uuid",
    "created_source" "text" DEFAULT 'manual'::"text" NOT NULL,
    "first_seen_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "last_seen_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_by" "uuid",
    "updated_by" "uuid",
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "pack_quantity" numeric(14,4),
    "pack_unit" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "organization_material_supplier_products_archive_state_check" CHECK ((("archived_at" IS NULL) OR ("is_active" = false))),
    CONSTRAINT "organization_material_supplier_products_confirmed_identity_chec" CHECK ((("identity_status" <> 'confirmed'::"text") OR ("normalized_supplier_sku" IS NOT NULL) OR ("normalized_supplier_description" IS NOT NULL))),
    CONSTRAINT "organization_material_supplier_products_created_source_not_blan" CHECK (("char_length"("btrim"("created_source")) > 0)),
    CONSTRAINT "organization_material_supplier_products_identity_status_check" CHECK (("identity_status" = ANY (ARRAY['confirmed'::"text", 'migrated_unverified'::"text", 'needs_review'::"text"]))),
    CONSTRAINT "organization_material_supplier_products_identity_variant_not_bl" CHECK (("char_length"("btrim"("identity_variant")) > 0)),
    CONSTRAINT "organization_material_supplier_products_pack_quantity_check" CHECK ((("pack_quantity" IS NULL) OR ("pack_quantity" > (0)::numeric))),
    CONSTRAINT "organization_material_supplier_products_pack_unit_check" CHECK ((("pack_unit" IS NULL) OR ("char_length"("btrim"("pack_unit")) > 0))),
    CONSTRAINT "organization_material_supplier_products_preferred_state_check" CHECK ((("is_preferred" = false) OR (("is_active" = true) AND ("archived_at" IS NULL)))),
    CONSTRAINT "organization_material_supplier_products_seen_window_check" CHECK (("last_seen_at" >= "first_seen_at")),
    CONSTRAINT "organization_material_supplier_products_supplier_unit_not_blank" CHECK (("char_length"("btrim"("supplier_unit")) > 0))
);

ALTER TABLE ONLY "public"."organization_material_supplier_products" FORCE ROW LEVEL SECURITY;


ALTER TABLE "public"."organization_material_supplier_products" OWNER TO "postgres";


