CREATE TABLE IF NOT EXISTS "public"."organization_memory_lifecycle_history" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "memory_id" "uuid" NOT NULL,
    "lifecycle_event_type" "text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "source_semantic_pool_id" "uuid",
    "source_revision_hash" "text",
    "synthesis_history_id" "uuid",
    "synthesis_queue_row_id" "uuid",
    "synthesis_run_id" "uuid",
    "before_memory_snapshot" "jsonb",
    "after_memory_snapshot" "jsonb",
    "reason_summary" "text",
    "schema_version" integer DEFAULT 1 NOT NULL,
    "lifecycle_metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "event_origin_type" "text" DEFAULT 'synthesis'::"text" NOT NULL,
    "source_memory_pool_type" "text",
    "source_memory_pool_id" "uuid",
    "source_queue_type" "text",
    "source_queue_id" "uuid",
    "source_run_type" "text",
    "source_run_id" "uuid",
    CONSTRAINT "omlh_event_origin_type_check" CHECK (("event_origin_type" = ANY (ARRAY['synthesis'::"text", 'retirement_evaluator'::"text", 'manual_admin'::"text"]))),
    CONSTRAINT "omlh_lifecycle_event_type_check" CHECK (("lifecycle_event_type" = ANY (ARRAY['memory_created'::"text", 'memory_reused'::"text", 'memory_updated'::"text", 'memory_reconciled'::"text", 'memory_reinforced'::"text", 'memory_contradicted'::"text", 'memory_superseded'::"text", 'memory_retired'::"text"]))),
    CONSTRAINT "omlh_lifecycle_metadata_object_check" CHECK (("jsonb_typeof"("lifecycle_metadata") = 'object'::"text")),
    CONSTRAINT "omlh_schema_version_positive" CHECK (("schema_version" > 0)),
    CONSTRAINT "omlh_source_revision_hash_not_blank" CHECK (("char_length"(TRIM(BOTH FROM "source_revision_hash")) > 0)),
    CONSTRAINT "omlh_synthesis_origin_linkage_check" CHECK (
CASE
    WHEN ("event_origin_type" = 'synthesis'::"text") THEN ((("source_semantic_pool_id" IS NOT NULL) AND ("source_revision_hash" IS NOT NULL) AND ("synthesis_history_id" IS NOT NULL) AND ("synthesis_queue_row_id" IS NOT NULL) AND ("synthesis_run_id" IS NOT NULL)) OR (("source_memory_pool_type" IS NOT NULL) AND ("source_memory_pool_id" IS NOT NULL) AND ("source_revision_hash" IS NOT NULL) AND ("synthesis_history_id" IS NOT NULL) AND ("source_queue_type" IS NOT NULL) AND ("source_queue_id" IS NOT NULL) AND ("source_run_type" IS NOT NULL) AND ("source_run_id" IS NOT NULL)))
    ELSE true
END)
);

