    "origin_accounting_document_id" "uuid",
    "origin_accounting_revision_id" "uuid",
    "origin_accounting_revision_line_id" "uuid",
    "legacy_tax_classification_id" "uuid",
    "allocation_id" "uuid" NOT NULL,
    "allocation_sequence" integer NOT NULL,
    "evidence_kind" "text" NOT NULL,
    "tax_type" "text" NOT NULL,
    "tax_rate_snapshot_id" "text",
    "tax_rate_name_snapshot" "text",
    "effective_rate_basis_points" integer NOT NULL,
    "origin_account_code_snapshot" "text" NOT NULL,
    "origin_account_id_snapshot" "text",
    "origin_retained_amount_minor" bigint NOT NULL,
    "origin_retained_tax_minor" bigint NOT NULL,
    "origin_retained_total_minor" bigint NOT NULL,
    "released_amount_minor" bigint NOT NULL,
    "released_tax_minor" bigint NOT NULL,
    "released_total_minor" bigint NOT NULL,
    "reservation_state" "text" NOT NULL,
    "reservation_root_id" "uuid" NOT NULL,
    "reservation_sequence" integer NOT NULL,
    "supersedes_ledger_id" "uuid",
    "replacement_root_accounting_document_id" "uuid" NOT NULL,
    "predecessor_retention_revision_id" "uuid",
    "actor_user_id" "uuid",
    "system_actor" "text",
    "evidence_snapshot" "jsonb" NOT NULL,
    "evidence_hash" "text" NOT NULL,
    "schema_version" integer DEFAULT 2 NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "retention_release_ledger_v2_actor_check" CHECK (((("actor_user_id" IS NOT NULL) AND ("system_actor" IS NULL)) OR (("actor_user_id" IS NULL) AND (NULLIF(TRIM(BOTH FROM "system_actor"), ''::"text") IS NOT NULL)))),
    CONSTRAINT "retention_release_ledger_v2_evidence_check" CHECK ((("jsonb_typeof"("evidence_snapshot") = 'object'::"text") AND ("evidence_hash" ~ '^[a-f0-9]{64}$'::"text"))),
    CONSTRAINT "retention_release_ledger_v2_evidence_kind_check" CHECK (("evidence_kind" = ANY (ARRAY['immutable_revision'::"text", 'exact_legacy_adoption'::"text", 'submission_snapshot'::"text", 'reviewed_classification'::"text"]))),
    CONSTRAINT "retention_release_ledger_v2_modern_evidence_check" CHECK (((("evidence_kind" = ANY (ARRAY['immutable_revision'::"text", 'exact_legacy_adoption'::"text"])) AND ("origin_accounting_document_id" IS NOT NULL) AND ("origin_accounting_revision_id" IS NOT NULL) AND ("origin_accounting_revision_line_id" IS NOT NULL) AND ("legacy_tax_classification_id" IS NULL)) OR (("evidence_kind" = ANY (ARRAY['submission_snapshot'::"text", 'reviewed_classification'::"text"])) AND ("legacy_tax_classification_id" IS NOT NULL)))),
    CONSTRAINT "retention_release_ledger_v2_origin_amount_check" CHECK ((("origin_retained_amount_minor" <> 0) AND (("origin_retained_tax_minor" = 0) OR ("sign"(("origin_retained_amount_minor")::double precision) = "sign"(("origin_retained_tax_minor")::double precision))) AND ("origin_retained_total_minor" = ("origin_retained_amount_minor" + "origin_retained_tax_minor")))),
    CONSTRAINT "retention_release_ledger_v2_rate_check" CHECK (("effective_rate_basis_points" >= 0)),
    CONSTRAINT "retention_release_ledger_v2_release_amount_check" CHECK ((("released_amount_minor" <> 0) AND (("released_tax_minor" = 0) OR ("sign"(("released_amount_minor")::double precision) = "sign"(("released_tax_minor")::double precision))) AND ("released_total_minor" = ("released_amount_minor" + "released_tax_minor")) AND ("abs"("released_amount_minor") <= "abs"("origin_retained_amount_minor")) AND ("abs"("released_tax_minor") <= "abs"("origin_retained_tax_minor")))),
    CONSTRAINT "retention_release_ledger_v2_state_check" CHECK (("reservation_state" = ANY (ARRAY['pending'::"text", 'reserved'::"text", 'completed'::"text", 'cancelled'::"text", 'superseded'::"text"]))),
    CONSTRAINT "retention_release_ledger_v2_text_check" CHECK ((("char_length"(TRIM(BOTH FROM "tenant_id")) > 0) AND ("char_length"(TRIM(BOTH FROM "currency_code")) = 3) AND ("currency_code" = "upper"("currency_code")) AND ("char_length"(TRIM(BOTH FROM "tax_type")) > 0) AND ("tax_type" = "upper"("tax_type")) AND ("char_length"(TRIM(BOTH FROM "origin_account_code_snapshot")) > 0))),
    CONSTRAINT "retention_release_ledger_v2_version_check" CHECK ((("schema_version" = 2) AND ("allocation_sequence" > 0) AND ("reservation_sequence" > 0)))
);

