CREATE OR REPLACE VIEW "public"."project_lifecycle_reconciliation_v1" WITH ("security_invoker"='true') AS
 SELECT "project"."organization_id",
    "project"."id" AS "project_id",
    "project"."source_opportunity_id",
        CASE
            WHEN ("project"."source_opportunity_id" IS NULL) THEN 'direct_project'::"text"
            WHEN (("final_project"."project_id" = "project"."id") AND ("lifecycle"."strategy" = 'promote_workspace_v1'::"text") AND ("opportunity"."workspace_project_id" = "project"."id")) THEN 'promoted_project'::"text"
            WHEN ("final_project"."project_id" = "project"."id") THEN 'historical_final_project'::"text"
            WHEN ("opportunity"."workspace_project_id" = "project"."id") THEN 'tender_workspace'::"text"
            WHEN ("project"."source_opportunity_id" IS NOT NULL) THEN 'orphan_final_candidate'::"text"
            ELSE 'unclassified'::"text"
        END AS "project_shape",
    "lifecycle"."strategy",
    "lifecycle"."strategy_version"
   FROM ((("public"."organization_projects" "project"
     LEFT JOIN "public"."organization_opportunities" "opportunity" ON ((("opportunity"."organization_id" = "project"."organization_id") AND ("opportunity"."id" = "project"."source_opportunity_id"))))
     LEFT JOIN "public"."opportunity_lifecycles" "lifecycle" ON ((("lifecycle"."organization_id" = "project"."organization_id") AND ("lifecycle"."opportunity_id" = "opportunity"."id"))))
     LEFT JOIN "public"."opportunity_final_projects" "final_project" ON ((("final_project"."organization_id" = "project"."organization_id") AND ("final_project"."opportunity_id" = "opportunity"."id"))));


ALTER VIEW "public"."project_lifecycle_reconciliation_v1" OWNER TO "postgres";


