    "status" "text" DEFAULT 'draft'::"text" NOT NULL,
    "revision" bigint DEFAULT 1 NOT NULL,
    "trigger_type" "text" NOT NULL,
    "entitlement_method" "text" NOT NULL,
    "percentage_bps" integer,
    "fixed_amount" numeric(14,2),
    "cap_amount" numeric(14,2),
    "scope_policy" "text" DEFAULT 'explicit'::"text" NOT NULL,
    "scheduled_trigger_date" "date",
    "actual_trigger_date" "date",
    "delay_days" integer DEFAULT 0 NOT NULL,
    "eligibility_date" "date",
    "confirmation_required" boolean DEFAULT true NOT NULL,
    "trigger_confirmed_at" timestamp with time zone,
    "trigger_confirmed_by" "uuid",
    "trigger_confirmation_reason" "text",
    "trigger_confirmation_evidence" "jsonb",
    "activated_at" timestamp with time zone,
    "activated_by" "uuid",
    "activation_position_state_hash" "text",
    "activation_eligibility_state_hash" "text",
    "activation_evidence" "jsonb",
    "reminder_rules" "jsonb" DEFAULT '[{"type": "eligibility_due", "offsetDays": 0, "recurrence": "none"}, {"type": "overdue_unclaimed", "offsetDays": 7, "recurrence": "weekly"}]'::"jsonb" NOT NULL,
    "replaces_schedule_id" "uuid",
