    "created_by" "uuid" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "project_retention_release_schedules_actor_pairs" CHECK (((("trigger_confirmed_at" IS NULL) = ("trigger_confirmed_by" IS NULL)) AND (("activated_at" IS NULL) = ("activated_by" IS NULL)) AND (("cancelled_at" IS NULL) = ("cancelled_by" IS NULL)) AND (("completed_at" IS NULL) = ("completed_by" IS NULL)))),
    CONSTRAINT "project_retention_release_schedules_cap_check" CHECK ((("cap_amount" IS NULL) OR ("cap_amount" > (0)::numeric))),
    CONSTRAINT "project_retention_release_schedules_delay_check" CHECK ((("delay_days" >= 0) AND ("delay_days" <= 36500))),
    CONSTRAINT "project_retention_release_schedules_evidence_shapes" CHECK (((("trigger_confirmation_evidence" IS NULL) OR ("jsonb_typeof"("trigger_confirmation_evidence") = 'object'::"text")) AND (("activation_evidence" IS NULL) OR ("jsonb_typeof"("activation_evidence") = 'object'::"text")) AND ("jsonb_typeof"("reminder_rules") = 'array'::"text"))),
    CONSTRAINT "project_retention_release_schedules_hash_shapes" CHECK (((("activation_position_state_hash" IS NULL) OR ("activation_position_state_hash" ~ '^[a-f0-9]{64}$'::"text")) AND (("activation_eligibility_state_hash" IS NULL) OR ("activation_eligibility_state_hash" ~ '^[a-f0-9]{64}$'::"text")))),
    CONSTRAINT "project_retention_release_schedules_method_check" CHECK (("entitlement_method" = ANY (ARRAY['percentage'::"text", 'fixed_amount'::"text"]))),
    CONSTRAINT "project_retention_release_schedules_method_values_check" CHECK (((("entitlement_method" = 'percentage'::"text") AND (("percentage_bps" >= 1) AND ("percentage_bps" <= 10000)) AND ("fixed_amount" IS NULL)) OR (("entitlement_method" = 'fixed_amount'::"text") AND ("percentage_bps" IS NULL) AND ("fixed_amount" > (0)::numeric)))),
    CONSTRAINT "project_retention_release_schedules_name_check" CHECK ((("char_length"(TRIM(BOTH FROM "name")) >= 1) AND ("char_length"(TRIM(BOTH FROM "name")) <= 250))),
    CONSTRAINT "project_retention_release_schedules_revision_positive" CHECK (("revision" > 0)),
    CONSTRAINT "project_retention_release_schedules_scope_check" CHECK (("scope_policy" = ANY (ARRAY['explicit'::"text", 'all_current_origins'::"text"]))),
    CONSTRAINT "project_retention_release_schedules_sequence_positive" CHECK (("schedule_sequence" > 0)),
    CONSTRAINT "project_retention_release_schedules_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'scheduled'::"text", 'awaiting_confirmation'::"text", 'activated'::"text", 'completed'::"text", 'cancelled'::"text"]))),
    CONSTRAINT "project_retention_release_schedules_trigger_check" CHECK (("trigger_type" = ANY (ARRAY['practical_completion'::"text", 'defects_liability_expiry'::"text", 'fixed_date'::"text", 'manual_milestone'::"text", 'custom'::"text"])))
);

