    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "retention_variances_amounts_nonnegative" CHECK ((("current_ownership" >= (0)::numeric) AND ("current_eligibility" >= (0)::numeric) AND ("committed_retention" >= (0)::numeric))),
    CONSTRAINT "retention_variances_blocking_consistency" CHECK (("is_blocking" = ("state" = ANY (ARRAY['reconciliation_required'::"text", 'over_allocated'::"text", 'resolution_pending'::"text"])))),
    CONSTRAINT "retention_variances_condition_check" CHECK (("contributing_conditions" <@ ARRAY['ownership_reduced'::"text", 'eligibility_reduced'::"text", 'origin_payment_claim_cancelled'::"text", 'schedule_changed'::"text", 'schedule_cancelled'::"text", 'legacy_reconciliation_conflict'::"text", 'xero_local_financial_divergence'::"text", 'corrective_transaction_pending'::"text"])),
    CONSTRAINT "retention_variances_corrective_amount" CHECK ((("corrective_amount_proposed" IS NULL) OR ("corrective_amount_proposed" > (0)::numeric))),
    CONSTRAINT "retention_variances_escalation_nonnegative" CHECK (("escalation_level" >= 0)),
    CONSTRAINT "retention_variances_evidence_object" CHECK ((("resolution_evidence" IS NULL) OR ("jsonb_typeof"("resolution_evidence") = 'object'::"text"))),
    CONSTRAINT "retention_variances_hashes_shape" CHECK ((("latest_phase2_state_hash" ~ '^[a-f0-9]{64}$'::"text") AND ("latest_phase4_eligibility_hash" ~ '^[a-f0-9]{64}$'::"text") AND ("committed_allocation_hash" ~ '^[a-f0-9]{64}$'::"text") AND (("prior_phase2_state_hash" IS NULL) OR ("prior_phase2_state_hash" ~ '^[a-f0-9]{64}$'::"text")) AND (("prior_phase4_eligibility_hash" IS NULL) OR ("prior_phase4_eligibility_hash" ~ '^[a-f0-9]{64}$'::"text")) AND (("prior_committed_allocation_hash" IS NULL) OR ("prior_committed_allocation_hash" ~ '^[a-f0-9]{64}$'::"text")) AND (("override_basis_hash" IS NULL) OR ("override_basis_hash" ~ '^[a-f0-9]{64}$'::"text")))),
    CONSTRAINT "retention_variances_override_amount" CHECK ((("override_approved_amount" IS NULL) OR ("override_approved_amount" >= (0)::numeric))),
    CONSTRAINT "retention_variances_revision_positive" CHECK (("revision" > 0)),
    CONSTRAINT "retention_variances_severity_check" CHECK (("severity" = ANY (ARRAY['low'::"text", 'medium'::"text", 'high'::"text", 'critical'::"text"]))),
    CONSTRAINT "retention_variances_state_check" CHECK (("state" = ANY (ARRAY['warning'::"text", 'reconciliation_required'::"text", 'over_allocated'::"text", 'resolution_pending'::"text", 'resolved'::"text", 'accepted_contractual_override'::"text"]))),
    CONSTRAINT "retention_variances_type_check" CHECK (("primary_type" = ANY (ARRAY['ownership_reduced'::"text", 'eligibility_reduced'::"text", 'origin_payment_claim_cancelled'::"text", 'schedule_changed'::"text", 'schedule_cancelled'::"text", 'legacy_reconciliation_conflict'::"text", 'xero_local_financial_divergence'::"text", 'corrective_transaction_pending'::"text"])))
);

