    CONSTRAINT "worksheet_pricing_pattern_shadow_propos_rejection_reasons_check" CHECK (("jsonb_typeof"("rejection_reasons") = 'array'::"text")),
    CONSTRAINT "worksheet_pricing_pattern_shadow_proposa_evidence_summary_check" CHECK (("jsonb_typeof"("evidence_summary") = 'object'::"text")),
    CONSTRAINT "worksheet_pricing_pattern_shadow_proposals_confidence_check" CHECK ((("confidence" IS NULL) OR (("confidence" >= (0)::numeric) AND ("confidence" <= (1)::numeric)))),
    CONSTRAINT "worksheet_pricing_pattern_shadow_proposals_gate_status_check" CHECK (("gate_status" = ANY (ARRAY['accepted'::"text", 'rejected'::"text", 'no_pattern'::"text"]))),
    CONSTRAINT "worksheet_pricing_pattern_shadow_proposals_pattern_value_check" CHECK (("jsonb_typeof"("pattern_value") = 'object'::"text")),
    CONSTRAINT "worksheet_pricing_pattern_shadow_proposals_proposal_kind_check" CHECK (("proposal_kind" = ANY (ARRAY['pattern'::"text", 'no_pattern'::"text"]))),
    CONSTRAINT "worksheet_pricing_pattern_shadow_proposals_scope_check" CHECK (("jsonb_typeof"("scope") = 'object'::"text")),
    CONSTRAINT "worksheet_pricing_pattern_shadow_proposals_validation_check" CHECK (("jsonb_typeof"("validation") = 'object'::"text"))
);

ALTER TABLE ONLY "public"."worksheet_pricing_pattern_shadow_proposals" FORCE ROW LEVEL SECURITY;


ALTER TABLE "public"."worksheet_pricing_pattern_shadow_proposals" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."worksheet_pricing_pattern_shadow_runs" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "requested_organization_id" "uuid",
    "input_limit_count" integer NOT NULL,
    "input_batch_size" integer NOT NULL,
    "fetched_event_count" integer DEFAULT 0 NOT NULL,
    "pools_built" integer DEFAULT 0 NOT NULL,
    "proposals_returned" integer DEFAULT 0 NOT NULL,
    "accepted_by_gate_count" integer DEFAULT 0 NOT NULL,
    "rejected_by_gate_count" integer DEFAULT 0 NOT NULL,
    "no_pattern_count" integer DEFAULT 0 NOT NULL,
    "family_distribution" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "strength_distribution" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "rejection_reasons" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "provider" "text" NOT NULL,
    "model" "text" NOT NULL,
    "duration_ms" integer DEFAULT 0 NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "worksheet_pricing_pattern_shadow_r_accepted_by_gate_count_check" CHECK (("accepted_by_gate_count" >= 0)),
    CONSTRAINT "worksheet_pricing_pattern_shadow_r_rejected_by_gate_count_check" CHECK (("rejected_by_gate_count" >= 0)),
    CONSTRAINT "worksheet_pricing_pattern_shadow_ru_strength_distribution_check" CHECK (("jsonb_typeof"("strength_distribution") = 'object'::"text")),
    CONSTRAINT "worksheet_pricing_pattern_shadow_runs_duration_ms_check" CHECK (("duration_ms" >= 0)),
    CONSTRAINT "worksheet_pricing_pattern_shadow_runs_family_distribution_check" CHECK (("jsonb_typeof"("family_distribution") = 'object'::"text")),
    CONSTRAINT "worksheet_pricing_pattern_shadow_runs_fetched_event_count_check" CHECK (("fetched_event_count" >= 0)),
    CONSTRAINT "worksheet_pricing_pattern_shadow_runs_input_batch_size_check" CHECK (("input_batch_size" > 0)),
    CONSTRAINT "worksheet_pricing_pattern_shadow_runs_input_limit_count_check" CHECK (("input_limit_count" > 0)),
    CONSTRAINT "worksheet_pricing_pattern_shadow_runs_no_pattern_count_check" CHECK (("no_pattern_count" >= 0)),
    CONSTRAINT "worksheet_pricing_pattern_shadow_runs_pools_built_check" CHECK (("pools_built" >= 0)),
    CONSTRAINT "worksheet_pricing_pattern_shadow_runs_proposals_returned_check" CHECK (("proposals_returned" >= 0)),
    CONSTRAINT "worksheet_pricing_pattern_shadow_runs_rejection_reasons_check" CHECK (("jsonb_typeof"("rejection_reasons") = 'object'::"text"))
);

ALTER TABLE ONLY "public"."worksheet_pricing_pattern_shadow_runs" FORCE ROW LEVEL SECURITY;


ALTER TABLE "public"."worksheet_pricing_pattern_shadow_runs" OWNER TO "postgres";


