   FROM "public"."organization_opportunities" "opportunity"
  WHERE (("opportunity"."id" = "project_job_todos"."opportunity_id") AND ("opportunity"."organization_id" = "project_job_todos"."organization_id") AND ("opportunity"."workspace_project_id" = "project_job_todos"."project_id")))))));



